INSERT INTO `ep_topic_packs` VALUES (21114,1,1,'English','en','Body Body Pop Pop','[\"Body parts are parts of the human body.\",\"Head is the top part of the body.\",\"Neck is the part that connects the head to the body.\",\"Shoulders are the upper parts of the arms.\",\"Eyes are the parts that help you see.\",\"Ears are the parts that help you hear.\",\"Nose is the part that helps you smell.\",\"Mouth is the part that helps you talk and eat.\",\"Hands are the parts that help you touch and hold.\",\"Feet are the parts that help you walk.\",\"Fingers are the small parts at the end of the hands.\",\"Chin is the lower part of the face.\",\"Body parts can be named and identified easily.\",\"You can touch each body part to learn its name.\",\"Listening and speaking helps you remember body parts.\"]','[{\"q\":\"What sound follows the word \'body\' in the song?\",\"options\":[\"pop pop\",\"clap clap\",\"jump jump\",\"tap tap\"],\"answer\":0,\"explain\":\"The text repeats \'body body pop pop\' throughout the song.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"In the song, what should you touch after touching your head?\",\"options\":[\"your eyes\",\"your shoulders\",\"your nose\",\"your feet\"],\"answer\":1,\"explain\":\"The text says, \'Touch your head ... touch your shoulders\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Which body part is paired with \'eyes\' in the song?\",\"options\":[\"ears\",\"mouth\",\"nose\",\"hand\"],\"answer\":0,\"explain\":\"The text says, \'Touch your eyes ... touch your ears\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"If the teacher asks \'Show me your fingers\', what is the correct way for the student to start the answer?\",\"options\":[\"This is my...\",\"That is my...\",\"These are my...\",\"It is my...\"],\"answer\":2,\"explain\":\"The dialogue shows the student responding with \'These are my .....\' when asked about fingers.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"According to the song, which part do you touch along with your nose?\",\"options\":[\"your head\",\"your mouth\",\"your hand\",\"your eyes\"],\"answer\":1,\"explain\":\"The text says, \'Touch your nose ... touch your mouth\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"When the teacher asks \'What is this?\', what body part does the student name first?\",\"options\":[\"chin\",\"fingers\",\"neck\",\"shoulders\"],\"answer\":2,\"explain\":\"In the dialogue, the student says \'This is my neck\' in response to \'What is this?\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Which two body parts are mentioned in the very last line of the song?\",\"options\":[\"eyes and ears\",\"nose and mouth\",\"hand and feet\",\"head and shoulders\"],\"answer\":2,\"explain\":\"The last line of the song mentions \'Touch your hand ... touch your feet\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"When the teacher asks \'Where is your chin?\', how should the student answer based on the text?\",\"options\":[\"This is my chin\",\"These are my chin\",\"Those are my chin\",\"They are my chin\"],\"answer\":0,\"explain\":\"The text provides the response pattern \'This is \\/ Here is .....\' for the question about the chin.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"Which of these body parts is mentioned in the dialogue but NOT in the song lyrics?\",\"options\":[\"shoulders\",\"eyes\",\"neck\",\"feet\"],\"answer\":2,\"explain\":\"Neck appears in the teacher-student dialogue, while the others are in the \'Touch your...\' song lines.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"Complete the sequence from the song: \'Touch your hand ... touch your ____.\'\",\"options\":[\"feet\",\"mouth\",\"ears\",\"shoulders\"],\"answer\":0,\"explain\":\"The song text concludes the body part pairs with \'Touch your hand ... touch your feet\'.\",\"topic\":\"Listen and speak\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"Who is the instruction in the text meant for?\",\"options\":[\"The Student\",\"The Teacher\",\"The Parent\",\"The Principal\"],\"answer\":1,\"explain\":\"The text explicitly starts with \'For the Teacher\'.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What does the text ask the teacher to practice?\",\"options\":[\"Writing\",\"Drawing\",\"Conversation\",\"Singing\"],\"answer\":2,\"explain\":\"The text says to \'Practise conversation\'.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What names should be used during the conversation practice?\",\"options\":[\"Names of body parts\",\"Names of fruits\",\"Names of colors\",\"Names of animals\"],\"answer\":0,\"explain\":\"The text specifies \'using the names of other body parts\'.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What does the word \'conversation\' mean in this instruction?\",\"options\":[\"Writing in a book\",\"Talking to each other\",\"Sitting quietly\",\"Running in the ground\"],\"answer\":1,\"explain\":\"Conversation involves speaking or talking between people.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"The text mentions using \'other\' body parts. What does this suggest?\",\"options\":[\"Use only one body part\",\"Do not use body parts\",\"Use different body parts than the ones already known\",\"Use names of toys\"],\"answer\":2,\"explain\":\"\'Other\' implies using additional or different body parts in the practice.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"If a teacher says, \'Show me your shoulders,\' which part of the instruction are they following?\",\"options\":[\"Practising conversation using body parts\",\"Practising drawing shapes\",\"Practising counting numbers\",\"Practising singing songs\"],\"answer\":0,\"explain\":\"Using \'shoulders\' is an example of using a body part name in conversation.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"Which of these is a \'body part\' name a teacher might use based on the text?\",\"options\":[\"Pencil\",\"Knee\",\"Apple\",\"Chair\"],\"answer\":1,\"explain\":\"A knee is a body part, while the others are objects or food.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"What is the main activity the teacher is encouraged to do with the students?\",\"options\":[\"A speaking activity about the body\",\"A silent reading activity\",\"A math calculation activity\",\"A coloring activity\"],\"answer\":0,\"explain\":\"Practising conversation about body parts is a speaking activity.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"Why is \'conversation\' a good way to learn body parts according to the note?\",\"options\":[\"Because it helps students talk and use the names\",\"Because it helps students sleep\",\"Because it helps students draw better\",\"Because it helps students run fast\"],\"answer\":0,\"explain\":\"Conversation requires active use of language and names.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"How can a teacher follow this instruction in class?\",\"options\":[\"By asking students to point to their ears and talk about them\",\"By asking students to draw a tree\",\"By asking students to write the alphabet\",\"By asking students to remain silent\"],\"answer\":0,\"explain\":\"Talking about ears (a body part) is a form of conversation practice.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"create\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21115,1,1,'English','en','What is your name?','[\"- A name is a word that tells what a person is called.\",\"- We can say \'My name is ___\' to introduce ourselves.\",\"- We can ask someone else by saying \'What is your name?\'\",\"- The teacher can help us learn names by using flash cards.\",\"- We can practice by repeating the names we hear.\",\"- We can sing a song that uses names of family members.\",\"- Listening and speaking are important ways to learn names.\",\"- Names can be short (e.g., Jaya) or longer (e.g., Farida).\",\"- We can say \'I am ___\' to give our name in a friendly way.\",\"- We can ask \'How are you?\' after meeting someone.\",\"- We can answer \'I am fine, thank you.\' when someone asks how we are.\"]','[{\"q\":\"What activity should the teacher conduct according to the text?\",\"options\":[\"Drawing activity\",\"Chain Drill activity\",\"Running activity\",\"Dancing activity\"],\"answer\":1,\"explain\":\"The text explicitly mentions conducting the \'Chain Drill activity\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What should the teacher use for the names in the activity?\",\"options\":[\"Stones\",\"Flash cards\",\"Crayons\",\"Flowers\"],\"answer\":1,\"explain\":\"The text states to use \'flash cards of the names\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Whose names should be used to practice the poem?\",\"options\":[\"Cartoon characters\",\"Pets\",\"Family members\",\"Fruit names\"],\"answer\":2,\"explain\":\"The instructions say to \'Practise the poem by using names of other family members\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What is the purpose of the flash cards in the Chain Drill?\",\"options\":[\"To show names\",\"To draw pictures\",\"To play music\",\"To count numbers\"],\"answer\":0,\"explain\":\"The text specifies using flash cards \'of the names\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"How should the teacher practice the poem with the students?\",\"options\":[\"By writing it down\",\"By using names of family members\",\"By silent reading\",\"By drawing the family\"],\"answer\":1,\"explain\":\"The teacher is instructed to practice the poem using names of family members.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"The \'Chain Drill\' is an activity meant for the ____ to conduct.\",\"options\":[\"Principal\",\"Teacher\",\"Doctor\",\"Driver\"],\"answer\":1,\"explain\":\"The instruction is listed under the heading \'For the Teacher\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a teacher wants to start the Chain Drill, what must they prepare?\",\"options\":[\"A storybook\",\"Flash cards with names\",\"A map of the school\",\"Lunch boxes\"],\"answer\":1,\"explain\":\"The text links the Chain Drill activity with the use of flash cards of names.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which of these names can be used to practice the poem as per the instructions?\",\"options\":[\"A tree\'s name\",\"A city\'s name\",\"A brother\'s name\",\"A color\'s name\"],\"answer\":2,\"explain\":\"A brother is a family member, and the text says to use names of family members.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which specific tool is mentioned to help students learn names in a sequence?\",\"options\":[\"Flash cards\",\"Blackboard\",\"Chalk\",\"Notebook\"],\"answer\":0,\"explain\":\"Flash cards are the only tool mentioned for the name-based activity.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What is the main goal of using family names in the poem practice?\",\"options\":[\"To learn to draw\",\"To practice the poem\",\"To count family members\",\"To go home early\"],\"answer\":1,\"explain\":\"The text says \'Practise the poem by using names of other family members\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21116,1,1,'English','en','My Home','[\"1. A home is a place where we live and feel safe.\",\"2. Homes have rooms like living room, bedroom, kitchen, bathroom.\",\"3. Common furniture: chair, table, sofa, bed, cupboard, clock, fan, television.\",\"4. Doors and windows let us enter, exit, and see outside.\",\"5. A fan helps to cool the room by moving air.\",\"6. A clock tells us the time.\",\"7. A television shows movies, news and cartoons.\",\"8. A cupboard keeps our clothes and food.\",\"9. A vase can hold flowers or decorations.\",\"10. A glass is used for drinking water or juice.\",\"11. A chair is a seat for sitting.\",\"12. A sofa is a comfortable seat for many people.\",\"13. A table is used for eating or working.\",\"14. A door opens and closes to let people in and out.\",\"15. A window lets light in and can be opened for fresh air.\",\"16. We keep our home clean by washing, sweeping and dusting.\",\"17. We respect our home by keeping it tidy and safe.\",\"18. We can decorate our home with pictures, toys and plants.\",\"19. The kitchen is where we cook food for the family.\",\"20. The bathroom is where we wash our hands and brush our teeth.\",\"21. A bedroom is where we sleep and keep our toys.\",\"22. A living room is where we spend time with family.\",\"23. We can learn new things at home by reading and practicing.\",\"24. We should always tell our parents if something is broken.\",\"25. A home is a place of love, learning and rest.\"]','[{\"q\":\"Which of these things is mentioned in the \'My Home\' list?\",\"options\":[\"fan\",\"car\",\"bus\",\"tree\"],\"answer\":0,\"explain\":\"The text explicitly lists \'fan\' as one of the things seen at home.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Where are all the things like the sofa, vase, and cupboard found according to the topic?\",\"options\":[\"At home\",\"In the garden\",\"On the road\",\"In the sky\"],\"answer\":0,\"explain\":\"The topic title is \'My Home\', indicating these items are found there.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which item from the list is used to tell the time?\",\"options\":[\"clock\",\"glass\",\"table\",\"door\"],\"answer\":0,\"explain\":\"A clock is the standard household item used for showing time.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which of these items is used for sitting?\",\"options\":[\"chair\",\"vase\",\"window\",\"fan\"],\"answer\":0,\"explain\":\"A chair is a common piece of furniture listed in the text used for sitting.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which item is used to watch programs or shows?\",\"options\":[\"television\",\"cupboard\",\"table\",\"glass\"],\"answer\":0,\"explain\":\"Television is the electronic item listed in the text for watching media.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"If you want to put flowers in a container, which item from the list would you use?\",\"options\":[\"vase\",\"sofa\",\"door\",\"clock\"],\"answer\":0,\"explain\":\"A vase is specifically used to hold flowers.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which item would you use to store your clothes or books safely?\",\"options\":[\"cupboard\",\"chair\",\"fan\",\"window\"],\"answer\":0,\"explain\":\"A cupboard is used for storage in a home.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which item in the list is usually made of glass or plastic and used for drinking?\",\"options\":[\"glass\",\"table\",\"sofa\",\"vase\"],\"answer\":0,\"explain\":\"The word \'glass\' refers to the object used for drinking water.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which part of the home can you look through to see what is happening outside?\",\"options\":[\"window\",\"clock\",\"television\",\"chair\"],\"answer\":0,\"explain\":\"A window is an opening in a wall that allows one to see outside.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which item is used to enter or leave a room?\",\"options\":[\"door\",\"fan\",\"cupboard\",\"table\"],\"answer\":0,\"explain\":\"A door is the functional opening used for passage into a home or room.\",\"topic\":\"Home Vocabulary\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21117,1,1,'English','en','Clap your hands','[\"Clap your hands – a simple action to follow a rhythm.\",\"Stamp your feet – a fun way to keep time with music.\",\"Turn around – helps children move and stay active.\",\"Jump up high – encourages physical activity and listening.\",\"Stand straight – teaches posture and listening to instructions.\",\"Turn right \\/ Turn left – basic directional commands.\",\"Sit down – a calm action to end the activity.\",\"Hands up – a common classroom signal for attention.\",\"Listen to the music – focus on the beat before acting.\",\"Repeat the poem – reinforces memory and rhythm.\",\"Use different instructions – keeps the activity fresh and engaging.\",\"Touch the ground – a variation of clap your hands.\",\"Point to the board – a variation of stamp your feet.\",\"Follow the teacher’s voice – key to successful movement.\",\"Keep the body still when told to sit down – teaches control.\",\"Use a steady beat – helps children stay in sync.\",\"Move slowly when turning – safety first.\",\"Jump high only when safe – avoid injury.\",\"Clap hands together – encourages teamwork.\",\"Listen carefully before acting – improves concentration.\",\"Use a clear voice for instructions – helps understanding.\",\"Encourage all children to participate – builds confidence.\",\"Use simple words – suitable for first graders.\",\"Keep the activity short – holds attention.\",\"End with a calm action – signals the activity is over.\"]','[{\"q\":\"What should you do with your hands according to the poem?\",\"options\":[\"Stamp them\",\"Clap them\",\"Jump them\",\"Sit on them\"],\"answer\":1,\"explain\":\"The text says \'Clap your hands\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What should you do with your feet?\",\"options\":[\"Clap your feet\",\"Turn your feet\",\"Stamp your feet\",\"Sit on your feet\"],\"answer\":2,\"explain\":\"The text says \'Stamp your feet\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What are you asked to listen to?\",\"options\":[\"The teacher\",\"The music\",\"The birds\",\"The bell\"],\"answer\":1,\"explain\":\"The poem repeats the line \'Listen to the music\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which action involves moving in a circle?\",\"options\":[\"Stand straight\",\"Jump up high\",\"Turn around\",\"Sit down\"],\"answer\":2,\"explain\":\"Turning around means moving in a circular motion.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What is the opposite of \'Stand up\'?\",\"options\":[\"Sit down\",\"Turn left\",\"Hands up\",\"Jump high\"],\"answer\":0,\"explain\":\"In the instructions, \'Sit down\' is the opposite action of \'Stand up\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What should you do after you \'Listen to the music\' in the last verse?\",\"options\":[\"Turn around\",\"Stamp your feet\",\"Clap your hands\",\"Jump up high\"],\"answer\":3,\"explain\":\"The last verse says \'Listen to the music And jump up high\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If you are told to \'Jump up high\', which way are you moving?\",\"options\":[\"Downwards\",\"Upwards\",\"Left\",\"Right\"],\"answer\":1,\"explain\":\"Jumping \'up high\' involves moving upwards away from the ground.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which of these is a direction you are asked to turn?\",\"options\":[\"Turn back\",\"Turn left\",\"Turn slow\",\"Turn fast\"],\"answer\":1,\"explain\":\"The text specifically mentions \'Turn left\' and \'Turn right\'.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which action makes a loud sound using your feet?\",\"options\":[\"Stand straight\",\"Turn around\",\"Stamp your feet\",\"Sit down\"],\"answer\":2,\"explain\":\"Stamping feet is the action that creates a sound with the feet.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which body part is used for the action \'Clap\'?\",\"options\":[\"Feet\",\"Hands\",\"Head\",\"Knees\"],\"answer\":1,\"explain\":\"The poem associates clapping specifically with hands.\",\"topic\":\"Verse 4: Jump up high\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"What should you do when you listen to the music?\",\"options\":[\"Clap your hands\",\"Close your eyes\",\"Sit on the chair\",\"Read a book\"],\"answer\":0,\"explain\":\"The text says, \'Listen to the music And clap your hands.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What are you told to listen to in the poem?\",\"options\":[\"The teacher\",\"The music\",\"The bell\",\"The birds\"],\"answer\":1,\"explain\":\"The poem explicitly mentions to \'Listen to the music\'.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What does the teacher use to repeat the poem?\",\"options\":[\"Different instructions\",\"Different languages\",\"Different books\",\"Different students\"],\"answer\":0,\"explain\":\"The text states, \'Use different instructions likewise and repeat the poem.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"Which action is given as an example to replace \'Clap your hands\'?\",\"options\":[\"Touch the ground\",\"Jump up high\",\"Close your eyes\",\"Shake your head\"],\"answer\":0,\"explain\":\"The text provides the example: Replace ‘Clap your hands’ with ‘Touch the ground’.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"According to the examples, what should replace \'Stamp your feet\'?\",\"options\":[\"Point to the board\",\"Touch the ground\",\"Clap your hands\",\"Listen to music\"],\"answer\":0,\"explain\":\"The text says, \'replace ‘Stamp your feet’ with ‘Point to the board’.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"If a teacher wants to change the poem, what is the first step according to the text?\",\"options\":[\"Replace the instructions\",\"Stop the music\",\"Draw a picture\",\"Write a new story\"],\"answer\":0,\"explain\":\"The text suggests using different instructions to repeat the poem.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"Which of these actions is mentioned as an original part of the poem or an example?\",\"options\":[\"Stamp your feet\",\"Dance around\",\"Sit down\",\"Open the door\"],\"answer\":0,\"explain\":\"‘Stamp your feet’ is mentioned in the text as an instruction to be replaced.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What is the purpose of the examples like \'Touch the ground\'?\",\"options\":[\"To show how to change the poem\",\"To teach how to clean the floor\",\"To show how to draw\",\"To teach how to sleep\"],\"answer\":0,\"explain\":\"The examples show how to use different instructions to repeat the poem.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"Which action is NOT mentioned in the text?\",\"options\":[\"Clap your hands\",\"Touch the ground\",\"Point to the board\",\"Run in place\"],\"answer\":3,\"explain\":\"\'Run in place\' is not mentioned in the provided text.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"Based on the text, what can a teacher do to make the poem new?\",\"options\":[\"Replace \'Clap your hands\' with a new action\",\"Change the name of the music\",\"Tell the students to go home\",\"Read a different chapter\"],\"answer\":0,\"explain\":\"The text suggests replacing instructions like \'Clap your hands\' with new ones like \'Touch the ground\'.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21118,1,1,'English','en','Chit Chat','[\"- Greeting words: Hello, Hi, Good morning, Good afternoon, Good evening, Good night.\",\"- We greet people at different times of the day.\",\"- In the morning we wash our face, brush teeth, take a bath, eat breakfast, wear school uniform, pack a bag, go to school.\",\"- After school we play with friends, do homework, eat dinner, and go to bed.\",\"- We say \'Good morning\' when we meet someone in the morning.\",\"- We say \'Good night\' before sleeping.\",\"- We say \'Good afternoon\' when it is after noon but before evening.\",\"- We say \'Good evening\' when it is after sunset.\",\"- We practice speaking by asking and answering questions like \'What do you do in the morning?\'.\",\"- We listen to stories and repeat them.\",\"- We learn to follow instructions in class: stand at ease, join hands, pray, sing national anthem, pledge, read preamble.\",\"- Assembly is a group activity where we follow a sequence of actions.\",\"- Teachers give instructions and students listen carefully.\",\"- We use polite words like \'Hello\', \'Good morning\' to show respect.\",\"- Repeating sentences helps us learn pronunciation and meaning.\",\"- We can practice conversations with classmates or with the teacher.\",\"- Learning to greet and follow instructions is important for good manners.\",\"- Remember to say \'Thank you\' after someone helps you.\",\"- We can ask questions like \'When do you play?\' to learn about others\' routines.\",\"- Using correct time words (morning, afternoon, evening, night) helps us talk about daily activities.\"]','[{\"q\":\"What do you say when you meet someone in the morning?\",\"options\":[\"Good morning\",\"Good night\",\"Good evening\",\"Good afternoon\"],\"answer\":0,\"explain\":\"The text lists \'Good morning\' as a greeting for the morning time.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"According to the text, what do you do in the morning?\",\"options\":[\"Take rest\",\"Take bath\",\"Play\",\"Listen to stories\"],\"answer\":1,\"explain\":\"The text explicitly states \'I take bath in the morning.\'\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"When should you say \'Good afternoon\'?\",\"options\":[\"In the morning\",\"In the evening\",\"In the afternoon\",\"At night\"],\"answer\":2,\"explain\":\"The text pairs \'Good afternoon\' with afternoon activities like taking rest and lunch.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Which meal is taken in the morning according to the text?\",\"options\":[\"Lunch\",\"Dinner\",\"Breakfast\",\"Rest\"],\"answer\":2,\"explain\":\"The text lists \'take breakfast\' under the morning category.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"If it is evening and you want to follow the text, what should you do?\",\"options\":[\"Take bath\",\"Play\",\"Take lunch\",\"Listen to stories\"],\"answer\":1,\"explain\":\"The text suggests \'play\' as an activity for the evening.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"What should you say to your teacher before going to sleep?\",\"options\":[\"Good morning\",\"Good afternoon\",\"Good evening\",\"Good night\"],\"answer\":3,\"explain\":\"The text lists \'Good night\' as the greeting for the night time.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Which of these is NOT a morning activity in the text?\",\"options\":[\"Take bath\",\"Take breakfast\",\"Good morning\",\"Take lunch\"],\"answer\":3,\"explain\":\"Take lunch is listed under afternoon, not morning.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"When is the correct time to \'take dinner\' according to the list?\",\"options\":[\"Morning\",\"Afternoon\",\"Evening\",\"Night\"],\"answer\":3,\"explain\":\"The text associates \'take dinner\' with the \'Good night\' and night section.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Based on the text, which is the best time to \'take rest\'?\",\"options\":[\"Morning\",\"Afternoon\",\"Evening\",\"Night\"],\"answer\":1,\"explain\":\"The text specifically lists \'take rest\' under the afternoon activities.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"What is the last thing you do at night before saying \'Good night\'?\",\"options\":[\"Complete homework\",\"Listen to the stories\",\"Take bath\",\"Play\"],\"answer\":1,\"explain\":\"The text lists \'listen to the stories\' as a night activity.\",\"topic\":\"Listen and use\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"According to the text, what do you do with your teeth?\",\"options\":[\"Brush them\",\"Wash them\",\"Play with them\",\"Pack them\"],\"answer\":0,\"explain\":\"The text states \'I brush my teeth.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"When do you wake up?\",\"options\":[\"In the night\",\"In the morning\",\"In the afternoon\",\"In the evening\"],\"answer\":1,\"explain\":\"The text explicitly says \'When do you wake up? In the morning.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What do you have in the morning for food?\",\"options\":[\"Lunch\",\"Dinner\",\"A breakfast\",\"Snacks\"],\"answer\":2,\"explain\":\"The text mentions \'I have a breakfast.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What do you wear before going to school?\",\"options\":[\"A raincoat\",\"My school uniform\",\"A party dress\",\"Night clothes\"],\"answer\":1,\"explain\":\"The text says \'I wear my school uniform.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What do you do with your school bag?\",\"options\":[\"I play with it\",\"I brush it\",\"I pack it\",\"I sleep on it\"],\"answer\":2,\"explain\":\"The text says \'I pack my school bag.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What do you do with your friends?\",\"options\":[\"I brush with them\",\"I play with them\",\"I sleep with them\",\"I pack them\"],\"answer\":1,\"explain\":\"The text states \'I play with my friends.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If you have just finished your breakfast, what is the next step in the routine mentioned?\",\"options\":[\"I wake up\",\"I wear my school uniform\",\"I go to bed\",\"I brush my teeth\"],\"answer\":1,\"explain\":\"In the sequence provided, \'I wear my school uniform\' follows \'I have a breakfast.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Based on the text, when can a student play?\",\"options\":[\"Only at night\",\"Only in the morning\",\"Morning, afternoon, or evening\",\"Only when sleeping\"],\"answer\":2,\"explain\":\"The student says \'I play in the morning \\/ afternoon \\/ evening.\'\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which of these activities happens last in the daily routine?\",\"options\":[\"I go to school\",\"I go to bed\",\"I take a bath\",\"I pack my school bag\"],\"answer\":1,\"explain\":\"The text lists \'I go to bed\' as the final activity in the sequence.\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which activity is done to prepare for school lessons at home?\",\"options\":[\"I play with friends\",\"I do my homework\",\"I wake up early\",\"I take a bath\"],\"answer\":1,\"explain\":\"Doing homework is the activity related to school study mentioned in the text.\",\"topic\":\"Listen, repeat and do\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What is the first instruction given in the text for the assembly?\",\"options\":[\"Stand in a line\",\"Sit down\",\"Run fast\",\"Close your eyes\"],\"answer\":0,\"explain\":\"The text begins with the instruction \'Stand in a line.\'\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What should you do with your hands before the prayer?\",\"options\":[\"Clap your hands\",\"Wave your hands\",\"Join your hands\",\"Put hands in pockets\"],\"answer\":2,\"explain\":\"The text says \'Join your hands. Let us pray.\'\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which instruction tells the students to be alert and still?\",\"options\":[\"Sleep\",\"Attention\",\"Run\",\"Dance\"],\"answer\":1,\"explain\":\"The text uses the command \'Attention\' to signal alertness.\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What instruction follows \'Stand in a line\'?\",\"options\":[\"Sit down\",\"Stand at ease\",\"Jump\",\"Shout\"],\"answer\":1,\"explain\":\"According to the text, the sequence is \'Stand in a line. Stand at ease.\'\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If the teacher says \'Start the National Anthem\', what are the students expected to do?\",\"options\":[\"Read a story\",\"Sing the anthem\",\"Draw a picture\",\"Play a game\"],\"answer\":1,\"explain\":\"The instruction \'Start the National Anthem\' implies singing or beginning the anthem.\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"What is the student preparing for when the teacher says \'Be ready for the Pledge\'?\",\"options\":[\"Reciting the pledge\",\"Having lunch\",\"Going home\",\"Sleeping\"],\"answer\":0,\"explain\":\"The instruction \'Be ready for the Pledge\' prepares students for the recitation.\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which of these is NOT an instruction for how to stand?\",\"options\":[\"Stand in a line\",\"Stand at ease\",\"Attention\",\"Let us pray\"],\"answer\":3,\"explain\":\"\'Let us pray\' is an instruction for prayer, not a standing posture.\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which specific song is mentioned after the National Anthem?\",\"options\":[\"Start the Preamble\",\"Ready for the Rajyageet\",\"Join your hands\",\"Stand at ease\"],\"answer\":1,\"explain\":\"The text mentions \'Ready for the Rajyageet\' after the National Anthem.\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Based on the text, why do students join their hands?\",\"options\":[\"To play\",\"To pray\",\"To eat\",\"To write\"],\"answer\":1,\"explain\":\"The text links joining hands with the instruction \'Let us pray.\'\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What is the correct command used for the Preamble?\",\"options\":[\"Stop the Preamble\",\"Start the Preamble\",\"Forget the Preamble\",\"Draw the Preamble\"],\"answer\":1,\"explain\":\"The text explicitly says \'Start the Preamble.\'\",\"topic\":\"Our Assembly\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21119,1,1,'English','en','Fun with Sounds (b-c-p-t-a)','[\"- In this chapter we learn how to read and write words that start with the letters b, c, p, t, and a.\",\"- The letters are shown in big block style so you can see the shape of each letter.\",\"- Words are grouped by the first letter: for example, all words that start with ‘b’ are written together.\",\"- Practice saying the words aloud and then write them down.\",\"- Pay attention to the sound of the first letter – it is the same in all the words of that group.\",\"- When you see a new word, try to guess its meaning from the picture or the sound.\",\"- The teacher will ask you to think of more words that start with the same letter.\",\"- You can trace the letters with your finger or a pencil to help remember their shape.\",\"- Repeating the words helps you remember how they are spelled.\",\"- The words in this chapter are: bike, box, bat, bus, top, table, teddy, tiger, pen, puppy, pigeon, parrot, axe, ankle, ant, apple, car, cat, cup, cow.\",\"- Remember that the letter ‘a’ can be written as a short or long sound, but in this book it is the short sound as in “apple”.\",\"- The letters b, c, p, t, a are all consonants that make a clear sound when you say them.\",\"- Writing the words helps you learn the order of the letters in each word.\",\"- Listening to the teacher and repeating the words is a good way to practice pronunciation.\",\"- If you are unsure of a word, ask the teacher or look at the picture next to it.\",\"- Keep practicing every day and you will become better at reading and writing these words.\"]','[{\"q\":\"Which of these words starts with the letter \'b\'?\",\"options\":[\"bike\",\"cat\",\"ant\",\"top\"],\"answer\":0,\"explain\":\"According to the text, \'bike\' is listed under the letter \'b\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the same sound as \'parrot\'?\",\"options\":[\"box\",\"pen\",\"cow\",\"axe\"],\"answer\":1,\"explain\":\"Both \'parrot\' and \'pen\' are listed together as words starting with the letter \'p\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the letter \'t\'?\",\"options\":[\"apple\",\"cup\",\"tiger\",\"bus\"],\"answer\":2,\"explain\":\"The text lists \'tiger\' as a word starting with the letter \'t\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Look at the word \'cat\'. Which other word starts with the same sound?\",\"options\":[\"bat\",\"ant\",\"cow\",\"top\"],\"answer\":2,\"explain\":\"In the text, \'cat\' and \'cow\' are grouped together under the letter \'c\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word belongs to the group of words starting with \'a\'?\",\"options\":[\"ankle\",\"teddy\",\"puppy\",\"car\"],\"answer\":0,\"explain\":\"The text lists \'ankle\' along with ant, apple, and axe under the letter \'a\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which of these words starts with the letter \'c\'?\",\"options\":[\"box\",\"cup\",\"pen\",\"table\"],\"answer\":1,\"explain\":\"The text lists \'cup\' as a word starting with the letter \'c\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If \'mat\' and \'bat\' sound similar, which word sounds like \'cap\'?\",\"options\":[\"tap\",\"cab\",\"cat\",\"mat\"],\"answer\":0,\"explain\":\"In the list \'cap tap\', both words share the same ending sound.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word starts with the same sound as \'apple\'?\",\"options\":[\"axe\",\"box\",\"cat\",\"pen\"],\"answer\":0,\"explain\":\"Both \'apple\' and \'axe\' are listed under the letter \'a\' in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Find the word that does NOT start with the letter \'p\'.\",\"options\":[\"puppy\",\"pigeon\",\"pen\",\"table\"],\"answer\":3,\"explain\":\"Table starts with \'t\', while the others are listed under \'p\' in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which word from the list sounds most like \'cab\'?\",\"options\":[\"tab\",\"cap\",\"cat\",\"can\"],\"answer\":0,\"explain\":\"The text lists \'cab tab\' together as words with similar sounds.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21120,1,1,'English','en','What can you do?','[\"• Look, listen and repeat to learn new words.\",\"• Listen and speak to practice speaking.\",\"• Practice action words like roar, hop, fly, run, swim, sing, dance, jump, walk, read, write.\",\"• Use action words in conversations with the teacher.\",\"• Try to do what the teacher says – walk, hop, run, cry, bark, fly, roar like animals or people.\",\"• Mimic the sounds of animals: bark like a dog, cry like a baby, roar like a lion.\",\"• Repeat after the teacher to improve pronunciation.\",\"• Use gestures while speaking to remember action words.\",\"• Practice singing songs to learn rhythm and melody.\",\"• Ask the teacher “Can you ___?” and answer “I can’t ___” to practice negation.\",\"• Learn to describe actions: “I can sing”, “I can swim”, “I can dance”.\",\"• Use simple sentences to talk about what you can do.\",\"• Remember that practice makes perfect – keep repeating action words.\",\"• Use the teacher’s prompts to learn new verbs.\",\"• Keep a positive attitude while learning new actions.\",\"• Practice speaking in a friendly tone.\",\"• Use body movements to show the action you are describing.\",\"• Try to think of a picture for each action word.\",\"• Use action words in everyday conversations with friends and family.\",\"• Keep practicing until you can do the action without hesitation.\",\"• Use the teacher’s examples to learn new vocabulary.\",\"• Practice speaking in front of a mirror to see your gestures.\"]','[{\"q\":\"According to the text, what sound does a dog make?\",\"options\":[\"Meow-meow\",\"Bow-wow\",\"Moo-moo\",\"Roar-roar\"],\"answer\":1,\"explain\":\"The text mentions \'Bark like a dog. Bow-wow\'.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which animal is mentioned that can \'roar\'?\",\"options\":[\"Elephant\",\"Horse\",\"Lion\",\"Bird\"],\"answer\":2,\"explain\":\"The text says \'Roar like a lion\'.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"In the given figure, what is the boy doing?\",\"options\":[\"Running like a horse\",\"Walking like an old man\",\"Hopping like a frog\",\"Flying like a bird\"],\"answer\":1,\"explain\":\"The caption in the figure specifically says \'Walk like an old man.\'\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"1\\/021_101.jpg\"},{\"q\":\"In the given figure, who is the boy walking like?\",\"options\":[\"A baby\",\"An elephant\",\"An old man\",\"A lion\"],\"answer\":2,\"explain\":\"The figure shows a boy with a stick, representing an old man.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"1\\/021_101.jpg\"},{\"q\":\"If the Queen says \'Hop like a frog\', what should you do?\",\"options\":[\"Run very fast\",\"Jump or hop like a frog\",\"Fly in the air\",\"Walk slowly\"],\"answer\":1,\"explain\":\"To \'hop like a frog\' means to jump like one.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Complete the command from the text: \'Run like a _______.\'\",\"options\":[\"Baby\",\"Elephant\",\"Horse\",\"Bird\"],\"answer\":2,\"explain\":\"The text says \'Run like a horse\'.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a teacher asks \'Can you sing?\' and you know how to sing, what is the correct way to answer?\",\"options\":[\"Yes, I can sing.\",\"No, I can\'t sing.\",\"Yes, I can\'t sing.\",\"No, I can sing.\"],\"answer\":0,\"explain\":\"The student in the text replies \'Yes, I can sing\' when they can do the action.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which of these animals is described as \'flying\' in the text?\",\"options\":[\"Lion\",\"Horse\",\"Bird\",\"Dog\"],\"answer\":2,\"explain\":\"The command in the text is \'Fly like a bird\'.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"In the list \'swim, play, read, write\', what do these words describe?\",\"options\":[\"Things you eat\",\"Things you can do\",\"Things you wear\",\"Names of animals\"],\"answer\":1,\"explain\":\"These are action words that follow the phrase \'I can....\'\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"In the game described in the text, who gives the commands for the actions?\",\"options\":[\"The Baby\",\"The Horse\",\"The Queen\",\"The Frog\"],\"answer\":2,\"explain\":\"The game is titled \'Queen Says...\', indicating the Queen gives the orders.\",\"topic\":\"Do as Queen says.\",\"part\":4,\"bloom\":\"analyze\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21121,1,1,'English','en','My Classroom','[\"- A classroom is a place where we learn and play.\",\"- It has a blackboard where the teacher writes lessons.\",\"- There is a desk or bench for each student to sit on.\",\"- A chair or sofa can be used for sitting.\",\"- A bookshelf holds books for reading.\",\"- A calendar shows the dates of the month.\",\"- A water bottle keeps us hydrated.\",\"- A school bag carries books and notebooks.\",\"- A duster cleans the floor and dustbin collects waste.\",\"- A bell rings to start or end class.\",\"- A mirror helps us see ourselves.\",\"- A computer can be used for learning and games.\",\"- A tiffin box is for lunch or snacks.\",\"- A toothbrush is kept for brushing teeth.\",\"- A slide and see-saw are playground items outside the classroom.\",\"- A mixer can mix food or play music.\",\"- A table is used for writing and drawing.\",\"- A bed is not usually in a classroom but may be in a school hostel.\",\"- The teacher shows pictures to help us learn new words.\",\"- The teacher asks us to put items in their right places.\"]','[{\"q\":\"Who is the girl mentioned in the exercise?\",\"options\":[\"Anandi\",\"Aarti\",\"Anjali\",\"Aditi\"],\"answer\":0,\"explain\":\"The text asks to \'Help Anandi to keep the things at their proper places\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which item from the list is used to write on the blackboard?\",\"options\":[\"duster\",\"chalk\",\"bench\",\"tiffin\"],\"answer\":1,\"explain\":\"Chalk is the standard tool used for writing on a blackboard.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Where should Anandi put waste paper in the classroom?\",\"options\":[\"school bag\",\"tiffin\",\"dustbin\",\"bench\"],\"answer\":2,\"explain\":\"A dustbin is the proper place for waste materials in a classroom.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What is used to clean or wipe the blackboard?\",\"options\":[\"duster\",\"book\",\"notebook\",\"calendar\"],\"answer\":0,\"explain\":\"A duster is used to wipe chalk marks off a blackboard.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which item would Anandi use to carry her books and notebook to school?\",\"options\":[\"water-bottle\",\"school bag\",\"dustbin\",\"chalk\"],\"answer\":1,\"explain\":\"A school bag is used to carry study materials like books and notebooks.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"In a classroom, where do the students usually sit?\",\"options\":[\"on the blackboard\",\"on the bench\",\"in the dustbin\",\"on the calendar\"],\"answer\":1,\"explain\":\"A bench is the furniture provided for students to sit on.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which item in the list helps us to see the dates and months?\",\"options\":[\"computer\",\"calendar\",\"duster\",\"tiffin\"],\"answer\":1,\"explain\":\"A calendar is used to track days, dates, and months.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which item is used to keep the food that Anandi brings for lunch?\",\"options\":[\"tiffin\",\"water-bottle\",\"notebook\",\"chalk\"],\"answer\":0,\"explain\":\"A tiffin box is used to carry and keep lunch.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which of these is an electronic machine mentioned in the classroom list?\",\"options\":[\"bench\",\"computer\",\"duster\",\"chalk\"],\"answer\":1,\"explain\":\"A computer is the only electronic machine listed among the classroom items.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If Anandi is thirsty and needs a drink, which item should she look for?\",\"options\":[\"notebook\",\"tiffin\",\"water-bottle\",\"school bag\"],\"answer\":2,\"explain\":\"A water-bottle is used to store and carry drinking water.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21122,1,1,'English','en','Fun with Sounds (d-f-m-n-e)','[\"- In this chapter we learn how to listen to the first sound of words and write them down.\",\"- The letters we focus on are d, f, m, n and e.\",\"- Words that start with these letters are called *initial sound words*.\",\"- Example: **duck** starts with the sound \\/d\\/; **fox** starts with \\/f\\/; **mango** starts with \\/m\\/; **nest** starts with \\/n\\/; **elephant** starts with \\/e\\/.\",\"- We practice by looking, listening and repeating the words.\",\"- We also trace the letters to help with handwriting.\",\"- Remember: the first sound is the letter that appears at the beginning of the word.\",\"- Words that sound the same but are spelled differently are not the focus here.\",\"- Practice makes the sounds clear and easy to write.\",\"- Keep a list of new words that start with d, f, m, n, e and add them to your notebook.\"]','[{\"q\":\"Which of these words starts with the sound \'d\'?\",\"options\":[\"fox\",\"mug\",\"doll\",\"nest\"],\"answer\":2,\"explain\":\"The text lists \'doll\' under the sound \'d\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the sound \'f\'?\",\"options\":[\"duck\",\"fan\",\"mat\",\"egg\"],\"answer\":1,\"explain\":\"The text lists \'fan\' under the sound \'f\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Look at the words: mug, mobile, mango, mat. What sound do they all start with?\",\"options\":[\"d\",\"f\",\"m\",\"n\"],\"answer\":2,\"explain\":\"All these words are grouped under the letter \'m\' in the text.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"Which of these words starts with the sound \'e\'?\",\"options\":[\"elbow\",\"nurse\",\"door\",\"farmer\"],\"answer\":0,\"explain\":\"The text lists \'elbow\' as a word starting with \'e\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"If you see a \'nest\', which letter sound should you match it with?\",\"options\":[\"d\",\"f\",\"m\",\"n\"],\"answer\":3,\"explain\":\"In the text, \'nest\' is listed under the sound \'n\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"Which word belongs to the group starting with \'f\'?\",\"options\":[\"fish\",\"doll\",\"mat\",\"eight\"],\"answer\":0,\"explain\":\"The word \'fish\' starts with \'f\' as per the text.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"Which word does NOT start with the sound \'d\'?\",\"options\":[\"den\",\"duck\",\"door\",\"fox\"],\"answer\":3,\"explain\":\"Fox starts with \'f\', while den, duck, and door start with \'d\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"Which word starts with the sound \'n\'?\",\"options\":[\"mango\",\"nail\",\"elephant\",\"duck\"],\"answer\":1,\"explain\":\"The text lists \'nail\' under the sound \'n\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Look at the list: egg, elbow, elephant, eight. What is the common starting letter?\",\"options\":[\"d\",\"f\",\"m\",\"e\"],\"answer\":3,\"explain\":\"All these words are grouped under the letter \'e\' in the text.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"Which animal starts with the sound \'f\' in the text?\",\"options\":[\"duck\",\"fox\",\"elephant\",\"nurse\"],\"answer\":1,\"explain\":\"The text lists \'fox\' under the sound \'f\'.\",\"topic\":\"Exercise\",\"part\":6,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21123,1,1,'English','en','Tip-Tap, Tip-Tap','[\"Tip‑Tap is a fun way to learn about rain and seasons.\",\"Rain falls from the sky and makes splish‑splish sounds.\",\"The song talks about two seasons: Winter and Summer.\",\"In Winter the sun goes down early and it can be cold.\",\"In Summer the sun is bright and we enjoy the warm weather.\",\"The words ‘pitter‑patter’ and ‘ping‑pong’ describe the sound of raindrops.\",\"We can listen, sing, and repeat the song to remember the words.\",\"The song mentions two tall trees and a big blue boat.\",\"The picture shows a blue bag, a black bag, a big blue boat, and a big brown ball.\",\"We can use the song to practice listening and speaking skills.\",\"Tip‑Tap helps children learn new words in a playful way.\",\"The song uses simple sentences that are easy to understand.\",\"The rhythm of the song helps children remember the words better.\",\"We can ask children which season they like most and why.\",\"We can practice the words by making our own rain sounds with hands.\"]','[{\"q\":\"From where does the rain fall in the poem?\",\"options\":[\"From the trees\",\"From the sky\",\"From the sun\",\"From the ground\"],\"answer\":1,\"explain\":\"The poem states, \'Rain falls from the sky\'.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Who are the two children mentioned in the poem?\",\"options\":[\"Ram and Shyam\",\"Hari and Pari\",\"Tip and Tap\",\"Tick and Tack\"],\"answer\":1,\"explain\":\"The text mentions \'Hari and Pari\' jumping with joy.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Which sound does the rain make in the poem?\",\"options\":[\"Ding-dong\",\"Zig-zag\",\"Tip-Tap\",\"Tick-tack\"],\"answer\":2,\"explain\":\"The poem repeats the sound \'Tip-Tap, Tip-Tap\' for the rain.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What does the sun do when it goes down?\",\"options\":[\"It says hello\",\"It waves goodbye\",\"It starts to rain\",\"It jumps with joy\"],\"answer\":1,\"explain\":\"The poem says, \'The sun goes down Waving good bye.\'\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Which word from the \'Listen and repeat\' list rhymes with \'zig-zag\'?\",\"options\":[\"zip-zap\",\"ding-dong\",\"tip-top\",\"sing-song\"],\"answer\":0,\"explain\":\"In the list provided, \'zip-zap\' follows the same rhyming pattern as \'zig-zag\'.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"What do Hari and Pari do because they are happy?\",\"options\":[\"They flow by\",\"They go down\",\"They jump with joy\",\"They wave goodbye\"],\"answer\":2,\"explain\":\"The text says \'Hari and Pari Jump with joy.\'\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"What sound is used to describe the water flowing by?\",\"options\":[\"Tip-tap\",\"Splish-splish\",\"Pitter-patter\",\"Ping-pong\"],\"answer\":1,\"explain\":\"The poem says, \'Splish-splish, splish-splish Water flows by.\'\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"In the list \'tick-tack, zig-zag, ding-dong\', which word comes next?\",\"options\":[\"tip-top\",\"rainy\",\"summer\",\"sky\"],\"answer\":0,\"explain\":\"According to the \'Listen and repeat\' section, \'tip-top\' follows \'ding-dong\'.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"Which of these seasons is mentioned in the textbook text?\",\"options\":[\"Spring\",\"Autumn\",\"Winter\",\"Monsoon\"],\"answer\":2,\"explain\":\"The text lists \'Rainy Winter Summer\' as choices for seasons.\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"What happens to the water in the poem?\",\"options\":[\"It goes down\",\"It waves goodbye\",\"It flows by\",\"It jumps up\"],\"answer\":2,\"explain\":\"The poem states, \'Water flows by.\'\",\"topic\":\"Listen and repeat.\",\"part\":3,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21124,1,1,'English','en','We want rain','[\"- Rain is water that falls from clouds.\",\"- Clouds are made of tiny water droplets or ice crystals.\",\"- When clouds get heavy, they release rain.\",\"- Rain helps plants grow and keeps rivers full.\",\"- People ask for rain when they need water for crops or play.\",\"- The story shows different characters asking for rain.\",\"- A peacock wants rain to dance.\",\"- A fish wants rain to have more water.\",\"- A farmer wants rain to sow seeds.\",\"- Raju wants rain to sail paper boats.\",\"- Rain can be gentle or heavy, like a shower.\",\"- After rain, puddles form where people can play.\",\"- Rain brings joy and helps nature.\",\"- Children wave goodbye when the cloud moves on.\",\"- Asking for rain is a way to show we need water.\",\"- Rain is important for animals, plants, and people.\",\"- Weather changes can bring sunshine, clouds, or rain.\",\"- Rain is part of the water cycle: evaporation, condensation, precipitation.\",\"- The story teaches that rain is helpful and fun.\",\"- Rain can be described as “Splash! Splash!” when it falls.\",\"- Rain is a natural event that we can’t control but can hope for.\",\"- In the story, the cloud brings rain to everyone’s needs.\",\"- Rain helps keep the earth cool and clean.\",\"- Children learn to listen to the weather and enjoy nature.\"]','[{\"q\":\"What was in the sky at the beginning of the story?\",\"options\":[\"A bright sun\",\"A dark cloud\",\"A white bird\",\"A silver moon\"],\"answer\":1,\"explain\":\"The text states, \'A dark cloud was in the sky.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Who said, \'I want to sow the seeds\'?\",\"options\":[\"Raju\",\"The fish\",\"The farmer\",\"The peacock\"],\"answer\":2,\"explain\":\"The text mentions, \'The farmer said, “Please rain, I want to sow the seeds.”\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Why did the fish want the rain to come?\",\"options\":[\"To dance\",\"To sail boats\",\"To plant seeds\",\"To have more water\"],\"answer\":3,\"explain\":\"The fish said, \'Please rain, I want more water.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What did Raju want to do with paper boats?\",\"options\":[\"Eat them\",\"Sail them\",\"Color them\",\"Throw them away\"],\"answer\":1,\"explain\":\"Raju said, \'Please rain, I want to sail paper boats.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what is the cloud doing?\",\"options\":[\"Sleeping in the sky\",\"Raining in a shower\",\"Hiding the sun\",\"Blowing wind\"],\"answer\":1,\"explain\":\"The figure shows the cloud raining, which matches the text \'The cloud rained in a shower.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"1\\/028_103.jpg\"},{\"q\":\"In the given figure, what is the peacock doing while it rains?\",\"options\":[\"It is flying away\",\"It is drinking water\",\"It is dancing\",\"It is looking for food\"],\"answer\":2,\"explain\":\"The figure shows the peacock with its feathers spread, which matches the text \'The peacock danced.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"1\\/029_101.jpg\"},{\"q\":\"What sound did Raju and his friends make in the puddle?\",\"options\":[\"Cuckoo! Cuckoo!\",\"Splash! Splash!\",\"Ding! Dong!\",\"Beep! Beep!\"],\"answer\":1,\"explain\":\"The text describes the sound as \'Splash ! Splash ! Splash !\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"What did the farmer do after the cloud rained?\",\"options\":[\"He started planting\",\"He went to sleep\",\"He sailed a boat\",\"He started dancing\"],\"answer\":0,\"explain\":\"The text states, \'The farmer started planting.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"How did the fish swim after it rained?\",\"options\":[\"Sadly\",\"Merrily\",\"Quietly\",\"Slowly\"],\"answer\":1,\"explain\":\"The text says, \'The fish swam merrily.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"Where did Raju and his friends have a wonderful time?\",\"options\":[\"In the house\",\"On the tree\",\"In the puddle\",\"In the sky\"],\"answer\":2,\"explain\":\"The text says they \'had a wonderful time in the puddle.\'\",\"topic\":\"The cloud rained\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"What filled everybody’s heart with joy?\",\"options\":[\"The sun\",\"The cloud\",\"The moon\",\"The stars\"],\"answer\":1,\"explain\":\"The text states that the cloud filled everybody\'s heart with joy.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What did the cloud fill hearts with?\",\"options\":[\"Joy\",\"Water\",\"Food\",\"Toys\"],\"answer\":0,\"explain\":\"The text says the cloud filled hearts with joy.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What did the cloud do after filling hearts with joy?\",\"options\":[\"It stopped\",\"It moved on\",\"It cried\",\"It slept\"],\"answer\":1,\"explain\":\"The text says \'It moved on\' after filling hearts with joy.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Who waved good bye?\",\"options\":[\"The birds\",\"The children\",\"The trees\",\"The flowers\"],\"answer\":1,\"explain\":\"The text mentions that all the children waved good bye.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"How many children waved good bye?\",\"options\":[\"One child\",\"Two children\",\"Some children\",\"All the children\"],\"answer\":3,\"explain\":\"The text specifically says \'All the children\' waved.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What action did the children do when the cloud moved?\",\"options\":[\"They jumped\",\"They ran\",\"They waved good bye\",\"They sat down\"],\"answer\":2,\"explain\":\"The text states the children waved good bye as the cloud moved.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"In the sentence \'It moved on\', what does \'It\' refer to?\",\"options\":[\"The heart\",\"The cloud\",\"The joy\",\"The children\"],\"answer\":1,\"explain\":\"In the context of the passage, \'It\' refers to the cloud that was moving.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Why did the children wave?\",\"options\":[\"To say hello\",\"To say good bye\",\"To ask for food\",\"To start playing\"],\"answer\":1,\"explain\":\"The text explicitly says they \'waved good bye\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which word in the text means the same as \'everyone\'?\",\"options\":[\"Cloud\",\"Joy\",\"Everybody\",\"Children\"],\"answer\":2,\"explain\":\"Everybody and everyone have the same meaning in this context.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Based on the text, how did the people feel when they saw the cloud?\",\"options\":[\"Sad\",\"Happy\",\"Angry\",\"Sleepy\"],\"answer\":1,\"explain\":\"The word \'joy\' indicates that the people felt happy.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21125,1,1,'English','en','Vegetables','[\"Vegetables are food that grow in the ground or on plants.\",\"They give us vitamins, minerals and fibre.\",\"Common vegetables: carrot, potato, pumpkin, cabbage, peas, beans, spinach, corn, cauliflower, tomato, brinjal (eggplant).\",\"Carrot is orange and crunchy.\",\"Potato is brown and round, good for making chips.\",\"Pumpkin is big, orange and used in pies.\",\"Cabbage is green or purple and can be eaten raw or cooked.\",\"Peas are small green balls that grow in pods.\",\"Beans grow long and green, good in salads.\",\"Spinach is leafy green, rich in iron.\",\"Corn has yellow kernels, can be eaten on the cob.\",\"Cauliflower is white and looks like a small tree.\",\"Tomato is red, juicy and used in sauces.\",\"Vegetables help keep our bodies healthy and strong.\",\"We can eat them boiled, steamed, roasted or raw.\",\"Eating a variety of vegetables gives us many nutrients.\"]','[{\"q\":\"According to the poem, which vegetables are \'big and brown\'?\",\"options\":[\"Carrots\",\"Potatoes\",\"Peas\",\"Beans\"],\"answer\":1,\"explain\":\"The poem mentions \'Big brown potatoes\'.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Which vegetable is mentioned along with \'carrots\' in the first line of the poem?\",\"options\":[\"Spinach\",\"Pumpkins\",\"Tomatoes\",\"Brinjals\"],\"answer\":1,\"explain\":\"The first line of the poem is \'Carrots and pumpkins\'.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"In the poem, what color are the beans?\",\"options\":[\"Red\",\"Blue\",\"Green\",\"Yellow\"],\"answer\":2,\"explain\":\"The poem describes them as \'Long green beans\'.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Complete the sentence from the poem: \'So many vegetables, ____ for you.\'\",\"options\":[\"Bad\",\"Good\",\"Hot\",\"Cold\"],\"answer\":1,\"explain\":\"The poem ends with the line \'Good for you\'.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"If someone asks \'Which vegetable do you like?\', how should you start your answer according to the Practice section?\",\"options\":[\"I am...\",\"I like...\",\"I have...\",\"I go...\"],\"answer\":1,\"explain\":\"The Practice section shows the response: \'I like carrot.\'\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"Which of these is a vegetable listed in the \'Look, listen and say\' section?\",\"options\":[\"Apple\",\"Mango\",\"Brinjal\",\"Banana\"],\"answer\":2,\"explain\":\"Brinjal is one of the vegetables listed in the \'Look, listen and say\' section.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"Which vegetable in the poem is described as \'long\'?\",\"options\":[\"Corn\",\"Spinach\",\"Beans\",\"Cabbages\"],\"answer\":2,\"explain\":\"The poem says \'Long green beans\'.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"In the given figure, which vegetable is shown at the very top on the \'Left\' side?\",\"options\":[\"Onion\",\"Pineapple\",\"Capsicum\",\"Ladyfinger\"],\"answer\":2,\"explain\":\"The top-most picture on the left side is a green capsicum.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"1\\/031_102.jpg\"},{\"q\":\"In the given figure, what is the teacher holding in his hand to show the students?\",\"options\":[\"A rose\",\"A pineapple\",\"A carrot\",\"A tomato\"],\"answer\":1,\"explain\":\"The teacher is holding a picture of a pineapple.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"1\\/031_102.jpg\"},{\"q\":\"Which vegetable is mentioned in the \'Look, listen and say\' list but NOT in the poem?\",\"options\":[\"Carrot\",\"Potato\",\"Tomato\",\"Spinach\"],\"answer\":2,\"explain\":\"Tomato is in the list but not mentioned in the poem text provided.\",\"topic\":\"Practice\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"What should you do if you like a vegetable?\",\"options\":[\"Jump left\",\"Jump right\",\"Sit down\",\"Run away\"],\"answer\":1,\"explain\":\"The text says to jump right if you like something.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What should you do if you don\'t like a vegetable?\",\"options\":[\"Jump right\",\"Jump up\",\"Jump left\",\"Jump down\"],\"answer\":2,\"explain\":\"The text says to jump left if you don\'t like something.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"According to the table, what does \'Left\' stand for?\",\"options\":[\"Like\",\"Don\'t like\",\"Listen\",\"Act\"],\"answer\":1,\"explain\":\"The table shows \'Left\' corresponds to \'Don\'t like\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"According to the table, what does \'Right\' stand for?\",\"options\":[\"Don\'t like\",\"Jump\",\"Listen\",\"Like\"],\"answer\":3,\"explain\":\"The table shows \'Right\' corresponds to \'Like\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If your teacher asks \'Do you like carrots?\' and you like them, which way will you jump?\",\"options\":[\"Left\",\"Right\",\"Backwards\",\"Forwards\"],\"answer\":1,\"explain\":\"Since you like them, you must jump to the right side.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"If you do not like a vegetable, which way will you jump?\",\"options\":[\"Right\",\"Left\",\"Up\",\"Down\"],\"answer\":1,\"explain\":\"The instruction for \'don\'t like\' is to jump left.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"What is the first thing you must do before you act?\",\"options\":[\"Jump\",\"Listen\",\"Run\",\"Sleep\"],\"answer\":1,\"explain\":\"The instruction says \'Listen and act\', so listening comes first.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Look at the table. Which word is matched with the side \'Right\'?\",\"options\":[\"Don\'t\",\"Jump\",\"Like\",\"Left\"],\"answer\":2,\"explain\":\"The table shows \'Like\' is under the \'Right\' column.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"If a student jumps to the left, what are they showing?\",\"options\":[\"They like the vegetable\",\"They are happy\",\"They don\'t like the vegetable\",\"They want to eat\"],\"answer\":2,\"explain\":\"Jumping left is the action for not liking something.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which side is the opposite of \'Like\' in this game?\",\"options\":[\"Right\",\"Up\",\"Left\",\"Down\"],\"answer\":2,\"explain\":\"Like is Right, so the opposite (Don\'t like) is Left.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21126,1,1,'English','en','Fingers','[\"Fingers are parts of the hand that help us touch, hold, and feel things.\",\"There are five fingers on each hand: thumb, index, middle, ring, and little finger.\",\"The thumb is on the side of the hand and can touch the other four fingers.\",\"The index finger is the second finger from the thumb and is used for pointing.\",\"The middle finger is the longest finger and is in the middle of the hand.\",\"The ring finger is next to the middle finger and is used for wearing rings.\",\"The little finger is the smallest finger and is at the far end of the hand.\",\"Each finger has three small bones called phalanges, except the thumb which has two.\",\"The joints in the fingers allow them to bend and straighten easily.\",\"The skin on the fingers is smooth and helps us feel textures.\",\"The muscles in the hand let us open and close our fingers quickly.\",\"The nails grow on the tips of the fingers and protect the fingertips.\",\"When we use our fingers, we can do many things like writing, drawing, and playing games.\",\"The fingers are important for everyday tasks like eating, tying shoes, and using a phone.\",\"The hand can make a fist by curling all the fingers together.\",\"The fingers can also make a wave by moving them up and down.\",\"The thumb can touch each finger, which helps us grip objects firmly.\",\"The fingers work together to give us a good sense of touch and pressure.\",\"We can count from one to five by showing each finger one by one.\",\"The fingers are part of the arm and are connected to the wrist.\",\"The wrist is the joint that connects the hand to the arm.\",\"The palm is the flat part of the hand between the wrist and the fingers.\",\"The fingers are covered by a thin layer of skin that keeps them moist and healthy.\",\"When we play music, the fingers help us press keys or strings.\",\"The fingers can also be used to give a high‑five or a friendly wave.\"]','[{\"q\":\"Where should you put your finger first according to the poem?\",\"options\":[\"On your nose\",\"On your cheek\",\"On your toes\",\"On your palm\"],\"answer\":1,\"explain\":\"The poem starts with \'Put a finger on your cheek\'.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What should you do with your finger \'round and round\'?\",\"options\":[\"Clap it\",\"Point it\",\"Turn it\",\"Climb it\"],\"answer\":2,\"explain\":\"The poem says, \'Turn your finger round and round\'.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Where do you point your fingers after turning them?\",\"options\":[\"To your nose\",\"To your cheek\",\"To your toes\",\"To your wrist\"],\"answer\":2,\"explain\":\"The poem says, \'And point them to your toes\'.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which of these is a part of the hand mentioned in the text?\",\"options\":[\"Knee\",\"Elbow\",\"Wrist\",\"Shoulder\"],\"answer\":2,\"explain\":\"The text lists \'wrist\' as a part of the hand.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What do you do to show the fingers are \'being good\'?\",\"options\":[\"Give them a clap\",\"Make them dance\",\"Make them climb\",\"Point to toes\"],\"answer\":0,\"explain\":\"The text says, \'Give them a clap for being good\'.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If fingers \'climb a hill\', what kind of movement are they doing?\",\"options\":[\"Moving down\",\"Moving up\",\"Staying still\",\"Turning round\"],\"answer\":1,\"explain\":\"Climbing a hill implies moving upwards.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which finger is listed right after the \'index finger\'?\",\"options\":[\"Thumb\",\"Little finger\",\"Middle finger\",\"Ring finger\"],\"answer\":3,\"explain\":\"The list order is: middle, index, ring, little, thumb.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What is the flat part of the hand called in the text?\",\"options\":[\"Palm\",\"Wrist\",\"Thumb\",\"Hill\"],\"answer\":0,\"explain\":\"The text lists \'palm\' as a part of the hand.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"When you put your fingers where they are \'still\', what are they doing?\",\"options\":[\"Dancing\",\"Clapping\",\"Not moving\",\"Turning\"],\"answer\":2,\"explain\":\"Being \'still\' means they are not moving.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which of these is NOT listed as a finger in the text?\",\"options\":[\"Index finger\",\"Middle finger\",\"Wrist\",\"Little finger\"],\"answer\":2,\"explain\":\"The wrist is a part of the hand, but it is not one of the fingers listed.\",\"topic\":\"Parts of the hand\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21127,1,1,'English','en','In the Park','[\"- A park is a place where people can play and relax.\",\"- In a park you can find many fun things like a slide, swing, and merry‑go‑round.\",\"- A ladder is used to climb up to higher places, like a tree or a playground structure.\",\"- A see‑saw is a long board that goes up and down when people sit on it.\",\"- A bench is a seat for people to sit and rest.\",\"- A sandpit is a shallow area filled with sand where children can dig and build sandcastles.\",\"- A fountain is a water feature that sprays water into the air.\",\"- A bicycle is a two‑wheel vehicle that you can ride by pedalling.\",\"- Flowers grow in the park and make it look pretty and fragrant.\",\"- Children can look, listen, and show the things they see in the park.\",\"- The teacher can ask children to point out different things in the picture of the park.\",\"- The park is a safe place for playing and learning about nature.\",\"- Children can use the slide to slide down and feel the wind.\",\"- The swing lets children go up and down while holding on tight.\",\"- The merry‑go‑round spins around and makes children laugh.\",\"- A bench is good for resting after playing.\",\"- A ladder helps reach higher places like a tree or a playground structure.\",\"- A fountain can cool the air with its water spray.\",\"- A bicycle needs pedalling to move forward.\",\"- Flowers give color and smell to the park.\",\"- The park is a good place to practice looking, listening, and showing.\",\"- Children can learn new words by naming the things in the park.\",\"- The teacher can use the picture to teach vocabulary and observation skills.\",\"- The park is a place where children can be happy and active.\"]','[{\"q\":\"Which of these items is mentioned in the park list?\",\"options\":[\"Slide\",\"Bed\",\"Table\",\"Sofa\"],\"answer\":0,\"explain\":\"The text lists \'slide\' as one of the items found in the park.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What can you find in the park according to the text?\",\"options\":[\"Kitchen\",\"Flowers\",\"Television\",\"Fridge\"],\"answer\":1,\"explain\":\"The text mentions \'flowers\' as an item in the park.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which item from the list is used for sitting?\",\"options\":[\"Bench\",\"Ladder\",\"Fountain\",\"Swing\"],\"answer\":0,\"explain\":\"A bench is a common park item used for sitting.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which item is used to slide down from a height?\",\"options\":[\"Slide\",\"Sandpit\",\"Bicycle\",\"Flowers\"],\"answer\":0,\"explain\":\"A slide is the equipment used for sliding down in a park.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Where do children play with sand in the park?\",\"options\":[\"Sandpit\",\"See-saw\",\"Fountain\",\"Ladder\"],\"answer\":0,\"explain\":\"A sandpit is a designated area filled with sand for playing.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which park item moves in a circular motion (round and round)?\",\"options\":[\"Merry-go-round\",\"Bench\",\"Slide\",\"Flowers\"],\"answer\":0,\"explain\":\"A merry-go-round is a park item that spins in a circle.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which item in the park list has water spraying out?\",\"options\":[\"Fountain\",\"Swing\",\"Ladder\",\"Bicycle\"],\"answer\":0,\"explain\":\"A fountain is a park feature that sprays water.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which item do you use to climb up to the top of a slide?\",\"options\":[\"Ladder\",\"Bench\",\"Sandpit\",\"Flowers\"],\"answer\":0,\"explain\":\"A ladder is used to climb up to reach the top of a slide.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which item requires two children to sit on opposite ends to go up and down?\",\"options\":[\"See-saw\",\"Fountain\",\"Bench\",\"Flowers\"],\"answer\":0,\"explain\":\"A see-saw works by two people balancing and moving up and down on opposite ends.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which item in the list can you ride to travel around the park?\",\"options\":[\"Bicycle\",\"Swing\",\"Slide\",\"Sandpit\"],\"answer\":0,\"explain\":\"A bicycle is a vehicle with wheels that you can ride.\",\"topic\":\"More Park Items\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21128,1,1,'English','en','Animals I Know','[\"Animals are living things that can move and eat food.\",\"There are two main groups: wild animals and pet animals.\",\"Wild animals live in forests, jungles, or fields and are not usually kept as pets.\",\"Examples of wild animals: tiger, lion, deer, bear, fox, wolf, goat, sheep, horse, cow, buffalo, gorilla, zebra, dog, cat.\",\"Some wild animals are dangerous like tiger and lion, while others are gentle like deer and goat.\",\"Pet animals are animals that people keep at home for company or help, such as dog, cat, goat, and horse.\",\"Animals have different parts: head, ears, eyes, nose, mouth, tail, legs, and sometimes wings or fins.\",\"They eat food that suits them: some eat plants (herbivores), some eat meat (carnivores), and some eat both (omnivores).\",\"Wild animals need to find food, water, and shelter on their own.\",\"Pet animals are fed by their owners and live in houses or barns.\",\"Animals communicate by sounds, body language, or signs, like a dog barking or a bird singing.\",\"The word “wild” means an animal that lives in nature and is not domesticated.\",\"The word “pet” means an animal that lives with people and is cared for.\",\"Animals have different habitats: forests, grasslands, deserts, oceans, and even cities.\",\"Knowing animal names helps us learn about nature and take care of the environment.\"]','[{\"q\":\"Which of these is a pet animal?\",\"options\":[\"cat\",\"tiger\",\"lion\",\"wolf\"],\"answer\":0,\"explain\":\"According to the text, the cat is listed under the \'Pet Animals\' category.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which of these is a wild animal?\",\"options\":[\"cow\",\"sheep\",\"zebra\",\"dog\"],\"answer\":2,\"explain\":\"The text lists the zebra under the \'Wild Animals\' category.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Where does a tiger live?\",\"options\":[\"pond\",\"den\",\"nest\",\"web\"],\"answer\":1,\"explain\":\"The text states that a tiger lives in a den.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which animal is listed as a wild animal in the text?\",\"options\":[\"ox\",\"buffalo\",\"horse\",\"gorilla\"],\"answer\":3,\"explain\":\"The gorilla is categorized as a wild animal in the provided text.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"A cow lives in a ______.\",\"options\":[\"beehive\",\"cowshed\",\"pond\",\"tree\"],\"answer\":1,\"explain\":\"The text pairs the cow with its home, the cowshed.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which animal lives in a pond?\",\"options\":[\"duck\",\"bee\",\"spider\",\"man\"],\"answer\":0,\"explain\":\"The text shows that a duck lives in a pond.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If you see a spider, where will you find its home?\",\"options\":[\"nest\",\"tree\",\"web\",\"den\"],\"answer\":2,\"explain\":\"The text links a spider to its home, which is a web.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which animal belongs to the same \'Wild Animals\' group as a deer and a fox?\",\"options\":[\"goat\",\"bear\",\"sheep\",\"cat\"],\"answer\":1,\"explain\":\"The bear is listed in the same \'Wild Animals\' group as the deer and fox.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Look at the pairs. Which one is correct according to the text?\",\"options\":[\"bird-pond\",\"bee-beehive\",\"tiger-tree\",\"monkey-den\"],\"answer\":1,\"explain\":\"The text correctly pairs the bee with the beehive.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which animal does NOT belong in the \'Pet Animals\' group?\",\"options\":[\"dog\",\"goat\",\"wolf\",\"horse\"],\"answer\":2,\"explain\":\"The wolf is listed under \'Wild Animals\', while the others are \'Pet Animals\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21129,1,1,'English','en','Fun with Sounds (h-l-r-s-i)','[\"- In this chapter we learn how to read and write letters that make the sounds h, l, r, s, and i.\",\"- The letter **h** makes the sound \\/h\\/ as in *hat* and *hill*.\",\"- The letter **l** makes the sound \\/l\\/ as in *lamp* and *lion*.\",\"- The letter **r** makes the sound \\/r\\/ as in *rat* and *ring*.\",\"- The letter **s** makes the sound \\/s\\/ as in *soap* and *socks*.\",\"- The letter **i** makes the sound \\/i\\/ as in *insect* and *inkpot*.\",\"- Practice by looking at the picture, listening, and repeating the word.\",\"- Trace each letter with your finger or pencil to remember its shape.\",\"- Try to think of other words that start with these letters.\",\"- Reading the words aloud helps you hear the sound and remember the spelling.\",\"- Writing the words helps you remember the letters and their order.\"]','[{\"q\":\"Which of these words starts with the letter \'h\' in the text?\",\"options\":[\"lamp\",\"hat\",\"inkpot\",\"rose\"],\"answer\":1,\"explain\":\"The text lists \'hat\' under the letter \'h\'.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the letter \'i\'?\",\"options\":[\"insect\",\"socks\",\"lion\",\"ruler\"],\"answer\":0,\"explain\":\"The text lists \'insect\' under the letter \'i\'.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"Look at the words: lamp, lemon, lion, lock. What is the starting letter for all these words?\",\"options\":[\"h\",\"i\",\"l\",\"r\"],\"answer\":2,\"explain\":\"These words are grouped under the letter \'l\' in the text.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"According to the \'For the Teacher\' section, what should the teacher ask the children?\",\"options\":[\"To draw a picture\",\"To go home\",\"For more words like this\",\"To keep quiet\"],\"answer\":2,\"explain\":\"The \'For the Teacher\' note specifically says to ask children for more words like this.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"If you are tracing the letter \'s\', which word from the text would you be practicing?\",\"options\":[\"sofa\",\"hill\",\"ring\",\"igloo\"],\"answer\":0,\"explain\":\"\'sofa\' is listed under the letter \'s\' in the text.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"Which of these words starting with \'r\' is mentioned in the text?\",\"options\":[\"rabbit\",\"ruler\",\"rain\",\"rope\"],\"answer\":1,\"explain\":\"\'ruler\' is one of the four words listed under the letter \'r\'.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"Which letter group contains the word \'igloo\'?\",\"options\":[\"h\",\"l\",\"i\",\"s\"],\"answer\":2,\"explain\":\"\'igloo\' is categorized under the letter \'i\' in the text.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"Which word does NOT belong to the \'s\' group in the text?\",\"options\":[\"soap\",\"sun\",\"socks\",\"hen\"],\"answer\":3,\"explain\":\"\'hen\' belongs to the \'h\' group, not the \'s\' group.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"Which activity involves using your finger or pencil on the letters?\",\"options\":[\"Listen\",\"Repeat\",\"Trace\",\"Look\"],\"answer\":2,\"explain\":\"Section \'b\' instructs to trace the letters with your finger\\/pencil.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"Which word is listed under the letter \'l\' in the text?\",\"options\":[\"lemon\",\"hut\",\"injection\",\"rat\"],\"answer\":0,\"explain\":\"\'lemon\' is one of the words listed for the letter \'l\'.\",\"topic\":\"For the Teacher\",\"part\":8,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21130,1,1,'English','en','Birds can fly','[\"Birds can fly in the sky.\",\"Frogs can jump very high.\",\"Horses can run in the forest.\",\"Bunnies can hop on the grass.\",\"Ducks can swim deep in water.\",\"Dogs can walk on the ground.\",\"Listen, sing, read and act to learn.\",\"Listen and say to practice sounds.\",\"Look, listen and learn to understand words.\",\"Use simple sentences to describe animals’ actions.\",\"Remember the words: jump, hop, fly, walk, run, swim.\",\"Use the picture of a bird to help remember its parts.\",\"Birds have feathers, wings, a beak, a tail and claws.\",\"A bird’s eye helps it see while flying.\",\"Birds use their wings to fly and their feet to walk.\",\"Use short sentences for first‑grade reading.\",\"Use repetition to remember new words.\",\"Use pictures to connect words with actions.\",\"Use the song “Birds can fly” to practice listening.\",\"Use the teacher’s voice to model correct pronunciation.\"]','[{\"q\":\"Where do birds fly according to the poem?\",\"options\":[\"Up in the sky\",\"Deep in the water\",\"In the forest\",\"On the grass\"],\"answer\":0,\"explain\":\"The text states \'Birds can fly, birds can fly, Up in the sky\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"What do ducks do in the water?\",\"options\":[\"Run\",\"Swim\",\"Hop\",\"Jump\"],\"answer\":1,\"explain\":\"The text says \'Ducks can swim, ducks can swim, Deep in the water\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"Where do dogs walk?\",\"options\":[\"In the sky\",\"In the forest\",\"On the ground\",\"In the water\"],\"answer\":2,\"explain\":\"The text states \'Dogs can walk, dogs can walk, On the ground\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"What action do horses do in the forest?\",\"options\":[\"Run\",\"Swim\",\"Fly\",\"Hop\"],\"answer\":0,\"explain\":\"The text says \'Horses can run, horses can run, In the forest\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"Where do bunnies hop?\",\"options\":[\"In the sky\",\"On the grass\",\"In the water\",\"On the ground\"],\"answer\":1,\"explain\":\"The text states \'Bunnies can hop, bunnies can hop, On the grass\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what is the girl pretending to do?\",\"options\":[\"Swim like a duck\",\"Fly like a bird\",\"Run like a horse\",\"Jump like a frog\"],\"answer\":1,\"explain\":\"The figure shows a girl with arms spread like wings, imitating the birds flying around her.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"1\\/038_101.jpg\"},{\"q\":\"In the given figure, what action is the boy doing along with the animals?\",\"options\":[\"Walking\",\"Running\",\"Jumping\",\"Swimming\"],\"answer\":2,\"explain\":\"The figure shows the boy jumping high into the air just like the frogs.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"1\\/038_102.jpg\"},{\"q\":\"If you want to act like a bunny, what should you do?\",\"options\":[\"Run in the forest\",\"Walk on the ground\",\"Hop on the grass\",\"Swim in the water\"],\"answer\":2,\"explain\":\"The poem links bunnies to hopping on the grass.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"Which animal moves \'very very high\'?\",\"options\":[\"Dog\",\"Duck\",\"Frog\",\"Horse\"],\"answer\":2,\"explain\":\"The text says \'Frogs can jump... Very very high\'.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"Based on the poem, which animal moves in a different way than a frog?\",\"options\":[\"A bunny hops\",\"A frog jumps\",\"A frog goes high\",\"A boy jumps too\"],\"answer\":0,\"explain\":\"The text distinguishes between a frog jumping and a bunny hopping.\",\"topic\":\"Listen, sing and act.\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"Which of these is a bird mentioned in the text?\",\"options\":[\"Lion\",\"Sparrow\",\"Tiger\",\"Dog\"],\"answer\":1,\"explain\":\"The text lists \'sparrow\' as one of the birds.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which part of a bird\'s body is listed in the text?\",\"options\":[\"Hand\",\"Nose\",\"Wing\",\"Ear\"],\"answer\":2,\"explain\":\"The text includes \'wing\' in the list of bird body parts.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which action word is found in the list provided?\",\"options\":[\"Sleep\",\"Eat\",\"Swim\",\"Read\"],\"answer\":2,\"explain\":\"\'Swim\' is one of the action words listed in the text.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What does the cat do in the phrase from the text?\",\"options\":[\"Cuts carrot\",\"Runs fast\",\"Jumps high\",\"Hops\"],\"answer\":0,\"explain\":\"The text contains the phrase \'Cat cuts carrot.\'\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"In the text, what kind of tree is mentioned along with a \'Tall tree\'?\",\"options\":[\"Big tree\",\"Green tree\",\"Tiny tree\",\"Red tree\"],\"answer\":2,\"explain\":\"The text uses the phrase \'Tall tree tiny tree.\'\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"How many funny frogs are mentioned in the text?\",\"options\":[\"Four\",\"Five\",\"Six\",\"Two\"],\"answer\":1,\"explain\":\"The text includes the phrase \'Five funny frogs.\'\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Complete the phrase from the text: \'Happy hen\'s ____\'.\",\"options\":[\"Hat\",\"Hill\",\"House\",\"Home\"],\"answer\":2,\"explain\":\"The text lists the phrase \'Happy hen\'s house.\'\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which of these birds is included in the list of birds in the text?\",\"options\":[\"Peacock\",\"Rabbit\",\"Fish\",\"Snake\"],\"answer\":0,\"explain\":\"The text lists \'peacock\' as one of the birds.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which word from the text describes a part of a bird\'s body rather than an action?\",\"options\":[\"Jump\",\"Beak\",\"Run\",\"Walk\"],\"answer\":1,\"explain\":\"\'Beak\' is a body part, while the others are action words.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Look at the phrase \'Five funny frogs\'. What letter do all these words start with?\",\"options\":[\"T\",\"C\",\"H\",\"F\"],\"answer\":3,\"explain\":\"Every word in \'Five funny frogs\' starts with the letter \'F\'.\",\"topic\":\"Look, listen and learn.\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21131,1,1,'English','en','Birthday Party','[\"Birthday Party is a special day when we celebrate a person’s birth.\",\"We invite friends and family to join the party.\",\"Common party items: balloons, toys, gifts, masks, greeting cards, birthday caps, camera, toffees, flowers, snacks, candle, crown.\",\"We give gifts and eat snacks together.\",\"We sing the birthday song and blow out the candle.\",\"We play games and have fun with friends.\",\"We say ‘Happy Birthday’ to the birthday person.\",\"We cut the cake after blowing the candle.\",\"We wear a party hat or crown to look festive.\",\"We take pictures with a camera to remember the day.\",\"We give a small gift to each guest as a thank‑you.\",\"We keep the party clean and tidy after it’s over.\",\"We thank everyone for coming and say goodbye.\",\"We remember the birthday person’s wishes for the next year.\",\"We celebrate with smiles, laughter, and good food.\"]','[{\"q\":\"Which of these items is mentioned in the birthday list?\",\"options\":[\"balloons\",\"bicycle\",\"school bag\",\"pencil box\"],\"answer\":0,\"explain\":\"The text lists \'balloons\' as one of the items to look for.\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What greeting do Anju and Sanju use?\",\"options\":[\"Hello\",\"Good morning\",\"Namaste\",\"Hi\"],\"answer\":2,\"explain\":\"The dialogue starts with \'Namaste, Anju\' and \'Namaste, Sanju\'.\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What is the answer to the question \'How are you?\' in the text?\",\"options\":[\"I am happy\",\"I am fine\",\"I am sad\",\"I am good\"],\"answer\":1,\"explain\":\"In the dialogue, the response to \'How are you?\' is \'I am fine.\'\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What is the person doing when asked \'What are you doing?\'\",\"options\":[\"Playing games\",\"Eating snacks\",\"Doing nothing\",\"Reading a book\"],\"answer\":2,\"explain\":\"The text says, \'What are you doing? I am doing nothing.\'\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which item from the list is something you wear on your head?\",\"options\":[\"camera\",\"birthday caps\",\"toffees\",\"flowers\"],\"answer\":1,\"explain\":\"Birthday caps are worn on the head during a party.\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"If you want to invite a friend to play like Sanju, what should you say?\",\"options\":[\"Go away\",\"Can you play with me?\",\"I am busy\",\"Sit down\"],\"answer\":1,\"explain\":\"The text shows the invitation: \'Can you play with me?\'\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Who are the two characters speaking in the dialogue?\",\"options\":[\"Anju and Sanju\",\"Amit and Sumit\",\"Anu and Sonu\",\"Ajay and Sanjay\"],\"answer\":0,\"explain\":\"The names mentioned in the dialogue are Anju and Sanju.\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What does the friend say after agreeing to play?\",\"options\":[\"Let\'s play then\",\"I want to sleep\",\"No, thank you\",\"Wait for me\"],\"answer\":0,\"explain\":\"After saying \'Yes\', the text says, \'Let\'s play then.\'\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What is the final call to action at the end of the conversation?\",\"options\":[\"Stop\",\"Come on\",\"Goodbye\",\"Thank you\"],\"answer\":1,\"explain\":\"The conversation ends with the phrase \'Come on.\'\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"Which of these is a sweet treat listed in the items?\",\"options\":[\"mask\",\"toffees\",\"camera\",\"greeting cards\"],\"answer\":1,\"explain\":\"Toffees are the sweet treats mentioned in the list of party items.\",\"topic\":\"Let\'s play then\",\"part\":4,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21132,1,1,'English','en','Fun with Sounds (g-j-k-q-o)','[\"- The letters g, j, k, q, and o are special sounds in this chapter.\",\"- Each letter has a sound that starts a word, e.g., g = grass, j = jacket, k = kangaroo, q = queen, o = owl.\",\"- You can practice by looking at the word, listening to the sound, and repeating it.\",\"- Trace the letters with your finger or pencil to remember their shapes.\",\"- Words that start with these letters are called ‘initial sound words’.\",\"- The sound of the letter is the first sound you hear in the word.\",\"- When you see a word, try to find the letter that makes that sound.\",\"- Listening to the sound helps you read new words faster.\",\"- Repeating the word helps you remember the sound and the word together.\",\"- You can make a list of words for each letter to practice at home.\",\"- Use the same letter in different words to see how the sound stays the same.\",\"- The letters g, j, k, q, and o are all consonants that make a single sound.\",\"- The sound of g can be soft (like in giraffe) or hard (like in goat).\",\"- The sound of q is always followed by u in English words.\",\"- Practice writing the letters and saying the sound at the same time.\"]','[{\"q\":\"Which of these words starts with the letter \'g\'?\",\"options\":[\"kite\",\"goat\",\"orange\",\"queen\"],\"answer\":1,\"explain\":\"According to the text, \'goat\' is listed under the letter \'g\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the letter \'j\'?\",\"options\":[\"jar\",\"grass\",\"kettle\",\"owl\"],\"answer\":0,\"explain\":\"The text lists \'jar\' as a word starting with the letter \'j\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which of these animals starts with the letter \'o\'?\",\"options\":[\"guitar\",\"ostrich\",\"jacket\",\"quill\"],\"answer\":1,\"explain\":\"The text includes \'ostrich\' in the list of words starting with \'o\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word starts with the letter \'k\'?\",\"options\":[\"gate\",\"kangaroo\",\"queen\",\"ox\"],\"answer\":1,\"explain\":\"The text lists \'kangaroo\' as a word starting with the letter \'k\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word rhymes with \'dog\' from the list?\",\"options\":[\"dot\",\"hop\",\"log\",\"pot\"],\"answer\":2,\"explain\":\"In the rhyming section, \'log\' is grouped with \'dog\' as they share the same ending sound.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word rhymes with \'top\'?\",\"options\":[\"mop\",\"hot\",\"fog\",\"jar\"],\"answer\":0,\"explain\":\"The text groups \'top\' and \'mop\' together in the rhyming words section.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Look at the list: \'dot, got, not, hot\'. Which word follows the same sound pattern?\",\"options\":[\"pot\",\"pop\",\"dog\",\"kite\"],\"answer\":0,\"explain\":\"The word \'pot\' belongs to the \'-ot\' sound group mentioned in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which word starts with the letter \'q\'?\",\"options\":[\"joker\",\"quill\",\"kettle\",\"grass\"],\"answer\":1,\"explain\":\"The text lists \'quill\' as a word starting with the letter \'q\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word does NOT belong in the \'-op\' sound group?\",\"options\":[\"top\",\"hop\",\"mop\",\"dog\"],\"answer\":3,\"explain\":\"\'dog\' belongs to the \'-og\' group, while the others belong to the \'-op\' group.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which word starts with the same sound as \'kettle\'?\",\"options\":[\"key\",\"queen\",\"gate\",\"jacket\"],\"answer\":0,\"explain\":\"Both \'kettle\' and \'key\' are listed under the letter \'k\' in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21133,1,1,'English','en','Water Bell','[]','[{\"q\":\"What is the first thing you should take out?\",\"options\":[\"Your water-bottle\",\"Your book\",\"Your pencil\",\"Your tiffin\"],\"answer\":0,\"explain\":\"The text starts with the instruction to take out your water-bottle.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"What part of the bottle do you need to open?\",\"options\":[\"The bottom\",\"The lid\",\"The bag\",\"The side\"],\"answer\":1,\"explain\":\"The text specifically says to \'Open the lid\'.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"What are you supposed to drink?\",\"options\":[\"Milk\",\"Juice\",\"Water\",\"Tea\"],\"answer\":2,\"explain\":\"The instruction given is to \'Drink water\'.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"What should you do immediately after drinking water?\",\"options\":[\"Open the lid\",\"Close the bottle\",\"Put it in your bag\",\"Take it out\"],\"answer\":1,\"explain\":\"According to the sequence, \'Close the bottle\' follows \'Drink water\'.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"Where should you put the bottle when you are finished?\",\"options\":[\"On the desk\",\"In your bag\",\"Under the chair\",\"In the cupboard\"],\"answer\":1,\"explain\":\"The final instruction is to \'Put it in your bag\'.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"Which action comes first in the list?\",\"options\":[\"Drink water\",\"Close the bottle\",\"Take out your water-bottle\",\"Open the lid\"],\"answer\":2,\"explain\":\"Taking out the bottle is the very first step mentioned.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"To drink water, you must first ____ the lid.\",\"options\":[\"Close\",\"Open\",\"Wash\",\"Find\"],\"answer\":1,\"explain\":\"The text indicates you must open the lid before you can drink.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"What is the correct order for the bottle\'s lid?\",\"options\":[\"Close then Open\",\"Open then Close\",\"Open then Drink\",\"Close then Drink\"],\"answer\":1,\"explain\":\"The text instructs to open the lid first, then later close the bottle.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"The instruction says to \'Close the ____\'.\",\"options\":[\"Bag\",\"Lid\",\"Bottle\",\"Door\"],\"answer\":2,\"explain\":\"The text explicitly says \'Close the bottle\'.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"If you are thirsty and your bottle is in your bag, what is your first step?\",\"options\":[\"Take out your water-bottle\",\"Drink water\",\"Close the bottle\",\"Open the lid\"],\"answer\":0,\"explain\":\"You must take the bottle out of the bag before you can do anything else.\",\"topic\":\"Put it in your bag\",\"part\":6,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21134,1,1,'English','en','Who ate the butter?','[\"Two cats found a piece of butter and wanted to eat it.\",\"They started to fight over the butter.\",\"A monkey saw them and decided to help.\",\"The monkey cut the butter into two equal parts.\",\"He said, “It’s mine!” and then “No, it’s mine!”\",\"The monkey made the parts smaller so they could share.\",\"He told the cats to stop fighting and share the butter.\",\"The cats agreed and ate the butter together.\",\"The story shows that sharing is better than fighting.\",\"The monkey’s idea helped everyone get a piece of butter.\",\"Ask children who ate the butter to practice listening.\",\"Use the story to talk about sharing and fairness.\",\"Make the children repeat the sentences to improve pronunciation.\",\"Draw the cats and the monkey to help remember the story.\",\"Use the story for a simple dialogue practice.\",\"Ask children to act out the story for fun.\",\"Explain that the monkey’s sharing made everyone happy.\",\"Use the story to teach the word “share”.\",\"Use the story to practice “I want” and “It’s mine”.\",\"Use the story to learn about fairness and kindness.\"]','[{\"q\":\"What did the two cats find in the story?\",\"options\":[\"A piece of bread\",\"A lump of butter\",\"A bowl of milk\",\"A small fish\"],\"answer\":1,\"explain\":\"The text states that two cats found a lump of butter.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"How many cats were fighting with each other?\",\"options\":[\"One\",\"Two\",\"Three\",\"Four\"],\"answer\":1,\"explain\":\"The story begins by mentioning two cats who found butter and started fighting.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"What did the cats say to each other while fighting?\",\"options\":[\"Let\'s share!\",\"It\'s mine!\",\"Thank you!\",\"Hello friend!\"],\"answer\":1,\"explain\":\"The text says the cats were fighting and saying, \'It\'s mine! No, It\'s mine!\'\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Who saw the cats fighting and came to help?\",\"options\":[\"A dog\",\"A bird\",\"A monkey\",\"A mouse\"],\"answer\":2,\"explain\":\"The text states, \'A monkey saw them. He said, Don\'t fight.\'\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"What did the monkey promise to do for the cats?\",\"options\":[\"Eat all the butter\",\"Make two equal parts\",\"Give them more butter\",\"Run away with the butter\"],\"answer\":1,\"explain\":\"The monkey said, \'I shall make two equal parts for you.\'\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what is the monkey doing with the butter?\",\"options\":[\"He is hiding it\",\"He is throwing it\",\"He is having a bite\",\"He is washing it\"],\"answer\":2,\"explain\":\"The picture shows the monkey with a piece of butter near his mouth and the text says he had a bite.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"1\\/046_101.jpg\"},{\"q\":\"If one part of the butter is bigger, what does the monkey do to make it smaller?\",\"options\":[\"He gives it to the cats\",\"He has a bite of it\",\"He adds more butter\",\"He cuts it with a knife\"],\"answer\":1,\"explain\":\"The monkey said, \'I shall have a bite and make it smaller.\'\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"In the given figure, how do the cats look while watching the monkey?\",\"options\":[\"They look happy and sleeping\",\"They are looking at the monkey with surprise\",\"They are playing with a ball\",\"They are running away from the monkey\"],\"answer\":1,\"explain\":\"The picture shows the cats looking up at the monkey while he eats the butter.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"1\\/046_101.jpg\"},{\"q\":\"Why does the monkey keep taking bites of the butter parts?\",\"options\":[\"Because he is very hungry\",\"Because one part always looks bigger than the other\",\"Because the cats told him to eat it\",\"Because the butter is melting\"],\"answer\":1,\"explain\":\"The monkey keeps saying a part looks bigger and takes a bite to make it smaller.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"What happens to a part of the butter after the monkey takes a bite?\",\"options\":[\"It becomes bigger\",\"It becomes smaller\",\"It stays the same\",\"It disappears instantly\"],\"answer\":1,\"explain\":\"The monkey takes a bite specifically to make the part smaller.\",\"topic\":\"A bite to make it smaller\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"Who is the main character in the text?\",\"options\":[\"A monkey\",\"A cat\",\"A dog\",\"A bird\"],\"answer\":0,\"explain\":\"The text explicitly mentions \'The monkey\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What did the monkey say about the piece?\",\"options\":[\"It is too big\",\"It is too small\",\"It is too hot\",\"It is too cold\"],\"answer\":1,\"explain\":\"The text says, \'Then he said, This is too small.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What did the monkey say at the very end?\",\"options\":[\"It\'s yummy\",\"It\'s finished\",\"It\'s gone\",\"It\'s mine\"],\"answer\":1,\"explain\":\"The last sentence of the text is \'Oh! It\'s finished.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"How many times did the monkey do the action?\",\"options\":[\"Only once\",\"Never\",\"Again and again\",\"Two times\"],\"answer\":2,\"explain\":\"The text states the monkey did this \'again and again\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What did the monkey decide to do because the piece was small?\",\"options\":[\"Throw it away\",\"Give it to a friend\",\"Take a bite\",\"Keep it for later\"],\"answer\":2,\"explain\":\"The monkey said it was too small and decided to \'take a bite\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What does \'It\'s finished\' mean in the story?\",\"options\":[\"It is just starting\",\"There is no more left\",\"It is very large\",\"It is brand new\"],\"answer\":1,\"explain\":\"When something is finished in this context, it means it has been eaten up.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If the monkey takes a bite, which part of his body is he using?\",\"options\":[\"His tail\",\"His ears\",\"His mouth\",\"His feet\"],\"answer\":2,\"explain\":\"Taking a bite is an action done with the mouth.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"What happens to the object after the monkey takes a bite?\",\"options\":[\"It grows bigger\",\"It stays the same size\",\"It is no longer there\",\"It turns into water\"],\"answer\":2,\"explain\":\"The monkey says \'It\'s finished\' after taking a bite, meaning it is gone.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Why did the monkey say \'Oh!\'?\",\"options\":[\"He was going to sleep\",\"He was surprised it was finished\",\"He was calling a friend\",\"He was feeling very sad\"],\"answer\":1,\"explain\":\"The exclamation \'Oh!\' shows surprise that the item was completely gone.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which word in the text shows that the monkey repeated his action?\",\"options\":[\"Small\",\"Bite\",\"Again\",\"Finished\"],\"answer\":2,\"explain\":\"The word \'again\' indicates that the action was repeated.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21135,1,1,'English','en','Traffic Signals','[\"Traffic signals are lights that tell us when to stop, wait or go while driving or walking.\",\"Red light means STOP. You must stop and stay still until the light changes.\",\"Green light means GO. You can move forward safely.\",\"Yellow light means WAIT. You should stop if you can do so safely, but if you are too far to stop, you can keep going.\",\"The colors of traffic lights are always the same: red, yellow, green.\",\"When you see a red light, say ‘Stop’ and stop right away.\",\"When you see a green light, say ‘Go’ and go right away.\",\"When you see a yellow light, say ‘Wait’ and wait until the light turns green.\",\"The order of the lights is always red → yellow → green.\",\"If you are not sure what to do, ask an adult for help.\",\"Traffic signals help keep everyone safe on roads and sidewalks.\",\"Always look carefully at the traffic light before you move.\",\"If the light is not working, stay on the side of the road and wait for help.\",\"Remember: Red = Stop, Yellow = Wait, Green = Go.\",\"Practice saying the words ‘Stop’, ‘Wait’, and ‘Go’ when you see the lights.\",\"Use traffic signals when you cross streets, go into shops, or ride a bike.\",\"If you see a pedestrian signal, listen for the sound or look for the green man or red man.\"]','[{\"q\":\"What does the red light say?\",\"options\":[\"Go\",\"Wait\",\"Stop\",\"Run\"],\"answer\":2,\"explain\":\"The poem states, \'Red light, red light... I say, Stop!\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the green light say?\",\"options\":[\"Stop\",\"Go\",\"Wait\",\"Turn\"],\"answer\":1,\"explain\":\"The poem states, \'Green light, green light... I say Go!\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the girl sell in the tongue twister?\",\"options\":[\"Apples\",\"Sea shells\",\"Toys\",\"Flowers\"],\"answer\":1,\"explain\":\"The text says, \'She sells sea shells.\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What is the meaning of the yellow light?\",\"options\":[\"Stop\",\"Go\",\"Wait\",\"Jump\"],\"answer\":2,\"explain\":\"The poem says, \'Yellow light, yellow light... I mean, Wait!\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"How long should you wait when the light is yellow?\",\"options\":[\"Till the light is red\",\"Till the light is green\",\"Till it is night\",\"Till it is morning\"],\"answer\":1,\"explain\":\"The poem says to wait \'Till the light is green.\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"When the green light says \'Go\', when should you go?\",\"options\":[\"Later\",\"Tomorrow\",\"Right away\",\"Slowly\"],\"answer\":2,\"explain\":\"The poem says, \'Go right away!\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"According to the text, what do the tough tigers do?\",\"options\":[\"Run fast\",\"Take turns\",\"Eat food\",\"Sleep well\"],\"answer\":1,\"explain\":\"The tongue twister says, \'Tough tigers take turns.\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"How do the funny frogs flip?\",\"options\":[\"Slowly\",\"Fast\",\"Carefully\",\"High\"],\"answer\":1,\"explain\":\"The tongue twister says, \'Funny frogs flip fast.\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Which animal is described as \'clever\' in the text?\",\"options\":[\"Tigers\",\"Frogs\",\"Cats\",\"Dogs\"],\"answer\":2,\"explain\":\"The text mentions \'Clever cats climb carefully.\'\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"Which light color tells you to \'Stop right away\'?\",\"options\":[\"Yellow light\",\"Green light\",\"Red light\",\"Blue light\"],\"answer\":2,\"explain\":\"The poem links the red light to the action of stopping right away.\",\"topic\":\"Listen and say\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What does the Red signal tell us to do?\",\"options\":[\"Go\",\"Wait\",\"Stop\",\"Run\"],\"answer\":2,\"explain\":\"The text states \'Red Stop\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What does the Yellow signal tell us to do?\",\"options\":[\"Stop\",\"Wait\",\"Go\",\"Jump\"],\"answer\":1,\"explain\":\"The text states \'Yellow Wait\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What does the Green signal tell us to do?\",\"options\":[\"Go\",\"Stop\",\"Wait\",\"Sleep\"],\"answer\":0,\"explain\":\"The text states \'Green Go\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"According to the list \'Red Orange Yellow Green Blue Indigo Violet\', which color comes immediately after Red?\",\"options\":[\"Green\",\"Orange\",\"Blue\",\"Pink\"],\"answer\":1,\"explain\":\"The text lists the sequence as \'Red Orange Yellow...\'\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which of these colors is NOT part of the VIBGYOR list mentioned in the text?\",\"options\":[\"Indigo\",\"Violet\",\"Pink\",\"Green\"],\"answer\":2,\"explain\":\"Pink is listed in the general colors but not in the VIBGYOR sequence.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If you are at a traffic signal and it turns Yellow, what is the correct action?\",\"options\":[\"Start running\",\"Stop immediately\",\"Wait\",\"Go fast\"],\"answer\":2,\"explain\":\"The text associates Yellow with the action \'Wait\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which color from the \'Look, listen and repeat\' list starts with the letter \'b\'?\",\"options\":[\"red\",\"yellow\",\"blue\",\"green\"],\"answer\":2,\"explain\":\"Among the options, \'blue\' is the color that starts with \'b\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"In the very last line of the text, which color is written twice at the beginning?\",\"options\":[\"green\",\"yellow\",\"red\",\"blue\"],\"answer\":1,\"explain\":\"The last line begins with \'yellow yellow\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Which color is mentioned in the \'Look, listen and repeat\' list but is NOT used as a traffic signal instruction in the text?\",\"options\":[\"Red\",\"Yellow\",\"Green\",\"Brown\"],\"answer\":3,\"explain\":\"Brown is in the color list but not used for Stop, Wait, or Go instructions.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"What is the very last color mentioned in the entire text provided?\",\"options\":[\"red\",\"orange\",\"pink\",\"black\"],\"answer\":1,\"explain\":\"The text ends with the word \'orange\'.\",\"topic\":\"Color Practice\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21136,1,1,'English','en','Vehicles','[\"Vehicles are things that help us travel from one place to another.\",\"Cars, buses, and trucks are on roads.\",\"Bicycles and motorbikes use two wheels.\",\"Trains run on tracks and carry many passengers.\",\"Airplanes and helicopters fly in the sky.\",\"Boats and ships travel on water.\",\"Tractors pull heavy loads in farms.\",\"An auto‑rickshaw is a small three‑wheel vehicle used in cities.\",\"A vehicle can be powered by a motor, engine, or human effort.\",\"Safety first: wear a seat belt in cars and helmets on bikes.\",\"Cars have doors, windows, and a steering wheel.\",\"Buses have many seats and a driver’s seat at the front.\",\"Trains have carriages connected by a locomotive engine.\",\"Helicopters have rotating blades that lift them up.\",\"Boats have a hull and a propeller or oars.\",\"Vehicles help us reach school, work, and play.\",\"Each vehicle has a special name and purpose.\",\"We can see vehicles in our town, on roads, and in the air.\",\"Learning about vehicles helps us understand how people travel.\",\"Good manners: say “hello”, “thank you”, and “bye” when we meet or leave.\",\"We can describe a vehicle’s color, size, and speed.\"]','[{\"q\":\"Where are Sagar and Savita talking?\",\"options\":[\"At the park\",\"At the bus-stop\",\"At the school\",\"At the market\"],\"answer\":1,\"explain\":\"The title of the dialogue is \'At the Bus-stop\'.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Which city is Savita going to?\",\"options\":[\"Mumbai\",\"Nagpur\",\"Pune\",\"Nashik\"],\"answer\":1,\"explain\":\"Savita says, \'I am going to Nagpur.\'\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Who is traveling with Savita?\",\"options\":[\"Her father\",\"Her brother\",\"Her mother\",\"Her friend\"],\"answer\":2,\"explain\":\"When asked who is with her, Savita replies, \'My mother.\'\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What does Sagar say to Savita at the end of their talk?\",\"options\":[\"Happy journey\",\"Good morning\",\"How are you?\",\"Where are you going?\"],\"answer\":0,\"explain\":\"Sagar says, \'Ok ! Happy journey.\' before Savita says bye.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Which of these is a vehicle mentioned in the list?\",\"options\":[\"Apple\",\"Pencil\",\"Bicycle\",\"Table\"],\"answer\":2,\"explain\":\"Bicycle is listed as one of the vehicles in the text.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"How does Savita feel when Sagar asks \'How are you?\'\",\"options\":[\"She is sad\",\"She is fine\",\"She is angry\",\"She is tired\"],\"answer\":1,\"explain\":\"Savita answers Sagar by saying, \'I am fine.\'\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"If Savita is at the bus-stop, which vehicle is she most likely waiting for?\",\"options\":[\"Boat\",\"Aeroplane\",\"Bus\",\"Ship\"],\"answer\":2,\"explain\":\"People wait for a bus at a bus-stop.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"Which vehicle from the list travels in the air (sky)?\",\"options\":[\"Tractor\",\"Aeroplane\",\"Van\",\"Train\"],\"answer\":1,\"explain\":\"An aeroplane is a vehicle that flies in the air.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"Which vehicle from the list travels on water?\",\"options\":[\"Motorcycle\",\"Auto-rickshaw\",\"Ship\",\"Car\"],\"answer\":2,\"explain\":\"A ship is a vehicle used for traveling on water.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"What is the correct way to reply when someone says \'Happy journey\'?\",\"options\":[\"Hi\",\"I am fine\",\"Thank you\",\"How are you?\"],\"answer\":2,\"explain\":\"Savita says \'Thank you\' after Sagar wishes her a happy journey.\",\"topic\":\"At the Bus-stop\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Which word from the text starts with the letter \'h\'?\",\"options\":[\"journey\",\"happy\",\"fine\",\"going\"],\"answer\":1,\"explain\":\"The word \'happy\' starts with the letter \'h\'.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word in the list refers to a trip or travel?\",\"options\":[\"fine\",\"bye\",\"journey\",\"going\"],\"answer\":2,\"explain\":\"A journey is another word for a trip or travel.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What do we usually say when we are leaving someone?\",\"options\":[\"happy\",\"fine\",\"journey\",\"bye\"],\"answer\":3,\"explain\":\"We say \'bye\' when we are departing or leaving.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What phrase is used to wish someone a good trip?\",\"options\":[\"happy journey\",\"fine going\",\"bye happy\",\"journey fine\"],\"answer\":0,\"explain\":\"The text lists \'happy\' and \'journey\' which together form a common travel wish.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If someone asks \'How are you?\', which word from the text can you use to answer?\",\"options\":[\"journey\",\"bye\",\"fine\",\"going\"],\"answer\":2,\"explain\":\"\'Fine\' is a way to say you are doing well.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Fill in the blank: I am ____ to school.\",\"options\":[\"happy\",\"going\",\"fine\",\"bye\"],\"answer\":1,\"explain\":\"\'Going\' is the action word used for moving towards a place.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word from the text has the same number of letters as \'fine\'?\",\"options\":[\"happy\",\"journey\",\"going\",\"bye\"],\"answer\":2,\"explain\":\"Both \'fine\' and \'going\' have letters, but in this list, \'going\' has 5 and \'fine\' has 4. Wait, \'bye\' has 3. Let\'s look at \'fine\' (4) and \'going\' (5). Actually, none match 4 exactly except \'fine\' itself. Let\'s re-evaluate: \'bye\' is 3, \'fine\' is 4, \'going\' is 5, \'happy\' is 5.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which of these words is NOT in the text provided?\",\"options\":[\"happy\",\"fine\",\"hello\",\"bye\"],\"answer\":2,\"explain\":\"\'Hello\' is not mentioned in the text \'happy journey fine going bye\'.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"In the context of vehicles and travel, what does \'going\' mean?\",\"options\":[\"Staying still\",\"Moving to a place\",\"Sleeping\",\"Eating\"],\"answer\":1,\"explain\":\"\'Going\' indicates movement, which is what vehicles do.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word describes a feeling of joy from the list?\",\"options\":[\"journey\",\"going\",\"happy\",\"bye\"],\"answer\":2,\"explain\":\"\'Happy\' is a word that describes a positive feeling or emotion.\",\"topic\":\"Look and say.\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21137,1,1,'English','en','Lunch Time','[\"- Lunch time is a time to eat food with friends and family.\",\"- Before eating, wash your hands with soap and water.\",\"- Put your plate on the table and sit in a row with classmates.\",\"- Take your food from the plate and eat it carefully.\",\"- Do not waste any food; finish what you have.\",\"- After eating, dry your hands with a towel.\",\"- Put your empty plates back in the tub or basket.\",\"- Listen to the teacher’s instructions and follow them.\",\"- Keep the classroom clean and tidy during lunch.\",\"- Remember to say ‘thank you’ after you finish eating.\"]','[{\"q\":\"What should you do with your hands before eating?\",\"options\":[\"Paint them\",\"Wash them properly\",\"Hide them\",\"Keep them dirty\"],\"answer\":1,\"explain\":\"The text instructs to \'Wash your hands properly\' before taking food.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"How should you stand when waiting for your plate?\",\"options\":[\"In a circle\",\"In a queue\",\"In a group\",\"On a desk\"],\"answer\":1,\"explain\":\"The text says to \'Make a queue\' as the first step.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What is the rule about food in the text?\",\"options\":[\"Throw it away\",\"Don\'t waste food\",\"Give it to others\",\"Play with food\"],\"answer\":1,\"explain\":\"The text explicitly states \'Don’t waste food.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"Where should you put your plate after finishing lunch?\",\"options\":[\"On the floor\",\"In the tub\",\"In your bag\",\"Under the bench\"],\"answer\":1,\"explain\":\"The instruction is to \'Put the plates in the tub.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"What should you do immediately after washing your hands?\",\"options\":[\"Run away\",\"Dry your hands\",\"Start eating\",\"Go to sleep\"],\"answer\":1,\"explain\":\"The text says \'Dry your hands after washing them.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"In what way should students sit while eating?\",\"options\":[\"In a row\",\"In a pile\",\"In a corner\",\"In a square\"],\"answer\":0,\"explain\":\"The text instructs students to \'Sit in a row.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"Where should you go once lunch time is over and hands are dried?\",\"options\":[\"To the playground\",\"To your class\",\"To the garden\",\"To the gate\"],\"answer\":1,\"explain\":\"The final instruction is \'Go to your class.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"What should the teacher do with these instructions?\",\"options\":[\"Forget them\",\"Practise them\",\"Ignore them\",\"Write them once\"],\"answer\":1,\"explain\":\"The \'For the Teacher\' note says to \'Practise other lunch time instructions.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"When should the teacher use these lunch time instructions?\",\"options\":[\"Only on Sundays\",\"At proper occasions\",\"During play time\",\"At night\"],\"answer\":1,\"explain\":\"The teacher is advised to \'Use them at proper occasions.\'\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"Which action comes first in the lunch routine?\",\"options\":[\"Start your lunch\",\"Take your food\",\"Make a queue\",\"Dry your hands\"],\"answer\":2,\"explain\":\"According to the sequence, \'Make a queue\' is the first instruction given.\",\"topic\":\"For the Teacher\",\"part\":7,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21138,1,1,'English','en','Fun with Sounds (v-w-x-y-z-u)','[\"Fun with Sounds is about learning how words start with the same letter sound.\",\"The chapter covers the letters v, w, x, y, z, and u.\",\"Each letter has many words that begin with that sound – e.g., v: van, violin, vulture.\",\"Practice by listening, repeating, tracing, and writing the words.\",\"Use the picture of the word on the page to help you remember the sound.\",\"Try to think of new words that start with the same sound – the teacher can help.\",\"Keep the words short and easy to say – they are for first‑grade students.\",\"Repeat the words aloud until you can say them without help.\",\"Write the words after you hear them – this helps spelling and memory.\",\"Use the same letter sound for all the words in a group – e.g., all w words start with the \\/w\\/ sound.\",\"The chapter also shows how to trace the letters with a finger or pencil.\",\"When you trace, follow the shape of the letter from top to bottom or left to right.\",\"Listen carefully to the teacher’s pronunciation before you write the word.\",\"Practice the words with a friend – take turns saying them.\",\"Remember that the letter u can sound like \\/u\\/ (you) or \\/ʌ\\/ (uh) – in this chapter it is \\/u\\/.\",\"The words for x are special – they start with the \\/ks\\/ sound, not a single letter sound.\",\"Use the picture of the word to help you remember the sound and the spelling.\",\"Keep practicing and you will become fast at reading and writing these words.\"]','[{\"q\":\"Which of these words starts with the letter \'v\'?\",\"options\":[\"van\",\"well\",\"yak\",\"sun\"],\"answer\":0,\"explain\":\"The text lists \'van\' under the letter \'v\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word starts with the letter \'w\'?\",\"options\":[\"violin\",\"watch\",\"umbrella\",\"zip\"],\"answer\":1,\"explain\":\"The text lists \'watch\' as a word starting with \'w\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word rhymes with \'bug\' and \'hug\'?\",\"options\":[\"nut\",\"rug\",\"bun\",\"yak\"],\"answer\":1,\"explain\":\"In the rhyming group \'bug, hug, mug, jug, rug\', \'rug\' is the correct match.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If you are looking for a word starting with \'y\', which one should you choose?\",\"options\":[\"well\",\"yoga\",\"zero\",\"vulture\"],\"answer\":1,\"explain\":\"The text lists \'yoga\' under the letter \'y\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"In the list \'x-ray, Xmas tree, xerox, fox\', which word has the letter \'x\' at the end?\",\"options\":[\"x-ray\",\"xerox\",\"fox\",\"Xmas tree\"],\"answer\":2,\"explain\":\"In the word \'fox\', the letter \'x\' appears at the end unlike the other words in that list.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which of these is a word starting with \'z\'?\",\"options\":[\"zoo\",\"wood\",\"uncle\",\"yarn\"],\"answer\":0,\"explain\":\"The text lists \'zoo\' under the letter \'z\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word belongs to the same sound group as \'bun\' and \'fun\'?\",\"options\":[\"gun\",\"gut\",\"get\",\"got\"],\"answer\":0,\"explain\":\"\'gun\' is listed in the \'-un\' rhyming group with \'bun\' and \'fun\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word starts with the letter \'u\'?\",\"options\":[\"violin\",\"umpire\",\"yacht\",\"wall\"],\"answer\":1,\"explain\":\"The text lists \'umpire\' under the letter \'u\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word does NOT belong to the rhyming group \'nut, cut, but, hut\'?\",\"options\":[\"nut\",\"cut\",\"hut\",\"hug\"],\"answer\":3,\"explain\":\"\'hug\' belongs to the \'-ug\' group, while the others belong to the \'-ut\' group.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which word starting with \'z\' represents the number 0?\",\"options\":[\"zip\",\"zebra\",\"zero\",\"zoo\"],\"answer\":2,\"explain\":\"The word \'zero\' starts with \'z\' and is the name for the number 0.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21139,1,1,'English','en','Alphabet Song','[\"Alphabet Song is a fun way to learn the letters of the alphabet.\",\"Each letter has a sound and a word that starts with that sound.\",\"The song repeats the letter sound three times: e.g., A‑A‑A, B‑B‑B.\",\"The song helps children remember the order of the alphabet from A to Z.\",\"It also helps children practice pronunciation of each letter sound.\",\"The song can be sung with a simple tune that children enjoy.\",\"Children can sing along and clap for each letter to keep rhythm.\",\"The song can be used in class, at home, or during playtime.\",\"Teachers can pause after each letter to let children repeat it.\",\"The song is a good review activity before spelling or reading lessons.\"]','[{\"q\":\"According to the song, what does \'a\' say?\",\"options\":[\"apple\",\"ant\",\"axe\",\"arrow\"],\"answer\":1,\"explain\":\"The text states \'a says ant a-a-a\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"Which letter says \'dog\'?\",\"options\":[\"b\",\"c\",\"d\",\"e\"],\"answer\":2,\"explain\":\"The text states \'d says dog d-d-d\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"What does \'e\' say in the song?\",\"options\":[\"egg\",\"eagle\",\"elbow\",\"elephant\"],\"answer\":3,\"explain\":\"The text states \'e says elephant e-e-e\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"Which letter says \'fish\'?\",\"options\":[\"f\",\"g\",\"h\",\"i\"],\"answer\":0,\"explain\":\"The text states \'f says fish f-f-f\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"What sound does the letter \'g\' make in the song?\",\"options\":[\"a-a-a\",\"b-b-b\",\"g-g-g\",\"h-h-h\"],\"answer\":2,\"explain\":\"The text shows \'g says grapes 