ions\":[\"Monday and Tuesday\",\"Wednesday and Thursday\",\"Friday and Saturday\",\"Sunday and Sunday\"],\"answer\":2,\"explain\":\"The song says, \'Friday, Saturday, We study everyday.\'\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What do we do on Wednesday and Thursday?\",\"options\":[\"We play\",\"We eat\",\"We study\",\"We bath\"],\"answer\":1,\"explain\":\"The song says, \'Wednesday, Thursday, We eat everyday.\'\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which day is mentioned as the day we play?\",\"options\":[\"Monday\",\"Friday\",\"Sunday\",\"Saturday\"],\"answer\":2,\"explain\":\"The song says, \'Sunday, Sunday, We play everyday.\'\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If today is Friday, what day was yesterday?\",\"options\":[\"Saturday\",\"Thursday\",\"Monday\",\"Sunday\"],\"answer\":1,\"explain\":\"The text states, \'Today is Friday. Yesterday was Thursday.\'\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If today is Friday, what day will it be tomorrow?\",\"options\":[\"Saturday\",\"Sunday\",\"Thursday\",\"Wednesday\"],\"answer\":0,\"explain\":\"The text states, \'Today is Friday... Tomorrow is Saturday.\'\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"If yesterday was Thursday, what day is it today?\",\"options\":[\"Friday\",\"Saturday\",\"Sunday\",\"Monday\"],\"answer\":0,\"explain\":\"Based on the text, if yesterday was Thursday, today is Friday.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which activity is done on the last day mentioned in the song?\",\"options\":[\"Studying\",\"Eating\",\"Bathing\",\"Playing\"],\"answer\":3,\"explain\":\"The last day mentioned is Sunday, and the activity is playing.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which two days are grouped together for the activity of eating?\",\"options\":[\"Monday and Tuesday\",\"Wednesday and Thursday\",\"Friday and Saturday\",\"Saturday and Sunday\"],\"answer\":1,\"explain\":\"The song groups Wednesday and Thursday for eating.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21142,1,1,'English','en','Word Family','[\"- A word family is a group of words that share the same root or base word.\",\"- The root word is the main part that gives the meaning.\",\"- Adding letters or changing the ending can make new words from the same root.\",\"- Example: the root **man** gives **man**, **mango**, **manor**.\",\"- Break down a word into its root and added part to see the family.\",\"- Practice by writing the root and the added part separately.\",\"- Circle the correct letter to form a word from the given letters.\",\"- Look at pictures and write the first letter of the word shown.\",\"- Use clues (like riddles) to guess the word.\",\"- Remember: the root stays the same, only the ending changes.\",\"- Words that differ only by a letter are part of the same family.\",\"- The word family helps you learn many words at once.\",\"- When you learn a new root, you can make many words from it.\",\"- Try to find as many words as possible from one root.\",\"- Writing the words in a notebook helps you remember them.\",\"- Practice makes the word family easier to use in sentences.\",\"- Use the word family to read and write simple sentences.\",\"- The word family is a useful tool for vocabulary building.\",\"- Keep the root word in the middle of your mind when you see new words.\",\"- The root word is the heart of the word family.\",\"- The added letters are like a small decoration on the heart.\",\"- Knowing word families helps you understand new words quickly.\",\"- Try to use word families in your daily conversations.\"]','[{\"q\":\"According to the table, how is the word \'man\' broken down?\",\"options\":[\"m and an\",\"ma and n\",\"man and o\",\"m and a\"],\"answer\":0,\"explain\":\"The table shows \'man\' broken down into \'m\' and \'an\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"What is the second part of the word \'mango\' in the example?\",\"options\":[\"man\",\"an\",\"go\",\"ngo\"],\"answer\":2,\"explain\":\"The table shows \'mango\' broken down into \'man\' and \'go\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"If \'man\' is \'m\' and \'an\', how should we break the word \'pen\'?\",\"options\":[\"pe and n\",\"p and en\",\"pen and n\",\"p and e\"],\"answer\":1,\"explain\":\"Following the pattern of \'man\', \'pen\' starts with \'p\' followed by \'en\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Following the example of \'mango\', how is \'pencil\' broken down?\",\"options\":[\"p and encil\",\"pen and cil\",\"penc and il\",\"pe and ncil\"],\"answer\":1,\"explain\":\"Following the \'mango\' pattern, \'pencil\' is split into \'pen\' and \'cil\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What is the first part of the word \'win\' when it is broken down?\",\"options\":[\"w\",\"wi\",\"in\",\"n\"],\"answer\":0,\"explain\":\"Based on the \'man\' example, the first letter \'w\' is separated from \'in\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"How is the word \'window\' broken down based on the pattern of \'mango\'?\",\"options\":[\"win and dow\",\"wind and ow\",\"w and indow\",\"wi and ndow\"],\"answer\":0,\"explain\":\"Following the \'mango\' pattern, \'window\' is split into \'win\' and \'dow\'.\",\"topic\":\"Break down the following words\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"In the word \'popcorn\', what is the second part?\",\"options\":[\"pop\",\"corn\",\"orn\",\"p\"],\"answer\":1,\"explain\":\"Based on the table\'s logic for longer words, \'popcorn\' is split into \'pop\' and \'corn\'.\",\"topic\":\"Break down the following words\