ांना मदत करतात आणि एकमेकांना आधार देतात.\",\"कुटुंबातील सर्वजण एकमेकांना प्रेम आणि आदर दाखवतात.\",\"कुटुंबात सर्वजण एकमेकांना आनंदी ठेवण्यासाठी प्रयत्न करतात.\",\"कुटुंबातील सर्वजण एकमेकांना सुरक्षित ठेवण्यासाठी प्रयत्न करतात.\",\"कुटुंबात सर्वजण एकमेकांना मदत करण्यास तयार असतात.\",\"कुटुंबातील सर्वजण एकमेकांना प्रोत्साहित करतात आणि एकमेकांना प्रेरणा देतात.\",\"कुटुंबात सर्वजण एकमेकांना समजून घेऊन एकत्र राहतात.\",\"कुटुंबातील सर्वजण एकमेकांना मदत करण्यास तयार असतात.\",\"कुटुंबात सर्वजण एकमेकांना प्रेम आणि आदर दाखवतात.\"]','[{\"q\":\"रिकाम्या चौकटीत काय चिकटवायला सांगितले आहे?\",\"options\":[\"फुलांचे फोटो\",\"कुटुंबातील व्यक्तींचे फोटो\",\"प्राण्यांचे फोटो\",\"खेळण्यांचे फोटो\"],\"answer\":1,\"explain\":\"पाठात कुटुंबातील व्यक्तींचे फोटो चिकटवण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जर फोटो उपलब्ध नसेल, तर काय करायचे आहे?\",\"options\":[\"काहीही करू नये\",\"चौकट रिकामी सोडावी\",\"चित्रे काढावीत\",\"दुसरे पुस्तक घ्यावे\"],\"answer\":2,\"explain\":\"फोटो उपलब्ध नसल्यास कुटुंबातील व्यक्तींची चित्रे काढण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"चित्राजवळ काय लिहिण्यास मदत करावी?\",\"options\":[\"व्यक्तींची नावे\",\"गावाचे नाव\",\"शाळेचे नाव\",\"फळांचे नाव\"],\"answer\":0,\"explain\":\"चित्राजवळ कुटुंबातील व्यक्तींची नावे लिहिण्यास मदत करावी असे म्हटले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"मुलांनी नाव लिहिताना कोणत्या लिपीचा स्वीकार करावा?\",\"options\":[\"केवळ इंग्रजी लिपी\",\"केवळ मराठी लिपी\",\"स्वलिपी\",\"मोडी लिपी\"],\"answer\":2,\"explain\":\"विद्यार्थ्यांच्या स्वलिपीचा स्वीकार करण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"हा स्वाध्याय कोणत्या विषयावर आधारित आहे?\",\"options\":[\"माझी शाळा\",\"माझे कुटुंब\",\"माझे मित्र\",\"माझे गाव\"],\"answer\":1,\"explain\":\"हा स्वाध्याय \'मी आणि माझे कुटुंब\' या विषयावर आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"चित्रात दिलेल्या रिकाम्या चौकटी कशासाठी आहेत?\",\"options\":[\"रंग भरण्यासाठी\",\"फोटो चिकटवण्यासाठी\",\"कागद कापण्यासाठी\",\"गणित सोडवण्यासाठी\"],\"answer\":1,\"explain\":\"रिकाम्या चौकटी फोटो चिकटवण्यासाठी किंवा चित्र काढण्यासाठी दिल्या आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"कुटुंबातील व्यक्तीचे चित्र काढल्यावर तुम्ही तिथे कोणाचे नाव लिहाल?\",\"options\":[\"त्या व्यक्तीचे\",\"मित्राचे\",\"शिक्षकांचे\",\"दुकानाचे\"],\"answer\":0,\"explain\":\"ज्याचे चित्र काढले आहे, त्या कुटुंबातील व्यक्तीचे नाव तिथे लिहावे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"नावे लिहिण्यासाठी कोणाची मदत घेण्यास सांगितले आहे?\",\"options\":[\"कोणाचीही नाही\",\"शिक्षकांची किंवा मोठ्यांची\",\"अनोळखी व्यक्तीची\",\"दुसऱ्या वर्गातील मुलांची\"],\"answer\":1,\"explain\":\"विद्यार्थ्यांना नावे लिहिण्यास मदत करावी, असे शिक्षकांसाठी सूचित केले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"या कृतीचा मुख्य उद्देश काय आहे?\",\"options\":[\"गाणी गाणे\",\"कुटुंबाची ओळख करून देणे\",\"बाहेर फिरायला जाणे\",\"जेवण करणे\"],\"answer\":1,\"explain\":\"स्वतःच्या कुटुंबातील व्यक्तींची ओळख होणे हा या कृतीचा उद्देश आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"फोटो चिकटवण्याच्या जागेला काय म्हटले आहे?\",\"options\":[\"वर्तुळ\",\"त्रिकोण\",\"चौकट\",\"रेघ\"],\"answer\":2,\"explain\":\"मजकुरात \'रिकाम्या चौकटींमध्ये\' असा शब्द वापरला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21157,2,1,'Marathi','mr','माझी जोडी','[\"- जोडी म्हणजे एकाच प्रकारचे दोन वस्तू एकत्र लावणे.\",\"- चित्रात दाखवलेल्या वस्तूंची नावे ओळखून त्यांची जोडी लावायची असते.\",\"- उदाहरणार्थ माठ आणि ससा, कावळा आणि भेडी यांची जोडी लावायची.\",\"- जोडी लावण्यासाठी समान आकार, रंग किंवा आकार असलेल्या वस्तू शोधाव्यात.\",\"- जोडी लावणे हे लक्ष आणि स्मरणशक्ती वाढवण्यासाठी उपयुक्त आहे.\",\"- लहान शब्द आणि चित्रे वापरून विद्यार्थ्यांना सराव करायला सांगावे.\",\"- जोडी लावताना चित्राचे नाव आणि वस्तूचे नाव दोन्ही सांगणे आवश्यक आहे.\",\"- जोडी लावल्यावर त्या जोडीचे नाव मोठ्याने वाचावे.\",\"- जोडी लावणे हे वर्गात खेळासारखे करता येते.\",\"- जोडी लावल्याने शब्दसंग्रह वाढतो.\",\"- जोडी लावण्यासाठी कार्ड किंवा चित्रांचा वापर करता येतो.\",\"- जोडी लावणे हे दृश्य आणि श्राव्य शिक्षणासाठी चांगले आहे.\",\"- जोडी लावताना विद्यार्थ्यांना एकमेकांना मदत करण्यास प्रोत्साहित करावे.\",\"- जोडी लावणे हे गणितातील समानता आणि जोडणी शिकवण्यासाठी आधारभूत आहे.\"]','[{\"q\":\"पाठात दिलेल्या चित्रांपैकी खालीलपैकी कोणते नाव आले आहे?\",\"options\":[\"चिंच\",\"ससा\",\"आंबा\",\"पेरू\"],\"answer\":1,\"explain\":\"पाठात ससा हे नाव आणि चित्र दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता पक्षी पाठात दाखवला आहे?\",\"options\":[\"पोपट\",\"चिमणी\",\"कावळा\",\"मोर\"],\"answer\":2,\"explain\":\"पाठात कावळा या पक्षाचे नाव आणि चित्र आले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पाठात कोणत्या भाजीचे नाव आले आहे?\",\"options\":[\"बटाटा\",\"भेंडी\",\"वांगी\",\"कोबी\"],\"answer\":1,\"explain\":\"पाठात भेंडी या भाजीचे नाव आणि चित्र दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'माठ\' या शब्दाची जोडी लावताना तुम्ही काय शोधाल?\",\"options\":[\"माठ हे सारखे नाव\",\"ससा हे नाव\",\"कावळा हे नाव\",\"भेंडी हे नाव\"],\"answer\":0,\"explain\":\"सारखी नावे ओळखून त्यांची जोडी लावायची आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'माझी जोडी\' या पाठात मुख्यत्वे काय करायला सांगितले आहे?\",\"options\":[\"गाणी म्हणणे\",\"चित्रे रंगवणे\",\"चित्रे व नावे यांच्या जोड्या लावणे\",\"गोष्ट लिहिणे\"],\"answer\":2,\"explain\":\"हा पाठ चित्र ओळखणे आणि त्यांच्या नावांच्या जोड्या लावण्यावर आधारित आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'ससा\' या शब्दाची सारखी जोडी ओळखा.\",\"options\":[\"माठ\",\"कावळा\",\"भेंडी\",\"ससा\"],\"answer\":3,\"explain\":\"ससा या शब्दाची जोडी ससा या सारख्याच शब्दाशी लागेल.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'भेंडी\' या शब्दाची जोडी खालीलपैकी कोणाशी लावाल?\",\"options\":[\"भेंडी\",\"माठ\",\"ससा\",\"कावळा\"],\"answer\":0,\"explain\":\"दिलेल्या सूचनेनुसार सारख्या नावांची जोडी लावायची आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"पाठात एकूण किती वेगवेगळ्या वस्तू\\/प्राण्यांची नावे दिली आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"कावळा, ससा, माठ आणि भेंडी अशी एकूण चार नावे दिली आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर \'कावळा\' हा पक्षी असेल, तर \'माठ\' काय आहे?\",\"options\":[\"प्राणी\",\"भाजी\",\"वस्तू\",\"फळ\"],\"answer\":2,\"explain\":\"माठ ही पाणी भरण्यासाठी वापरली जाणारी एक वस्तू आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"\'कावळा\' या शब्दाची जोडी लावण्यासाठी खालीलपैकी कोणता शब्द योग्य ठरेल?\",\"options\":[\"कावळा\",\"ससा\",\"माठ\",\"भेंडी\"],\"answer\":0,\"explain\":\"सारखी नावे ओळखून त्यांची जोडी लावणे ही पाठातील कृती आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21158,2,1,'Marathi','mr','मला घरापर्यंत पोहोचव','[\"मला घरापर्यंत पोहोचव हे एक कथा आहे ज्यात मुख्य पात्राला घरापर्यंत पोहोचायचे आहे.\",\"कथेतील मुख्य पात्राला विविध अडथळे पार करावे लागतात.\",\"कथा साध्या मराठी शब्दांत लिहिलेली आहे, ज्यामुळे लहान मुलांना समजायला सोपे जाते.\",\"कथेतील पात्रे आणि घटना दैनंदिन जीवनाशी संबंधित आहेत.\",\"कथेचा मुख्य संदेश आहे: धैर्य आणि चिकाटीने सर्व अडचणींवर मात करता येते.\",\"कथेतील संवाद साधे आणि स्पष्ट आहेत, ज्यामुळे मुलांना वाचनाची सवय लागते.\",\"कथेतील चित्रे मुलांना दृश्यात्मक समज देतात.\",\"कथेतील वाक्यरचना लहान आणि सोपी आहे, ज्यामुळे वाचन सोपे होते.\",\"कथेतील शब्दसंग्रह प्राथमिक शाळेतील विद्यार्थ्यांसाठी योग्य आहे.\",\"कथेतील कथानकाची रचना स्पष्ट आहे: सुरुवात, मध्य आणि शेवट.\",\"कथेतील पात्रांची वागणूक आणि भावना स्पष्टपणे दाखवली आहेत.\",\"कथेतील घटना क्रमाने मांडलेल्या आहेत, ज्यामुळे समजायला सोपे होते.\",\"कथेतील मुख्य पात्राला मदत करणारे मित्र आणि कुटुंबीय आहेत.\",\"कथेतील अडथळे वास्तववादी आहेत, जसे की रस्ता, पाऊस, इत्यादी.\",\"कथेतील शेवटी मुख्य पात्राला घर पोहोचते, ज्यामुळे आनंद वाटतो.\",\"कथेतील संदेश मुलांना प्रोत्साहित करतो की त्यांनी आपले ध्येय साध्य करावे.\",\"कथेतील शब्दसंग्रहात नवीन शब्द शिकायला मिळतात.\",\"कथेतील वाचनानंतर चर्चा करून मुलांना विचार करण्यास प्रोत्साहन दिले जाते.\",\"कथेतील कथानकातून मुलांना धैर्य आणि सहकार्याचे महत्त्व समजते.\",\"कथेतील पात्रांच्या संवादातून मुलांना संवाद कौशल्य शिकायला मिळते.\",\"कथेतील कथानकात नैतिक मूल्ये स्पष्टपणे दाखवली आहेत.\",\"कथेतील घटनांमध्ये मुलांना आपले अनुभव जोडता येतात.\",\"कथेतील कथानकात मुलांना समस्या सोडवण्याची पद्धत शिकवली जाते.\",\"कथेतील शेवटच्या भागात मुलांना समाधान आणि आनंदाची भावना येते.\"]','[{\"q\":\"\'मला घरापर्यंत पोहोचव\' या पाठात मुख्यत्वे कोणती कृती करायला सांगितली आहे?\",\"options\":[\"गाणे म्हणणे\",\"मार्गावरून बोट फिरवणे व गिरवणे\",\"चित्र रंगवणे\",\"गोष्ट सांगणे\"],\"answer\":1,\"explain\":\"पाठात मार्गावरून बोट फिरवण्यास आणि आकार गिरवण्यास सांगितले आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"मार्गावरून काय फिरवण्यास सांगितले आहे?\",\"options\":[\"पेन्सिल\",\"बोट\",\"खडू\",\"पेन\"],\"answer\":1,\"explain\":\"सूचनांनुसार विद्यार्थ्यांना दिलेल्या आकारातून बोट फिरवण्यास सांगावे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"आकार गिरवल्यामुळे कशाची तयारी होते?\",\"options\":[\"धावण्याची व खेळण्याची\",\"जेवणाची व झोपण्याची\",\"वाचनपूर्व व लेखनपूर्व\",\"गाण्याची व नाचण्याची\"],\"answer\":2,\"explain\":\"विविध आकार गिरवल्यामुळे विद्यार्थ्यांची वाचनपूर्व व लेखनपूर्व तयारी होते.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'गिरवणे\' या शब्दाचा अर्थ पाठाच्या संदर्भात काय आहे?\",\"options\":[\"दिलेल्या आकारावरून पुन्हा पुन्हा रेघ ओढणे\",\"कागद फाडणे\",\"चित्र पुसून टाकणे\",\"रंग बाहेर काढणे\"],\"answer\":0,\"explain\":\"दिलेल्या मार्गावरून किंवा आकारावरून बोट किंवा पेन्सिल फिरवणे म्हणजे गिरवणे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"विद्यार्थ्यांचा अधिकाधिक सराव होण्यासाठी शिक्षकांनी काय करावे?\",\"options\":[\"फक्त एकच आकार द्यावा\",\"विविध प्रकारचे आकार तयार करून घ्यावेत\",\"मुलांना खेळायला पाठवावे\",\"काहीही करू नये\"],\"answer\":1,\"explain\":\"पाठात विविध आकार तयार करून विद्यार्थ्यांचा अधिकाधिक सराव करून घेण्यास सांगितले आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"लेखनपूर्व तयारीसाठी खालीलपैकी कोणती कृती सर्वात महत्त्वाची आहे?\",\"options\":[\"मोठ्याने ओरडणे\",\"दिलेले आकार गिरवणे\",\"गप्प बसणे\",\"डोळे मिटणे\"],\"answer\":1,\"explain\":\"आकार गिरवणे ही लेखनपूर्व तयारीसाठी आवश्यक कृती आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पाठाचे नाव काय आहे?\",\"options\":[\"माझे घर\",\"मला शाळेत ने\",\"मला घरापर्यंत पोहोचव\",\"रस्ता दाखव\"],\"answer\":2,\"explain\":\"पाठाचे शीर्षक \'मला घरापर्यंत पोहोचव\' असे आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या सूचनांनुसार, बोट फिरवल्यानंतर दुसरी कोणती कृती करायची आहे?\",\"options\":[\"आकार गिरवणे\",\"कागद मोडणे\",\"चित्र काढणे\",\"गाणे गाणे\"],\"answer\":0,\"explain\":\"सूचनेनुसार बोट फिरवल्यानंतर आकार गिरवण्यास सांगितले आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"वाचनपूर्व तयारीसाठी खालीलपैकी कशाचा सराव करणे उपयुक्त ठरेल?\",\"options\":[\"केवळ बसून राहणे\",\"विविध आकारांवरून बोट फिरवणे\",\"जेवण करणे\",\"बाहेर फिरणे\"],\"answer\":1,\"explain\":\"आकारांवरून बोट फिरवणे ही वाचनपूर्व तयारीची एक कृती आहे.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"या पाठातील कृती कोणासाठी आहेत?\",\"options\":[\"केवळ शिक्षकांसाठी\",\"केवळ पालकांसाठी\",\"विद्यार्थ्यांसाठी\",\"प्राण्यांसाठी\"],\"answer\":2,\"explain\":\"या कृती विद्यार्थ्यांची वाचनपूर्व व लेखनपूर्व तयारी करून घेण्यासाठी आहेत.\",\"topic\":\"वाचनपूर्व व लेखनपूर्व तयारी\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21159,2,1,'Marathi','mr','ठिपके जोड व गिरव','[\"• ठिपके म्हणजे लहान गोल बिंदू.\",\"• ठिपके जोडून आकृती तयार करतात.\",\"• आकृती पूर्ण करण्यासाठी ठिपके एकमेकांना रेषांनी जोडावेत.\",\"• ठिपके जोडताना रेषा सरळ आणि स्वच्छ असाव्यात.\",\"• ठिपके जोडताना डोळ्यांना सोपे वाटेल अशा क्रमाने जोडावेत.\",\"• आकृती काढताना ठिपक्यांच्या जागी योग्य आकार भरणे आवश्यक.\",\"• ठिपके जोडताना हाताची स्थिरता राखावी.\",\"• ठिपके जोडताना डावीकडून उजवीकडे, वरून खाली अशी पद्धत वापरावी.\",\"• आकृती काढताना रंग भरताना समान रंग वापरावा.\",\"• ठिपके जोडून आकृती ओळखण्यासाठी पॅटर्न पाहावा.\",\"• आकृती काढताना रेषा ओलांडू नयेत.\",\"• आकृती काढताना रेषा एकमेकांना स्पर्श करू नयेत.\",\"• ठिपके जोडताना आकृतीची सममिती लक्षात घ्यावी.\",\"• ठिपके जोडताना आकृतीचे प्रमाण योग्य ठेवावे.\",\"• ठिपके जोडताना आकृतीचे कोन योग्य ठेवावेत.\",\"• ठिपके जोडताना आकृतीचे आकार स्पष्ट दिसावेत.\",\"• ठिपके जोडताना आकृतीचे भाग स्पष्ट ओळखता यावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व भाग पूर्ण करावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व रेषा एकसमान जाडीच्या असाव्यात.\",\"• ठिपके जोडताना आकृतीचे सर्व कोन तीक्ष्ण असावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व भाग एकमेकांशी जोडलेले असावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व भाग स्पष्ट दिसावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व भाग एकसमान रंगाचे असावेत.\",\"• ठिपके जोडताना आकृतीचे सर्व भाग एकसमान जाडीचे असावेत.\"]','[{\"q\":\"ठिपक्यांचे काय करायचे आहे?\",\"options\":[\"ते पुसून टाकायचे\",\"ते एकमेकांना जोडायचे\",\"त्यांच्यावर रेघा ओढायच्या\",\"त्यांच्याकडे दुर्लक्ष करायचे\"],\"answer\":1,\"explain\":\"पाठाच्या शीर्षकानुसार ठिपके जोडण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी सूचना\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"उरलेल्या जागी काय करायचे आहे?\",\"options\":[\"काहीही करू नये\",\"चित्रे चिकटवावीत\",\"दिलेले आकार काढण्याचा सराव करावा\",\"गाणी लिहावीत\"],\"answer\":2,\"explain\":\"सूचनांनुसार उरलेल्या जागी दिलेले आकार काढण्याचा सराव करण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी सूचना\",\"part\":4,\"bloom\":