\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'म + ा\' चा उच्चार खालीलपैकी कोणता आहे?\",\"options\":[\"म\",\"मा\",\"मी\",\"मो\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील सूचनेनुसार म + ा = मा असा उच्चार होतो.\",\"topic\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'लाला\' या शब्दात \'ा\' हे चिन्ह किती वेळा आले आहे?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":1,\"explain\":\"\'लाला\' या शब्दात \'ल\' ला दोन वेळा \'ा\' जोडले आहे.\",\"topic\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"\'काम\' हा शब्द तयार करण्यासाठी \'क\' ला कोणते चिन्ह जोडावे लागेल?\",\"options\":[\"अ\",\"ा\",\"ल\",\"म\"],\"answer\":1,\"explain\":\"\'काम\' शब्दातील पहिल्या अक्षराचा उच्चार \'का\' असल्यामुळे त्याला \'ा\' जोडावे लागेल.\",\"topic\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या शब्दात \'ा\' हे चिन्ह वापरलेले नाही?\",\"options\":[\"मामा\",\"अजगर\",\"कला\",\"आला\"],\"answer\":1,\"explain\":\"\'अजगर\' या शब्दात \'ा\' हे स्वराचिन्ह वापरलेले नाही.\",\"topic\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"\'मका\' या शब्दात \'ा\' हे चिन्ह कोणत्या अक्षराला जोडले आहे?\",\"options\":[\"म\",\"क\",\"अ\",\"ल\"],\"answer\":1,\"explain\":\"\'मका\' या शब्दात \'क\' या अक्षराला \'ा\' जोडल्यामुळे त्याचा उच्चार \'का\' होतो.\",\"topic\":\"\'आ\' स्वराची ओळख\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"\'काका आला\' या वाक्यात कोण आले आहे?\",\"options\":[\"मामा\",\"काका\",\"लाला\",\"आलम\"],\"answer\":1,\"explain\":\"पाठातील पहिल्या वाक्यात \'काका आला\' असे दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"आलम कधी आला?\",\"options\":[\"आज\",\"उद्या\",\"काल\",\"परवा\"],\"answer\":2,\"explain\":\"पाठात \'काल आलम आला\' असे स्पष्ट लिहिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'मामा\' या शब्दात कोणते अक्षर दोन वेळा आले आहे?\",\"options\":[\"का\",\"ला\",\"मा\",\"आ\"],\"answer\":2,\"explain\":\"\'मामा\' या शब्दात \'मा\' हे अ