,(21229,4,1,'Maths','mr','जवळ-दूर','[\"जवळ आणि दूर हे दोन शब्द एकमेकांशी तुलना करण्यासाठी वापरतो.\",\"जवळ म्हणजे एखाद्या गोष्टीच्या खूप जवळ असणे.\",\"दूर म्हणजे एखाद्या गोष्टीच्या खूप दूर असणे.\",\"उदाहरण: शाळा जवळ आहे, घर दूर आहे.\",\"जवळ आणि दूर याची तुलना करण्यासाठी आपण \'जवळ\' आणि \'दूर\' हे शब्द वापरतो.\",\"जवळ असलेल्या गोष्टीला आपण \'जवळची\' म्हणतो.\",\"दूर असलेल्या गोष्टीला आपण \'दूरची\' म्हणतो.\",\"जवळ आणि दूर हे शब्द तुलना करण्यास मदत करतात.\",\"जवळ आणि दूर यांची तुलना करताना आपण दोन्ही गोष्टींची स्थिती पाहतो.\",\"जवळ असलेल्या गोष्टीची लांबी कमी असते.\",\"दूर असलेल्या गोष्टीची लांबी जास्त असते.\",\"जवळ आणि दूर यांची तुलना करताना आपण अंतर मोजतो.\",\"जवळ आणि दूर हे शब्द आपल्याला वस्तूंची स्थिती समजायला मदत करतात.\",\"जवळ आणि दूर यांची तुलना करताना आपण दृश्यातून पाहतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण आवाजातूनही समजू शकतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण स्पर्शातूनही जाणू शकतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण अनुभवून पाहतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण विचार करून पाहतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण तुलना करून पाहतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण निर्णय घेतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण योग्य निर्णय घेतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण शिकतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण ज्ञान वाढवतो.\",\"जवळ आणि दूर यांची तुलना करताना आपण जीवन समजतो.\"]','[{\"q\":\"या पाठाचे नाव काय आहे?\",\"options\":[\"वर-खाली\",\"जवळ-दूर\",\"आत-बाहेर\",\"मागे-पुढे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील या प्रकरणाचे शीर्षक \'जवळ-दूर\' असे आहे.\",\"topic\":\"शिक्षकांसाठी सूचना\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शाळेच्या जवळ कोण आहे हे शोधण्यासाठी काय करायला सांगितले आहे?\",\"options\":[\"गाणे गा\",\"चित्र बघ\",\"गोष्ट सांग\",\"उड्या मार\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात \'चित्र बघ\' अशी सूचना दिली आहे.\",\"topic\":\"शिक्षकांसाठी सूचना\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"पाण्याच्या भांड्यापासून दूर असणाऱ्या कोणत्या पक्षाचे चित्र दिले आहे?\",\"options\":[\"पोपट\",\"चिमणी\",\"कावळा