"ताटात १ मोदक आहे\",\"ताटात ० मोदक आहेत\",\"ताटात खूप मोदक आहेत\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की मोदक उरले नाहीत म्हणजेच \'०\' मोदक आहेत.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"प्रत्येक वेळी ताटातील किती मोदक कमी झाले?\",\"options\":[\"दोन\",\"एक\",\"तीन\",\"पाच\"],\"answer\":1,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेत \'प्रत्येक वेळी ताटातील एक मोदक कमी झाला\' असे म्हटले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्याकडे एकही पेन्सिल नसेल, तर तुमच्याकडे किती पेन्सिली आहेत?\",\"options\":[\"०\",\"१\",\"२\",\"५\"],\"answer\":0,\"explain\":\"काहीही उरले नाही किंवा नसणे म्हणजे शून्य (०) ही संकल्पना येथे लागू होते.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"५, ४, ३, २, १ या क्रमाने मोदक कमी झाल्यावर शेवटी किती उरतात?\",\"options\":[\"५\",\"२\",\"०\",\"४\"],\"answer\":2,\"explain\":\"दिलेल्या क्रमानुसार १ नंतर शेवटी ताटात काहीही उरत नाही, म्हणजेच ० उरतात.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"शून्याची संकल्पना अधिक स्पष्ट करण्यासाठी शिक्षकांनी कशाचा आधार घ्यावा?\",\"options\":[\"केवळ फळ्याचा\",\"परिसरातील विविध वस्तूंचा\",\"मोठ्या संख्यांचा\",\"केवळ गोष्टींचा\"],\"answer\":1,\"explain\":\"मजकुरात परिसरातील विविध वस्तूंच्या आधारे शून्याची संकल्पना स्पष्ट करण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'०\' या संख्येचे नाव काय आहे?\",\"options\":[\"एक\",\"दोन\",\"शून्य\",\"पाच\"],\"answer\":2,\"explain\":\"मजकुरात \'०\' या चिन्हाला शून्य असे म्हटले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"एका डब्यात १ लाडू होता, तो खाऊन संपला. आता डब्यात किती लाडू उरले?\",\"options\":[\"०\",\"१\",\"२\",\"५\"],\"answer\":0,\"explain\":\"१ मोदक उरला होता तो कमी झाल्यावर ० उरले, याच उदाहरणावरून हे उत्तर येते.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"ताटात ५ मोदक होते आणि शेवटी ० उरले, यावरून काय समजते?\",\"options\":[\"मोदक वाढत गेले\",\"मोदक कमी होत गेले\",\"मोदक तेवढेच राहिले\",\"मोदक बदलले नाहीत\"],\"answer\":1,\"explain\":\"५, ४, ३, २, १, ० हा क्रम संख्या कमी होत असल्याचे दर्शवतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28');
INSERT INTO `ep_topic_packs` VALUES (21234,4,1,'Maths','mr','१०ची ओळख','[\"१० म्हणजे एक दशक\",\"१० एकक ठोकळे म्हणजे १ दशक\",\"१० एकक मणी म्हणजे १ दशक\",\"१० एकक खडू म्हणजे १ दशक\",\"१० एकक पेन्सिली म्हणजे १ दशक\",\"१० एकक लाडू म्हणजे १ दशक\",\"१० एकक म्हणजे १ गट\",\"१० एककांची संख्या १० आहे\",\"१० वाचायला, लिहायला व गिरवायला शिकतो\",\"१० च्या बोटांनी दाखवून समजावतो\",\"१० च्या आकड्याने ९ नंतर १० कसे बनते ते दाखवतो\",\"१० च्या आकड्याने १० च्या गटाची ओळख करतो\",\"१० च्या आकड्याने १० च्या गटाची बेरीज करतो\",\"१० च्या आकड्याने १० च्या गटाची मोजणी करतो\",\"१० च्या आकड्याने १० च्या गटाची तुलना करतो\",\"१० च्या आकड्याने १० च्या गटाची गणना करतो\",\"१० च्या आकड्याने १० च्या गटाची बेरीज व वजाबाकी करतो\",\"१० च्या आकड्याने १० च्या गटाची बेरीज व वजाबाकी समजतो\",\"१० च्या आकड्याने १० च्या गटाची बेरीज व वजाबाकी करतो\",\"१० च्या आकड्याने १० च्या गटाची बेरीज व वजाबाकी समजतो\"]','[{\"q\":\"९ नंतर कोणती संख्या येते?\",\"options\":[\"दहा (१०)\",\"आठ (८)\",\"सात (७)\",\"सहा (६)\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार ९ नंतर १० ही संख्या येते.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"१० एकक म्हणजे किती?\",\"options\":[\"नऊ\",\"दहा\",\"आठ\",\"सात\"],\"answer\":1,\"explain\":\"१० एकक म्हणजेच \'दहा\' ही संख्या होय.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"९ ठोकळ्यांमध्ये १ ठोकळा मिळवल्यास किती ठोकळे होतात?\",\"options\":[\"८ ठोकळे\",\"९ ठोकळे\",\"१० ठोकळे\",\"७ ठोकळे\"],\"answer\":2,\"explain\":\"९ एकक ठोकळे आणि अजून एक मिळून १० होतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"पाठ्यपुस्तकात १० ही संख्या दाखवण्यासाठी खालीलपैकी कशाचा वापर केला आहे?\",\"options\":[\"पेन्सिल\",\"सफरचंद\",\"चेंडू\",\"बॅट\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकात १० एकक पेन्सिलींचे उदाहरण दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"हातांच्या बोटांच्या साहाय्याने ९ नंतर कोणती संख्या तयार होते?\",\"options\":[\"७\",\"८\",\"९\",\"१०\"],\"answer\":3,\"explain\":\"बोटांच्या साहाय्याने ९ नंतर १० ही संख्या तयार होते हे दाखवता येते.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"१० एकक खडू म्हणजे किती खडू?\",\"options\":[\"९ खडू\",\"१० खडू\",\"८ खडू\",\"७ खडू\"],\"answer\":1,\"explain\":\"१० एकक खडू म्हणजे १० ही संख्या होय.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"नऊ एकक ठोकळे आणि एक एकक ठोकळा मिळून काय तयार होते?\",\"options\":[\"दहा\",\"आठ\",\"सात\",\"सहा\"],\"answer\":0,\"explain\":\"९ एकक आणि १ एकक मिळून १० तयार होतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी \'दहा\' ही संख्या अंकात कशी लिहितात?\",\"options\":[\"९\",\"७\",\"१०\",\"८\"],\"answer\":2,\"explain\":\"दहा ही संख्या \'१०\' अशी लिहिली जाते.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"१० मणी होण्यासाठी ९ मण्यांमध्ये अजून किती मणी मिळवावे लागतील?\",\"options\":[\"२ मणी\",\"१ मणी\",\"३ मणी\",\"० मणी\"],\"answer\":1,\"explain\":\"९ मण्यांमध्ये १ मणी मिळवला की १० मणी होतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"\'१०\' या संख्येचे वाचन कसे कराल?\",\"options\":[\"आठ\",\"नऊ\",\"दहा\",\"सात\"],\"answer\":2,\"explain\":\"१० या संख्येला \'दहा\' असे वाचतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21235,4,1,'Maths','mr','बेरीज (उत्तर ९पर्यंत)','[\"बेरीज म्हणजे दोन किंवा अधिक संख्यांची एकत्रित बेरीज करणे.\",\"आडवी मांडणी म्हणजे सर्व संख्या एकाच ओळीत लिहून बेरीज करणे.\",\"उभी मांडणी म्हणजे संख्या एकमेकांच्या वर लिहून बेरीज करणे, जसे ३ + २ = ५.\",\"बेरीज करताना एकक, दहाचे, शंभराचे स्थान वेगळे ठेवून लिहावे.\",\"जर एकक स्थानावर बेरीज १० किंवा अधिक झाली तर १ पुढच्या स्थानावर नेऊन १० वजा करावे.\",\"बेरीज करताना सर्व संख्यांचे स्थान एकसारखे ठेवणे महत्त्वाचे आहे.\",\"उदाहरण: ४ + ३ = ७, ६ + २ = ८, ९ + १ = १० (१ पुढे नेऊन ० लिहा).\",\"बेरीजचे नियम: ० जोडल्यास संख्या बदलत नाही.\",\"बेरीज करताना ‘कमी’ किंवा ‘जास्त’ हे शब्द वापरू नये, फक्त ‘बेरीज’ म्हणावे.\",\"बेरीजची सराव करताना लहान लहान संख्या वापरून सुरुवात करावी.\",\"बेरीज करताना ‘कमी’ किंवा ‘जास्त’ यांचा वापर वजाबाकीच्या वेळी करावा.\",\"बेरीजचे उत्तर ९ पेक्षा कमी असणे अपेक्षित आहे, कारण या अध्यायात ९ पर्यंतची बेरीज शिकवली जाते.\",\"बेरीज करताना ‘समान’ किंवा ‘बराबर’ हे शब्द वापरून उत्तर दाखवावे.\",\"बेरीजचे उदाहरण: २ + ३ = ५, ४ + ४ = ८, १ + १ = २.\",\"बेरीज करताना ‘आडवी’ आणि ‘उभी’ या दोन्ही पद्धतींचा सराव करावा.\",\"बेरीजची गणना करताना ‘कमी’ किंवा ‘जास्त’ हे शब्द वजाबाकीच्या वेळी वापरावेत.\",\"बेरीजच्या सरावात ‘फुले’, ‘धावा’, ‘बादल्या’ इत्यादी गोष्टींचा वापर करून मजा वाढवा.\",\"बेरीजची गणना करताना ‘मिळून’ हे शब्द वापरून एकूण संख्या दाखवावी.\",\"बेरीज करताना ‘एकूण’ हे शब्द वापरून उत्तर स्पष्ट करावे.\",\"बेरीजच्या सरावात ‘सुरेश’, ‘समीर’, ‘सुलभा’ इत्यादी नावे वापरून प्रश्न तयार करावेत.\",\"बेरीजच्या सरावात ‘वर्ग’ किंवा ‘शाळा’ यांसारख्या ठिकाणांचा वापर करून प्रश्न तयार करावेत.\",\"बेरीजच्या सरावात ‘कमी’ किंवा ‘जास्त’ या शब्दांचा वापर वजाबाकीच्या वेळी करावा.\",\"बेरीजच्या सरावात ‘कमी’ किंवा ‘जास्त’ हे शब्द वजाबाकीच्या वेळी वापरावेत.\",\"बेरीजच्या सरावात ‘कमी’ किंवा ‘जास्त’ हे शब्द वजाबाकीच्या वेळी वापरावेत.\"]','[{\"q\":\"१० एकक म्हणजे किती दशक होतात?\",\"options\":[\"१ दशक\",\"२ दशक\",\"५ दशक\",\"१० दशक\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार १० एकक म्हणजे १ दशक होय.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"किती समान वस्तूंचा एक गट म्हणजे १ दशक असतो?\",\"options\":[\"५\",\"१\",\"१०\",\"९\"],\"answer\":2,\"explain\":\"१० समान वस्तूंचा एक गट म्हणजे १ दशक असतो.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"अमनने काजलला सुरुवातीला किती रंगीत खडू दिले?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"पाच\"],\"answer\":1,\"explain\":\"अमनने काजलला सुरुवातीला दोन रंगीत खडू दिले.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"काजलकडे २ खडू होते, दादाने तिला अजून ३ खडू दिले, तर तिच्याकडे एकूण किती खडू झाले?\",\"options\":[\"३\",\"४\",\"५\",\"६\"],\"answer\":2,\"explain\":\"२ आणि ३ मिळून ५ होतात (२ + ३ = ५).\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"१० एकक मणी एकत्र केल्यावर काय तयार होते?\",\"options\":[\"१ दशक माळ\",\"१ दशक दांडा\",\"१ दशक लाडू\",\"१ एकक माळ\"],\"answer\":0,\"explain\":\"१० एकक मणी म्हणजे १ दशक माळ असे पुस्तकात दिले आहे.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात मुलगा काय करत आहे?\",\"options\":[\"जेवण करत आहे\",\"चित्रे रंगवत आहे\",\"अभ्यास करत आहे\",\"खेळत आहे\"],\"answer\":1,\"explain\":\"चित्रात अमन चित्र रंगवताना दिसत आहे.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"4\\/029_101.jpg\"},{\"q\":\"दिलेल्या चित्रात एकूण किती मुले दिसत आहेत?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":1,\"explain\":\"चित्रात अमन आणि काजल अशी २ मुले दिसत आहेत.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"apply\",\"figure_image\":\"4\\/029_101.jpg\"},{\"q\":\"१ दशक दांडा तयार करण्यासाठी किती एकक ठोकळे लागतात?\",\"options\":[\"१\",\"५\",\"९\",\"१०\"],\"answer\":3,\"explain\":\"१० एकक ठोकळे मिळून १ दशक दांडा तयार होतो.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"काजलने रंगवलेले चित्र पाहून दादाने तिला काय म्हटले?\",\"options\":[\"छान\",\"वाईट\",\"अजून रंगव\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"दादाने काजलला \'तू चित्र छान रंगवले आहे\' असे म्हणून शाब्बासकी दिली.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर तुझ्याकडे १० लाडू असतील, तर त्याचे किती दशक तयार होतील?\",\"options\":[\"१० दशक\",\"५ दशक\",\"१ दशक\",\"२ दशक\"],\"answer\":2,\"explain\":\"१० वस्तूंचा एक गट म्हणजे १ दशक, म्हणून १० लाडूंचा १ दशक होईल.\",\"topic\":\"बेरीज (उत्तर ९ पर्यंत)\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"अमनदादाने काजलला चित्र रंगवण्यासाठी काय दिले?\",\"options\":[\"वह्या\",\"रंगीत खडू\",\"पेन्सिल\",\"चित्रे\"],\"answer\":1,\"explain\":\"पाठाच्या सुरुवातीला अमनदादाने काजलला रंगीत खडू दिल्याचे नमूद केले आहे.\",\"topic\":\"बेरजेची 