\":[\"१०\",\"१२\",\"२०\",\"०२\"],\"answer\":2,\"explain\":\"२ दशक आणि ० एकक म्हणजे वीस (२०) ही संख्या होय.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"१८ मध्ये १ मिळवल्यास कोणती संख्या मिळते?\",\"options\":[\"१९\",\"२०\",\"१७\",\"२१\"],\"answer\":0,\"explain\":\"१८ (१ दशक ८ एकक) मध्ये १ एकक मिळवला की १९ (१ दशक ९ एकक) होतात.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या संख्येत एकही एकक नाही (० एकक)?\",\"options\":[\"१८\",\"१९\",\"१७\",\"२०\"],\"answer\":3,\"explain\":\"२० या संख्येत २ दशक आणि ० एकक असतात.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"१८, १९ आणि २० यांपैकी सर्वात मोठी संख्या कोणती?\",\"options\":[\"१८\",\"१९\",\"२०\",\"सर्व सारख्या आहेत\"],\"answer\":2,\"explain\":\"दिलेल्या क्रमानुसार १८ पेक्षा १९ मोठी आणि १९ पेक्षा २० ही संख्या मोठी आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"\'१ दशक ९ एकक\' याला अक्षरात कसे लिहाल?\",\"options\":[\"अठरा\",\"एकोणवीस\",\"वीस\",\"सतरा\"],\"answer\":1,\"explain\":\"१ दशक ९ एकक म्हणजे एकोणवीस होय.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21238,4,1,'Maths','mr','लगतची पुढची, लगतची मागची व मधली संख्या','[\"लगतची पुढची संख्या म्हणजे दिलेल्या संख्येच्या उजवीकडील संख्या.\",\"लगतची मागची संख्या म्हणजे दिलेल्या संख्येच्या डावीकडील संख्या.\",\"मधली संख्या म्हणजे दोन संख्यांच्या मध्ये येणारी संख्या.\",\"उदाहरण: ५ च्या लगतची पुढची संख्या ६ आहे.\",\"उदाहरण: ५ च्या लगतची मागची संख्या ४ आहे.\",\"उदाहरण: ३ आणि ५ यांच्या मधली संख्या ४ आहे.\",\"१ आणि २ यांच्या मधली संख्या १.५ नाही, कारण १ आणि २ मध्ये फक्त १ संख्या नाही; त्यामुळे मधली संख्या फक्त दोन सलग संख्यांमध्येच असते.\",\"१ ते २० पर्यंतच्या संख्यांसाठी हे नियम लागू होतात.\",\"संकल्पना लक्षात ठेवण्यासाठी तालिका काढणे उपयुक्त ठरते.\",\"संकल्पना समजण्यासाठी लहान खेळ खेळू शकतो.\",\"वर्गात एकमेकांना प्रश्न विचारून सराव करणे चांगले.\",\"संकल्पना समजल्यावर गणिताच्या इतर भागातही मदत होते.\",\"कधी कधी ० किंवा १ सारख्या संख्यांसाठी लगतची संख्या नसते, ते लक्षात ठेवा.\",\"संकल्पना शिकताना चित्रे आणि तक्ते वापरा.\",\"संकल्पना समजल्यावर विद्यार्थ्यांना स्वतःची तक्ता तयार करण्यास प्रोत्साहित करा.\",\"संकल्पना शिकताना शब्दांची स्पष्टता राखा.\",\"संकल्पना समजण्यासाठी दैनंदिन जीवनातील उदाहरणे द्या.\",\"संकल्पना शिकताना प्रश्नांची पुनरावृत्ती करा.\",\"संकल्पना समजल्यावर विद्यार्थ्यांना स्वतःचे प्रश्न तयार करण्यास सांगा.\",\"संकल्पना शिकताना शिक्षकाने स्पष्ट बोलणे आवश्यक आहे.\",\"संकल्पना शिकताना विद्यार्थ्यांना उत्तर लिहिण्यास सांगणे उपयुक्त ठरते.\"]','[{\"q\":\"६ च्या लगतची मागची संख्या कोणती?\",\"options\":[\"४\",\"५\",\"७\",\"८\"],\"answer\":1,\"explain\":\"मजकुरानुसार, ५ ही ६ च्या लगतची मागची संख्या आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"६ च्या लगतची पुढची संख्या कोणती?\",\"options\":[\"५\",\"७\",\"८\",\"९\"],\"answer\":1,\"explain\":\"मजकुरानुसार, ७ ही ६ च्या लगतची पुढची संख्या आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"५ आणि ७ यांच्या मधली संख्या कोणती?\",\"options\":[\"४\",\"५\",\"६\",\"७\"],\"answer\":2,\"explain\":\"६ ही संख्या ५ व ७ यांच्या मधली संख्या आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"४ च्या लगतची मागची संख्या कोणती?\",\"options\":[\"२\",\"३\",\"५\",\"६\"],\"answer\":1,\"explain\":\"दिलेल्या माहितीनुसार, ४ च्या लगतची मागची संख्या ३ आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"३ आणि ५ यांच्या मधली संख्या कोणती?\",\"options\":[\"२\",\"४\",\"६\",\"७\"],\"answer\":1,\"explain\":\"३ व ५ यांच्या मधली संख्या ४ आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"१० च्या लगतची पुढची संख्या कोणती?\",\"options\":[\"९\",\"८\",\"११\",\"१२\"],\"answer\":2,\"explain\":\"१० च्या लगतची पुढची संख्या ११ आहे.\",\"topic\":\"लगतची व मधली संख्या\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"९ आणि ११ यांच्या मधली संख्या कोणती?\",\"options\":[\"८\",\"१०\",\"१२\",\"७\"],\"