"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'पाच\' या शब्दासाठी योग्य अंक कोणता?\",\"options\":[\"४\",\"६\",\"५\",\"७\"],\"answer\":2,\"explain\":\"तक्त्यामध्ये \'पाच\' या शब्दासमोर ५ हा अंक दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'१०\' या अंकाचे अक्षरी नाव काय आहे?\",\"options\":[\"नऊ\",\"आठ\",\"सात\",\"दहा\"],\"answer\":3,\"explain\":\"तक्त्यानुसार १० या अंकाला \'दहा\' असे म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"संख्यांच्या क्रमानुसार \'तीन\' नंतर कोणता अंक येतो?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"एक\"],\"answer\":1,\"explain\":\"तक्त्यातील क्रमानुसार तीन नंतर चार हा अंक येतो.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'आठ\' या अंकाच्या आधी कोणता अंक येतो?\",\"options\":[\"सात\",\"नऊ\",\"सहा\",\"पाच\"],\"answer\":0,\"explain\":\"दिलेल्या क्रमानुसार आठच्या आधी सात हा अंक येतो.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'चार\' आणि \'सहा\' यांच्या मध्ये कोणता अंक येतो?\",\"options\":[\"तीन\",\"सात\",\"पाच\",\"आठ\"],\"answer\":2,\"explain\":\"तक्त्यानुसार ४, ५, ६ असा क्रम असल्याने मध्ये ५ (पाच) येतो.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तुझ्याकडे \'दोन\' चॉकलेट आहेत, तुला अजून \'एक\' मिळाले, तर एकूण किती होतील?\",\"options\":[\"दोन\",\"चार\",\"तीन\",\"पाच\"],\"answer\":2,\"explain\":\"दोन आणि एक मिळून तीन होतात.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"\'सहा\' या अंकाचे योग्य अक्षरी लेखन ओळखा.\",\"options\":[\"सात\",\"सहा\",\"पाच\",\"आठ\"],\"answer\":1,\"explain\":\"६ या अंकाचे अक्षरी रूप \'सहा\' असे आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी चुकीची जोडी ओळखा.\",\"options\":[\"१ - एक\",\"२ - दोन\",\"३ - पाच\",\"४ - चार\"],\"answer\":2,\"explain\":\"३ या अंकासमोर \'तीन\' हवे होते, \'पाच\' ही चुकीची जोडी आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"\'नऊ\' हा अंक \'दहा\' च्या ________ येतो.\",\"options\":[\"आधी\",\"नंतर\",\"मध्ये\",\"खाली\"],\"answer\":0,\"explain\":\"संख्यांच्या क्रमानुसार नऊ हा अंक दहाच्या आधी येतो.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21247,4,1,'Maths','mr','आकृतिबंध','[\"आकृतिबंध म्हणजे आकृती आणि आकारांची ओळख.\",\"वर्गात आपण वर्तुळ, चौकोन, त्रिकोण, आयत हे आकृतिबंध पाहतो.\",\"वर्तुळाला \'वर्तुळ\' म्हणतात, त्यात एकच बाजू असते.\",\"चौकोनाला चार समान बाजू असतात आणि चार समकोन असतात.\",\"त्रिकोणाला तीन बाजू आणि तीन कोन असतात.\",\"आयताला चार बाजू असतात, पण बाजूंची लांबी वेगवेगळी असू शकते.\",\"समकोन म्हणजे ९० अंशाचा कोन.\",\"समकोन असलेल्या आकृतिबंधाला \'समकोनी\' म्हणतात.\",\"वर्तुळाचे केंद्र \'केंद्रबिंदू\' म्हणतात.\",\"वर्तुळाची परिमिती \'परिघ\' म्हणतात.\",\"आयताची लांबी आणि रुंदी \'माप\' म्हणतात.\",\"आकृतिबंधांमध्ये समान बाजू असलेल्या आकृतिबंधांना \'समरूप\' म्हणतात.\",\"वर्तुळात कोणतीही बाजू नसते, त्यामुळे त्याला \'बाजू\' म्हणत नाहीत.\",\"आकृतिबंध ओळखण्यासाठी आपण त्याच्या बाजूंची आणि कोनांची मोजणी करतो.\",\"आकृतिबंधांचे नाव शिकताना आपण त्यांना चित्रासह ओळखतो.\",\"आकृतिबंधांचे गुणधर्म लक्षात ठेवण्यासाठी आपण तक्ती वापरतो.\",\"आकृतिबंध ओळखताना आपण त्याच्या आकारावरून नाव ओळखतो.\",\"आकृतिबंधांचे वर्गीकरण करताना आपण \'आकार\' आणि \'बाजू\' या आधारावर करतो.\",\"आकृतिबंधांमध्ये सममिती असू शकते, ज्याला \'सममिती रेषा\' म्हणतात.\",\"आकृतिबंध ओळखताना आपण त्यांच्या कोनांची मोजणी करतो.\"]','[{\"q\":\"अनयाने कोणत्या सणाच्या दिवशी सजावटीचे निरीक्षण केले?\",\"options\":[\"दिवाळी\",\"बैलपोळा\",\"दसरा\",\"होळी\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या माहितीनुसार, अनयाने बैलपोळा या दिवशी सजावटीचे निरीक्षण केले.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"विशिष्ट क्रमाने येणाऱ्या घटकांच्या मालिकेला काय म्हणतात?\",\"options\":[\"चित्र\",\"संख्या\",\"आकृतिबंध\",\"रंगकाम\"],\"answer\":2,\"explain\":\"विशिष्ट क्रमाने येणाऱ्या घटकांच्या मालिकेला आकृतिबंध म्हणतात, असे पाठात स्पष्ट केले आहे.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"अनयाने आकृतिबंध कोठे रेखाटले?\",\"options\":[\"भिंतीवर\",\"स्वतःच्या वहीमध्ये\",\"जमिनीवर\",\"पाटीवर\"],\"answer\":1,\"explain\":\"अनयाने तोरण व झुली यांतील आकृतिबंध स्वतःच्या वहीमध्ये रेखाटले आहेत.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"बैलांच्या अंगावरील कशावर आकृतिबंध दिसला?\",\"options\":[\"दोरीवर\",\"शिंगांवर\",\"झुलींवर\",\"पायांवर\"],\"answer\":2,\"explain\":\"पाठात बैलांच्या अंगावरील झुलींमधील आकृतिबंधाचा उल्लेख आहे.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"आकृतिबंध तयार होण्यासाठी घटक कोणत्या प्रकारे येणे आवश्यक आहे?\",\"options\":[\"कसेही\",\"विशिष्ट क्रमाने\",\"फक्त एकदाच\",\"उलट्या क्रमाने\"],\"answer\":1,\"explain\":\"घटक विशिष्ट क्रमाने येतात तेव्हाच त्याला आकृतिबंध म्हणतात.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"घराच्या कशावर अनयाला आकृतिबंध पाहायला मिळाला?\",\"options\":[\"खिडकीवर\",\"दरवाजावर\",\"तोरणावर\",\"छतावर\"],\"answer\":2,\"explain\":\"अनयाने घराच्या तोरणातील आकृतिबंधाचे निरीक्षण केले.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर आपण एक फूल आणि एक पान अशा क्रमाने माळ तयार केली, तर त्याला काय म्हणता येईल?\",\"options\":[\"ढिगारा\",\"आकृतिबंध\",\"साधी ओळ\",\"रंग\"],\"answer\":1,\"explain\":\"विशिष्ट क्रमाने येणाऱ्या घटकांच्या मालिकेला आकृतिबंध म्हणतात, म्हणून ही माळ एक आकृतिबंध आहे.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"आकृतिबंध ओळखण्यासाठी चित्रात काय शोधणे आवश्यक आहे?\",\"options\":[\"विशिष्ट क्रमाने येणारे घटक\",\"मोठी चित्रे\",\"फक्त पांढरा रंग\",\"कागदाचा आकार\"],\"answer\":0,\"explain\":\"चित्राचे निरीक्षण करून त्यात विशिष्ट क्रमाने येणारे घटक शोधल्यास आकृतिबंध ओळखता येतो.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कशामध्ये आकृतिबंध असू शकतो असे पाठात सुचवले आहे?\",\"options\":[\"पाण्याच्या भांड्यात\",\"सजावटीच्या तोरणात\",\"नुसत्या मातीत\",\"आकाशात\"],\"answer\":1,\"explain\":\"पाठात सजावटीचे तोरण आणि झुली यांमधील आकृतिबंधाचे उदाहरण दिले आहे.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"आकृतिबंधाची व्याख्या खालीलपैकी कोणती आहे?\",\"options\":[\"चित्रात रंग भरणे\",\"वहीमध्ये रेघा ओढणे\",\"विशिष्ट क्रमाने येणाऱ्या घटकांची मालिका\",\"सण साजरा करणे\"],\"answer\":2,\"explain\":\"विशिष्ट क्रमाने येणाऱ्या घटकांच्या मालिकेला आकृतिबंध म्हणतात, ही त्याची व्याख्या आहे.\",\"topic\":\"आकृतिबंधाची व्याख्या\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जंगलातून कोण आले?\",\"options\":[\"हत्ती\",\"वाघ\",\"माकड\",\"ससा\"],\"answer\":2,\"explain\":\"कवितेच्या पहिल्या ओळीनुसार जंगलातून माकड आले.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"माकड कशा प्रकारे आले?\",\"options\":[\"हळूहळू चालत\",\"टणटण उड्या मारत\",\"पळत पळत\",\"रांगत रांगत\"],\"answer\":1,\"explain\":\"कवितेत \'टणटण उड्या मारू लागले\' असे म्हटले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"कवितेत कोणत्या संख्येचा टप्पा पूर्ण झाला आहे?\",\"options\":[\"एकचा\",\"दोनचा\",\"तीनचा\",\"चारचा\"],\"answer\":1,\"explain\":\"कवितेत \'पूर्ण झाला दोनचा टप्पा\' असे स्पष्ट दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता आवाजाचा आकृतिबंध तयार करण्यासाठी वापरला जातो?\",\"options\":[\"टाळी\",\"जेवण\",\"झोप\",\"वाचन\"],\"answer\":0,\"explain\":\"प्रकल्पात टाळी, चुटकी आणि पाय आपटणे या हालचाली आवाजासाठी दिल्या आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दोन, चार, सहा, आठ हा कशाचा थाट आहे?\",\"options\":[\"गाण्याचा\",\"खेळाचा\",\"आकृतिबंधाचा\",\"फळांचा\"],\"answer\":2,\"explain\":\"कवितेच्या शेवटच्या ओळीत याला \'आकृतिबंधाचा थाट\' म्हटले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"माकडाच्या उड्यांचा क्रम ओळखा: २, ४, ६, ...?\",\"options\":[\"७\",\"९\",\"८\",\"५\"],\"answer\":2,\"explain\":\"कवितेनुसार दोनच्या टप्प्यातील पुढची संख्या आठ आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"हालचालींच्या आकृतिबंधात \'हात वर\' नंतर कोणती कृती दिली आहे?\",\"options\":[\"हात खाली\",\"हात मागे\",\"हात पुढे\",\"हात बाजूला\"],\"answer\":2,\"explain\":\"प्रकल्पात \'हात वर कर-हात पुढे कर\' असा हालचालींचा क्रम दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'टाळी, चुटकी, पाय आपटणे\' यातून कोणता आकृतिबंध तयार होतो?\",\"options\":[\"आवाजाचा\",\"रंगांचा\",\"फळांचा\",\"अक्षरांचा\"],\"answer\":0,\"explain\":\"या तिन्ही कृतींमधून आवाज निर्माण होतो, म्हणून हा आवाजाचा आकृतिबंध आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"कवितेत दिलेल्या आकृतिबंधात प्रत्येक संख्येमध्ये कितीचा फरक आहे?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":1,\"explain\":\"दोनचा टप्पा म्हणजे प्रत्येक संख्येत २ मिळवले आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती कृती हालचालींच्या आकृतिबंधासाठी (Movements) वापरली आहे?\",\"options\":[\"पाय आपटणे\",\"हात पुढे करणे\",\"चुटकी वाजवणे\",\"टाळी वाजवणे\"],\"answer\":1,\"explain\":\"हात पुढे करणे ही शारीरिक हालचाल आहे, तर इतर आवाजाच्या कृती आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21248,4,1,'Maths','mr','मापन','[\"- मापन म्हणजे वस्तूंची लांबी, वजन, वेळ इत्यादी मोजणे.\",\"- लांबी मोजण्यासाठी मीटर, सेंटीमीटर, इंच वापरतात.\",\"- वजन मोजण्यासाठी किलोग्राम, ग्रॅम, पाउंड वापरतात.\",\"- वेळ मोजण्यासाठी सेकंद, मिनिट, तास वापरतात.\",\"- मापनाचे एकक म्हणजे लांबीचे एकक, वजनाचे एकक, वेळेचे एकक.\",\"- लांबी मोजताना पट्टी किंवा रूलर वापरतो.\",\"- वजन मोजताना तौल किंवा स्केल वापरतो.\",\"- वेळ मोजण्यासाठी घड्याळ किंवा स्टॉपवॉच वापरतो.\",\"- मापन करताना एककाचे रूपांतर करणे आवश्यक असते.\",\"- १०० सेंटीमीटर = १ मीटर.\",\"- १००० ग्रॅम = १ किलोग्राम.\",\"- ६० सेकंद = १ मिनिट.\",\"- ६० मिनिट = १ तास.\",\"- मापन करताना अचूकता महत्त्वाची असते.\",\"- मापनाचे परिणाम नोंदवताना एककासह लिहावे.\",\"- मापनाच्या प्रश्नांमध्ये रिकाम्या जागा भरणे, बरोबर\\/चूक, जुळवणे अशा प्रकारचे प्रश्न असतात.\",\"- मापनाचे प्रश्न सोडवताना दिलेल्या आकड्यांवरून योग्य एकक निवडावे.\",\"- मापनाचे प्रश्न सोडवताना एकक रूपांतराचे नियम लक्षात ठेवावेत.\",\"- मापनाच्या प्रश्नांमध्ये चित्र किंवा आकृती दिली असेल तर ती नीट पाहून उत्तर द्यावे.\",\"- मापनाचे प्रश्न सोडवताना गणितीय चिन्हे आणि शब्दांची योग्य वापर करावी.\",\"- मापनाच्या प्रश्नांमध्ये दिलेल्या आकड्यांवरून लांबी, वजन किंवा वेळेचे मूल्य शोधावे.\",\"- मापनाचे प्रश्न सोडवताना उत्तरात एककासह लिहावे.\",\"- मापनाचे प्रश्न सोडवताना दिलेल्या आकड्यांवरून योग्य एकक निवडावे.\",\"- मापनाचे प्रश्न सोडवताना एकक रूपांतराचे नियम लक्षात ठेवावेत.\"]','[{\"q\":\"नमिताने गोट्यांचे अंतर खड्ड्यापासून मोजण्यासाठी कशाचा वापर केला?\",\"options\":[\"काठीचा\",\"वितीचा\",\"बोटांचा\",\"दोरीचा\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील मजकुरानुसार, नमिताने गोट्यांचे अंतर मोजण्यासाठी वितीचा वापर केला.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मीना कशाची लांबी मोजण्याचा प्रयत्न करत होती?\",\"options\":[\"टेबलची\",\"पुस्तकाची\",\"झाडाच्या पानाची\",\"फळ्याची\"],\"answer\":2,\"explain\":\"मीनाने झाडाच्या पानाची लांबी वितीने मोजण्याचा प्रयत्न केला.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मीनाला पानाची लांबी मोजण्यासाठी वितीपेक्षा काय वापरणे सोयीचे वाटले?\",\"options\":[\"बोटे\",\"हात\",\"पाय\",\"पेन्सिल\"],\"answer\":0,\"explain\":\"मीनाला पानाची लांबी वितीपेक्षा बोटाने मोजणे सोयीचे आहे, हे लक्षात आले.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"तुमचे पुस्तक मोजण्यासाठी खालीलपैकी कोणते साधन वापरणे योग्य ठरेल?\",\"options\":[\"पाय\",\"वीत\",\"काठी\",\"दगड\"],\"answer\":1,\"explain\":\"पुस्तकासारख्या मध्यम आकाराच्या वस्तू मोजण्यासाठी वितीचा वापर करणे सोयीचे असते.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात मुले कोणता खेळ खेळत आहेत?\",\"options\":[\"लपंडाव\",\"गोट्या\",\"क्रिकेट\",\"पकडापकडी\"],\"answer\":1,\"explain\":\"चित्रात रोहित, नमिता आणि संजय गोट्या खेळताना दिसत आहेत.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"4\\/078_101.jpg\"},{\"q\":\"दिलेल्या चित्रात पानाची लांबी मोजण्यासाठी कोणती पद्धत जास्त योग्य दिसत आहे?\",\"options\":[\"वितीने मोजणे\",\"बोटांनी मोजणे\",\"दोन्ही चुकीचे\",\"सांगता येत नाही\"],\"answer\":1,\"explain\":\"पानासारख्या लहान वस्तूसाठी बोटांनी मोजणे ही पद्धत जास्त सोयीची आणि योग्य आहे.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"4\\/078_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील लाकडाचा ओंडका मोजण्यासाठी काय वापरणे जास्त सोयीचे ठरेल?\",\"options\":[\"बोटे\",\"वीत\",\"केस\",\"नखे\"],\"answer\":1,\"explain\":\"मोठ्या वस्तू जसे की लाकडाचा ओंडका मोजण्यासाठी बोटांपेक्षा वीत वापरणे जास्त सोयीचे असते.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"evaluate\",\"figure_image\":\"4\\/079_101.jpg\"},{\"q\":\"खूप लहान वस्तू मोजण्यासाठी वितीपेक्षा बोटे वापरणे का सोयीचे असते?\",\"options\":[\"कारण बोटे लांब असतात\",\"कारण वीत मोठी असते\",\"कारण वस्तू लहान असते\",\"कारण वीत लहान असते\"],\"answer\":2,\"explain\":\"वस्तू लहान असल्यामुळे ती वितीने मोजणे कठीण जाते, म्हणून बोटे वापरणे सोयीचे असते.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"पाठ्यपुस्तकानुसार, फळा मोजण्यासाठी कोणते एकक सुचवले आहे?\",\"options\":[\"बोटे\",\"वीत\",\"मीटर\",\"सेंटीमीटर\"],\"answer\":1,\"explain\":\"मजकुरात \'वर्गातील फळा .....वित लांब आहे\' असे विचारले आहे, म्हणजेच वीत हे एकक सुचवले आहे.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला तुमचा हात मोजायचा असेल, तर तुम्ही काय वापराल?\",\"options\":[\"वीत\",\"बोटे\",\"दोरी\",\"काठी\"],\"answer\":0,\"explain\":\"मजकुरात \'माझा हात .....वित लांब आहे\' असे मोजण्यास सांगितले आहे.\",\"topic\":\"लांबी\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लांबी मोजण्यासाठी वितीप्रमाणेच आपण आणखी काय वापरू शकतो?\",\"options\":[\"पावले\",\"दगड\",\"पाणी\",\"पेन्सिल\"],\"answer\":0,\"explain\":\"मजकुरात लांबी मोजण्यासाठी हाताच्या वितीप्रमाणेच पावले वापरता येतात असे सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"अतुल कोणाला मदत करत होता?\",\"options\":[\"वडिलांना\",\"शिक्षकांना\",\"आईला\",\"मित्राला\"],\"answer\":2,\"explain\":\"अतुल त्याच्या आईला बाजारातून आणलेल्या वस्तू घरात ठेवण्यासाठी मदत करत होता.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पावलाने मोजताना आपण सर्वात आधी काय लिहितो?\",\"options\":[\"प्रत्यक्ष पावले\",\"माझा अंदाज\",\"वस्तूचे नाव\",\"वजन\"],\"answer\":1,\"explain\":\"तक्त्यानुसार, मोजणी करताना आधी \'माझा अंदाज\' लिहिण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वर्गाच्या एका भिंतीची लांबी मोजण्यासाठी काय वापरण्यास सुचवले आहे?\",\"options\":[\"हात\",\"पट्टी\",\"पावले\",\"दोरी\"],\"answer\":2,\"explain\":\"मजकुरात भिंतीची लांबी पावलाने मोजून लिहिण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"मजकुरात \'जड\' या शब्दाच्या विरुद्ध कोणता शब्द वापरला आहे?\",\"options\":[\"मोठा\",\"हलका\",\"लांब\",\"उंच\"],\"answer\":1,\"explain\":\"मजकुरात जड आणि हलका अशा दोन प्रकारच्या वस्तूंचा उल्लेख आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"फळ्याची भिंत ते दरवाजा यांमधील काय मोजायचे आहे?\",\"options\":[\"वजन\",\"अंतर\",\"उंची\",\"रंग\"],\"answer\":1,\"explain\":\"मजकुरात फळ्याची भिंत ते दरवाजा यांमधील \'अंतर\' मोजण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला वर्गातील समोरासमोरील भिंतींमधील अंतर मोजायचे असेल, तर तुम्ही काय मोजाल?\",\"options\":[\"पावले\",\"किलो\",\"लिटर\",\"मिनिटे\"],\"answer\":0,\"explain\":\"भिंतींमधील अंतर मोजण्यासाठी पावलांचा वापर करण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"जड वस्तूंभोवती कोणते चिन्ह करण्यास सांगितले आहे?\",\"options\":[\"X\",\"O\",\"त्रिकोण\",\"चौकोन\"],\"answer\":1,\"explain\":\"मजकुरात जड वस्तूंभोवती \'O\' हे चिन्ह करण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दोन वस्तूंमधील फरक ओळखण्यासाठी विद्यार्थ्यांना काय दाखवण्यास सांगितले आहे?\",\"options\":[\"चित्रे\",\"दोन प्रत्यक्ष वस्तू\",\"फक्त फळा\",\"पुस्तके\"],\"answer\":1,\"explain\":\"विद्यार्थ्यांना दोन वस्तू प्रत्यक्ष दाखवून जड-हलकी वस्तू ओळखण्याचा सराव करण्यास सांगितले आहे.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"तक्त्यामध्ये \'माझा अंदाज\' आणि \'प्रत्यक्ष पावले\' या दोन गोष्टी का दिल्या आहेत?\",\"options\":[\"फक्त लिहिण्यासाठी\",\"अंदाज आणि प्रत्यक्ष मोजणी यांची तुलना करण्यासाठी\",\"चित्र काढण्यासाठी\",\"रंग भरण्यासाठी\"],\"answer\":1,\"explain\":\"अंदाज किती अचूक आहे हे प्रत्यक्ष मोजणी करून पाहण्यासाठी हे दोन रकाने दिले आहेत.\",\"topic\":\"जड-हलका\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पाठ्यपुस्तकातील कृतीनुसार, बादली भरण्यासाठी पेल्यासोबत आणखी कशाचा वापर केला आहे?\",\"options\":[\"चमचा\",\"तांबे\",\"बादली\",\"माठ\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात बादली भरण्यासाठी पेले आणि तांबे यांचा वापर करण्यास सांगितले आहे.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"तुमच्या पाण्याची बाटली भरण्यासाठी पाठ्यपुस्तकात कोणते साधन वापरण्यास सांगितले आहे?\",\"options\":[\"पेला\",\"तांबे\",\"वाटी\",\"बादली\"],\"answer\":2,\"explain\":\"बाटलीत किती पाणी मावेल हे मोजण्यासाठी \'वाटी\' वापरण्यास सांगितले आहे.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"ज्या वस्तूत जास्त पाणी मावेल, त्या वस्तूभोवती कोणते चिन्ह करायचे आहे?\",\"options\":[\"X\",\"O\",\"V\",\"Δ\"],\"answer\":1,\"explain\":\"ज्यात जास्त पाणी मावेल, त्या वस्तूला \'O\' (गोल) करायला सांगितले आहे.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"एका बाटलीत ५ वाट्या पाणी मावते आणि दुसऱ्या बाटलीत ८ वाट्या पाणी मावते, तर कोणती बाटली मोठी आहे?\",\"options\":[\"५ वाट्यांची बाटली\",\"८ वाट्यांची बाटली\",\"दोन्ही सारख्याच\",\"सांगता येणार नाही\"],\"answer\":1,\"explain\":\"ज्या बाटलीत जास्त वाट्या पाणी मावते, ती बाटली मोठी असते.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"बादली पाण्याने \'पूर्ण भरली\' आहे असे कधी म्हणता येईल?\",\"options\":[\"जेव्हा ती रिकामी असेल\",\"जेव्हा त्यात अर्धे पाणी असेल\",\"जेव्हा त्यात आणखी पाणी मावणार नाही\",\"जेव्हा त्यात एकच वाटी पाणी असेल\"],\"answer\":2,\"explain\":\"पूर्ण भरलेली वस्तू म्हणजे ज्यात आणखी पाणी मावणार नाही.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर पेल्याचा आकार तांब्यापेक्षा लहान असेल, तर बादली भरण्यासाठी काय जास्त लागेल?\",\"options\":[\"पेले\",\"तांबे\",\"दोन्ही सारखेच\",\"काहीच नाही\"],\"answer\":0,\"explain\":\"लहान साधनाने मोठी वस्तू भरताना जास्त वेळा पाणी टाकावे लागते.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तुझ्या बाटलीत ४ वाट्या पाणी मावले आणि तुझ्या मित्राच्या बाटलीत ७ वाट्या पाणी मावले, तर कोणाच्या बाटलीत जास्त पाणी मावले?\",\"options\":[\"माझ्या बाटलीत\",\"मित्राच्या बाटलीत\",\"दोघांच्या बाटलीत सारखेच\",\"कोणाच्याच नाही\"],\"answer\":1,\"explain\":\"७ वाट्या हे ४ वाट्यांपेक्षा जास्त असल्यामुळे मित्राच्या बाटलीत जास्त पाणी मावले.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"एकाच आकाराच्या दोन बाटल्या भरण्यासाठी लागणाऱ्या वाट्यांची संख्या कशी असेल?\",\"options\":[\"वेगवेगळी\",\"कमी-जास्त\",\"सारखीच\",\"शून्य\"],\"answer\":2,\"explain\":\"वस्तूंचा आकार सारखा असल्यास त्यांची धारकता (पाणी मावण्याची क्षमता) सारखीच असते.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"बादली भरण्यासाठी पेल्यांची संख्या आणि तांब्यांची संख्या वेगवेगळी का आली असेल?\",\"options\":[\"कारण बादली मोठी आहे\",\"कारण पेला आणि तांब्याचा आकार वेगवेगळा आहे\",\"कारण पाणी कमी आहे\",\"कारण बादली गळकी आहे\"],\"answer\":1,\"explain\":\"मोजण्याचे साधन बदलले की त्यांची संख्याही बदलते कारण त्यांचे आकार वेगवेगळे असतात.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"जर एका वाटीने बाटली भरली, तर त्या बाटलीत किती पाणी मावते हे कशावरून ठरते?\",\"options\":[\"बाटलीच्या रंगावरून\",\"बाटलीच्या उंचीवरून\",\"लागणाऱ्या वाट्यांच्या संख्येवरून\",\"बाटलीच्या टोपणवरून\"],\"answer\":2,\"explain\":\"एखाद्या भांड्यात किती पाणी मावते हे ते भरण्यासाठी लागणाऱ्या लहान मापांच्या संख्येवरून ठरते.\",\"topic\":\"धारकता\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21249,4,1,'Maths','mr','कालमापन','[\"कालमापन म्हणजे वेळ मोजण्याची पद्धत.\",\"सकाळ, दुपार, संध्याकाळ, रात्र या चार वेळा आहेत.\",\"सकाळी ६ वाजता सूर्योदय होतो.\",\"दुपारी १२ वाजता सूर्य सर्वाधिक उंचीवर असतो.\",\"संध्याकाळी ६ वाजता सूर्य मावळतो.\",\"रात्री १२ वाजता अंधार असतो.\",\"घड्याळाच्या तीन काट्यांपैकी तासाचा काटा सर्वात लहान असतो.\",\"मिनिटाचा काटा तासाच्या काट्यापेक्षा मोठा असतो.\",\"सेकंदाचा काटा सर्वात लहान असतो.\",\"सकाळी ८ वाजता शाळा सुरू होते.\",\"दुपारी १ वाजता दुपारचे जेवण असते.\",\"संध्याकाळी ६ वाजता शाळा संपते.\",\"रात्री ९ वाजता झोपायला जायचे असते.\",\"घड्याळावर १२ वाजेची खूण 12 वाजेची असते.\",\"घड्याळावर ६ वाजेची खूण 6 वाजेची असते.\",\"घड्याळावर ३ वाजेची खूण 3 वाजेची असते.\",\"घड्याळावर ९ वाजेची खूण 9 वाजेची असते.\",\"सकाळी ७ वाजता नाश्ता होतो.\",\"दुपारी ४ वाजता चहा पीता.\",\"संध्याकाळी ८ वाजता गृहपाठ पूर्ण करतो.\",\"रात्री १० वाजता झोपायला जातो.\",\"घड्याळावर 1 वाजेची खूण 1 वाजेची असते.\",\"घड्याळावर 2 वाजेची खूण 2 वाजेची असते.\",\"घड्याळावर 4 वाजेची खूण 4 वाजेची असते.\",\"घड्याळावर 5 वाजेची खूण 5 वाजेची असते.\"]','[{\"q\":\"भाकरी करण्यासाठी सर्वात आधी काय करावे लागते?\",\"options\":[\"भाकरी थापणे\",\"पीठ मळणे\",\"भाकरी भाजणे\",\"हात धुणे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील संवादानुसार, आई म्हणते की आधी पीठ मळावे लागते.\",\"topic\":\"घटनेचा क्रम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भाकरी खाण्याआधी काय करणे आवश्यक आहे?\",\"options\":[\"पीठ मळणे\",\"हात धुणे\",\"भाकरी थापणे\",\"पाणी भरणे\"],\"answer\":1,\"explain\":\"अनय म्हणतो की भाकरी खाण्याआधी हात धुवावे, ज्याला आईने बरोबर म्हटले आहे.\",\"topic\":\"घटनेचा क्रम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"पीठ मळून घेतल्यानंतर कोणती कृती केली जाते?\",\"options\":[\"भाकरी खाणे\",\"हात धुणे\",\"भाकरी थापणे\",\"पीठ दळणे\"],\"answer\":2,\"explain\":\"आईने सांगितले आहे की पीठ मळून घेतल्यानंतर भाकरी थापावी लागते.\",\"topic\":\"घटनेचा क्रम\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"भाकरी भाजण्यापूर्वी कोणती कृती केली जाते?\",\"options\":[\"भाकरी थापणे\",\"भाकरी खाणे\",\"हात धुण