art\":7,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात १ तारीख कोणत्या वारी आहे?\",\"options\":[\"सोमवार\",\"मंगळवार\",\"बुधवार\",\"गुरुवार\"],\"answer\":3,\"explain\":\"चित्रातील दिनदर्शिकेचे निरीक्षण केल्यास १ तारीख गुरुवारच्या रकान्यात दिसते.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"4\\/088_101.jpg\"},{\"q\":\"मजकुराप्रमाणे २६ जानेवारीला कोणता दिन साजरा केला जातो?\",\"options\":[\"स्वातंत्र्य दिन\",\"प्रजासत्ताक दिन\",\"शिक्षक दिन\",\"बालदिन\"],\"answer\":1,\"explain\":\"दिलेल्या दिनदर्शिकेच्या खाली २६ जानेवारीला प्रजासत्ताक दिन असे नमूद केले आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिनदर्शिकेत तारखेसोबत आणखी कशाची माहिती दिलेली असते?\",\"options\":[\"फक्त चित्रे\",\"वार\",\"फक्त नावे\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"दिनदर्शिकेत तारखेसोबत रविवार, सोमवार असे वार दिलेले असतात.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात जानेवारी महिन्यात एकूण किती दिवस आहेत?\",\"options\":[\"३०\",\"३१\",\"२८\",\"२९\"],\"answer\":1,\"explain\":\"चित्रातील दिनदर्शिकेत शेवटचा दिनांक ३१ आहे, म्हणून या महिन्यात ३१ दिवस आहेत.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"4\\/088_101.jpg\"},{\"q\":\"आठवड्यातील एका वाराचे नाव खालीलपैकी कोणते?\",\"options\":[\"जानेवारी\",\"मंगळवार\",\"डिसेंबर\",\"सण\"],\"answer\":1,\"explain\":\"मंगळवार हा आठवड्यातील सात वारांपैकी एक वार आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"सुट्ट्यांचे दिवस आणि सण पाहण्यासाठी आपण कशाचा वापर करतो?\",\"options\":[\"दिनदर्शिका\",\"गोष्टीचे पुस्तक\",\"रंगपेटी\",\"खेळणी\"],\"answer\":0,\"explain\":\"दिनदर्शिकेचा उपयोग सण, सुट्ट्या आणि विशिष्ट दिवस पाहण्यासाठी केला जातो.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"दिनदर्शिकेतील १२ महिने कोणत्या क्रमाने असतात?\",\"options\":[\"जानेवारी ते डिसेंबर\",\"डिसेंबर ते जानेवारी\",\"रविवार ते शनिवार\",\"१ ते ३१\"],\"answer\":0,\"explain\":\"मजकुराप्रमाणे दिनदर्शिकेत जानेवारी ते डिसेंबर हा १२ महिन्यांचा क्रम असतो.\",\"topic\":\"दिनदर्शिका\",\"part\":7,\"bloom\":\"analyze\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21250,4,1,'Maths','mr','बेरीज (उत्तर १८पर्यंत)','[\"बेरीज म्हणजे दोन किंवा अधिक संख्यांची एकत्रित बेरीज करणे.\",\"१ ते १० पर्यंतच्या संख्यांची बेरीज ५५ होते.\",\"१+२=३, ३+४=७, ५+६=११ अशा सोप्या बेरीज शिकतो.\",\"बेरीज करताना डावीकडून उजवीकडे लिहावे.\",\"एकक, दहाच्या, शंभराच्या स्थानांची ओळख ठेवावी.\",\"जर बेरीज १० पेक्षा जास्त झाली तर पुढच्या स्थानावर १ जोडावे (कॅरी).\",\"उदाहरण: ७+५=१२, येथे २ एकक आणि १ दहाचे स्थान.\",\"बेरीज करताना समान स्थानांची संख्या एकत्र करावी.\",\"१+१=२, २+२=४, ३+३=६ अशा जोड्या लवकर लक्षात ठेवाव्यात.\",\"बेरीजच्या तक्त्याने लवकर उत्तर शोधता येते.\",\"१० पेक्षा कमी बेरीजसाठी तक्ता वापरू नका, थेट जोडू शकतो.\",\"बेरीज करताना आकड्यांना ओळीतून वाचून एकत्र करणे महत्त्वाचे.\",\"कॅरीची संकल्पना समजून घेणे आवश्यक आहे, अन्यथा चुकीचे उत्तर येऊ शकते.\",\"बेरीजचे तक्ते १ ते १० पर्यंत शिकून लवकर गणना करता येते.\",\"बेरीज शिकल्यावर वजाबाकी सोपी होते, कारण दोन्ही एकत्र येतात.\",\"बेरीजच्या तक्त्यातील पॅटर्न लक्षात ठेवा, जसे १+९=१०, २+८=१० इत्यादी.\",\"बेरीजच्या तक्त्यातील सर्व जोड्या १० होतात, हे लक्षात ठेवा.\",\"बेरीज शिकताना दररोज सराव केल्यास स्मरणशक्ती वाढते.\",\"बेरीजचा अभ्यास करताना चित्रे आणि आकृत्या वापरल्यास समज वाढते.\",\"बेरीज करताना त्रुटी टाळण्यासाठी उत्तर तपासणे आवश्यक आहे.\"]','[{\"q\":\"जोसेफजवळ किती वह्या आहेत?\",\"options\":[\"४\",\"६\",\"८\",\"१२\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार जोसेफजवळ ८ वह्या आहेत.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"सायलीने किती पुस्तके वाचली आहेत?\",\"options\":[\"५\",\"६\",\"७\",\"८\"],\"answer\":2,\"explain\":\"दिलेल्या मजकुरात सायलीने ७ पुस्तके वाचली असे नमूद केले आहे.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"बेरीज करण्यासाठी कोणत्या चिन्हाचा वापर केला जातो?\",\"options\":[\"-\",\"+\",\"=\",\"×\"],\"answer\":1,\"explain\":\"गणितात बेरीज करण्यासाठी \'+\' या चिन्हाचा वापर करतात.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"\'दोघांकडील मिळून एकूण\' वस्तू काढण्यासाठी कोणती क्रिया करावी लागते?\",\"options\":[\"वजाबाकी\",\"बेरीज\",\"गुणाकार\",\"भागाकार\"],\"answer\":1,\"explain\":\"वस्तू एकत्र मोजण्यासाठी किंवा एकूण काढण्यासाठी बेरीज ही क्रिया करतात.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"सिमरनच्या बागेत ८ झाडे आणि राजूच्या बागेत ६ झाडे आहेत, तर दोघांच्या बागेत मिळून एकूण किती झाडे आहेत?\",\"options\":[\"१२\",\"१३\",\"१४\",\"१५\"],\"answer\":2,\"explain\":\"८ + ६ = १४, म्हणून एकूण १४ झाडे आहेत.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"विजूकडे ३ बॉल आणि रवीकडे ७ बॉल आहेत, तर दोघांकडील एकूण बॉलची संख्या किती?\",\"options\":[\"९\",\"१०\",\"११\",\"१२\"],\"answer\":1,\"explain\":\"३ + ७ = १०, म्हणून एकूण १० बॉल आहेत.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"सायलीने ७ पुस्तके वाचली आणि संगीताने ६ पुस्तके वाचली. दोघांनी मिळून एकूण १३ पुस्तके वाचली. या माहितीवरून सर्वात जास्त पुस्तके कोणी वाचली?\",\"options\":[\"संगीता\",\"सायली\",\"दोघींनी सारखी\",\"सांगता येत नाही\"],\"answer\":1,\"explain\":\"७ हे ६ पेक्षा मोठे आहेत, म्हणून सायलीने जास्त पुस्तके वाचली.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या माहितीनुसार, कोणाकडे सर्वात कमी वस्तू आहेत?\",\"options\":[\"विजू (३ बॉल)\",\"सदाशिव (४ वह्या)\",\"रेहाना (५ फुले)\",\"मंथन (६ फुले)\"],\"answer\":0,\"explain\":\"दिलेल्या सर्व संख्यांमध्ये ३ ही सर्वात लहान संख्या आहे.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, सदाशिवजवळ किती वह्या दाखवल्या आहेत?\",\"options\":[\"८\",\"४\",\"१२\",\"५\"],\"answer\":1,\"explain\":\"चित्रातील तक्त्यानुसार सदाशिवजवळ ४ वह्या आहेत.\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"4\\/092_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत, मंथन आणि रेहानाने मिळून एकूण किती फुले आणली आहेत?\",\"options\":[\"१०\",\"११\",\"१२\",\"१३\"],\"answer\":1,\"explain\":\"मंथनची ६ फुले आणि रेहानाची ५ फुले मिळून ११ फुले होतात (६ + ५ = ११).\",\"topic\":\"सोडव\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"4\\/092_102.jpg\"},{\"q\":\"\'खेळ खेळू\' या भागात जास्तीत जास्त किती उत्तर येणारी बेरजेची उदाहरणे दिली आहेत?\",\"options\":[\"१०\",\"१५\",\"१८\",\"२०\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात १८ पर्यंत उत्तर येणाऱ्या बेरजांचा सराव करण्यास सांगितले आहे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खेळ खेळताना एका विद्यार्थ्याने संख्याकार्ड्सच्या समूहातून काय घ्यायचे आहे?\",\"options\":[\"एक पेन\",\"एक वही\",\"एक संख्याकार्ड\",\"एक खडू\"],\"answer\":2,\"explain\":\"खेळ खेळताना एका विद्यार्थ्याने हातात एक संख्याकार्ड घ्यावे असे मजकुरात दिले आहे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकानुसार किती अंकी दोन संख्यांच्या बेरजांचा सराव करायचा आहे?\",\"options\":[\"एक अंकी\",\"दोन अंकी\",\"तीन अंकी\",\"चार अंकी\"],\"answer\":0,\"explain\":\"मजकुरात \'एक अंकी दोन संख्यांच्या बेरजांची\' उदाहरणे घेण्यास सांगितले आहे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खेळामध्ये इतर विद्यार्थ्यांनी काय तयार करायचे आहे?\",\"options\":[\"चित्रे काढणे\",\"उदाहरणे किंवा प्रश्न तयार करणे\",\"गाणी म्हणणे\",\"संख्याकार्ड लपवणे\"],\"answer\":1,\"explain\":\"इतर विद्यार्थ्यांनी संख्याकार्डवरील संख्याएवढे उत्तर येईल अशी उदाहरणे\\/प्रश्न तयार करायचे आहेत.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"विद्यार्थ्यांनी तयार केलेल्या उदाहरणाचे उत्तर कशाएवढे आले पाहिजे?\",\"options\":[\"१० पेक्षा कमी\",\"शिक्षकांनी सांगितलेल्या संख्येएवढे\",\"संख्याकार्डवरील संख्याएवढे\",\"नेहमी १८\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की उत्तर संख्याकार्डवरील संख्याएवढे असावे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर संख्याकार्डवर \'१२\' ही संख्या असेल, तर खालीलपैकी कोणते उदाहरण बरोबर आहे?\",\"options\":[\"९ + २\",\"९ + ३\",\"८ + ३\",\"७ + ४\"],\"answer\":1,\"explain\":\"९ आणि ३ ची बेरीज १२ येते, जे संख्याकार्डवरील उत्तर आहे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या दोन एक अंकी संख्यांची बेरीज \'१४\' येते?\",\"options\":[\"७ + ७\",\"५ + ६\",\"९ + ३\",\"८ + ४\"],\"answer\":0,\"explain\":\"७ + ७ = १४ ही एक अंकी दोन संख्यांची बेरीज आहे.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"रिकाम्या चौकटीत योग्य संख्या भरा: ९ + ४ = $\\\\square$\",\"options\":[\"१२\",\"१३\",\"१४\",\"१५\"],\"answer\":1,\"explain\":\"९ मध्ये ४ मिळवल्यास १३ हे उत्तर येते.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जर उत्तर \'१५\' हवे असेल आणि एक संख्या \'७\' असेल, तर दुसरी संख्या कोणती असेल? ( $\\\\square$ + ७ = १५ )\",\"options\":[\"६\",\"७\",\"८\",\"९\"],\"answer\":2,\"explain\":\"८ + ७ = १५, म्हणून रिकाम्या चौकटीत ८ ही संख्या येईल.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"उत्तर \'१८\' येण्यासाठी ९ मध्ये किती मिळवावे लागतील?\",\"options\":[\"८\",\"९\",\"७\",\"१०\"],\"answer\":1,\"explain\":\"९ + ९ = १८, म्हणून ९ मध्ये ९ मिळवावे लागतील.\",\"topic\":\"खेळ खेळू\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"बाबांनी आणलेल्या पिशवीत काय होते?\",\"options\":[\"सफरचंद\",\"आंबे\",\"पेरू\",\"चिकू\"],\"answer\":1,\"explain\":\"पाठाच्या सुरुवातीलाच \'बाबांनी आणलेली पिशवी पाहिली. त्यांतील आंबे टोपलीत घेतले\' असे दिले आहे.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"सुरुवातीला टोपलीत एकूण किती आंबे होते?\",\"options\":[\"२\",\"३\",\"५\",\"८\"],\"answer\":2,\"explain\":\"पाठात स्पष्ट दिले आहे की \'टोपलीत ५ आंबे होते\'.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दीपकने टोपलीतून २ आंबे घेतल्यावर टोपलीत किती आंबे शिल्लक राहिले?\",\"options\":[\"१\",\"२\",\"३\",\"५\"],\"answer\":2,\"explain\":\"५ - २ = ३, म्हणजे ३ आंबे शिल्लक राहिले.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, ३ आणि २ ची बेरीज किती दाखवली आहे?\",\"options\":[\"३\",\"२\",\"५\",\"४\"],\"answer\":2,\"explain\":\"आकृतीमध्ये ३ + २ = ५ ही बेरीज स्पष्टपणे दाखवली आहे.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"4\\/095_103.jpg\"},{\"q\":\"दिलेल्या आकृतीत, टोपलीमध्ये एकूण किती आंबे दिसत आहेत?\",\"options\":[\"३\",\"४\",\"५\",\"२\"],\"answer\":2,\"explain\":\"चित्रात टोपलीमध्ये ५ आंबे मोजता येतात.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"4\\/095_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत, दीपकने हातात २ आंबे घेतल्यावर टोपलीत किती आंबे उरलेले दिसत आहेत?\",\"options\":[\"२\",\"३\",\"५\",\"१\"],\"answer\":1,\"explain\":\"चित्रात दीपकच्या हातात २ आंबे आहेत आणि टोपलीत ३ आंबे शिल्लक दिसत आहेत.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"apply\",\"figure_image\":\"4\\/095_102.jpg\"},{\"q\":\"दोन संख्यांची बेरीज करून येणाऱ्या संख्येतून एक संख्या वजा केल्यास कोणती संख्या मिळते?\",\"options\":[\"शून्य\",\"तीच संख्या\",\"दुसरी संख्या\",\"मोठी संख्या\"],\"answer\":2,\"explain\":\"पाठातील नियमानुसार, बेरीज करून येणाऱ्या संख्येतून एक संख्या वजा केल्यास दुसरी संख्या मिळते.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"जर ५ - ३ = २, तर यावरून कोणती बेरीज तयार होईल?\",\"options\":[\"५ + ३ = ८\",\"२ + ३ = ५\",\"५ + २ = ७\",\"३ + ३ = ६\"],\"answer\":1,\"explain\":\"वजाबाकीच्या उलट क्रियेने २ + ३ = ५ ही बेरीज मिळते.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"काजलच्या मते, शिल्लक ३ आंबे आणि घेतलेले २ आंबे मिळून किती होतात?\",\"options\":[\"५ आंबे\",\"२ आंबे\",\"३ आंबे\",\"६ आंबे\"],\"answer\":0,\"explain\":\"काजल म्हणते की ३ + २ = ५ आंबे होते.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"५ - २ = ३ आणि ३ + २ = ५ यावरून आपल्याला काय समजते?\",\"options\":[\"फक्त बेरीज समजते\",\"फक्त वजाबाकी समजते\",\"बेरीज-वजाबाकीचा सहसंबंध समजतो\",\"काहीच समजत नाही\"],\"answer\":2,\"explain\":\"या उदाहरणांवरून बेरीज आणि वजाबाकी एकमेकांशी कशा जोडलेल्या आहेत (सहसंबंध) हे समजते.\",\"topic\":\"बेरीज-वजाबाकी : सहसंबंध\",\"part\":6,\"bloom\":\"evaluate\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21251,4,1,'Maths','mr','नाणी व नोटा','[\"नाणी म्हणजे लहान गोलाकार चलन ज्याची किंमत ₹१, ₹२, ₹५, ₹१० अशी असते.\",\"नोटा म्हणजे मोठी चलन ज्याची किंमत ₹५, ₹१०, ₹२०, ₹५०, ₹१०० अशी असते.\",\"नाणी व नोटा दोन्ही एकत्र वापरून रक्कम तयार करता येते.\",\"₹१०० च्या नोटेची किंमत ₹१०० असते, ₹५० ची नोट ₹५० असते.\",\"₹५ च्या नोटेची किंमत ₹५ असते.\",\"नाणी व नोटा ओळखण्यासाठी त्यांच्या आकार, रंग व पृष्ठभागावर असलेल्या चिन्हांकडे पाहावे.\",\"नाणी व नोटा वापरून खरेदी करताना रक्कम मोजून देणे आवश्यक असते.\",\"नाणी व नोटा बचतपेटीत ठेवून पैसे वाचवता येतात.\",\"नाणी व नोटा एकमेकांशी जोडून एकूण रक्कम शोधता येते.\",\"नाणी व नोटा वापरून गणिताचे प्रश्न सोडवता येतात.\",\"नाणी व नोटा ओळखून त्यांची किंमत मोजणे हे लहान मुलांना गणित शिकवण्यासाठी उपयुक्त असते.\",\"नाणी व नोटा वापरून खरेदी करताना \'कमी वेळ\' आणि \'जास्त वेळ\' यांचा फरक समजतो.\",\"नाणी व नोटा वापरून \'एकूण रक्कम\' शोधणे हे बेरीज व वजाबाकीचे मूलभूत तत्त्व आहे.\",\"नाणी व नोटा ओळखून त्यांची किंमत मोजणे हे दैनंदिन जीवनातील गणिताचे उदाहरण आहे.\",\"नाणी व नोटा वापरून खरेदी करताना \'कमी वेळ\' आणि \'जास्त वेळ\' यांचा फरक समजतो.\",\"नाणी व नोटा ओळखून त्यांची किंमत मोजणे हे दैनंदिन जीवनातील गणिताचे उदाहरण आहे.\"]','[{\"q\":\"पाठात \'बचतपेटी\'साठी कोणता इंग्रजी शब्द वापरला आहे?\",\"options\":[\"बँक\",\"पिगी बँक\",\"मनी बॉक्स\",\"कॅश बॉक्स\"],\"answer\":1,\"explain\":\"पाठात बचतपेटीला कंसात \'पिगी बँक\' असे म्हटले आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सर्व नाणी (coins) जमा करण्याचे काम कोणी केले?\",\"options\":[\"सचिन\",\"आई\",\"बाबा\",\"अवनी\"],\"answer\":3,\"explain\":\"पाठाच्या शेवटी अवनी म्हणते, \'सर्व नाणी मी जमा करते.\'\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"अवनी आणि सचिन उद्या कोठे जाणार आहेत?\",\"options\":[\"शाळेत\",\"बागेत\",\"जत्रेत\",\"गावाला\"],\"answer\":2,\"explain\":\"संवादाच्या सुरुवातीलाच अवनी जत्रेत जाण्याबद्दल बोलते.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सचिन जत्रेतून कोणती वस्तू विकत घेणार नाही?\",\"options\":[\"बाहुली\",\"रंगीत पेन्सील\",\"चेंडू\",\"फुगा\"],\"answer\":3,\"explain\":\"सचिन बाहुली, पेन्सील आणि चेंडू घेणार आहे, फुगा अवनी घेणार आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"बचतपेटी उघडण्यापूर्वी मुलांनी कोणाची परवानगी घेतली?\",\"options\":[\"मित्रांची\",\"शिक्षकांची\",\"आईबाबांची\",\"कोणाचीच नाही\"],\"answer\":2,\"explain\":\"पाठात दिले आहे की, अवनी आणि सचिन आपली बचतपेटी आईबाबांना विचारून उघडतात.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात मुलगा (सचिन) काय गोळा करत आहे?\",\"options\":[\"फक्त नाणी\",\"कागदी नोटा\",\"खेळणी\",\"रंगीत खडू\"],\"answer\":1,\"explain\":\"चित्रात मुलगा (सचिन) त्याच्या बाजूला असलेल्या नोटा गोळा करताना दिसत आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"4\\/097_101.jpg\"},{\"q\":\"दिलेल्या चित्रावरून मुलांची बचतपेटी कशाची बनलेली दिसते?\",\"options\":[\"प्लास्टिकची\",\"लोखंडाची\",\"मातीची\",\"काचेची\"],\"answer\":2,\"explain\":\"चित्रात फुटलेली बचतपेटी ही मातीच्या मडक्यासारखी (clay pot) दिसत आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"4\\/097_101.jpg\"},{\"q\":\"अवनीला जत्रेतून कोणत्या वस्तू घ्यायच्या आहेत?\",\"options\":[\"बाहुली, रंगीत खडू व फुगा\",\"बाहुली, चेंडू व फुगा\",\"पेन्सील, खडू व चेंडू\",\"फक्त फुगा\"],\"answer\":0,\"explain\":\"अवनीने जत्रेतून बाहुली, रंगीत खडू व फुगा घेण्याचे ठरवले आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"स्वतःच्या बचतीचे पैसे वापरणे ही कल्पना कोणाची होती?\",\"options\":[\"अवनीची\",\"आईची\",\"सचिनची\",\"बाबांची\"],\"answer\":2,\"explain\":\"सचिनने बचतपेटीतील पैसे वापरण्याची कल्पना मांडली.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"अवनी आणि सचिन या दोघांच्याही यादीत कोणती वस्तू समान (common) आहे?\",\"options\":[\"फुगा\",\"चेंडू\",\"बाहुली\",\"रंगीत खडू\"],\"answer\":2,\"explain\":\"सचिन आणि अवनी या दोघांनाही जत्रेतून बाहुली विकत घ्यायची आहे.\",\"topic\":\"माझी बचत\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"सचिनने सांगितलेल्या नाण्यांमध्ये खालीलपैकी कोणते नाणे आहे?\",\"options\":[\"₹ ५० चे नाणे\",\"₹ २० चे नाणे\",\"₹ ५ चे नाणे\",\"₹ १०० चे नाणे\"],\"answer\":2,\"explain\":\"मजकुरात सचिनने ₹ १, ₹ २, ₹ ५ आणि ₹ १० च्या नाण्यांचा उल्लेख केला आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"अवनीने सांगितलेल्या नोटांमध्ये सर्वात मोठी नोट कोणती आहे?\",\"options\":[\"₹ १०\",\"₹ ५०\",\"₹ २०\",\"₹ १००\"],\"answer\":3,\"explain\":\"अवनीने ₹ ५, ₹ १०, ₹ २०, ₹ ५० आणि ₹ १०० च्या नोटांचा उल्लेख केला आहे, त्यातील ₹ १०० ही सर्वात मोठी आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"बाहुलीची किंमत किती रुपये आहे?\",\"options\":[\"१० रुपये\",\"१५ रुपये\",\"२० रुपये\",\"५ रुपये\"],\"answer\":1,\"explain\":\"मजकुरात बाहुलीची किंमत १५ रुपये दिली आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"अवनीकडे १० रुपये आहेत आणि बाहुली १५ रुपयांची आहे, तर तिला अजून किती रुपये लागतील?\",\"options\":[\"२ रुपये\",\"१० रुपये\",\"५ रुपये\",\"१५ रुपये\"],\"answer\":2,\"explain\":\"१५ - १० = ५, म्हणून अवनीला आणखी ५ रुपये लागतील.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"मोठ्यांच्या मदतीने काय तयार करण्यास सांगितले आहे?\",\"options\":[\"खेळणी\",\"बचतपेटी\",\"नोटा\",\"नाणी\"],\"answer\":1,\"explain\":\"प्रकल्पामध्ये मोठ्यांच्या मदतीने बचतपेटी तयार करण्यास सांगितले आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सचिनकडे १० रुपये असल्यास, तो किती रुपयांपर्यंतची खेळणी विकत घेऊ शकेल?\",\"options\":[\"फक्त ५ रुपयांची\",\"१० रुपयांपर्यंतची\",\"१५ रुपयांची\",\"२० रुपयांची\"],\"answer\":1,\"explain\":\"सचिनकडे १० रुपये असल्यामुळे तो १० रुपयांपर्यंतची खेळणी घेऊ शकतो.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती नोट अवनीने सांगितलेल्या नोटांच्या यादीत नाही?\",\"options\":[\"₹ २०\",\"₹ ५०\",\"₹ ५\",\"₹ ५००\"],\"answer\":3,\"explain\":\"मजकुरात ₹ ५०० च्या नोटेचा उल्लेख नाही.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"नाणी आणि नोटांचा ओळख कशासाठी करून घ्यायची आहे?\",\"options\":[\"चित्र काढण्यासाठी\",\"व्यवहारातील वापरासाठी\",\"खेळण्यासाठी\",\"फेकून देण्यासाठी\"],\"answer\":1,\"explain\":\"नाणी व नोटांचा व्यवहारातील वापर समजावून सांगण्यासाठी त्यांची ओळख करून द्यायची आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सचिनने किती प्रकारच्या नाण्यांचा उल्लेख केला आहे?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"सचिनने ₹ १, ₹ २, ₹ ५ आणि ₹ १० अशा एकूण ४ प्रकारच्या नाण्यांचा उल्लेख केला आहे.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला १० रुपयांचे खेळणे घ्यायचे असेल, तर तुम्ही कोणती नोट द्याल?\",\"options\":[\"₹ ५ ची नोट\",\"₹ २ ची नोट\",\"₹ १० ची नोट\",\"₹ १ ची नोट\"],\"answer\":2,\"explain\":\"१० रुपयांच्या वस्तूसाठी ₹ १० ची नोट वापरता येईल.\",\"topic\":\"खेळणीवाला\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"मजकुरात कोणती रक्कम वेगवेगळ्या प्रकारे तयार करण्याबद्दल सांगितले आहे?\",\"options\":[\"₹ ५\",\"₹ १०\",\"₹ २\",\"₹ १\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे ₹ १० ही रक्कम वेगवेगळ्या प्रकारे तयार करण्याबद्दल सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"₹ १० ही रक्कम कशी तयार करता येते?\",\"options\":[\"फक्त कागदाने\",\"फक्त चित्राने\",\"नाणी व नोटांचा वापर करून वेगवेगळ्या प्रकारे\",\"फक्त मोठ्यांच्या मदतीने\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे नाणी व नोटा वापरून ही रक्कम वेगवेगळ्या प्रकारे तयार करता येते.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"तुमच्याकडे ₹ ५ ची दोन नाणी असल्यास एकूण किती रक्कम होईल?\",\"options\":[\"₹ ७\",\"₹ ५\",\"₹ १०\",\"₹ २\"],\"answer\":2,\"explain\":\"५ + ५ = १०, म्हणून ₹ ५ ची दोन नाणी म्हणजे ₹ १० होतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या नाण्यांच्या गटाने ₹ १० तयार होतील?\",\"options\":[\"₹ ५ चे एक नाणे व ₹ १ चे एक नाणे\",\"₹ २ ची पाच नाणी\",\"₹ ५ ची तीन नाणी\",\"₹ १ ची तीन नाणी\"],\"answer\":1,\"explain\":\"२ रुपयांची ५ नाणी मिळून १० रुपये होतात (२+२+२+२+२=१०).\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"चौकटीत दिलेल्या रकमा तयार करण्यासाठी काय वापरण्यास सांगितले आहे?\",\"options\":[\"दगड आणि काड्या\",\"नाणी व नोटा\",\"पेन आणि पेन्सिल\",\"खेळणी\"],\"answer\":1,\"explain\":\"मजकुरात नाणी व नोटांचा वापर करून रकमा तयार करण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"एकाच रकमेसाठी नाणी व नोटांचे विविध गट वापरणे म्हणजे काय?\",\"options\":[\"रक्कम मोजणे\",\"वेगवेगळ्या प्रकारे रक्कम तयार करणे\",\"पैसे खर्च करणे\",\"पैसे हरवणे\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे ₹ १० ही रक्कम आपण वेगवेगळ्या प्रकारे (नाणी व नोटांचे विविध गट वापरून) तयार करू शकतो.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"₹ ५ चे एक नाणे आणि ₹ १ ची पाच नाणी मिळून किती रक्कम होते?\",\"options\":[\"₹ ६\",\"₹ १०\",\"₹ १५\",\"₹ ५\"],\"answer\":1,\"explain\":\"५ + ५ (१ रुपयाची ५ नाणी) = १०, म्हणून एकूण ₹ १० होतात.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती पद्धत ₹ १० तयार करण्यासाठी चुकीची आहे?\",\"options\":[\"₹ १ ची दहा नाणी\",\"₹ ५ ची दोन नाणी\",\"₹ २ ची पाच नाणी\",\"₹ ५ ची तीन नाणी\"],\"answer\":3,\"explain\":\"₹ ५ ची तीन नाणी म्हणजे ₹ १५ होतात, ₹ १० नाही.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"मजकुराप्रमाणे, आपण ₹ १० ही रक्कम ______ प्रकारे तयार करू शकतो.\",\"options\":[\"फक्त एकाच\",\"वेगवेगळ्या\",\"कठीण\",\"चुकीच्या\"],\"answer\":1,\"explain\":\"मजकुराच्या पहिल्या ओळीत \'वेगवेगळ्या प्रकारे\' असे म्हटले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"विद्यार्थ्यांना कोणता प्रत्यक्ष अनुभव देण्यास सांगितले आहे?\",\"options\":[\"चित्रे काढण्याचा\",\"गाणी म्हणण्याचा\",\"नाणी व नोटा वापरून एकच रक्कम तयार करण्याचा\",\"बागेत खेळण्याचा\"],\"answer\":2,\"explain\":\"मजकुराच्या शेवटी विद्यार्थ्यांना नाणी व नोटा वापरून रक्कम तयार करण्याचा प्रत्यक्ष अनुभव देण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"p