\",\"६२ मध्ये ६ ची स्थानिक किंमत ६ आहे\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील चौथ्या विधानानुसार ३८ मध्ये ३ ची दर्शनी किंमत ३ आहे हे बरोबर आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21353,8,2,'Maths','mr','संख्यांचा लहान-मोठेपणा','[\"दो अंकी संख्यांमध्ये मोठी संख्या शोधण्यासाठी पहिले दशक स्थानाचे अंक पहातात.\",\"दशक समान असल्यास, एकक स्थानाचे अंक पहातात.\",\"ज्यांचे दशक मोठे, त्यांची संख्या मोठी होते.\",\"ज्यांचे एकक मोठे, त्यांची संख्या मोठी होते (दशक समान असल्यास).\",\"सर्वांत लहान संख्या शोधण्यासाठी सर्वात लहान दशक पहातं, त्यानंतर एकक पहातं.\",\"सर्वांत मोठी संख्या शोधण्यासाठी सर्वात मोठा दशक पहातं, त्यानंतर एकक पहातं.\",\"दो अंकी संख्या तयार करण्यासाठी दोन अंको वापरतात, एक दशकासाठी, एक एककासाठी.\",\"एकही अंक दोन वेळा वापरता येतो (उदा. ३३, ४४).\",\"शून्य (०) एकक स्थानावर येतो, पण दशक स्थानावर नाही (उदा. ०५ नाही, ५ आहे).\",\"दो अंकी संख्यांची श्रेणी १० ते ९९ होती.\",\"चिन्ह > मोठा आहे, < लहान आहे दर्शवते.\",\"चिन्ह = समान आहे दर्शवते.\",\"दो अंकी संख्यांची तुलना करताना पहिले दशक, नंतर एकक पहातं.\",\"संख्या २५ मधील दशक २, एकक ५ आहे.\",\"संख्या ४२ मधील दशक ४, एकक २ आहे.\"]','[{\"q\":\"दोन अंकी संख्यांचा लहान-मोठेपणा ठरवताना कोणता नियम वापरतात?\",\"options\":[\"ज्या संख्येचा एकक स्थानचा अंक मोठा ती संख्या मोठी\",\"ज्या संख्येचा दशक स्थानचा अंक मोठा ती संख्या मोठी\",\"ज्या संख्येचा एकक स्थानचा अंक लहान ती संख्या मोठी\",\"दोन्ही अंक सारखे असावे लागतात\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, ज्या दोन अंकी संख्येत दशक स्थानाचा अंक मोठा, ती संख्या मोठी असते.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत, पहिल्या ओळीत एकूण किती मणी दाखवले आहेत?\",\"options\":[\"९ मणी\",\"१० मणी\",\"१९ मणी\",\"२५ मणी\"],\"answer\":2,\"explain\":\"आकृतीत पहिल्या ओळीत १० मण्यांचा एक हार आणि ९ सुटे मणी असे एकूण १९ मणी आहेत.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"8\\/026_103.jpg\"},{\"q\":\"दिलेल्या आकृतीतील तक्त्यावरून, कोणत्या संख्येचा दशक स्थानचा अंक मोठा आहे?\",\"options\":[\"१९\",\"२५\",\"९\",\"५\"],\"answer\":1,\"explain\":\"तक्त्यानुसार १९ चा दशक अंक १ आहे आणि २५ चा दशक अंक २ आहे, म्हणून २५ चा दशक अंक मोठा आहे.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"8\\/026_103.jpg\"},{\"q\":\"रमाकडे ९ मणी आहेत आणि गीताकडे १३ मणी आहेत, तर कोणाकडे जास्त मणी आहेत?\",\"options\":[\"रमाकडे\",\"दोघींकडे सारखेच\",\"गीताकडे\",\"कोणाकडेच नाही\"],\"answer\":2,\"explain\":\"१३ ही संख्या ९ पेक्षा मोठी आहे, म्हणून गीताकडे जास्त मणी आहेत.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'१९ ही संख्या २५ पेक्षा लहान आहे\' हे चिन्हाचा वापर करून कसे लिहाल?\",\"options\":[\"१९ > २५\",\"१९ = २५\",\"१९ < २५\",\"२५ < १९\"],\"answer\":2,\"explain\":\"लहान संख्येसाठी \'<\' हे चिन्ह वापरले जाते, म्हणून १९ < २५ असे लिहितात.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"२५ आणि १९ यांपैकी मोठी संख्या कोणती?\",\"options\":[\"१९\",\"२५\",\"९\",\"५\"],\"answer\":1,\"explain\":\"२५ चा दशक अंक २ हा १९ च्या दशक अंक १ पेक्षा मोठा आहे, म्हणून २५ ही मोठी संख्या आहे.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"४ आणि ७ यांपैकी लहान संख्या कोणती?\",\"options\":[\"७\",\"४\",\"११\",\"३\"],\"answer\":1,\"explain\":\"उजळणीनुसार ४ ही संख्या ७ पेक्षा लहान आहे.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"२५ > १९ यातील \'>\' या चिन्हाचा अर्थ काय होतो?\",\"options\":[\"पेक्षा लहान\",\"पेक्षा मोठे\",\"बरोबर\",\"बेरीज\"],\"answer\":1,\"explain\":\"गणितात \'>\' या चिन्हाचा अर्थ \'पेक्षा मोठे\' असा होतो.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर एका संख्येचा दशक अंक ३ असेल आणि दुसऱ्या संख्येचा दशक अंक १ असेल, तर कोणती संख्या मोठी असेल?\",\"options\":[\"दशक अंक १ असलेली संख्या\",\"दोन्ही संख्या सारख्या असतील\",\"दशक अंक ३ असलेली संख्या\",\"सांगता येणार नाही\"],\"answer\":2,\"explain\":\"ज्या संख्येचा दशक स्थानाचा अंक मोठा असतो ती संख्या मोठी असते.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"१९ या संख्येत दशक स्थानी कोणता अंक आहे?\",\"options\":[\"९\",\"१\",\"०\",\"२\"],\"answer\":1,\"explain\":\"१९ या संख्येत १ हा दशक स्थानी आणि ९ हा एकक स्थानी आहे.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी चुकीचे विधान ओळखा.\",\"options\":[\"१३ ही संख्या ९ पेक्षा मोठी आहे.\",\"९ ही संख्या १३ पेक्षा लहान आहे.\",\"२५ ही संख्या १९ पेक्षा लहान आहे.\",\"१९ ही संख्या २५ पेक्षा लहान आहे.\"],\"answer\":2,\"explain\":\"२५ ही संख्या १९ पेक्षा मोठी आहे, कारण तिचा दशक अंक मोठा आहे.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"दशक स्थानावरून संख्यांचा लहान-मोठेपणा ठरवताना आपण काय पाहतो?\",\"options\":[\"फक्त एकक स्थानचा अंक\",\"फक्त दशक स्थानचा अंक\",\"मण्यांचा रंग\",\"संख्येतील एकूण अंकांची बेरीज\"],\"answer\":1,\"explain\":\"दोन अंकी संख्यांची तुलना करताना प्रथम दशक स्थानचा अंक पाहिला जातो.\",\"topic\":\"दशक स्थानावरून लहान-मोठेपणा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर दोन संख्यांचा दशक अंक समान असेल, तर आपण कोणत्या स्थानातील अंक पाहतो?\",\"options\":[\"एकक\",\"दशक\",\"शतक\",\"हजार\"],\"answer\":0,\"explain\":\"दशक समान असेल तर एकक स्थानातील अंक पाहून लहान-मोठेपणा ठरवला जातो.\",\"topic\":\"दशक समान असताना लहान-मोठेपणा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दशक समान असेल, तर कोणती संख्या मोठी असते?\",\"options\":[\"ज्याचा एकक लहान\",\"ज्याचा एकक मोठा\",\"ज्याचा दशक मोठा\",\"ज्याचा दशक लहान\"],\"answer\":1,\"explain\":\"दशक समान असताना ज्या संख्येचा एकक मोठा असतो, ती संख्या मोठी असते.\",\"topic\":\"दशक समान असताना लहान-मोठेपणा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"१८ ही संख्या १५ पेक्षा मोठी आहे, हे चिन्हाचा वापर करून कसे लिहाल?\",\"options\":[\"१८ < १५\",\"१५ > १८\",\"१८ > १५\",\"१८ = १५\"],\"answer\":2,\"explain\":\"मोठ्या संख्येकडे चिन्हाचे तोंड उघडे असते