,\"~\"],\"answer\":3,\"explain\":\"पाठात \'~\' या चिन्हाला वक्र रेषा म्हटले आहे.\",\"topic\":\"चित्र प्रदर्शन\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"वारली चित्रात घराचे छप्पर काढण्यासाठी नीताने कोणता आकार वापरला असेल?\",\"options\":[\"त्रिकोण\",\"वर्तुळ\",\"वक्र रेषा\",\"उभी रेषा\"],\"answer\":0,\"explain\":\"वारली चित्रकलेत घराच्या छपरासाठी सहसा त्रिकोण (△) वापरला जातो.\",\"topic\":\"चित्र प्रदर्शन\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"पाठात दिलेल्या माहितीनुसार \'\\\\\' आणि \'\\/\' या कोणत्या प्रकारच्या रेषा आहेत?\",\"options\":[\"उभ्या रेषा\",\"आडव्या रेषा\",\"तिरप्या रेषा\",\"वक्र रेषा\"],\"answer\":2,\"explain\":\"पाठात \'\\\\\' आणि \'\\/\' या चिन्हांना तिरप्या रेषा म्हटले आहे.\",\"topic\":\"चित्र प्रदर्शन\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"बोटांच्या मदतीने सावलीतून काय तयार करता येते असे पाठात म्हटले आहे?\",\"options\":[\"विविध प्राणी\",\"विविध फुले\",\"विविध झाडे\",\"विविध फळे\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकात बोटांच्या मदतीने सावलीतून विविध प्राणी तयार करण्याबद्दल सांगितले आहे.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी ठोकळ्यांसोबत कोणता खेळ खेळण्यास सांगितले आहे?\",\"options\":[\"विजेरीच्या मदतीने सावल्यांचा खेळ\",\"ठोकळ्यांचा मनोरा रचणे\",\"ठोकळे मोजणे\",\"ठोकळ्यांना रंग लावणे\"],\"answer\":0,\"explain\":\"शिक्षकांनी विद्यार्थ्यांना विजेरीच्या मदतीने ठोकळ्यांसोबत सावल्यांचा खेळ खेळण्यास सांगितले.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकात कोणत्या रेषांचा सराव करण्यास सांगितले आहे?\",\"options\":[\"आडवी, उभी, तिरपी आणि वक्र रेषा\",\"फक्त सरळ रेषा\",\"फक्त गोल रेषा\",\"फक्त लांब रेषा\"],\"answer\":0,\"explain\":\"पाठात आडवी, उभी, तिरपी आणि वक्र रेषा गिरवण्याचा व काढण्याचा सराव करण्यास सांगितले आहे.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"सावल्यांची गंमत अनुभवताना विद्यार्थ्यांनी सावल्यांमध्ये काय शोधले?\",\"options\":[\"विविध आकार\",\"विविध रंग\",\"वस्तूंची नावे\",\"वस्तूंची किंमत\"],\"answer\":0,\"explain\":\"विजेरीच्या मदतीने खेळताना विद्यार्थ्यांनी सावल्यांमध्ये विविध आकार शोधले.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"\')\', \'U\', \'C\', \'S\' या चिन्हांचा सराव कोणत्या प्रकारच्या रेषेसाठी दिला आहे?\",\"options\":[\"वक्र रेषा\",\"सरळ रेषा\",\"उभी रेषा\",\"आडवी रेषा\"],\"answer\":0,\"explain\":\"हे सर्व आकार वक्र रेषेचे प्रकार आहेत.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"△, □, 〇 या भौमितिक आकारांच्या मदतीने काय करण्यास सुचवले आहे?\",\"options\":[\"आवडीचे चित्र काढणे\",\"अंक लिहिणे\",\"गाणे म्हणणे\",\"मैदानावर खेळणे\"],\"answer\":0,\"explain\":\"पाठात या आकारांच्या मदतीने आवडीचे चित्र काढून ते रंगवण्यास सांगितले आहे.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, चेंडूची सावली कोणत्या आकाराची दिसत आहे?\",\"options\":[\"वर्तुळ\",\"त्रिकोण\",\"चौरस\",\"आयत\"],\"answer\":0,\"explain\":\"चित्रात चेंडूवर विजेरीचा प्रकाश पडल्यावर त्याची सावली वर्तुळाकार दिसत आहे.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"8\\/068_102.jpg\"},{\"q\":\"दिलेल्या चित्रात, सावली पाडण्यासाठी प्रकाशाचे कोणते साधन वापरले आहे?\",\"options\":[\"विजेरी\",\"सूर्य\",\"मेणबत्ती\",\"दिवा\"],\"answer\":0,\"explain\":\"चित्रात सावली तयार करण्यासाठी विजेरीचा (Torch) वापर केलेला दिसत आहे.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"8\\/068_102.jpg\"},{\"q\":\"विविध वस्तूंच्या सावल्या तयार केल्यावर त्यांत काय शोधल्यामुळे आपल्याला भौमितिक आकारांची ओळख होते?\",\"options\":[\"सावल्यांमधील आकार\",\"सावल्यांचा अंधार\",\"सावल्यांची लांबी\",\"सावल्यांची दिशा\"],\"answer\":0,\"explain\":\"सावल्यांमधील आकार शोधल्यामुळे आपल्याला भौमितिक आकारांची समज येते.\",\"topic\":\"सावल्यांची गंमत\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"जर आपण एका त्रिकोणी वस्तूची सावली भिंतीवर पाडली, तर आपल्याला कोणता आकार मिळण्याची शक्यता आहे?\",\"options\":[\"त्रिकोण\",\"वर्तुळ\",\"गोल\",\"वक्र रेषा\"],\"answer\":0,\"explain\":\"वस्