\":\"फेब्रुवारी महिन्यात २८ किंवा २९ दिवस असतात.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"एका वर्षात ३१ दिवस असणारे एकूण किती महिने आहेत?\",\"options\":[\"४\",\"५\",\"६\",\"७\"],\"answer\":3,\"explain\":\"कॅलेंडरनुसार एका वर्षात ७ महिन्यांचे ३१ दिवस असतात.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"एका वर्षात ३० दिवस असणारे किती महिने आहेत?\",\"options\":[\"४\",\"७\",\"१२\",\"१\"],\"answer\":0,\"explain\":\"एका वर्षात एप्रिल, जून, सप्टेंबर आणि नोव्हेंबर या ४ महिन्यांचे ३० दिवस असतात.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जानेवारीपासून जूनपर्यंत मोजल्यास एकूण किती महिने होतात?\",\"options\":[\"४\",\"५\",\"६\",\"७\"],\"answer\":2,\"explain\":\"जानेवारी(१), फेब्रु(२), मार्च(३), एप्रिल(४), मे(५), जून(६) असे एकूण ६ महिने होतात.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"मे महिन्यानंतर लगतचा पुढचा कोणता महिना येतो?\",\"options\":[\"एप्रिल\",\"जून\",\"जुलै\",\"ऑगस्ट\"],\"answer\":1,\"explain\":\"मे महिन्यानंतर लगेच जून महिना येतो.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"३१ दिवस असणारे लगतचे (एकामागून एक येणारे) महिने कोणते?\",\"options\":[\"मे आणि जून\",\"जून आणि जुलै\",\"जुलै आणि ऑगस्ट\",\"ऑगस्ट आणि सप्टेंबर\"],\"answer\":2,\"explain\":\"जुलै आणि ऑगस्ट या दोन्ही लगतच्या महिन्यांचे प्रत्येकी ३१ दिवस असतात.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जर वर्ष जानेवारीला सुरू होऊन डिसेंबरला संपते, तर वर्षाचा सहावा महिना कोणता असेल?\",\"options\":[\"मे\",\"जून\",\"जुलै\",\"ऑगस्ट\"],\"answer\":1,\"explain\":\"जानेवारीपासून मोजल्यास सहावा महिना जून येतो.\",\"topic\":\"उत्तरे लिहा\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"एका इंग्रजी वर्षात साधारणपणे किती दिवस असतात?\",\"options\":[\"३६०\",\"३६५\",\"३६६\",\"३००\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार एका इंग्रजी वर्षात ३६५ दिवस असतात.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"ज्या वर्षात ३६६ दिवस असतात, त्या वर्षाला काय म्हणतात?\",\"options\":[\"मोठे वर्ष\",\"इंग्रजी वर्ष\",\"लीप वर्ष\",\"ऋतू वर्ष\"],\"answer\":2,\"explain\":\"३६६ दिवस असलेल्या वर्षाला लीप वर्ष म्हणतात.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"लीप वर्षात फेब्रुवारी महिना किती दिवसांचा असतो?\",\"options\":[\"२८\",\"३०\",\"२९\",\"३१\"],\"answer\":2,\"explain\":\"लीप वर्षात फेब्रुवारी महिना २९ दिवसांचा असतो.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"एका ऋतूमध्ये साधारणपणे किती महिने असतात?\",\"options\":[\"२\",\"३\",\"४\",\"५\"],\"answer\":2,\"explain\":\"ऋतुचक्रानुसार एका ऋतूमध्ये साधारण ४ महिने असतात.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, ऑगस्ट महिना कोणत्या ऋतूत येतो?\",\"options\":[\"उन्हाळा\",\"पावसाळा\",\"हिवाळा\",\"वसंत\"],\"answer\":1,\"explain\":\"आकृतीमध्ये ऑगस्ट महिना पावसाळा या ऋतूच्या भागात दाखवला आहे.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"8\\/095_101.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. हिवाळ्याची सुरुवात कोणत्या महिन्यापासून होते?\",\"options\":[\"सप्टेंबर\",\"ऑक्टोबर\",\"नोव्हेंबर\",\"जानेवारी\"],\"answer\":1,\"explain\":\"ऋतुचक्रानुसार हिवाळा ऋतू ऑक्टोबर महिन्यापासून सुरू होतो.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"8\\/095_101.jpg\"},{\"q\":\"खालीलपैकी कोणते महिने उन्हाळा या ऋतूचे आहेत?\",\"options\":[\"फेब्रुवारी, मार्च, एप्रिल, मे\",\"जून, जुलै, ऑगस्ट, सप्टेंबर\",\"ऑक्टोबर, नोव्हेंबर, डिसेंबर, जानेवारी\",\"एप्रिल, मे, जून, जुलै\"],\"answer\":0,\"explain\":\"आकृतीनुसार फेब्रुवारी ते मे हे महिने उन्हाळ्याचे आहेत.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जर या वर्षी फेब्रुवारी महिन्यात २९ दिवस असतील, तर या संपूर्ण वर्षात एकूण किती दिवस असतील?\",\"options\":[\"३६५\",\"३६४\",\"३६६\",\"३६०\"],\"answer\":2,\"explain\":\"फेब्रुवारी २९ दिवसांचा असल्यास ते लीप वर्ष असते आणि त्यात ३६६ दिवस असतात.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पावसाळा ऋतू कोणत्या महिन्यात संपतो?\",\"options\":[\"ऑगस्ट\",\"सप्टेंबर\",\"ऑक्टोबर\",\"जुलै\"],\"answer\":1,\"explain\":\"ऋतुचक्रानुसार पावसाळ्याचा शेवटचा महिना सप्टेंबर आहे.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"ऋतुचक्रानुसार, मे महिना संपल्यानंतर कोणता ऋतू सुरू होईल?\",\"options\":[\"हिवाळा\",\"उन्हाळा\",\"पावसाळा\",\"लीप वर्ष\"],\"answer\":2,\"explain\":\"मे महिना उन्हाळ्याचा शेवटचा महिना असून त्यानंतर पावसाळा सुरू होतो.\",\"topic\":\"ऋतुचक्र\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"भारतीय सौर वर्ष कोणत्या महिन्यापासून सुरू होते?\",\"options\":[\"वैशाख\",\"चैत्र\",\"फाल्गुन\",\"आषाढ\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, भारतीय सौर वर्ष चैत्र महिन्यापासून सुरू होते.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"भारतीय सौर वर्षातील शेवटचा महिना कोणता असतो?\",\"options\":[\"चैत्र\",\"माघ\",\"फाल्गुन\",\"पौष\"],\"answer\":2,\"explain\":\"भारतीय सौर वर्ष फाल्गुन महिन्यात संपते, म्हणजेच तो शेवटचा महिना आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दिनदर्शिकेत काही तारखा आणि वार लाल रंगात का दाखवले जातात?\",\"options\":[\"ते शाळेचे दिवस असतात म्हणून\",\"ते सुट्ट्यांचे दिवस असतात म्हणून\",\"ते परीक्षेचे दिवस असतात म्हणून\",\"ते अभ्यासाचे दिवस असतात म्हणून\"],\"answer\":1,\"explain\":\"दिनदर्शिकेत सुट्ट्यांचे दिवस किंवा वार लाल रंगात दाखवले जातात.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात मुलगी दिनदर्शिकेतील कोणत्या महिन्याबद्दल सांगत आहे?\",\"options\":[\"फेब्रुवारी\",\"मार्च\",\"जानेवारी\",\"एप्रिल\"],\"answer\":2,\"explain\":\"चित्रात मुलगी \'दिनदर्शिकेतील हा जानेवारी महिना आहे\' असे म्हणत आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"8\\/097_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील माहितीनुसार, १० तारखेपासून १६ तारखेपर्यंत कोणत्या तारखांना सुट्ट्या आहेत?\",\"options\":[\"११ व १२\",\"१० व १५\",\"१३ व १४\",\"१५ व १६\"],\"answer\":1,\"explain\":\"चित्रातील संवादानुसार १० व १५ तारखांना सुट्ट्या आहेत.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"8\\/098_101.jpg\"},{\"q\":\"१० ते १६ तारखेच्या आठवड्यात शाळा एकूण किती दिवस होती?\",\"options\":[\"४ दिवस\",\"६ दिवस\",\"७ दिवस\",\"५ दिवस\"],\"answer\":3,\"explain\":\"पाठात दिलेल्या माहितीनुसार, या आठवड्यात शाळा ५ दिवस होती.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"१ तारखेपासून १० तारखेपर्यंत ७ दिवस शाळा होती, तर या १० दिवसांत किती दिवस सुट्टी होती?\",\"options\":[\"३ दिवस\",\"२ दिवस\",\"५ दिवस\",\"१ दिवस\"],\"answer\":0,\"explain\":\"एकूण १० दिवसांतून ७ दिवस शाळा वजा केल्यास ३ दिवस सुट्टी उरते.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"भारतीय सौर वर्षात फाल्गुन महिना संपल्यानंतर पुन्हा कोणता महिना सुरू होतो?\",\"options\":[\"चैत्र\",\"वैशाख\",\"ज्येष्ठ\",\"आषाढ\"],\"answer\":0,\"explain\":\"फाल्गुन महिना संपल्यावर पुन्हा नवीन सौर वर्ष चैत्र महिन्यापासून सुरू होते.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"१० ते १६ तारखेच्या दरम्यान खालीलपैकी कोणता दिवस शाळेचा दिवस म्हणून दिलेला नाही?\",\"options\":[\"सोमवार\",\"बुधवार\",\"शुक्रवार\",\"शनिवार\"],\"answer\":2,\"explain\":\"पाठात शाळेच्या दिवसांच्या यादीत शुक्रवार दिलेला नाही, कारण १५ तारखेला सुट्टी आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दिनदर्शिकेचा वापर मुख्यत्वे कशासाठी केला जातो?\",\"options\":[\"चित्रे काढण्यासाठी\",\"तारीख आणि वार पाहण्यासाठी\",\"गाणी गाण्यासाठी\",\"खेळ खेळण्यासाठी\"],\"answer\":1,\"explain\":\"दिनदर्शिकेचा वापर तारखा, वार आणि सुट्ट्या समजून घेण्यासाठी केला जातो.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एका आठवड्यात १० आणि १५ तारखेला सुट्टी असेल, तर त्या आठवड्यातील कामाचे दिवस किती असतील?\",\"options\":[\"७\",\"६\",\"५\",\"४\"],\"answer\":2,\"explain\":\"आठवड्यात ७ दिवस असतात, त्यातून २ सुट्ट्या वजा केल्यास ५ दिवस कामाचे उरतात.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"चैत्र हा भारतीय सौर वर्षातील कितवा महिना आहे?\",\"options\":[\"दुसरा\",\"शेवटचा\",\"पाचवा\",\"पहिला\"],\"answer\":3,\"explain\":\"सौर वर्ष चैत्र महिन्यापासून सुरू होते, म्हणून तो पहिला महिना आहे.\",\"topic\":\"दिनदर्शिका\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"२०२७ च्या जानेवारी महिन्याचा पहिला वार कोणता आहे?\",\"options\":[\"गुरुवार\",\"शुक्रवार\",\"शनिवार\",\"रविवार\"],\"answer\":1,\"explain\":\"मजकुरातील पर्यायानुसार जानेवारी २०२७ चा पहिला वार शुक्रवार आहे.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जानेवारी २०२७ मध्ये पहिला रविवार कोणत्या तारखेला येतो?\",\"options\":[\"३\",\"४\",\"५\",\"१\"],\"answer\":0,\"explain\":\"दिनदर्शिकेच्या निरीक्षणावरून पहिला रविवार ३ तारखेला येतो.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"८ जानेवारी २०२७ रोजी कोणता वार आहे?\",\"options\":[\"सोमवार\",\"मंगळवार\",\"बुधवार\",\"शुक्रवार\"],\"answer\":3,\"explain\":\"जर १ तारीख शुक्रवार असेल, तर ८ तारखेला पुन्हा शुक्रवार येतो.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जानेवारी २०२७ चा शेवटचा वार कोणता आहे?\",\"options\":[\"शुक्रवार\",\"शनिवार\",\"रविवार\",\"सोमवार\"],\"answer\":2,\"explain\":\"मजकुरातील पर्यायानुसार या महिन्याचा शेवटचा वार रविवार आहे.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जानेवारी २०२७ मध्ये एकूण किती शुक्रवार आले आहेत?\",\"options\":[\"४\",\"५\",\"६\",\"३\"],\"answer\":1,\"explain\":\"१, ८, १५, २२ आणि २९ या तारखांना शुक्रवार असल्याने एकूण ५ शुक्रवार येतात.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर जानेवारीचा शेवटचा वार रविवार असेल, तर १ फेब्रुवारी २०२७ रोजी कोणता वार येईल?\",\"options\":[\"सोमवार\",\"मंगळवार\",\"रविवार\",\"शनिवार\"],\"answer\":0,\"explain\":\"रविवारनंतर लगेच येणारा वार सोमवार असतो, म्हणून १ फेब्रुवारीला सोमवार येईल.\",\"topic\":\"दिनदर्शिकेचे निरीक्षण\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"मजकुरात कोणत्या वर्षाच्या दिनदर्शिकेचे निरीक्षण करण्यास सांगितले आहे?\",\"options\":[\"२०२५\",\"२०२६\",\"२०२७\",\"२०२८\"],\"answer