tand\"},{\"q\":\"आजी-आजोबा घरात कोणती महत्त्वाची भूमिका बजावत होते?\",\"options\":[\"ते स्वयंपाक करत होते\",\"ते कामांवर देखरेख आणि पाहुण्यांचे स्वागत करत होते\",\"ते फक्त विश्रांती घेत होते\",\"ते बाजारात खरेदीला गेले होते\"],\"answer\":1,\"explain\":\"आजी-आजोबा सगळ्या कामांवर देखरेख करत होते आणि पाहुण्यांचे स्वागत करत होते.\",\"topic\":\"मीनाच्या घरी लग्नाची लगबग\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सगळे नातेवाईक एकमेकांबरोबर कसे काम करत होते?\",\"options\":[\"भांडण करत\",\"शांत बसून\",\"मिळूनमिसळून आणि हसतखेळत\",\"नाइलाजाने\"],\"answer\":2,\"explain\":\"सगळे नातेवाईक एकमेकांबरोबर मिळूनमिसळून, हसतखेळत काम करत होते असे वर्णन पाठात आहे.\",\"topic\":\"मीनाच्या घरी लग्नाची लगबग\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, मुलगी (मीना) मोठ्या माणसांना मदत करण्यासाठी काय करत आहे?\",\"options\":[\"ती जमिनीवर बसून खेळत आहे\",\"ती पाहुण्यांना प्लेटमधून काहीतरी खाऊ देत आहे\",\"ती दारापाशी उभी आहे\",\"ती फुले वेचत आहे\"],\"answer\":1,\"explain\":\"चित्रात मुलगी हातात प्लेट घेऊन बसलेल्या मोठ्या माणसांना काहीतरी देताना दिसत आहे.\",\"topic\":\"मीनाच्या घरी लग्नाची लगबग\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"10\\/015_101.jpg\"},{\"q\":\"लग्नानिमित्त आलेल्या लहान मुलाची (नातवाची) काळजी घरातील लोक कशी घेत होते?\",\"options\":[\"त्याला एकटे सोडून\",\"त्याच्याशी खेळून आणि त्याची काळजी घेऊन\",\"त्याला बाहेर पाठवून\",\"त्याला झोपवून\"],\"answer\":1,\"explain\":\"सर्वजण नातवाशी खेळण्यात दंग झाले होते आणि त्याची काळजीही घेत होते.\",\"topic\":\"मीनाच्या घरी लग्नाची लगबग\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात, लग्नाच्या तयारीचा भाग म्हणून एक माणूस हातात काय घेऊन उभा आहे?\",\"options\":[\"मिठाईचा डबा\",\"फुलांचा हार\",\"पाण्याची बाटली\",\"लग्नाची पत्रिका\"],\"answer\":1,\"explain\":\"चित्रात एक माणूस दाराजवळ पिवळ्या फुलांचा हार हातात धरून उभा असल्याचे दिसते.\",\"topic\":\"मीनाच्या घरी लग्नाची लगबग\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"10\\/015_101.jpg\"},{\"q\":\"मीनाच्या घरी उत्साहाचे वातावरण असण्याचे मुख्य 