loom\":\"apply\"},{\"q\":\"मीनाच्या आजोबांच्या आजारपणात शेजाऱ्यांनी मदत केली, यावरून शेजाऱ्यांचा कोणता गुण दिसून येतो?\",\"options\":[\"स्वार्थीपणा\",\"गरज असताना मदत करणे\",\"फक्त खेळणे\",\"दुर्लक्ष करणे\"],\"answer\":1,\"explain\":\"गरज असेल तेव्हा एकमेकांना मदत करणे हा शेजाऱ्यांचा महत्त्वाचा गुण या उदाहरणातून दिसतो.\",\"topic\":\"शेजारी आणि समाज\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, शेजारी आपल्या जीवनात का महत्त्वाचे आहेत?\",\"options\":[\"कारण ते फक्त गोष्टी सांगतात\",\"कारण ते फक्त रांगोळी काढतात\",\"कारण ते सुख-दुःखात आणि गरजेच्या वेळी सोबत असतात\",\"कारण ते फक्त सुट्टीत भेटतात\"],\"answer\":2,\"explain\":\"समारंभ साजरे करणे आणि आजारपणात मदत करणे यावरून शेजारी सुख-दुःखात सोबत असतात हे स्पष्ट होते.\",\"topic\":\"शेजारी आणि समाज\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरासाठी सर्वात योग्य शीर्षक कोणते असेल?\",\"options\":[\"माझी शाळा\",\"मीनाचे आजोबा\",\"आपला समाज आणि शेजारी\",\"फुलांची तोरणे\"],\"answer\":2,\"explain\":\"हा संपूर्ण उतारा शेजारी, एकमेकांना होणारी मदत आणि समाजाची रचना यावर आधारित आहे.\",\"topic\":\"शेजारी आणि समाज\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"मीनाच्या घरात कोणते प्राणी होते?\",\"options\":[\"गाय आणि बैल\",\"कुत्रा आणि मांजर\",\"घोडा आणि गाढव\",\"ससा आणि पोपट\"],\"answer\":1,\"explain\":\"मजकुरात मीनाच्या घरात एक कुत्रा व एक मांजर असल्याचे सांगितले आहे.\",\"topic\":\"प्राणी, पक्षी आणि निसर्ग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मीना पक्ष्यांसाठी पाणी आणि दाणे कशात ठेवते?\",\"options\":[\"प्लास्टिकच्या डब्यात\",\"स्टीलच्या ताटात\",\"मातीच्या भांड्यात\",\"काचेच्या पेल्यात\"],\"answer\":2,\"explain\":\"मजकुरात मीना मातीच्या दोन भांड्यांत पाणी आणि दाणे ठेवते असे दिले आहे.\",\"topic\":\"प्राणी, पक्षी आणि निसर्ग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"कुत्र्याला आनंद का झाला होता?\",\"options\":[\"त्याला खाऊ मिळाला म्हणून\",\"घरात खूप माणसे बसली होती म्हणून\",\"तो बाहेर फिरायला गेला म्हणून\",\"त्याला नवीन खेळणी मिळाली म्हणून\"],\"answer\":1,\"explain\":\"मजकुरात दिले आह