ptions\":[\"फक्त प्लास्टिकची भांडी\",\"फक्त सोन्याची भांडी\",\"मातीची आणि धातूंची भांडी\",\"कागदी भांडी\"],\"answer\":2,\"explain\":\"मजकुरात मातीची आणि धातूंची भांडी विक्रीला ठेवल्याचा उल्लेख आहे.\",\"topic\":\"आठवडी बाजार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"आठवडी बाजाराचा खरेदी-विक्री व्यतिरिक्त दुसरा कोणता महत्त्वाचा फायदा मजकुरात सांगितला आहे?\",\"options\":[\"लोकांना व्यायाम होतो\",\"लोकांच्या एकमेकांशी गाठीभेटी होतात\",\"गावात खूप गोंधळ होतो\",\"शाळेला सुट्टी मिळते\"],\"answer\":1,\"explain\":\"आठवडी बाजाराच्या निमित्ताने लोकांच्या एकमेकांशी गाठीभेटी होतात, हा एक सामाजिक फायदा आहे.\",\"topic\":\"आठवडी बाजार\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"बाजारातील दुकानांच्या मांडणीवरून काय समजते?\",\"options\":[\"सर्व दुकाने पक्क्या इमारतीत होती\",\"काही विक्रेते जमिनीवर पथऱ्या पसरून तर काही बाकांवर बसले होते\",\"बाजारात दुकानेच नव्हती\",\"सर्व दुकाने चालती-फिरती होती\"],\"answer\":1,\"explain\":\"बाजारात विक्रेते जमिनीवर पथऱ्या पसरून किंवा तात्पुरत्या लाकडी बाकांवर दुकान मांडून बसले होते.\",\"topic\":\"आठवडी बाजार\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"विक्रेते आपापल्या वस्तूंची जाहिरात कशी करत होते?\",\"options\":[\"टीव्हीवर जाहिरात देऊन\",\"शांत बसून राहून\",\"ओरडून जाहिरात करून\",\"पत्रके वाटून\"],\"answer\":2,\"explain\":\"ग्राहकांना आकर्षित करण्यासाठी विक्रेते आपापल्या वस्तूंची ओरडून जाहिरात करत होते.\",\"topic\":\"आठवडी बाजार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, विक्रेत्यांनी आपले दुकान मांडण्यासाठी कशाचा वापर केला आहे?\",\"options\":[\"मोठ्या काचेच्या शोकेसचा\",\"जमिनीवर अंथरलेले कापड (पथऱ्या) आणि लाकडी बाक\",\"मोठ्या लोखंडी कपाटांचा\",\"फक्त सायकलींचा\"],\"answer\":1,\"explain\":\"चित्रात विक्रेते जमिनीवर बसून किंवा छोट्या बाकांवर वस्तू ठेवून विकताना दिसत आहेत.\",\"topic\":\"आठवडी बाजार\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"10\\/033_102.jpg\"},{\"q\":\"दिलेल्या चित्रात, खरेदीसाठी आलेले लोक सामान नेण्यासाठी काय वापरत आहेत?\",\"options\":[\"प्लास्टिकच्या पिशव्या\",\"कापडी पिशव्या\",\"मोठ्या टोप