ly\"},{\"q\":\"मजकुरात \'गंज\'चे कोणते उदाहरण दिले आहे?\",\"options\":[\"भांडीगंज\",\"भाजीगंज\",\"कापडगंज\",\"फळगंज\"],\"answer\":2,\"explain\":\"मजकुरात गंजचे उदाहरण म्हणून \'कापडगंज\' हा शब्द दिला आहे.\",\"topic\":\"सांगा पाहू!\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या ठिकाणी फक्त भांडी विकली जात असतील, तर त्या ठिकाणाला काय म्हणता येईल?\",\"options\":[\"भांडीगंज\",\"भांडीहाट\",\"भांडीबाजार\",\"भांडीघर\"],\"answer\":0,\"explain\":\"फक्त भांडी (एकाच प्रकारची वस्तू) विकल्या जाणाऱ्या ठिकाणाला भांडीगंज म्हणता येईल.\",\"topic\":\"सांगा पाहू!\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"बाजार आणि हाट यांमधील मुख्य फरक कोणता?\",\"options\":[\"बाजार रोज असतो, तर हाट ठराविक वेळी असतो\",\"बाजार मोठा असतो आणि हाट लहान असतो\",\"बाजार गावात असतो आणि हाट शहरात असतो\",\"बाजार फक्त कपड्यांचा असतो\"],\"answer\":0,\"explain\":\"बाजार रोजच्या खरेदी-विक्रीचे ठिकाण आहे, तर हाट ठराविक दिवशी किंवा काळात भरतो.\",\"topic\":\"सांगा पाहू!\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"पुढीलपैकी चुकीची जोडी ओळखा:\",\"options\":[\"रोजची खरेदी-विक्री : बाजार\",\"ठराविक दिवशी भरणारा : हाट\",\"एकाच प्रकारच्या वस्तू : गंज\",\"फक्त कापड विकले जाणारे ठिकाण : हाट\"],\"answer\":3,\"explain\":\"फक्त कापड विकले जाणारे ठिकाण म्हणजे \'गंज\' असते, \'हाट\' नाही.\",\"topic\":\"सांगा पाहू!\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"मजकुराच्या शेवटी विचारलेल्या प्रश्नानुसार, बाजार आपल्याला काय करतो?\",\"options\":[\"बाजार आपल्याला काहीतरी शिकवतो\",\"बाजार आपल्याला खेळायला देतो\",\"बाजार आपल्याला झोपायला सांगतो\",\"बाजार आपल्याला रडवतो\"],\"answer\":0,\"explain\":\"मजकुरातील शेवटच्या प्रश्नानुसार, बाजार आपल्याला काहीतरी शिकवतो असे सूचित केले आहे.\",\"topic\":\"सांगा पाहू!\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"ग्राहकांचे संरक्षण करण्यासाठी काय अस्तित्वात आली?\",\"options\":[\"शिक्षण चळवळ\",\"ग्राहक चळवळ\",\"राजकीय चळवळ\",\"खेळ चळवळ\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, ग्राहकांच्या संरक्षणासाठी ग्राहक चळवळ अस्तित्वात आली आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"ग्राहक चळवळ कशासाठी सुरू झाली आहे?\",\"options\":[\"वस्तूंची जाहिरात करण्यासाठी\",\"वस्तूंची विक्री वाढवण्यासाठी\",\"फसवणुकीपासून ग्राहकांचे संरक्षण करण्यासाठी\",\"नवीन दुकाने उघडण्यासाठी\"],\"answer\":2,\"explain\":\"ग्राहकांची फसवणूक टाळणे आणि त्यांचे संरक्षण करणे हा ग्राहक चळवळीचा उद्देश आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात फसवणुकीचा कोणता प्रकार सांगितला आहे?\",\"options\":[\"वस्तूंची चोरी\",\"वजनमापातील फसवणूक\",\"वस्तूंचे मोफत वाटप\",\"वस्तूंची कमी किंमत\"],\"answer\":1,\"explain\":\"वजनमापातील फसवणूक हा ग्राहकांच्या फसवणुकीचा एक प्रकार उताऱ्यात दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"वस्तू खरेदी करताना ग्राहकाने कशाची खातरी करून घ्यावी?\",\"options\":[\"वस्तूचा रंग\",\"दुकानाचे नाव\",\"योग्य मोजमाप आणि योग्य भाव\",\"दुकानदाराचे वय\"],\"answer\":2,\"explain\":\"ग्राहकाने वस्तू घेताना तिचे मोजमाप आणि भाव योग्य असल्याची खातरी करणे गरजेचे आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"वस्तूमध्ये केली जाणारी \'भेसळ\' म्हणजे काय?\",\"options\":[\"वस्तू स्वच्छ करणे\",\"वस्तूमध्ये कमी दर्जाचे पदार्थ मिसळणे\",\"वस्तूची किंमत कमी करणे\",\"वस्तूची नीट मांडणी करणे\"],\"answer\":1,\"explain\":\"भेसळ म्हणजे मूळ वस्तूमध्ये इतर काहीतरी मिसळून ग्राहकाची फसवणूक करणे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"दुकानदाराने वस्तूची किंमत खूप जास्त वाढवली, तर त्याला काय म्हणतात?\",\"options\":[\"ग्राहकांचा फायदा\",\"वस्तूंची मदत\",\"ग्राहकांची फसवणूक\",\"वस्तूंची विक्री\"],\"answer\":2,\"explain\":\"वाढवलेली किंमत हा फसवणुकीचा एक प्रकार आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"वस्तूचा \'योग्य भाव\' तपासणे का गरजेचे आहे?\",\"options\":[\"फसवणूक टाळण्यासाठी\",\"दुकानदाराला मदत करण्यासाठी\",\"वस्तू फुकट मिळवण्यासाठी\",\"वेळ घालवण्यासाठी\"],\"answer\":0,\"explain\":\"योग्य भाव तपासल्यामुळे ग्राहकाची पैशांच्या बाबतीत फसवणूक होत नाही.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"बाजारपेठेत कोणाचे संरक्षण होणे गरजेचे आहे?\",\"options\":[\"फक्त दुकानदारांचे\",\"ग्राहकांचे\",\"फक्त जाहिरातदारांचे\",\"फक्त सरकारचे\"],\"answer\":1,\"explain\":\"बाजारपेठेत विविध प्रकारच्या फसवणुकीपासून ग्राहकांचे संरक्षण होणे महत्त्वाचे आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"ग्राहक चळवळीचा मुख्य उद्देश काय आहे?\",\"options\":[\"वस्तूंचे उत्पादन वाढवणे\",\"ग्राहकांना फसवणुकीपासून वाचवणे\",\"वस्तूंची किंमत वाढवणे\",\"दुकानांची संख्या कमी करणे\"],\"answer\":1,\"explain\":\"ग्राहकांचे संरक्षण करणे हाच ग्राहक चळवळीचा मुख्य हेतू आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"जर ग्राहकाने वजनमाप न तपासता वस्तू घेतली, तर काय होऊ शकते?\",\"options\":[\"त्याला जास्त वस्तू मिळेल\",\"त्याची फसवणूक होऊ शकते\",\"वस्तूची किंमत कमी होईल\",\"दुकानदार खुश होईल\"],\"answer\":1,\"explain\":\"वजनमाप न तपासल्यास ग्राहकाला कमी वजनाची वस्तू मिळून त्याची फसवणूक होऊ शकते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21375,10,3,'EVS','mr','आपल्या गरजा व समस्या','[\"गरजा म्हणजे जिवंत राहण्यासाठी आवश्यक गोष्टी जसे पाणी, अन्न, निवारा, वस्त्र, आरोग्य व शिक्षण.\",\"आवड म्हणजे जीवन अधिक सुखकर करणाऱ्या गोष्टी जसे मिठाई, खेळ, संगीत.\",\"गरजा पूर्ण करणे अनिवार्य असते, आवड पूर्ण करणे ऐच्छिक असते.\",\"पाणी हे जीवनाचे मूलभूत स्रोत आहे, पाण्याशिवाय सर्व जीव मरतात.\",\"अन्नाशिवाय शरीराला ऊर्जा मिळत नाही.\",\"वस्त्र शरीराचे संरक्षण करते – ऊन, वारा, पाऊस यापासून बचाव करते.\",\"निवारा म्हणजे सुरक्षित राहण्याची जागा – घर किंवा आश्रय.\",\"आरोग्य म्हणजे शारीरिक व मानसिक तंदुरुस्ती, नियमित व्यायाम व स्वच्छतेने ते राखले जाते.\",\"शिक्षण सर्वांना समज, विचार व समस्या सोडवण्याची क्षमता देते.\",\"नैसर्गिक संसाधने म्हणजे पाणी, हवा, जमीन, वनस्पती व प्राणी – यांचा वापर काटकसरीने करावा.\",\"मानवनिर्मित संसाधने म्हणजे पैसा, वाहने, यंत्रे इत्यादी.\",\"समस्या म्हणजे गरजा पूर्ण न होणे किंवा अडचणी येणे – जसे पाण्याची टंचाई, अन्नटंचाई.\",\"समस्येचे निराकरण करण्यासाठी उपाय शोधणे व अंमलात आणणे आवश्यक आहे.\",\"दिव्यांग व्यक्तींसाठी विशेष सुविधा व मदतीची गरज असते – रॅम्प, ब्रेल लिपी, सांकेतिक भाषा इत्यादी.\",\"सर्वांना स्वच्छता, आरोग्य व शिक्षणाची समान संधी मिळणे गरजेचे आहे.\",\"आवड नियंत्रित करणे व गरजा पूर्ण करणे हे संतुलित जीवनाचे मूलभूत तत्त्व आहे.\"]','[{\"q\":\"ज्या गोष्टींशिवाय माणसाचे जगणे कठीण होते, त्या गोष्टींना काय म्हणतात?\",\"options\":[\"छंद\",\"मूलभूत गरजा\",\"सवयी\",\"खेळ\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, ज्या गोष्टींशिवाय जगणे कठीण होते त्यांना \'मूलभूत गरजा\' म्हणतात.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणती गोष्ट माणसाच्या मूलभूत गरजांच्या यादीत येते?\",\"options\":[\"खेळणी\",\"दूरदर्शन\",\"शिक्षण\",\"मोबाईल\"],\"answer\":2,\"explain\":\"अन्न, वस्त्र, निवारा, आरोग्य आणि शिक्षण या माणसाच्या मूलभूत गरजा आहेत.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात मुलगा कोणती गोष्ट पिताना दिसत आहे, जी जगण्यासाठी आवश्यक आहे?\",\"options\":[\"दूध\",\"सरबत\",\"पाणी\",\"चहा\"],\"answer\":2,\"explain\":\"चित्रात मुलगा पाणी पिताना दिसत आहे, जी जगण्यासाठी आवश्यक गोष्ट आहे.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"10\\/040_101.jpg\"},{\"q\":\"पाठ्यपुस्तकातील माहितीनुसार \'गरज\' म्हणजे काय?\",\"options\":[\"फक्त खेळण्यासाठी लागणाऱ्या गोष्टी\",\"सकाळी उठल्यापासून रात्री झोपेपर्यंत आवश्यक असणाऱ्या गोष्टी\",\"बाजारात मिळणाऱ्या महागड्या गोष्टी\",\"फक्त सुट्टीत लागणाऱ्या गोष्टी\"],\"answer\":1,\"explain\":\"सकाळी उठल्यापासून रात्री झोपेपर्यंत आपल्याला ज्या गोष्टी आवश्यक असतात, त्यांना \'गरज\' म्हणतात.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"माणसाला रोजच्या जगण्यासाठी सर्वात आधी कोणत्या दोन गोष्टी आवश्यक असतात?\",\"options\":[\"पाणी व अन्न\",\"गाडी व बंगला\",\"सोने व चांदी\",\"फळे व फुले\"],\"answer\":0,\"explain\":\"पाणी व अन्न या दोन गोष्टी माणसाला रोजच्या जगण्यासाठी आवश्यक असतात.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात कुटुंब एकत्र बसून कोणती मूलभूत गरज पूर्ण करत आहे?\",\"options\":[\"शिक्षण\",\"अन्न\",\"आरोग्य\",\"वस्त्र\"],\"answer\":1,\"explain\":\"चित्रात कुटुंब एकत्र जेवण करताना दिसत आहे, म्हणजेच ते \'अन्न\' ही गरज पूर्ण करत आहेत.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"10\\/040_101.jpg\"},{\"q\":\"जर एखादा माणूस आजारी पडला, तर त्याला दिलेल्या पर्यायांपैकी कोणत्या मूलभूत गरजेची सर्वात जास्त गरज असेल?\",\"options\":[\"वस्त्र\",\"शिक्षण\",\"आरोग्य\",\"निवारा\"],\"answer\":2,\"explain\":\"आजारपणात उपचारांसाठी \'आरोग्य\' ही मूलभूत गरज महत्त्वाची ठरते.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"शाळेत जाऊन अभ्यास करणे, ही माणसाची कोणती मूलभूत गरज पूर्ण करण्याचा प्रयत्न आहे?\",\"options\":[\"अन्न\",\"शिक्षण\",\"निवारा\",\"वस्त्र\"],\"answer\":1,\"explain\":\"शाळेत जाणे आणि अभ्यास करणे हे \'शिक्षण\' या मूलभूत गरजेत येते.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"थंडी, वारा आणि पावसापासून स्वतःचे रक्षण करण्यासाठी माणसाला कोणत्या मूलभूत गरजेची आवश्यकता असते?\",\"options\":[\"शिक्षण\",\"आरोग्य\",\"अन्न\",\"निवारा\"],\"answer\":3,\"explain\":\"निवारा (घर) माणसाचे ऊन, वारा आणि पावसापासून रक्षण करतो.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता गट माणसाच्या सर्व मूलभूत गरजा अचूकपणे दर्शवतो?\",\"options\":[\"अन्न, पाणी, खेळ, फिरणे\",\"अन्न, वस्त्र, निवारा, आरोग्य, शिक्षण\",\"मोबाईल, टीव्ही, संगणक, सायकल\",\"फळे, फुले, मिठाई, खेळणी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात अन्न, वस्त्र, निवारा, आरोग्य आणि शिक्षण या पाच मूलभूत गरजा सांगितल्या आहेत.\",\"topic\":\"आपल्या गरजा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'गरज\' म्हणजे काय?\",\"options\":[\"ज्यांच्याशिवाय आपण जिवंत राहणे अवघड असते अशा गोष्टी\",\"ज्या गोष्टी फक्त खेळण्यासाठी असतात\",\"ज्या गोष्टी खूप महाग असतात\",\"ज्या गोष्टी फक्त सुट्टीत लागतात\"],\"answer\":0,\"explain\":\"पाठात दिलेल्या व्याख्येनुसार, गरज म्हणजे अशा गोष्टी ज्यांच्याशिवाय जिवंत राहणे अवघड असते.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"अन्न आणि पाण्याशिवाय काय होईल?\",\"options\":[\"आपण जगू शकणार नाही\",\"आपल्याला खूप आनंद होईल\",\"आपले जीवन सुखकारक होईल\",\"काहीच फरक पडणार नाही\"],\"answer\":0,\"explain\":\"अन्न आणि पाणी ही आपली मूलभूत गरज आहे, त्याशिवाय आपण जगू शकत नाही.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"आवडीच्या गोष्टींमुळे आपल्या जीवनावर काय परिणाम होतो?\",\"options\":[\"जीवन अधिक सुखकारक आणि आरामदायक होते\",\"जीवन जगणे अशक्य होते\",\"आरोग्य बिघडते\",\"गरजा कमी होतात\"],\"answer\":0,\"explain\":\"पाठात नमूद केल्याप्रमाणे आवडीच्या गोष्टी आपले जीवन अधिक सुखकारक आणि आरामदायक करतात.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"राजू रोज खूप मिठाई खातो, हे योग्य आहे का?\",\"options\":[\"हो, कारण त्याला ती आवडते\",\"नाही, हे योग्य नाही\",\"हो, कारण मिठाई ही गरज आहे\",\"माहित नाही\"],\"answer\":1,\"explain\":\"अति प्रमाणात मिठाई खाणे आरोग्यासाठी योग्य नसते, जरी ती आवड असली तरी.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणती गोष्ट \'गरज\' या गटात येते?\",\"options\":[\"वेफर्स\",\"चॉकलेट\",\"धान्य\",\"शीतपेय\"],\"answer\":2,\"explain\":\"धान्य हे अन्नाचा भाग असल्याने ती एक गरज आहे, तर इतर गोष्टी आवडीच्या आहेत.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पाठात दिलेल्या माहितीनुसार, कशाला आवर घालणे शक्य असते?\",\"options\":[\"गरजेला\",\"तहानेला\",\"भुकेला\",\"आवडीला\"],\"answer\":3,\"explain\":\"पाठात स्पष्ट म्हटले आहे की, आवडीला आवर घालणे शक्य असते.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती गोष्ट \'आवड\' या गटात मोडते?\",\"options\":[\"घर\",\"खेळणी\",\"कपडे\",\"पाणी\"],\"answer\":1,\"explain\":\"खेळणी ही मनोरंजनासाठी असतात, ती जगण्यासाठी आवश्यक गरज नाहीत.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"जर आवडीच्या गोष्टी नसतील, तर काय होईल?\",\"options\":[\"जगणे अशक्य होईल\",\"माणूस आजारी पडेल\",\"तरीही जगणे शक्य असते\",\"भूक लागणार नाही\"],\"answer\":2,\"explain\":\"पाठात सांगितले आहे की आवडीच्या गोष्टी नसल्या तरीही जगणे शक्य असते.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पुस्तके ही खालीलपैकी काय आहे?\",\"options\":[\"गरज\",\"आवड\",\"फक्त खेळ\",\"संकट\"],\"answer\":0,\"explain\":\"पाठातील यादीनुसार पुस्तके ही शिक्षणासाठी आवश्यक असल्याने ती \'गरज\' आहे.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"शीतपेय (Cold drinks) हे कोणत्या गटात येते?\",\"options\":[\"गरज\",\"आवड\",\"मूलभूत गरज\",\"औषध\"],\"answer\":1,\"explain\":\"शीतपेय हे जगण्यासाठी आवश्यक नाही, ती एक आवड आहे.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\\\"सगळ्याच गरजेच्या गोष्टी आवडीच्या असू शकत नाहीत\\\" या विधानाचा अर्थ काय?\",\"options\":[\"गरज आणि आवड नेहमी एकच असते\",\"गरज असली तरी ती गोष्ट आपल्याला आवडेलच असे नाही\",\"आवड हीच गरज असते\",\"गरजा पूर्ण करू नयेत\"],\"answer\":1,\"explain\":\"काही गोष्टी आपल्यासाठी गरजेच्या असतात (उदा. औषध), पण त्या आपल्याला आवडतीलच असे नाही.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणती गोष्ट जगण्यासाठी सर्वात महत्त्वाची आहे?\",\"options\":[\"चॉकलेट\",\"खेळणी\",\"पाणी\",\"व्हिडिओ गेम\"],\"answer\":2,\"explain\":\"पाणी ही मूलभूत गरज आहे, ज्याशिवाय आपण जगू शकत नाही.\",\"topic\":\"गरज आणि आवड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पाण्याचा मुख्य स्रोत कोणता आहे?\",\"options\":[\"नदी\",\"धरण\",\"पाऊस\",\"विहीर\"],\"answer\":2,\"explain\":\"पाऊस हा पाण्याचा मुख्य स्रोत आहे असे पाठात दिले आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पाण्याला \'जीवन\' असे का म्हणतात?\",\"options\":[\"कारण ते चवीला चांगले असते\",\"कारण पाण्याशिवाय जगणे अशक्य असते\",\"कारण ते नळाने येते\",\"कारण ते सार्वजनिक संपत्ती आहे\"],\"answer\":1,\"explain\":\"पाणी मिळाले नाही तर जगणे अशक्य होते, म्हणूनच पाण्याला जीवन म्हणतात.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पाणी ही कोणत्या प्रकारची संपत्ती आहे?\",\"options\":[\"खाजगी संपत्ती\",\"फक्त प्राण्यांची संपत्ती\",\"सार्वजनिक संपत्ती\",\"फक्त वनस्पतींची संपत्ती\"],\"answer\":2,\"explain\":\"पाठात स्पष्ट उल्लेख आहे की पाणी ही सार्वजनिक संपत्ती आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"माणसाप्रमाणेच पाणी कोणासाठी आवश्यक आहे?\",\"options\":[\"केवळ पशुपक्ष्यांसाठी\",\"केवळ वनस्पतींसाठी\",\"पशुपक्षी आणि वनस्पती दोघांसाठीही\",\"फक्त डोंगरांसाठी\"],\"answer\":2,\"explain\":\"पाणी हे माणसाप्रमाणे पशुपक्ष्यांसाठी आणि वनस्पतींसाठीही आवश्यक आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या संकल्पनाचित्रात पाण्याचा \'मुख्य स्रोत\' म्हणून काय दाखवले आहे?\",\"options\":[\"नदी\",\"पाऊस\",\"धरण\",\"विहीर\"],\"answer\":1,\"explain\":\"आकृतीत सर्वात वर \'पाऊस\' हा मुख्य स्रोत म्हणून दाखवला आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"10\\/042_101.jpg\"},{\"q\":\"दिलेल्या संकल्पनाचित्रात पाणी घरापर्यंत येण्यासाठी खालीलपैकी कोणते साधन दिले आहे?\",\"options\":[\"नळ\",\"आकाश\",\"डोंगर\",\"समुद्र\"],\"answer\":0,\"explain\":\"आकृतीत पाणी घरापर्यंत कसे आले या चौकटीत \'नळ\' हा पर्याय दिला आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"10\\/042_101.jpg\"},{\"q\":\"पाणी ही सार्वजनिक संपत्ती आहे, याचा अर्थ काय होतो?\",\"options\":[\"पाण्यावर कोणाचाच हक्क नाही\",\"पाण्यावर सर्वांचा हक्क असतो\",\"पाणी फक्त विकत घेता येते\",\"पाणी फक्त धरणात असते\"],\"answer\":1,\"explain\":\"सार्वजनिक संपत्तीवर सर्वांचा हक्क असतो असे पाठात म्हटले आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या झाडाला अनेक दिवस पाणी मिळाले नाही, तर काय होईल?\",\"options\":[\"ते वेगाने वाढेल\",\"त्याचे जगणे अशक्य होईल\",\"त्याला जास्त फुले येतील\",\"काहीही फरक पडणार नाही\"],\"answer\":1,\"explain\":\"वनस्पतींना पाणी मिळाले नाही तर त्यांचे जगणे अशक्य होते.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"पाण्यामुळे आपली कोणती गरज भागते?\",\"options\":[\"भूक\",\"तहान\",\"झोप\",\"खेळ\"],\"answer\":1,\"explain\":\"पाण्यामुळे तहान भागते असे पाठाच्या सुरुवातीलाच दिले आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पाणी ही सार्वजनिक संपत्ती आहे, या विचाराचा वापर करून आपण काय केले पाहिजे?\",\"options\":[\"पाणी वाया घालवले पाहिजे\",\"पाण्याचा वापर सर्वांसाठी जपून केला पाहिजे\",\"पाणी फक्त स्वतःसाठी साठवले पाहिजे\",\"पाण्याचा वापर करणे थांबवले पाहिजे\"],\"answer\":1,\"explain\":\"पाणी सर्वांचा हक्क असल्याने त्याचा वापर जबाबदारीने करणे आवश्यक आहे.\",\"topic\":\"मूलभूत गरज : पाणी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"माणसाला जगण्यासाठी पाण्याबरोबरच कशाची आवश्यकता असते?\",\"options\":[\"अन्नाची\",\"कपड्यांची\",\"खेळण्यांची\",\"पुस्तकांची\"],\"answer\":0,\"explain\":\"पाठात नमूद केल्याप्रमाणे जगण्यासाठी पाण्याबरोबरच अन्नाची गरज असते.\",\"topic\":\"मूलभूत गरज : हवा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"हवेमध्ये कशाचे कण मिसळल्यामुळे हवा अशुद्ध होते?\",\"options\":[\"पाण्याचे\",\"साखरेचे\",\"धुळीचे\",\"अन्नाचे\"],\"answer\":2,\"explain\":\"हवेमध्ये वाहनांचा धूर, कारखान्यातील धूर आणि धुळीचे कण मिसळल्याने हवा अशुद्ध होते.\",\"topic\":\"मूलभूत गरज : हवा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"शुद्ध हवेत श्वसन केल्यामुळे शरीराचा कोणता भाग निरोगी राहतो?\",\"options\":[\"केस\",\"नखे\",\"फुप्फुसे\",\"दात\"],\"answer\":2,\"explain\":\"शुद्ध हवेमुळे फुप्फुसांचे आरोग्य चांगले राहते.\",\"topic\":\"मूलभूत गरज : हवा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"प्रत्येकाला पुरेसे आणि कसे अन्न मिळायला हवे?\",\"options\":[\"सकस\",\"तेलकट\",\"तिखट\",\"शिळे\"],\"answer\":0,\"explain\":\"उत्तम आरोग्यासाठी सर्वांना पुरेसे आणि सकस अन्न मिळणे आवश्यक आहे.\",\"topic\":\"मूलभूत गरज : हवा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर आपल्याला रोजची कामे करायला उत्साह हवा असेल, तर काय आवश्यक आहे?\",\"options\":[\"अशुद्ध हवा\",\"शुद्ध हवा\",\"खूप झोप\",\"फक्त पाणी\"],\"answer\":1,\"explain\":\"शुद्ध हवेमुळे आपल्याला धावायला, पळायला आणि कामे करायला उत्साह येतो.\",\"topic\":\"मूलभूत गरज : हवा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\