\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"छत्रपती शिवाजी महाराजांच्या \'गडावरी आधी उदक पाहून किल्ला बांधावा\' या विधानाचा अर्थ काय?\",\"options\":[\"किल्ल्यावर आधी सैन्य असावे\",\"किल्ल्यावर आधी उंच बुरूज असावा\",\"किल्ल्यावर आधी पिण्याच्या पाण्याची सोय असावी\",\"किल्ल्यावर आधी धान्य साठवण्याची सोय असावी\"],\"answer\":2,\"explain\":\"उदक म्हणजे पाणी; जेथे पाणी उपलब्ध असेल तेथेच किल्ला बांधावा असा याचा अर्थ होतो.\",\"topic\":\"ऐतिहासिक जलसोयी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"रायगडावरील तलावांमध्ये कोणते पाणी साठवले जाईल अशी सोय शिवाजी महाराजांनी केली होती?\",\"options\":[\"नदीचे पाणी\",\"पावसाचे पाणी\",\"विहिरीचे पाणी\",\"समुद्राचे पाणी\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे पावसाचे पाणी तलावांमध्ये साठवले जाईल अशी सोय केली होती.\",\"topic\":\"ऐतिहासिक जलसोयी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला शिवाजी महाराजांच्या विचारांप्रमाणे नवीन वस्ती वसवयाची असेल, तर तुम्ही सर्वात आधी कशाची खात्री कराल?\",\"options\":[\"रस्त्यांची सोय\",\"पाण्याची उपलब्धता\",\"मोठी दुकाने\",\"बागेची सोय\"],\"answer\":1,\"explain\":\"महाराजांच्या मते कोणतीही उभारणी करण्यापूर्वी पाण्याची सोय पाहणे सर्वात महत्त्वाचे आहे.\",\"topic\":\"ऐतिहासिक जलसोयी\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जलाशयांच्या बाबतीत छत्रपती शिवाजी महाराजांनी कोणती महत्त्वाची सूचना दिली होती?\",\"options\":[\"पाणी फक्त शेतीसाठी वापरावे\",\"जलाशयांची स्वच्छता राखावी\",\"तलावात पोहण्यास परवानगी द्यावी\",\"पाणी साठवू नये\"],\"answer\":1,\"explain\":\"जलाशयांची स्वच्छता राखणे आणि पाणी जपून वापरणे असे महाराजांनी सांगितले होते.\",\"topic\":\"ऐतिहासिक जलसोयी\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"पुण्यश्लोक अहिल्याबाई होळकर यांनी वाटसरूंसाठी (प्रवाशांसाठी) पाण्याची कोणती सोय केली?\",\"options\":[\"मोठे धरण बांधले\",\"पाणपोया उभारल्या\",\"नळ योजना आणली\",\"पाण्याचे हौद बांधले\"],\"answer\":1,\"explain\":\"पाठात उल्लेख आहे की त्यांनी पाणपोया उभारून वाटसरूंना पाण्याची सोय केली.\",\"topic\":\"ऐतिहासिक जलसोयी\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"इंदापूर येथी