r\":1,\"explain\":\"पॅराशूट हवेतून खाली उतरते, त्यामुळे जमिनीवरील अडथळ्यांचा त्यावर परिणाम होत नाही.\",\"topic\":\"वाहतुकीबद्दल रंजक माहिती\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात दाखवलेले साधन प्रामुख्याने कोणत्या परिस्थितीत वापरले जाते?\",\"options\":[\"दैनंदिन शाळेत जाण्यासाठी\",\"बाजारात भाजी आणण्यासाठी\",\"महापुरासारख्या आपत्कालीन परिस्थितीत संपर्क साधण्यासाठी\",\"लहान मुलांच्या खेळण्यासाठी\"],\"answer\":2,\"explain\":\"चित्रात पॅराशूट दाखवले आहे, ज्याचा वापर आपत्कालीन परिस्थितीत संपर्क साधण्यासाठी होतो.\",\"topic\":\"वाहतुकीबद्दल रंजक माहिती\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"10\\/070_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील साधनाचा वापर करून कोणत्या गोष्टी पोहोचवता येतात असे पाठ्यपुस्तकात म्हटले आहे?\",\"options\":[\"जीवनावश्यक वस्तू\",\"मोठ्या गाड्या\",\"लोखंडी खांब\",\"विटा आणि दगड\"],\"answer\":0,\"explain\":\"चित्रातील पॅराशूटच्या मदतीने जीवनावश्यक वस्तू पोहोचवता येतात असे मजकुरात दिले आहे.\",\"topic\":\"वाहतुकीबद्दल रंजक माहिती\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"10\\/070_101.jpg\"},{\"q\":\"माहितीची तसेच संदेशांची देवाणघेवाण करणे म्हणजे काय?\",\"options\":[\"प्रवास करणे\",\"संदेशवहन\",\"खेळ खेळणे\",\"जेवण करणे\"],\"answer\":1,\"explain\":\"उताऱ्यातील पहिल्या ओळीनुसार, माहितीची आणि संदेशांची देवाणघेवाण म्हणजे संदेशवहन होय.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"दुसऱ्या गावाला राहणाऱ्या मित्राला वाढदिवसाच्या शुभेच्छा देण्यासाठी खालीलपैकी कोणता मार्ग सर्वात जलद असू शकतो?\",\"options\":[\"त्याच्या घरी चालत जाणे\",\"पोस्टाने पत्र पाठवणे\",\"मोबाईल फोनवरून संदेश पाठवणे\",\"कबुतराच्या पायाला चिठ्ठी बांधणे\"],\"answer\":2,\"explain\":\"मोबाईल फोनवरून संदेश पाठवणे हा इतर पर्यायांच्या तुलनेत सर्वात जलद मार्ग आहे.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"पत्राद्वारे शुभेच्छा देण्यासाठी आपण कशाचा वापर करू शकतो?\",\"options\":[\"भेटकार्ड\",\"ई-मेल\",\"दूरध्वनी\",\"मोबाईल\"],\"answer\":0,\"explain\":\"उताऱ्यात पोस्टाने पत्र किंवा भेटकार्ड पाठवण्याचा पर्याय दिला आहे.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जुन्या काळी संदेश पाठवण्यासाठी कोणत्या पक्षाचा उल्लेख उताऱ्यात केला आहे?\",\"options\":[\"पोपट\",\"चिमणी\",\"कबूतर\",\"कावळा\"],\"answer\":2,\"explain\":\"उताऱ्यात कबुतराच्या पायाला चिठ्ठी बांधून संदेश पाठवण्याचा उल्लेख आहे.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"संगणकाचा वापर करून संदेश पाठवण्याच्या कोणत्या पद्धतीचा उल्लेख उताऱ्यात आहे?\",\"options\":[\"दूरध्वनी\",\"ई-मेल\",\"भेटकार्ड\",\"पत्र\"],\"answer\":1,\"explain\":\"ई-मेल हा संगणकाद्वारे संदेश पाठवण्याचा एक आधुनिक मार्ग आहे.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला तुमच्या मित्राशी थेट बोलून शुभेच्छा द्यायच्या असतील, तर तुम्ही कोणता पर्याय निवडाल?\",\"options\":[\"पत्र लिहिणे\",\"ई-मेल करणे\",\"दूरध्वनीवरून संपर्क साधणे\",\"कबूतर पाठवणे\"],\"answer\":2,\"explain\":\"दूरध्वनीवरून (फोनवरून) आपण थेट बोलून संपर्क साधू शकतो.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"संदेशवहन करताना आपण कशाची देवाणघेवाण करतो?\",\"options\":[\"फक्त वस्तूंची\",\"माहितीची आणि संदेशांची\",\"फक्त पैशांची\",\"फक्त अन्नाची\"],\"answer\":1,\"explain\":\"संदेशवहनाची व्याख्याच माहिती आणि संदेशांची देवाणघेवाण अशी आहे.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता संदेशवहनाचा मार्ग आजच्या काळात सर्वात कमी सोयीचा ठरेल?\",\"options\":[\"मोबाईल फोन\",\"ई-मेल\",\"कबुतराच्या पायाला चिठ्ठी बांधणे\",\"दूरध्वनी\"],\"answer\":2,\"explain\":\"कबुतराद्वारे संदेश पाठवणे ही जुनी पद्धत असून ती आता सोयीची राहिलेली नाही.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दूरध्वनी आणि मोबाईल फोन हे संदेशवहनाचे कोणते मार्ग आहेत?\",\"options\":[\"लेखन मार्ग\",\"मौखिक\\/संवाद मार्ग\",\"शारीरिक मार्ग\",\"प्राण्यांद्वारे संदेश\"],\"answer\":1,\"explain\":\"दूरध्वनी आणि मोबाईलवर आपण बोलून संदेश देतो, म्हणून ते संवादाचे मार्ग आहेत.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात दिलेल्या पर्यायांपैकी कोणते साधन संदेशवहनासाठी प्रत्यक्ष जाण्याची गरज कमी करते?\",\"options\":[\"लगेचच त्याच्या घरी जाणे\",\"मोबाईल फोन\",\"जेवण करणे\",\"खेळणे\"],\"answer\":1,\"explain\":\"मोबाईल फोनमुळे आपल्याला प्रत्यक्ष न जाता संदेश पोहोचवता येतो.\",\"topic\":\"संदेशवहन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"पूर्वीच्या काळी संदेश पाठवण्यासाठी कोणत्या पक्ष्याचा वापर केला जात असे?\",\"options\":[\"पोपट\",\"कबुतर\",\"कावळा\",\"चिमणी\"],\"answer\":1,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे, पूर्वीच्या काळी कबुतरांद्वारे संदेश पाठवले जात असत.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"कबुतरांकडून संदेशवहनाचे काम करून घेण्यासाठी त्यांना काय दिले जात असे?\",\"options\":[\"खाद्य\",\"बक्षीस\",\"प्रशिक्षण\",\"विश्रांती\"],\"answer\":2,\"explain\":\"संदेश पाठवण्यासाठी कबुतरे पाळून त्यांना प्रशिक्षण दिले जात असे.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"राजांचे दूत संदेश पोहोचवण्यासाठी कोणत्या प्राण्यांचा वापर करत असत?\",\"options\":[\"हत्ती आणि घोडा\",\"बैल आणि उंट\",\"घोडा आणि उंट\",\"गाढव आणि घोडा\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे, राजांचे दूत घोड्यावरून किंवा उंटावरून संदेशवहन करत असत.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पूर्वीच्या काळी दूतांचे संदेशवहनाचे काम कसे होते?\",\"options\":[\"सोपे आणि मजेशीर\",\"कष्टाचे आणि जोखमीचे\",\"वेगाने होणारे\",\"विनासायास होणारे\"],\"answer\":1,\"explain\":\"दूतांचे संदेशवहनाचे काम कष्टाचे आणि जोखमीचे असे, असे मजकुरात म्हटले आहे.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"पोस्टाद्वारे आपण कोठे पत्रे आणि वस्तू पाठवू शकतो?\",\"options\":[\"फक्त स्वतःच्या गावात\",\"फक्त शेजारच्या शहरात\",\"देशभरात आणि परदेशात\",\"फक्त राज्यापुरते\"],\"answer\":2,\"explain\":\"पोस्टातून आपण देशभरात आणि परदेशातही पत्र, वस्तू पाठवू शकतो.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"महत्त्वाची पत्रे लवकरात लवकर पोहोचवण्यासाठी कोणती सुविधा वापरली जाते?\",\"options\":[\"साधे पोस्ट\",\"स्पीड पोस्ट\",\"कबुतर पोस्ट\",\"दूत सेवा\"],\"answer\":1,\"explain\":\"महत्त्वाची पत्रे लवकर पोहोचवण्यासाठी \'स्पीड पोस्ट\' सुविधेचा वापर केला जातो.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"परदेशात वस्तू पाठवण्यासाठी खालीलपैकी कोणत्या वाहनाचा उपयोग केला जातो?\",\"options\":[\"सायकल\",\"बैलगाडी\",\"रिक्षा\",\"विमान\"],\"answer\":3,\"explain\":\"वस्तू पाठवण्यासाठी बस, आगगाडी, जहाज आणि विमान इत्यादी वाहनांचा उपयोग केला जातो.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला तुमच्या मित्राला दुसऱ्या देशात भेटवस्तू पाठवायची असेल, तर तुम्ही कोठे जाल?\",\"options\":[\"शाळेत\",\"पोस्ट ऑफिसमध्ये\",\"बागेत\",\"दवाखान्यात\"],\"answer\":1,\"explain\":\"वस्तू आणि पत्रे देशभरात किंवा परदेशात पाठवण्यासाठी पोस्टाचा वापर होतो.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"मजकुरात दिलेल्या माहितीनुसार, संदेशवहनाच्या इतिहासातील सर्वात जुनी पद्धत कोणती?\",\"options\":[\"स्पीड पोस्ट\",\"आगगाडीने वस्तू पाठवणे\",\"कबुतरांद्वारे संदेश पाठवणे\",\"विमानाने पत्र पाठवणे\"],\"answer\":2,\"explain\":\"मजकुराची सुरुवात \'पूर्वीच्या काळी कबुतरांद्वारे संदेश पाठवले जात\' अशी होते, जी सर्वात जुनी पद्धत दर्शवते.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"दूतांद्वारे होणाऱ्या संदेशवहनापेक्षा पोस्ट सेवा कशी वेगळी आहे?\",\"options\":[\"पोस्ट सेवा फक्त घोड्यावरून चालते\",\"पोस्टातून परदेशातही वस्तू पाठवता येतात\",\"पोस्टाचे काम जास्त जोखमीचे असते\",\"पोस्टात फक्त कबुतरे असतात\"],\"answer\":1,\"explain\":\"दूतांचे काम कष्टाचे होते, तर पोस्टाद्वारे आपण आधुनिक वाहनांच्या मदतीने देश-परदेशात वस्तू पाठवू शकतो.\",\"topic\":\"संदेशवहनाचा इतिहास\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"भारतातील पहिले पोस्ट ऑफिस कोणत्या साली सुरू झाले?\",\"options\":[\"१९३२\",\"१७७४\",\"१९४७\",\"१८५०\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, भारतातील पहिले पोस्ट ऑफिस १७७४ साली सुरू झाले.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"भारतातील पहिले पोस्ट ऑफिस कोठे सुरू झाले?\",\"options\":[\"मुंबई\",\"पुणे\",\"दिल्ली\",\"कोलकाता\"],\"answer\":3,\"explain\":\"भारतातील पहिले पोस्ट ऑफिस कोलकाता येथे सुरू झाले असे पाठात नमूद केले आहे.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"टेलिफोनचे अत्याधुनिक रूप खालीलपैकी कोणते आहे?\",\"options\":[\"रेडिओ\",\"टी.व्ही.\",\"मोबाईल फोन\",\"वृत्तपत्र\"],\"answer\":2,\"explain\":\"टेलिफोनचे अत्याधुनिक रूप म्हणजे \'मोबाईल फोन\' होय.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"टाटा एअरलाईन्स या विमान वाहतूक कंपनीची स्थापना कोणत्या शहरात झाली?\",\"options\":[\"कोलकाता\",\"मुंबई\",\"नागपूर\",\"चेन्नई\"],\"answer\":1,\"explain\":\"टाटा एअरलाईन्स ही कंपनी मुंबईत १९३२ साली स्थापन झाली.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"जगभरात संदेशवहनासाठी कशाचा उपयोग केला जातो?\",\"options\":[\"विमानांचा\",\"उपग्रहांचा\",\"गाड्यांचा\",\"पत्रांचा\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, जगभरात संदेशवहनासाठी उपग्रहांचा उपयोग केला जातो.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"पोस्टाच्या तिकिटांवर कोणाची चित्रे छापलेली असतात?\",\"options\":[\"केवळ फुलांची\",\"केवळ प्राण्यांची\",\"महत्त्वाच्या घटनांची आणि व्यक्तींची\",\"केवळ वाहनांची\"],\"answer\":2,\"explain\":\"पोस्टाच्या तिकिटांवर महत्त्वाच्या घटनांची आणि व्यक्तींची चित्रे छापलेली असतात.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"बिरसा मुंडा हे कोण होते?\",\"options\":[\"थोर क्रांतिकारक\",\"विमानचालक\",\"टपाल अधिकारी\",\"शास्त्रज्ञ\"],\"answer\":0,\"explain\":\"पाठात दिलेल्या माहितीनुसार बिरसा मुंडा हे थोर क्रांतिकारक होते.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"टेलिफोनच्या शोधामुळे कोणती महत्त्वाची गोष्ट साध्य झाली?\",\"options\":[\"माणसे वेगाने धावू लागली\",\"दूरवर असणाऱ्या व्यक्तींना सहज संवाद करता येऊ लागला\",\"विमानांचा वेग वाढला\",\"पोस्ट ऑफिस बंद झाले\"],\"answer\":1,\"explain\":\"टेलिफोनमुळे दूरवरच्या व्यक्तींशी सहज संवाद साधणे शक्य झाले आणि जग जवळ आले.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते साधन संदेशवहन आणि माहिती प्रसारणाचे साधन म्हणून पाठात आले आहे?\",\"options\":[\"बैलगाडी\",\"सायकल\",\"ड्रोन\",\"टांगा\"],\"answer\":2,\"explain\":\"पाठात रेडिओ, टी.व्ही., मासिके आणि ड्रोन ही संदेशवहनाची साधने असल्याचे सांगितले आहे.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"टाटा एअरलाईन्सची स्थापना कोणत्या वर्षी झाली?\",\"options\":[\"१७७४\",\"१९३२\",\"२०००\",\"१८३२\"],\"answer\":1,\"explain\":\"भारतातील पहिली नागरी विमान वाहतूक कंपनी १९३२ साली स्थापन झाली.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला जुन्या काळातील महत्त्वाच्या व्यक्तींची माहिती मिळवायची असेल, तर तुम्ही कशाचा संग्रह कराल?\",\"options\":[\"मोबाईल फोनचा\",\"विमानांच्या तिकिटांचा\",\"पोस्टाच्या तिकिटांचा\",\"वर्तमानपत्रांच्या रद्दीचा\"],\"answer\":2,\"explain\":\"पोस्टाची तिकिटे आपल्याला महत्त्वाच्या व्यक्तींची आणि घटनांची माहिती देतात.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"टेलिफोनच्या शोधामुळे \'जग जवळ आले\' असे का म्हटले जाते?\",\"options\":[\"कारण पृथ्वीचा आकार लहान झाला\",\"कारण रस्ते जवळ आले\",\"कारण दूरच्या व्यक्तींशी सहज संवाद साधता येऊ लागला\",\"कारण विमानाचा शोध लागला\"],\"answer\":2,\"explain\":\"संवाद सहज झाल्यामुळे अंतर कमी भासू लागले, म्हणून जग जवळ आले असे म्हणतात.\",\"topic\":\"आधुनिक संदेशवहनाची साधने\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21379,10,3,'EVS','mr','ऐतिहासिक वास्तू','[\"ऐतिहासिक वास्तू म्हणजे जुनी इमारतें, किल्ले, मंदिरे, वाडे इत्यादी ज्या आपल्या वारसाची ओळख करतात.\",\"लेणी म्हणजे पाण्याचे संग्रह करण्यासाठी बनवलेली गुफा, ज्यात प्राचीन चित्रे व लेखक शिल्पकला दिसते.\",\"जलदुर्ग म्हणजे समुद्रातील टापूवर बनेला किल्ला, जसे सिंधुदुर्ग.\",\"सिंधुदुर्ग किल्ला कोकणातील समुद्रातील टापूवर आहे आणि शिवाजी महाराजांनी बनवला होता.\",\"शिवनेरी किल्ला पुणे जिल्ह्यात आहे व छत्रपती शिवाजी महाराजांचा जन्मस्थान आहे.\",\"शिवनेरी किल्ल्यावर लेणी, पाणपोयी, शिवाई देवीचे मंदिर, टटबंदी, बुरूज इत्यादी पाहता येतात.\",\"रायगड किल्ला छत्रपती शिवाजी महाराजांचा राज्याभिषेक स्थळ होते आणि त्याची राजधानी होती.\",\"रामटेक मंदिर नागपूर जिल्ह्यात आहे व प्रभू श्रीरामाला समर्पित आहे.\",\"महात्मा फुले वाडा पुण्यात आहे व तिथे सर्व जाती-धर्मांसाठी पाणी उपलब्ध करवला जातो.\",\"डॉ. बाबासाहेब आंबेडकर संग्रहालय पुणे येथे आहे व त्यात भारतीयराज्यratna पदक ठेवलेला आहे.\",\"सावित्रीबाई फुले यांच्या नावाने पुणे विद्यापीठ असतो, जे आज सावित्रीबाई फुले पुणे विद्यापीठ कहातात.\",\"पाठ्यपुस्तक निर्मिती केंद्र बालभारती आहे, जे महाराष्ट्र शासनाच्या पाठ्यपुस्तके तयार करतो.\",\"ऐतिहासिक ठिकाणी भेट देण्यावर कचरा टाकणे, प्लास्टिक फेकणे, नाव लिहणे वर्जित आहे.\",\"वारसा सहल म्हणजे जुन्या वास्तूंचे संरक्षण व त्याबद्दल माहिती condivीणे.\",\"जागतिक वारसास्थळ यादीत UNESCO द्वारा महत्त्वाची सांस्कृतिक व naturelles ठिकाणी समाविष्ट केली जातात.\"]','[{\"q\":\"शाळेचे नाव काय आहे?\",\"options\":[\"जीवन शिक्षण विद्या मंदिर\",\"ज्ञान प्रकाश शाळा\",\"सरस्वती विद्यालय\",\"आदर्श प्राथमिक शाळा\"],\"answer\":0,\"explain\":\"पाठाच्या सुरुवातीलाच \'जीवन शिक्षण विद्या मंदिर\' शाळेचा उल्लेख आला आहे.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"शाळेत कितवे सत्र सुरू झाले होते?\",\"options\":[\"पहिले सत्र\",\"द्वितीय सत्र\",\"तृतीय सत्र\",\"अंतिम सत्र\"],\"answer\":1,\"explain\":\"पाठात स्पष्टपणे दिले आहे की शाळेत द्वितीय सत्र सुरू झाले.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"बाईंनी ऐतिहासिक वास्तूंचे फोटो कशावर पाठवायला सांगितले?\",\"options\":[\"पत्राद्वारे\",\"ईमेलवर\",\"मोबाईलवर\",\"वहीमध्ये\"],\"answer\":2,\"explain\":\"बाईंनी मुलांना ऐतिहासिक वास्तूंचे फोटो मोबाईलवर पाठवण्यास सांगितले.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"पुढील आठवड्यात बाईंनी कशाचे आयोजन करण्याचे ठरवले होते?\",\"options\":[\"क्रीडा स्पर्धा\",\"सहलीचे\",\"ऐतिहासिक वास्तूंच्या फोटोंचे प्रदर्शन\",\"गाण्याच्या कार्यक्रमाचे\"],\"answer\":2,\"explain\":\"बाईंनी ऐतिहासिक वास्तूंच्या फोटोंचे प्रदर्शन भरवण्याचे ठरवले होते.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती एक ऐतिहासिक वास्तू आहे?\",\"options\":[\"नवे बस स्थानक\",\"किल्ला\",\"शाळेची नवीन इमारत\",\"भाजी मंडई\"],\"answer\":1,\"explain\":\"पाठात ऐतिहासिक वास्तूंच्या उदाहरणांमध्ये \'किल्ले\' यांचा समावेश आहे.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"बाईंनी फळ्यावर काय चिकटवले होते?\",\"options\":[\"अभ्यासाचे वेळापत्रक\",\"मुलांनी पाठवलेले वास्तूंचे फोटो\",\"रंगीत चित्रे\",\"सुट्टीचा गृहपाठ\"],\"answer\":1,\"explain\":\"बाईंनी मोठ्या कागदांवर मुलांनी सुट्टीत बघितलेल्या वास्तूंचे फोटो चिकटवले होते.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"बाईंनी मुलांना डोळे बंद करायला का सांगितले असावे?\",\"options\":[\"मुलांना झोपवण्यासाठी\",\"मुलांना आश्चर्य (सरप्राईज) देण्यासाठी\",\"मुले दंगा करत होती म्हणून\",\"प्रार्थना करण्यासाठी\"],\"answer\":1,\"explain\":\"फळ्यावर फोटो लावून मुलांना आश्चर्याचा धक्का देण्यासाठी बाईंनी डोळे बंद करायला सांगितले.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"ऐतिहासिक वास्तूंच्या यादीत खालीलपैकी कशाचा समावेश होतो?\",\"options\":[\"वस्तुसंग्रहालये\",\"मोठी दुकाने\",\"चित्रपटगृहे\",\"बागा\"],\"answer\":0,\"explain\":\"पाठात ऐतिहासिक वास्तूंमध्ये वस्तुसंग्रहालयांचा उल्लेख केला आहे.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला \'थोरांचे जन्मस्थान\' पाहायचे असेल, तर तुम्ही कोणत्या प्रकारच्या ठिकाणाला भेट द्याल?\",\"options\":[\"ऐतिहासिक वास्तूला\",\"आधुनिक कारखान्याला\",\"बागेला\",\"खेळाच्या मैदानाला\"],\"answer\":0,\"explain\":\"थोरांची जन्मस्थाने ही ऐतिहासिक वास्तूंचाच एक भाग आहेत.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"प्रदर्शनामुळे मुलांना कोणता मुख्य फायदा होईल असे वाटते?\",\"options\":[\"त्यांना नवीन खेळ खेळता येतील\",\"त्यांना वेगवेगळ्या ऐतिहासिक वास्तूंची माहिती मिळेल\",\"त्यांना सुट्टी मिळेल\",\"त्यांना बक्षीस मिळेल\"],\"answer\":1,\"explain\":\"प्रदर्शनामुळे आणि माहिती दिल्याने मुलांना विविध वास्तूंची ओळख होईल.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रात मुले काय करत आहेत?\",\"options\":[\"ती मैदानात खेळत आहेत\",\"ती शाळेच्या गणवेशात चालत आहेत\",\"ती नदीत पोहत आहेत\",\"ती झोपली आहेत\"],\"answer\":1,\"explain\":\"चित्रात मुले शाळेच्या गणवेशात आणि दप्तर घेऊन चालताना दिसत आहेत.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"10\\/073_101.jpg\"},{\"q\":\"दिलेल्या चित्रात डाव्या बाजूला कोणत्या प्रकारचे दृश्य दिसत आहे?\",\"options\":[\"मोठ्या इमारतींचे शहर\",\"झोपड्या, झाडे आणि नदी असलेले गाव\",\"बर्फाच्छादित डोंगर\",\"वाळवंट\"],\"answer\":1,\"explain\":\"चित्राच्या डाव्या बाजूला ग्रामीण भागातील घरे, झाडे आणि नदीचे दृश्य आहे.\",\"topic\":\"ऐतिहासिक वास्तूंची ओळख\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"10\\/073_101.jpg\"},{\"q\":\"छत्रपती शिवाजी महाराजांचे जन्मस्थान कोणता किल्ला आहे?\",\"options\":[\"रायगड किल्ला\",\"प्रतापगड किल्ला\",\"शिवनेरी किल्ला\",\"सिंहगड किल्ला\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे दिले आहे की शिवनेरी किल्ला हे छत्रपती शिवाजी महाराजांचे जन्मस्थान आहे.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"उमाकांत कोणासोबत शिवनेरी किल्ल्यावर गेली होती?\",\"options\":[\"शिक्षकांबरोबर\",\"आईवडिलांबरोबर\",\"मित्र-मैत्रिणींबरोबर\",\"भावाबरोबर\"],\"answer\":1,\"explain\":\"उमाकांतने सांगितले की ती आईवडिलांबरोबर शिवनेरी किल्ल्यावर गेली होती.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"उमाकांतला शिवनेरी किल्ल्यावर गोष्ट कोणी सांगितली?\",\"options\":[\"शिक्षकांनी\",\"गाइडने\",\"आईवडिलांनी\",\"मित्रांनी\"],\"answer\":2,\"explain\":\"शिवरायांचा जन्म ज्या किल्ल्यावर झाला, तेथे उमाकांतला तिच्या आईवडिलांनी गोष्ट सांगितली.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शिवनेरी किल्ल्यावर पाणी साठवण्यासाठी काय आहे, असे उमाकांतने सांगितले?\",\"options\":[\"नदी\",\"पाण्याचे हौद\",\"विहीर\",\"धरण\"],\"answer\":1,\"explain\":\"उमाकांतने शिवनेरीवर पाहिलेल्या गोष्टींमध्ये \'पाण्याचे हौद\' यांचा उल्लेख केला आहे.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"उमाकांतने शिवनेरीवर कोणत्या देवाचे मंदिर पाहिले?\",\"options\":[\"गणपतीचे मंदिर\",\"विष्णूचे मंदिर\",\"शिवाजी देवाचे मंदिर\",\"हनुमानाचे मंदिर\"],\"answer\":2,\"explain\":\"दिलेल्या मजकुरानुसार उमाकांतने शिवनेरीवर \'शिवाजी देवाचे मंदिर\' पाहिले.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"ऐतिहासिक स्थळांच्या सहलीच्या फोटोंचे काय तयार करण्यास सांगितले आहे?\",\"options\":[\"पुस्तक\",\"तक्ता\",\"नकाशा\",\"चित्र\"],\"answer\":1,\"explain\":\"मजकुराच्या सुरुवातीला ऐतिहासिक स्थळांच्या सहलीच्या फोटोंचा \'तक्ता\' तयार करण्यास सांगितले आहे.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला शिवनेरी किल्ल्याची तटबंदी पाहायची असेल, तर तुम्ही कोठे जाल?\",\"options\":[\"बागेत\",\"शिवनेरी किल्ल्यावर\",\"शाळेत\",\"बाजारात\"],\"answer\":1,\"explain\":\"तटबंदी ही किल्ल्याची वास्तू आहे आणि उमाकांतने ती शिवनेरीवर पाहिली आहे.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"किल्ल्याच्या संरक्षणासाठी बांधलेल्या भिंतीला काय म्हणतात, जे उमाकांतने पाहिले?\",\"options\":[\"तटबंदी\",\"लेणी\",\"हौद\",\"टोक\"],\"answer\":0,\"explain\":\"किल्ल्याच्या संरक्षणात्मक रचनेला \'तटबंदी\' म्हणतात, जी उमाकांतने शिवनेरीवर पाहिली.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती गोष्ट उमाकांतने शिवनेरीवर पाहिली नाही?\",\"options\":[\"बुरुज\",\"कडेलोट टोक\",\"लेणी\",\"विमानतळ\"],\"answer\":3,\"explain\":\"उमाकांतने बुरुज, कडेलोट टोक आणि लेणी पाहिली, पण विमानतळाचा उल्लेख मजकुरात नाही.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"उमाकांतने शिवनेरीवर पाहिलेल्या गोष्टींपैकी \'कडेलोट\' हे काय आहे?\",\"options\":[\"एक मंदिर\",\"एक टोक\",\"एक पाण्याचा हौद\",\"एक लेणी\"],\"answer\":1,\"explain\":\"मजकुरात \'कडेलोट टोक\' असा उल्लेख आला आहे, म्हणजेच ते एक टोक आहे.\",\"topic\":\"शिवनेरी किल्ला\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"रामटेक हे शहर महाराष्ट्रातील कोणत्या जिल्ह्यात आहे?\",\"options\":[\"पुणे\",\"नागपूर\",\"नाशिक\",\"अमरावती\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की रामटेक हे नागपूर जिल्ह्यातील एक शहर आहे.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'मेघदूत\' हे प्रसिद्ध महाकाव्य कोणी रचले?\",\"options\":[\"संत तुकाराम\",\"महाकवी कालिदास\",\"संत ज्ञानेश्वर\",\"समर्थ रामदास\"],\"answer\":1,\"explain\":\"रामटेक येथे महाकवी कालिदासांनी मेघदूत हे महाकाव्य रचले असे पाठ सांगतो.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नंदीवर्धन (नगरधन) हा कोणत्या प्रकारचा किल्ला आहे?\",\"options\":[\"जलदुर्ग\",\"डोंगरी किल्ला\",\"भुईकोट किल्ला\",\"गिरीदुर्ग\"],\"answer\":2,\"explain\":\"उताऱ्यात नंदीवर्धन किल्ल्याचा उल्लेख \'भुईकोट किल्ला\' असा केला आहे.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"रामटेक येथील श्रीराम मंदिरात कोणत्या दिवशी जत्रा भरते?\",\"options\":[\"दिवाळीला\",\"दसऱ्याला\",\"रामनवमीला\",\"होळीला\"],\"answer\":2,\"explain\":\"उताऱ्यात दिले आहे की रामटेकला रामनवमीला जत्रा भरते.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला महाकवी कालिदासांच्या \'मेघदूत\' काव्याच्या निर्मितीचे ठिकाण पाहायचे असेल, तर तुम्ही कोठे जाल?\",\"options\":[\"नागपूर शहर\",\"रामटेक\",\"मुंबई\",\"पुणे\"],\"answer\":1,\"explain\":\"मेघदूत हे महाकाव्य रामटेक येथे रचले गेले, म्हणून तिथे जावे लागेल.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या माहितीनुसार, नंदीवर्धन किल्ला आणि रामटेक यांच्यातील भौगोलिक संबंध काय आहे?\",\"options\":[\"ते एकमेकांपासून खूप लांब आहेत\",\"नंदीवर्धन किल्ला रामटेक जवळ आहे\",\"ते दोन्ही एकाच डोंगरावर आहेत\",\"नंदीवर्धन हे रामटेकचे दुसरे नाव आहे\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की रामटेक जवळ नंदीवर्धन (नगरधन) हा भुईकोट किल्ला आहे.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात कोणता ऐतिहासिक भुईकोट किल्ला दिसत आहे?\",\"options\":[\"रायगड किल्ला\",\"नंदीवर्धन (नगरधन) किल्ला\",\"जंजिरा किल्ला\",\"प्रतापगड किल्ला\"],\"answer\":1,\"explain\":\"चित्राखालील मजकुरावरून स्पष्ट होते की हा नंदीवर्धन (नगरधन) भुईकोट किल्ला आहे.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"10\\/074_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील मंदिर रामटेक येथील कोणत्या देवाचे आहे?\",\"options\":[\"श्री विठ्ठल मंदिर\",\"श्रीराम मंदिर\",\"श्री गणेश मंदिर\",\"शिव मंदिर\"],\"answer\":1,\"explain\":\"चित्राखालील शीर्षकावरून हे रामटेक येथील श्रीराम मंदिर असल्याचे समजते.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"10\\/074_102.jpg\"},{\"q\":\"नंदू विदर्भाच्या सहलीला गेला होता, तर त्याने खालीलपैकी कोणत्या वास्तूला भेट दिली असण्याची शक्यता आहे?\",\"options\":[\"शनिवारवाडा\",\"अजिंठा लेणी\",\"रामटेकचे श्रीराम मंदिर\",\"गेटवे ऑफ इंडिया\"],\"answer\":2,\"explain\":\"नंदू विदर्भात रामटेकला गेला होता, जिथे श्रीराम मंदिर आहे.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यातील माहितीच्या आधारे, रामटेक हे ठिकाण कशासाठी प्रसिद्ध नाही असे म्हणता येईल?\",\"options\":[\"श्रीराम मंदिर\",\"रामनवमीची जत्रा\",\"मेघदूत महाकाव्य\",\"समुद्रकिनारा\"],\"answer\":3,\"explain\":\"उताऱ्यात मंदिर, जत्रा आणि मेघदूत यांचा उल्लेख आहे, पण समुद्रकिनाऱ्याचा उल्लेख नाही.\",\"topic\":\"रामटेक आणि नंदीवर्धन किल्ला\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"पुण्यात कोणाचे ऐतिहासिक घर आहे?\",\"options\":[\"लोकमान्य टिळक\",\"महात्मा फुले आणि सावित्रीबाई फुले\",\"छत्रपती शिवाजी महाराज\",\"न्यायमूर्ती रानडे\"],\"answer\":1,\"explain\":\"उताऱ्यात गार्गी सांगते की तिने पुण्यात महात्मा फुले आणि सावित्