ons\":[\"कामे कठीण होतात\",\"अशक्य गोष्टी सहज व लवकर होतात\",\"वेळ जास्त लागतो\",\"काहीच फरक पडत नाही\"],\"answer\":1,\"explain\":\"एकजुटीने राहिल्यास अनेक अशक्य असणाऱ्या गोष्टी आपण सहज व लवकर करू शकतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"कोणत्या सालातील जागतिक स्तरावरील महिला क्रिकेट विश्वचषकाच्या स्पर्धांमध्ये भारतीय संघांनी चमकदार कामगिरी केली?\",\"options\":[\"२०१०\",\"२०१२\",\"२०१५\",\"२०२०\"],\"answer\":2,\"explain\":\"२०१५ मधील जागतिक स्तरावरील महिला क्रिकेट विश्वचषकाच्या स्पर्धांमध्ये या संघांनी विजेतेपद पटकावले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"दृष्टिहीन महिलांची क्रिकेटमधील कामगिरी कौतुकास्पद का आहे?\",\"options\":[\"कारण त्या फक्त खेळतात\",\"कारण त्यांनी दृष्टी नसतानाही एकजुटीने यश मिळवले\",\"कारण त्या परदेशात गेल्या\",\"कारण त्यांना क्रिकेट आवडते\"],\"answer\":1,\"explain\":\"दृष्टिहीन असूनही जागतिक स्तरावर विजेतेपद मिळवणे ही मोठी आणि कौतुकास्पद बाब आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर वर्गातील मुलांना शाळेचे मैदान लवकर स्वच्छ करायचे असेल, तर त्यांनी काय करावे?\",\"options\":[\"प्रत्येकाने वेगळे काम करावे\",\"फक्त एकाच मुलाने काम करावे\",\"सर्वांनी एकजुटीने काम करावे\",\"काम उद्यावर ढकलावे\"],\"answer\":2,\"explain\":\"एकजुटीने काम केल्यास कोणतेही काम लवकर आणि सहज पूर्ण होते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात खेळाडू आनंदाने काय उंचावून धरत आहेत?\",\"options\":[\"बॅट\",\"चेंडू\",\"विश्वचषक (ट्रॉफी)\",\"ध्वज\"],\"answer\":2,\"explain\":\"चित्रात १९ वर्षांखालील महिला क्रिकेट संघ विश्वचषक (ट्रॉफी) उंचावून विजयाचा आनंद साजरा करत आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"remember\",\"figure_image\":\"10\\/097_101.jpg\"},{\"q\":\"दिलेल्या चित्रावरून संघाच्या भावनेबद्दल काय सांगता येईल?\",\"options\":[\"त्यांना खेळायला आवडत नाही\",\"त्या पराभूत झाल्या आहेत\",\"त्या विजयाचा आनंद साजरा करत आहेत\",\"त्या थकल्या आहेत\"],\"answer\":2,\"explain\":\"चित्रातील खेळाडूंचे चेहरे आणि त्यांनी उंचावलेला चषक त्यांच्या विजयाचा आनंद दर्शवतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"10\\/097_101.jpg\"},{\"q\":\"उताऱ्यात क्रिकेटला कोणत्या प्रकारचा खेळ म्हटले आहे?\",\"options\":[\"वैयक्तिक खेळ\",\"सांघिक खेळ\",\"बैठे खेळ\",\"साहसी खेळ\"],\"answer\":1,\"explain\":\"उताऱ्यात क्रिकेटचा उल्लेख \'सांघिक खेळ\' असा केला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यानुसार आपण आपल्या देशाची मान गौरवाने कशी उंचावू शकतो?\",\"options\":[\"एकजुटीने यश मिळवून\",\"फक्त स्वतःचा विचार करून\",\"खेळ न खेळता\",\"भांडण करून\"],\"answer\":0,\"explain\":\"सांघिक खेळात एकजुटीने यश मिळवून आपण देशाची मान गौरवाने उंचावू शकतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"या माहितीचा मुख्य संदेश काय आहे?\",\"options\":[\"फक्त क्रिकेट खेळावे\",\"एकजुटीचे महत्त्व\",\"फक्त २०१५ साल महत्त्वाचे आहे\",\"दृष्टिहीन लोकांनी खेळू नये\"],\"answer\":1,\"explain\":\"हा उतारा आपल्याला एकजुटीने राहण्याचे आणि काम करण्याचे महत्त्व सांगतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर कोणी अयोग्य रीतीने स्पर्श केल्यामुळे तुम्ही अस्वस्थ झाला असाल, तर तुम्ही काय केले पाहिजे?\",\"options\":[\"गप्प बसले पाहिजे\",\"अजिबात गप्प बसू नका\",\"स्वतःला दोष द्या\",\"कोणालाही सांगू नका\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे सांगितले आहे की अयोग्य स्पर्श झाल्यास अजिबात गप्प बसू नका.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"अयोग्य स्पर्श झाल्यास खालीलपैकी कोणती गोष्ट करणे चुकीचे आहे?\",\"options\":[\"विश्वासू व्यक्तीला सांगणे\",\"राष्ट्रीय आयोगाला कळवणे\",\"स्वतःला दोष देणे\",\"ई-बॉक्सचा वापर करणे\"],\"answer\":2,\"explain\":\"उताऱ्यात सांगितले आहे की अशा घटनेत स्वतःला दोष देऊ नका.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"हक्कांच्या संरक्षणासाठी स्थापन केलेल्या राष्ट्रीय आयोगाला कोणत्या माध्यमातून कळवता येते?\",\"options\":[\"पत्राद्वारे\",\"फोनद्वारे\",\"पोक्सो (POCSO) ई-बॉक्सद्वारे\",\"फॅक्सद्वारे\"],\"answer\":2,\"explain\":\"उताऱ्यात राष्ट्रीय आयोगाला कळवण्यासाठी पोक्सो ई-बॉक्सचा उल्लेख आहे.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"अयोग्य स्पर्शामुळे वाईट वाटणे किंवा गोंधळून जाणे यात तुमचा दोष का नाही?\",\"options\":[\"कारण ही एक सामान्य गोष्ट आहे\",\"कारण यात तुमचा काहीच दोष नसतो\",\"कारण तुम्ही लहान आहात\",\"कारण तुम्ही गप्प बसलात\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की \'यात तुमचा दोष नाही\', म्हणून वाईट वाटण्याचे कारण नाही.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"POCSO ई-बॉक्स कोणत्या वेबसाईटवर उपलब्ध आहे?\",\"options\":[\"ncper@gov.in\",\"school@gov.in\",\"child@gov.in\",\"safety@gov.in\"],\"answer\":0,\"explain\":\"उताऱ्यात दिलेल्या माहितीनुसार वेबसाईट ncper@gov.in ही आहे.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"एखाद्या व्यक्तीच्या स्पर्शामुळे तुम्हाला \'असह्य\' वाटत असेल, तर तुम्ही पहिली पायरी काय उचलली पाहिजे?\",\"options\":[\"ती जागा सोडून पळून जाणे\",\"घटनेबद्दल तुमच्या विश्वासू व्यक्तीला सांगणे\",\"रडत बसणे\",\"कोणाशीही न बोलणे\"],\"answer\":1,\"explain\":\"उताऱ्यात दिलेल्या मार्गदर्शनानुसार, ज्याच्यावर विश्वास आहे त्यांना घटनेबद्दल सांगावे.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"वेबसाईटवर तक्रार नोंदवण्यासाठी कोणते बटन दाबण्यास सांगितले आहे?\",\"options\":[\"स्टार्ट बटन\",\"सबमिट बटन\",\"ई (e) बटन\",\"मदत बटन\"],\"answer\":2,\"explain\":\"उताऱ्यात \'ई बटन दाबा\' असे स्पष्ट निर्देश दिले आहेत.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, अयोग्य स्पर्श झाल्यास मुलांच्या मनात कोणत्या भावना येऊ शकतात?\",\"options\":[\"आनंद आणि उत्साह\",\"गोंधळ आणि अस्वस्थता\",\"शांतता आणि समाधान\",\"काहीच वाटत नाही\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे अयोग्य स्पर्शामुळे मूल अस्वस्थ, गोंधळलेले किंवा वाईट वाटू शकते.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्या मित्राला कोणी अयोग्य स्पर्श केला असेल, तर तुम्ही त्याला कोणता सल्ला द्याल?\",\"options\":[\"ही गोष्ट गुपित ठेव\",\"स्वतःला दोष दे\",\"विश्वासू मोठ्या माणसाला सांग आणि ई-बॉक्स वापर\",\"काहीच करू नकोस\"],\"answer\":2,\"explain\":\"उताऱ्यातील माहितीनुसार विश्वासू व्यक्तीला सांगणे आणि ई-बॉक्स वापरणे हा योग्य सल्ला आहे.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"राष्ट्रीय आयोगाची स्थापना कशासाठी करण्यात आली आहे?\",\"options\":[\"खेळ खेळण्यासाठी\",\"हक्कांच्या संरक्षणासाठी\",\"अभ्यास करण्यासाठी\",\"जेवण देण्यासाठी\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की राष्ट्रीय आयोगाची स्थापना \'हक्कांच्या संरक्षणासाठी\' केली आहे.\",\"topic\":\"स्वतःची सुरक्षा (POCSO)\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"चाइल्ड लाइनचा संपर्क क्रमांक कोणता आहे?\",\"options\":[\"१००\",\"१०१\",\"१०९८\",\"१०९१\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, संकटात असलेल्या मुलांसाठी १०९८ (दहा नऊ आठ) हा संपर्क क्रमांक आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चाइल्ड लाइन ही सेवा किती वर्षांपेक्षा कमी वयाच्या मुलांसाठी आहे?\",\"options\":[\"१५ वर्षे\",\"१८ वर्षे\",\"२० वर्षे\",\"२१ वर्षे\"],\"answer\":1,\"explain\":\"जर तुमचे वय १८ वर्षांपेक्षा कमी असेल, तर तुम्ही या सेवेचा लाभ घेऊ शकता.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चाइल्ड लाइन ही सेवा दिवसातील किती तास उपलब्ध असते?\",\"options\":[\"८ तास\",\"१२ तास\",\"१८ तास\",\"२४ तास\"],\"answer\":3,\"explain\":\"चाइल्ड लाइन १०९८ ही एक २४ तास उपलब्ध असणारी राष्ट्रीय आपत्कालीन फोन सेवा आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, फोनवर बोलणाऱ्या मुलाच्या उजव्या बाजूला इंग्रजीत काय लिहिले आहे?\",\"options\":[\"HELP LINE\",\"CHILD LINE\",\"KIDS LINE\",\"SCHOOL LINE\"],\"answer\":1,\"explain\":\"दिलेल्या चित्रात स्पष्टपणे \'CHILD LINE\' असे लिहिले आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"remember\",\"figure_image\":\"10\\/099_102.jpg\"},{\"q\":\"चाइल्ड लाइन १०९८ ही कोणत्या प्रकारची फोन सेवा आहे?\",\"options\":[\"खाजगी सेवा\",\"सशुल्क सेवा\",\"राष्ट्रीय आपत्कालीन टोल फ्री सेवा\",\"फक्त मनोरंजनाची सेवा\"],\"answer\":2,\"explain\":\"ही एक २४ तास टोल फ्री राष्ट्रीय आपत्कालीन फोन सेवा आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्या ओळखीचे एखादे मूल खूप संकटात असेल, तर तुम्ही काय कराल?\",\"options\":[\"त्याकडे दुर्लक्ष करू\",\"१०९८ ला संपर्क साधू\",\"त्याला घरी पाठवू\",\"दुसऱ्या कोणाला तरी सांगायला सांगू\"],\"answer\":1,\"explain\":\"संकट सहन करणारे कोणी माहितीतील असेल, तर १०९८ ला संपर्क साधणे आवश्यक आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात खालील बाजूस \'NIGHT & DAY\' असे लिहिले आहे, त्याचा अर्थ काय होतो?\",\"options\":[\"ही सेवा फक्त रात्रीसाठी आहे\",\"ही सेवा फक्त दिवसासाठी आहे\",\"ही सेवा रात्र आणि दिवस अशा दोन्ही वेळी उपलब्ध आहे\",\"ही सेवा फक्त सुट्टीच्या दिवशी आहे\"],\"answer\":2,\"explain\":\"\'NIGHT & DAY\' म्हणजे ही सेवा २४ तास, रात्रंदिवस उपलब्ध आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"10\\/099_102.jpg\"},{\"q\":\"चाइल्ड लाइन हा उपक्रम कोणत्या मंत्रालयामार्फत राबवला जातो?\",\"options\":[\"शिक्षण मंत्रालय\",\"आरोग्य मंत्रालय\",\"महिला आणि बालविकास मंत्रालय\",\"गृह मंत्रालय\"],\"answer\":2,\"explain\":\"हा महिला आणि बालविकास मंत्रालयाचा पीडित मुलांसाठी राबवला जाणारा उपक्रम आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"१०९८ या क्रमांकावर फोन केल्यामुळे मुलांच्या जीवनावर काय परिणाम होऊ शकतो?\",\"options\":[\"काहीही बदल होत नाही\",\"मुलांना भीती वाटते\",\"आपले व मित्रांचे जीवन बदलू शकते\",\"फक्त वेळ वाया जातो\"],\"answer\":2,\"explain\":\"१०९८ ला संपर्क साधल्यामुळे आपले व मित्रांचे जीवन बदलू शकते असे पाठात म्हटले आहे.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या परिस्थितीत १०९८ ला फोन करणे योग्य ठरेल?\",\"options\":[\"जेव्हा कोणी त्रास देत असेल आणि तुम्ही संकटात असाल\",\"जेव्हा तुम्हाला गृहपाठ करायचा नसेल\",\"जेव्हा तुम्हाला खेळायला जायचे असेल\",\"जेव्हा तुम्हाला नवीन कपडे हवे असतील\"],\"answer\":0,\"explain\":\"त्रास होत असल्यास, पीडित असल्यास किंवा संकटात असल्यास या क्रमांकावर फोन करावा.\",\"topic\":\"चाइल्ड लाइन १०९८\",\"part\":8,\"bloom\":\"apply\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21384,11,3,'English','en','We are Happy Everyday','[\"- We are Happy Everyday is a poem about joy and friendship.\",\"- The poem talks about singing, dancing, and playing together.\",\"- It encourages us to clap our hands, tap our feet, and jump with happiness.\",\"- The poem mentions that we should stand up, raise our hands, and shake our waist.\",\"- We should also sit, fold our hands, and touch our feet.\",\"- The poem has rhyming words like sun, fun, one, run, play, day, stay, say.\",\"- Opposite words of happy, laughing, sweet, start, stand are unhappy, crying, bitter, end, sit.\",\"- The poem shows that learning and laughing make us happy everyday.\",\"- The activities in the lesson include the Onion Ring activity and the Captain Says game.\",\"- The Onion Ring activity helps us practice listening and speaking in circles.\",\"- The Captain Says game is a fun way to follow commands and move around.\",\"- The poem uses simple words suitable for Standard 3 students.\",\"- The poem is written in a rhythmic and repetitive style to aid memory.\",\"- The poem teaches values of sharing, teamwork, and positivity.\",\"- The poem ends with a message that we are happy everyday when we learn and play together.\"]','[{\"q\":\"According to the poem, what should you do with your hands?\",\"options\":[\"Clap your hands\",\"Wash your hands\",\"Wave your hands\",\"Fold your hands\"],\"answer\":0,\"explain\":\"The poem explicitly says \'Clap your hands\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"In the Onion Ring activity, how should the learners in the circles stand?\",\"options\":[\"Facing away from each other\",\"Facing each other\",\"Sitting on the floor\",\"Standing in a straight line\"],\"answer\":1,\"explain\":\"The instructions state: \'Let learners stand in the circles facing each other.\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What do the children do while they play?\",\"options\":[\"Eat and drink\",\"Sleep and rest\",\"Learning and laughing\",\"Fighting and crying\"],\"answer\":2,\"explain\":\"The poem says, \'Learning, laughing while we play.\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"How often does the poem say we are happy?\",\"options\":[\"Only on holidays\",\"Everyday\",\"Only at school\",\"Once a week\"],\"answer\":1,\"explain\":\"The first line of the poem is \'We are happy everyday\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"What kind of thoughts do the children bring to school?\",\"options\":[\"Sad thoughts\",\"Angry thoughts\",\"Happy thoughts\",\"Scary thoughts\"],\"answer\":2,\"explain\":\"The poem mentions, \'Happy thoughts are what we bring.\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"How does the poem describe every friend we meet?\",\"options\":[\"They are tall\",\"They are sweet\",\"They are funny\",\"They are quiet\"],\"answer\":1,\"explain\":\"The poem states, \'Every friend we meet is sweet.\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"If you are following the poem\'s actions, what do you do with your feet?\",\"options\":[\"Stomp your feet\",\"Kick your feet\",\"Tap your feet\",\"Hide your feet\"],\"answer\":2,\"explain\":\"The poem says, \'tap your feet\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Which of these pairs of items are mentioned as things children have in the poem?\",\"options\":[\"Bags and bottles\",\"Books and pencils\",\"Toys and games\",\"Chalk and slate\"],\"answer\":1,\"explain\":\"The poem mentions \'Books and pencils\' in the second stanza.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"In the Onion Ring activity, which circle moves one step forward after introducing themselves?\",\"options\":[\"The inner circle\",\"Both circles\",\"The outer circle\",\"Neither circle\"],\"answer\":2,\"explain\":\"The text says, \'Then the outer circle moves one step forward.\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What does the phrase \'Together strong, we always stand\' suggest about the children?\",\"options\":[\"They are tired of standing\",\"They are united and help each other\",\"They are standing in a circle\",\"They are very tall\"],\"answer\":1,\"explain\":\"The context of helping others hand in hand shows they are united.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"The poem compares the children\'s brightness to which object?\",\"options\":[\"A shining star\",\"A glowing lamp\",\"The Sun\",\"The Moon\"],\"answer\":2,\"explain\":\"The poem says, \'Shining bright just like the Sun\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"What action in the poem shows that the children support one another?\",\"options\":[\"Running and jumping\",\"Helping others hand in hand\",\"Clapping hands\",\"Tapping feet\"],\"answer\":1,\"explain\":\"The poem says \'Helping others hand in hand\' to show support.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What is the very first instruction given by the Captain before the numbered list?\",\"options\":[\"Stand up\",\"Stretch your arms\",\"Raise your hands\",\"Shake it fast\"],\"answer\":1,\"explain\":\"The text begins with the instruction \'Stretch your arms\' before starting the numbered list.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"According to command number 9, what should you touch?\",\"options\":[\"Your head\",\"Your knees\",\"Your waist\",\"Your feet\"],\"answer\":3,\"explain\":\"Command number 9 in the text is \'Touch your feet.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What are the two different speeds mentioned for shaking in the exercise?\",\"options\":[\"High and low\",\"Fast and slow\",\"Left and right\",\"Up and down\"],\"answer\":1,\"explain\":\"Commands 3 and 4 specify \'Shake it fast\' and \'Shake it slow.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If the Captain says command number 5, where should you place your hands?\",\"options\":[\"On your head\",\"On your waist\",\"On your feet\",\"In the air\"],\"answer\":1,\"explain\":\"Command number 5 is \'Hands on waist.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which two numbered commands involve the \'waist\'?\",\"options\":[\"1 and 2\",\"3 and 4\",\"5 and 6\",\"7 and 8\"],\"answer\":2,\"explain\":\"Command 5 is \'Hands on waist\' and command 6 is \'Shake your waist.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"What is command number 7 in the list?\",\"options\":[\"Hands up\",\"Stand up\",\"Fold your hands\",\"Shake it fast\"],\"answer\":2,\"explain\":\"The text lists command 7 as \'Fold your hands.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which command is the opposite of \'sitting down\'?\",\"options\":[\"Stand up\",\"Hands up\",\"Shake it slow\",\"Touch your feet\"],\"answer\":0,\"explain\":\"Command 1 is \'Stand up\', which is the opposite action of sitting.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"When following command number 2, what action are you performing with your hands?\",\"options\":[\"Folding them\",\"Shaking them\",\"Raising them\",\"Touching feet\"],\"answer\":2,\"explain\":\"Command 2 is \'Raise your hands.\'\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Based on the text, which body part is mentioned most frequently in the commands?\",\"options\":[\"Feet\",\"Waist\",\"Hands\",\"Arms\"],\"answer\":2,\"explain\":\"The word \'hands\' appears in commands 2, 5, 7, and 8, making it the most mentioned body part.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"How many times does the word \'Shake\' appear in the numbered list of commands?\",\"options\":[\"One\",\"Two\",\"Three\",\"Four\"],\"answer\":2,\"explain\":\"The word \'Shake\' appears in commands 3, 4, and 6.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21385,11,3,'English','en','Word Family - I','[\"- A word family is a group of words that share the same root or base word.\",\"- The base word is the part that stays the same in all words of the family.\",\"- Adding a prefix (e.g., re-) or suffix (e.g., -ing) changes the word but keeps the root.\",\"- In this chapter we look at short words that share the same ending sound, like ‘at’, ‘an’, ‘ad’.\",\"- The sound ‘at’ can be heard in cat, bat, sat, fat, pat, hat, etc.\",\"- The sound ‘an’ can be heard in can, fan, man, van, pan, tan, etc.\",\"- The sound ‘ad’ can be heard in dad, mad, pad, sad, bad, lad, etc.\",\"- Children can practice by reading the words aloud and listening for the common sound.\",\"- Circle the words that have the same sound in a list of words.\",\"- Writing the words in a notebook helps remember the family.\",\"- Using a dictionary helps find new words that belong to the same family.\",\"- Phonemes are the smallest sounds that change meaning of a word.\",\"- A syllable is a part of a word that has one vowel sound.\",\"- Identifying phonemes and syllables helps with spelling and pronunciation.\",\"- Repeating words with the same ending sound builds confidence in reading.\",\"- Practice makes the sound patterns easier to spot in new words.\"]','[{\"q\":\"Which of these words is listed in section \'c\' of the textbook?\",\"options\":[\"dog\",\"bag\",\"pig\",\"sun\"],\"answer\":1,\"explain\":\"The word \'bag\' is explicitly listed in the textbook under section \'c\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word from the list ends with the letters \'ax\'?\",\"options\":[\"wax\",\"van\",\"tap\",\"gas\"],\"answer\":0,\"explain\":\"The word \'wax\' is found in the last row of the list in section \'c\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"In the list provided, which word ends with the letters \'ad\'?\",\"options\":[\"am\",\"an\",\"sad\",\"at\"],\"answer\":2,\"explain\":\"The word \'sad\' belongs to the \'-ad\' word family in the list.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word from the list rhymes with \'map\'?\",\"options\":[\"cap\",\"gas\",\"jam\",\"ran\"],\"answer\":0,\"explain\":\"\'Cap\' and \'map\' share the same ending sound \'-ap\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If you are looking for a word that ends with \'at\' in the list, which one should you choose?\",\"options\":[\"rat\",\"ran\",\"rag\",\"rap\"],\"answer\":0,\"explain\":\"\'Rat\' is the word in the list that ends with \'at\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word from the list has the same ending sound as \'pan\'?\",\"options\":[\"ran\",\"pat\",\"gap\",\"tax\"],\"answer\":0,\"explain\":\"\'Ran\' and \'pan\' both belong to the \'-an\' word family.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Look at the group: \'cap\', \'tap\', \'gap\'. Which other word from the list belongs to this group?\",\"options\":[\"lap\",\"dad\",\"gas\",\"jam\"],\"answer\":0,\"explain\":\"\'Lap\' ends with \'-ap\', just like cap, tap, and gap.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which word in the list starts with the letter \'t\' and ends with \'ax\'?\",\"options\":[\"tax\",\"tap\",\"wax\",\"gas\"],\"answer\":0,\"explain\":\"The word \'tax\' is listed in the final row of section \'c\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which of these is a three-letter word ending in \'am\' found in the list?\",\"options\":[\"jam\",\"pan\",\"van\",\"ran\"],\"answer\":0,\"explain\":\"\'Jam\' is the word in the list that ends with \'am\'.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which word from the list rhymes with \'bad\'?\",\"options\":[\"dad\",\"bat\",\"bag\",\"ban\"],\"answer\":0,\"explain\":\"\'Dad\' and \'bad\' rhyme as they both end with the \'-ad\' sound.\",\"topic\":\"c. Read and copy in your notebook.\",\"part\":4,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21386,11,3,'English','en','The Picnic','[\"- A picnic is a fun outing where people bring food and play together.\",\"- The Cat Family (Daddy, Mummy, Didi and Baby Cat) went on a picnic.\",\"- They went to the garden, a riverside, a hill or by train or bus.\",\"- They carried cake, milk, a mat, a hat, a bat, a ball, fruits and books.\",\"- Baby Cat felt sad when his cake fell, but happy when others shared cake.\",\"- Everyone felt happy at the end of the picnic.\",\"- Words can be changed by adding prefixes like dis-, over-, re-, un-, pre- or suffixes like -ing, -ful, -ly, -less.\",\"- Simple sentences: \\\"I will take fruits for the picnic.\\\"\",\"- Questions in the story: “What shall we go to?” “Where shall we go?”\",\"- Remember to read, repeat and write the sentences to practice pronunciation.\"]','[{\"q\":\"On which day did the Cat Family decide to go for a picnic?\",\"options\":[\"Sunday\",\"Monday\",\"Saturday\",\"Friday\"],\"answer\":0,\"explain\":\"The text states, \'One fine Sunday, the Cat Family decided to go for a picnic.\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"According to the text, how many members are there in the Cat Family?\",\"options\":[\"Two\",\"Three\",\"Four\",\"Five\"],\"answer\":2,\"explain\":\"The text mentions Daddy Cat, Mummy Cat, Didi Cat, and Baby Cat, which makes four members.\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Why did the family finally decide to go to the garden?\",\"options\":[\"It is near the river\",\"It is very big\",\"It is so beautiful\",\"It has many trees\"],\"answer\":2,\"explain\":\"The text says they decided on the garden because \'It is so beautiful.\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what question is Daddy Cat asking the family?\",\"options\":[\"How shall we go?\",\"Where shall we go?\",\"What shall we eat?\",\"When shall we go?\"],\"answer\":1,\"explain\":\"In the picture, the speech bubble for Daddy Cat says, \'Where shall we go?\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"11\\/016_101.jpg\"},{\"q\":\"Which word in the text shows that the Cat Family was very happy and eager about the picnic?\",\"options\":[\"Decided\",\"Beautiful\",\"Excited\",\"Riverside\"],\"answer\":2,\"explain\":\"The text states the family members \'were excited,\' which means they were happy and eager.\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"In the given figure, why does Daddy Cat suggest that the family should walk?\",\"options\":[\"Because they do not have a car\",\"Because the garden is near their house\",\"Because they want to exercise\",\"Because the bus is too slow\"],\"answer\":1,\"explain\":\"In the picture, Daddy Cat says, \'The garden is near our house. Let\'s walk.\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"11\\/016_102.jpg\"},{\"q\":\"Who suggested that the family should go to the riverside?\",\"options\":[\"Daddy Cat\",\"Mummy Cat\",\"Didi Cat\",\"Baby Cat\"],\"answer\":1,\"explain\":\"In the first picture, the speech bubble from Mummy Cat says, \'Let\'s go to the riverside.\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Which of these places was NOT suggested as a picnic spot by the family?\",\"options\":[\"The hill\",\"The garden\",\"The riverside\",\"The beach\"],\"answer\":3,\"explain\":\"The text mentions the hill, riverside, and garden, but does not mention the beach.\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"Who suggested going to the picnic by a train?\",\"options\":[\"Baby Cat\",\"Didi Cat\",\"Mummy Cat\",\"Daddy Cat\"],\"answer\":0,\"explain\":\"In the second picture, the smallest cat (Baby Cat) says, \'Let\'s go by a train.\'\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the word \'decided\' mean in the context of the story?\",\"options\":[\"To forget a plan\",\"To make a choice after thinking\",\"To start crying\",\"To go to sleep\"],\"answer\":1,\"explain\":\"To decide means to make a choice, as the family chose where to go for their picnic.\",\"topic\":\"The Cat Family\'s Decision\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"How did the characters finally decide to go to the garden?\",\"options\":[\"By a train\",\"By a bus\",\"By walking\",\"By a car\"],\"answer\":2,\"explain\":\"The text states, \'So, they all decided to walk to the garden.\'\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What food and drink did they decide to take with them?\",\"options\":[\"Bread and water\",\"Cake and milk\",\"Fruit and juice\",\"Biscuits and tea\"],\"answer\":1,\"explain\":\"The text says, \'I shall take cake and milk.\'\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Why did they decide to walk instead of taking a bus or a train?\",\"options\":[\"They did not have money\",\"The bus was late\",\"The garden is near their house\",\"They wanted to run\"],\"answer\":2,\"explain\":\"The text explains, \'The garden is near our house. Let\'s walk.\'\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which of these rhyming pairs of items did they take to the picnic?\",\"options\":[\"Cake and Bake\",\"Mat and Hat\",\"Ball and Tall\",\"Milk and Silk\"],\"answer\":1,\"explain\":\"The text mentions, \'I shall take a mat and a hat.\'\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Based on the text, which items are needed for the game they played?\",\"options\":[\"A mat and a hat\",\"Cake and milk\",\"A bat and a ball\",\"A train and a bus\"],\"answer\":2,\"explain\":\"The text mentions taking a bat and a ball, and then says they played together.\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"If you want to sit on the grass during the picnic, which item from the text should you use?\",\"options\":[\"A hat\",\"A mat\",\"A bat\",\"A ball\"],\"answer\":1,\"explain\":\"A mat is typically used for sitting on the ground during a picnic.\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"In the given figure, what game are the characters playing in the garden?\",\"options\":[\"Football\",\"Hide and seek\",\"Cricket\",\"Tag\"],\"answer\":2,\"explain\":\"The figure shows characters with a bat, ball, and wickets, which are used in cricket.\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"11\\/017_101.jpg\"},{\"q\":\"In the given figure, how many characters are seen playing together?\",\"options\":[\"Two\",\"Three\",\"Four\",\"Five\"],\"answer\":2,\"explain\":\"There are four cat characters shown in the illustration.\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"11\\/017_101.jpg\"},{\"q\":\"What was the final result of their picnic trip?\",\"options\":[\"They got tired and went home\",\"They all had a lot of fun\",\"They lost their ball\",\"They missed the train\"],\"answer\":1,\"explain\":\"The text concludes by saying, \'They all had a lot of fun.\'\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"Which of these travel options was NOT suggested in the text?\",\"options\":[\"Train\",\"Bus\",\"Walking\",\"Cycling\"],\"answer\":3,\"explain\":\"The text mentions train, bus, and walking, but does not mention cycling.\",\"topic\":\"What shall we take?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Who gave everyone some cake at the picnic?\",\"options\":[\"Baby Cat\",\"Mummy Cat\",\"Daddy Cat\",\"The friends\"],\"answer\":1,\"explain\":\"The text states that Mummy Cat gave everyone some cake.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"What happened to Baby Cat\'s cake?\",\"options\":[\"It was eaten by a bird\",\"It fell down\",\"It was lost\",\"It was hidden\"],\"answer\":1,\"explain\":\"The text says, \'Oh no! Baby Cat\'s cake fell down.\'\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"Why did Baby Cat start crying?\",\"options\":[\"Because she was hungry\",\"Because she wanted to go home\",\"Because her cake fell down\",\"Because she was tired\"],\"answer\":2,\"explain\":\"Baby Cat started crying right after her cake fell down.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"What did the others do when Baby Cat\'s cake fell?\",\"options\":[\"They laughed at her\",\"They told her to be quiet\",\"They shared their cake with her\",\"They gave her their toys\"],\"answer\":2,\"explain\":\"The text shows multiple characters saying, \'I shall share my cake.\'\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"Why did Baby Cat get \'more cake\' in the end?\",\"options\":[\"She found her cake on the ground\",\"Mummy Cat had a spare box\",\"Several others shared their cake with her\",\"She took cake from the others\"],\"answer\":2,\"explain\":\"Because three different characters offered to share, she ended up with more cake.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"Which word from the \'Listen and repeat\' list means \'all the people\'?\",\"options\":[\"decided\",\"excited\",\"together\",\"everyone\"],\"answer\":3,\"explain\":\"The word \'everyone\' refers to all the people in a group.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"If the cats are sitting by the side of a river, which word from the list describes their location?\",\"options\":[\"decided\",\"riverside\",\"excited\",\"together\"],\"answer\":1,\"explain\":\"Riverside means the area along the side of a river.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"How did the picnic end for everyone?\",\"options\":[\"Everyone was sad\",\"Everyone was hungry\",\"Everyone was happy\",\"Everyone was tired\"],\"answer\":2,\"explain\":\"The text concludes by saying, \'Everyone was happy.\'\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"What does the story tell us about the characters at the picnic?\",\"options\":[\"They were selfish\",\"They were helpful and kind to each other\",\"They did not like cake\",\"They were very quiet\"],\"answer\":1,\"explain\":\"The characters shared their food to make Baby Cat happy, showing kindness.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"Which of these words is NOT in the \'Listen and repeat\' list?\",\"options\":[\"decided\",\"excited\",\"hungry\",\"together\"],\"answer\":2,\"explain\":\"The word \'hungry\' is in the story text, but not in the specific \'Listen and repeat\' list.\",\"topic\":\"Listen and Repeat\",\"part\":6,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21387,11,3,'English','en','Twinkle, Twinkle','[\"Twinkle, Twinkle is a popular nursery rhyme about a shining star that twinkles in the night sky.\",\"The rhyme is written by Jane Taylor and is often sung by children to practice rhythm and rhyme.\",\"The star is described as a small light that keeps shining even when the sun is gone.\",\"Key words: twinkle, star, night, sky, light, dark, bright, shine, glow.\",\"Rhyme scheme: AABB – the first two lines rhyme and the last two lines rhyme.\",\"The poem teaches children about opposites: dark vs. bright, day vs. night, up vs. down.\",\"Students can sing the poem to improve pronunciation and listening skills.\",\"The rhyme can be acted out: opening a window, shutting a door, turning off a fan, etc.\",\"Opposite words: dark – bright, full – empty, day – night, up – down.\",\"Matching activity: match words with pictures of a star, moon, sun, cloud.\",\"Fill‑in‑the‑blank: complete the lines “Shut the ______” and “Twinkle, twinkle ______”.\",\"Listening activities: repeat the poem, listen to tongue twisters, and act out actions.\",\"The poem is short, making it easy for Standard‑3 students to remember and recite.\",\"It encourages teamwork when children sing together in class.\",\"It also helps with memory by repeating the same words in different contexts.\",\"The rhyme can be used to teach basic punctuation: commas and periods.\",\"It is a good example of a simple poem with a clear message.\",\"Students can draw a picture of the star to reinforce visual learning.\",\"The rhyme can be used to practice counting: “Twinkle, twinkle, little star, how I wonder what you are.”\",\"It introduces the concept of a “little light” that shines at night.\",\"The poem is often used in early childhood education to develop language skills.\",\"It can be used to teach the idea of a “tiny spark” that helps travelers see the way.\"]','[{\"q\":\"Who is the author of the poem \'Twinkle, Twinkle\'?\",\"options\":[\"Robert Louis Stevenson\",\"Jane Taylor\",\"William Wordsworth\",\"Rudyard Kipling\"],\"answer\":1,\"explain\":\"The poem text mentions Jane Taylor at the end as the author.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"When does the star show its little light?\",\"options\":[\"When the sun is blazing\",\"During the afternoon\",\"When the blazing sun is gone\",\"When the moon is full\"],\"answer\":2,\"explain\":\"The poem states, \'When the blazing sun is gone... Then you show your little light\'.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"Why does the traveller in the dark thank the star?\",\"options\":[\"Because it is very big\",\"For its tiny spark that shows the way\",\"Because it makes the night warm\",\"Because it sings a song\"],\"answer\":1,\"explain\":\"The poem says the traveller thanks the star for its \'tiny spark\' because he could not see which way to go without it.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"According to the poem, what does the star do through the curtains?\",\"options\":[\"Sleeps\",\"Hides\",\"Peeps\",\"Dances\"],\"answer\":2,\"explain\":\"The poem says, \'And often through my curtains peep\'.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"If a traveller is lost in the dark, what helps him see which way to go?\",\"options\":[\"The blazing sun\",\"The dark blue sky\",\"The star\'s twinkle\",\"The curtains\"],\"answer\":2,\"explain\":\"The text mentions the traveller could not see which way to go if the star did not twinkle.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"What does the poet mean by saying the star \'never shut your eye\'?\",\"options\":[\"The star is blind\",\"The star stays awake and shines all night\",\"The star is afraid of the dark\",\"The star is looking for the sun\"],\"answer\":1,\"explain\":\"Shuttng an eye refers to sleeping; never shutting it means staying awake\\/shining continuously.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"Based on the poem, when does the star finally \'shut its eye\' or stop shining?\",\"options\":[\"When the traveller reaches home\",\"When it gets tired\",\"Till the sun is in the sky\",\"At midnight\"],\"answer\":2,\"explain\":\"The poem states the star stays in the sky \'Till the sun is in the sky\'.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"What color is the sky where the star keeps its place?\",\"options\":[\"Bright yellow\",\"Dark blue\",\"Light green\",\"Pale grey\"],\"answer\":1,\"explain\":\"The poem describes the setting as \'In the dark blue sky you keep\'.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"In the given figure, what is the girl looking at through the window?\",\"options\":[\"The blazing sun\",\"The stars and the moon\",\"A traveller on the road\",\"The curtains\"],\"answer\":1,\"explain\":\"The illustration shows a girl looking out at a night sky filled with stars and a crescent moon.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"11\\/020_101.jpg\"},{\"q\":\"In the given figure, what has been moved to the side so the girl can see the \'tiny sparks\' in the sky?\",\"options\":[\"The window frame\",\"The sun\",\"The curtains\",\"The bed\"],\"answer\":2,\"explain\":\"The picture shows a green curtain pulled to the side of the window.\",\"topic\":\"Twinkle, Twinkle\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"11\\/020_101.jpg\"},{\"q\":\"What should you do to the board according to the \'Listen and act\' section?\",\"options\":[\"Wash the board\",\"Paint the board\",\"Wipe the board\",\"Draw on the board\"],\"answer\":2,\"explain\":\"The text explicitly says \'Wipe the board\' in the \'Listen and act\' section.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What color are the lorries mentioned in the \'Listen and repeat\' section?\",\"options\":[\"Red and blue\",\"Red and yellow\",\"Green and yellow\",\"Blue and white\"],\"answer\":1,\"explain\":\"The text mentions \'Red lorry, yellow lorry\' in the tongue twister section.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What should you do with the fan according to the instructions?\",\"options\":[\"Turn on the fan\",\"Turn off the fan\",\"Clean the fan\",\"Fix the fan\"],\"answer\":1,\"explain\":\"The text lists \'Turn off the fan\' as one of the actions.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"According to the \'For the Teacher\' section, what should learners use to create a picture dictionary?\",\"options\":[\"Newspapers\",\"Sight words\",\"Crayons\",\"Stickers\"],\"answer\":1,\"explain\":\"The text advises teachers to encourage learners to use sight words for their picture dictionary.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What did the five funny frogs find in the tongue twister?\",\"options\":[\"Fresh fruit\",\"Fresh flies\",\"Fresh water\",\"Fresh fish\"],\"answer\":1,\"explain\":\"The tongue twister says \'Five funny frogs found fresh flies\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which action is related to a poem in the \'Listen and act\' section?\",\"options\":[\"Read a poem\",\"Write a poem\",\"Sing a poem\",\"Draw a poem\"],\"answer\":2,\"explain\":\"The text specifies the action \'Sing a poem\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a teacher says \'Sharpen your pencil\', which object is the student using?\",\"options\":[\"A pen\",\"A book\",\"A pencil\",\"A board\"],\"answer\":2,\"explain\":\"The command \'Sharpen your pencil\' directly involves a pencil.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Where does the girl sell seashells in the tongue twister?\",\"options\":[\"At the market\",\"By the seashore\",\"In the shop\",\"On the boat\"],\"answer\":1,\"explain\":\"The text says \'She sells seashells by the seashore\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"What should the teacher motivate learners to identify in the poem besides the characters?\",\"options\":[\"The number of words\",\"The important idea\",\"The page number\",\"The colors used\"],\"answer\":1,\"explain\":\"The \'For the Teacher\' section mentions motivating them to identify the important idea.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"In the phrase \'Blue birds bring bright berries back\', what do the birds bring?\",\"options\":[\"Bright berries\",\"Fresh flies\",\"Small sticks\",\"Yellow lorries\"],\"answer\":0,\"explain\":\"The tongue twister states the birds bring \'bright berries back\'.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21388,11,3,'English','en','The First Aid Box','[\"First Aid Box is a small white box that helps when someone gets hurt.\",\"It contains useful items like a bandage, cotton, antiseptic liquid, ointment, scissors, thermometer, soap and tablets.\",\"A bandage covers cuts or small wounds so they don’t get dirty.\",\"Cotton and antiseptic liquid clean the wound before you put a bandage on it.\",\"Ointment helps the wound heal faster.\",\"Scissors can cut bandages or cloth if needed.\",\"A thermometer checks if you have a fever when you feel sick.\",\"Soap and water keep your hands clean so germs don’t spread.\",\"Keeping a first aid box at school and at home is important.\",\"If someone is injured, wash the wound with soap and water, apply antiseptic, put a clean bandage, and check the temperature if fever is suspected.\",\"Ask a teacher or a grown‑up for help if the injury is serious.\",\"Remember to keep the first aid box tidy and replace used items.\",\"Good personal hygiene (washing hands, brushing teeth, eating fresh food, drinking water, sleeping well) helps prevent injuries and illnesses.\",\"The first aid box is a small tool that can make a big difference in a small injury.\"]','[{\"q\":\"What color was the box that Rina Madam brought to the class?\",\"options\":[\"Red\",\"White\",\"Blue\",\"Yellow\"],\"answer\":1,\"explain\":\"The text states Rina Madam walked into the class with a \'small white box\' in her hands.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Which grade did Rina Madam enter?\",\"options\":[\"Grade One\",\"Grade Two\",\"Grade Three\",\"Grade Four\"],\"answer\":2,\"explain\":\"The text mentions Rina Madam walked into \'Grade Three\' class.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Who guessed that the box was a lunchbox?\",\"options\":[\"Rina Madam\",\"The whole class\",\"Aarav\",\"The Principal\"],\"answer\":2,\"explain\":\"The text says, \'Aarav raised his hand and replied. \\\"Is it a lunchbox?\\\"\'\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What is the special box called?\",\"options\":[\"A lunchbox\",\"A pencil box\",\"A first aid box\",\"A toy box\"],\"answer\":2,\"explain\":\"Rina Madam identifies the box by saying, \'This is a first aid box.\'\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"When is a first aid box used?\",\"options\":[\"When someone is hungry\",\"When someone gets injured\",\"When someone is sleeping\",\"When someone is playing\"],\"answer\":1,\"explain\":\"The text defines it as a special box used \'when someone gets injured\'.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"How did Rina Madam greet the learners?\",\"options\":[\"With a smile\",\"With a loud shout\",\"With a song\",\"With a frown\"],\"answer\":0,\"explain\":\"The text says she said \'Good morning, everyone!\' with a smile.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"According to Rina Madam, where should we keep a first aid box?\",\"options\":[\"Only at the hospital\",\"Only in the playground\",\"In our school and at home\",\"Only in the market\"],\"answer\":2,\"explain\":\"Rina Madam states, \'we must keep this first aid box in our school and at home too.\'\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"If a student gets a small cut while playing in class, what should be used?\",\"options\":[\"A lunchbox\",\"A first aid box\",\"A school bag\",\"A water bottle\"],\"answer\":1,\"explain\":\"The text explains that the first aid box helps to cure small injuries.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Why did the class laugh loudly at Aarav?\",\"options\":[\"Because he told a joke\",\"Because he fell down\",\"Because he thought the first aid box was a lunchbox\",\"Because he was wearing a funny hat\"],\"answer\":2,\"explain\":\"The class laughed because Aarav incorrectly guessed the first aid box was a lunchbox.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What kind of injuries does the first aid box help to cure?\",\"options\":[\"Very deep wounds\",\"Small injuries\",\"Broken bones\",\"Serious illnesses\"],\"answer\":1,\"explain\":\"The text specifically mentions the box helps to \'cure small injuries\'.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Based on the text, why is the first aid box described as \'special\'?\",\"options\":[\"Because it is white in color\",\"Because it belongs to Rina Madam\",\"Because it is used to help injured people\",\"Because it contains food\"],\"answer\":2,\"explain\":\"It is called special because it is used for a specific purpose: when someone gets injured.\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"What did Rina Madam do to show the box to the learners?\",\"options\":[\"She hid it behind her back\",\"She held up the box in her hands\",\"She put it under the table\",\"She left it outside the room\"],\"answer\":1,\"explain\":\"The text says, \'Rina Madam held up the box and said...\'\",\"topic\":\"Read and know the use\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Which of these is used along with antiseptic liquid to clean wounds?\",\"options\":[\"Bandage\",\"Cotton\",\"Thermometer\",\"Soap\"],\"answer\":1,\"explain\":\"The text states that cotton and antiseptic liquid are used to clean wounds.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What is the purpose of a thermometer?\",\"options\":[\"To clean wounds\",\"To cover cuts\",\"To check our body temperature\",\"To heal wounds\"],\"answer\":2,\"explain\":\"According to the text, a thermometer is used to check our body temperature.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which word from the list means the same as \'hurt\'?\",\"options\":[\"Special\",\"Raised\",\"Picked\",\"Injured\"],\"answer\":3,\"explain\":\"In the context of first aid and wounds, \'injured\' refers to being hurt.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"According to the text, what is an ointment used for?\",\"options\":[\"To clean wounds\",\"To cure or heal wounds\",\"To cover cuts\",\"To check temperature\"],\"answer\":1,\"explain\":\"The text mentions that ointment is used to cure\\/heal wounds.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What should be used to cover a small wound?\",\"options\":[\"Bandage\",\"Thermometer\",\"Antiseptic\",\"Scissors\"],\"answer\":0,\"explain\":\"The text states that a bandage is used to cover cuts or small wounds.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which of these pairs is specifically mentioned for cleaning wounds?\",\"options\":[\"Soap and water\",\"Cotton and antiseptic liquid\",\"Bandage and ointment\",\"Tablets and medicines\"],\"answer\":1,\"explain\":\"The text explicitly pairs cotton and antiseptic liquid for cleaning wounds.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If Rahul has a fever, which tool from the first aid box will be used?\",\"options\":[\"Cotton\",\"Bandage\",\"Thermometer\",\"Ointment\"],\"answer\":2,\"explain\":\"A thermometer is used to check body temperature, which is necessary when someone has a fever.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Sita has a small cut on her finger. What should she use to cover it?\",\"options\":[\"Ointment\",\"Antiseptic liquid\",\"Bandage\",\"Thermometer\"],\"answer\":2,\"explain\":\"The text says a bandage is used to cover cuts.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Identify the item that is listed in the \'Listen and repeat\' section but not given a specific function in the \'Little Tools, Big Help\' section.\",\"options\":[\"Cotton\",\"Scissors\",\"Ointment\",\"Bandage\"],\"answer\":1,\"explain\":\"Scissors are listed in the vocabulary section (c) but their specific use is not described in section (d).\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"In the phrase \'Little Tools, Big Help\', which tool provides the \'help\' of healing?\",\"options\":[\"Antiseptic liquid\",\"Thermometer\",\"Bandage\",\"Ointment\"],\"answer\":3,\"explain\":\"The text associates \'heal\' specifically with the use of ointment.\",\"topic\":\"Listen and repeat\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21389,11,3,'English','en','Flying Man','[\"Flying Man is a poem about things that fly in the sky.\",\"Things that can fly: birds, kites, aeroplanes, buses (in stories), and the flying man himself.\",\"The poem uses simple words and rhymes to help children remember them.\",\"Opposite words are used to teach antonyms: down, under, coming, give, low, day.\",\"The poem asks questions like “Where are you going?” to make children think about flying.\",\"The teacher can ask students to write their own poems about birds, flowers, or the sky.\",\"Students should look for punctuation marks such as question marks and capital letters in the poem.\",\"Using a dictionary helps children learn new words and their meanings.\",\"The poem encourages imagination: the flying man can be a kite, a toy, or a small bird.\",\"The poem shows that flying can be fun and safe when you have a string or a wing.\",\"The teacher can ask students to circle words that mean “fly” or “flying.”\",\"The poem has a repeating line “Flying‑man, Flying‑man” to help memory.\",\"The poem shows that flying can be high, low, and over mountains and sea.\",\"Opposite words help students understand meaning by contrast.\",\"The poem can be read aloud to practice pronunciation and rhythm.\",\"Students can practice writing rhyming words that match the poem’s ending sounds.\",\"The poem encourages children to think about what they would like to fly.\",\"The poem is a good example of a simple, rhythmic poem for young learners.\",\"The poem can be used to teach basic reading comprehension and vocabulary.\",\"The poem can be used to practice writing sentences with capital letters.\",\"The poem can be used to practice writing sentences with question marks.\",\"The poem can be used to practice writing sentences with simple verbs like fly, go, come.\",\"The poem can be used to practice writing sentences with nouns like sky, sea, mountain.\",\"The poem can be used to practice writing sentences with adjectives like high, low, gentle.\",\"The poem can be used to practice writing sentences with adjectives like small, bright, bright.\"]','[{\"q\":\"Where is the Flying-man going in the poem?\",\"options\":[\"Down to the ground\",\"Up in the sky\",\"Inside a house\",\"Under the sea\"],\"answer\":1,\"explain\":\"The poem starts by saying the Flying-man is \'Up in the sky\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the Flying-man have that are described as \'so light\'?\",\"options\":[\"Shoes\",\"Hands\",\"Wings\",\"Hat\"],\"answer\":2,\"explain\":\"The poem mentions \'With wings so light\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the child want the Flying-man to show him?\",\"options\":[\"The clouds\",\"The birds\",\"The stars\",\"The sun\"],\"answer\":2,\"explain\":\"The child asks the Flying-man to \'Show me the stars\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"According to the poem, where does the Flying-man fly over?\",\"options\":[\"Over the mountains and the sea\",\"Over the trees and the grass\",\"Over the schools and the shops\",\"Over the cars and the buses\"],\"answer\":0,\"explain\":\"The poem states he flies \'Over the mountains, And over the sea!\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"From the list of words in the textbook, which one is related to flying?\",\"options\":[\"Pen\",\"Bus\",\"Book\",\"Aeroplane\"],\"answer\":3,\"explain\":\"An aeroplane is a vehicle that flies in the air.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"If the child wants to see the stars shine as mentioned in the poem, when should they look?\",\"options\":[\"In the morning\",\"In the night\",\"In the afternoon\",\"At noon\"],\"answer\":1,\"explain\":\"The poem mentions \'stars, That shine in the night\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"What is the child\'s final request to the Flying-man?\",\"options\":[\"To give him a kite\",\"To come down to earth\",\"To take the child with him\",\"To stop flying so high\"],\"answer\":2,\"explain\":\"The last line of the poem is \'Can’t you take me?\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"Which word from the poem describes how the Flying-man is flying?\",\"options\":[\"Slowly\",\"High\",\"Quietly\",\"Heavy\"],\"answer\":1,\"explain\":\"The poem asks \'Where are you going to, Flying so high?\'.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what is the man doing?\",\"options\":[\"Swimming in the sea\",\"Climbing a mountain\",\"Flying in the sky\",\"Driving a bus\"],\"answer\":2,\"explain\":\"The picture shows the man in the sky with clouds, using a wing to fly.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"remember\",\"figure_image\":\"11\\/024_101.jpg\"},{\"q\":\"In the given figure, what color is the wing or parachute the man is using to fly?\",\"options\":[\"Blue\",\"Green\",\"Orange\",\"Black\"],\"answer\":2,\"explain\":\"The illustration shows a man flying with a large orange wing.\",\"topic\":\"Flying Man Poem\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"11\\/024_101.jpg\"},{\"q\":\"What should learners use to find the meaning of words according to the text?\",\"options\":[\"A map\",\"A dictionary\",\"A notebook\",\"A textbook\"],\"answer\":1,\"explain\":\"The text explicitly states to encourage learners to use a dictionary to find the meaning of words.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which specific punctuation mark is mentioned in the text for learners to identify?\",\"options\":[\"Full stop\",\"Comma\",\"Question mark\",\"Exclamation mark\"],\"answer\":2,\"explain\":\"The text mentions motivating learners to identify punctuation marks like the question mark.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"According to the text, what are learners encouraged to write?\",\"options\":[\"Stories\",\"Poems\",\"Letters\",\"Essays\"],\"answer\":1,\"explain\":\"The text suggests encouraging learners to write poems on different topics.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which of these is a topic suggested in the text for writing a poem?\",\"options\":[\"A car\",\"A bird\",\"A house\",\"A school\"],\"answer\":1,\"explain\":\"The text lists \'a bird\' as one of the topics for writing poems.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Besides question marks, what else should learners be motivated to identify?\",\"options\":[\"Small letters\",\"Capital letters\",\"Numbers\",\"Colors\"],\"answer\":1,\"explain\":\"The text mentions motivating learners to identify punctuation marks and capital letters.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"The text suggests writing poems about a bird and a flower. What is the third example given?\",\"options\":[\"The sun\",\"The sky\",\"The rain\",\"The moon\"],\"answer\":1,\"explain\":\"The text lists \'a bird, a flower, sky, etc.\' as poem topics.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a student sees the word \'HELLO\', which feature mentioned in the text are they identifying?\",\"options\":[\"Question marks\",\"Capital letters\",\"Dictionary meanings\",\"Poem topics\"],\"answer\":1,\"explain\":\"Identifying \'HELLO\' involves recognizing capital letters, which is a skill mentioned in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"If a student finds a word they do not understand, what action does the text recommend?\",\"options\":[\"Write a poem about it\",\"Use a dictionary\",\"Look for a question mark\",\"Draw a flower\"],\"answer\":1,\"explain\":\"The text recommends using a dictionary to find the meaning of words.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which of these pairs contains only poem topics mentioned in the text?\",\"options\":[\"Bird and sky\",\"Tree and river\",\"Cloud and rain\",\"Sun and moon\"],\"answer\":0,\"explain\":\"Both \'bird\' and \'sky\' are explicitly listed as poem topics in the text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Based on the text, why would a teacher encourage the use of a dictionary?\",\"options\":[\"To help students draw birds\",\"To help students find word meanings\",\"To help students find capital letters\",\"To help students write punctuation marks\"],\"answer\":1,\"explain\":\"The text links the use of a dictionary specifically to finding the meaning of words.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21390,11,3,'English','en','A Happy Day in the Park','[\"- A park is a place where people go to play and relax.\",\"- It is usually sunny and full of trees, flowers and animals.\",\"- Children can run, play games, and have picnics in a park.\",\"- In a park we can see trees, birds, flowers, benches, and sometimes a playground.\",\"- We visit a park to enjoy nature, have fun, and keep our bodies healthy.\",\"- We should keep the park clean by using the dustbin and not littering.\",\"- We should not cut trees, pluck flowers or break branches because they hurt the plants.\",\"- We can help by taking care of plants and keeping the park tidy.\",\"- A happy day in the park means everyone is smiling, playing, and enjoying the sunshine.\",\"- Remember to respect nature and follow the rules of the park.\"]','[{\"q\":\"What kind of day is it in the park?\",\"options\":[\"A rainy day\",\"A bright sunny day\",\"A cold dark day\",\"A cloudy day\"],\"answer\":1,\"explain\":\"The text states \'It is a bright sunny day.\'\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What is Rekha doing while she is sitting?\",\"options\":[\"Eating a snack\",\"Playing with a ball\",\"Reading a book\",\"Sleeping\"],\"answer\":2,\"explain\":\"The text mentions Rekha is \'reading a\' (book).\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Where is Amar riding his bicycle?\",\"options\":[\"On the grass\",\"On the path\",\"Near the pond\",\"In the sky\"],\"answer\":1,\"explain\":\"The text says \'Amar is riding his on the path.\'\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Where are all the children playing together?\",\"options\":[\"In the school\",\"In the park\",\"In the house\",\"On the road\"],\"answer\":1,\"explain\":\"The title and the first sentence indicate the children are in the park.\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"What is Seema doing near the pond?\",\"options\":[\"Swimming\",\"Feeding the ducks\",\"Picking flowers\",\"Flying a kite\"],\"answer\":1,\"explain\":\"The text says Seema is \'feeding the near the\' (pond).\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Which child is described as smiling while playing?\",\"options\":[\"Asif\",\"Vikas\",\"Meera\",\"John\"],\"answer\":2,\"explain\":\"The text states \'Meera is the and smiling.\'\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"John is flying something colorful in the sky. What is it?\",\"options\":[\"A bird\",\"A balloon\",\"A kite\",\"A plane\"],\"answer\":2,\"explain\":\"In a park context, flying something colorful in the sky refers to a kite.\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Asif is sitting on the grass. What is he most likely picking?\",\"options\":[\"Stones\",\"Flowers\",\"Apples\",\"Paper\"],\"answer\":1,\"explain\":\"The text says Asif is \'picking\' while sitting on the grass, which refers to flowers in this context.\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Which word from the text describes how the children are playing?\",\"options\":[\"Quietly\",\"Happily\",\"Slowly\",\"Sadly\"],\"answer\":1,\"explain\":\"The text says \'The children are playing happily\'.\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What is the overall mood of the children in the park?\",\"options\":[\"They are bored\",\"They are tired\",\"They are enjoying the day\",\"They are looking for someone\"],\"answer\":2,\"explain\":\"The final sentence says \'Everyone is enjoying the lovely day together.\'\",\"topic\":\"Let’s read\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"According to the poem, what are the trees doing?\",\"options\":[\"Sleeping\",\"Dancing\",\"Running\",\"Crying\"],\"answer\":1,\"explain\":\"The text states \'The trees are dancing\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"What is the sun doing in the short poem?\",\"options\":[\"Hiding\",\"Raining\",\"Shining\",\"Setting\"],\"answer\":2,\"explain\":\"The text states \'The sun is shining\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which word is used to describe both the \'trees\' and the \'birds\' in the poem?\",\"options\":[\"Green\",\"Small\",\"Happy\",\"Fast\"],\"answer\":2,\"explain\":\"The text uses the phrases \'Happy trees\' and \'Happy birds\'.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"Which of these is a \'correct action\' to take in a park?\",\"options\":[\"Cut the trees\",\"Break the branches\",\"Pluck the flowers\",\"Use the dustbin\"],\"answer\":3,\"explain\":\"The text lists \'Use the dustbin\' as a correct action to tick.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"What should you do to the plants in the park according to the text?\",\"options\":[\"Take care of them\",\"Break their branches\",\"Pluck their flowers\",\"Cut them down\"],\"answer\":0,\"explain\":\"The text lists \'Take care of plants\' as a correct action.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"Which action helps to \'Keep the park clean\'?\",\"options\":[\"Plucking flowers\",\"Using the dustbin\",\"Breaking branches\",\"Cutting trees\"],\"answer\":1,\"explain\":\"Using a dustbin is the correct way to keep a park clean.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"If you see a beautiful flower in the park, what is the correct thing to do?\",\"options\":[\"Pluck it to take home\",\"Break the branch it is on\",\"Leave it and take care of the plant\",\"Throw it in the dustbin\"],\"answer\":2,\"explain\":\"The text indicates we should take care of plants and not pluck flowers.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"If you have an empty biscuit packet in the park, where should you put it?\",\"options\":[\"Under a tree\",\"In the dustbin\",\"Near the flowers\",\"On the grass\"],\"answer\":1,\"explain\":\"The text advises to \'Use the dustbin\' as a correct action.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which of the following actions is harmful to the park environment?\",\"options\":[\"Using the dustbin\",\"Taking care of plants\",\"Keeping the park clean\",\"Breaking the branches\"],\"answer\":3,\"explain\":\"Breaking branches is not a correct action and harms the trees.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"Following the pattern \'Happy trees, The trees are dancing\', how would you complete the line for \'Happy birds\'?\",\"options\":[\"The birds are singing\",\"The birds are sad\",\"The birds are sleeping\",\"The birds are hiding\"],\"answer\":0,\"explain\":\"The pattern uses an active, happy verb to complete the thought.\",\"topic\":\"Exercise\",\"part\":5,\"bloom\":\"create\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21391,11,3,'English','en','Getting Ready','[\"1. Getting ready means preparing yourself for school or any activity.\",\"2. We do simple actions like comb hair, button shirt, tie shoes.\",\"3. These actions are called *actions* or *tasks*.\",\"4. We can talk about actions by adding ‘ing’ to the verb: comb → combing, button → buttoning.\",\"5. Adding ‘ing’ makes a word that shows the action is happening now.\",\"6. In a conversation, we listen and repeat to practice speaking.\",\"7. We can write our own short conversation with our mother or teacher.\",\"8. We can number the actions in the right order: comb, button, tie shoes.\",\"9. We can describe daily chores of our mother or friends.\",\"10. We can use a dictionary to find meanings of new words.\",\"11. We can practice reading ‘ing’ words with the right stress.\",\"12. We can act out the conversation to make learning fun.\",\"13. We can ask questions like ‘What do you do in the morning?’\",\"14. We can say ‘I am combing my hair’ to use present continuous tense.\",\"15. We can use simple sentences: ‘I am tying my shoes.’\",\"16. We can remember that ‘ing’ words are often used for actions happening now.\",\"17. We can use pictures to help us learn new words.\",\"18. We can practice speaking with a partner or in a group.\",\"19. We can write a short dialogue about getting ready.\",\"20. We can use the word ‘ready’ to mean prepared.\",\"21. We can use the word ‘school’ to mean the place where we learn.\",\"22. We can use the word ‘mother’ or ‘mum’ to mean our parent.\",\"23. We can use the word ‘shirt’ to mean a piece of clothing.\",\"24. We can use the word ‘shoes’ to mean the footwear we wear.\",\"25. We can use the word ‘hair’ to mean the strands on our head.\"]','[{\"q\":\"Who is Shantanu talking to in the text?\",\"options\":[\"His Father\",\"His Mother\",\"His Teacher\",\"His Friend\"],\"answer\":1,\"explain\":\"The text explicitly mentions \'Mother\' speaking to Shantanu.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"Where is Shantanu getting ready to go?\",\"options\":[\"To the playground\",\"To the market\",\"To school\",\"To a party\"],\"answer\":2,\"explain\":\"Mother says, \'It\'s time to get ready for school.\'\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"In the given figure, what is the color of the shirt Shantanu is wearing?\",\"options\":[\"Blue\",\"Red\",\"Yellow\",\"Green\"],\"answer\":2,\"explain\":\"In the illustration, Shantanu is depicted wearing a yellow shirt.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"11\\/028_101.jpg\"},{\"q\":\"What is the first instruction Mother gives to Shantanu?\",\"options\":[\"Tie your shoe laces\",\"Button up your shirt\",\"Comb your hair\",\"Wash your face\"],\"answer\":2,\"explain\":\"Mother\'s first instruction is \'First, comb your hair.\'\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"In the given figure, what is Mother wearing on her face?\",\"options\":[\"A mask\",\"Glasses\",\"A scarf\",\"Paint\"],\"answer\":1,\"explain\":\"The illustration shows Mother wearing spectacles\\/glasses.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"11\\/028_101.jpg\"},{\"q\":\"How does Mother tell Shantanu to button up his shirt?\",\"options\":[\"Quickly\",\"Properly\",\"Slowly\",\"Tight\"],\"answer\":1,\"explain\":\"Mother says, \'Now, button up your shirt properly.\'\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"If Shantanu is following his mother\'s advice on how to tie his shoe laces, how will they look?\",\"options\":[\"Loose\",\"Dirty\",\"Neat\",\"Long\"],\"answer\":2,\"explain\":\"Mother tells him to \'Tie your shoe laces neatly.\'\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"Which action shows that Shantanu is listening to his mother\'s instructions about his clothes?\",\"options\":[\"Combing hair\",\"Buttoning the shirt\",\"Tying laces\",\"Saying goodbye\"],\"answer\":1,\"explain\":\"Buttoning a shirt is the action related specifically to his clothes.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"Based on the conversation, why does Shantanu say \'Thank you\' to his mother?\",\"options\":[\"Because she gave him a gift\",\"Because she is helping him get ready for school\",\"Because she is going to school with him\",\"Because she finished her work\"],\"answer\":1,\"explain\":\"Shantanu thanks his mother because she is guiding him through the steps of getting ready.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"Which word best describes Shantanu\'s behavior towards his mother in this talk?\",\"options\":[\"Obedient\",\"Angry\",\"Lazy\",\"Careless\"],\"answer\":0,\"explain\":\"Shantanu follows every instruction his mother gives, showing he is obedient.\",\"topic\":\"Let\'s talk\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"According to the teacher\'s instructions, what should learners create instructions for?\",\"options\":[\"Drawing pictures\",\"Health hygiene\",\"Playing games\",\"Reading books\"],\"answer\":1,\"explain\":\"The text explicitly tells the teacher to encourage learners to create instructions to maintain health hygiene.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What suffix is added to words like \'brush\', \'play\', and \'sleep\' in the given list?\",\"options\":[\"ed\",\"s\",\"ing\",\"ly\"],\"answer\":2,\"explain\":\"The text shows the pattern \'+ ing =\' and lists words like brushing, playing, and sleeping.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What should the teacher help learners use to find the meaning of unfamiliar words?\",\"options\":[\"A textbook\",\"A dictionary\",\"A notebook\",\"A map\"],\"answer\":1,\"explain\":\"The text states: \'Help learners to find the meaning of the unfamiliar words by using the dictionary.\'\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What should the teacher encourage learners to find from the given conversation?\",\"options\":[\"Important ideas\",\"Spelling mistakes\",\"New characters\",\"Hidden numbers\"],\"answer\":0,\"explain\":\"The text instructs the teacher to \'Encourage them to find important ideas from the given conversation.\'\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"When practicing \'ing\' words, what should the teacher focus on?\",\"options\":[\"Writing speed\",\"Proper stress\",\"Capital letters\",\"Silent letters\"],\"answer\":1,\"explain\":\"The text says to \'Take more practice of reading \'ing\' words with proper stress.\'\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a student is using a broom to tidy the floor, which word from the list describes this action?\",\"options\":[\"Cooking\",\"Sweeping\",\"Studying\",\"Playing\"],\"answer\":1,\"explain\":\"Sweeping is the action of cleaning a floor with a broom, which is included in the list of \'ing\' words.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Which word from the list describes the action of preparing food?\",\"options\":[\"Cleaning\",\"Learning\",\"Cooking\",\"Talking\"],\"answer\":2,\"explain\":\"Cooking is the word in the list that refers to the preparation of food.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"What does the teacher motivate the learners to do with the conversation?\",\"options\":[\"Write it five times\",\"Enact the conversation\",\"Draw the conversation\",\"Ignore the conversation\"],\"answer\":1,\"explain\":\"The text says: \'Motivate them to enact the conversation.\'\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Looking at the list of words, which activity is related to using a pencil or crayons on paper?\",\"options\":[\"Sleeping\",\"Cutting\",\"Drawing\",\"Sweeping\"],\"answer\":2,\"explain\":\"Drawing is the activity in the list performed with pencils or crayons on paper.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which of these words from the list is an action performed while a person is resting in bed?\",\"options\":[\"Studying\",\"Sleeping\",\"Helping\",\"Playing\"],\"answer\":1,\"explain\":\"Sleeping is the resting state mentioned in the list of \'ing\' words.\",\"topic\":\"For the Teacher\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21392,11,3,'English','en','Go, Go, Go!','[\"- Vehicles are means of transport: bus, train, jet, car, boat, helicopter, auto rickshaw, ship, metro‑train, bullock cart, mono‑rail, aeroplane.\",\"- Short forms are shortened words: I’ll = I will, I’d = I would, Don’t = Do not, It’s = It is, etc.\",\"- In the poem we use ‘I’d’ to mean ‘I would’ – e.g., ‘I’d rather take a train.’\",\"- We can ask questions like ‘How did you get there, how did you go?’ to talk about travel.\",\"- Vehicles belong to different ways: Road ways (bus, car), Railways (train, metro‑train), Air ways (jet, aeroplane), Water ways (boat, ship).\",\"- You can make a list of vehicles you know and draw or collect pictures of them.\",\"- New words about space journey can be found in a dictionary and added to a picture dictionary.\",\"- Simple sentences from the poem: ‘The bus is too slow.’ ‘I’d rather take a jet.’\",\"- True\\/false: ‘The jet is too high.’ (False – it is too fast).\",\"- Matching: match vehicle names with their ways (road, rail, air, water).\",\"- Fill in the blanks: ‘I’d ______ take a train.’ (would)\",\"- Use short forms correctly in sentences.\"]','[{\"q\":\"According to the poem, what does the short form \'I\'ll\' stand for?\",\"options\":[\"I shall or I will\",\"I am\",\"I have\",\"I would\"],\"answer\":0,\"explain\":\"The text explicitly states that \'I\'ll\' means \'I shall\\/ I will\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Why did the person in the poem say \'No\' to taking the Bus?\",\"options\":[\"It is too fast\",\"It is too slow\",\"It is too high\",\"It is too expensive\"],\"answer\":1,\"explain\":\"The poem says, \'The Bus is too slow, don\'t you know?\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Which mode of transport is described as being \'too high\' in the poem?\",\"options\":[\"Train\",\"Bus\",\"Jet\",\"Car\"],\"answer\":2,\"explain\":\"The poem states, \'The Jet is too high, don\'t you know?\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"What is the reason given for not using a Car?\",\"options\":[\"It is too fast\",\"It is too slow\",\"Petrol is too expensive\",\"It is too high\"],\"answer\":2,\"explain\":\"The poem mentions, \'Petrol is too expensive, don\'t you know?\' as the reason for not taking the car.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"If you want to say \'We are\' using a short form from the text, which one would you use?\",\"options\":[\"We\'re\",\"We\'ll\",\"We\'d\",\"Who\'s\"],\"answer\":0,\"explain\":\"The text lists \'We\'re\' as the short form for \'We are\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Which vehicle does the person want to take because the Bus is too slow?\",\"options\":[\"Jet\",\"Car\",\"Train\",\"Bicycle\"],\"answer\":2,\"explain\":\"The poem says, \'The Bus is too slow... I\'d rather take a Train\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Why does the person finally decide to walk?\",\"options\":[\"Because walking is the fastest way\",\"Because the Jet is too slow\",\"Because petrol for the car is too expensive\",\"Because the train is too high\"],\"answer\":2,\"explain\":\"After rejecting the car due to expensive petrol, the person decides to walk.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"Based on the poem, which of these is the most expensive way to travel?\",\"options\":[\"Walking\",\"Taking a Bus\",\"Taking a Train\",\"Taking a Car\"],\"answer\":3,\"explain\":\"The poem specifically mentions \'expensive\' only in relation to the car\'s petrol.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"What is the full form of \'Can\'t\' as given in the text?\",\"options\":[\"Can not\",\"Can do\",\"Could not\",\"Can will\"],\"answer\":0,\"explain\":\"The text lists \'Can\'t - Can not\' in the short forms section.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What does the word \'Let\'s\' mean in the poem?\",\"options\":[\"Let is\",\"Let us\",\"Let has\",\"Let as\"],\"answer\":1,\"explain\":\"The text states \'Let\'s - Let us\'.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"In the given figure, which mode of transport is the child riding?\",\"options\":[\"A Bus\",\"A Train\",\"A Jet\",\"A Car\"],\"answer\":1,\"explain\":\"The illustration shows a child in a train engine on a track.\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"remember\",\"figure_image\":\"11\\/030_101.jpg\"},{\"q\":\"In the given figure, the child is on a vehicle. According to the poem, why did the person later say \'No\' to this specific vehicle?\",\"options\":[\"It is too slow\",\"It is too fast\",\"It is too high\",\"It is too expensive\"],\"answer\":1,\"explain\":\"The figure shows a train, and the poem says, \'The Train is too fast, don\'t you know?\'\",\"topic\":\"Listen and sing\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"11\\/030_101.jpg\"},{\"q\":\"What does the short form \'I\'d\' stand for in the poem \'Go, Go, Go!\'?\",\"options\":[\"I did\",\"I do\",\"I would\",\"I had\"],\"answer\":2,\"explain\":\"The teacher\'s note specifically asks to use \'I would\' for \'I\'d\' in this poem.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"What type of words does the teacher want the learners to understand?\",\"options\":[\"Long forms\",\"Short forms\",\"New words\",\"Hard words\"],\"answer\":1,\"explain\":\"The text states to encourage learners to understand short forms of the words.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"According to the teacher\'s note, how should a student read the word \'I\'d\' in the poem?\",\"options\":[\"I did\",\"I would\",\"I am\",\"I will\"],\"answer\":1,\"explain\":\"The instruction says to ask learners to use \'I would\' for \'I\'d\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Why does the teacher ask students to use \'I would\' instead of \'I\'d\'?\",\"options\":[\"To make the poem longer\",\"To help them understand the short form\",\"To change the meaning of the poem\",\"To practice spelling long words\"],\"answer\":1,\"explain\":\"The goal is to encourage learners to understand how short forms work.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which specific short form is mentioned in the teacher\'s note?\",\"options\":[\"It\'s\",\"Don\'t\",\"I\'d\",\"Can\'t\"],\"answer\":2,\"explain\":\"The text explicitly mentions \'I\'d\' as the example to be used.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"In the context of this lesson, \'I would\' is the ______ of \'I\'d\'.\",\"options\":[\"Opposite\",\"Short form\",\"Full form\",\"Rhyming word\"],\"answer\":2,\"explain\":\"If \'I\'d\' is the short form, \'I would\' is the full or expanded form the teacher wants them to understand.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If a teacher follows the instructions, what will they encourage learners to do?\",\"options\":[\"Write a new poem\",\"Understand short forms of words\",\"Draw pictures for the poem\",\"Memorize the whole book\"],\"answer\":1,\"explain\":\"The first bullet point says to encourage learners to understand short forms.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which of these is a \'short form\' based on the teacher\'s instructions?\",\"options\":[\"I would\",\"I\'d\",\"Teacher\",\"Poem\"],\"answer\":1,\"explain\":\"The text identifies \'I\'d\' as the short form to be replaced by \'I would\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Based on the text, which is the correct pair?\",\"options\":[\"I\'d = I did\",\"I\'d = I would\",\"I\'d = I had\",\"I\'d = I could\"],\"answer\":1,\"explain\":\"The text specifically links \'I\'d\' with \'I would\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"If you are reading the poem \'Go, Go, Go!\', what should you say when you see \'I\'d\'?\",\"op