\":2,\"bloom\":\"apply\"},{\"q\":\"Which of these words is mentioned in the list to \'Listen and repeat\'?\",\"options\":[\"Computer\",\"Robot\",\"Mobile\",\"Internet\"],\"answer\":1,\"explain\":\"The word \'robot\' is explicitly listed in the textbook text.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Choose the correct spelling of the word from the text.\",\"options\":[\"Technolagy\",\"Teknology\",\"Technology\",\"Technolgy\"],\"answer\":2,\"explain\":\"The correct spelling as per the text is \'technology\'.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Which word in the list is used to describe something that is very surprising or very good?\",\"options\":[\"App\",\"Tablet\",\"Robot\",\"Amazing\"],\"answer\":3,\"explain\":\"\'Amazing\' is an adjective used to describe something wonderful or surprising.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What is the short form for \'application\' mentioned in the text?\",\"options\":[\"App\",\"Apt\",\"Apple\",\"Add\"],\"answer\":0,\"explain\":\"In the context of technology, \'app\' is the short form for application.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"Which device from the list is a flat, touch-screen computer?\",\"options\":[\"Robot\",\"Amazing\",\"Tablet\",\"App\"],\"answer\":2,\"explain\":\"A tablet is a portable, flat computing device with a touch screen.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If you see a machine that can move and perform tasks automatically, which word from the list describes it?\",\"options\":[\"App\",\"Robot\",\"Technology\",\"Tablet\"],\"answer\":1,\"explain\":\"A robot is a machine designed to carry out tasks automatically.\",\"topic\":\"Exercise\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"When we use science to create new things like apps and robots, what is the general term for this?\",\"options\":[\"Amazing\",\"Tablet\",\"Technology\",\"Repeat\"],\"answer