\":4,\"bloom\":\"understand\"},{\"q\":\"महाराज कशाबद्दल विचार करू लागले?\",\"options\":[\"युद्धाबद्दल\",\"प्रजेच्या भल्यासाठी काय करता येईल याबद्दल\",\"जेवणाबद्दल\",\"विश्रांतीबद्दल\"],\"answer\":1,\"explain\":\"प्रजेच्या भल्यासाठी आणखी काय करता येईल, याबद्दल महाराज विचार करू लागले.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर एखादा मुलगा अभ्यासात \'दंग\' झाला असेल, तर त्यासाठी उताऱ्यातील कोणता शब्द योग्य ठरेल?\",\"options\":[\"मग्न होणे\",\"दक्ष असणे\",\"हित होणे\",\"सावध असणे\"],\"answer\":0,\"explain\":\"\'दंग होणे\' आणि \'मग्न होणे\' हे समानार्थी शब्द आहेत.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"प्रजेचा \'फायदा\' व्हावा या अर्थाचा कोणता शब्द उताऱ्यात वापरला आहे?\",\"options\":[\"विचार\",\"दक्ष\",\"हित\",\"नेहमीप्रमाणे\"],\"answer\":2,\"explain\":\"\'फायदा\' या अर्थासाठी \'हित\' हा शब्द उताऱ्यात आला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"महाराज विचारमग्न का झाले असावेत?\",\"options\":[\"त्यांना तेनालीरामचे म्हणणे पटले नव्हते\",\"त्यांना तेनालीरामचे म्हणणे पूर्णपणे पटले होते\",\"तेनालीराम त्यांच्याशी खोटे बोलला होता\",\"त्यांना खूप भूक लागली होती\"],\"answer\":1,\"explain\":\"तेनालीरामचे म्हणणे पूर्णपणे पटल्यामुळे महाराज विचारमग्न झाले.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्याच्या शेवटी महाराज कोणासोबत पुढे जाऊ लागले?\",\"options\":[\"तेनालीरामसोबत\",\"सैन्यासोबत\",\"एकटेच\",\"प्रजेसोबत\"],\"answer\":0,\"explain\":\"महाराज नेहमीप्रमाणे तेनालीरामसोबत पुढे जाऊ लागले असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"\'पुल्लिंग\' शब्दासाठी कोणता शब्द वापरला जातो?\",\"options\":[\"तो\",\"ती\",\"ते\",\"आम्ही\"],\"answer\":0,\"explain\":\"पाठानुसार \'तो\' म्हणजे पुल्लिंग.\",\"topic\":\"लिंग ओळख\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'स्त्रीलिंग\' शब्दासाठी कोणता शब्द वापरला जातो?\",\"options\":[\"तो\",\"ती\",\"ते\",\"तुम्ही\"],\"answer\":1,\"explain\":\"पाठानुसार \'ती\' म्हणजे स्त्रीलिंग.\",\