ions\":[\"वैयक्तिक व सामूहिक\",\"फक्त शिक्षकांनी म्हणणे\",\"फक्त मुलांनी म्हणणे\",\"रेडिओवर ऐकणे\"],\"answer\":0,\"explain\":\"मजकुरात \'वैयक्तिक व सामूहिक\' कविता म्हणून घ्यावी असे म्हटले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या विद्यार्थ्याला अंतराळातील नव्या शोधांची माहिती हवी असेल, तर त्याने काय करावे?\",\"options\":[\"गोष्टींची पुस्तके वाचावीत\",\"वर्तमानपत्रातील बातम्यांचे वाचन करावे\",\"मैदानावर खेळावे\",\"गाणी ऐकावीत\"],\"answer\":1,\"explain\":\"नव्या शोधांच्या माहितीसाठी वर्तमानपत्रातील बातम्या वाचण्यास मजकुरात सुचवले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"मजकुरातील \'साभिनय\' या शब्दाचा अर्थ खालीलपैकी काय असू शकतो?\",\"options\":[\"अभिनयाशिवाय\",\"खूप वेगाने\",\"हावभावासह (अभिनयासह)\",\"डोळे मिटून\"],\"answer\":2,\"explain\":\"कविता साभिनय म्हणणे म्हणजे योग्य हावभावासह किंवा अभिनयासह म्हणणे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"काव्यलेखन स्पर्धेमुळे विद्यार्थ्यांच्या कोणत्या कौशल्याला वाव मिळेल?\",\"options\":[\"धावण्याचे कौशल्य\",\"लेखन व कल्पनाशक्ती\",\"चित्र काढणे\",\"जेवण बनवणे\"],\"answer\":1,\"explain\":\"काव्यलेखन स्पर्धेचा संबंध विद्यार्थ्यांच्या लेखन कौशल्याशी येतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"\'अंतराळवीर\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"पाण्यात पोहणारी व्यक्ती\",\"अंतराळात प्रवास करणारी व्यक्ती\",\"विमान चालवणारी व्यक्ती\",\"रस्त्यावर चालणारी व्यक्ती\"],\"answer\":1,\"explain\":\"मजकुरानुसार, अंतराळात प्रवास करणाऱ्या व्यक्तीला अंतराळवीर म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"अंतराळात प्रवास करण्यासाठी वापरल्या जाणाऱ्या साधनाला काय म्हणतात?\",\"options\":[\"बस\",\"विमान\",\"यान\",\"जहाज\"],\"answer\":2,\"explain\":\"मजकुरात दिले आहे की यान हे अंतराळात प्रवास करण्याचे साधन आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"अंतराळात प्रवास करणारी व्यक्ती कोण असते?\",\"options\":[\"वैमानिक\",\"नाविक\",\"अंतराळव