,{\"q\":\"\'निश्चय\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"निर्णय\",\"उत्सुकता\",\"लळा\",\"अंकुर\"],\"answer\":0,\"explain\":\"पाठात \'निर्णय\' या शब्दाचा अर्थ \'निश्चय\' असा दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'आतुरता\' या शब्दाचा अर्थ स्पष्ट करणारा शब्द ओळखा.\",\"options\":[\"लळा\",\"निर्णय\",\"उत्सुकता\",\"अंकुर\"],\"answer\":2,\"explain\":\"पाठात \'उत्सुकता\' या शब्दाचा अर्थ \'आतुरता\' असा दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"एखाद्या गोष्टीची खूप \'गोडी\' लागणे, याला पाठात कोणता शब्द आहे?\",\"options\":[\"निश्चय\",\"लळा\",\"कोंब\",\"नापसंती\"],\"answer\":1,\"explain\":\"पाठात \'लळा\' या शब्दाचा अर्थ \'गोडी\' असा दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जर शुभ्राला एखादी भाजी आवडली नाही, तर ती काय करेल?\",\"options\":[\"लळा लावेल\",\"नाका मुरडेल\",\"निश्चय करेल\",\"अंकुर काढेल\"],\"answer\":1,\"explain\":\"नापसंती दर्शवण्यासाठी \'नाका मुरडणे\' हा वाक्प्रचार वापरला जातो.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"बी पेरल्यानंतर जमिनीतून काय बाहेर येतो?\",\"options\":[\"निर्णय\",\"लळा\",\"अंकुर\",\"नापसंती\"],\"answer\":2,\"explain\":\"बीला मोड किंवा कोंब येतो, ज्याला \'अंकुर\' म्हणतात.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी शब्दाची योग्य जोडी ओळखा.\",\"options\":[\"लळा - नापसंती\",\"निर्णय - निश्चय\",\"अंकुर - आतुरता\",\"उत्सुकता - मोड\"],\"answer\":1,\"explain\":\"पाठातील शब्दार्थांनुसार \'निर्णय\' म्हणजे \'निश्चय\' ही जोडी बरोबर आहे.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"\'कोंब\' या शब्दाचा अर्थ खालीलपैकी कोणता?\",\"options\":[\"अंकुर\",\"निर्णय\",\"उत्सुकता\",\"लळा\"],\"answer\":0,\"explain\":\"पाठात \'अंकुर\' या शब्दाचे अर्थ \'मोड\' आणि \'कोंब\' असे दिले आहेत.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जेव्हा आपण एखादी गोष्ट करायचे पक्के ठरवतो, तेव्हा आपण काय घेतला असे म्हणतात?\",\"options\":[\"लळा\",\"अंकुर\",\"निर्णय\",\"नाका मुरडणे\"],\"answer\":2,\"explain\":\"पक्के ठरवणे म्हणजे \'निश्चय\' करणे किंवा \'निर्णय\' घेणे.\",\"topic\":\"नवीन शब्द\",\"part\":7,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21430,12,3,'Marathi','mr','टिंब (कविता)','[\"टिंब म्हणजे शब्दातील अक्षरांचे फेरफार करून नवीन शब्द तयार करणे.\",\"टिंबात अक्षरे हिंडून हिंडून फेरली जातात, जुळे शब्दाचा अर्थ बदलतो.\",\"कवितेत टिंबातील शब्द फुलपाखरू झाले, जे हिंडून हिंडून दमले.\",\"वाक्याच्या शेवटी पूर्णविराम (.) येतो, जे टिंबाचा पूर्णविराम म्हणून ओळखले जाते.\",\"अनुस्वार म्हणजे नाकातून स्पष्टपणे उच्चार होणारा अक्षर, ज्यासाठी टिंबाला \'अनुस्वार\' म्हणतात.\",\"कवितेत \'नंदी\', \'मांडी\', \'बांबू\', \'कुंडी\', \'शेंडी\', \'अंग\', \'भांडे\', \'रंग\' यांसारखे टिंब शब्द दिसतात.\",\"टिंबातील फेरफार नेकमी शब्दाच्या अर्थात बदल आणतो, जसे \'रग\' हिंडून \'रंग\' झाले.\",\"कवितेचा भाव: शब्दांचे खेळ, हिंडणे, फेरणे, आणि अंतिमे पूर्णविराम.\",\"शिक्षकांना सांगितले जाते की विद्यार्थ्यांना टिंबाची ओळख करावी, यासाठी चित्रे दाखविणे व चर्चा करणे उपयुक्त.\",\"टिंबातील यमक शब्द (जसे नंदी-मांडी, बांबू-कुंडी) एकमेकाशी आवाजात समान असतात.\",\"पूर्णविराम म्हणजे वाक्याचा शेवट, जे \'.\', \'?\', \'!\' इत्यादींमधील काही चिन्हाने दर्शवले जाते.\",\"अनुस्वार असलेले शब्द नाकातून स्पष्ट उच्चार होतात, जसे \'मांडी\', \'शेंडी\' इत्यादी.\",\"टिंबातील फेरफार नेकमी शब्दाची ओळख वाटते, जसे \'आबा\' हिंडून \'आंबा\' झाले.\",\"कवितेचा शैली: सोपा, खेळदंडा, बालमित्र, आणि शब्दांचा संगीत.\"]','[{\"q\":\"अक्षराच्या डोक्यावर येणाऱ्या टिंबाला काय म्हणतात?\",\"options\":[\"पूर्णविराम\",\"स्वल्पविराम\",\"अनुस्वार\",\"काना\"],\"answer\":2,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, अक्षरात येणाऱ्या टिंबाला \'अनुस्वार\' म्हणतात.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"वाक्य पूर्ण झाल्यावर जे टिंब दिले जाते, त्यास काय म्हणतात?\",\"options\":[\"अनुस्वार\",\"पूर्णविराम\",\"प्रश्नचिन्ह\",\"उद्गारचिन्ह\"],\"answer\":1,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, वाक्य पूर्ण झाल्यावर दिलेल्या टिंबाला \'पूर्णविराम\' म्हणतात.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी विद्यार्थ्यांकडून कविता कशी म्हणून घ्यावी?\",\"options\":[\"फक्त मनातल्या मनात\",\"मोठ्याने ओरडून\",\"तालासुरात व साभिनय\",\"फक्त वाचून\"],\"answer\":2,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, कविता तालासुरात व साभिनय म्हणून घ्यावी.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"कवितेनुसार, शब्दांच्या बागेत टिंब काय झाले?\",\"options\":[\"फूल\",\"फुलपाखरू\",\"पान\",\"झाड\"],\"answer\":1,\"explain\":\"कवितेच्या पहिल्या कडव्यात म्हटले आहे की टिंब शब्दांच्या बागेमध्ये फुलपाखरू झाले.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"\'नदी\' या शब्दावर टिंब (अनुस्वार) दिल्यावर कोणता शब्द तयार झाला?\",\"options\":[\"नंदी\",\"नांदी\",\"नदीम\",\"नणंद\"],\"answer\":0,\"explain\":\"कवितेत \'नदी\'चा \'नंदी\' केला असे दिले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"टिंब अगदी का दमले?\",\"options\":[\"खूप काम केल्यामुळे\",\"खूप रडल्यामुळे\",\"हिंडून हिंडून\",\"अभ्यास केल्यामुळे\"],\"answer\":2,\"explain\":\"कवितेत म्हटले आहे की \'हिंडून हिंडून असे टिंब अगदी दमले\'.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर \'माडी\' शब्दावर अनुस्वार दिला, तर कोणता नवीन शब्द तयार होईल?\",\"options\":[\"मंडी\",\"माड\",\"मांड\",\"मांडी\"],\"answer\":3,\"explain\":\"कवितेनुसार \'माडी\'ची \'मांडी\' केली आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"\'कुडी\' या शब्दापासून \'कुंडी\' तयार करण्यासाठी कशाचा वापर केला आहे?\",\"options\":[\"काना\",\"वेलांटी\",\"अनुस्वार\",\"मात्रा\"],\"answer\":2,\"explain\":\"कुडी शब्दावर अनुस्वार (टिंब) दिल्यास कुंडी शब्द तयार होतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांनी उच्चार समजून सांगण्यासाठी कशाचे निरीक्षण करून चर्चा घडवून आणावी?\",\"options\":[\"पुस्तकांचे\",\"चित्रांचे\",\"फळ्याचे\",\"बागेचे\"],\"answer\":1,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, चित्रांचे निरीक्षण करून चर्चा घडवून आणावी.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"कवितेत \'भाडे\' या शब्दाचे \'भांडे\' झाले, तसे \'रग\' या शब्दाचे काय झाले?\",\"options\":[\"राग\",\"रंग\",\"रंगा\",\"रंगी\"],\"answer\":1,\"explain\":\"कवितेत \'रग बनला रंग\' असे दिले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"\'हिंडणे\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"फिरणे\",\"बसणे\",\"धावणे\",\"झोपणे\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुरानुसार \'हिंडणे\' म्हणजे \'फिरणे\'.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'माडी\' म्हणजे घराचा कोणता भाग?\",\"options\":[\"खालचा मजला\",\"वरचा मजला\",\"अंगण\",\"स्वयंपाकघर\"],\"answer\":1,\"explain\":\"मजकुरानुसार \'माडी\' म्हणजे \'वरचा मजला\'.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'वेळूची काठी\' याला काय म्हणतात?\",\"options\":[\"रग\",\"शेंडी\",\"बांबू\",\"माडी\"],\"answer\":2,\"explain\":\"मजकुरात \'बांबू\' या शब्दाचा अर्थ \'वेळूची काठी\' असा दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"फळाचा उभा लांबट कापलेला तुकडा म्हणजे काय?\",\"options\":[\"बांबू\",\"शेंडी\",\"रग\",\"माडी\"],\"answer\":1,\"explain\":\"मजकुरानुसार \'शेंडी\' म्हणजे फळाचा उभा लांबट कापलेला तुकडा.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'रग\' या शब्दाचा योग्य अर्थ ओळखा.\",\"options\":[\"मऊपणा\",\"शांतता\",\"जोर किंवा ताण\",\"आनंद\"],\"answer\":2,\"explain\":\"मजकुरात \'रग\' या शब्दाचा अर्थ \'जोर\' किंवा \'ताण\' असा दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"राजू बागेत \'फिरत\' आहे. या वाक्यातील \'फिरणे\' साठी कोणता शब्द मजकुरात आला आहे?\",\"options\":[\"हिंडणे\",\"माडी\",\"बांबू\",\"रग\"],\"answer\":0,\"explain\":\"हिंडणे आणि फिरणे हे समानार्थी शब्द आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता शब्द घराच्या रचनेशी संबंधित आहे?\",\"options\":[\"शेंडी\",\"माडी\",\"रग\",\"हिंडणे\"],\"answer\":1,\"explain\":\"माडी म्हणजे वरचा मजला, जो घराचा भाग असतो.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर तुम्हाला फणसाचा उभा लांबट तुकडा कापून दिला, तर मजकुरानुसार त्याला काय म्हणाल?\",\"options\":[\"बांबू\",\"रग\",\"शेंडी\",\"माडी\"],\"answer\":2,\"explain\":\"फळाच्या उभ्या लांबट तुकड्याला \'शेंडी\' म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'ताण\' या शब्दासाठी मजकुरात कोणता दुसरा शब्द वापरला आहे?\",\"options\":[\"रग\",\"बांबू\",\"माडी\",\"हिंडणे\"],\"answer\":0,\"explain\":\"मजकुरानुसार \'रग\' म्हणजे जोर किंवा ताण.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती वस्तू निसर्गातील झाडाच्या काठीशी संबंधित आहे?\",\"options\":[\"बांबू\",\"माडी\",\"रग\",\"हिंडणे\"],\"answer\":0,\"explain\":\"बांबू ही वेळूची काठी असते, जी झाडाशी संबंधित आहे.\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21431,12,3,'Marathi','mr','कसे मिळेल पाणी? (चित्रकथा)','[\"पाणी हे जीवनाचे मूलभूत घटक आहे.\",\"पाण्याचे स्त्रोत म्हणजे नद्या, तलाव, पावसाचे पाणी आणि भूमिगत पाणी.\",\"पाणी स्वच्छ आणि सुरक्षित असायला हवे, अन्यथा आजार होऊ शकतो.\",\"पाण्याची टंचाई म्हणजे पाण्याची कमतरता.\",\"पाण्याची टंचाई टाळण्यासाठी गाळ काढून तलाव स्वच्छ करणे उपयुक्त ठरते.\",\"पाण्याची बचत करण्यासाठी पाणी कमी वापरणे आणि गळती दुरुस्त करणे आवश्यक आहे.\",\"पाण्याचे संरक्षण करण्यासाठी वृक्षारोपण करणे महत्त्वाचे आहे.\",\"पाण्याचे शुद्धीकरण करण्यासाठी गाळ काढणे, फिल्टर वापरणे, उकळणे इत्यादी पद्धती आहेत.\",\"पाणी वापरताना स्वच्छ हाताने हाताळणे गरजेचे आहे.\",\"पाणी वापरून झाल्यावर नळ बंद करणे आवश्यक आहे.\",\"पाण्याच्या टंचाईतून वाचण्यासाठी घरात पाणी साठवणे उपयुक्त आहे.\",\"पाणी शुद्ध करण्यासाठी बायोलॉजिकल फिल्टर वापरता येतो.\",\"पाण्याचे संरक्षण करण्यासाठी पाणी वाया जाणे टाळावे.\",\"पाण्याच्या वापरावर लक्ष ठेवण्यासाठी पाणी मोजमाप यंत्र वापरता येते.\",\"पाणी वापरताना स्वच्छता राखणे हे आरोग्यासाठी चांगले आहे.\",\"पाणी शुद्ध करण्यासाठी रासायनिक पद्धती वापरता येतात, पण काळजीपूर्वक वापरावे.\",\"पाणी शुद्ध करण्यासाठी सौर उष्णता वापरून उकळणे सोपे आहे.\",\"पाणी शुद्ध करण्यासाठी नळाच्या पाण्यातून गाळ काढण्यासाठी गाळणी वापरता येते.\",\"पाणी शुद्ध करण्यासाठी पाण्याच्या स्रोतावर लक्ष ठेवणे आवश्यक आहे.\",\"पाणी शुद्ध करण्यासाठी पाण्याचे तापमान महत्त्वाचे आहे.\",\"पाणी शुद्ध करण्यासाठी पाण्याचे pH मोजणे उपयुक्त आहे.\",\"पाणी शुद्ध करण्यासाठी पाण्यातील जीवाणू नष्ट करण्यासाठी उकळणे आवश्यक आहे.\",\"पाणी शुद्ध करण्यासाठी पाण्यातील गाळ काढण्यासाठी फिल्टर वापरता येतो.\",\"पाणी शुद्ध करण्यासाठी पाण्यातील रासायनिक दूषितपणा तपासणे आवश्यक आहे.\",\"पाणी शुद्ध करण्यासाठी पाण्यातील धातू काढण्यासाठी फिल्टर वापरता येतो.\"]','[{\"q\":\"सिंहराजांनी सभा केव्हा बोलावली आहे?\",\"options\":[\"आज सकाळी\",\"आज दुपारी\",\"आज संध्याकाळी\",\"आज रात्री\"],\"answer\":2,\"explain\":\"पाठातील पहिल्या ओळीनुसार, सिंहराजांनी सभा आज संध्याकाळी बोलावली आहे.\",\"topic\":\"प्रत्यक्ष काम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जंगलात कोणत्या ऋतूमध्ये पाण्याची टंचाई निर्माण झाली आहे?\",\"options\":[\"पावसाळ्यात\",\"हिवाळ्यात\",\"उन्हाळ्यात\",\"सर्व ऋतूंमध्ये\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट म्हटले आहे की, दरवर्षीप्रमाणे उन्हाळ्यात पाण्याची टंचाई निर्माण झाली आहे.\",\"topic\":\"प्रत्यक्ष काम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जंगलातील जुन्या तलावाचे काय झाले होते?\",\"options\":[\"तो फुटला होता\",\"तो बुजला होता\",\"तो चोरीला गेला होता\",\"तो वाळून गेला होता\"],\"answer\":1,\"explain\":\"मजकुरातील माहितीनुसार, जंगलातील जुना तलाव आता बुजला आहे.\",\"topic\":\"प्रत्यक्ष काम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"पाण्याचा प्रश्न सोडवण्यासाठी तलावातून काय काढणे गरजेचे आहे?\",\"options\":[\"पाणी\",\"मासे\",\"गाळ\",\"दगड\"],\"answer\":2,\"explain\":\"तलावातून गाळ काढला, तर पाण्याचा प्रश्न सुटेल असे मजकुरात सुचवले आहे.\",\"topic\":\"प्रत्यक्ष काम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तलावाचे काम सुरू करण्यासाठी सिंहराजांनी प्राण्यांकडे सर्वात आधी कोणती मागणी केली?\",\"options\":[\"पाणी आणण्याची\",\"तलावाची जागा दाखवण्याची\",\"जेवण ब