 चौकीदार कळवळून विनंती करूनही दरवाजा उघडत नाही, यावरून नियम कडक असल्याचे समजते.\",\"topic\":\"गडाचे दरवाजे बंद झाले\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"हिरकणीने चौकीदाराला \'बाबा\' म्हणून का संबोधले असावे?\",\"options\":[\"तो तिचा खरा बाबा होता\",\"ती त्याला घाबरवण्यासाठी असे म्हणाली\",\"ती कळवळून आणि आदराने विनंती करत होती\",\"तिला त्याचे नाव माहित नव्हते\"],\"answer\":2,\"explain\":\"संकटाच्या वेळी मदतीसाठी विनवणी करताना तिने आदराने \'बाबा\' हा शब्द वापरला.\",\"topic\":\"गडाचे दरवाजे बंद झाले\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"हिरा कोणाला भेटण्यासाठी धावत सुटली?\",\"options\":[\"तिच्या नवऱ्याला\",\"तिच्या बाळाला\",\"तिच्या मैत्रिणीला\",\"गडाच्या राजाला\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की गड उतरल्यावर हिरा बाळाला भेटण्यासाठी धावत सुटली.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हिराचा पाय निसटला तेव्हा तिला कोणी सावरले?\",\"options\":[\"एका मोठ्या दगडाने\",\"एका वेलीने\",\"झाडाच्या एका फांदीने\",\"गडाच्या पहारेकऱ्याने\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे सांगितले आहे की झाडाच्या एका फांदीने तिला सावरले.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हिरा वाट शोधण्यासाठी गडावर कोठे फिरली?\",\"options\":[\"राजवाड्यात\",\"बुरुजांकडे\",\"बाजारात\",\"मंदिरात\"],\"answer\":1,\"explain\":\"हिरा वाट शोधण्यासाठी या बुरुजाकडे, त्या बुरुजाकडे अशी पुष्कळ फिरली.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हिरा गडावर इकडेतिकडे का पाहू लागली?\",\"options\":[\"फुले शोधण्यासाठी\",\"पक्षी पाहण्यासाठी\",\"खाली उतरण्याची वाट शोधण्यासाठी\",\"मैत्रिणीला शोधण्यासाठी\"],\"answer\":2,\"explain\":\"कोठून खाली उतरता येईल का, याचा विचार करत ती इकडेतिकडे पाहू लागली.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"हिराच्या डोळ्यांसमोर सतत कोण दिसत होते?\",\"options\":[\"तिचे बाळ\",\"गडाचा दरवाजा\",\"तिचे घर\",\"गडाचे बुरुज\"],\"answer\":0,\"explain\":\"तिच्या डोळ्यांसमोर तिला तिचे बाळ दिसू लागले, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"गड उतरल्यावर हिराच्या मनात कोणती भावना होती?\",\"options\":[\"तिला खूप भीती वाटली\",\"तिला खूप आनंद झाला\",\"तिला खूप राग आला\",\"ती खूप दुःखी झाली\"],\"answer\":1,\"explain\":\"गड उतरल्यावर तिला खूप आनंद झाला, असे उताऱ्यात दिले आहे.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात हिरा कशाच्या आधाराने कडा उतरताना दिसत आहे?\",\"options\":[\"दोरीच्या आधाराने\",\"शिडीच्या आधाराने\",\"झाडाच्या फांदीच्या आधाराने\",\"पायऱ्यांच्या आधाराने\"],\"answer\":2,\"explain\":\"चित्रात हिरा झाडाची फांदी धरून कडा उतरताना दिसत आहे.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"apply\",\"figure_image\":\"12\\/071_101.jpg\"},{\"q\":\"हिरा कडा उतरताना पडली, तेव्हा तिने काय केले?\",\"options\":[\"ती तिथेच बसून रडू लागली\",\"ती उठून पुन्हा गड उतरू लागली\",\"ती मदतीसाठी ओरडू लागली\",\"ती पुन्हा वर गडावर गेली\"],\"answer\":1,\"explain\":\"ती पडत होती; पण उठून पुन्हा गड उतरत होती, असे उताऱ्यात सांगितले आहे.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात आकाशात काय दिसत आहे, ज्यावरून ही रात्रीची वेळ आहे असे समजते?\",\"options\":[\"तेजस्वी सूर्य\",\"काळे ढग\",\"पूर्ण चंद्र\",\"विजांचा कडकडाट\"],\"answer\":2,\"explain\":\"चित्रात आकाशात पूर्ण चंद्र दिसत आहे, जो रात्रीच्या वेळेचे प्रतीक आहे.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"12\\/071_101.jpg\"},{\"q\":\"हिरा कडा उतरताना \'कशीबशी\' उतरत होती, यावरून काय समजते?\",\"options\":[\"ती खूप आरामात उतरत होती\",\"ती खूप कष्टाने आणि प्रयत्नाने उतरत होती\",\"ती खेळत खेळत उतरत होती\",\"ती खूप वेगाने धावत उतरत होती\"],\"answer\":1,\"explain\":\"\'कशीबशी\' या शब्दावरून तिला कडा उतरताना खूप कष्ट पडत होते हे समजते.\",\"topic\":\"हिराचे धाडस\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"हिराने शेवटी काय करण्याचा ठाम निश्चय केला?\",\"options\":[\"गडावरच राहण्याचा\",\"काहीही करून गड उतरायचाच\",\"सकाळ होण्याची वाट पाहण्याचा\",\"कोणाची तरी मदत घेण्याचा\"],\"answer\":1,\"explain\":\"काह