\":\"understand\"},{\"q\":\"यशने दुकानदाराला ५०० रुपयांची एक नोट व २०० रुपयांची एक नोट दिली, तर त्याने एकूण किती रुपये दिले?\",\"options\":[\"५०० रुपये\",\"६०० रुपये\",\"७०० रुपये\",\"८०० रुपये\"],\"answer\":2,\"explain\":\"५०० + २०० = ७०० रुपये यशने दुकानदाराला दिले.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"७०० - ५१० या वजाबाकीत, ० दशकातून १ दशक वजा होत नाही तेव्हा काय करावे लागते?\",\"options\":[\"एकक मोकळा करणे\",\"१०० मिळवणे\",\"७ शतकातील एक शतक मोकळा करणे\",\"वजाबाकी थांबवणे\"],\"answer\":2,\"explain\":\"मजकुरानुसार, ० दशकातून १ दशक वजा होत नाही म्हणून ७ शतकातील एक शतक मोकळा केला जातो.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एक शतक मोकळा केल्यावर त्याचे किती दशक होतात?\",\"options\":[\"१ दशक\",\"१० दशक\",\"१०० दशक\",\"२० दशक\"],\"answer\":1,\"explain\":\"मजकुरात दिले आहे की एक शतक मोकळा केल्यावर त्याचे १० दशक होतात.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"७०० - ५१० या वजाबाकीचे उत्तर किती येते?\",\"options\":[\"२१०\",\"१९०\",\"११०\",\"२००\"],\"answer\":1,\"explain\":\"मजकुरात दिलेल्या हिशोबाप्रमाणे ७०० - ५१० = १९० रुपये होतात.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"५०७ - २६८ या वजाबाकीत एककाच्या घरात ७ मधून ८ वजा होत नाहीत, तेव्हा सुरुवातीला काय करावे लागते?\",\"options\":[\"१ दशक मोकळा करणे\",\"१ शतक मोकळा करून १० दशक करणे\",\"थेट शतकातून वजा करणे\",\"८ मधून ७ वजा करणे\"],\"answer\":1,\"explain\":\"दशकात काही नसल्यामुळे आधी १ शतक मोकळा करून १० दशक करावे लागतात.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"५०७ - २६८ करताना, १० दशकातील १ दशक मोकळा केल्यावर दशकाच्या घरात किती दशक उरतात?\",\"options\":[\"१० दशक\",\"८ दशक\",\"९ दशक\",\"७ दशक\"],\"answer\":2,\"explain\":\"१० दशकातील १ दशक एककासाठी मोकळा केल्यावर ९ दशक उरतात.\",\"topic\":\"वजाबाकी (हातच्याची)\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"५०७ - २६८ या वजाबाकीचे अंतिम उत्तर काय आहे?\",\"options\":[\"२३९\",\"३३९\",\"