"q\":\"एकक अपूर्णांक १\\/४ हा ४ समान भागांपैकी किती भाग दर्शवतो?\",\"options\":[\"१ भाग\",\"२ भाग\",\"३ भाग\",\"४ भाग\"],\"answer\":0,\"explain\":\"प्रत्येक भाग १\\/४ आहे, म्हणजेच तो ४ भागांपैकी १ भाग आहे.\",\"topic\":\"एकक अपूर्णांक\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, अपूर्णांक शिकवण्यासाठी खालीलपैकी कोणत्या वस्तूचा वापर करण्यास सांगितले आहे?\",\"options\":[\"लोखंडी सळई\",\"रवा\",\"काचेचे तुकडे\",\"प्लास्टिक पिशवी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात शिक्षकांसाठी दिलेल्या भागात \'रवा\' या वस्तूचा उल्लेख आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या अपूर्णांकाचा अंश हा छेदाच्या दुप्पट असेल, तर तो काय होईल?\",\"options\":[\"तो अपूर्णांकच राहील\",\"तो शून्य होईल\",\"तो पूर्ण होईल\",\"तो पाव होईल\"],\"answer\":2,\"explain\":\"अंश छेदाच्या दुप्पट असल्यास तो पूर्ण होतो, असे चर्चेसाठी विचारले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"१\\/४ हा भाग चार वेळा घेतल्यास काय तयार होईल?\",\"options\":[\"पाव\",\"अर्धा\",\"पाऊण\",\"एक पूर्ण\"],\"answer\":3,\"explain\":\"पाव भाग (१\\/४) चार वेळा घेतल्यास एक पूर्ण एकक तयार होतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"पाठ्यपुस्तकातील चर्चेनुसार, अपूर्णांकात छेद हा अंशापेक्षा नेहमी मोठाच असतो का?\",\"options\":[\"हो, नेहमीच\",\"नाही, तसे नसते\",\"फक्त पाऊण भागात\",\"फक्त अर्ध्या भागात\"],\"answer\":1,\"explain\":\"अपूर्णांकात छेद नेहमी अंशापेक्षा मोठाच असतो का, यावर चर्चा करण्यास सांगितले आहे, ज्याचा अर्थ तो नेहमी मोठा नसतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"\'निमपट\' या शब्दाचा संबंध खालीलपैकी कशाशी आहे?\",\"options\":[\"दुप्पट\",\"अर्धा\",\"पाव\",\"पाऊण\"],\"answer\":1,\"explain\":\"शिक्षकांसाठीच्या सूचनेत अर्धा, पाव, पाऊण आणि निमपट या संबंधांचा उल्लेख आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"१\\/४ हा भाग दोन वेळा घेतल्यास कोणता भाग तयार होतो?\",\"options\":[\"अर्धा\",\"पाव\",\"पाऊण\",\"पूर्ण\"],\"answer\":0,\"explain\":\"१\\/४ दोन वेळा म्हणजे २\\/४, म्हणजेच अर्धा भाग होय.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"व्यावहारिक उदाहरणे तयार करण्यासाठी विद्यार्थ्यांनी कोणाचे सहकार्य घेण्यास सुचवले आहे?\",\"options\":[\"फक्त दुकानदार\",\"अनोळखी व्यक्ती\",\"मित्र आणि पालक\",\"फक्त पोलीस\"],\"answer\":2,\"explain\":\"आवश्यकतेनुसार मित्र आणि पालक यांचे सहकार्य घेण्यास पाठ्यपुस्तकात सुचवले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"१\\/४ हा भाग पाच वेळा घेतला, तर तो अपूर्णांक कसा लिहिला जाईल?\",\"options\":[\"१\\/५\",\"५\\/४\",\"४\\/५\",\"५\\/१\"],\"answer\":1,\"explain\":\"१\\/४ पाच वेळा घेतल्यास तो ५\\/४ असा लिहिला जातो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांनी विद्यार्थ्यांना कोणत्या प्रकारचे समूह वापरून उदाहरणे सोडवण्याची संधी द्यावी?\",\"options\":[\"प्राण्यांचा समूह\",\"वस्तूंचा समूह\",\"नद्यांचा समूह\",\"गावांचा समूह\"],\"answer\":1,\"explain\":\"शिक्षकांसाठीच्या सूचनेत \'वस्तूंचा समूह\' वापरून उदाहरणे सोडवण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"१\\/४ हा भाग तीन वेळा घेतल्यास कोणता अपूर्णांक तयार होईल?\",\"options\":[\"१\\/३\",\"३\\/४\",\"४\\/३\",\"३\\/१\"],\"answer\":1,\"explain\":\"१\\/४ तीन वेळा घेतल्यास ३\\/४ (पाऊण) हा अपूर्णांक तयार होतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"ज्या अपूर्णांकांमध्ये अंशापेक्षा छेद मोठे असतात, त्यांना काय म्हणतात?\",\"options\":[\"अंशाधिक अपूर्णांक\",\"छेदाधिक अपूर्णांक\",\"समान अपूर्णांक\",\"मोठा अपूर्णांक\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, ज्या अपूर्णांकात अंशापेक्षा छेद मोठा असतो तो छेदाधिक अपूर्णांक असतो.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"ज्या अपूर्णांकांमध्ये छेदापेक्षा अंश मोठे असतात, त्यांना काय म्हणतात?\",\"options\":[\"छेदाधिक अपूर्णांक\",\"लहान अपूर्णांक\",\"अंशाधिक अपूर्णांक\",\"अंशहीन अपूर्णांक\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे, ज्या अपूर्णांकात छेदापेक्षा अंश मोठा असतो तो अंशाधिक अपूर्णांक असतो.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता अपूर्णांक \'छेदाधिक अपूर्णांक\' आहे?\",\"options\":[\"५\\/२\",\"७\\/४\",\"३\\/४\",\"१३\\/२\"],\"answer\":2,\"explain\":\"३\\/४ मध्ये अंश (३) हा छेदापेक्षा (४) लहान आहे, म्हणून तो छेदाधिक आहे.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता अपूर्णांक \'अंशाधिक अपूर्णांक\' आहे?\",\"options\":[\"१\\/२\",\"५\\/८\",\"१\\/५\",\"७\\/४\"],\"answer\":3,\"explain\":\"७\\/४ मध्ये अंश (७) हा छेदापेक्षा (४) मोठा आहे, म्हणून तो अंशाधिक आहे.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"३ वेळा १\\/४ घेतल्यास कोणता अपूर्णांक तयार होतो?\",\"options\":[\"१\\/४\",\"३\\/४\",\"४\\/३\",\"३\\/१\"],\"answer\":1,\"explain\":\"मजकुरात दिल्याप्रमाणे ३ वेळा १\\/४ = ३\\/४ होते.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"७ वेळा १\\/४ घेतल्यास मिळणारा अपूर्णांक ७\\/४ हा कोणत्या प्रकारचा आहे?\",\"options\":[\"छेदाधिक अपूर्णांक\",\"अंशाधिक अपूर्णांक\",\"समान अपूर्णांक\",\"अंशहीन अपूर्णांक\"],\"answer\":1,\"explain\":\"७\\/४ मध्ये अंश मोठा असल्याने तो अंशाधिक अपूर्णांक आहे.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"५\\/८ या अपूर्णांकात अंशापेक्षा छेद कसा आहे?\",\"options\":[\"छोटा आहे\",\"समान आहे\",\"मोठा आहे\",\"काहीच नाही\"],\"answer\":2,\"explain\":\"५\\/८ मध्ये ८ (छेद) हा ५ (अंश) पेक्षा मोठा आहे.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"मजकुरात दिलेल्या उदाहरणांप्रमाणे ४\\/४ हा कोणत्या प्रकारचा अपूर्णांक आहे?\",\"options\":[\"छेदाधिक\",\"अंशाधिक\",\"छेदहीन\",\"पूर्ण\"],\"answer\":1,\"explain\":\"मजकुरात ४\\/४ चा समावेश अंशाधिक अपूर्णांकांच्या गटात केला आहे.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"१\\/२, १\\/३, १\\/४, १\\/५ हे कोणत्या प्रकारचे अपूर्णांक आहेत?\",\"options\":[\"अंशाधिक\",\"मोठे\",\"छेदाधिक\",\"समान\"],\"answer\":2,\"explain\":\"या सर्व अपूर्णांकांत छेद अंशापेक्षा मोठे आहेत, म्हणून ते छेदाधिक आहेत.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"१५\\/२ हा अपूर्णांक अंशाधिक का आहे?\",\"options\":[\"कारण त्याचा अंश छेदापेक्षा मोठा आहे\",\"कारण त्याचा छेद अंशापेक्षा मोठा आहे\",\"कारण तो २ वेळा घेतला आहे\",\"कारण तो १\\/२ आहे\"],\"answer\":0,\"explain\":\"ज्या अपूर्णांकात छेदापेक्षा अंश मोठा असतो तो अंशाधिक असतो.\",\"topic\":\"छेदाधिक व अंशाधिक अपूर्णांक व्याख्या\",\"part\":5,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21467,14,3,'Maths','mr','लांबी व वजन','[\"लांबी मोजण्यासाठी मीटर, सेमीमीटर, पाव मीटर, अर्धा मीटर इत्यादी एकक वापरतात.\",\"एक मीटर = 100 सेमीमीटर.\",\"पाव मीटर = 50 सेमीमीटर.\",\"अर्धा मीटर = 50 सेमीमीटर.\",\"वस्तूची लांबी मोजताना तिच्या दोन टोके जोडून मोजली जाते.\",\"दोरी जोडून लांबी वाढवली जाऊ शकते, जसे की दोन अर्धा मीटरची दोरी जोडून एक मीटर बनवली जाते.\",\"वजन मोजण्यासाठी किलोग्राम, ग्राम इत्यादी एकक वापरतात.\",\"एक किलोग्राम = 1000 ग्राम.\",\"वजन तुलन्यासाठी तराजू वापरते, जिथे दोन पायरी समान होऊन वजन मोजला जातो.\",\"जड वस्तू त्यांच्या वजनामुळे खालच्या दिशेने जातात, त्यामुळे तराजूतील पायरी खाली जाते.\",\"वस्तूचे वजन अंदाजे लागवून, त्यानंतर प्रत्यक्ष मोजून खातरी केली जाते.\",\"वस्तूचे वजन जास्त असल्यास तराजूतील तिच्या पायरी खाली जाते.\",\"वस्तूचे वजन कमी असल्यास तराजूतील तिच्या पायरी वर राहते.\",\"वजन मोजताना समान वजनाची वस्तू (जसे की गोट्या) वापरली जाते, जिथे समान संख्या होऊन वजन समान मोजला जातो.\",\"वस्तूचे वजन मोजताना, तिचे वजन ज्ञात असलेली वस्तू (जसे की 1 किलोग्रामची पुडा) तुलनेसाठी वापरली जाते.\"]','[{\"q\":\"खालीलपैकी लांबी मोजण्याचे साधन कोणते नाही?\",\"options\":[\"वीत\",\"पाऊल\",\"वजनकाटा\",\"काठी\"],\"answer\":2,\"explain\":\"वीत, पाऊल आणि काठी ही लांबी मोजण्याची साधने आहेत, पण वजनकाटा वजन मोजण्यासाठी वापरतात.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"तनुश्री दरवाजाची लांबी मोजण्यासाठी कशाचा वापर करत आहे?\",\"options\":[\"वीत\",\"पेन्सिल\",\"दोरी\",\"मापनटेप\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील प्रश्नानुसार तनुश्री दरवाजाची लांबी पेन्सिलने मोजत आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"अनुज आणि रिना यांनी एकाच टेबलाची लांबी वितीने मोजल्यास ती समान का नसेल?\",\"options\":[\"टेबल खूप मोठे आहे\",\"दोघांच्या वितीची लांबी वेगळी असू शकते\",\"रिना वेगाने मोजते\",\"अनुजला मोजता येत नाही\"],\"answer\":1,\"explain\":\"प्रत्येक व्यक्तीच्या वितीचा आकार वेगवेगळा असतो, म्हणून मोजमाप समान येत नाही.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"कोणीही मोजली तरी लांबी समान येण्यासाठी खालीलपैकी काय वापरणे योग्य ठरेल?\",\"options\":[\"हात\",\"वीत\",\"मापनटेप\",\"पाऊल\"],\"answer\":2,\"explain\":\"मापनटेप हे प्रमाणित साधन असल्याने त्याने मोजलेली लांबी सर्वांसाठी समान येते.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला तुमच्या वहीची लांबी मोजायची असेल, तर पाठ्यपुस्तकातील चर्चेनुसार तुम्ही कोणते अप्रमाणित साधन वापरू शकता?\",\"options\":[\"पेन्सिल\",\"वजन\",\"लिटर\",\"घड्याळ\"],\"answer\":0,\"explain\":\"पेन्सिल हे लांबी मोजण्याचे एक अप्रमाणित साधन आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"वीत, हात आणि पाऊल यांना \'अप्रमाणित\' साधने का म्हणतात?\",\"options\":[\"ती लोखंडी असतात\",\"ती प्रत्येक व्यक्तीनुसार बदलू शकतात\",\"ती फक्त शाळेत वापरतात\",\"ती खूप महाग असतात\"],\"answer\":1,\"explain\":\"व्यक्ती बदलली की हात, वीत किंवा पाऊल यांचे माप बदलते, म्हणून त्यांना अप्रमाणित म्हणतात.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात, फळ्याची लांबी मोजण्यासाठी कोणता मुलगा मापनटेप वापरत आहे?\",\"options\":[\"श्याम\",\"अर्णव\",\"अनुज\",\"रिना\"],\"answer\":1,\"explain\":\"चित्रात अर्णव फळ्यापाशी उभा राहून मापनटेपने लांबी मोजताना दिसत आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"14\\/059_101.jpg\"},{\"q\":\"दिलेल्या चित्राचे निरीक्षण करा. खिडकीची लांबी मोजण्यासाठी श्याम कशाचा वापर करत आहे?\",\"options\":[\"वितीचा\",\"काठीचा\",\"पेन्सिलचा\",\"मापनटेपचा\"],\"answer\":0,\"explain\":\"चित्रात श्याम खिडकीच्या बाजूला हात लावून वितीने मोजताना दिसत आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"14\\/059_101.jpg\"},{\"q\":\"पाठ्यपुस्तकातील चर्चेनुसार, अर्णव कशाची लांबी मोजत आहे?\",\"options\":[\"खिडकी\",\"दरवाजा\",\"फळा\",\"टेबल\"],\"answer\":2,\"explain\":\"मजकुरात प्रश्न ५ मध्ये विचारले आहे की अर्णव फळ्याची लांबी कशाने मोजत आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'वीत\' हे लांबी मोजण्याचे साधन कोणत्या प्रकारचे आहे?\",\"options\":[\"प्रमाणित\",\"अप्रमाणित\",\"वजन मोजण्याचे\",\"वेळ मोजण्याचे\"],\"answer\":1,\"explain\":\"शिक्षकांसाठी दिलेल्या टीपमध्ये वीत हे अप्रमाणित साधन असल्याचे म्हटले आहे.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर दोन मित्रांनी एकाच दोरीची लांबी आपापल्या हाताने मोजली, तर काय होईल?\",\"options\":[\"लांबी नेहमी सारखीच येईल\",\"दोघांनी मोजलेली लांबी वेगवेगळी असू शकते\",\"दोरीची लांबी आपोआप वाढेल\",\"दोरीची लांबी कमी होईल\"],\"answer\":1,\"explain\":\"व्यक्तीनुसार हाताची लांबी वेगळी असल्याने मोजमाप वेगवेगळे येईल.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"अचूक मापनासाठी मापनटेप वापरणे का सोयीचे आहे?\",\"options\":[\"तो दिसायला छान असतो\",\"तो लांब असतो\",\"त्याने मोजलेली लांबी कोणीही मोजली तरी समान येते\",\"तो फक्त शिक्षक वापरतात\"],\"answer\":2,\"explain\":\"मापनटेपमुळे लांबीमध्ये फरक पडत नाही, ती सर्वांसाठी समान राहते.\",\"topic\":\"लांबी मोजणे\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"कापड मोजण्यासाठी दुकानदार कशाचा वापर करतात?\",\"options\":[\"दोरी\",\"मीटरपट्टी\",\"हात\",\"वीत\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, कापड मोजण्यासाठी दुकानदार नेहमी मीटरपट्टीचा वापर करतात.\",\"topic\":\"मीटरपट्टीने मोजणी\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"लांबी मोजण्याचे प्रमाणित एकक कोणत