[\"सेंटीमीटर, मीटर, किलोमीटर\",\"पाव, अर्धा आणि एक मीटर\",\"हात, वीत आणि पाऊल\",\"लहान, मध्यम आणि मोठी\"],\"answer\":1,\"explain\":\"चित्रातील तक्त्यात पाव मीटर, अर्धा मीटर आणि एक मीटरपेक्षा कमी किंवा जास्त असे रकाने दिले आहेत.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"14\\/061_103.jpg\"},{\"q\":\"जर एखादी वस्तू अर्ध्या मीटरपेक्षा जास्त लांब असेल, तर ती वस्तू पाव मीटरपेक्षा कशी असेल?\",\"options\":[\"कमी\",\"तेवढीच\",\"जास्त\",\"सांगता येणार नाही\"],\"answer\":2,\"explain\":\"अर्धा मीटर हा पाव मीटरपेक्षा मोठा असतो, म्हणून अर्ध्या मीटरपेक्षा जास्त असलेली वस्तू पाव मीटरपेक्षाही जास्तच असेल.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील तक्त्यानुसार, वस्तूची लांबी मोजल्यानंतर कोणती खूण करायची आहे?\",\"options\":[\"X अशी खूण\",\"गोल खूण\",\"✓ अशी खूण\",\"टिंब\"],\"answer\":2,\"explain\":\"तक्त्यात योग्य चौकटीमध्ये ✓ अशी खूण करण्यास सांगितले आहे.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"14\\/061_103.jpg\"},{\"q\":\"एक मीटर लांबीच्या दोरीचे समान दोन भाग केले, तर प्रत्येक भागाची लांबी किती असेल?\",\"options\":[\"पाव मीटर\",\"अर्धा मीटर\",\"एक मीटर\",\"पाऊण मीटर\"],\"answer\":1,\"explain\":\"एक मीटरचे दोन समान भाग म्हणजे अर्धा मीटर होय.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"तुमच्याकडे अर्धा मीटरची दोरी आहे, तुम्हाला पाव मीटर लांबी मोजायची असेल तर तुम्ही काय कराल?\",\"options\":[\"दोरी तशीच वापरू\",\"दोरीची दोन्ही टोके जुळवून अर्धी करू\",\"दोन दोऱ्या जोडू\",\"दोरी फेकून देऊ\"],\"answer\":1,\"explain\":\"अर्ध्या मीटरची टोके जुळवली की पाव मीटर तयार होतो, हे मजकुरात दिले आहे.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खिडकीची लांबी मोजताना ती एक मीटरपेक्षा जास्त भरली, तर तुम्ही तक्त्यात कुठे खूण कराल?\",\"options\":[\"एक मीटरपेक्षा कमी\",\"अर्धा मीटरपेक्षा कमी\",\"एक मीटरपेक्षा जास्त\",\"पाव मीटरपेक्षा कमी\"],\"answer\":2,\"explain\":\"वस्तूची लांबी ज्या मापापेक्षा जास्त असेल, त्या \'जास्त\' असलेल्या रकान्यात खूण करावी लागते.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांनी सांगितल्याप्रमाणे, पाव मीटरचे चारही समान भाग एकावर एक जोडून लांबी मोजली, तर ती किती भरेल?\",\"options\":[\"अर्धा मीटर\",\"पाव मीटर\",\"एक मीटर\",\"दोन मीटर\"],\"answer\":2,\"explain\":\"पाव मीटरचे चार भाग एकत्र केल्यास मूळ एक मीटर लांबीची दोरी तयार होते.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर एखादी वस्तू पाव मीटरपेक्षाही \'कमी\' लांबीची असेल, तर ती अर्ध्या मीटरपेक्षा कशी असेल?\",\"options\":[\"जास्त\",\"कमी\",\"तेवढीच\",\"खूप जास्त\"],\"answer\":1,\"explain\":\"पाव मीटर हा अर्ध्या मीटरपेक्षा लहान असतो, त्यामुळे पाव मीटरपेक्षा कमी असलेली वस्तू अर्ध्या मीटरपेक्षाही कमीच असेल.\",\"topic\":\"एक मीटरचा पाव, अर्धा, पाऊण भाग\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जड वस्तू त्यांच्या वजनामुळे कोणत्या दिशेने जातात?\",\"options\":[\"वरच्या दिशेने\",\"खालच्या दिशेने\",\"बाजूच्या दिशेने\",\"स्थिर राहतात\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील शिक्षकांसाठी दिलेल्या टीपेनुसार, जड वस्तू वजनामुळे खालच्या दिशेने जातात.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अनुजा आणि मीना यांनी एकाच वहीचे वजन केले असता गोट्यांच्या संख्येत फरक का पडला असावा?\",\"options\":[\"वही बदलली होती\",\"गोट्यांचा आकार वेगळा होता\",\"तराजू खराब होता\",\"मुलींची नावे वेगळी होती\"],\"answer\":1,\"explain\":\"गोट्यांचा आकार आणि त्या कशाने बनल्या आहेत यावर त्यांची संख्या अवलंबून असते.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर अनुजाने वापरलेल्या गोट्याच वापरून दुसऱ्या मुलाने त्याच वहीचे वजन केले, तर वजनात फरक पडेल का?\",\"options\":[\"हो, खूप फरक पडेल\",\"नाही, फरक पडणार नाही\",\"कदाचित पडेल\",\"सांगता येणार नाही\"],\"answer\":1,\"explain\":\"वस्तू आणि मोजण्याचे साधन (गोट्या) तेच राहिल्यास वजनात फरक पडत नाही.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"वस्तूंचे वजन करण्यासाठी पाठ्यपुस्तकात कोणते साधन वापरण्यास सांगितले आहे?\",\"options\":[\"पट्टी\",\"दोरी\",\"तराजू\",\"पेन्सिल\"],\"answer\":2,\"explain\":\"वस्तूंचे वजन करण्यासाठी तराजू वापरण्याचा अनुभव देण्यास सांगितले आहे.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"क्रिकेटची बॅट ही क्रिकेटच्या चेंडूच्या तुलनेत कशी असते?\",\"options\":[\"हलकी\",\"जड\",\"समान वजनाची\",\"खूपच लहान\"],\"answer\":1,\"explain\":\"सामान्य अनुभवानुसार आणि पाठ्यपुस्तकातील तक्त्यानुसार बॅट चेंडूपेक्षा जड असते.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"तराजूची दोन्ही पारडी समान होणे म्हणजे काय?\",\"options\":[\"एका बाजूचे वजन वाढणे\",\"दोन्ही बाजूंचे वजन सारखे होणे\",\"तराजू तुटणे\",\"वजन मोजता न येणे\"],\"answer\":1,\"explain\":\"जेव्हा दोन्ही पारडी एकाच पातळीवर येतात, तेव्हा वजन समान असते.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"मीनाला वहीचे वजन करण्यासाठी किती गोट्या लागल्या?\",\"options\":[\"१५ गोट्या\",\"१० गोट्या\",\"२० गोट्या\",\"२५ गोट्या\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील तक्त्यानुसार मीनाला २० गोट्या लागल्या.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"गोट्या कोणत्या पदार्थांपासून बनलेल्या असू शकतात, ज्याचा उल्लेख पाठात आला आहे?\",\"options\":[\"काच किंवा शिसे\",\"प्लास्टिक किंवा लाकूड\",\"कापूस किंवा कागद\",\"रबर किंवा माती\"],\"answer\":0,\"explain\":\"पाठात गोट्या काच किंवा शिसे यांपासून बनलेल्या असू शकतात असा उल्लेख आहे.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एका वहीचे वजन १५ गोट्या असेल, तर त्यापेक्षा जड असलेल्या पुस्तकाचे वजन करण्यासाठी किती गोट्या लागतील?\",\"options\":[\"१५ पेक्षा कमी\",\"नेमक्या १५\",\"१५ पेक्षा जास्त\",\"एकही नाही\"],\"answer\":2,\"explain\":\"वस्तू जड असल्यास ती तोलण्यासाठी जास्त गोट्यांची गरज भासते.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अनुजाला १५ गोट्या लागल्या आणि मीनाला २० गोट्या लागल्या, तर कोणाच्या गोट्या आकाराने मोठ्या असतील?\",\"options\":[\"मीनाच्या\",\"अनुजाच्या\",\"दोघींच्या सारख्याच\",\"सांगता येणार नाही\"],\"answer\":1,\"explain\":\"कमी गोट्या लागल्या याचा अर्थ अनुजाच्या गोट्या आकाराने किंवा वजनाने मोठ्या होत्या.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"वजन करण्यासाठी प्रत्येकाने वेगवेगळ्या आकाराच्या किती गोट्या घ्याव्यात?\",\"options\":[\"५ ते १०\",\"१५ ते २०\",\"५० ते १००\",\"१ ते ५\"],\"answer\":1,\"explain\":\"पाठातील कृतीमध्ये १५ ते २० गोट्या घेण्यास सांगितले आहे.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दप्तराच्या तुलनेत जेवणाचा डबा कसा असतो?\",\"options\":[\"जड\",\"हलका\",\"मोठा\",\"समान वजनाचा\"],\"answer\":1,\"explain\":\"दप्तरात अनेक वस्तू असल्याने जेवणाचा डबा त्यापेक्षा हलका असतो.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या पहिल्या तक्त्यानुसार, शेवटच्या ओळीत बॅटची तुलना कशासोबत केली आहे?\",\"options\":[\"चेंडू\",\"दप्तर\",\"वही\",\"डबा\"],\"answer\":2,\"explain\":\"तक्त्यातील शेवटच्या ओळीत \'बॅटपेक्षा वही जड\\/हलकी आहे\' असे दिले आहे.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"14\\/063_101.jpg\"},{\"q\":\"दिलेल्या तक्त्यात अनुजाच्या नावासमोर वहीचे वजन किती गोट्या नोंदवले आहे?\",\"options\":[\"१० गोट्या\",\"१५ गोट्या\",\"२० गोट्या\",\"५ गोट्या\"],\"answer\":1,\"explain\":\"तक्त्यामध्ये अनुजाच्या समोर १५ गोट्या असे स्पष्ट लिहिले आहे.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"14\\/063_103.jpg\"},{\"q\":\"दिलेल्या चित्रात, जर वही असलेले पारडे गोट्यांच्या पारड्यापेक्षा खाली झुकले असेल, तर त्याचा अर्थ काय?\",\"options\":[\"वही गोट्यांपेक्षा हलकी आहे\",\"वही गोट्यांपेक्षा जड आहे\",\"दोन्हीचे वजन सारखे आहे\",\"तराजू रिकामा आहे\"],\"answer\":1,\"explain\":\"तराजूचे जे पारडे खाली झुकते, त्यातील वस्तू जड असते.\",\"topic\":\"वजनाची तुलना\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"14\\/063_102.jpg\"},{\"q\":\"वजन मोजण्याचे प्रमाणित एकक कोणते आहे?\",\"options\":[\"मीटर\",\"लिटर\",\"किलोग्रॅम\",\"सेंटीमीटर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, किलोग्रॅम हे वजन मोजण्याचे प्रमाणित एकक आहे.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"१ किलोग्रॅम म्हणजे किती ग्रॅम?\",\"options\":[\"१०० ग्रॅम\",\"५०० ग्रॅम\",\"१० ग्रॅम\",\"१००० ग्रॅम\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकात स्पष्ट दिले आहे की १ किलोग्रॅम = १००० ग्रॅम.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"एकाच वस्तूचे वजन एकाच मापाच्या साहाय्याने वेगवेगळ्या व्यक्तींनी केले, तर ते कसे भरेल?\",\"options\":[\"समान भरेल\",\"वेगवेगळे भरेल\",\"कमी भरेल\",\"जास्त भरेल\"],\"answer\":0,\"explain\":\"एकाच वस्तूचे वजन एकाच मापाच्या साहाय्याने कोणीही केले तरी ते समानच भरते.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दैनंदिन व्यवहारात वस्तूचे वजन मोजण्यासाठी काय वापरले जाते?\",\"options\":[\"दोरी\",\"प्रमाणित मापे\",\"हात\",\"पट्टी\"],\"answer\":1,\"explain\":\"दैनंदिन व्यवहारात वस्तूचे वजन मोजण्यासाठी प्रमाणित मापे वापरली जातात.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जर एका मिठाच्या पुड्याचे वजन १ किलोग्रॅम असेल, तर त्याचे वजन ग्रॅममध्ये किती असेल?\",\"options\":[\"१०० ग्रॅम\",\"५०० ग्रॅम\",\"१००० ग्रॅम\",\"२५० ग्रॅम\"],\"answer\":2,\"explain\":\"१ किलोग्रॅम म्हणजे १००० ग्रॅम, म्हणून १ किलो मिठाचे वजन १००० ग्रॅम असेल.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात वजन मोजण्यासाठी कोणते साधन दाखवले आहे?\",\"options\":[\"पट्टी\",\"तराजू\",\"घड्याळ\",\"तापमापी\"],\"answer\":1,\"explain\":\"चित्रात वजन मोजण्यासाठी वापरला जाणारा तराजू दाखवला आहे.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"14\\/064_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील साधनाचा वापर कशासाठी केला जातो?\",\"options\":[\"लांबी मोजण्यासाठी\",\"वेळ पाहण्यासाठी\",\"वजन मोजण्यासाठी\",\"दूध मोजण्यासाठी\"],\"answer\":2,\"explain\":\"तराजू हे वजन मोजण्याचे एक साधन आहे.\",\"topic\":\"वजन\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"14\\/064_101.jpg\"},{\"q\":\"वजन मोजताना अचूकता येण्यासाठी कश