om\":\"analyze\"},{\"q\":\"भागाकार चिन्हाचा उपयोग करून भागाकार करताना, ज्या संख्येला भागले जाते त्या \'भाज्य\' संख्येला कोठे लिहिले जाते?\",\"options\":[\"चिन्हाच्या डावीकडे\",\"चिन्हाच्या पिवळ्या भागात (आत)\",\"चिन्हाच्या वर\",\"चिन्हाच्या खाली\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, भागाकार चिन्हाचा उपयोग करताना भाज्य पिवळ्या भागात (आत) लिहावा.\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"भागाकार चिन्हाच्या डावीकडे कोणती संख्या लिहिली जाते?\",\"options\":[\"भाज्य\",\"बाकी\",\"भागाकार\",\"भाजक\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकात स्पष्ट केले आहे की डावीकडे भाजक लिहावा.\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"भागाकार म्हणजे वस्तूंची किंवा संख्यांची केलेली कोणती क्रिया होय?\",\"options\":[\"समान वाटणी करणे\",\"एकत्र करणे\",\"दुप्पट करणे\",\"गुणाकार करणे\"],\"answer\":0,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, भागाकार म्हणजे समान वाटणी करणे होय.\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"आजीकडे ७५ रुपये आहेत आणि तिला प्रत्येकाला १५ रुपये द्यायचे आहेत, तर हा व्यवहार कोणत्या भागाकाराशी संबंधित आहे?\",\"options\":[\"७५ ÷ १५\",\"७५ ÷ ५\",\"१५ ÷ ५\",\"७५ ÷ १०\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात ७५ रुपयांची प्रत्येकाला १५ याप्रमाणे वाटणी ७५ ÷ ५ या भागाकाराशी जोडण्यास सांगितले आहे.\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"२४ ÷ ४ या भागाकाराचे उत्तर काय येईल?\",\"options\":[\"४\",\"५\",\"६\",\"८\"],\"answer\":2,\"explain\":\"४ चा पाढा ६ पर्यंत म्हटल्यास २४ येतात (४ × ६ = २४).\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"३९ ÷ ५ हा भागाकार केल्यास बाकी किती उरेल?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":3,\"explain\":\"५ × ७ = ३५ आणि ३९ - ३५ = ४, म्हणून बाकी ४ उरेल.\",\"topic\":\"विचार करा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात \'बंदे\' या रकान्यात १० रुपयांची एकूण किती नाणी दाखवली आहेत?\",\"options\":[\"१\",\"२\",\"४\",\"१०\"],\"answer\":1,\"explain\":\"चित्रात \'बंदे\' भागात १० रु