:\"14\\/117_103.jpg\"},{\"q\":\"महाराष्ट्रातील कोणत्या ठिकाणी नक्षींमध्ये अप्रतिम सममिती पाहायला मिळते?\",\"options\":[\"फक्त नवीन कारखाने\",\"प्राचीन लेणी आणि वास्तू\",\"फक्त आधुनिक रस्ते\",\"फक्त बाजारपेठा\"],\"answer\":1,\"explain\":\"महाराष्ट्रातील प्रसिद्ध लेणी आणि प्राचीन वास्तूंमध्ये सममिती पाहायला मिळते.\",\"topic\":\"सममित आकार फिरवणे\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"सममित अक्षाच्या दुसऱ्या बाजूची प्रतिमा पूर्ण केल्यावर काय करता येते?\",\"options\":[\"आकार ओळखून चित्र पूर्ण करता येते\",\"चित्र खोडून टाकता येते\",\"कागद फाडता येतो\",\"रंग बदलता येतो\"],\"answer\":0,\"explain\":\"प्रतिमा पूर्ण करून त्यामध्ये कोणता आकार लपला आहे हे ओळखून चित्र पूर्ण करता येते.\",\"topic\":\"सममित आकार फिरवणे\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"ताजमहाल आणि बिबीका मकबरा यांसारख्या वास्तू गणितातील कोणत्या संकल्पनेची उदाहरणे आहेत?\",\"options\":[\"फक्त भागाकार\",\"सममिती\",\"फक्त गुणाकार\",\"फक्त वजन\"],\"answer\":1,\"explain\":\"या प्राचीन वास्तू नक्षींमधील अप्रतिम सममितीची उदाहरणे आहेत.\",\"topic\":\"सममित आकार फिरवणे\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला एखादा आकार \'प्रतिघटीवत्\' फिरवायचा असेल, तर तुम्ही तो कसा फिरवाल?\",\"options\":[\"घड्याळाच्या काट्याच्या दिशेने\",\"घड्याळाच्या काट्याच्या विरुद्ध दिशेने\",\"वरच्या दिशेने\",\"खालच्या दिशेने\"],\"answer\":1,\"explain\":\"प्रतिघटीवत् म्हणजे घड्याळाच्या काट्यांच्या विरुद्ध दिशा होय.\",\"topic\":\"सममित आकार फिरवणे\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"सममित आकार घड्याळाच्या काट्यांच्या दिशेने फिरवल्यास काय होते?\",\"options\":[\"आकार मोठा होतो\",\"आकारात बदल होत नाही\",\"आकार लहान होतो\",\"आकार पूर्णपणे बदलतो\"],\"answer\":1,\"explain\":\"दिलेल्या मजकुराप्रमाणे, सममित आकार फिरवल्यास त्यात बदल होत नाही.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"सममित आकार कोणत्या दिशेने फिरवता येतो?\",\"options\":[\"फक्त वरच्या दिशेने\",\"फक्त खालच्या दिशेने\",\"घड्याळाच्या काट्यांच्या दिशेने किंवा विरुद्ध दिशेने\",\"फक्त डाव्या दिशेने\"],\"answer\":2,\"explain\":\"मजकु