mage\":\"16\\/021_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील मातीचा उपयोग प्रामुख्याने कशासाठी केला जातो?\",\"options\":[\"रस्ते बनवण्यासाठी\",\"पाणी झिरपवण्यासाठी\",\"विविध वस्तू तयार करण्यासाठी\",\"वाळू काढण्यासाठी\"],\"answer\":2,\"explain\":\"चित्रात चिकणमाती दिसत आहे, जिचा उपयोग वस्तू तयार करण्यासाठी व पिकांच्या वाढीसाठी होतो.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"16\\/021_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील माती कशाच्या मिश्रणातून तयार झाली आहे?\",\"options\":[\"केवळ वाळू आणि दगड\",\"केवळ गाळ आणि पाणी\",\"वालुकामय माती, चिकणमाती आणि गाळ\",\"लाल माती आणि काळी माती\"],\"answer\":2,\"explain\":\"चित्रात पोयटा माती दिसत आहे, जी वालुकामय माती, चिकणमाती आणि गाळ यांच्या मिश्रणातून तयार होते.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"16\\/021_103.jpg\"},{\"q\":\"जर एखाद्या मातीतून पाणी लगेच झिरपून जात असेल आणि ती लवकर कोरडी होत असेल, तर ती कोणत्या प्रकारची माती आहे?\",\"options\":[\"चिकणमाती\",\"पोयटा माती\",\"वालुकामय माती\",\"काळी माती\"],\"answer\":2,\"explain\":\"वालुकामय मातीतून पाणी लगेच झिरपते आणि ती लवकर कोरडी होते.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"कुंभारकाम करण्यासाठी किंवा मातीच्या मूर्ती बनवण्यासाठी कोणत्या प्रकारची माती सर्वात योग्य ठरेल?\",\"options\":[\"वालुकामय माती\",\"चिकणमाती\",\"डोंगराळ माती\",\"पीठ माती\"],\"answer\":1,\"explain\":\"चिकणमाती चिकट व मऊ असते, त्यामुळे तिचा उपयोग विविध वस्तू तयार करण्यासाठी होतो.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"पोयटा माती पिकांच्या वाढीसाठी चांगली का मानली जाते?\",\"options\":[\"कारण ती खूप लवकर कोरडी होते.\",\"कारण ती पाणी धरून ठेवते व ओलावा टिकवते.\",\"कारण ती फक्त वाळूपासून बनलेली असते.\",\"कारण ती खूप कडक असते.\"],\"answer\":1,\"explain\":\"पोयटा माती पाणी धरून ठेवते, ज्यामुळे जमिनीतील ओलावा राहतो आणि पिकांची वाढ चांगली होते.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"एका शेतकऱ्याला त्याच्या शेतात अशी माती हवी आहे जिचे कण एकमेकांना घट्ट चिकटलेले असतील, तर त्याने कोणती माती निवडावी?\",\"options\":[\"वालुकामय माती\",\"पोयटा माती\",\"चिकणमाती\",\"डोंगराळ माती\"],\"answer\":2,\"explain\":\"चिकणमातीचे कण खूप लहान व एकमेकांना घट्ट चिकटलेले असतात.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मातीचे संवर्धन करणे का गरजेचे आहे, यावर विचार करून योग्य कारण निवडा.\",\"options\":[\"कारण माती सहज उपलब्ध असते.\",\"कारण मातीचा सुपीक थर तयार होण्यास खूप वर्षे लागतात.\",\"कारण मातीचा रंग बदलत असतो.\",\"कारण माती फक्त महाराष्ट्रातच आढळते.\"],\"answer\":1,\"explain\":\"माती तयार होण्यास खूप वर्षे लागतात आणि तिचा वरचा थर सुपीक असतो, म्हणून तिचे संरक्षण करणे गरजेचे आहे.\",\"topic\":\"माती संवर्धन आणि मातीचे प्रकार\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"मातीची सुपीकता कमी होणे आणि ती दूषित होणे या प्रक्रियेला काय म्हणतात?\",\"options\":[\"हवा प्रदूषण\",\"जल प्रदूषण\",\"माती प्रदूषण\",\"ध्वनी प्रदूषण\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, मातीची सुपीकता कमी होऊन ती दूषित होण्याला माती प्रदूषण म्हणतात.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मातीची सुपीकता प्रामुख्याने कशामुळे कमी होते?\",\"options\":[\"सेंद्रिय खतांच्या वापरामुळे\",\"रासायनिक खतांच्या अतिवापरामुळे\",\"झाडे लावल्यामुळे\",\"पाऊस पडल्यामुळे\"],\"answer\":1,\"explain\":\"रासायनिक खते आणि कीटकनाशके यांच्या अतिवापरामुळे मातीची सुपीकता कमी होते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"शेतात मातीचे आरोग्य टिकवण्यासाठी रासायनिक खतांऐवजी कशाचा वापर केला पाहिजे?\",\"options\":[\"प्लास्टिक कचरा\",\"सेंद्रिय खते\",\"कारखान्यातील विषारी पदार्थ\",\"कीटकनाशके\"],\"answer\":1,\"explain\":\"माती प्रदूषण रोखण्यासाठी शेतात रासायनिक खतांऐवजी सेंद्रिय खतांचा वापर करणे आवश्यक आहे.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"सेंद्रिय खत तयार करण्यासाठी खालीलपैकी कोणत्या घटकाचा वापर केला जातो?\",\"options\":[\"काच आणि लोखंड\",\"प्लास्टिक आणि रबर\",\"जनावरांचे मलमूत्र आणि पालापाचोळा\",\"कारखान्यातील रसायने\"],\"answer\":2,\"explain\":\"सेंद्रिय खत जनावरांचे मलमूत्र आणि कुजलेला पालापाचोळा यांपासून तयार केले जाते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"कारखान्यातील विषारी पदार्थ मातीत मिसळल्यास काय परिणाम होतो?\",\"options\":[\"माती अधिक सुपीक होते\",\"माती दूषित होते\",\"मातीचा रंग बदलतो\",\"मातीचे प्रमाण वाढते\"],\"answer\":1,\"explain\":\"कारखान्यातील विषारी पदार्थ आणि कचरा मातीत मिसळल्यामुळे माती दूषित होते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता घटक माती प्रदूषणास कारणीभूत ठरत नाही?\",\"options\":[\"कीटकनाशके\",\"कचरा\",\"कुजलेला पालापाचोळा\",\"विषारी पदार्थ\"],\"answer\":2,\"explain\":\"कुजलेला पालापाचोळा सेंद्रिय खत तयार करण्यासाठी वापरला जातो, तो प्रदूषक नाही.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात दाखवल्याप्रमाणे कचऱ्याचे ढीग मातीत साचल्यास काय होईल?\",\"options\":[\"मातीची सुपीकता वाढेल\",\"मातीचे प्रदूषण होईल\",\"झाडे वेगाने वाढतील\",\"माती स्वच्छ होईल\"],\"answer\":1,\"explain\":\"चित्रात दाखवल्याप्रमाणे कचरा मातीत मिसळल्यामुळे माती प्रदूषण होते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"16\\/022_104.jpg\"},{\"q\":\"दिलेल्या चित्रातील टँकरमधून कारखान्यातील कोणते पदार्थ सांडल्यास माती दूषित होऊ शकते?\",\"options\":[\"पिण्याचे पाणी\",\"विषारी पदार्थ\",\"फळांचा रस\",\"सेंद्रिय खत\"],\"answer\":1,\"explain\":\"कारखान्यातील विषारी पदार्थ मातीत मिसळल्याने माती दूषित होते, असे चित्रावरून स्पष्ट होते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"remember\",\"figure_image\":\"16\\/022_105.jpg\"},{\"q\":\"दिलेल्या चित्रात शेतकरी पिकांवर कशाची फवारणी करत आहे, ज्याच्या अतिवापरामुळे मातीचे प्रदूषण होऊ शकते?\",\"options\":[\"शुद्ध पाणी\",\"कीटकनाशके\",\"दूध\",\"सेंद्रिय खत\"],\"answer\":1,\"explain\":\"चित्रात शेतकरी कीटकनाशकांची फवारणी करत आहे, ज्याच्या अतिवापरामुळे माती दूषित होते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"apply\",\"figure_image\":\"16\\/022_102.jpg\"},{\"q\":\"माती प्रदूषण रोखण्यासाठी आपण कोणती मुख्य दक्षता घेतली पाहिजे?\",\"options\":[\"जास्त कीटकनाशके वापरणे\",\"कचरा मातीत टाकणे\",\"हानिकारक पदार्थ मातीत मिसळू न देणे\",\"रासायनिक खते वापरणे\"],\"answer\":2,\"explain\":\"विषारी पदार्थ आणि कचरा मातीत मिसळणार नाही याची दक्षता घेतल्यास माती प्रदूषण रोखता येते.\",\"topic\":\"माती प्रदूषण\",\"part\":9,\"bloom\":\"understand\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21478,16,4,'EVS Part 1','mr','आपले शरीर','[\"पाणी निर्धोक करणे म्हणजे पाण्यापासून गंदगी व जंतू काढून स्वच्छ करणे.\",\"पाणी निर्धोक करण्याची पद्धती: गाळणे, निवळणे, उकळणे, निर्जंतुकीकरण.\",\"गाळणे म्हणजे पाण्याने कपडा किंवा गाळणीने गाळून घेणे, ज्यामुळे मातीचे कण वेगळा होतो.\",\"निवळणे म्हणजे पाण्यात तुरटी फिरवून मातीचे कण तळाशी जाणे.\",\"उकळणे म्हणजे पाण्याला १० ते १५ मिनिटे उकळून जंतू नष्ट करणे.\",\"निर्जंतुकीकरण म्हणजे पाण्यात ब्लिचिंग पावडर किंवा क्लोरीन टाकून जंतू नष्ट करणे.\",\"निर्धोक पाणी म्हणजे कोणत्याही प्रकारे धोका न देणारा पाणी.\",\"निर्धोक पाणी पिण्यासाठी स्वच्छ व सुरक्षित असतो, ज्यामुळे पोटदुखी, जुलाब टाळता येतात.\",\"पाण्याचा पुनर्वापर म्हणजे वापरलेले पाणी पुन्हा वापरणे, जसे धुतले पाणी झाडांना देणे.\",\"पावसाच्या पाण्याचे संवर्धन म्हणजे पावसाचे पाणी साठवून जमिनीतील पाण्याची पातळी वाढवणे.\",\"पावसाचे पाणी संवर्धन करण्यासाठी शेततळी खोदली जातात व डोंगर उतारावर चर खणले जातात.\",\"माती तयार होण्यासाठी खूप वर्षे लागतात, म्हणून तिचे संरक्षण करणे आवश्यक आहे.\",\"वालुकामय मातीत वाळू जास्त असतो, पाणी लगेच झिरपून जाते, माती लवकर कोरडी होते.\",\"चिकणमाती खूप चिकट व मऊ असते, पाणी सहज धरून ठेवते, पिकांच्या वाढीसाठी वापरली जाते.\",\"पोयटा माती वालुकामय, चिकणमाती व गाळ यांचे मिश्रण आहे, पाणी धरून ठेवते, ओलावा राहतो.\"]','[{\"q\":\"शरीराच्या बाहेरील बाजूस असणाऱ्या अवयवांना काय म्हणतात?\",\"options\":[\"आंतरेंद्रिये\",\"बाह्येंद्रिये\",\"कर्मेंद्रिये\",\"ज्ञानेंद्रिये\"],\"answer\":1,\"explain\":\"पाठात स्पष्ट केले आहे की शरीराच्या बाहेरील बाजूस असणाऱ्या अवयवांना बाह्य अवयव किंवा बाह्येंद्रिये म्हणतात.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"वस्तू उचलणे, चालणे आणि धावणे यांसारखी कामे करण्यासाठी आपण कोणाचा उपयोग करतो?\",\"options\":[\"नाक आणि कान\",\"डोळे आणि जीभ\",\"हात आणि पाय\",\"त्वचा आणि डोळे\"],\"answer\":2,\"explain\":\"दैनंदिन कामे करण्यासाठी आपण हातांचा व पायांचा उपयोग करतो.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"हात आणि पाय यांना \'कर्मेंद्रिये\' का म्हणतात?\",\"options\":[\"ते शरीराच्या आत असतात म्हणून\",\"त्यांच्यामुळे आपल्याला वासाची जाणीव होते म्हणून\",\"त्यांच्या मदतीने आपण विविध कामे व हालचाली करतो म्हणून\",\"ते फक्त पाहण्यासाठी उपयोगी पडतात म्हणून\"],\"answer\":2,\"explain\":\"काम करण्यासाठी (कर्म करण्यासाठी) हातापायांचा उपयोग होतो, म्हणून त्यांना कर्मेंद्रिये म्हणतात.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"ज्या इंद्रियांच्या मदतीने आपल्याला आजूबाजूच्या परिस्थितीची जाणीव होते, त्यांना काय म्हणतात?\",\"options\":[\"कर्मेंद्रिये\",\"ज्ञानेंद्रिये\",\"स्नायू\",\"हाडे\"],\"answer\":1,\"explain\":\"आजूबाजूच्या परिस्थितीचे ज्ञान करून देणाऱ्या इंद्रियांना ज्ञानेंद्रिये म्हणतात.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते इंद्रिय हे ज्ञानेंद्रिय आहे?\",\"options\":[\"हात\",\"पाय\",\"जीभ\",\"केस\"],\"answer\":2,\"explain\":\"पाठात दिलेल्या माहितीनुसार जीभ हे एक ज्ञानेंद्रिय आहे.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"डोळे, कान, नाक आणि त्वचा ही ज्ञानेंद्रिये खालीलपैकी कोणत्या प्रकारातही मोडतात?\",\"options\":[\"केवळ आंतरेंद्रिये\",\"बाह्येंद्रिये\",\"केवळ कर्मेंद्रिये\",\"हाडे\"],\"answer\":1,\"explain\":\"ही ज्ञानेंद्रिये शरीराच्या बाहेरील बाजूस असल्याने ती बाह्येंद्रियेदेखील आहेत.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला गरम वस्तूचा स्पर्श जाणवला, तर तुम्ही कोणत्या ज्ञानेंद्रियाचा वापर केला आहे?\",\"options\":[\"नाक\",\"कान\",\"त्वचा\",\"डोळे\"],\"answer\":2,\"explain\":\"स्पर्शाची जाणीव त्वचा या ज्ञानेंद्रियामुळे होते.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात, मुलगा फुलाचा वास घेण्यासाठी कोणत्या ज्ञानेंद्रियाचा उपयोग करत आहे?\",\"options\":[\"जीभ\",\"नाक\",\"कान\",\"त्वचा\"],\"answer\":1,\"explain\":\"चित्रात मुलगा फुलाचा वास घेण्यासाठी नाकाचा वापर करताना दिसत आहे.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"16\\/027_101.jpg\"},{\"q\":\"दिलेल्या चित्रात, मुलगी फुटबॉल खेळताना कोणत्या प्रमुख कर्मेंद्रियाचा वापर करत आहे?\",\"options\":[\"पाय\",\"नाक\",\"कान\",\"डोळे\"],\"answer\":0,\"explain\":\"चित्रात मुलगी फुटबॉलला लाथ मारण्यासाठी पायाचा (कर्मेंद्रियाचा) वापर करत आहे.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"16\\/027_101.jpg\"},{\"q\":\"खालीलपैकी कोणता गट फक्त ज्ञानेंद्रियांचा आहे?\",\"options\":[\"हात, पाय, डोळे\",\"नाक, त्वचा, कान\",\"जीभ, हात, नाक\",\"पाय, कान, त्वचा\"],\"answer\":1,\"explain\":\"नाक, त्वचा आणि कान ही तिन्ही ज्ञानेंद्रिये आहेत; हात आणि पाय ही कर्मेंद्रिये आहेत.\",\"topic\":\"बाह्य अवयव आणि ज्ञानेंद्रिये\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"शरीराच्या आत असणारी आणि बाहेरून न दिसणारी इंद्रिये म्हणजे काय?\",\"options\":[\"बाह्येंद्रिये\",\"आंतरेंद्रिये\",\"ज्ञानेंद्रिये\",\"कर्मेंद्रिये\"],\"answer\":1,\"explain\":\"शरीराच्या आत असणाऱ्या आणि बाहेरून न दिसणाऱ्या इंद्रियांना आंतरेंद्रिये म्हणतात.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"मेंदू आपल्या शरीराच्या कोणत्या भागात असतो?\",\"options\":[\"छातीमध्ये\",\"पोटामध्ये\",\"कवटीमध्ये\",\"पायामध्ये\"],\"answer\":2,\"explain\":\"मेंदू आपल्या डोक्यातील कवटीमध्ये असतो.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"कवटीमुळे मेंदूला काय मिळते?\",\"options\":[\"संरक्षण\",\"आकार\",\"रक्त\",\"अन्न\"],\"answer\":0,\"explain\":\"कवटीमुळे मेंदूला संरक्षण मिळते.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"ज्ञानेंद्रियांकडून मिळालेली माहिती कोठे साठवली जाते?\",\"options\":[\"हृदयात\",\"मेंदूत\",\"पोटात\",\"हाडांत\"],\"answer\":1,\"explain\":\"ज्ञानेंद्रियांकडून मिळालेली माहिती मेंदूत साठवली जाते.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"राग, आनंद आणि दुःख या भावनांची जाणीव आपल्याला कशामुळे होते?\",\"options\":[\"हातांमुळे\",\"डोळ्यांमुळे\",\"मेंदूमुळे\",\"जिभेमुळे\"],\"answer\":2,\"explain\":\"भावनांची जाणीव आपल्याला मेंदूमधून होते.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मेंदूत साठवलेल्या माहितीचा उपयोग कधी केला जातो?\",\"options\":[\"फक्त एकदाच\",\"कधीच नाही\",\"वेळोवेळी\",\"फक्त झोपेत\"],\"answer\":2,\"explain\":\"मेंदूत साठवलेल्या माहितीचा उपयोग वेळोवेळी केला जातो.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला एखादी जुनी गोष्ट आठवली, तर त्यासाठी कोणते इंद्रिय कारणीभूत असेल?\",\"options\":[\"नाक\",\"कान\",\"मेंदू\",\"त्वचा\"],\"answer\":2,\"explain\":\"माहिती साठवणे आणि तिचा वापर करणे हे मेंदूचे कार्य आहे.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खेळताना पडल्यावर दुःख झाले, तर ही जाणीव शरीराच्या कोणत्या भागामुळे होते?\",\"options\":[\"मेंदू\",\"गुडघा\",\"कवटी\",\"बाह्येंद्रिय\"],\"answer\":0,\"explain\":\"दुःख या भावनेची जाणीव मेंदूमधून होते.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विधान मेंदूच्या संरक्षणाबाबत योग्य आहे?\",\"options\":[\"मेंदू बाहेरून दिसतो म्हणून तो सुरक्षित आहे.\",\"मेंदू कवटीत असल्यामुळे त्याला संरक्षण मिळते.\",\"मेंदूला संरक्षणाची गरज नसते.\",\"जीभ मेंदूचे संरक्षण करते.\"],\"answer\":1,\"explain\":\"कवटी हे मेंदूचे संरक्षक कवच आहे.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"मेंदूला \'आंतरेंद्रिय\' का म्हटले जाते?\",\"options\":[\"कारण तो डोक्याच्या बाहेर असतो.\",\"कारण तो माहिती साठवतो.\",\"कारण तो शरीराच्या आत असतो आणि बाहेरून दिसत नाही.\",\"कारण तो भावनांची जाणीव करून देतो.\"],\"answer\":2,\"explain\":\"शरीराच्या आत असणाऱ्या आणि बाहेरून न दिसणाऱ्या इंद्रियांना आंतरेंद्रिये म्हणतात.\",\"topic\":\"मेंदू\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"आपल्या छातीमध्ये एकूण किती फुप्फुसे असतात?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार आपल्या छातीमध्ये दोन फुप्फुसे असतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"फुप्फुसे संपूर्ण शरीराला कशाचा पुरवठा करण्याचे काम करतात?\",\"options\":[\"पाणी\",\"अन्न\",\"ऑक्सिजन\",\"रक्त\"],\"answer\":2,\"explain\":\"संपूर्ण शरीरात ऑक्सिजन पुरवण्याचे काम फुप्फुसे करतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"फुप्फुसाचे काम कोणत्या इंद्रियाच्या कामावर अवलंबून असते?\",\"options\":[\"जठर\",\"मेंदू\",\"हृदय\",\"आतडे\"],\"answer\":2,\"explain\":\"हृदय व फुप्फुसे यांची कामे एकमेकांवर अवलंबून असतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"छातीच्या पिंजऱ्यातील पातळ आणि चपट्या हाडांना काय म्हणतात?\",\"options\":[\"स्नायू\",\"बरगड्या\",\"मणके\",\"सांधे\"],\"answer\":1,\"explain\":\"छातीच्या पिंजऱ्याच्या पातळ चपट्या हाडांना बरगड्या म्हणतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"रक्त शुद्ध करण्यासाठी आवश्यक असणारा ऑक्सिजन कोणाकडून पुरवला जातो?\",\"options\":[\"हृदयाकडून\",\"रक्तवाहिन्यांकडून\",\"फुप्फुसांकडून\",\"बरगड्यांकडून\"],\"answer\":2,\"explain\":\"रक्त शुद्ध करण्यासाठी आवश्यक ऑक्सिजन फुप्फुसांकडून पुरवला जातो.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"हृदय आणि फुप्फुसे शरीराच्या कोणत्या भागात सुरक्षित असतात?\",\"options\":[\"डोक्याच्या कवटीत\",\"छातीच्या पिंजऱ्यात\",\"पोटाच्या पोकळीत\",\"हाताच्या मुठीत\"],\"answer\":1,\"explain\":\"ही दोन्ही इंद्रिये छातीच्या पिंजऱ्यात असतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर फुप्फुसांनी ऑक्सिजन पुरवणे थांबवले, तर रक्तावर काय परिणाम होईल?\",\"options\":[\"रक्त जास्त होईल\",\"रक्त शुद्ध होणार नाही\",\"रक्त गोठणार नाही\",\"रक्तवाहिन्या बंद होतील\"],\"answer\":1,\"explain\":\"रक्त शुद्ध करण्यासाठी ऑक्सिजनची गरज असते, जो फुप्फुसे पुरवतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"हृदय आणि फुप्फुसे यांच्या कामाबद्दल कोणते विधान सत्य आहे?\",\"options\":[\"ती स्वतंत्रपणे काम करतात\",\"ती एकमेकांवर अवलंबून असतात\",\"फुप्फुस रक्ताभिसरण करते\",\"हृदय ऑक्सिजन तयार करते\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे हृदय व फुप्फुसे यांची कामे एकमेकांवर अवलंबून असतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"छातीच्या पिंजऱ्याचे मुख्य कार्य काय असावे?\",\"options\":[\"अन्न पचवणे\",\"रक्त तयार करणे\",\"हृदय व फुप्फुसांचे रक्षण करणे\",\"शरीराची हालचाल करणे\"],\"answer\":2,\"explain\":\"नाजूक इंद्रिये (हृदय व फुप्फुसे) पिंजऱ्यात असणे म्हणजे त्यांचे रक्षण होणे होय.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता घटक फुप्फुसाशी थेट संबंधित आहे?\",\"options\":[\"बंद मूठ\",\"पंप\",\"ऑक्सिजन पुरवठा\",\"डावा भाग\"],\"answer\":2,\"explain\":\"फुप्फुसे शरीराला ऑक्सिजन पुरवण्याचे काम करतात.\",\"topic\":\"फुप्फुस\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"तोंडाद्वारे खाल्लेले अन्न जठरापर्यंत वाहून नेणाऱ्या लांब नळीला काय म्हणतात?\",\"options\":[\"श्वसननलिका\",\"अन्ननलिका\",\"रक्तवाहिनी\",\"मज्जारज्जू\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, तोंडाद्वारे खाल्लेले अन्न वाहून नेणारी लांब नळी म्हणजे अन्ननलिका होय.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जठर हे कोणत्या आकाराचे आंतरेंद्रिय आहे?\",\"options\":[\"नळीसारखे\",\"चौकोनी\",\"पिशवीसारखे\",\"गोल\"],\"answer\":2,\"explain\":\"जठर हे पिशवीसारखे आंतरेंद्रिय असून त्यात अन्न घुसळले जाते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जठरामध्ये अन्नावर कोणती मुख्य क्रिया घडते?\",\"options\":[\"अन्न चावले जाते\",\"अन्न घुसळले जाते\",\"अन्न सुकवले जाते\",\"अन्न बाहेर टाकले जाते\"],\"answer\":1,\"explain\":\"जठरात अन्न घुसळले जाते, ज्यामुळे अन्नाचे पचन करण्यास मदत होते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"अन्नाचे पचन पूर्ण होऊन त्यातील पोषकतत्त्वे कोठे शोषली जातात?\",\"options\":[\"अन्ननलिकेत\",\"जठरात\",\"लहान आतड्यात\",\"मलाशयात\"],\"answer\":2,\"explain\":\"लहान आतड्यामध्ये अन्नाचे पचन पूर्ण होऊन पोषकतत्त्वे आणि पाणी शोषले जाते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"मोठ्या आतड्याचे मुख्य कार्य कोणते आहे?\",\"options\":[\"अन्न घुसळणे\",\"न पचलेल्या अन्नातील पाणी शोषून घेणे\",\"अन्न चावणे\",\"अन्न तोंडातून जठरात नेणे\"],\"answer\":1,\"explain\":\"न पचलेल्या अन्नातील पाणी मोठ्या आतड्यात शोषले जाते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"पचनक्रियेत तयार झालेले टाकाऊ पदार्थ (मल) शरीराबाहेर कोणत्या भागातून टाकले जातात?\",\"options\":[\"जठर\",\"लहान आतडे\",\"गुदद्वार\",\"अन्ननलिका\"],\"answer\":2,\"explain\":\"टाकाऊ पदार्थ (मल) गुदद्वारामधून शरीराबाहेर टाकले जातात.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"मोठ्या आतड्याच्या शेवटच्या भागाला काय म्हणतात?\",\"options\":[\"मलाशय\",\"जठर\",\"अन्ननलिका\",\"लहान आतडे\"],\"answer\":0,\"explain\":\"मोठ्या आतड्याच्या शेवटच्या भागाला मलाशय म्हणतात, जिथे मल साठवला जातो.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"लहान आतडे आणि मोठे आतडे यांच्या रचनेतील मुख्य फरक कोणता?\",\"options\":[\"लहान आतडे रुंद असते, मोठे आतडे लांब असते\",\"लहान आतडे पिशवीसारखे असते, मोठे आतडे नळीसारखे असते\",\"लहान आतडे लांब नळी असते, मोठे आतडे रुंद नळी असते\",\"दोन्हीची लांबी आणि रुंदी सारखीच असते\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे लहान आतडे लांब नळी आहे, तर मोठे आतडे रुंद नळी आहे.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"अन्नाचा प्रवास शरीरात कोणत्या क्रमाने होतो?\",\"options\":[\"अन्ननलिका -> जठर -> लहान आतडे\",\"जठर -> अन्ननलिका -> मोठे आतडे\",\"लहान आतडे -> जठर -> अन्ननलिका\",\"मोठे आतडे -> लहान आतडे -> जठर\"],\"answer\":0,\"explain\":\"अन्ननलिकेतून अन्न जठरात जाते आणि जठराला जोडून लहान आतडे असते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या व्यक्तीच्या शरीरात अन्नातील पोषकतत्त्वे शोषली जात नसतील, तर कोणत्या इंद्रियाच्या कार्यात अडथळा आला असावा?\",\"options\":[\"अन्ननलिका\",\"लहान आतडे\",\"मलाशय\",\"गुदद्वार\"],\"answer\":1,\"explain\":\"अन्नातील पोषकतत्त्वे शोषण्याचे काम लहान आतड्यात होते.\",\"topic\":\"पचनसंस्थेतील आंतरेंद्रिये\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"शरीराच्या आत असणाऱ्या आणि बाहेरून न दिसणाऱ्या इंद्रियांना काय म्हणतात?\",\"options\":[\"बाह्येंद्रिये\",\"आंतरेंद्रिये\",\"ज्ञानेंद्रिये\",\"कर्मेंद्रिये\"],\"answer\":1,\"explain\":\"शरीराच्या आत असणाऱ्या इंद्रियांना आंतरेंद्रिये म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते आंतरेंद्रिय आहे?\",\"options\":[\"नाक\",\"हात\",\"हृदय\",\"डोळे\"],\"answer\":2,\"explain\":\"हृदय हे शरीराच्या आत असते, म्हणून ते आंतरेंद्रिय आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"आंतरेंद्रिये शरीराच्या कोणत्या भागात असतात?\",\"options\":[\"शरीराच्या बाहेर\",\"शरीराच्या आत पोकळीमध्ये\",\"त्वचेच्या वरच्या बाजूला\",\"केसांच्या मध्ये\"],\"answer\":1,\"explain\":\"आंतरेंद्रिये शरीराच्या आतील सुरक्षित पोकळीमध्ये असतात.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"आपण खाल्लेल्या अन्नाचे पचन शरीरातील कोणत्या आंतरेंद्रियात होते?\",\"options\":[\"फुप्फुस\",\"जठर\",\"मेंदू\",\"हृदय\"],\"answer\":1,\"explain\":\"जठर हे अन्नाचे पचन करणारे महत्त्वाचे आंतरेंद्रिय आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"मेंदू हे महत्त्वाचे आंतरेंद्रिय कोठे सुरक्षित असते?\",\"options\":[\"छातीच्या पोकळीत\",\"पोटाच्या पोकळीत\",\"शिरोपोकळीत (कवटीत)\",\"पायाच्या हाडात\"],\"answer\":2,\"explain\":\"मेंदूचे संरक्षण कवटीच्या आत शिरोपोकळीत केले जाते.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"श्वास घेतल्यानंतर हवा ज्या आंतरेंद्रियात भरली जाते, त्यास काय म्हणतात?\",\"options\":[\"हृदय\",\"जठर\",\"फुप्फुसे\",\"मेंदू\"],\"answer\":2,\"explain\":\"श्वसनासाठी फुप्फुसे हे आंतरेंद्रिय वापरले जाते.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"शरीराच्या सर्व हालचालींवर नियंत्रण ठेवणारे आंतरेंद्रिय कोणते?\",\"options\":[\"मेंदू\",\"हृदय\",\"फुप्फुस\",\"जठर\"],\"answer\":0,\"explain\":\"मेंदू हा शरीराच्या सर्व कार्यांवर नियंत्रण ठेवतो.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"बाह्येंद्रिये आणि आंतरेंद्रिये यांच्यातील मुख्य फरक कोणता?\",\"options\":[\"बाह्येंद्रिये आत असतात, आंतरेंद्रिये बाहेर असतात.\",\"दोन्ही बाहेरून दिसतात.\",\"बाह्येंद्रिये बाहेरून दिसतात, पण आंतरेंद्रिये दिसत नाहीत.\",\"दोन्ही शरीराच्या आत असतात.\"],\"answer\":2,\"explain\":\"बाह्येंद्रिये शरीराच्या बाहेर असतात तर आंतरेंद्रिये आत दडलेली असतात.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"जर मेंदूला इजा झाली तर शरीराचे कार्य विस्कळीत होते, यावरून मेंदूचे स्थान कसे असावे?\",\"options\":[\"उघड्यावर\",\"अतिशय सुरक्षित ठिकाणी\",\"हाताच्या तळव्यावर\",\"त्वचेच्या वर\"],\"answer\":1,\"explain\":\"महत्त्वाचे कार्य करत असल्याने मेंदू अतिशय सुरक्षित पोकळीत असतो.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"हृदय सतत धडधडत असते, हे कोणत्या प्रकारचे इंद्रिय आहे?\",\"options\":[\"बाह्येंद्रिय\",\"आंतरेंद्रिय\",\"ज्ञानेंद्रिय\",\"कर्मेंद्रिय\"],\"answer\":1,\"explain\":\"हृदय शरीराच्या आत असल्याने ते आंतरेंद्रिय आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21479,16,4,'EVS Part 1','mr','ग्रह व तारे','[\"आकाशात चमचमणाऱ्या चांदण्यांना \'तारे\' म्हणतात.\",\"ज्या चांदण्या चमचमत नाहीत त्यांना \'ग्रह\' म्हणतात.\",\"सूर्य हा एक तारा आहे, पृथ्वी हा एक ग्रह आहे.\",\"पृथ्वीभोवती फिरणारा चंद्र हा पृथ्वीचा उपग्रह आहे.\",\"सूर्यमालेत एकूण आठ ग्रह आहेत.\",\"ग्रहांचा क्रम: बुध, शुक्र, पृथ्वी, मंगळ, गुरू, शनी, युरेनस, नेपच्यून.\",\"सूर्यापासूनचे अंतर खगोलीय एकक (AU) मापतात.\",\"1 खगोलीय एकक = पृथ्वी व सूर्याचं सरासरी अंतर = १४९ दशलक्ष किमी.\",\"अंतर्गृह: बुध, शुक्र, पृथ्वी, मंगळ (सूर्यापासून लघुग्रह पट्ट्यापर्यंत).\",\"बहिर्ग्रह: गुरू, शनि, युरेनस, नेपच्यून (लघुग्रह पट्ट्यापलीकडे).\",\"उपग्रह: ग्रहांभोवती फिरणारे, e.g. चंद्र.\",\"लघुग्रह: मंगळ व गुरू दरम्यान पट्ट्यातील खगोल.\",\"बट॒ग्रह: सूर्याभोवती स्वतंत्रपणे फिरणारे लहान वस्तू, e.g. प्लुटो.\",\"धूमकेतू: बर्फ, धूल, खडक बने खगोलीय वस्तू, लांब कालानंतर दिसते.\",\"पृथ्वीची स्वत:भोवती गती = दैनिक गती = परिभ्रमण = 24 तास = 1 दिवस.\",\"पृथ्वीची सूर्याभोवती गती = वार्षिक गती = परिक्रमा = ३६५ दिवस = 1 वर्ष.\",\"पृथ्वी गोलाकार असल्याने दिवस व रात्र होतात.\",\"चंद्राच्या प्रकाशित भागातील बदल चंद्रकला म्हणतात.\",\"शुक्ल पक्ष: अमावस्या ते पौर्णिमा (प्रकाशित भाग वाढतो).\",\"कृष्ण पक्ष: पौर्णिमे ते अमावस्या (प्रकाशित भाग कमी होतो).\",\"चंद्र हा पृथ्वीचा उपग्रह आहे, त्याची फिरण्याची गती महिना मापण्यासाठी वापरते.\"]','[{\"q\":\"आकाशात चमचमणाऱ्या चांदण्यांना काय म्हणतात?\",\"options\":[\"ग्रह\",\"तारे\",\"उपग्रह\",\"ग्रहमालिका\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या व्याख्येनुसार, आकाशात चमचमणाऱ्या चांदण्यांना \'तारे\' म्हणतात.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"ज्या चांदण्या चमचमत नाहीत त्यांना काय म्हणतात?\",\"options\":[\"तारे\",\"सूर्य\",\"ग्रह\",\"स्वयंमप्रकाशित\"],\"answer\":2,\"explain\":\"ज्या चांदण्या चमचमत नाहीत त्यांना \'ग्रह\' म्हणतात असे पाठात नमूद केले आहे.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"तारे आणि ग्रह यांच्यातील मुख्य फरक कोणता आहे?\",\"options\":[\"तारे फिरतात, ग्रह स्थिर असतात\",\"ग्रहांना स्वतःचा प्रकाश असतो, ताऱ्यांना नसतो\",\"तारे स्वयंमप्रकाशित असतात, ग्रहांना स्वतःचा प्रकाश नसतो\",\"तारे पृथ्वीभोवती फिरतात, ग्रह सूर्याभोवती फिरतात\"],\"answer\":2,\"explain\":\"पाठाप्रमाणे, तारे स्वयंमप्रकाशित असतात तर ग्रहांना स्वतःचा प्रकाश नसतो.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"सूर्य हा खालीलपैकी काय आहे?\",\"options\":[\"एक ग्रह\",\"एक उपग्रह\",\"एक तारा\",\"एक ग्रहमालिका\"],\"answer\":2,\"explain\":\"पाठात स्पष्टपणे सांगितले आहे की, सूर्य हा एक तारा आहे.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात पृथ्वीभोवती फिरणारा कोणता घटक दाखवला आहे?\",\"options\":[\"सूर्य\",\"चंद्र\",\"तारा\",\"दुसरा ग्रह\"],\"answer\":1,\"explain\":\"आकृतीत पृथ्वीच्या जवळ \'चंद्र\' हा उपग्रह दाखवला आहे जो पृथ्वीभोवती फिरतो.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"apply\",\"figure_image\":\"16\\/032_101.jpg\"},{\"q\":\"पृथ्वी हा सूर्याभोवती फिरणारा एक ______ आहे.\",\"options\":[\"तारा\",\"उपग्रह\",\"ग्रह\",\"प्रकाश\"],\"answer\":2,\"explain\":\"पाठात दिले आहे की आपली पृथ्वी हा एक ग्रह आहे.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"चंद्र हा पृथ्वीचा \'उपग्रह\' आहे, कारण तो ______.\",\"options\":[\"स्वतःभोवती फिरतो\",\"पृथ्वीभोवती फिरतो\",\"सूर्याभोवती फिरतो\",\"चमचम करतो\"],\"answer\":1,\"explain\":\"विशिष्ट ग्रहांभोवती फिरणाऱ्या ग्रहगोलांना उपग्रह म्हणतात, म्हणून चंद्र हा पृथ्वीचा उपग्रह आहे.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीशिवाय सूर्याभोवती आणखी किती ग्रह फिरतात?\",\"options\":[\"पाच\",\"सहा\",\"सात\",\"आठ\"],\"answer\":2,\"explain\":\"पाठात उल्लेख आहे की पृथ्वीप्रमाणेच अजून सात ग्रह सूर्याभोवती फिरतात.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्राचे निरीक्षण करा. सूर्य, पृथ्वी आणि चंद्र यांपैकी आकाराने सर्वात मोठा आणि तेजस्वी कोणता दिसत आहे?\",\"options\":[\"पृथ्वी\",\"चंद्र\",\"सूर्य\",\"सर्व सारखे आहेत\"],\"answer\":2,\"explain\":\"चित्रात सूर्य हा सर्वात मोठा आणि तेजस्वी (प्रकाश देणारा) दाखवला आहे.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"16\\/032_101.jpg\"},{\"q\":\"जर तुम्हाला आकाशात एक चांदणी स्थिर (न चमचमणारी) दिसली, तर ती काय असू शकते?\",\"options\":[\"तारा\",\"सूर्य\",\"ग्रह\",\"स्वयंमप्रकाशित वस्तू\"],\"answer\":2,\"explain\":\"जे चमचमत नाहीत त्यांना ग्रह म्हणतात, या माहितीवरून आपण तो ग्रह असल्याचे ओळखू शकतो.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"सूर्यमालेत पृथ्वी आणि इतर सात ग्रह मिळून एकूण किती ग्रह सूर्याभोवती फिरतात?\",\"options\":[\"७\",\"८\",\"९\",\"१०\"],\"answer\":1,\"explain\":\"पृथ्वी (१) + अजून सात ग्रह (७) = एकूण ८ ग्रह सूर्यमालेत आहेत.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"अवकाशात फक्त एकच सूर्यमाला आहे का?\",\"options\":[\"हो, फक्त एकच आहे\",\"नाही, अशा अनेक ग्रहमालिका आहेत\",\"फक्त पृथ्वीचीच सूर्यमाला आहे\",\"याबद्दल माहिती दिलेली नाही\"],\"answer\":1,\"explain\":\"पाठाच्या शेवटी दिले आहे की सूर्यमालेशिवाय अशा अनेक ग्रहमालिका अवकाशात आहेत.\",\"topic\":\"तारे व ग्रह\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"शिक्षक आणि मुलांनी खेळ खेळण्यासाठी मैदानावर किती लंबवर्तुळे तयार केली होती?\",\"options\":[\"पाच\",\"सहा\",\"सात\",\"आठ\"],\"answer\":3,\"explain\":\"पाठातील मजकुरानुसार, शिक्षकांनी मैदानावर आठ लंबवर्तुळे बनवलेली होती.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"मैदानावरील खेळात \'सूर्य\' म्हणून कोणाला उभे केले होते?\",\"options\":[\"शिक्षकांना\",\"राजेशला\",\"बुधला\",\"नेपच्यूनला\"],\"answer\":1,\"explain\":\"शिक्षकांनी राजेशला मध्यभागी उभे केले आणि तो \'सूर्य\' आहे असे सांगितले.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"आकाशातील ग्रह पाहण्यासाठी कशाचा वापर केला जातो असे शिक्षकांनी सांगितले?\",\"options\":[\"भिंगाच्या\",\"आरशाच्या\",\"दुर्बिणीच्या\",\"कॅमेऱ्याच्या\"],\"answer\":2,\"explain\":\"मजकुरानुसार, आपण आकाशातील ग्रह दुर्बिणीच्या साहाय्याने पाहू शकतो.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"ग्रहांचे सूर्यापासूनचे अंतर सतत का बदलत राहते?\",\"options\":[\"ग्रह वेगाने फिरतात म्हणून\",\"ग्रह लंबवर्तुळाकार कक्षेत फिरतात म्हणून\",\"सूर्य आपली जागा बदलतो म्हणून\",\"ग्रह स्वतःभोवती फिरत नाहीत म्हणून\"],\"answer\":1,\"explain\":\"प्रत्येक ग्रह लंबवर्तुळाकार कक्षेत फिरत असल्यामुळे त्याचे सूर्यापासूनचे अंतर बदलत राहते.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत सूर्यापासून तिसऱ्या क्रमांकावर असलेला निळ्या रंगाचा ग्रह कोणता आहे?\",\"options\":[\"मंगळ\",\"शुक्र\",\"पृथ्वी\",\"गुरू\"],\"answer\":2,\"explain\":\"आकृतीनुसार, सूर्यापासून तिसऱ्या कक्षेतील ग्रह पृथ्वी आहे.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"16\\/033_101.jpg\"},{\"q\":\"खेळ खेळताना मुलांनी कोणत्या दोन प्रकारे हालचाल केली?\",\"options\":[\"फक्त स्वतःभोवती फिरणे\",\"फक्त राजेशभोवती फिरणे\",\"स्वतःभोवती गिरकी घेणे आणि राजेशभोवती फिरणे\",\"एकाच जागी उभे राहून उड्या मारणे\"],\"answer\":2,\"explain\":\"प्रत्येक मुलाला स्वतःभोवती गिरकी घेत राजेश (सूर्य) भोवती फिरायला सांगितले होते.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. कोणत्या ग्रहाच्या भोवती स्पष्ट कडे (रिंग) दिसत आहे?\",\"options\":[\"गुरू\",\"शनी\",\"युरेनस\",\"नेपच्यून\"],\"answer\":1,\"explain\":\"आकृतीमध्ये शनी ग्रहाभोवती कडे स्पष्टपणे दाखवले आहे.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"16\\/033_101.jpg\"},{\"q\":\"मजकुरात दिलेल्या ग्रहांच्या नावांच्या क्रमानुसार, सर्वात शेवटी कोणत्या ग्रहाचे नाव आले आहे?\",\"options\":[\"युरेनस\",\"शनी\",\"नेपच्यून\",\"मंगळ\"],\"answer\":2,\"explain\":\"मजकुरात बुध ते नेपच्यून अशा क्रमाने ग्रहांची नावे दिली आहेत, ज्यात नेपच्यून शेवटचा आहे.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"ग्रहांच्या सूर्याभोवती फिरण्याच्या मार्गाला काय म्हणतात?\",\"options\":[\"वर्तुळ\",\"लंबवर्तुळाकार कक्षा\",\"त्रिकोण\",\"चौकोन\"],\"answer\":1,\"explain\":\"मजकुरानुसार, प्रत्येक ग्रह सूर्याभोवती लंबवर्तुळाकार कक्षेत फिरतो.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एखादा विद्यार्थी \'मंगळ\' या ग्रहाची भूमिका करत असेल, तर तो कोणाभोवती प्रदक्षिणा घालेल?\",\"options\":[\"पृथ्वीभोवती\",\"चंद्राभोवती\",\"राजेशभोवती (सूर्य)\",\"इतर मुलांभोवती\"],\"answer\":2,\"explain\":\"खेळात सर्व ग्रहांची भूमिका करणारी मुले राजेशभोवती (सूर्य) फिरत होती.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"ग्रहाच्या एका प्रदक्षिणेदरम्यान खालीलपैकी कोणती गोष्ट घडते?\",\"options\":[\"ग्रहाचा आकार बदलतो\",\"ग्रहाचा रंग बदलतो\",\"ग्रहाचे सूर्यापासूनचे अंतर बदलत राहते\",\"ग्रह आपली कक्षा सोडून देतो\"],\"answer\":2,\"explain\":\"लंबवर्तुळाकार कक्षेमुळे प्रदक्षिणेदरम्यान ग्रहाचे सूर्यापासूनचे अंतर बदलत राहते.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मजकुरात सूर्याभोवती फिरणाऱ्या एकूण किती ग्रहांची नावे दिली आहेत?\",\"options\":[\"नऊ\",\"सात\",\"आठ\",\"दहा\"],\"answer\":2,\"explain\":\"मजकुरात बुध, शुक्र, पृथ्वी, मंगळ, गुरू, शनी, युरेनस व नेपच्यून अशा ८ ग्रहांची नावे दिली आहेत.\",\"topic\":\"सूर्यमाला समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"सूर्यमालेत एकूण किती ग्रह आहेत?\",\"options\":[\"सहा\",\"सात\",\"आठ\",\"नऊ\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार सूर्यमालेत एकूण आठ ग्रह आहेत.\",\"topic\":\"सूर्यमालेतील घटक\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"सूर्यापासून सर्वात जवळचा ग्रह कोणता आहे?\",\"options\":[\"शुक्र\",\"बुध\",\"पृथ्वी\",\"मंगळ\"],\"answer\":1,\"explain\":\"बुध हा सूर्यापासून सर्वात जवळचा ग्रह आहे.\",\"topic\":\"सूर्यमालेतील घटक\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"सूर्यमालेतील कोणत्या ग्रहावर सजीवसृष्टी अस्तित्वात आहे?\",\"options\":[\"मंगळ\",\"बुध\",\"शुक्र\",\"पृथ्वी\"],\"answer\":3,\"explain\":\"पृथ्वी ग्रहावर सजीवसृष्टी आहे असे पाठात नमूद केले आहे.\",\"topic\":\"सूर्यमालेतील घटक\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात पृथ्वीचे सूर्यापासूनचे अंतर किती दशलक्ष किमी दाखवले आहे?\",\"options\":[\"४४ दशलक्ष किमी\",\"१०४ दशलक्ष किमी\",\"१४९ दशलक्ष किमी\",\"२२४ दशलक्ष किमी\"],\"answer\":2,\"explain\":\"दिलेल्या तक्त्यानुसार पृथ्वीचे सूर्यापासूनचे अंतर १४९ दशलक्ष किमी आहे.\",\"topic\":\"सूर्यमालेतील घटक\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"16\\/034_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील ग्रहावर मानवाने कोणते यान पाठवले आहे?\",\"options\":[\"चंद्रयान\",\"मंगळयान\",\"सूर्ययान\",\"आकाशयान\"],\"answer\":1,\"explain\":\"मंगळ ग्रहावर मानवाने मंगळयान पाठवले आहे.\",\"topic\":\"सूर्यमालेतील घटक\",\"part\":4,\"bloom\":\"remember\",\"