d\"},{\"q\":\"दिलेल्या आकृतीत मासे टिकवण्यासाठी कोणती पद्धत वापरली जात आहे?\",\"options\":[\"फक्त शिजवणे\",\"खारवणे आणि वाळवणे\",\"हवाबंद डब्यात भरणे\",\"फक्त तेल लावणे\"],\"answer\":1,\"explain\":\"आकृतीत मासे दोरीला टांगून वाळत घातलेले दिसत आहेत, ही खारवणे आणि वाळवणे या पद्धतीचा भाग आहे.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"16\\/073_102.jpg\"},{\"q\":\"लोणचे तयार करताना बरणीत ओला चमचा वापरल्यास काय होईल?\",\"options\":[\"लोणचे जास्त काळ टिकेल\",\"लोणच्याला चांगली चव येईल\",\"पाण्याच्या अंशामुळे लोणचे खराब होईल\",\"लोणच्याचा रंग बदलेल\"],\"answer\":2,\"explain\":\"अन्नपदार्थात पाण्याचा अंश राहिल्यास त्याला बुरशी लागून ते खराब होते.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अन्नामध्ये काचेचे तुकडे, धातूचे कण किंवा माती मिसळणे हे कोणत्या प्रकारचे दूषितीकरण आहे?\",\"options\":[\"रासायनिक दूषितीकरण\",\"सूक्ष्मजंतूंचा संसर्ग\",\"भौतिक पदार्थ मिसळणे\",\"नैसर्गिक बदल\"],\"answer\":2,\"explain\":\"काच, धातू, प्लास्टिक आणि माती यांसारख्या बाह्य वस्तू अन्नात मिसळणे म्हणजे भौतिक दूषितीकरण होय.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दूषित अन्न खाल्ल्यामुळे शरीरावर कोणता दुष्परिणाम होऊ शकतो?\",\"options\":[\"उंची वाढणे\",\"जुलाब आणि उलट्या होणे\",\"भूक वाढणे\",\"हाडे मजबूत होणे\"],\"answer\":1,\"explain\":\"दूषित अन्नातील रोगजंतूंमुळे पोटदुखी, जुलाब आणि उलट्या यांसारखे आजार होतात.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अन्नपदार्थ खराब झाला आहे हे ओळखण्याची मुख्य खूण कोणती?\",\"options\":[\"अन्नाचा रंग पांढरा होणे\",\"अन्नाला दुर्गंधी येणे किंवा ते चिकट होणे\",\"अन्न गरम असणे\",\"अन्नाचे वजन वाढणे\"],\"answer\":1,\"explain\":\"अन्नाला घाण वास येणे किंवा त्याचा पोत चिकट होणे ही अन्न खराब झाल्याची लक्षणे आहेत.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत दाखवलेला मुरांबा वर्षभर टिकण्यासाठी त्यात कशाचा वापर केला जातो?\",\"options\":[\"जास्त पाणी\",\"परिरक्षक\",\"दूध\",\"फक्त फळे\"],\"answer\":1,\"explain\":\"मुरांबा किंवा लोणची टिकवण्यासाठी त्यात साखर किंवा मीठ यांसारखी परिरक्षके वापरली जातात.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"16\\/073_103.jpg\"},{\"q\":\"अन्न दूषित होणे टाळण्यासाठी खालीलपैकी कोणती कृती करणे योग्य आहे?\",\"options\":[\"अन्न उघड्यावर ठेवणे\",\"अस्वच्छ हाताने जेवणे\",\"अन्न नेहमी झाकून ठेवणे\",\"शिळे अन्न खाणे\"],\"answer\":2,\"explain\":\"अन्न झाकून ठेवल्यामुळे त्यावर धूळ, माश्या किंवा सूक्ष्मजंतू बसत नाहीत आणि अन्न सुरक्षित राहते.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अन्न उघड्यावर ठेवल्याने ते दूषित का होते?\",\"options\":[\"त्याला हवा लागते म्हणून\",\"प्रदूषित हवा आणि सूक्ष्मजंतूंचा संपर्क येतो म्हणून\",\"त्याचा रंग उडतो म्हणून\",\"ते थंड होते म्हणून\"],\"answer\":1,\"explain\":\"हवेतील सूक्ष्मजंतू आणि प्रदूषके उघड्या अन्नावर बसल्यामुळे अन्न विषारी किंवा दूषित होते.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खूप काळ ठेवलेले शिळे अन्न खाणे आरोग्यासाठी कसे असते?\",\"options\":[\"फायदेशीर\",\"शक्तिवर्धक\",\"हानिकारक\",\"पचायला हलके\"],\"answer\":2,\"explain\":\"जास्त काळ ठेवलेले अन्न शिळे होऊन त्यात जंतूंची वाढ होऊ शकते, जे आरोग्यास अपायकारक असते.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"लोणच्याची बरणी भरल्यानंतर तिच्या तोंडावर काय बांधावे असे पाठात सांगितले आहे?\",\"options\":[\"प्लास्टिकची पिशवी\",\"स्वच्छ कापड\",\"कागद\",\"काहीही बांधू नये\"],\"answer\":1,\"explain\":\"बरणीच्या तोंडावर स्वच्छ कापड घट्ट बांधून ठेवल्याने बाहेरील कचरा किंवा ओलावा आत जात नाही.\",\"topic\":\"अन्न साठवणूक आणि दूषित अन्न\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"आपल्या शरीराचे काम व्यवस्थित चालण्यासाठी आपल्याला कशाची गरज असते?\",\"options\":[\"खेळण्यांची\",\"अन्नाची\",\"कपड्यांची\",\"पुस्तकांची\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, शरीराचे काम व्यवस्थित चालण्यासाठी अन्नाची गरज असते.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रावरून, आजारपणात शरीराची ताकद परत मिळवण्यासाठी अन्नासोबत कशाची गरज असते?\",\"options\":[\"व्यायामाची\",\"विश्रांतीची\",\"फिरण्याची\",\"कामाची\"],\"answer\":1,\"explain\":\"चित्रातील मुलगी योग्य आहार आणि विश्रांतीमुळे बरी झाली आहे.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"16\\/076_101.jpg\"},{\"q\":\"कडाक्याची थंडी आणि मुसळधार पाऊस यांच्यापासून बचाव होण्यासाठी आपल्याला कशाची गरज असते?\",\"options\":[\"बागेची\",\"शाळेची\",\"घराची\",\"मैदानाची\"],\"answer\":2,\"explain\":\"थंडी, वारा, ऊन आणि पाऊस यांपासून संरक्षणासाठी आपण घरात राहतो.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"पक्षी घरटी कशासाठी बांधतात?\",\"options\":[\"फक्त झोपण्यासाठी\",\"अंडी घालण्यासाठी व पिल्लांच्या रक्षणासाठी\",\"खेळण्यासाठी\",\"अन्न साठवण्यासाठी\"],\"answer\":1,\"explain\":\"अंडी घालण्यासाठी सुरक्षित जागा हवी असते आणि पिल्लांचे रक्षण व्हावे म्हणून पक्षी घरटी बांधतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"मधमाश्या आपला निवारा (पोळे) कोठे तयार करतात?\",\"options\":[\"जमिनीखाली\",\"पाण्यामध्ये\",\"झाडांवर किंवा डोंगरांच्या कपारीत\",\"माणसांच्या घरात\"],\"answer\":2,\"explain\":\"मधमाश्या झाडांवर किंवा डोंगरांच्या कपारीत पोळे तयार करतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जमिनीखाली बिळे तयार करून राहणारे प्राणी कोणते?\",\"options\":[\"वाघ आणि सिंह\",\"चिमणी आणि कावळा\",\"उंदीर आणि घुशी\",\"मधमाशी आणि मुंग्या\"],\"answer\":2,\"explain\":\"उंदीर व घुशी जमिनीखाली बिळे तयार करून राहतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पक्षी घरट्यासाठी कोणती जागा निवडतात?\",\"options\":[\"पाण्याखालील जागा\",\"उंच व सोयीची जागा\",\"रस्त्याच्या मधली जागा\",\"अंधारी जागा\"],\"answer\":1,\"explain\":\"पक्षी घरट्यासाठी सुरक्षिततेच्या दृष्टीने उंच व सोयीची जागा निवडतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, कोंबड्यांसाठी मानवाने तयार केलेला कोणता निवारा दिसत आहे?\",\"options\":[\"तबेला\",\"गोठा\",\"खुराडे\",\"बिळ\"],\"answer\":2,\"explain\":\"चित्रात कोंबड्यांसाठी टोपलीसारखे खुराडे दाखवले आहे.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"16\\/078_102.jpg\"},{\"q\":\"अमितच्या खिडकीत चिमणीने घरटे बांधले आहे, तर त्याने काय करणे योग्य ठरेल?\",\"options\":[\"घरटे काढून टाकणे\",\"घरट्याला हानी पोहोचू नये याची काळजी घेणे\",\"घरट्यातील अंडी बाहेर काढणे\",\"खिडकी कायमची बंद करणे\"],\"answer\":1,\"explain\":\"प्राण्यांच्या निवाऱ्याला हानी पोहोचवू नये, हे मुलाने समजून घेणे आवश्यक आहे.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"काही प्राणी स्वतः निवारा तयार करत नाहीत, ते काय करतात?\",\"options\":[\"दुसऱ्या प्राण्यांचे घर हिरावून घेतात\",\"परिसरातील सुरक्षित जागी निवारा शोधतात\",\"नेहमी फिरत राहतात\",\"पाण्यात राहतात\"],\"answer\":1,\"explain\":\"काही प्राणी स्वतः निवारा न बनवता निसर्गातील सुरक्षित जागा शोधतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या तक्त्यानुसार, \'निसर्गनिर्मित निवारा\' शोधणाऱ्या प्राण्यांच्या यादीत खालीलपैकी कोणाचा समावेश होईल?\",\"options\":[\"पाळीव कुत्रा\",\"गुहेत राहणारा वाघ\",\"घरटे बांधणारी चिमणी\",\"पोळे बनवणारी मधमाशी\"],\"answer\":1,\"explain\":\"वाघ स्वतः निवारा बनवत नाही, तो निसर्गातील गुहा शोधतो.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"16\\/078_101.jpg\"},{\"q\":\"पिल्लांना घरट्याची गरज का असते?\",\"options\":[\"त्यांना उडता येत नाही म्हणून\",\"त्यांच्यात स्वतःचे रक्षण करण्याची ताकद नसते म्हणून\",\"त्यांना खेळायचे असते म्हणून\",\"त्यांना घरटे आवडते म्हणून\"],\"answer\":1,\"explain\":\"पिल्लांमध्ये स्वतःचे रक्षण करण्याची ताकद नसल्यामुळे घरट्यामुळे त्यांचे रक्षण होते.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"मांजर घरट्याकडे दबा धरून का बसले असावे?\",\"options\":[\"पक्षांशी मैत्री करण्यासाठी\",\"घरट्यातील अंडी किंवा पिल्ले खाण्यासाठी\",\"घरट्यात झोपण्यासाठी\",\"घरटे नीट करण्यासाठी\"],\"answer\":1,\"explain\":\"काही प्राणी पक्ष्यांची अंडी किंवा पिल्ले खातात, म्हणून मांजर दबा धरून बसते.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"स्वतःसाठी निवारा तयार करणाऱ्या प्राण्यांमध्ये खालीलपैकी कोणाचा समावेश होतो?\",\"options\":[\"वाघ\",\"मधमाशी\",\"हत्ती\",\"हरिण\"],\"answer\":1,\"explain\":\"मधमाशी स्वतःसाठी पोळे तयार करते, बाकी प्राणी निसर्गात जागा शोधतात.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या प्राण्याला पुरेसे अन्न मिळाले नाही, तर त्याच्या शरीरावर काय परिणाम होईल?\",\"options\":[\"तो अधिक शक्तिशाली होईल\",\"त्याला खूप झोप येईल\",\"तो अशक्त होईल\",\"त्याच्या शरीरावर काहीही परिणाम होणार नाही\"],\"answer\":2,\"explain\":\"अन्नाच्या अभावामुळे शरीर अशक्त होते, जसे चित्रातील मुलगी झाली होती.\",\"topic\":\"निवारा आणि प्राण्यांची घरे\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"ऊन, वारा व पाऊस यांच्यापासून रक्षण होईल अशा सुरक्षित जागेला काय म्हणतात?\",\"options\":[\"अन्न\",\"निवारा\",\"वस्ती\",\"परिसर\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या व्याख्येनुसार, ऊन, वारा व पाऊस यांच्यापासून रक्षण करणाऱ्या जागेला निवारा म्हणतात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"कोकणातील जास्त पावसाच्या प्रदेशात कोणत्या प्रकारची घरे आढळतात?\",\"options\":[\"धाब्याची घरे\",\"कुडाची घरे\",\"उतरत्या छपरांची कौलारू घरे\",\"बहुमजली इमारती\"],\"answer\":2,\"explain\":\"जास्त पावसाच्या प्रदेशात पाणी वाहून जाण्यासाठी उतरत्या छपरांची घरे बांधली जातात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"शहरी भागात घरे बांधण्यासाठी प्रामुख्याने कोणत्या साहित्याचा वापर केला जातो?\",\"options\":[\"गवत आणि बांबू\",\"माती आणि दगड\",\"सिमेंट, वाळू आणि लोखंड\",\"नारळाच्या झावळ्या\"],\"answer\":2,\"explain\":\"शहरातील पक्की घरे बांधण्यासाठी सिमेंट, वाळू, काँक्रीट आणि लोखंडाचा वापर होतो.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"वनस्पती आपले अन्न कसे मिळवतात?\",\"options\":[\"इतर प्राण्यांना खाऊन\",\"स्वतःचे अन्न स्वतः तयार करतात\",\"झाडांचा पाला खाऊन\",\"माणसाने दिलेले अन्न खाऊन\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे वनस्पती स्वतःचे अन्न स्वतः तयार करतात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"ग्रामीण भागातील घरांच्या रचनेवर खालीलपैकी कोणत्या गोष्टीचा प्रभाव असतो?\",\"options\":[\"केवळ फॅशन\",\"हवामान, पर्जन्यमान व भौगोलिक परिस्थिती\",\"केवळ घराची किंमत\",\"गाड्यांची संख्या\"],\"answer\":1,\"explain\":\"परिसरातील हवामान आणि भौगोलिक स्थितीनुसार ग्रामीण घरांची रचना ठरते.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"विदर्भ व चंद्रपूर यांसारख्या आदिवासी भागात कोणत्या प्रकारची घरे आढळतात?\",\"options\":[\"बहुमजली इमारती\",\"धाब्याची घरे\",\"कुडाची घरे\",\"सिमेंटची घरे\"],\"answer\":2,\"explain\":\"पाठातील माहितीनुसार आदिवासी भागात कुडाची घरे आढळतात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"शहरांमध्ये बहुमजली इमारती का बांधल्या जातात?\",\"options\":[\"शहरात वस्ती दाट असते आणि जागा कमी असते\",\"शहरात पाऊस खूप पडतो\",\"शहरात माती उपलब्ध नसते\",\"शहरात झाडे नसतात\"],\"answer\":0,\"explain\":\"शहरी भागात लोकसंख्या जास्त आणि वस्ती दाट असल्याने उंच इमारती बांधल्या जातात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"पठारी प्रदेशात, जिथे मध्यम पाऊस पडतो, तिथे कोणत्या प्रकारची घरे असतात?\",\"options\":[\"कौलारू घरे\",\"धाब्याची मातीची घरे\",\"कुडाची घरे\",\"काचेची घरे\"],\"answer\":1,\"explain\":\"मध्यम पर्जन्यमान असलेल्या पठारी प्रदेशात धाब्याची व मातीची घरे आढळतात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"ग्रामीण भागातील घरे बहुतेक कोणत्या स्वरूपाची असतात?\",\"options\":[\"पक्की\",\"कच्ची\",\"बहुमजली\",\"स्टीलची\"],\"answer\":1,\"explain\":\"नैसर्गिक साधनांपासून बनवलेली ग्रामीण घरे बहुतेक कच्ची असतात.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला एखादे पक्के घर बांधायचे असेल, तर तुम्ही खालीलपैकी कोणते साहित्य निवडाल?\",\"options\":[\"गवत आणि पालापाचोळा\",\"बांबू आणि माती\",\"सिमेंट आणि सळया\",\"नारळाच्या झावळ्या\"],\"answer\":2,\"explain\":\"पक्के घर बांधण्यासाठी सिमेंट आणि लोखंडी सळयांची गरज असते.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मानव समूहाने वस्ती करून राहतो, यावरून काय समजते?\",\"options\":[\"मानवाला एकटे राहायला आवडते\",\"मानव हा सामाजिक प्राणी असून तो एकत्र राहतो\",\"मानवाला अन्नाची गरज नसते\",\"मानव फक्त जंगलात राहतो\"],\"answer\":1,\"explain\":\"मानव समूहाने राहतो कारण त्याला सुरक्षितता आणि सहकार्याची गरज असते.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रात घराच्या छतावर काय दिसत आहे आणि ते कोणत्या प्रदेशाचे वैशिष्ट्य आहे?\",\"options\":[\"सपाट छत - पठारी प्रदेश\",\"कौलारू उतरते छत - कोकण प्रदेश\",\"गवताचे छत - आदिवासी भाग\",\"सिमेंटचे छत - शहरी भाग\"],\"answer\":1,\"explain\":\"चित्र १ मध्ये कौलारू आणि उतरते छत दिसत आहे, जे कोकणातील घरांचे वैशिष्ट्य आहे.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"16\\/080_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील वस्तीचे निरीक्षण केल्यास ती कोणत्या भागातील वाटते?\",\"options\":[\"शहरी भाग\",\"ग्रामीण भाग\",\"औद्योगिक भाग\",\"वाळवंटी भाग\"],\"answer\":1,\"explain\":\"चित्र २ मध्ये मोकळी जागा, कौलारू आणि गवताची घरे तसेच बैलगाडी दिसत असल्याने ती ग्रामीण वस्ती आहे.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"16\\/080_102.jpg\"},{\"q\":\"दिलेल्या चित्रात शेतीशी संबंधित कोणती साधने आणि कामे दिसत आहेत?\",\"options\":[\"नांगर, कुळव आणि लावणीचे काम\",\"कार, बस आणि रस्ते बांधणी\",\"संगणक, लॅपटॉप आणि ऑफिसचे काम\",\"विमान, जहाज आणि वाहतूक\"],\"answer\":0,\"explain\":\"चित्र ३ मध्ये शेतीची अवजारे (नांगर, कुळव) आणि शेतात काम करणाऱ्या स्त्रिया दिसत आहेत.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"16\\/070_103.jpg\"},{\"q\":\"मानवी निवाऱ्याचे साधारण दोन प्रकार कोणते आहेत?\",\"options\":[\"जंगलातील घरे व पाण्यातील घरे\",\"शहरी घरे व ग्रामीण घरे\",\"पर्वतावरील घरे व गुहा\",\"हवेतील घरे व जमिनीवरील घरे\"],\"answer\":1,\"explain\":\"पाठात मानवी निवाऱ्याचे शहरी आणि ग्रामीण असे दोन मुख्य प्रकार दिले आहेत.\",\"topic\":\"मानवी निवारा आणि घरांचे प्रकार\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"लोकसंख्या वाढल्यामुळे खालीलपैकी कशाच्या संख्येत वाढ होत आहे?\",\"options\":[\"जंगलांच्या\",\"घरांच्या\",\"नद्यांच्या\",\"पर्वतांच्या\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, जसजशी लोकसंख्या वाढते तशी वस्त्यांच्या व घरांच्या संख्येत वाढ होत आहे.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"ग्रामीण भागातील घरे बांधण्यासाठी खालीलपैकी कोणत्या नैसर्गिक साधनाचा वापर केला जातो?\",\"options\":[\"सिमेंट\",\"लोखंड\",\"माती\",\"काच\"],\"answer\":2,\"explain\":\"ग्रामीण भागातील घरे माती, शेण, बांबू, लाकूड, गवत, दगड यांपासून बनवलेली असतात.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"पर्यावरणपूरक घरांचे मुख्य वैशिष्ट्य काय आहे?\",\"options\":[\"ती खूप उंच असतात\",\"ती पर्यावरणाचे रक्षण करतात\",\"ती फक्त शहरात असतात\",\"ती खूप महाग असतात\"],\"answer\":1,\"explain\":\"पर्यावरणपूरक घरे ही पर्यावरणाचे रक्षण करणारी असतात.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"पर्यावरणपूरक घरांमध्ये कोणत्या प्रकारच्या ऊर्जा साधनांचा जास्त वापर केला जातो?\",\"options\":[\"पारंपरिक ऊर्जा\",\"अपारंपरिक ऊर्जा\",\"विद्युत ऊर्जा\",\"अणू ऊर्जा\"],\"answer\":1,\"explain\":\"अशा घरांमध्ये पवन ऊर्जा, सौर ऊर्जा, बायोगॅस यांसारख्या अपारंपरिक ऊर्जा साधनांचा वापर होतो.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शहरी वस्त्यांची प्रचंड वाढ पर्यावरणासाठी कशी ठरत आहे?\",\"options\":[\"फायदेशीर\",\"हानिकारक\",\"सुरक्षित\",\"उपयुक्त\"],\"answer\":1,\"explain\":\"शहरी वस्त्यांची प्रचंड वाढ ही पर्यावरणाला हानिकारक ठरत आहे.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"पर्यावरणपूरक घरांमध्ये नैसर्गिक प्रकाश व हवा खेळती राहण्यासाठी काय व्यवस्था केलेली असते?\",\"options\":[\"मोठे पंखे लावले जातात\",\"एअर कंडिशनर वापरले जातात\",\"नैसर्गिक व्यवस्था केलेली असते\",\"खिडक्या बंद ठेवल्या जातात\"],\"answer\":2,\"explain\":\"अशा घरांमध्ये नैसर्गिक प्रकाश व हवा खेळती राहण्यासाठी विशेष व्यवस्था केलेली असते.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला पर्यावरणपूरक घर बांधायचे असेल, तर तुम्ही पाण्याचे काय कराल?\",\"options\":[\"पाणी वाया घालवू\",\"पाण्याचा पुनर्वापर करू\",\"पाणी साठवणार नाही\",\"पाणी फक्त बागेला देऊ\"],\"answer\":1,\"explain\":\"पर्यावरणपूरक घरांमध्ये पाण्याचा पुनर्वापर केला जातो.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात घराच्या छतावर निळ्या रंगाची काय बसवलेली दिसत आहेत?\",\"options\":[\"पाण्याच्या टाक्या\",\"सौर तावदाने (Solar Panels)\",\"डिश अँटेना\",\"विटांचे थर\"],\"answer\":1,\"explain\":\"चित्रात घराच्या छतावर सौर ऊर्जेसाठी सौर तावदाने (Solar Panels) बसवलेली दिसत आहेत.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"16\\/081_101.jpg\"},{\"q\":\"दिलेल्या चित्रात घरासमोर असलेल्या निळ्या आणि हिरव्या रंगाच्या पेट्या कशासाठी वापरल्या जात असाव्यात?\",\"options\":[\"खेळणी ठेवण्यासाठी\",\"कचरा व्यवस्थापन व पुनर्वापर\",\"बैठक व्यवस्था\",\"पाणी साठवण्यासाठी\"],\"answer\":1,\"explain\":\"पर्यावरणपूरक घरांमध्ये टाकाऊ वस्तूंचा पुनर्वापर केला जातो, त्यासाठी कचरा वर्गीकरण महत्त्वाचे आहे.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"16\\/081_101.jpg\"},{\"q\":\"पर्यावरणपूरक घरांमध्ये टाकाऊ वस्तूंचे काय केले जाते?\",\"options\":[\"त्या फेकून दिल्या जातात\",\"त्या जाळल्या जातात\",\"त्यांचा पुनर्वापर केला जातो\",\"त्या जमिनीत गाडल्या जातात\"],\"answer\":2,\"explain\":\"पर्यावरणपूरक घरांमध्ये ज्या वस्तू टाकाऊ आहेत त्यांचा पुनर्वापर केला जातो.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"पवन ऊर्जा आणि सौर ऊर्जा यांचा वापर केल्यामुळे काय साध्य होते?\",\"options\":[\"पर्यावरणाची हानी होते\",\"नैसर्गिक साधनांची बचत होते\",\"घराची उंची वाढते\",\"पाण्याचा वापर वाढतो\"],\"answer\":1,\"explain\":\"अपारंपरिक ऊर्जा साधनांचा वापर केल्यामुळे नैसर्गिक साधनांचे रक्षण होते व हानी टाळता येते.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"पर्यावरणपूरक घरांच्या बांधकामात वापरलेल्या साहित्यामुळे पर्यावरणावर काय परिणाम होतो?\",\"options\":[\"पर्यावरणाला हानी पोहोचत नाही\",\"पर्यावरण दूषित होते\",\"जमिनीची धूप होते\",\"हवा प्रदूषण वाढते\"],\"answer\":0,\"explain\":\"पर्यावरणपूरक घरे बांधताना वापरलेल्या साहित्यामुळे पर्यावरणाला हानी पोहोचत नाही.\",\"topic\":\"पर्यावरणपूरक निवारा\",\"part\":9,\"bloom\":\"evaluate\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28');
INSERT INTO `ep_topic_packs` VALUES (21483,16,4,'EVS Part 1','mr','जागरूकता हीच सुरक्षा','[\"आपत्ती म्हणजे अचानक उद्भवणारी आणि मोठा नुकसान करणारी घटना.\",\"नैसर्गिक आपत्ती: पाऊस, भूकंप, दरड कोसळणे, चक्रीवादळ, दुष्काळ इत्यादी.\",\"मानवनिर्मित आपत्ती: आग, प्रदूषण, युद्ध, अपघात, शॉर्टसर्किट.\",\"दुष्काळ म्हणजे पाऊस कमी पडल्यामुळे पाण्याची टंचाई.\",\"दुष्काळावर मात करण्यासाठी पाण्याचे नियोजन, बंधारे, तलाव, धरणे बांधणे.\",\"तिबक व तुषार सिंचन वापरण्याने पाण्याची बचत होते.\",\"चक्रीवादळामुळे वेगाने वारे, मुसळधार पाऊस, समुद्री उंच लाटा निर्माण होतो.\",\"चक्रीवादळापासून बचाव: हवामान खात्याने संदेश ऐकणे, सुरक्षित ठिकाणी राहणे, अनावश्यक प्रवास टाळणे.\",\"अतिवृष्टीमुळे नद्या-नाल्यांमध्ये पाणी भरतो, पूर येतो, घरे, पिके, झाडे नष्ट होतात.\",\"घरात सुरक्षित राहण्यासाठी गॅस, विजेची उपकरणे, धोकादायक रसायने, उंची ठिकाणी काळजी घ्यावी.\",\"लिफ्टमध्ये वडीलधार्यांसोबतच जाणे, लहान मुलांना आधार देणे, दृष्टिहीन मदत करणे.\",\"दृष्टिमित्र बनवणे: डोळ्यांवर पट्टी बांधणे, आधार देणे, मार्गदर्शन करणे.\",\"अनोळखी व्यक्‍तीने काही देण्याचा प्रयत्न केल्यास तुरंत \'नाही\' म्हणा, बोलणे व थांबणे टाळणे.\",\"बळजबरीने पकडण्याचा प्रयत्न केल्यास शांत राहणे, हातापात करणे, धक्का देणे.\",\"सुरक्षा चिन्हे: जीवनरक्षक पिशवी तयार करणे, आपत्ती व्यवस्थापन क्रमांक जाणून घेणे (पोलीस-100, अग्निशमन-101, अंबुलन्स-108\\/102, बाल मदत-1098, आपत्ती व्यवस्थापन-1077).\"]','[{\"q\":\"इर्शाळवाडीची दुर्घटना कोणत्या तारखेला घडली?\",\"options\":[\"१९ जून २०२३\",\"१९ जुलै २०२३\",\"१५ ऑगस्ट २०२३\",\"२६ जानेवारी २०२३\"],\"answer\":1,\"explain\":\"पाठातील मजकुरानुसार, १९ जुलै २०२३ हा दिवस इर्शाळवाडीसाठी दुःखद ठरला.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"इर्शाळवाडी हे गाव कोणत्या जिल्ह्यात आहे?\",\"options\":[\"पुणे\",\"ठाणे\",\"रायगड\",\"रत्नागिरी\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट उल्लेख आहे की ही घटना रायगड जिल्ह्यातील खालापूर तालुक्यात घडली.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"इर्शाळवाडीची घटना कोणत्या प्रकारचे संकट आहे?\",\"options\":[\"मानवनिर्मित संकट\",\"नैसर्गिक संकट\",\"रासायनिक संकट\",\"तांत्रिक संकट\"],\"answer\":1,\"explain\":\"डोंगर कोसळणे किंवा दरड कोसळणे हे एक नैसर्गिक संकट आहे.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मजकुरानुसार, दरड कोसळण्याचे मुख्य कारण काय होते?\",\"options\":[\"भूकंप\",\"अति पाऊस\",\"वादळ\",\"वणवा\"],\"answer\":1,\"explain\":\"अति पावसामुळे रात्रीच्या सुमारास अचानक दरड कोसळली असे मजकुरात दिले आहे.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात दुर्घटनेनंतर घरांची काय अवस्था दिसत आहे?\",\"options\":[\"घरे सुरक्षित आहेत\",\"घरे नवीन बांधलेली दिसत आहेत\",\"घरे पूर्णपणे उद्ध्वस्त होऊन ढिगाऱ्याखाली गाडली गेली आहेत\",\"घरांना फक्त रंग लावला आहे\"],\"answer\":2,\"explain\":\"चित्रात घरांचे अवशेष आणि मातीचे ढिगारे दिसत आहेत, ज्यावरून ती नष्ट झाल्याचे समजते.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"16\\/084_101.jpg\"},{\"q\":\"दिलेल्या चित्रात डोंगराचा भाग कोसळल्यामुळे वस्तीवर काय पसरलेले दिसत आहे?\",\"options\":[\"केवळ पाणी\",\"माती आणि दगडांचे ढिगारे\",\"वाळू\",\"फुले\"],\"answer\":1,\"explain\":\"चित्रात दरड कोसळल्यामुळे माती आणि दगडांचे मोठे ढिगारे घरांवर पसरलेले स्पष्ट दिसत आहेत.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"16\\/084_101.jpg\"},{\"q\":\"रात्री अकराच्या सुमारास ही घटना घडल्यामुळे लोकांवर काय परिणाम झाला असावा?\",\"options\":[\"लोक शेतात काम करत होते\",\"लोक शाळेत होते\",\"लोक गाढ झोपेत असल्याने त्यांना सावरायला वेळ मिळाला नाही\",\"लोक प्रवासात होते\"],\"answer\":2,\"explain\":\"मजकुरात \'इर्शाळवाडी गाढ झोपेत असताना\' असा उल्लेख आहे, ज्यामुळे जीवितहानी जास्त झाली.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"डोंगर कोसळल्यामुळे मृत पावलेल्या लोकांचे मृतदेह कोठे गाडले गेले?\",\"options\":[\"नदीच्या पात्रात\",\"मातीच्या ढिगाऱ्याखाली\",\"झाडांच्या फांद्यांमध्ये\",\"रस्त्यावर\"],\"answer\":1,\"explain\":\"मजकुरानुसार, मृतदेह टेकडीवरील मातीच्या ढिगाऱ्याखाली गाडले गेले.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"डोंगर कोसळण्यासारख्या नैसर्गिक संकटामुळे खालीलपैकी कशाचे नुकसान होते?\",\"options\":[\"केवळ घरांचे\",\"केवळ शेतीचे\",\"केवळ झाडांचे\",\"घरे, शेते आणि झाडे या सर्वांचे\"],\"answer\":3,\"explain\":\"मजकुरात म्हटले आहे की घरे, शेते, झाडे, सगळे नष्ट झाले होते.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"अति पाऊस होत असताना डोंगराच्या पायथ्याशी राहणाऱ्या लोकांनी कोणती जागरूकता दाखवणे गरजेचे आहे?\",\"options\":[\"घरातच थांबून राहावे\",\"दरड कोसळण्याच्या शक्यतेमुळे सुरक्षित ठिकाणी स्थलांतर करावे\",\"शेतात काम करत राहावे\",\"पावसात फिरायला जावे\"],\"answer\":1,\"explain\":\"इर्शाळवाडीच्या घटनेवरून हे समजते की अशा वेळी सुरक्षिततेसाठी सतर्क राहणे आवश्यक आहे.\",\"topic\":\"जागरूकता हीच सुरक्षा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"अचानक उद्भवणाऱ्या आणि मोठ्या प्रमाणात नुकसान करणाऱ्या संकटाला काय म्हणतात?\",\"options\":[\"उत्सव\",\"आपत्ती\",\"सण\",\"नियोजन\"],\"answer\":1,\"explain\":\"पाठातील व्याख्येनुसार, अचानक उद्भवणारे आणि मोठे नुकसान घडवणारे संकट म्हणजे आपत्ती होय.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"आपत्तीमुळे मानवाची कोणत्या प्रकारची हानी मोठ्या प्रमाणात होते?\",\"options\":[\"केवळ अन्नाची हानी\",\"केवळ खेळाची हानी\",\"जीवित व आर्थिक हानी\",\"केवळ वेळेची हानी\"],\"answer\":2,\"explain\":\"आपत्तीमुळे मानवाची जीवित व आर्थिक हानी मोठ्या प्रमाणात होते असे पाठात नमूद केले आहे.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिकरीत्या येणाऱ्या आपत्तीला काय म्हणतात?\",\"options\":[\"मानवनिर्मित आपत्ती\",\"नैसर्गिक आपत्ती\",\"कृत्रिम आपत्ती\",\"सांस्कृतिक आपत्ती\"],\"answer\":1,\"explain\":\"नैसर्गिकरीत्या येणाऱ्या आपत्तीला \'नैसर्गिक आपत्ती\' म्हणतात.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणती नैसर्गिक आपत्ती आहे?\",\"options\":[\"युद्ध\",\"प्रदूषण\",\"भूकंप\",\"अपघात\"],\"answer\":2,\"explain\":\"भूकंप ही निसर्गाकडून येणारी आपत्ती असल्याने ती नैसर्गिक आपत्ती आहे.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"मानवाच्या चुकांमुळे आणि हव्यासामुळे निर्माण होणाऱ्या आपत्तीला काय म्हणतात?\",\"options\":[\"नैसर्गिक आपत्ती\",\"मानवनिर्मित आपत्ती\",\"दैवी आपत्ती\",\"अकस्मात आपत्ती\"],\"answer\":1,\"explain\":\"मानवाच्या चुकांमुळे व हव्यासामुळे निर्माण होणाऱ्या आपत्तीला \'मानवनिर्मित आपत्ती\' म्हणतात.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती मानवनिर्मित आपत्ती आहे?\",\"options\":[\"चक्रीवादळ\",\"आग लागणे\",\"दुष्काळ\",\"अतिवृष्टी\"],\"answer\":1,\"explain\":\"आग लागणे ही मानवाच्या चुकांमुळे घडू शकणारी मानवनिर्मित आपत्ती आहे.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पाठात दिलेल्या माहितीनुसार, आपत्तीचे मुख्य किती प्रकार आहेत?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"पाठात आपत्तीचे नैसर्गिक आणि मानवनिर्मित असे दोन प्रकार सांगितले आहेत.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दरड कोसळणे, गारपीट आणि अतिवृष्टी यांचा समावेश कोणत्या गटात होतो?\",\"options\":[\"मानवनिर्मित आपत्ती\",\"नैसर्गिक आपत्ती\",\"अपघात\",\"युद्ध\"],\"answer\":1,\"explain\":\"दरड कोसळणे, गारपीट आणि अतिवृष्टी ही निसर्गातील संकटे असल्याने ती नैसर्गिक आपत्ती आहेत.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मानवनिर्मित आपत्ती कशामुळे ओढवतात?\",\"options\":[\"निसर्गाच्या चक्रामुळे\",\"मानवाच्या चुका आणि हव्यासामुळे\",\"ग्रहांच्या स्थितीमुळे\",\"समुद्राच्या लाटांमुळे\"],\"answer\":1,\"explain\":\"मानवाच्या चुकांमुळे तसेच हव्यासामुळे निसर्गात हानी होऊन मानवनिर्मित आपत्ती निर्माण होतात.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"युद्ध आणि प्रदूषण या आपत्तींना मानवनिर्मित का म्हटले जाते?\",\"options\":[\"कारण त्या निसर्गामुळे होतात\",\"कारण त्या मानवाच्या कृतीमुळे व चुकांमुळे घडतात\",\"कारण त्या पावसाळ्यात येतात\",\"कारण त्या जमिनीखालून येतात\"],\"answer\":1,\"explain\":\"युद्ध आणि प्रदूषण हे मानवाच्या हव्यासामुळे आणि कृतीमुळे घडत असल्याने त्यांना मानवनिर्मित आपत्ती म्हणतात.\",\"topic\":\"आपत्ती म्हणजे काय?\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"सुका दुष्काळ म्हणजे नेमके काय?\",\"options\":[\"खूप जास्त पाऊस पडणे\",\"पाऊस कमी पडल्यामुळे पाण्याची टंचाई होणे\",\"नदीला पूर येणे\",\"जमिनीत पाणी साचणे\"],\"answer\":1,\"explain\":\"पाऊस कमी पडल्यामुळे निर्माण होणाऱ्या पाण्याच्या टंचाईला सुका दुष्काळ म्हणतात.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"काँक्रीटीकरणामुळे जमिनीवर कोणता परिणाम होतो?\",\"options\":[\"पाणी जमिनीत जास्त मुरते\",\"पाणी जमिनीत मुरत नाही\",\"झाडांची वाढ वेगाने होते\",\"पाऊस जास्त पडतो\"],\"answer\":1,\"explain\":\"काँक्रीटीकरणामुळे पाणी जमिनीत मुरण्यास अडथळा निर्माण होतो.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात जमिनीला पडलेल्या भेगा आणि लोकांची स्थिती काय दर्शवते?\",\"options\":[\"भरपूर पाऊस\",\"दुष्काळाची परिस्थिती\",\"शेतीची कापणी\",\"नदीचा पूर\"],\"answer\":1,\"explain\":\"चित्रातील भेगा पडलेली जमीन आणि लोकांची चिंता दुष्काळ दर्शवते.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"16\\/085_101.jpg\"},{\"q\":\"दिलेल्या चित्रात पिकांच्या मुळाशी नळीद्वारे पाणी देण्याच्या पद्धतीला काय म्हणतात?\",\"options\":[\"तुषार सिंचन\",\"ठिबक सिंचन\",\"कालवा सिंचन\",\"बादलीने पाणी देणे\"],\"answer\":1,\"explain\":\"चित्रात दाखवल्याप्रमाणे थेंब थेंब पाणी देण्याच्या पद्धतीला ठिबक सिंचन म्हणतात.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"16\\/086_101.jpg\"},{\"q\":\"दिलेल्या चित्रात कारंज्याप्रमाणे पिकांवर पाणी फवारण्याच्या पद्धतीला काय म्हणतात?\",\"options\":[\"ठिबक सिंचन\",\"नदी सिंचन\",\"तुषार सिंचन\",\"धरण सिंचन\"],\"answer\":2,\"explain\":\"चित्रात दाखवल्याप्रमाणे पावसासारखे पाणी फवारण्याच्या पद्धतीला तुषार सिंचन म्हणतात.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"16\\/086_102.jpg\"},{\"q\":\"दुष्काळावर मात करण्यासाठी शेतीमध्ये पाण्याचा वापर कसा करावा?\",\"options\":[\"जास्त पाणी लागणारी पिके घ्यावीत\",\"पाण्याचा अपव्यय करावा\",\"ठिबक व तुषार सिंचनाचा वापर करावा\",\"फक्त पावसाच्या पाण्यावर अवलंबून राहावे\"],\"answer\":2,\"explain\":\"ठिबक व तुषार सिंचनामुळे पाण्याची बचत होऊन दुष्काळावर मात करता येते.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते दुष्काळाचे एक कारण आहे?\",\"options\":[\"झाडे लावणे\",\"पाण्याचे योग्य नियोजन\",\"वृक्षतोड\",\"धरणे बांधणे\"],\"answer\":2,\"explain\":\"वृक्षतोड हे दुष्काळ पडण्याचे एक मुख्य कारण आहे.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दुष्काळात कोणाला पाण्याची टंचाई भासते?\",\"options\":[\"फक्त माणसांना\",\"फक्त जनावरांना\",\"फक्त शेतीला\",\"लोक, जनावरे आणि शेती या सर्वांना\"],\"answer\":3,\"explain\":\"दुष्काळात पाणी नसल्यामुळे लोक, प्राणी आणि पिके या सर्वांवर परिणाम होतो.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पाण्याचे नियोजन करण्यासाठी खालीलपैकी कोणता उपाय योग्य आहे?\",\"options\":[\"पाण्याचा अपव्यय करणे\",\"तलाव, बंधारे आणि धरणे बांधणे\",\"झाडे तोडणे\",\"जमिनीत पाणी न मुरवणे\"],\"answer\":1,\"explain\":\"तलाव आणि धरणे बांधल्यामुळे पाणी साठवून त्याचे नियोजन करता येते.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"दुष्काळाची तीव्रता कमी करण्यासाठी खालीलपैकी कोणता कृती कार्यक्रम सर्वात प्रभावी ठरेल?\",\"options\":[\"रस्ते काँक्रीटचे करणे\",\"झाडे लावणे आणि कमी पाण्यात येणारी पिके घेणे\",\"पाणी साठवणे बंद करणे\",\"शेतीसाठी जास्त पाणी वापरणे\"],\"answer\":1,\"explain\":\"वृक्षारोपण आणि कमी पाण्याची पिके घेणे हे दुष्काळावर मात करण्याचे प्रभावी उपाय आहेत.\",\"topic\":\"दुष्काळ आणि त्याचे नियोजन\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"अतिवृष्टी म्हणजे काय?\",\"options\":[\"कमी पाऊस पडणे\",\"मध्यम पाऊस पडणे\",\"खूप जास्त पाऊस पडणे\",\"अजिबात पाऊस न पडणे\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, अतिवृष्टी म्हणजे खूप जास्त पाऊस पडणे होय.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हवामानाचा अंदाज आणि धोक्याचा इशारा देण्याचे काम कोणते खाते करते?\",\"options\":[\"पोलीस खाते\",\"हवामान खाते\",\"रेल्वे खाते\",\"शिक्षण खाते\"],\"answer\":1,\"explain\":\"चक्रीवादळ किंवा पावसाचा इशारा हवामान खाते देते.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"चक्रीवादळामुळे समुद्रात काय बदल होतात?\",\"options\":[\"उंच लाटा निर्माण होतात\",\"पाणी आटते\",\"पाणी गोठते\",\"समुद्र शांत होतो\"],\"answer\":0,\"explain\":\"चक्रीवादळामुळे समुद्रात खूप वेगाने वारे वाहतात आणि उंच लाटा निर्माण होतात.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"अतिवृष्टीमुळे पूर आल्यास सुरक्षिततेसाठी कोठे जावे?\",\"options\":[\"नदीच्या काठी\",\"सखल भागात\",\"उंच ठिकाणी\",\"झाडाच्या खाली\"],\"answer\":2,\"explain\":\"पुराच्या पाण्यापासून वाचण्यासाठी जनवस्तीत सुरक्षित किंवा उंच ठिकाणी जावे.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील बातमीनुसार, कोणत्या जिल्ह्याला धोक्याची सूचना (अलर्ट) देण्यात आली नाही?\",\"options\":[\"रायगड\",\"रत्नागिरी\",\"पुणे\",\"सिंधुदुर्ग\"],\"answer\":2,\"explain\":\"चित्रातील बातमीत रायगड, रत्नागिरी आणि सिंधुदुर्ग या जिल्ह्यांचा उल्लेख आहे, पुणे जिल्ह्याचा नाही.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"16\\/087_101.jpg\"},{\"q\":\"दिलेल्या चित्रात अतिवृष्टीचा कोणता परिणाम प्रामुख्याने दिसून येत आहे?\",\"options\":[\"जमिनीला भेगा पडल्या आहेत\",\"सर्वत्र पाणी साचून पूर आला आहे\",\"मोठी आग लागली आहे\",\"वादळामुळे झाडे उन्मळून पडली आहेत\"],\"answer\":1,\"explain\":\"चित्रात अतिवृष्टीमुळे नद्या-नाल्यांचे पाणी वस्तीत शिरून पूर आल्याचे दिसत आहे.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"16\\/088_101.jpg\"},{\"q\":\"चक्रीवादळापासून बचाव करण्यासाठी खालीलपैकी कोणती कृती योग्य आहे?\",\"options\":[\"अनावश्यक प्रवास करणे\",\"हवामान खात्याने दिलेले संदेश ऐकणे\",\"समुद्रकिनारी फिरायला जाणे\",\"विजेच्या खांबाखाली उभे राहणे\"],\"answer\":1,\"explain\":\"सुरक्षिततेसाठी हवामान खात्याचे संदेश ऐकणे आणि सुरक्षित ठिकाणी राहणे महत्त्वाचे आहे.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"लोकांच्या मदतीसाठी शासन कोणती यंत्रणा तयार ठेवते?\",\"options\":[\"आपत्कालीन यंत्रणा\",\"व्यापार यंत्रणा\",\"करमणूक यंत्रणा\",\"वाहतूक यंत्रणा\"],\"answer\":0,\"explain\":\"संकटकाळात लोकांच्या मदतीसाठी शासन आपत्कालीन यंत्रणा सज्ज ठेवते.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"अतिवृष्टीमुळे खालीलपैकी कोणाचे नुकसान होते?\",\"options\":[\"केवळ पिकांचे\",\"केवळ घरांचे\",\"केवळ जनावरांचे\",\"घरे, पिके आणि जनावरे या सर्वांचे\"],\"answer\":3,\"explain\":\"अतिवृष्टीमुळे पूर येतो आणि घरे, पिके, झाडे, जनावरे इत्यादींचे मोठे नुकसान होते.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"चक्रीवादळाच्या वेळी वाऱ्याचा वेग कसा असतो?\",\"options\":[\"खूप मंद\",\"खूप वेगवान\",\"वारे वाहत नाहीत\",\"नेहमीसारखा\"],\"answer\":1,\"explain\":\"चक्रीवादळाच्या वेळी वारे खूप वेगाने वाहतात.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"चक्रीवादळामुळे गावात वीज गेल्यास तुम्ही कोणता उपाय सुचवाल?\",\"options\":[\"विजेच्या तारांना स्पर्श करणे\",\"अंधारात बाहेर खेळायला जाणे\",\"टॉर्च किंवा बॅटरीचा वापर करणे\",\"टीव्ही सुरू करण्याचा प्रयत्न करणे\"],\"answer\":2,\"explain\":\"वीज गेल्यावर सुरक्षिततेसाठी टॉर्च किंवा बॅटरीचा वापर करणे हा योग्य उपाय आहे.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"अतिवृष्टीमुळे नद्या-नाल्यांमध्ये पाणी भरल्यास काय होते?\",\"options\":[\"दुष्काळ पडतो\",\"पूर येतो\",\"थंडी वाढते\",\"भूकंप होतो\"],\"answer\":1,\"explain\":\"अतिवृष्टीमुळे नद्या-नाल्यांमध्ये पाणी भरते आणि पूर येतो.\",\"topic\":\"चक्रीवादळ आणि अतिवृष्टी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"आपत्तीच्या वेळी सोबत नेण्यासाठी तयार केलेल्या पिशवील