part\":4,\"bloom\":\"remember\",\"figure_image\":\"16\\/100_102.jpg\"},{\"q\":\"कंपोस्ट खत तयार करण्यासाठी कोणत्या प्रकारचा कचरा वापरला जातो?\",\"options\":[\"प्लॅस्टिकच्या पिशव्या\",\"ओला कचरा\",\"बिघडलेले चार्जर\",\"जुने पुठ्ठे\"],\"answer\":1,\"explain\":\"मजकुरात दिले आहे की ओला कचरा कुजवून खत तयार केले जाते.\",\"topic\":\"कचरा व्यवस्थापन\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'शेंगदाण्याची टरफले\' आणि \'कापसाच्या वाती\' हे ओल्या कचऱ्यात का मोडतात?\",\"options\":[\"कारण ते प्लॅस्टिकचे आहेत\",\"कारण ते काही दिवसांनी कुजतात\",\"कारण ते कारखान्यात जातात\",\"कारण ते जळत नाहीत\"],\"answer\":1,\"explain\":\"जे पदार्थ नैसर्गिकरित्या कुजतात, त्यांचा समावेश ओल्या कचऱ्यात होतो.\",\"topic\":\"कचरा व्यवस्थापन\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"शाळेत खत तयार करण्यासाठी कचरा कशात टाकावा असे सांगितले आहे?\",\"options\":[\"प्लास्टिकच्या पिशवीत\",\"मोठ्या रिकाम्या पिंपात\",\"शाळेच्या मैदानात\",\"वर्गाच्या कोपऱ्यात\"],\"answer\":1,\"explain\":\"उताऱ्यात खड्डा खणून किंवा मोठ्या रिकाम्या पिंपात कचरा टाकण्यास सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खत तयार करण्यासाठी कोणत्या प्रकारचा कचरा वापरण्यास सांगितले आहे?\",\"options\":[\"सुका कचरा\",\"काच आणि प्लास्टिक\",\"ओला कचरा\",\"लोखंडी वस्तू\"],\"answer\":2,\"explain\":\"खत तयार करण्यासाठी रोज ओला कचरा टाकण्यास सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"कचरा टाकल्यानंतर त्यावर काय टाकणे आवश्यक आहे?\",\"options\":[\"वाळू\",\"दगड\",\"माती\",\"सिमेंट\"],\"answer\":2,\"explain\":\"ओल्या कचऱ्यासोबत त्यावर थोडी माती टाकण्यास सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खत तयार होण्यासाठी साधारण किती कालावधी लागतो?\",\"options\":[\"१-२ दिवस\",\"४-६ आठवडे\",\"१०-१२ महिने\",\"१ वर्ष\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार खत तयार होण्यासाठी ४-६ आठवडे लागतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"शाळेत तयार झालेल्या खताचा उपयोग कोठे करता येईल?\",\"options\":[\"शालेय परसबागेत\",\"रस्त्यावर\",\"वर्गाच्या स्वच्छतेसाठी\",\"पिण्याच्या पाण्यासाठी\"],\"answer\":0,\"explain\":\"तयार झालेल्या खताचा उपयोग शालेय परसबागेत करता येतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"कचरा कुजण्याची प्रक्रिया होण्यासाठी अधूनमधून काय करणे गरजेचे आहे?\",\"options\":[\"कचरा जाळणे\",\"पाणी शिंपडणे\",\"कचरा बाहेर काढणे\",\"खड्डा उघडा ठेवणे\"],\"answer\":1,\"explain\":\"प्रक्रियेसाठी कचऱ्यावर अधूनमधून पाणी शिंपडणे आवश्यक असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"शेतकरी शेतात खताचा वापर का करतात?\",\"options\":[\"तण वाढवण्यासाठी\",\"पिकांच्या जोमदार वाढीसाठी\",\"जमीन कडक करण्यासाठी\",\"कीटक वाढवण्यासाठी\"],\"answer\":1,\"explain\":\"पिकांची वाढ जोमदार व्हावी यासाठी शेतकरी खत वापरतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"शेणखत तयार करण्यासाठी जनावरांच्या मलमूत्रासोबत आणखी काय वापरले जाते?\",\"options\":[\"प्लास्टिकचे तुकडे\",\"उरलेला चारा\",\"केला जाणारा धूर\",\"केवळ पाणी\"],\"answer\":1,\"explain\":\"जनावरांच्या मलमूत्रासोबत उरलेल्या चाऱ्यापासून शेणखत तयार केले जाते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खत तयार करण्याच्या प्रक्रियेत \'झाकून ठेवणे\' ही पायरी का महत्त्वाची असावी?\",\"options\":[\"कचरा चोरीला जाऊ नये म्हणून\",\"प्रक्रिया व्यवस्थित होण्यासाठी\",\"कचरा दिसू नये म्हणून\",\"खड्डा भरण्यासाठी\"],\"answer\":1,\"explain\":\"खत तयार होण्यासाठी कचरा झाकून ठेवणे ही एक आवश्यक कृती आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या गोष्टीपासून बायोगॅस आणि शेणखत तयार करता येते?\",\"options\":[\"कागद आणि पुठ्ठा\",\"लोखंड आणि तांबे\",\"जनावरांचे मलमूत्र\",\"काचेच्या बाटल्या\"],\"answer\":2,\"explain\":\"जनावरांच्या मलमूत्रापासून बायोगॅस आणि शेणखत तयार केले जाते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"कचरा कमी करणे याला इंग्रजीत काय म्हणतात?\",\"options\":[\"Reuse\",\"Recycle\",\"Reduce\",\"Remove\"],\"answer\":2,\"explain\":\"कचरा कमी करणे म्हणजे \'Reduce\' होय.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जुनी झालेली वस्तू पुन्हा वापरणे म्हणजे काय?\",\"options\":[\"पुनर्वापर (Reuse)\",\"पुनर्चक्रीकरण (Recycle)\",\"कचरा कमी करणे (Reduce)\",\"कचरा टाकून देणे\"],\"answer\":0,\"explain\":\"वस्तू पुन्हा वापरणे म्हणजे पुनर्वापर (Reuse) होय.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"सुक्या कचऱ्यातील वस्तूंपासून नवीन वस्तू बनवण्याच्या प्रक्रियेला काय म्हणतात?\",\"options\":[\"कचरा साठवणे\",\"पुनर्चक्रीकरण (Recycle)\",\"कचरा कमी करणे\",\"पुनर्वापर\"],\"answer\":1,\"explain\":\"जुन्या वस्तूंपासून नवीन वस्तू बनवणे म्हणजे पुनर्चक्रीकरण होय.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"३R पाळल्यामुळे खालीलपैकी कोणता मुख्य फायदा होतो?\",\"options\":[\"कचरा वाढतो\",\"परिसर अस्वच्छ होतो\",\"परिसर स्वच्छ व सुंदर राहतो\",\"प्राण्यांना त्रास होतो\"],\"answer\":2,\"explain\":\"३R मुळे कचरा कमी होऊन परिसर स्वच्छ व सुंदर राहतो.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"टिश्यू पेपरऐवजी कापडी रुमाल वापरणे हे कशाचे उदाहरण आहे?\",\"options\":[\"कचरा कमी करणे (Reduce)\",\"पुनर्वापर (Reuse)\",\"पुनर्चक्रीकरण (Recycle)\",\"कचरा वाढवणे\"],\"answer\":0,\"explain\":\"कापडी रुमाल वापरल्याने कचरा कमी तयार होतो, म्हणून हे \'Reduce\' चे उदाहरण आहे.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जुन्या वर्तमानपत्रापासून पुन्हा कागद तयार करणे हे कोणत्या \'R\' चे उदाहरण आहे?\",\"options\":[\"Reduce\",\"Reuse\",\"Recycle\",\"Remove\"],\"answer\":2,\"explain\":\"जुन्या कागदापासून नवीन कागद बनवणे हे पुनर्चक्रीकरण (Recycle) आहे.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"तुमची पेन्सील छोटी झाली, तर तुम्ही काय कराल?\",\"options\":[\"ती लगेच फेकून द्याल\",\"ती शेवटपर्यंत वापराल\",\"दुसरी नवीन पेन्सील मागाल\",\"ती कचऱ्याच्या डब्यात टाकाल\"],\"answer\":1,\"explain\":\"कचरा कमी करण्यासाठी पेन्सील छोटी झाली तरी ती शेवटपर्यंत वापरावी.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"आइसक्रीमचा रिकामा डबा तुम्ही कशासाठी वापरू शकता?\",\"options\":[\"कचरा टाकण्यासाठी\",\"खेळणी किंवा पेन्सील ठेवण्यासाठी\",\"बाहेर फेकून देण्यासाठी\",\"जाळून टाकण्यासाठी\"],\"answer\":1,\"explain\":\"रिकाम्या डब्याचा वापर वस्तू ठेवण्यासाठी करणे हा पुनर्वापर (Reuse) आहे.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"वहीतील उरलेल्या कोऱ्या पानांचा योग्य वापर कसा करावा?\",\"options\":[\"पाने फाडून फेकून द्यावीत\",\"कच्च्या कामासाठी किंवा चित्रे काढण्यासाठी वापरावीत\",\"वही रद्दीत टाकावी\",\"पाने जाळून टाकावीत\"],\"answer\":1,\"explain\":\"कोऱ्या पानांचा वापर कच्च्या कामासाठी करणे हा पुनर्वापर आहे.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"प्लॅस्टिकच्या पेल्याऐवजी स्टीलचा पेला वापरल्याने काय साध्य होते?\",\"options\":[\"कचरा वाढतो\",\"कचरा कमी होतो (Reduce)\",\"पाणी खराब होते\",\"काहीच फरक पडत नाही\"],\"answer\":1,\"explain\":\"स्टीलचा पेला पुन्हा पुन्हा वापरता येतो, ज्यामुळे प्लॅस्टिकचा कचरा कमी होतो.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"३R च्या नियमांचे पालन केल्यामुळे कोणाचे संरक्षण होते?\",\"options\":[\"केवळ इमारतींचे\",\"केवळ वाहनांचे\",\"वनस्पती आणि प्राण्यांचे\",\"केवळ खेळण्यांचे\"],\"answer\":2,\"explain\":\"परिसर स्वच्छ राहिल्यामुळे वनस्पती आणि प्राणी सुरक्षित राहतात.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"वापरलेल्या प्लॅस्टिकच्या बाटल्यांपासून नवीन वस्तू बनवणे ही क्रिया कोणत्या गटात येते?\",\"options\":[\"कचरा वाढवणे\",\"पुनर्वापर (Reuse)\",\"पुनर्चक्रीकरण (Recycle)\",\"कचरा कमी करणे (Reduce)\"],\"answer\":2,\"explain\":\"जुन्या प्लॅस्टिकपासून नवीन वस्तू बनवणे म्हणजे पुनर्चक्रीकरण होय.\",\"topic\":\"३R चे महत्त्व\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"कचऱ्याचे कोणते दोन मुख्य गट करण्यास पाठात सुचवले आहे?\",\"options\":[\"काळा व पांढरा\",\"ओला व सुका\",\"मोठा व लहान\",\"जड व हलका\"],\"