",\"१४ जानेवारी\",\"१४ ऑक्टोबर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, राष्ट्रीय ऊर्जा संवर्धन दिन दरवर्षी १४ डिसेंबर रोजी साजरा केला जातो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या वस्तूमध्ये चुंबकाचा वापर केला जातो?\",\"options\":[\"लाकडी खुर्ची\",\"काचेचा पेला\",\"ध्वनिक्षेपक\",\"प्लास्टिकची बादली\"],\"answer\":2,\"explain\":\"दिलेल्या यादीत ध्वनिक्षेपक (Loudspeaker) हे चुंबक असलेल्या वस्तूंचे उदाहरण आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"राष्ट्रीय ऊर्जा संवर्धन दिन साजरा करण्याचा मुख्य उद्देश काय आहे?\",\"options\":[\"नवीन खेळणी तयार करणे\",\"ऊर्जेचा वापर वाढवणे\",\"ऊर्जेच्या योग्य वापरासाठी जनजागृती करणे\",\"चुंबकाचा शोध लावणे\"],\"answer\":2,\"explain\":\"ऊर्जेचा योग्य वापर करण्यासाठी जनजागृती करणे हा या दिवसाचा मुख्य उद्देश आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"टाळी वाजवताना प्रामुख्याने कोणती ऊर्जा वापरली जाते?\",\"options\":[\"सौर ऊर्जा\",\"स्नायू ऊर्जा\",\"विद्युत ऊर्जा\",\"अणू ऊर्जा\"],\"answer\":1,\"explain\":\"टाळी वाजवण्यासाठी आपण आपल्या शरीराची म्हणजेच स्नायूंची ऊर्जा वापरतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला दिशा ओळखायची असेल, तर तुम्ही पाठ्यपुस्तकात दिलेल्या कोणत्या साधनाचा वापर कराल?\",\"options\":[\"इलेक्ट्रिक मोटार\",\"होकायंत्र\",\"फ्रीजवरील स्टिकर्स\",\"ध्वनिक्षेपक\"],\"answer\":1,\"explain\":\"होकायंत्राचा वापर दिशा ओळखण्यासाठी केला जातो आणि त्यात चुंबक असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"बॅग किंवा दरवाजांच्या कुलुपांमध्ये चुंबकाचा वापर कशासाठी केला असावा?\",\"options\":[\"वस्तू जड करण्यासाठी\",\"वस्तू चमकण्यासाठी\",\"पकड मिळवण्यासाठी किंवा घट्ट बंद होण्यासाठी\",\"आवाज करण्यासाठी\"],\"answer\":2,\"explain\":\"चुंबक लोखंडी वस्तूंना चिकटते, त्यामुळे बॅग किंवा कुलुपे घट्ट बंद होण्यास मदत होते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या इलेक्ट्रॉनिक उपकरणामध्ये चुंबक असते असे मजकुरात नमूद केले आहे?\",\"options\":[\"संगणक (कंप्यूटर)\",\"गॅस शेगडी\",\"साधी पेन्सिल\",\"कापडी पिशवी\"],\"answer\":0,\"explain\":\"मजकुरात दिलेल्या यादीमध्ये \'कंप्यूटर\' मध्ये चुंबक असल्याचे सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"ऊर्जा संवर्धन (Conservation) म्हणजे काय असावे?\",\"options\":[\"ऊर्जा वाया घालवणे\",\"ऊर्जेची बचत आणि योग्य वापर करणे\",\"ऊर्जा वापरणे बंद करणे\",\"फक्त विद्युत ऊर्जेचा वापर करणे\"],\"answer\":1,\"explain\":\"ऊर्जा संवर्धन म्हणजे ऊर्जेचा अपव्यय टाळून तिचा योग्य आणि काटकसरीने वापर करणे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या पर्यायांपैकी कोणत्या वस्तूमध्ये चुंबक नसते?\",\"options\":[\"खेळणे\",\"कपाट (साधे लाकडी)\",\"कंपासपेटी\",\"इलेक्ट्रिक मोटार\"],\"answer\":1,\"explain\":\"मजकुरातील यादीत खेळणे, कंपासपेटी आणि इलेक्ट्रिक मोटार यांचा समावेश आहे, पण साध्या लाकडी कपाटाचा नाही.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"शिक्षकांनी विद्यार्थ्यांना चुंबकाची ओळख करून देण्यासाठी काय करणे अपेक्षित आहे?\",\"options\":[\"फक्त चित्र दाखवणे\",\"चुंबकाच्या शोधाची गोष्ट सांगून विविध चुंबक हाताळायला देणे\",\"चुंबक वापरू नका असे सांगणे\",\"केवळ पाठांतर करून घेणे\"],\"answer\":1,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, त्यांनी गोष्ट सांगून विद्यार्थ्यांना चुंबक हाताळायला द्यावेत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"\'खेळ खेळू या\' या उपक्रमासाठी खालीलपैकी कोणते साहित्य आवश्यक आहे?\",\"options\":[\"मातीची भांडी\",\"उपकरणांची चित्रकार्ड\",\"रंगीत खडू\",\"खेळण्यातील गाड्या\"],\"answer\":1,\"explain\":\"पाठातील मजकुरानुसार उपकरणांचे चित्र असलेली चित्रकार्ड आवश्यक आहेत.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"रिकाम्या खोक्यांवर कशाची नावे लिहिलेली असावीत?\",\"options\":[\"विद्यार्थ्यांची नावे\",\"ऊर्जा स्रोतांची नावे\",\"शाळेचे नाव\",\"गावांची नावे\"],\"answer\":1,\"explain\":\"खेळासाठी प्रत्येक ऊर्जा स्रोताचे नाव असलेले रिकामे खोके हवेत.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत एकूण किती प्रकारच्या ऊर्जा स्रोतांचे खोके दाखवले आहेत?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"तीन\"],\"answer\":3,\"explain\":\"आकृतीत विद्युत, सौर आणि उष्णता ऊर्जा असे तीन खोके दिसत आहेत.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"16\\/158_102.jpg\"},{\"q\":\"दिलेल्या आकृतीनुसार, जर तुमच्याकडे \'सौर चूल\' असलेले चित्रकार्ड असेल, तर तुम्ही ते कोणत्या खोक्यात टाकाल?\",\"options\":[\"विद्युत ऊर्जा\",\"सौर ऊर्जा\",\"उष्णता ऊर्जा\",\"कोणत्याही नाही\"],\"answer\":1,\"explain\":\"सौर चूल हा सौर ऊर्जेवर चालणारे उपकरण असल्याने ते सौर ऊर्जेच्या खोक्यात टाकावे.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"16\\/158_102.jpg\"},{\"q\":\"खेळ सुरू करताना सर्व चित्रकार्ड कशी ठेवायची आहेत?\",\"options\":[\"एकावर एक रचून\",\"लपवून\",\"पसरून\",\"खोक्यात भरून\"],\"answer\":2,\"explain\":\"मजकुरानुसार खेळ सुरू करताना सर्व चित्रकार्ड पसरून ठेवावीत.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चित्रकार्ड खोक्यात टाकल्यानंतर विद्यार्थ्याने काय करणे अपेक्षित आहे?\",\"options\":[\"चित्र काढून दाखवणे\",\"उपकरणाचे उपयोग अभिनयातून सांगणे\",\"खोके रंगवणे\",\"गाणे म्हणणे\"],\"answer\":1,\"explain\":\"विद्यार्थ्याने उपकरणाचे उपयोग भूमिका अभिनयातून सांगावेत असे पाठात म्हटले आहे.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"“मी नाशवंत वस्तू अनेक दिवस सुरक्षित ठेवतो, तर मी कोण?” या कोड्याचे उत्तर काय असेल?\",\"options\":[\"सौर कंदील\",\"इस्त्री\",\"फ्रीज (शीतपेय यंत्र)\",\"गॅस शेगडी\"],\"answer\":2,\"explain\":\"नाशवंत वस्तू सुरक्षित ठेवण्याचे काम फ्रीज करतो, हे मजकुरातील उदाहरणावरून स्पष्ट होते.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांनी या खेळाच्या माध्यमातून कोणत्या विषयावर चर्चा करणे आवश्यक आहे?\",\"options\":[\"ऊर्जा बचतीचे उपाय\",\"चित्रांचे रंग\",\"खोक्यांचा आकार\",\"विद्यार्थ्यांचे कपडे\"],\"answer\":0,\"explain\":\"शिक्षकांसाठी असलेल्या सूचनेनुसार खेळामधून ऊर्जा बचतींच्या उपायांची चर्चा करावी.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"या खेळातून विद्यार्थी प्रामुख्याने काय शिकतात?\",\"options\":[\"वेगाने धावणे\",\"उपकरणांचे वर्गीकरण आणि त्यांचे उपयोग\",\"चित्रकला\",\"खोके बनवणे\"],\"answer\":1,\"explain\":\"उपकरणे योग्य ऊर्जेच्या खोक्यात टाकणे आणि त्यांचे उपयोग सांगणे यातून वर्गीकरण व उपयोगांची माहिती मिळते.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"प्रत्येक विद्यार्थ्याला या खेळात संधी मिळणे का महत्त्वाचे आहे?\",\"options\":[\"खेळ लवकर संपवण्यासाठी\",\"सर्वांचा सहभाग व शिक्षण होण्यासाठी\",\"गोंधळ कमी करण्यासाठी\",\"शिक्षकांना विश्रांती मिळण्यासाठी\"],\"answer\":1,\"explain\":\"प्रत्येक विद्यार्थ्याला शिकण्याची संधी मिळावी यासाठी नियोजन करणे आवश्यक आहे.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"भूमिका अभिनय करताना इतर विद्यार्थ्यांनी काय करायचे आहे?\",\"options\":[\"गप्प बसायचे\",\"उपकरणाचे नाव ओळखायचे\",\"खोके हलवायचे\",\"चित्रे रंगवायची\"],\"answer\":1,\"explain\":\"एका विद्यार्थ्याने अभिनय केल्यावर इतर विद्यार्थ्यांनी त्या उपकरणाचे नाव ओळखायचे आहे.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर चित्रकार्डची संख्या वाढवायची असेल, तर तो निर्णय कोणी घ्यावा?\",\"options\":[\"विद्यार्थ्यांनी\",\"पालकांनी\",\"शिक्षकांनी\",\"मुख्याध्यापकांनी\"],\"answer\":2,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार त्यांनी आपल्या सोयीनुसार चित्रकार्डची संख्या वाढवावी.\",\"topic\":\"खेळ खेळू या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"ज्या दिवशी सूर्य बरोबर मध्यावर येतो, त्या दिवसाला काय म्हणतात?\",\"options\":[\"सूर्यग्रहण दिन\",\"शून्य छाया दिन\",\"मोठा दिवस\",\"प्रकाश दिन\"],\"answer\":1,\"explain\":\"पाठात स्पष्ट केले आहे की ज्या दिवशी सूर्य बरोबर मध्यावर येतो, त्याला \'शून्य छाया दिन\' म्हणतात.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"महाराष्ट्रात शून्य छाया दिवसाचा अनुभव साधारणतः कोणत्या महिन्यात येतो?\",\"options\":[\"जानेवारी\",\"मार्च\",\"मे\",\"ऑक्टोबर\"],\"answer\":2,\"explain\":\"पाठात दिलेल्या माहितीनुसार, महाराष्ट्रात हा अनुभव साधारणतः मे महिन्यात येतो.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शून्य छाया दिनी सावली कधी नाहीशी होते?\",\"options\":[\"सूर्योदयाच्या वेळी\",\"मध्यान्हच्या सुमारास\",\"सूर्यास्ताच्या वेळी\",\"मध्यरात्री\"],\"answer\":1,\"explain\":\"शून्य छाया दिनी मध्यान्हच्या (दुपारच्या) सुमारास सावली नाहीशी होते.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शून्य छाया दिनी सूर्याचे स्थान कोठे असते?\",\"options\":[\"क्षितिजावर\",\"ढगांच्या मागे\",\"बरोबर मध्यावर\",\"उत्तरेकडे\"],\"answer\":2,\"explain\":\"जेव्हा सूर्य बरोबर मध्यावर येतो, तेव्हाच शून्य छाया दिन होतो.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"भारतात शून्य छाया दिन कोणत्या ऋतूत येतो?\",\"options\":[\"हिवाळा\",\"पावसाळा\",\"उन्हाळा\",\"शरद\"],\"answer\":2,\"explain\":\"पाठात नमूद केले आहे की भारतात उन्हाळ्यात ही घटना घडते.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"पाठाच्या सुरुवातीला सावलीबद्दल काय सांगितले आहे?\",\"options\":[\"सावली नेहमी मोठी असते\",\"सावली आपली साथ कधीच सोडत नाही\",\"सावली फक्त रात्री दिसते\",\"सावली रंगाने पांढरी असते\"],\"answer\":1,\"explain\":\"पाठाची सुरुवात \'आपली सावली आपली साथ कधीच सोडत नाही\' या वाक्याने झाली आहे.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही मे महिन्यात महाराष्ट्रात असाल, तर तुम्हाला कोणता विशेष अनुभव घेता येईल?\",\"options\":[\"खूप पाऊस पडण्याचा\",\"सावली नाहीशी होण्याचा\",\"दिवस लहान होण्याचा\",\"बर्फ पडण्याचा\"],\"answer\":1,\"explain\":\"मे महिन्यात महाराष्ट्रात शून्य छाया दिन येतो, त्यामुळे सावली नाहीशी होण्याचा अनुभव घेता येतो.\",\"topic\":\"शून्य छाया दिन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"शून्य छाया दिनाचा अनुभव घेण्यासाठी तुम्हाला काय करावे लागेल?\",\"options\":[\"रात्री चंद्राकडे पाहावे लागेल\",\"दुपारी मध्यान्हच्