\":[\"भेदभाव\",\"समता\",\"राजेशाही\",\"प्रादेशिकवाद\"],\"answer\":1,\"explain\":\"स्वामींच्या संपूर्ण कार्याचा मुख्य आधार \'समता\' हा होता.\",\"topic\":\"श्रीचक्रधर स्वामी\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"संत नामदेव कोणत्या गावचे राहणारे होते?\",\"options\":[\"नरसी\",\"पैठण\",\"देहू\",\"आळंदी\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार संत नामदेव नरसी गावचे राहणारे होते.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"संत नामदेव कोणत्या देवाचे निस्सीम भक्त होते?\",\"options\":[\"श्री राम\",\"विठ्ठल\",\"श्री कृष्ण\",\"गणपती\"],\"answer\":1,\"explain\":\"संत नामदेव विठ्ठलाचे निस्सीम भक्त होते असे पाठात नमूद केले आहे.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"संत नामदेवांनी महाराष्ट्रभर संचार कशासाठी केला?\",\"options\":[\"व्यापारासाठी\",\"युद्धासाठी\",\"भागवत धर्माच्या प्रसारासाठी\",\"पर्यटनासाठी\"],\"answer\":2,\"explain\":\"त्यांनी भागवत धर्माच्या प्रसारासाठी महाराष्ट्रभर संचार केला.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"संत नामदेवांनी पंजाबातील लोकांना कोणता संदेश दिला?\",\"options\":[\"समतेचा\",\"भेदाभेदाचा\",\"शस्त्रांचा\",\"केवळ मराठी भाषेचा\"],\"answer\":0,\"explain\":\"ते पंजाबात गेले आणि तेथील लोकांना त्यांनी समतेचा संदेश दिला.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"शीख धर्माच्या \'गुरुग्रंथसाहेब\' या ग्रंथात कोणाची पदे समाविष्ट आहेत?\",\"options\":[\"संत ज्ञानेश्वर\",\"संत नामदेव\",\"संत तुकाराम\",\"संत एकनाथ\"],\"answer\":1,\"explain\":\"संत नामदेवांची काही हिंदी पदे शीख लोकांच्या \'गुरुग्रंथसाहेब\' या ग्रंथात आहेत.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"संत नामदेवांनी लोकांमध्ये जागृती निर्माण करण्यासाठी प्रामुख्याने काय केले?\",\"options\":[\"शाळा उघडल्या\",\"अनेक अभंग रचले व कीर्तने केली\",\"मोठी मंदिरे बांधली\",\"व्यायामशाळा सुरू केल्या\"],\"answer\":1,\"explain\":\"त्यांनी अनेक अभंग रचले, कीर्तने केली व जनतेत जागृती निर्माण केली.\",\"topic\":\"संत नामदेव\",\"part\":3,\"bloom\":\