,\"options\":[\"सर्वात बलाढ्य सरदाराला\",\"सर्वात कमकुवत सरदाराला\",\"नवीन सरदाराला\",\"परदेशी सरदाराला\"],\"answer\":0,\"explain\":\"विजापूरचा सर्वात बलाढ्य सरदार (अफजलखान) शिवाजींनी धुळीस मिळवला.\",\"topic\":\"खानाच्या फौजेची दाणादाण\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"विजयी झाल्यानंतर शिवराय कोठे गेले?\",\"options\":[\"विजापूरला\",\"गडावर\",\"जंगलात\",\"समुद्रावर\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच म्हटले आहे की विजयी होऊन शिवराय गडावर गेले.\",\"topic\":\"खानाच्या फौजेची दाणादाण\",\"part\":9,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21499,18,4,'EVS Part 2','mr','शर्थीने खिंड लढवली','[\"पन्हाळगड, घोडखिंड, विशाळगड हे तीन प्रमुख गड आहेत ज्यावर शिवाजी महाराजांनी लढाई केली.\",\"शिवरायांनी गडावर वेढा घातला आणि शत्रूला रोखण्यासाठी विविध युक्त्या वापरल्या.\",\"सिद्दी जौहर हे शिवाजीचे प्रमुख सरदार होते ज्यांनी गडावर वेढा घातला.\",\"बाजीप्रभू देशपांडे हे शौर्यवान योद्धा होते ज्यांनी घोडखिंडीत शत्रूला रोखले.\",\"शिवरायांनी वेढ्यातून सुटका करण्यासाठी \'युक्ती\' म्हणून शत्रूला गोंधळात टाकले.\",\"गडावर वेढा घातल्यावर शत्रूला पळून जाणे कठीण होते कारण गडाभोवती दगड आणि पाणी होते.\",\"घोडखिंडीत शत्रूला रोखण्यासाठी शत्रूच्या पायावर दगड फेकले जात होते.\",\"शिवरायांनी शत्रूच्या तुकड्यांना गोंधळात टाकण्यासाठी आवाज आणि तोफांचा वापर केला.\",\"शिवरायांच्या सेवेमध्ये \'शिवा काशिद\' नावाचा एक शूर पण क्रूर योद्धा होता.\",\"शिवरायांची शौर्य आणि धैर्यामुळे मराठ्यांना स्वराज्य मिळाले.\",\"शिवरायांनी गडावर वेढा घातला तेव्हा शत्रूने पळून जाण्याचा प्रयत्न केला.\",\"शिवरायांनी गडावर वेढा घातल्यावर शत्रूने पाण्याने भरलेल्या खिंडीतून पळून जाण्याचा प्रयत्न केला.\",\"शिवरायांनी शत्रूला रोखण्यासाठी घोडखिंडीत दगडांचा वर्षाव केला.\",\"शिवरायांनी शत्रूच्या तुकड्यांना गोंधळात टाकण्यासाठी आवाज आणि तोफांचा वापर केला.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\",\"शिवरायांनी शत्रूला रोखण्यासाठी \'बाजीप्रभू\' नावाच्या योद्ध्याला नेतृत्व दिले.\"]','[{\"q\":\"अफजलखानाच्या वधानंतर शिवाजी महाराजांनी विजापूरकरांचा कोणता गड जिंकला?\",\"options\":[\"प्रतापगड\",\"पन्हाळगड\",\"रायगड\",\"सिंहगड\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे, अफजलखानाच्या वधानंतर शिवाजी महाराजांनी पन्हाळगड जिंकला.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"शिवाजी महाराजांचा नाश करण्यासाठी आदिलशहाने कोणत्या सरदाराला पाठवले?\",\"options\":[\"फाजलखान\",\"अफजलखान\",\"सिद्दी जौहर\",\"सिद्दी मसूद\"],\"answer\":2,\"explain\":\"शिवाजी महाराजांचा नाश करण्यासाठी आदिलशहाने सिद्दी जौहर या सरदाराला पाठवले.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"सिद्दी जौहरसोबत त्याच्या बापाच्या वधाचा सूड घेण्यासाठी कोण निघाला?\",\"options\":[\"फाजलखान\",\"आदिलशहा\",\"सिद्दी मसूद\",\"बडी साहेबीण\"],\"answer\":0,\"explain\":\"अफजलखानाचा मुलगा फाजलखान बापाच्या वधाचा सूड घेण्यासाठी सिद्दी जौहरसोबत निघाला.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"सिद्दी जौहरच्या स्वभावाबद्दल उताऱ्यात कोणते वर्णन आले आहे?\",\"options\":[\"तो भित्रा आणि आळशी होता\",\"तो शूर पण क्रूर होता\",\"तो दयाळू आणि शांत होता\",\"तो खूप मवाळ होता\"],\"answer\":1,\"explain\":\"उताऱ्यात सिद्दी जौहर हा \'शूर पण क्रूर\' होता असे म्हटले आहे.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पावसाळा सुरू झाल्यावर सिद्दी जौहरने वेढ्याबाबत काय केले?\",\"options\":[\"त्याने वेढा उठवला\",\"त्याने वेढा शिथिल केला\",\"त्याने वेढा अधिकच कडक केला\",\"तो वेढा सोडून विजापूरला गेला\"],\"answer\":2,\"explain\":\"पाऊस सुरू होताच सिद्दी जौहरने वेढा अधिकच कडक केला.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"गडावरची कोणती गोष्ट संपत आल्यामुळे शिवाजी महाराज चिंतेत पडले?\",\"options\":[\"पाणी\",\"दारूगोळा\",\"शिदोरी\",\"कापड\"],\"answer\":2,\"explain\":\"वेढा कडक झाल्यामुळे गडावरची शिदोरी (अन्नसाठा) संपत आली होती.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"शिवाजी महाराजांनी सिद्दीला \'लवकरच किल्ला तुमच्या स्वाधीन करतो\' असा निरोप का पाठवला?\",\"options\":[\"खरोखरच शरण जाण्यासाठी\",\"युक्तीने सुटका करून घेण्यासाठी\",\"युद्धाला घाबरल्यामुळे\",\"सैन्य संपल्यामुळे\"],\"answer\":1,\"explain\":\"शक्तीचे काम नाही, तेव्हा युक्तीने सुटका करून घेण्याचे महाराजांनी ठरवले होते.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"शिवाजी महाराज शरण येत आहेत हे ऐकून सिद्दीच्या सैनिकांची अवस्था काय झाली?\",\"options\":[\"ते अधिक सावध झाले\",\"ते घाबरून पळून गेले\",\"ते आनंदित होऊन दंग झाले\",\"त्यांनी युद्ध सुरू केले\"],\"answer\":2,\"explain\":\"शिवाजी शरण येत आहेत हे ऐकून सैनिक आनंदित झाले आणि खाणे-पिणे, गाणे-बजावणे यात दंग झाले.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"आदिलशहाला \'अन्नपाणी गोड लागेना\' याचा अर्थ काय?\",\"options\":[\"त्याला जेवण आवडत नव्हते\",\"तो आजारी होता\",\"तो खूप चिंतेत आणि रागात होता\",\"त्याला भूक लागत नव्हती\"],\"answer\":2,\"explain\":\"शिवाजी महाराजांनी पन्हाळगड जिंकल्यामुळे आदिलशहा प्रचंड चिडला आणि अस्वस्थ झाला होता.\",\"topic\":\"पन्हाळगडाचा वेढा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"सिद्दी जौहरच्या वेढ्याबाबत शिवाजी महाराजांचा कोणता अंदाज चुकला?\",\"options\":[\"पाऊस पडणार नाही\",\"पावसाळ्यात सिद्दी वेढा उठवील\",\"सिद्दी शरण येईल\",\"गडावरची शिदोरी संपणार नाही\"],\"answer\":1,\"explain\":\"पावसाळा सुरू झाला की सिद्द