wer\":2,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेत \'विविध कार्यक्रमांच्या निमंत्रणपत्रिकांचा संग्रह\' करण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"निमंत्रणपत्रिकांचा संग्रह केल्यानंतर वर्गात कोणती कृती करणे अपेक्षित आहे?\",\"options\":[\"त्यांचे वाचन करणे\",\"त्यांचे प्रदर्शन भरवणे\",\"त्यांना रंगवणे\",\"त्या फाडून टाकणे\"],\"answer\":0,\"explain\":\"सूचनेनुसार, निमंत्रणपत्रिकांचे वर्गात वाचन करून घेणे अपेक्षित आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"कार्यक्रमाचे ठिकाण जाणून घेण्यासाठी कोणता प्रश्न विचारला आहे?\",\"options\":[\"निमंत्रक कोण आहेत?\",\"प्रमुख पाहुणे कोण आहेत?\",\"कार्यक्रमाचे स्थळ कोणते आहे?\",\"कोणत्या दिवशी कार्यक्रम आहे?\"],\"answer\":2,\"explain\":\"प्रश्न क्र. २ मध्ये \'स्थळ\' (ठिकाण) बद्दल विचारले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला कार्यक्रमाची तारीख शोधायची असेल, तर तुम्ही कोणत्या क्रमांकाचा प्रश्न वापराल?\",\"options\":[\"प्रश्न १\",\"प्रश्न २\",\"प्रश्न ३\",\"प्रश्न ५\"],\"answer\":2,\"explain\":\"प्रश्न ३ मध्ये \'कोणत्या दिवशी\' कार्यक्रम आहे हे विचारले आहे, जे तारखेशी संबंधित आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"निमंत्रणपत्रिकेत \'प्रमुख पाहुणे\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"निमंत्रण देणारे लोक\",\"कार्यक्रमाला येणारे विशेष अतिथी\",\"शाळेतील सर्व विद्यार्थी\",\"कार्यक्रमाचे आयोजन करणारे\"],\"answer\":1,\"explain\":\"प्रमुख पाहुणे म्हणजे कार्यक्रमाला विशेष अतिथी म्हणून बोलावलेले व्यक्ती.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मजकुरातील प्रश्न ५ नुसार \'निमंत्रक\' म्हणजे कोण?\",\"options\":[\"कार्यक्रमाला उपस्थित राहणारे\",\"भाषण देणारे पाहुणे\",\"निमंत्रण देणारे किंवा बोलावणारे\",\"गाणी गाणारे विद्यार्थी\"],\"answer\":2,\"explain\":\"निमंत्रक म्हणजे जो कार्यक्रमाचे निमंत्रण देतो.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या ५ प्रश्नांचा मुख्य उद्देश काय आहे?\",\"options\":[\"गाणी पाठ करणे\",\"निमंत्रणपत्रिकेतील माहिती समजून घेणे\",\"चित्रकला शिकणे\",\"मैदानी खेळ खेळणे\"],\"answer\":1,\"explain\":\"हे प्रश्न निमंत्रणपत्रिकेतील महत्त्वाची माहिती (स्थळ, वेळ, पाहुणे) शोधण्यासाठी दिले आहेत.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"एखाद्या विद्यार्थ्याने लग्नाची पत्रिका वर्गात आणली, तर ती शिक्षकांनी दिलेल्या कोणत्या सूचनेचे पालन ठरेल?\",\"options\":[\"पाठांतर करणे\",\"लेखन करणे\",\"निमंत्रणपत्रिकांचा संग्रह करणे\",\"चित्र काढणे\"],\"answer\":2,\"explain\":\"लग्नाची पत्रिका ही एक निमंत्रणपत्रिका आहे, त्यामुळे हा \'संग्रह\' करण्याच्या सूचनेचा भाग आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"निमंत्रणपत्रिकेत खालीलपैकी कोणती माहिती असणे आवश्यक आहे असे या प्रश्नांवरून वाटते?\",\"options\":[\"जेवणाचा बेत\",\"पाहुण्यांची नावे आणि स्थळ\",\"विद्यार्थ्यांचे गुण\",\"शिक्षकांचे पगार\"],\"answer\":1,\"explain\":\"प्रश्नांमध्ये प्रमुख पाहुणे (प्रश्न ४) आणि स्थळ (प्रश्न २) यावर भर दिला आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":4,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21551,20,4,'Marathi','mr','आभाळातील फरकांड्या','[\"आभाळातील फरकांड्या हे एक कथा आहे ज्या मध्ये मुलगी चित्र काढते आणि रंगते.\",\"मुलगी शाळेच्या सुट्टीवर घरच्या अंगणात चित्र काढते.\",\"ती रंग, पेन्सील, रबर, कागद हे रविवारचे मित्र मानते.\",\"ती झाडे, घर, घोडा, उंट, मांजर इत्यादी काढते.\",\"चंद्र व सूर्य चित्रे केव्हा काढत असत हे विचारते.\",\"आकाश रंगवताना त्याचे रंग धूसर, निळेसावळा, केशरी टिळा इत्यादी बदलतात.\",\"आकाश रंगवताना आईची फटफजिती होऊ शकते.\",\"रंग भरल्यावर कागदवरील चित्रात नाक, केस, हाताची बोटे माखली जाऊ शकतात.\",\"बोटे एकत्र जुळून नवीन रंग निर्माण होऊ शकतो.\",\"रंगांचे पोपडे निघाल्याने आकाश व इतर वस्तूंचे रंग बदलतात.\",\"मुलगी आईशी प्रश्न करती की \'असं कुठे रंगवतात का आकाश ?\'\",\"आई उत्तर देते की \'रंगव बाबा, रंगवायचं तसं रंगब आकाश.\'\",\"कथा मध्ये कल्पना, रचनात्मकता, व पितृ-आईच्या प्रेमाचे दर्शवले जाते.\",\"शिक्षकांना विद्यार्थ्यांना पाठाचे वाचन, आशय सांगणे, संवाद तयार करणे हा मार्गदर्शन दिला जातो.\",\"पाठातील शब्दांचे अर्थ: शिंतोडा = लहान थेंब, कुंचला = चित्र रंगवण्याचे साधन, धूसर = अस्पष्ट, गर्द = गडद.\"]','[{\"q\":\"लेखक चित्र काढण्यासाठी गुपचूप कोठे जाऊन बसायचे?\",\"options\":[\"शाळेच्या वर्गात\",\"घराच्या गच्चीवर\",\"नदीच्या काठी\",\"बागेतल्या झाडाखाली\"],\"answer\":1,\"explain\":\"उताऱ्यात उल्लेख आहे की लेखक गुपचूप गच्चीवर जाऊन बसायचे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखकाने रंगांच्या पेटीची तुलना कशाशी केली आहे?\",\"options\":[\"फुलांच्या ताटव्याशी\",\"पिकाच्या वाफ्यांशी\",\"रंगीत दगडांशी\",\"आकाशातील ढगांशी\"],\"answer\":1,\"explain\":\"लेखकाने म्हटले आहे की, पिकाचे वाफे करावेत तशी वाफे केलेली रंगांची पेटी सोबतीला असायची.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखकाचे \'रविवारचे मित्र\' कोण बनले होते?\",\"options\":[\"शाळेतील सोबती\",\"शेजारी राहणारी मुले\",\"रंग, पेन्सील, रबर आणि कागद\",\"घोडा, उंट आणि मांजर\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट दिले आहे की रंग, पेन्सील, रबर, कागद हे रविवारचे मित्र बनले.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"चित्र काढताना हाताखाली धरायला लेखक काय वापरत असे?\",\"options\":[\"मोठे पुस्तक\",\"खपटे\",\"लोखंडी पाटी\",\"प्लास्टिकचा कागद\"],\"answer\":1,\"explain\":\"लेखक चित्र काढताना हाताखाली धरायला खपटे वापरत असत.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या मते, चित्र काढणे कोणाला आवडत नसे?\",\"options\":[\"त्यांच्या गुरुजींना\",\"त्यांच्या मित्रांना\",\"त्यांच्या घरच्यांना\",\"त्यांच्या शेजाऱ्यांना\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की, चित्र काढणे घरच्यांना आवडायचे नाही.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"वाटीला धक्का लागून पाणी सांडल्यामुळे काय व्हायचे?\",\"options\":[\"कागद पूर्ण ओला व्हायचा\",\"चड्डीची एक बाजू आपोआप रंगीत व्हायची\",\"सगळे रंग खराब व्हायचे\",\"लेखक रडायला लागायचे\"],\"answer\":1,\"explain\":\"पाणी मांडीवर सांडल्यामुळे चड्डीची एक बाजू रंगीत व्हायची असे उताऱ्यात सांगितले आहे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर घोडा, उंट किंवा मांजर हे प्राणी चित्रासाठी हाती लागले नाहीत, तर लेखक काय काढायचे?\",\"options\":[\"केवळ झाडे आणि घरे\",\"रस्त्यावरून जाणारी माणसे\",\"झाडाआडून येणारा चंद्र किंवा सूर्य\",\"शाळेची इमारत\"],\"answer\":2,\"explain\":\"प्राणी हाती लागले नाहीत तरच लेखक चंद्राला किंवा सूर्याला झाडाआडून येताना दाखवायचे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात, मुलगा चित्र काढण्यासाठी कशाचा वापर करत आहे?\",\"options\":[\"खडू\",\"पेन\",\"ब्रश\",\"कोळसा\"],\"answer\":2,\"explain\":\"चित्रात मुलगा हातात ब्रश धरून चित्र रंगवताना दिसत आहे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"20\\/024_101.jpg\"},{\"q\":\"दिलेल्या चित्रावरून मुलाच्या आनंदाचे कारण काय असावे, असे तुम्हाला वाटते?\",\"options\":[\"त्याला नवीन कपडे मिळाले आहेत\",\"तो आपल्या आवडीचे चित्र काढण्यात दंग आहे\",\"तो शाळेत पहिला आला आहे\",\"तो बागेत खेळत आहे\"],\"answer\":1,\"explain\":\"चित्रात मुलगा हसत आनंदाने चित्र काढताना आणि रंगवताना दिसत आहे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"20\\/024_101.jpg\"},{\"q\":\"\'घे ब्रश आणि मार फरकांड्या\' या सवयीचा अर्थ काय होतो?\",\"options\":[\"ब्रश तोडून टाकणे\",\"रंग नीट न भरता ओबडधोबड रेघोट्या मारणे\",\"ब्रशने भिंती रंगवणे\",\"ब्रश पाण्यात धुणे\"],\"answer\":1,\"explain\":\"फरकांड्या मारणे म्हणजे मुक्तपणे आणि वेगाने रंग लावणे किंवा रेघोट्या ओढणे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"चित्र पूर्ण व्हायच्या आधीच लेखकाच्या शरीराचे कोणते भाग रंगाने माखलेले असायचे?\",\"options\":[\"केवळ पाय आणि पोट\",\"नाक, केसाची बट आणि हाताची बोटे\",\"केवळ डोळे आणि कान\",\"पाठ आणि खांदे\"],\"answer\":1,\"explain\":\"उताऱ्यात नाक, केसाची बट आणि हाताची पाच बोटे रंगाने माखलेली असायची असा उल्लेख आहे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लेखकाने \'कायम वेठीला धरलेले\' असे कोणत्या प्राण्यांबाबत म्हटले आहे?\",\"options\":[\"वाघ आणि सिंह\",\"गाय आणि बैल\",\"घोडा, उंट आणि मांजर\",\"कुत्रा आणि ससा\"],\"answer\":2,\"explain\":\"उताऱ्यात घोडा, उंट, मांजर यांना कायम वेठीला धरलेले असे म्हटले आहे.\",\"topic\":\"४. आभाळातील फरकांड्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"हुशारीचा तक्ता पाहिल्यानंतर लेखकाने कोणाचे चित्र काढले?\",\"options\":[\"गुरुजींचे\",\"वडिलांचे\",\"भडकलेल्या आईचे\",\"मित्रांचे\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केले आहे की हुशारीचा तक्ता पाहून लेखक भडकलेल्या आईचे चित्र काढायचा.\",\"topic\":\"आकाश रंगवण्याचा प्रयत्न\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"आईच्या चित्रात काय बदल केल्यावर तिचा चेहरा बघण्यासारखा व्हायचा?\",\"options\":[\"डोळे मोठे केल्यावर\",\"नाक वाकडे दाखवल्यावर\",\"केस विस्कटलेले दाखवल्यावर\",\"कान लांब केल्यावर\"],\"answer\":1,\"explain\":\"सरळ नाकाच्या आईचे वाकडे नाक दाखवले की तिचा चेहरा बघण्यासारखा व्हायचा असे उताऱ्यात म्हटले आहे.\",\"topic\":\"आकाश रंगवण्याचा प्रयत्न\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"लेखकाने पुन्हा पुन्हा उठबस करायला लागू नये म्हणून काय केले?\",\"options\":[\"रंगांच्या बाटल्या जवळ घेतल्या\",\"घागरभर पाणी आणून ठेवले\",\"खपटे कोपऱ्यात ठेवले\",\"आईला मदतीला बोलावले\"],\"answer\":1,\"explain\":\"पुन्हा पुन्हा उठबस टाळण्यासाठी लेखकाने घागरभर पाणी आधीच आणून ठेवले होते.\",\"topic\":\"आकाश रंगवण्याचा प्रयत्न\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"लेखकाने कागद कशावर अंथरला होता?\",\"options\":[\"टेबलावर\",\"जमिनीवर\",\"चटईवर\",\"पाटावर\"],\"answer\":3,\"explain\":\"लेखकाने स्वयंपाकघरातील लाकडी पाट मांडीवर ठेवून त्यावर कागद अंथरला होता.\",\"topic\":\"आकाश रंगवण्याचा प्रयत्न\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"बशीमध्ये लेखकाने कोणते तीन रंग कालवले होते?\",\"options\":[\"पिवळा, निळा आणि हिरवा\",\"निळा, तांबडा आणि जांभळा\",\"पांढरा, काळा आणि निळा\",\"लाल, पिवळा आणि जांभळा\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट दिले आहे की बशीत निळा, तांबडा आणि जांभळा रंग कालवला होता.\",\"topic\":\"आकाश रंगवण्याच