explain\":\"मजकुरात \'कर\' हा ज्वारी-बाजरीच्या पिठापासून तयार करतात असे म्हटले आहे.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'कोर\' या शब्दाचे मजकुरात दिलेले दोन अर्थ कोणते?\",\"options\":[\"आवाज आणि पसंती\",\"लोणच्याचे फळ आणि इळाचा प्रकार\",\"तुकडे करणे आणि रागावणे\",\"सांभाळणे आणि अडकवणे\"],\"answer\":1,\"explain\":\"मजकुरात \'कोर\' म्हणजे लोणच्याचे फळ किंवा इळाचा प्रकार असे दिले आहे.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'गर\' म्हणजे लाल भोपळा किंवा मेथीकुटासारखा पदार्थ, तर \'गोर\' म्हणजे काय?\",\"options\":[\"छोटा पर्वत किंवा मोठी टेकडी\",\"मोठा दगड\",\"पाण्याचा साठा\",\"जंगलाचा भाग\"],\"answer\":0,\"explain\":\"मजकुरानुसार \'गोर\' म्हणजे छोटा पर्वत किंवा मोठी टेकडी होय.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'खले\' आणि \'खोले\' या शब्दांच्या अर्थाबाबत योग्य जोडी ओळखा.\",\"options\":[\"खले - अडकवले, खोले - सांभाळले\",\"खले - रागावणे, खोले - तुकडे करणे\",\"खले - सांभाळले, खोले - अडकवले\",\"खले - आवाज, खोले - पसंती\"],\"answer\":2,\"explain\":\"मजकुरात \'खले\' म्हणजे टिकवले\\/सांभाळले आणि \'खोले\' म्हणजे अडकवले असे दिले आहे.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"\'पला\' म्हणजे चिरणे किंवा तुकडे करणे, तर \'पोला\' या शब्दाचा अर्थ काय?\",\"options\":[\"हसणे\",\"पळणे\",\"रागावणे\",\"बोलणे\"],\"answer\":2,\"explain\":\"मजकुरात \'पोला\' या शब्दाचा अर्थ \'रागावणे\' असा दिला आहे.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"एकाक्षरी शब्दांतील इकार किंवा उकार कसे लिहावेत असा नियम मजकुरात दिला आहे?\",\"options\":[\"ऱ्हस्व लिहावेत\",\"दीर्घ लिहावेत\",\"लिहू नयेत\",\"कोणत्याही प्रकारे चालेल\"],\"answer\":1,\"explain\":\"एकाक्षरी शब्दांतील इकार किंवा उकार दीर्घ उच्चारले जातात म्हणून ते दीर्घ लिहावेत.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एकाक्षरी शब्दांच्या नियमाला (दीर्घ लिहिणे) कोणता शब्द अपवाद आहे?\",\"options\":[\"मी\",\"तू\",\"नि\",\"जी\"],\"answer\":2,\"explain\":\"मजकुरात \'नि\' हा शब्द अपवाद म्हणून दिला आहे, जो दीर्घ लिहिला जात नाही.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता शब्द मजकुरात दिलेल्या एकाक्षरी शब्दांच्या उदाहरणात नाही?\",\"options\":[\"स्त्री\",\"बी\",\"भू\",\"ती\"],\"answer\":3,\"explain\":\"मजकुरात मी, ही, तू, धू, जू, ऊ, स्त्री, जी, पी, बी, भू हे शब्द दिले आहेत, \'ती\' हा शब्द दिलेला नाही.\",\"topic\":\"‘आ-ओ’ची धमाल\",\"part\":5,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28');
INSERT INTO `ep_topic_packs` VALUES (21555,20,4,'Marathi','mr','डोंगरदादा','[\"डोंगरदादा एकटेपणामुळे दुःखी होता.\",\"एक रोपटे डोंगरदादाच्या कुशीतून वर आला.\",\"डोंगरदादाने रोपटेला आसरा दिला, त्यामुळे तो आनंदित झाला.\",\"रोपटे डोंगरदादाच्या मांडीवर बसले आणि त्याने त्याला खाऊपिऊ घातले.\",\"वेळेने अनेक रोपट्या आली आणि डोंगरदादाकडे खूप झाडे झाले.\",\"हवामान बदलल्यामुळे धिटुकल्या वेली आली, त्यामुळे झाडे फळाफुलांनी बहरले.\",\"बुटकी झुडपे आली, माना डोलावत उभी राहिली, त्यांच्यासोबत गवत होते.\",\"गवताचा स्पर्श डोंगरदादाला गुदगुल्या दिला.\",\"सिंह डोंगरदादाच्या जंगलात आला आणि गर्जना केली.\",\"सिंहाने क्षमा मागली आणि डोंगरदादाला पुढे राहण्यास सांगितले.\",\"सिंह डोंगरदादाच्या जंगलात गुहेत राहायला लागला.\",\"जंगलात अनेक प्राणी आले: वाघ, हत्ती, जिराफ, कोल्हा, अस्वल, लांडगे, हरणे, ससे, माकड.\",\"डोंगरदादाने सर्व प्राण्यांना आसरा दिला आणि प्राण्यांचा गलबला सुरू झाला.\",\"झाडे फळाफुलांनी बहरले आणि त्यांचा घमघमाट सगळीकडे पसरला.\",\"पक्ष्यांची झुंबड उडाली आणि त्यांची किलबिल सुरू झाली.\",\"प्राण्यांने झाडांची फळे खाल्ली त्यांच्या बिया दुसरीकडे नेली, त्यामुळे नवीन झाडे तयार झाले.\",\"डोंगरदादाचा एकटेपणा संपला आणि तो अगदी आनंदून गेला.\",\"ढग डोंगरदादाजवळ आले, त्यांच्यासोबत खेळवले आणि त्यामुळे पाऊस पडायला लागला.\",\"पाऊस पडला, जंगल हसला, डोंगरदादा गाऊ लागला, जंगलाने ताल धरला.\",\"पाठातील शब्दांचे अर्थ: आसरा - निवारा, फेर धरणे - गोलाकार हात धरून नाचणे, माना डोलावणे - होकार देणे, थाट - रुबाब, घमघमाट - सगळीकडे सुगंध पसरणे, झुंबड उडणे - गर्दी होणे.\"]','[{\"q\":\"डोंगरदादा कशामुळे कष्टी होता?\",\"options\":[\"उन्हामुळे\",\"एकटेपणामुळे\",\"पावसामुळे\",\"गर्दीमुळे\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की डोंगरदादा एकटेपणामुळे कष्टी होता.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"डोंगरदादाच्या कुशीतून कोण हळूच वर आले?\",\"options\":[\"एक दगड\",\"एक पक्षी\",\"एक छोटेसे रोपटे\",\"एक मोठा वृक्ष\"],\"answer\":2,\"explain\":\"उताऱ्याप्रमाणे डोंगरदादाच्या कुशीतून एक छोटेसे रोपटे वर आले.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'टकमक टकमक पाहणे\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"डोळे मिटून घेणे\",\"रागाने पाहणे\",\"एकटक किंवा निरखून पाहणे\",\"रडत पाहणे\"],\"answer\":2,\"explain\":\"टकमक पाहणे म्हणजे कुतूहलाने किंवा एकटक पाहणे.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"रोपट्याने डोंगरदादाकडे कशाची मागणी केली?\",\"options\":[\"पाण्याची\",\"आसऱ्याची\",\"खाऊची\",\"खेळण्याची\"],\"answer\":1,\"explain\":\"रोपट्याने डोंगरदादाला विचारले, \'मला देशील का तू आसरा?\'\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"डोंगरदादाला आनंद का झाला असावा?\",\"options\":[\"त्याला आता बोलायला आणि खेळायला सोबत मिळाली\",\"त्याला खूप भूक लागली होती\",\"त्याला पाऊस आवडत होता\",\"त्याला झोपायचे होते\"],\"answer\":0,\"explain\":\"डोंगरदादा एकटा होता, रोपट्यामुळे त्याला सोबत मिळाली म्हणून तो आनंदी झाला.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात डोंगरदादाच्या चेहऱ्यावरील भाव कसा दिसतोय?\",\"options\":[\"तो खूप रागावलेला आहे\",\"तो रडत आहे\",\"तो आनंदी आणि हसरा दिसत आहे\",\"तो घाबरलेला आहे\"],\"answer\":2,\"explain\":\"चित्रात डोंगरदादा रोपट्याकडे पाहून आनंदाने हसताना दिसत आहे.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"20\\/041_101.jpg\"},{\"q\":\"दिलेल्या चित्रात रोपटे नेमके कोठे उगवलेले दिसत आहे?\",\"options\":[\"डोंगरदादाच्या डोक्यावर\",\"डोंगरदादाच्या कुशीत (मध्यभागी)\",\"डोंगरदादापासून खूप लांब\",\"ढगांच्या वर\"],\"answer\":1,\"explain\":\"चित्रात रोपटे डोंगरदादाच्या अंगावर म्हणजेच कुशीत उगवलेले दिसत आहे.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"20\\/041_101.jpg\"},{\"q\":\"रोपट्याने डोंगरदादाला विचारून मगच तिथे राहण्याचे ठरवले, यावरून रोपट्याचा स्वभाव कसा वाटतो?\",\"options\":[\"उद्धट\",\"नम्र आणि समजूतदार\",\"आळशी\",\"भीतरा\"],\"answer\":1,\"explain\":\"परवानगी मागून राहणे हे नम्रपणाचे लक्षण आहे.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"डोंगरदादाच्या मनात \'कोणी नाही बोलायला, कोणी नाही हसायला\' असे विचार का येत होते?\",\"options\":[\"कारण त्याला शांतता हवी होती\",\"कारण तो खूप आजारी होता\",\"कारण तो एकटा होता आणि त्याला कोणाची तरी संगत हवी होती\",\"कारण त्याला कोणाशीच बोलायचे नव्हते\"],\"answer\":2,\"explain\":\"एकटेपणामुळे डोंगरदादाला कोणाची तरी सोबत हवी होती.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर डोंगरदादाने रोपट्याला आसरा दिला नसता, तर काय झाले असते?\",\"options\":[\"डोंगरदादा खूप आनंदी झाला असता\",\"डोंगरदादाचा एकटेपणा आणि दुःख तसेच राहिले असते\",\"डोंगरदादाला नवीन मित्र मिळाले असते\",\"डोंगरदादा खेळायला गेला असता\"],\"answer\":1,\"explain\":\"सोबत न मिळाल्यास डोंगरदादाचे दुःख कायम राहिले असते.\",\"topic\":\"पहिले रोपटे\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"डोंगरदादाच्या मांडीवर कोण जाऊन बसले?\",\"options\":[\"वेली\",\"झुडपे\",\"रोपटे\",\"गवत\"],\"answer\":2,\"explain\":\"उताऱ्यात दिले आहे की रोपटे डोंगरदादाच्या मांडीवर जाऊन बसले.\",\"topic\":\"झाडे, वेली आणि झुडपे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"चिटुकल्या वेलींनी झाडांच्या भोवताली काय केले?\",\"options\":[\"हातात हात धरून फेर धरला\",\"माना डोलावल्या\",\"डोंगरदादाला बिलगल्या\",\"खाऊपिऊ घातले\"],\"answer\":0,\"explain\":\"वेली झाडांच्या भोवताली जमून हातात हात धरून फेर धरू लागल्या असे उताऱ्यात म्हटले आहे.\",\"topic\":\"झाडे, वेली आणि झुडपे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"डोंगरदादाला गुदगुल्या का झाल्या?\",\"options\":[\"वेलींनी फेर धरल्यामुळे\",\"गवताच्या मृदू स्पर्शामुळे\",\"झुडपांनी माना डोलावल्यामुळे\",\"फुलांनी नटल्यामुळे\"],\"answer\":1,\"explain\":\"गवताचा मृदू स्पर्श झाल्यामुळे डोंगरदादाला गुदगुल्या झाल्या.\",\"topic\":\"झाडे, वेली आणि झुडपे\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"बुटकी झुडपे कशी उभी राहिली?\",\"options\":[\"लाजत लाजत\",\"फेर धरून\",\"माना डोलावत\",\"बिलगून\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, बुटकी झुडपे माना डोलावत उभी राहिली.\",\"topic\":\"झाडे, वेली आणि झुडपे\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"डोंगरदादाने रोपट्याला खाऊपिऊ घातल्यावर काय बदल झाला?\",\"options\":[\"ते वाळून गेले\",\