[\"बाहेरच्या दुधाशी\",\"फळांच्या रसाशी\",\"खानावळीतील दुधातुपाशी\",\"आईच्या दुधाशी\"],\"answer\":2,\"explain\":\"उताऱ्यात आई म्हणते की घरच्या अन्नाने जशी पुष्टी येते, तशी खानावळीतील दुधातुपाने येत नाही.\",\"topic\":\"आईची शिकवण\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"देवाला फुले वाहण्याबाबत आईने कोणती अट सांगितली आहे?\",\"options\":[\"खूप सारी फुले वाहावीत\",\"फक्त कळ्याच वाहाव्यात\",\"नीट फुललेले फूल वाहावे\",\"बाजारातून आणलेली फुले वाहावीत\"],\"answer\":2,\"explain\":\"आई म्हणते, \'देवाला एक फूल मिळाले तरी पुरे; परंतु ते नीट फुललेले वाहा.\'\",\"topic\":\"आईची शिकवण\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"आईने श्यामला \'अधोश्यासारखा\' का म्हटले असावे?\",\"options\":[\"कारण तो खूप जेवला होता\",\"कारण त्याने उतावळ होऊन कळ्या तोडल्या होत्या\",\"कारण तो खेळायला गेला होता\",\"कारण तो अभ्यास करत नव्हता\"],\"answer\":1,\"explain\":\"कळ्या नीट फुलण्याआधीच त्या तोडण्याच्या घाईमुळे आईने त्याला \'अधोश्यासारखा उतावळ\' म्हटले.\",\"topic\":\"आईची शिकवण\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"बाळाचे पोषण कशावर उत्तम होते असे आईला वाटते?\",\"options\":[\"बाहेरच्या दुधावर\",\"खानावळीतील अन्नावर\",\"आईच्या दुधावर\",\"फळांच्या रसावर\"],\"answer\":2,\"explain\":\"आईच्या दुधावर बाळ पोसते, तसे बाहेरच्या दुधावर पोसत नाही असे उताऱ्यात दिले आहे.\",\"topic\":\"आईची शिकवण\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"झाडे आणि फुले यांच्यातील नाते आईने कसे स्पष्ट केले आहे?\",\"options\":[\"झाडे फुलांचे शत्रू आहेत\",\"झाडे फुलांना जीवनरस देणाऱ्या माता आहेत\",\"झाडे आणि फुले यांचा काही संबंध नाही\",\"फुले झाडांना अन्न देतात\"],\"answer\":1,\"explain\":\"झाडे कळ्यांना जीवनरस पाजून फुलवितात, म्हणून ती फुलांच्या माता आहेत.\",\"topic\":\"आईची शिकवण\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"या उताऱ्यातून आईने श्यामला मुख्यत्वे कोणती शिकवण दिली आहे?\",\"options\":[\"नेहमी भरपूर फुले तोडावीत\",\"कळ्यांना पाण्यात टाकून फुलवावे\",\"नैसर्गिकरीत्या नीट फुललेलीच फुले देवाला वाहावीत\",\"खानावळीत जाऊन जेवण करावे\"],\"answer\":2,\"explain\":\"निसर्गाच्या प्रक्रियेत हस्तक्षेप न करता फुले नीट