c\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात दोन्ही मुलींनी कोणता पेहराव केला आहे?\",\"options\":[\"घरचे कपडे\",\"शालेय गणवेश\",\"खेळाचे कपडे\",\"सणाचे कपडे\"],\"answer\":1,\"explain\":\"चित्रात दोन्ही मुली शाळेच्या गणवेशात दिसत आहेत.\",\"topic\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"20\\/064_101.jpg\"},{\"q\":\"अनिताने जेव्हा आईच्या नोकरीबद्दल विचारले, तेव्हा लेखिकेची स्थिती कशी झाली?\",\"options\":[\"ती खूप आनंदी झाली\",\"ती सावध झाली आणि गोंधळली\",\"ती जोरात हसायला लागली\",\"ती रागाने ओरडली\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, अनिताच्या प्रश्नाने लेखिका एकदम सावध झाली आणि थोडा वेळ गोंधळली.\",\"topic\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखिकेला पूर्वी कोणत्या गोष्टीबद्दल विचारलेले आवडत नसे?\",\"options\":[\"तिच्या अभ्यासाबद्दल\",\"तिच्या खेळाबद्दल\",\"तिच्या आईच्या नोकरीबद्दल\",\"तिच्या मैत्रिणींबद्दल\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की, आईच्या नोकरीबद्दल कोणी विचारलेले तिला मुळीच आवडत नसे.\",\"topic\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात डाव्या बाजूला उभी असलेली मुलगी खाली का बघत आहे असे वाटते?\",\"options\":[\"तिचे काहीतरी हरवले आहे\",\"ती रस्ता शोधत आहे\",\"तिला आईच्या कामाबद्दल सांगायला संकोच वाटत आहे\",\"तिला झोप येत आहे\"],\"answer\":2,\"explain\":\"उताऱ्यातील संदर्भावरून, लेखिका आईच्या कामाबद्दल सांगताना गोंधळली होती, जे चित्रात तिच्या खाली बघण्यावरून जाणवते.\",\"topic\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"20\\/064_101.jpg\"},{\"q\":\"अनिताने प्रश्न विचारल्यावर लेखिकेने उत्तर देण्याऐवजी काय केले?\",\"options\":[\"ती पळून गेली\",\"तिने अनितालाच उलट प्रश्न विचारला\",\"ती रडायला लागली\",\"तिने शिक्षकांना बोलावले\"],\"answer\":1,\"explain\":\"प्रश्नाचे उत्तर देण्याच्या ऐवजी लेखिकेने अनितालाच विचारले, \'तुझी आई काय करते?\'\",\"topic\":\"पाठाची प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखिकेने \'जाऊ दे ते\' असे का म्हटले असावे