},{\"q\":\"तन्मयच्या जखमेला आजीने हळद का लावली असावी?\",\"options\":[\"हळदीचा रंग पिवळा असतो म्हणून\",\"हळदीचे शास्त्रीय गुणधर्म माहीत असल्यामुळे\",\"हळद घरात उपलब्ध होती म्हणून\",\"हळदीचा वास छान येतो म्हणून\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की, आजीला शास्त्रीय दृष्टिकोनातून हळदीचे गुणधर्म माहीत होते.\",\"topic\":\"कणकणात विज्ञान\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"आईच्या मते विज्ञान कोठे भरलेले आहे?\",\"options\":[\"फक्त शाळेच्या पुस्तकात\",\"फक्त प्रयोगशाळेत\",\"जगण्याच्या प्रत्येक कणात आणि क्षणात\",\"केवळ दवाखान्यात\"],\"answer\":2,\"explain\":\"आईच्या मते आपल्या जगण्याच्या प्रत्येक कणात आणि प्रत्येक क्षणात विज्ञानच भरलंय.\",\"topic\":\"कणकणात विज्ञान\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"मुलाने परीक्षेला जाण्यासाठी आईसमोर कोणती अट ठेवली?\",\"options\":[\"आईने त्याला खाऊ द्यावा\",\"आईने त्याला नवीन दप्तर द्यावे\",\"आईने प्रत्येक कणात विज्ञान कसे आहे ते सांगावे\",\"आईने त्याला शाळेत सोडून यावे\"],\"answer\":2,\"explain\":\"मुलगा म्हणतो, \'आई, अंगी प्रत्येक कणात, विज्ञान आहे... कसं काय ते सांग, तरच मी जाईन परीक्षेला!\'\",\"topic\":\"कणकणात विज्ञान\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"जर तुम्हाला जखम झाली, तर उताऱ्यातील माहितीनुसार कोणता घरगुती उपाय शास्त्रीय ठरेल?\",\"options\":[\"ओवा खाणे\",\"हळद लावणे\",\"पाणी उकळणे\",\"कडुलिंबाचा पाला खाणे\"],\"answer\":1,\"explain\":\"तन्मयच्या जखमेला आजीने हळद लावली होती, कारण तिला हळदीचे शास्त्रीय गुणधर्म माहीत होते.\",\"topic\":\"कणकणात विज्ञान\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मुलाने पोट दुखण्याचे कारण का दिले असावे?\",\"options\":[\"त्याला खूप भूक लागली होती\",\"त्याला विज्ञानाच्या पेपरची भीती वाटत असावी किंवा जायचे नसावे\",\"त्याला ओवा खायचा होता\",\"त्याला आजीकडे जायचे होते\"],\"answer\":1,\"explain\":\"विज्ञानाचा पेपर असल्यामुळे मुलगा शाळेत न जाण्यासाठी पोट दुखण्याचे कारण सांगत आहे.\",\"topic\":\"कणकणात विज्ञान\",\"part\":6,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21562,20,4,'Marathi','mr','कणाकणांत विज्ञान (नाट्यछटा)','[\"विज्ञान म्हणजे पदार्थांचे गुणधर्म, व्यवहार आणि त्यांचे उपयोग जाणून घेणे.\",\"विज्ञानाने खाद्य पदार्थांचे फायदे व नुकसान ओळखले जाते.\",\"विज्ञानाने पदार्थांचे शरीरावर होणारा परिणाम जाणून घेतला.\",\"डॉक्टर, इंजिनिअर, बिल्डर खाद्य पदार्थांचा व्यवसाय करताना विज्ञानाचा वापर करतात.\",\"विज्ञानाने पदार्थांचे घटक ओळखले जेणेकरून त्यांचे फायदे व हानि ओळखली जाते.\",\"विज्ञानाने पदार्थांचे शुद्धता तपासणे केली जाते.\",\"विज्ञानाने पदार्थांचे संरक्षण केली जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्याचे योग्य मार्ग सांगितले जाते.\",\"विज्ञानाने पदार्थांचे नवनिर्माण केली जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी तपासणे केली जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी त्यांचे परिणाम जाणून घेतले जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी त्यांचे फायदे व हानि ओळखले जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी त्यांचे शरीरावर होणारा परिणाम जाणून घेतला.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी त्यांचे शुद्धता तपासली जाते.\",\"विज्ञानाने पदार्थांचे वापर करण्यापूर्वी त्यांचे संरक्षण केला जातो.\"]','[{\"q\":\"विज्ञानाचा संबंध खालीलपैकी कशाशी आहे असे उताऱ्यात म्हटले आहे?\",\"options\":[\"वेग, प्रकाश आणि हवामान\",\"केवळ खेळ आणि गाणी\",\"फक्त चित्रकला\",\"केवळ गोष्टी सांगणे\"],\"answer\":0,\"explain\":\"उताऱ्याच्या सुरुवातीलाच वेग, प्रकाश, हवामान यात विज्ञान असल्याचे म्हटले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात विजेच्या कोणत्या उपकरणांचा उल्लेख आला आहे?\",\"options\":[\"इस्त्री आणि ओव्हन\",\"दूरदर्शन संच, पंखा, संगणक\",\"फ्रिज आणि मिक्सर\",\"वॉशिंग मशीन आणि गिझर\"],\"answer\":1,\"explain\":\"मजकुरात दूरदर्शन संच, पंखा आणि संगणक ही उदाहरणे दिली आहेत.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"बाई मधल्या सुट्टीत मुलांचे काय तपासतात?\",\"options\":[\"दप्तर\",\"नखे\",\"डबा\",\"गृहपाठ\"],\"answer\":2,\"explain\":\"बाई मधल्या सुट्टीत प्रत्येकाचा डबा तपासतात असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"पिशवीबंद पदार्थ (उदा. वेफर्स) शरीरासाठी कसे असतात?\",\"options\":[\"खूप पौष्टिक\",\"अतिशय फायदेशीर\",\"अपायकारक\",\"गरजेचे\"],\"answer\":2,\"explain\":\"पिशवीबंद पदार्थ शरीरासाठी अपायकारक आहेत, हे विज्ञानाने सिद्ध झाले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"खाद्यपदार्थांचा व्यवसाय करायचा असेल, तरी कशाचे ज्ञान असणे आवश्यक आहे?\",\"options\":[\"इतिहासाचे\",\"पदार्थांच्या विज्ञानाचे\",\"चित्रकलेचे\",\"भूगोलाचे\"],\"answer\":1,\"explain\":\"खाद्यपदार्थांचा व्यवसाय करायलाही पदार्थांचे विज्ञान कळावे लागते असे उताऱ्यात म्हटले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"हिवाळ्यात कोणत्या सणाला खाल्ल्या जाणाऱ्या पोळीमागे विज्ञान दडले आहे?\",\"options\":[\"दिवाळी\",\"दसरा\",\"संक्रांत\",\"होळी\"],\"answer\":2,\"explain\":\"हिवाळ्यात संक्रांतीला पोळी खाण्यामागेही विज्ञान दडले आहे, असे मजकुरात आले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"बाई मुलांची \'कानउघाडणी\' का करतात?\",\"options\":[\"मुले अभ्यास करत नाहीत म्हणून\",\"मुले पिशवीबंद पदार्थ आणतात म्हणून\",\"मुले उशिरा येतात म्हणून\",\"मुले खेळत नाहीत म्हणून\"],\"answer\":1,\"explain\":\"पिशवीबंद पदार्थ शरीरासाठी घातक असल्याने ते आणणाऱ्या मुलांची बाई कानउघाडणी करतात.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लेखिकेने विज्ञानाला कशाची उपमा दिली आहे?\",\"options\":[\"अन्नाची\",\"पाण्याची\",\"आपल्या श्वासाची\",\"कपड्यांची\"],\"answer\":2,\"explain\":\"विज्ञान म्हणजे आपला श्वास आहे, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"डॉक्टर, इंजिनिअर आणि बिल्डर या सर्वांमध्ये समान गोष्ट कोणती?\",\"options\":[\"त्यांना विज्ञानाची गरज लागते\",\"ते सर्व एकाच शाळेत जातात\",\"ते सर्व फक्त खेळतात\",\"त्यांना विज्ञानाची गरज नसते\"],\"answer\":0,\"explain\":\"या सर्व व्यावसायिकांना विज्ञानाची माहिती असणे आवश्यक असल्याचे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"मुलगी शाळेत कशासाठी जात आहे?\",\"options\":[\"फक्त जेवायला\",\"परीक्षा द्यायला आणि विज्ञानाशी मैत्री करायला\",\"गाणी म्हणायला\",\"चित्र काढायला\"],\"answer\":1,\"explain\":\"शेवटच्या ओळीत मुलगी परीक्षा द्यायला आणि विज्ञानाशी मैत्री करायला निघाल्याचे म्हटले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'कणाकणांत विज्ञान\' या नाट्यछटेच्या लेखिका कोण आहेत?\",\"options\":[\"शांता शेळके\",\"क्षितिजा आगाशे\",\"विंदा करंदीकर\",\"पु. ल. देशपांडे\"],\"answer\":1,\"explain\":\"उताऱ्याच्या शेवटी लेखिकेचे नाव \'क्षितिजा आगाशे\' असे दिले आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"या उताऱ्याचा मुख्य संदेश काय आहे?\",\"options\":[\"विज्ञान फक्त प्रयोगशाळेत असते\",\"विज्ञानाशिवाय जगणे शक्य नाही, ते सर्वत्र आहे\",\"फक्त डॉक्टरांनाच विज्ञान लागते\",\"शाळेत विज्ञान शिकू नये\"],\"answer\":1,\"explain\":\"विज्ञान प्रत्येक गोष्टीत आणि आपल्या श्वासात आहे, हा या नाट्यछटेचा मुख्य विचार आहे.\",\"topic\":\"कणाकणांत विज्ञान (नाट्यछटा)\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"\'दृष्टिकोन\' या शब्दाचा खालीलपैकी योग्य अर्थ कोणता?\",\"options\":[\"विचारसरणी\",\"पाहणे\",\"डोळे\",\"चित्र\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुरानुसार \'दृष्टिकोन\' म्हणजे \'विचारसरणी\' होय.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'अपायकारक\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"फायदेशीर\",\"हानिकारक\",\"मदतीचा\",\"सुखद\"],\"answer\":1,\"explain\":\"मजकुरात \'अपायकारक\' या शब्दाचा अर्थ \'हानिकारक\' असा दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'हानिकारक\' या अर्थाचा पाठात आलेला शब्द ओळखा.\",\"options\":[\"दृष्टिकोन\",\"विचारसरणी\",\"अपायकारक\",\"विज्ञान\"],\"answer\":2,\"explain\":\"पाठात \'हानिकारक\' साठी \'अपायकारक\' हा शब्द वापरला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'विचारसरणी\' या शब्दासाठी कोणता पर्यायी शब्द मजकुरात दिला आहे?\",\"options\":[\"दृष्टिकोन\",\"अपाय\",\"समजले\",\"नवीन\"],\"answer\":0,\"explain\":\"मजकुरानुसार \'दृष्टिकोन\' आणि \'विचारसरणी\' हे समानार्थी शब्द आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या गोष्टीमुळे शरीराला इजा होत असेल, तर ती गोष्ट कशी आहे?\",\"options\":[\"फायदेशीर\",\"अपायकारक\",\"चांगली\",\"गरजेची\"],\"answer\":1,\"explain\":\"इजा होणे म्हणजे नुकसान होणे, ज्याला \'अपायकारक\' किंवा \'हानिकारक\' म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"एखाद्या विषयाकडे पाहण्याची तुमची पद्धत म्हणजे तुमचा काय असतो?\",\"options\":[\"अपाय\",\"दृष्टिकोन\",\"धोका\",\"अभ्यास\"],\"answer\":1,\"explain\":\"विचार करण्याची किंवा पाहण्याची पद्धत म्हणजे \'दृष्टिकोन\' (विचारसरणी) होय.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती जोडी समानार्थी शब्दांची आहे?\",\"options\":[\"दृष्टिकोन - अपायकारक\",\"विचारसरणी - हानिकारक\",\"दृष्टिकोन - विचारसरणी\",\"नवीन - हानिकारक\"],\"answer\":2,\"explain\":\"मजकुरात \'दृष्टिकोन\' आणि \'विचारसरणी\' ही समानार्थी जोडी दिली आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"\'नवीन शब्द शिकू या\' या शीर्षकाखाली एकूण किती शब्दांचे अर्थ दिले आहेत?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"मजकुरात \'दृष्टिकोन\' आणि \'अपायकारक\' अशा दोन शब्दांचे अर्थ दिले आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या मजकुरानुसार खालीलपैकी चुकीची जोडी ओळखा.\",\"options\":[\"दृष्टिकोन - विचारसरणी\",\"अपायकारक - हानिकारक\",\"हानिकारक - विचारसरणी\",\"विचारसरणी - दृष्टिकोन\"],\"answer\":2,\"explain\":\"हानिकारक आणि विचारसरणी हे शब्द समानार्थी नाहीत, त्यामुळे ही जोडी चुकीची आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"\'आम्हांला हे समजले\' या वाक्यातून काय स्पष्ट होते?\",\"options\":[\"मुलांना काहीच कळले नाही\",\"दिलेल्या शब्दांचे अर्थ समजले आहेत\",\"मुले खेळत आहेत\",\"मुले नवीन शब्द शोधत आहेत\"],\"answer\":1,\"explain\":\"हे वाक्य शिकलेल्या भागाचे आकलन झाल्याचे दर्शवते.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21563,20,4,'Marathi','mr','पुस्तकांच्या सहवासात','[\"पुस्तकं मित्र समान असतात, त्यांचा सहवास शांत आयुष्य देतो.\",\"पुस्तक वाचणे व लिहणे थकावून येत नाही, तर ऊर्जा वाढवते.\",\"पुस्तकं स्मरणशक्ती तल्लख आणि प्रखर करतात.\",\"पुस्तकं नवी वाट दाखवतात, शिकवतात.\",\"पुस्तक देणे जीवनावर येतो, त्यामुळे इतरांचा उपकार होतो.\",\"डॉ. आंबेडकर यांचे वडिल त्यांच्याबाहेर पुस्तकं आणून देत होते.\",\"डॉ. आंबेडकर यांची स्मरणशक्ती वाचनामुळे तल्लख आणि प्रखर झाली.\",\"पुस्तक वाचणे उपास्य दैवत मानले जाते.\",\"गरीब वाऱ्यांमध्येही पुस्तकांचा महत्त्व समजले जाते.\",\"सतत परिश्रमाने ज्ञानी होऊ शकतो, हे सत्य आहे.\",\"पुस्तकांचे प्रकार: दैनिक, साप्ताहिक, पाक्षिक, मासिक, त्रैमासिक, षण्मासिक, वार्षिक.\",\"पुस्तकांचे भाग: मुखपृष्ठ, पहिला पान, शेवटचा पान, प्रकाशक, लेखक.\",\"पुस्तक वाचनाची होस वडिलांनी पुरवली होती.\",\"पुस्तकांची देवघेव नोंदवही तयार करणे महत्त्वाचे आहे.\"]','[{\"q\":\"सुरुवातीला लेखकाच्या घरची स्थिती कशी होती?\",\"options\":[\"खूप श्रीमंत\",\"बऱ्यापैकी\",\"अत्यंत हलाखीची\",\"मध्यम\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच म्हटले आहे की सुरुवातीला घरची स्थिती बऱ्यापैकी होती.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या वडिलांना काय मिळत असे?\",\"options\":[\"पगार\",\"बक्षीस\",\"पेन्शन\",\"भाडे\"],\"answer\":2,\"explain\":\"वडिलांना थोडेसे पेन्शन मिळत असे, असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"पुस्तके आणून देणे वडिलांच्या आवाक्याबाहेरचे का होते?\",\"options\":[\"त्यांना पुस्तके आवडत नव्हती\",\"मुंबईची राहणी आणि कुटुंबातील बरीच माणसे यामुळे\",\"पुस्तके बाजारात मिळत नव्हती\",\"लेखकाला वाचता येत नव्हते\"],\"answer\":1,\"explain\":\"मुंबईची महागडी राहणी आणि मोठ्या कुटुंबाची जबाबदारी यामुळे वडिलांना पुस्तके घेणे कठीण होते.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखकाची त्या वेळी कोणती मुख्य महत्त्वाकांक्षा होती?\",\"options\":[\"खूप पैसे कमवणे\",\"मोठे घर बांधणे\",\"स्वतःच्या मालकीची पुस्तके असणे\",\"मुंबईला फिरायला जाणे\"],\"answer\":2,\"explain\":\"स्वतःची पुस्तके असावीत म्हणजे फक्त स्वतःच्या मालकीची, ही लेखकाची त्या वेळची महत्त्वाकांक्षा होती.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या कोणत्या स्वभावामुळे त्याला वडिलांच्या प्रेमाची किंमत त्या वेळी कळली नाही?\",\"options\":[\"रागीट स्वभाव\",\"अल्लड स्वभाव\",\"शांत स्वभाव\",\"अभ्यासू स्वभाव\"],\"answer\":1,\"explain\":\"लेखकाने म्हटले आहे की त्यांच्या अल्लड स्वभावामुळे त्यांना वडिलांच्या प्रेमळपणाची किंमत कळली नाही.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखकाचे ग्रंथालय कशामुळे निर्माण झाले?\",\"options\":[\"वडिलांच्या पेन्शनमुळे\",\"स्वतःची पुस्तके असण्याच्या महत्त्वाकांक्षेमुळे\",\"शाळेच्या ग्रंथालयामुळे\",\"मित्रांच्या मदतीमुळे\"],\"answer\":1,\"explain\":\"स्वतःची पुस्तके असावीत या महत्त्वाकांक्षेपासूनच लेखकाचे ग्रंथालय निर्माण झाले.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखक वडिलांकडे कशासाठी हट्ट धरत असे?\",\"options\":[\"खाऊसाठी\",\"खेळण्यांसाठी\",\"नवीन नवीन पुस्तकांसाठी\",\"कपड्यांसाठी\"],\"answer\":2,\"explain\":\"लेखक नवीन नवीन पुस्तके आणून देण्यासाठी वडिलांकडे हट्ट धरत असे.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"वडील लेखकाची हौस कशी पुरवत असत?\",\"options\":[\"हवी ती झीज सोसून\",\"कर्ज काढून\",\"लेखकाला रागावून\",\"दुसऱ्यांकडून पुस्तके मागून\"],\"answer\":0,\"explain\":\"परिस्थिती हलाखीची असूनही वडील हवी ती झीज सोसून लेखकाची हौस पुरवायला तयार असत.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"जर लेखकाने सकाळी एखादे पुस्तक मागितले, तर वडील ते कधीपर्यंत आणून देत असत?\",\"options\":[\"दुसऱ्या दिवशी सकाळी\",\"दुपारपर्यंत\",\"संध्याकाळपर्यंत\",\"आठवडाभराने\"],\"answer\":2,\"explain\":\"वडील मागितलेले पुस्तक संध्याकाळपर्यंत कुठूनतरी आणून देत असत, असे उताऱ्यात दिले आहे.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लेखकाला आपल्या वडिलांचा अत्यंत अभिमान का वाटतो?\",\"options\":[\"ते मुंबईत राहत होते म्हणून\",\"ते खूप श्रीमंत होते म्हणून\",\"हलाखीच्या परिस्थितीतही त्यांनी लेखकाची पुस्तकांची हौस पुरवली म्हणून\",\"त्यांनी लेखकाला कधीच रागावले नाही म्हणून\"],\"answer\":2,\"explain\":\"वडिलांनी स्वतः कष्ट सोसून लेखकाची आवड जपली, म्हणून लेखकाला त्यांचा अभिमान वाटतो.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात वडिलांसाठी कोणता शब्द वापरला आहे जो त्यांच्या स्वभावाचे वर्णन करतो?\",\"options\":[\"कडक\",\"प्रेमळ\",\"रागीट\",\"आळशी\"],\"answer\":1,\"explain\":\"लेखकाने वडिलांना \'प्रेमळ पिता\' असे संबोधले आहे.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"घरची स्थिती \'हलाखीची\' झाली म्हणजे काय झाले?\",\"options\":[\"घरची स्थिती सुधारली\",\"घरची स्थिती खूप गरिबीची झाली\",\"घरची स्थिती बदलली नाही\",\"घरची स्थिती श्रीमंतीची झाली\"],\"answer\":1,\"explain\":\"हलाखीची स्थिती म्हणजे अत्यंत गरिबीची किंवा कठीण परिस्थिती होय.\",\"topic\":\"कौटुंबिक परिस्थिती आणि वडिलांचे प्रेम\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखकाच्या वडिलांच्या खिशात बहुतेक काय नसायचे?\",\"options\":[\"पेन\",\"पैसे\",\"रुमाल\",\"चावी\"],\"answer\":1,\"explain\":\"उताऱ्यात उल्लेख आहे की वडिलांच्या खिशात बहुतेक पैसे नसायचेच.\",\"topic\":\"वडिलांची धडपड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या बहिणी कोठे राहत होत्या?\",\"options\":[\"पुण्यात\",\"नाशिकला\",\"मुंबईत\",\"नागपूरला\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की लेखकच्या दोघी बहिणी मुंबईतच असायच्या.\",\"topic\":\"वडिलांची धडपड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"लेखकाला पुस्तकासाठी साधारण किती रुपयांची गरज होती?\",\"options\":[\"दहा-बारा रुपये\",\"शंभर-दोनशे रुपये\",\"तीन-चार रुपये\",\"पन्नास रुपये\"],\