ly\"},{\"q\":\"\'बिल्लोरी\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"चकाकणारे\",\"अंधारलेले\",\"मोठे\",\"जुने\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुरानुसार \'बिल्लोरी\' म्हणजे \'चकाकणारे\' होय.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'भरारी घेणे\' या वाक्प्रचाराचा अर्थ ओळखा.\",\"options\":[\"पळणे\",\"उडणे\",\"पडणे\",\"बसणे\"],\"answer\":1,\"explain\":\"मजकुरात \'भरारी घेणे\' याचा अर्थ \'उडणे\' असा दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'गोजिरा\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"कडू\",\"सुंदर\",\"वाईट\",\"उंच\"],\"answer\":1,\"explain\":\"दिलेल्या माहितीनुसार \'गोजिरा\' या शब्दाचा अर्थ \'सुंदर\' असा होतो.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'चकाकणारे\' या अर्थासाठी कवितेत कोणता शब्द वापरला आहे?\",\"options\":[\"गोजिरा\",\"भरारी\",\"बिल्लोरी\",\"सुंदर\"],\"answer\":2,\"explain\":\"\'बिल्लोरी\' या शब्दाचा अर्थ \'चकाकणारे\' असा मजकुरात दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'उडणे\' या क्रियेसाठी कोणता शब्दसमूह आला आहे?\",\"options\":[\"भरारी घेणे\",\"गोजिरा होणे\",\"बिल्लोरी असणे\",\"सुंदर दिसणे\"],\"answer\":0,\"explain\":\"\'भरारी घेणे\' म्हणजे \'उडणे\' असा अर्थ मजकुरात स्पष्ट केला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'सुंदर\' या शब्दाचा अर्थ स्पष्ट करणारा शब्द कोणता?\",\"options\":[\"बिल्लोरी\",\"भरारी\",\"गोजिरा\",\"चकाकणारे\"],\"answer\":2,\"explain\":\"\'गोजिरा\' या शब्दाचा अर्थ \'सुंदर\' असा मजकुरात दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\\\"पक्षाने आकाशात उंच ____ घेतली.\\\" या वाक्यात रिकाम्या जागी कोणता शब्द योग्य ठरेल?\",\"options\":[\"बिल्लोरी\",\"भरारी\",\"गोजिरा\",\"सुंदर\"],\"answer\":1,\"explain\":\"पक्षी उडतात, म्हणून \'भरारी\' हा शब्द \'उडणे\' या अर्थासाठी योग्य आहे.\",\"topic\":\"स्वाध्याय\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"\\\"काचेचे मणी उन्हात ____ दिसतात.\\\" या वाक्यासाठी योग्य शब्द नि