",\"संरक्षण करणे\",\"वजन वाढवणे\",\"पोहण्यास मदत करणे\"],\"answer\":1,\"explain\":\"कवच हे संरक्षण करणारे आवरण असते, असे पाठात म्हटले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"शिक्षकांनी समुद्राच्या तळाशी असणाऱ्या कोणत्या गोष्टींविषयी चर्चा करावी?\",\"options\":[\"समुद्रातील लाटांविषयी\",\"विविध घटकांविषयी\",\"फक्त जहाजांविषयी\",\"आकाशातील ढगांविषयी\"],\"answer\":1,\"explain\":\"समुद्राच्या तळाशी असणाऱ्या विविध घटकांविषयी चर्चा घडवून आणावी, अशी सूचना दिली आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"मोती कसा तयार होतो हे दाखवण्यासाठी शिक्षकांनी कशाचे साहाय्य घ्यावे?\",\"options\":[\"कागदाच्या कपट्यांचे\",\"वेगवेगळ्या शिंपल्यांचे\",\"मातीच्या गोळ्यांचे\",\"प्लास्टिकच्या बाटल्यांचे\"],\"answer\":1,\"explain\":\"वेगवेगळ्या शिंपल्यांच्या साहाय्याने मोती कसा तयार होतो ते दाखवावे, असे पाठात नमूद आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"विद्यार्थ्यांचे लेखन कौशल्य सुधारण्यासाठी शिक्षकांनी पाठातील परिच्छेदांचे काय करून घ्यावे?\",\"options\":[\"फक्त वाचन\",\"अनुलेखन व श्रुतलेखन\",\"पाठांतर\",\"चित्रकला\"],\"answer\":1,\"explain\":\"लेखन सरावासाठी पाठातील परिच्छेदांचे अनुलेखन व श्रुतलेखन करून घेण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या वस्तूची किंमत खूप जास्त असेल, तर त्या वस्तूला पाठातील कोणत्या शब्दाने संबोधता येईल?\",\"options\":[\"कवच\",\"घटक\",\"मौल्यवान\",\"आवरण\"],\"answer\":2,\"explain\":\"अधिक किंमत असलेल्या वस्तूला \'मौल्यवान\' असे म्हणतात.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांसाठी दिलेल्या सूचनांनुसार, मोती तयार होण्याची प्रक्रिया समजून घेण्यासाठी कोणती कृती सर्वात योग्य ठरेल?\",\"options\":[\"समुद्राचे चित्र काढणे\",\"शिंपल्यांचा वापर करून प्रात्यक्षिक दाखवणे\",\"केवळ शब्दांचे अर्थ सांगणे\",\"पाठाचे पाठांतर करणे\"],\"answer\":1,\"explain\":\"शिंपल्यांच्या साहाय्याने मोती कसा तयार होतो हे प्रत्यक्ष दाखवणे ही प्रक्रिया समजून घेण्याची योग्य पद्धत आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"शिक्षकांसाठी दिलेल्या सूचनांचा मुख्य उद्देश काय आहे?\",\"options\":[\"विद्यार्थ्यांना फक्त खेळायला लावणे\",\"पाठातील संकल्पना विविध कृतींतून स्पष्ट करणे\",\"केवळ कठीण शब्दांचे पाठांतर करून घेणे\",\"समुद्राची सहल आयोजित करणे\"],\"answer\":1,\"explain\":\"वाचन, चर्चा, प्रात्यक्षिक आणि लेखन या कृतींतून पाठातील विषय नीट समजून सांगणे हा या सूचनांचा उद्देश आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"मराठी शब्दाच्या शेवटी येणारा इकार किंवा उकार उच्चारानुसार नेहमी कसा लिहावा?\",\"options\":[\"ऱ्हस्व\",\"दीर्घ\",\"अर्धा\",\"यांपैकी काहीही\"],\"answer\":1,\"explain\":\"मराठी भाषेच्या नियमानुसार शब्दाच्या शेवटी येणारा इकार किंवा उकार नेहमी दीर्घ लिहावा.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता शब्द शुद्धलेखनाच्या नियमानुसार अचूक लिहिला आहे?\",\"options\":[\"टोपि\",\"दांडु\",\"वाटी\",\"खेळु\"],\"answer\":2,\"explain\":\"शब्दाच्या शेवटी येणारा इकार दीर्घ असावा, म्हणून \'वाटी\' हा शब्द बरोबर आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला \'आई\' हा शब्द लिहायचा असेल, तर शेवटी कोणता इकार वापराल?\",\"options\":[\"ऱ्हस्व (पहिली वेलांटी)\",\"दीर्घ (दुसरी वेलांटी)\",\"वेलांटी देणार नाही\",\"यांपैकी कोणतेही नाही\"],\"answer\":1,\"explain\":\"नियमानुसार शब्दाच्या शेवटी येणारा इकार दीर्घ (दुसरी वेलांटी) असावा.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"बालसाहित्यामध्ये खालीलपैकी कशाचा अंतर्भाव होतो?\",\"options\":[\"फक्त बातम्यांचा\",\"फक्त जाहिरातींचा\",\"विविध प्रकारच्या साहित्याचा\",\"केवळ मोठ्या माणसांच्या कथांचा\"],\"answer\":2,\"explain\":\"बालसाहित्यामध्ये विविध प्रकारच्या साहित्याचा समावेश होतो, जसे की कथा.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"एखाद्या थोर व्यक्तीच्या जीवनावर आधारित कथेला काय म्हणतात?\",\"options\":[\"विज्ञान कथा\",\"साहस कथा\",\"चरित्र कथा\",\"रहस्य कथा\"],\"answer\":2,\"explain\":\"व्यक्तीच्या जीवनावर आधारित कथेला चरित्र कथा म्हणतात.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"शिवाजी महाराजांच्या पराक्रमाची गोष्ट कोणत्या कथा प्रकारात येईल?\",\"options\":[\"ऐतिहासिक कथा\",\"विज्ञान कथा\",\"प्राणी कथा\",\"रहस्य कथा\"],\"answer\":0,\"explain\":\"इतिहासातील घटनांवर आधारित गोष्टी ऐतिहासिक कथा या प्रकारात मोडतात.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या माहितीनुसार, \'चातुर्य कथा\' या प्रकारात कशाचे वर्णन असेल?\",\"options\":[\"भीतीचे\",\"हुशारीचे किंवा युक्तीचे\",\"विज्ञानातील प्रयोगांचे\",\"केवळ प्राण्यांच्या खेळांचे\"],\"answer\":1,\"explain\":\"चातुर्य म्हणजे हुशारी, म्हणून अशा कथांत युक्तीचे वर्णन असते.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"शब्दाच्या शेवटी दीर्घ उकार असलेला शब्द ओळखा.\",\"options\":[\"वाळू\",\"भाउ\",\"लाडु\",\"पेरु\"],\"answer\":0,\"explain\":\"दिलेल्या पर्यायांपैकी \'वाळू\' या शब्दात शेवटी दीर्घ उकार (दुसरा उकार) आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत मध्यभागी असलेल्या गोलात कोणता शब्द लिहिला आहे?\",\"options\":[\"साहित्य\",\"कविता\",\"कथा\",\"नाटक\"],\"answer\":2,\"explain\":\"आकृतीच्या मध्यभागी \'कथा\' हा शब्द दिला आहे ज्याचे विविध प्रकार बाणांनी दाखवले आहेत.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"remember\",\"figure_image\":\"20\\/090_103.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. \'कथा\' या मुख्य प्रकाराचे एकूण किती उपप्रकार बाणांच्या साहाय्याने दाखवले आहेत?\",\"options\":[\"५\",\"७\",\"९\",\"१०\"],\"answer\":2,\"explain\":\"आकृतीत मध्यभागी असलेल्या \'कथा\' या शब्दापासून एकूण ९ बाण बाहेर पडले आहेत, जे ९ उपप्रकार दर्शवतात.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"20\\/090_103.jpg\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28'),(21568,20,4,'Marathi','mr','सण आला पाडव्याचा! (कविता)','[\"गुढीपाडवा मराठी नवीन वर्षाची सुरुवात होतो.\",\"गुढीपाडवा चैत्र शुद्ध प्रथम दिवसाला साजरा केला जातो.\",\"गुढीपाडव्यासाठी घरात गुढी (ब्रह्मध्वज) टाकली जाते.\",\"गुढीवर साफ कपडा, नारळ, गुलाब, शक्कर, neem के पात व गुढी बांधली जाते.\",\"गुढीपाडव्याचा अर्थ हा नवीन वर्षाचा स्वागत करणे आहे.\",\"सणात घरोघरी शालू व हार-कडे सजवले जातात.\",\"पर्यावरणाचे संतुलन व निसर्गाचा आदर दर्शविणे हे गुढीपाडव्याचा संदेश आहे.\",\"कडुनिंबा (नीम) व पानगळ खाण्याने आरोग्य व मिठासची शिकवली जाते.\",\"नवचैतन्याने प्रगतीकडे मारग वाहणे हे सणाचा विचार आहे.\",\"सणांमध्ये सांस्कृतिक जतन, एकता व हर्ष वाढवते.\",\"गुढीपाडवा सणावर शुभेच्छापत्रे तयार केली जातात.\",\"सणांवर आधारित कविता, लोकगीत व कथा ऐकणे मराठी संस्कृतीचा भाग आहे.\",\"सणात परंपरागत खाणे पदार्थे खाण्याने आरोग्य ठेवले जाते.\",\"सणांचा उद्देश्य सामाजिक एकता व सकारात्मकता फैलवणे आहे.\",\"गुढीपाडवा सणाला हिंदू पंचांगनुसार चैत्र महिना साजरा केला जातो.\"]','[{\"q\":\"पाडव्याचा सण कशाचा सांगावा घेऊन येतो?\",\"options\":[\"पावसाळ्याचा\",\"दिवाळीचा\",\"नववर्षाचा\",\"सुट्टीचा\"],\"answer\":2,\"explain\":\"कवितेच्या पहिल्या ओळीत \'सांगावा नववर्षाचा\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"कवितेनुसार पाडव्याचा सण आल्यावर काय संपते?\",\"options\":[\"पागळ\",\"उन्हाळा\",\"शाळा\",\"पाऊस\"],\"answer\":0,\"explain\":\"कवितेत \'संपली ती पागळ\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'हर्षोर्मी\' या शब्दाचा अर्थ काय?\",\"options\":[\"दुःखाची लाट\",\"आनंदाची लाट\",\"पाण्याची लाट\",\"थंडीची लाट\"],\"answer\":1,\"explain\":\"हर्ष म्हणजे आनंद आणि ऊर्मी म्हणजे लाट, म्हणून हर्षोर्मी म्हणजे आनंदाची लाट.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"रानोवनी कशाची सळसळ चालली आहे?\",\"options\":[\"वाळलेल्या पानांची\",\"फुलांची\",\"हिरव्या पानांची\",\"प्राण्यांची\"],\"answer\":2,\"explain\":\"कवितेत \'हिरव्या पानांची चाले रानोवनी सळसळ\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"पर्यावरणाचे भान राखून कोणाचा सन्मान करावा असे कवितेत सांगितले आहे?\",\"options\":[\"वाहनांचा\",\"वृक्षांचा\",\"मोठ्या माणसांचा\",\"खेळांचा\"],\"answer\":1,\"explain\":\"कवितेत \'कुटुंबिबांदी वृक्षांचा नित्य करावा सन्मान\' असे सांगितले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"प्रगतीकडे भरारी घेण्यासाठी काय आवश्यक आहे?\",\"options\":[\"आळस\",\"भीती\",\"नवचैतन्य\",\"विश्रांती\"],\"answer\":2,\"explain\":\"कवितेत \'नवचैतन्याने घेऊ प्रगतीकडे भरारी\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"\'चराचरी दिसे ऊर्मी\' या ओळीतील \'चराचरी\' या शब्दाचा अर्थ काय?\",\"options\":[\"फक्त माणसांमध्ये\",\"फक्त प्राण्यांमध्ये\",\"सजीव आणि निर्जीव अशा सर्व ठिकाणी\",\"केवळ घरामध्ये\"],\"answer\":2,\"explain\":\"चराचर म्हणजे सृष्टीतील सर्व सजीव आणि निर्जीव वस्तू.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"कवितेत वृक्षांना \'कुटुंबिबांदी\' का म्हटले असावे?\",\"options\":[\"कारण ते घराच्या जवळ असतात\",\"कारण ते कुटुंबातील सदस्यांसारखेच महत्त्वाचे आहेत\",\"कारण ते खूप मोठे असतात\",\"कारण ते सावली देतात\"],\"answer\":1,\"explain\":\"वृक्षांना कुटुंबाचा भाग मानून त्यांचा सन्मान करावा हा संदेश देण्यासाठी हा शब्द वापरला आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रात, गुढीच्या कलशावर (तांब्यावर) कोणते शुभ चिन्ह दिसत आहे?\",\"options\":[\"ओम\",\"स्वस्तिक\",\"त्रिशूळ\",\"कमळ\"],\"answer\":1,\"explain\":\"चित्रात गुढीच्या तांब्यावर स्वस्तिकाचे चिन्ह स्पष्ट दिसत आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"20\\/091_101.jpg\"},{\"q\":\"दिलेल्या चित्रात, गुढीच्या काठीला शालू व्यतिरिक्त काय लावलेले दिसत आहे?\",\"options\":[\"फुलांचा हार\",\"फटाके\",\"पुस्तके\",\"खेळणी\"],\"answer\":0,\"explain\":\"चित्रात गुढीला फुलांचा हार आणि कडुलिंबाची पाने लावलेली दिसत आहेत.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"20\\/091_101.jpg\"},{\"q\":\"\'सांगावा\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"निरोप\",\"गडबड\",\"उत्साह\",\"झेप\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील शब्दार्थांनुसार सांगावा म्हणजे निरोप होय.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"remember\