opic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"understand\"},{\"q\":\"For the number 3524, what is the number obtained by arranging its digits in descending order?\",\"options\":[\"2345\",\"3524\",\"5432\",\"4352\"],\"answer\":2,\"explain\":\"Arranging digits of 3524 from greatest to smallest gives 5432.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"apply\"},{\"q\":\"For the number 3524, what is the number obtained by arranging its digits in ascending order?\",\"options\":[\"2345\",\"5432\",\"3524\",\"4325\"],\"answer\":0,\"explain\":\"Arranging digits of 3524 from smallest to greatest gives 2345.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"apply\"},{\"q\":\"In the Kaprekar procedure, which subtraction is performed?\",\"options\":[\"Greater number from smaller number\",\"Smaller number from greater number\",\"Odd number from even number\",\"First number from last number\"],\"answer\":1,\"explain\":\"The text says \'Subtract smaller number from greater number\'.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"understand\"},{\"q\":\"What is the result of subtracting 2345 from 5432 as shown in the text?\",\"options\":[\"8352\",\"6174\",\"3087\",\"0378\"],\"answer\":2,\"explain\":\"According to the text, 5432 - 2345 = 3087.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"remember\"},{\"q\":\"When arranging the digits of the answer 3087 in ascending order, what number do we get?\",\"options\":[\"8730\",\"0378\",\"3078\",\"7830\"],\"answer\":1,\"explain\":\"Arranging 3, 0, 8, 7 in ascending order gives 0378.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"apply\"},{\"q\":\"What is the descending order of the digits in the number 8352?\",\"options\":[\"2358\",\"8532\",\"8352\",\"5832\"],\"answer\":1,\"explain\":\"The text shows that for the answer 8352, the descending order is 8532.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"apply\"},{\"q\":\"What happens when you repeat the procedure on the number 6174?\",\"options\":[\"The number becomes zero\",\"The number increases\",\"The same answer 6174 is obtained\",\"The digits reverse their order\"],\"answer\":2,\"explain\":\"The text notes that repeating the procedure on 6174 gives the same answer 6174.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"understand\"},{\"q\":\"The teacher should help students make number bonds for which number?\",\"options\":[\"10\",\"50\",\"100\",\"1000\"],\"answer\":2,\"explain\":\"The text states: \'Let us make number bonds for 100.\'\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"remember\"},{\"q\":\"If the descending order is 8730 and the ascending order is 0378, what is the result of the subtraction?\",\"options\":[\"3087\",\"8352\",\"6174\",\"5432\"],\"answer\":1,\"explain\":\"As per the text\'s sequence, 8730 - 0378 results in 8352.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"analyze\"},{\"q\":\"What is the final step in the procedure before repeating it?\",\"options\":[\"Adding the two numbers\",\"Multiplying the digits\",\"Subtracting smaller number from greater number\",\"Dividing by 100\"],\"answer\":2,\"explain\":\"The text indicates the step is to \'Subtract smaller number from greater number\'.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"understand\"},{\"q\":\"For the number 6174, what is the ascending order of its digits?\",\"options\":[\"1467\",\"7641\",\"1476\",\"4167\"],\"answer\":0,\"explain\":\"The text shows that for 6174, the ascending order is 1467.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"apply\"},{\"q\":\"Which of these numbers is NOT used as a subtraction result in the text\'s example?\",\"options\":[\"3087\",\"8352\",\"6174\",\"9999\"],\"answer\":3,\"explain\":\"The text mentions 3087, 8352, and 6174 as results, but not 9999.\",\"topic\":\"Kaparekar Constant\",\"part\":14,\"bloom\":\"analyze\"},{\"q\":\"Based on the text, what is the result of 7641 minus 1467?\",\"options\":[\"617