ptions\":[\"केवळ एक\",\"केवळ दोन\",\"अनेक (अंक निवडणे, वजाबाकी, अदलाबदल, बेरीज)\",\"फक्त गुणाकार\"],\"answer\":2,\"explain\":\"या खेळात अंक निवडण्यापासून ते बेरीज करण्यापर्यंत अनेक पायऱ्यांचा समावेश आहे.\",\"topic\":\"गणित गंमत\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"\'ह श द ए\' या प्रतीकांमध्ये \'ह\' हे अक्षर कोणत्या स्थानासाठी वापरले आहे?\",\"options\":[\"हजार\",\"शतक\",\"दशक\",\"एकक\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील प्रतीकांनुसार \'ह\' म्हणजे हजार स्थान होय.\",\"topic\":\"खेळांतून गणित\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'आय गॉट\' (I got) खेळात संख्या तयार केल्यावर विद्यार्थ्याने काय म्हणणे आवश्यक आहे?\",\"options\":[\"मी जिंकलो\",\"संख्या तयार\",\"आय गॉट\",\"माझे झाले\"],\"answer\":2,\"explain\":\"जो विद्यार्थी संख्या चटकन व अचूकपणे तयार करेल त्याने \'आय गॉट\' असे म्हणायचे आहे.\",\"topic\":\"खेळांतून गणित\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'०८२९\' ही संख्या प्रत्यक्षात किती अंकी संख्या आहे?\",\"options\":[\"चार अंकी\",\"दोन अंकी\",\"तीन अंकी\",\"पाच अंकी\"],\"answer\":2,\"explain\":\"संख्येच्या सुरुवातीला शून्य असल्यास ती तीन अंकी संख्या मानली जाते.\",\"topic\":\"खेळांतून गणित\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"\'आय गॉट\' खेळ खेळण्यासाठी ० ते ९ पर्यंतच्या अंकाकाडीचे किती संच तयार करायचे आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार विद्यार्थ्यांकडून चार संच तयार करून घ्यावेत.\",\"topic\":\"खेळांतून गणित\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'ह श द ए\' या प्रतीकांमध्ये \'ए\' चा अर्थ काय होतो?\",\"options\":[\"एक\",\"एकक\",\"एकोणतीस\",\"एकूण\"],\"answer\":1,\"explain\":\"संख्या स्थानांच्या प्रतीकांमध्ये \'ए\' म्हणजे एकक स्थान होय.\",\"topic\":\"खेळांतून गणित\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'आय गॉट\' खेळात विजेता ठरण्यासाठी कोणती अट पूर्ण करणे आवश्यक आहे?\",\"options\":[\"फक्त सर्वात मोठी संख्या तयार करणे\",\"फक्त सर्वात छोटी संख्या तयार करणे\",\"चटकन व अचूकपणे संख्या तयार करणे\",\"फक्त शून्याचा वापर करणे\"],\"answer\":2,\"explain\":\"जो वि