INSERT INTO `ep_topic_packs` VALUES (21589,22,4,'Maths','mr','लांबी व वजन','[\"लांबी मोजण्याचे मानक एकक: मिलिमीटर (mm), सेंटिमीटर (cm), मीटर (m), किलोमीटर (km)\",\"1 सेमी = 10 mm, 1 मीटर = 100 सेमी = 1000 mm, 1 किलोमीटर = 1000 मीटर\",\"वापरण्याचे नियम: लहान वस्तू (जसे पेन) मिमी\\/सेमी, मध्यम (जसे टेबल) मीटर, मोठी अंतर (जसे गाव) किलोमीटर\",\"रूपांतर: सेमी ला mm मधे = 10 गुणा, मीटर ला सेमी = 100 गुणा, किलोमीटर ला मीटर = 1000 गुणा\",\"वजन मोजण्याचे एकक: ग्रॅम (g), किलोग्रॅम (kg)\",\"1 किलोग्रॅम = 1000 ग्रॅम, अर्धा किलो = 500 ग्रॅम, पाव किलो = 250 ग्रॅम, सव्वा किलो = 1250 ग्रॅम\",\"वजन जोडणे\\/घटणे: समान एककात लावा (उदा. kg ला g मधे रूपांतर करून)\",\"वजन अंदाज: हाताळून अंदाज लगवणे, नंतर तुलनेने मोजून तपासणे\",\"वस्तू उभी, आडवी, तिरपी ठेवून लांबी मोजणे: उभी = base, आडवी = side, तिरपी = diagonal\",\"प्राचीन भारतीय एकक: 1 अंगुल = 8 jaw, 24 अंगुल = 1 हस्त, 4 हस्त = 1 दंड, 2000 दंड = 1 क्रोष, 4 क्रोष = 1 योजन\",\"वापरयोग्य साधने: रूलर (सेमी\\/मी), मापी (मी\\/किमी), तराजू (वजन)\",\"सावधानी: मोजत वेळी शून्यपunktून मोजणे, एकक समान ठेवणे\",\"उदाहरण: पेनची लांबी ~10 सेमी, पातळी किताबची जाडी ~1 मिमी, शाळेची लांबी ~30 मीटर\",\"रूपांतर तपासणे: 2.5 मीटर = 250 सेमी = 2500 mm\",\"वजन तुलना: 1.5 kg > 1200 g, 750 g < 1 kg\"]','[{\"q\":\"शाळेच्या क्रीडांगणावरील वस्तूंची लांबी मोजण्यासाठी काय करणे आवश्यक आहे?\",\"options\":[\"वस्तूंचा रंग पाहणे\",\"योग्य एककांचा वापर करणे\",\"वस्तूंचे वजन करणे\",\"वस्तूंची संख्या मोजणे\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, वस्तूंची लांबी मोजण्यासाठी योग्य एककांचा वापर करणे आवश्यक आहे.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या मजकुरात खालीलपैकी कोणत्या वस्तूची \'उंची\' मोजण्यास सांगितले आहे?\",\"options\":[\"बंटाची\",\"भाल्याची\",\"यष्टीची\",\"घुंगरूकाठीची\"],\"answer\":2,\"explain\":\"मजकुरातील यादीत ३ व्या क्रमांकावर \'यष्टीची उंची\' मोजण्यास सांगितले आहे.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खो-खोच्या दोन खांबांमधील अंतर मोजण्यासाठी कोणते एकक सर्वात योग्य ठरेल?\",\"options\":[\"सेंटीमीटर\",\"मीटर\",\"मिलीमीटर\",\"ग्रॅम\"],\"answer\":1,\"explain\":\"मैदानावरील दोन खांबांमधील जास्त अंतर मोजण्यासाठी \'मीटर\' हे एकक सोयीचे असते.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"मजकुराप्रमाणे, \'बंटेची\' कोणती गोष्ट मोजण्यास सांगितले आहे?\",\"options\":[\"उंची\",\"वजन\",\"रुंदी\",\"जाडी\"],\"answer\":2,\"explain\":\"मजकुरातील दुसऱ्या मुद्द्यात \'बंटेची रुंदी\' मोजण्यास सांगितले आहे.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खो-खोच्या खांबांमधील अंतर \'फुटांमध्ये\' (पावलांनी) मोजल्यास कोणती अडचण येईल?\",\"options\":[\"मोजायला वेळ लागेल\",\"प्रत्येकाच्या पावलांची लांबी वेगळी असल्याने मोजमाप चुकेल\",\"पावले मोजणे सोपे असते\",\"खांब हलतील\"],\"answer\":1,\"explain\":\"व्यक्तीनुसार पावलांची लांबी बदलत असल्याने फुटांमधील मोजमाप प्रमाणित नसते.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"भाल्याची लांबी मोजण्यासाठी सेंटीमीटरपेक्षा मीटर हे एकक वापरणे का सोयीचे आहे?\",\"options\":[\"भाला खूप हलका असतो\",\"भाल्याची लांबी जास्त असते\",\"सेंटीमीटरने मोजता येत नाही\",\"मीटर हे लहान एकक आहे\"],\"answer\":1,\"explain\":\"मोठ्या वस्तूंची लांबी मोजण्यासाठी मीटर हे मोठे एकक वापरणे सोयीचे ठरते.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला घुंगरूकाठीची लांबी मोजायची असेल, तर तुम्ही खालीलपैकी कशाचा वापर कराल?\",\"options\":[\"वजन काटा\",\"मोजपट्टी किंवा टेप\",\"तापमापी\",\"लिटरचे माप\"],\"answer\":1,\"explain\":\"लांबी मोजण्यासाठी मोजपट्टी किंवा मोजपट्टीचा टेप वापरला जातो.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या मजकुरात कोणत्या खेळाच्या मैदानातील खांबांचा उल्लेख आहे?\",\"options\":[\"कबड्डी\",\"क्रिकेट\",\"खो-खो\",\"फुटबॉल\"],\"answer\":2,\"explain\":\"मजकुरात \'खो-खोच्या दोन खांबांमधील अंतर\' मोजण्याबाबत चर्चा केली आहे.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात मुले क्रिकेट खेळत आहेत, तिथे \'यष्टीची उंची\' मोजण्यासाठी कोणते एकक वापरणे सर्वात अचूक ठरेल?\",\"options\":[\"मीटर\",\"सेंटीमीटर\",\"किलोमीटर\",\"लिटर\"],\"answer\":1,\"explain\":\"यष्टीची उंची साधारणपणे सेंटीमीटरमध्ये मोजणे अधिक अचूक आणि सोयीचे असते.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"22\\/055_101.jpg\"},{\"q\":\"दिलेल्या चित्रात दाखवलेल्या \'बॅटची लांबी\' मोजण्यासाठी खालीलपैकी कोणते साधन वापरणे योग्य ठरेल?\",\"options\":[\"हाताची वीत\",\"पावलांचे अंतर\",\"प्रमाणित मोजपट्टी\",\"दोरीचा तुकडा\"],\"answer\":2,\"explain\":\"अचूक लांबी मोजण्यासाठी प्रमाणित मोजपट्टीचा वापर करणे आवश्यक आहे.\",\"topic\":\"लांबी व वजन - चर्चा करा\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"22\\/055_101.jpg\"},{\"q\":\"चेंडू कोठून फेकायचा आहे?\",\"options\":[\"प्रारंभ रेषेपासून\",\"मैदानाच्या मधून\",\"भिंतीपासून\",\"कोठूनही\"],\"answer\":0,\"explain\":\"मजकुरात स्पष्टपणे \'प्रारंभ रेषेपासून\' चेंडू फेकायला सांगितले आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"चेंडूचे अंतर मोजण्यासाठी खुणेने खूण कोठे करायची आहे?\",\"options\":[\"चेंडू जिथे थांबेल तिथे\",\"चेंडूचा प्रथम टप्पा जेथे पडेल तिथे\",\"प्रारंभ रेषेवर\",\"अंदाजे सहा मीटरवर\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, चेंडूचा प्रथम टप्पा जेथे पडेल तेथे खुणेने खूण करायची आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"या कृतीमध्ये अंदाजे किती अंतरावर चेंडू फेकायचा आहे?\",\"options\":[\"दोन मीटर\",\"चार मीटर\",\"सहा मीटर\",\"दहा मीटर\"],\"answer\":2,\"explain\":\"मजकुरात \'अंदाजे सहा मीटर अंतरावर\' चेंडू फेकावयाचा आहे असे दिले आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"प्रत्यक्ष अंतर मोजण्यासाठी कोणते साधन वापरायचे आहे?\",\"options\":[\"हाताची वीत\",\"पावले\",\"मीटरपट्टी\",\"काठी\"],\"answer\":2,\"explain\":\"मजकुरात प्रत्यक्ष अंतर \'मीटरपट्टिने\' मोजण्यास सांगितले आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर चेंडू ७ मीटर अंतरावर पडला, तर तक्त्यात कोणत्या रकान्यात \'√\' खूण कराल?\",\"options\":[\"६ मी. पेक्षा जास्त\",\"६ मी.\",\"६ मी. पेक्षा कमी\",\"प्रारंभ रेषा\"],\"answer\":0,\"explain\":\"७ मीटर हे ६ मीटरपेक्षा जास्त असल्याने \'६ मी. पेक्षा जास्त\' या रकान्यात खूण येईल.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"तक्त्यामध्ये \'अंदाजे अंतर\' या मुख्य रकान्यात किती उप-पर्याय दिले आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"तक्त्यात ६ मी.पेक्षा जास्त, ६ मी., आणि ६ मी.पेक्षा कमी असे तीन उप-रकाने आहेत.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"चेंडू फेकल्यानंतर प्रत्यक्ष मोजलेले अंतर कोठे नोंदवायचे आहे?\",\"options\":[\"फळ्यावर\",\"तक्त्यातील शेवटच्या रकान्यात\",\"प्रारंभ रेषेवर\",\"चेंडूवर\"],\"answer\":1,\"explain\":\"तक्त्यात \'प्रत्यक्ष मोजलेले अंतर\' हा शेवटचा रकाना नोंदीसाठी दिला आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर चेंडू ४ मीटर अंतरावर पडला, तर तो ६ मीटरपेक्षा कसा आहे?\",\"options\":[\"जास्त\",\"समान\",\"कमी\",\"दुप्पट\"],\"answer\":2,\"explain\":\"४ मीटर हे ६ मीटरपेक्षा कमी असते, म्हणून \'६ मी. पेक्षा कमी\' हा पर्याय योग्य आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"या कृतीचा मुख्य उद्देश काय आहे?\",\"options\":[\"चेंडू हरवणे\",\"अंदाजे आणि प्रत्यक्ष अंतराची तुलना करणे\",\"वेगाने धावणे\",\"मैदानाची लांबी मोजणे\"],\"answer\":1,\"explain\":\"अंदाजे अंतर आणि प्रत्यक्ष मोजलेले अंतर यांची नोंद तक्त्यात करणे हा या कृतीचा उद्देश आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"तक्त्यातील \'अंदाजे अंतर\' या रकान्यात कोणती खूण करायला सांगितली आहे?\",\"options\":[\"गुणाकाराची (X)\",\"वर्तुळाची (O)\",\"बरोबरची (√)\",\"ताऱ्याची (*)\"],\"answer\":2,\"explain\":\"मजकुरात \'तुमचे जे उत्तर असेल तिथे √ अशी खूण करा\' असे स्पष्ट म्हटले आहे.\",\"topic\":\"कृती: चेंडू फेकून अंतर मोजणे\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'मीटर\' हे शब्द थोडक्यात कसे लिहितात?\",\"options\":[\"मी\",\"सेंमी\",\"म\",\"मीट\"],\"answer\":0,\"explain\":\"मजकुरात स्पष्ट दिले आहे की मीटर हे ‘मी’ असे लिहितात.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"१ मीटर म्हणजे किती सेंटीमीटर?\",\"options\":[\"५० सेंमी\",\"२५ सेंमी\",\"१०० सेंमी\",\"७५ सेंमी\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे १ मीटर म्हणजे १०० सेंमी होय.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"\'सेंमी\' हे कोणत्या शब्दाचे संक्षिप्त रूप आहे?\",\"options\":[\"मीटर\",\"मिलीमीटर\",\"सेंटीमीटर\",\"सेकंद\"],\"answer\":2,\"explain\":\"मजकुरात दिले आहे की सेंटीमीटर हे थोडक्यात ‘सेंमी’ असे लिहितात.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"अर्धा मीटर म्हणजे किती सेंटीमीटर?\",\"options\":[\"२५ सेंमी\",\"५० सेंमी\",\"७५ सेंमी\",\"१०० सेंमी\"],\"answer\":1,\"explain\":\"मजकुरात अर्धा मीटर म्हणजे ५० सेंमी असे नमूद केले आहे.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पाव मीटरची लांबी किती असते?\",\"options\":[\"५० सेंमी\",\"७५ सेंमी\",\"१०० सेंमी\",\"२५ सेंमी\"],\"answer\":3,\"explain\":\"मजकुराप्रमाणे पाव मीटर म्हणजे २५ सेंमी होय.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दोन वेळा अर्धा मीटर एकत्र केल्यास किती लांबी होते?\",\"options\":[\"पाव मीटर\",\"पाऊण मीटर\",\"१ मीटर\",\"२ मीटर\"],\"answer\":2,\"explain\":\"दोन वेळा अर्धा मीटर (५०+५०) एकत्र केल्यास १ मीटर लांबी होते.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"तीन वेळा पाव मीटर घेतल्यास त्याला काय म्हणतात?\",\"options\":[\"अर्धा मीटर\",\"पाऊण मीटर\",\"१ मीटर\",\"सव्वा मीटर\"],\"answer\":1,\"explain\":\"मजकुरात दिले आहे की तीन वेळा पाव मीटर घेतल्यास लांबी पाऊण मीटर होते.\",\"topic\":\"मीटर आणि सेंटीमीटर\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"अर्धा मीटर व पाव मीटर मिळून किती लांबी तयार होते?\",\"options\":[\"१ मीटर\",\"पाऊण मीट