ी\",\"१ सेंमी = १० मिमी\",\"१० सेंमी = १ मिमी\"],\"answer\":2,\"explain\":\"१० समान भाग म्हणजे १० मिलिमीटर, म्हणून १ सेंमी = १० मिमी.\",\"topic\":\"सेंटिमीटर - मिलिमीटर\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एका वस्तूची लांबी ३० मिमी आहे, तर ती किती सेंटिमीटर आहे?\",\"options\":[\"३ सेंमी\",\"३० सेंमी\",\"३०० सेंमी\",\"१३ सेंमी\"],\"answer\":0,\"explain\":\"३ सेंमी = ३ × १० मिमी = ३० मिमी, म्हणून ३० मिमी म्हणजे ३ सेंमी.\",\"topic\":\"सेंटिमीटर - मिलिमीटर\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"\'किमी\' हे कोणत्या शब्दाचे संक्षिप्त रूप आहे?\",\"options\":[\"किलोग्रॅम\",\"किलोमीटर\",\"किलोलिटर\",\"किरण\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, किमी म्हणजे किलोमीटर होय.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दोन गावांमधील अंतर मोजण्यासाठी कोणते एकक वापरतात?\",\"options\":[\"मीटर\",\"सेंटीमीटर\",\"किलोमीटर\",\"ग्रॅम\"],\"answer\":2,\"explain\":\"दोन गावांमधलं अंतर मोजण्यासाठी किलोमीटर (किमी) हे एकक वापरतात.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"१ किलोमीटर म्हणजे किती मीटर होतात?\",\"options\":[\"१०० मीटर\",\"५०० मीटर\",\"७५० मीटर\",\"१००० मीटर\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकातील \'लक्षात ठेवा\' या भागात १ किमी = १००० मी असे दिले आहे.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"अर्धा किलोमीटर म्हणजे किती मीटर?\",\"options\":[\"२५० मी\",\"५०० मी\",\"७५० मी\",\"१०० मी\"],\"answer\":1,\"explain\":\"अर्धा किमी = 1\\/2 किमी = ५०० मी.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"३ किमी चे मीटरमध्ये रूपांतर केल्यास किती उत्तर येईल?\",\"options\":[\"३० मी\",\"३०० मी\",\"३००० मी\",\"३५०० मी\"],\"answer\":2,\"explain\":\"३ किमी = ३ × १००० मी = ३००० मी.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"जर ८ किमी = ८ × १००० मी असेल, तर रिकाम्या जागी कोणती संख्या येईल?\",\"options\":[\"८०० मी\",\"८००० मी\",\"८० मी\",\"८०,००० मी\"],\"answer\":1,\"explain\":\"८ किमी चे मीटरमध्ये रूपांतर ८००० मी होते.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"पाऊण किलोमीटर म्हणजे किती मीटर?\",\"options\":[\"२५० मी\",\"५०० मी\",\"७५० मी\",\"१००० मी\"],\"answer\":2,\"explain\":\"पाऊण किमी = 3\\/4 किमी = ७५० मी.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एका फलकावर ६००० मी अंतर लिहिले असेल, तर ते किती किलोमीटर आहे?\",\"options\":[\"४ किमी\",\"५ किमी\",\"६ किमी\",\"७ किमी\"],\"answer\":2,\"explain\":\"१००० मी = १ किमी, म्हणून ६००० मी = ६ किमी.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. जांब (बुद्रुक) ते शिरूर हे अंतर किती किमी आहे?\",\"options\":[\"२३ किमी\",\"३० किमी\",\"२४ किमी\",\"४ किमी\"],\"answer\":2,\"explain\":\"आकृतीमधील दिशादर्शक फलकावर शिरूर समोर २४ किमी असे लिहिले आहे.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"22\\/060_102.jpg\"},{\"q\":\"दिलेल्या आकृतीनुसार, जांब (बुद्रुक) पासून सर्वात कमी अंतरावर कोणते गाव आहे?\",\"options\":[\"मुखेड\",\"कंधार\",\"शिरूर\",\"जळकोट\"],\"answer\":3,\"explain\":\"आकृतीत जळकोटचे अंतर सर्वात कमी म्हणजे ४ किमी आहे.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"22\\/060_102.jpg\"},{\"q\":\"पाव किलोमीटर म्हणजे किती मीटर?\",\"options\":[\"१०० मी\",\"२५० मी\",\"५०० मी\",\"७५० मी\"],\"answer\":1,\"explain\":\"पाव किमी = 1\\/4 किमी = २५० मी.\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"७ किमी चे मीटरमध्ये रूपांतर करण्यासाठी ७ ला कोणत्या संख्येने गुणावे लागेल?\",\"options\":[\"१०\",\"१००\",\"१०००\",\"५००\"],\"answer\":2,\"explain\":\"किलोमीटरचे मीटरमध्ये रूपांतर करताना १००० ने गुणतात (७ × १००० मी).\",\"topic\":\"किलोमीटर - मीटर\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"प्राचीन काळातील अंतर मोजण्याच्या एककांबद्दलची माहिती कोणत्या ग्रंथात दिली आहे?\",\"options\":[\"लीलावती\",\"गणित सार\",\"बीजगणित\",\"सिद्धांत शिरोमणी\"],\"answer\":0,\"explain\":\"भास्कराचार्य यांनी लिहिलेल्या \'लीलावती\' या ग्रंथात प्राचीन मापन पद्धतीची माहिती दिली आहे.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"एखाद्या वस्तूची लांबी उभी, आडवी किंवा तिरपी मोजल्यास काय फरक पडतो?\",\"options\":[\"लांबी वाढते\",\"लांबी कमी होते\",\"लांबी सारखीच भरते\",\"लांबी मोजता येत नाही\"],\"answer\":2,\"explain\":\"प्रमाणित एककाचा वापर करून वस्तू कशीही धरून मोजली तरी तिची लांबी सारखीच भरते.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"भास्कराचार्यांच्या मते, ८ जव म्हणजे किती अंगुल होतात?\",\"options\":[\"२ अंगुल\",\"१ अंगुल\",\"४ अंगुल\",\"२४ अंगुल\"],\"answer\":1,\"explain\":\"ग्रंथातील माहितीनुसार ८ जव = १ अंगुल असे प्रमाण दिले आहे.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत वस्तूची लांबी मोजण्याची कोणती पद्धत दर्शवली आहे?\",\"options\":[\"उभी\",\"आडवी\",\"तिरपी\",\"वर्तुळाकार\"],\"answer\":1,\"explain\":\"आकृतीमध्ये वस्तू जमिनीला समांतर म्हणजेच \'आडवी\' ठेवून मोजली जात आहे.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"22\\/061_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत वस्तू \'अ\' आणि \'ब\' या बिंदूंमध्ये तिरपी ठेवली आहे. जर हीच वस्तू सरळ उभी केली, तर तिच्या लांबीवर काय परिणाम होईल?\",\"options\":[\"लांबी वाढेल\",\"लांबी कमी होईल\",\"लांबी तीच राहील\",\"लांबी मोजता येणार नाही\"],\"answer\":2,\"explain\":\"वस्तूची स्थिती बदलली तरी तिची मूळ लांबी बदलत नाही, ती सारखीच राहते.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"22\\/061_103.jpg\"},{\"q\":\"नीरज चोप्रा यांनी टोकियो ऑलिम्पिकमध्ये किती मीटर अंतरावर भालाफेक केली?\",\"options\":[\"८०.५८ मीटर\",\"८७.५८ मीटर\",\"९०.०० मीटर\",\"८५.७८ मीटर\"],\"answer\":1,\"explain\":\"नीरज चोप्रा यांनी ८७.५८ मीटर अंतरावर भालाफेक करून सुवर्णपदक जिंकले.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रातील खेळाडूने भारतासाठी कोणत्या खेळात पहिले सुवर्णपदक मिळवले आहे?\",\"options\":[\"धावणे\",\"गोळाफेक\",\"भालाफेक\",\"कुस्ती\"],\"answer\":2,\"explain\":\"चित्रात नीरज चोप्रा दिसत आहेत, जे एक प्रसिद्ध भालाफेक पटू आहेत.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"22\\/062_101.jpg\"},{\"q\":\"जर १ हस्त म्हणजे २४ अंगुल असेल, तर २ हस्त म्हणजे किती अंगुल होतील?\",\"options\":[\"१२ अंगुल\",\"४८ अंगुल\",\"३६ अंगुल\",\"२४ अंगुल\"],\"answer\":1,\"explain\":\"१ हस्त = २४ अंगुल, म्हणून २ हस्त = २४ x २ = ४८ अंगुल.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"प्राचीन मापन पद्धतीनुसार, १ योजन पूर्ण करण्यासाठी किती क्रोष अंतर पार करावे लागेल?\",\"options\":[\"४ क्रोष\",\"२००० क्रोष\",\"८ क्रोष\",\"२४ क्रोष\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार ४ क्रोष = १ योजन असे दिले आहे.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"१ क्रोष म्हणजे २००० दंड असल्यास, ८००० दंड म्हणजे किती क्रोष होतील?\",\"options\":[\"२ क्रोष\",\"४ क्रोष\",\"६ क्रोष\",\"८ क्रोष\"],\"answer\":1,\"explain\":\"८००० ला २००० ने भागल्यास ४ उत्तर येते, म्हणजेच ४ क्रोष.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"नीरज चोप्रा यांना भारत सरकारने कोणत्या वर्षी \'पद्मश्री\' पुरस्काराने सन्मानित केले?\",\"options\":[\"२०२०\",\"२०२१\",\"२०२२\",\"१९९७\"],\"answer\":2,\"explain\":\"नीरज चोप्रा यांना २०२२ मध्ये पद्मश्री पुरस्कार देण्यात आला.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते विधान लांबी मोजण्याच्या संदर्भात अचूक आहे?\",\"options\":[\"वस्तू तिरपी धरल्यास तिची लांबी वाढते.\",\"वस्तू उभी धरल्यास तिची लांबी कमी होते.\",\"प्रमाणित एककामुळे वस्तूची लांबी कोणत्याही स्थितीत सारखीच भरते.\",\"प्राचीन काळात लांबी मोजण्यासाठी मीटर वापरत असत.\"],\"answer\":2,\"explain\":\"प्रमाणित एककाचा वापर केल्यामुळे वस्तूची स्थिती बदलली तरी मोजमाप बदलत नाही.\",\"topic\":\"लांबी मोजण्याचे विविध पैलू\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"मीराबाई चानू या कोणत्या खेळाशी संबंधित खेळाडू आहेत?\",\"options\":[\"धावणे\",\"भारोत्तोलन (Weight lifting)\",\"कुस्ती\",\"क्रिकेट\"],\"answer\":1,\"explain\":\"मजकुरात मीराबाई चानू यांचा उल्लेख भारतीय भारोत्तोलक खेळाडू असा केला आहे.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मीराबाई चानू यांचा जन्म कोठे झाला?\",\"options\":[\"पूर्व इंफाळ, मणिपूर\",\"मुंबई, महाराष्ट्र\",\"दिल्ली\",\"पुणे\"],\"answer\":0,\"explain\":\"मजकुराप्रमाणे मीराबाई चानू यांचा जन्म पूर्व इंफाळ, मणिपूर येथे झाला.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"२०२० च्या टोकियो ऑलिंपिकमध्ये मीराबाई चानू यांनी एकूण किती वजन उचलले?\",\"options\":[\"४९ किलो\",\"१०० किलो\",\"२०२ किलो\",\"२०१८ किलो\"],\"answer\":2,\"explain\":\"मीराबाई चानू यांनी टोकियो ऑलिंपिकमध्ये एकूण २०२ किलो वजन उचलून रौप्य पदक जिंकले.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मजकुरातील सूत्रानुसार, २ किलोग्रॅमचे वजन करण्यासाठी १ किलोग्रॅमच्या मापासोबत ५०० ग्रॅमची किती मापे लागतील?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"१ किलोग्रॅम + ५०० ग्रॅम + ५०० ग्रॅम = २ किलोग्रॅम, म्हणजेच ५०० ग्रॅमची २ मापे लागतील.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"३ किलोग्रॅम पोहे मोजण्यासाठी १ किलोग्रॅमची किती मापे वापरावी लागतील?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":2,\"explain\":\"१ किलोग्रॅम + १ किलोग्रॅम + १ किलोग्रॅम = ३ किलोग्रॅम, म्हणून ३ मापे लागतील.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"जर एका पारड्यात २ किलोग्रॅमचे एक माप आणि १ किलोग्रॅमचे एक माप असेल, तर पारडे समतोल करण्यासाठी दुसऱ्या पारड्यात किती किलो वस्तू असावी?\",\"options\":[\"१ किलोग्रॅम\",\"२ किलोग्रॅम\",\"३ किलोग्रॅम\",\"४ किलोग्रॅम\"],\"answer\":2,\"explain\":\"२ किलोग्रॅम + १ किलोग्रॅम = ३ किलोग्रॅम, म्हणून ३ किलो वस्तू लागेल.\",\"topic\":\"वजन - समजून घ्या\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मीराबाई चानू यांना २०१८ मध्ये भारत सरकारने कोणत्या नागरी पुरस्काराने सन्मानित केले?\",\"options\":[\"