\":5,\"bloom\":\"analyze\"},{\"q\":\"सभागृहातील २७० खुर्च्यांची मांडणी खालीलपैकी कोणत्या प्रकारे केल्यास एकूण संख्या बदलणार नाही?\",\"options\":[\"२० रांगा आणि १० खुर्च्या\",\"२७ रांगा आणि १० खुर्च्या\",\"१५ रांगा आणि १५ खुर्च्या\",\"१८ रांगा आणि १० खुर्च्या\"],\"answer\":1,\"explain\":\"२७ x १० = २७०, त्यामुळे ही मांडणी केल्यास खुर्च्यांची एकूण संख्या तीच राहील.\",\"topic\":\"कृती आणि करून पाहा\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जमा पावती भरताना \'नाणी\\/नोटांची संख्या\' या रकान्यात काय लिहिणे अपेक्षित आहे?\",\"options\":[\"एकूण रक्कम लिहिण्यासाठी\",\"नोटांची किंमत लिहिण्यासाठी\",\"नोटा किंवा नाण्यांची मोजलेली संख्या लिहिण्यासाठी\",\"बँकेचे नाव लिहिण्यासाठी\"],\"answer\":2,\"explain\":\"या रकान्यात प्रत्येक मूल्याच्या किती नोटा किंवा नाणी आहेत ती संख्या लिहायची असते.\",\"topic\":\"कृती आणि करून पाहा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"बालआनंद मेळाव्यात ओंकारने कोणत्या पदार्थाची विक्री केली?\",\"options\":[\"वडापाव\",\"भेळ\",\"चहा\",\"बिस्किटे\"],\"answer\":1,\"explain\":\"मजकुराच्या पहिल्या ओळीतच ओंकारला भेळ विक्रीतून पैसे मिळाल्याचा उल्लेख आहे.\",\"topic\":\"कृती आणि करून पाहा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"१६ व्या शतकातील थोर भारतीय गणितज्ञ कोण होते?\",\"options\":[\"आर्यभट्ट\",\"गणेश देवज्ञ\",\"भास्कराचार्य\",\"वराहमिहिर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार गणेश देवज्ञ हे १६ व्या शतकातील थोर भारतीय गणितज्ञ होते.\",\"topic\":\"भारतीय ज्ञानप्रणाली\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"गणेश देवज्ञ यांनी गुणाकार करण्याची कोणती पद्धत सांगितली आहे?\",\"options\":[\"उभी मांडणी\",\"आडवी मांडणी\",\"कपटसंधि पद्धत\",\"वेदिक पद्धत\"],\"answer\":2,\"explain\":\"गणेश देवज्ञ यांच्या गुणाकार करण्याच्या पद्धतीला \'कपटसंधि\' पद्धत म्हणतात.\",\"topic\":\"भारतीय ज्ञानप्रणाली\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कपटसंधि पद्धत कोणत्या पद्धतीसारखी आहे?\",\"options\":[\"चौकट पद्धत\",\"भागाकार पद्धत\",\"बेरीज पद्धत\",\"वजाबाकी पद्धत\"],\"answer\":0,\"explain\":\"कपटसंधि पद्धतीत आपण चौकट पद्धतीत जसा गुणाकार करतो त्याप्रमाणे