 ५ मिली औषध दिवसातून दोन वेळा घ्यायला सांगितले, तर ती एका दिवसात एकूण किती मिली औषध घेते?\",\"options\":[\"५ मिली\",\"१० मिली\",\"१५ मिली\",\"२० मिली\"],\"answer\":1,\"explain\":\"५ मिली औषध दोन वेळा म्हणजे ५ + ५ = १० मिली.\",\"topic\":\"मापनाच्या एककाचे रूपांतर\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"१००० मिली आणि २५० मिली ही बेरीज खालीलपैकी कोणत्या मापनाचे रूपांतर आहे?\",\"options\":[\"दीड लीटर\",\"सव्वा लीटर\",\"पाऊण लीटर\",\"पावणेदोन लीटर\"],\"answer\":1,\"explain\":\"१००० मिली (१ लीटर) आणि २५० मिली (पाव लीटर) म्हणजे सव्वा लीटर.\",\"topic\":\"मापनाच्या एककाचे रूपांतर\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"१ लीटर म्हणजे किती मिलीलीटर?\",\"options\":[\"१०० मिलीलीटर\",\"५०० मिलीलीटर\",\"१००० मिलीलीटर\",\"२००० मिलीलीटर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार १ लीटर = १००० मिलीलीटर असते.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"५००० मिलीलीटर म्हणजे किती लीटर?\",\"options\":[\"५ लीटर\",\"५० लीटर\",\"५०० लीटर\",\"५००० लीटर\"],\"answer\":0,\"explain\":\"१००० मिली = १ लीटर, म्हणून ५००० मिली = ५ लीटर.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"३ लीटर = ३ x १००० मिली = किती मिलीलीटर?\",\"options\":[\"३०० मिली\",\"३००० मिली\",\"३० मिली\",\"३ मिली\"],\"answer\":1,\"explain\":\"लीटरचे मिलीलीटरमध्ये रूपांतर करण्यासाठी १००० ने गुणतात, म्हणून ३ x १००० = ३००० मिली.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत, पसरट भांड्यातील पाण्याचे आकारमान किती दाखवले आहे?\",\"options\":[\"१०० मिली\",\"२०० मिली\",\"३०० मिली\",\"४०० मिली\"],\"answer\":1,\"explain\":\"आकृतीमध्ये पसरट भांड्यावर \'२०० मिली\' असे स्पष्टपणे लिहिलेले आहे.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"22\\/118_101.jpg\"},{\"q\":\"दिलेल्या आकृतीवरून, भांडे बदलले तरी द्रवाच्या कशात बदल होत नाही असे समजते?\",\"options\":[\"रंग\",\"आकारमान\",\"उंची\",\"रुंदी\"],\"answer\":1,\"explain\":\"भांडे बदलले तरी द्रवाचे आकारमान बदलत नाही, हे आकृतीतील तिन्ही भांड्यांच्या २०० मिली या मापावरून सिद्ध होते.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"evaluate\",\"figure_image\":\"22\\/118_101.jpg\"},{\"q\":\"८००० मिली म्हणजे किती लीटर?\",\"options\":[\"८० लीटर\",\"८०० लीटर\",\"८ लीटर\",\"८० मिली\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील मिलीलीटरचे लीटरमध्ये रूपांतर करण्याच्या नियमानुसार ८००० मिली = ८ लीटर.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"३४५० मिली म्हणजे किती लीटर आणि किती मिली?\",\"options\":[\"३४ लीटर ५० मिली\",\"३ लीटर ४५० मिली\",\"३४५ लीटर ० मिली\",\"३० लीटर ४५० मिली\"],\"answer\":1,\"explain\":\"३४५० मिली = ३००० मिली + ४५० मिली = ३ लीटर + ४५० मिली.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"४ लीटर = ४ x ______ मिली = ४००० मिली. रिकाम्या जागी काय येईल?\",\"options\":[\"१००\",\"५००\",\"१०\",\"१०००\"],\"answer\":3,\"explain\":\"लीटरचे मिलीमध्ये रूपांतर करताना १००० ने गुणले जाते.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"१००० मिलीलीटर = १ लीटर, तर ४००० मिली = किती लीटर?\",\"options\":[\"२ लीटर\",\"४ लीटर\",\"४० लीटर\",\"४०० लीटर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील उदाहरणाप्रमाणे ४००० मिली = ४ लीटर.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"काचेच्या पसरट भांड्यातील पाणी उंच भांड्यात ओतले, तर पाण्याचे आकारमान काय होईल?\",\"options\":[\"वाढेल\",\"कमी होईल\",\"सारखेच राहील\",\"दुप्पट होईल\"],\"answer\":2,\"explain\":\"भांडे बदलले तरी द्रवाचे आकारमान बदलत नाही, ते सारखेच राहते.\",\"topic\":\"कृती करा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"पहिल्या उदाहरणात ५ लीटर धारकतेची किती भांडी उपलब्ध आहेत?\",\"options\":[\"दोन\",\"एक\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"पाठातील मजकुरानुसार बागेत ५ लीटर धारकतेचे एकच भांडे आहे.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"दुसऱ्या उदाहरणात पंपामध्ये एकूण किती लीटर खाद्यतेल भरलेले आहे?\",\"options\":[\"१० लीटर\",\"५ लीटर\",\"१५ लीटर\",\"१२ लीटर\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट दिले आहे की एक पंप १५ लीटर खाद्यतेलाने भरलेला आहे.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दुसऱ्या उदाहरणात एका डब्यात ५ लीटर तेल भरण्यासाठी २ लीटर आणि १ लीटरच्या मापांचा वापर कमीतकमी किती वेळा करावा लागेल?\",\"options\":[\"२ वेळा\",\"३ वेळा\",\"५ वेळा\",\"४ वेळा\"],\"answer\":1,\"explain\":\"५ लीटरसाठी २ लीटरचे माप २ वेळा (४ लीटर) आणि १ लीटरचे माप १ वेळा असे एकूण ३ वेळा माप वापरावे लागेल.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"पहिल्या उदाहरणात ५ लीटरच्या पूर्ण भरलेल्या भांड्यातून ३ लीटरचे भांडे पूर्ण भरून पाणी काढल्यास, ५ लीटरच्या भांड्यात किती पाणी शिल्लक राहील?\",\"options\":[\"१ लीटर\",\"३ लीटर\",\"२ लीटर\",\"४ लीटर\"],\"answer\":2,\"explain\":\"५ - ३ = २, म्हणून ५ लीटरच्या भांड्यात २ लीटर पाणी शिल्लक राहील.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"तिसऱ्या उदाहरणात दूध विक्रेत्याकडे असलेल्या रिकाम्या भांड्यांची धारकता किती आहे?\",\"options\":[\"२, ४ आणि ६ लीटर\",\"३, ५ आणि ७ लीटर\",\"१, २ आणि ५ लीटर\",\"४, ४ आणि ४ लीटर\"],\"answer\":1,\"explain\":\"मजकुरानुसार दूध विक्रेत्याकडे ३ लीटर, ५ लीटर आणि ७ लीटर धारकतेची रिकामी भांडी आहेत.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"तिसऱ्या उदाहरणात १२ लीटर दुधाचे ३ जणांना समान वाटप केल्यास प्रत्येकाला किती दूध मिळेल?\",\"options\":[\"३ लीटर\",\"५ लीटर\",\"४ लीटर\",\"६ लीटर\"],\"answer\":2,\"explain\":\"१२ लीटर दुधाचे ३ समान भाग केल्यास प्रत्येकाला ४ लीटर दूध मिळते.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दुसऱ्या उदाहरणात १५ लीटर तेल ३ डब्यांत समान भरायचे असल्यास, प्रत्येक डब्यात किती तेल भरावे लागेल?\",\"options\":[\"३ लीटर\",\"५ लीटर\",\"७ लीटर\",\"२ लीटर\"],\"answer\":1,\"explain\":\"१५ लीटर तेल ३ डब्यांत समान भरल्यास प्रत्येक डब्यात ५ लीटर तेल येते.\",\"topic\":\"गणित गंमत\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"तिसऱ्या उदाहरणात तिघांना प्रत्येकी ४ लीटर दूध दिल्यास एकूण किती दूध वाटले जाईल?\",\"options\":[\"१० लीटर\",\"१२ लीटर\",\"१५ लीटर\",\"८ लीटर\"],\"answer\":1,\"explain\":\"४ + ४ + ४ = १२, म्हणजेच एकूण १२ लीटर दूध वाट