:\"apply\"},{\"q\":\"सूर्यापासूनच्या अंतराच्या चढत्या क्रमाने (जवळून लांब) कोणता गट योग्य आहे?\",\"options\":[\"बुध-शुक्र-पृथ्वी\",\"पृथ्वी-बुध-शुक्र\",\"शुक्र-बुध-पृथ्वी\",\"बुध-पृथ्वी-शुक्र\"],\"answer\":0,\"explain\":\"सूर्यापासून ग्रहांचा योग्य क्रम बुध, शुक्र, पृथ्वी असा आहे.\",\"topic\":\"सांग पाहू !\",\"part\":15,\"bloom\":\"analyze\"},{\"q\":\"जर आपण सूर्यापासून लांब जात असू, तर गुरु ग्रहाच्या नंतर लगेच कोणता ग्रह येईल?\",\"options\":[\"मंगळ\",\"शनी\",\"युरेनस\",\"नेपच्यून\"],\"answer\":1,\"explain\":\"सूर्यमालेच्या क्रमानुसार गुरु ग्रहाच्या बाहेरची कक्षा शनी ग्रहाची आहे.\",\"topic\":\"सांग पाहू !\",\"part\":15,\"bloom\":\"apply\"},{\"q\":\"सूर्यमालेच्या चित्रात पृथ्वीच्या दोन्ही बाजूंना असणारे शेजारील ग्रह कोणते?\",\"options\":[\"बुध आणि शुक्र\",\"शुक्र आणि मंगळ\",\"मंगळ आणि गुरु\",\"गुरु आणि शनी\"],\"answer\":1,\"explain\":\"पृथ्वी ही शुक्र आणि मंगळ या दोन ग्रहांच्या मध्ये स्थित आहे.\",\"topic\":\"सांग पाहू !\",\"part\":15,\"bloom\":\"analyze\"},{\"q\":\"सूर्यमालेच्या आकृतीचे निरीक्षण केल्यास, क्रमाने पाचव्या स्थानावर कोणता ग्रह येतो?\",\"options\":[\"मंगळ\",\"गुरु\",\"शनी\",\"युरेनस\"],\"answer\":1,\"explain\":\"बुध(१), शुक्र(२), पृथ्वी(३), मंगळ(४) आणि गुरु(५) असा ग्रहांचा क्रम आहे.\",\"topic\":\"सांग पाहू !\",\"part\":15,\"bloom\":\"understand\"},{\"q\":\"खगोलीय वस्तूंमध्ये एकमेकांना स्वतःकडे खेचण्याच्या शक्तीला काय म्हणतात?\",\"options\":[\"चुंबकीय शक्ती\",\"गुरुत्वाकर्षण शक्ती\",\"घर्षण शक्ती\",\"स्नायू शक्ती\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, खगोलीय वस्तूंमधील आकर्षित करण्याच्या शक्तीला गुरुत्वाकर्षण शक्ती म्हणतात.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"remember\"},{\"q\":\"खगोलीय वस्तू एकमेकांना काय करतात?\",\"options\":[\"ढकलतात\",\"आकर्षित करतात\",\"थांबवतात\",\"लांब फेकतात\"],\"answer\":1,\"explain\":\"खगोलीय वस्तूंमध्ये एकमेकांना स्वतःकडे खेचण्याची म्हणजेच आकर्षित करण्याची शक्ती असते.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"remember\"},{\"q\":\"ग्रह सूर्याभोवती ठराविक कक्षेत कशामुळे परिभ्रमण करतात?\",\"options\":[\"फक्त सूर्याच्या गुरुत्वाकर्षणामुळे\",\"फक्त ग्रहांच्या वेगामुळे\",\"गुरुत्वाकर्षण आणि दूर जाण्याची प्रवृत्ती यांच्या एकत्रित परिणामामुळे\",\"चंद्राच्या आकर्षणामुळे\"],\"answer\":2,\"explain\":\"सूर्याचे गुरुत्वाकर्षण आणि ग्रहांची दूर जाण्याची प्रवृत्ती यांच्या एकत्रित परिणामामुळे ग्रह कक्षेत राहतात.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"understand\"},{\"q\":\"ग्रहांची सूर्यापासून ______ जाण्याची प्रवृत्ती असते.\",\"options\":[\"जवळ\",\"दूर\",\"वेगाने\",\"खाली\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की ग्रहांची सूर्यापासून दूर जाण्याची प्रवृत्ती असते.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"remember\"},{\"q\":\"ग्रहांच्या सूर्याभोवती फिरण्याच्या मार्गाला काय म्हणतात?\",\"options\":[\"रेषा\",\"वर्तुळ\",\"कक्षा\",\"रस्ता\"],\"answer\":2,\"explain\":\"ग्रह सूर्याभोवती ज्या ठराविक मार्गावरून फिरतात, त्याला \'कक्षा\' असे म्हणतात.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"understand\"},{\"q\":\"उपग्रह कोणाभोवती परिभ्रमण करतात?\",\"options\":[\"सूर्याभोवती\",\"ताऱ्यांभोवती\",\"ग्रहांभोवती\",\"अवकाशाभोवती\"],\"answer\":2,\"explain\":\"ज्याप्रमाणे ग्रह सूर्याभोवती फिरतात, त्याच पद्धतीने उपग्रह ग्रहांभोवती परिभ्रमण करतात.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"understand\"},{\"q\":\"सूर्याची गुरुत्वाकर्षण शक्ती कोणावर कार्य करते?\",\"options\":[\"फक्त पृथ्वीवर\",\"ग्रहांवर\",\"फक्त चंद्रावर\",\"कशावरही नाही\"],\"answer\":1,\"explain\":\"मजकुरानुसार सूर्याची गुरुत्वाकर्षण शक्ती ग्रहांवर कार्य करते.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"apply\"},{\"q\":\"जर सूर्याची गुरुत्वाकर्षण शक्ती नसेल, तर ग्रहांच्या \'दूर जाण्याच्या प्रवृत्ती\'मुळे काय होईल?\",\"options\":[\"ग्रह स्थिर राहतील\",\"ग्रह सूर्याजवळ येतील\",\"ग्रह सूर्यापासून लांब जातील\",\"ग्रह नष्ट होतील\"],\"answer\":2,\"explain\":\"गुरुत्वाकर्षण शक्ती नसेल तर ग्रहांची दूर जाण्याची प्रवृत्ती त्यांना सूर्यापासून लांब नेईल.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"analyze\"},{\"q\":\"मजकुरावरून, उपग्रहांच्या परिभ्रमणाचे तत्व कोणासारखेच आहे?\",\"options\":[\"ग्रहांच्या सूर्याभोवती फिरण्यासारखे\",\"ताऱ्यांच्या फिरण्यासारखे\",\"ढगांच्या फिरण्यासारखे\",\"मानवाच्या चालण्यासारखे\"],\"answer\":0,\"explain\":\"मजकुरात म्हटले आहे की \'याच पद्धतीने\' (ग्रहांच्या पद्धतीप्रमाणे) उपग्रह परिभ्रमण करतात.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"analyze\"},{\"q\":\"ग्रहांच्या हालचालीसाठी \'ठराविक अंतर\' आणि \'ठराविक कक्षा\' राखण्यासाठी काय आवश्यक आहे?\",\"options\":[\"शक्तींचा एकत्रित परिणाम\",\"ग्रहांचा मोठा आकार\",\"सूर्याचा प्रकाश\",\"ताऱ्यांची संख्या\"],\"answer\":0,\"explain\":\"गुरुत्वाकर्षण आणि दूर जाण्याची प्रवृत्ती या दोन शक्तींच्या एकत्रित परिणामामुळे अंतर आणि कक्षा ठरते.\",\"topic\":\"गुरुत्वाकर्षण\",\"part\":16,\"bloom\":\"apply\"},{\"q\":\"ग्रह आणि तारे यांच्या दरम्यान असणाऱ्या रिकाम्या जागेला काय म्हणतात?\",\"options\":[\"जमीन\",\"डोंगर\",\"अवकाश\",\"पाऊस\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, ग्रह आणि तारे यांच्या दरम्यान असणारी रिकामी जागा म्हणजे अवकाश होय.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या कोणत्या शक्तीमुळे पृथ्वीवरील सर्व वस्तू पृथ्वीवरच राहतात?\",\"options\":[\"चुंबकीय शक्ती\",\"गुरुत्वाकर्षण\",\"विद्युत शक्ती\",\"स्नायू शक्ती\"],\"answer\":1,\"explain\":\"पृथ्वीच्या गुरुत्वाकर्षणामुळे पृथ्वीवरील सर्व वस्तू पृथ्वीवरच राहतात असे मजकुरात नमूद केले आहे.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"remember\"},{\"q\":\"\'अवकाश\' या शब्दासाठी उताऱ्यात कोणता दुसरा शब्द वापरला आहे?\",\"options\":[\"पाताळ\",\"आकाश\",\"अंतराळ\",\"क्षितिज\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे दिले आहे की अवकाशालाच \'अंतराळ\' असेही म्हणतात.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"remember\"},{\"q\":\"झाडावरून गळलेली पाने, फुले आणि फळे कोणत्या दिशेने पडतात?\",\"options\":[\"वरच्या दिशेने\",\"बाजूच्या दिशेने\",\"पृथ्वीच्या दिशेने (खाली)\",\"आकाशाच्या दिशेने\"],\"answer\":2,\"explain\":\"गुरुत्वाकर्षणामुळे झाडावरून गळणाऱ्या वस्तू जमिनीवर म्हणजेच पृथ्वीच्या दिशेने पडतात.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"understand\"},{\"q\":\"आकाशातून येणारा पाऊस जमिनीवरच का पडतो?\",\"options\":[\"पृथ्वीच्या गुरुत्वाकर्षणामुळे\",\"वाऱ्याच्या वेगामुळे\",\"ढगांच्या गडगडाटामुळे\",\"सूर्याच्या प्रकाशामुळे\"],\"answer\":0,\"explain\":\"पृथ्वीच्या गुरुत्वाकर्षणामुळे आकाशातून येणारा पाऊस जमिनीवरच येतो.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"understand\"},{\"q\":\"डोंगरावरून सुटे झालेले खडक खाली पडण्याचे कारण काय असावे?\",\"options\":[\"खडकांचा रंग\",\"पृथ्वीचे गुरुत्वाकर्षण\",\"डोंगराची उंची\",\"खडकांचा आकार\"],\"answer\":1,\"explain\":\"उताऱ्यात दिलेल्या माहितीनुसार, सर्व वस्तू पृथ्वीवर पडण्याचे कारण पृथ्वीचे गुरुत्वाकर्षण आहे.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही एखादा चेंडू जोरात वर फेकला, तर शेवटी काय होईल?\",\"options\":[\"तो अवकाशातच राहील\",\"तो ढगांमध्ये अडकेल\",\"तो जमिनीवरच येऊन पडेल\",\"तो हवेत तरंगत राहील\"],\"answer\":2,\"explain\":\"मजकुरात म्हटले आहे की, एखादी वस्तू जोरात वर फेकली की ती शेवटी जमिनीवरच येऊन पडते.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या ठिकाणी \'अवकाश\' ही संकल्पना लागू होते?\",\"options\":[\"दोन झाडांमधील अंतर\",\"दोन डोंगरांमधील दरी\",\"दोन ग्रहांमधील रिकामी जागा\",\"दोन घरांच्या मधील रस्ता\"],\"answer\":2,\"explain\":\"ग्रह आणि तारे यांच्या दरम्यान असणाऱ्या रिकाम्या जागेला अवकाश म्हणतात.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीच्या गुरुत्वाकर्षणाचा परिणाम खालीलपैकी कोणत्या गोष्टीवर होत नाही असे उताऱ्यावरून वाटते?\",\"options\":[\"झाडावरून पडणारी फळे\",\"आकाशातून येणारा पाऊस\",\"डोंगरावरून पडणारे खडक\",\"ग्रहांमधील रिकामी जागा\"],\"answer\":3,\"explain\":\"ग्रहांमधील रिकामी जागा म्हणजे अवकाश, तर गुरुत्वाकर्षण वस्तूंना पृथ्वीकडे खेचते.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"analyze\"},{\"q\":\"गुरुत्वाकर्षण ही शक्ती नसती तर काय झाले असते?\",\"options\":[\"वस्तू जमिनीवर पडल्या असत्या\",\"वस्तू पृथ्वीवरच राहिल्या असत्या\",\"वस्तू पृथ्वीवर स्थिर राहिल्या नसत्या\",\"पाऊस जमिनीवर पडला असता\"],\"answer\":2,\"explain\":\"गुरुत्वाकर्षणामुळे वस्तू पृथ्वीवर राहतात, ती नसल्यास त्या स्थिर राहू शकणार नाहीत.\",\"topic\":\"नवीन शब्द शिका\",\"part\":18,\"bloom\":\"evaluate\"},{\"q\":\"\'इस्रो\' (I.S.R.O.) या संस्थेचे पूर्ण नाव काय आहे?\",\"options\":[\"भारतीय अवकाश संशोधन संस्था\",\"भारतीय विज्ञान संस्था\",\"भारतीय ग्रह संशोधन संस्था\",\"भारतीय तंत्रज्ञान संस्था\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार I.S.R.O. म्हणजे \'भारतीय अवकाश संशोधन संस्था\' (Indian Space Research Organization) होय.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"remember\"},{\"q\":\"भारताने \'चंद्रयान-१\' ही मोहीम कोणत्या तारखेला राबवली?\",\"options\":[\"१५ ऑगस्ट १९४७\",\"२२ ऑक्टोबर २००८\",\"५ नोव्हेंबर २०१३\",\"२४ सप्टेंबर २०१४\"],\"answer\":1,\"explain\":\"इस्रोने २२ ऑक्टोबर २००८ रोजी चंद्रयान सोडले होते, ज्याला \'चंद्रयान-१\' म्हणून ओळखले जाते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीवरून एखादी वस्तू अवकाशात पाठवण्यासाठी तिला कशाच्या विरुद्ध शक्ती द्यावी लागते?\",\"options\":[\"हवेचा दाब\",\"पृथ्वीचे गुरुत्वाकर्षण\",\"सूर्याचा प्रकाश\",\"चंद्राचे आकर्षण\"],\"answer\":1,\"explain\":\"पृथ्वीच्या गुरुत्वाकर्षणामुळे वस्तू खाली खेचली जाते, म्हणून अवकाशात जाण्यासाठी त्याविरुद्ध शक्ती द्यावी लागते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"understand\"},{\"q\":\"भारतीय अवकाश मोहिमेतील \'मॉम\' (M.O.M.) हे नाव कोणत्या उपक्रमासाठी प्रसिद्ध आहे?\",\"options\":[\"चंद्रयान\",\"सूर्ययान\",\"मंगलयान\",\"पृथ्वीयान\"],\"answer\":2,\"explain\":\"मंगलयान हा उपक्रम \'मॉम\' (Mars Orbit Mission) या नावाने प्रसिद्ध आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"remember\"},{\"q\":\"मंगलयान मंगळ ग्रहाच्या दिशेने ५ नोव्हेंबर २०१३ रोजी झेपावले, तर ते मंगळाच्या कक्षेत कधी प्रस्थापित झाले?\",\"options\":[\"२२ ऑक्टोबर २००८\",\"१ जानेवारी २०१४\",\"२४ सप्टेंबर २०१४\",\"५ नोव्हेंबर २०१४\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे मंगलयान २४ सप्टेंबर २०१४ रोजी मंगळ ग्रहाभोवतीच्या कक्षेत प्रस्थापित झाले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"apply\"},{\"q\":\"भारताची चंद्रयान आणि मंगलयान ही दोन्ही याने कोणत्या प्रकारची आहेत?\",\"options\":[\"मानवासहित\",\"मानवरहित\",\"फक्त प्राण्यांसाठी\",\"पर्यटनासाठी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात स्पष्ट नमूद केले आहे की भारताची ही दोन्ही याने \'मानवरहित\' आहेत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीच्या गुरुत्वाकर्षणाविरुद्ध शक्ती देऊन वस्तू अवकाशात पाठवण्याच्या तंत्रास काय म्हणतात?\",\"options\":[\"विमान तंत्रज्ञान\",\"अवकाश प्रक्षेपण तंत्र\",\"गुरुत्वाकर्षण तंत्र\",\"ग्रहांचे तंत्र\"],\"answer\":1,\"explain\":\"अवकाशात वस्तू पाठवण्यासाठी वापरल्या जाणाऱ्या तंत्रास \'अवकाश प्रक्षेपण तंत्र\' म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"understand\"},{\"q\":\"मंगलयानाचा प्रवास ५ नोव्हेंबर २०१३ ला सुरू होऊन २४ सप्टेंबर २०१४ ला पूर्ण झाला. या प्रवासाला अंदाजे किती महिने लागले असतील?\",\"options\":[\"२ महिने\",\"५ महिने\",\"१० महिन्यांपेक्षा जास्त\",\"२४ महिने\"],\"answer\":2,\"explain\":\"नोव्हेंबर २०१३ ते सप्टेंबर २०१४ हा कालावधी साधारण १० महिन्यांपेक्षा जास्त आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"apply\"},{\"q\":\"इस्रोने मंगलयान मोहिमेबाबत कोणते विशेष यश संपादन केले आहे?\",\"options\":[\"सर्वात मोठे यान बनवले\",\"पहिल्याच प्रयत्नात यश प्राप्त केले\",\"चंद्रावर पाणी शोधले\",\"सूर्याजवळ यान पाठवले\"],\"answer\":1,\"explain\":\"इस्रोने मंगलयान मोहिमेत पहिल्याच प्रयत्नात यश प्राप्त केले आहे, हे भारताचे मोठे यश आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रात भारतीय अवकाश मोहिमेतील कोणते यान दिसत आहे?\",\"options\":[\"मंगलयान\",\"चंद्रयान\",\"सूर्ययान\",\"रॉकेट\"],\"answer\":1,\"explain\":\"चित्राखालील मजकुराप्रमाणे हे \'चंद्रयान\' आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"remember\",\"figure_image\":\"24\\/013_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील यान कोणत्या ग्रहाच्या सखोल अभ्यासासाठी पाठवण्यात आले आहे?\",\"options\":[\"चंद्र\",\"मंगळ\",\"पृथ्वी\",\"गुरु\"],\"answer\":1,\"explain\":\"हे मंगलयानाचे चित्र असून ते मंगळ ग्रहाच्या अभ्यासासाठी पाठवले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"understand\",\"figure_image\":\"24\\/013_102.jpg\"},{\"q\":\"दिलेल्या चित्रात मंगलयानाने कोणत्या भागाचे छायाचित्र टिपले आहे?\",\"options\":[\"चंद्राचा पृष्ठभाग\",\"भारतीय प्रदेश\",\"अमेरिकन प्रदेश\",\"मंगळाचे मैदान\"],\"answer\":1,\"explain\":\"हे चित्र मंगलयानाने काढलेले \'भारतीय प्रदेशाचे\' छायाचित्र आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":20,\"bloom\":\"analyze\",\"figure_image\":\"24\\/013_103.jpg\"},{\"q\":\"काही मोहिमांमध्ये वैज्ञानिकसुद्धा अवकाशयानातून जातात, त्यांना काय म्हणतात?\",\"options\":[\"विमानचालक\",\"अंतराळवीर\",\"खगोलशास्त्रज्ञ\",\"संशोधक\"],\"answer\":1,\"explain\":\"मजकुरामध्ये स्पष्टपणे नमूद केले आहे की अवकाशयानातून जाणाऱ्या वैज्ञानिकांना अंतराळवीर म्हणतात.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"जगातील काही देशांनी अवकाश प्रक्षेपण तंत्रज्ञान कोणत्या शतकात विकसित केले?\",\"options\":[\"एकोणिसाव्या शतकात\",\"एकविसाव्या शतकात\",\"विसाव्या शतकात\",\"अठराव्या शतकात\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, विसाव्या शतकात जगातील काही देशांनी अवकाश प्रक्षेपण तंत्रज्ञान विकसित केले.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"दिवाळीच्या रॉकेट फटाक्यामध्ये कोणते पदार्थ ठासून भरलेले असतात?\",\"options\":[\"रंगीत खडे\",\"विस्फोटक पदार्थ\",\"लोखंडी कण\",\"केवळ हवा\"],\"answer\":1,\"explain\":\"दिवाळीच्या रॉकेट फटाक्यामध्ये विस्फोटक पदार्थ ठासून भरलेले असतात.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"अवकाशयानाचे अवकाश प्रक्षेपण करण्यासाठी कशाचा उपयोग करतात?\",\"options\":[\"विमानाचा\",\"शक्तिशाली अग्निबाणाचा\",\"मोठ्या फुग्यांचा\",\"हेलिकॉप्टरचा\"],\"answer\":1,\"explain\":\"अवकाशयानाचे अवकाश प्रक्षेपण करण्यासाठी शक्तिशाली अग्निबाणाचा म्हणजेच रॉकेटचा उपयोग करतात.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"रॉकेटमध्ये प्रचंड प्रमाणावर इंधन का जाळले जाते?\",\"options\":[\"प्रकाश निर्माण करण्यासाठी\",\"हजारो टन वजनाचे अवकाशयान अंतराळात नेण्यासाठी\",\"फक्त उष्णता निर्माण करण्यासाठी\",\"रॉकेटचा रंग बदलण्यासाठी\"],\"answer\":1,\"explain\":\"हजारो टन वजनाचे अवकाशयान अंतराळात नेण्यासाठी रॉकेटमध्ये प्रचंड प्रमाणावर इंधन जाळले जाते.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"रॉकेट फटाका ठराविक दिशेने वेगाने का ढकलला जातो?\",\"options\":[\"त्याच्या वजनामुळे\",\"त्याच्या रचनेमुळे\",\"वाऱ्याच्या दिशेमुळे\",\"त्याच्या रंगा मुळे\"],\"answer\":1,\"explain\":\"रॉकेटच्या विशिष्ट रचनेमुळे फटाका ठराविक दिशेने वेगाने ढकलला जातो.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"अवकाश मोहिमांच्या बाबतीत खालीलपैकी कोणते विधान मजकुराच्या आधारे सत्य आहे?\",\"options\":[\"सर्व अवकाशयाने पृथ्वीवर परत येतात.\",\"सर्व अवकाशयाने दुसऱ्या ग्रहावर उतरतात.\",\"काही अवकाशयाने कायमची अंतराळातच राहतात.\",\"कोणतेही अवकाशयान पृथ्वीवर परत येत नाही.\"],\"answer\":2,\"explain\":\"मजकुरात सांगितले आहे की काही अवकाशयाने कायमची अंतराळातच राहतात.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"आपला देश कोणत्या तंत्रज्ञानाच्या विकासासाठी प्रसिद्ध आहे?\",\"options\":[\"फटाके बनवण्याच्या\",\"विमान निर्मितीच्या\",\"अवकाश प्रक्षेपण तंत्रज्ञानाच्या\",\"फक्त इंधन निर्मितीच्या\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे, आपला देश अवकाश प्रक्षेपण तंत्रज्ञानाच्या विकासात प्रसिद्ध आहे.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या अवकाशयानाला मंगळ ग्रहाचा अभ्यास करायचा असेल, तर मजकुरातील माहितीनुसार त्या यानाचे काय केले जाईल?\",\"options\":[\"ते यान पृथ्वीवरच ठेवले जाईल.\",\"ते यान दुसऱ्या ग्रहावर उतरवले जाईल.\",\"ते यान दिवाळीत वापरले जाईल.\",\"ते यान समुद्रात सोडले जाईल.\"],\"answer\":1,\"explain\":\"मजकुरात म्हटले आहे की काही अवकाशयाने दुसऱ्या ग्रहांवर किंवा उपग्रहांवर उतरवली जातात.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात दाखवल्याप्रमाणे, अग्निबाण अवकाशात झेपावताना खालच्या बाजूने काय बाहेर पडताना दिसत आहे?\",\"options\":[\"पाण्याचे कारंजे\",\"केवळ रंगीत हवा\",\"इंधनाच्या ज्वलनातून निर्माण झालेली ऊर्जा आणि धूर\",\"मोठे दगड\"],\"answer\":2,\"explain\":\"चित्रात अग्निबाणाच्या खालच्या भागातून इंधन जळल्यामुळे निर्माण झालेली ऊर्जा आणि धूर बाहेर पडताना दिसत आहे.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"apply\",\"figure_image\":\"24\\/014_101.jpg\"},{\"q\":\"दिलेल्या चित्रात कोणती प्रक्रिया दर्शवली आहे?\",\"options\":[\"विमान उड्डाण\",\"अवकाश प्रक्षेपण\",\"फटाके तयार करणे\",\"ग्रह निरीक्षण\"],\"answer\":1,\"explain\":\"चित्राखालील मजकुराप्रमाणे हे \'अग्निबाणाच्या साहाय्याने अवकाश प्रक्षेपण\' आहे.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"analyze\",\"figure_image\":\"24\\/014_101.jpg\"},{\"q\":\"दिवाळीचा रॉकेट फटाका आणि अंतराळात जाणारे रॉकेट यांच्यात कोणता मुख्य समान गुणधर्म मजकुरातून दिसून येतो?\",\"options\":[\"दोन्हीमध्ये वैज्ञानिक बसून जातात.\",\"दोन्हीमध्ये स्फोटक पदार्थ ठासून भरलेले असतात.\",\"दोन्हीमध्ये ज्वलनातून ऊर्जा निर्माण होऊन ते ठराविक दिशेने ढकलले जातात.\",\"दोन्ही नेहमी पृथ्वीवर परत येतात.\"],\"answer\":2,\"explain\":\"दोन्हीमध्ये इंधन\\/विस्फोटक जळून ऊर्जा निर्माण होते आणि रचनेमुळे ते ठराविक दिशेने ढकलले जातात हे मुख्य साम्य आहे.\",\"topic\":\"अवकाश प्रक्षेपण आणि रॉकेट\",\"part\":21,\"bloom\":\"analyze\"},{\"q\":\"अवकाशात जाणारे पहिले भारतीय अंतराळवीर कोण आहेत?\",\"options\":[\"नील आर्मस्ट्राँग\",\"राकेश शर्मा\",\"कल्पना चावला\",\"सुनिता विल्यम्स\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार राकेश शर्मा हे १९८४ साली अवकाशात जाणारे पहिले भारतीय अंतराळवीर होत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"राकेश शर्मा कोणत्या वर्षी अवकाशात गेले होते?\",\"options\":[\"१९७४\",\"१९९४\",\"१९८४\",\"२००४\"],\"answer\":2,\"explain\":\"राकेश शर्मा १९८४ साली अवकाशात गेले होते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"राकेश शर्मा यांनी अवकाशयानकात किती दिवस वास्तव्य केले?\",\"options\":[\"५ दिवस\",\"१० दिवस\",\"८ दिवस\",\"१५ दिवस\"],\"answer\":2,\"explain\":\"राकेश शर्मा यांनी अवकाशयानकात आठ दिवस वास्तव्य केले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"राकेश शर्मा यांची अंतराळ मोहीम कोणत्या दोन संस्थांचा संयुक्त उपक्रम होती?\",\"options\":[\"इस्रो व नासा\",\"इस्रो व सोव्हिएत इंटरकॉसमॉस\",\"नासा व सोव्हिएत इंटरकॉसमॉस\",\"इस्रो व युरोपियन स्पेस एजन्सी\"],\"answer\":1,\"explain\":\"ही मोहीम इस्रो व सोव्हिएत इंटरकॉसमॉस यांचा संयुक्त उपक्रम होती.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"राकेश शर्मा यांनी अवकाशातून भारताला कोणता संदेश पाठवला?\",\"options\":[\"जय हिंद\",\"सत्यमेव जयते\",\"सारे जहाँसे अच्छा, हिंदोस्ताँ हमारा\",\"वंदे मातरम्\"],\"answer\":2,\"explain\":\"त्यांनी भारताकडे पाहताना \'सारे जहाँसे अच्छा, हिंदोस्ताँ हमारा\' हा संदेश पाठवला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"राकेश शर्मा यांनी भारताचा संदेश कोठून पाठवला?\",\"options\":[\"चंद्रावरून\",\"अवकाशयानकातून\",\"विमानातून\",\"दुसऱ्या ग्रहावरून\"],\"answer\":1,\"explain\":\"राकेश शर्मा यांनी अवकाशयानकातून भारताकडे पाहताना संदेश पाठवला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या मजकुरानुसार, राकेश शर्मा यांच्या मोहिमेचे स्वरूप काय होते?\",\"options\":[\"वैयक्तिक मोहीम\",\"केवळ रशियाची मोहीम\",\"संयुक्त अंतराळ मोहीम\",\"केवळ अमेरिकेची मोहीम\"],\"answer\":2,\"explain\":\"मजकुरात या मोहिमेचा उल्लेख \'संयुक्त अंतराळ मोहीम\' असा केला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"जर राकेश शर्मा यांनी ८ दिवस वास्तव्य केले, तर त्यांनी किती काळ अवकाशयानकात घालवला?\",\"options\":[\"एक आठवडा\",\"एक आठवडा आणि एक दिवस\",\"दोन आठवडे\",\"पाच दिवस\"],\"answer\":1,\"explain\":\"८ दिवस म्हणजे एक आठवडा आणि एक दिवस (७+१) होय.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"apply\"},{\"q\":\"राकेश शर्मा यांनी \'सारे जहाँसे अच्छा\' हा संदेश पाठवण्यामागील कारण काय असावे?\",\"options\":[\"त्यांना अंतराळात भीती वाटत होती\",\"त्यांना अवकाशयान आवडले नव्हते\",\"अवकाशातून भारताकडे पाहताना त्यांना अभिमान वाटला\",\"त्यांना रशियाला संदेश द्यायचा होता\"],\"answer\":2,\"explain\":\"अवकाशातून भारताकडे पाहताना त्यांनी हा देशप्रेमाचा संदेश पाठवला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते विधान राकेश शर्मा यांच्याबद्दल सत्य आहे?\",\"options\":[\"ते अमेरिकेचे अंतराळवीर होते\",\"ते १९८४ मध्ये अवकाशात जाणारे पहिले भारतीय होते\",\"त्यांनी अवकाशात एक महिना वास्तव्य केले\",\"त्यांनी इस्रो सोडून इतर संस्थेत काम केले नाही\"],\"answer\":1,\"explain\":\"मजकुरानुसार ते १९८४ साली अवकाशात जाणारे पहिले भारतीय अंतराळवीर होते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":22,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21600,24,5,'EVS Part 1','mr','पृथ्वीचे फिरणे','[\"पृथ्वी स्वतःभोवती फिरते याला परिबलन म्हणतात.\",\"पृथ्वी सूर्याभोवती फिरते याला परिभ्रमण म्हणतात.\",\"परिबलनाचा अक्ष म्हणजे पृथ्वीचा कललेला अक्ष.\",\"विषुववृत्त हे पृथ्वीच्या पृष्ठभागावरचे वर्तुळ आहे ज्याने पृथ्वी दोन गोलार्धात विभागली जाते.\",\"विषुववृत्तावरून पृथ्वीचे उत्तर गोलार्ध आणि दक्षिण गोलार्ध बनतात.\",\"पृथ्वीच्या परिबलनामुळे दिन व रात्र होते.\",\"एक परिबलन पूर्ण होण्यासाठी २४ तास लागतात, याला एक दिवस म्हणतात.\",\"पृथ्वीच्या परिभ्रमणामुळे वर्ष पूर्ण होण्यासाठी ३६५ दिवस ६ तास लागतात.\",\"चंद्र पृथ्वीभोवती फिरतो आणि त्याच्या प्रकाशाच्या अवस्थांना अमावस्या, पौर्णिमा, शुक्लपक्ष, कृष्णपक्ष असे म्हणतात.\",\"चंद्राच्या प्रकाशाच्या अवस्थांना एक चांद्रमास म्हणतात ज्यात २८-३० दिवस असतात.\",\"लीप वर्षात फेब्रुवारीला २९ दिवस असतात ज्यामुळे वर्ष ३६६ दिवसांचे होते.\",\"पृथ्वीचा अक्ष कललेला असल्यामुळे सूर्योदय, मध्यान्ह आणि सूर्यास्त वेगवेगळ्या वेळांना होतात.\",\"उष्णता आणि अंधाराचे वेळ पृथ्वीच्या गोलार्धानुसार बदलतात.\",\"पृथ्वीच्या परिबलनामुळे पृथ्वीच्या पृष्ठभागावर दिन व रात्र यांचा चक्र तयार होतो.\",\"चंद्राच्या प्रकाशाच्या अवस्थांमध्ये उत्तर गोलार्धात उन्हाळा आणि दक्षिण गोलार्धात हिवाळा असतो.\"]','[{\"q\":\"वस्तूच्या स्वतःभोवती फिरण्याला काय म्हणतात?\",\"options\":[\"भ्रमण\",\"परिवलन\",\"प्रदक्षिणा\",\"आकर्षण\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे दिले आहे की वस्तूच्या स्वतःभोवती फिरण्याला \'परिवलन\' म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"वस्तू ज्या अदृश्य रेषेभोवती फिरते, तिला काय म्हणतात?\",\"options\":[\"कक्षा\",\"वर्तुळ\",\"अक्ष किंवा आस\",\"ओळंबा\"],\"answer\":2,\"explain\":\"वस्तू ज्या अदृश्य रेषेभोवती फिरते तिला त्या वस्तूच्या परिवलनाचा \'अक्ष\' किंवा \'आस\' म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीचा अक्ष कोणत्या स्थितीत असतो?\",\"options\":[\"सरळ\",\"आडवा\",\"कललेला\",\"वर्तुळाकार\"],\"answer\":2,\"explain\":\"ओळंबा आणि पृथ्वीचा अक्ष यांच्यातील कोनावरून समजते की पृथ्वीचा अक्ष कललेला आहे.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीच्या मध्याबिंदूतून जाणाऱ्या रेषेच्या टोकांना (N व S) काय म्हणतात?\",\"options\":[\"गोलार्ध\",\"विषुववृत्त\",\"ध्रुव\",\"अक्ष\"],\"answer\":2,\"explain\":\"पृथ्वीच्या अक्षावरील N व S या बिंदूंना पृथ्वीचे ध्रुव म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या पृष्ठभागावर उत्तर आणि दक्षिण ध्रुवांच्या मध्यावर काढलेल्या काल्पनिक वर्तुळाला काय म्हणतात?\",\"options\":[\"विषुववृत्त\",\"कर्कवृत्त\",\"मकरवृत्त\",\"अक्षवृत्त\"],\"answer\":0,\"explain\":\"उत्तर आणि दक्षिण ध्रुवांच्या मध्यावर काढलेल्या काल्पनिक वर्तुळाला \'विषुववृत्त\' म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"विषुववृत्तामुळे पृथ्वीचे कोणते दोन समान भाग होतात?\",\"options\":[\"पूर्व आणि पश्चिम गोलार्ध\",\"उत्तर आणि दक्षिण गोलार्ध\",\"वरचा आणि खालचा गोलार्ध\",\"मोठा आणि लहान गोलार्ध\"],\"answer\":1,\"explain\":\"विषुववृत्तामुळे होणाऱ्या पृथ्वीच्या दोन समान भागांना उत्तर गोलार्ध आणि दक्षिण गोलार्ध म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"भोवरा फिरत असताना तो प्रत्यक्षात कशाभोवती फिरत असतो?\",\"options\":[\"एका अदृश्य रेषेभोवती\",\"ओळंब्याभोवती\",\"विषुववृत्ताभोवती\",\"जमिनीभोवती\"],\"answer\":0,\"explain\":\"स्वतःभोवती फिरणारी कोणतीही वस्तू प्रत्यक्षात एका अदृश्य रेषेभोवती फिरत असते.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, पृथ्वीचे दोन समान भाग करणाऱ्या रेषेला काय नाव दिले आहे?\",\"options\":[\"पृथ्वीचा अक्ष\",\"उत्तर ध्रुव\",\"विषुववृत्त\",\"ओळंबा\"],\"answer\":2,\"explain\":\"आकृतीत पृथ्वीच्या मध्यभागातून जाणारी आडवी रेषा \'विषुववृत्त\' म्हणून दर्शवली आहे.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"24\\/016_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत, \'N\' हे अक्षर काय दर्शवते?\",\"options\":[\"दक्षिण ध्रुव\",\"उत्तर ध्रुव\",\"विषुववृत्त\",\"उत्तर गोलार्ध\"],\"answer\":1,\"explain\":\"आकृतीत अक्षाचे वरचे टोक \'N\' म्हणजेच उत्तर ध्रुव (North Pole) असे दाखवले आहे.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"24\\/016_101.jpg\"},{\"q\":\"जर तुम्हाला पृथ्वीचा अक्ष कललेला आहे हे तपासायचे असेल, तर पृथ्वीगोलासोबत कोणते साधन वापरावे लागेल?\",\"options\":[\"भोवरा\",\"होकायंत्र\",\"ओळंबा\",\"भिंग\"],\"answer\":2,\"explain\":\"मजकुरात सांगितल्याप्रमाणे ओळंबा आणि पृथ्वीचा अक्ष यांच्यातील कोनावरून अक्ष कललेला असल्याचे समजते.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीच्या परिवलनाबद्दल खालीलपैकी कोणते विधान अचूक आहे?\",\"options\":[\"पृथ्वीचा अक्ष सरळ असतो.\",\"पृथ्वी विषुववृत्ताभोवती परिवलन करते.\",\"पृथ्वी अक्ष कललेल्या स्थितीमध्येच परिवलन करते.\",\"पृथ्वीला परिवलनासाठी ओळंब्याची गरज असते.\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की अक्ष कललेल्या स्थितीमध्येच पृथ्वी परिवलन करत असते.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जर एखादा देश विषुववृत्ताच्या खालच्या भागात असेल, तर तो कोणत्या गोलार्धात येईल?\",\"options\":[\"उत्तर गोलार्ध\",\"दक्षिण गोलार्ध\",\"मध्य गोलार्ध\",\"पूर्व गोलार्ध\"],\"answer\":1,\"explain\":\"विषुववृत्ताच्या खालील (दक्षिण ध्रुवाकडील) भागाला दक्षिण गोलार्ध म्हणतात.\",\"topic\":\"पृथ्वीचे परिवलन\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"प्रयोगामध्ये मेणबत्ती म्हणजे काय आहे असे समजायचे आहे?\",\"options\":[\"चंद्र\",\"सूर्य\",\"पृथ्वी\",\"तारा\"],\"answer\":1,\"explain\":\"पाठातील प्रयोगात मेणबत्तीला सूर्य मानण्यास सांगितले आहे.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पृथ्वी स्वतःभोवती कोणत्या दिशेकडून कोणत्या दिशेकडे फिरते?\",\"options\":[\"पूर्वेकडून पश्चिमेकडे\",\"उत्तरेकडून दक्षिणेकडे\",\"पश्चिमेकडून पूर्वेकडे\",\"दक्षिणेकडून उत्तरेकडे\"],\"answer\":2,\"explain\":\"पृथ्वी स्वतःभोवती पश्चिमेकडून पूर्वेकडे फिरते असे पाठात नमूद केले आहे.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीगोलाच्या ज्या भागावर उजेड पडतो, तेथे काय आहे असे आपण म्हणतो?\",\"options\":[\"रात्र\",\"संध्याकाळ\",\"दिन\",\"अंधार\"],\"answer\":2,\"explain\":\"ज्या भागावर उजेड पडतो तेथे दिन आहे असे म्हणतात.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीगोलाचे विविध भाग क्रमाने उजेडात का येतात?\",\"options\":[\"सूर्य फिरत असल्यामुळे\",\"पृथ्वी स्वतःभोवती फिरत असल्यामुळे\",\"मेणबत्ती हलवल्यामुळे\",\"खोलीत अंधार असल्यामुळे\"],\"answer\":1,\"explain\":\"पृथ्वी स्वतःभोवती फिरत असल्यामुळे तिचे विविध भाग क्रमाने उजेडात येतात.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"प्रयोगात पृथ्वीगोल उत्तर ध्रुवाकडून पाहिल्यास तो कोणत्या दिशेने फिरवावा लागतो?\",\"options\":[\"घड्याळाच्या काट्यांच्या दिशेने\",\"वरून खाली\",\"खालून वर\",\"घड्याळाच्या काट्यांच्या विरुद्ध दिशेने\"],\"answer\":3,\"explain\":\"उत्तर ध्रुवाकडून पाहिल्यास पृथ्वी घड्याळाच्या काट्यांच्या विरुद्ध दिशेने फिरते.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"जर पृथ्वीचा एक भाग आता अंधारात असेल, तर पृथ्वी फिरत असताना पुढे काय होईल?\",\"options\":[\"तो भाग कायम अंधारात राहील\",\"तो भाग क्रमाने उजेडात येईल\",\"तो भाग सूर्यापासून दूर जाईल\",\"तो भाग फिरणे थांबवेल\"],\"answer\":1,\"explain\":\"पृथ्वी फिरत असल्यामुळे अंधारातील भाग क्रमाने उजेडात येतो.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीवर एकाच वेळी सर्व ठिकाणी \'दिन\' का असू शकत नाही?\",\"options\":[\"पृथ्वी स्वतःभोवती फिरते आणि ती गोल आहे\",\"सूर्य खूप लांब आहे\",\"पृथ्वीवर खूप अंधार असतो\",\"मेणबत्तीचा प्रकाश कमी असतो\"],\"answer\":0,\"explain\":\"पृथ्वी गोल असल्यामुळे आणि ती स्वतःभोवती फिरत असल्यामुळे एका वेळी अर्ध्याच भागावर उजेड पडतो.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीवर दिन आणि रात्र होण्याचे मुख्य कारण काय आहे?\",\"options\":[\"सूर्याचे फिरणे\",\"पृथ्वीचे स्वतःभोवती फिरणे\",\"चंद्राचा उजेड\",\"मेणबत्तीची ज्योत\"],\"answer\":1,\"explain\":\"पृथ्वीच्या स्वतःभोवती फिरण्यामुळेच दिन आणि रात्र होतात.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत पृथ्वीगोलावर जो उजेड दिसत आहे, त्याला काय म्हणतात?\",\"options\":[\"रात्र\",\"सावली\",\"दिन\",\"अंधार\"],\"answer\":2,\"explain\":\"आकृतीमध्ये स्पष्टपणे \'पृथ्वीगोलावर दिसणारा उजेड म्हणजे दिन\' असे लिहिले आहे.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"24\\/017_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत पृथ्वीगोलाच्या वर असलेला वक्र बाण काय दर्शवतो?\",\"options\":[\"पृथ्वीची फिरण्याची दिशा\",\"मेणबत्तीची उंची\",\"सूर्याचा प्रकाश\",\"वर्तुळाचा आकार\"],\"answer\":0,\"explain\":\"आकृतीतील बाण पृथ्वी स्वतःभोवती कोणत्या दिशेने फिरते ते दर्शवतो.\",\"topic\":\"दिन आणि रात्र\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"24\\/017_102.jpg\"},{\"q\":\"पृथ्वीच्या स्वतःभोवतीच्या एका फेरीला काय म्हणतात?\",\"options\":[\"परिभ्रमण\",\"परिवलन\",\"मध्यान्ह\",\"सूर्यास्त\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, पृथ्वीच्या स्वतःभोवतीच्या एका फेरीला \'परिवलन\' म्हणतात.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"कालमापनासाठी एका दिवसाच