":[\"सूर्योदय, सूर्यास्त, मध्यान्ह\",\"मध्यान्ह, सूर्योदय, सूर्यास्त\",\"सूर्योदय, मध्यान्ह, सूर्यास्त\",\"सूर्यास्त, मध्यान्ह, सूर्योदय\"],\"answer\":2,\"explain\":\"परिवलनामुळे क्रमाने सूर्योदय, त्यानंतर मध्यान्ह आणि शेवटी सूर्यास्त होतो.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत, पृथ्वीगोलाचा जो भाग उजेडात (मेणबत्तीसमोर) आहे, तिथे काय असेल?\",\"options\":[\"रात्र\",\"दिन\",\"मध्यरात्र\",\"ग्रहण\"],\"answer\":1,\"explain\":\"आकृतीनुसार, पृथ्वीचा जो भाग प्रकाशात असतो तिथे \'दिन\' असतो.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"24\\/017_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत, लाल टिकली अंधारातून उजेडाकडे (घड्याळाच्या विरुद्ध दिशेने) सरकल्यास तिथे काय होईल?\",\"options\":[\"सूर्यास्त\",\"मध्यान्ह\",\"सूर्योदय\",\"मध्यरात्र\"],\"answer\":2,\"explain\":\"अंधारातून उजेडाकडे येणे म्हणजे सूर्योदय होणे होय.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"apply\",\"figure_image\":\"24\\/017_101.jpg\"},{\"q\":\"पृथ्वीच्या एका परिवर्तनाच्या (परिवलनाच्या) कालावधीला आपण काय म्हणतो?\",\"options\":[\"एक आठवडा\",\"एक महिना\",\"एक वर्ष\",\"एक दिवस\"],\"answer\":3,\"explain\":\"पृथ्वीच्या एका परिवर्तनाच्या कालावधीला आपण \'एक दिवस\' म्हणतो.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर पृथ्वीने स्वतःभोवती फिरणे थांबवले, तर लाल टिकलीवर काय परिणाम होईल?\",\"options\":[\"तिथे सतत सूर्योदय होईल\",\"तिथे दिवस-रात्र चक्र थांबेल\",\"तिथे फक्त मध्यान्ह होईल\",\"काहीही फरक पडणार नाही\"],\"answer\":1,\"explain\":\"परिवलन थांबल्यास पृथ्वीचा जो भाग मेणबत्तीसमोर आहे तिथे कायमचा दिवस राहील आणि विरुद्ध भागात कायमची रात्र राहील.\",\"topic\":\"सूर्योदय आणि सूर्यास्त\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीच्या सूर्याभोवतीच्या एका परिभ्रणाला जो कालावधी लागतो, त्याला काय म्हणतात?\",\"options\":[\"महिना\",\"दिवस\",\"वर्ष\",\"ऋतू\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे, पृथ्वीच्या सूर्याभोवतीच्या एका परिभ्रणाच्या कालावधीला \'वर्ष\' म्हणतात.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"एका वर्षात सुमारे किती दिवस असतात?\",\"options\":[\"३६० दिवस\",\"३६५ दिवस\",\"३६६ दिवस\",\"३५५ दिवस\"],\"answer\":1,\"explain\":\"एका वर्षात सुमारे ३६५ दिवस आणि ६ तास असतात असे पाठ्यपुस्तकात नमूद केले आहे.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पृथ्वी स्वतःभोवती फिरत असतानाच कोणाभोवती परिभ्रमण करते?\",\"options\":[\"चंद्राभोवती\",\"ताऱ्यांभोवती\",\"सूर्याभोवती\",\"ग्रहाभोवती\"],\"answer\":2,\"explain\":\"पृथ्वी स्वतःभोवती फिरत सूर्याभोवतीही परिभ्रमण करत असते.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एका वर्षात ३६५ दिवसांव्यतिरिक्त आणखी किती तास असतात?\",\"options\":[\"२ तास\",\"४ तास\",\"६ तास\",\"१२ तास\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार, एका वर्षात सुमारे ३६५ दिवस आणि ६ तास असतात.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीगोल टेबलावर फिरवताना कोणती गोष्ट बदलणार नाही याची काळजी घ्यावी लागते?\",\"options\":[\"पृथ्वीगोलाचा रंग\",\"अक्षाची दिशा\",\"टेबलाचा आकार\",\"फिरण्याचा वेग\"],\"answer\":1,\"explain\":\"प्रयोग करताना पृथ्वीच्या अक्षाची दिशा बदलणार नाही याची काळजी घ्यावी लागते.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीच्या सूर्याभोवती फिरण्याच्या क्रियेला काय म्हणतात?\",\"options\":[\"परिवलन\",\"स्थलांतर\",\"परिभ्रमण\",\"भ्रमण\"],\"answer\":2,\"explain\":\"पृथ्वीच्या सूर्याभोवती फिरण्याच्या क्रियेला \'परिभ्रमण\' म्हणतात.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर पृथ्वीने एका वर्षात ३६५ दिवस आणि ६ तास पूर्ण केले, तर २ वर्षात किती अतिरिक्त तास होतील?\",\"options\":[\"६ तास\",\"१० तास\",\"१२ तास\",\"२४ तास\"],\"answer\":2,\"explain\":\"एका वर्षात ६ तास अतिरिक्त असतात, म्हणून २ वर्षात ६ + ६ = १२ तास होतील.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"पृथ्वी सूर्याभोवती फिरताना स्वतःभोवती फिरते का?\",\"options\":[\"नाही, ती फक्त सूर्याभोवती फिरते\",\"हो, ती स्वतःभोवती फिरतच सूर्याभोवती फिरते\",\"ती फक्त कधीकधी स्वतःभोवती फिरते\",\"ती फक्त रात्री स्वतःभोवती फिरते\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्ट केले आहे की पृथ्वी स्वतःभोवती फिरत सूर्याभोवतीही परिभ्रमण करते.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीगोलाच्या प्रयोगात, वर्तुळावरून पुढे सरकत शेवटी पृथ्वीगोल कोठे पोहोचतो?\",\"options\":[\"दुसऱ्या टेबलावर\",\"चंद्राच्या जागी\",\"पुन्हा सूर्याच्याच (सुरुवातीच्या) जागी\",\"वर्तुळाच्या बाहेर\"],\"answer\":2,\"explain\":\"परिभ्रमण पूर्ण झाल्यावर पृथ्वीगोल पुन्हा सूर्याच्याच (सुरुवातीच्या) जागी पोहोचतो.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विधान पृथ्वीच्या हालचालीबाबत सत्य आहे?\",\"options\":[\"पृथ्वी फक्त परिवलन करते.\",\"पृथ्वी फक्त परिभ्रमण करते.\",\"पृथ्वी एकाच वेळी परिवलन आणि परिभ्रमण करते.\",\"पृथ्वीचा अक्ष सतत दिशा बदलत असतो.\"],\"answer\":2,\"explain\":\"पृथ्वी स्वतःभोवती फिरणे (परिवलन) आणि सूर्याभोवती फिरणे (परिभ्रमण) या दोन्ही क्रिया एकाच वेळी करते.\",\"topic\":\"वर्ष\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"ग्रेगरियन पद्धतीच्या दिनदर्शिकेत वर्षाचे सर्वसाधारणपणे किती दिवस धरले जातात?\",\"options\":[\"३६० दिवस\",\"३६४ दिवस\",\"३६५ दिवस\",\"३६६ दिवस\"],\"answer\":2,\"explain\":\"ग्रेगरियन दिनदर्शिकेत वर्षाचे साधारणपणे ३६५ दिवस मानले जातात.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"ग्रेगरियन दिनदर्शिकेनुसार प्रत्येक वर्षात किती तास कमी धरले जातात?\",\"options\":[\"४ तास\",\"६ तास\",\"१२ तास\",\"२४ तास\"],\"answer\":1,\"explain\":\"ग्रेगरियन पद्धतीत प्रत्येक वर्षात ६ तास कमी धरले जातात.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"चार वर्षांत एकूण किती तास कमी धरले जातात, ज्यामुळे एक पूर्ण दिवस तयार होतो?\",\"options\":[\"१२ तास\",\"१८ तास\",\"२४ तास\",\"३० तास\"],\"answer\":2,\"explain\":\"प्रत्येक वर्षाचे ६ तास याप्रमाणे ४ वर्षांत ६ x ४ = २४ तास (१ दिवस) कमी होतात.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"लीप वर्षामध्ये फेब्रुवारी महिना किती दिवसांचा असतो?\",\"options\":[\"२८ दिवस\",\"२९ दिवस\",\"३० दिवस\",\"३१ दिवस\"],\"answer\":1,\"explain\":\"लीप वर्षात फेब्रुवारी महिन्यात एक अधिकचा दिवस जोडल्यामुळे तो २९ दिवसांचा असतो.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"लीप वर्षात एकूण किती दिवस असतात?\",\"options\":[\"३६५ दिवस\",\"३६४ दिवस\",\"३६६ दिवस\",\"३६० दिवस\"],\"answer\":2,\"explain\":\"लीप वर्षात एक दिवस वाढल्यामुळे एकूण ३६६ दिवस होतात.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"ग्रेगरियन दिनदर्शिकेत अधिकचा दिवस कोणत्या महिन्यात जोडला जातो?\",\"options\":[\"जानेवारी\",\"फेब्रुवारी\",\"मार्च\",\"डिसेंबर\"],\"answer\":1,\"explain\":\"लीप वर्षाचा अधिकचा दिवस फेब्रुवारी महिन्यात जोडला जातो.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"लीप वर्ष दर किती वर्षांनी येते?\",\"options\":[\"दर दुसऱ्या वर्षी\",\"दर तिसऱ्या वर्षी\",\"दर चौथ्या वर्षी\",\"दर पाचव्या वर्षी\"],\"answer\":2,\"explain\":\"सहा तासांची तूट भरून काढण्यासाठी प्रत्येक चौथ्या वर्षात एक दिवस वाढवला जातो.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एका वर्षात ६ तास कमी धरले, तर २ वर्षात किती तास कमी धरले जातील?\",\"options\":[\"६ तास\",\"१२ तास\",\"१८ तास\",\"२४ तास\"],\"answer\":1,\"explain\":\"एका वर्षात ६ तास, म्हणून दोन वर्षात ६ + ६ = १२ तास कमी धरले जातील.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"लीप वर्षाची संकल्पना का मांडली गेली असावी?\",\"options\":[\"फेब्रुवारी महिना मोठा करण्यासाठी\",\"वर्ष ३६० दिवसांचे करण्यासाठी\",\"दरवर्षी कमी होणारे ६ तास भरून काढण्यासाठी\",\"दिवस २४ तासांपेक्षा मोठा करण्यासाठी\"],\"answer\":2,\"explain\":\"दरवर्षी कमी होणारे ६ तास ४ वर्षांत २४ तास होतात, ते भरून काढण्यासाठी लीप वर्ष असते.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते विधान लीप वर्षासाठी योग्य आहे?\",\"options\":[\"लीप वर्षात ३६५ दिवस असतात.\",\"लीप वर्षात फेब्रुवारी २८ दिवसांचा असतो.\",\"लीप वर्षात ३६६ दिवस असतात.\",\"लीप वर्ष दरवर्षी येते.\"],\"answer\":2,\"explain\":\"लीप वर्षात फेब्रुवारी २९ दिवसांचा आणि वर्षाचे एकूण ३६६ दिवस असतात.\",\"topic\":\"लीप वर्ष\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"पृथ्वीवर दिन व रात्रीचा कालावधी सारखा नसण्याचे मुख्य कारण काय आहे?\",\"options\":[\"पृथ्वीचा अक्ष कललेला असणे व तिचे परिभ्रमण\",\"पृथ्वीचा आकार गोल असणे\",\"चंद्राचे पृथ्वीभोवती फिरणे\",\"सूर्याचे स्वतःभोवती फिरणे\"],\"answer\":0,\"explain\":\"उताऱ्यानुसार, पृथ्वीचा अक्ष कललेला असल्यामुळे व पृथ्वीच्या परिभ्रमणामुळे दिन व रात्रीचा कालावधी बदलतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"२२ मार्च ते २३ सप्टेंबर या काळात उत्तर गोलार्धात कोणता ऋतू असतो?\",\"options\":[\"हिवाळा\",\"पावसाळा\",\"उन्हाळा\",\"शिशिर\"],\"answer\":2,\"explain\":\"या काळात उत्तर गोलार्धात दिनमान जास्त असल्याने उष्णता जास्त मिळते, म्हणून तेथे उन्हाळा असतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जेव्हा उत्तर गोलार्धात उन्हाळा असतो, तेव्हा दक्षिण गोलार्धात कोणता ऋतू असतो?\",\"options\":[\"उन्हाळा\",\"हिवाळा\",\"वसंत\",\"ग्रीष्म\"],\"answer\":1,\"explain\":\"उत्तर गोलार्धात उन्हाळा असताना दक्षिण गोलार्धात रात्र मोठी असते आणि उष्णता कमी मिळाल्याने तेथे हिवाळा असतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"२३ सप्टेंबर ते २२ मार्च या काळात दक्षिण गोलार्धात दिनमान जास्त का असते?\",\"options\":[\"कारण तेथे पाऊस पडतो\",\"कारण पृथ्वीचा अक्ष सरळ असतो\",\"कारण पृथ्वीच्या परिभ्रमणामुळे हा भाग सूर्याकडे झुकलेला असतो\",\"कारण तेथे रात्र मोठी असते\"],\"answer\":2,\"explain\":\"पृथ्वीच्या परिभ्रमणामुळे ठराविक काळात विशिष्ट गोलार्धात दिनमान जास्त असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"भारतात प्रामुख्याने मानले जाणारे तीन मुख्य ऋतू कोणते?\",\"options\":[\"वसंत, शरद, शिशिर\",\"उन्हाळा, पावसाळा, हिवाळा\",\"ग्रीष्म, वर्षा, हेमंत\",\"उन्हाळा, हिवाळा, शरद\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की भारतात उन्हाळा, पावसाळा व हिवाळा हे मुख्य ऋतू मानतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"ऋतूंच्या निश्चित तारखांमध्ये कशामुळे थोडा फरक पडू शकतो?\",\"options\":[\"वातावरणामुळे\",\"लीप वर्षामुळे\",\"चंद्राच्या कलांमुळे\",\"समुद्राच्या लाटांमुळे\"],\"answer\":1,\"explain\":\"उताऱ्यात दिलेल्या तारखांमध्ये लीप वर्षामुळे फरक पडू शकतो अशी नोंद दिली आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर १० नोव्हेंबर ही तारीख असेल, तर उत्तर गोलार्धात साधारणपणे कोणती स्थिती असेल?\",\"options\":[\"दिनमान जास्त असेल\",\"उष्णता खूप जास्त असेल\",\"रात्रमान जास्त असेल व हिवाळा असेल\",\"उन्हाळा असेल\"],\"answer\":2,\"explain\":\"२३ सप्टेंबर ते २२ मार्च या काळात उत्तर गोलार्धात रात्रमान जास्त असते, त्यामुळे तेथे हिवाळा असतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"भारतीय परंपरेनुसार मानल्या जाणाऱ्या सहा ऋतूंच्या चक्रातील खालीलपैकी कोणता ऋतू नाही?\",\"options\":[\"वसंत\",\"शरद\",\"शिशिर\",\"नोव्हेंबर\"],\"answer\":3,\"explain\":\"वसंत, ग्रीष्म, वर्षा, शरद, हेमंत, शिशिर हे सहा ऋतू आहेत; नोव्हेंबर हा महिना आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"दक्षिण गोलार्धात २३ सप्टेंबर ते २२ मार्च या काळात उष्णता जास्त का मिळते?\",\"options\":[\"कारण तेथे रात्र मोठी असते\",\"कारण तेथे दिनमान जास्त असते\",\"कारण तेथे पाऊस पडत नाही\",\"कारण तेथे वारे वाहत नाहीत\"],\"answer\":1,\"explain\":\"दिनमान जास्त असल्यामुळे त्या भागाला सूर्याची उष्णता जास्त प्रमाणात मिळते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"आपल्या देशात सण, उत्सव आणि गाणी यांचा संबंध कशाशी जोडलेला असतो?\",\"options\":[\"फक्त खेळांशी\",\"शाळांशी\",\"ऋतुमानाशी\",\"केवळ तारखांशी\"],\"answer\":2,\"explain\":\"आपल्या देशात ऋतुमानाशी निगडित सण, उत्सव, गाणी आणि खेळ साजरे केले जातात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीचा अक्ष कललेला नसता, तर उताऱ्यात दिलेल्या माहितीनुसार काय झाले असते?\",\"options\":[\"दिवस आणि रात्रीच्या कालावधीत फरक पडला नसता\",\"पृथ्वी फिरणे थांबली असती\",\"पाऊस पडणे बंद झाले असते\",\"सहा ऋतूंचे चक्र वेगाने फिरले असते\"],\"answer\":0,\"explain\":\"अक्ष कललेला असल्यामुळेच दिन व रात्रीचा कालावधी बदलतो, असे उताऱ्याच्या सुरुवातीला म्हटले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या काळात उत्तर गोलार्धात उष्णता कमी प्रमाणात मिळते?\",\"options\":[\"२२ मार्च ते २३ सप्टेंबर\",\"२३ सप्टेंबर ते २२ मार्च\",\"२२ मार्च ते २२ जून\",\"२३ सप्टेंबर ते २३ डिसेंबर\"],\"answer\":1,\"explain\":\"२३ सप्टेंबर ते २२ मार्च या काळात उत्तर गोलार्धात रात्रमान जास्त असल्याने उष्णता कमी मिळते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"चंद्राच्या पृथ्वीवरून दिसणाऱ्या प्रकाशित भागाला काय म्हणतात?\",\"options\":[\"चंद्राचे फिरणे\",\"चंद्राच्या कला\",\"चंद्राचा प्रकाश\",\"चंद्राची कक्षा\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, चंद्राच्या पृथ्वीवरून दिसणाऱ्या प्रकाशित भागाला \'चंद्राच्या कला\' म्हणतात.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चंद्र स्वयंप्रकाशित नाही, तरीही तो आपल्याला का दिसतो?\",\"options\":[\"पृथ्वीच्या प्रकाशामुळे\",\"ताऱ्यांच्या प्रकाशामुळे\",\"सूर्याचा प्रकाश चंद्रावर पडल्यामुळे\",\"चंद्राच्या स्वतःच्या उष्णतेमुळे\"],\"answer\":2,\"explain\":\"सूर्याचा प्रकाश चंद्रावर पडल्यामुळे तो आपल्याला पृथ्वीवरून दिसतो असे पाठात स्पष्ट केले आहे.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीवरून आपल्याला चंद्राची नेहमी किती बाजू दिसते?\",\"options\":[\"पूर्ण बाजू\",\"नेहमी एकच बाजू\",\"दोन्ही बाजू\",\"वेगवेगळ्या बाजू\"],\"answer\":1,\"explain\":\"पृथ्वीवरून आपल्याला चंद्राची नेहमी एकच बाजू दिसते कारण आपल्याला चंद्राच्या पृष्ठभागाचा पृथ्वीकडील अर्धाच भाग दिसतो.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"पौर्णिमेच्या रात्री चंद्राचा कोणता भाग दिसतो?\",\"options\":[\"कुठलाच भाग दिसत नाही\",\"अर्धा भाग दिसतो\",\"पृथ्वीकडील पूर्ण भाग दिसतो\",\"फक्त कडा दिसते\"],\"answer\":2,\"explain\":\"पौर्णिमेच्या रात्री आपल्याला चंद्राचा पृथ्वीकडील पूर्ण भाग दिसतो.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"अमावस्येच्या रात्री चंद्राची स्थिती कशी असते?\",\"options\":[\"चंद्राचा पूर्ण भाग दिसतो\",\"चंद्राचा कुठलाच भाग दिसत नाही\",\"चंद्र सूर्यापेक्षा मोठा दिसतो\",\"चंद्राचा अर्धा भाग दिसतो\"],\"answer\":1,\"explain\":\"अमावस्येच्या रात्री चंद्राचा कुठलाच भाग दिसत नाही.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"सूर्य, चंद्र आणि पृथ्वी हे नेहमी एकाच सरळ रेषेत का नसतात?\",\"options\":[\"कारण ते खूप लांब आहेत\",\"कारण त्यांच्या भ्रमकक्षा एकमेकांना छेदतात\",\"कारण पृथ्वी गोल आहे\",\"कारण चंद्र लहान आहे\"],\"answer\":1,\"explain\":\"चंद्र आणि पृथ्वी यांच्या भ्रमकक्षा एकमेकांना छेदतात, म्हणून ते नेहमी एकाच सरळ रेषेत नसतात.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"पौर्णिमेपासून अमावस्येपर्यंत चंद्राच्या प्रकाशित भागामध्ये काय बदल होतो?\",\"options\":[\"प्रकाशित भाग वाढत जातो\",\"प्रकाशित भाग स्थिर राहतो\",\"प्रकाशित भाग कमी कमी होत जातो\",\"प्रकाशित भाग पिवळा होतो\"],\"answer\":2,\"explain\":\"पौर्णिमेपासून अमावस्येपर्यंत चंद्राचा पृथ्वीवरून दिसणारा प्रकाशित भाग कमी कमी होत जातो.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"अमावस्येपासून पौर्णिमेपर्यंत चंद्राच्या प्रकाशित भागात कोणता बदल दिसून येतो?\",\"options\":[\"तो पुन्हा वाढत वाढत जातो\",\"तो अधिक गडद होतो\",\"तो पूर्णपणे नाहीसा होतो\",\"तो कमी होत जातो\"],\"answer\":0,\"explain\":\"अमावस्येपासून पौर्णिमेपर्यंत चंद्राचा प्रकाशित भाग पुन्हा वाढत वाढत जातो.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"चंद्र कोणाभोवती परिभ्रमण करतो?\",\"options\":[\"सूर्याभोवती\",\"ताऱ्यांभोवती\",\"पृथ्वीभोवती\",\"स्वतःभोवती फक्त\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे चंद्र पृथ्वीभोवती परिभ्रमण करतो.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"पृथ्वी कोणाभोवती परिभ्रमण करते?\",\"options\":[\"चंद्राभोवती\",\"सूर्याभोवती\",\"ग्रहाभोवती\",\"आकाशाभोवती\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्ट दिले आहे की पृथ्वी सूर्याभोवती परिभ्रमण करते.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर चंद्राला स्वतःचा प्रकाश असता, तर काय झाले असते?\",\"options\":[\"तो अमावस्येलाही पूर्ण दिसला असता\",\"तो कधीच दिसला नसता\",\"त्याच्या कला दिसल्या नसत्या\",\"तो सूर्यापेक्षा जास्त गरम झाला असता\"],\"answer\":0,\"explain\":\"चंद्र स्वयंप्रकाशित नाही म्हणून तो सूर्याच्या प्रकाशानुसार बदलत्या रूपात दिसतो; स्वतःचा प्रकाश असता तर तो नेहमी प्रकाशित दिसला असता.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणते विधान \'चंद्राच्या कला\' या संदर्भात योग्य आहे?\",\"options\":[\"चंद्र स्वतःचा आकार बदलतो\",\"पृथ्वीवरून दिसणारा चंद्राचा प्रकाशित भाग बदलतो\",\"सूर्य चंद्राभोवती फिरतो\",\"अमावस्येला चंद्र सर्वात मोठा दिसतो\"],\"answer\":1,\"explain\":\"चंद्राचा पृथ्वीवरून दिसणारा प्रकाशित भाग कमी-जास्त होणे म्हणजेच चंद्राच्या कला होय.\",\"topic\":\"चंद्राच्या कला\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"एका अमावस्येपासून पुढच्या अमावस्येपर्यंतच्या काळाला काय म्हणतात?\",\"options\":[\"सौर वर्ष\",\"चांद्रमास\",\"तिथी\",\"शुक्लपक्ष\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, एका अमावस्येपासून पुढच्या अमावस्येपर्यंतच्या सुमारे २८ ते ३० दिवसांच्या काळाला ‘चांद्रमास’ म्हणतात.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"चांद्रमासातील प्रत्येक दिवसाला काय म्हणतात?\",\"options\":[\"वार\",\"दिनांक\",\"तिथी\",\"पक्ष\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की, चांद्रमासातील प्रत्येक दिवसाला ‘तिथी’ म्हणतात.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"अमावस्येपासून पौर्णिमेपर्यंतच्या पंधरवड्याला काय म्हणतात?\",\"options\":[\"कृष्णपक्ष\",\"शुक्लपक्ष\",\"चांद्रमास\",\"तिथी\"],\"answer\":1,\"explain\":\"अमावस्येपासून पौर्णिमेच्या स्थितीला येण्यास चंद्राला १४-१५ दिवस लागतात, या पंधरवड्याला ‘शुक्लपक्ष’ म्हणतात.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"पौर्णिमेनंतर चंद्राच्या पृथ्वीकडील प्रकाशित भागाबाबत काय घडते?\",\"options\":[\"तो वाढत जातो\",\"तो तसाच राहतो\",\"तो पूर्णपणे नाहीसा होतो\",\"तो कमी कमी होऊ लागतो\"],\"answer\":3,\"explain\":\"मजकुराप्रमाणे, पौर्णिमेनंतर चंद्राचा पृथ्वीकडील प्रकाशित भाग कमी कमी होऊ लागतो.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, \'शुक्लपक्ष\' आणि \'कृष्णपक्ष\' एकत्र मिळून काय तयार होते?\",\"options\":[\"एक आठवडा\",\"चांद्रमास (एक महिना)\",\"एक तिथी\",\"एक वर्ष\"],\"answer\":1,\"explain\":\"दिलेल्या आकृतीमधील शेवटच्या ओळीत \'शुक्लपक्ष + कृष्णपक्ष = चांद्रमास (एक महिना)\' असे दर्शवले आहे.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"24\\/019_102.jpg\"},{\"q\":\"दिलेल्या चित्रात चंद्राचे जे विविध आकार दिसत आहेत, त्यांना काय म्हणतात?\",\"options\":[\"चंद्राच्या कला\",\"चंद्राचे ग्रहण\",\"चंद्राची तिथी\",\"चंद्राचा मास\"],\"answer\":0,\"explain\":\"चित्रात चंद्राचे बदलणारे प्रकाशित भाग दाखवले आहेत, ज्यांना मजकुरात \'कला\' असे संबोधले आहे.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"24\\/019_101.jpg\"},{\"q\":\"जर आज पौर्णिमा असेल, तर आजपासून पुढच्या अमावस्येपर्यंतच्या पंधरवड्याला काय म्हणाल?\",\"options\":[\"शुक्लपक्ष\",\"कृष्णपक्ष\",\"चांद्रमास\",\"तिथी\"],\"answer\":1,\"explain\":\"पौर्णिमेनंतर १४-१५ दिवसांनी पुन्हा अमावस्या येते आणि या पंधरवड्याला ‘कृष्णपक्ष’ म्हणतात.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"चांद्रमासाचा काळ सुमारे किती दिवसांचा असतो?\",\"options\":[\"१४ ते १५ दिवस\",\"१५ ते २० दिवस\",\"२८ ते ३० दिवस\",\"३० ते ३१ दिवस\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे, एका अमावस्येपासून पुढच्या अमावस्येपर्यंतचा काळ सुमारे २८ ते ३० दिवसांचा असतो.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"कृष्णपक्षामध्ये चंद्राचा प्रवास कोणत्या स्थितीकडून कोणत्या स्थितीकडे होतो?\",\"options\":[\"अमावस्येकडून पौर्णिमेकडे\",\"पौर्णिमेकडून अमावस्येकडे\",\"अमावस्येकडून शुक्लपक्षाकडे\",\"पौर्णिमेकडून शुक्लपक्षाकडे\"],\"answer\":1,\"explain\":\"पौर्णिमेनंतर १४-१५ दिवसांनी पुन्हा अमावस्या येते, या पंधरवड्याला कृष्णपक्ष म्हणतात, म्हणजेच हा प्रवास पौर्णिमेकडून अमावस्येकडे असतो.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"चंद्राला अमावस्येपासून पौर्णिमेच्या स्थितीला येण्यास किती दिवस लागतात?\",\"options\":[\"७ ते ८ दिवस\",\"१४ ते १५ दिवस\",\"२८ ते ३० दिवस\",\"१ महिना\"],\"answer\":1,\"explain\":\"मजकुरात दिले आहे की अमावस्येपासून पौर्णिमेच्या स्थितीला येण्यास चंद्राला १४ किंवा १५ दिवस लागतात.\",\"topic\":\"चंद्रमास आणि तिथी\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीवर दिन आणि रात्र कशामुळे होतात?\",\"options\":[\"पृथ्वीचे सूर्याभोवतीचे परिभ्रमण\",\"पृथ्वीचे स्वतःभोवतीचे परिवलन\",\"चंद्राचे पृथ्वीभोवतीचे परिभ्रमण\",\"पृथ्वीचा कललेला अक्ष\"],\"answer\":1,\"explain\":\"पृथ्वीच्या स्वतःभोवती फिरण्याला परिवलन म्हणतात आणि यामुळेच दिवस व रात्र होतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीवर ऋतू कशामुळे होतात?\",\"options\":[\"केवळ पृथ्वीच्या परिवलनामुळे\",\"केवळ चंद्राच्या परिभ्रमणामुळे\",\"पृथ्वीचे परिभ्रमण आणि कललेला अक्ष\",\"सूर्याचे पृथ्वीभोवतीचे फिरणे\"],\"answer\":2,\"explain\":\"पृथ्वीचे सूर्याभोवतीचे परिभ्रमण आणि पृथ्वीचा कललेला अक्ष या दोन्ही गोष्टींमुळे ऋतू होतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"एका अमावस्येपासून पुढच्या अमावस्येपर्यंतच्या काळाला काय म्हणतात?\",\"options\":[\"सौरमास\",\"पंधरवडा\",\"चांद्रमास\",\"तिथी\"],\"answer\":2,\"explain\":\"एका अमावस्येपासून दुसऱ्या अमावस्येपर्यंतच्या काळाला चांद्रमास असे म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"चांद्रमास साधारणपणे किती दिवसांचा असतो?\",\"options\":[\"१५ दिवस\",\"३० ते ३१ दिवस\",\"२८ ते ३० दिवस\",\"३६५ दिवस\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार चांद्रमास सुमारे २८ ते ३० दिवसांचा असतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पौर्णिमेला शेवट होणाऱ्या पंधरवड्याला काय म्हणतात?\",\"options\":[\"कृष्णपक्ष\",\"शुक्लपक्ष\",\"चांद्रमास\",\"तिथी\"],\"answer\":1,\"explain\":\"ज्या पंधरवड्याचा शेवट पौर्णिमेने होतो, त्याला शुक्लपक्ष म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"अमावस्येस शेवट होणाऱ्या पंधरवड्याला काय म्हणतात?\",\"options\":[\"शुक्लपक्ष\",\"कृष्णपक्ष\",\"पौर्णिमा\",\"चांद्रमास\"],\"answer\":1,\"explain\":\"ज्या पंधरवड्याचा शेवट अमावस्येने होतो, त्याला कृष्णपक्ष म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"चांद्रमासातील प्रत्येक दिवसाला काय म्हणतात?\",\"options\":[\"वार\",\"तारीख\",\"तिथी\",\"वेळ\"],\"answer\":2,\"explain\":\"चांद्रमासातील दिवसांना \'तिथी\' असे संबोधले जाते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"जर पृथ्वीचा अक्ष कललेला नसता, तर खालीलपैकी कशावर परिणाम झाला असता?\",\"options\":[\"दिवस आणि रात्र होण्यावर\",\"ऋतूचक्रावर\",\"चंद्राच्या कलांवर\",\"चांद्रमासाच्या कालावधीवर\"],\"answer\":1,\"explain\":\"ऋतू होण्यासाठी पृथ्वीचा कललेला अक्ष कारणीभूत असतो, त्यामुळे अक्ष कललेला नसता तर ऋतूचक्रावर परिणाम झाला असता.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"चंद्राच्या कला आपल्याला कशामुळे दिसतात?\",\"options\":[\"पृथ्वीच्या परिवलनामुळे\",\"चंद्राच्या पृथ्वीभोवतीच्या परिभ्रमणामुळे\",\"पृथ्वीच्या सूर्याभोवतीच्या परिभ्रमणामुळे\",\"पृथ्वीच्या कललेल्या अक्षामुळे\"],\"answer\":1,\"explain\":\"चंद्र पृथ्वीभोवती परिभ्रमण करतो, त्यामुळे आपल्याला त्याच्या विविध कला दिसतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"एका चांद्रमासात किती पंधरवडे असतात आणि त्यांची नावे काय?\",\"options\":[\"दोन; शुक्लपक्ष आणि कृष्णपक्ष\",\"दोन; अमावस्या आणि पौर्णिमा\",\"चार; आठवडे\",\"एक; तिथी\"],\"answer\":0,\"explain\":\"चांद्रमासात शुक्लपक्ष आणि कृष्णपक्ष असे दोन पंधरवडे असतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21601,24,5,'EVS Part 1','mr','पृथ्वी आणि जीवसृष्टी','[\"पृथ्वीचे तीन आवरणे आहेत – शिलावरण (कठीण बाह्य कवच), जलावरण (पाणी), आणि वातावरण (हवा).\",\"शिलावरण माती व खडकांनी बनलेले असते आणि पृथ्वीला आधार देते.\",\"जलावरणात महासागर, समुद्र, नद्या, सरोवरे आणि भूजल यांचा समावेश होतो.\",\"वातावरणात नायट्रोजन, ऑक्सिजन, कार्बन डायऑक्साइड व बाष्प यांसारखे वायू असतात.\",\"पृथ्वीचा पृष्ठभाग सुमारे 70 % पाण्याने आणि 30 % जमिनीने व्यापलेला आहे.\",\"महासागर पाच आहेत – अटलांटिक, पॅसिफिक, आर्क्टिक, हिंदी आणि दक्षिणी.\",\"किनारपट्टी म्हणजे जमिनीचा तो भाग जो पाण्याने झाकलेला असतो.\",\"भूजल म्हणजे जमिनीखालील खडकांच्या थरात साठलेले पाणी.\",\"हिमनदी जमिनीवरील बर्फाचे थर हळूहळू खाली सरकून बनते.\",\"हिमनग म्हणजे समुद्रावर तरंगणारे मोठे बर्फाचे तुकडे.\",\"पृथ्वीचे वातावरण चार थरांमध्ये विभागलेले आहे – तपांबर, स्थितांबर, आयनांबर आणि बाह्यांबर.\",\"तपांबरात सर्वाधिक हवामान घटना जसे की ढग, पाऊस, धुके आणि वादळे घडतात.\",\"सूर्यापासून येणारी अतिनील किरणे ओझोन थराने शोषली जातात, ज्यामुळे जीवांना हानी पोहोचत नाही.\",\"पाण्याचे बाष्पीभवन, संघनन आणि पर्जन्य या प्रक्रियांनी जलचक्र चालते.\",\"पृथ्वीवरील सजीव – वनस्पती, प्राणी आणि सूक्ष्मजीव – हे शिलावरण, जलावरण आणि वातावरण या तीन आवरणांमध्ये राहतात.\"]','[{\"q\":\"पृथ्वीला प्रकाश आणि उष्णता कोणापासून मिळते?\",\"options\":[\"चंद्र\",\"सूर्य\",\"तारे\",\"वीज\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, पृथ्वीला प्रकाश आणि उष्णता सूर्यापासून मिळते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीभोवती असणाऱ्या हवेच्या आवरणाला काय म्हणतात?\",\"options\":[\"शिलावरण\",\"जलावरण\",\"वातावरण\",\"जीवावरण\"],\"answer\":2,\"explain\":\"पृथ्वीभोवती असणाऱ्या हवेच्या आवरणाला वातावरण म्हणतात.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सजीवांचे अस्तित्व कोठे असते?\",\"options\":[\"फक्त जमिनीवर\",\"फक्त पाण्यात\",\"जमीन, पाणी आणि हवा या तिन्ही ठिकाणी\",\"फक्त हवेत\"],\"answer\":2,\"explain\":\"जमिनीत, पाण्यात आणि हवेत अशा तिन्ही ठिकाणी सजीवांचे अस्तित्व असते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जीवावरण हे खालीलपैकी कोणत्या आवरणात दिसून येते?\",\"options\":[\"फक्त शिलावरणात\",\"फक्त जलावरणात\",\"फक्त वातावरणात\",\"इतर तीनही आवरणांत\"],\"answer\":3,\"explain\":\"जीवावरण हे शिलावरण, जलावरण आणि वातावरण या तीनही आवरणांत दिसून येते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"तुमचे घर कोणत्या आधारावर बांधलेले आहे, जे शिलावरणाचे प्रतिनिधित्व करते?\",\"options\":[\"हवा\",\"पाणी\",\"जमीन\",\"आकाश\"],\"answer\":2,\"explain\":\"घर जमिनीवर बांधलेले असते आणि जमीन शिलावरणाचे प्रतिनिधित्व करते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीवरील अनेक नैसर्गिक घडामोडींना कोण कारणीभूत ठरतो?\",\"options\":[\"चंद्र\",\"सूर्य\",\"वारा\",\"पाऊस\"],\"answer\":1,\"explain\":\"पृथ्वीवरील अनेक नैसर्गिक घडामोडींना सूर्य कारणीभूत ठरतो.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीवरील \'पाणी\' कोणत्या आवरणाचे प्रतिनिधित्व करते?\",\"options\":[\"शिलावरण\",\"जलावरण\",\"वातावरण\",\"जीवावरण\"],\"answer\":1,\"explain\":\"पृथ्वीवरील पाणी हे जलावरणाचे प्रतिनिधित्व करते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"श्वासोच्छ्वास करण्यासाठी आपल्याला हवेची गरज असते, हे कोणत्या आवरणाशी संबंधित आहे?\",\"options\":[\"जलावरण\",\"शिलावरण\",\"वातावरण\",\"भूवरण\"],\"answer\":2,\"explain\":\"हवा हे वातावरणाचे घटक आहे, ज्याची गरज आपल्याला श्वासोच्छ्वासासाठी लागते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते आवरण पृथ्वीच्या पृष्ठभागावरील जमीन, पाणी आणि हवा यांच्याशी संबंधित नाही?\",\"options\":[\"शिलावरण\",\"जलावरण\",\"सौरवरण\",\"वातावरण\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात शिलावरण, जलावरण आणि वातावरण ही तीन मुख्य आवरणे सांगितली आहेत; सौरवरण नाही.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"पृथ्वीच्या पृष्ठभागावर काय दिसते?\",\"options\":[\"फक्त जमीन\",\"फक्त पाणी\",\"काही भागात जमीन व काही भागात पाणी\",\"फक्त बर्फ\"],\"answer\":2,\"explain\":\"पृथ्वीच्या पृष्ठभागावर काही भागात जमीन तर काही भागात पाणी दिसते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीचे बाहेरील कवच कशाचे बनलेले आहे?\",\"options\":[\"केवळ पाण्याचे\",\"माती व खडकांचे\",\"केवळ हवेचे\",\"वाळू आणि बर्फाचे\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की पृथ्वीचे बाहेरील कवच माती व खडकांचे बनलेले आहे.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीवरील जमिनीच्या थराला काय म्हणतात?\",\"options\":[\"जलावरण\",\"वातावरण\",\"शिलावरण\",\"जीवावरण\"],\"answer\":2,\"explain\":\"पृथ्वीवरील जमिनीचा थर हा शिलावरणाचा भाग असतो.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"डोंगराळ भागातून प्रवास करताना आपल्याला जमिनीचे काय पाहायला मिळते?\",\"options\":[\"पाण्याचे प्रवाह\",\"हवेचे थर\",\"खडकांचे किंवा जमिनीचे थर\",\"केवळ ढग\"],\"answer\":2,\"explain\":\"डोंगराळ भागातून प्रवास करताना जमिनीचे किंवा खडकांचे थर दिसतात असे उताऱ्यात दिले आहे.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पाण्याखाली शिलावरण असते का?\",\"options\":[\"नाही, तिथे फक्त पाणी असते\",\"हो, पाण्याखालीही शिलावरण असते\",\"केवळ समुद्राच्या काठी असते\",\"फक्त नद्यांच्या खाली असते\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, पृथ्वीचा बराचसा भाग पाण्याने झाकलेला असला तरी त्या पाण्याखालीही शिलावरण असते.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, पृथ्वीच्या पृष्ठभागावर पाण्याचे प्रमाण किती आहे?\",\"options\":[\"१\\/३\",\"२\\/३\",\"अर्धे\",\"पूर्ण\"],\"answer\":1,\"explain\":\"आकृतीमध्ये स्पष्टपणे दाखवले आहे की पाण्याचे प्रमाण २\\/३ आहे.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"apply\",\"figure_image\":\"24\\/021_102.jpg\"},{\"q\":\"जर झाडाची मुळे जमिनीत खोलवर गेली असतील, तर ती कोणत्या आवरणाचा भाग व्यापतात?\",\"options\":[\"जलावरण\",\"वातावरण\",\"शिलावरण\",\"बाह्यावरण\"],\"answer\":2,\"explain\":\"माती आणि खडक हे शिलावरणाचे भाग आहेत, त्यामुळे मुळे शिलावरणात असतात.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत, दोन डोंगरांच्या मधील सखल भागाला काय म्हटले आहे?\",\"options\":[\"पर्वत\",\"दरी\",\"पठार\",\"मैदान\"],\"answer\":1,\"explain\":\"आकृतीमध्ये डोंगरांच्या मधील भागाला \'दरी\' असे नाव दिले आहे.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"24\\/022_101.jpg\"},{\"q\":\"शिलावरण कशाचे मिळून बनलेले असते?\",\"options\":[\"केवळ मातीचे थर\",\"केवळ समुद्राचे पाणी\",\"पृथ्वीचे बाहेरील कवच व त्याखालील थराचा काही भाग\",\"केवळ उंच पर्वत\"],\"answer\":2,\"explain\":\"उताऱ्याच्या शेवटच्या ओळीनुसार, बाहेरील कवच व त्याखालील थराचा काही भाग मिळून शिलावरण बनते.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात दिलेल्या वर्णनानुसार, ओसाड जमिनीवर काय आढळते?\",\"options\":[\"दाट झाडी\",\"पिके\",\"वाळूच वाळू\",\"गवताळ विस्तार\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की कोठे ओसाड जमिनीवर वाळूच वाळू असते.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीवरून, जमिनीचा भाग (१\\/३) आणि पाण्याचा भाग (२\\/३) यांची तुलना केल्यास काय निष्कर्ष निघतो?\",\"options\":[\"जमीन पाण्यापेक्षा जास्त आहे\",\"पाणी जमिनीच्या दुप्पट आहे\",\"दोन्ही समान आहेत\",\"जमीन पाण्याचा अर्धा भाग आहे\"],\"answer\":1,\"explain\":\"२\\/३ हे १\\/३ च्या दुप्पट आहे, म्हणजेच पृथ्वीवर पाणी जमिनीच्या दुप्पट आहे.\",\"topic\":\"शिलावरण आणि जलावरण\",\"part\":2,\"bloom\":\"evaluate\",\"figure_image\":\"24\\/021_102.jpg\"},{\"q\":\"पृथ्वीच्या पृष्ठभागाचा सुमारे किती भाग जमिनीचा आहे?\",\"options\":[\"१\\/२ भाग\",\"१\\/३ भाग\",\"१\\/४ भाग\",\"२\\/३ भाग\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की पृथ्वीच्या पृष्ठभागाचा सुमारे १\\/३ भाग जमिनीचा आहे.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जमिनीच्या सलग व मोठ्या भागास काय म्हणतात?\",\"options\":[\"मैदान\",\"बेट\",\"खंड\",\"डोंगर\"],\"answer\":2,\"explain\":\"जमिनीच्या सलग व मोठ्या भागास \'खंड\' असे म्हणतात.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीवरील जमीन एकूण किती खंडांमध्ये विभागली आहे?\",\"options\":[\"पाच\",\"सहा\",\"सात\",\"आठ\"],\"answer\":2,\"explain\":\"पृथ्वीवरील जमीन सात खंडांमध्ये विभागली आहे.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता खंड सर्वात मोठा आहे?\",\"options\":[\"आफ्रिका\",\"आशिया\",\"ऑस्ट्रेलिया\",\"युरोप\"],\"answer\":1,\"explain\":\"आशिया हा जगातील सर्वात मोठा खंड आहे.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"क्षेत्रफळाच्या दृष्टीने सर्वात लहान खंड कोणता?\",\"options\":[\"अंटार्क्टिका\",\"दक्षिण अमेरिका\",\"ऑस्ट्रेलिया\",\"उत्तर अमेरिका\"],\"answer\":2,\"explain\":\"ऑस्ट्रेलिया हा सर्वात लहान खंड आहे.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जमिनीच्या उंचसखलपणामुळे तिला जे विशिष्ट आकार प्राप्त होतात, त्यांना काय म्हणतात?\",\"options\":[\"भूरूपे\",\"जलावरण\",\"खंड\",\"महासागर\"],\"answer\":0,\"explain\":\"जमिनीच्या उंचसखलपणामुळे प्राप्त होणाऱ्या विशिष्ट आकारांना \'भूरूपे\' म्हणतात.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला सपाट जमिनीचा मोठा भाग दिसत असेल, तर ते खालीलपैकी कोणते भूरूप असू शकते?\",\"options\":[\"टेकडी\",\"डोंगर\",\"मैदान\",\"पर्वत\"],\"answer\":2,\"explain\":\"मैदान हे सपाट जमिनीचे एक उदाहरण आहे, जे भूरूपांमध्ये येते.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"एका पर्यटकाने आशिया, युरोप आणि आफ्रिका या तिन्ही ठिकाणी प्रवास केला. त्याने एकूण किती खंडांना भेट दिली?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"सात\"],\"answer\":1,\"explain\":\"आशिया, युरोप आणि आफ्रिका हे तिन्ही स्वतंत्र खंड आहेत.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता गट केवळ खंडांची नावे दर्शवतो?\",\"options\":[\"आशिया, मैदान, डोंगर\",\"युरोप, आफ्रिका, ऑस्ट्रेलिया\",\"टेकडी, मैदान, डोंगर\",\"अंटार्क्टिका, भूरूपे, खंड\"],\"answer\":1,\"explain\":\"युरोप, आफ्रिका आणि ऑस्ट्रेलिया ही तिन्ही खंडांची नावे आहेत.\",\"topic\":\"भूरूपे\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, जमिनीबद्दल कोणते विधान सत्य आहे?\",\"options\":[\"पृथ्वीवरील सर्व जमीन सलग आहे.\",\"जमीन समुद्राकडे सर्वत्र सारख्या उंचीची असते.\",\"जमिनीच्या उंचसखलपणामुळे भूरूपे तयार होतात.\",\"पृथ्वीचा २\\/३ भाग जमि