:[\"डोंगाळ भागात\",\"वाळवंटात\",\"किनारपट्टीवर\",\"जमिनीच्या मध्यभागी\"],\"answer\":2,\"explain\":\"सामुद्रधुनी हे किनारपट्टीवर तयार होणारे एक जलरूप आहे.\",\"topic\":\"महासागर आणि जलरूपे\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते जलरूप किनारपट्टीवर तयार होणाऱ्या आकाराचे उदाहरण आहे?\",\"options\":[\"आखात\",\"पर्वत\",\"ढग\",\"जमीन\"],\"answer\":0,\"explain\":\"मजकुरात आखात हे किनारपट्टीवर तयार होणाऱ्या जलरूपाचे उदाहरण म्हणून दिले आहे.\",\"topic\":\"महासागर आणि जलरूपे\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीवरील बहुतांश पाणी पिण्यासाठी थेट वापरता येत नाही, याचे मजकुराच्या आधारे कारण काय?\",\"options\":[\"ते जमिनीखाली आहे\",\"ते बर्फाच्या स्वरूपात आहे\",\"ते खारे आहे\",\"ते खूप खोल आहे\"],\"answer\":2,\"explain\":\"बहुतांश पाणी महासागरात असून ते खारे असते, म्हणून ते थेट वापरता येत नाही.\",\"topic\":\"महासागर आणि जलरूपे\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"महासागर आणि किनारपट्टीवरील जलरूपे यांच्यातील योग्य संबंध ओळखा.\",\"options\":[\"जलरूपे महासागरापेक्षा मोठी असतात\",\"जलरूपे महासागराचेच भाग असतात\",\"महासागर हे जलरूपांचे भाग असतात\",\"जलरूपांचा महासागराशी संबंध नसतो\"],\"answer\":1,\"explain\":\"मजकुराच्या शेवटच्या ओळीनुसार, ही जलरूपे महासागराचेच भाग आहेत.\",\"topic\":\"महासागर आणि जलरूपे\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जमिनीवरून वाहणाऱ्या जलरूपांपैकी सर्वात लहान जलरूप कोणते?\",\"options\":[\"नदी\",\"ओढा\",\"ओहळ\",\"उपनदी\"],\"answer\":2,\"explain\":\"पाठातील माहितीनुसार, ओहळ हे सर्वात लहान जलरूप असते.\",\"topic\":\"सरोवर, हिम आणि भूजल\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"समुद्रावर तरंगणाऱ्या बर्फाच्या खूप मोठ्या तुकड्यांना काय म्हणतात?\",\"options\":[\"हिमनदी\",\"हिमनग\",\"धबधबा\",\"सरोवर\"],\"answer\":1,\"explain\":\"समुद्रावर तरंगणाऱ्या बर्फाच्या मोठ्या तुकड्यांना हिमनग म्हणतात.\",\"topic\":\"सरोवर, हिम आणि भूजल\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जमिनीच्या सखल भागात नैसर्गिकरीत्या पाणी साठून तयार झालेल्या मोठ्या जलाशयाला काय म्हणतात?\",\"options\":[\"तळे\",\"ओढा\",\"सरोवर\",\"विहीर\"],\"answer\":2,\"