m\":\"understand\"},{\"q\":\"पंचांनी \'नाबाद\' निर्णय दिल्यावर सचिन तेंडुलकर यांनी काय केले?\",\"options\":[\"ते खेळत राहिले\",\"त्यांनी पंचांशी वाद घातला\",\"ते स्वतःहून पॅव्हेलियनमध्ये परतले\",\"त्यांनी गोलंदाजाला विचारले\"],\"answer\":2,\"explain\":\"नाबाद घोषित असूनही सचिन तेंडुलकर स्वतःहून मैदानातून पॅव्हेलियनमध्ये परतले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"सचिन तेंडुलकर यांनी स्वतःहून बाद होऊन परतण्याचा निर्णय का घेतला?\",\"options\":[\"कारण त्यांना खेळायचा कंटाळा आला होता\",\"कारण त्यांना माहीत होते की चेंडूचा स्पर्श बॅटला झाला आहे\",\"कारण प्रेक्षक ओरडत होते\",\"कारण पंचांनी त्यांना तसे सांगितले होते\"],\"answer\":1,\"explain\":\"चेंडूचा स्पर्श आपल्या बॅटला झाला आहे हे माहीत असल्याने त्यांनी हा निर्णय घेतला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"या घटनेतून सचिन तेंडुलकर यांचे कोणते महत्त्वाचे मूल्य दिसून येते?\",\"options\":[\"शौर्य\",\"दयाळूपणा\",\"प्रामाणिकपणा\",\"चिकाटी\"],\"answer\":2,\"explain\":\"पंचांचा निर्णय बाजूने असूनही सत्याची साथ देणे हा प्रामाणिकपणा आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"झेल पकडल्यानंतर गोलंदाजाने काय केले?\",\"options\":[\"तो आनंदाने नाचू लागला\",\"त्याने पंचांकडे अपील केले\",\"त्याने चेंडू फेकून दिला\",\"त्याने सचिनला बाद व्हायला सांगितले\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की झेल पकडल्यावर गोलंदाजाने पंचांकडे अपील केले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"ही घटना सामन्याच्या कोणत्या टप्प्यावर घडली?\",\"options\":[\"सामन्याच्या शेवटच्या षटकात\",\"सामन्याच्या मध्यंतरात\",\"सुरुवातीच्याच एका षटकात\",\"सामना संपल्यानंतर\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की ही घटना सुरुवातीच्याच एका षटकात घडली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही सचिन तेंडुलकर यांच्या जागी असता आणि तुम्हाला माहीत असते की तुम्ही बाद आहात, तर प्रामाणिकपणा जपण्यासाठी तुम्ही काय केले असते?