opic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"संत गाडगेबाबा लोकांना स्वच्छता कशी करावी हे कशा प्रकारे दाखवून देत?\",\"options\":[\"चित्रे काढून\",\"फक्त सांगून\",\"प्रत्यक्ष कृतीतून\",\"पुस्तके लिहून\"],\"answer\":2,\"explain\":\"स्वच्छता कशी करावी हे संत गाडगेबाबा प्रत्यक्ष कृतीतून दाखवून देत असत.\",\"topic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"राष्ट्रसंत तुकडोजीमहाराज यांनी स्वच्छतेचे महत्त्व कोणत्या ग्रंथातून सांगितले आहे?\",\"options\":[\"दासबोध\",\"ज्ञानेश्वरी\",\"गाथा\",\"ग्रामगीता\"],\"answer\":3,\"explain\":\"राष्ट्रसंत तुकडोजीमहाराज यांनी ग्रामगीतेतून स्वच्छतेचे महत्त्व सांगितले आहे.\",\"topic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"तुकडोजी महाराजांच्या काव्यपंक्तीनुसार, ग्रामसफाईमध्ये कोणत्या गोष्टींची सफाई करणे अपेक्षित आहे?\",\"options\":[\"फक्त घरांची\",\"नाली आणि मोरी\",\"फक्त बागांची\",\"फक्त मंदिरांची\"],\"answer\":1,\"explain\":\"\'मिळोनी करावी ग्रामसफाई । नाली, मोरी ठायीठायी ।\' या ओळींतून नाली आणि मोरीच्या सफाईचा उल्लेख येतो.\",\"topic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खुदावाडीत प्रत्येक घरासाठी काय बांधण्यात आले?\",\"options\":[\"विहीर\",\"स्वच्छतागृह\",\"गोठा\",\"अंगण\"],\"answer\":1,\"explain\":\"गावकऱ्यांनी स्वच्छतेसाठी प्रत्येक घरासाठी स्वच्छतागृह बांधले.\",\"topic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात डाव्या बाजूला बसलेले आणि हातात गाडगे घेतलेले संत कोण आहेत?\",\"options\":[\"संत तुकाराम\",\"संत गाडगेबाबा\",\"राष्ट्रसंत तुकडोजीमहाराज\",\"संत एकनाथ\"],\"answer\":1,\"explain\":\"चित्रात डाव्या बाजूला संत गाडगेबाबांचे छायाचित्र आहे.\",\"topic\":\"श्रमदानातून ग्रामसफाई\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"24\\/043_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील दोन्ही महापुरुषांच्या कार्यामध्ये कोणता समान धागा दिसून येतो?\",\"options\":[\"व्यापार करणे\",\"ग्रामस्वच्छता आणि लोकजागृती\",\"युद्ध करणे\",\"परदेशात जाणे\"],\"answer\":1,\"explain\":\"दोन्ही संतांन