remember\"},{\"q\":\"दिलेल्या आकृतीत \'RF\' हे अक्षर कोणत्या ठिकाणासाठी वापरले आहे?\",\"options\":[\"रस्ता\",\"राखीव वने\",\"रेल्वे फाटा\",\"रांग\"],\"answer\":1,\"explain\":\"आकृतीमध्ये \'RF\' हे चिन्ह राखीव वने (Reserved Forest) दर्शवण्यासाठी वापरले आहे.\",\"topic\":\"चिन्हे व खुणांचा वापर\",\"part\":8,\"bloom\":\"remember\",\"figure_image\":\"24\\/052_101.jpg\"},{\"q\":\"दिलेल्या आकृतीनुसार, \'किल्ला\' दर्शवण्यासाठी कोणते चिन्ह वापरले आहे?\",\"options\":[\"PO हे अक्षर\",\"नांगरासारखे चिन्ह\",\"लाल रंगाची बुरुज असलेली चौकोनी आकृती\",\"तीन वक्र रेषा\"],\"answer\":2,\"explain\":\"आकृतीमध्ये किल्ल्यासाठी लाल रंगाचे बुरुज असलेले चिन्ह दिले आहे.\",\"topic\":\"चिन्हे व खुणांचा वापर\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"24\\/052_103.jpg\"},{\"q\":\"तुम्हाला नकाशात \'PO\' हे अक्षर दिसले, तर त्याचा अर्थ काय होतो?\",\"options\":[\"पोलीस चौकी\",\"टपाल कार्यालय\",\"बंदर\",\"किल्ला\"],\"answer\":1,\"explain\":\"PO म्हणजे Post Office म्हणजेच टपाल कार्यालय होय.\",\"topic\":\"चिन्हे व खुणांचा वापर\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला नकाशात पिण्याच्या पाण्याचे ठिकाण (विहीर) शोधायचे असेल, तर तुम्ही खालीलपैकी कोणते चिन्ह शोधाल?\",\"options\":[\"हिरवे गवत\",\"निळा भरीव गोल\",\"काळा भरीव गोल\",\"गुलाबी रेषा\"],\"answer\":1,\"explain\":\"आकृतीनुसार विहिरीसाठी निळा भरीव गोल हे चिन्ह वापरले जाते.\",\"topic\":\"चिन्हे व खुणांचा वापर\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"नकाशात \'स्थानिक उंची\' दर्शवण्यासाठी कशाचा वापर केला जातो?\",\"options\":[\"त्रिकोण आणि त्यासमोर दिलेली संख्या\",\"फक्त वर्तुळ\",\"फक्त चौकोन\",\"फक्त रेषा\"],\"answer\":0,\"explain\":\"स्थानिक उंची दर्शवण्यासाठी त्रिकोण आणि त्यासमोर उंचीची संख्या (उदा. २००) दिली जाते.\",\"topic\":\"चिन्हे व खुणांचा वापर\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"नकाशातील \'युद्धभूमी\' दर्शवण्यासाठी कोणत्या खुणेचा वापर केला जातो?\",\"options\":[\"दोन एकमेकांना छेदणाऱ्या तलवारी\",\"एक मोठी विहीर\",\"एक सरळ रस्ता\",\"एक मोठा किल्ला\"],\"answer\":0,\"explain\":\"युद्धभूमी दर्शवण्यासाठी दोन तलवा