यासाठी\",\"उंची व खोलीतील फरक दाखवण्यासाठी\",\"रस्ते दाखवण्यासाठी\"],\"answer\":2,\"explain\":\"उंची आणि खोली यांमधील तफावत स्पष्ट करण्यासाठी रंगांच्या विविध छटांचा वापर होतो.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"प्राकृतिक रचना नकाशात दाखवण्याच्या पद्धतींमुळे आपल्याला कशाची माहिती मिळते?\",\"options\":[\"जमिनीचा उंच-सखलपणा\",\"गावातील घरांची संख्या\",\"जंगलातील प्राण्यांची नावे\",\"हवेचा दाब\"],\"answer\":0,\"explain\":\"प्राकृतिक रचनेमुळे जमिनीचे स्वरूप आणि तिचा उंच-सखलपणा समजण्यास मदत होते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला नकाशात एखादा किल्ला किंवा रुग्णालय दाखवायचे असेल, तर तुम्ही खालीलपैकी काय वापराल?\",\"options\":[\"मोठा रंगीत पट्टा\",\"सांकेतिक चिन्हे\",\"केवळ शब्दांची यादी\",\"काहीही वापरणार नाही\"],\"answer\":1,\"explain\":\"विशिष्ट वास्तू किंवा ठिकाणे दाखवण्यासाठी सांकेतिक चिन्हांचा वापर करणे सोयीचे असते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"नकाशात उंचीसाठी गडद रंग आणि कमी उंचीसाठी फिकट रंग वापरणे, हे कोणत्या घटकाचे उदाहरण आहे?\",\"options\":[\"सांकेतिक खुणा\",\"सांकेतिक चिन्हे\",\"उंची व खोलीसाठी रंगांचा वापर\",\"भूपृष्ठाची ओळख\"],\"answer\":2,\"explain\":\"हे उंचीनुसार रंगांच्या वापराचे थेट उदाहरण आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"नकाशात सांकेतिक खुणांचा वापर केल्यामुळे कोणता फायदा होतो?\",\"options\":[\"नकाशा वाचणे कठीण होते\",\"नकाशात खूप जागा लागते\",\"नकाशातील माहिती समजणे सोपे होते\",\"नकाशा चुकीचा दिसतो\"],\"answer\":2,\"explain\":\"चिन्हे आणि खुणांमुळे नकाशातील माहिती अचूक आणि सहजपणे समजते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती गोष्ट प्राकृतिक नकाशात भूपृष्ठाची रचना समजून घेण्यास मदत करत नाही?\",\"options\":[\"रंगांचा वापर\",\"सांकेतिक चिन्हे\",\"प्राकृतिक रचना पद्धती\",\"नकाशाचा कागद\"],\"answer\":3,\"explain\":\"नकाशाचा कागद हा केवळ आधार आहे, तो भूपृष्ठाची रचना स्पष्ट करत नाही.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"नकाशात \'चिन्हे\' आणि \'खुणा\' यांमध्ये कोणता मुख्य फरक असू शकतो?\",\"options\":[\"चिन्हे ही चित्रात्मक असतात तर खुणा भूमितीय आकृत्यांसारख्या असतात\",\"चिन्हे केवळ रंगांसाठी वापरतात\",\"खुणा फक्त उंचीसाठी वापरतात\",\"दोन्हीमध्ये काहीही फरक नसतो\"],\"answer\":0,\"explain\":\"सांकेतिक चिन्हे ही सहसा वस्तूच्या लहान रूपातील चित्र असते, तर खुणा भूमितीय आकारांच्या स्वरूपात असतात.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28');
INSERT INTO `ep_topic_packs` VALUES (21608,24,5,'EVS Part 1','mr','ओळख भारताची','[\"भारत हा एक विशाल देश आहे ज्यात विविध नद्या, पर्वत, पठारे, मैदाने आणि बेटे आहेत.\",\"उत्तरेकडील सीमा हिमालय पर्वतांनी बनलेली आहे.\",\"दक्षिणेकडील भागात अरबी समुद्र, बंगाल उपसागर आणि हिंदी महासागर आहेत.\",\"भारताला तीन बाजूंनी पाण्याने वेढलेले आहे, त्यामुळे त्याला ‘द्वीपकल्प’ म्हणतात.\",\"गंगा, यमुना, गोदावरी, नर्मदा, कावेरी या प्रमुख नद्या भारतात वाहतात.\",\"हिमालयात उगम पावणाऱ्या नद्यांचा प्रवाह दक्षिणेकडे जातो.\",\"पर्वतांमध्ये हिमालय, सह्याद्री, कोंकण आणि पश्चिम घाट आहेत.\",\"पठारे म्हणजे उंच सपाट प्रदेश, जसे की थार वाळवंट आणि पश्चिम घाटातील पठारे.\",\"भारताचे प्रमुख बेटसमूह लक्षद्वीप, अंदमान-निकोबार आणि कोकण बेट आहेत.\",\"हवामान विविधतेमुळे वनस्पती, प्राणी आणि पिकेही विविध आहेत.\",\"उत्तर भारतात गहू प्रमुख पिक, दक्षिण भारतात भात प्रमुख पिक.\",\"मध्य भारतात ज्वारीचे उत्पादन जास्त.\",\"राज्यांची क्षेत्रफळे वेगवेगळी आहेत – राजस्थान सर्वात मोठे, गोवा सर्वात लहान.\",\"राज्यांची राजधान्या दिल्ली, मुंबई, चेन्नई, कोलकाता इत्यादी.\",\"राज्यांमध्ये विविध भाषा, सण आणि परंपरा आहेत.\",\"भारताचे भूगोल समजण्यासाठी नकाशा अभ्यासणे महत्त्वाचे आहे.\"]','[{\"q\":\"दिलेल्या नकाशात प्रामुख्याने काय दाखवले आहे?\",\"options\":[\"भारतातील रस्ते\",\"भारतातील विविध नद्या\",\"भारतातील शहरे\",\"भारतातील जंगले\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की, या नकाशात भारतातील विविध नद्या दाखवल्या आहेत.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार आपला देश कशामुळे समृद्ध आहे?\",\"options\":[\"केवळ नद्यांमुळे\",\"केवळ पर्वतांमुळे\",\"नद्या, पर्वत व पठारे यामुळे\",\"केवळ पठारांमुळे\"],\"answer\":2,\"explain\":\"विविध नद्या, पर्वत व पठारे यांनी आपला देश समृद्ध आहे असे उताऱ्यात म्हटले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"नद्यांची नावे आपण नकाशाव्यतिरिक्त कोठे ऐकतो किंवा वाचतो?\",\"options\":[\"गणित विषयाच्या पुस्तकात\",\"देशभक्तीपर गीतांत\",\"खेळांच्या नियमावलीत\",\"परदेशी कथांमध्ये\"],\"answer\":1,\"explain\":\"उताऱ्यात उल्लेख आहे की काही नद्यांची नावे देशभक्तीपर गीतांतही येतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"नकाशात दिलेल्या नावांपैकी परिचयाची नावे शोधून त्यांना कोणती खूण (Symbol) करण्यास सांगितले आहे?\",\"options\":[\"चौकट (Square)\",\"त्रिकोण (Triangle)\",\"गोल (O)\",\"फुुली (X)\"],\"answer\":2,\"explain\":\"उताऱ्यात नकाशामधील ओळखीच्या नावांना \'O\' (गोल) करण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यातील माहितीवरून \'नकाशाशी मैत्री\' या कृतीचा मुख्य उद्देश काय असावा?\",\"options\":[\"नकाशात रंग भरणे\",\"नकाशातील भौगोलिक नावांची ओळख करून घेणे\",\"नकाशा फाडणे\",\"नकाशाची छपाई करणे\"],\"answer\":1,\"explain\":\"नकाशातील नावे वाचणे आणि ती कोठे आहेत याचा विचार करणे म्हणजे भौगोलिक ओळख करून घेणे होय.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला नकाशात \'हिमालय\' हे नाव दिसले, तर उताऱ्यातील वर्गीकरणानुसार ते कोणत्या गटात येईल?\",\"options\":[\"नदी\",\"पठार\",\"पर्वत\",\"समुद्र\"],\"answer\":2,\"explain\":\"उताऱ्यात नद्या, पर्वत व पठारे यांचा उल्लेख आहे; हिमालय हा पर्वत आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"नकाशात दिलेल्या नावांपैकी कोणती नावे तुमच्या परिचयाची आहेत हे शोधणे, ही कृती कशावर आधारित आहे?\",\"options\":[\"केवळ कल्पनेवर\",\"तुमच्या पूर्वज्ञानावर आणि वाचनावर\",\"केवळ गणितावर\",\"केवळ चित्रावर\"],\"answer\":1,\"explain\":\"ती नावे कोठे वाचलीत किंवा ऐकलीत याचा विचार करण्यास सांगितले आहे, जे पूर्वज्ञानावर आधारित असते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात दिलेल्या \'समृद्ध\' या शब्दाचा अर्थ भौगोलिक संदर्भात काय होतो?\",\"options\":[\"देशात खूप पैसा असणे\",\"देशात विविध नैसर्गिक भूरूपे असणे\",\"देशात खूप लोकसंख्या असणे\",\"देशात खूप कारखाने असणे\"],\"answer\":1,\"explain\":\"नद्या, पर्वत व पठारे यांच्या उपलब्धतेमुळे देशाला समृद्ध म्हटले आहे, म्हणजेच नैसर्गिक विविधता.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"देशभक्तीपर गीतांमधील नद्यांची नावे नकाशात शोधल्यामुळे काय साध्य होईल?\",\"options\":[\"गाणे पाठ होईल\",\"नकाशातील नद्यांचे स्थान समजण्यास मदत होईल\",\"गाणे म्हणता येईल\",\"नकाशा खराब होईल\"],\"answer\":1,\"explain\":\"वाचलेली किंवा ऐकलेली नावे नकाशात शोधल्याने त्यांचे भौगोलिक स्थान निश्चित समजते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"नकाशातील नावांना गोल (O) करण्याच्या सूचनेवरून विद्यार्थ्यांच्या कोणत्या कौशल्याचा विकास होतो?\",\"options\":[\"गायन कौशल्य\",\"नकाशा वाचन आणि निरीक्षण कौशल्य\",\"धावण्याचे कौशल्य\",\"स्वयंपाकाचे कौशल्य\"],\"answer\":1,\"explain\":\"नकाशातील विशिष्ट नावे शोधून त्यांना खूण करणे हे निरीक्षण आणि वाचन कौशल्याचा भाग आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"उत्तरेकडील मैदानी प्रदेशात कोणत्या प्रमुख नदीचे खोरे आहे?\",\"options\":[\"नर्मदा\",\"गंगा\",\"गोदावरी\",\"कावेरी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील प्रश्नानुसार उत्तरेकडील मैदानी प्रदेशात गंगा नदीचे खोरे आढळते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"सिंधू नदीला येऊन मिळणाऱ्या नद्यांचा उगम कोठे होतो?\",\"options\":[\"सह्याद्री पर्वत\",\"हिमालय पर्वत\",\"सातपुडा पर्वत\",\"अरवली पर्वत\"],\"answer\":1,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे सिंधू नदीस मिळणाऱ्या नद्या हिमालयात उगम पावतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"भारताच्या किती बाजूंना जलभाग (पाणी) पसरलेला आहे?\",\"options\":[\"दोन\",\"चार\",\"तीन\",\"एक\"],\"answer\":2,\"explain\":\"मजकुरात भारताच्या तीनही बाजूस असलेल्या जलभागाचे निरीक्षण करण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"नद्यांच्या प्रवाह मार्गाचे निरीक्षण केल्यास आपल्याला कशाची माहिती मिळते?\",\"options\":[\"जमिनीचा उतार\",\"जमिनीची सुपीकता\",\"पाण्याचे तापमान\",\"नदीची खोली\"],\"answer\":0,\"explain\":\"नद्यांच्या प्रवाहावरून त्या प्रदेशातील जमिनीचा उतार कोणत्या दिशेला आहे हे समजते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता बेटांचा समूह भारताचा भाग म्हणून नकाशात दर्शवला आहे?\",\"options\":[\"श्रीलंका\",\"मालदीव\",\"लक्षद्वीप\",\"जावा\"],\"answer\":2,\"explain\":\"मजकुरात लक्षद्वीप, अंदमान आणि निकोबार या भारतीय बेटांचा उल्लेख आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"कोरोमंडल किनाऱ्याला जाऊन मिळणाऱ्या नद्या शोधण्यासाठी तुम्ही नकाशात कोणत्या दिशेला पाहाल?\",\"options\":[\"उत्तर\",\"दक्षिण-पूर्व (पूर्व किनारा)\",\"पश्चिम\",\"वायव्य\"],\"answer\":1,\"explain\":\"कोरोमंडल किनारा भारताच्या पूर्व भागात असून तेथे प्रमुख नद्या समुद्राला मिळतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"नकाशात \'खाड्या\' शोधताना त्या प्रामुख्याने कोठे आढळतील?\",\"options\":[\"पर्वतांच्या शिखरावर\",\"मैदानी प्रदेशाच्या मध्यभागी\",\"भारताच्या किनारपट्टीच्या भागात\",\"वाळवंटी प्रदेशात\"],\"answer\":2,\"explain\":\"खाड्या या समुद्र आणि जमीन जिथे मिळते त्या किनारपट्टीच्या भागात असतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"गंगा, नर्मदा आणि गोदावरी या नद्यांच्या अभ्यासातून नकाशात काय शोधता येते?\",\"options\":[\"नद्यांची लांबी\",\"नद्यांचा प्रवाह मार्ग\",\"नद्यांमधील मासे\",\"नद्यांवरील धरणे\"],\"answer\":1,\"explain\":\"मजकुरात या नद्यांच्या प्रवाह मार्गाचे निरीक्षण करण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला सिंधू नदीच्या उपनद्यांची वाहण्याची दिशा ठरवायची असेल, तर तुम्ही काय कराल?\",\"options\":[\"नदीच्या खोऱ्यातील जमिनीचा उतार पाहू\",\"नदीची खोली मोजू\",\"नदीतील पाण्याचे प्रमाण पाहू\",\"नकाशाचा रंग बदलू\"],\"answer\":0,\"explain\":\"नदीच्या वाहण्याची दिशा ही जमिनीच्या उतारावर अवलंबून असते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"अंदमान आणि निकोबार हे काय आहेत?\",\"options\":[\"पर्वत रांगा\",\"बेटांचे समूह\",\"वाळवंटी प्रदेश\",\"नद्यांची खोरी\"],\"answer\":1,\"explain\":\"मजकुरात अंदमान आणि निकोबार यांचा उल्लेख बेटांचे समूह म्हणून केला आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"नकाशात दिलेल्या पर्वत श्रेण्या आणि डोंगर यांच्या नावांवरून आपल्याला भारताच्या कोणत्या रूपाची माहिती मिळते?\",\"options\":[\"राजकीय\",\"सांस्कृतिक\",\"प्राकृतिक (Physical)\",\"आर्थिक\"],\"answer\":2,\"explain\":\"पर्वत, डोंगर, नद्या ही भारताची प्राकृतिक रूपे आहेत.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"नकाशात सरोवरे शोधण्यासाठी तुम्ही कोणत्या खुणांचा वापर कराल?\",\"options\":[\"उंच पर्वत दर्शवणाऱ्या रेषा\",\"निळ्या रंगाचे पाण्याचे साठे\",\"काळ्या रंगाचे ठिपके\",\"हिरव्या रंगाचे पट्टे\"],\"answer\":1,\"explain\":\"नकाशात जलसाठे (सरोवरे) सामान्यतः निळ्या रंगाने दर्शवले जातात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"भारतीय भूखंडाच्या तीन दिशांना पाण्याने व्यापलेल्या व दक्षिणेकडे निमुळत्या होत जाणाऱ्या भागास काय म्हणतात?\",\"options\":[\"भारतीय बेट\",\"भारतीय द्वीपकल्प\",\"भारतीय पठार\",\"भारतीय मैदान\"],\"answer\":1,\"explain\":\"पाण्याने तीन बाजूंनी वेढलेल्या आणि दक्षिणेकडे निमुळत्या होणाऱ्या भागाला \'भारतीय द्वीपकल्प\' म्हणतात.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"भारताच्या हवामानात विविधता आढळण्याचे मुख्य कारण काय आहे?\",\"options\":[\"केवळ नद्यांची संख्या जास्त आहे\",\"देशाचा मोठा विस्तार आणि समुद्रसपाटीपासूनच्या उंचीतील फरक\",\"केवळ विविध भाषा बोलल्या जातात\",\"केवळ सण-उत्सव साजरे केले जातात\"],\"answer\":1,\"explain\":\"देशाचा मोठा विस्तार आणि समुद्रसपाटीपासूनच्या उंचीतील ८०० मीटरपेक्षा जास्त फरक यामुळे हवामानात विविधता आढळते.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"भारताची उत्तरेकडील सीमा कोणत्या नैसर्गिक घटकाने तयार झाली आहे?\",\"options\":[\"अरबी समुद्र\",\"थारचे वाळवंट\",\"हिमालय पर्वतरांगा\",\"सह्याद्री पर्वत\"],\"answer\":2,\"explain\":\"भारताची उत्तरेकडील सीमा हिमालयासारख्या अतिउंच पर्वतरांगांनी तयार झाली आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"उत्तर भारतातून दक्षिण भारतात प्रवास करताना मुख्य पिकांमध्ये कोणता बदल प्रामुख्याने दिसून येईल?\",\"options\":[\"गहू ऐवजी भात हे प्रमुख पीक दिसेल\",\"भात ऐवजी गहू हे प्रमुख पीक दिसेल\",\"ज्वारी ऐवजी बाजरी हे प्रमुख पीक दिसेल\",\"कोणताही बदल दिसणार नाही\"],\"answer\":0,\"explain\":\"उत्तर भारतात गहू हे प्रमुख पीक आहे, तर दक्षिण भारतात भात हे प्रमुख पीक आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"जर एखादा शेतकरी मध्यभारतात शेती करत असेल, तर पाठ्यपुस्तकातील माहितीनुसार तो कोणत्या पिकाचे उत्पादन मोठ्या प्रमाणावर घेईल?\",\"options\":[\"नारळ\",\"गहू\",\"ज्वारी\",\"सफरचंद\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार मध्यभारतात ज्वारीचे उत्पादन मोठ्या प्रमाणावर होते.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"हवामानातील विविधतेचा सजीवांवर कोणता परिणाम होतो?\",\"options\":[\"केवळ मानवाच्या आहारात बदल होतो\",\"केवळ प्राण्यांच्या संख्येत घट होते\",\"वनस्पती, प्राणी व पक्ष्यांमध्ये मोठ्या प्रमाणावर विविधता आढळते\",\"सजीवांवर कोणताही परिणाम होत नाही\"],\"answer\":2,\"explain\":\"हवामानातील विविधतेमुळे वनस्पती, प्राणी व पक्ष्यांमध्येही मोठ्या प्रमाणावर विविधता पाहायला मिळते.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"भारतातील समुद्रसपाटीपासूनच्या उंचीतील फरक किती मीटरपेक्षा जास्त आहे?\",\"options\":[\"५०० मीटर\",\"१००० मीटर\",\"८०० मीटर\",\"२०० मीटर\"],\"answer\":2,\"explain\":\"भारतात समुद्रसपाटीपासून उंचीतील फरक ८०० मीटरपेक्षा जास्त आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या गोष्टीवर भौगोलिक विविधतेचा परिणाम झालेला आढळत नाही?\",\"options\":[\"लोकजीवन व संस्कृती\",\"चालीरिती व परंपरा\",\"आहार व पेहराव\",\"ग्रहांची संख्या\"],\"answer\":3,\"explain\":\"भौगोलिक विविधतेचा परिणाम जीवनमान, संस्कृती, आहार, पेहराव यांवर होतो, पण ग्रहांच्या संख्येवर होत नाही.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात कोणत्या प्रकारचा भौगोलिक प्रदेश दर्शवलेला आहे?\",\"options\":[\"वाळवंटी प्रदेश\",\"मैदानी प्रदेश\",\"वन प्रदेश\",\"दलदलीचा प्रदेश\"],\"answer\":2,\"explain\":\"चित्रामध्ये दाट झाडी आणि जंगलाचा भाग दिसत असल्याने तो \'वन प्रदेश\' आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"24\\/056_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील प्रदेशात राहणाऱ्या लोकांच्या वाहतुकीसाठी खालीलपैकी कोणता प्राणी सर्वात उपयुक्त ठरेल?\",\"options\":[\"उंट\",\"हत्ती\",\"घोडा\",\"बैल\"],\"answer\":0,\"explain\":\"चित्रामध्ये वाळवंटी प्रदेश आणि उंट दिसत आहेत, जे तेथील वाहतुकीसाठी उपयुक्त असतात.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"24\\/056_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील भूप्रदेशाचे निरीक्षण केल्यास तो भारताच्या कोणत्या प्राकृतिक रचनेचा भाग वाटतो?\",\"options\":[\"पर्वतीय प्रदेश\",\"मैदानी प्रदेश\",\"बेटांचा समूह\",\"उंच पठार\"],\"answer\":1,\"explain\":\"चित्रामध्ये सपाट जमीन आणि गवत दिसत असल्याने तो \'मैदानी प्रदेश\' आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"24\\/056_103.jpg\"},{\"q\":\"किनारपट्टीच्या प्रदेशात राहणाऱ्या लोकांच्या आहारात प्रामुख्याने कोणत्या पिकाचा समावेश असेल?\",\"options\":[\"गहू\",\"ज्वारी\",\"भात\",\"बाजरी\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार किनारपट्टीच्या प्रदेशात भात हे प्रमुख पीक आहे.\",\"topic\":\"भारताची प्राकृतिक रचना\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"भारताचा कोणता नकाशा पाठ्यपुस्तकात अभ्यासासाठी दिला आहे?\",\"options\":[\"प्राकृतिक नकाशा\",\"राजकीय नकाशा\",\"हवामान नकाशा\",\"लोकसंख्या नकाशा\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील मजकुरात \'भारताच्या राजकीय नकाशाचे निरीक्षण करा\' असे स्पष्ट म्हटले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नकाशात लाल रंगाच्या अक्षरांनी लिहिलेली नावे कोणती क्षेत्रे दर्शवतात?\",\"options\":[\"घटकराज्ये\",\"राजधान्या\",\"संघराज्य क्षेत्रे\",\"जिल्हे\"],\"answer\":2,\"explain\":\"नकाशातील सूची आणि मजकुरावरून स्पष्ट होते की लाल अक्षरातील नावे संघराज्य क्षेत्रे (केंद्रशासित प्रदेश) आहेत.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या नकाशाचे निरीक्षण केल्यास, भारताच्या सर्वात उत्तरेला कोणता भाग दिसतो?\",\"options\":[\"महाराष्ट्र\",\"तमिळनाडू\",\"लडाख\",\"गुजरात\"],\"answer\":2,\"explain\":\"नकाशात सर्वात वरच्या (उत्तर) बाजूला लडाख हे क्षेत्र दाखवले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"apply\",\"figure_image\":\"24\\/057_101.jpg\"},{\"q\":\"दिलेल्या नकाशात आकारमानाने सर्वात मोठे दिसणारे राज्य कोणते आहे?\",\"options\":[\"उत्तर प्रदेश\",\"महाराष्ट्र\",\"राजस्थान\",\"मध्य प्रदेश\"],\"answer\":2,\"explain\":\"नकाशातील क्षेत्राच्या विस्तारावरून राजस्थान हे सर्वात मोठे राज्य असल्याचे समजते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"24\\/057_101.jpg\"},{\"q\":\"भारताच्या अतिपूर्वेकडील राज्यांपैकी खालीलपैकी कोणते राज्य आहे?\",\"options\":[\"अरुणाचल प्रदेश\",\"गोवा\",\"पंजाब\",\"केरळ\"],\"answer\":0,\"explain\":\"नकाशात पूर्वेकडे पाहिल्यास अरुणाचल प्रदेश हे अतिपूर्वेकडील राज्य असल्याचे दिसते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नकाशाच्या सूचीनुसार, घटकराज्यांची राजधानी कोणत्या चिन्हाने दर्शवली आहे?\",\"options\":[\"लाल ठिपका\",\"काळा भरीव ठिपका (●)\",\"दुहेरी वर्तुळ\",\"त्रिकोण\"],\"answer\":1,\"explain\":\"नकाशाच्या सूचीमध्ये घटकराज्यांच्या राजधानीसाठी काळा भरीव ठिपका (●) वापरला आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"भारताच्या सर्वात दक्षिणेला असणारे राज्य कोणते?\",\"options\":[\"हिमाचल प्रदेश\",\"तमिळनाडू\",\"गुजरात\",\"आसाम\"],\"answer\":1,\"explain\":\"नकाशात सर्वात खालच्या (दक्षिण) टोकाला तमिळनाडू हे राज्य आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नकाशात \'नवी दिल्ली\' या नावाभोवती कोणते विशेष चिन्ह आहे?\",\"options\":[\"काळा ठिपका\",\"पोकळ वर्तुळ\",\"दुहेरी वर्तुळ (◎)\",\"चौकोन\"],\"answer\":2,\"explain\":\"नवी दिल्ली ही देशाची राजधानी असल्याने ती दुहेरी वर्तुळाने (◎) दर्शवली आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला नकाशात राजस्थान राज्य रंगवायचे असेल, तर मजकुरात कोणता रंग सुचवला आहे?\",\"options\":[\"लाल\",\"निळा\",\"हिरवा\",\"पिवळा\"],\"answer\":3,\"explain\":\"मजकुरात \'आकारमानाने मोठे असणारे राज्य पिवळ्या रंगाने रंगवा\' असे सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"नकाशातील सूचीवरून \'आंतरराष्ट्रीय सीमा\' आणि \'राज्य सीमा\' यांच्यातील फरक कसा ओळखता येईल?\",\"options\":[\"रंगावरून\",\"रेषेच्या प्रकारावरून (जाड-ठळक विरुद्ध तुटक)\",\"अक्षरांच्या आकारावरून\",\"फक्त नावावरून\"],\"answer\":1,\"explain\":\"सूचीमध्ये आंतरराष्ट्रीय सीमेसाठी ठळक रेषा आणि बिंदू, तर राज्य सीमेसाठी तुटक रेषा वापरली आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"भारताची राजधानी कोणती आहे?\",\"options\":[\"मुंबई\",\"दिल्ली\",\"जयपूर\",\"पणजी\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, दिल्ली ही भारताची राजधानी आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"क्षेत्रफळाच्या दृष्टीने भारतातील सर्वात मोठे राज्य कोणते?\",\"options\":[\"महाराष्ट्र\",\"मध्यप्रदेश\",\"राजस्थान\",\"गोवा\"],\"answer\":2,\"explain\":\"क्षेत्रफळाच्या दृष्टीने राजस्थान हे भारतातील सर्वात मोठे राज्य आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"भारतातील सर्वात कमी क्षेत्रफळ असलेले राज्य कोणते?\",\"options\":[\"गोवा\",\"सिक्कीम\",\"त्रिपुरा\",\"केरळ\"],\"answer\":0,\"explain\":\"गोवा हे भारतातील सर्वात कमी क्षेत्रफळ असलेले राज्य आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"भारत हे कोणत्या प्रकारचे राष्ट्र आहे?\",\"options\":[\"हुकूमशाही राष्ट्र\",\"राजेशाही राष्ट्र\",\"लोकशाही प्रजासत्ताक राष्ट्र\",\"साम्यवादी राष्ट्र\"],\"answer\":2,\"explain\":\"पाठाच्या सुरुवातीलाच नमूद केले आहे की भारत एक लोकशाही प्रजासत्ताक राष्ट्र आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते राज्याचे भौगोलिक वैशिष्ट्य नाही?\",\"options\":[\"भूपृष्ठ\",\"जलरूपे\",\"वने\",\"सण व उत्सव\"],\"answer\":3,\"explain\":\"सण व उत्सव हे सामाजिक\\/सांस्कृतिक वैशिष्ट्य आहे, भौगोलिक नाही.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"राज्याची सामाजिक आणि सांस्कृतिक वैशिष्ट्ये अभ्यासताना खालीलपैकी कोणत्या गोष्टीचा विचार केला जातो?\",\"options\":[\"नृत्यप्रकार\",\"नद्या\",\"पर्वत\",\"हवामान\"],\"answer\":0,\"explain\":\"नृत्यप्रकार हे सामाजिक व सांस्कृतिक वैशिष्ट्यांमध्ये येते.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एखाद्या राज्याची माहिती मिळवण्यासाठी तुम्ही खालीलपैकी कोणत्या साधनाची मदत घेऊ शकता?\",\"options\":[\"खेळणी\",\"इंटरनेट\",\"कथा कादंबरी\",\"चित्रपट\"],\"answer\":1,\"explain\":\"पाठात माहिती मिळवण्यासाठी इंटरनेट, वर्तमानपत्रे, मासिके इत्यादींचा वापर करण्यास सांगितले आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"भारतीय महावाळवंट प्रामुख्याने कोणत्या राज्यात येते?\",\"options\":[\"महाराष्ट्र\",\"गुजरात\",\"राजस्थान\",\"मध्यप्रदेश\"],\"answer\":2,\"explain\":\"भारतीय महावाळवंट (थारचे वाळवंट) प्रामुख्याने राजस्थान राज्यात येते.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"क्षेत्रफळाच्या बाबतीत महाराष्ट्र राज्याचा भारतात कितवा क्रमांक लागतो?\",\"options\":[\"पहिला\",\"दुसरा\",\"तिसरा\",\"चौथा\"],\"answer\":2,\"explain\":\"राजस्थान व मध्यप्रदेश नंतर महाराष्ट्र राज्याचा तिसरा क्रमांक लागतो.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"क्षेत्रफळाच्या उतरत्या क्रमाने (मोठ्याकडून लहानाकडे) राज्यांचा कोणता गट योग्य आहे?\",\"options\":[\"राजस्थान, महाराष्ट्र, मध्यप्रदेश\",\"राजस्थान, मध्यप्रदेश, महाराष्ट्र\",\"महाराष्ट्र, मध्यप्रदेश, राजस्थान\",\"मध्यप्रदेश, राजस्थान, महाराष्ट्र\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार राजस्थान (१), मध्यप्रदेश (२) आणि महाराष्ट्र (३) असा क्रम आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रातील पहिल्या प्रश्नानुसार, आपल्या राज्याच्या शेजारील नवीन राज्य कोणत्या साली तयार झाले?\",\"options\":[\"२०१०\",\"२०१२\",\"२०१४\",\"२०१६\"],\"answer\":2,\"explain\":\"चित्रातील पहिल्या प्रश्नात २०१४ या सालाचा उल्लेख आहे.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"24\\/058_101.jpg\"},{\"q\":\"दिलेल्या चित्रात \'जरा डोके चालवा\' या शीर्षकाखाली एकूण किती प्रश्न विचारले आहेत?\",\"options\":[\"१\",\"२\",\"३\",\"४\"],\"answer\":2,\"explain\":\"चित्रात १, २ आणि ३ असे तीन स्वतंत्र प्रश्न विचारले आहेत.\",\"topic\":\"करून पाहा\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"24\\/058_101.jpg\"},{\"q\":\"लक्षद्वीप बेटे कोणत्या समुद्रात आहेत?\",\"options\":[\"अरबी समुद्र\",\"बंगालचा उपसागर\",\"हिंदी महासागर\",\"मृत समुद्र\"],\"answer\":0,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की लक्षद्वीप बेटे अरबी समुद्रात आहेत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"बंगालच्या उपसागरात खालीलपैकी कोणती बेटे आहेत?\",\"options\":[\"लक्षद्वीप\",\"अंदमान आणि निकोबार\",\"श्रीलंका\",\"मालदीव\"],\"answer\":1,\"explain\":\"अंदमान आणि निकोबार बेटे बंगालच्या उपसागरात आहेत असे उताऱ्यात दिले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"भारतातील विविध प्रदेशांनुसार कशामध्ये फरक आढळतो?\",\"options\":[\"फक्त लोकसंख्या\",\"पिकांचे उत्पादन\",\"फक्त हवामान\",\"फक्त भाषा\"],\"answer\":1,\"explain\":\"भारतातील विविध प्रदेशानुसार पिकांच्या उत्पादनात फरक आढळतो असे उताऱ्यात सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"महाराष्ट्राच्या किनाऱ्याच्या रक्षणासाठी बेटांवर काय बांधले गेले?\",\"options\":[\"मोठी शहरे\",\"कारखाने\",\"किल्ले\",\"बाजारपेठा\"],\"answer\":2,\"explain\":\"किनाऱ्याच्या रक्षणासाठी काही बेटांवर किल्ले बांधले गेले, ज्यांना जलदुर्ग म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"चहा, कॉफी यांसारख्या वस्तू कोठे उत्पादित होतात हे समजून घेण्यासाठी कशाचा वापर करणे योग्य ठरेल?\",\"options\":[\"गोष्टीचे पुस्तक\",\"नकाशा\",\"शब्दकोश\",\"दैनंदिनी\"],\"answer\":1,\"explain\":\"पिकांचे उत्पादन कोठे होते हे नकाशावरून समजून घेता येते असे उताऱ्यात सुचवले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"ऐतिहासिक जलदुर्ग प्रामुख्याने कोणत्या किनारपट्टीवर पाहायला मिळतात?\",\"options\":[\"गुजरात किनारपट्टी\",\"मलबार किनारपट्टी\",\"कोकण किनारपट्टी\",\"कोरोमंडल किनारपट्टी\"],\"answer\":2,\"explain\":\"कोकण किनाऱ्यावर जलदुर्ग अनेक ठिकाणी पहावयास मिळतात असे उताऱ्यात दिले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"भारताच्या संरक्षणाच्या दृष्टीने कशाची स्थाने अत्यंत महत्त्वाची आहेत?\",\"options\":[\"शहरांची\",\"पिकांची\",\"बेटांची\",\"बाजारपेठांची\"],\"answer\":2,\"explain\":\"अरबी समुद्र आणि बंगालच्या उपसागरातील बेटांची स्थाने संरक्षणाच्या दृष्टीने महत्त्वाची आहेत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"\'जलदुर्ग\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"जमिनीवरील किल्ला\",\"डोंगरावरील किल्ला\",\"समुद्रातील किल्ला\",\"हवेतील किल्ला\"],\"answer\":2,\"explain\":\"समुद्रातील बेटांवर बांधलेल्या किल्ल्यांना जलदुर्ग म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात कोणता ऐतिहासिक जलदुर्ग दाखवला आहे?\",\"options\":[\"सिंधुदुर्ग\",\"प्रतापगड\",\"जंजिरा\",\"पन्हाळा\"],\"answer\":2,\"explain\":\"चित्राच्या खाली \'जलदुर्ग : जंजिरा\' असे नाव स्पष्टपणे दिले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\",\"figure_image\":\"24\\/058_104.jpg\"},{\"q\":\"दिलेल्या चित्रातील किल्ल्याचे स्थान कोठे आहे?\",\"options\":[\"दाट जंगलात\",\"उंच डोंगरावर\",\"समुद्राच्या पाण्यात\",\"मोठ्या मैदानात\"],\"answer\":2,\"explain\":\"चित्रात जंजिरा हा किल्ला चहूबाजूने पाण्याने वेढलेला म्हणजेच समुद्रात दिसत आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"24\\/058_104.jpg\"},{\"q\":\"भारताच्या मुख्य भूमीशिवाय इतर बेटांचे महत्त्व काय आहे?\",\"options\":[\"ती फक्त पर्यटनासाठी आहेत\",\"ती देशाच्या संरक्षणाच्या दृष्टीने महत्त्वाची आहेत\",\"ती फक्त मासेमारीसाठी आहेत\",\"ती फक्त शेतीसाठी आहेत\"],\"answer\":1,\"explain\":\"उताऱ्यात बेटांचे स्थान देशाच्या संरक्षणाच्या दृष्टीने अत्यंत महत्त्वाचे असल्याचे सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"उताऱ्यात पिकांच्या उदाहरणांमध्ये कोणत्या पेयांचा (beverages) उल्लेख आला आहे?\",\"options\":[\"दूध आणि सरबत\",\"चहा आणि कॉफी\",\"लिंबू पाणी आणि ताक\",\"नारळ पाणी आणि ज्यूस\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीला चहा आणि कॉफी या वस्तूंचा उल्लेख पिकांची उदाहरणे म्हणून आला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"नागपूरची संत्री कोणत्या शहराला पाठवण्यासाठी मार्ग निश्चित करण्यास सांगितले आहे?\",\"options\":[\"मुंबई\",\"बिकानेर\",\"कोलकाता\",\"दिल्ली\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील पाचव्या प्रश्नानुसार नागपूरची संत्री बिकानेरला पाठवायची आहेत.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"सफरचंदाचे उत्पादन होणाऱ्या राज्यांच्या नावाभोवती नकाशात कोणती खूण करायची आहे?\",\"options\":[\"चौकोन (☐)\",\"त्रिकोण (△)\",\"गोल (O)\",\"काटकोन (L)\"],\"answer\":2,\"explain\":\"चौथ्या प्रश्नात सफरचंदाचे उत्पादन होणाऱ्या राज्यांच्या नावाभोवती \'O\' (गोल) करण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"महाराष्ट्रातील कांदा कोणत्या राज्यात पाठवण्यासाठी नकाशावर मार्ग निश्चित करायचा आहे?\",\"options\":[\"अरुणाचल प्रदेश\",\"पश्चिम बंगाल\",\"राजस्थान\",\"केरळ\"],\"answer\":0,\"explain\":\"सातव्या प्रश्नानुसार महाराष्ट्रातील कांदा अरुणाचल प्रदेश या राज्यात पाठवायचा आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"पश्चिम बंगाल राज्यात खालीलपैकी कोणती उत्पादने पाठवण्यासाठी मार्ग निश्चित करायचा आहे?\",\"options\":[\"चहा आणि संत्री\",\"केसर आणि सफरचंद\",\"कॉफी आणि आंबे\",\"कांदा आणि लवंग\"],\"answer\":2,\"explain\":\"सहाव्या प्रश्नात पश्चिम बंगाल राज्यात कॉफी व आंबे पाठवण्याबद्दल विचारले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"नकाशात \'मार्ग गिरवा\' या सूचनेचा मुख्य उद्देश काय आहे?\",\"options\":[\"नकाशात रंग भरण्यासाठी\",\"एका ठिकाणाहून दुसऱ्या ठिकाणी जाण्याचा रस्ता समजण्यासाठी\",\"राज्यांच्या सीमा ठरवण्यासाठी\",\"नकाशावर चित्रे काढण्यासाठी\"],\"answer\":1,\"explain\":\"वस्तू एका राज्यातून दुसऱ्या राज्यात नेण्यासाठी सोयीचा मार्ग समजून घेणे हा याचा उद्देश आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"केसर आणि लवंग आपल्या राज्यात आणण्यासाठी नकाशावर कोणती कृती करण्यास सांगितले आहे?\",\"options\":[\"राज्यांना नावे देणे\",\"चित्रे काढणे\",\"मार्ग निश्चित करून गिरवणे\",\"केवळ राज्यांना गोल करणे\"],\"answer\":2,\"explain\":\"प्रश्न १ आणि ३ मध्ये केसर आणि लवंग आणण्यासाठी मार्ग निश्चित करून गिरवण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"चहाचे उत्पादन भारतातील कोणत्या राज्यांत होते, हे शोधण्यासाठी तुम्ही नकाशात काय पाहाल?\",\"options\":[\"राज्यांची लोकसंख्या\",\"चहा उत्पादक क्षेत्रांची चिन्हे किंवा सूची\",\"केवळ राज्यांच्या राजधानीची नावे\",\"समुद्राची खोली\"],\"answer\":1,\"explain\":\"नकाशात विशिष्ट उत्पादने शोधण्यासाठी त्या उत्पादनांच्या चिन्हांचा वापर केला जातो.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला नकाशात सफरचंदाचे उत्पादन होणारी राज्ये शोधायची असतील, तर तुम्ही प्रामुख्याने भारताच्या कोणत्या दिशेला पाहाल?\",\"options\":[\"दक्षिण भारत\",\"उत्तर भारत\",\"पश्चिम भारत\",\"वाळवंटी भाग\"],\"answer\":1,\"explain\":\"भारतात सफरचंदाचे उत्पादन प्रामुख्याने उत्तरेकडील थंड राज्यांत होते, जे नकाशावरून स्पष्ट होते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरात खालीलपैकी कोणत्या पिकाचा उल्लेख \'उत्पादन होणारी राज्ये शोधा\' यासाठी केला आहे?\",\"options\":[\"केसर\",\"सफरचंद\",\"कांदा\",\"संत्री\"],\"answer\":1,\"explain\":\"प्रश्न ४ मध्ये सफरचंदाचे उत्पादन कोणकोणत्या राज्यात होते ते शोधण्यास सांगितले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"नकाशाशी मैत्री या घटकातील प्रश्नांवरून असे लक्षात येते की, भारतात विविध उत्पादने एका ठिकाणाहून दुसऱ्या ठिकाणी नेण्यासाठी कशाचा वापर होतो?\",\"options\":[\"केवळ विमानाचा\",\"वाहतुकीच्या मार्गांचा\",\"केवळ पायवाटांचा\",\"टेलिफोनचा\"],\"answer\":1,\"explain\":\"सर्व प्रश्नांमध्ये \'मार्ग निश्चित करा\' असे म्हटले आहे, जे वाहतुकीचे महत्त्व दर्शवते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"हर्ष आणि तनिष्का कोणत्या शहरात राहतात?\",\"options\":[\"चेन्नई\",\"मुंबई\",\"अंदमान\",\"निकोबार\"],\"answer\":1,\"explain\":\"उताऱ्याच्या पहिल्या वाक्यात नमूद केल्याप्रमाणे हर्ष व तनिष्का मुंबईला राहतात.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"हर्ष आणि तनिष्का यांना कोणत्या बेटांना भेट द्यायची आहे?\",\"options\":[\"लक्षद्वीप बेटे\",\"माजुली बेटे\",\"अंदमान आणि निकोबार बेटे\",\"श्रीलंका बेटे\"],\"answer\":2,\"explain\":\"त्यांना अंदमान आणि निकोबार बेटे पाहायची आहेत असे उताऱ्यात दिले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"अंदमान आणि निकोबार बेटांना जाण्यापूर्वी ते कोठे जाणार आहेत?\",\"options\":[\"दिल्ली\",\"चेन्नई\",\"कोलकाता\",\"बेंगळुरू\"],\"answer\":1,\"explain\":\"ते प्रथम चेन्नई येथे मामाकडे जाणार आहेत आणि त्यानंतर बेटांना भेट देणार आहेत.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"चेन्नई येथे कोणाचे घर आहे?\",\"options\":[\"काकांचे\",\"मावशीचे\",\"मामाचे\",\"आत्याचे\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे \'चेन्नई येथे मामाकडे जाणार आहेत\' असे म्हटले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"हर्ष आणि तनिष्का यांच्या प्रवासाचा योग्य क्रम कोणता असेल?\",\"options\":[\"चेन्नई -> मुंबई -> अंदमान\",\"मुंबई -> अंदमान -> चेन्नई\",\"मुंबई -> चेन्नई -> अंदमान आणि निकोबार\",\"अंदमान -> चेन्नई -> मुंबई\"],\"answer\":2,\"explain\":\"ते मुंबईत राहतात, तिथून चेन्नईला जातील आणि मग बेटांना भेट देतील.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"प्रवासाचे मार्ग शोधण्यासाठी त्यांना कोणत्या साधनाचा वापर करायला सांगितला आहे?\",\"options\":[\"होकायंत्र\",\"नकाशा\",\"रोजनिशी\",\"छायाचित्र\"],\"answer\":1,\"explain\":\"उताऱ्यात पृष्ठ ४९ वरील \'नकाशात\' दिलेल्या मार्गांचा अवलंब करण्यास सांगितले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"आपल्या देशातील वनस्पती, प्राणी आणि पक्षी यांच्यात काय आढळते?\",\"options\":[\"समानता\",\"विविधता\",\"कमतरता\",\"एकसारखेपणा\"],\"answer\":1,\"explain\":\"उताऱ्यातील \'हे नेहमी लक्षात ठेवा\' या भागात देशातील वनस्पती, प्राणी व पक्षी यांच्यात विविधता असल्याचे सांगितले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिक विविधता आपल्याला कोठे सहज पाहता येते?\",\"options\":[\"शहरांमध्ये\",\"कारखान्यांमध्ये\",\"वनप्रदेशात\",\"रस्त्यांवर\"],\"answer\":2,\"explain\":\"वनप्रदेशात गेल्यावर आपल्याला ही विविधता सहज पाहता येते असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"हर्ष आणि तनिष्का यांना मदत करण्यासाठी तुम्हाला नकाशात काय करावे लागेल?\",\"options\":[\"नकाशा रंगवणे\",\"मार्ग गिरवणे\",\"नवीन नकाशा काढणे\",\"शहरांची नावे लिहिणे\"],\"answer\":1,\"explain\":\"उताऱ्यात \'नकाशात हे मार्ग गिरवून तुम्ही त्यांना मदत कराल का?\' असा प्रश्न विचारला आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"देशातील विविधतेबाबत आपली कोणती जबाबदारी उताऱ्यात सांगितली आहे?\",\"options\":[\"विविधता नष्ट करणे\",\"विविधतेकडे दुर्लक्ष करणे\",\"विविधता जपली पाहिजे\",\"विविधता बदलली पाहिजे\"],\"answer\":2,\"explain\":\"उताऱ्याच्या शेवटी \'ही विविधता आपण जपली पाहिजे\' असे स्पष्टपणे सांगितले आहे.\",\"topic\":\"काय करावे बरे?\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"भारताचे वर्णन प्रामुख्याने कशाच्या आधारे समजून घेतले जाते?\",\"options\":[\"गोष्टींच्या पुस्तकावरून\",\"नकाशाच्या आधारे\",\"केवळ चित्रांवरून\",\"रेडिओवरील बातम्यांवरून\"],\"answer\":1,\"explain\":\"पाठाच्या सारांशानुसार, भारताचे वर्णन नकाशाच्या आधारे समजून घेतले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या गोष्टींचा समावेश \'भूपृष्ठे व जलरूपे\' या गटात होतो?\",\"options\":[\"रस्ते आणि रेल्वे\",\"सण आणि उत्सव\",\"पर्वत आणि नद्या\",\"भाषा आणि पेहराव\"],\"answer\":2,\"explain\":\"पर्वत हे भूपृष्ठाचे आणि नद्या हे जलरूपाचे उदाहरण आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"भारतातील विविध भाषा, पेहराव आणि सण यांची माहिती आपण कशी समजून घेतली?\",\"options\":[\"केवळ पाठांतर करून\",\"कृतीतून\",\"फक्त ऐकून\",\"दूरदर्शन पाहून\"],\"answer\":1,\"explain\":\"भारतातील विविधता कृतीतून समजून घेतली असल्याचे मजकुरात नमूद आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"पाठात कोणत्या प्रकारच्या उत्पादनांची ओळख करून देण्यात आली आहे?\",\"options\":[\"औद्योगिक उत्पादने\",\"कृषी उत्पादने\",\"इलेक्ट्रॉनिक उत्पादने\",\"खेळणी\"],\"answer\":1,\"explain\":\"मजकुरात भारतातील काही कृषी उत्पादनांची ओळख करून घेतल्याचे सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"वाहतुकीचे मार्ग समजून घेतल्यामुळे आपल्याला कशाची माहिती मिळते?\",\"options\":[\"देशातील पिकांची\",\"देशातील भाषांची\",\"देशातील जोडणी आणि प्रवासाच्या साधनांची\",\"देशातील सणांची\"],\"answer\":2,\"explain\":\"वाहतुकीचे मार्ग हे एका ठिकाणाहून दुसऱ्या ठिकाणी जाण्यासाठी आणि जोडणीसाठी महत्त्वाचे असतात.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला भारताची नैसर्गिक रचना अभ्यासायची असेल, तर तुम्ही खालीलपैकी काय पाहाल?\",\"options\":[\"भााषांची यादी\",\"भूपृष्ठे व जलरूपे\",\"सणांची नावे\",\"पेहरावाचे प्रकार\"],\"answer\":1,\"explain\":\"नैसर्गिक रचना समजून घेण्यासाठी भूपृष्ठे आणि जलरूपे यांचा अभ्यास आवश्यक असतो.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"विविध पेहराव आणि सण हे भारताचे काय दर्शवतात?\",\"options\":[\"केवळ गरिबी\",\"केवळ हवामान\",\"सांस्कृतिक विविधता\",\"केवळ लोकसंख्या\"],\"answer\":2,\"explain\":\"पेहराव, सण आणि उत्सव हे भारताच्या विविधतेचे आणि संस्कृतीचे वैशिष्ट्य आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"नकाशाचा वापर करून आपण भारताच्या कोणत्या पैलूची माहिती घेऊ शकतो?\",\"options\":[\"लोकांच्या आवडीनिवडी\",\"भौगोलिक स्थान आणि विस्तार\",\"लोकांचे बोलणे\",\"स्वयंपाकाच्या पद्धती\"],\"answer\":1,\"explain\":\"नकाशा भौगोलिक स्थान, सीमा आणि विस्तार समजून घेण्यास मदत करतो.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता घटक भारताच्या \'वैशिष्ट्ये\' या गटात समाविष्ट होऊ शकतो?\",\"options\":[\"विविध सण आणि उत्सव\",\"केवळ शाळेचे नियम\",\"केवळ घरातील कामे\",\"परदेशातील नद्या\"],\"answer\":0,\"explain\":\"सण, उत्सव, भाषा आणि पेहराव ही भारताची प्रमुख वैशिष्ट्ये आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"कृषी उत्पादने आणि वाहतुकीचे मार्ग यांचा एकत्रित विचार केल्यास काय समजते?\",\"options\":[\"शेतीचा माल बाजारपेठेपर्यंत कसा पोहोचतो\",\"पाऊस कसा पडतो\",\"नद्या कशा वाहतात\",\"सण कसे साजरे होतात\"],\"answer\":0,\"explain\":\"कृषी उत्पादनांची वाहतूक करण्यासाठी वाहतुकीच्या मार्गांची आवश्यकता असते, हे यातून स्पष्ट होते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21609,24,5,'EVS Part 1','mr','आपले घर व पर्यावरण','[\"घर म्हणजे निवारा, अन्न, पाणी, वस्त्र व शिक्षणाची गरज पूर्ण करणारी जागा.\",\"घराचे मुख्य घटक: दारे, खिडक्या, भिंती, छप्पर.\",\"घराचे साहित्य: लाकूड, दगड, माती, चुनखडी, सिमेंट, विटा, काच, लोखंड, वाळू, कापूस.\",\"प्रदेशानुसार घराची रचना बदलते – मैदानी, वाळवंटी, दलदलयुक्त, पर्वतीय, वाळबंटी प्रदेशांमध्ये भिन्न साहित्य व आकार वापरले जातात.\",\"उष्णता, थंडी, वारा, पाऊस व ऊन यांपासून संरक्षण देणारे घर आपल्याला विश्रांती व सुरक्षितता देते.\",\"अ, ब, क घरांचे फरक: आकार, साहित्य व रचना – जंगली प्राण्यांपासून संरक्षणासाठी ‘अ’ घर सर्वात सुरक्षित.\",\"शहरी भागात ‘ब’ घर सर्वात जास्त वापरले जाते कारण ते समाजकंटकांपासून संरक्षण देते.\",\"घर बांधताना नैसर्गिक साधनांचा वापर करून पर्यावरणपूरक घर बनवणे आवश्यक आहे.\",\"बायोगॅस, पवनऊर्जा व सौरऊर्जा यांचा वापर करून ऊर्जा बचत करता येते.\",\"पाण्याचा पुनर्वापर व टाकाऊ वस्तूंचा पुनर्वापर हे पर्यावरणपूरक घराचे महत्त्वाचे गुण आहेत.\",\"घर बांधताना साहित्याची निवड व स्वच्छता राखणे हे प्रदूषण टाळण्यासाठी महत्त्वाचे आहे.\",\"घर बांधताना स्थानिक हवामान व भूभागाचा विचार करून साहित्य व रचना ठरवली जाते.\",\"घर बांधताना बेघर लोकांना निवारा देण्यासाठी शासन विविध योजना चालवते.\",\"नैसर्गिक ऊर्जास्त्रोतांचा वापर वाढवून पर्यावरणाची हानी कमी करता येते.\",\"घराचे डिझाइन व साहित्य हे स्थानिक उपलब्धतेवर अवलंबून असते.\",\"घर बांधताना पर्यावरणपूरक साहित्य व तंत्रज्ञानाचा वापर केल्याने ऊर्जा व पाण्याची बचत होते.\",\"घर बांधताना स्थानिक समुदायाची सहभागिता व जनजागृती आवश्यक आहे.\",\"घर बांधताना वाळू, कोळसा, सिमेंट व विटा यांचा वापर होतो, परंतु पर्यावरणपूरक पर्याय निवडणे चांगले.\",\"घर बांधताना मुख्य ४ साहित्य: लोखंड, सिमेंट, वाळू, विटा.\",\"घर बांधताना आराम, रचना व हवामान या तीन गोष्टींचा विचार करावा.\",\"घरातील सौरऊर्जेने चालणारी उपकरणे: दिवे, पंखे, पाणी पंप इत्यादी.\",\"घर बांधताना पर्यावरणपूरक घराची प्रतिकृती तयार करणे हे शिक्षणाचे महत्त्वाचे कार्य आहे.\",\"घर बांधताना स्थानिक नैसर्गिक साधनांचा वापर करून ऊर्जा व पाण्याची बचत करता येते.\",\"घर बांधताना प्रदूषण टाळण्यासाठी स्वच्छता व पुनर्वापराचे उपाय अवलंबावेत.\",\"घर बांधताना स्थानिक समुदायाची सहभागिता व जनजागृती आवश्यक आहे.\"]','[{\"q\":\"घरांचे निरीक्षण करताना खालीलपैकी कोणत्या बाबीचा विचार करावा असे पाठात सुचवले आहे?\",\"options\":[\"घराचा रंग\",\"घराची रचना\",\"घरातील व्यक्तींची संख्या\",\"घराची किंमत\"],\"answer\":1,\"explain\":\"पाठात घरांचे निरीक्षण करताना त्यांची रचना, आकार आणि साहित्य विचारात घेण्यास सांगितले आहे.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"घरांच्या रचनेत आणि आकारात फरक असण्याचे मुख्य कारण काय असू शकते?\",\"options\":[\"लोकांचे कपडे\",\"परिसरातील हवामान\",\"रस्त्यांची रुंदी\",\"वाहनांची संख्या\"],\"answer\":1,\"explain\":\"परिसराचा आणि हवामानाचा विचार करून घरांची रचना ठरवली जाते.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"शहरी भागात खालीलपैकी कोणत्या प्रकारची घरे प्रामुख्याने आढळतात?\",\"options\":[\"गवताच्या झोपड्या\",\"मातीची छोटी घरे\",\"बहुमजली इमारती\",\"कापडी तंबू\"],\"answer\":2,\"explain\":\"शहरी भागात जागेच्या कमतरतेमुळे आणि उपलब्ध साहित्यामुळे इमारती जास्त आढळतात.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"घरामुळे आपल्याला खालीलपैकी कोणत्या बाबीपासून संरक्षण मिळते?\",\"options\":[\"शाळेतील अभ्यासापासून\",\"खेळाच्या मैदानापासून\",\"ऊन, वारा आणि पाऊस यांपासून\",\"टीव्हीवरील कार्यक्रमांपासून\"],\"answer\":2,\"explain\":\"घर आपल्याला नैसर्गिक आपत्ती आणि हवामानापासून संरक्षण देते.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"प्रवासात घरे पाहताना कोणत्या गोष्टीचे निरीक्षण करण्यास सांगितले आहे?\",\"options\":[\"घराचा नंबर\",\"घराचे नाव\",\"बांधकामाचे साहित्य\",\"घराची बाग\"],\"answer\":2,\"explain\":\"घरांच्या निरीक्षणात वापरलेले बांधकामाचे साहित्य ही महत्त्वाची बाब आहे.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रातील \'अ\' या घराचे छप्पर कोणत्या साहित्यापासून बनवलेले दिसते?\",\"options\":[\"सिमेंट आणि काँक्रीट\",\"लोखंडी पत्रा\",\"गवत किंवा पेंढा\",\"काचेचे तावदान\"],\"answer\":2,\"explain\":\"चित्रात दाखवलेले \'अ\' हे घर झोपडी असून त्याचे छप्पर गवताचे आहे.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"24\\/061_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील \'अ\' प्रकारचे घर सामान्यतः कोणत्या भागात आढळते?\",\"options\":[\"मोठ्या शहरात\",\"ग्रामीण भागात\",\"बर्फाळ प्रदेशात\",\"समुद्राच्या आत\"],\"answer\":1,\"explain\":\"नैसर्गिक साहित्यापासून बनवलेली अशी घरे प्रामुख्याने ग्रामीण भागात दिसतात.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"24\\/061_101.jpg\"},{\"q\":\"घरांचे विविध नमुने कशावरून ठरतात?\",\"options\":[\"घराचा आकार आणि रचना\",\"घरातील फर्निचर\",\"घराचा दरवाजा कोणत्या दिशेला आहे\",\"घराच्या खिडक्यांचा रंग\"],\"answer\":0,\"explain\":\"आकार आणि रचना यावरून घरांचे वेगवेगळे नमुने ओळखले जातात.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"तुमच्या परिसरातील हवामानाचा विचार करून योग्य घर निवडण्यासाठी तुम्ही काय पाहाल?\",\"options\":[\"घराची उंची\",\"घराची सुरक्षितता आणि हवामानाशी सुसंगतता\",\"घराचा रंग\",\"घराचे अंतर\"],\"answer\":1,\"explain\":\"हवामानानुसार योग्य घराची निवड करणे सुरक्षिततेसाठी आवश्यक असते.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"घरांचे निरीक्षण करताना खालीलपैकी कोणती बाब पाठात नमूद केलेली नाही?\",\"options\":[\"रचना\",\"आकार\",\"वापरलेले साहित्य\",\"घरातील लोकांचे नाव\"],\"answer\":3,\"explain\":\"पाठात रचना, आकार आणि साहित्य यांवर लक्ष देण्यास सांगितले आहे, नावावर नाही.\",\"topic\":\"करून पाहा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"घरांचा उपयोग प्रामुख्याने खालीलपैकी कशासाठी होतो?\",\"options\":[\"फक्त खेळण्यासाठी\",\"निवाऱ्यासाठी आणि विश्रांतीसाठी\",\"फक्त जेवण करण्यासाठी\",\"बाहेर फिरण्यासाठी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार घराचा उपयोग प्रामुख्याने निवारा व विश्रांतीसाठी होतो.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"थंडी, ऊन, वारा आणि पाऊस यांपासून संरक्षण होण्यासाठी आपल्याला कशाची गरज असते?\",\"options\":[\"वाहनांची\",\"बागेची\",\"घराची\",\"रस्त्यांची\"],\"answer\":2,\"explain\":\"घर आपल्याला नैसर्गिक घटकांपासून जसे की थंडी, ऊन, वारा आणि पाऊस यांपासून संरक्षण देते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जंगली श्वापदांपासून सुरक्षित राहण्यासाठी घराचा उपयोग होतो, हे विधान कोणत्या बाबीशी संबंधित आहे?\",\"options\":[\"फक्त सजावट\",\"सुरक्षितता\",\"फक्त विश्रांती\",\"सामाजिक कार्य\"],\"answer\":1,\"explain\":\"जंगली श्वापदांपासून संरक्षण मिळवणे ही घराची एक महत्त्वाची सुरक्षिततेची बाजू आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"घरांच्या रचनेमध्ये प्रदेशानुसार बदल होण्याचे मुख्य कारण काय असावे?\",\"options\":[\"लोकांचे कपडे\",\"केवळ घराचा रंग\",\"हवामान व भौगोलिक प्रदेशातील विविधता\",\"घराची उंची\"],\"answer\":2,\"explain\":\"प्रदेशानुसार पावसाचे प्रमाण, वाळवंटी भाग, पर्वतीय भाग यांमुळे घरांच्या रचनेत बदल होतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या नकाशात, जास्त पावसाच्या प्रदेशातील घरांच्या छपरांचे निरीक्षण केल्यास ती कशी दिसतात?\",\"options\":[\"सपाट\",\"उतरती\",\"गोल\",\"छप्पर नसलेली\"],\"answer\":1,\"explain\":\"नकाशातील चित्रांवरून स्पष्ट होते की जास्त पावसाच्या प्रदेशात पाणी वाहून जाण्यासाठी उतरती छपरे असतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"24\\/062_101.jpg\"},{\"q\":\"दिलेल्या तक्त्यातील माहितीनुसार, मैदानी प्रदेशातील घराच्या छतासाठी कोणते साहित्य वापरले जाते?\",\"options\":[\"सिमेंट आणि लोखंड\",\"गवत आणि पाने\",\"लाकूड आणि माती\",\"काच आणि प्लास्टिक\"],\"answer\":2,\"explain\":\"तक्त्यात मैदानी प्रदेशातील धाब्याच्या घराच्या छतासाठी लाकूड व माती वापरल्याचे नमूद केले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"24\\/063_101.jpg\"},{\"q\":\"वाळवंटी प्रदेशात घरांची रचना करताना कोणत्या गोष्टीचा विचार प्रामुख्याने केला जात असेल?\",\"options\":[\"अतिवृष्टी\",\"दलदल\",\"कमी पाऊस आणि उष्णता\",\"बर्फवृष्टी\"],\"answer\":2,\"explain\":\"वाळवंटी प्रदेशात पाऊस कमी असतो, त्यामुळे तेथील घरांची रचना त्या हवामानानुसार असते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या नकाशात, भारताच्या उत्तरेकडील पर्वतीय प्रदेशात (उदा. काश्मीर) कोणत्या प्रकारचे विशेष घर चित्रात दाखवले आहे?\",\"options\":[\"धाब्याचे घर\",\"पाण्यावरील घर (हाऊस बोट)\",\"कुडाचे घर\",\"बहुमजली इमारत\"],\"answer\":1,\"explain\":\"नकाशात काश्मीरमधील दल सरोवरासारख्या भागात हाऊस बोट दाखवली आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"24\\/062_101.jpg\"},{\"q\":\"मैदानी प्रदेशातील धाब्याच्या घराचा आकार कसा असतो?\",\"options\":[\"त्रिकोणी\",\"गोल\",\"आयताकृती\",\"अनियमित\"],\"answer\":2,\"explain\":\"तक्त्यानुसार मैदानी प्रदेशातील धाब्याच्या घराचा आकार आयताकृती असतो.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"24\\/063_101.jpg\"},{\"q\":\"जर एखाद्या प्रदेशात दलदल असेल, तर तेथील घरांची रचना कशी असावी असे तुम्हाला वाटते?\",\"options\":[\"जमिनीच्या आत\",\"दलदलमुक्त व उंचावर\",\"काचेच्या भिंती असलेली\",\"छप्पर नसलेली\"],\"answer\":1,\"explain\":\"दलदलमुक्त प्रदेशात राहण्यासाठी घरांची रचना जमिनीच्या ओलाव्यापासून सुरक्षित असावी लागते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"नकाशातील घरांच्या चित्रांची तुलना केल्यास, मैदानी प्रदेश आणि पर्वतीय प्रदेशातील घरांमध्ये कोणता प्रमुख फरक जाणवतो?\",\"options\":[\"घरांचा रंग\",\"छपरांचा आकार आणि रचना\",\"घराची खिडकी\",\"घराचे नाव\"],\"answer\":1,\"explain\":\"नकाशावरून दिसते की मैदानी भागात सपाट\\/धाब्याची तर पर्वतीय भागात उतरती छपरे असतात.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"24\\/062_101.jpg\"},{\"q\":\"समाजकंटकांपासून सुरक्षित राहण्यासाठी घराचा उपयोग होतो, यात \'समाजकंटक\' म्हणजे कोण?\",\"options\":[\"मित्र\",\"पाहुणे\",\"सुरक्षितता धोक्यात आणणारे लोक\",\"कुटुंबातील सदस्य\"],\"answer\":2,\"explain\":\"समाजकंटक म्हणजे चोरी किंवा नुकसान करणारे लोक, ज्यांच्यापासून घर आपल्याला वाचवते.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"प्रत्येकाला हवा, अन्न, पाणी आणि वस्त्र यांसोबतच कशाची गरज असते?\",\"options\":[\"गाडी\",\"निवारा\",\"दागिने\",\"मोबाईल\"],\"answer\":1,\"explain\":\"पाठातील मजकुरानुसार हवा, अन्न, पाणी, वस्त्र व निवारा या मानवाच्या मूलभूत गरजा आहेत.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"माणसाने घरे बांधताना प्रामुख्याने कशाचा उपयोग केलेला आढळतो?\",\"options\":[\"फक्त सिमेंट आणि लोखंडाचा\",\"परदेशातील साहित्याचा\",\"हवामान व उपलब्ध नैसर्गिक साधनसंपत्तीचा\",\"केवळ प्लास्टिकचा\"],\"answer\":2,\"explain\":\"प्रदेशातील हवामान आणि उपलब्ध नैसर्गिक साधनसंपत्तीनुसार घरांच्या रचनेत विविधता आढळते.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"बेघर असणे ही खालीलपैकी कोणती समस्या आहे?\",\"options\":[\"वैयक्तिक समस्या\",\"कौटुंबिक समस्या\",\"सामाजिक समस्या\",\"राजकीय समस्या\"],\"answer\":2,\"explain\":\"पाठात स्पष्टपणे नमूद केले आहे की बेघर असणे ही एक सामाजिक समस्या आहे.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीनुसार, खालीलपैकी कोणते बेघरपणाचे एक कारण आहे?\",\"options\":[\"जास्त शिक्षण\",\"बेरोजगारी\",\"सहलीला जाणे\",\"नवीन कपडे खरेदी करणे\"],\"answer\":1,\"explain\":\"दिलेल्या आकृतीत (F1) \'बेरोजगारी\' हे बेघरपणाचे एक कारण म्हणून दाखवले आहे.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"24\\/063_102.jpg\"},{\"q\":\"दिलेल्या चित्रात दाखवल्याप्रमाणे, लोक निवाऱ्यासाठी कोणत्या जागेचा वापर करत आहेत?\",\"options\":[\"पडकी इमारत\",\"रेल्वे स्टेशन\",\"पदपथ\",\"बसस्थानक\"],\"answer\":2,\"explain\":\"दिलेल्या चित्रात (F2) लोक पदपथावर निवारा करून राहत असल्याचे दिसत आहे.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"24\\/063_103.jpg\"},{\"q\":\"अनेकांना बेघर व्हावे लागण्याचे मुख्य कारण काय असू शकते?\",\"options\":[\"उपजीविकेचे साधन पुरेसे नसणे\",\"फिरायची आवड असणे\",\"शाळा लांब असणे\",\"पाऊस कमी पडणे\"],\"answer\":0,\"explain\":\"उपजीविकेचे साधन मिळत नसल्यामुळे किंवा ते पुरेसे नसल्यामुळे अनेकांना बेघर व्हावे लागते.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"काही शहरांमध्ये शासनामार्फत बेघरांसाठी काय उपलब्ध केले जाते?\",\"options\":[\"रात्रीनिवारा\",\"मोफत चित्रपट\",\"हॉटेलमधील जेवण\",\"विमानाची तिकिटे\"],\"answer\":0,\"explain\":\"शासन शहरांमध्ये बेघरांसाठी रात्रीनिवाऱ्याची सोय उपलब्ध करून देते.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"घरांच्या रचनेत आणि ते बांधण्यासाठी वापरलेल्या साहित्यात विविधता का आढळते?\",\"options\":[\"केवळ फॅशन म्हणून\",\"हवामानातील बदलांमुळे\",\"दुकानांच्या उपलब्धतेमुळे\",\"लोकांच्या उंचीमुळे\"],\"answer\":1,\"explain\":\"प्रदेशातील हवामानानुसार घरांच्या रचनेत आणि साहित्यात विविधता येते.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"निवारा नसलेले लोक खालीलपैकी कोणत्या ठिकाणी राहताना दिसतात?\",\"options\":[\"पुलाखाली\",\"शाळेच्या वर्गात\",\"मोठ्या दवाखान्यात\",\"बँकेच्या आत\"],\"answer\":0,\"explain\":\"बेघर लोक रस्त्याच्या बाजूला, पदपथावर किंवा पुलाखाली निवारा शोधतात.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"बेघरांना घरे बांधून देण्यासाठी कोण योजना राबवते?\",\"options\":[\"दुकानदार\",\"शासन\",\"विद्यार्थी\",\"परदेशी पर्यटक\"],\"answer\":1,\"explain\":\"शासन बेघर व्यक्तींना घरे बांधून देण्यासाठी अनेक योजना राबवते.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिक आपत्तीचा बेघरपणाशी काय संबंध असू शकतो?\",\"options\":[\"त्यामुळे उत्पन्न वाढते\",\"त्यामुळे घरे बांधणे सोपे जाते\",\"ते बेघरपणाचे एक कारण असू शकते\",\"त्याचा घरांशी काहीही संबंध नसतो\"],\"answer\":2,\"explain\":\"आकृती F1 नुसार नैसर्गिक आपत्ती हे बेघरपणाचे एक महत्त्वाचे कारण आहे.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणते बेघरपणाचे आर्थिक कारण आहे?\",\"options\":[\"मानसिक आजार\",\"नैसर्गिक आपत्ती\",\"अपुरे आर्थिक उत्पन्न\",\"हवामान\"],\"answer\":2,\"explain\":\"अपुरे आर्थिक उत्पन्न हे थेट पैशांशी संबंधित म्हणजेच आर्थिक कारण आहे.\",\"topic\":\"घरांच्या रचनेत विविधता व बेघरपणा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"सिमेंट तयार करण्यासाठी कोणता मूळ स्रोत वापरला जातो?\",\"options\":[\"माती\",\"चुनखडीचा दगड\",\"लोखंड\",\"लाकूड\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील तक्त्यानुसार सिमेंटचा मूळ स्रोत चुनखडीचा दगड आहे.\",\"topic\":\"करून पाहा - बांधकाम साहित्य\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अजितला त्याच्या घरासमोरील बांधकामामुळे प्रामुख्याने कोणत्या गोष्टींचा त्रास होत आहे?\",\"options\":[\"पाणी आणि वीज\",\"वाहतूक आणि गर्दी\",\"आवाज आणि धूळ\",\"दुर्गंधी आणि कचरा\"],\"answer\":2,\"explain\":\"पाठ्यभागात नमूद केल्याप्रमाणे बांधकामामुळे मोठ्या प्रमाणावर आवाज होतो व धूळ पसरते.\",\"topic\":\"करून पाहा - बांधकाम साहित्य\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत \'काच\' या साहित्यासमोर कोणता मूळ स्रोत लिहिला आहे?\",\"options\":[\"चुनखडी\",\"वाळू\",\"पाणी\",\"लोखंड\"],\"answer\":1,\"explain\":\"तक्त्यामध्ये काच या साहित्याचा मूळ स्रोत वाळू असा दिला आहे.\",\"topic\":\"करून पाहा - बांधकाम साहित्य\",\"part\":6,\"bloom\":\"remember\",\"