:0,\"explain\":\"लोकांसाठी राबवण्यात येणाऱ्या शासकीय योजना यशस्वी करण्यामध्ये प्रसारमाध्यमे मदत करतात.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखादी व्यक्ती तुमच्यापासून खूप दूर राहत असेल, तर प्रसारमाध्यमांमुळे काय शक्य झाले आहे?\",\"options\":[\"तिला भेटणे अनिवार्य आहे\",\"तिच्याशी सहज संपर्क साधता येतो\",\"तिला पत्र लिहिणेच गरजेचे आहे\",\"तिच्याशी बोलणे अशक्य आहे\"],\"answer\":1,\"explain\":\"आपल्यापासून दूर असलेल्या व्यक्तींशी सहज संपर्क साधता येतो, हा प्रसारमाध्यमांचा पहिला फायदा आहे.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"आरोग्याविषयी जागरूकता निर्माण करण्यासाठी खालीलपैकी कोणता मार्ग प्रभावी ठरेल?\",\"options\":[\"घरी बसून राहणे\",\"प्रसारमाध्यमांचा वापर करणे\",\"केवळ व्यायाम करणे\",\"काहीही न करणे\"],\"answer\":1,\"explain\":\"आरोग्य, शिक्षण व समाजातील चांगल्या घटनांबाबत प्रसारमाध्यमांमुळे जागरूकता निर्माण होते.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"प्रसारमाध्यमांमुळे पर्यावरणाचे रक्षण करण्यासाठी लोकांमध्ये काय निर्माण होण्यास मदत होते?\",\"options\":[\"भीती\",\"दुर्लक्ष\",\"संवेदनशीलता\",\"राग\"],\"answer\":2,\"explain\":\"पर्यावरण आणि स्वच्छता यांबाबत संवेदनशीलता वाढण्यास प्रसारमाध्यमे मदत करतात.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"समुद्रकिनारी राहणाऱ्या लोकांना वादळाची पूर्वसूचना मिळाल्यास काय होईल?\",\"options\":[\"त्यांना काहीच फरक पडणार नाही\",\"ते सुरक्षित स्थळी जाऊ शकतील\",\"त्यांना भीती वाटेल\",\"ते मासेमारीला जातील\"],\"answer\":1,\"explain\":\"नैसर्गिक आपत्तींची पूर्वकल्पना मिळाल्यामुळे लोक सावध होऊन स्वतःचे रक्षण करू शकतात.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"प्रसारमाध्यमे समाजातील कोणत्या प्रकारच्या घटनांबाबत जागरूकता निर्माण करतात?\",\"options\":[\"केवळ वाईट घटना\",\"केवळ गुन्हेगारी\",\"चांगल्या घटना व प्रसंग\",\"केवळ अफवा\"],\"answer\":2,\"explain\":\"समाजातील चांगल्या घटना तसेच प्रसंगांबाबत जागरूकता निर्माण करण्याचे काम प्रसारमाध्यमे करतात.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"माहितीची देवाणघेवाण जलद गतीने होणे, हे कशामुळे शक्य झाले आहे?\",\"options\":[\"प्रसारमाध्यमांच्या वापरामुळे\",\"केवळ पत्रांमुळे\",\"केवळ प्रवासा मुळे\",\"केवळ पुस्तकांमुळे\"],\"answer\":0,\"explain\":\"प्रसारमाध्यमांमुळे माहिती मिळवण्यासाठी व देण्यासाठी लागणारा वेळ कमी झाला आहे, म्हणजेच ती जलद झाली आहे.\",\"topic\":\"प्रसारमाध्यमांचे चांगले परिणाम\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"दूरदर्शन, संगणक आणि मोबाइल यांच्या अति वापरामुळे कोणत्या अवयवाचे आजार संभवतात?\",\"options\":[\"पाय\",\"डोळे\",\"पोट\",\"दात\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, यांच्या अति वापरामुळे डोळ्यांचे, पाठीचे व श्रवणाचे आजार होतात.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"प्रसारमाध्यमांच्या अति वापरामुळे कोणता मानसिक त्रास होऊ शकतो?\",\"options\":[\"खूप मित्र मिळणे\",\"एकलकोंडेपणा वाढणे\",\"स्मरणशक्ती वाढणे\",\"आनंद मिळणे\"],\"answer\":1,\"explain\":\"अति वापरामुळे मनोविकार आणि एकलकोंडेपणा वाढणे असे त्रास संभवतात.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"माहितीचा दुरुपयोग केल्यामुळे कशावर विपरीत परिणाम होतो?\",\"options\":[\"केवळ हवामानावर\",\"केवळ प्राण्यांवर\",\"समाजाची शांतता व स्वास्थ्य\",\"केवळ झाडांवर\"],\"answer\":2,\"explain\":\"माहितीचा दुरुपयोग करून समाजाची शांतता व स्वास्थ्य बिघडवण्याचे प्रकार घडतात.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"प्रसारमाध्यमांवरील कार्यक्रम सतत पाहिल्यामुळे कशाकडे दुर्लक्ष होते?\",\"options\":[\"जेवणाकडे\",\"मैदानी खेळांकडे\",\"झोपण्याकडे\",\"कपड्यांकडे\"],\"answer\":1,\"explain\":\"विविध कार्यक्रम पाहण्यात वेळ घालवल्याने मैदानी खेळ व शारीरिक क्षमता यांकडे दुर्लक्ष होते.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता आजार प्रसारमाध्यमांच्या अति वापराशी संबंधित आहे?\",\"options\":[\"श्रवणाचे आजार\",\"त्वचेचे आजार\",\"दातांचे आजार\",\"हाडांचे आजार\"],\"answer\":0,\"explain\":\"उताऱ्यात डोळे, पाठ आणि श्रवणाचे (ऐकण्याचे) आजार होतात असे नमूद केले आहे.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मैदानी खेळांकडे दुर्लक्ष झाल्याचा थेट परिणाम कशावर होतो?\",\"options\":[\"आर्थिक स्थितीवर\",\"शारीरिक स्वास्थ्यावर\",\"घराच्या रंगावर\",\"पावसाच्या प्रमाणावर\"],\"answer\":1,\"explain\":\"मैदानी खेळांकडे दुर्लक्ष झाल्याचा विपरीत परिणाम शारीरिक स्वास्थ्यावर होतो.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एखादा मुलगा दिवसभर मोबाईलवर गेम खेळत असेल, तर त्याला कोणता त्रास होण्याची शक्यता आहे?\",\"options\":[\"त्याची उंची वेगाने वाढेल\",\"त्याला पाठीचे आजार होऊ शकतात\",\"त्याची दृष्टी अधिक तीक्ष्ण होईल\",\"त्याला भूक जास्त लागेल\"],\"answer\":1,\"explain\":\"मोबाईलच्या अति वापरामुळे पाठीचे आजार संभवतात.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"इंटरनेटचा वापर करताना कोणती काळजी घेणे आवश्यक आहे असे उताऱ्यावरून वाटते?\",\"options\":[\"माहितीचा दुरुपयोग टाळणे\",\"जास्तीत जास्त वेळ इंटरनेटवर राहणे\",\"मैदानी खेळ पूर्णपणे बंद करणे\",\"केवळ गाणी ऐकणे\"],\"answer\":0,\"explain\":\"माहितीचा दुरुपयोग समाजाची शांतता बिघडवू शकतो, म्हणून तो टाळणे आवश्यक आहे.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"प्रसारमाध्यमांच्या अति वापरामुळे होणारा \'मनोविकार\' हा कोणत्या प्रकारचा परिणाम आहे?\",\"options\":[\"शारीरिक\",\"मानसिक\",\"सामाजिक\",\"आर्थिक\"],\"answer\":1,\"explain\":\"मनोविकार आणि एकलकोंडेपणा हे मानसिक आरोग्याशी संबंधित परिणाम आहेत.\",\"topic\":\"प्रसारमाध्यमांचे हानिकारक परिणाम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"शारीरिक क्षमता टिकवून ठेवण्यासाठी खालीलपैकी कोणता पर्याय योग्य आहे?\",\"options\":[\"दिवसभर दूरदर्शन पाहणे\",\"जास्तीत जास्त वेळ मोबाईल वापरणे\",\"मैदानी खेळांना प्राधान्य देणे\",\"सतत इंटरनेटवर माहिती शोधणे\"],\"answer\":2,\"explain\":\"प्रसारमाध्यमांत व