part\":8,\"bloom\":\"understand\"},{\"q\":\"आमोदच्या आईची काळजी दूर करण्यासाठी त्याने खालीलपैकी कोणती कृती करणे योग्य ठरेल?\",\"options\":[\"आणखी जास्त वेळ टीव्ही पाहणे\",\"मैदानी खेळ खेळणे आणि साधनांचा वापर कमी करणे\",\"संगणकावर नवीन संकेतस्थळे शोधणे\",\"दिवसभर मोबाइलवर गेम खेळणे\"],\"answer\":1,\"explain\":\"साधनांचा अतिरेक टाळून बाहेर पडल्यास त्याची प्रकृती सुधारेल व आईची काळजी दूर होईल.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"माहिती प्रसारण साधनांच्या बाबतीत कोणती गोष्ट टाळावी असे उताऱ्यात सुचवले आहे?\",\"options\":[\"वापर\",\"अतिरेक\",\"खरेदी\",\"दुरुस्ती\"],\"answer\":1,\"explain\":\"साधनांचा अतिरेक होणार नाही याची काळजी घ्यावी असे उताऱ्यात स्पष्ट म्हटले आहे.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"आमोदच्या वागण्यावरून त्याच्या कोणत्या सवयीचे दुष्परिणाम दिसून येत आहेत?\",\"options\":[\"अभ्यासाची सवय\",\"वाचनाची सवय\",\"प्रसार माध्यमांच्या अतिवापराची सवय\",\"जेवणाच्या सवयी\"],\"answer\":2,\"explain\":\"आमोदच्या शारीरिक समस्यांचे मूळ कारण टीव्ही, संगणक आणि मोबाइलचा अतिवापर हे आहे.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील \'तारतम्याने वापर करावा\' या विधानाचा योग्य अर्थ काय?\",\"options\":[\"गरजेनुसार योग्य प्रमाणात वापर करणे\",\"मर्जीप्रमाणे कितीही वापर करणे\",\"वापर पूर्णपणे बंद करणे\",\"दुसऱ्याला वापरायला देणे\"],\"answer\":0,\"explain\":\"तारतम्य म्हणजे योग्य-अयोग्य समजून गरजेनुसार संतुलित वापर करणे.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"ज्या संदेशवहनामध्ये आपण एकमेकांना पाहू आणि ऐकू शकतो, त्याला काय म्हणतात?\",\"options\":[\"केवळ श्राव्य संदेशवहन\",\"दृक्-श्राव्य संदेशवहन\",\"लेखी संदेशवहन\",\"सांकेतिक संदेशवहन\"],\"answer\":1,\"explain\":\"मजकुरात उल्लेख केल्याप्रमाणे, मोबाइलवर एकमेकांना पाहून बोलणे हे दृक्-श्राव्य संदेशवहन आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पूर्वीच्या दूरध्वनीवरून (Telephone) बोलताना कोणती गोष्ट शक्य नव्हती?\",\"options\":[\"आवाज ऐकणे\",\"संभाषण करणे\",\"एकमेकांना पाहणे\",\"संदेश देणे\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे, दूरध्वनीवरून बोलताना आपण एकमेकांना पाहू शकत नव्हतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"मोबाइलवर एकमेकांना पाहून बोलणे कशामुळे शक्य झाले आहे?\",\"options\":[\"माहिती प्रसारणाच्या नवीन तंत्रामुळे\",\"जुन्या पद्धतीमुळे\",\"केवळ आवाजाच्या तंत्रामुळे\",\"पत्रांच्या वापरामुळे\"],\"answer\":0,\"explain\":\"माहिती प्रसारणाच्या नवीन तंत्रामुळे मोबाइलवर आता एकमेकांना पाहणे शक्य झाले आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"संदेशवहनाकरिता कोणत्या तंत्राचा वापर केला जातो, असे पाठाच्या शेवटी सांगितले आहे?\",\"options\":[\"रस्ते वाहतूक तंत्र\",\"अवकाश प्रक्षेपण तंत्र\",\"पाणी शुद्धीकरण तंत्र\",\"शेती तंत्र\"],\"answer\":1,\"explain\":\"संदेशवहनाकरिता अवकाश प्रक्षेपणाचे तंत्र वापरले जाते असा उल्लेख मजकुरात आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"जर तुम्ही तुमच्या मित्राशी व्हिडिओ कॉलवर बोलत असाल, तर तुम्ही कोणत्या प्रकारचे तंत्र वापरत आहात?\",\"options\":[\"केवळ श्राव्य तंत्र\",\"माहिती प्रसारणाचे नवीन तंत्र\",\"जुने दूरध्वनी तंत्र\",\"टपाल सेवा तंत्र\"],\"answer\":1,\"explain\":\"व्हिडिओ कॉलवर एकमेकांना पाहणे हे नवीन तंत्राचे उदाहरण आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"प्रसारमाध्यमांच्या बाबतीत आपण कोणत्या दोन महत्त्वाच्या गोष्टींचा अभ्यास केला?\",\"options\":[\"फक्त प्रसारमाध्यमांचे फायदे\",\"फक्त प्रसारमाध्यमांचे तोटे\",\"प्रसारमाध्यमांचे फायदे व तोटे\",\"प्रसारमाध्यमांची किंमत\"],\"answer\":2,\"explain\":\"पाठाच्या सारांशानुसार आपण प्रसारमाध्यमांचे फायदे व तोटे दोन्ही शिकलो आहोत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते विधान \'दृक्-श्राव्य\' संदेशवहनाचे वैशिष्ट्य दर्शवते?\",\"options\":[\"यात फक्त आवाज ऐकू येतो.\",\"यात फक्त मजकूर वाचता येतो.\",\"यात संभाषण करताना एकमेकांना पाहता येते.\",\"यात संदेश पोहोचायला खूप वेळ लागतो.\"],\"answer\":2,\"explain\":\"दृक्-श्राव्य म्हणजे पाहणे आणि ऐकणे, ज्यामुळे संभाषण करताना व्यक्ती दिसते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"एखाद्या नवीन मोबाइल ॲपद्वारे जगभरात माहिती पसरवणे हे कशाचे उदाहरण आहे?\",\"options\":[\"प्रसारमाध्यम साधनांची ओळख\",\"अवकाश प्रक्षेपणाचा अभाव\",\"केवळ वैयक्तिक पत्रव्यवहार\",\"जुन्या काळातील संदेशवहन\"],\"answer\":0,\"explain\":\"माहिती पसरवण्यासाठी वापरली जाणारी साधने प्रसारमाध्यमांत मोडतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"संदेशवहन आणि प्रसारमाध्यमे या पाठात \'अवकाश प्रक्षेपण\' या विषयाचा संबंध कशाशी जोडला आहे?\",\"options\":[\"विमान प्रवासाशी\",\"संदेशवहनाशी\",\"खेतीकामाशी\",\"स्वयंपाकाशी\"],\"answer\":1,\"explain\":\"मजकुरात \'संदेशवहनाकरिता अवकाश प्रक्षेपणाचे तंत्र\' असा स्पष्ट उल्लेख आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"प्रसारमाध्यमांचा वापर करताना आपण कोणत्या गोष्टीची काळजी घेणे आवश्यक आहे असे मजकुरावरून सुचवले जाते?\",\"options\":[\"त्यांचा वापर पूर्णपणे बंद करणे\",\"त्यांचे केवळ फायदे लक्षात घेणे\",\"त्यांचे फायदे व तोटे ओळखून वापर करणे\",\"त्यांच्या तोट्यांकडे दुर्लक्ष करणे\"],\"answer\":2,\"explain\":\"फायदे आणि तोटे या दोन्ही बाजूंची ओळख असणे महत्त्वाचे आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21614,24,5,'EVS Part 1','mr','पाणी','[\"पाणी हे जीवनाचे मूलभूत स्रोत आहे.\",\"पाण्याचे तीन अवस्थाः घन (बर्फ), द्रव (पाणी), वायू (वाफ).\",\"सांडपाणी म्हणजे घर, उद्योग, कारखाने इथून बाहेर पडणारे पाणी ज्यात घाण व विषारी पदार्थ असतात.\",\"सांडपाण्याची विल्हेवाट लावण्यासाठी शुद्धीकरण केंद्रे वापरली जातात.\",\"शुद्धीकरण प्रक्रियेतील मुख्य टप्पे: निस्पंदन, निर्जंतुकीकरण, ऑक्सिजनीकरण.\",\"निस्पंदनात वाळू, कोळसा, जाड वाळू इत्यादी थर वापरले जातात.\",\"निर्जंतुकीकरणात क्लोरीन किंवा इतर रसायनांचा वापर होतो.\",\"ऑक्सिजनीकरणात पाण्यात हवा खेळवून ऑक्सिजन वाढवला जातो.\",\"पावसाचे पाणी जमिनीत जिरवून भूजल वाढवता येते.\",\"दुष्काळात पाण्याची तुटवड्यामुळे शेती व जनावरांना त्रास होतो.\",\"जलव्यवस्थापन म्हणजे पाणी साठवणे, शुद्धीकरण व योग्य वापर यांची योजना.\",\"सांडपाणी शुद्धीकरण न केल्यास रोग पसरतात.\",\"पाण्यातील सूक्ष्मजीव व विषारी पदार्थ मानवी व प्राण्यांना हानी पोहोचवतात.\",\"पाणी शुद्ध करण्यासाठी कोळसा, वाळू, जाड वाळू यांचा थर तयार केला जातो.\",\"पाण्याच्या शुद्धीकरणासाठी वापरले जाणारे रसायन क्लोरीन आहे.\",\"पाणी शुद्ध केल्यावर ते पिण्यासाठी सुरक्षित होते.\",\"पाणी शुद्धीकरण केंद्रात पाणी प्रथम टाक्यांमध्ये स्थिर ठेवले जाते.\",\"पाणी शुद्धीकरणाचे उद्दिष्ट: निर्जंतुकीकरण व ऑक्सिजनीकरण.\",\"पाण्याचे प्रदूषण टाळण्यासाठी सांडपाण्याचे योग्य व्यवस्थापन आवश्यक आहे.\",\"पाणी शुद्धीकरणाची प्रक्रिया जलस्रोतांपासून सुरू होते.\",\"पाणी शुद्ध केल्यावर ते नद्या, तळी व विहिरींमध्ये परत सोडले जाते.\",\"पाणी शुद्धीकरणात वापरलेल्या थरांची क्रमवारी: जाड वाळू, कोळसा, बारीक वाळू.\",\"पाणी शुद्धीकरणानंतर पाणी स्वच्छ व पारदर्शक होते.\",\"पाणी शुद्धीकरण केंद्रात पाणी निस्पंदनानंतर क्लोरीन मिसळले जाते.\",\"पाणी शुद्धीकरणात ऑक्सिजन वाढवण्यासाठी पंप वापरले जातात.\"]','[{\"q\":\"पाण्यात लाकडाचा भुसा टाकला तर काय होईल?\",\"options\":[\"तो पाण्यात विरघळेल\",\"तो दिसेनासा होईल\",\"तो पाण्यात तरंगत राहील\",\"पाणी अधिक स्वच्छ होईल\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, काही पदार्थ पाण्यात तरंगत राहतात, ज्यामुळे पाणी अस्वच्छ दिसते.\",\"topic\":\"पाण्याचे प्रदूषण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पाणी \'प्रदूषित\' आहे असे आपण कधी म्हणतो?\",\"options\":[\"जेव्हा त्यात साखर विरघळते\",\"जेव्हा त्यात मिसळलेले पदार्थ सजीवांसाठी अपायकारक असतात\",\"जेव्हा पाणी स्वच्छ भांड्यात असते\",\"जेव्हा पाणी नळाला येते\"],\"answer\":1,\"explain\":\"पाण्यात मिसळलेले पदार्थ सजीवांसाठी अपायकारक असले तर ते पाणी प्रदूषित आहे असे म्हणतात.\",\"topic\":\"पाण्याचे प्रदूषण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात पाण्याचे मुख्य स्रोत म्हणून कोणाचा उल्लेख केला आहे?\",\"options\":[\"विहिरी आणि टाक्या\",\"नद्या आणि सरोवरे\",\"समुद्र आणि खाडी\",\"नळ आणि बादल्या\"],\"answer\":1,\"explain\":\"नद्या आणि सरोवरे हे आपले पाण्याचे स्रोत आहेत असे उताऱ्यात नमूद केले आहे