,{\"q\":\"भारताच्या विविध प्रदेशातून लोक मुंबईत येऊन का स्थायिक झाले?\",\"options\":[\"पर्यटनासाठी\",\"हवामानासाठी\",\"रोजगारासाठी\",\"शिक्षणासाठी\"],\"answer\":2,\"explain\":\"कापड उद्योगाच्या भरभराटीमुळे रोजगारासाठी लोक मुंबईत येऊन स्थायिक झाले.\",\"topic\":\"निसर्ग आणि कापड उद्योग केंद्र\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"मुंबई हे भारतातील कोणत्या घडामोडींचे महत्त्वाचे केंद्र बनले आहे?\",\"options\":[\"राजकीय\",\"आर्थिक\",\"धार्मिक\",\"सांस्कृतिक\"],\"answer\":1,\"explain\":\"कापड उद्योगामुळे मुंबई हे भारतातील आर्थिक घडामोडींचे महत्त्वाचे केंद्र बनले.\",\"topic\":\"निसर्ग आणि कापड उद्योग केंद्र\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यातील माहितीवरून, कापड उद्योगाच्या विकासासाठी मुंबईला कोणता नैसर्गिक फायदा मिळाला?\",\"options\":[\"भरपूर पाऊस\",\"मोठी मैदाने\",\"दमट हवामान\",\"खनिज संपत्ती\"],\"answer\":2,\"explain\":\"मुंबईतील दमट हवामान हा कापड उद्योगासाठी मोठा नैसर्गिक फायदा होता.\",\"topic\":\"निसर्ग आणि कापड उद्योग केंद्र\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"जर मुंबईत दमट हवामान नसते, तर उताऱ्यानुसार खालीलपैकी काय घडले नसते?\",\"options\":[\"पाऊस पडला नसता\",\"लांब धाग्याचे कापड तयार करणे सुलभ झाले नसते\",\"लोक तिथे राहायला आले नसते\",\"शेती झाली नसती\"],\"answer\":1,\"explain\":\"दमट हवामानाचा थेट संबंध लांब धाग्याचे कापड तयार करण्याशी जोडला आहे.\",\"topic\":\"निसर्ग आणि कापड उद्योग केंद्र\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"निसर्ग आणि मानवी गरजा यांच्या संबंधाबाबत उताऱ्यातून कोणता संदेश मिळतो?\",\"options\":[\"माणसाने कितीही हव्यास केला तरी निसर्ग तो पूर्ण करतो.\",\"निसर्ग फक्त मुंबईतील लोकांच्या गरजा पूर्ण करतो.\",\"माणसाने गरजा मर्यादित ठेवल्या तरच निसर्ग साथ देईल.\",\"कापड उद्योग हा निसर्गापेक्षा महत्त्वाचा आहे.\"],\"answer\":2,\"explain\":\"माणसाने गरजांना प्राधान्य दिले तरच निसर्ग सर्वांचा सांभाळ करू शकेल, असा संदेश मिळतो.\",\"topic\":\"निसर्ग आणि कापड उद्योग केंद्र\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"हवामानातील बदलानुसार वेगवेगळ्या प्रदेशांत वापरण्यात येणाऱ्या कशामध्ये बदल होतात?\",\"options\":[\"घरांच्या रचनेत\",\"कपड्यांमध्ये\",\"अन्नाच्या चवीत\",\"वाहनांच्या प्रकारात\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे, हवामानातील बदलानुसार कपड्यांमध्ये बदल होतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"वस्तूंची गरज नसताना त्या मिळवण्याची तीव्र इच्छा होणे म्हणजे काय?\",\"options\":[\"गरज\",\"हव्यास\",\"बचत\",\"काटकसर\"],\"answer\":1,\"explain\":\"वस्तूंची गरज नसताना त्या हव्याहव्याशा वाटणे म्हणजे हव्यास होय.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"देशातील वस्त्रांमधील विविधता कशाच्या साहाय्याने सहजपणे समजून घेता येते?\",\"options\":[\"नकाशा\",\"होकायंत्र\",\"दुर्बीण\",\"घड्याळ\"],\"answer\":0,\"explain\":\"देशातील वस्त्रांमधील विविधता नकाशाच्या साहाय्याने समजून घेता येते असे पाठात म्हटले आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या राज्याचा उल्लेख पाठात पोषाखांच्या चित्रांच्या संदर्भात केला आहे?\",\"options\":[\"गुजरात\",\"महाराष्ट्र\",\"पंजाब\",\"कर्नाटक\"],\"answer\":1,\"explain\":\"पाठात जम्मू-काश्मीर, राजस्थान, महाराष्ट्र व केरळ या राज्यांचा उल्लेख आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"आपण वस्तूंचा वापर कसा केला पाहिजे?\",\"options\":[\"इतरांना दाखवण्यासाठी\",\"फॅशन म्हणून\",\"गरजानुसार\",\"हव्यास म्हणून\"],\"answer\":2,\"explain\":\"पाठातील संदेशानुसार आपण वस्तूंचा वापर गरजेनुसार केला पाहिजे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"आपल्या देशातील विविध प्रदेशांना कशाची परंपरा आहे?\",\"options\":[\"वैशिष्ट्यपूर्ण वस्त्रनिर्मितीची\",\"केवळ आधुनिक कपड्यांची\",\"परदेशी वस्त्रांची\",\"वस्त्रे न वापरण्याची\"],\"answer\":0,\"explain\":\"भारतातील विविध प्रदेशांना वैशिष्ट्यपूर्ण वस्त्रनिर्मितीची परंपरा आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"जम्मू-काश्मीर आणि केरळ या राज्यांतील पोषाखांमध्ये फरक असण्याचे मुख्य कारण काय असावे?\",\"options\":[\"लोकांची उंची\",\"हवामानातील बदल\",\"रस्त्यांची लांबी\",\"भाषेतील फरक\"],\"answer\":1,\"explain\":\"हवामानातील बदलानुसार वेगवेगळ्या प्रदेशांतील कपड्यांमध्ये बदल होतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला राजस्थानमधील लोकांच्या पोषाखावरून तेथील हवामानाचा अंदाज लावायचा असेल, तर तुम्ही काय कराल?\",\"options\":[\"तेथील लोकांची संख्या मोजाल\",\"तेथील पोषाखांच्या चित्रांचे निरीक्षण करून चर्चा कराल\",\"तेथील अन्नाची चव घ्याल\",\"तेथील गाणी ऐकाल\"],\"answer\":1,\"explain\":\"पोषाखांच्या चित्रांच्या आधारे तेथील हवामानाविषयी चर्चा करता येते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"वस्तूंची गरज नसतानाही त्या हव्या वाटणे, या वर्तणुकीबद्दल पाठात काय सुचवले आहे?\",\"options\":[\"अशी इच्छा असणे चांगले आहे\",\"हा हव्यास टाळून गरजेनुसार वापर करावा\",\"जास्तीत जास्त वस्तू साठवाव्यात\",\"गरज नसली तरी खरेदी करावी\"],\"answer\":1,\"explain\":\"पाठात हव्यास टाळून गरजेनुसार वस्तू वापरण्याचा सल्ला दिला आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"वस्त्रनिर्मितीच्या परंपरेबाबत खालीलपैकी कोणते विधान पाठाच्या आधारे योग्य आहे?\",\"options\":[\"सर्व प्रदेशात एकच प्रकारचे वस्त्र मिळते\",\"वस्त्रनिर्मितीची परंपरा केवळ महाराष्ट्रात आहे\",\"विविध प्रदेशांना स्वतःची वैशिष्ट्यपूर्ण वस्त्रनिर्मिती परंपरा आहे\",\"वस्त्रांमध्ये कोणतीही विविधता नसते\"],\"answer\":2,\"explain\":\"देशातील विविध प्रदेशांना वैशिष्ट्यपूर्ण वस्त्रनिर्मितीची परंपरा आहे हे पाठात स्पष्ट केले आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21616,24,5,'EVS Part 1','mr','पर्यावरण आणि आपण','[\"जंगलात सजीवांना अन्न व पाणी मिळते, जंगलतोड झाल्यास हे स्रोत कमी होतात.\",\"जंगलात राहणारे प्राणी व पक्षी इतरत्र स्थलांतर करतात, कारण निवारा व अन्न कमी होते.\",\"जंगलातील वनस्पती व प्राणी यांची वास्तव्य जागा कमी होते, ज्यामुळे जैवविविधता घटते.\",\"लोहमार्ग व धरण बांधण्यासाठी जंगलतोड केल्याने अनेक प्राण्यांचे निवास नष्ट होते.\",\"हवा प्रदूषणाचे प्रमुख कारण इंधन ज्वलनामुळे कार्बन डायऑक्साइड व विषारी वायूंची निर्मिती.\",\"इंधन (पेट्रोल, डिझेल, केरोसीन, नैसर्गिक वायू, कोळसा, लाकूड) वाहतूक, उद्योग व घरगुती गरजांसाठी वापरले जाते.\",\"उद्योगांचे सांडपाणी व धुराड्यांमधून बाहेर पडणारे विषारी वायू जल व हवा प्रदूषित करतात.\",\"जैविक घटक (वनस्पती, प्राणी) प्रदूषणामुळे नष्ट होतात, ज्यामुळे अन्नसाखळी तुटते.\",\"जैवविविधता उद्याने, राष्ट्रीय उद्याने व अभयारण्ये हे वन्यजीव व वनस्पतींचे संरक्षण करतात.\",\"जंगलतोड व प्रदूषणामुळे हवामान बदल होतो, तापमान वाढते.\",\"जंगलातील प्राणी व पक्षी स्थलांतर करतात, ज्यामुळे त्यांच्या प्रजननावर परिणाम होतो.\",\"वनस्पतींची संख्या कमी झाल्यास प्राण्यांची अन्नसाखळी तुटते.\",\"जैवविविधता जपण्यासाठी वृक्षारोपण व संरक्षण कार्यक्रम आवश्यक आहेत.\",\"जगभरात जैवविविधता उद्याने व अभयारण्ये स्थापन करून संरक्षण केले जाते.\",\"जंगलतोड व प्रदूषणामुळे मानवी आरोग्यावर व पर्यावरणावर नकारात्मक परिणाम होतो.\",\"जंगलातील पाणी व मातीची गुणवत्ता घटल्याने शेतीवर व मानवी जीवनावर परिणाम होतो.\",\"वनस्पती व प्राणी यांचा समतोल राखण्यासाठी निसर्गाचे संतुलन जपणे गरजेचे आहे.\",\"जंगलतोड व प्रदूषणामुळे अन्नसाखळीतील कडी नष्ट झाल्यास संपूर्ण जीवसृष्टीला धोका.\",\"जैवविविधता उद्याने व अभयारण्ये हे जैविक व अजैविक घटकांचे संरक्षण करतात.\",\"वनस्पती व प्राणी यांची संख्या वाढवण्यासाठी वृक्षारोपण व संरक्षण कार्यक्रम चालवणे आवश्यक.\",\"जंगलातील प्राणी व पक्षी यांची संख्या घटल्यास अन्नसाखळीतील इतर प्रजातींवर परिणाम होतो.\",\"जंगलतोड व प्रदूषणामुळे हवामान बदल व पर्यावरणीय संतुलन बिघडते.\",\"जैवविविधता जपण्यासाठी आंतरराष्ट्रीय स्तरावर विविध प्रकल्प राबवले जातात.\",\"वनस्पती व प्राणी यांचे संरक्षण केल्याने मानवी जीवनमान सुधारते.\",\"जंगलतोड व प्रदूषणामुळे मानवी आरोग्य व जीवनशैलीवर विपरीत परिणाम होतो.\"]','[{\"q\":\"जगभरातील एकूण लोकसंख्या सुमारे किती कोटींच्या घरात आहे?\",\"options\":[\"चारशे कोटी\",\"पाचशे कोटी\",\"सहाशे कोटी\",\"सातशे कोटी\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार जगभरातील एकूण लोकसंख्या आता सुमारे सहाशे कोटींच्या घरात आहे.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जंगलात राहणाऱ्या प्राण्यांमध्ये खालीलपैकी कोणाचा उल्लेख पाठात आला आहे?\",\"options\":[\"गाय\",\"हत्ती\",\"कुत्रा\",\"मांजर\"],\"answer\":1,\"explain\":\"पाठात अस्वल, हरीण, माकड, हत्ती, वाघ यांसारखे प्राणी जंगलात राहतात असे नमूद केले आहे.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जंगले कमी झाली, की तेथील कशाचा ऱ्हास होतो?\",\"options\":[\"लोकसंख्येचा\",\"जैवविविधतेचा\",\"तंत्रज्ञानाचा\",\"उद्योगांचा\"],\"answer\":1,\"explain\":\"जंगले कमी झाली, की तेथील जैवविविधतेचा ऱ्हास होतो असे पाठात स्पष्ट केले आहे.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मानवाला अधिकाधिक जमीन व जलस्रोत वापरण्याची गरज का भासत आहे?\",\"options\":[\"केवळ करमणुकीसाठी\",\"वाढत्या लोकांच्या गरजा भागवण्यासाठी\",\"प्राणी पाळण्यासाठी\",\"जंगले वाढवण्यासाठी\"],\"answer\":1,\"explain\":\"सहाशे कोटी लोकांच्या गरजा भागवण्यासाठी मानव अधिकाधिक जमीन व जलस्रोत वापरत आहे.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या भागात मोठ्या प्रमाणावर जंगलतोड झाली, तर तेथील सजीवांच्या अन्नाच्या स्रोतावर काय परिणाम होईल?\",\"options\":[\"अन्नाचे स्रोत वाढतील\",\"अन्नाचे स्रोत तसेच राहतील\",\"अन्नाचे स्रोत घटतील\",\"नवीन स्रोत तयार होतील\"],\"answer\":2,\"explain\":\"जंगलतोडीमुळे सजीवांचे अन्न व पाण्याचे स्रोत घटतात.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"जंगलतोडीमुळे प्राण्यांच्या वास्तव्याच्या जागेवर (निवारा) काय परिणाम होतो?\",\"options\":[\"वास्तव्याची जागा वाढते\",\"वास्तव्याची जागा कमी होते\",\"जागा बदलत नाही\",\"जागा अधिक सुरक्षित होते\"],\"answer\":1,\"explain\":\"जंगलतोडीमुळे वनस्पतींच्या व प्राण्यांच्या वास्तव्याची जागा कमी होते.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"शेती, वसाहती आणि रस्ते तयार करण्यासाठी मानवाला प्रामुख्याने कशाची आवश्यकता असते?\",\"options\":[\"फक्त पाण्याचे स्रोत\",\"मोकळी जमीन\",\"केवळ तंत्रज्ञान\",\"केवळ प्राणी\"],\"answer\":1,\"explain\":\"शेती, वसाहती, उद्योगधंदे तसेच रस्ते तयार करण्यासाठी खूप मोठ्या प्रमाणात मोकळी जमीन आवश्यक असते.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जंगलतोडीमुळे निवारा नष्ट झाल्यावर प्राणी काय करतात?\",\"options\":[\"ते तिथेच राहतात\",\"ते निवाऱ्यासाठी इतरत्र जातात\",\"ते स्वतःचे घर बांधतात\",\"ते काहीच करत नाहीत\"],\"answer\":1,\"explain\":\"जंगलतोडीमुळे निवारा नष्ट झाल्यास सजीव निवाऱ्यासाठी इतरत्र जातात.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मानवाच्या वाढत्या गरजा पूर्ण करण्यासाठी कशाचा शोध घेऊन वापर केला जात आहे?\",\"options\":[\"जुन्या परंपरांचा\",\"तंत्रज्ञानाचा\",\"नवीन जंगलांचा\",\"प्राण्यांच्या घरांचा\"],\"answer\":1,\"explain\":\"लोकांच्या गरजा भागवण्यासाठी मानव खूप मोठ्या प्रमाणावर तंत्रज्ञान शोधून काढत आहे व वापरत आहे.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत मानवनिर्मित कोणता मार्ग दाखवला आहे ज्याच्या बांधकामासाठी मोठ्या प्रमाणात जंगलतोड करावी लागते?\",\"options\":[\"जलमार्ग\",\"हवाईमार्ग\",\"लोहमार्ग\",\"पायवाट\"],\"answer\":2,\"explain\":\"दिलेल्या आकृतीत \'लोहमार्ग\' दाखवला आहे, जो तयार करण्यासाठी मोकळ्या जमिनीची गरज असल्याने जंगलतोड होते.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"24\\/099_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील हा लोहमार्ग तयार करण्यासाठी प्रामुख्याने काय करावे लागले असेल?\",\"options\":[\"डोंगर वाढवणे\",\"जंगलतोड करणे\",\"नदी आटवणे\",\"नवीन झाडे लावणे\"],\"answer\":1,\"explain\":\"लोहमार्ग तयार करण्यासाठी मोकळी जमीन आवश्यक असल्याने मोठ्या प्रमाणात जंगलतोड करावी लागते.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"24\\/099_101.jpg\"},{\"q\":\"जंगलतोडीमुळे त्या भागातील सजीवांच्या एकूण संख्येवर काय परिणाम होतो?\",\"options\":[\"सजीवांची संख्या वाढते\",\"सजीवांची संख्या स्थिर राहते\",\"सजीवांची संख्या कमी होते\",\"सजीवांची संख्या दुप्पट होते\"],\"answer\":2,\"explain\":\"जंगलतोडीमुळे अन्न, पाणी आणि निवारा कमी झाल्याने तेथील सजीवांची संख्या कमी होते.\",\"topic\":\"जंगलतोड\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"दलदलीच्या प्रदेशात किंवा खोलगट भूभागात जमिनीचे सपाटीकरण करण्यासाठी काय केले जाते?\",\"options\":[\"पाणी काढले जाते\",\"भराव घातला जातो\",\"झाडे लावली जातात\",\"खड्डे खोदले जातात\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे, खोलगट भूभागात भराव घालून जमिनीचे सपाटीकरण केले जाते.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"प्राणी, पक्षी आणि वनस्पती यांचे अस्तित्व धोक्यात आल्याची माहिती आपल्याला प्रामुख्याने कोठून मिळते?\",\"options\":[\"केवळ गोष्टींच्या पुस्तकातून\",\"बातम्यांतून\",\"केवळ चित्रांमधून\",\"जाहिरातींमधून\"],\"answer\":1,\"explain\":\"विविध प्रकारचे सजीव धोक्यात आल्याच्या बातम्या आपण वेळोवेळी वाचतो, ऐकतो व पाहतो.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात पर्यावरणावर परिणाम करणारी कोणती मानवनिर्मित कृती दिसत आहे?\",\"options\":[\"शेती करणे\",\"रस्ते बांधणी\",\"धरण बांधणे\",\"खाणकाम\"],\"answer\":1,\"explain\":\"चित्रात डोंगराळ भागात रस्ता आणि त्यावर चालणारी बस दाखवली आहे, जी रस्ते बांधणी दर्शवते.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"24\\/099_102.jpg\"},{\"q\":\"एखाद्या ठिकाणी धरण बांधले गेले, तर तेथील पर्यावरणावर कोणता परिणाम होऊ शकतो?\",\"options\":[\"तेथील झाडे आणि प्राण्यांचे अधिवास नष्ट होऊ शकतात\",\"पाऊस पडणे बंद होते\",\"जमीन आपोआप सपाट होते\",\"सर्व प्राणी शहरात राहायला जातात\"],\"answer\":0,\"explain\":\"धरण बांधल्यामुळे मोठा भूभाग पाण्याखाली जातो, ज्यामुळे तेथील वनस्पती आणि प्राण्यांच्या राहण्याच्या जागेत बदल होतो.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"सजीवांच्या अस्तित्वाचा धोका समजून घेण्यासाठी तयार करायच्या तक्त्यात कोणता रकाना समाविष्ट नाही?\",\"options\":[\"प्राणी किंवा वनस्पतीचे नाव\",\"कोणता धोका निर्माण झाला?\",\"बातम्यांची किंमत\",\"बातमीत दिलेली कारणे\"],\"answer\":2,\"explain\":\"पाठातील तक्त्यात नाव, धोका आणि कारणे हे तीन रकाने दिले आहेत; बातम्यांची किंमत नाही.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रावरून, रस्ता तयार करण्यासाठी नैसर्गिक पर्यावरणात कोणता बदल केला असावा असे वाटते?\",\"options\":[\"नदीचा प्रवाह बदलला असावा\",\"डोंगर कापून किंवा झाडे तोडून जागा केली असावी\",\"केवळ नवीन झाडे लावली असावीत\",\"जमिनीत मोठे खड्डे केले असावेत\"],\"answer\":1,\"explain\":\"चित्रात रस्ता डोंगराच्या बाजूने जात असल्याचे दिसते, ज्यासाठी डोंगर कापावा लागतो किंवा झाडे तोडावी लागतात.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"24\\/099_102.jpg\"},{\"q\":\"सजीवांचे अस्तित्व धोक्यात येण्याची कारणे कोठे दिलेली असतात असे पाठात म्हटले आहे?\",\"options\":[\"केवळ गणिताच्या पुस्तकात\",\"बातम्यांमध्ये\",\"केवळ खेळाच्या मैदानावर\",\"स्वयंपाकघरात\"],\"answer\":1,\"explain\":\"सजीवांचे अस्तित्व धोक्यात येण्याची कारणे बातम्यांमध्ये दिलेली असतात असे पाठात स्पष्ट केले आहे.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"खोलगट भूभागाचे सपाटीकरण केल्यामुळे तेथील नैसर्गिक पर्यावरणावर काय परिणाम होईल?\",\"options\":[\"पर्यावरणात काहीही बदल होणार नाही\",\"तेथील नैसर्गिक जलसाठे किंवा दलदल नष्ट होऊ शकते\",\"तेथे आपोआप जंगल तयार होईल\",\"पाऊस जास्त पडू लागेल\"],\"answer\":1,\"explain\":\"भराव घालून सपाटीकरण केल्याने त्या ठिकाणची मूळ नैसर्गिक स्थिती (उदा. दलदल) बदलून जाते.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला \'वाघांची संख्या कमी होत आहे\' अशी बातमी मिळाली, तर तुम्ही तक्त्यातील \'कोणता धोका निर्माण झाला?\' या रकान्यात काय लिहाल?\",\"options\":[\"वाघ\",\"शिकार\",\"अस्तित्व धोक्यात आले आहे\",\"जंगल तोड\"],\"answer\":2,\"explain\":\"संख्या कमी होणे हा सजीवांच्या अस्तित्वासाठी निर्माण झालेला धोका आहे.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"\'जरा डोके चालवा\' या उपक्रमात कोणत्या मानवनिर्मित बांधकामाचा पर्यावरणावरील परिणामाचा विचार करायला सांगितला आहे?\",\"options\":[\"शाळा\",\"धरण\",\"दवाखाना\",\"बाजार\"],\"answer\":1,\"explain\":\"पाठात \'एखाद्या ठिकाणी धरण बांधले गेले, तर त्या पर्यावरणात कोणते बदल होतील?\' असा प्रश्न विचारला आहे.\",\"topic\":\"कृती आणि चर्चा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दूषित पाणी जमिनीत मुरत राहिले, तर ती जमीन कशी होते?\",\"options\":[\"सुपीक होते\",\"नापीक होते\",\"मऊ होते\",\"काळी पडते\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की दूषित पाणी जमिनीत मुरल्यास जमीन नापीक होते.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शेतीसाठी मोठ्या प्रमाणावर कशाचा वापर केल्यामुळे रसायने मातीत जिरतात?\",\"options\":[\"सेंद्रिय खते\",\"शुद्ध पाणी\",\"रासायनिक खते आणि कीटकनाशके\",\"नैसर्गिक औषधे\"],\"answer\":2,\"explain\":\"शेतीसाठी वापरली जाणारी रासायनिक खते आणि कीटकनाशके मातीत जिरतात.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"सांडपाण्यावर आवश्यक त्या प्रक्रिया न करताच ते जलस्रोतात सोडले तर काय होते?\",\"options\":[\"पाणी शुद्ध होते\",\"जलस्रोतांचे प्रदूषण वाढते\",\"माती सुपीक होते\",\"पाणी पिण्यायोग्य होते\"],\"answer\":1,\"explain\":\"सांडपाण्यावर प्रक्रिया न करता जलस्रोतात सोडल्यास प्रदूषण वाढते.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"प्रदूषणामुळे सजीवांवर होणारा सर्वात गंभीर परिणाम कोणता?\",\"options\":[\"सजीवांची संख्या वाढते\",\"सजीव स्थलांतर करतात\",\"सजीव नामशेष होतात\",\"सजीव अधिक कार्यक्षम होतात\"],\"answer\":2,\"explain\":\"प्रदूषणामुळे सजीवांची संख्या कमी होऊन ते शेवटी नामशेष होतात.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शेतातील रसायने नद्यांमध्ये कशी पोहोचतात?\",\"options\":[\"वाऱ्यामुळे उडून\",\"पावसाच्या पाण्याबरोबर वाहून\",\"प्राण्यांच्या माध्यमातून\",\"वाहनांच्या टायरला चिकटून\"],\"answer\":1,\"explain\":\"मातीत जिरलेली रसायने पावसाच्या पाण्याबरोबर वाहून नद्यांमध्ये पोहोचतात.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या तलावात कारखान्याचे प्रक्रिया न केलेले सांडपाणी सोडले, तर तेथील जलचरांवर काय परिणाम होईल?\",\"options\":[\"त्यांची संख्या वाढेल\",\"त्यांना धोका पोहोचून त्यांची संख्या कमी होईल\",\"त्यांना काहीच फरक पडणार नाही\",\"ते अधिक वेगाने पोहू लागतील\"],\"answer\":1,\"explain\":\"प्रदूषणामुळे तेथील प्राण्यांना धोका पोहोचतो आणि त्यांची संख्या कमी होते.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"मातीचे प्रदूषण होण्यास खालीलपैकी कोणते मुख्य कारण जबाबदार आहे?\",\"options\":[\"झाडे लावणे\",\"दूषित पाणी जमिनीत मुरणे\",\"नदीचे पाणी शेतीला देणे\",\"पावसाचे पाणी साठवणे\"],\"answer\":1,\"explain\":\"कारखान्यांचे दूषित पाणी जमिनीत मुरल्यामुळे मातीचे प्रदूषण होते.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"पाण्याचे व मातीचे प्रदूषण घडत राहिल्याने पर्यावरणावर काय परिणाम होतो?\",\"options\":[\"वनस्पती आणि प्राण्यांना धोका पोहोचतो\",\"जमीन अधिक सुपीक होते\",\"नद्यांचे पाणी स्वच्छ होते\",\"नवीन सजीव निर्माण होतात\"],\"answer\":0,\"explain\":\"प्रदूषणामुळे तेथील वनस्पती आणि प्राण्यांना धोका पोहोचतो.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात कारखान्यातून बाहेर काय सोडले जात आहे?\",\"options\":[\"पिण्याचे पाणी\",\"सांडपाणी\",\"दुध\",\"तेल\"],\"answer\":1,\"explain\":\"चित्राच्या खालील मजकुरानुसार कारखान्यातून परिसरात सांडपाणी सोडले जात आहे.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"24\\/100_101.jpg\"},{\"q\":\"दिलेल्या चित्राचे निरीक्षण केल्यास, कारखान्यातील सांडपाणी थेट कोठे जात आहे असे दिसते?\",\"options\":[\"टाकीमध्ये साठवले जात आहे\",\"परिसरातील जलस्रोतात किंवा जमिनीत\",\"शुद्धीकरण केंद्रात\",\"डोंगराच्या शिखरावर\"],\"answer\":1,\"explain\":\"चित्रात पाईपद्वारे सांडपाणी थेट परिसरात किंवा जलस्रोतात सोडलेले दिसत आहे.\",\"topic\":\"प्रदूषण\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"24\\/100_101.jpg\"},{\"q\":\"इंधनांच्या ज्वलनातून कोणता वायू प्रचंड प्रमाणावर हवेत मिसळतो?\",\"options\":[\"ऑक्सिजन\",\"नायट्रोजन\",\"कार्बन डायऑक्साइड\",\"हायड्रोजन\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे इंधनांच्या ज्वलनातून कार्बन डायऑक्साइड हवेत मिसळतो.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"मजकुरात खालीलपैकी कोणत्या इंधनाचा उल्लेख केलेला नाही?\",\"options\":[\"केरोसीन\",\"नैसर्गिक वायू\",\"कोळसा\",\"सौर ऊर्जा\"],\"answer\":3,\"explain\":\"मजकुरात पेट्रोल, डिझेल, केरोसीन, नैसर्गिक वायू, कोळसा आणि लाकूड यांचा उल्लेख आहे, सौर ऊर्जेचा नाही.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"हवेतील वाढलेला कार्बन डायऑक्साइड शोषून घेण्याचे काम कोण करते?\",\"options\":[\"प्राणी\",\"वनस्पती\",\"कारखाने\",\"इंधने\"],\"answer\":1,\"explain\":\"वनस्पती हवेतील कार्बन डायऑक्साइड शोषून घेतात.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"वातावरणातील कार्बन डायऑक्साइडचे प्रमाण वाढल्याचा मुख्य परिणाम काय होतो?\",\"options\":[\"थंडी वाढते\",\"पाऊस वाढतो\",\"तापमान वाढते\",\"हवा शुद्ध होते\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की कार्बन डायऑक्साइडचे प्रमाण वाढले की तापमानही वाढते.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वनस्पती कार्बन डायऑक्साइड शोषून घेण्यासाठी अपुऱ्या का पडत आहेत?\",\"options\":[\"वनस्पतींची वाढ वेगाने होत आहे\",\"जंगलांचा मोठ्या प्रमाणावर ऱ्हास होत आहे\",\"पाऊस कमी पडत आहे\",\"इंधनाचा वापर कमी झाला आहे\"],\"answer\":1,\"explain\":\"जंगलांचा ऱ्हास होत असल्यामुळे वाढलेला कार्बन डायऑक्साइड शोषण्यासाठी वनस्पती अपुऱ्या पडत आहेत.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"इंधनांच्या ज्वलनातून कार्बन डायऑक्साइडशिवाय आणखी काय निर्माण होते?\",\"options\":[\"शुद्ध हवा\",\"पाणी\",\"विषारी वायू आणि धूर\",\"खनिज तेल\"],\"answer\":2,\"explain\":\"इंधनांच्या ज्वलनातून विषारी वायू आणि मोठ्या प्रमाणावर धूर निर्माण होतो.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या शहरात नवीन कारखाने आणि उद्योगधंदे मोठ्या प्रमाणावर सुरू झाले, तर तेथील हवेवर काय परिणाम होईल?\",\"options\":[\"हवेतील विषारी वायूंचे प्रमाण वाढेल\",\"हवा अधिक थंड होईल\",\"कार्बन डायऑक्साइडचे प्रमाण कमी होईल\",\"हवा शुद्ध होईल\"],\"answer\":0,\"explain\":\"उद्योगधंद्यांतून हवेत विषारी वायू मिसळतात, ज्यामुळे प्रदूषण वाढते.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"स्वयंपाकासाठी लाकूड जाळल्यास खालीलपैकी काय घडेल?\",\"options\":[\"केवळ ऑक्सिजन मिळेल\",\"हवेत धूर आणि कार्बन डायऑक्साइड मिसळेल\",\"तापमान कमी होईल\",\"हवेचे प्रदूषण थांबेल\"],\"answer\":1,\"explain\":\"लाकूड हे एक इंधन आहे आणि त्याच्या ज्वलनातून कार्बन डायऑक्साइड व धूर निघतो.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"तापमान वाढ आणि इंधनाचा वापर यांचा संबंध कसा आहे?\",\"options\":[\"इंधनाचा वापर वाढल्याने तापमान कमी होते\",\"इंधनाचा वापर आणि तापमानाचा काहीही संबंध नाही\",\"इंधनांच्या ज्वलनातून निघणाऱ्या कार्बन डायऑक्साइडमुळे तापमान वाढते\",\"केवळ नैसर्गिक वायूमुळे तापमान वाढते\"],\"answer\":2,\"explain\":\"इंधनांच्या ज्वलनातून कार्बन डायऑक्साइड वाढतो आणि त्यामुळे तापमान वाढते.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"हवा प्रदूषणास कारणीभूत असलेल्या दोन मुख्य गोष्टी कोणत्या?\",\"options\":[\"वनस्पतींची वाढ आणि पाऊस\",\"इंधनांचा वापर आणि जंगलांचा ऱ्हास\",\"शेती आणि पशुपालन\",\"नैसर्गिक वायू आणि ऑक्सिजन\"],\"answer\":1,\"explain\":\"इंधनांचे ज्वलन आणि जंगलांचा नाश या दोन गोष्टींमुळे कार्बन डायऑक्साइड वाढून प्रदूषण होते.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"तापमान वाढ ही जगाच्या सर्व भागात का दिसून येत आहे?\",\"options\":[\"कारण सर्वत्र जंगले वाढत आहेत\",\"कारण वातावरणातील कार्बन डायऑक्साइडचे प्रमाण सर्वत्र वाढत आहे\",\"कारण लोक इंधनाचा वापर करणे बंद करत आहेत\",\"कारण विषारी वायूंचे प्रमाण कमी होत आहे\"],\"answer\":1,\"explain\":\"वातावरणातील कार्बन डायऑक्साइडचे प्रमाण वाढल्यामुळे होणारी तापमान वाढ जागतिक स्तरावर दिसून येते.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"मजकुराच्या आधारे, हवा प्रदूषण कमी करण्यासाठी सर्वात प्रभावी कृती कोणती ठरेल?\",\"options\":[\"जास्तीत जास्त कारखाने उभारणे\",\"इंधनांचा वापर प्रचंड वाढवणे\",\"जंगलांचे रक्षण करणे आणि झाडे लावणे\",\"केवळ लाकडाचा इंधन म्हणून वापर करणे\"],\"answer\":2,\"explain\":\"वनस्पती कार्बन डायऑक्साइड शोषतात, म्हणून जंगलांचे रक्षण करणे हा प्रदूषण रोखण्याचा मार्ग आहे.\",\"topic\":\"हवा प्रदूषण\",\"part\":5,\"bloom\":\"create\"},{\"q\":\"मानवाच्या निसर्गातील हस्तक्षेपामुळे खालीलपैकी कोणत्या घटकांचे प्रदूषण होत आहे?\",\"options\":[\"केवळ जैविक घटकांचे\",\"अजैविक घटकांचे\",\"केवळ मानवनिर्मित वस्तूंचे\",\"केवळ अवकाशाचे\"],\"answer\":1,\"explain\":\"पाठात स्पष्ट केले आहे की मानवाच्या हस्तक्षेपामुळे हवा, पाणी, जमीन यांसारख्या अजैविक घटकांचे प्रदूषण होत आहे.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"पर्यावरणातील एका घटकात बिघाड झाला, तर त्याचा परिणाम कशावर होतो?\",\"options\":[\"केवळ मानवावर\",\"केवळ प्राण्यांवर\",\"इतर घटकांवर आणि पर्यावरणाच्या समतोलावर\",\"कोणत्याही गोष्टीवर परिणाम होत नाही\"],\"answer\":2,\"explain\":\"पर्यावरणातील घटक एकमेकांशी संबंधित असल्याने एका घटकातील बिघाड पर्यावरणाचा समतोल बिघडवतो.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"पाठात दिलेल्या माहितीनुसार \'नामशेष होणे\' म्हणजे काय?\",\"options\":[\"दुसऱ्या ठिकाणी स्थलांतर करणे\",\"संख्या वाढणे\",\"अस्तित्व संपणे किंवा नष्ट होणे\",\"आजारी पडणे\"],\"answer\":2,\"explain\":\"जैविक घटक अस्तित्वात नसणे म्हणजेच ते नामशेष होणे होय.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"हवा, पाणी आणि जमीन हे पर्यावरणाचे कोणते घटक आहेत?\",\"options\":[\"जैविक घटक\",\"अजैविक घटक\",\"सजीव घटक\",\"कृत्रिम घटक\"],\"answer\":1,\"explain\":\"हवा, पाणी आणि जमीन हे निर्जीव म्हणजेच अजैविक घटक आहेत.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अन्नसाखळीतील एक कडी निखळली, तर त्याचा काय परिणाम होईल?\",\"options\":[\"साखळी अधिक मजबूत होईल\",\"साखळीतील इतर सजीवांवर परिणाम होईल\",\"पर्यावरणाचा समतोल सुधारेल\",\"काहीही फरक पडणार नाही\"],\"answer\":1,\"explain\":\"अन्नसाखळीतील प्रत्येक कडी महत्त्वाची असते, एक कडी निखळल्यास संपूर्ण साखळी विस्कळीत होते.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"सध्याच्या काळात सजीव नामशेष होण्याची प्रक्रिया कशी होत आहे?\",\"options\":[\"खूप मंद गतीने\",\"थांबली आहे\",\"खूप वेगाने\",\"केवळ जंगलात होत आहे\"],\"answer\":2,\"explain\":\"पाठात नमूद केल्याप्रमाणे, सध्याच्या काळात सजीव नामशेष होण्याची प्रक्रिया खूप वेगाने होत आहे.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जैविक घटकांचे अस्तित्व धोक्यात येण्याचे मुख्य कारण काय आहे?\",\"options\":[\"अजैविक घटकांचे प्रदूषण\",\"सजीवांची वाढती संख्या\",\"पावसाचे प्रमाण वाढणे\",\"सूर्याचा प्रकाश कमी होणे\"],\"answer\":0,\"explain\":\"अजैविक घटकांच्या (हवा, पाणी, जमीन) प्रदूषणामुळे जैविक घटकांचे अस्तित्व धोक्यात आले आहे.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर अन्नसाखळीतील नाकतोडा हा घटक नष्ट झाला, तर त्याचा सर्वात मोठा धोका कोणाला आहे?\",\"options\":[\"केवळ जमिनीला\",\"केवळ हवेला\",\"संपूर्ण जीवसृष्टीला आणि अन्नसाखळीला\",\"केवळ मानवाला\"],\"answer\":2,\"explain\":\"अन्नसाखळीतील कोणताही एक सजीव नष्ट झाला तर त्याचा धोका संपूर्ण जीवसृष्टीला पोहोचतो.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मानवाच्या हस्तक्षेपामुळे पर्यावरणात कोठे बदल घडून येत आहेत?\",\"options\":[\"केवळ शहरात\",\"केवळ गावात\",\"हवा, पाणी, जमीन अशा सर्व ठिकाणी\",\"केवळ कारखान्यांमध्ये\"],\"answer\":2,\"explain\":\"मानवी हस्तक्षेपामुळे निसर्गातील हवा, पाणी आणि जमीन या सर्व ठिकाणी मोठे बदल होत आहेत.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"पर्यावरणाचा समतोल बिघडण्याचे मुख्य कारण काय आहे?\",\"options\":[\"नैसर्गिक चक्राची गती वाढणे\",\"पर्यावरणाच्या घटकांमधील संबंधांवर होणारा विपरीत परिणाम\",\"नवीन सजीवांची निर्मिती होणे\",\"पावसाळा वेळेवर येणे\"],\"answer\":1,\"explain\":\"जेव्हा पर्यावरणाच्या एका घटकात बिघाड होतो, तेव्हा इतर घटकांशी असलेल्या संबंधावर परिणाम होऊन समतोल बिघडतो.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"जीवसृष्टीला धोका निर्माण होण्याचे कारण काय असू शकते?\",\"options\":[\"पर्यावरणाचे रक्षण करणे\",\"सजीवांचे वेगाने नामशेष होणे\",\"झाडे लावणे\",\"प्रदूषण कमी करणे\"],\"answer\":1,\"explain\":\"सजीव वेगाने नामशेष होत असल्यामुळे संपूर्ण जीवसृष्टीला धोका निर्माण झाला आहे.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"अन्नसाखळीतील कड्या कशाचे प्रतीक आहेत?\",\"options\":[\"सजीवांच्या एकमेकांवरील अवलंबनाचे\",\"केवळ वनस्पतींच्या वाढीचे\",\"केवळ पावसाच्या चक्राचे\",\"केवळ जमिनीच्या सुपीकतेचे\"],\"answer\":0,\"explain\":\"अन्नसाखळीतील कड्या या सजीवांच्या परस्परांशी असलेल्या संबंधांचे आणि अन्नासाठीच्या अवलंबनाचे प्रतीक आहेत.\",\"topic\":\"पर्यावरण संतुलन राखण्याची गरज\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"अन्न, पाणी आणि वस्त्र या आपल्या काय आहेत?\",\"options\":[\"केवळ इच्छा\",\"गरजा\",\"हौस\",\"मनोरंजन\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे अन्न, पाणी आणि वस्त्र या आपल्या मूलभूत गरजा आहेत.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"अनेक अन्नसाखळ्यांमधील कड्या नष्ट झाल्या तर त्याचा काय परिणाम होईल?\",\"options\":[\"केवळ वनस्पती वाढतील\",\"केवळ प्राणी वाढतील\",\"पर्यावरणाचा समतोल कोलमडेल\",\"काहीही परिणाम होणार नाही\"],\"answer\":2,\"explain\":\"अन्नसाखळीतील कड्या नष्ट झाल्यामुळे निसर्गातील पर्यावरणाचा समतोल बिघडतो असे शास्त्रज्ञांचे मत आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"पर्यावरणाचा ऱ्हास थांबवण्यासाठी आपण कोणती कृती करणे आवश्यक आहे?\",\"options\":[\"नवीन वस्तूंचा सतत वापर करणे\",\"साधने कमीत कमी दिवस वापरणे\",\"टाकाऊ वस्तूंपासून टिकाऊ वस्तू बनवणे\",\"जास्तीत जास्त वस्तू साठवून ठेवणे\"],\"answer\":2,\"explain\":\"पर्यावरणाचा ऱ्हास थांबवण्यासाठी टाकाऊ वस्तूंपासून टिकाऊ वस्तू बनवण्याचा विचार गांभीर्याने करायला हवा.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"पर्यावरणाचा वेगाने ऱ्हास होण्याचे मुख्य कारण काय आहे?\",\"options\":[\"केवळ प्राण्यांची संख्या वाढणे\",\"लोकांच्या वाढत्या गरजा आणि इच्छा\",\"पावसाचे प्रमाण वाढणे\",\"शास्त्रज्ञांचे नवीन शोध\"],\"answer\":1,\"explain\":\"जगभरातील सर्व लोकांच्या गरजा आणि इच्छांमुळे पर्यावरणाचा वेगाने ऱ्हास होत आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात कोणता प्राणी दाखवला आहे?\",\"options\":[\"वाघ\",\"बिबट्या\",\"भारतीय चित्ता\",\"सिंह\"],\"answer\":2,\"explain\":\"दिलेले चित्र \'भारतीय चित्ता\' या प्राण्याचे आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"remember\",\"figure_image\":\"24\\/101_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील प्राण्याच्या स्थितीबद्दल काय सांगता येईल?\",\"options\":[\"हा प्राणी पाळीव आहे\",\"हा प्राणी नामशेष झाला आहे\",\"हा प्राणी सर्वत्र आढळतो\",\"हा प्राणी फक्त बागेत राहतो\"],\"answer\":1,\"explain\":\"चित्राखालील मजकुरानुसार भारतीय चित्ता हा नामशेष झालेला प्राणी आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"24\\/101_101.jpg\"},{\"q\":\"आपल्याला लागणाऱ्या सर्व गोष्टी आपल्याला कोठून मिळतात?\",\"options\":[\"केवळ कारखान्यातून\",\"केवळ दुकानातून\",\"पर्यावरणातील पदार्थांपासून\",\"केवळ घरातून\"],\"answer\":2,\"explain\":\"आपल्याला लागणाऱ्या सर्व गोष्टी पर्यावरणातील पदार्थ वापरून मिळतात.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"निसर्गाचा समतोल बिघडला तर त्याचा परिणाम मानवावर का होईल?\",\"options\":[\"कारण मानव निसर्गाचाच भाग आहे\",\"कारण मानव निसर्गापेक्षा वेगळा आहे\",\"कारण मानव खूप शक्तिशाली आहे\",\"कारण मानव निसर्गावर अवलंबून नाही\"],\"answer\":0,\"explain\":\"मानव हा निसर्गाचाच भाग असल्यामुळे निसर्गाचा समतोल बिघडल्यास त्याचा मानवावर परिणाम होतो.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जीवसृष्टीच्या संवर्धनासाठी आपण कोणता निर्धार करायला हवा?\",\"options\":[\"जास्तीत जास्त साधने विकत घेणे\",\"कोणत्याही कृतीमुळे प्रदूषण होऊ नये\",\"वस्तूंचा वापर कमी करणे\",\"केवळ मनोरंजनावर लक्ष देणे\"],\"answer\":1,\"explain\":\"आपल्या कोणत्याही कृतीमुळे प्रदूषण होऊ नये आणि जीवसृष्टीचे नुकसान होऊ नये असा निर्धार आपण करायला हवा.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"शास्त्रज्ञांच्या मते पृथ्वीवरील सर्वच जीवसृष्टीवर परिणाम केव्हा होईल?\",\"options\":[\"जेव्हा आपण खेळ खेळू\",\"जेव्हा आपण अभ्यास करू\",\"जेव्हा वनस्पती किंवा प्राणी नामशेष होतील\",\"जेव्हा आपण वस्तू घरात साठवू\"],\"answer\":2,\"explain\":\"विविध प्रकारचे प्राणी किंवा वनस्पती नामशेष झाले तर त्याचा परिणाम सर्व जीवसृष्टीवर होईल असे शास्त्रज्ञांचे मत आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"पर्यावरणाचे रक्षण करण्यासाठी खालीलपैकी कोणती कृती योग्य आहे?\",\"options\":[\"साधने शक्य तितके जास्त दिवस वापरणे\",\"वस्तू एकदा वापरून फेकून देणे\",\"जास्तीत जास्त प्रदूषण करणे\",\"निसर्गाचा समतोल बिघडवणे\"],\"answer\":0,\"explain\":\"एखादे साधन शक्य तितके जास्त दिवस वापरणे ही पर्यावरणाचा ऱ्हास थांबवण्यासाठी योग्य कृती आहे.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"आपण अनेक गोष्टी घरात साठवून का ठेवतो?\",\"options\":[\"फक्त हौस म्हणून\",\"गरज पडेल तेव्हा उपलब्ध असाव्यात म्हणून\",\"जागा भरण्यासाठी\",\"प्रदूषण करण्यासाठी\"],\"answer\":1,\"explain\":\"आपल्याला लागतील तेव्हा त्या उपलब्ध असाव्यात म्हणून आपण अनेक गोष्टी घरात साठवून ठेवतो.\",\"topic\":\"आपल्या गरजा आणि पर्यावरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"जैवविविधतेचे रक्षण व संवर्धन करण्याच्या दृष्टीने राखून ठेवलेल्या क्षेत्राला काय म्हणतात?\",\"options\":[\"राष्ट्रीय उद्यान\",\"अभयारण्य\",\"जैवविविधता उद्यान\",\"शेती क्षेत्र\"],\"answer\":2,\"explain\":\"पाठातील व्याख्येनुसार, जैवविविधतेचे रक्षण व संवर्धन करण्यासाठी राखून ठेवलेल्या क्षेत्राला \'जैवविविधता उद्यान\' म्हणतात.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"वन्यजीव संरक्षण व संवर्धन करण्याच्या उद्देशाने राखून ठेवलेल्या क्षेत्राला काय म्हणतात? (उदा. ताडोबा)\",\"options\":[\"राष्ट्रीय उद्यान\",\"जैवविविधता उद्यान\",\"खाजगी जंगल\",\"शहरी उद्यान\"],\"answer\":0,\"explain\":\"वन्यजीव संरक्षण व संवर्धनासाठी राखून ठेवलेल्या क्षेत्रांना राष्ट्रीय उद्याने म्हणतात.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"विशिष्ट प्राण्यांचे आणि वनस्पतींचे संरक्षण व्हावे यासाठी राखीव ठेवलेल्या वनक्षेत्राला काय म्हणतात?\",\"options\":[\"जैवविविधता उद्यान\",\"अभयारण्य\",\"राष्ट्रीय उद्यान\",\"नर्सरी\"],\"answer\":1,\"explain\":\"विशिष्ट प्राण्यांच्या आणि वनस्पतींच्या संरक्षणासाठी राखीव ठेवलेल्या क्षेत्राला अभयारण्य म्हणतात.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जैवविविधता उद्यानाला भेट देणाऱ्या लोकांना कशाचा आनंद घेता येतो, ज्यामुळे निसर्गाविषयी आस्था वाढते?\",\"options\":[\"मोठ्या इमारतींचा\",\"वनराईचा\",\"वाहनांच्या गर्दीचा\",\"खेळण्यांच्या दुकानांचा\"],\"answer\":1,\"explain\":\"जैवविविधता उद्यानातील वनराईचा आनंद घेतल्यामुळे लोकांची निसर्गाविषयीची आस्था वाढते.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"निसर्गाचा समतोल राखण्यासाठी कोणत्या स्तरावर अनेक प्रकल्प राबवले जात आहेत?\",\"options\":[\"केवळ एका गावाच्या स्तरावर\",\"केवळ एका जिल्ह्याच्या स्तरावर\",\"आंतरराष्ट्रीय स्तरावर\",\"केवळ एका कुटुंबाच्या स्तरावर\"],\"answer\":2,\"explain\":\"निसर्गाचा समतोल राखण्यासाठी आंतरराष्ट्रीय स्तरावर अनेक प्रकल्प राबवले जात आहेत.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात निसर्गाचा समतोल राखण्यासाठी कोणत्या स्तरावर प्रयत्न सुरू असल्याचे दर्शवले आहे?\",\"options\":[\"स्थानिक स्तर\",\"कौटुंबिक स्तर\",\"आंतरराष्ट्रीय स्तर\",\"शालेय स्तर\"],\"answer\":2,\"explain\":\"चित्रात निसर्गाचा समतोल राखण्यासाठी आंतरराष्ट्रीय स्तरावर प्रकल्प राबवले जात असल्याचे नमूद आहे.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"24\\/102_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील प्राण्यासारख्या वन्यजीवांचे रक्षण करण्यासाठी खालीलपैकी कोणती कृती सर्वात महत्त्वाची आहे?\",\"options\":[\"जंगलातील वनस्पतींचे संरक्षण व संवर्धन करणे\",\"प्राण्यांना शहरात आणणे\",\"जंगलतोड वाढवणे\",\"प्राण्यांना पिंजऱ्यात बंद करणे\"],\"answer\":0,\"explain\":\"वनस्पतींचे रक्षण केल्यास त्यावर अवलंबून असणाऱ्या वन्यजीवांचेही रक्षण होते, असे चित्राच्या माहितीवरून समजते.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"apply\",\"figure_image\":\"24\\/102_101.jpg\"},{\"q\":\"पाणी, अन्न आणि वस्त्र यांसारख्या गरजेच्या गोष्टींचा साठा आपण कसा ठेवावा, यावर पाठात चर्चा करण्यास सांगितले आहे?\",\"options\":[\"अमर्याद साठा असावा\",\"गरजेपुरता साठा असावा\",\"साठा अजिबात नसावा\",\"दुसऱ्यांकडून हिसकावून घ्यावा\"],\"answer\":1,\"explain\":\"निसर्गाचा समतोल राखण्यासाठी गरजेच्या गोष्टींचा साठा गरजेपुरताच असणे आवश्यक आहे.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीवरील वनस्पती नष्ट होऊ लागल्यास प्राण्यांच्या संख्येवर काय परिणाम होईल?\",\"options\":[\"प्राण्यांची संख्या वाढेल\",\"प्राण्यांची संख्या कमी होईल\",\"प्राण्यांवर काहीही परिणाम होणार नाही\",\"प्राणी अधिक बलवान होतील\"],\"answer\":1,\"explain\":\"वनस्पती नष्ट झाल्यामुळे प्राण्यांना अन्न व निवारा मिळणार नाही, परिणामी त्यांची संख्या कमी होईल.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"हवा, पाणी आणि जमीन प्रदूषित होऊ नये यासाठी जगभरातील देश काय करत आहेत?\",\"options\":[\"नवीन कारखाने बांधत आहेत\",\"कायदे करत आहेत\",\"प्रदूषण वाढवत आहेत\",\"जंगले तोडत आहेत\"],\"answer\":1,\"explain\":\"प्रदूषण रोखण्यासाठी जगभरातील सर्व देश कायदे करत आहेत.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"वन्यजीवांचे रक्षण करण्यासाठी खालीलपैकी कोणता पर्याय सर्वात योग्य आहे?\",\"options\":[\"केवळ प्राण्यांना खायला देणे\",\"जंगलतोड थांबवून वृक्षारोपण करणे\",\"जंगलात रस्ते बांधणे\",\"वनस्पती तोडणे\"],\"answer\":1,\"explain\":\"जंगलतोड थांबवून वृक्षारोपण केल्यास वनस्पतींचे रक्षण होते आणि पर्यायाने वन्यजीवांचेही रक्षण होते.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"काझीरंगा आणि ताडोबा ही कशाची उदाहरणे आहेत?\",\"options\":[\"अभयारण्ये\",\"राष्ट्रीय उद्याने\",\"जैवविविधता उद्याने\",\"खाजगी बागा\"],\"answer\":1,\"explain\":\"पाठात काझीरंगा आणि ताडोबा ही राष्ट्रीय उद्यानांची उदाहरणे म्हणून दिली आहेत.\",\"topic\":\"पर्यावरण संरक्षणाचे जागतिक प्रयत्न\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"उत्तर आशियातील सायबेरिया प्रदेशातून मायणी तलावात कोणते पक्षी स्थलांतर करून येतात?\",\"options\":[\"माळढोक\",\"रोहित\",\"मोर\",\"चिमणी\"],\"answer\":1,\"explain\":\