m\":\"analyze\"},{\"q\":\"मायणी तलाव सातारा जिल्ह्यातील कोणत्या नदीवर धरण बांधल्यामुळे तयार झाला आहे?\",\"options\":[\"कृष्णा\",\"कोयना\",\"चांद\",\"मुळा-मुठा\"],\"answer\":2,\"explain\":\"सातारा जिल्ह्याच्या चांद नदीवर ब्रिटीशकालीन धरणामुळे मायणी तलाव तयार झाला आहे.\",\"topic\":\"महाराष्ट्रातील अभयारण्ये\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"माळढोक पक्ष्यांच्या अन्नाबाबत खालीलपैकी कोणते विधान योग्य आहे?\",\"options\":[\"ते फक्त चिंचेची फळे खातात\",\"ते गवताळ प्रदेशातील कीटक खातात\",\"ते फक्त मासे खातात\",\"ते सायबेरियातील धान्य खातात\"],\"answer\":1,\"explain\":\"माळढोक पक्षी गवताळ प्रदेशातील माळरानावर राहतात आणि कीटक खातात.\",\"topic\":\"महाराष्ट्रातील अभयारण्ये\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"मोरगावची चिंचोली येथे मोरांसाठी अनुकूल पर्यावरण कशामुळे निर्माण झाले आहे?\",\"options\":[\"तेथे खूप पाऊस पडतो म्हणून\",\"तेथे धरण बांधले आहे म्हणून\",\"चिंचेच्या झाडांची निगा राखल्यामुळे\",\"तेथे कीटक जास्त आहेत म्हणून\"],\"answer\":2,\"explain\":\"चिंचेची झाडे असून त्यांची निगा राखल्यामुळे तेथील पर्यावरण मोरांना अनुकूल आहे.\",\"topic\":\"महाराष्ट्रातील अभयारण्ये\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात दिसणारा पक्षी त्याच्या कोणत्या वैशिष्ट्यासाठी प्रसिद्ध आहे?\",\"options\":[\"वेगाने पोहण्यासाठी\",\"डौलदार चालीसाठी\",\"पाण्यात घरटी बांधण्यासाठी\",\"खूप उंचावर उडण्यासाठी\"],\"answer\":1,\"explain\":\"चित्रातील माळढोक पक्षी त्यांच्या डौलदार चालीबद्दल प्रसिद्ध आहेत.\",\"topic\":\"महाराष्ट्रातील अभयारण्ये\",\"part\":10,\"bloom\":\"remember\",\"figure_image\":\"24\\/103_102.jpg\"},{\"q\":\"दिलेल्या चित्रात माळढोक मादीसोबत आढळणारा प्राणी माळढोक अभयारण्यातील कोणत्या भागात राहतो?\",\"options\":[\"दाट जंगलात\",\"पाण्याखाली\",\"गवताळ माळरानावर\",\"बर्फाळ प्रदेशात\"],\"answer\":2,\"explain\":\"चित्रात हरणे दिसत आहेत आणि माळढोक व हरणे गवताळ माळरानावर राहतात.\",\"topic\":\"महाराष्ट्रातील अभयारण्ये\",\"part\":10,\"bloom\":\"understand\",\"figure_image\":\"24\\/104_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील पक्ष्यांची संख्या मोरगावची चिंचोली ये