opic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"देवरायांना प्राचीन काळातील काय म्हणावे लागेल?\",\"options\":[\"करमणूक केंद्रे\",\"अभयारण्ये\",\"बाजारपेठा\",\"शहरे\"],\"answer\":1,\"explain\":\"पाठाच्या शेवटच्या ओळीनुसार, या देवराया प्राचीन काळातील अभयारण्येच आहेत.\",\"topic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात देवराईमध्ये सुरक्षित असलेला कोणता पक्षी दिसत आहे?\",\"options\":[\"पोपट\",\"चिमणी\",\"मोर\",\"गरुड\"],\"answer\":2,\"explain\":\"पहिल्या चित्रात (F1) देवराईच्या नैसर्गिक वातावरणात एक मोर बसलेला दिसत आहे.\",\"topic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"remember\",\"figure_image\":\"24\\/104_102.jpg\"},{\"q\":\"दिलेल्या चित्राचे निरीक्षण केल्यास, देवराईच्या घनदाट झाडीमध्ये काय असल्याचे दिसून येते?\",\"options\":[\"मोठा कारखाना\",\"एक छोटे मंदिर\",\"पक्के सिमेंटचे रस्ते\",\"बहुमजली इमारत\"],\"answer\":1,\"explain\":\"दुसऱ्या चित्रात (F2) झाडांच्या मध्यभागी एक छोटे मंदिर दाखवले आहे, जे देवराईची संकल्पना स्पष्ट करते.\",\"topic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"understand\",\"figure_image\":\"24\\/104_104.jpg\"},{\"q\":\"जर तुम्हाला पर्यावरणाचे रक्षण करायचे असेल, तर देवराई या संकल्पनेतून तुम्ही कोणता धडा घ्याल?\",\"options\":[\"जंगलातील सर्व झाडे कापून टाकणे\",\"जंगलात नवीन रस्ते तयार करणे\",\"परंपरेने चालत आलेल्या नैसर्गिक क्षेत्रांचे जतन करणे\",\"जंगलात मोठी शहरे वसवणे\"],\"answer\":2,\"explain\":\"देवराई ही संकल्पना नैसर्गिक क्षेत्रांचे जतन आणि संरक्षण करण्याची शिकवण देते.\",\"topic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"देवराईमधील झाडे तोडली जात नाहीत, यावरून लोकांच्या कोणत्या वृत्तीचे दर्शन घडते?\",\"options\":[\"निसर्गाबद्दलची भीती\",\"निसर्गाबद्दलची आदरयुक्त भावना आणि श्रद्धा\",\"आळशीपणा\",\"केवळ लाकडाची गरज नसणे\"],\"answer\":1,\"explain\":\"लोकांच्या मनात निसर्गाबद्दल (देवाचे जंगल म्हणून) आदर आणि श्रद्धा असल्याने ते झाडे तोडत नाहीत.\",\"topic\":\"देवराई - एक वरदान !\",\"part\":11,\"bloom\":\"evaluate\"},{\"q\":\"निसर्ग सर्वांची गरज भागवतो, परंतु काय भागवू शकत नाही?\",\"options\":[\"तहान\",\"भूक\",\"हाव\",\"आशा\"],\"answer\":2,\"explain\":\"पाठातील \'हे नेहमी लक्षात ठेवा\' या भागात निसर्ग हाव भागवू शकत नाही असे स्पष्ट म्हटले आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"पर्यावरणातील कोणत्या घटकांचा एकमेकांशी संबंध असतो?\",\"options\":[\"केवळ जैविक घटक\",\"केवळ अजैविक घटक\",\"जैविक व अजैविक घटक\",\"केवळ मानव आणि प्राणी\"],\"answer\":2,\"explain\":\"पर्यावरणातील जैविक व अजैविक घटकांचे एकमेकांशी संबंध असतात हे आपण शिकलो आहोत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"हजारो वर्षांपासून पर्यावरणाचे संतुलन कशामुळे कायम राखले गेले आहे?\",\"options\":[\"वायूचक्र, जलचक्र आणि अन्नसाखळ्या\",\"केवळ मानवी हस्तक्षेप\",\"केवळ कारखान्यांमुळे\",\"केवळ प्राण्यांच्या संख्येमुळे\"],\"answer\":0,\"explain\":\"वातावरणातील वायूचक्र, जलचक्र आणि अन्नसाखळ्या यांच्यामुळे पर्यावरणाचे संतुलन टिकून आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"पाण्याच्या प्रदूषणामुळे खालीलपैकी कोणाला धोका पोहोचतो?\",\"options\":[\"केवळ जमिनीवरील प्राण्यांना\",\"केवळ हवेतील पक्षांना\",\"पाण्यातील वनस्पती व जलचरांना\",\"केवळ मानवाच्या घरांना\"],\"answer\":2,\"explain\":\"पाण्याच्या प्रदूषणामुळे त्यात वाढणाऱ्या वनस्पती व जलचरांना धोका पोहोचतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"पर्यावरणाचे संतुलन ढळण्यास मुख्यत्वे कोण कारणीभूत ठरत आहे?\",\"options\":[\"सूक्ष्मजीव\",\"मानवाचा हस्तक्षेप\",\"वनस्पतींची वाढ\",\"जलचक्र\"],\"answer\":1,\"explain\":\"मानवाच्या हस्तक्षेपामुळे पर्यावरणाचे संतुलन ढळत चालले आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"वनस्पती व प्राणी यांना संरक्षण मिळावे यासाठी खालीलपैकी कशाची निर्मिती केली जाते?\",\"options\":[\"मोठी शहरे\",\"जैवविविधता उद्याने\",\"रस्ते आणि महामार्ग\",\"कारखाने\"],\"answer\":1,\"explain\":\"वनस्पती व प्राण्यांच्या संरक्षणासाठी जैवविविधता उद्याने, राष्ट्रीय उद्याने व अभयारण्ये यांची निर्मिती होते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"वेगवेगळ्या प्रदेशात वेगवेगळे प्राणी आणि वनस्पती आढळतात, यावरून काय समजते?\",\"options\":[\"निसर्गात सर्वत्र सारखेच सजीव असतात\",\"पर्यावरणात विविधता असते\",\"प्राणी एकाच ठिकाणी राहतात\",\"सूक्ष्मजीव कोठेही नसतात\"],\"answer\":1,\"explain\":\"वेगवेगळ्या प्रदेशात वेगवेगळे प्राणी, वनस्पती आणि सूक्ष्मजीव आढळणे हे पर्यावरणातील विविधतेचे लक्षण आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"पर्यावरणाचे संतुलन राखण्याची जबाबदारी कोणाची आहे?\",\"options\":[\"केवळ प्राण्यांची\",\"केवळ वनस्पतींची\",\"आपली (मानवाची)\",\"कोणाचीच नाही\"],\"answer\":2,\"explain\":\"मानवाच्या हस्तक्षेपामुळे ढळत चाललेले पर्यावरणाचे संतुलन आपणच राखले पाहिजे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"\'निसर्ग हाव भागवू शकत नाही\' या विधानाचा योग्य अर्थ काय?\",\"options\":[\"निसर्गात काहीच उपलब्ध नाही\",\"आपण निसर्गाचा अमर्याद वापर करू नये\",\"निसर्ग फक्त प्राण्यांसाठी आहे\",\"मानवाने निसर्गाकडे लक्ष देऊ नये\"],\"answer\":1,\"explain\":\"हाव म्हणजे लोभ; निसर्ग गरजा पूर्ण करतो पण लोभ नाही, म्हणून संसाधनांचा वापर जपून करावा.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणते ठिकाण वनस्पती आणि प्राण्यांच्या संरक्षणासाठी राखून ठेवलेले असते?\",\"options\":[\"बाजारपेठ\",\"खेळाचे मैदान\",\"देवराई\",\"विमानतळ\"],\"answer\":2,\"explain\":\"देवराई ही वनस्पती व प्राण्यांना संरक्षण मिळावे यासाठी निर्माण झालेली एक जागा आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21617,24,5,'EVS Part 1','mr','अन्नघटक','[\"आहार म्हणजे शरीराला आवश्यक असणारे अन्नपदार्थ\",\"अन्नघटक तीन प्रकारचे असतात – पिष्टमय पदार्थ, शर्करा व तंतुमय पदार्थ\",\"पिष्टमय पदार्थ (कर्बोदके) शरीराला ऊर्जा देतात\",\"शर्करा म्हणजे गोड पदार्थ, ज्यातूनही ऊर्जा मिळते\",\"तंतुमय पदार्थ पचनात मदत करतात व बद्धकोष्ठता टाळतात\",\"स्निग्ध पदार्थ (चरबी) शरीराला उष्णता व संरक्षण देतात\",\"प्रथिने शरीराच्या वाढीसाठी व दुरुस्तीसा