ीला पचनाच्या तक्रारी असून पोट साफ होत नसेल, तर त्याला काय खाण्याचा सल्ला द्याल?\",\"options\":[\"जास्त गोड पदार्थ\",\"फळे (सालीसह) आणि पालेभाज्या\",\"मैद्याचे पदार्थ\",\"तळलेले पदार्थ\"],\"answer\":1,\"explain\":\"पालेभाज्या आणि फळांच्या सालींमध्ये तंतुमय पदार्थ असतात जे बद्धकोष्ठता दूर करतात.\",\"topic\":\"तंतुमय पदार्थ\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"धान्य बारीक दळून आणल्यावरही त्यात कोंडा का शिल्लक राहतो?\",\"options\":[\"धान्य खराब असल्यामुळे\",\"धान्य एकसारखे बारीक होत नसल्यामुळे\",\"गिरणी नीट नसल्यामुळे\",\"धान्य ओले असल्यामुळे\"],\"answer\":1,\"explain\":\"धान्य बारीक दळून आणले तरी ते एकसारखे बारीक होत नाही, म्हणून कोंडा शिल्लक राहतो.\",\"topic\":\"तंतुमय पदार्थ\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"कागदाला तेल लावल्यास तो कसा होतो?\",\"options\":[\"पारदर्शक\",\"अपारदर्शक\",\"अर्धपारदर्शक\",\"रंगीत\"],\"answer\":2,\"explain\":\"तेलामुळे कागद अर्धपारदर्शक होतो, हे पाठात दिले आहे.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"अन्नपदार्थात स्निग्ध पदार्थ असल्याची कोणती खूण आहे?\",\"options\":[\"कागद ओला होणे\",\"कागद अर्धपारदर्शक होणे\",\"कागद फाटणे\",\"कागद काळा पडणे\"],\"answer\":1,\"explain\":\"कागद अर्धपारदर्शक होणे ही अन्नपदार्थात स्निग्ध पदार्थ असल्याची खूण आहे.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"स्निग्ध पदार्थांपासून पिष्टाच्या तुलनेत किती ऊर्जा मिळते?\",\"options\":[\"समान\",\"अर्धी\",\"दुप्पट\",\"तिप्पट\"],\"answer\":2,\"explain\":\"पिष्टापासून मिळते त्यापेक्षा दुप्पट ऊर्जा स्निग्ध पदार्थांपासून मिळते.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता पदार्थ प्राण्यांपासून मिळणारा स्निग्ध पदार्थ आहे?\",\"options\":[\"गोडेतेल\",\"लोणी\",\"शेंगदाणे\",\"तांदूळ\"],\"answer\":1,\"explain\":\"लोणी हे दुधापासून (प्राण्यांपासून) मिळणारे स्निग्ध पदार्थाचे उदाहरण आहे.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"अंड्यातील कोणत्या भागात स्निग्ध पदार्थ असतात?\",\"options\":[\"पांढरा बलक\",\"कवच\",\"पिवळा बलक\",\"वरील सर्व\"],\"answer\":2,\"explain\":\"अंड्यातील बलक (पिवळा भाग) यात स्निग्ध पदार्थ असतात.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"शरीरातील चरबीचा थर कोठे असतो?\",\"options\":[\"हाडांच्या आत\",\"त्वचेखाली\",\"रक्तात\",\"मेंदूमध्ये\"],\"answer\":1,\"explain\":\"चरबीचा एक थर आपल्या त्वचेखाली असतो असे पाठात नमूद आहे.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"काही काळ अन्न मिळाले नाही, तर शरीराला ऊर्जा कशापासून मिळते?\",\"options\":[\"पाण्यापासून\",\"हवेपासून\",\"साठवलेल्या चरबीपासून\",\"हाडांपासून\"],\"answer\":2,\"explain\":\"काही काळ अन्न मिळाले नाही तर शरीरातील चरबीपासून ऊर्जा मिळू शकते.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"त्वचेखालील चरबीच्या थरामुळे शरीराला काय मिळते?\",\"options\":[\"रंग\",\"उंची\",\"आकार\",\"कडकपणा\"],\"answer\":2,\"explain\":\"चरबीच्या थरामुळे शरीराला आकार मिळतो.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"आपल्या आहारात स्निग्ध पदार्थांचे प्रमाण पिष्टमय पदार्थांच्या तुलनेत कसे असावे?\",\"options\":[\"जास्त\",\"कमी\",\"समान\",\"अजिबात नसावे\"],\"answer\":1,\"explain\":\"आहारात स्निग्ध पदार्थ पिष्टमय पदार्थांपेक्षा कमी प्रमाणात असतात.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एका प्रयोगात वडा कागदावर ठेवला असता कागद अर्धपारदर्शक झाला, तर त्यातून काय सिद्ध होते?\",\"options\":[\"वड्यात पाणी आहे\",\"वड्यात पिष्ट आहे\",\"वड्यात स्निग्ध पदार्थ आहेत\",\"वडा खराब झाला आहे\"],\"answer\":2,\"explain\":\"कागद अर्धपारदर्शक होणे ही स्निग्ध पदार्थांची चाचणी आहे.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता गट केवळ स्निग्ध पदार्थांचा आहे?\",\"options\":[\"तूप, लोणी, तेल\",\"बटाटा, भात, तेल\",\"दूध, साखर, मीठ\",\"तूप, गहू, अंडी\"],\"answer\":0,\"explain\":\"तूप, लोणी आणि तेल ही सर्व स्निग्ध पदार्थांची उदाहरणे आहेत.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"स्निग्ध पदार्थांचे शरीरातील मुख्य कार्य काय आहे?\",\"options\":[\"केवळ हाडे मजबूत करणे\",\"ऊर्जा देणे आणि चरबी साठवणे\",\"रक्त शुद्ध करणे\",\"पचन सुधारणे\"],\"answer\":1,\"explain\":\"स्निग्ध पदार्थांपासून ऊर्जा मिळते आणि शरीरात चरबी तयार होते.\",\"topic\":\"स्निग्ध पदार्थ\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"शरीराच्या बांधणीसाठी प्रामुख्याने कोणत्या अन्नघटकाची गरज असते?\",\"options\":[\"कर्बोदके\",\"स्निग्ध पदार्थ\",\"प्रथिने\",\"जीवनसत्त्वे\"],\"answer\":2,\"explain\":\"पाठात दिलेल्या माहितीनुसार, शरीराच्या बांधणीसाठी प्रथिनांची गरज असते.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"भिंत बांधण्यासाठी लागणाऱ्या विटांची तुलना शरीरातील कोणत्या घटकाशी केली आहे?\",\"options\":[\"पाणी\",\"प्रथिने\",\"हाडे\",\"स्नायू\"],\"answer\":1,\"explain\":\"भिंत बांधण्यासाठी जसे दगड किंवा विटांची गरज पडते, तसेच शरीराच्या बांधणीसाठी प्रथिनांची गरज असते.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"शरीराची सतत होणारी झीज भरून काढण्यासाठी कशाची गरज असते?\",\"options\":[\"प्रथिने\",\"साखर\",\"तेल\",\"मीठ\"],\"answer\":0,\"explain\":\"शरीराची सतत होणारी झीज आणि दुरुस्तीसाठी प्रथिनांची गरज असते.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"शरीराची वाढ होत असताना प्रथिनांची गरज कशी असते?\",\"options\":[\"कमी प्रमाणात\",\"भरपूर प्रमाणात\",\"गरज नसते\",\"फक्त आजारी असताना\"],\"answer\":1,\"explain\":\"शरीराची वाढ होत असताना प्रथिनांची भरपूर प्रमाणात गरज असते.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता पदार्थ प्रथिनांचा मुख्य स्रोत आहे?\",\"options\":[\"तांदूळ\",\"बटाटा\",\"कडधान्ये\",\"तेल\"],\"answer\":2,\"explain\":\"विविध कडधान्ये आणि डाळी हे प्रथिनांचे मुख्य स्रोत आहेत.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दुग्धजन्य पदार्थांपैकी प्रथिनांचा स्रोत कोणता आहे?\",\"options\":[\"तूप\",\"पनीर\",\"लोणी\",\"साखर\"],\"answer\":1,\"explain\":\"दूध, दही, खवा आणि पनीर हे प्रथिनांचे दुग्धजन्य स्रोत आहेत.\",\"topic\":\"प्रथिने\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"शरीराला मोठ्या प्रमाणावर लाग