:[\"तो फक्त भावनाशील आहे\",\"तो विचारक्षम आहे\",\"तो रागीट आहे\",\"तो घाबरलेला आहे\"],\"answer\":1,\"explain\":\"अभ्यासाचा विचार करणारा मुलगा माणसाच्या विचारक्षम असण्याचे उदाहरण आहे.\",\"topic\":\"भावनांचा मेळ कसा घालावा?\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"24\\/113_101.jpg\"},{\"q\":\"दिलेल्या चित्रात, ज्या मुलाच्या हातात \'प्रगतीपुस्तक\' आहे आणि त्याच्या चेहऱ्यावर दु:खी भाव आहेत, त्यावरून त्याला भावनांचा मेळ घालण्यासाठी काय करावे लागेल?\",\"options\":[\"त्याला अजून जास्त रडावे लागेल\",\"त्याला प्रगतीपुस्तक फाडून टाकावे लागेल\",\"त्याला किती वाईट वाटून घ्यायचे यावर नियंत्रण ठेवावे लागेल\",\"त्याला इतरांना दोष द्यावा लागेल\"],\"answer\":2,\"explain\":\"वाईट वाटणे स्वाभाविक असले तरी किती वाईट वाटून घ्यायचे हे कळणे म्हणजे भावनांचा मेळ घालणे होय.\",\"topic\":\"भावनांचा मेळ कसा घालावा?\",\"part\":2,\"bloom\":\"analyze\",\"figure_image\":\"24\\/113_101.jpg\"},{\"q\":\"आनंद आणि दुःख यांप्रमाणेच \'राग\' ही सुद्धा आपली एक काय आहे?\",\"options\":[\"सवय\",\"भावना\",\"गरज\",\"शक्ती\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार आनंद व दुःख यांप्रमाणेच राग ही सुद्धा आपली एक भावना आहे.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या प्रसंगी आपल्याला राग येतो?\",\"options\":[\"कोणी कौतुक केल्यावर\",\"आपला अपमान झाल्यावर\",\"खेळात जिंकल्यावर\",\"अभ्यास पूर्ण झाल्यावर\"],\"answer\":1,\"explain\":\"आपला अपमान झाला की आपल्याला राग येतो असे पाठात नमूद केले आहे.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"एखाद्यावर अन्याय झालेला पाहिला की कोणती भावना निर्माण होते?\",\"options\":[\"आनंद\",\"भीती\",\"राग\",\"संकोच\"],\"answer\":2,\"explain\":\"एखाद्यावर अन्याय झालेला पाहिला तरी आपल्याला राग येतो.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"रागाचा अतिरेक झाल्यास किंवा राग अनावर झाल्यास त्याचे कोणते दुष्परिणाम होतात?\",\"options\":[\"केवळ शारीरिक\",\"केवळ मानसिक\",\"मानसिक व शारीरिक\",\"काहीही परिणाम होत नाहीत\"],\"answer\":2,\"explain\":\"राग अनावर झाल्यास त्याचे मानसिक व शारीरिक दुष्परिणाम होतात.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सतत रागवणाऱ्या व्यक्तीच्या स्वभावात कोणता बदल होतो?\",\"options\":[\"ती व्यक्ती समजूतदार होते\",\"ती व्यक्ती रागीट व हट्टी होते\",\"ती व्यक्ती आनंदी होते\",\"ती व्यक्ती बुजरी होते\"],\"answer\":1,\"explain\":\"रागामुळे आपण रागीट व हट्टी होतो असे पाठात सांगितले आहे.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"रागामुळे खालीलपैकी कोणत्या वृत्तीत घट होते?\",\"options\":[\"हट्टीपणा\",\"रागिष्ठपणा\",\"सहकार्याची वृत्ती\",\"अन्याय करण्याची वृत्ती\"],\"answer\":2,\"explain\":\"रागामुळे समजूतपणा व सहकार्याची वृत्ती कमी होते.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"रागाच्या भरात आपल्या हातून कोणती चुकीची गोष्ट घडू शकते?\",\"options\":[\"इतरांना मदत करणे\",\"इतरांचे मन दुखावणे\",\"सर्वांना सहकार्य करणे\",\"शांत राहणे\"],\"answer\":1,\"explain\":\"रागाच्या भरात आपण इतरांचे मन दुखावतो.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता आजार रागाच्या दुष्परिणामामुळे होऊ शकतो?\",\"options\":[\"ताप\",\"खोकला\",\"रक्तदाब\",\"कावीळ\"],\"answer\":2,\"explain\":\"रागामुळे डोकेदुखी, निद्रानाश आणि रक्तदाब यांसारख्या समस्या उद्भवू शकतात.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"रणजित आणि अभय यांच्यात कोणत्या कारणावरून वाद झाला होता?\",\"options\":[\"खेळण्यावरून\",\"पहिल्या बाकावर बसण्यावरून\",\"वही घरी नेल्यावरून\",\"शिक्षकांना सांगण्यावरून\"],\"answer\":1,\"explain\":\"रणजित आणि अभय यांच्यात पहिल्या बाकावर कोण बसणार यावरून वाद झाला होता.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"रागामुळे होणारा \'निद्रानाश\' हा परिणाम कशाशी संबंधित आहे?\",\"options\":[\"भूक न लागणे\",\"झोप न येणे\",\"विसर पडणे\",\"खूप झोप येणे\"],\"answer\":1,\"explain\":\"निद्रानाश म्हणजे झोप न येणे, जो रागाचा एक दुष्परिणाम आहे.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर निशाची वही रेखाने चुकून घरी नेली, तर निशाने रागावण्याऐवजी काय दाखवणे गरजेचे आहे?\",\"options\":[\"हट्टीपणा\",\"समजूतपणा\",\"अपमान\",\"अन्याय\"],\"answer\":1,\"explain\":\"अशा प्रसंगी रागावण्याऐवजी समजूतपणा दाखवणे हे भावनिक आरोग्यासाठी चांगले असते.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"रागावर नियंत्रण न मिळवल्यास सामाजिक संबंधांवर काय परिणाम होईल?\",\"options\":[\"मित्र वाढतील\",\"सहकार्य वाढेल\",\"इतरांची मने दुखावली जातील\",\"मान सन्मान वाढेल\"],\"answer\":2,\"explain\":\"रागाच्या भरात आपण इतरांचे मन दुखावतो, ज्यामुळे सामाजिक संबंध बिघडतात.\",\"topic\":\"राग आणि त्याचे दुष्परिणाम\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"रमेशने सुरेशला त्याच्याबद्दल कोणीतरी वाईट बोलल्याचे सांगितल्यावर सुरेशने काय ठरवले?\",\"options\":[\"लगेच भांडायला जायचे\",\"रमेशवर विश्वास ठेवायचा\",\"खात्री करून घेऊनच प्रतिक्रिया द्यायची\",\"दुसऱ्याला जाऊन सांगायचे\"],\"answer\":2,\"explain\":\"सुरेशने घटनेची सत्यता पडताळून पाहण्याचे ठरवले, जे भावनांवर नियंत्रण ठेवण्याचे लक्षण आहे.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी छायाच्या निबंधाचे कौतुक केल्यावर मीनाला राग का आला?\",\"options\":[\"तिला निबंध लिहिता येत नव्हता\",\"दोघींची अभ्यासात सारखीच प्रगती होती\",\"छायाने तिची पेन्सिल लपवली होती\",\"तिला शिक्षकांचा राग आला होता\"],\"answer\":1,\"explain\":\"दोघींची प्रगती सारखी असूनही फक्त एकाचे कौतुक झाल्यामुळे मीनाला मत्सर वाटला.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दिनेशने मनोजची वस्तू लपवल्यानंतर आपली चूक कशी सुधारली?\",\"options\":[\"मनोजला नवीन पेन दिले\",\"दुसऱ्याची तक्रार केली\",\"माफी मागितली व पुन्हा तसे न करण्याचे आश्वासन दिले\",\"काहीच न करता गप्प बसला\"],\"answer\":2,\"explain\":\"चूक मान्य करून माफी मागणे आणि आश्वासन देणे ही सकारात्मक कृती आहे.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"सुनीताचा राग कोणत्या गोष्टीमुळे निवळला?\",\"options\":[\"आईने तिला नवीन खेळणी दिली\",\"तिला आईचे लवकर जाण्याचे कारण पटले\",\"ती स्वतः बाजारात गेली\",\"तिने आईशी बोलणे बंद केले\"],\"answer\":1,\"explain\":\"परिस्थिती समजून घेतल्यामुळे सुनीताचा राग शांत झाला.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिनेशने मनोजच्या दप्तरातील कोणत्या वस्तू लपवून ठेवल्या होत्या?\",\"options\":[\"वही आणि पुस्तक\",\"पेन आणि पेन्सिल\",\"डबा आणि पाण्याची बाटली\",\"रबर आणि पट्टी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील मजकुरानुसार दिनेशने पेन व पेन्सिल लपवली होती.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सुरेशच्या वागण्यातून आपल्याला कोणता धडा मिळतो?\",\"options\":[\"कोणाचेही ऐकू नये\",\"अफवांवर विश्वास ठेवू नये\",\"सत्य जाणून घेतल्याशिवाय प्रतिक्रिया देऊ नये\",\"नेहमी शांत राहावे\"],\"answer\":2,\"explain\":\"घटनेची खात्री करणे हे भावनांवर नियंत्रण ठेवण्यासाठी आवश्यक असते.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्या मित्राचे शिक्षकांनी कौतुक केले, तर तुम्ही मीनासारखे वागणे टाळण्यासाठी काय कराल?\",\"options\":[\"त्याच्याशी बोलणे बंद करू\",\"त्याचे अभिनंदन करू आणि स्वतः अधिक प्रयत्न करू\",\"शिक्षकांकडे तक्रार करू\",\"स्वतःचा निबंध फाडून टाकू\"],\"answer\":1,\"explain\":\"मत्सर करण्याऐवजी कौतुक करणे हे भावनिक नियंत्रणाचे उदाहरण आहे.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"सुनीताला कोणाबरोबर बाजारात जायचे होते?\",\"options\":[\"वडिलांबरोबर\",\"आईबरोबर\",\"मैत्रिणीबरोबर\",\"भावाबरोबर\"],\"answer\":1,\"explain\":\"मजकुरात उल्लेख केल्याप्रमाणे सुनीताला आईबरोबर बाजारात जायचे होते.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"रमेशने सुरेशला काय सांगितले?\",\"options\":[\"त्याच्याबद्दल कोणीतरी वाईट बोलल्याचे\",\"त्याचा निबंध चांगला असल्याचे\",\"त्याला बाजारात जायचे असल्याचे\",\"त्याचे पेन हरवल्याचे\"],\"answer\":0,\"explain\":\"रमेशने सुरेशला त्याच्याबद्दलच्या नकारात्मक बोलण्याबाबत सांगितले होते.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"मीनाने छायाशी न बोलण्याचे ठरवले, ही कृती योग्य आहे की अयोग्य?\",\"options\":[\"योग्य, कारण तिचा अपमान झाला\",\"अयोग्य, कारण तिने रागावर नियंत्रण ठेवले नाही\",\"योग्य, कारण छाया तिची मैत्रीण नव्हती\",\"अयोग्य, कारण छायाने तिची माफी मागितली नाही\"],\"answer\":1,\"explain\":\"दुसऱ्याच्या यशाचा राग येणे आणि संवाद तोडणे हे अयोग्य वर्तन आहे.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"सुनीताने रागावल्यानंतर प्रथम कोणती गोष्ट केली?\",\"options\":[\"रडायला सुरुवात केली\",\"आईला लवकर जाण्याचे कारण विचारले\",\"घराबाहेर निघून गेली\",\"जेवण केले नाही\"],\"answer\":1,\"explain\":\"रागाच्या भरात चुकीची कृती करण्याऐवजी तिने संवाद साधून कारण जाणून घेतले.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"छाया आणि मीना यांच्यात कोणता समान गुण होता?\",\"options\":[\"त्या दोघींना चित्रकला आवडायची\",\"त्या दोघी अभ्यासात सारखीच प्रगती करणाऱ्या होत्या\",\"त्या दोघींना खेळायला आवडायचे\",\"त्या दोघी एकाच घरात राहायच्या\"],\"answer\":1,\"explain\":\"मजकुरात त्यांच्या अभ्यासातील प्रगती सारखी असल्याचे नमूद केले आहे.\",\"topic\":\"भावनांवर नियंत्रण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"आपल्याला ज्या गोष्टी नीट जमत नाहीत, त्यांना उताऱ्यात काय म्हटले आहे?\",\"options\":[\"आवडनिवड\",\"क्षमता\",\"उणिवा\",\"कौशल्य\"],\"answer\":2,\"explain\":\"उताऱ्यात आपल्याला काय येत नाही किंवा ज्या गोष्टींत आपली गती कमी असते, त्यांना \'उणिवा\' म्हटले आहे.\",\"topic\":\"आपल्यातील उणिवांची जाणीव\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"आपल्याला आपल्या क्षमता कशा प्रकारे समजू लागतात?\",\"options\":[\"एका दिवसात\",\"हळूहळू\",\"जन्मजात\",\"कोणीतरी सांगितल्यावरच\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की आपल्याला आपल्या क्षमता हळूहळू समजू लागतात.\",\"topic\":\"आपल्यातील उणिवांची जाणीव\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"प्रत्येक व्यक्तीच्या आवडनिवडी आणि क्षमता कशा असतात?\",\"options\":[\"सारख्याच असतात\",\"फक्त मित्रांसारख्या असतात\",\"वेगवेगळ्या असतात\",\"बदलत नाहीत\"],\"answer\":2,\"explain\":\"प्रत्येक 