\":10,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीला खूप राग येत असेल, तर तिने काय करणे आरोग्यासाठी हिताचे आहे?\",\"options\":[\"रागाच्या भरात ओरडणे.\",\"रागावर नियंत्रण ठेवणे.\",\"जेवण सोडणे.\",\"कोणाशीही न बोलणे.\"],\"answer\":1,\"explain\":\"रागावर नियंत्रण ठेवल्याने शारीरिक व मानसिक दुष्परिणाम टाळता येतात.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला तुमच्यातील एखाद्या कमतरतेची (उणीव) जाणीव झाली, तर तुम्ही काय कराल?\",\"options\":[\"ती बदलण्यासाठी प्रयत्न करेन.\",\"ती उणीव तशीच ठेवेन.\",\"दुसऱ्यांवर राग व्यक्त करेन.\",\"स्वतःला दोष देत बसेन.\"],\"answer\":0,\"explain\":\"स्वभावातील उणिवा प्रयत्नांनी बदलता येतात, म्हणून प्रयत्न करणे योग्य आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विधान योग्य भावनिक विकासासाठी बरोबर आहे?\",\"options\":[\"केवळ भावना महत्त्वाच्या असतात, विचार नाही.\",\"उणिवा कधीच बदलता येत नाहीत.\",\"विचार आणि भावनांचा मेळ घालणे आवश्यक आहे.\",\"राग व्यक्त करणे नेहमीच चांगले असते.\"],\"answer\":2,\"explain\":\"विचार आणि भावनांचा मेळ घालणे हे भावनिक विकासासाठी आवश्यक आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"शारीरिक आणि मानसिक स्वास्थ्यासाठी खालीलपैकी कोणती गोष्ट टाळली पाहिजे?\",\"options\":[\"भावना व्यक्त करणे.\",\"क्षमतांची जाणीव असणे.\",\"अनियंत्रित राग.\",\"उणिवा बदलण्याचा प्रयत्न.\"],\"answer\":2,\"explain\":\"रागावर नियंत्रण न ठेवल्यास दुष्परिणाम होतात, म्हणून अनियंत्रित राग टाळला पाहिजे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"स्वतःच्या स्वभावाचे परीक्षण करताना कोणत्या दोन गोष्टींची जाणीव असणे महत्त्वाचे आहे?\",\"options\":[\"यश आणि अपयश\",\"क्षमता आणि उणिवा\",\"सुख आणि दुःख\",\"राग आणि आनंद\"],\"answer\":1,\"explain\":\"पाठात क्षमता आणि उणिवा या दोन्हीची जाणीव असण्यावर भर दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":10,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21619,24,5,'EVS Part 1','mr','कामांत व्यस्त आपली आंतरेंद्रिये','[\"श्वसन म्हणजे शरीरात ऑक्सिजन घेऊन कार्बन डायऑक्साइड बाहेर टाकणे होय.\",\"श्वसनाचे प्रमुख अवयव नाक, श्वासनलिका, फुप्फुसे आणि श्वासपटल आहेत.\",\"श्वसनाची पोकळी फुप्फुसात असते, जिथे वायूंची देवाणघेवाण होते.\",\"श्वसनाचे कार्य शरीराला ऑक्सिजन पुरवणे आणि कार्बन डायऑक्साइड काढून टाकणे हे आहे.\",\"श्वसनाचे संरक्षण करणारी हाडे म्हणजे छातीची पिंजरे (स्टर्नम, पसळी आणि कशेरुक).\",\"पचन म्हणजे अन्नाचे शरीरात शोषण होणारे रासायनिक आणि यांत्रिक प्रक्रिया.\",\"पचनाचे प्रमुख अवयव तोंड, अन्ननलिका, जठर, लहान आतडे आणि मोठे आतडे आहेत.\",\"पचनात लाळ आणि पाचकरस (पाचक रस) महत्त्वाची भूमिका बजावतात.\",\"पचनादरम्यान अन्न पचनक्रियेने लहान तुकड्यांमध्ये विभागले जाते.\",\"पचनातून तयार झालेले पोषक तत्त्वे रक्तात शोषले जातात आणि शरीरात वितरित होतात.\",\"रक्ताभिसरण म्हणजे रक्ताचे शरीरभर फिरणे, ज्यामुळे ऑक्सिजन व पोषक तत्त्वे पोहोचतात.\",\"रक्ताभिसरणाचे प्रमुख अवयव हृदय, रक्तवाहिन्या आणि रक्त आहेत.\",\"हृदय सतत आकुंचन-शिथिलीकरण करून रक्त पंप करते.\",\"चेतासंस्था म्हणजे मेंदू आणि चेतातंतूंचे जाळे, जे शरीरातील सर्व क्रिया समन्वयित करते.\",\"चेतासंस्थेचे प्रमुख अवयव मेंदू, चेतातंतू आणि मेंदूचे तंतु आहेत.\",\"श्वसन, पचन, रक्ताभिसरण आणि चेतासंस्था या सर्वांना एकत्रितपणे शरीराची \'इंद्रियसंस्था\' म्हणतात.\",\"श्वसनात धूळ व धुराचे कण श्वसनमार्गात अडकतात, ज्यामुळे श्वसनाचे आजार होऊ शकतात.\",\"धूम्रपानामुळे फुप्फुसात श्लेष्म जमा होते आणि ऑक्सिजन पुरवठा कमी होतो.\",\"मद्यपानामुळे चेतासंस्थेवर परिणाम होऊन समन्वय कमी होतो.\",\"शरीरातील ऊर्जा मिळवण्यासाठी श्वसन, पचन आणि रक्ताभिसरण हे एकत्र काम करतात.\",\"दातांना एनॅमल नावाचे कठीण आवरण असते, ज्यामुळे दातांचे संरक्षण होते.\",\"दातांची नियमित स्वच्छता न केल्यास दात किडतात.\",\"शरीरातील पाणी पचनक्रियेकरिता आवश्यक आहे, पाणी कमी झाल्यास पचनात अडचण येते.\",\"शरीरात पचनादरम्यान तयार होणारे विष्ठा मोठ्या आतड्यातून बाहेर टाकले जाते.\",\"शरीरातील सर्व अवयव एकमेकांशी संवाद साधून समन्वय राखतात.\"]','[{\"q\":\"मजकुरात खालीलपैकी कोणत्या आंतरेंद्रियाचा उल्लेख नाही?\",\"options\":[\"मेंदू\",\"हृदय\",\"जठर\",\"मूत्रपिंड\"],\"answer\":3,\"explain\":\"दिलेल्या मजकुरात मेंदू, हृदय, फुप्फुसे आणि जठर या चार इंद्रियांचा उल्लेख आहे, पण मूत्रपिंडाचा नाही.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"कागदावर शरीराची बाह्यरेषा काढण्याचा मुख्य उद्देश काय आहे?\",\"options\":[\"विद्यार्थ्याची उंची मोजणे\",\"आंतरेंद्रियांची शरीरातील ठिकाणे दर्शवणे\",\"कागद भिंतीवर पक्का चिकटवणे\",\"चित्रात रंग भरण्यास शिकवणे\"],\"answer\":1,\"explain\":\"बाह्यरेषेचा उपयोग आंतरेंद्रियांची शरीरातील नेमकी जागा दाखवण्यासाठी केला जातो.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"\'जठर\' हे इंद्रिय शरीराच्या कोणत्या भागात असते हे दर्शवण्यासाठी तुम्ही बाह्यरेषेत कोठे खूण कराल?\",\"options\":[\"डोके\",\"छाती\",\"पोट\",\"हात\"],\"answer\":2,\"explain\":\"जठर हे पोटाच्या भागात (उदरपोकळीत) असते, म्हणून पोटावर खूण करावी लागेल.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"इंद्रियांचे संरक्षण करणाऱ्या हाडांची माहिती असणे का महत्त्वाचे आहे?\",\"options\":[\"इंद्रियांचे वजन मोजण्यासाठी\",\"इंद्रिय सुरक्षित कसे राहते हे समजण्यासाठी\",\"इंद्रियाचा रंग ओळखण्यासाठी\",\"हाडांची संख्या मोजण्यासाठी\"],\"answer\":1,\"explain\":\"हाडे महत्त्वाची नाजूक आंतरेंद्रिये सुरक्षित ठेवण्याचे काम करतात, हे समजण्यासाठी ही माहिती आवश्यक आहे.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"मजकुरात दिलेल्या कोणत्या इंद्रियाचे संरक्षण कवटीच्या हाडांमुळे होते?\",\"options\":[\"हृदय\",\"फुप्फुसे\",\"मेंदू\",\"जठर\"],\"answer\":2,\"explain\":\"मेंदू हा डोक्यात असतो आणि त्याचे संरक्षण कवटीच्या हाडांमुळे होते.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'आंतरेंद्रिय\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"शरीराच्या बाहेरील अवयव\",\"शरीराच्या आतील अवयव\",\"डोळ्यांनी दिसणारे अवयव\",\"केवळ हात आणि पाय\"],\"answer\":1,\"explain\":\"जे अवयव शरीराच्या आत असतात आणि बाहेरून दिसत नाहीत, त्यांना आंतरेंद्रिये म्हणतात.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात मुले कागदावर काय काढत आहेत?\",\"options\":[\"झाडाचे चित्र\",\"शरीराची बाह्यरेषा\",\"घराचे चित्र\",\"फुलांचे चित्र\"],\"answer\":1,\"explain\":\"चित्रात एक मुलगी भिंतीवरील कागदावर मुलाच्या शरीराची बाह्यरेषा काढताना दिसत आहे.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"24\\/117_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील कृतीनुसार, शरीराच्या बाह्यरेषेच्या आत \'मेंदू\' हे इंद्रिय कोठे दर्शवले जाईल?\",\"options\":[\"सर्वात वरच्या भागात (डोक्यात)\",\"सर्वात खालच्या भागात (पायात)\",\"मध्यभागी (छातीत)\",\"हाताच्या बाजूला\"],\"answer\":0,\"explain\":\"मेंदू हा शरीराच्या सर्वात वरच्या भागात म्हणजेच डोक्यात असतो, त्यामुळे तो बाह्यरेषेच्या वरच्या भागात येईल.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"24\\/117_101.jpg\"},{\"q\":\"मजकुरानुसार, प्रत्येक इंद्रियाबद्दल खालीलपैकी कोणती गोष्ट आठवण्यास सांगितली आहे?\",\"options\":[\"इंद्रियाचा रंग\",\"इंद्रियाचे कार्य\",\"इंद्रियाचा आकार\",\"इंद्रियाचे नाव\"],\"answer\":1,\"explain\":\"मजकुरात इंद्रियाचे कार्य, त्याची पोकळी आणि संरक्षण करणारी हाडे या तीन गोष्टी आठवायला सांगितल्या आहेत.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मजकुरानुसार, शरीराच्या बाह्यरेषेच्या आत एकूण किती आंतरेंद्रियांची ठिकाणे दर्शवायला सांगितली आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"मजकुरात मेंदू, फुप्फुसे, हृदय आणि जठर या चार आंतरेंद्रियांची नावे दिली आहेत.\",\"topic\":\"थोडे आठवा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या मजकुरानुसार, शरीरात सतत चालू असणाऱ्या क्रियेचे उदाहरण कोणते?\",\"options\":[\"खेळणे\",\"धावणे\",\"श्वसन\",\"गाणे\"],\"answer\":2,\"explain\":\"मजकुरात श्वसन आणि पचन या शरीरात सतत चालू असणाऱ्या क्रिया असल्याचे सांगितले आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पुस्तक वाचत असताना खालीलपैकी कोणती क्रिया शरीरात सुरू असते?\",\"options\":[\"केवळ वाचन\",\"श्वसन आणि पचन\",\"केवळ पचन\",\"कोणतीही क्रिया सुरू नसते\"],\"answer\":1,\"explain\":\"पुस्तक वाचत असतानाही शरीरात श्वसन आणि पचन यांसारख्या अनेक क्रिया सुरू असतात.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"शरीरातील क्रिया घडवून आणणाऱ्या भागांना काय म्हणतात?\",\"options\":[\"हाडे\",\"इंद्रिये\",\"स्नायू\",\"त्वचा\"],\"answer\":1,\"explain\":\"मजकुरानुसार, शरीरातील विविध क्रिया इंद्रिये घडवून आणतात.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"एका मिनिटात तुम्ही किती वेळा श्वास घेता, हे मोजण्यासाठी कशाची मदत घेण्यास सांगितले आहे?\",\"options\":[\"पुस्तकाची\",\"घड्याळाची\",\"आरशाची\",\"मित्राची\"],\"answer\":1,\"explain\":\"श्वासांची संख्या मोजण्यासाठी घड्याळाची मदत घेण्यास सांगितले आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर एका मिनिटात तुम्ही १५ वेळा श्वास घेतला, तर एका तासात (६० मिनिटे) साधारणपणे किती वेळा श्वास घ्याल?\",\"options\":[\"६० वेळा\",\"१५० वेळा\",\"९०० वेळा\",\"१५ वेळा\"],\"answer\":2,\"explain\":\"एका मिनिटाचे १५ श्वास गुणिले ६० मिनिटे (१ तास) = ९०० श्वास.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"शरीरातील श्वसन आणि पचन या क्रिया कधी चालू असतात?\",\"options\":[\"केवळ जेवताना\",\"केवळ झोपताना\",\"दररोजच्या जीवनात सतत\",\"केवळ खेळताना\"],\"answer\":2,\"explain\":\"या क्रिया दररोजच्या जीवनामध्ये सतत चालू असतात असे मजकुरात नमूद केले आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"निवांत बसलेल्या स्थितीत श्वास मोजण्याच्या कृतीतून आपल्याला काय समजते?\",\"options\":[\"आपल्याला भूक लागली आहे\",\"आपल्याला झोप येत आहे\",\"शरीरातील क्रियेची गती आणि जाणीव\",\"पुस्तकातील मजकूर\"],\"answer\":2,\"explain\":\"ही कृती शरीरातील श्वसन क्रियेची जाणीव करून देण्यासाठी दिली आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जर एका मिनिटात श्वासांची संख्या २० असेल, तर एका तासातील श्वासांची संख्या काढण्यासाठी कोणती क्रिया करावी लागेल?\",\"options\":[\"२० + ६०\",\"२० - ६०\",\"२० × ६०\",\"६० ÷ २०\"],\"answer\":2,\"explain\":\"एका मिनिटावरून एका तासाचे (६० मिनिटे) प्रमाण काढण्यासाठी गुणाकार करावा लागतो.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती क्रिया आपण जाणीवपूर्वक न करताही शरीरात आपोआप सतत घडत असते?\",\"options\":[\"सायकल चालवणे\",\"पचन\",\"चित्र काढणे\",\"गाणे गाणे\"],\"answer\":1,\"explain\":\"पचन ही शरीरात सतत चालू असणारी एक नैसर्गिक क्रिया आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मजकुरातील \'करून पाहा\' या भागाचा मुख्य उद्देश काय आहे?\",\"options\":[\"वेळ घालवणे\",\"घड्याळ दुरुस्त करणे\",\"शरीरातील श्वसन क्रियेचा अनुभव घेणे\",\"वाचन सुधारणे\"],\"answer\":2,\"explain\":\"स्वतःचे श्वास मोजून शरीरातील क्रियेचा प्रत्यक्ष अनुभव घेणे हा या कृतीचा उद्देश आहे.\",\"topic\":\"आपल्या शरीरातील क्रिया\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जगण्यासाठी आपल्याला खालीलपैकी कोणत्या तीन गोष्टींची गरज असते?\",\"options\":[\"हवा, पाणी आणि कपडे\",\"हवा, पाणी आणि अन्न\",\"अन्न, निवारा आणि शिक्षण\",\"हवा, प्रकाश आणि माती\"],\"answer\":1,\"explain\":\"पाठाच्या सुरुवातीनुसार जगण्यासाठी हवा, पाणी आणि अन्न या तीन गोष्टींची गरज असते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"फुप्फुसातील श्वसननलिकेच्या प्रत्येक शाखेच्या टोकाशी असलेल्या हवेच्या पिशव्यांना काय म्हणतात?\",\"options\":[\"रक्तवाहिन्या\",\"श्वसननलिका\",\"वायुकोश\",\"श्वासपटल\"],\"answer\":2,\"explain\":\"फुप्फुसातील शाखेच्या टोकाशी असलेल्या हवेच्या पिशव्यांना वायुकोश म्हणतात.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"ओघळपट्टी आणि उदरपोकळी दरम्यान असलेल्या लवचीक पडद्यासारख्या अवयवाला काय म्हणतात?\",\"options\":[\"हवेची पिशवी\",\"श्वासपटल\",\"श्वसननलिका\",\"रक्तवाहिनी\"],\"answer\":1,\"explain\":\"ओघळपट्टी आणि उदरपोकळी दरम्यानच्या लवचीक पडद्याला श्वासपटल म्हणतात.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शरीराच्या सर्व भागांत ऑक्सिजन कोणामार्फत वाहून नेला जातो?\",\"options\":[\"हवेमार्फत\",\"पाण्यामार्फत\",\"रक्तामार्फत\",\"अन्नामार्फत\"],\"answer\":2,\"explain\":\"हवेतील ऑक्सिजन वायुकोशांभोवतीच्या रक्तवाहिन्यांत जातो आणि रक्तातून शरीराच्या सर्व भागांत वाहून नेला जातो.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जेव्हा श्वासपटल खालच्या दिशेने सरकते, तेव्हा काय घडते?\",\"options\":[\"हवा नाकावाटे शरीराबाहेर टाकली जाते.\",\"हवा नाकावाटे येऊन वायुकोशात भरते.\",\"रक्तातील कार्बन डायऑक्साइड वाढतो.\",\"हवेची हालचाल थांबते.\"],\"answer\":1,\"explain\":\"श्वासपटल खालच्या दिशेने सरकते तेव्हा श्वास घेतला जातो आणि हवा वायुकोशात भरते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वायूंची देवाणघेवाण श्वसनसंस्थेच्या कोणत्या भागात होते?\",\"options\":[\"नाकामध्ये\",\"श्वसननलिकेत\",\"वायुकोशांमध्ये\",\"उदरपोकळीत\"],\"answer\":2,\"explain\":\"वायुकोशांमध्ये ऑक्सिजन व कार्बन डायऑक्साइड या वायूंची देवाणघेवाण होते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"उच्छ्‌वासाच्या वेळी शरीरातून कोणता वायू बाहेर टाकला जातो?\",\"options\":[\"ऑक्सिजन\",\"नायट्रोजन\",\"हायड्रोजन\",\"कार्बन डायऑक्साइड\"],\"answer\":3,\"explain\":\"शरीराच्या भागांतून आलेला कार्बन डायऑक्साइड उच्छ्‌वासावाटे बाहेर टाकला जातो.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"हवेतील ऑक्सिजनचा पुरवठा शरीराला सतत होण्यासाठी कोणती क्रिया सतत चालू असणे गरजेचे असते?\",\"options\":[\"पचन\",\"श्वासोच्छ्‌वास\",\"रक्तभिसरण\",\"हालचाल\"],\"answer\":1,\"explain\":\"शरीराला ऑक्सिजनचा सतत पुरवठा होण्यासाठी श्वासोच्छ्‌वास सतत चालू असणे गरजेचे असते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या व्यक्तीने नाकावाटे हवा आत घेतली, तर त्या हवेचा प्रवास कसा असेल?\",\"options\":[\"नाक -> वायुकोश -> श्वसननलिका\",\"नाक -> श्वसननलिका -> वायुकोश\",\"नाक -> उदरपोकळी -> फुप्फुस\",\"नाक -> श्वासपटल -> श्वसननलिका\"],\"answer\":1,\"explain\":\"हवा नाकावाटे श्वसननलिकेत जाते आणि तिथून शाखांमार्फत वायुकोशात पोहोचते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"एखादी व्यक्ती हवा बाहेर सोडत (उच्छ्‌वास) असेल, तर तिच्या श्वासपटलाची हालचाल कशी होत असेल?\",\"options\":[\"श्वासपटल खालच्या दिशेने सरकत असेल.\",\"श्वासपटल स्थिर असेल.\",\"श्वासपटल वरच्या दिशेने सरकत असेल.\",\"श्वासपटल उजव्या दिशेने सरकत असेल.\"],\"answer\":2,\"explain\":\"श्वासपटल वरच्या दिशेने सरकते तेव्हा उच्छ्‌वासावाटे हवा बाहेर टाकली जाते.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"वायुकोशांभोवती असलेल्या बारीक रक्तवाहिन्यांचे मुख्य कार्य काय आहे?\",\"options\":[\"हवा साठवून ठेवणे.\",\"हवेतील ऑक्सिजन शोषून घेणे व कार्बन डायऑक्साइड हवेत सोडणे.\",\"श्वासपटल वर-खाली हलवणे.\",\"नाकावाटे हवा आत ओढणे.\"],\"answer\":1,\"explain\":\"रक्तवाहिन्या हवेतील ऑक्सिजन घेतात आणि शरीरातील कार्बन डायऑक्साइड वायुकोशातील हवेत सोडतात.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"श्वसननलिकेच्या दोन शाखांचे महत्त्व काय आहे?\",\"options\":[\"त्या हवा थेट पोटात नेतात.\",\"त्या हवा दोन्ही फुप्फुसांत विभागून नेतात.\",\"त्या कार्बन डायऑक्साइड तयार करतात.\",\"त्या श्वासपटल धरून ठेवतात.\"],\"answer\":1,\"explain\":\"श्वसननलिकेच्या दोन शाखांमार्फत हवा फुप्फुसात शिरते, जिथे पुढे अनेक उपशाखा फुटतात.\",\"topic\":\"श्वसन व श्वसनसंस्था\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"श्वसनेंद्रियांच्या आतील त्वचेवर काय असते?\",\"options\":[\"हाडे\",\"बारीक केसांसारखी लव\",\"स्नायू\",\"रक्तवाहिन्या\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, श्वसनेंद्रियांच्या आतील त्वचेला बारीक केसांसारखी लव असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हवेतील हानिकारक कण फुप्फुसांपर्यंत का पोहोचू शकत नाहीत?\",\"options\":[\"फुप्फुसे खूप लांब असल्यामुळे\",\"हवा शुद्ध असल्यामुळे\",\"लव आणि श्लेष्म यांमुळे कण तिथेच चिकटतात\",\"आपण श्वास रोखून धरतो म्हणून\"],\"answer\":2,\"explain\":\"हवेतील कण लव आणि श्लेष्म यांवर चिकटून बसतात, त्यामुळे ते फुप्फुसांपर्यंत पोहोचत नाहीत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"धावण्याच्या क्रियेनंतर श्वासाच्या संख्येत कोणता बदल होतो?\",\"options\":[\"श्वासाची संख्या कमी होते\",\"श्वासाची संख्या वाढते\",\"श्वासाची संख्या स्थिर राहते\",\"श्वास घेणे थांबते\"],\"answer\":1,\"explain\":\"शरीर हालचाल करत असताना किंवा धावताना श्वासाची गती वाढते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या माहितीनुसार, पुरेसे पाणी न प्यायल्यास कोणता त्रास होऊ शकतो?\",\"options\":[\"ताप येणे\",\"बद्धकोष्ठता\",\"सर्दी होणे\",\"डोकेदुखी\"],\"answer\":1,\"explain\":\"दिलेल्या आकृतीतील माहितीनुसार, पुरेसे पाणी न प्यायल्यास बद्धकोष्ठतेचा त्रास होऊ शकतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"24\\/120_101.jpg\"},{\"q\":\"दिलेल्या माहितीनुसार, अन्नमार्गातून अन्न पुढे सरकण्यासाठी कशाची गरज असते?\",\"options\":[\"हवेची\",\"रक्ताची\",\"पुरेशा पाण्याची\",\"हाडांची\"],\"answer\":2,\"explain\":\"अन्नमार्गातून अन्न पुढे सरकत राहण्यासाठी पुरेशा पाण्याची गरज असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"24\\/120_101.jpg\"},{\"q\":\"श्वसनेंद्रियांच्या आतल्या स्तरावर असणाऱ्या चिकट बुळबुळीत पदार्थाला काय म्हणतात?\",\"options\":[\"लाळ\",\"श्लेष्म\",\"रक्त\",\"पित्त\"],\"answer\":1,\"explain\":\"श्वसनेंद्रियांच्या आतल्या स्तरावर चिकट बुळबुळीत श्लेष्म असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'श्लेष्म\' या पदार्थाला रोजच्या भाषेत काय म्हणतात?\",\"options\":[\"थुंकी\",\"शेंबूड\",\"घाम\",\"लघवी\"],\"answer\":1,\"explain\":\"श्लेष्म या पदार्थाला आपण रोजच्या भाषेत शेंबूड म्हणतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या व्यक्तीला शौचाला होताना खडा पडत असेल, तर त्याला काय करावे लागेल?\",\"options\":[\"जास्त व्यायाम करावा लागेल\",\"कमी जेवावे लागेल\",\"पुरेसे पाणी प्यावे लागेल\",\"जास्त झोपावे लागेल\"],\"answer\":2,\"explain\":\"बद्धकोष्ठता (खडा पडणे) टाळण्यासाठी पुरेसे पाणी पिणे महत्त्वाचे आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पचनक्रियेत शोषले जाणारे पाणी शरीरासाठी का महत्त्वाचे आहे?\",\"options\":[\"त्याचा उपयोग शरीरातील इतर सर्व कामांसाठी होतो\",\"ते फक्त अन्न पचवण्यासाठी लागते\",\"