ptions\":[\"रक्त वेगाने वाहू लागेल\",\"रक्ताचे वहन थांबेल\",\"रक्त केवळ फुप्फुसांकडे जाईल\",\"रक्ताचे प्रमाण वाढेल\"],\"answer\":1,\"explain\":\"रक्त वाहन ठेवण्याचे काम हृदयाच्या आकुंचन-शिथिलीकरणामुळे होते, त्यामुळे ते थांबल्यास रक्ताभिसरण थांबेल.\",\"topic\":\"रक्ताभिसरण\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विधान रक्ताभिसरण संस्थेसाठी योग्य आहे?\",\"options\":[\"रक्त केवळ हृदयाकडून शरीराकडे जाते, परत येत नाही.\",\"रक्तवाहिन्यांचे जाळे केवळ पचनसंस्थेशी जोडलेले असते.\",\"रक्तवाहिन्या रक्ताला हृदयापासून लांब नेतात आणि परत हृदयाकडे आणतात.\",\"रक्ताभिसरण केवळ झोपेत असताना थांबते.\"],\"answer\":2,\"explain\":\"हृदयापासून रक्त वाहून नेणाऱ्या तसेच फिरून परत हृदयापर्यंत रक्त आणणाऱ्या रक्तवाहिन्यांचे जाळे असते.\",\"topic\":\"रक्ताभिसरण\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"आपण खाल्लेल्या अन्नातील पोषक घटक पायाच्या बोटांपर्यंत पोहोचवण्यासाठी कोणती संस्था मदत करते?\",\"options\":[\"श्वसन संस्था\",\"रक्ताभिसरण संस्था\",\"अस्थि संस्था\",\"ज्ञानेंद्रिये\"],\"answer\":1,\"explain\":\"रक्ताभिसरणामुळे असंख्य पदार्थ एका भागातून दुसऱ्या भागात पोहोचवले जातात.\",\"topic\":\"रक्ताभिसरण\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"रक्ताभिसरण प्रक्रियेत रक्ताची भूमिका काय आहे?\",\"options\":[\"ती केवळ शरीराला थंड ठेवते.\",\"ती इंधनपदार्थ व ऑक्सिजन वाहून नेणारे माध्यम आहे.\",\"ती केवळ हाडांना मजबुती देते.\",\"ती अन्नाचे पचन करते.\"],\"answer\":1,\"explain\":\"रक्त इंधनपदार्थ व ऑक्सिजन शरीराच्या सर्व भागांत पोहोचवण्याचे काम करते.\",\"topic\":\"रक्ताभिसरण\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"मद्यपानाचा शरीराच्या कोणत्या संस्थेवर प्रामुख्याने विपरीत परिणाम होतो?\",\"options\":[\"श्वसनसंस्था\",\"चेतासंस्था\",\"रक्ताभिसरण संस्था\",\"अस्थिसंस्था\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, मद्यपानाचा चेतासंस्थेवर परिणाम होऊन शरीराच्या हालचालींवर ताबा राहत नाही.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"मद्यपान केल्यामुळे शरीराचा कोणता गुणधर्म कमी होतो, ज्यामुळे वाहन चालवणे धोक्याचे ठरते?\",\"options\":[\"वेग\",\"दृष्टी\",\"समन्वय\",\"भूक\"],\"answer\":2,\"explain\":\"मद्यपानामुळे चेतासंस्थेवर परिणाम होतो आणि शरीराचा समन्वय कमी होतो.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"दीर्घकाळ मद्यपान केल्याने पचनेंद्रियांच्या आतील स्तरावर काय पडतात?\",\"options\":[\"सूज\",\"गाठी\",\"व्रण\",\"रक्त\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार, दीर्घकाळ मद्यपान केल्याने पचनेंद्रियांच्या आतील स्तरावर व्रण पडतात.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकात \'वृक्क\' या अवयवासाठी कोणता पर्यायी शब्द वापरला आहे?\",\"options\":[\"यकृत\",\"किडनी\",\"हृदय\",\"फुप्फुस\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात वृक्कांच्या कंसात (किडन्या) असे दिले आहे.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"श्वसनसंस्था आणि रक्ताभिसरण संस्थांची कामे सतत चालू राहणे हे कशाचे उदाहरण आहे?\",\"options\":[\"अचूक नियोजन\",\"केवळ पचन\",\"ऐच्छिक हालचाल\",\"बाहेरून मिळणारी ऊर्जा\"],\"answer\":0,\"explain\":\"इंद्रियसंस्थांची कामे सतत चालू ठेवणे हे शरीराच्या अचूक नियोजनाचा भाग आहे.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या व्यक्तीचा चालताना स्वतःच्या हालचालींवर ताबा राहत नसेल, तर त्याच्या कोणत्या संस्थेत बिघाड झाला असण्याची शक्यता आहे?\",\"options\":[\"पचनसंस्था\",\"चेतासंस्था\",\"श्वसनसंस्था\",\"उत्सर्जन संस्था\"],\"answer\":1,\"explain\":\"चेतासंस्थेवर परिणाम झाल्यास शरीराच्या हालचालींवर ताबा राहत नाही.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"तोंडात अन्न आल्यावर लाळ स्रवण्यासाठी कोणाला संदेश मिळणे आवश्यक असते?\",\"options\":[\"यकृताला\",\"लाळग्रंथींना\",\"वृक्कांना\",\"फुप्फुसांना\"],\"answer\":1,\"explain\":\"अन्न पचण्यासाठी लाळ स्रवण्याचे काम लाळग्रंथी करतात.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"मद्यपानामुळे खालीलपैकी कोणत्या दोन महत्त्वाच्या अवयवांच्या कार्यावर गंभीर परिणाम होऊ शकतो?\",\"options\":[\"हृदय आणि फुप्फुस\",\"जठर आणि आतडे\",\"यकृत आणि वृक्क\",\"नाक आणि घसा\"],\"answer\":2,\"explain\":\"मद्यपानामुळे यकृत आणि वृक्कांच्या (किडन्या) कार्यावर गंभीर परिणाम होतो.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"शरीरातील ऊर्जा मिळवून देण्याच्या कामात कोणाचा सहभाग असतो?\",\"options\":[\"केवळ एका इंद्रियाचा\",\"केवळ रक्ताचा\",\"विविध इंद्रियसंस्थांचा\",\"केवळ अन्नाचा\"],\"answer\":2,\"explain\":\"ऊर्जा मिळवून देण्याच्या कामात विविध इंद्रियसंस्थांचा सहभाग असतो.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीने मद्यपान केले असल्यास त्याला वाहन चालवू देऊ नये, कारण:\",\"options\":[\"त्याला भूक लागते\",\"त्याच्या शरीराचा समन्वय कमी होतो\",\"त्याला तहान लागते\",\"त्याचे पचन सुधारते\"],\"answer\":1,\"explain\":\"मद्यपानामुळे समन्वय कमी झाल्याने अपघात होण्याची शक्यता असते.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"आपल्याला भूक लागली आहे हे समजणे, हे शरीरातील कोणत्या प्रक्रियेमुळे शक्य होते?\",\"options\":[\"केवळ पचन\",\"केवळ श्वसन\",\"चेतासंस्थेमार्फत होणारे नियोजन\",\"केवळ रक्ताभिसरण\"],\"answer\":2,\"explain\":\"भूक लागल्याचे समजणे हे चेतासंस्थेच्या नियोजनाचा आणि समन्वयाचा भाग आहे.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"मद्यपानाचे पचनसंस्थेवर होणारे दुष्परिणाम आणि चेतासंस्थेवर होणारे दुष्परिणाम यात मुख्य फरक काय आहे?\",\"options\":[\"पचनसंस्थेवर व्रण पडतात, तर चेतासंस्थेमुळे हालचालींवरील ताबा जातो\",\"पचनसंस्थेमुळे ताबा जातो, तर चेतासंस्थेवर व्रण पडतात\",\"दोन्हींचा कोणताही परिणाम होत नाही\",\"पचनसंस्थेमुळे केवळ भूक लागते\"],\"answer\":0,\"explain\":\"मद्यपानामुळे पचनेंद्रियांच्या स्तरावर व्रण पडतात आणि चेतासंस्थेवर परिणाम होऊन हालचालींवरील ताबा सुटतो.\",\"topic\":\"चेतासंस्था\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"शरीराचे एखादे काम मिळून पूर्ण करणाऱ्या इंद्रियांना एकत्रितपणे काय म्हणतात?\",\"options\":[\"इंद्रिय गट\",\"इंद्रियसंस्था\",\"इंद्रिय जुळणी\",\"इंद्रिय समूह\"],\"answer\":1,\"explain\":\"पाठातील व्याख्येनुसार, शरीराचे एखादे काम मिळून पूर्ण करणाऱ्या इंद्रियांना \'इंद्रियसंस्था\' म्हणतात.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"शरीराला आधार आणि आकार देण्याचे महत्त्वाचे कार्य कोणती संस्था करते?\",\"options\":[\"पचनसंस्था\",\"श्वसनसंस्था\",\"अस्थिसंस्था\",\"उत्सर्जनसंस्था\"],\"answer\":2,\"explain\":\"अस्थिसंस्था शरीराला आधार, आकार देते आणि महत्त्वाच्या इंद्रियांचे रक्षण करते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"शरीरात तयार होणारे अनेक टाकाऊ पदार्थ शरीराबाहेर टाकणाऱ्या संस्थेला काय म्हणतात?\",\"options\":[\"रक्ताभिसरण संस्था\",\"उत्सर्जनसंस्था\",\"चेतासंस्था\",\"पचनसंस्था\"],\"answer\":1,\"explain\":\"टाकाऊ पदार्थ शरीराबाहेर टाकण्याचे काम उत्सर्जनसंस्था करते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"श्वसनसंस्थेमध्ये खालीलपैकी कोणत्या अवयवाचा समावेश होतो?\",\"options\":[\"जठर\",\"लहान आतडे\",\"श्वासपटल\",\"मलाशय\"],\"answer\":2,\"explain\":\"नाक, श्वासनलिका, फुफ्फुसे आणि श्वासपटल मिळून श्वसनसंस्था बनते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"पचनसंस्थेमध्ये अन्ननलिकेच्या भागांशिवाय आणखी कशाचा समावेश होतो?\",\"options\":[\"हाडांचा\",\"काही ग्रंथींचा\",\"श्वासपटलाचा\",\"रक्तवाहिन्यांचा\"],\"answer\":1,\"explain\":\"पचनसंस्थेत अन्ननलिकेच्या बाहेर असणाऱ्या काही ग्रंथींचाही समावेश होतो.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"शरीराच्या सर्व कामांमध्ये समन्वय साधण्याचे काम कोणती संस्था करते?\",\"options\":[\"चेतासंस्था\",\"अस्थिसंस्था\",\"श्वसनसंस्था\",\"रक्ताभिसरण संस्था\"],\"answer\":0,\"explain\":\"चेतासंस्था शरीराच्या सर्व कामांमध्ये समन्वय साधण्याचे काम करते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या व्यक्तीची पचनसंस्था व्यवस्थित काम करत नसेल, तर त्याचा परिणाम कशावर होईल?\",\"options\":[\"फक्त पचनसंस्थेवर\",\"फक्त श्वसनसंस्थेवर\",\"इतर इंद्रियसंस्थांवर\",\"कोणत्याही संस्थेवर होणार नाही\"],\"answer\":2,\"explain\":\"एखाद्या इंद्रियसंस्थेचे कार्य व्यवस्थित झाले नाही, तर इतर इंद्रियसंस्थांवर त्याचा परिणाम होतो.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"हृदय आणि फुफ्फुसे यांसारख्या नाजूक इंद्रियांचे रक्षण करण्यासाठी कोणती संस्था उपयुक्त ठरते?\",\"options\":[\"उत्सर्जनसंस्था\",\"अस्थिसंस्था\",\"पचनसंस्था\",\"रक्ताभिसरण संस्था\"],\"answer\":1,\"explain\":\"अस्थिसंस्था शरीरातील महत्त्वाच्या इंद्रियांचे रक्षण करण्याचे काम करते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता गट पचनसंस्थेतील अवयवांचा योग्य क्रम दर्शवतो?\",\"options\":[\"नाक -> श्वासनलिका -> फुफ्फुसे\",\"तोंड -> ग्रासिका -> जठर -> लहान आतडे\",\"तोंड -> श्वासनलिका -> जठर -> मलाशय\",\"ग्रासिका -> फुफ्फुसे -> मोठे आतडे\"],\"answer\":1,\"explain\":\"पचनसंस्थेत तोंड, ग्रासिका, जठर, लहान आतडे इत्यादींचा समावेश होतो.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता अवयव श्वसनसंस्थेचा भाग नाही?\",\"options\":[\"नाक\",\"श्वासनलिका\",\"गुदद्वार\",\"फुफ्फुसे\"],\"answer\":2,\"explain\":\"गुदद्वार हा पचनसंस्थेचा भाग आहे, श्वसनसंस्थेचा नाही.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"निरोगी जीवनासाठी खालीलपैकी कोणती अट सर्वात महत्त्वाची आहे?\",\"options\":[\"फक्त पचनसंस्था कार्यरत असणे\",\"फक्त चेतासंस्था कार्यरत असणे\",\"सर्व इंद्रियसंस्थांचे काम सुरळीत चालू राहणे\",\"केवळ अस्थिसंस्था मजबूत असणे\"],\"answer\":2,\"explain\":\"निरोगी जीवनासाठी सर्व इंद्रियसंस्थांचे काम सुरळीत चालू राहणे गरजेचे असते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"evaluate\"},{\"q\":\"शरीरात रक्ताचे वहन सतत चालू ठेवणाऱ्या संस्थेला काय म्हणतात?\",\"options\":[\"रक्ताभिसरण संस्था\",\"उत्सर्जनसंस्था\",\"अस्थिसंस्था\",\"पचनसंस्था\"],\"answer\":0,\"explain\":\"रक्ताभिसरण संस्था शरीरात सतत काम करत असते आणि रक्ताचे वहन करते.\",\"topic\":\"इतर संस्था व आपण काय शिकलो\",\"part\":11,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21620,24,5,'EVS Part 1','mr','वाढ आणि व्यक्तिमत्त्व विकास','[\"वाढ म्हणजे शरीराची उंची व वजन वाढणे.\",\"विकास म्हणजे नवीन कौशल्ये शिकणे आणि त्यांचा वापर करणे.\",\"बाळाचे पहिले कौशल्य म्हणजे हाताने वस्तू उचलणे.\",\"दोन वर्षांच्या मुलांना कपडे घालणे, बोटांनी वस्तू पकडणे शिकतात.\",\"तीन वर्षांच्या नंतर चालणे, धावणे, पळणे शिकतात.\",\"वय वाढल्यावर शरीराची ताकद व समन्वय वाढतो.\",\"आनुवंशिकता म्हणजे आई-वडिलांकडून मिळणारी गुणधर्मे.\",\"कौशल्ये शिकण्यासाठी सराव व निरीक्षण आवश्यक आहे.\",\"चांगला आहार व व्यायाम विकासाला मदत करतात.\",\"विकासाची पातळी व्यक्तीपरत्वे वेगळी असते.\",\"उंची व वजन जन्मापासून वृद्धावस्थेपर्यंत वाढतात.\",\"शारीरिक वाढ म्हणजे शरीराचे आकारमान व वजन वाढणे.\",\"मानसिक विकास म्हणजे विचार व वर्तनात बदल होणे.\",\"कौशल्ये आत्मसात केल्याने इतरांवर कमी अवलंबित्व राहते.\",\"विकासाच्या टप्प्यांमध्ये शारीरिक, मानसिक व सामाजिक बदल होतात.\"]','[{\"q\":\"साधारणपणे मुला-मुलींच्या वाढीचे वय किती वर्षांपर्यंत असते?\",\"options\":[\"१० वर्षांपर्यंत\",\"१५ वर्षांपर्यंत\",\"१८ वर्षांपर्यंत\",\"२५ वर्षांपर्यंत\"],\"answer\":2,\"explain\":\"पाठातील मजकुरानुसार, साधारणपणे १८ वर्षांचे होईपर्यंत सर्व मुला-मुलींचे वाढीचे वय असते.\",\"topic\":\"वाढ\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"जन्मापासून प्रौढावस्थेपर्यंत आपल्या शरीरात प्रामुख्याने कोणते बदल होतात?\",\"options\":[\"केवळ केसांचा रंग बदलतो\",\"उंची आणि वजन वाढत राहते\",\"केवळ बोलण्याची पद्धत बदलते\",\"उंची कमी होत जाते\"],\"answer\":1,\"explain\":\"जन्मापासून प्रौढावस्थेपर्यंत आपली उंची व वजन वाढत राहते, ही शारीरिक वाढीची लक्षणे आहेत.\",\"topic\":\"वाढ\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"तुम्ही बाळ असतानाचे कपडे आता तुम्हांला का होत नाहीत?\",\"options\":[\"कपडे लहान झाले आहेत\",\"तुमची शारीरिक वाढ झाली आहे\",\"कपड्यांचा रंग गेला आहे\",\"तुम्ही ते कपडे वापरणे बंद केले आहे\"],\"answer\":1,\"explain\":\"बाळ असतानाच्या तुलनेत आपली शारीरिक वाढ झाल्यामुळे जुने कपडे आपल्याला बसत नाहीत.\",\"topic\":\"वाढ\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"शारीरिक वाढ हे कोणाचे वैशिष्ट्य आहे?\",\"options\":[\"केवळ मानवाचे\",\"केवळ प्राण्यांचे\",\"सर्व सजीवांचे\",\"केवळ वनस्पतींचे\"],\"answer\":2