\"topic\":\"विकास\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"प्राण्यांची पिल्ले आईला सोडून स्वतंत्र जीवन केव्हा जगू लागतात?\",\"options\":[\"जन्म झाल्याबरोबर\",\"काहीही न शिकता\",\"आवश्यक कौशल्ये शिकल्यानंतर\",\"फक्त उंची वाढल्यानंतर\"],\"answer\":2,\"explain\":\"आवश्यक कौशल्ये शिकल्यानंतर प्राणी आईला सोडून स्वतंत्र जीवन जगू लागतात.\",\"topic\":\"विकास\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"समीरची उंची वाढली आहे आणि आता तो स्वतःचे गणित स्वतः सोडवू शकतो. हे कशाचे उदाहरण आहे?\",\"options\":[\"केवळ शारीरिक वाढ\",\"विकास\",\"केवळ खेळ\",\"विश्रांती\"],\"answer\":1,\"explain\":\"उंची वाढणे (वाढ) आणि गणित सोडवणे (कौशल्य) मिळून विकास होतो.\",\"topic\":\"विकास\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"प्राण्यांसाठी आवश्यक असणारी कौशल्ये कशी असतात?\",\"options\":[\"अमर्याद\",\"खूप कठीण\",\"मर्यादित\",\"मानवापेक्षा जास्त\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे प्राण्यांसाठी आवश्यक कौशल्ये मर्यादित असतात.\",\"topic\":\"विकास\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वाढ आणि विकास यातील मुख्य फरक मजकुराच्या आधारे काय सांगता येईल?\",\"options\":[\"वाढ म्हणजे फक्त वजन वाढणे, तर विकास म्हणजे फक्त उंची वाढणे\",\"वाढ ही केवळ शारीरिक असते, तर विकासात कौशल्ये शिकण्याचाही समावेश होतो\",\"वाढ प्राण्यांची होत नाही, फक्त मानवाची होते\",\"विकास फक्त आईमुळे होतो, वाढ आपोआप होते\"],\"answer\":1,\"explain\":\"वाढीसोबत कौशल्ये शिकून प्रगती होणे म्हणजे विकास होय.\",\"topic\":\"विकास\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"चालण्या-धावण्यासारखी सुरुवातीची कौशल्ये आपल्यात कशी येतात?\",\"options\":[\"कोणाकडून तरी शिकून\",\"वयाप्रमाणे आपोआप\",\"पुस्तके वाचून\",\"व्यायाम शाळेत जाऊन\"],\"answer\":1,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे चालण्या-धावण्यासारखी कौशल्ये वयाप्रमाणे आपोआप येतात.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"वाहन चालवण्यासाठी कशाची आवश्यकता असते?\",\"options\":[\"केवळ खूप पैशांची\",\"केवळ मोठ्या उंचीची\",\"ठराविक वयाची व कायदेशीर परवानगीची\",\"केवळ स्वतःच्या आवडीची\"],\"answer\":2,\"explain\":\"वाहन चालवणे आणि मतदान करणे यासाठी कायदेशीर परवानगी ठराविक वयातच मिळते.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"आपण कौशल्ये कोणाकडून शिकतो?\",\"options\":[\"केवळ मित्रांकडून\",\"केवळ टीव्हीवरून\",\"आई-वडील, शिक्षक आणि इतर मोठ्या माणसांकडून\",\"कोणाकडूनही न शिकता ती आपोआप येतात\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे आपण अनेक कौशल्ये आई-वडील, शिक्षक आणि इतर मोठ्या माणसांकडून शिकतो.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जास्तीत जास्त कौशल्ये आत्मसात केल्यामुळे काय होते?\",\"options\":[\"इतरांवर अवलंबून राहणे कमी होते\",\"इतरांवर अवलंबून राहणे वाढते\",\"अभ्यास करण्याची गरज उरत नाही\",\"वयानुसार वाढ थांबते\"],\"answer\":0,\"explain\":\"जितकी जास्त कौशल्ये आपण आत्मसात करतो, तितकेच आपले इतरांवर अवलंबून राहणे कमी होते.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मजकुरात दिलेल्या उदाहरणांपैकी कोणते काम प्रत्येक व्यक्ती स्वतः करत नाही?\",\"options\":[\"जेवण करणे\",\"स्वतःचे कपडे शिवणे\",\"पाणी पिणे\",\"चालणे\"],\"answer\":1,\"explain\":\"मजकुरात उदाहरण दिले आहे की, प्रत्येक व्यक्ती स्वतःचे कपडे शिवत नाही किंवा स्वतः शेती करत नाही.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"स्वतःची कामे पूर्ण होण्यासाठी आपण काय करायला शिकले पाहिजे?\",\"options\":[\"दुसऱ्यांवर अवलंबून राहायला\",\"कामे अर्धवट सोडायला\",\"कामाची जबाबदारी स्वतः घ्यायला\",\"कामे दुसऱ्यांना सांगायला\"],\"answer\":2,\"explain\":\"स्वतःची कामे पूर्ण होतील याची जबाबदारी स्वतः घ्यायला शिकले पाहिजे असे मजकुरात म्हटले आहे.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"५ वीत शिकणारा विद्यार्थी खालीलपैकी कोणती गोष्ट कायदेशीररित्या करू शकत नाही?\",\"options\":[\"सारांशलेखन करणे\",\"मतदान करणे\",\"किराणा सामान आणणे\",\"इस्त्री करणे\"],\"answer\":1,\"explain\":\"मतदान करण्यासाठी कायदेशीर परवानगी ठराविक वयातच (१८ वर्ष) मिळते, जी ५ वीच्या विद्यार्थ्याकडे नसते.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या मुलाने स्वतःचे किराणा सामान आणण्याचे कौशल्य आत्मसात केले, तर त्याचा काय फायदा होईल?\",\"options\":[\"त्याचे त्या कामासाठी पालकांवरचे अवलंबित्व कमी होईल\",\"त्याला लगेच वाहन चालवण्याचा परवाना मिळेल\",\"त्याला शाळेत जाण्याची गरज पडणार नाही\",\"त्याचे वय वेगाने वाढू लागेल\"],\"answer\":0,\"explain\":\"कौशल्ये आत्मसात केल्याने स्वावलंबन वाढते आणि इतरांवरचे अवलंबित्व कमी होते.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"\'चालणे\' आणि \'स्वयंपाक करणे\' या दोन कौशल्यांमध्ये कोणता मुख्य फरक मजकुरात सूचित केला आहे?\",\"options\":[\"दोन्ही शिकावी लागतात\",\"दोन्ही आपोआप येतात\",\"चालणे आपोआप येते, पण स्वयंपाक करणे शिकावे लागते\",\"स्वयंपाक आपोआप येतो, पण चालणे शिकावे लागते\"],\"answer\":2,\"explain\":\"चालणे हे वयानुसार आपोआप येणारे कौशल्य आहे, तर स्वयंपाक हे कोणाकडून तरी शिकावे लागणारे कौशल्य आहे.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"मजकुराच्या आधारे खालीलपैकी चुकीचे विधान ओळखा.\",\"options\":[\"आपण प्रत्येक काम स्वतःच करतो, असे कधीच होत नाही\",\"काही कौशल्ये आपल्याला कोणाकडून तरी शिकावी लागतात\",\"मतदान करण्यासाठी वयाची अट नसते\",\"जबाबदारी घ्यायला शिकणे महत्त्वाचे आहे\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट म्हटले आहे की मतदान करण्यासाठी कायदेशीर परवानगी ठराविक वयातच असते.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"आजारी व्यक्तीची शुश्रूषा करणे हे कोणत्या प्रकारचे कौशल्य आहे?\",\"options\":[\"वयानुसार आपोआप येणारे\",\"कोणाकडून तरी शिकावे लागणारे\",\"कायदेशीर परवानगी लागणारे\",\"केवळ मनोरंजनासाठी असणारे\"],\"answer\":1,\"explain\":\"शुश्रूषा करणे हे अशा कामांपैकी आहे जे आपल्याला शिकावे लागते, ते आपोआप येत नाही.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मजकुरातील \'स्वावलंबन\' या संकल्पनेचा अर्थ काय होतो?\",\"options\":[\"सर्व कामे दुसऱ्यांकडून करून घेणे\",\"इतरांवर अवलंबून राहणे कमी करणे\",\"कोणतेही कौशल्य न शिकणे\",\"केवळ मनोरंजनासाठी कामे करणे\"],\"answer\":1,\"explain\":\"जास्त कौशल्ये आत्मसात केल्याने इतरांवरचे अवलंबित्व कमी होणे म्हणजेच स्वावलंबनाकडे वाटचाल करणे होय.\",\"topic\":\"कौशल्ये आत्मसात करणे\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"साधारणपणे आपली उंची कोणत्या वयापर्यंत वाढते?\",\"options\":[\"१५ वर्षांपर्यंत\",\"१८ वर्षांपर्यंत\",\"२० वर्षांपर्यंत\",\"२५ वर्षांपर्यंत\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की वयाच्या १८ वर्षांपर्यंत साधारणपणे आपली उंची वाढते.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"आपल्या कुटुंबियांसारखी आपल्यामध्ये जन्मतःच अनेक लक्षणे येणे, याला काय म्हणतात?\",\"options\":[\"प्रगती\",\"विकास\",\"आनुवंशिकता\",\"शिक्षण\"],\"answer\":2,\"explain\":\"कुटुंबियांसारखी लक्षणे जन्मतःच येण्याला \'आनुवंशिकता\' असे म्हणतात.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यानुसार, खालीलपैकी कोणते शारीरिक लक्षण पालकांसारखे असू शकते?\",\"options\":[\"कपड्यांची निवड\",\"अंगकाठी\",\"जेवणाच्या आवडी\",\"हस्ताक्षर\"],\"answer\":1,\"explain\":\"दिसणे आणि अंगकाठी अशी शारीरिक लक्षणे साधारणपणे आई-वडिलांसारखी असतात.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"एखादा मुलगा १० वर्षांचा आहे, तर साधारणपणे अजून किती वर्षे त्याची उंची वाढू शकते?\",\"options\":[\"५ वर्षे\",\"८ वर्षे\",\"१० वर्षे\",\"२ वर्षे\"],\"answer\":1,\"explain\":\"१८ वर्षे वयापर्यंत उंची वाढते, म्हणून १८ - १० = ८ वर्षे.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जन्मतः आपल्यामध्ये कोणती लक्षणे आनुवंशिकतेने येतील, यावर कोणाचे नियंत्रण असते?\",\"options\":[\"आई-वडिलांचे\",\"स्वतःचे\",\"कोणाचेही नाही\",\"डॉक्टरांचे\"],\"answer\":2,\"explain\":\"आनुवंशिकतेने कोणती लक्षणे येतील आणि कोणती नाही यावर कोणाचेही नियंत्रण नसते.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एखादा अनोळखी माणूस तुम्हाला पाहून \'तू तुझ्या मामासारखा दिसतोस\' असे म्हणतो, हे कशामुळे शक्य होते?\",\"options\":[\"ओळखीमुळे\",\"आनुवंशिक साम्यामुळे\",\"कपड्यांमुळे\",\"उंचीमुळे\"],\"answer\":1,\"explain\":\"नातेवाईकांशी असलेल्या साम्यावरून लोक आपल्याला ओळखू शकतात.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात आनुवंशिक लक्षणांसाठी आई-वडिलांशिवाय इतर कोणत्या नातेवाईकांचा उल्लेख आला आहे?\",\"options\":[\"शेजारी\",\"मित्र-मैत्रिणी\",\"आजी-आजोबा, मामा-मावशी\",\"शिक्षक\"],\"answer\":2,\"explain\":\"आपली काही लक्षणे आजी-आजोबा, मामा-मावशी किंवा काका-आत्यासारखी असू शकतात.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"आनुवंशिकतेबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"लक्षणे प्रयत्नाने मिळवता येतात\",\"लक्षणे जन्मतःच येतात\",\"लक्षणे फक्त वडिलांकडूनच येतात\",\"लक्षणे १८ वर्षांनंतर बदलतात\"],\"answer\":1,\"explain\":\"आनुवंशिक लक्षणे ही जन्मतःच आपल्यामध्ये येतात.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"एकाच कुटुंबातील लोकांमध्ये अनेक बाबतीत काय दिसून येते?\",\"options\":[\"फरक\",\"साम्य\",\"वाद\",\"वेगळेपण\"],\"answer\":1,\"explain\":\"एका कुटुंबातील लोकांमध्ये अनेक बाबतीत साम्य दिसून येते.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"उंचीच्या बाबतीत उताऱ्यात कोणते निरीक्षण करायला सांगितले आहे?\",\"options\":[\"केवळ स्वतःची उंची मोजणे\",\"आईवडिलांपेक्षा खूप उंच किंवा कमी उंचीचे लोक पाहणे\",\"मित्रांची उंची मोजणे\",\"प्राण्यांची उंची पाहणे\"],\"answer\":1,\"explain\":\"आईवडिलांपेक्षा खूप उंच किंवा खूप कमी उंचीचे लोक किती आहेत हे पाहण्यास सांगितले आहे.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या मुलाचे नाक त्याच्या आत्यासारखे असेल, तर हे कशाचे उदाहरण आहे?\",\"options\":[\"आनुवंशिकता\",\"सवय\",\"शिक्षण\",\"वाढ\"],\"answer\":0,\"explain\":\"नातेवाईकांसारखी शारीरिक लक्षणे असणे हे आनुवंशिकतेचे उदाहरण आहे.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"आनुवंशिकतेमुळे मिळणाऱ्या लक्षणांची निवड आपण करू शकतो का?\",\"options\":[\"हो, आपण निवडू शकतो\",\"नाही, त्यावर कोणाचेही नियंत्रण नसते\",\"फक्त आई-वडील निवडू शकतात\",\"केवळ उंची निवडता येते\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की कोणती लक्षणे येतील यावर कोणाचेही नियंत्रण नसते.\",\"topic\":\"आनुवंशिकता\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"अनेक कौशल्ये शिकण्याच्या क्षमता आपल्याकडे कशाने येतात?\",\"options\":[\"आनुवंशिकतेने\",\"केवळ पैशांमुळे\",\"केवळ मित्रांमुळे\",\"केवळ शहरात राहिल्यामुळे\"],\"answer\":0,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की अनेक कौशल्ये शिकण्याच्या क्षमता आपल्याकडे आनुवंशिकतेने येतात.\",\"topic\":\"चांगला विकास होण्यासाठी...\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"स्वतःच्या क्षमता ओळखण्याची आणि कौशल्यांचे विकसित करण्याची संधी कोणत्या काळात असते?\",\"options\":[\"वृद्धापकाळात\",\"वाढीच्या वयात\",\"केवळ नोकरी करताना\",\"केवळ झोपताना\"],\"answer\":1,\"explain\":\"वाढीचे वय म्हणजे स्वतःच्या क्षमता ओळखण्याची आणि कौशल्यांचे विकसित करण्याची संधी असते.\",\"topic\":\"चांगला विकास होण्यासाठी...\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कौशल्यांच्या आधारे व्यक्तीला कशाची तयारी करता येते?\",\"options\":[\"केवळ खेळ खेळण्याची\",\"स्वतंत्रपणे उपयोगी आणि समृद्ध जीवन जगण्याची\",\"केवळ आनुवंशिकता मिळवण्याची\",\"केवळ उंची वाढवण्याची\"],\"answer\":1,\"explain\":\"कौशल्यांच्या आधारे स्वतंत्रपणे उपयोगी आणि समृद्ध जीवन जगण्याची तयारी होते.\",\"topic\":\"चांगला विकास होण्यासाठी...\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"वाढीच्या वयात कुपोषणामुळे शरीरावर कोणता परिणाम होऊ शकतो?\",\"options\":[\"उंची खूप वेगाने वाढते\",\"विविध अन्नद्रव्ये पुरेशा प्रमाणात मिळतात\",\"उंची जेवढी व्हायला हवी होती त्यापेक्षा कमी राहते\",\"शरीर खूप लवचिक होते\"],\"answer\":2,\"explain\":\"कुपोषणामुळे वाढीच्या वयात उंची जेवढी व्हायला हवी होती त्यापेक्षा कमी राहून जाते.\",\"topic\":\"चांगला विकास होण्यासाठी...\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"वाढीचे वय उलटून गेल्यावर चांगला आहार घेतल्यास काय होते?\",\"options\":[\"उंची अचानक वाढते\",\"त्याचा वाढीसाठी उपयोग होत नाही\",\"कौशल्ये आपोआप विकसित होतात\",\"आनुवंशिकता बदलते\"],\"answer\":1,\"explain\":\"वाढीचे वय गेल्यावर चांगला आहार मिळाला, तरी त्याचा वाढीसाठी उपयोग होत नाही.\",\"topic\":\"चांगला विकास होण्यासाठी...\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"उत्तम विकासासाठी पौष्टिक अन्नाबरोबरच खा