करू शकत नाही?\",\"options\":[\"रडणे\",\"झोपणे\",\"स्वतःची कामे करणे\",\"दूध पिणे\"],\"answer\":2,\"explain\":\"आकृतीत स्पष्ट केले आहे की बाळ लहान असते तेव्हा ते स्वतःची कुठलीच कामे करू शकत नाही.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"24\\/130_102.jpg\"},{\"q\":\"जितकी जास्त कौशल्ये आपण आत्मसात करतो, तितके आपले इतरांवर अवलंबून राहणे ______.\",\"options\":[\"वाढते\",\"कमी होते\",\"तसेच राहते\",\"बंद होते\"],\"answer\":1,\"explain\":\"कौशल्ये शिकल्यामुळे आपण स्वावलंबी होतो, त्यामुळे इतरांवरील अवलंबित्व कमी होते.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"एका कुटुंबातील लोकांमध्ये साम्य असले, तरी प्रत्येक व्यक्ती कशी असते?\",\"options\":[\"इतरांसारखीच असते\",\"इतर सर्वांपेक्षा वेगळी असते\",\"केवळ आईसारखी असते\",\"केवळ वडिलांसारखी असते\"],\"answer\":1,\"explain\":\"साम्य असूनही प्रत्येक व्यक्तीचे स्वतःचे वेगळेपण असते.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"स्वतंत्रपणे उपयोगी आणि समृद्ध जीवन जगण्याची तयारी कशामुळे होते?\",\"options\":[\"केवळ उंची वाढल्यामुळे\",\"कौशल्यांच्या आधारे\",\"केवळ वजन वाढल्यामुळे\",\"जास्त जेवल्यामुळे\"],\"answer\":1,\"explain\":\"कौशल्यांच्या आधारे आपण स्वतंत्र आणि समृद्ध जीवन जगण्यास तयार होतो.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"समीरने आता स्वतःचे दप्तर स्वतः भरायला सुरुवात केली आहे, यावरून काय समजते?\",\"options\":[\"त्याने नवीन कौशल्य आत्मसात केले आहे\",\"त्याचे वजन कमी झाले आहे\",\"त्याला शाळेत जायचे नाही\",\"त्याची उंची वाढणे थांबले आहे\"],\"answer\":0,\"explain\":\"स्वतःची कामे स्वतः करणे हे एक कौशल्य आहे जे आपण वाढीसोबत शिकतो.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"वाढीच्या प्रक्रियेत शरीरात होणारे मुख्य बदल कोणते आहेत?\",\"options\":[\"केवळ केसांचा रंग बदलणे\",\"केवळ डोळ्यांचा रंग बदलणे\",\"उंची व वजन वाढणे\",\"केवळ कपड्यांचा आकार बदलणे\"],\"answer\":2,\"explain\":\"जन्मापासून प्रौढावस्थेपर्यंत उंची आणि वजन वाढणे हे वाढीचे प्रमुख लक्षण आहे.\",\"topic\":\"आपण काय शिकलो\",\"part\":8,\"bloom\":\"remember\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:28');
INSERT INTO `ep_topic_packs` VALUES (21621,24,5,'EVS Part 1','mr','संसर्गजन्य रोग आणि रोगप्रतिबंध','[\"संसर्गजन्य रोग म्हणजे सूक्ष्मजीवांमुळे होणारे रोग.\",\"रोगजंतू म्हणजे रोग निर्माण करणारे सूक्ष्मजीव.\",\"प्रत्येक रोगाचा एक विशिष्ट रोगजंतू असतो.\",\"रोगप्रसाराची ४ मुख्य पद्धती – हवेमार्फत, पाण्याद्वारे, अन्नाद्वारे आणि थेट संपर्काद्वारे.\",\"हवेमार्फत प्रसारात शिंक, खोकला, थुंकीमधील जंतू हवेत पसरतात.\",\"पाण्याद्वारे प्रसारात विष्ठा किंवा दूषित पाणी रोगजंतू घेऊन जाते.\",\"अन्नाद्वारे प्रसारात अन्नावर माश्या बसणे किंवा कचरा मिसळणे रोगजंतू आणते.\",\"थेट संपर्कात त्वचेचा जखम, कपडे, रुमाल यांचा वापर होतो.\",\"रोगप्रतिबंध म्हणजे स्वच्छता, संतुलित आहार, लसीकरण आणि कीटकनाशकांचा वापर.\",\"लसीकरणाने शरीरात प्रतिकारशक्ती वाढते आणि रोग टाळता येतो.\",\"डास, पिसवा यांसारख्या कीटकांमुळे मलेरिया आणि इतर रोग पसरतात.\",\"हवेतून पसरलेल्या रोगांना टाळण्यासाठी शिंकताना रुमाल वापरावा.\",\"पाण्याचे निर्जंतुकीकरण करण्यासाठी ब्लीच किंवा उकळणे आवश्यक.\",\"अन्न झाकून ठेवणे आणि हात स्वच्छ धुणे हे अन्नाद्वारे प्रसार रोखतात.\",\"रोगजंतू शरीरात शिरल्यावर रोगप्रतिकारक प्रणाली लढते.\",\"रोगप्रसार टाळण्यासाठी घरात स्वच्छता, पाणी साचू न देणे, कीटकनाशक वापरणे महत्त्वाचे.\",\"रोगाची साथ झाल्यास त्वरित आरोग्य विभागाला कळवावे.\",\"संसर्गजन्य रोगांची लक्षणे – ताप, खोकला, पोटदुखी इत्यादी.\",\"रोगप्रसाराची पद्धत ओळखून योग्य प्रतिबंध उपाय निवडता येतात.\",\"रोगजंतूंची ओळख आणि त्यांचा प्रसार समजून घेणे आरोग्यविषयक निर्णय घेण्यासाठी आवश्यक.\"]','[{\"q\":\"आजारी व्यक्तीने वापरलेल्या कोणत्या वस्तू आपण वापरू नयेत असे पाठात सांगितले आहे?\",\"options\":[\"फक्त पुस्तके\",\"रुमाल, टॉवेल आणि कपडे\",\"फक्त खेळणी\",\"फक्त चप्पल\"],\"answer\":1,\"explain\":\"पाठात आजारी व्यक्तीचे रुमाल, टॉवेल आणि कपडे वापरू नका असे सांगितले आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"तुमचे मित्र किंवा मैत्रिणी खेळताना पडले आणि त्यांना लागले, तर त्यांच्या जवळ गेल्याने तुम्हालाही लागेल का?\",\"options\":[\"हो, नक्कीच लागेल\",\"नाही, तसे होत नाही\",\"कदाचित लागू शकते\",\"फक्त जखम मोठी असेल तर लागेल\"],\"answer\":1,\"explain\":\"पडल्यामुळे झालेली जखम ही संसर्गजन्य नसते, त्यामुळे जवळ गेल्याने ती दुसऱ्याला होत नाही.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आईचे डोके दुखत असताना तिच्या जवळ गेल्यावर काय होते?\",\"options\":[\"तुमचेही डोके दुखू लागते\",\"तुम्हाला ताप येतो\",\"तुमचे डोके दुखू लागत नाही\",\"तुम्ही आजारी पडता\"],\"answer\":2,\"explain\":\"डोकेदुखी हा संसर्गजन्य आजार नसल्याने जवळ गेल्यावर ती दुसऱ्याला होत नाही.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात मुलगी पडली आहे. तिच्या जखमेबाबत पाठाच्या आधारे कोणते विधान योग्य आहे?\",\"options\":[\"तिच्या जवळ गेल्यावर तुम्हालाही जखम होईल\",\"तिच्या जवळ जाऊ नका असे कोणीही सांगत नाही\",\"तिची जखम हवेतून पसरते\",\"तिच्या जवळ गेल्यावर तुम्हाला लगेच लागेल\"],\"answer\":1,\"explain\":\"पडल्यामुळे झालेल्या जखमेच्या बाबतीत \'जवळ जाऊ नका, तुम्हालाही लागेल\' असे कोणी सांगत नाही.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"24\\/131_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील व्यक्तीच्या स्थितीबाबत पाठात कोणता प्रश्न विचारला आहे?\",\"options\":[\"तिच्या जवळ गेल्यावर तुमचेही डोके दुखू लागते का?\",\"तिला औषध कोणी दिले?\",\"तिला ताप आला आहे का?\",\"ती कधी बरी होईल?\"],\"answer\":0,\"explain\":\"चित्रात आईचे डोके दुखत आहे आणि त्या संदर्भात जवळ गेल्यावर तुमचेही डोके दुखते का, असा प्रश्न विचारला आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"evaluate\",\"figure_image\":\"24\\/131_102.jpg\"},{\"q\":\"आजारी व्यक्तीच्या बाबतीत खालीलपैकी कोणती गोष्ट टाळण्यास सांगितले आहे?\",\"options\":[\"त्यांच्याशी बोलणे\",\"त्यांच्याकडे पाहणे\",\"त्यांनी वापरलेल्या भांड्यातून जेवणे\",\"त्यांना मदत करणे\"],\"answer\":2,\"explain\":\"संसर्ग टाळण्यासाठी आजारी व्यक्तीच्या भांड्यातून जेवू नये असे सांगितले आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"आजारी व्यक्तीच्या जवळ जाऊ नका, असे केव्हा सांगितले जाते?\",\"options\":[\"जेव्हा व्यक्तीला साधी जखम होते\",\"जेव्हा व्यक्तीचे डोके दुखते\",\"जेव्हा व्यक्तीला संसर्गजन्य आजार असण्याची शक्यता असते\",\"जेव्हा व्यक्ती झोपलेली असते\"],\"answer\":2,\"explain\":\"आजार पसरू नये म्हणून विशिष्ट परिस्थितीत आजारी व्यक्तीपासून दूर राहण्यास सांगितले जाते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आजारी व्यक्तीने वापरलेले पाणी पिण्याबाबत काय काळजी घ्यावी?\",\"options\":[\"त्यांनी वापरलेल्या भांड्यातून पाणी पिऊ नका\",\"नेहमी त्यांच्याच भांड्यातून पाणी प्या\",\"पाणी गरम करून प्या\",\"काहीही काळजी घेण्याची गरज नाही\"],\"answer\":0,\"explain\":\"पाठात आजारी व्यक्तीने वापरलेल्या भांड्यातून पाणी पिऊ नका असे स्पष्ट म्हटले आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"पाठातील \'सांगा पाहू\' या भागात एकूण किती मुख्य प्रश्न किंवा प्रसंग विचारले आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"पाठातील या भागात (१), (२) आणि (३) असे तीन मुख्य प्रसंग दिले आहेत.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"जखम होणे आणि डोके दुखणे या गोष्टी आजारी व्यक्तीच्या संपर्कात येण्याबाबत काय सुचवतात?\",\"options\":[\"या गोष्टी संपर्कात आल्याने पसरतात\",\"या गोष्टी संपर्कात आल्याने पसरत नाहीत\",\"या गोष्टी फक्त मुलांना होतात\",\"या गोष्टी हवेतून पसरतात\"],\"answer\":1,\"explain\":\"जखम आणि डोकेदुखी हे संपर्कात आल्याने पसरत नाहीत, हे पाठातील प्रश्नांवरून स्पष्ट होते.\",\"topic\":\"सांगा पाहू !\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"एका व्यक्तीकडून दुसऱ्या व्यक्तीला लागण होऊ शकणाऱ्या रोगांना काय म्हणतात?\",\"options\":[\"मानसिक रोग\",\"संसर्गजन्य रोग\",\"अनुवांशिक रोग\",\"हाडांचे रोग\"],\"answer\":1,\"explain\":\"ज्या रोगांची एकाकडून दुसऱ्याला लागण होते, त्यांना संसर्गजन्य रोग म्हणतात.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"रोगाला कारणीभूत ठरणाऱ्या सूक्ष्मजीवांना काय म्हणतात?\",\"options\":[\"विषाणू\",\"कीटक\",\"रोगजंतू\",\"पेशी\"],\"answer\":2,\"explain\":\"रोगाला कारणीभूत ठरणाऱ्या सूक्ष्मजीवांना रोगजंतू म्हणतात.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता आजार संसर्गजन्य नाही?\",\"options\":[\"पटकी\",\"नायटा\",\"पाठदुखी\",\"कांजिण्या\"],\"answer\":2,\"explain\":\"पाठदुखी हा आजार दुसऱ्याला होत नाही, त्यामुळे तो संसर्गजन्य नाही.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"संसर्गजन्य रोग कशामुळे होतात?\",\"options\":[\"थंडीमुळे\",\"सूक्ष्मजीवांमुळे\",\"जास्त कामामुळे\",\"भाजल्यामुळे\"],\"answer\":1,\"explain\":\"संसर्गजन्य रोग हे सूक्ष्मजीवांमुळे होतात.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"एखाद्या व्यक्तीला रोग कधी होतो?\",\"options\":[\"जेव्हा तो औषध घेतो\",\"जेव्हा तो व्यायाम करतो\",\"जेव्हा रोगजंतू शरीरात वाढू लागतात\",\"जेव्हा तो विश्रांती घेतो\"],\"answer\":2,\"explain\":\"शरीरात रोगजंतूंचा प्रवेश होऊन ते वाढू लागले की रोग होतो.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"आईचा हात भाजून झालेली जखम मुलाला का होत नाही?\",\"options\":[\"कारण ती जखम संसर्गजन्य नाही\",\"कारण मुलगा औषध घेतो\",\"कारण आई मुलाला जवळ घेत नाही\",\"कारण जखम छोटी आहे\"],\"answer\":0,\"explain\":\"भाजलेली जखम हा संसर्गजन्य आजार नसल्याने त्याची लागण दुसऱ्याला होत नाही.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्याला \'गोवर\' झाला असेल, तर इतरांनी कोणती काळजी घ्यावी?\",\"options\":[\"त्याच्यासोबत खेळावे\",\"त्याच्यापासून दूर राहावे\",\"त्याचे कपडे वापरावे\",\"काहीही काळजी घेऊ नये\"],\"answer\":1,\"explain\":\"गोवर हा संसर्गजन्य रोग असल्याने रोगापासून दूर राहण्याची काळजी घ्यावी लागते.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता गट संसर्गजन्य रोगांचा आहे?\",\"options\":[\"पाठदुखी, हात भाजणे, ताप\",\"पटकी, प्लेग, खरूज\",\"नायटा, डोकेदुखी, जखम\",\"गोवर, थकवा, पाठदुखी\"],\"answer\":1,\"explain\":\"पटकी, प्लेग आणि खरूज हे सर्व संसर्गजन्य रोग आहेत.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"विशिष्ट रोगाच्या बाबतीत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"सर्व रोगांना एकच जंतू असतो\",\"प्रत्येक रोगास विशिष्ट रोगजंतू असतो\",\"रोगजंतू डोळ्यांनी सहज दिसतात\",\"भाजल्यामुळे रोगजंतू तयार होतात\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे प्रत्येक रोगास एक विशिष्ट रोगजंतू कारणीभूत ठरतो.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"प्लेग आणि नायटा या आजारांमध्ये कोणते साम्य आहे?\",\"options\":[\"दोन्ही आजार भाजल्यामुळे होतात\",\"दोन्ही आजार सूक्ष्मजीवांमुळे होतात\",\"दोन्ही आजार संसर्गजन्य नाहीत\",\"दोन्ही आजार फक्त आजोबांना होतात\"],\"answer\":1,\"explain\":\"प्लेग आणि नायटा हे दोन्ही संसर्गजन्य रोग असून ते सूक्ष्मजीवांमुळे (रोगजंतूंमुळे) होतात.\",\"topic\":\"संसर्गजन्य रोग\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"रोगजंतू एका व्यक्तीकडून दुसऱ्या व्यक्तीकडे जाण्याच्या क्रियेला काय म्हणतात?\",\"options\":[\"रोगप्रसार\",\"रोगप्रतिबंध\",\"आरोग्य\",\"उपचार\"],\"answer\":0,\"explain\":\"उताऱ्यात दिलेल्या व्याख्येनुसार, रोगजंतू दुसऱ्यांच्या शरीरात जाण्याला रोगप्रसार म्हणतात.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पडसे झालेल्या व्यक्तीच्या कोणत्या क्रियेमुळे रोगजंतू हवेत मिसळतात?\",\"options\":[\"जेवल्यामुळे\",\"खोकल्यामुळे व शिंकल्यामुळे\",\"चालल्यामुळे\",\"झोपल्यामुळे\"],\"answer\":1,\"explain\":\"पडसे झालेल्या व्यक्तीच्या खोकल्यातून आणि शिंकण्यातून रोगजंतू हवेत मिसळतात.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"टायफॉइड या रोगाला उताऱ्यात दुसरे कोणते नाव दिले आहे?\",\"options\":[\"क्षयरोग\",\"पडसे\",\"विषमज्वर\",\"ताप\"],\"answer\":2,\"explain\":\"उताऱ्यात टायफॉइडचा उल्लेख \'विषमज्वर\' असा केला आहे.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या व्यक्तीला पडसे झाले असेल, तर त्याचे रोगजंतू कोठे मिसळतात?\",\"options\":[\"पाण्यात\",\"हवेत\",\"अन्नात\",\"जमिनीत\"],\"answer\":1,\"explain\":\"पडसे झालेल्या व्यक्तीच्या शिंकण्यातून रोगजंतू हवेत मिसळतात असे उताऱ्यात म्हटले आहे.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"निरोगी व्यक्तीला रोग केव्हा होऊ शकतो?\",\"options\":[\"जेव्हा ती व्यायाम करते\",\"जेव्हा ती पाणी पिते\",\"जेव्हा रोगजंतू तिच्या शरीरात शिरतात\",\"जेव्हा ती अभ्यास करते\"],\"answer\":2,\"explain\":\"रोगजंतू दुसऱ्यांच्या शरीरात गेले की त्यांना रोग होऊ शकतो.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"टायफॉइडचा प्रसार कसा होतो?\",\"options\":[\"केवळ हवेतून\",\"रोगजंतू निरोगी व्यक्तीच्या शरीरात गेल्याने\",\"फळे खाल्ल्याने\",\"खूप खेळल्याने\"],\"answer\":1,\"explain\":\"टायफॉइडग्रस्त व्यक्तीकडून रोगजंतू निरोगी व्यक्तीच्या शरीरात गेल्याने प्रसार होतो.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"समीरला पडसे झाले आहे. त्याने वर्गात रुमाल न धरता शिंकल्यानंतर त्याच्या मित्रालाही पडसे झाले. हे कशामुळे झाले असावे?\",\"options\":[\"हवेतून रोगजंतूंचा प्रसार झाल्यामुळे\",\"पाणी प्यायल्यामुळे\",\"जेवण केल्यामुळे\",\"जास्त बोलल्यामुळे\"],\"answer\":0,\"explain\":\"शिंकल्यामुळे रोगजंतू हवेत मिसळतात आणि दुसऱ्याच्या शरीरात जाऊन रोग पसरवतात.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्याला क्षयरोग झाला असेल, तर तो इतरांना होण्यासाठी खालीलपैकी काय कारणीभूत ठरेल?\",\"options\":[\"त्याच्याशी बोलणे\",\"त्याच्या शरीरातील रोगजंतूंचा प्रसार होणे\",\"त्याच्याकडे पाहणे\",\"त्याच्यासोबत चालणे\"],\"answer\":1,\"explain\":\"कोणताही संसर्गजन्य रोग हा रोगजंतूंच्या प्रसारामुळे होतो.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यातील माहितीनुसार, रोगप्रसारासाठी मुख्यत्वे काय कारणीभूत असतात?\",\"options\":[\"हवामान\",\"रोगजंतू\",\"रुग्णालय\",\"औषधे\"],\"answer\":1,\"explain\":\"पडसे आणि टायफॉइड या दोन्ही उदाहरणांमध्ये रोगजंतूंच्या वहनामुळे रोग होतो असे स्पष्ट होते.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"रोगप्रसार होण्यासाठी खालीलपैकी कोणती अट आवश्यक आहे?\",\"options\":[\"व्यक्तीने औषध घेणे\",\"रोगजंतू निरोगी शरीरात शिरणे\",\"व्यक्तीने विश्रांती घेणे\",\"व्यक्तीने व्यायाम करणे\"],\"answer\":1,\"explain\":\"रोगजंतू दुसऱ्यांच्या शरीरात गेले तरच रोगप्रसार होतो, असे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"रोगप्रसार\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पडशासारख्या रोगाचे जंतू रोग्याच्या शरीर