:1,\"explain\":\"थुंकल्याने थुंकीतील रोगजंतू हवेत पसरतात आणि इतरांना संसर्ग होऊ शकतो.\",\"topic\":\"हवेमार्फत रोगप्रसार\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तुमच्या मित्राला सतत खोकला येत आहे, तर तुम्ही त्याला कोणता सल्ला द्याल?\",\"options\":[\"उघड्यावर थुंकण्याचा\",\"खोकताना तोंडावर रुमाल धरण्याचा\",\"मैदानावर खेळायला जाण्याचा\",\"जोरात ओरडण्याचा\"],\"answer\":1,\"explain\":\"रोगप्रसार रोखण्यासाठी खोकताना तोंडावर रुमाल धरणे ही योग्य कृती आहे.\",\"topic\":\"हवेमार्फत रोगप्रसार\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या क्रियेमुळे रोगजंतू हवेत पसरत नाहीत?\",\"options\":[\"थुंकल्याने\",\"खोकल्याने\",\"शिंकल्याने\",\"शांत बसल्याने\"],\"answer\":3,\"explain\":\"थुंकणे, खोकणे आणि शिंकणे या तीन क्रियांनी जंतू हवेत पसरतात असे मजकूर सांगतो.\",\"topic\":\"हवेमार्फत रोगप्रसार\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"हवेमार्फत होणारा रोगप्रसार थांबवण्यासाठी सर्वात प्रभावी प्रतिबंधात्मक उपाय कोणता?\",\"options\":[\"भरपूर पाणी पिणे\",\"उघड्यावर न थुंकणे व रुमाल वापरणे\",\"नेहमी व्यायाम करणे\",\"जास्त जेवण करणे\"],\"answer\":1,\"explain\":\"मजकुरातील सूचनेनुसार, उघड्यावर न थुंकणे आणि रुमाल वापरणे हे हवेमार्फत होणारा प्रसार रोखतात.\",\"topic\":\"हवेमार्फत रोगप्रसार\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणता रोग आतड्याचा रोग आहे?\",\"options\":[\"खोकला\",\"टायफॉइड\",\"क्षय\",\"सर्दी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार टायफॉइड, कॉलरा आणि जुलाब हे आतड्याचे रोग आहेत.\",\"topic\":\"पाण्यामार्फत रोगप्रसार\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"काविळीचे जंतू रुग्णाच्या शरीरातील कोणत्या घटकामध्ये असतात?\",\"options\":[\"रक्त\",\"घाम\",\"विष्ठा\",\"थुंकी\"],\"answer\":2,\"explain\":\"काविळीचे जंतू रोगाच्या विष्ठेमध्ये असतात असे पाठात नमूद केले आहे.\",\"topic\":\"पाण्यामार्फत रोगप्रसार\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"दूषित पाणी प्यायल्यामुळे रोगजंतू शरीराच्या कोणत्या भागात शिरकाव करतात?\",\"options\":[\"फुफ्फुस\",\"मेंदू\",\"हृदय\",\"आतडे\"],\"answer\":3,\"explain\":\"दूषित पाणी प्यायल्यामुळे रोगजंतू पाणी 