",\"options\":[\"हो म्हणायला\",\"ठामपणे नकार द्यायला\",\"गप्प बसायला\",\"पळून जायला\"],\"answer\":1,\"explain\":\"वाईट सवयींना ठामपणे नकार द्यायला शिकणे महत्त्वाचे आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"सामाजिक आरोग्यासोबतच आणखी कशाची दक्षता असावी?\",\"options\":[\"वैयक्तिक खेळाची\",\"सार्वजनिक आरोग्याची\",\"केवळ स्वतःची\",\"घराची\"],\"answer\":1,\"explain\":\"सामाजिक व सार्वजनिक आरोग्याचीही दक्षता असावी असे पाठ सांगतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला कोणी चुकीच्या गोष्टीचा किंवा व्यसनाचा आग्रह केला, तर तुम्ही काय कराल?\",\"options\":[\"एकदा करून पाहू\",\"ठामपणे नकार देऊ\",\"मित्राला सांगू\",\"विचार करू\"],\"answer\":1,\"explain\":\"वाईट सवयींना ठामपणे नकार देणे हे आरोग्यासाठी आवश्यक आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"रिकाम्या वेळेत चित्रकला किंवा वाचन करणे हे कशासाठी उपयुक्त ठरू शकते?\",\"options\":[\"वेळ घालवण्यासाठी\",\"व्यसनांपासून दूर राहण्यासाठी\",\"पैसे मिळवण्यासाठी\",\"थकवा घालवण्यासाठी\"],\"answer\":1,\"explain\":\"छंद जोपासल्यामुळे मन चांगल्या कामात गुंतते आणि व्यसनांपासून दूर राहता येते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"सामाजिक निरामयता आणि समाजाचे स्वास्थ्य यांचा काय संबंध आहे?\",\"options\":[\"काहीच संबंध नाही\",\"निरामयतेमुळे स्वास्थ्य कमी होते\",\"निरामयतेमुळे स्वास्थ्य वाढते\",\"निरामयता आरोग्यासाठी घातक आहे\"],\"answer\":2,\"explain\":\"सामाजिक निरामयता समाजाचे स्वास्थ्य वाढवण्यास मदत करते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"व्यसनांपासून दूर राहण्यासाठी मनाचा कोणता गुण सर्वात महत्त्वाचा आहे?\",\"options\":[\"चंचलता\",\"खंबीरपणा\",\"भीती\",\"आळस\"],\"answer\":1,\"explain\":\"मनाचा खंबीरपणा व्यसनांना नकार देण्यासाठी आणि त्यापासून दूर राहण्यासाठी आवश्यक असतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21624,26,5,'EVS Part 2','mr','इतिहास म्हणजे काय ?','[\"इतिहास म्हणजे भूतकाळात घडलेल्या घटनांचे ज्ञान.\",\"भूतकाळ म्हणजे गेलेला वेळ, उदा. गेल्या वर्षी.\",\"वर्तमानकाळ म्हणजे आत्ता, आजचा क्षण.\",\"भविष्यकाळ म्हणजे येणारा वेळ, उदा. उद्या, पुढील वर्षी.\",\"इतिहास शास्त्र म्हणजे भूतकाळातील घटना समजून परिणाम घेण्याचा शास्त्र.\",\"इतिहासाच्या साधने त्रिविध आहेत: भौतिक, लिखित, मौखिक.\",\"भौतिक साधने: नाणी, भांडी, शिल्पे, वास्तू, किल्ले, ताम्रपट.\",\"लिखित साधने: ग्रंथ, हस्तलिखिते, ताम्रपट, शिलालेख, चरित्रग्रंथ.\",\"मौखिक साधने: लोकगीते, लोककथा, स्तंभ, वाडे.\",\"पुरातत्त्व शास्त्र म्हणजे भूतकाळातील अवशेषांचा अभ्यास करणारा शास्त्र.\",\"पुरावशेप म्हणजे जुन्या वस्तू व वास्तूचे अवशेष, जे मातीत गाडले जाते.\",\"पुरातत्त्वज्ञ पुरावशेप शोधून काढतात व त्यांचा अभ्यास करतात.\",\"इतिहासाचा अभ्यास करून आपली सांस्कृतिक प्रगती समजते.\",\"इतिहास केवळ कल्पनेवर आधारित नाही, तर प्रमाणावर आधारित आहे.\",\"इतिहासाचा अभ्यास करून आपण भूतकाळातील मानवी जीवन पद्धती समजतो.\"]','[{\"q\":\"भूतकाळात घडलेल्या घटना समजून घेण्याच्या शास्त्राला काय म्हणतात?\",\"options\":[\"भूगोल\",\"नागरिकशास्त्र\",\"इतिहास\",\"विज्ञान\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, भूतकाळात घडलेल्या घटना समजून घेण्याच्या शास्त्राला \'इतिहास\' म्हणतात.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"छत्रपती शिवाजी महाराजांच्या जन्मापूर्वीचा काळ म्हणजे आजपासून सुमारे किती वर्षांपूर्वीचा काळ होय?\",\"options\":[\"शंभर वर्षे\",\"दोनशे वर्षे\",\"तीनशे वर्षे\",\"चारशे वर्षे\"],\"answer\":3,\"explain\":\"शिवाजी महाराजांच्या जन्मापूर्वीचा काळ म्हणजे आजपासून सुमारे चारशे वर्षांपूर्वीचा काळ आहे.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'आत्ता\', \'आज\' आणि \'या वर्षी\' हे शब्द कोणता काळ दर्शवतात?\",\"options\":[\"भूतकाळ\",\"वर्तमानकाळ\",\"भविष्यकाळ\",\"जुना काळ\"],\"answer\":1,\"explain\":\"\'आत्ता\', \'आज\', \'या वर्षी\' इत्यादी शब्दांनी लक्षात येणारा काळ म्हणजे वर्तमानकाळ होय.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"निघून गेलेला क्षण हा कोणता काळ असतो?\",\"options\":[\"वर्तमानकाळ\",\"भविष्यकाळ\",\"भूतकाळ\",\"चालू काळ\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील व्याख्येनुसार, निघून गेलेला क्षण हा भूतकाळ असतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात दाखवलेली बालकाची स्थिती जीवनातील कोणता काळ दर्शवते?\",\"options\":[\"वर्तमानकाळ\",\"भविष्यकाळ\",\"भूतकाळ (जन्मदिवस)\",\"येणारा काळ\"],\"answer\":2,\"explain\":\"चित्रातील मजकुरानुसार, जन्मदिवसाची ही घटना भूतकाळ दर्शवते.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"26\\/012_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील मुले सध्या कोणत्या वयाची आहेत असे मजकुरात म्हटले आहे?\",\"options\":[\"पाच वर्षांचे\",\"दहा वर्षांचे\",\"वीस वर्षांचे\",\"पंधरा वर्षांचे\"],\"answer\":1,\"explain\":\"चित्रातील मजकुरानुसार, मुले आज दहा वर्षांची आहेत, जो वर्तमानकाळ आहे.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"26\\/012_102.jpg\"},{\"q\":\"दिलेल्या चित्रात दाखवल्याप्रमाणे, दहा वर्षांनंतर मुलांचे वय किती होईल?\",\"options\":[\"दहा वर्षे\",\"पंधरा वर्षे\",\"वीस वर्षे\",\"पंचवीस वर्षे\"],\"answer\":2,\"explain\":\"चित्रातील मजकुरानुसार, दहा वर्षांनी भविष्यकाळात मुलांचे वय वीस वर्षे होईल.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"26\\/012_103.jpg\"},{\"q\":\"\'थोड्या वेळानंतर\', \'उद्या\' आणि \'पुढील वर्षी\' या शब्दांतून कोणता काळ समजतो?\",\"options\":[\"भूतकाळ\",\"वर्तमानकाळ\",\"भविष्यकाळ\",\"होऊन गेलेला काळ\"],\"answer\":2,\"explain\":\"भविष्यकाळ हा अजून यायचा असतो, जो \'उद्या\' किंवा \'पुढील वर्षी\' या शब्दांनी समजतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"जर आज तुमचे वय १० वर्षे असेल, तर तुमच्या जन्माची घटना किती वर्षांपूर्वी घडली असेल?\",\"options\":[\"५ वर्षांपूर्वी\",\"१० वर्षांपूर्वी\",\"२० वर्षांपूर्वी\",\"४०० वर्षांपूर्वी\"],\"answer\":1,\"explain\":\"आजचे वय १० वर्षे असल्यास, जन्माची घटना १० वर्षांपूर्वी भूतकाळात घडली असा अर्थ होतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"आपल्या जन्माच्या दिवसापासून आजपर्यंतचा निघून गेलेला काळ म्हणजे काय?\",\"options\":[\"आपला भविष्यकाळ\",\"आपला वर्तमानकाळ\",\"आपला भविष्यवेध\",\"आपल्या आयुष्यातील भूतकाळ\"],\"answer\":3,\"explain\":\"जन्मापासून आजपर्यंतचा निघून गेलेला काळ हा एका व्यक्तीच्या आयुष्यातील भूतकाळ असतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता शब्द \'भूतकाळ\' दर्शवण्यासाठी वापरला जातो?\",\"options\":[\"आत्ता\",\"उद्या\",\"काल\",\"आज\"],\"answer\":2,\"explain\":\"\'काल\' हा शब्द होऊन गेलेला काळ म्हणजेच भूतकाळ दर्शवतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"काळाचे भाग आपण कशासाठी पाडत असतो?\",\"options\":[\"इतिहास लिहिण्यासाठी\",\"व्यवहाराच्या सोयीसाठी\",\"शाळा शिकण्यासाठी\",\"भविष्य पाहण्यासाठी\"],\"answer\":1,\"explain\":\"आपण व्यवहाराच्या सोयीसाठी काळाचे वेगवेगळ्या पद्धतीने भाग पाडत असतो.\",\"topic\":\"१.१ इतिहास : भूतकाळातील घटनांचे ज्ञान\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"प्रत्येक पुरावा वेगवेगळ्या कसोट्यांवर तपासून तो विश्वास ठेवण्याजोगा आहे की नाही, हे ठरवण्याच्या पद्धतीला काय म्हणतात?\",\"options\":[\"ऐतिहासिक पद्धत\",\"शास्त्रीय पद्धत\",\"काल्पनिक पद्धत\",\"प्रायोगिक पद्धत\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, पुरावा तपासून पाहण्याच्या पद्धतीला \'शास्त्रीय पद्धत\' असे म्हणतात.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहासाच्या साधनांचे एकूण किती प्रकार पडतात?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"इतिहासाच्या साधनांचे भौतिक, लिखित आणि मौखिक असे तीन प्रकार असतात.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहास केवळ कशाच्या आधारे लिहिला जात नाही?\",\"options\":[\"पुराव्यांच्या\",\"शास्त्राच्या\",\"कल्पनेच्या\",\"साधनांच्या\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की इतिहास केवळ कल्पनेच्या आधारे लिहिला जात नाही.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहास हे एक शास्त्र आहे असे का म्हटले जाते?\",\"options\":[\"कारण त्यात गोष्टी सांगितल्या जातात.\",\"कारण तो केवळ कल्पनेवर आधारित असतो.\",\"कारण पुरावा शोधण्यासाठी आणि तपासण्यासाठी शास्त्रीय पद्धतीचाच उपयोग केला जातो.\",\"कारण त्यात प्रयोगशाळेत प्रयोग केले जातात.\"],\"answer\":2,\"explain\":\"इतिहासात पुरावा शोधण्यासाठी, तपासण्यासाठी आणि जुळवण्यासाठी शास्त्रीय पद्धत वापरली जाते, म्हणून ते एक शास्त्र आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इतर शास्त्रांपेक्षा इतिहासाची मांडणी करण्याची पद्धत वेगळी का आहे?\",\"options\":[\"इतिहास जुना असतो म्हणून.\",\"भूतकाळातील घटना पुन्हा जशाच्या तशा घडवून आणण्याचा प्रयोग करणे शक्य नसते म्हणून.\",\"इतिहासात पुरावे नसतात म्हणून.\",\"इतिहास केवळ आजीआजोबा सांगतात म्हणून.\"],\"answer\":1,\"explain\":\"इतर शास्त्रांप्रमाणे भूतकाळातील घटनांचा पुन्हा प्रयोग करणे शक्य नसल्यामुळे इतिहासाची पद्धत वेगळी आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जेव्हा एकाच गोष्टीची आठवण वेगवेगळ्या व्यक्ती सांगतात आणि त्यात फरक असतो, तेव्हा काय करावे लागते?\",\"options\":[\"दोन्ही गोष्टी खऱ्या मानाव्यात.\",\"दोन्ही गोष्टी सोडून द्याव्यात.\",\"नेमके बरोबर कोणते हे ठरवण्यासाठी बारकाईने तपासणी करावी लागते.\",\"सर्वात मोठ्या व्यक्तीचे सांगणे बरोबर मानावे.\"],\"answer\":2,\"explain\":\"फरक असल्यास नेमके बरोबर काय हे ठरवण्यासाठी गोष्टींची बारकाईने तपासणी करावी लागते.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात इतिहासाचे कोणते साधन दाखवले आहे?\",\"options\":[\"ताम्रपट\",\"भांडी\",\"नाणी\",\"ग्रंथ\"],\"answer\":2,\"explain\":\"दिलेले चित्र \'नाणी\' या ऐतिहासिक साधनाचे आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"remember\",\"figure_image\":\"26\\/013_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील साधन इतिहासाच्या कोणत्या प्रकारात मोडते?\",\"options\":[\"लिखित साधने\",\"भौतिक साधने\",\"मौखिक साधने\",\"काल्पनिक साधने\"],\"answer\":1,\"explain\":\"नाणी हे वस्तू स्वरूपात असल्याने ते \'भौतिक साधन\' आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"apply\",\"figure_image\":\"26\\/013_102.jpg\"},{\"q\":\"जर तुम्हाला जुन्या काळातील एखादे हस्तलिखित सापडले, तर तुम्ही त्याचा समावेश कोणत्या साधनात कराल?\",\"options\":[\"भौतिक साधन\",\"मौखिक साधन\",\"लिखित साधन\",\"प्रायोगिक साधन\"],\"answer\":2,\"explain\":\"हस्तलिखिते ही लिहिलेली असतात, म्हणून ती \'लिखित साधने\' आहेत.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पुढीलपैकी कोणते साधन \'मौखिक साधन\' या गटात येते?\",\"options\":[\"ताम्रपट\",\"भांडी\",\"लोकगीते\",\"शिलालेख\"],\"answer\":2,\"explain\":\"लोकांच्या स्मरणात असलेली लोकगीते ही मौखिक साधने आहेत.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"इतिहासाची शास्त्रीय मांडणी करताना पुराव्यांच्या बाबतीत कोणती प्रक्रिया केली जाते?\",\"options\":[\"पुराव्यांच्या खरेखोटेपणाची कसून तपासणी केली जाते.\",\"पुरावे जसे आहेत तसे स्वीकारले जातात.\",\"पुराव्यांकडे दुर्लक्ष केले जाते.\",\"केवळ जुन्या पुराव्यांचा विचार केला जातो.\"],\"answer\":0,\"explain\":\"भूतकाळात काय घडले याचा शोध घेण्यासाठी पुराव्यांच्या खरेखोटेपणाची कसून तपासणी करणे ही शास्त्रीय पद्धत आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"कसोटीला उतरलेल्या पुराव्यांच्या आधारे भूतकाळातील घटनांची मांडणी कशी केली जाते?\",\"options\":[\"उलट क्रमाने\",\"क्रमवार\",\"विस्कळीतपणे\",\"केवळ महत्त्वाच्या घटनांची\"],\"answer\":1,\"explain\":\"पुराव्यांच्या आधारे घटनांची \'क्रमवार\' मांडणी करणे ही इतिहासाची पद्धत आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहास लेखनात इतर शास्त्रांची मदत का घेतली जाते?\",\"options\":[\"इतिहास हे शास्त्र नसल्यामुळे.\",\"इतिहासकारांना माहिती नसल्यामुळे.\",\"पुरावा शोधण्यासाठी, तपासण्यासाठी आणि जुळवण्यासाठी आवश्यक असल्यास.\",\"इतर शास्त्रांना काम मिळावे म्हणून.\"],\"answer\":2,\"explain\":\"पुराव्यांची विश्वासार्हता तपासण्यासाठी आणि जुळवण्यासाठी इतिहासात इतर शास्त्रांची मदत घेतली जाते.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते विधान इतिहासाच्या शास्त्रीय पद्धतीला अनुसरून आहे?\",\"options\":[\"इतिहास केवळ कल्पनेवर लिहिता येतो.\",\"कोणताही पुरावा प्रत्यक्ष प्रयोगांच्या कसोट्यांवर पुन्हापुन्हा तपासून पाहता येतो.\",\"इतिहासात पुराव्यांची गरज नसते.\",\"इतिहासातील घटना पुन्हा घडवून आणता येतात.\"],\"answer\":1,\"explain\":\"पुराव्यांची वारंवार तपासणी करणे हे सर्व शास्त्रांचे आणि इतिहासाचे वैशिष्ट्य आहे.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"ताम्रपट हे इतिहासाचे साधन आहे, कारण...\",\"options\":[\"ते तांब्याचे असते.\",\"ते जुने असते.\",\"त्यातून भूतकाळातील घटनांचा पुरावा मिळतो.\",\"ते दिसायला सुंदर असते.\"],\"answer\":2,\"explain\":\"ज्या वस्तूंमधून किंवा लिखाणातून भूतकाळाची माहिती मिळते, त्यांना इतिहासाची साधने म्हणतात.\",\"topic\":\"१.२ इतिहासाची शास्त्रीय पद्धत\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"इतिहास हा कोणत्या काळातील घटनांचा अभ्यास करतो?\",\"options\":[\"भविष्यकाळातील\",\"वर्तमानकाळातील\",\"भूतकाळातील\",\"काल्पनिक\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, इतिहास भूतकाळातील घटनांचा अभ्यास करतो.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पर्यावरणशास्त्र कोणत्या विषयाचा अभ्यास करते?\",\"options\":[\"भूतकाळातील घटना\",\"पर्यावरणाची हानी आणि प्रदूषण\",\"ग्रहांची स्थिती\",\"केवळ प्राणीसृष्टी\"],\"answer\":1,\"explain\":\"पर्यावरणशास्त्र पर्यावरणाची हानी, प्रदूषण आणि त्यांवरील उपाय यांचा अभ्यास करते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"गावाचा विकास उत्तम रीतीने होण्यासाठी काय आवश्यक असते?\",\"options\":[\"लोकांमधील स्पर्धा\",\"लोकांची एकजूट आणि एकमेकांना साहाय्य\",\"केवळ नवीन तंत्रज्ञान\",\"केवळ सरकारी मदत\"],\"answer\":1,\"explain\":\"जेव्हा गावातील लोक एकजुटीने आणि साहाय्याने कामे करतात, तेव्हा गावाचा विकास उत्तम होतो.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"गावाच्या विकासात अडथळे केव्हा निर्माण होतात?\",\"options\":[\"जेव्हा लोक खूप काम करतात\",\"जेव्हा लोकांमध्ये एकजूट नसते\",\"जेव्हा पाऊस पडतो\",\"जेव्हा लोक शिक्षण घेतात\"],\"answer\":1,\"explain\":\"गावातील लोकांमध्ये एकजूट झाली नाही, तर विकासात अडथळे निर्माण होतात.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"इतिहासाच्या अभ्यासामुळे मानवी समाजाच्या प्रगतीसाठी काय शक्य होते?\",\"options\":[\"केवळ जुन्या गोष्टींची माहिती मिळवणे\",\"इष्ट काय आणि अनिष्ट काय याचा अभ्यास करणे\",\"केवळ भविष्य सांगणे\",\"केवळ युद्धे करणे\"],\"answer\":1,\"explain\":\"इतिहासाच्या अभ्यासामुळे मानवी समाजाच्या प्रगतीसाठी इष्ट काय आणि अनिष्ट काय, हे समजते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"भविष्यकाळ चांगल्या प्रकारे घडवण्यासाठी कशाचा उपयोग होतो?\",\"options\":[\"केवळ कल्पनाशक्तीचा\",\"वर्तमानकाळात आपण कसे वागतो याचा\",\"केवळ पैशांचा\",\"केवळ नशिबाचा\"],\"answer\":1,\"explain\":\"वर्तमानकाळात आपण कसे वागल्याने भविष्यकाळ चांगला घडवता येईल, हे इतिहासातून समजते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"थोर व्यक्तींच्या चरित्रांतून आपल्याला काय मिळते?\",\"options\":[\"केवळ मनोरंजन\",\"स्फूर्ती आणि प्रेरणा\",\"केवळ संपत्ती\",\"केवळ भीती\"],\"answer\":1,\"explain\":\"थोर व्यक्तींच्या चरित्रांतून स्फूर्ती आणि प्रेरणा मिळवून देण्याचे कार्य इतिहास करतो.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"इतिहासामुळे आपल्याला मानवी संस्कृतीबद्दल काय समजते?\",\"options\":[\"केवळ लढायांची माहिती\",\"संस्कृतींमधील देवाणघेवाण आणि विकासाची वाटचाल\",\"केवळ राजांची नावे\",\"केवळ जुनी गाणी\"],\"answer\":1,\"explain\":\"इतिहासामुळे आपली आणि इतर संस्कृतींमधील देवाणघेवाण आणि विकासाची वाटचाल समजते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणाला स्वतःचा स्वतंत्र इतिहास नसतो?\",\"options\":[\"गाव आणि जिल्हा\",\"पृथ्वी आणि डोंगर\",\"प्राणीसृष्टी\",\"दिलेल्या पर्यायांपैकी सर्वांना इतिहास असतो\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकानुसार गाव, जिल्हा, राज्य, देश, पृथ्वी, डोंगर, जलाशय, प्राणीसृष्टी या सर्वांना स्वतंत्र इतिहास असतो.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शास्त्रीय शोध आणि शास्त्रज्ञांची माहिती आपल्याला कशाच्या आधारे मिळते?\",\"options\":[\"केवळ वर्तमानपत्रातून\",\"प्रत्येक शास्त्राच्या स्वतःच्या इतिहासातून\",\"केवळ गोष्टींच्या पुस्तकातून\",\"केवळ भविष्यातील नियोजनातून\"],\"answer\":1,\"explain\":\"प्रत्येक शास्त्राचा स्वतःचा इतिहास असतो, त्यातून शास्त्रीय शोध आणि शास्त्रज्ञांची माहिती मिळते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"मानवी समाजाच्या प्रगतीसाठी पोषक किंवा हानिकारक वातावरण कशामुळे निर्माण होते?\",\"options\":[\"केवळ हवामानामुळे\",\"माणसाच्या व्यक्तिगत किंवा सामूहिक कृतींच्या परिणामांतून\",\"केवळ नशिबामुळे\",\"केवळ प्राण्यांच्या हालचालींमुळे\"],\"answer\":1,\"explain\":\"माणसाच्या व्यक्तिगत किंवा सामूहिक कृतींच्या परिणामांतून प्रगतीसाठी पोषक किंवा हानिकारक वातावरण निर्माण होते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"इतिहास कोणत्या गोष्टींचा शोध घेऊन प्रश्नांची उत्तरे शोधतो?\",\"options\":[\"केवळ भविष्यकाळातील स्वप्नांचा\",\"भूतकाळातील मानवी समाजाचे विचार, कृती आणि कृतींचे परिणाम\",\"केवळ आजच्या बातम्यांचा\",\"केवळ अवकाशातील ग्रहांचा\"],\"answer\":1,\"explain\":\"इतिहास भूतकाळातील मानवी समाजाचे विचार, कृती आणि कृतींचे परिणाम यांचा शोध घेतो.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"एका विद्यार्थ्याला विज्ञानातील प्रगती कशी झाली हे जाणून घ्यायचे आहे, त्याने काय अभ्यासावे?\",\"options\":[\"केवळ कविता\",\"विज्ञानाचा इतिहास\",\"केवळ चित्रकला\",\"केवळ खेळ\"],\"answer\":1,\"explain\":\"प्रत्येक शास्त्राचा स्वतःचा इतिहास असतो, ज्यातून त्या विषयातील बदलांची माहिती मिळते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"माणसाच्या जीवनपद्धतीत कसे बदल होत गेले, हे आपल्याला कशामुळे समजते?\",\"options\":[\"भूगोलामुळे\",\"इतिहासामुळे\",\"केवळ गणितामुळे\",\"केवळ नागरिकशास्त्रामुळे\"],\"answer\":1,\"explain\":\"इतिहासामुळे माणसांच्या जीवनपद्धतीत कसे बदल होत गेले, हे समजून घेता येते.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"इतिहासाच्या अभ्यासाचे मुख्य महत्त्व काय आहे?\",\"options\":[\"केवळ जुन्या कथा वाचणे\",\"मानवी संस्कृतीच्या विकासाची वाटचाल समजून घेणे\",\"केवळ सनावळ्या पाठ करणे\",\"केवळ चित्रे काढणे\"],\"answer\":1,\"explain\":\"मानवी संस्कृतीच्या विकासाची वाटचाल आणि मानवी प्रगती समजून घेणे हे इतिहासाचे महत्त्व आहे.\",\"topic\":\"१.३ इतिहास आणि आपण\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"भारत देश कोणत्या तारखेला स्वतंत्र झाला?\",\"options\":[\"१५ ऑगस्ट १९४७\",\"२६ जानेवारी १९५०\",\"१५ ऑगस्ट १९५०\",\"२६ जानेवारी १९४७\"],\"answer\":0,\"explain\":\"पाठातील मजकुरानुसार, १५ ऑगस्ट १९४७ रोजी भारत देश स्वतंत्र झाला.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"भूतकाळ, वर्तमानकाळ आणि भविष्यकाळ हे कशाने जोडलेले असतात?\",\"options\":[\"वेगवेगळ्या पुस्तकांनी\",\"अखंड साखळीने\",\"केवळ फोटोंनी\",\"स्वतंत्र घटनांनी\"],\"answer\":1,\"explain\":\"भूतकाळ, वर्तमानकाळ आणि भविष्यकाळ हे विविध घटनांच्या अखंड साखळीने जोडलेले असतात.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"स्वातंत्र्यप्राप्ती ही घटना कोणत्या कृतीचा परिणाम आहे?\",\"options\":[\"चाकाच्या शोधाचा\",\"हत्यारे बनवण्याचा\",\"इंग्रज सरकारविरुद्ध दिलेल्या लढ्याचा\",\"बौद्धिक विकासाचा\"],\"answer\":2,\"explain\":\"भारतीयांनी इंग्रज सरकारविरुद्ध लढा दिला, या कृतीचा परिणाम म्हणजे स्वातंत्र्यप्राप्ती होय.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"भविष्यकाळ हा कशावर अवलंबून असतो?\",\"options\":[\"केवळ नशिबावर\",\"भूतकाळातील कृतींवर\",\"केवळ भविष्यातील विचारांवर\",\"इतिहासाच्या पुस्तकावर\"],\"answer\":1,\"explain\":\"भूतकाळातील कृतींवर भविष्यकाळ अवलंबून असतो, हे आपल्याला इतिहासाच्या अभ्यासातून कळते.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मानवाने हत्यारे निर्माण करण्यासाठी कशाचा वापर केला?\",\"options\":[\"परिसरातील उपलब्ध साहित्याचा\",\"लोखंडी कारखान्यांचा\",\"परदेशातील तंत्रज्ञानाचा\",\"केवळ मातीचा\"],\"answer\":0,\"explain\":\"मानवाने आसपासच्या परिसरात उपलब्ध असलेल्या साहित्यातून हत्यारे निर्माण करण्याची कला आत्मसात केली.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"हत्यारे बनवण्याची कला आत्मसात केल्यानंतर मानवाने पुढे कोणता महत्त्वाचा शोध लावला?\",\"options\":[\"संगणकाचा\",\"विमानाचा\",\"चाकाचा\",\"मोबाईलचा\"],\"answer\":2,\"explain\":\"मानवाने हत्यारे बनवल्यानंतर पुढे चाकाचा शोध लावला.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"तंत्रज्ञान विकसित होण्यामागे मानवाचा कोणता विकास कारणीभूत आहे?\",\"options\":[\"केवळ शारीरिक विकास\",\"केवळ आर्थिक विकास\",\"शारीरिक आणि बौद्धिक विकास\",\"केवळ सामाजिक विकास\"],\"answer\":2,\"explain\":\"मानवाच्या शारीरिक आणि बौद्धिक विकासाच्या जोडीनेच तंत्रज्ञानही विकसित होत गेले.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"नवनवीन शोध लावणे कशामुळे शक्य होते?\",\"options\":[\"भूतकाळातील शोधांच्या आधाराने\",\"केवळ नवीन विचारांमुळे\",\"इतिहास विसरल्यामुळे\",\"जुने शोध नष्ट केल्यामुळे\"],\"answer\":0,\"explain\":\"भूतकाळातील शोधांच्या आधारानेच पुढचे नवनवीन शोध लावणे शक्य असते.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"तंत्रज्ञान विकसित होण्याची प्रक्रिया कशी आहे?\",\"options\":[\"ती पूर्ण झाली आहे\",\"ती थांबली आहे\",\"ती अखंडपणे सुरू आहे\",\"ती आता सुरू होणार आहे\"],\"answer\":2,\"explain\":\"तंत्रज्ञान विकसित होण्याची प्रक्रिया अजूनही अखंडपणे सुरूच आहे.\",\"topic\":\"१.३ भूतकाळ आणि भविष्यकाळ\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर मानवाने पूर्वी अग्नीचा शोध लावला नसता, तर आजच्या प्रगत चुलींचा शोध लागला असता का? यावरून काय सिद्ध होते?\",\"options\":[\"भूतकाळ महत्त्वाचा नाही\",\"भविष्यकाळ भूतकाळावर अवलंबून 