q\":\"मृत व्यक्तीच्या अंगाला कोणत्या रंगाची माती चोळण्याची प्रथा शक्तीमान मानवात होती?\",\"options\":[\"काळ्या रंगाची\",\"पांढऱ्या रंगाची\",\"पिवळ्या रंगाची\",\"लाल रंगाची\"],\"answer\":3,\"explain\":\"शक्तीमान मानव मृत व्यक्तीच्या अंगाला लाल रंगाची माती चोळत असत.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शक्तीमान मानवाच्या हत्यारांमध्ये कोणती सुधारणा झाली होती?\",\"options\":[\"त्याने धातूची हत्यारे बनवली\",\"त्याने हाडांच्या किंवा लाकडाच्या दांड्यांवर दगडी शस्त्रे बसवली\",\"त्याने फक्त लाकडी शस्त्रांचा वापर केला\",\"त्याने हत्यारे बनवणे बंद केले\"],\"answer\":1,\"explain\":\"तो लांब हाडांच्या किंवा लाकडाच्या दांड्यांवर भाला, कुऱ्हाड इत्यादी शस्त्रे तयार करत असे.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"शक्तीमान मानवांनी आफ्रिकेतून बाहेर पडून कोणत्या खंडांपर्यंत स्थलांतर केले?\",\"options\":[\"ऑस्ट्रेलिया आणि अमेरिका\",\"युरोप आणि आशिया\",\"अंटार्क्टिका\",\"फक्त आशिया\"],\"answer\":1,\"explain\":\"काळाच्या ओघात त्यांनी युरोप आणि आशिया या खंडांपर्यंत स्थलांतर केले.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शक्तीमान मानवाच्या संवादाबद्दल शास्त्रज्ञांचे काय मत आहे?\",\"options\":[\"तो स्पष्ट मराठी बोलत असे\",\"तो काही जुजबी आवाज काढून संवाद साधत असावा\",\"त्याच्याकडे अत्यंत विकसित भाषापद्धती होती\",\"तो अजिबात आवाज काढत नसे\"],\"answer\":1,\"explain\":\"काही शास्त्रज्ञांच्या मते, तो काही जुजबी आवाज काढून संवाद साधत असावा.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शक्तीमान मानवाचे अस्तित्व सुमारे किती वर्षांपूर्वी संपुष्टात आले?\",\"options\":[\"५०,००० वर्षांपूर्वी\",\"१०,००० वर्षांपूर्वी\",\"३०,००० वर्षांपूर्वी\",\"१,००,००० वर्षांपूर्वी\"],\"answer\":2,\"explain\":\"सुमारे ३०,००० वर्षांपूर्वी शक्तीमान मानव नष्ट झाला असे मानले जाते.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शक्तीमान मानवाचा काळ निश्चित करण्यासाठी कोणती शास्त्रीय पद्धत वापरली जाते?\",\"options\":[\"क्ष-किरण पद्धत\",\"कार्बन-१४ पद्धत\",\"रक्त तपासणी पद्धत\",\"दगड मोजणी पद्धत\"],\"answer\":1,\"explain\":\"कार्बन-१४ पद्धतीच्या आधारे शक्तीमान मानवाचा काळ सांगितला जातो.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"शक्तीमान मानवाचे अस्तित्व नष्ट होण्याचे एक संभाव्य कारण कोणते?\",\"options\":[\"मोठा महापूर आला\",\"बुद्धिमान मानवांच्या समूहांबरोबरचा संघर्ष\",\"त्यांना अग्नीचा वापर करता आला नाही\",\"त्यांनी शिकार करणे सोडले\"],\"answer\":1,\"explain\":\"बुद्धिमान मानवांच्या समूहांबरोबरचा संघर्ष आणि पर्यावरणातील बदल ही विनाशाची कारणे मानली जातात.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"शक्तीमान मानवाने नवीन वातावरणात जगण्यासाठी काय केले?\",\"options\":[\"तो पुन्हा आफ्रिकेत निघून गेला\",\"त्याने जगण्याच्या आणि अन्न मिळवण्याच्या नवीन पद्धती आत्मसात केल्या\",\"त्याने हत्यारे वापरणे सोडून दिले\",\"त्याने गुहेत राहणे बंद केले\"],\"answer\":1,\"explain\":\"भिन्न वातावरणात त्यांना जगण्याच्या आणि अन्न मिळवण्याच्या नवीन पद्धती आत्मसात कराव्या लागल्या.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"शक्तीमान मानवापेक्षा अधिक प्रगत असणाऱ्या मानवास काय म्हणतात?\",\"options\":[\"कुशल मानव\",\"ताठ कण्याचा मानव\",\"बुद्धिमान मानव\",\"राक्षसी मानव\"],\"answer\":2,\"explain\":\"शक्तीमान मानवापेक्षा अधिक प्रगत असणाऱ्या मानवास \'बुद्धिमान मानव\' म्हणतात.\",\"topic\":\"शक्तीमान मानव\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'सेपियन\' (Sapien) या शब्दाचा अर्थ काय होतो?\",\"options\":[\"शक्तिमान\",\"कुशल\",\"बुद्धिमान\",\"ताठ चालणारा\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार \'सेपियन\' म्हणजे बुद्धिमान होय.\",\"topic\":\"बुद्धिमान मानव\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"युरोपमध्ये बुद्धिमान मानवाला कोणत्या नावाने ओळखले गेले?\",\"options\":[\"निअँडरथल\",\"क्रोमॅनॉन\",\"होमो इरेक्टस\",\"होमो हॅबिलिस\"],\"answer\":1,\"explain\":\"बुद्धिमान मानवाला युरोपमध्ये \'क्रोमॅनॉन\' या नावाने ओळखले गेले.\",\"topic\":\"बुद्धिमान मानव\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"बुद्धिमान मानवाने हत्यारे बनवण्यासाठी दगडाची छोटी पाती कशात बसवली ह