ply\"},{\"q\":\"उताऱ्यातील माहितीनुसार, मानवी संस्कृतीच्या विकासाचा क्रम कसा आहे?\",\"options\":[\"अन्न मिळवणे -> कल्पकता व कौशल्य वापरणे -> जीवन समृद्ध करणे\",\"शेती करणे -> वानर बनणे -> शिकार करणे\",\"केवळ शारीरिक वाढ -> अन्नाचा शोध\",\"सांस्कृतिक वाटचाल -> वानराचा जन्म\"],\"answer\":0,\"explain\":\"मानवाने अन्नाच्या गरजेपलीकडे जाऊन कल्पकता व कौशल्याने जीवन समृद्ध केले, हीच संस्कृतीची वाटचाल आहे.\",\"topic\":\"मानवी संस्कृतीची वाटचाल\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"\'अश्म\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"माती\",\"दगड\",\"हाड\",\"पाणी\"],\"answer\":1,\"explain\":\"पाठातील मजकुराप्रमाणे \'अश्म\' म्हणजे \'दगड\' असा होतो.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"हाडांच्या आकारातील दगडांना काय म्हणतात?\",\"options\":[\"खनिजे\",\"मातीचे गोळे\",\"प्राण्यांचे अश्मीभूत अवशेष\",\"प्राण्यांची हाडे\"],\"answer\":2,\"explain\":\"हाडांच्या आकारांत शिल्लक राहिलेल्या खनिजांना \'प्राण्यांचे अश्मीभूत अवशेष\' म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"हाडांच्या सच्छिद्र पोकळ्यांमध्ये मातीमधील काय जमा होते?\",\"options\":[\"पाणी\",\"खनिजे\",\"हवा\",\"कचरा\"],\"answer\":1,\"explain\":\"वर्षानुवर्षे मातीखाली राहिल्यामुळे हाडांच्या पोकळ्यांमध्ये खनिजे जमा होतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मानवी उत्क्रांतीचे अश्मीभूत अवशेष खालीलपैकी कोणत्या खंडात मिळालेले नाहीत?\",\"options\":[\"आफ्रिका\",\"आशिया\",\"युरोप\",\"अंटार्क्टिका\"],\"answer\":3,\"explain\":\"मजकुरात आफ्रिका, आशिया आणि युरोपमध्ये अवशेष मिळाल्याचा उल्लेख आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मानवी उत्क्रांतीचा क्रम पूर्णपणे मांडण्यासाठी सध्या कोणती अडचण येत आहे?\",\"options\":[\"खनिजे संपली आहेत\",\"सर्व दुवे अजून मिळालेले नाहीत\",\"शास्त्रज्ञ काम करत नाहीत\",\"हाडे खूप जुनी आहेत\"],\"answer\":1,\"explain\":\"उत्क्रांतीचा क्रम मांडण्यासाठी आवश्यक असलेले सर्व दुवे अजून मिळालेले नाहीत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मानवी उत्क्रांतीच्या प्रक्रियेबद्दल खालीलपैकी कोणते विधान योग्य आहे?\",\"options\":[\"ती एका सरळ रेषेत झाली\",\"पूर्वज प्रजातीतून अनेक शाखा निर्माण झाल्या\",\"सर्व शाखा आजही अस्तित्वात आहेत\",\"उत्क्रांती फक्त आशियात झाली\"],\"answer\":1,\"explain\":\"एखादी पूर्वज प्रजाती उत्क्रांत होत असताना तिच्या अनेक शाखा निर्माण झाल्या.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"मानवी संस्कृतीच्या इतिहासाची मांडणी कशाच्या आधारे करणे शक्य होते?\",\"options\":[\"केवळ हाडांच्या आधारे\",\"केवळ मातीच्या आधारे\",\"मानवाने घडवलेली हत्यारे आणि इतर वस्तू\",\"केवळ झाडांच्या आधारे\"],\"answer\":2,\"explain\":\"मानवाने बनवलेली हत्यारे आणि वस्तू संस्कृतीच्या इतिहासाची मांडणी करण्यास मदत करतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या पर्यायांपैकी मानवी उत्क्रांतीचा योग्य क्रम कोणता?\",\"options\":[\"शक्तिमान मानव → कुशल मानव → बुद्धिमान मानव\",\"कुशल मानव → ताठ कण्याचा मानव → शक्तिमान मानव → बुद्धिमान मानव\",\"बुद्धिमान मानव → शक्तिमान मानव → ताठ कण्याचा मानव\",\"ताठ कण्याचा मानव → कुशल मानव → बुद्धिमान मानव\"],\"answer\":1,\"explain\":\"पाठात कुशल, ताठ कण्याचा, शक्तिमान आणि बुद्धिमान असा क्रम दिला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मृत प्राण्यांच्या शरीराचे विघटन झाल्यावर काय विखुरली जातात?\",\"options\":[\"खनिजे\",\"हाडे\",\"हत्यारे\",\"दगड\"],\"answer\":1,\"explain\":\"मृत प्राण्यांच्या शरीराचे विघटन होऊन त्यांची हाडे विखुरली जातात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"एखाद्या हाडाचे अश्मीभूत अवशेष तयार होण्यासाठी काय होणे आवश्यक आहे?\",\"options\":[\"ते हाड जाळणे आवश्यक आहे\",\"ते हाड पाण्यात टाकणे आवश्यक आहे\",\"ते हाड वर्षानुवर्षे मातीखाली राहणे आवश्यक आहे\",\"ते हाड उन्हात ठेवणे आवश्यक आहे\"],\"answer\":2,\"explain\":\"वर्षानुवर्षे मातीखाली राहिल्यामुळेच हाडांचे अश्मीभूत अवशेष तयार होतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"उत्क्रांतीच्या क्रमात निर्माण झालेल्या काही शाखांचे काय झाले?\",\"options\":[\"त्या अमर झाल्या\",\"त्या नष्ट झाल्या\",\"त्यांनी नवीन ग्रह शोधला\",\"त्या झाडावर राहू लागल्या\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे उत्क्रांतीच्या क्रमातील काही शाखा नष्टही झाल्या.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला प्राचीन मानवाच्या संस्कृतीचा अभ्यास करायचा असेल, तर तुम्ही कशाचा शोध घ्याल?\",\"options\":[\"त्या काळातील नद्यांचा\",\"त्या काळातील ताऱ्यांचा\",\"त्यांनी वापरलेल्या हत्यारांचा आणि वस्तूंचा\",\"त्या काळातील पावसाचा\"],\"answer\":2,\"explain\":\"मानवी संस्कृतीच्या वाटचालीचे टप्पे हत्यारे आणि वस्तूंवरून समजतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मानवाला इतर पृष्ठवंशीय प्राण्यांपेक्षा वेगळे ठरवणारे प्रमुख शारीरिक वैशिष्ट्य कोणते?\",\"options\":[\"चार पायांवर चालणे\",\"ताठ उभे राहणे\",\"वेगाने धावणे\",\"झाडावर चढणे\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे मानवाला ताठ उभे राहणे शक्य झाल्यामुळे तो इतर पृष्ठवंशीय प्राण्यांपेक्षा वेगळा ठरतो.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मानवाच्या पुढच्या दोन पायांचा उपयोग \'हात\' म्हणून का होऊ लागला?\",\"options\":[\"त्याला झाडावर लोंबकळायचे होते\",\"त्याचे पाय लांब झाले\",\"तो ताठ उभा राहून दोन पायांवर चालू लागला\",\"त्याला चार पायांवर चालणे आवडत नव्हते\"],\"answer\":2,\"explain\":\"मानव ताठ उभा राहून दोन पायांवर चालू लागल्यामुळे त्याच्या पुढच्या दोन पायांचा उपयोग हात म्हणून होऊ लागला.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"मानवाला वस्तूंवर पक्की आणि लवचीक पकड कशामुळे घेता येते?\",\"options\":[\"हाताची बोटे लांब असल्यामुळे\",\"हाताचा अंगठा इतर चार बोटांपुढे आणून फिरवता येतो म्हणून\",\"हाताचे पंजे मोठे असल्यामुळे\",\"हाताचे स्नायू मजबूत असल्यामुळे\"],\"answer\":1,\"explain\":\"अंगठा इतर चार बोटांपुढे आणून आतबाहेर फिरवता येण्याच्या वैशिष्ट्यामुळे मानवाला वस्तूंवर पक्की पकड घेता येते.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"मानवाला \'साधने आणि हत्यारे निर्माण करणारा प्राणी\' का म्हटले जाते?\",\"options\":[\"त्याला हस्तकौशल्याची कामे करता येतात म्हणून\",\"तो खूप वेगाने धावू शकतो म्हणून\",\"त्याला खूप भूक लागते म्हणून\",\"तो चार पायांवर चालतो म्हणून\"],\"answer\":0,\"explain\":\"हाताच्या वैशिष्ट्यपूर्ण रचनेमुळे मानवाला हस्तकौशल्याची कामे आणि वस्तू घडवता येतात, म्हणून त्याला साधने निर्माण करणारा प्राणी म्हणतात.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"इतर प्राण्यांच्या तुलनेत मानवाच्या मेंदूची क्षमता कशी आहे?\",\"options\":[\"कमी आहे\",\"समान आहे\",\"अधिक आहे\",\"अजिबात नाही\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे मानवाच्या मेंदूची क्षमता इतर प्राण्यांपेक्षा अधिक आहे.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मानवाच्या चेहऱ्याच्या स्नायूंच्या वैशिष्ट्यपूर्ण रचनेमुळे त्याला काय शक्य होते?\",\"options\":[\"वेगाने अन्न चावणे\",\"मनातल्या भावना चेहऱ्यावर व्यक्त करणे\",\"डोळे मोठे करणे\",\"श्वास रोखून धरणे\"],\"answer\":1,\"explain\":\"चेहऱ्याच्या स्नायूंच्या रचनेमुळे मानव आपल्या मनातील भावना चेहऱ्यावर दाखवू शकतो.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"बोलण्यासाठी मानवामध्ये कोणते इंद्रिय विकसित होणे आवश्यक होते?\",\"options\":[\"नाक\",\"कान\",\"स्वरयंत्र\",\"डोळे\"],\"answer\":2,\"explain\":\"विविध ध्वनींचा उच्चार करण्यासाठी मानवामध्ये स्वरयंत्राची रचना विकसित होणे आवश्यक होते.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मानवामध्ये स्वरयंत्र विकसित होऊन त्याला बोलता येण्यासाठी साधारण किती कालावधी जावा लागला?\",\"options\":[\"शंभर वर्षे\",\"दोनशे वर्षे\",\"हजारो वर्षे\",\"पन्नास वर्षे\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे मानवाला बोलता येण्यासाठी स्वरयंत्र विकसित होण्यास हजारो वर्षांचा कालावधी जावा लागला.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"एखादा प्राणी ताठ उभा राहू शकत नसेल, तर तो साधारणपणे किती पायांवर चालतो?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"इतर पृष्ठवंशीय प्राणी ताठ उभे राहू शकत नसल्यामुळे ते चार पायांवर चालतात.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"मानवाच्या हातांच्या पंजांची रचना इतर प्राण्यांच्या पुढच्या दोन पायांपेक्षा वेगळी का झाली?\",\"options\":[\"तो हाताने जेवण करू लागला म्हणून\",\"पुढच्या दोन पायांचा उपयोग हात म्हणून होऊ लागल्यामुळे\",\"तो झाडावरून खाली उतरला म्हणून\",\"त्याला पोहता येत होते म्हणून\"],\"answer\":1,\"explain\":\"दोन पायांवर चालल्यामुळे पुढच्या दोन पायांचा उपयोग हात म्हणून झाल्याने पंजांची रचना बदलली.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत मानवी सांगाडा आणि हत्तीचा सांगाडा यांच्यातील कोणता मुख्य फरक शरीररचनेच्या वैशिष्ट्यावरून दिसून येतो?\",\"options\":[\"हत्तीचा आकार मोठा आहे\",\"मानव ताठ उभा आहे तर हत्ती चार पायांवर आहे\",\"हत्तीला सोंड आहे\",\"मानवाचे हाडे पांढरी आहेत\"],\"answer\":1,\"explain\":\"आकृतीवरून स्पष्ट होते की मानव ताठ उभा राहू शकतो, जे त्याचे प्रमुख शारीरिक वैशिष्ट्य आहे.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"evaluate\",\"figure_image\":\"26\\/035_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत मानवाच्या हाताच्या कोणत्या हालचालीमुळे त्याला वस्तूवर पकड घेणे शक्य होते हे दाखवले आहे?\",\"options\":[\"बोटे सरळ ठेवणे\",\"मुठ आवळून धरणे\",\"अंगठ्याची इतर बोटांसमोरील लवचिकता\",\"हात वर करणे\"],\"answer\":2,\"explain\":\"आकृतीत अंगठा इतर बोटांच्या समोर आणून विविध प्रकारे पकड घेण्याची क्षमता (लवचिकता) दर्शवली आहे.\",\"topic\":\"मानवाच्या शरीररचनेची वैशिष्ट्ये\",\"part\":9,\"bloom\":\"apply\",\"figure_image\":\"26\\/035_103.jpg\"},{\"q\":\"दिलेल्या कृतीनुसार, मानवाच्या वाटचालीची सुरुवात कोणत्या टप्प्यापासून होते?\",\"options\":[\"कुशल मानव\",\"ताठ कण्याचा मानव\",\"शक्तिमान मानव\",\"प्रगत बुद्धीचा मानव\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुरात \'कुशल मानव ते प्रगत बुद्धीचा मानव\' अ