s\":[\"दोघांची चित्रे रंगवाल\",\"दोघांच्या प्रगतीमधील फरक तक्त्यात मांडाल\",\"दोघांची नावे पाठ कराल\",\"दोघांच्या गोष्टी सांगाल\"],\"answer\":1,\"explain\":\"तुलनात्मक तक्ता तयार करणे म्हणजे दोन किंवा अधिक गोष्टींमधील फरक किंवा साम्य मांडणे होय.\",\"topic\":\"कृती\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"या कृतीचा मुख्य उद्देश काय आहे?\",\"options\":[\"मानवाच्या उत्क्रांतीचा प्रवास समजून घेणे\",\"केवळ तक्ता कसा काढायचा हे शिकणे\",\"मानवाचे चित्र काढणे\",\"इतिहासातील तारखा पाठ करणे\"],\"answer\":0,\"explain\":\"कुशल मानव ते प्रगत बुद्धीचा मानव या प्रवासातील प्रगती समजून घेणे हा मुख्य उद्देश आहे.\",\"topic\":\"कृती\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरातील \'वाटचाल\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"रस्त्यावरून चालणे\",\"एका ठिकाणाहून दुसऱ्या ठिकाणी जाणे\",\"मानवाच्या विकासाचा किंवा उत्क्रांतीचा प्रवास\",\"पायी प्रवास करणे\"],\"answer\":2,\"explain\":\"इतिहासाच्या संदर्भात \'वाटचाल\' म्हणजे मानवाच्या विकासाचा टप्प्याटप्प्याने झालेला प्रवास होय.\",\"topic\":\"कृती\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"तुलनात्मक तक्ता तयार करण्यासाठी माहितीचे वर्गीकरण कसे असावे?\",\"options\":[\"केवळ एकाच मानवाच्या माहितीचे\",\"मानवाच्या विविध टप्प्यांच्या आणि त्यांच्या वैशिष्ट्यांच्या आधारे\",\"केवळ आधुनिक मानवाच्या माहितीचे\",\"कोणत्याही क्रमाने माहिती लिहिणे\"],\"answer\":1,\"explain\":\"तुलना करण्यासाठी विविध टप्प्यांची माहिती क्रमाने आणि वैशिष्ट्यांसह मांडणे आवश्यक आहे.\",\"topic\":\"कृती\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:28'),(21629,26,5,'EVS Part 2','mr','अश्मयुग : दगडाची हत्यारे','[\"अश्मयुग म्हणजे दगडाचा वापर मुख्यतः करणारा काळ\",\"या काळात दगड, हाडे, शंख यांपासून साधी हत्यारे बनवली जात\",\"साधनांची निवड उपलब्धता, वेळ, ऊर्जा आणि परिणामकारकतेवर अवलंबून\",\"दगडाची हत्यारे: दगडी गोट्या, तासणी, घण, छिलक्‍याचे तोडहत्यार\",\"हाडाची हत्यारे: हाडाचा टोचा, शिंगाचे खणते\",\"काठी आणि काटक्या नाशवंत असल्याने क्वचित वापरली जात\",\"पुराश्मयुग, मध्याश्मयुग आणि नवाश्मयुग हे तीन उपकाळ आहेत\",\"