plain\":\"चित्रात आणि मजकुरात दाखवल्याप्रमाणे, एका हाताने आकार देत असताना दुसऱ्या हाताने फळी फिरवली जात आहे.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"26\\/051_102.jpg\"},{\"q\":\"भारतातील कोणत्या भागातील आदिवासी स्त्रिया अलीकडच्या काळापर्यंत भांड्याला आकार देण्यासाठी फिरत्या फळीचा उपयोग करत असत?\",\"options\":[\"दक्षिण भारत\",\"पश्चिम भारत\",\"उत्तर भारत\",\"ईशान्य भारत\"],\"answer\":3,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे ईशान्य भारतातील आदिवासी स्त्रिया फिरत्या फळीचा उपयोग करत असत.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"मातीची भांडी बनवण्याच्या चाकाला बसवलेल्या अणकुचीदार दांड्याला काय म्हणतात?\",\"options\":[\"लोखंडी दांडा\",\"कुंभार दांडा\",\"चाक दांडा\",\"लाकडी खुंटी\"],\"answer\":1,\"explain\":\"चाक ज्या अणकुचीदार दांड्यावर तोलले जाते, त्याला \'कुंभार दांडा\' म्हणतात.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"चाकाचा विकास होण्याचा योग्य क्रम कोणता असावा?\",\"options\":[\"चाक -> फिरती फळी -> हाताने घडवणे\",\"फिरती फळी -> हाताने घडवणे -> चाक\",\"हाताने घडवणे -> फिरती फळी -> चाक\",\"हाताने घडवणे -> चाक -> फिरती फळी\"],\"answer\":2,\"explain\":\"मजकुरावरून समजते की आधी हाताने भांडी घडवली जात, मग फिरती फळी आली आणि त्यातून चाक विकसित झाले.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"कुंभार दांडा या अणकुचीदार दांड्याचा मुख्य उपयोग काय असतो?\",\"options\":[\"माती कापण्यासाठी\",\"चाक त्यावर तोलले जाऊन जोरात फिरण्यासाठी\",\"भांड्याला नक्षी काढण्यासाठी\",\"भांडी उचलून ठेवण्यासाठी\"],\"answer\":1,\"explain\":\"अणकुचीदार दांड्यावर चाक तोलले जाते, ज्यामुळे ते जोरात फिरू शकते.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"मजकुराच्या आधारे, चाकाच्या उपयोगाबाबत कोणते विधान कालक्रमानुसार योग्य वाटते?\",\"options\":[\"वाहनांसाठी चाकाचा उपयोग भांड्यांच्या आधी झाला\",\"भांड्यांसाठी आणि वाहनांसाठी चाकाचा उपयोग एकाच वेळी सुरू झाला\",\"वाहनांसाठी चाकाचा उपयोग भांड्यांसाठीच्या उपयोगानंतर काही काळाने सुरू झाला असावा\",\"वाहनांसाठी चाकाचा उपयोग कधीच झाला नाही\"],\"answer\":2,\"explain\":\"मजकुरात म्हटले आहे की भांड्यांसाठी उपयोग सर्वप्रथम झाला आणि वाहनांसाठी त्यानंतर काही काळाने सुरू झाला असावा.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या कुंभाराकडे आधुनिक चाक नसेल, तर तो मजकुरात वर्णन केलेल्या कोणत्या जुन्या साधनाचा वापर करून भांडे फिरवू शकेल?\",\"options\":[\"स्थिर दगड\",\"फिरती फळी\",\"मोठी टोपली\",\"लाकडी ओंडका\"],\"answer\":1,\"explain\":\"चाक विकसित होण्यापूर्वी फिरती फळी हे भांडे फिरवण्यासाठी वापरले जाणारे साधन होते.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"ताम्रयुगाला \'वेगाने होणाऱ्या बदलांचा काळ\' का म्हटले असावे?\",\"options\":[\"कारण त्या काळात फक्त शेती होत होती\",\"कारण त्या काळात चाकासारखे अत्यंत महत्त्वाचे शोध लागले\",\"कारण लोक एका ठिकाणाहून दुसऱ्या ठिकाणी पळत होते\",\"कारण त्या काळात पाऊस खूप पडत होता\"],\"answer\":1,\"explain\":\"नवनव्या शोधांमुळे (उदा. चाक) जीवनात वेगाने बदल घडून आले, म्हणून तसे म्हटले आहे.\",\"topic\":\"९.२ चाकावर घडवलेली भांडी\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"चाकांवर चालणाऱ्या गाड्या सर्वप्रथम कोठे उपयोगात आणल्या गेल्या?\",\"options\":[\"इजिप्तमध्ये\",\"मेसोपोटेमियात\",\"हडप्पामध्ये\",\"चीनमध्ये\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार, चाकांवर चालणाऱ्या गाड्या सर्वप्रथम मेसोपोटेमियात वापरल्या गेल्या.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"भांड्यांचे उत्पादन मोठ्या प्रमाणावर करणे कशामुळे शक्य झाले?\",\"options\":[\"दगडी हत्यारांच्या वापरामुळे\",\"शेतीच्या शोधामुळे\",\"भांडी चाकावर घडवायला लागल्यामुळे\",\"लोखंडाच्या शोधामुळे\"],\"answer\":2,\"explain\":\"भांडी चाकावर घडवायला लागल्यानंतर त्यांचे उत्पादन मोठ्या प्रमाणावर करणे शक्य झाले.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"कुशल कारागीर गावांमध्ये एके ठिकाणी वस्ती का करू लागले?\",\"options\":[\"कामाच्या सोईसाठी\",\"सुरक्षेसाठी\",\"शेती करण्यासाठी\",\"पाण्याच्या उपलब्धतेसाठी\"],\"answer\":0,\"explain\":\"कुशल कारागीर कामाच्या सोईसाठी गावात एके ठिकाणी वस्ती करू लागले.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"वस्तूंच्या उत्पादन केंद्रांचा खास विभाग कोणत्या गावांमध्ये तयार झाला?\",\"options\":[\"ज्या गावांमध्ये फक्त शेती केली जात होती\",\"ज्या गावांमध्ये कच्चा माल सहज उपलब्ध होता आणि जी गावे व्यापारासाठी सोईची होती\",\"ज्या गावांमध्ये लोकसंख्या कमी होती\",\"ज्या गावांमध्ये फक्त मासेमारी चालत असे\"],\"answer\":1,\"explain\":\"कच्चा माल आणि व्यापाराची सोय असलेल्या गावांमध्येच उत्पादन केंद्रांचे विभाग तयार झाले.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"व्यापारात वाढ झाल्यामुळे खालीलपैकी कोणत्या गोष्टीत बदल होणे गरजेचे होते?\",\"options\":[\"शिकार करण्याच्या पद्धतीत\",\"वाहतुकीच्या पद्धतीत\",\"कपडे विणण्याच्या पद्धतीत\",\"घर बांधणीच्या पद्धतीत\"],\"answer\":1,\"explain\":\"वस्तूंचे उत्पादन आणि व्यापार वाढल्यामुळे वाहतुकीच्या पद्धतीत बदल होणे गरजेचे झाले.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"या काळात कोणत्या प्रकारची भांडी घडवली जाऊ लागली?\",\"options\":[\"फक्त ओबडधोबड भांडी\",\"सुबक आकारांची आणि सुंदर नक्षीची रंगीत भांडी\",\"केवळ काळ्या रंगाची भांडी\",\"दगडाची जड भांडी\"],\"answer\":1,\"explain\":\"चाकाचा वापर सुरू झाल्यावर सुबक आकारांची आणि सुंदर नक्षीची रंगीत भांडी घडवली जाऊ लागली.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"गावांचा विस्तार होण्यामागे खालीलपैकी कोणते कारण महत्त्वाचे ठरले?\",\"options\":[\"केवळ लोकसंख्या वाढल्यामुळे\",\"लोकांनी शेती सोडल्यामुळे\",\"उत्पादन केंद्रांची निर्मिती आणि व्यापारातील वाढीमुळे\",\"जंगले तोडल्यामुळे\"],\"answer\":2,\"explain\":\"उत्पादन केंद्रांची निर्मिती आणि व्यापारातील वाढीमुळे त्या गावांचा विस्तार झाला.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या गावात कच्चा माल मुबलक असेल आणि ते गाव व्यापारासाठी सोईचे असेल, तर तिथे काय घडण्याची शक्यता अधिक होती?\",\"options\":[\"ते गाव ओसाड पडेल\",\"तेथे वस्तूंच्या उत्पादन केंद्रांचा खास विभाग तयार होईल\",\"तेथे लोक फक्त शिकार करतील\",\"ते गाव लहान होत जाईल\"],\"answer\":1,\"explain\":\"अशा गावांमध्ये कुशल कारागिरांच्या वस्तीमुळे उत्पादन केंद्रांचा खास विभाग तयार झाला.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"वाहतुकीसाठी चाकाच्या गाड्यांचा वापर सुरू होण्यामागील मुख्य कारण काय होते?\",\"options\":[\"लोकांना फिरायला आवडत होते\",\"व्यापारात झालेली वाढ आणि मोठ्या प्रमाणावरील उत्पादन\",\"प्राण्यांची संख्या वाढली होती\",\"शेतीसाठी जागा कमी पडत होती\"],\"answer\":1,\"explain\":\"उत्पादन आणि व्यापारात वाढ झाल्यामुळे वाहतुकीसाठी चाकाच्या गाड्यांची गरज निर्माण झाली.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या माहितीनुसार, विकासाचा योग्य क्रम कोणता?\",\"options\":[\"वाहतूक बदल -> व्यापार वाढ -> चाकाचा शोध\",\"चाकावर भांडी घडवणे -> मोठ्या प्रमाणावर उत्पादन -> व्यापारात वाढ\",\"गावांचा विस्तार -> कच्चा माल संपणे -> व्यापार थांबणे\",\"मेसोपोटेमियाचा शोध -> चाकाचा नाश -> व्यापार वाढ\"],\"answer\":1,\"explain\":\"चाकावर भांडी घडवल्यामुळे उत्पादन वाढले आणि त्यातून व्यापारात वाढ झाली.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रातील माहितीनुसार, चाकांवर चालणाऱ्या गाड्यांचा वापर सर्वप्रथम कोणत्या प्रदेशात झाला?\",\"options\":[\"सिंधू संस्कृतीत\",\"मेसोपोटेमियात\",\"नाईल नदीच्या खोऱ्यात\",\"चीनच्या खोऱ्यात\"],\"answer\":1,\"explain\":\"चित्राखालील मजकुरात स्पष्टपणे नमूद केले आहे की या गाड्या सर्वप्रथम मेसोपोटेमियात वापरल्या गेल्या.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"26\\/052_101.jpg\"},{\"q\":\"दिलेल्या चित्रात दाखवलेल्या साधनाचा मानवी जीवनात कोणता मुख्य बदल घडवून आणण्यासाठी उपयोग झाला असेल?\",\"options\":[\"केवळ करमणुकीसाठी\",\"शिकार करण्यासाठी\",\"व्यापार आणि जलद वाहतुकीसाठी\",\"घरे बांधण्यासाठी\"],\"answer\":2,\"explain\":\"चाकाच्या गाडीमुळे मालाची ने-आण करणे सोपे झाले, ज्यामुळे व्यापार आणि वाहतुकीत प्रगती झाली.\",\"topic\":\"९.३ व्यापार आणि वाहतूक\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"26\\/052_101.jpg\"},{\"q\":\"नगरे उदयाला येण्याचे एक महत्त्वाचे कारण खालीलपैकी कोणते आहे?\",\"options\":[\"अग्नीचा शोध\",\"मालाची जलद वाहतूक\",\"शिकार करणे\",\"गुहेत राहणे\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे मालाची जलद वाहतूक आणि उत्पादन केंद्रांमुळे नगरे उदयाला आली.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"भारतीय उपखंडातील सर्वाधिक प्राचीन नागरी संस्कृती कोणती होती?\",\"options\":[\"चीनची संस्कृती\",\"मेसोपोटेमिया संस्कृती\",\"हडप्पा संस्कृती\",\"इजिप्शियन संस्कृती\"],\"answer\":2,\"explain\":\"हडप्पा संस्कृती ही भारतीय उपखंडाची सर्वाधिक प्राचीन नागरी संस्कृती होती असे उताऱ्यात स्पष्ट म्हटले आहे.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सुरुवातीच्या काळात नोंदी ठेवण्यासाठी कशाचा वापर केला जात असे?\",\"options\":[\"कागद आणि पेन्सिल\",\"सांकेतिक खुणा आणि चिन्हे\",\"संगणक\",\"मोबाईल\"],\"answer\":1,\"explain\":\"नोंदी ठेवण्यासाठी आधीच्या काळातही सांकेतिक खुणा आणि चिन्हे यांचा वापर होत होता.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"उत्खननात मोठ्या संख्येने काय मिळाले आहे, ज्यावर सांकेतिक खुणा आहेत?\",\"options\":[\"लोखंडी हत्यारे\",\"कापडी पिशव्या\",\"खापरे\",\"सोन्याची नाणी\"],\"answer\":2,\"explain\":\"सांकेतिक खुणा असलेली खापरे उत्खननात मोठ्या संख्येने मिळतात.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"प्रत्येक संस्कृतीची आपापली लिपी कशी तयार झाली?\",\"options\":[\"सांकेतिक खुणांवर संस्करण केल्यामुळे\",\"परदेशी भाषा शिकल्यामुळे\",\"केवळ चित्रे काढल्यामुळे\",\"राजाच्या आज्ञेमुळे\"],\"answer\":0,\"explain\":\"सांकेतिक खुणा आणि चिन्हे यांमध्ये सुधारणा आणि संस्करण केल्यामुळे लिपी तयार झाली.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वाढलेल्या व्यापाराच्या आणि उत्पादनाच्या नोंदी ठेवणे का आवश्यक झाले?\",\"options\":[\"त्या कायमस्वरूपी राहाव्यात म्हणून\",\"चित्रे काढण्यासाठी\",\"खेळणी बनवण्यासाठी\",\"केवळ मजेसाठी\"],\"answer\":0,\"explain\":\"वाढलेल्या व्यापाराच्या आणि उत्पादनाच्या कायमस्वरूपी नोंदी ठेवणे आवश्यक झाले होते.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या प्राचीन संस्कृतीत व्यापाराचा व्याप खूप वाढला, तर उताऱ्यातील माहितीनुसार काय घडणे अपेक्षित आहे?\",\"options\":[\"व्यापार बंद होईल\",\"लोक शेती सोडून देतील\",\"सांकेतिक खुणांमध्ये सुधारणा केली जाईल\",\"वाहतूक थांबेल\"],\"answer\":2,\"explain\":\"व्यापार आणि नोंदींचा व्याप वाढल्यामुळे आधीपासून वापरात असलेल्या सांकेतिक खुणांमध्ये सुधारणा केल्या गेल्या.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"नगरांमध्ये विविध प्रकारची कामे करणारे लोक एकत्र येण्याचे मुख्य कारण काय होते?\",\"options\":[\"व्यापार आणि उत्पादनाची केंद्रे\",\"मोठी जंगले\",\"नद्यांना आलेला पूर\",\"शिकारीची आवड\"],\"answer\":0,\"explain\":\"व्यापार, जलद वाहतूक आणि उत्पादन केंद्रे यामुळे अनेक प्रकारचे काम करणारे लोक एकत्र आले व नगरे उदयाला आली.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"लिपीच्या विकासाचा योग्य क्रम उताऱ्याच्या आधारे ओळखा:\",\"options\":[\"लिपी -> व्यापार -> चिन्हे\",\"व्यापार वाढणे -> नोंदींची गरज -> लिपी निर्मिती\",\"शेती -> लिपी -> व्यापार\",\"वाहतूक -> खेळणी -> चिन्हे\"],\"answer\":1,\"explain\":\"व्यापार वाढल्यामुळे नोंदींची गरज निर्माण झाली आणि त्यातून सांकेतिक खुणांचे रूपांतर लिपीत झाले.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, \'नगरांचा उदय\' आणि \'लिपीची निर्मिती\' या दोन्ही गोष्टींमधील समान दुवा कोणता?\",\"options\":[\"दगडी हत्यारे\",\"वाढलेला व्यापार आणि उत्पादन\",\"गुहेतील चित्रे\",\"प्राण्यांची शिकार\"],\"answer\":1,\"explain\":\"व्यापार आणि उत्पादन वाढल्यामुळे नगरे उदयाला आली आणि त्याच कारणाने नोंदी ठेवण्यासाठी लिपी विकसित झाली.\",\"topic\":\"९.४ नगरांचा उदय आणि लिपी\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात हडप्पा संस्क