\"},{\"q\":\"शहर की स्वच्छता बनाए रखने के लिए हमें क्या करना चाहिए?\",\"options\":[\"कचरा सड़क पर फेंकना\",\"अनुशासन का पालन करना\",\"शोर मचाना\",\"दीवारें गंदी करना\"],\"answer\":1,\"explain\":\"अनुशासन का पालन करने से स्वच्छता बनी रहती है।\",\"topic\":\"चर्चा और निरीक्षण\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"गाँव और शहर दोनों के लिए अनुशासन क्यों आवश्यक है?\",\"options\":[\"सजा देने के लिए\",\"व्यवस्था और प्रगति के लिए\",\"केवल दिखावे के लिए\",\"भीड़ बढ़ाने के लिए\"],\"answer\":1,\"explain\":\"अनुशासन से ही किसी भी स्थान की व्यवस्था सुचारू रूप से चलती है।\",\"topic\":\"चर्चा और निरीक्षण\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"चित्रों के संदर्भ में \'निरीक्षण\' का क्या अर्थ है?\",\"options\":[\"चित्रों को ध्यानपूर्वक देखना\",\"चित्रों को फाड़ना\",\"चित्रों को छुपाना\",\"चित्रों को फेंकना\"],\"answer\":0,\"explain\":\"निरीक्षण का अर्थ है किसी चीज़ को बारीकी से और ध्यान से देखना।\",\"topic\":\"चर्चा और निरीक्षण\",\"part\":4,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21693,28,5,'Hindi','hi','जीवन','[\"1. जीवन का अर्थ है अपने जीवन को सही दिशा में चलाना।\",\"2. जीवन में तीन प्रमुख चरण होते हैं – बचपन, किशोरावस्था और वयस्कता।\",\"3. हर व्यक्ति का जीवन अनोखा और खास होता है।\",\"4. जीवन में सबसे महत्वपूर्ण है स्वास्थ्य – शरीर और मन दोनों स्वस्थ रहना।\",\"5. जीवन में शिक्षा का बड़ा महत्व है – यह हमें ज्ञान और कौशल देती है।\",\"6. परिवार जीवन का आधार है – माता-पिता, भाई-बहन, दादा-दादी।\",\"7. दोस्ती जीवन को खुशहाल बनाती है।\",\"8. जीवन में लक्ष्य और सपने होना चाहिए।\",\"9. मेहनत और लगन से ही सफलता मिलती है।\",\"10. जीवन में सच्चाई और ईमानदारी का बहुत महत्व है।\",\"11. समय का सही उपयोग करना सीखना चाहिए।\",\"12. जीवन में नयी चीजें सीखते रहना चाहिए।\",\"13. जीवन में संतुलन – काम, खेल और आराम का संतुलन।\",\"14. जीवन में सहानुभूति और दया दिखाना चाहिए।\",\"15. जीवन में समस्याओं का सामना धैर्य से करना चाहिए।\",\"16. जीवन में सकारात्मक सोच रखना ज़रूरी है।\",\"17. जीवन में अपनी क्षमताओं पर विश्वास रखना चाहिए।\",\"18. जीवन में अपने अनुभवों से सीखना चाहिए।\",\"19. जीवन में दूसरों की मदद करना एक गुण है।\",\"20. जीवन का सबसे बड़ा उद्देश्य है खुश रहना और दूसरों को खुश करना।\"]','[{\"q\":\"कविता के अनुसार जीवन किसका नाम है?\",\"options\":[\"सोने का\",\"चलने का\",\"बैठने का\",\"रुकने का\"],\"answer\":1,\"explain\":\"कविता की पहली पंक्ति के अनुसार \'जीवन है चलने का नाम\' ।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"हमें लहराना किससे सीखना चाहिए?\",\"options\":[\"नदी से\",\"आसमान से\",\"सागर से\",\"धरती से\"],\"answer\":2,\"explain\":\"कविता में कहा गया है कि \'लहराना सागर से सीखो\' ।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"हृदय किसके समान विशाल होना चाहिए?\",\"options\":[\"पहाड़ जैसा\",\"आसमान-सा\",\"पेड़ जैसा\",\"मैदान जैसा\"],\"answer\":1,\"explain\":\"कविता के अनुसार हमारा हृदय \'आसमान-सा\' विशाल होना चाहिए।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"धरती की तरह हमें क्या बनना चाहिए?\",\"options\":[\"कठोर\",\"आलसी\",\"सहनशील\",\"चंचल\"],\"answer\":2,\"explain\":\"कविता में \'सहनशील बन धरती जैसे\' बनने की सीख दी गई है।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"मेहनत करने वाले व्यक्ति को क्या प्राप्त होता है?\",\"options\":[\"विश्राम\",\"पद नाम\",\"केवल थकान\",\"उपहार\"],\"answer\":1,\"explain\":\"कविता के अनुसार \'मेहनत कर पाता पद नाम\' ।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"हमारी बोली किसके जैसी मीठी होनी चाहिए?\",\"options\":[\"शहद जैसी\",\"चीनी जैसी\",\"माँ जैसी\",\"कोयल जैसी\"],\"answer\":2,\"explain\":\"कविता में कहा गया है कि \'माँ जैसी हो मीठी बोली\' ।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"मन में कैसे विचार रखने की सीख दी गई है?\",\"options\":[\"सच्चे और उच्च विचार\",\"चतुर विचार\",\"पुराने विचार\",\"स्वार्थी विचार\"],\"answer\":0,\"explain\":\"कविता के अनुसार मन में \'सच्चे उच्च विचार\' होने चाहिए।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दूसरों के प्रति हमारा दृष्टिकोण कैसा होना चाहिए?\",\"options\":[\"सबको छोटा समझो\",\"अपने जैसा सबको जानो\",\"सबको पराया समझो\",\"सबसे दूर रहो\"],\"answer\":1,\"explain\":\"कवि कहते हैं कि हमें \'अपने जैसा सबको जानो\' की भावना रखनी चाहिए।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"\'मिलजुल करते जाना काम\' इस पंक्ति का क्या अर्थ है?\",\"options\":[\"अकेले काम करना\",\"काम न करना\",\"सहयोग के साथ काम करना\",\"दूसरों से काम करवाना\"],\"answer\":2,\"explain\":\"यह पंक्ति एकता और सहयोग के साथ काम करने का संदेश देती है।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"कविता के अनुसार हमें क्या कभी नहीं करना चाहिए?\",\"options\":[\"काम\",\"विश्राम\",\"मेहनत\",\"बातचीत\"],\"answer\":1,\"explain\":\"कविता की पंक्ति है \'करना कभी नहीं विश्राम\' ।\",\"topic\":\"वाणी, विचार और सेवा\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"घड़ी सदा कैसी आवाज़ करती है?\",\"options\":[\"टिक-टिक\",\"छुक-छुक\",\"टप-टप\",\"गड़-गड़\"],\"answer\":0,\"explain\":\"कविता की पहली पंक्ति के अनुसार घड़ी सदा टिक-टिक करती है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"कविता के अनुसार, घड़ी क्या काम नहीं करती?\",\"options\":[\"चलना\",\"रुकना\",\"बजना\",\"टिक-टिक करना\"],\"answer\":1,\"explain\":\"पाठ में लिखा है कि घड़ी \'रुकने का नहीं लेती नाम\' अर्थात् वह रुकती नहीं है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"हमें किसके समान \'नित ऊपर उठना\' चाहिए?\",\"options\":[\"चंद्रमा-सा\",\"तारों-सा\",\"सूरज-सा\",\"बादलों-सा\"],\"answer\":2,\"explain\":\"कविता में \'सूरज-सा नित ऊपर उठना\' का संदेश दिया गया है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'घड़ीनुमा\' शब्द का क्या तात्पर्य है?\",\"options\":[\"घड़ी की तरह\",\"घड़ी के पीछे\",\"घड़ी के नीचे\",\"घड़ी के बिना\"],\"answer\":0,\"explain\":\"\'घड़ीनुमा\' का अर्थ है घड़ी के समान या घड़ी की तरह निरंतर आगे बढ़ना।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'कण-कण में अपनत्व देखकर\' पंक्ति में \'अपनत्व\' का क्या अर्थ है?\",\"options\":[\"दुश्मनी\",\"अपनापन\",\"घृणा\",\"डर\"],\"answer\":1,\"explain\":\"अपनत्व का अर्थ है सबके प्रति अपनापन या प्रेम का भाव रखना।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"कविता में \'नित\' शब्द का क्या अर्थ है?\",\"options\":[\"कभी-कभी\",\"प्रतिदिन\\/हमेशा\",\"साल में एक बार\",\"रात को\"],\"answer\":1,\"explain\":\"\'नित\' का अर्थ है रोज या निरंतर, जैसे सूरज रोज ऊपर उठता है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"यदि कोई व्यक्ति घड़ी के गुण को अपनाता है, तो वह जीवन में क्या करेगा?\",\"options\":[\"आराम करेगा\",\"रुक जाएगा\",\"सदा आगे बढ़ेगा\",\"पीछे हटेगा\"],\"answer\":2,\"explain\":\"कविता कहती है \'घड़ीनुमा सब आगे बढ़ना\', जिसका अर्थ है निरंतर प्रगति करना।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"सबको दिल से प्रणाम करने के लिए कवि ने क्या शर्त बताई है?\",\"options\":[\"पैसे होना\",\"कण-कण में अपनत्व देखना\",\"घड़ी पहनना\",\"सूरज को देखना\"],\"answer\":1,\"explain\":\"पाठ के अनुसार, जब हम कण-कण में अपनत्व देखेंगे, तभी सबको दिल से प्रणाम कर पाएंगे।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'सूरज-सा नित ऊपर उठना\' जीवन के किस सकारात्मक पहलू को दर्शाता है?\",\"options\":[\"आलस्य करना\",\"प्रगति और उन्नति करना\",\"अंधेरा करना\",\"स्थिर रहना\"],\"answer\":1,\"explain\":\"सूरज का ऊपर उठना जीवन में निरंतर उन्नति और विकास का प्रतीक है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"घड़ी के \'टिक-टिक\' करने और न रुकने से हमें क्या मुख्य प्रेरणा मिलती है?\",\"options\":[\"शोर मचाने की\",\"समय के साथ निरंतर चलते रहने की\",\"नाम कमाने की\",\"थक कर बैठ जाने की\"],\"answer\":1,\"explain\":\"घड़ी की टिक-टिक हमें बिना रुके निरंतर अपने मार्ग पर आगे बढ़ने की प्रेरणा देती है।\",\"topic\":\"स्वाध्याय\",\"part\":5,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21694,28,5,'Hindi','hi','भाई-भाई का प्रेम','[\"राष्ट्रीय त्योहार वे खास दिन हैं जिन्हें पूरे देश में मनाया जाता है।\",\"भारत में हर राज्य का अपना खास त्योहार होता है, पर कुछ त्योहार पूरे देश में एक साथ मनाए जाते हैं।\",\"दसवें दिन को ‘दिवाली’ कहा जाता है, यह रोशनी का त्योहार है।\",\"गणेश चतुर्थी में भगवान गणेश की पूजा की जाती है और मिठाई बाँटी जाती है।\",\"होलिका दहन में लालटेन जलाकर बुराई को दूर किया जाता है।\",\"ईद-उल-फ़ितर और ईद-उल-ज़हज़ा मुस्लिमों के दो बड़े त्योहार हैं।\",\"क्रिसमस पर क्रिसमस ट्री सजाया जाता है और उपहार दिए जाते हैं।\",\"गणतंत्र दिवस पर ध्वज फहराया जाता है और देशभक्ति गीत गाए जाते हैं।\",\"राष्ट्रभक्ति के दिन, जैसे स्वतंत्रता दिवस, पर स्कूलों में नाटक और कार्यक्रम होते हैं।\",\"राष्ट्रीय त्योहार हमें एकजुट करते हैं और सांस्कृतिक विविधता को दिखाते हैं।\",\"हर त्योहार के साथ खास व्यंजन और परंपराएँ जुड़ी होती हैं।\",\"त्योहारों के दौरान परिवार और दोस्तों के साथ समय बिताना अच्छा होता है।\",\"त्योहारों के दौरान साफ-सफाई और पर्यावरण का ध्यान रखना ज़रूरी है।\",\"त्योहारों के दौरान दान और मदद करना समाज की भलाई के लिए अच्छा है।\",\"त्योहारों के दौरान हमें अपने देश के इतिहास और संस्कृति को याद रखना चाहिए।\"]','[{\"q\":\"कहानी में बताए गए गाँव का नाम क्या था?\",\"options\":[\"सुंदरपुर\",\"मनोहरपुर\",\"रामपुर\",\"किसानपुर\"],\"answer\":1,\"explain\":\"पाठ की पहली पंक्ति के अनुसार गाँव का नाम मनोहरपुर था।\",\"topic\":\"बड़े भाई का विचार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मनोहरपुर गाँव के अधिकांश लोग खेती क्यों करते थे?\",\"options\":[\"क्योंकि वहाँ पानी बहुत था\",\"क्योंकि वहाँ की मिट्टी बहुत उपजाऊ थी\",\"क्योंकि उन्हें दूसरा काम नहीं आता था\",\"क्योंकि गाँव बहुत सुंदर था\"],\"answer\":1,\"explain\":\"पाठ में उल्लेख है कि गाँव की मिट्टी बहुत उपजाऊ थी, अतः अधिकांश लोग खेती करते थे।\",\"topic\":\"बड़े भाई का विचार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दोनों भाइयों के बीच कैसा संबंध था?\",\"options\":[\"वे हमेशा लड़ते थे\",\"वे एक-दूसरे को पसंद नहीं करते थे\",\"दोनों में बड़ा प्रेम था\",\"वे एक-दूसरे से बात नहीं करते थे\"],\"answer\":2,\"explain\":\"पाठ के अनुसार दोनों भाइयों में बड़ा प्रेम था और वे एक-दूसरे की भलाई सोचते थे।\",\"topic\":\"बड़े भाई का विचार\",\"part\