"bloom\":\"apply\"},{\"q\":\"कवयित्री माय मराठीच्या स्वरूपात कशी मिळून जाते?\",\"options\":[\"केवळ स्वप्नात\",\"क्षणाक्षणाने व कणाकणाने\",\"फक्त गाणे गाऊन\",\"लांबून नमस्कार करून\"],\"answer\":1,\"explain\":\"शेवटच्या ओळीत \'क्षणाक्षणाने कणाकणाने तुझ्या स्वरूपा मिळते मी\' असे स्पष्ट केले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"कवयित्रीला माय मराठीचा संतोष आणि अजून काय हवाहवासे वाटते?\",\"options\":[\"राग\",\"आनंद\",\"खेळ\",\"पैसा\"],\"answer\":0,\"explain\":\"कवितेत \'हवाहवासा मला वाटतो राग तुझा, संतोष तुझा\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'तुझिया अंकी लोळण घेते\' यातील \'अंकी\' या शब्दाचा अर्थ काय?\",\"options\":[\"अंकात (नंबरात)\",\"कुशीत किंवा मांडीवर\",\"पाण्यात\",\"घरात\"],\"answer\":1,\"explain\":\"येथे \'अंकी\' म्हणजे आईच्या (मराठी भाषेच्या) कुशीत किंवा मांडीवर असा अर्थ होतो.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"कवितेनुसार माय मराठीचे काय आहे, जे कवयित्रीला आवडते?\",\"options\":[\"केवळ उंच डोंगर\",\"झरे आणि पाखरे\",\"केवळ समुद्र\",\"फक्त पाऊस\"],\"answer\":1,\"explain\":\"कवितेत \'तुझे झरे अन् तुझी पाखरे\' यांचा उल्लेख मराठीचे वैभव म्हणून केला आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"\'वाट होउनी जळते मी\' या ओळीतून कवयित्रीची कोणती भावना व्यक्त होते?\",\"options\":[\"राग\",\"भीती\",\"समर्पण वृत्ती\",\"कंटाळा\"],\"answer\":2,\"explain\":\"दिव्यातील वातीप्रमाणे स्वतःला जाळून प्रकाश देणे म्हणजेच भाषेसाठी पूर्णपणे समर्पित होणे होय.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"\'माय मराठी\' या गाण्याच्या कवयित्री कोण आहेत?\",\"options\":[\"बहिणाबाई चौधरी\",\"संजीवनी मराठे\",\"शांता शेळके\",\"पद्मा गोळे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील मजकुरानुसार या गाण्याच्या कवयित्री संजीवनी मराठे आहेत.\",\"topic\":\"शिक्षकांसाठी - उपक्रम\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी गाणे कसे म्हणून दाखवावे असे सुचवले आहे?\",\"options\":[\"फक्त वाचून दाखवावे\",\"तालासुरात आणि सभिनय\",\"मोठ्या आवाज