ions\":[\"अनेक दंशांपासून होणारा दाह\",\"गोड पदार्थ देणे\",\"वसाहत सोडून जाणे\",\"माती टाकणे\"],\"answer\":0,\"explain\":\"अनेक मुंग्यांनी दंश केल्यामुळे होणारा दाह शत्रूला दूर पळवतो.\",\"topic\":\"संरक्षण आणि शत्रू\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'मुंग्या नेहमी तत्पर असतात\' यातून त्यांचा कोणता स्वभाव वैशिष्ट्य दिसून येते?\",\"options\":[\"आळशीपणा\",\"संरक्षणाबाबतची सतर्कता\",\"खेळकरपणा\",\"भित्रेपणा\"],\"answer\":1,\"explain\":\"स्वतःचे आणि वसाहतीचे संरक्षण करण्यासाठी त्या नेहमी तयार (सतर्क) असतात.\",\"topic\":\"संरक्षण आणि शत्रू\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"मुंग्यांच्या संरक्षणाच्या पद्धतींमध्ये खालीलपैकी कशाचा समावेश नाही?\",\"options\":[\"विषारी द्रव सोडणे\",\"आम्लाचा फवारा मारणे\",\"शत्रूशी मैत्री करणे\",\"कडकडून चावा घेणे\"],\"answer\":2,\"explain\":\"उताऱ्यात चावा घेणे, द्रव सोडणे आणि आम्ल फवारणे या पद्धती दिल्या आहेत, मैत्री करणे नाही.\",\"topic\":\"संरक्षण आणि शत्रू\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्याच्या आधारे, मुंग्यांच्या संरक्षणाची कोणती पद्धत रासायनिक स्वरूपाची आहे?\",\"options\":[\"सुईसारखा दंश करणे\",\"कडकडून चावा घेणे\",\"विशिष्ट आम्लाचा फवारा सोडणे\",\"गटाने हल्ला करणे\"],\"answer\":2,\"explain\":\"आम्ल (Acid) फवारणे ही एक रासायनिक संरक्षण पद्धत आहे.\",\"topic\":\"संरक्षण आणि शत्रू\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"\'मुंग्यांच्या जगात\' या पाठाचे लेखक कोण आहेत?\",\"options\":[\"प्रकाश किसन नवाळे\",\"व. पु. काळे\",\"साने गुरुजी\",\"वि. वा. शिरवाडकर\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुराच्या शेवटी लेखकाचे नाव \'प्रकाश किसन नवाळे\' असे दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'वसाहत\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"फिरण्याचे ठिकाण\",\"राहण्याचे ठिकाण\",\"खेळण्याचे मैदान\",\"कामाची जागा\"],\"answer\":1,\"explain\":\"शब्दार्थात \'वसाहत\' म्हणजे \'राहण्याचे ठिकाण\' किंवा \'वस्ती\' असे दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मुंग्यांच्या अंगी कोणता गुण असतो, असे लेखकाने म्हटले आहे?\",\"options\":[\"आळशीपणा\",\"बेशिस्तपणा\",\"शिस्तबद्धता\",\"एकलकोंडेपणा\"],\"answer\":2,\"explain\":\"मजकुरात मुंग्यांना \'शिस्तबद्ध\' आणि \'सामाजिक जीवन जगणाऱ्या\' म्हटले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'गंध\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"प्रकाश\",\"रंग\",\"वास\",\"चव\"],\"answer\":2,\"explain\":\"शब्दार्थात \'गंध\' या शब्दाचा अर्थ \'वास\' असा दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"एखाद्या गोष्टीचा शोध घेण्यासाठी कोणता वाक्प्रचार वापरला जातो?\",\"options\":[\"पळ काढणे\",\"माग काढणे\",\"दाह होणे\",\"तत्पर असणे\"],\"answer\":1,\"explain\":\"शब्दार्थात \'माग काढणे\' म्हणजे \'शोध घेणे\' असा अर्थ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"जर एखादी मुंगी कामासाठी नेहमी तयार असेल, तर तिला काय म्हणता येईल?\",\"options\":[\"ती पळ काढणारी आहे\",\"ती तत्पर आहे\",\"तिचा दाह होत आहे\",\"ती गंध घेत आहे\"],\"answer\":1,\"explain\":\"\'तत्पर असणे\' म्हणजे \'तयार असणे\', म्हणून कामासाठी तयार असणाऱ्या मुंगीला तत्पर म्हणता येईल.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"\'हाणून पाडणे\' या वाक्प्रचाराचा अर्थ काय?\",\"options\":[\"यशस्वी करणे\",\"मदत करणे\",\"निष्फळ करणे\",\"तयार असणे\"],\"answer\":2,\"explain\":\"शब्दार्थात \'हाणून पाडणे\' म्हणजे \'निष्फळ करणे\' किंवा \'खोडून काढणे\' असा अर्थ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मुंगी चावल्यानंतर होणाऱ्या \'आगीला\' शब्दार्थात काय म्हटले आहे?\",\"options\":[\"गंध\",\"वसाहत\",\"सुगावा\",\"दाह\"],\"answer\":3,\"explain\":\"शब्दार्थात \'दाह होणे\' म्हणजे \'आग होणे\' असे स्पष्ट केले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मुंग्यांच्या \'सामाजिक\' जीवनावरून आपल्याला काय शिकता येईल?\",\"options\":[\"एकटे राहणे\",\"मिळून-मिसळून राहणे\",\"कामाला उशीर करणे\",\"दुसऱ्याला त्रास देणे\"],\"answer\":1,\"explain\":\"सामाजिक जीवन जगणे म्हणजे समूहात मिळून-मिसळून राहणे, जे मुंग्यांकडून शिकण्यासारखे आहे.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"\'उद्योगशील\' या शब्दाचा विरुद्धार्थी अर्थ खालीलपैकी कोणत्या वागण्यातून दिसतो?\",\"options\":[\"सतत काम करणे\",\"कामात मग्न राहणे\",\"आळस करून बसून राहणे\",\"नवनवीन उद्योग करणे\"],\"answer\":2,\"explain\":\"\'उद्योगशील\' म्हणजे \'उद्योगप्रिय\' (काम करणारा), त्यामुळे आळस करून बसणे हा त्याच्या विरुद्ध अर्थ होतो.\",\"topic\":\"स्वाध्याय\",\"part\":8,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21714,29,5,'Marathi','mr','माहेर (कविता)','[\"1. काव्याचे नाव ‘माहेर (कविता) सदाशिव माळी’ आहे.\",\"2. कवितेत ‘माहेर’ नदीचा उल्लेख आहे.\",\"3. ‘माहेर’ नदीच्या काठावर चिकणमाती (चिकट माती) आढळते.\",\"4. चिकणमातीचा वापर ओटा (काठी) बांधण्यासाठी केला जातो.\",\"5. ओटा म्हणजे लाकडाचा किंवा लांब काठीचा तुकडा.\",\"6. ‘सोजी’ म्हणजे ओलसर गहू दळून चाळलेले पीठ (रवा).\",\"7. सोजी लाडू (गोडी) बनवण्यासाठी वापरले जाते.\",\"8. लाडू म्हणजे गोड पदार्थ, ज्याला सोजीने बांधले जाते.\",\"9. सोजी लाडू घेऊन ‘माहेर’ नदीकाठीच्या घरात जाते.\",\"10. ‘नंदी’ म्हणजे सजवलेला बैल, ज्याला ‘नदी’ पासून वेगळे ओळखले जाते.\",\"11. ‘शेला’ म्हणजे अंगावर पांघरायचे भरजरी वस्त्र.\",\"12. ‘भाऊराया’ म्हणजे भाऊ, ज्याला भेटण्यासाठी गाडी आणली जाते.\",\"13. ‘दारी रथ’ म्हणजे रथ (गाडी) जी दारी (दरी) आणते.\",\"14. कवितेतील स्त्री ‘सोजी’ च्या कल्पना क्रमाने मांडतात: ओटा बांधणे, लाडू बनवणे, नदीकाठी जाणे.\",\"15. ‘चिकणमाती’ ची वैशिष्ट्ये: चिकटपणा, ओलावा, मऊपणा.\",\"16. ‘सोजी’ चा उपयोग: गहू दळून चाळलेले पीठ, लाडू बनवण्यासाठी.\",\"17. ‘माहेर’ नदीच्या काठावर मातीची विविधता असते.\",\"18. ‘नदी’ आणि ‘नंदी’ या शब्दांतील ‘अनुस्वार’ चा फरक.\",\"19. ‘सुधीर’ आणि ‘सुमन’ या भावंडांच्या कथेत सर्वनामांचा वापर.\",\"20. ‘नागपंचमी’ आणि ‘नवरात्री’ गाण्यांचा संग्रह करण्याची क्रिया.\",\"21. ‘नंदी’ आणि ‘नदी’ या शब्दांच्या जोड्या लिहिणे.\",\"22. ‘चिकणमाती’ पासून खेळणी किंवा किल्ला बनवणे.\",\"23. ‘सोजी’ लाडू घेऊन ‘माहेर’ नदीकाठी जाणे.\",\"24. ‘भाऊराया’ ला भेटण्यासाठी ‘दारी रथ’ आणणे.\",\"25. ‘माहेर’ नदीकाठीच्या मातीचा प्रकार ‘चिकणमाती’ आहे.\"]','[{\"q\":\"कवयित्रीने कोणत्या नदीकाठच्या चिकण मातीचा उल्लेख केला आहे?\",\"options\":[\"गोदावरी\",\"तापी\",\"कृष्णा\",\"नर्मदा\"],\"answer\":1,\"explain\":\"कवितेच्या पहिल्या ओळीत \'तापीकाठची चिकण माती\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"चिकण मातीपासून काय बांधायचे आहे?\",\"options\":[\"घर\",\"भिंत\",\"ओटा\",\"विहीर\"],\"answer\":2,\"explain\":\"कवितेनुसार चिकण मातीपासून ओटा बांधायचा आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"ओटा चांगला असेल, तर त्यावर काय मांडायचे आहे?\",\"options\":[\"जाते\",\"चुली\",\"भांडी\",\"खेळणी\"],\"answer\":0,\"explain\":\"कवितेत \'असा ओटा चांगला तर, जाते तरी मांडू ग बाई\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जात्यावर काय दळायचे आहे?\",\"options\":[\"गहू\",\"पीठ\",\"सोजि\",\"डाळ\"],\"answer\":2,\"explain\":\"जात्यावर सोजि दळण्याचा उल्लेख कवितेत आला आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सोजि दळल्यानंतर त्याचे काय बनवायचे आहे?\",\"options\":[\"करंज्या\",\"लाडू\",\"पुरणपोळी\",\"मोदक\"],\"answer\":1,\"explain\":\"सोजि चांगली असेल तर लाडू बांधायचे आहेत.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"तयार केलेले लाडू कशाच्या पदरी बांधायचे आहेत?\",\"options\":[\"साडीच्या\",\"रुमालाच्या\",\"शेल्याच्या\",\"पिशवीच्या\"],\"answer\":2,\"explain\":\"कवितेत लाडू शेल्याच्या पदरी बांधण्याचा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दारी रथ कोण घेऊन येणार आहे?\",\"options\":[\"वडील\",\"भाऊराया\",\"नंदी\",\"मित्र\"],\"answer\":1,\"explain\":\"भाऊराया दारी रथ आणील असे कवितेत सांगितले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"रथाला काय जुंपायचे आहे?\",\"options\":[\"घोडा\",\"बैल\",\"नंदी\",\"उंट\"],\"answer\":2,\"explain\":\"रथाला नंदी जुंपण्याचा उल्लेख कवितेत आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"नंदी जुंपलेल्या रथात बसून कोठे जायचे आहे?\",\"options\":[\"बाजारात\",\"माहेराला\",\"सासरी\",\"बागेत\"],\"answer\":1,\"explain\":\"नंदी जुंपलेल्या रथातून माहेराला जाण्याची इच्छा व्यक्त केली आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"माहेराला गेल्यावर काय करायचे आहे?\",\"options\":[\"काम\",\"अभ्यास\",\"विश्रांती\",\"धिंगामस्ती\"],\"answer\":3,\"explain\":\"कवितेच्या शेवटच्या ओळीत \'माहेर चांगलं तर, धिंगामस्ती करू ग बाई\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"\'चिकण माती\' म्हणजे काय?\",\"options\":[\"कोरडी माती\",\"वाळू\",\"चिकटपणा असलेली माती\",\"लाल माती\"],\"answer\":2,\"explain\":\"पाठातील शब्दार्थांनुसार चिकण माती म्हणजे चिकटपणा असलेली माती होय.\",\"topic\":\"खेळूया शब्दशक्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'शेला\' या शब्दाचा योग्य अर्थ निवडा.\",\"options\":[\"साधी ओढणी\",\"अंगावर पांघरायचे भरजरी वस्त्र\",\"सुती कापड\",\"रेशमी धागा\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या शब्दार्थांनुसार शेला म्हणजे अंगावर पांघरायचे भरजरी वस्त्र.\",\"topic\":\"खेळूया शब्दशक्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"धान्य दळण्याचे दगडाचे साधन कोणते?\",\"options\":[\"खलबत्ता\",\"पाटा\",\"वरवंटा\",\"जातं\"],\"answer\":3,\"explain\":\"पाठात दिलेल्या माहितीनुसार जातं हे धान्य दळण्याचे दगडाचे साधन आहे.\",\"topic\":\"खेळूया शब्दशक्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'सोजि\' तयार करण्यासाठी गहू कसा असावा लागतो?\",\"options\":[\"कोरडा\",\"भाजलेला\",\"ओलसर\",\"भिजवलेला\"],\"answer\":2,\"explain\":\"सोजि म्हणजे ओलसर गहू दळून चाळलेलं पीठ किंवा रवा होय.\",\"topic\":\"खेळूया शब्दशक्ती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'नंदी\' या शब्दातील \'न\' वरील अनुस्वार काढला तर कोणता शब्द तयार होतो?\",\"options\":[\"नदी\",\"नादी\",\"नद\",\"नंदी\"],\"answer\":0,\"explain\":\"नंदी या शब्दातील अनुस्वार काढल्यास \'नदी\' हा शब्द तयार होतो.\",\"topic\":\"खेळूया शब्दशक्ती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'सजवलेला थोरला बैल\' याला काय म्हणतात?\",\"options\":[\"घोडा\",\"नंदी\",\"गाय\",\"वासरू\"],\"answer\":1,\"explain\":\"पाठातील शब्दार्थांनुसार सजवलेल्या थोरल्या बैलाला नंदी म्हणतात.\",\"topic\":\"खेळूया श