"understand\"},{\"q\":\"जनाईला समोरून काय आल्याचा भास झाला?\",\"options\":[\"गाडी\",\"विमान\",\"सायकल\",\"बैलगाडी\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की, वाकलेली मान वर करून बघताना तिला विमान समोरून आल्याचा भास झाला.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"सापाचे वर्णन उताऱ्यात कसे केले आहे?\",\"options\":[\"पांढऱ्या ठिपक्यांची तुळी\",\"हिरव्या रंगाचा नाग\",\"काळ्या ठिपक्यांची चार वाव तुळी\",\"लाल डोळ्यांचा साप\"],\"answer\":2,\"explain\":\"सापाचे वर्णन \'काळ्या ठिपक्यांची एक चार वाव तुळी\' असे केले आहे.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"सापाला पाहिल्यावर जनाईने कोणाचे नाव घेतले?\",\"options\":[\"विठ्ठलाचे\",\"आईचे\",\"अंबाबाईचे\",\"देवाचे\"],\"answer\":2,\"explain\":\"सापाला पाहिल्यावर जनाई \'अंबाबाई, साप!\' असे ओरडली.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'वारं सुटावं तशी पळत सुटली\' या वाक्यातून काय समजते?\",\"options\":[\"जनाई वाऱ्यासोबत खेळत होती\",\"जनाई खूप वेगाने पळाली\",\"जनाई हळूहळू चालत होती\",\"वारा खूप सुटला होता\"],\"answer\":1,\"explain\":\"वाऱ्याच्या वेगाने पळणे म्हणजे अतिशय वेगाने धावणे.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"साप जवळ येत असताना जमिनीवर काय बदल होत होते?\",\"options\":[\"जमीन फाटत होती\",\"जमिनीवर पाणी येत होते\",\"भुईमुगाच्या आऱ्या वर उचकत होत्या\",\"जमीन थंड पडली होती\"],\"answer\":2,\"explain\":\"साप येत असताना भुईमुगाच्या आऱ्या वर उचकत होत्या आणि जमीन हादरत होती.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"वस्तीवर पोहोचल्यावर जनाईची शारीरिक स्थिती कशी होती?\",\"options\":[\"ती उत्साहात होती\",\"अंग घामाने थबथबलं होतं आणि हातपाय थरथरत होते\",\"ती गाणी गात होती\",\"तिला खूप भूक लागली होती\"],\"answer\":1,\"explain\":\"भीतीमुळे जनाईचे अंग घामाने थबथबले होते आणि हातपाय थरथरत होते.\",\"topic\":\"सापाचा थरार\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\'वाचाच गेल्यागत झाली होती\' या ओळीचा अर्थ काय?\",\"options\":[\"जनाईला बोलता येत नव्हते\",\"जनाई खूप बोलत