\":7,\"bloom\":\"understand\"},{\"q\":\"कारखान्याच्या अधिकाऱ्यांनी कोणती जबाबदारी घेण्याचे आश्वासन दिले?\",\"options\":[\"नवीन गाडी घेण्याची\",\"दवाखान्याच्या खर्चाची\",\"मुलांच्या शिक्षणाची\",\"बैल खरेदी करण्याची\"],\"answer\":1,\"explain\":\"अधिकाऱ्यांनी दवाखान्याच्या खर्चाचे आणि त्याच्या कामाचे पाहू असे आश्वासन दिले.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"गाडीवान कोणत्या गोष्टीमुळे अधिक काळजीत किंवा \'आंधळा\' झाला होता?\",\"options\":[\"अंधारामुळे\",\"कर्ज आणि उसनवारीमुळे\",\"रस्त्यामुळे\",\"आजारपणामुळे\"],\"answer\":1,\"explain\":\"उताऱ्यात \'कर्ज, उसनवारीने आंधळेपण आलेल्या\' असा उल्लेख गाडीवानासाठी केला आहे.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"गाडीवानाला हुंदके का आवरेनात?\",\"options\":[\"तो खूप जखमी होता म्हणून\",\"त्याची गाडी फुटली होती म्हणून\",\"अधिकाऱ्यांच्या आश्वासनाने भारावून गेल्यामुळे\",\"त्याला खूप भूक लागली होती म्हणून\"],\"answer\":2,\"explain\":\"अधिकाऱ्यांनी दिलेल्या मदतीच्या आश्वासनामुळे भारावून जाऊन त्याला हुंदके आवरेनात.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'अश्रूंना वाट मोकळी करून देणे\' या वाक्प्रचाराचा उताऱ्यातील संदर्भाप्रमाणे अर्थ काय?\",\"options\":[\"डोळे पुसणे\",\"खूप रडणे किंवा भावना व्यक्त करणे\",\"पाणी पिणे\",\"दुसऱ्याला रडवणे\"],\"answer\":1,\"explain\":\"गाडीवानाने कृतज्ञतेपोटी आणि भावनावेगात येऊन रडून आपल्या भावना व्यक्त केल्या.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"अपघाताच्या ठिकाणी इतर गाडीवानांनी केलेली पहिली मदत कोणती होती?\",\"options\":[\"जेवण देणे\",\"पलटी झालेली गाडी बैलांसह मार्गी लावणे\",\"पैसे गोळा करणे\",\"गाणी गाणे\"],\"answer\":1,\"explain\":\"गाडीवानांनी सर्वात आधी पलटी झालेली गाडी बैलांसह हळूहळू मार्गी लावली.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"कारखान्याच्या अधिकाऱ्यांच्या वागण्यातून त्यांचा कोणता गुण दिसून येतो?\",\"options\":[\"कठोरपणा\",\"बेजबाबदारपणा\",\"संवेदनशीलता आणि मदतवृत्ती\",\"रागीटपणा\"],\"answer\":2,\"explain\":\"जखमी कुटुंबाला धीर देणे आणि खर्चाची जबाबदारी उचलणे यातून त्यांची मदतवृत्ती दिसते.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"शिक्षक आणि अधिकारी यांनी गाडीवानाला दिलेल्या मदतीचे स्वरूप कसे होते?\",\"options\":[\"केवळ आर्थिक\",\"केवळ शाब्दिक\",\"मानसिक आधार आणि आर्थिक मदत\",\"केवळ कायदेशीर\"],\"answer\":2,\"explain\":\"शिक्षकांनी मानसिक आधार दिला, तर अधिकाऱ्यांनी आर्थिक आणि कामाचा आधार दिला.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"या प्रसंगातून आपल्याला काय शिकायला मिळते?\",\"options\":[\"संकटाच्या वेळी एकमेकांना मदत करावी\",\"गाडी वेगाने चालवावी\",\"कर्ज घेऊ नये\",\"कोणाशीही बोलू नये\"],\"answer\":0,\"explain\":\"कठीण समयी सर्वजण मदतीला धावून आले, यातून माणुसकी आणि सहकार्याची शिकवण मिळते.\",\"topic\":\"दिलासा आणि मदत\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"\'मुंडसे\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"डोक्याला बांधायचे पागोटे\",\"हाताला बांधायचा रुमाल\",\"खांद्यावरचे उपरणे\",\"पायातील मोजे\"],\"answer\":0,\"explain\":\"उताऱ्यातील शब्दार्थानुसार, मुंडसे म्हणजे डोक्याला बांधायचे पागोटे होय.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'दोरखंड\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"बारीक धागा\",\"जाड दोर\",\"लोखंडी साखळी\",\"कापडी पट्टी\"],\"answer\":1,\"explain\":\"दिलेल्या शब्दार्थानुसार दोरखंड म्हणजे जाड दोर.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"अपघाताची सविस्तर बातमी कोणी प्रसिद्ध केली?\",\"options\":[\"विद्यार्थ्यांनी\",\"शिक्षकांनी\",\"दोन पत्रकारांनी\",\"मान्यवरांनी\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केले आहे की, त्या दोन पत्रकारांनी अपघाताची सविस्तर बातमी प्रसिद्ध केली.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'काळजात धस्स होणे\' या वाक्प्रचाराचा अर्थ ओळखा.\",\"options\":[\"खूप आनंद होणे\",\"खूप घाबरणे\",\"खूप राग येणे\",\"खूप भूक लागणे\"],\"answer\":1,\"explain\":\"शब्दार्थानुसार काळजात धस्स होणे म्हणजे खूप घाबरणे.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"विद्यार्थ्यांनी केलेल्या कोणत्या कामाचे सगळ्यांनी कौतुक केले?\",\"options\":[\"अभ्यास\",\"खेळ\",\"आपत्ती व्यवस्थापन\",\"गायन\"],\"answer\":2,\"explain\":\"विद्यार्थ्यांनी केलेल्या आपत्ती व्यवस्थापनबद्दल सगळ्यांनी त्यांचे कौतुक केले.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'हायसे वाटणे\' या शब्दाचा वापर खालीलपैकी कोणत्या प्रसंगी केला जाईल?\",\"options\":[\"जेव्हा एखादी वस्तू हरवते\",\"जेव्हा संकटातून सुटल्यासारखे वाटते\",\"जेव्हा खूप जोरात पाऊस येतो\",\"जेव्हा कोणीतरी रागावते\"],\"answer\":1,\"explain\":\"हायसे वाटणे म्हणजे समाधान वाटणे किंवा संकटातून सुटल्यासारखे वाटणे.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"एखादी व्यक्ती भीतीने खूप घाबरली असेल, तर उताऱ्यातील कोणता शब्द तिच्यासाठी वापरता येईल?\",\"options\":[\"मुंडसे\",\"भेदरणे\",\"दोरखंड\",\"पलटी होणे\"],\"answer\":1,\"explain\":\"भेदरणे या शब्दाचा अर्थ भीतीने घाबरणे असा होतो.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"\'हालचाल न होता पडून राहणे\' या स्थितीसाठी उताऱ्यात कोणता शब्द आला आहे?\",\"options\":[\"व्याकूळ होणे\",\"निष्पन्न पडणे\",\"पलटी होणे\",\"हायसे वाटणे\"],\"answer\":1,\"explain\":\"निष्पन्न पडणे या शब्दाचा अर्थ हालचाल न होता पडून राहणे असा दिला आहे.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"\'व्याकूळ होणे\' आणि \'कासावीस होणे\' यांच्यातील संबंध ओळखा.\",\"options\":[\"ते विरुद्धार्थी शब्द आहेत\",\"ते एकाच अर्थाचे शब्द आहेत\",\"त्यांचा अर्थाशी संबंध नाही\",\"ते चुकीचे शब्द आहेत\"],\"answer\":1,\"explain\":\"शब्दार्थानुसार व्याकूळ होणे म्हणजेच कासावीस होणे, हे दोन्ही समानार्थी शब्द आहेत.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"मान्यवरांनी शाळेला अभिनंदनाचे पत्र का पाठवले असावे?\",\"options\":[\"शाळेचा निकाल चांगला लागला म्हणून\",\"शाळेची इमारत मोठी होती म्हणून\",\"विद्यार्थ्यांनी केलेल्या आपत्ती व्यवस्थापनामुळे\",\"शाळेत नवीन शिक्षक आले म्हणून\"],\"answer\":2,\"explain\":\"विद्यार्थ्यांनी केलेल्या आपत्ती व्यवस्थापनाचे कौतुक म्हणून मान्यवरांनी अभिनंदनाचे पत्र पाठवले.\",\"topic\":\"शब्दार्थ\",\"part\":9,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21720,29,5,'Marathi','mr','माळीण गाव : एक घटना','[\"माळीण गाव हे पुणे जिल्ह्यातील डोंगराळ भागात वसलेले एक छोटे गाव आहे.\",\"३० जुलै २०१४ रोजी प्रचंड पावसामुळे भूस्खलन झाले आणि गाव गाडले गेले.\",\"या भूस्खलनात मानवी हानी झाली आणि संपूर्ण देशात धक्का बसला.\",\"भूस्खलनानंतर पुनर्वसनाची प्रक्रिया सुरू करण्यात आली.\",\"भूस्खलनामुळे ढिगाऱ्याखाली अनेक लोक अडकले होते.\",\"सुरक्षा दल आणि स्वयंसेवकांनी शोध व बचाव कार्य केले.\",\"माळीण गावात साधारण १०० कुटुंबे राहत होती.\",\"भूस्खलनाची सूचना स्थानिक प्रशासनाने दिली.\",\"मदतीची घोषणा राज्य सरकारने केली.\",\"मदत विविध स्वरूपात दिली – अन्न, पाणी, वैद्यकीय सेवा.\",\"भूस्खलनामुळे पाणीपुरवठा व रस्ते बंद झाले.\",\"भूस्खलनाचे मुख्य कारण पावसाचे तीव्र प्रमाण आणि भू-तलावरील अस्थिरता होती.\",\"भूस्खलनानंतर शोध कार्यात अडथळे – भूभागाची कठीणता, पाण्याचा प्रवाह, वीजपुरवठा नसणे.\",\"भूस्खलनानंतरच्या पुनर्वसनात तात्पुरती निवास व्यवस्था व स्वच्छता व्यवस्था आवश्यक होती.\",\"भूस्खलनाची घटना आपत्ती व्यवस्थापनाचे महत्त्व दाखवते.\",\"आपत्ती व्यवस्थापनात पूर्वसूचना, बचाव, पुनर्वसन व पुनर्निर्माण हे टप्पे असतात.\",\"नासा (NASA) ही अमेरिकेची अवकाश संस्था आहे, ती अवकाश संशोधन व तंत्रज्ञानावर काम करते.\",\"आपत्तीच्या वेळी मदत विविध स्वरूपात – वैद्यकीय, अन्न, पाणी, तात्पुरती निवास व्यवस्था, मनोवैज्ञानिक मदत.\",\"आपत्तीच्या वेळी स्थानिक प्रशासन व स्वयंसेवकांची भूमिका महत्त्वाची असते.\",\"आपत्ती नंतरच्या काळात गावाची पुनर्रचना व पायाभूत सुविधा सुधारण्यासाठी योजना आखली जाते.\",\"आपत्ती व्यवस्थापनात सर्व स्तरांवर सहकार्य आवश्यक असते.\",\"आपत्तीची तयारी व प्रतिबंधासाठी शिक्षण व जागरूकता महत्त्वाची असते.\",\"आपत्ती नंतरच्या काळात मानसिक आरोग्याची काळजी घेणे गरजेचे असते.\",\"आपत्ती व्यवस्थापनात तंत्रज्ञानाचा वापर – ड्रोन, GIS, मोबाइल अॅप्स यांचा उपयोग होतो.\",\"आपत्तीच्या वेळी माहितीची देवाणघेवाण व संवाद महत्त्वाचा असतो.\"]','[{\"q\":\"माळीण गावची दुर्घटना कोणत्या तारखेला घडली?\",\"options\":[\"३० जुलै २०१४\",\"१५ ऑगस्ट २०१४\",\"२६ जानेवारी २०१४\",\"३० जून २०१४\"],\"answer\":0,\"explain\":\"उताऱ्यात दिलेल्या माहितीनुसार, ३० जुलै २०१४ रोजी ही घटना घडली.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"माळीण गाव कोणत्या जिल्ह्यात वसलेले आहे?\",\"options\":[\"सातारा\",\"पुणे\",\"नाशिक\",\"रायगड\"],\"answer\":1,\"explain\":\"उताऱ्याच्या पहिल्या ओळीत नमूद केल्याप्रमाणे माळीण गाव पुणे जिल्ह्यात आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"माळीण गाव गाडले जाण्याचे मुख्य कारण काय होते?\",\"options\":[\"भूकंप\",\"पूर\",\"प्रचंड पावसामुळे दरड कोसळणे\",\"वादळ\"],\"answer\":2,\"explain\":\"प्रचंड पावसामुळे दरड कोसळून हे गाव गाडले गेले असे उताऱ्यात म्हटले आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'हसरे बाळ\' या शब्दसमूहात \'हसरे\' हा शब्द काय आहे?\",\"options\":[\"विशेषण\",\"नाम\",\"क्रियापद\",\"सर्वनाम\"],\"answer\":0,\"explain\":\"\'हसरे\' हा शब्द बाळाबद्दल विशेष माहिती सांगतो, म्हणून ते विशेषण आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पाठ्यपुस्तकातील उदाहरणांनुसार \'हत्ती\' या नामासाठी कोणते विशेषण वापरले आहे?\",\"options\":[\"पाळीव\",\"मोठा\",\"शक्तिशाली\",\"जंगली\"],\"answer\":3,\"explain\":\"उताऱ्यातील विशेषणांच्या यादीत \'जंगली हत्ती\' असा उल्लेख आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\'लालभडक\' हे विशेषण कोणत्या फुलासाठी वापरले आहे?\",\"options\":[\"गुलाब\",\"जास्वंद\",\"कमळ\",\"चाफा\"],\"answer\":1,\"explain\":\"उताऱ्यात \'लालभडक जास्वंद\' असा शब्दसमूह दिला आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\'तेजस्वी\' हे विशेषण खालीलपैकी कोणाचे वर्णन करण्यासाठी वापरले आहे?\",\"options\":[\"चंद्र\",\"तारा\",\"सूर्य\",\"दिवा\"],\"answer\":2,\"explain\":\"उताऱ्यात \'तेजस्वी सूर्य\' असे उदाहरण दिले आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'गोड पेरू\' या उदाहरणावरून \'विशेषण\' म्हणजे काय हे कसे समजते?\",\"options\":[\"पेरू हे फळ आहे म्हणून\",\"पेरू कसा आहे हे \'गोड\' या शब्दावरून समजते म्हणून\",\"पेरू खातात म्हणून\",\"पेरू झाडाला लागतो म्हणून\"],\"answer\":1,\"explain\":\"नामाबद्दल विशेष माहिती सांगणाऱ्या शब्दाला विशेषण म्हणतात, येथे \'गोड\' ही माहिती आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी चव (taste) दर्शवणारे विशेषण कोणते?\",\"options\":[\"उंच\",\"गोड\",\"ताजे\",\"सुंदर\"],\"answer\":1,\"explain\":\"दिलेल्या पर्यायांपैकी \'गोड\' हा शब्द चवीचे वर्णन करतो.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात \'डोंगर\' साठी \'उंच\' हे विशेषण आहे, तर \'नदी\' साठी कोणते विशेषण दिले आहे?\",\"options\":[\"खोल\",\"निळी\",\"लांब\",\"थंड\"],\"answer\":2,\"explain\":\"उताऱ्यातील शब्दसमूहात \'लांब नदी\' असा उल्लेख आहे.\",\"topic\":\"आपण समजून घेऊया - विशेषण\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"नामाबद्दल विशेष माहिती सांगणाऱ्या शब्दांना काय म्हणतात?\",\"options\":[\"नाम\",\"विशेषण\",\"क्रियापद\",\"सर्वनाम\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्ट दिले आहे की नामाबद्दल विशेष माहिती सांगणाऱ्या शब्दांना विशेषण म्हणतात.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'जंगली हत्ती\' या शब्दसमूहात \'जंगली\' हा शब्द काय आहे?\",\"options\":[\"नाम\",\"विशेषण\",\"क्रिया\",\"आकार\"],\"answer\":1,\"explain\":\"हत्ती या नामाबद्दल \'जंगली\' हा शब्द विशेष माहिती देतो, म्हणून ते विशेषण आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मजकुरात \'जास्वंद\' या फुलासाठी कोणते विशेषण वापरले आहे?\",\"options\":[\"सुंदर\",\"ताजे\",\"लालभडक\",\"तेजस्वी\"],\"answer\":2,\"explain\":\"दिलेल्या मजकुरात जास्वंदासाठी \'लालभडक\' हे विशेषण वापरले आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"कलिंगडाचा आकार, रंग आणि चव सांगणारे शब्द म्हणजे काय असतात?\",\"options\":[\"नावे\",\"क्रियापदे\",\"विशेषणे\",\"वाक्ये\"],\"answer\":2,\"explain\":\"कलिंगडाची वैशिष्ट्ये सांगणारे शब्द त्याची विशेषणे असतात असे मजकुरात म्हटले आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विशेषण \'सूर्य\' या नामासाठी वापरले आहे?\",\"options\":[\"गोड\",\"तेजस्वी\",\"लांब\",\"उंच\"],\"answer\":1,\"explain\":\"मजकुरात सूर्यासाठी \'तेजस्वी\' हा शब्द विशेष माहिती सांगणारा शब्द म्हणून आला आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'ताजे फूल\' या शब्दसमूहात \'ताजे\' हे विशेषण कोणत्या नामाबद्दल माहिती देते?\",\"options\":[\"सूर्य\",\"जास्वंद\",\"फूल\",\"पेरू\"],\"answer\":2,\"explain\":\"\'ताजे\' हे विशेषण \'फूल\' या नामाबद्दल अधिक माहिती सांगते.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता शब्द \'विशेषण\' नाही?\",\"options\":[\"हसरे\",\"डोंगर\",\"सुंदर\",\"गोड\"],\"answer\":1,\"explain\":\"डोंगर हे एक नाव (नाम) आहे, विशेषण नाही.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"मजकुरात \'नदी\' या नामासाठी कोणते विशेषण दिले आहे?\",\"options\":[\"उंच\",\"लांब\",\"ताजी\",\"जंगली\"],\"answer\":1,\"explain\":\"नदी या नामासाठी \'लांब\' हे विशेषण मजकुरात वापरले आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"कलिंगडाची चव कशी? या प्रश्नाचे उत्तर व्याकरणदृष्ट्या काय असेल?\",\"options\":[\"नाम\",\"विशेषण\",\"सर्वनाम\",\"क्रियापद\"],\"answer\":1,\"explain\":\"चव सांगणारा शब्द कलिंगडाबद्दल विशेष माहिती देतो, म्हणून ते विशेषण असते.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"विशेषण ओळखण्यासाठी शिक्षकांनी कोणते उदाहरण दिले आहे?\",\"options\":[\"पेरूचे\",\"हत्तीचे\",\"कलिंगडाचे\",\"सूर्याचे\"],\"answer\":2,\"explain\":\"मजकुरात शिक्षकांसाठी दिलेल्या सूचनेत कलिंगडाचे उदाहरण दिले आहे.\",\"topic\":\"विशेषण - कृती\",\"part\":4,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21721,29,5,'Marathi','mr','सण एक दिन! (कविता)','[\"सण एक दिन! ही कविता बैलांच्या सणाबद्दल आहे.\",\"बैलांच्या कपाळावर बाशिंग, शिंगांना गोंडे बांधले जातात.\",\"झुली म्हणजे लहान आरसे लावून केलेली सजावट.\",\"बैलांच्या गळ्यात घुंगरांच्या माळा असतात.\",\"आसूड म्हणजे चाबूक, ज्याने बैलाला चालवतात.\",\"वेसण म्हणजे नाकातून घातलेली दोरी, ज्याने बैलाला ओळखता येते.\",\"बैलांना रंगवून, शिंगांना गोंडे लावून, झुली लावून सजवतात.\",\"सणाच्या दिवशी बैलांना मिरवून नेतात, गाणे व वाद्य वाजवतात.\",\"सण एक दिवसच असतो, वर्षभर बैलांना काम करावे लागते.\",\"बैलपोळा सणात बैलांना विविध रंग व सजावट लावली जाते.\",\"बैलपोळा सणात बैलांना वेसण घातली जाते.\",\"सणाच्या दिवशी बैलांना चाबूक (आसूड) दिले जाते.\",\"बैलपोळा सणात बैलांना गोंडे व शिंगे लावली जातात.\",\"बैलांना गळ्यात घुंगरांची माळ लावली जाते.\",\"सणाच्या दिवशी बैलांना झुली लावली जाते.\",\"बैलपोळा सणात बैलांना विविध प्रकारचे नावे दिली जातात.\",\"बैलांना विविध प्रकार असतात: लाल कंधारी, खिल्लारी इत्यादी.\",\"बैलपोळा सणात बैलांना मातीचे बैल बनवून सजवतात.\",\"सणाच्या दिवशी बैलांना चाबूक व वेसण दिली जाते.\",\"बैलपोळा सणात बैलांना गोंडे व शिंगे लावली जातात.\",\"बैलपोळा सणात बैलांना गळ्यात घुंगरांची माळ लावली जाते.\",\"बैलपोळा सणात बैलांना झुली लावली जाते.\",\"बैलपोळा सणात बैलांना विविध रंग व सजावट लावली जाते.\",\"बैलपोळा सणात बैलांना विविध प्रकारचे नावे दिली जातात.\",\"बैलांना विविध प्रकार असतात: लाल कंधारी, खिल्लारी इत्यादी.\"]','[{\"q\":\"कवितेनुसार बैलांच्या शिंगांना काय बांधले आहे?\",\"options\":[\"घुंगरू\",\"बाशिंगे\",\"वेसण\",\"आसूड\"],\"answer\":1,\"explain\":\"कवितेच्या पहिल्या ओळीत \'शिंगे रंगविली, बाशिंगे बांधली\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'राजा, पवार्या, रतन, दिवाण\' ही कोणाची नावे कवितेत आली आहेत?\",\"options\":[\"शेतकऱ्यांची\",\"वाजंत्र्यांची\",\"बैलांची\",\"गावातील लोकांची\"],\"answer\":2,\"explain\":\"ही नावे बैलांची असून त्यांना मिरवणुकीसाठी सजवले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात बैलांच्या पाठीवर जे रंगीत नक्षीदार कापड दिसत आहे, त्याला कवितेत काय म्हटले आहे?\",\"options\":[\"चादर\",\"झूल\",\"गोंडा\",\"बाशिंग\"],\"answer\":1,\"explain\":\"बैलांच्या अंगावर चढवलेल्या सुशोभित कापडाला \'झूल\' म्हणतात.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"29\\/048_101.jpg\"},{\"q\":\"बैलांच्या गळ्यात काय वाजत आहे असे कवितेत वर्णन केले आहे?\",\"options\":[\"लेझीम\",\"बाशिंगे\",\"घुंगरांच्या माळा\",\"वेसण\"],\"answer\":2,\"explain\":\"कवितेत \'वाजती गळ्यात घुंगरांच्या माळा\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'झुलींच्या खालती काय नसतील आसुडाचे वळ उठलेले?\' या ओळीतून कवीला काय सुचवायचे आहे?\",\"options\":[\"बैलांना खूप खाऊ घातले आहे\",\"बैलांना मार बसलेला असतो\",\"बैलांना थंडी वाजत आहे\",\"बैलांना झूल आवडली आहे\"],\"answer\":1,\"explain\":\"झुलीच्या सजावटीखाली बैलांच्या अंगावर मारहाणीचे व्रण (वळ) लपलेले असतात, हे कवी सांगत आहेत.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात बैलांच्या शिंगांच्या टोकावर आणि बाजूला काय बांधलेले दिसत आहे?\",\"options\":[\"फक्त दोरी\",\"बाशिंगे आणि गोंडे\",\"आसूड\",\"काहीही नाही\"],\"answer\":1,\"explain\":\"चित्रात बैलांच्या शिंगांना बाशिंगे आणि गोंडे लावून सजवलेले स्पष्ट दिसत आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"29\\/048_101.jpg\"},{\"q\":\"बैलाने जराशी मान झटकली तरी काय ओढले जाते?\",\"options\":[\"झूल\",\"बाशिंग\",\"वेसण\",\"घुंगरू\"],\"answer\":2,\"explain\":\"कवितेनुसार, बैलांच्या नाकात घट्ट वेसण असते, जी मान झटकल्यावर खेचली जाते.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"कवीने \'सण एक दिन!\' असे का म्हटले असावे?\",\"options\":[\"कारण बैल फक्त एक दिवस काम करतात\",\"कारण बैलांना फक्त एक दिवस मान मिळतो, बाकी वर्षभर कष्ट असतात\",\"कारण पोळा हा सण आठवडाभर चालतो\",\"कारण बैलांना सण आवडत नाही\"],\"answer\":1,\"explain\":\"सणादिवशी सजावट असली तरी वर्षभर बैलांना ओझे ओढण्याचे कष्ट करावे लागतात, हे कवीला अधोरेखित करायचे आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'ओझे मरमर ओढायाचे\' या शब्दप्रयोगाचा अर्थ काय?\",\"options\":[\"हसत खेळत काम करणे\",\"खूप कष्ट उपसणे\",\"फक्त सणादिवशी काम करणे\",\"काहीही काम न करणे\"],\"answer\":1,\"explain\":\"\'मरमर ओढणे\' म्हणजे अत्यंत कष्टदायक काम सतत करत राहणे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"या कवितेतून बैलांच्या आयुष्यातील कोणत्या वास्तवावर प्रकाश टाकला आहे?\",\"options\":[\"बैलांचे आयुष्य खूप सुखाचे असते\",\"बैलांना फक्त सजवून मिरवले जाते\",\"सणाचे कौतुक क्षणिक असून बैलांचे कष्ट कायमस्वरूपी असतात\",\"बैल कधीही काम करत नाहीत\"],\"answer\":2,\"explain\":\"कविता सणाचे बाह्य रूप आणि बैलांचे वर्षभराचे कष्ट यातील विरोधाभास दाखवते.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"बैलाच्या नाकातून घातलेल्या दोरीला काय म्हणतात?\",\"options\":[\"बाशिंग\",\"आसुड\",\"वेसण\",\"खोडं\"],\"answer\":2,\"explain\":\"उताऱ्यात दिलेल्या माहितीनुसार, बैलाच्या नाकातून घातलेल्या दोरीला \'वेसण\' म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"बैलांच्या पाठीवरील उंच भागाला काय म्हणतात?\",\"options\":[\"बांडं\",\"बाशिंग\",\"गोंडा\",\"वेसण\"],\"answer\":0,\"explain\":\"उताऱ्यात \'बांडं\' म्हणजे बैलांच्या पाठीवरील उंच भाग असे स्पष्ट केले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"काही भागात \'बैलपोळा\' सणास काय म्हणतात?\",\"options\":[\"दिवाळी\",\"बेंदूर\",\"दसरा\",\"होळी\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे बैलपोळा सणास काही भागात \'बेंदूर\' असे म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'खोडं\' या शब्दाचा उताऱ्यातील अर्थ काय आहे?\",\"options\":[\"म्हातारा बैल\",\"आजार पडलेला बैल\",\"तरुण बैल\",\"शेतीचे अवजार\"],\"answer\":2,\"explain\":\"उताऱ्यातील शब्दार्थांनुसार \'खोडं\' म्हणजे तरुण बैल होय.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"आपली संस्कृती कोणत्या प्रकारची आहे?\",\"options\":[\"औद्योगिक संस्कृती\",\"कृषी संस्कृती\",\"पाश्चात्य संस्कृती\",\"नागरी संस्कृती\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे म्हटले आहे की आपली संस्कृती \'कृषी संस्कृती\' आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'अवखळ\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"शांत\",\"आळशी\",\"चपळ\",\"रागीट\"],\"answer\":2,\"explain\":\"उताऱ्यात \'अवखळ\' या शब्दाचा अर्थ \'चपळ\' असा दिला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शेतीतील कामे झटपट कशामुळे होऊ लागली आहेत?\",\"options\":[\"जास्त मजूर मिळाल्यामुळे\",\"पाऊस जास्त पडल्यामुळे\",\"आधुनिक तंत्रज्ञानामुळे\",\"बैलांची संख्या वाढल्यामुळे\"],\"answer\":2,\"explain\":\"आधुनिक तंत्रज्ञानामुळे शेतीतील कामे झटपट होऊ लागली आहेत असे उताऱ्यात म्हटले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'रेशीमदार\' सजावट कशाचा वापर करून केली जाते?\",\"options\":[\"फुलांचा वापर करून\",\"लहान लहान आरसे लावून\",\"रंगीत खडू वापरून\",\"केवळ धाग्यांचा वापर करून\"],\"answer\":1,\"explain\":\"उताऱ्यात \'रेशीमदार\' म्हणजे लहान लहान आरसे लावून केलेली शोभिवंत सजावट असा अर्थ दिला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते काम शेतीशी संबंधित असल्याचे उताऱ्यात नमूद केले आहे?\",\"options\":[\"विणकाम\",\"कोळपणी\",\"कुंभारकाम\",\"लोहारकाम\"],\"answer\":1,\"explain\":\"उताऱ्यात नांगणी, पेरणी आणि कोळपणी ही शेतीतील कामे असल्याचे सांगितले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"विज्ञान व तंत्रज्ञानातील प्रगतीचा बैलांच्या संख्येवर काय परिणाम झाला आहे?\",\"options\":[\"बैलांची संख्या वाढली आहे\",\"बैलांची संख्या कमी झाली आहे\",\"बैलांच्या संख्येत काहीच बदल झाला नाही\",\"बैल जास्त वेगाने काम करू लागले आहेत\"],\"answer\":1,\"explain\":\"यंत्रांचा वापर वाढल्यामुळे गावा-गावातील बैलांची संख्या रोडावली (कमी झाली) आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"बैलपोळा सणाबाबत उताऱ्यात कोणती नवीन पद्धत नमूद केली आहे?\",\"options\":[\"सण साजरा करणे बंद झाले आहे\",\"केवळ मशीनचे बैल आणून सण साजरा केला जातो\",\"बैलपोळा आता फक्त शहरात साजरा होतो\",\"बैलपोळ्याला सुटी दिली जात नाही\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की, आता कितीतरी शेतकरी केवळ मशीनचे बैल आणून बैलपोळा साजरा करतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"यंत्रांच्या वाढत्या वापरामुळे कोणत्या खताच्या वापरावर परिणाम झाला आहे?\",\"options\":[\"रासायनिक खत\",\"जैविक खत\",\"पाणी\",\"माती\"],\"answer\":1,\"explain\":\"बैलांची संख्या कमी झाल्यामुळे गोवरास आणि जैविक खतांच्या वापराचे प्रमाण कमी झाले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"उपक्रमानुसार, बैलपोळ्याविषयी माहिती घेण्यासाठी कोणाशी गप्पा मारायला सांगितले आहे?\",\"options\":[\"शिक्षकांशी\",\"मित्रांशी\",\"आजोबा किंवा चुलतोजोबांशी\",\"दुकानदाराशी\"],\"answer\":2,\"explain\":\"मजकुरात आजोबांशी किंवा चुलतोजोबांशी गप्पा मारून माहिती घेण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"आजोबांच्या कोणत्या काळातील बैलपोळा साजरा करण्याच्या पद्धतीची माहिती घ्यायची आहे?\",\"options\":[\"तरुणपणी\",\"लहानपणी\",\"वृद्धपणी\",\"नोकरीच्या वेळी\"],\"answer\":1,\"explain\":\"त्यांच्या लहानपणी हा सण कसा साजरा व्हायचा, याची माहिती घेण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"मजकुरात बैलांच्या कोणत्या दोन प्रकारांचा उल्लेख उदाहरणादाखल केला आहे?\",\"options\":[\"जर्सी व गीर\",\"लाल कंधारी व खिल्लारी\",\"साहिवाल व ओंगोल\",\"देवणी व हरियाना\"],\"answer\":1,\"explain\":\"मजकुरात लाल कंधारी आणि खिल्लारी या बैलांच्या प्रकारांचा उल्लेख आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"उपक्रमात बैलांव्यतिरिक्त आणखी कोणत्या प्राण्यांच्या नावांची माहिती मिळवायला सांगितली आहे?\",\"options\":[\"वाघ व सिंह\",\"घोडा व हत्ती\",\"कुत्री व मांजरे\",\"शेळी व मेंढी\"],\"answer\":2,\"explain\":\"परिसरातील बैलांसोबतच पाळीव कुत्र्यांना व मांजरांना दिलेल्या नावांची माहिती मिळवायला सांगितली आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"मिळवलेल्या कवितांचा काय तयार करायला सांगितले आहे?\",\"options\":[\"चित्रसंग्रह\",\"काव्यगुच्छ\",\"निबंध\",\"शब्दकोश\"],\"answer\":1,\"explain\":\"मिळवलेल्या कविता एकत्र करून त्यांचा काव्यगुच्छ तयार करण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"काव्यगुच्छ तयार केल्यानंतर त्याचे वर्गात काय करायचे आहे?\",\"options\":[\"लेखन\",\"चित्रण\",\"वाचन\",\"गायन\"],\"answer\":2,\"explain\":\"तयार केलेल्या काव्यगुच्छाचे वर्गात वाचन करायला सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"कविता मिळवण्यासाठी कोणते तीन विषय मजकुरात सुचवले आहेत?\",\"options\":[\"शाळा, घर, रस्ता\",\"सण, प्राणी, पक्षी\",\"नदी, डोंगर, समुद्र\",\"खेळ, व्यायाम, आरोग्य\"],\"answer\":1,\"explain\":\"सण, प्राणी आणि पक्षी यांच्यावर आधारित कविता मिळवण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"पाळीव प्राण्यांच्या नावांची माहिती मिळवून ती कोठे सांगायची आहे?\",\"options\":[\"घरात\",\"मैदानावर\",\"वर्गात\",\"बाजारात\"],\"answer\":2,\"explain\":\"मिळवलेली नावांची माहिती वर्गात सांगण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"बैलांचे प्रकार शोधणे हा उपक्रम कशावर आधारित आहे?\",\"options\":[\"बैलांचे खाद्य\",\"बैलांच्या जाती\\/प्रकार\",\"बैलांचे आजार\",\"बैलांची किंमत\"],\"answer\":1,\"explain\":\"लाल कंधारी आणि खिल्लारी हे बैलांचे वेगवेगळे प्रकार शोधण्यास सांगितले आहे.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरात एकूण किती मुख्य उपक्रम (क्रमांकानुसार) दिले आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"दिलेल्या मजकुरात १ ते ४ असे चार क्रमांकित उपक्रम दिले आहेत.\",\"topic\":\"उपक्रम\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सात चंच्या कोठे राहायच्या?\",\"options\":[\"एका मोठ्या वाड्यात\",\"पर्वताच्या पायथ्याशी असलेल्या गुहेत\",\"नदीच्या काठी असलेल्या झोपडीत\",\"बर्फाच्या घरात\"],\"answer\":1,\"explain\":\"पाठाच्या सुरुवातीलाच दिले आहे की सात चंच्या पर्वताच्या पायथ्याशी एका गुहेत राहायच्या.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"हिवाळ्याच्या महिन्यांत चंच्या राहतात त्या प्रदेशात काय पडायचे?\",\"options\":[\"पाऊस\",\"गारा\",\"बर्फ\",\"फुले\"],\"answer\":2,\"explain\":\"थंड प्रदेशात हिवाळ्याच्या काळात बर्फ पडत असे, असे मजकुरात नमूद केले आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"चंच्या रात्री झोपण्यासाठी कशाचा वापर करायच्या?\",\"options\":[\"चटई\",\"दुलई\",\"गोधडी\",\"गादी\"],\"answer\":1,\"explain\":\"चंच्या रात्री त्यांच्या गुहेतल्या दुलईत शिरून झोपी जायच्या.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"चंच्यांच्या बोलण्यातील \'एकाहून एक चढ\' असणे म्हणजे काय?\",\"options\":[\"एकमेकींवर ओरडणे\",\"प्रत्येक चंचीने आधीच्या माहितीपेक्षा जास्त माहिती सांगणे\",\"पर्वतावर चढणे\",\"खूप वेगाने बोलणे\"],\"answer\":1,\"explain\":\"प्रत्येक चंचीने दुलईबद्दल एक एक नवीन विशेषण जोडून माहिती वाढवली आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दुसऱ्या चंचीने दुलईसाठी कोणता विशेष शब्द वापरला आहे?\",\"options\":[\"मऊमऊ\",\"स्वच्छ\",\"उबदार\",\"रेशमी\"],\"answer\":2,\"explain\":\"दुसरी चंची म्हणाली, \'मी उबदार दुलईतून बाहेर पडले.\'\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"तिसरी चंची दुलईबद्दल काय म्हणाली?\",\"options\":[\"मी मऊमऊ, उबदार दुलईतून बाहेर पडले\",\"मी स्वच्छ दुलईतून बाहेर पडले\",\"मी जुनाट दुलईतून बाहेर पडले\",\"मी हलक्या दुलईतून बाहेर पडले\"],\"answer\":0,\"explain\":\"तिसऱ्या चंचीने \'मऊमऊ\' आणि \'उबदार\' हे दोन्ही शब्द वापरले आहेत.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"चंच्यांची गुहा नेमकी कोठे होती?\",\"options\":[\"समुद्रकिनारी\",\"पर्वताच्या शिखरावर\",\"थंड प्रदेशातील पर्वताच्या पायथ्याशी\",\"दाट जंगलात\"],\"answer\":2,\"explain\":\"मजकुराच्या पहिल्या ओळीत गुहेचे स्थान स्पष्ट केले आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"चंच्या दुलईबद्दल जी माहिती सांगत होत्या, त्या शब्दांना व्याकरणात काय म्हणतात?\",\"options\":[\"नाम\",\"सर्वनाम\",\"विशेषण\",\"क्रियापद\"],\"answer\":2,\"explain\":\"वस्तूविषयी विशेष माहिती देणाऱ्या शब्दांना विशेषण म्हणतात.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत अमिताला कोणती गोष्ट आवडते असे दाखवले आहे?\",\"options\":[\"गुलाब\",\"पेरू\",\"आइसक्रीम\",\"शेंगदाणे\"],\"answer\":1,\"explain\":\"तक्त्यानुसार अमिताच्या नावासमोर \'पेरू\' ही गोष्ट दिली आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"remember\",\"figure_image\":\"29\\/050_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील तक्त्यानुसार, \'बुरबुर\' हा शब्द कशाचे वर्णन करण्यासाठी वापरला आहे?\",\"options\":[\"पेरू\",\"आइसक्रीम\",\"पाऊस\",\"नदीकाठ\"],\"answer\":2,\"explain\":\"तक्त्यात रजनीला आवडणाऱ्या \'पाऊस\' या गोष्टीसाठी \'बुरबुर\' हा शब्द वापरला आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"29\\/050_101.jpg\"},{\"q\":\"चंच्या कोणत्या ऋतूत बर्फात खेळायच्या?\",\"options\":[\"उन्हाळा\",\"पावसाळा\",\"हिवाळा\",\"वसंत\"],\"answer\":2,\"explain\":\"मजकुरात \'हिवाळ्याच्या महिन्यांत तिथे बर्फ पडायचा\' असे म्हटले आहे.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"कंसातील शब्दांपैकी कोणता शब्द दुलईच्या कापडाचा प्रकार दर्शवतो?\",\"options\":[\"खुसखुशीत\",\"सुती\",\"जुनाट\",\"झिरमिरीत\"],\"answer\":1,\"explain\":\"\'सुती\' हा कापडाचा एक प्रकार आहे जो दुलईसाठी वापरला जाऊ शकतो.\",\"topic\":\"चंच्या काय बोलल्या?\",\"part\":7,\"bloom\":\"apply\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29'),(21722,29,5,'Marathi','mr','राष्ट्रसंत तुकडोजीमहाराज','[\"राष्ट्रसंत तुकडोजीमहाराज हे महाराष्ट्रातील प्रसिद्ध संत आणि सामाजिक कार्यकर्ते होते.\",\"त्यांनी १९४० च्या दशकात \'ग्रामगीता\' नावाचा ग्रंथ लिहिला ज्याने ग्रामीण जीवनातील समस्या आणि समाधान स्पष्ट केले.\",\"त्यांनी \'भूदान\' चळवळ सुरू केली ज्यात शेतकऱ्यांनी आपली जमीन दान दिली आणि ती समाजसेवेसाठी वापरली.\",\"तुकडोजीमहाराज यांनी जपानमध्ये \'विश्‍वशांती परिषद\' मध्ये भाग घेतला आणि भारताच्या स्वातंत्र्य संग्रामाला मदत केली.\",\"त्यांनी विविध भाषांमध्ये गाणी गायली – मराठी, इंग्रजी, हिंदी, आणि इतर प्रादेशिक भाषा.\",\"त्यांनी \'सामुदायिक सहभोजन\' आयोजित केले ज्यात सर्व जाती-धर्मांचे लोक एकत्र आले.\",\"त्यांनी \'संत संमेलन\' आणि \'ग्रामोद्योग संवर्धन\' यांसारखे कार्यक्रम सुरू केले.\",\"त्यांना \'राष्ट्रसंत\' ही पदवी डॉ. राजेंद्रप्रसाद यांनी दिली.\",\"त्यांनी \'सानेगुरुजी\' यांच्या उपोषणाला पाठिंबा दिला आणि समाजात अहिंसा व धर्मनिरपेक्षता पसरवली.\",\"त्यांच्या कार्यामुळे महाराष्ट्रातील ग्रामीण समाजात सुधारणा झाली.\",\"त्यांनी \'हठयोग\' आणि \'पाले\' यांसारख्या परंपरांचा प्रसार केला.\",\"त्यांनी \'धुंडाळणे\' या शब्दाचा वापर शोध घेण्यासाठी केला.\",\"त्यांनी \'कवन\' या पद्यरचनेचा वापर केला.\",\"त्यांनी \'खंजिरी\' या वाद्याचा वापर केला.\",\"त्यांनी \'समर्थन\' या शब्दाचा अर्थ पाठबळ असा स्पष्ट केला.\"]','[{\"q\":\"राष्ट्रसंत तुकडोजीमहाराजांचे लहानपणीचे नाव काय होते?\",\"options\":[\"माणिक\",\"तुकडोजी\",\"चंद्रपूर\",\"जयपूर\"],\"answer\":0,\"explain\":\"उताऱ्यात स्पष्टपणे दिले आहे की त्या मुलाचे नाव \'माणिक\' होते.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"जयपूरचा राजा चंद्रपूरजवळच्या ताडोबा अरण्यात कशासाठी आला होता?\",\"options\":[\"ध्यान लावण्यासाठी\",\"शिकारीसाठी\",\"मुलाला भेटण्यासाठी\",\"सहलीसाठी\"],\"answer\":1,\"explain\":\"उताऱ्याच्या दुसऱ्या ओळीत राजा शिकारीसाठी आला होता असे नमूद केले आहे.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"ही गोष्ट सुमारे किती वर्षांपूर्वीची आहे?\",\"options\":[\"पन्नास\",\"शंभर\",\"नव्वद\",\"सत्तर\"],\"answer\":2,\"explain\":\"पाठाची सुरुवातच \'सुमारे नव्वद वर्षांपूर्वीची ही गोष्ट\' अशी झाली आहे.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"माणिकने राजाला कोणती शपथ घ्यायला लावली?\",\"options\":[\"नेहमी खरे बोलण्याची\",\"झाडे लावण्याची\",\"कोणत्याही प्राण्याची शिकार न करण्याची\",\"जंगलात राहण्याची\"],\"answer\":2,\"explain\":\"माणिकच्या सांगण्यावरून राजाने यापुढे शिकार न करण्याची शपथ घेतली.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"राजा निरुत्तर का झाला?\",\"options\":[\"त्याला रस्ता सापडत नव्हता\",\"मुलाने विचारलेल्या प्रश्नामुळे त्याला स्वतःची चूक कळून आली\",\"त्याला जंगलातील प्राण्यांची भीती वाटली\",\"त्याला मुलाचे नाव माहित नव्हते\"],\"answer\":1,\"explain\":\"मुलाने प्राण्यांना का ठार करता असे विचारल्यावर राजाला आपली चूक उमजली व तो निरुत्तर झाला.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"मुलगा गुहेच्या तोंडाशी काय करत बसला होता?\",\"options\":[\"खेळत होता\",\"शिकार करत होता\",\"ध्यान लावून बसला होता\",\"प्राण्यांना खाऊ घालत होता\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की एक मुलगा गुहेच्या तोंडाशी ध्यान लावून बसला होता.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राजा कोणत्या ठिकाणचा होता?\",\"options\":[\"चंद्रपूर\",\"ताडोबा\",\"जयपूर\",\"नागपूर\"],\"answer\":2,\"explain\":\"उताऱ्यात \'जयपूरकडचा एक राजा\' असा उल्लेख आहे.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात माणिक या मुलाचे वर्णन करण्यासाठी कोणता शब्द वापरला आहे?\",\"options\":[\"आळशी\",\"चुणचुणीत\",\"भीतरा\",\"शांत\"],\"answer\":1,\"explain\":\"उताऱ्यात मुलाला \'चुणचुणीत\' असे संबोधले आहे.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रातील व्यक्ती पुढे कोणत्या नावाने प्रसिद्धीस आली?\",\"options\":[\"संत ज्ञानेश्वर\",\"राष्ट्रसंत तुकडोजीमहाराज\",\"संत तुकाराम\",\"संत नामदेव\"],\"answer\":1,\"explain\":\"चित्रातील व्यक्ती माणिक असून ते पुढे राष्ट्रसंत तुकडोजीमहाराज या नावाने प्रसिद्ध झाले.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"29\\/051_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील व्यक्तीने लहानपणी कोणाला अहिंसेची शपथ घ्यायला लावली?\",\"options\":[\"एका सामान्य माणसाला\",\"ताडोबाच्या वाघाला\",\"जयपूरच्या राजाला\",\"स्वतःच्या मित्रांना\"],\"answer\":2,\"explain\":\"चित्रातील तुकडोजीमहाराजांनी (माणिकने) जयपूरच्या राजाला शिकारीपासून परावृत्त करून शपथ दिली.\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"29\\/051_101.jpg\"},{\"q\":\"माणिकच्या वडिलांचे नाव काय होते?\",\"options\":[\"बंडोजी इंगळे ठाकूर\",\"आडकोजीमहाराज\",\"तुकडोजीमहाराज\",\"रामजी ठाकूर\"],\"answer\":0,\"explain\":\"उताऱ्याच्या पहिल्या ओळीत माणिकच्या वडिलांचे नाव बंडोजी इंगळे ठाकूर असे दिले आहे.\",\"topic\":\"बालपण आणि सा