ic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"पाणी विकत घ्यावे लागत असल्यामुळे कोणाचे नुकसान होते?\",\"options\":[\"श्रीमंत लोकांचे\",\"पैसे नसणाऱ्या कोट्यवधी लोकांचे\",\"दुकानदारांचे\",\"प्रवाशांचे\"],\"answer\":1,\"explain\":\"पैसे नसल्यामुळे कोट्यवधी लोक स्वच्छ पाण्यास मुकतात असे उताऱ्यात म्हटले आहे.\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"सार्वजनिक ठिकाणी पिण्याचे पाणी कसे उपलब्ध व्हायला हवे?\",\"options\":[\"महाग\",\"विकत\",\"मोफत\",\"कमी प्रमाणात\"],\"answer\":2,\"explain\":\"सार्वजनिक ठिकाणी पिण्याचे पाणी मोफत उपलब्ध व्हायला हवे, असे कोशाचे मत आहे.\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एका कुटुंबाला प्रवासात ४ लीटर पाणी विकत घ्यायचे असेल, तर त्यांना किमान (कमीत कमी) किती रुपये लागतील?\",\"options\":[\"४० रुपये\",\"६० रुपये\",\"८० रुपये\",\"१०० रुपये\"],\"answer\":1,\"explain\":\"एका लीटरला किमान १५ रुपये लागतात, म्हणून ४ लीटरसाठी १५ x ४ = ६० रुपये लागतील. (पर्यायानुसार किमान १५ दराने ६० रुपये होतात, परंतु उताऱ्यातील १५-२० दराचा विचार करता ६० हा योग्य पर्याय आहे).\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'निर्धोक\' या शब्दाचा पाठाच्या संदर्भात योग्य अर्थ काय?\",\"options\":[\"धोकादायक\",\"सुरक्षित किंवा शुद्ध\",\"थंडगार\",\"रंगीत\"],\"answer\":1,\"explain\":\"निर्धोक म्हणजे ज्यापासून कोणताही धोका नाही असे, म्हणजेच सुरक्षित पाणी.\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यातील माहितीनुसार, प्रवासात पाणी विकत घेण्याचे मुख्य कारण काय आहे?\",\"options\":[\"पाणी स्वस्त मिळते म्हणून\",\"सार्वजनिक ठिकाणी पाणी पिण्यालायक नसते म्हणून\",\"लोकांना पाणी विकत घ्यायला आवडते म्हणून\",\"पाणी सर्वत्र मोफत मिळते म्हणून\"],\"answer\":1,\"explain\":\"सार्वजनिक ठिकाणी पाणी मिळत नाही किंवा ते पिण्यालायक नसते, म्हणून लोक पाणी विकत घेतात.\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"कोशाच्या बोलण्यातून कोणता सामाजिक प्रश्न मांडला गेला आहे?\",\"options\":[\"प्रवासातील सोयींचा अभाव\",\"पाण्याचे वाढते दर\",\"स्वच्छ पाण्याचा अधिकार आणि त्याची अनुपलब्धता\",\"रेल्वेस्टेशनवरील गर्दी\"],\"answer\":2,\"explain\":\"उताऱ्यात स्वच्छ पाण्याचा अधिकार आणि गरिबांना ते न मिळणे हा मुख्य प्रश्न मांडला आहे.\",\"topic\":\"स्वच्छ व निर्धोक पाण्याचा अधिकार\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"पाण्यासाठी वणवण करावी लागल्यामुळे कोणाच्या आरोग्यावर दुष्परिणाम होत आहेत?\",\"options\":[\"केवळ पुरुषांच्या\",\"अनेक मुलींच्या व स्त्रियांच्या\",\"केवळ प्राण्यांच्या\",\"केवळ लहान मुलांच्या\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की पाण्यासाठी वणवण केल्यामुळे मुलींच्या व स्त्रियांच्या आरोग्यावर परिणाम होतो.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"देशभरातल्या लाखो मुलींच्या कशावर पाणीटंचाईमुळे परिणाम होत आहे?\",\"options\":[\"खेळावर\",\"जेवणावर\",\"शिक्षणावर\",\"झोपेवर\"],\"answer\":2,\"explain\":\"पाणीटंचाईमुळे देशभरातील लाखो मुलींच्या शिक्षणावर परिणाम होत असल्याचे उताऱ्यात म्हटले आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"काही छोट्या शहरांमध्ये किती दिवसांतून एकदा पाणी मिळते?\",\"options\":[\"दररोज\",\"दोन दिवसांतून एकदा\",\"आठवड्यातून किंवा दहा दिवसांतून एकदा\",\"महिन्यातून एकदा\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, काही छोट्या शहरांमध्ये आठवड्यातून किंवा दहा दिवसांतून एकदाच पाणी मिळते.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"ग्रामीण भागात पाण्याचा तुटवडा असल्यामुळे कोणता गंभीर प्रश्न निर्माण झाला आहे?\",\"options\":[\"रस्त्यांचा प्रश्न\",\"स्वच्छतेचा प्रश्न\",\"विजेचा प्रश्न\",\"बागांचा प्रश्न\"],\"answer\":1,\"explain\":\"ग्रामीण भागात पाण्याचा तुटवडा असल्यामुळे स्वच्छतेचा गंभीर प्रश्न निर्माण झाला आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"मोठ्या शहरांमध्ये पाण्याचा पुरवठा कसा होतो?\",\"options\":[\"अखंड पुरवठा\",\"कधीतरी पुरवठा\",\"आठवड्यातून एकदा\",\"पुरवठाच होत नाही\"],\"answer\":0,\"explain\":\"उताऱ्यात मोठ्या शहरांमध्ये पाण्याचा अखंड पुरवठा होत असल्याचे सांगितले आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'पाण्यासाठी वणवण करणे\' या शब्दाचा अर्थ काय?\",\"options\":[\"पाण्यात पोहणे\",\"पाण्यासाठी खूप फिरावे लागणे किंवा कष्ट करणे\",\"पाणी वाया घालवणे\",\"पाणी साठवून ठेवणे\"],\"answer\":1,\"explain\":\"पाणी मिळवण्यासाठी कराव्या लागणाऱ्या कष्टाला किंवा भटकंतीला \'वणवण\' असे म्हटले आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या मुलीला पाण्यासाठी खूप दूर जावे लागत असेल, तर उताऱ्याप्रमाणे तिच्या आयुष्यातील कोणत्या महत्त्वाच्या गोष्टीवर गदा येईल?\",\"options\":[\"तिच्या कपड्यांवर\",\"तिच्या शिक्षणावर\",\"तिच्या खेळाच्या साहित्यावर\",\"तिच्या घराच्या रंगावर\"],\"answer\":1,\"explain\":\"पाण्यासाठी वणवण करावी लागल्यामुळे मुलींच्या शिक्षणावर परिणाम होतो, असे उताऱ्यात दिले आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"एखाद्या गावात पाणी खूप कमी असेल, तर तिथे आरोग्याव्यतिरिक्त दुसरी कोणती मुख्य समस्या जाणवेल?\",\"options\":[\"वाहतुकीची कोंडी\",\"इंटरनेटचा अभाव\",\"स्वच्छतेचा अभाव\",\"मोठी दुकाने नसणे\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे पाण्याचा तुटवडा असल्यास स्वच्छतेचा गंभीर प्रश्न निर्माण होतो.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मोठी शहरे आणि छोटी शहरे यांच्या पाणीपुरवठ्यातील मुख्य फरक कोणता?\",\"options\":[\"मोठ्या शहरात पाणी महाग असते\",\"छोट्या शहरात पाणी जास्त असते\",\"मोठ्या शहरात अखंड पुरवठा असतो, तर छोट्या शहरात पाणी उशिरा मिळते\",\"दोन्ही ठिकाणी सारखाच पुरवठा असतो\"],\"answer\":2,\"explain\":\"उताऱ्यात मोठ्या शहरांतील अखंड पुरवठा आणि छोट्या शहरांतील आठवड्यातून एकदा मिळणारे पाणी यांची तुलना केली आहे.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"या उताऱ्यातून पाणीटंचाईचा कोणता परिणाम प्रामुख्याने दिसून येतो?\",\"options\":[\"केवळ आर्थिक परिणाम\",\"केवळ औद्योगिक परिणाम\",\"सामाजिक आणि आरोग्याशी संबंधित परिणाम\",\"केवळ शेतीवर होणारा परिणाम\"],\"answer\":2,\"explain\":\"हा उतारा आरोग्य, शिक्षण आणि स्वच्छता यांसारख्या सामाजिक परिणामांवर प्रकाश टाकतो.\",\"topic\":\"पाणीटंचाईचे सामाजिक परिणाम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"घरातल्या प्रत्येकाने दररोज किती पाणी वाचवले पाहिजे असे उताऱ्यात म्हटले आहे?\",\"options\":[\"एक बादली\",\"एक तांब्या\",\"दोन बादल्या\",\"पाच लीटर\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की प्रत्येकाने दररोज एक तांब्या पाणी वाचवले पाहिजे.\",\"topic\":\"घरगुती पाणी बचत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"एका बादलीत जवळपास किती लीटर पाणी मावते असे उताऱ्यात सांगितले आहे?\",\"options\":[\"५ ते १० लीटर\",\"१० ते १२ लीटर\",\"१५ ते २० लीटर\",\"२० ते २५ लीटर\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, एक बादली म्हणजे जवळपास १५ ते २० लीटर पाणी होय.\",\"topic\":\"घरगुती पाणी बचत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात स्त्री कोणते घरगुती काम करताना दिसत आहे?\",\"options\":[\"कपडे धुणे\",\"सडा-सारवण करणे\",\"भांडी घासणे\",\"अंघोळ करणे\"],\"answer\":2,\"explain\":\"चित्रात स्त्री नळापाशी बसून भांडी घासताना\\/स्वच्छ करताना दिसत आहे.\",\"topic\":\"घरगुती पाणी बचत\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"29\\/094_101.jpg\"},{\"q\":\"हजार कुटुंबांच्या एका वस्तीत दिवसाला किती पाणी वाचू शकते?\",\"options\":[\"१५ ते २० हजार लीटर\",\"४ ते ६ लाख लीटर\",\"५० ते ७० लाख लीटर\",\"एक हजार लीटर\"],\"answer\":0,\"explain\":\"उताऱ्यात दिलेल्या हिशोबाप्रमाणे हजार कुटुंबांच्या वस्तीत दिवसाला १५ ते २० हजार लीटर पाणी वाचू शकते.\",\"topic\":\"घरगुती पाणी बचत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"पाणी बचतीसाठी उताऱ्यात खालीलपैकी कोणत्या कामाचा उल्लेख केलेला नाही?\",\"options\":[\"अंघोळ करणे\",\"सडा-सारवण करणे\",\"भांडी घासणे\",\"बागकाम करणे\"],\"answer\":3,\"explain\":\"उताऱ्यात अंघोळ, सडा-सारवण आणि भांडी घासणे यांचा उल्लेख आहे, पण बागकामाचा नाही.\",\"topic\":\"घरगुती पाणी बचत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"एका वर्षात अंदाजे किती पाणी वाचू