ic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"If one computer costs 27,540 rupees, what does the calculation 27,540 × 18 represent?\",\"options\":[\"The cost of 1 computer\",\"The cost of 18 computers\",\"The number of computers bought\",\"The total number of students\"],\"answer\":1,\"explain\":\"Multiplying the cost of one item by the quantity gives the total cost for that quantity.\",\"topic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"A traveller incurs a cost of 7,650 rupees for a journey. What will be the cost for 26 such travellers?\",\"options\":[\"1,98,900 rupees\",\"1,88,900 rupees\",\"1,97,900 rupees\",\"2,08,900 rupees\"],\"answer\":0,\"explain\":\"7650 × 26 = 1,98,900.\",\"topic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"In a plantation, there are 215 saplings in each of the 132 rows. Which expression correctly calculates the total saplings?\",\"options\":[\"215 + 132\",\"215 - 132\",\"215 × 132\",\"215 ÷ 132\"],\"answer\":2,\"explain\":\"The total number of saplings is found by multiplying the number of saplings per row by the number of rows.\",\"topic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"What is the result of multiplying 327 by 92?\",\"options\":[\"30,084\",\"29,084\",\"30,184\",\"30,074\"],\"answer\":0,\"explain\":\"327 × 92 = 30,084.\",\"topic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"When framing a word problem using the numbers 5473 and 627 as per Question 8, which mathematical operation is intended?\",\"options\":[\"Addition\",\"Subtraction\",\"Multiplication\",\"Division\"],\"answer\":2,\"explain\":\"Problem Set 14 focuses on multiplication word problems.\",\"topic\":\"Problem Set 14\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"In the \'Inspire Awards\' problem, what does the number 154 represent?\",\"options\":[\"The total amount granted\",\"The cost of project materials\",\"The number of students covered\",\"The number of schools