and\"},{\"q\":\"5\\/9 आणि 2\\/9 यांपैकी कोणता अपूर्णांक मोठा आहे?\",\"options\":[\"2\\/9\",\"5\\/9\",\"दोन्ही समान\",\"9\\/5\"],\"answer\":1,\"explain\":\"छेद समान असताना ज्याचा अंश (5) मोठा तो अपूर्णांक मोठा असतो.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"2\\/5 आणि 2\\/7 यांमध्ये कोणता अपूर्णांक लहान आहे?\",\"options\":[\"2\\/5\",\"5\\/2\",\"2\\/7\",\"7\\/2\"],\"answer\":2,\"explain\":\"अंश समान असताना ज्याचा छेद (7) मोठा असतो तो अपूर्णांक लहान असतो.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"3\\/7 < 4\\/7 या मांडणीचा अर्थ काय होतो?\",\"options\":[\"3\\/7 हा 4\\/7 पेक्षा मोठा आहे\",\"3\\/7 हा 4\\/7 पेक्षा लहान आहे\",\"3\\/7 आणि 4\\/7 समान आहेत\",\"यांपैकी काहीही नाही\"],\"answer\":1,\"explain\":\"गणितात \'<\' हे चिन्ह \'पेक्षा लहान\' दर्शवण्यासाठी वापरतात.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"भिन्न छेद असलेल्या अपूर्णांकांचा लहान-मोठेपणा ठरवण्यासाठी प्रथम काय करावे लागते?\",\"options\":[\"अंश समान करावे लागतात\",\"छेद समान करावे लागतात\",\"अंशांची बेरीज करावी लागते\",\"छेदांची वजाबाकी करावी लागते\"],\"answer\":1,\"explain\":\"भिन्न छेद असलेल्या अपूर्णांकांचे छेद समान केल्यावरच त्यांचा लहान-मोठेपणा ठरवता येतो.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सोनूच्या मते, 5 आणि 7 हे छेद असलेल्या अपूर्णांकांचा छेद समान करण्यासाठी कोणती संख्या वापरता येईल?\",\"options\":[\"12\",\"2\",\"35\",\"25\"],\"answer\":2,\"explain\":\"35 ला 5 आणि 7 या दोन्ही छेदांनी भाग जातो, म्हणून छेद 35 करता येईल.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जर दोन अपूर्णांकांचे अंश समान असतील, तर कोणता अपूर्णांक मोठा असेल?\",\"options\":[\"ज्याचा छेद मोठा आहे\",\"ज्याचा छेद लहान आहे\",\"ज्याचा छेद 10 आहे\",\"ज्याचा छेद 0 आहे\"],\"answer\":1,\"explain\":\"समान अंश असताना लहान छेद असलेला अपूर्णांक मोठा असतो.\",\"topic\":\"अपूर्णांकांचा लहान-मोठेपणा\",\"part\":5,\"bloom\":\"analyze\"},