\":[\"मोजपट्टी\",\"दोरखंड\",\"आलेखाकागद\",\"कोनमापक\"],\"answer\":2,\"explain\":\"उपक्रमात आलेखाकागदाचा उपयोग करून क्षेत्रफळ काढण्यास सांगितले आहे.\",\"topic\":\"शोध म्हणजे सापडेल व उपक्रम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"जर एका आयतात 1 सेमी बाजूचे 10 चौरस मावत असतील, तर त्या आयताचे क्षेत्रफळ किती असेल?\",\"options\":[\"1 चौसेमी\",\"5 चौसेमी\",\"10 चौसेमी\",\"20 चौसेमी\"],\"answer\":2,\"explain\":\"ABCD आयताच्या उदाहरणावरून, चौरसांची संख्या हीच त्या आयताचे चौसेमीमधील क्षेत्रफळ असते.\",\"topic\":\"शोध म्हणजे सापडेल व उपक्रम\",\"part\":6,\"bloom\":\"create\"},{\"q\":\"लांबी मोजण्याचे प्रमाणित एकक कोणते आहे?\",\"options\":[\"चौरस\",\"सेंटीमीटर\",\"क्षेत्रफळ\",\"बाजू\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, सेंटीमीटर हे लांबीचे प्रमाणित एकक आहे.\",\"topic\":\"क्षेत्रफळाचे एकक\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"क्षेत्रफळ मोजण्यासाठी प्रमाणित एकक म्हणून काय वापरतात?\",\"options\":[\"1 सेमी बाजू असलेला चौरस\",\"1 सेमी लांबीची रेघ\",\"कोणताही आयत\",\"फक्त वर्तुळ\"],\"answer\":0,\"explain\":\"क्षेत्रफळ मोजण्यासाठी 1 सेमी बाजू असलेला चौरस हे प्रमाणित एकक म्हणून घेतात.\",\"topic\":\"क्षेत्रफळाचे एकक\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'1 चौरस सेमी\' हे थोडक्यात कसे लिहिले जाते?\",\"options\":[\"1 सेमी\",\"1 चौमी\",\"1 चौसेमी\",\"1 चौकिमी\"],\"answer\":2,\"explain\":\"1 सेमी बाजू असलेला चौरस हे प्रमाणित एकक थोडक्यात 1 चौसेमी असे लिहितात.\",\"topic\":\"क्षेत्रफळाचे एकक\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शेती आणि बागा यांसारखी मोठी क्षेत्रफळे मोजण्यासाठी कोणते प्रमाणित एकक वापरतात?\",\"options\":[\"1 चौरस सेमी\",\"1 चौरस मीटर (चौमी)\",\"1 चौरस किलोमीटर\",\"1 सेंटीमीटर\"],\"answer\":1,\"explain\":\"मोठी क्षेत्रफळं मोजण्यासाठी 1 मीटर बाजू असलेला चौरस, म्हणजे 1 चौमी हे एकक वापरतात.\",\"topic\":\"क्षेत्रफळाचे एकक\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"तालुका किंवा जिल्हा यांचे क्षेत्रफळ मोजण्यासाठी कोणते एकक योग्य आहे?\",\"options\":[\"चौरस सेमी\",\"चौरस मीटर\",\"चौरस किलोमीटर (चौकिमी)\",\"सेंटीमीटर\"],\"answer\":2,\"explain\