nderstand\"},{\"q\":\"लेखक एका दिवसात जास्तीत जास्त किती कविता लिहायचे?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":2,\"explain\":\"लेखक कधी एका दिवसात तीन कविता लिहायचे, असा उल्लेख उताऱ्यात आहे.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या मते शब्दांना आपण कसे बघायला हवे?\",\"options\":[\"एकाच बाजूने\",\"फक्त वरवर\",\"चौफेर\",\"केवळ अर्थासाठी\"],\"answer\":2,\"explain\":\"लेखकाच्या मते शब्दांना आपल्याला चौफेर बघता आले पाहिजे.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता साहित्यप्रकार लेखक वाचत असल्याचे उताऱ्यात दिलेले नाही?\",\"options\":[\"कादंबरी\",\"आत्मचरित्र\",\"ललित\",\"विज्ञान कथा\"],\"answer\":3,\"explain\":\"उताऱ्यात सामाजिक पुस्तके, कादंबरी, कथा, आत्मचरित्र आणि ललित यांचा उल्लेख आहे, विज्ञान कथांचा नाही.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"शब्दांचे आणि भाषेचे वेगवेगळे आयाम कधी कळतात?\",\"options\":[\"जेव्हा आपण खूप पुस्तके वाचतो\",\"जेव्हा आपण कविता लिहितो\",\"जेव्हा आपल्याला बक्षीस मिळते\",\"जेव्हा आपण शाळेत जातो\"],\"answer\":0,\"explain\":\"जर खूप पुस्तकं वाचलीत, तर शब्दांचे आणि भाषेचे वेगवेगळे आयाम कळतील असे लेखकाने सांगितले आहे.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"लेखकाच्या मते शब्दांचा लळा कधी लागतो?\",\"options\":[\"जेव्हा आपण कविता पाठ करतो\",\"जेव्हा आपण शब्दांवर प्रेम करू लागतो\",\"जेव्हा आपण शब्दकोश वाचतो\",\"जेव्हा आपण परीक्षेत पास होतो\"],\"answer\":1,\"explain\":\"शब्दांवर आपण प्रेम करू लागतो तेव्हाच शब्दांचा लळा लागतो.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता लेखकाचा कवितासंग्रह आहे?\",\"options\":[\"शब्दांची मैत्री\",\"पुस्तकांचे जग\",\"नेणिवेची अक्षरे\",\"माझे गुरू\"],\"answer\":2,\"explain\":\"उताऱ्यात \'नेणिवेची अक्षरे\' हा लेखकाचा कवितासंग्रह असल्याचे नमूद केले आहे.\",\"topic\":\"पुस्तकं माझे गुरू\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"लेखकाने विविध प्रकारचे वाचन केल्यामुळे त्यांना काय साध्