c\":\"कवी परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता कल्याण इनामदार यांचा \'बालगीतसंग्रह\' आहे?\",\"options\":[\"सत्त्वाचा राजा\",\"टिपकाणा आणि मंडळी\",\"छन छन छडी\",\"मोरुची डोळे\"],\"answer\":2,\"explain\":\"\'छन छन छडी\' हा त्यांचा प्रसिद्ध बालगीतसंग्रह आहे, तर इतर बालकादंबऱ्या आहेत.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'सत्त्वांकुर\' हे कल्याण इनामदार यांचे साहित्यातील कोणत्या प्रकारचे पुस्तक आहे?\",\"options\":[\"बालगीतसंग्रह\",\"बालकादंबरी\",\"अभ्यासपूर्ण पुस्तक\",\"काव्यसंग्रह\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात \'सत्त्वांकुर\'चा उल्लेख बालकादंबरी म्हणून केला आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"कल्याण इनामदार यांना २००८ साली कोणत्या पुरस्काराने गौरवण्यात आले होते?\",\"options\":[\"पद्मश्री पुरस्कार\",\"साहित्य अकादमी पुरस्कार\",\"बालकविता वाङ्मय पुरस्कार\",\"ज्ञानपीठ पुरस्कार\"],\"answer\":2,\"explain\":\"त्यांना महाराष्ट्र साहित्य परिषदेचा \'बालकविता वाङ्मय पुरस्कार २००८\' मिळाला होता.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"एखाद्या विद्यार्थ्याला कवी कल्याण इनामदार यांचे \'अभ्यासपूर्ण पुस्तक\' वाचायचे असल्यास त्याने कोणते पुस्तक निवडावे?\",\"options\":[\"बाल गाणी\",\"गतिस्पंदना : स्वरूप आणि विकास\",\"देवांची लेकरे\",\"गाणारे गाणे\"],\"answer\":1,\"explain\":\"\'गतिस्पंदना : स्वरूप आणि विकास\' हे त्यांचे अभ्यासपूर्ण पुस्तक म्हणून प्रसिद्ध आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\'प्रकाशयात्री\' ही कविता कोणत्या संकलित काव्यसंग्रहातून घेतली आहे?\",\"options\":[\"फुलपाखरांचे डोळे\",\"भविष्याच्या कुतूहला\",\"सत्त्वाचा राजा\",\"गतिस्पंदना\"],\"answer\":1,\"explain\":\"कवितेच्या शेवटी दिलेल्या माहितीनुसार ही कविता \'भविष्याच्या कुतूहला\' या संग्रहातून घेतली आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणती साहित्यकृती \'बालकादंबरी\' या गटात मोडत नाही?\",\"options\":[\"टिपकाणा आणि मंडळी\",\"मोरुची डोळे\",\"देवांची लेकरे\",\"बाल गाणी\"],\"answer\":3,\"explain\":\"\'बाल गाणी\' हा बालगीतसंग्रह आहे, कादंबरी नाही.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"कल्याण इनामदार यांना कोणत्या संस्थेने पुरस्कार देऊन सन्मानित केले?\",\"options\":[\"मराठी साहित्य संमेलन\",\"महाराष्ट्र साहित्य परिषद\",\"साहित्य अकादमी\",\"राज्य शासन\"],\"answer\":1,\"explain\":\"त्यांना महाराष्ट्र साहित्य परिषदेचा पुरस्कार मिळाला होता.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"कवी परिचयानुसार, कल्याण इनामदार यांची मुख्य ओळख काय आहे?\",\"options\":[\"ऐतिहासिक संशोधक\",\"विज्ञान कथालेखक\",\"प्रसिद्ध मराठी कवी आणि बालसाहित्यिक\",\"नाट्यकार\"],\"answer\":2,\"explain\":\"परिचयाच्या पहिल्याच ओळीत त्यांचा उल्लेख प्रसिद्ध मराठी कवी आणि बालसाहित्यिक असा केला आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"\'प्रकाशयात्री\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"प्रकाशाच्या मार्गावर चालणारा\",\"अंधारात राहणारा\",\"प्रवास करणारा\",\"खेळणारा\"],\"answer\":0,\"explain\":\"दिलेल्या शब्दांच्या यादीनुसार प्रकाशयात्री म्हणजे प्रकाशाच्या मार्गावर चालणारा होय.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'गगन\' या शब्दासाठी खालीलपैकी कोणता समानार्थी शब्द दिला आहे?\",\"options\":[\"पृथ्वी\",\"आकाश\",\"पाणी\",\"वारा\"],\"answer\":1,\"explain\":\"नवीन शब्दांच्या यादीत गगन म्हणजे आकाश असा अर्थ दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'चितारणे\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"गाणे\",\"रेखाटणे\",\"पळणे\",\"वाचणे\"],\"answer\":1,\"explain\":\"चितारणे या शब्दाचा अर्थ रेखाटणे असा होतो.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"\'गंध\' या शब्दाचा योग्य अर्थ ओळखा.\",\"options\":[\"दुर्गंधी\",\"सुगंध\",\"रंग\",\"आकार\"],\"answer\":1,\"explain\":\"गंध म्हणजे फुलांचा सुगंध किंवा सुवास असा अर्थ पाठ्यपुस्तकात दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'घोस\' या शब्दाचा अर्थ खालीलपैकी कोणता?\",\"options\":[\"पान\",\"मूळ\",\"गुच्छ\",\"फांदी\"],\"answer\":2,\"explain\":\"घोस म्हणजे गुच्छ किंवा वसंतपुष्प असा अर्थ होतो.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\'खडे\' या शब्दाचा कवितेतील संदर्भाप्रमाणे अर्थ काय आहे?\",\"options\":[\"बसलेले\",\"पडलेले\",\"उभे\",\"धावणारे\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील नवीन शब्दांनुसार खडे म्हणजे उभे असा अर्थ होतो.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"\\\"आम्ही सर्व भारतीय एकमेकांचे ______ आहोत.\\\" या वाक्यात पाठातील कोणता शब्द योग्य ठरेल?\",\"options\":[\"शत्रू\",\"बांधव\",\"शेजारी\",\"पाहुणे\"],\"answer\":1,\"explain\":\"बांधव या शब्दाचा अर्थ भाऊ असा होतो, जो या वाक्यात योग्य बसतो.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"\\\"कोकिळेचा मधुर ______ ऐकू आला.\\\" या वाक्यात \'स्वर\' या शब्दाचा कोणता अर्थ अभिप्रेत आहे?\",\"options\":[\"आवाज\",\"रूप\",\"गंध\",\"स्पर्श\"],\"answer\":0,\"explain\":\"स्वर या शब्दाचा अर्थ आवाज असा होतो.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"प्रस्तावनेनुसार, \'प्रकाशयात्री\' ही व्यक्ती खालीलपैकी काय साधणारी असते?\",\"options\":[\"स्वतःचा फायदा\",\"जगाची प्रगती\",\"केवळ मनोरंजन\",\"विश्रांती\"],\"answer\":1,\"explain\":\"प्रस्तावनेत स्पष्ट केले आहे की प्रकाशयात्री ही जगाची प्रगती साधणारी व्यक्ती असते.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"कवितेतील \'गाणे\' या शब्दाचा अर्थ \'घोषणा\' असा दिला आहे, तर \'स्वर\' म्हणजे काय?\",\"options\":[\"शब्द\",\"आवाज\",\"ओळ\",\"ताल\"],\"answer\":1,\"explain\":\"दिलेल्या शब्दांच्या यादीत स्वर या शब्दाचा अर्थ आवाज असा दिला आहे.\",\"topic\":\"नवीन शब्द\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"\'घोषवाक्य\' म्हणजे काय?\",\"options\":[\"एखादी मोठी कथा\",\"प्रभावी व लक्षवेधी शब्दांत मांडलेले लहान वाक्य\",\"पाच-सहा ओळींची कविता\",\"नाटकातील एक संवाद\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, घोषवाक्य म्हणजे प्रभावी व लक्षवेधी शब्दांत मांडलेले लहान व अर्थपूर्ण वाक्य होय.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"घोषवाक्य कशासाठी तयार केले जाते?\",\"options\":[\"केवळ मनोरंजनासाठी\",\"विविध विषयांवर जागृती करण्यासाठी\",\"चित्रपट पाहण्यासाठी\",\"खेळ खेळण्यासाठी\"],\"answer\":1,\"explain\":\"विविध विषयांवर जागृती करण्यासाठी घोषवाक्ये तयार केली जातात.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"घोषवाक्याचे स्वरूप कसे असावे?\",\"options\":[\"खूप पाल्हाळिक आणि मोठे\",\"कमी शब्दात लयबद्ध व प्रभावी\",\"कठिण आणि न समजणारे\",\"केवळ गद्यात लिहिलेले\"],\"answer\":1,\"explain\":\"घोषवाक्य हे कमी शब्दात लयबद्ध व प्रभावी मांडणीचे असावे.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"घोषवाक्य सूत्रबद्ध करण्यासाठी कशाचा वापर केला जातो?\",\"options\":[\"यमक जुळणारे शब्द\",\"मोठी विशेषणे\",\"कठिण व्याकरण\",\"केवळ इंग्रजी शब्द\"],\"answer\":0,\"explain\":\"यमक जुळणारे शब्द वापरून घोषवाक्य सूत्रबद्ध केले जाते.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"समूहात जोश आणि उत्साह निर्माण करण्यासाठी कशाचा वापर केला जातो?\",\"options\":[\"गोष्टींचा\",\"घोषणांचा (घोषवाक्यांचा)\",\"पत्रांचा\",\"निबंधांचा\"],\"answer\":1,\"explain\":\"समूहात जोश निर्माण करण्यासाठी घोषवाक्ये घोषणा म्हणून वापरली जातात.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते घोषवाक्य उताऱ्यात उदाहरण म्हणून दिले आहे?\",\"options\":[\"पाणी वाचवा, जीवन वाचवा।\",\"झाडे लावा, झाडे जगवा।\",\"साक्षर जनता, भूषण भारत।\",\"जय जवान, जय किसान।\"],\"answer\":2,\"explain\":\"उताऱ्यात \'साक्षर जनता, भूषण भारत\' हे उदाहरण दिले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"पर्यावरण विषयावर जागृती करण्यासाठी काय तयार करता येईल?\",\"options\":[\"घोषवाक्य\",\"कादंबरी\",\"मोठा ग्रंथ\",\"शब्दकोश\"],\"answer\":0,\"explain\":\"पर्यावरणविषयक विषयांवर जागृतीसाठी घोषवाक्ये तयार करता येतात.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"घोषवाक्याच्या वैशिष्ट्यांबाबत चुकीचे विधान ओळखा.\",\"options\":[\"ते लयबद्ध असावे.\",\"त्यात यमक जुळणारे शब्द असावेत.\",\"ते खूप लांबलचक असावे.\",\"ते अर्थपूर्ण असावे.\"],\"answer\":2,\"explain\":\"घोषवाक्य लहान असावे, लांबलचक नसावे.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"\'स्वच्छ भारत, सुंदर भारत\' या घोषवाक्यातून कोणता उद्देश स्पष्ट होतो?\",\"options\":[\"आरोग्य आणि स्वच्छता\",\"केवळ खेळ\",\"केवळ शिक्षण\",\"केवळ वनभोजन\"],\"answer\":0,\"explain\":\"हे घोषवाक्य स्वच्छतेच्या उद्देशाने (आरोग्यविषयक\\/सामाजिक) तयार केलेले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"विविध उपक्रमांच्या प्रसंगी घोषवाक्यांचा वापर कशा प्रकारे करण्यास सुचवले आहे?\",\"options\":[\"पुस्तकात लिहून ठेवून\",\"आकर्षक पट्ट्या तयार करून\",\"केवळ मनात म्हणून\",\"घरी लपवून ठेवून\"],\"answer\":1,\"explain\":\"विविध विषयांवरील आकर्षक घोषवाक्यांच्या पट्ट्या तयार करून त्यांचा वापर करण्यास सुचवले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"शब्दांच्या जाती म्हणजे काय?\",\"options\":[\"शब्दांचे अर्थ\",\"शब्दांचे प्रकार\",\"शब्दांचे उच्चार\",\"शब्दांचे लेखन\"],\"answer\":1,\"explain\":\"पाठातील मजकुरानुसार, शब्दांच्या जाती म्हणजे शब्दांचे प्रकार होय.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"ज्या शब्दांच्या रूपात लिंग, वचन किंवा विभक्तीमुळे बदल होतो, त्यांना काय म्हणतात?\",\"options\":[\"अविकारी शब्द\",\"नाम\",\"विकारी शब्द\",\"अव्यय\"],\"answer\":2,\"explain\":\"ज्या शब्दांमध्ये बदल होतो, त्यांना ‘विकारी शब्द’ म्हणतात.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"वाक्यातील शब्दांना वेगवेगळी नावे कशावरून देण्यात आली आहेत?\",\"options\":[\"त्यांच्या लांबीवरून\",\"त्यांच्या उच्चारावरून\",\"त्यांच्या वाक्यातील कार्यावरून\",\"त्यांच्या लेखनावरून\"],\"answer\":2,\"explain\":\"शब्दांच्या वाक्यातील कार्यांवरून त्यांना वेगवेगळी नावे देण्यात आली आहेत.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते \'उभयान्वयी अव्यय\' आहे?\",\"options\":[\"सभोवार\",\"परंतु\",\"देखील\",\"शाब्बास\"],\"answer\":1,\"explain\":\"मजकुरात दिलेल्या उदाहरणांनुसार \'परंतु\' हे उभयान्वयी अव्यय आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, शब्दांच्या जातींचे मुख्य दोन प्रकार कोणते आहेत?\",\"options\":[\"नाम व सर्वनाम\",\"विशेषण व क्रियापद\",\"विकारी व अविकारी\",\"सव्यय व नाम\"],\"answer\":2,\"explain\":\"आकृतीमध्ये शब्दांच्या जातींचे विकारी (सव्यय) आणि अविकारी (अव्यय) असे दोन मुख्य विभाग दाखवले आहेत.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"33\\/031_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील तक्त्यानुसार, \'विशेषण\' या शब्दाचे अनेकवचनी रूप कोणते आहे?\",\"options\":[\"चांगला\",\"चांगली\",\"चांगले\",\"चांगल्यांना\"],\"answer\":2,\"explain\":\"तक्त्यामध्ये विशेषण या जातीसमोर अनेकवचनाच्या रकान्यात \'चांगले\' हा शब्द दिला आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"apply\",\"figure_image\":\"33\\/031_102.jpg\"},{\"q\":\"\'गातो\' या क्रियापदाचे स्त्रीलिंगी रूप काय होईल?\",\"options\":[\"गातात\",\"गाते\",\"गाणे\",\"गाण्याने\"],\"answer\":1,\"explain\":\"तक्त्यानुसार \'गातो\' (पुल्लिंग) चे स्त्रीलिंगी रूप \'गाते\' असे होते.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता शब्द \'अविकारी\' गटातील आहे?\",\"options\":[\"मुलगा\",\"चांगला\",\"नेहमी\",\"तो\"],\"answer\":2,\"explain\":\"\'नेहमी\' हे क्रियाविशेषण अव्यय असून ते अविकारी शब्दांच्या उदाहरणात दिले आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"शब्दांच्या रूपात बदल केव्हा होतो?\",\"options\":[\"जेव्हा शब्दांचा अर्थ बदलतो\",\"जेव्हा शब्दांचे लिंग किंवा वचन बदलते\",\"जेव्हा शब्द वाक्याच्या शेवटी येतो\",\"जेव्हा शब्द केवळप्रयोगी असतो\"],\"answer\":1,\"explain\":\"जेव्हा शब्दांचे लिंग किंवा वचन बदलते किंवा विभक्तीचे प्रत्यय लागतात, तेव्हा शब्दांच्या रूपात बदल होतो.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"विकारी आणि अविकारी शब्दांमधील मुख्य फरक कोणता?\",\"options\":[\"विकारी शब्द बदलतात, अविकारी बदलत नाहीत\",\"विकारी शब्द मोठे असतात, अविकारी लहान असतात\",\"विकारी शब्द वाक्यात येतात, अविकारी येत नाहीत\",\"विकारी शब्द नाम असतात, अविकारी सर्वनाम असतात\"],\"answer\":0,\"explain\":\"ज्या शब्दांत बदल होतो ते विकारी आणि ज्यात बदल होत नाही ते अविकारी शब्द असतात.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"\'शाब्बास\' हा शब्द कोणत्या प्रकारच्या अव्ययाचे उदाहरण आहे?\",\"options\":[\"क्रियाविशेषण अव्यय\",\"शब्दयोगी अव्यय\",\"उभयान्वयी अव्यय\",\"केवलप्रयोगी अव्यय\"],\"answer\":3,\"explain\":\"मजकुरातील उदाहरणांनुसार \'शाब्बास\' हे केवलप्रयोगी अव्यय आहे.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"या इयत्तेत (सहावीत) आपण कोणत्या शब्दांच्या प्रकारांची माहिती घेणार आहोत?\",\"options\":[\"केवळ अविकारी शब्दांची\",\"केवळ अव्ययांची\",\"नाम, सर्वनाम, विशेषण व क्रियापद या विकारी शब्दांची\",\"केवळ क्रियाविशेषण अव्ययांची\"],\"answer\":2,\"explain\":\"मजकुराच्या शेवटी स्पष्ट केले आहे की या इयत्तेत नाम, सर्वनाम, विशेषण व क्रियापद या विकारी शब्दांची माहिती पाहाणार आहोत.\",\"topic\":\"आपण समजून घेऊ या\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"व्याकरणात प्रत्यक्षात दिसणाऱ्या किंवा कल्पनेने जाणलेल्या वस्तूंना किंवा त्यांच्या गुणधर्मांना दिलेल्या नावांना काय म्हणतात?\",\"options\":[\"सर्वनाम\",\"विशेषण\",\"नाम\",\"क्रियापद\"],\"answer\":2,\"explain\":\"पाठातील व्याख्येनुसार, वस्तू किंवा त्यांच्या गुणधर्मांना दिलेल्या नावांना \'नाम\' म्हणतात.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"व्याकरणशास्त्रात \'वस्तू\' या शब्दाच्या व्यापक अर्थामध्ये खालीलपैकी कशाचा अंतर्भाव होतो?\",\"options\":[\"केवळ डोळ्यांना दिसणारे पदार्थ\",\"केवळ प्राणी\",\"केवळ निर्जीव वस्तू\",\"पदार्थ, प्राणी, गुणधर्म आणि भाव-भावना\"],\"answer\":3,\"explain\":\"व्याकरणात \'वस्तू\' या शब्दात पदार्थ, प्राणी, गुणधर्म आणि भाव-भावना या सर्वांचा समावेश होतो.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'शौर्य हे वीराचे लक्षण आहे\' या वाक्यातील \'शौर्य\' हे कोणत्या प्रकारचे नाम आहे?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"सर्वनाम\"],\"answer\":2,\"explain\":\"शौर्य हा एक गुणधर्म असल्याने ते भाववाचकनाम आहे.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"एकाच जातीच्या पदार्थांतील समान गुणधर्मामुळे त्या पदार्थाला जे सर्वसामान्य नाव दिले जाते, त्याला काय म्हणतात?\",\"options\":[\"विशेषनाम\",\"सामान्यनाम\",\"भाववाचकनाम\",\"सर्वनाम\"],\"answer\":1,\"explain\":\"एकाच जातीच्या पदार्थांतील समान गुणधर्मामुळे दिलेल्या नावाला \'सामान्यनाम\' म्हणतात.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'गंगा ही भारत देशातील मोठी नदी आहे\' या वाक्यातील \'नदी\' हे कोणत्या प्रकारचे नाम आहे?\",\"options\":[\"विशेषनाम\",\"भाववाचकनाम\",\"सामान्यनाम\",\"सर्वनाम\"],\"answer\":2,\"explain\":\"नदी हे एका जातीला दिलेले सर्वसामान्य नाव असल्याने ते सामान्यनाम आहे.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"ज्या नामाने जातीचा बोध होत नसून त्या जातीतील एका विशिष्ट व्यक्तीचा, प्राण्याचा किंवा वस्तूचा बोध होतो, त्यास काय म्हणतात?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"सर्वनाम\"],\"answer\":1,\"explain\":\"विशिष्ट व्यक्ती किंवा वस्तूचा बोध करून देणाऱ्या नावाला \'विशेषनाम\' म्हणतात.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'सह्याद्री पर्वतरांगात कळसुबाई हे सर्वात उंच शिखर आहे\' या वाक्यातील \'सह्याद्री\' हे कोणत्या प्रकारचे नाम आहे?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"सर्वनाम\"],\"answer\":1,\"explain\":\"सह्याद्री हे एका ठराविक पर्वताला दिलेले नाव असल्याने ते विशेषनाम आहे.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी \'सामान्यनाम\' ओळखा.\",\"options\":[\"रोहित\",\"कळसुबाई\",\"विद्यार्थी\",\"अनघा\"],\"answer\":2,\"explain\":\"विद्यार्थी हे एका जातीला दिलेले नाव आहे, तर इतर तिन्ही विशेषनामे आहेत.\",\"topic\":\"नाम आणि नामाचे प्रकार\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"ज्या नामाने प्राणी किंवा वस्तू यांच्यामध्ये असलेले गुण, धर्म किंवा भाव यांचा बोध होतो, त्याला काय म्हणतात?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"सर्वनाम