हा आजीला काय वाटते?\",\"options\":[\"नातू परदेशात गेला आहे\",\"कोणीतरी \'इंग्रजीत\' नावाचा माणूस बोलतोय\",\"नातू खूप हुशार झाला आहे\",\"फोन खराब झाला आहे\"],\"answer\":1,\"explain\":\"आजी \'कोण बोलतोय\' असे विचारते, कारण तिला वाटते इंग्रजीत हे कोणाचे तरी नाव आहे.\",\"topic\":\"करून पाहू या\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"\'चांगुलपणा\' हा शब्द कोणत्या रकान्यात लिहावा लागेल?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"सर्वनाम\"],\"answer\":2,\"explain\":\"चांगुलपणा हा एक गुण किंवा भाव आहे, म्हणून तो भाववाचकनाम आहे.\",\"topic\":\"करून पाहू या\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"विनोदच्या मते, \'खूप थंडी\' वाजली तर तो काय करतो?\",\"options\":[\"स्वेटर घालतो\",\"मेणबत्तीजवळ बसतो\",\"मेणबत्ती पेटवतो\",\"शेकोटी पेटवतो\"],\"answer\":2,\"explain\":\"विनोद म्हणतो की खूप थंडी वाजली तर तो मेणबत्ती पेटवतो.\",\"topic\":\"करून पाहू या\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या यादीतील \'गोदावरी\' या शब्दाचे वर्गीकरण कसे कराल?\",\"options\":[\"सामान्यनाम\",\"विशेषनाम\",\"भाववाचकनाम\",\"विशेषण\"],\"answer\":1,\"explain\":\"गोदावरी हे एका विशिष्ट नदीचे नाव असल्यामुळे ते विशेषनाम आहे.\",\"topic\":\"करून पाहू या\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"विद्यार्थ्यांनी कविता कशा प्रकारे म्हणायला हवी?\",\"options\":[\"फक्त मनातल्या मनात\",\"तालसुरात व सस्वर\",\"मोठ्याने ओरडून\",\"फक्त वाचून\"],\"answer\":1,\"explain\":\"मजकुरानुसार, विद्यार्थ्यांनी कविता तालसुरात व सस्वरमध्ये म्हणायला हवी.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी विद्यार्थ्यांना कवितेतील कोणत्या गोष्टीचा अर्थ समजावून सांगावा?\",\"options\":[\"फक्त जुन्या शब्दांचा\",\"कवितेच्या नावाचा\",\"नवीन शब्दांचा\",\"कवीच्या नावाचा\"],\"answer\":2,\"explain\":\"शिक्षकांनी विद्यार्थ्यांना कवितेतील नवीन शब्दांचा अर्थ समजावून सांगणे आवश्यक आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"शिक्षकांनी कवितेच्या कोणत्या पैलूंबाबत मार्गदर्शन करावे?\",\"options\":[\"फक्त कवितेची लांबी\",\"वैशिष्ट्ये, भावार्थ व शैली\",\"कवितेचा कागद\",\"कवितेचे अक्षर\"],\"answer\":1,\"explain\":\"मजकुरात कवितेची वैशिष्ट्ये, भावार्थ व शैली याबाबत मार्गदर्शन करण्यास सांगितले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"या पाठात व्याकरणाच्या कोणत्या घटकाची ओळख करून देण्यास सांगितले आहे?\",\"options\":[\"क्रियापद व त्याचे प्रकार\",\"विशेषण व त्याचे प्रकार\",\"नाम व नामाचे प्रकार\",\"सर्वनाम व त्याचे प्रकार\"],\"answer\":2,\"explain\":\"मजकुरानुसार, विद्यार्थ्यांना नामांची व नामाच्या प्रकारांची ओळख करून द्यावी.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"नामाचे प्रकार ओळखण्यासाठी शिक्षकांनी काय करून घ्यावे?\",\"options\":[\"जास्तीत जास्त सराव\",\"फक्त पाठांतर\",\"चित्रे काढणे\",\"गाणी गाणे\"],\"answer\":0,\"explain\":\"वाक्यांतील नाम व नामाचे प्रकार ओळखण्याला जास्तीत जास्त सराव करून घ्यावा असे मजकुरात म्हटले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"कविता म्हणण्याच्या कोणत्या दोन पद्धती मजकुरात सुचवल्या आहेत?\",\"options\":[\"हळू आणि जोरात\",\"वैयक्तिक आणि सामूहिक\",\"लिहून आणि वाचून\",\"बसून आणि उभे राहून\"],\"answer\":1,\"explain\":\"विद्यार्थ्यांना वैयक्तिक व सामूहिकरीत्या कविता म्हणायला सांगावे, असे मजकुरात दिले आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"नामाचा सराव प्रभावी होण्यासाठी शिक्षकांनी काय करावे?\",\"options\":[\"कठोर शिक्षा करावी\",\"वेगवेगळ्या प्रकारच्या कृती करून घ्याव्यात\",\"फक्त गृहपाठ द्यावा\",\"काहीही करू नये\"],\"answer\":1,\"explain\":\"सरावासाठी वेगवेगळ्या प्रकारच्या कृती करून घ्याव्यात असे मजकुरात नमूद आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"शिक्षकांनी विद्यार्थ्यांना नामाची ओळख करून दिल्यावर पुढची पायरी कोणती असावी?\",\"options\":[\"कविता पाठ करणे\",\"नवीन शब्द शोधणे\",\"वाक्यांतील नाम व नामाचे प्रकार ओळखणे\",\"चित्रे रंगवणे\"],\"answer\":2,\"explain\":\"नामाची ओळख करून दिल्यावर वाक्यांतील नाम व प्रकार ओळखण्याचा सराव करणे ही पुढची पायरी आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"कवितेचा \'भावार्थ\' समजावून सांगणे म्हणजे काय?\",\"options\":[\"कवितेतील शब्दांची संख्या मोजणे\",\"कवितेचा अर्थ आणि त्यातील भावना स्पष्ट करणे\",\"कवितेचे हस्ताक्षर सुधारणे\",\"कविता पाठ करणे\"],\"answer\":1,\"explain\":\"भावार्थ म्हणजे कवितेचा गर्भित अर्थ आणि त्यातील भावना समजून सांगणे होय.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरानुसार, शिक्षकांचे मुख्य कार्य काय आहे?\",\"options\":[\"केवळ कविता वाचून दाखवणे\",\"विद्यार्थ्यांना मार्गदर्शन करणे आणि सराव करून घेणे\",\"विद्यार्थ्यांना फक्त खेळायला सांगणे\",\"कवितेचे पाठांतर घेणे\"],\"answer\":1,\"explain\":\"मजकुरानुसार शिक्षकांनी मार्गदर्शन करणे, अर्थ समजावणे आणि सराव करून घेणे अपेक्षित आहे.\",\"topic\":\"शिक्षकांसाठी\",\"part\":10,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (21803,33,6,'Marathi','mr','राष्ट्रध्वज माझा अभिमान','[\"राष्ट्रध्वज म्हणजे देशाचा प्रतीक, अभिमानाचा प्रतीक.\",\"राष्ट्रध्वजात तीन रंग: केशरी, पांढरा, हिरवा.\",\"केशरी रंग त्याग व शोर्य दर्शवतो.\",\"पांढरा रंग शांतता व सत्याचे प्रतीक आहे.\",\"हिरवा रंग समृद्धी व निसर्गाचे प्रतीक मानला जातो.\",\"मध्यभागात निळ्या रंगाचे अशोकचक्र असतो.\",\"अशोकचक्र प्रगतीचा आणि सतत पुढे जाण्याचा संदेश देते.\",\"स्वातंत्र्यदिन व प्रजासत्ताकदिन राष्ट्रीय सणे आहेत.\",\"राष्ट्रीय सणांमध्ये राष्ट्रध्वज फडकताना प्रत्येक भारतीयाचा हृदय आनंदाने भरतो.\",\"सैनिक राष्ट्रध्वजासाठी प्राण अर्पण करतात.\",\"राष्ट्रध्वजाचा आदर करणे प्रत्येक नागरिकाचा कर्तव्य आहे.\",\"राष्ट्रध्वज एकता, देशभक्ती व राष्ट्रसेवा यांची प्रेरणा देतो.\",\"सर्व भारतीयांमध्ये \'राष्ट्रध्वज माझा अभिमान\' ही भावना दिसते.\",\"राष्ट्रध्वज पाहिल्याने देशप्रेमाची भावना जागृत होते.\",\"राष्ट्रध्वज आपल्याला एकता व देशसेवेचा संदेश देते.\"]','[{\"q\":\"\'राष्ट्रध्वज माझा अभिमान\' या पाठाच्या लेखिका कोण आहेत?\",\"options\":[\"स्वप्न गोवेकर\",\"शांता शेळके\",\"बहिणाबाई चौधरी\",\"विजया वाड\"],\"answer\":0,\"explain\":\"पाठाच्या सुरुवातीला दिलेल्या लेखिका परिचयानुसार स्वप्न गोवेकर या या पाठाच्या लेखिका आहेत.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"स्वप्न गोवेकर यांचा \'जागरूकता\' हा कथासंग्रह कोणत्या वर्षी प्रसिद्ध झाला?\",\"options\":[\"२०१४\",\"२०१५\",\"२०१६\",\"२०१७\"],\"answer\":1,\"explain\":\"परिचयानुसार २०१५ मधील ‘जागरूकता’ हा कथासंग्रह प्रसिद्ध झाला आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"\'काव्यरंग\' या काव्यसंग्रहासाठी लेखिकेला कोणत्या परिषदेचा पुरस्कार मिळाला?\",\"options\":[\"महाराष्ट्र साहित्य परिषद\",\"विदर्भ साहित्य संघ\",\"कोकण मराठी साहित्य परिषद\",\"मराठवाडा साहित्य परिषद\"],\"answer\":2,\"explain\":\"लेखिकेला कोकण मराठी साहित्य परिषदेच्या राज्यस्तरीय पुरस्काराने सन्मानित करण्यात आले आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"हा पाठ मूळतः कोणत्या मासिकातून घेण्यात आला आहे?\",\"options\":[\"बालभारती\",\"किशोर\",\"लोकराज्य\",\"साप्ताहिक सकाळ\"],\"answer\":1,\"explain\":\"हा पाठ ‘किशोर’ जानेवारी २०१६ या मासिकातून घेण्यात आलेला आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"प्रस्तुत पाठात कोणत्या स्पर्धेच्या माध्यमातून मुलांचा राष्ट्रध्वजाविषयीचा अभिमान दिसून येतो?\",\"options\":[\"चित्रकला स्पर्धा\",\"निबंध स्पर्धा\",\"वक्तृत्व स्पर्धा\",\"क्रीडा स्पर्धा\"],\"answer\":2,\"explain\":\"पाठात वक्तृत्व स्पर्धेच्या माध्यमातून राष्ट्रध्वजाविषयीचा अभिमान प्रतिबिंबित होतो.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखिका स्वप्न गोवेकर यांचा २०१७ मध्ये कोणता संग्रह प्रसिद्ध झाला?\",\"options\":[\"जागरूकता\",\"काव्यरंग\",\"अभिमान\",\"देशभक्ती\"],\"answer\":1,\"explain\":\"२०१७ मधील ‘काव्यरंग’ हा काव्यसंग्रह प्रसिद्ध झाला आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मुलांच्या स्पर्धेच्या तयारीसाठी पालकांनी काय केल्याचे पाठात नमूद केले आहे?\",\"options\":[\"केवळ आर्थिक मदत\",\"परिश्रम व प्रोत्साहन\",\"शाळेत तक्रार\",\"स्पर्धेला विरोध\"],\"answer\":1,\"explain\":\"मुलांच्या स्पर्धेच्या तयारीसाठी पालकांनी दिलेले परिश्रम व प्रोत्साहन यांमुळे सुंदर निकाल लागल्याचे पाठात म्हटले आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला \'किशोर\' मासिकाचा जानेवारी २०१६ चा अंक मिळाला, तर त्यात तुम्हाला कोणता पाठ वाचायला मिळेल?\",\"options\":[\"जागरूकता\",\"काव्यरंग\",\"राष्ट्रध्वज माझा अभिमान\",\"कोकण साहित्य\"],\"answer\":2,\"explain\":\"हा पाठ \'किशोर\' जानेवारी २०१६ च्या मासिकातून घेतल्यामुळे तो तिथे उपलब्ध असेल.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लेखिका परिचयानुसार, लेखिकेच्या कोणत्या कार्यामुळे त्यांना राज्यस्तरीय पुरस्कार मिळाला असावा?\",\"options\":[\"वक्तृत्व स्पर्धेचे आयोजन केल्यामुळे\",\"कथासंग्रहाच्या विक्रीमुळे\",\"उत्कृष्ट साहित्य निर्मिती (काव्यरंग) मुळे\",\"शिक्षिका म्हणून काम केल्यामुळे\"],\"answer\":2,\"explain\":\"‘काव्यरंग’ या पुस्तकासाठी (साहित्य निर्मितीसाठी) त्यांना राज्यस्तरीय पुरस्काराने सन्मानित करण्यात आले आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"पाठाच्या ओळखीनुसार, या पाठाचा मुख्य उद्देश काय असावा?\",\"options\":[\"केवळ वक्तृत्व कलेची माहिती देणे\",\"मुलांच्या मनातील राष्ट्रध्वजाविषयीचा अभिमान व्यक्त करणे\",\"कोकण साहित्य परिषदेची माहिती देणे\",\"कथासंग्रह कसा लिहावा हे सांगणे\"],\"answer\":1,\"explain\":\"पाठातून राष्ट्रध्वजाविषयी मुलांच्या मनामध्ये असणारा अभिमान प्रतिबिंबित करणे हा मुख्य उद्देश आहे.\",\"topic\":\"लेखिका परिचय व पाठाची ओळख\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"शाळेतील वक्तृत्व स्पर्धेचा विषय काय होता?\",\"options\":[\"माझा देश\",\"राष्ट्रध्वज माझा अभिमान\",\"२६ जानेवारी\",\"माझा आवडता नेता\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच स्पर्धेचा विषय \'राष्ट्रध्वज माझा अभिमान\' असा दिला आहे.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"वक्तृत्व स्पर्धेचे परीक्षक कोण होते?\",\"options\":[\"श्री. देसाई सर\",\"श्री. सुपेकर सर\",\"श्री. जाधव सर\",\"श्री. श्रीधर सर\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट उल्लेख आहे की स्पर्धेचे परीक्षक श्री. जाधव सर होते.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"वक्तृत्व स्पर्धेत प्रथम क्रमांक कोणाला मिळाला?\",\"options\":[\"अभिषेक देसाई\",\"श्रेया सुपेकर\",\"जाधव सर\",\"श्रीधर देसाई\"],\"answer\":1,\"explain\":\"उताऱ्यात दिलेल्या निकालाप्रमाणे प्रथम क्रमांक श्रेया सुपेकर हिला मिळाला.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"तालुका स्तरावरील स्पर्धा कोणत्या दिवशी होणार होती?\",\"options\":[\"१५ ऑगस्ट\",\"१ मे\",\"२ ऑक्टोबर\",\"२६ जानेवारी\"],\"answer\":3,\"explain\":\"जाधव सरांनी सांगितले की तालुका स्तरावर २६ जानेवारी रोजी स्पर्धा होणार आहे.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"तालुका स्तरावरील स्पर्धेसाठी कोणत्या क्रमांकांच्या विद्यार्थ्यांची निवड करण्यात आली?\",\"options\":[\"केवळ प्रथम\",\"प्रथम आणि द्वितीय\",\"प्रथम, द्वितीय आणि तृतीय\",\"सहभागी सर्व विद्यार्थी\"],\"answer\":1,\"explain\":\"जाधव सरांच्या म्हणण्यानुसार केवळ प्रथम आणि द्वितीय क्रमांकाच्या विद्यार्थ्यांना तालुका स्तरावर संधी मिळणार होती.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यातील \'स्वारी काहीशी हिरमुसली होती\' या वाक्याचा अर्थ काय?\",\"options\":[\"अभिषेक खूप आनंदी होता\",\"अभिषेकला राग आला होता\",\"अभिषेक थोडा नाराज होता\",\"अभिषेकला भीती वाटत होती\"],\"answer\":2,\"explain\":\"हिरमुसले होणे म्हणजे नाराज किंवा खिन्न होणे.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जाधव सरांच्या मते, स्पर्धेत यश मिळवण्यासाठी विद्यार्थ्यांनी काय करायला हवे?\",\"options\":[\"केवळ स्पर्धेत भाग घ्यावा\",\"भरपूर मेहनत घेऊन गुण विकसित करावेत\",\"फक्त निकालाची वाट पाहावी\",\"दुसऱ्यांशी स्पर्धा करावी\"],\"answer\":1,\"explain\":\"सरांनी सांगितले की गुण विकसित करण्यासाठी प्रत्येकाने भरपूर मेहनत घ्यायला हवी.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात मुलगा व्यासपीठावर उभा राहून काय करत आहे?\",\"options\":[\"गाणे गात आहे\",\"कविता वाचत आहे\",\"भाषण करत आहे\",\"चित्र काढत आहे\"],\"answer\":2,\"explain\":\"चित्रात मुलगा माईकसमोर उभा राहून वक्तृत्व स्पर्धेत भाषण करताना दिसत आहे.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"understand\",\"figure_image\":\"33\\/034_101.jpg\"},{\"q\":\"अभिषेकला तालुका स्तरावर पहिला नंबर काढण्यासाठी त्याच्या वडिलांनी काय आश्वासन दिले?\",\"options\":[\"त्याला नवीन पुस्तक देण्याचे\",\"त्याची तयारी करून घेण्याचे\",\"त्याला बक्षीस देण्याचे\",\"त्याला सहलीला नेण्याचे\"],\"answer\":1,\"explain\":\"वडील म्हणाले की \'आम्ही तुझी तयारी करून घेऊ\', म्हणजेच त्यांनी तयारीचे आश्वासन दिले.\",\"topic\":\"शालेय वक्तृत्व स्पर्धा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात व्यासपीठावर (स्टेजवर) बसलेले लोक कोण असावेत?\",\"options\":[\"अभिषेकचे मित्र\",\"शाळेचे शिपाई\",\"स्पर्धेचे परीक्षक कि