om\":\"understand\"},{\"q\":\"रोहनच्या आई-वडिलांना प्रथमच विमानाने कोठे जाता आले?\",\"options\":[\"मुंबईला\",\"बीडला\",\"दिल्लीला\",\"पुण्याला\"],\"answer\":2,\"explain\":\"पुरस्कार घेण्यासाठी रोहनचे आई-वडील विमानाने दिल्लीला गेले.\",\"topic\":\"धाडसी रोहनची शौर्यगाथा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"रोहनने महिलेचे प्राण वाचवले, यामागे त्याचे कोणते कौशल्य सर्वात महत्त्वाचे ठरले?\",\"options\":[\"सायकल चालवणे\",\"नदीत पोहायला येणे\",\"अभ्यास करणे\",\"धावणे\"],\"answer\":1,\"explain\":\"रोहनला नदीत पोहायला खूप आवडत होते, याच कौशल्यामुळे तो महिलेला वाचवू शकला.\",\"topic\":\"धाडसी रोहनची शौर्यगाथा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"रोहनच्या मते, त्याच्या हातून हे धाडसी कृत्य का घडले?\",\"options\":[\"त्याला बक्षीस हवे होते\",\"त्याला प्रसिद्धी हवी होती\",\"आईवडिलांनी केलेल्या मदतीच्या संस्कारामुळे\",\"त्याला विमानाने फिरायचे होते\"],\"answer\":2,\"explain\":\"दुसऱ्याला मदत करण्याचा संस्कार आईवडिलांनी केला, असे रोहनने सांगितले.\",\"topic\":\"धाडसी रोहनची शौर्यगाथा\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"डॉ. संजय तांदळे यांनी रोहनचे कौतुक कशा प्रकारे केले?\",\"options\":[\"त्याला सायकल भेट दिली\",\"त्याला ५०० रुपये दिले\",\"दप्तर, पुस्तके आणि पुष्पगुच्छ देऊन सत्कार केला\",\"त्याला डॉक्टर बनवले\"],\"answer\":2,\"explain\":\"डॉ. तांदळे यांनी रोहनला शैक्षणिक साहित्य आणि पुष्पगुच्छ देऊन गौरविले.\",\"topic\":\"धाडसी रोहनची शौर्यगाथा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'कौतुक\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"प्रशंसा\",\"बक्षीस\",\"साहस\",\"प्रवाह\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार \'कौतुक\' म्हणजे \'प्रशंसा\' होय.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"वाक्याचा अर्थ पूर्ण करणाऱ्या क्रियावाचक शब्दाला काय म्हणतात?\",\"options\":[\"कर्ता\",\"कर्म\",\"क्रियापद\",\"विशेषण\"],\"answer\":2,\"explain\":\"वाक्याचा अर्थ पूर्ण करणाऱ्या शब्दाला क्रियापद म्हणतात.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'वैभव आंबा खातो\'