loom\":\"apply\"},{\"q\":\"\'आर्या लाडू खाते\' या वाक्यात \'खाते\' हे कोणत्या प्रकारचे क्रियापद आहे?\",\"options\":[\"अकर्मक\",\"सकर्मक\",\"नाम\",\"विशेषण\"],\"answer\":1,\"explain\":\"या वाक्यात \'लाडू\' हे कर्म असल्याने \'खाते\' हे सकर्मक क्रियापद आहे.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'शौर्य\' या शब्दाचा समानार्थी शब्द कोणता?\",\"options\":[\"भित्रेपणा\",\"साहस\",\"शांतता\",\"आनंद\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील शब्दार्थानुसार शौर्य म्हणजे साहस किंवा धाडस.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"\'किती सुंदर भाषण केले आज सुमनने!\' या वाक्यातील क्रियापद ओळखा.\",\"options\":[\"सुंदर\",\"भाषण\",\"केले\",\"सुमनने\"],\"answer\":2,\"explain\":\"या वाक्यात \'केले\' हे क्रियापद आहे जे सुरुवातीच्या भागात आले आहे.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"पुढीलपैकी सकर्मक वाक्य कोणते?\",\"options\":[\"रमेश उठतो.\",\"अभय पुस्तक वाचतो.\",\"तो बसला.\",\"ती हसली.\"],\"answer\":1,\"explain\":\"\'अभय पुस्तक वाचतो\' यात \'पुस्तक\' हे कर्म असल्याने ते सकर्मक वाक्य आहे.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'गौरव लिहितो\' या वाक्याचा अर्थ पूर्ण का वाटत नाही?\",\"options\":[\"कारण यात कर्ता नाही.\",\"कारण यात क्रियापद नाही.\",\"कारण यात कर्म दिलेले नाही.\",\"कारण वाक्य खूप छोटे आहे.\"],\"answer\":2,\"explain\":\"\'लिहितो\' या सकर्मक क्रियापदाला अर्थ पूर्ण करण्यासाठी कर्माची (उदा. पत्र) गरज असते.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"वाक्यातील कर्ता, कर्म व क्रियापद यांची मांडणी नेहमी एकाच क्रमाने येते का?\",\"options\":[\"हो, नेहमी कर्ता आधीच येतो.\",\"नाही, त्यांचा क्रम बदलू शकतो.\",\"हो, क्रियापद नेहमी शेवटीच येते.\",\"नाही, कर्म कधीच सुरुवातीला येत नाही.\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार कर्ता, कर्म व क्रियापद यांचा क्रम वाक्यात बदलू शकतो.\",\"topic\":\"क्रियापदे व सकर्मक क्रियापद\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"ज्या वेळी वाक्यातील क्रियापदाला कर्माची गरज लागत नाही, तेव्हा त्यास काय म्हणतात?\",\"options\":[\"सकर्मक क्रियापद\",\"अकर्मक क्रियापद\",\"संयुक्त क्रियापद\",\"सहायक क्रियापद\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, कर्माची गरज नसलेल्या क्रियापदाला \'अकर्मक क्रियापद\' म्हणतात.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"\'मी उद्या पुण्याला जाईन\' या वाक्यात \'पुण्याला\' हे काय नाही?\",\"options\":[\"नाम\",\"क्रियापद\",\"कर्म\",\"कर्ता\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की \'पुण्याला\' हे \'जाईन\' या क्रियापदाचे कर्म नाही.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'गाई झाडाखाली थांबल्या\' या वाक्यातील क्रियापद कोणते आहे?\",\"options\":[\"गाई\",\"झाडाखाली\",\"थांबल्या\",\"झाड\"],\"answer\":2,\"explain\":\"वाक्याच्या शेवटी येणारा आणि क्रिया दर्शवणारा शब्द \'थांबल्या\' हे क्रियापद आहे.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"\'आज गुढीपाडवा आहे\' या वाक्यातील क्रियापद कोणत्या प्रकारचे आहे?\",\"options\":[\"सकर्मक\",\"अकर्मक\",\"नाम\",\"विशेषण\"],\"answer\":1,\"explain\":\"येथे \'आहे\' हे क्रियापद कर्मरहित आहे, म्हणून ते अकर्मक आहे.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"अकर्मक क्रियापद म्हणजे काय?\",\"options\":[\"ज्याला दोन कर्मे असतात\",\"ज्याला कर्माची गरज असते\",\"ज्याला कर्म नसते\",\"ज्याला कर्ता नसतो\"],\"answer\":2,\"explain\":\"ज्या क्रियापदाला कर्म नसते, त्याला अकर्मक क्रियापद म्हणतात.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी अकर्मक क्रियापदाचे उदाहरण कोणते?\",\"options\":[\"मी आंबा खातो\",\"गाई झाडाखाली थांबल्या\",\"त्याने पत्र लिहिले\",\"राम पुस्तक वाचतो\"],\"answer\":1,\"explain\":\"उताऱ्यातील उदाहरणाप्रमाणे \'थांबल्या\' हे अकर्मक क्रियापद आहे.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अकर्मक क्रियापदात क्रिया कोणावर घडते?\",\"options\":[\"कर्मावर\",\"कोणत्याही वस्तूवर घडत नाही\",\"फक्त झाडावर\",\"फक्त पुण्यावर\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की, असण्याची क्रिया कोणत्याही वस्तूवर घडत नाही.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'मी उद्या पुण्याला जाईन\' या वाक्यात क्रियापदाचा अर्थ पूर्ण करण्यासाठी कशाची गरज नाही?\",\"options\":[\"कर्त्याची\",\"कर्माची\",\"क्रियापदाची\",\"शब्दांची\"],\"answer\":1,\"explain\":\"अकर्मक क्रियापदांना अर्थ पूर्ण करण्यासाठी कर्माची गरज लागत नाही.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"वाक्यातील क्रियापदाला अर्थ पूर्ण करण्यासाठी कर्माची गरज लागत नाही, हे विधान कोणासाठी लागू होते?\",\"options\":[\"सकर्मक क्रियापद\",\"अकर्मक क्रियापद\",\"विशेषण\",\"सर्वनाम\"],\"answer\":1,\"explain\":\"हे अकर्मक क्रियापदाचे मुख्य लक्षण आहे.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यातील उदाहरणांनुसार \'आहे\' हे क्रियापद काय सांगते?\",\"options\":[\"ते सकर्मक आहे\",\"ते कर्मरहित आहे\",\"ते कर्मासह आहे\",\"ते चुकीचे आहे\"],\"answer\":1,\"explain\":\"उताऱ्यात \'आहे\' हे क्रियापद कर्मरहित असल्याचे सांगितले आहे.\",\"topic\":\"अकर्मक क्रियापद\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"धातूसाधित व सहायक क्रियापद मिळून काय तयार होते?\",\"options\":[\"नाम\",\"विशेषण\",\"संयुक्त क्रियापद\",\"अव्यय\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे दिले आहे की धातूसाधित व सहायक क्रियापद मिळून संयुक्त क्रियापद होते.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'मीना गोष्ट सांगत आहे\' या वाक्यात \'आहे\' हे कोणते क्रियापद आहे?\",\"options\":[\"मुख्य क्रियापद\",\"सहायक क्रियापद\",\"धातूसाधित\",\"विशेषण\"],\"answer\":1,\"explain\":\"वाक्याचा अर्थ पूर्ण करण्यासाठी \'सांगत\' या धातूसाधिताला \'आहे\' या क्रियापदाची मदत घ्यावी लागली आहे, म्हणून ते सहायक क्रियापद आहे.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"वाक्याचा अर्थ पूर्ण करण्यासाठी धातूसाधिताला कोणाची मदत घ्यावी लागते?\",\"options\":[\"नामाची\",\"सर्वनामाची\",\"सहायक क्रियापदाची\",\"विभक्तीची\"],\"answer\":2,\"explain\":\"वाक्याचा अर्थ पूर्ण होण्यासाठी धातूसाधिताच्या जोडीला सहायक क्रियापद वापरावे लागते.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'सांगत\' या शब्दाने वाक्याचा अर्थ पूर्ण का होत नाही?\",\"options\":[\"कारण तो शब्द नाम आहे\",\"कारण ते धातूसाधित आहे\",\"कारण ते सहायक क्रियापद आहे\",\"कारण तो शब्द अव्यय आहे\"],\"answer\":1,\"explain\":\"धातूसाधिताने वाक्याचा अर्थ पूर्ण होत नाही, त्यासाठी सहायक क्रियापदाची गरज असते.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'दुर्गीने सर्व अभ्यास करून टाकला\' या वाक्यातील संयुक्त क्रियापद ओळखा.\",\"options\":[\"दुर्गीने\",\"अभ्यास\",\"करून\",\"करून टाकला\"],\"answer\":3,\"explain\":\"धातूसाधित (करून) आणि सहायक क्रियापद (टाकला) मिळून \'करून टाकला\' हे संयुक्त क्रियापद तयार झाले आहे.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या सारणीनुसार \'कर\' या मुख्य धातूचे धातूसाधित कोणते आहे?\",\"options\":[\"करतो\",\"करून\",\"केला\",\"करणार\"],\"answer\":1,\"explain\":\"सारणीमध्ये \'कर\' या धातूसाठी \'करून\' हे धातूसाधित दिले आहे.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या शब्दाला \'सहायक क्रियापद\' म्हणता येईल?\",\"options\":[\"सांगत\",\"करून\",\"असेल\",\"दिसत\"],\"answer\":2,\"explain\":\"दिलेल्या उदाहरणांमध्ये \'असेल\' हे धातूसाधिताला मदत करणारे सहायक क्रियापद आहे.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर \'दिस\' हा मुख्य धातू असेल, तर \'दिसत + असेल\' यापासून कोणते संयुक्त क्रियापद तयार होईल?\",\"options\":[\"दिसत असेल\",\"दिसणार आहे\",\"दिसला होता\",\"दिसत नाही\"],\"answer\":0,\"explain\":\"सारणीनुसार \'दिसत + असेल\' मिळून \'दिसत असेल\' हे संयुक्त क्रियापद तयार होते.\",\"topic\":\"सहायक व संयुक्त क्रियापद\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"\'सांगत आहे\' या संयुक्त क्रियापदातील \'सांगत\' हा शब्द कोणत्या क्रियापदाऐवजी वापरला आहे?\",\"options\":[\"बोलणे\",\"सांगणे\",\"ऐकणे\",\"पाह