m\":\"analyze\"},{\"q\":\"माणूस हवेतून कोणता वायू घेतो?\",\"options\":[\"विषारी वायू\",\"धूर\",\"प्राणवायू\",\"नत्रवायू\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे दिले आहे की माणूस हवेतून प्राणवायू घेतो.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"जमिनीतून अन्न मिळवल्यावर माणूस तिला बदल्यात काय देतो?\",\"options\":[\"शुद्ध पाणी\",\"जळजळीत रासायनिक खतं\",\"सेंद्रिय खत\",\"कच्चा माल\"],\"answer\":1,\"explain\":\"मजकुरात म्हटले आहे की माणूस जमिनीला जळजळीत रासायनिक खतं देतो.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"निसर्गाच्या बाबतीत इतर प्राणी आणि माणूस यांच्यात कोणता मुख्य फरक आहे?\",\"options\":[\"प्राणी शोषण करतात, माणूस पोषण करतो\",\"प्राणी आणि माणूस दोघेही पोषण करतात\",\"प्राणी पोषण करतात, माणूस शोषण करतो\",\"दोघेही फक्त निसर्गाकडून घेतात\"],\"answer\":2,\"explain\":\"मजकुराच्या शेवटी दिले आहे की सर्व प्राणी निसर्गाचे पोषण करतात, पण माणूस त्याचे शोषण करतो.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"माणूस शुद्ध पाण्याचा उपयोग करून त्यात काय सोडतो?\",\"options\":[\"प्राणवायू\",\"अन्न\",\"घातक व विषारी रसायने\",\"कच्चा माल\"],\"answer\":2,\"explain\":\"मजकुरात पाण्याचा उपयोग करून त्यात घातक, विषारी रसायने सोडल्याचा उल्लेख आहे.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एखाद्या कारखान्याने नदीत सांडपाणी सोडणे, हे मजकुरातील कोणत्या कृतीचे उदाहरण आहे?\",\"options\":[\"हवेत धूर सोडणे\",\"पाण्यात विषारी रसायने सोडणे\",\"जमिनीतून अन्न मिळवणे\",\"खाणी खणणे\"],\"answer\":1,\"explain\":\"नदीत सांडपाणी सोडणे ही कृती मजकुरातील \'पाण्यात विषारी रसायने सोडणे\' या विधानाला लागू होते.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"माणूस जंगलंच्या जंगलं कशासाठी साफ करतो?\",\"options\":[\"प्राण्यांना राहण्यासाठी\",\"लाकडासाठी\",\"हवा शुद्ध करण्यासाठी\",\"पाणी मिळवण्यासाठी\"],\"answer\":1,\"explain\":\"मजकुरात \'लाकडासाठी जंगलंच्या जंगलं साफ करायची\' असे स्पष्ट दिले आहे.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात माणसे कोणती कृती करताना दिसत आहेत?\",\"options\":[\"झाडे लावत आहेत\",\"जंगल साफ करत आहेत\",\"खाणी खणत आहेत\",\"शेती करत आहेत\"],\"answer\":1,\"explain\":\"चित्रात दोन माणसे कुऱ्हाडीने झाड तोडताना दिसत आहेत, ज्याला मजकुरात जंगल साफ करणे म्हटले आहे.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"33\\/084_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील कृतीतून माणसाचा निसर्गाप्रती कोणता स्वभाव दिसून येतो?\",\"options\":[\"निसर्गाचे पोषण करणे\",\"निसर्गाचे रक्षण करणे\",\"निसर्गाचे शोषण करणे\",\"निसर्गाची दया करणे\"],\"answer\":2,\"explain\":\"झाडे तोडणे ही कृती मजकुराप्रमाणे माणसाच्या निसर्गावरील शोषणाचे उदाहरण आहे.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"evaluate\",\"figure_image\":\"33\\/084_101.jpg\"},{\"q\":\"मजकुरात वापरलेल्या \'खाक्या\' या शब्दाचा अर्थ काय असावा?\",\"options\":[\"वागण्याची विशिष्ट पद्धत\",\"निसर्गावर केलेले प्रेम\",\"प्राण्यांना दिलेली मदत\",\"जमिनीची सुपीकता\"],\"answer\":0,\"explain\":\"\'खाक्या\' म्हणजे माणसाची फक्त घेण्याची आणि घातक गोष्टी देण्याची बनलेली पद्धत किंवा वृत्ती.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एखाद्या ठिकाणचा कच्चा माल संपल्यावर माणूस त्या खाणींचे काय करतो?\",\"options\":[\"त्या बुजवून टाकतो\",\"त्या तशाच सोडून देतो\",\"तिथे नवीन झाडे लावतो\",\"तिथे पाणी साठवतो\"],\"answer\":1,\"explain\":\"मजकुरात दिले आहे की कच्चा माल संपल्यावर माणूस खाणी तशाच सोडून देतो.\",\"topic\":\"मानवाचा हव्यास आणि शोषण\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"निसर्गाचा किंवा पर्यावरणाचा तोल कोणाच्या वागण्यामुळे ढासळून गेला आहे?\",\"options\":[\"प्राण्यांच्या\",\"पक्ष्यांच्या\",\"माणसाच्या\",\"सूक्ष्मजीवांच्या\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की माणसाच्या वागण्यामुळेच निसर्गाचा तोल ढासळला आहे.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"सूक्ष्मजीव, किडे, पक्षी, प्राणी आणि वनस्पती यांच्यातील परस्परसंबंधांना काय म्हटले आहे?\",\"options\":[\"परस्परविरोध\",\"परस्परपूरकता\",\"परस्परस्पर्धा\",\"परस्परअवलंबित्व\"],\"answer\":1,\"explain\":\"उताऱ्यात या सजीवांच्या परस्परसंबंधांना \'परस्परपूरकता\' असे म्हटले आहे.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मानवेतर सजीव पर्यावरणासाठी कशा प्रकारे काम करतात?\",\"options\":[\"पर्यावरणाला घातक ठरेल अशा\",\"पर्यावरणाला पोषक ठरेल अशा\",\"केवळ स्वतःचा विचार करून\",\"निसर्गाला हानी पोहोचवून\"],\"answer\":1,\"explain\":\"मानवेतर सजीव एकत्रपणे विचार केला तर पर्यावरणाला पोषक अशा प्रकारानं काम करतात.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"निसर्गातील चक्रे अखंडितपणे काम का करतात?\",\"options\":[\"मानवाच्या हस्तक्षेपामुळे\",\"कारखान्यांमुळे\",\"सजीवांच्या देणे-घेणे प्रक्रियेमुळे\",\"केवळ पावसामुळे\"],\"answer\":2,\"explain\":\"सजीव निसर्गाकडून काही घेतात आणि देतातही, त्यामुळे निसर्गातील चक्रे अखंडितपणे काम करतात.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात उल्लेखिलेल्या \'अतूट\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"कधीही न तुटणारी\",\"सहज तुटणारी\",\"कमकुवत\",\"विखुरलेली\"],\"answer\":0,\"explain\":\"पर्यावरणातल्या साखळ्या अखंड राहतात म्हणजेच त्या \'अतूट\' (न तुटणाऱ्या) राहतात.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर सजीवांनी निसर्गाला काहीही परत दिले नाही, तर उताऱ्यानुसार काय परिणाम होईल?\",\"options\":[\"निसर्गाची चक्रे अधिक वेगाने फिरतील\",\"पर्यावरणाचा तोल अधिक सुधारेल\",\"निसर्गातील चक्रे आणि साखळ्या खंडित होतील\",\"प्राण्यांची संख्या वाढेल\"],\"answer\":2,\"explain\":\"सजीवांच्या देणे-घेणे प्रक्रियेमुळेच चक्रे अखंडित राहतात; ती थांबल्यास साखळ्या खंडित होतील.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात मानवाच्या कोणत्या कृतीमुळे पर्यावरणाचा तोल ढासळताना दिसत आहे?\",\"options\":[\"वृक्षारोपण केल्यामुळे\",\"वाहने आणि कारखान्यांच्या प्रदूषणामुळे\",\"नदीची स्वच्छता केल्यामुळे\",\"सायकलचा वापर केल्यामुळे\"],\"answer\":1,\"explain\":\"चित्रात वाहनांचा धूर, कारखान्यांचा धूर आणि पाण्यात सोडलेले सांडपाणी (प्रदूषण) दिसत आहे.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"33\\/084_103.jpg\"},{\"q\":\"दिलेल्या चित्रातील परिस्थितीमुळे उताऱ्यात उल्लेखिलेल्या कोणत्या गोष्टीवर सर्वात वाईट परिणाम होईल?\",\"options\":[\"इमारतींच्या रंगावर\",\"रस्त्यावरील वाहनांच्या वेगावर\",\"निसर्गाचा समतोल आणि परस्परपूरकतेवर\",\"शहरातील दुकानांच्या संख्येवर\"],\"answer\":2,\"explain\":\"प्रदूषणामुळे निसर्गाचा समतोल बिघडतो, ज्याचा परिणाम सजीवांच्या परस्परपूरकतेवर होतो.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"evaluate\",\"figure_image\":\"33\\/084_103.jpg\"},{\"q\":\"पर्यावरणातील साखळ्या अतूट राहण्यासाठी खालीलपैकी काय आवश्यक आहे?\",\"options\":[\"जास्तीत जास्त कारखाने उभारणे\",\"सजीवांमधील परस्परसंबंध टिकून राहणे\",\"नद्यांमध्ये कचरा टाकणे\",\"शहरात वाहनांची संख्या वाढवणे\"],\"answer\":1,\"explain\":\"सजीवांच्या परस्परसंबंधांमुळेच पर्यावरणातील साखळ्या अतूट राहतात.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मानवेतर सजीवांच्या बाबतीत \'देणे आणि घेणे\' या क्रियेचा मुख्य फायदा काय होतो?\",\"options\":[\"केवळ माणसाला फायदा होतो\",\"निसर्गातील विविध चक्रे अखंडित राहतात\",\"प्राणी आळशी होतात\",\"निसर्गाचा तोल ढासळतो\"],\"answer\":1,\"explain\":\"सजीवांच्या देणे-घेणे प्रक्रियेमुळे निसर्गातील विविध चक्रे अखंडितपणे काम करतात.\",\"topic\":\"निसर्गाचा समतोल आणि परस्परपूरकता\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"माधवकाका कोणाशी संवाद साधत आहेत?\",\"options\":[\"इतर विचारवंतांशी\",\"गावातील लोकांशी\",\"शाळेतील मुलांशी\",\"कारखान्यातील कामगारांशी\"],\"answer\":2,\"explain\":\"उताऱ्याच्या शेवटी \'मुले विचारांत गढून गेली\' असे म्हटले आहे, ज्यावरून माधवकाका मुलांशी बोलत असल्याचे समजते.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"माणसाला लाकडाच्या रूपातल्या कच्च्या मालासाठी काय हवे आहे?\",\"options\":[\"शेती\",\"जंगलं\",\"कारखाने\",\"नद्या\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की, आपल्याला जंगलं हवीत ती लाकडाच्या रूपातल्या कच्च्या मालासाठी.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"आजचे विचारवंत कोणत्या गोष्टीमुळे व्यथित झाले आहेत?\",\"options\":[\"माणसाच्या निसर्गाकडून केवळ घेण्याच्या सवयीमुळे\",\"मुलांच्या वागण्यामुळे\",\"जंगलांच्या वाढीमुळे\",\"नैसर्गिक साधनसंपत्तीच्या अतिवापरामुळे\"],\"answer\":0,\"explain\":\"माणसाच्या निसर्गाकडून केवळ घेण्याच्या सवयीमुळे आजचे विचारवंत व्यथित झाले आहेत.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"निसर्गाची खंडित झालेली चक्रं आणि तुटलेल्या साखळ्या यांचे दुष्परिणाम कधीपासून तीव्रतेने जाणवू लागले आहेत?\",\"options\":[\"गेल्या पन्नास वर्षांपासून\",\"गेल्या पाच वर्षांपासून\",\"गेल्या शंभर वर्षांपासून\",\"गेल्या दहा-वीस वर्षांपासून\"],\"answer\":3,\"explain\":\"उताऱ्यानुसार, हे दुष्परिणाम गेल्या दहा-वीस वर्षांपासून तीव्रतेने जाणवू लागले आहेत.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात उल्लेख केलेली \'उगवती पिढी\' म्हणजे कोण?\",\"options\":[\"वृद्ध माणसे\",\"आजची मुले\",\"विचारवंत\",\"शेतकरी\"],\"answer\":1,\"explain\":\"माधवकाका मुलांना उद्देशून \'तुम्ही मुलं उगवत्या पिढीतली आहात\' असे म्हणतात.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"माणूस निसर्गाबाबत कोणती महत्त्वाची गोष्ट विसरत चालला आहे?\",\"options\":[\"निसर्ग खूप मोठा आहे\",\"आपण निसर्गाचा एक घटक आहोत\",\"निसर्ग आपल्याला सर्व काही देतो\",\"निसर्गाचे रक्षण करणे कठीण आहे\"],\"answer\":1,\"explain\":\"माणूस आपण निसर्गाचा एक घटक आहोत हे विसरत चालला आहे, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात नदीच्या पाण्याचे प्रदूषण कशामुळे होताना दिसत आहे?\",\"options\":[\"पावसामुळे\",\"केवळ मासेमारीमुळे\",\"कारखान्यातून सोडलेले सांडपाणी आणि कचऱ्यामुळे\",\"नदीतील वनस्पतींमुळे\"],\"answer\":2,\"explain\":\"चित्रात कारखान्यातून एक मोठा पाईप नदीत सांडपाणी आणि कचरा सोडताना स्पष्ट दिसत आहे.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"33\\/084_102.jpg\"},{\"q\":\"दिलेल्या चित्रात दिसणारे कापलेले झाड (खोड) उताऱ्यातील कोणत्या विचाराशी संबंधित आहे?\",\"options\":[\"निसर्गचक्र पूर्ण करणे\",\"कच्च्या मालासाठी जंगलांचा वापर\",\"नवीन झाडे लावणे\",\"पर्यावरणाचे रक्षण करणे\"],\"answer\":1,\"explain\":\"चित्रातील कापलेले झाड हे माणसाच्या लाकडासाठी जंगल तोडण्याच्या (कच्चा माल मिळवण्याच्या) सवयीचे प्रतीक आहे.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"33\\/084_102.jpg\"},{\"q\":\"माणसाच्या वागण्यात कशाची कमतरता आहे असे लेखकाने म्हटले आहे?\",\"options\":[\"परस्परपूरकता\",\"स्वार्थीपणा\",\"वेगवानता\",\"बुद्धिमत्ता\"],\"answer\":0,\"explain\":\"उताऱ्याच्या सुरुवातीलाच म्हटले आहे की, माणसाच्या वागण्यात परस्परपूरकता नाही.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"भावी पिढीचे भवितव्य कोणाच्या हातात आहे?\",\"options\":[\"केवळ विचारवंतांच्या\",\"केवळ निसर्गाच्या\",\"उगवत्या पिढीच्या (मुलांच्या)\",\"केवळ कारखानदारांच्या\"],\"answer\":2,\"explain\":\"माधवकाका म्हणतात की, तुमच्या (मुलांच्या) भावी पिढीचे भवितव्य तुमच्याच हातात आहे.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"निसर्गाकडून \'केवळ घेण्याच्या\' सवयीमुळे काय निर्माण झाले आहे?\",\"options\":[\"खूप संपत्ती\",\"भविष्याविषयी चिंता\",\"निसर्गाचा आनंद\",\"नवीन जंगले\"],\"answer\":1,\"explain\":\"माणसाच्या केवळ घेण्याच्या सवयीमुळे भविष्याविषयी चिंता निर्माण झाली आहे, असे उताऱ्यात नमूद आहे.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"माधवकाकांचे बोलणे ऐकल्यावर मुलांच्या प्रतिक्रियेवरून काय समजते?\",\"options\":[\"मुलांना काहीच समजले नाही\",\"मुले खेळायला गेली\",\"मुले गंभीरपणे विचार करू लागली\",\"मुले रागावली\"],\"answer\":2,\"explain\":\"\'मुले विचारांत गढून गेली\' यावरून ती विषयाचे गांभीर्य समजून घेऊन विचार करू लागली असे समजते.\",\"topic\":\"भविष्याविषयी चिंता\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"\'मकरंद\' या शब्दाचा अर्थ काय?\",\"options\":[\"फुलांतील मध\",\"जंगलातील आग\",\"चिरेबंदी वाट\",\"पाण्याचा प्रवाह\"],\"answer\":0,\"explain\":\"दिलेल्या मजकुरानुसार, मकरंद म्हणजे फुलांतील मध होय.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जंगलात अचानक लागलेल्या आगीला काय म्हणतात?\",\"options\":[\"पाखाडी\",\"वणवा\",\"व्यथित\",\"मकरंद\"],\"answer\":1,\"explain\":\"मजकुरात वणवा म्हणजे जंगलात अचानक लागलेली आग असे दिले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'पाणि\' (न ला ऱ्हस्व वेलांटी) या शब्दाचा योग्य अर्थ ओळखा.\",\"options\":[\"जल\",\"नदी\",\"हात\",\"समुद्र\"],\"answer\":2,\"explain\":\"मजकुरानुसार पाणी म्हणजे जल, तर पाणि म्हणजे हात असा अर्थ होतो.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'दीन\' (द ला दीर्घ वेलांटी) या शब्दाचा अर्थ काय होतो?\",\"options\":[\"दिवस\",\"गरीब\",\"श्रीमंत\",\"दु:खी\"],\"answer\":1,\"explain\":\"मजकुरात दिन म्हणजे दिवस आणि दीन म्हणजे गरीब असे स्पष्ट केले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'सूत\' (स ला दीर्घ उकार) या शब्दाचा अर्थ खालीलपैकी कोणता?\",\"options\":[\"मुलगा\",\"धागा\",\"मित्र\",\"वडील\"],\"answer\":1,\"explain\":\"दिलेल्या माहितीनुसार सुत म्हणजे मुलगा आणि सूत म्हणजे धागा.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"एखादा माणूस खूप काळजीत असेल, तर मजकुरातील कोणत्या शब्दाने त्याचे वर्णन करता येईल?\",\"options\":[\"संचित\",\"व्यथित\",\"सचिंत\",\"खाक्या\"],\"answer\":2,\"explain\":\"सचिंत या शब्दाचा अर्थ मजकुरात \'चिंताग्रस्त\' असा दिला आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"\'चिरेबंदी अरुंद वाट\' या शब्दसमूहासाठी मजकुरात कोणता शब्द आला आहे?\",\"options\":[\"पाखाडी\",\"खाक्या\",\"वणवा\",\"मकरंद\"],\"answer\":0,\"explain\":\"पाखाडी या शब्दाचा अर्थ मजकुरात चिरेबंदी अरुंद वाट असा दिला आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शेतकऱ्याने शेतात धान्य पिकवले, तर त्या धान्यासाठी मजकुरातील कोणता योग्य शब्द वापरता येईल?\",\"options\":[\"पिक\",\"पीक\",\"संचित\",\"उपहार\"],\"answer\":1,\"explain\":\"पीक (दीर्घ ई) म्हणजे धान्य, तर पिक (ऱ्हस्व इ) म्हणजे कोकीळ असा फरक मजकुरात दिला आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"\'लक्ष\' या शब्दाचे मजकुरानुसार कोणते दोन अर्थ होतात?\",\"options\":[\"नेम आणि साध्य\",\"लाख आणि अवधान\",\"दिवस आणि गरीब\",\"भेट आणि फराळ\"],\"answer\":1,\"explain\":\"मजकुरात लक्ष म्हणजे लाख किंवा अवधान, तर लक्ष्य म्हणजे नेम किंवा साध्य असे दिले आहे.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"शब्दांच्या लेखनात काना, मात्रा किंवा वेलांटी बदलल्यास काय परिणाम होतो?\",\"options\":[\"शब्दाचा उच्चार बदलत नाही\",\"शब्दाचा अर्थ तोच राहतो\",\"शब्दाचा अर्थ बदलतो\",\"शब्दावर काहीही परिणाम होत नाही\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की स्वल्प-दीर्घ किंवा काना-मात्रेच्या फरकामुळे शब्दाचे अर्थ बदलतात.\",\"topic\":\"जाणून घेऊ या\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"भूतकाळ, वर्तमानकाळ व भविष्यकाळ या प्रत्येकाचे किती उपप्रकार आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"मजकुराच्या पहिल्या ओळीनुसार, प्रत्येक काळाचे ४ उपप्रकार आहेत.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'मी चित्र काढत आहे\' हे कोणत्या उपप्रकाराचे उदाहरण आहे?\",\"options\":[\"साधा वर्तमानकाळ\",\"अपूर्ण वर्तमानकाळ\",\"पूर्ण वर्तमानकाळ\",\"रीती वर्तमानकाळ\"],\"answer\":1,\"explain\":\"तक्त्यानुसार \'मी चित्र काढत आहे\' हे अपूर्ण वर्तमानकाळाचे उदाहरण आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"\'राघव कबड्डी खेळतो\' या वाक्याचे साधा भूतकाळात रूपांतर काय होईल?\",\"options\":[\"राघव कबड्डी खेळला\",\"राघव कबड्डी खेळत होता\",\"राघव कबड्डी खेळला होता\",\"राघव कबड्डी खेळत असे\"],\"answer\":0,\"explain\":\"तक्त्यातील \'मी चित्र काढले\' या साध्या भूतकाळाच्या रूपाप्रमाणे \'राघव कबड्डी खेळला\' असे होईल.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"\'मी चित्र काढले आहे\' आणि \'मी चित्र काढले होते\' या दोन वाक्यांमध्ये कोणता फरक आहे?\",\"options\":[\"उपप्रकार बदलला आहे\",\"क्रियापद सारखेच आहे\",\"मुख्य काळ बदलला आहे\",\"वाक्याचा अर्थ एकच आहे\"],\"answer\":2,\"explain\":\"पहिले वाक्य वर्तमानकाळातील आहे आणि दुसरे भूतकाळातील, म्हणजेच मुख्य काळ बदलला आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"\'रीती\' काळाला दुसऱ्या कोणत्या नावाने ओळखले जाते?\",\"options\":[\"अपूर्ण\",\"पूर्ण\",\"साधा\",\"चालू पूर्ण\"],\"answer\":3,\"explain\":\"मजकुरात कंसात \'रीती (चालू पूर्ण)\' असे स्पष्ट दिले आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'मी चित्र काढेन\' हे क्रियापद कोणत्या काळाचे आहे?\",\"options\":[\"साधा वर्तमानकाळ\",\"साधा भूतकाळ\",\"साधा भविष्यकाळ\",\"अपूर्ण भविष्यकाळ\"],\"answer\":2,\"explain\":\"तक्त्यानुसार \'मी चित्र काढेन\' हे साधा भविष्यकाळाचे उदाहरण आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"तक्त्यानुसार \'राघव कबड्डी खेळत होता\' हे कोणत्या काळाचे उदाहरण आहे?\",\"options\":[\"अपूर्ण वर्तमानकाळ\",\"अपूर्ण भूतकाळ\",\"अपूर्ण भविष्यकाळ\",\"साधा भूतकाळ\"],\"answer\":1,\"explain\":\"तक्त्यातील दुसऱ्या भागात \'राघव कबड्डी खेळत होता\' हे अपूर्ण भूतकाळाच्या रकान्यात येते.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"\'मी चित्र काढत असते\' या वाक्यात कोणता उपप्रकार वापरला आहे?\",\"options\":[\"रीती वर्तमानकाळ\",\"रीती भूतकाळ\",\"रीती भविष्यकाळ\",\"पूर्ण वर्तमानकाळ\"],\"answer\":0,\"explain\":\"तक्त्यानुसार \'मी चित्र काढत असते\' हे रीती वर्तमानकाळाचे उदाहरण आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता काळाचा मुख्य प्रकार नाही?\",\"options\":[\"वर्तमानकाळ\",\"भूतकाळ\",\"भविष्यकाळ\",\"अपूर्णकाळ\"],\"answer\":3,\"explain\":\"अपूर्णकाळ हा उपप्रकार आहे, मुख्य प्रकार नाही.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'राघव कबड्डी खेळला असेल\' हे वाक्य कोणत्या काळाचे आहे?\",\"options\":[\"पूर्ण वर्तमानकाळ\",\"पूर्ण भूतकाळ\",\"पूर्ण भविष्यकाळ\",\"साधा भविष्यकाळ\"],\"answer\":2,\"explain\":\"तक्त्यानुसार \'राघव कबड्डी खेळला असेल\' हे पूर्ण भविष्यकाळाचे उदाहरण आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"\'राघव कबड्डी खेळतो\' या वाक्याचे साधा भविष्यकाळात योग्य रूप कोणते?\",\"options\":[\"राघव कबड्डी खेळत असेल\",\"राघव कबड्डी खेळला असेल\",\"राघव कबड्डी खेळेल\",\"राघव कबड्डी खेळत जाईन\"],\"answer\":2,\"explain\":\"तक्त्यातील रिकाम्या जागा भरण्याच्या भागात \'राघव कबड्डी खेळेल\' हे साधा भविष्यकाळ म्हणून दिले आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"तक्त्यावरून \'रीती भूतकाळ\' दर्शवणारे योग्य वाक्य ओळखा.\",\"options\":[\"मी चित्र काढत असे\",\"मी चित्र काढत होते\",\"मी चित्र काढले होते\",\"मी चित्र काढत असते\"],\"answer\":0,\"explain\":\"तक्त्यानुसार रीती भूतकाळाचे उदाहरण \'मी चित्र काढत असे\' हे आहे.\",\"topic\":\"काळ व त्याचे प्रकार\",\"part\":10,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21812,33,6,'Marathi','mr','आंब्याचा मोहोर','[\"आंब्याचा मोहोर म्हणजे वसंत ऋतूचे आगमन व आनंदाची चाहूल.\",\"हिवाळा संपून वसंत सुरू झाल्यावर आंब्याच्या झाडांना मोहोर येतो.\",\"मोहोर आल्यावर संपूर्ण परिसर सुगंधाने दरवळतो.\",\"शिशिर ऋतूमध्ये झाडांचे पाने गळती राहतात, त्यानंतर पोरकी होऊन घरंगळतात.\",\"गुलमोहर, कडूनिंब, रंगाचा पट्टा संध्याकाळी नेमका पश्‍चिम चिंच, वड यांचे पाने क्षितीजाबरही दिसतात.\",\"शिशिर ऋतूची जादू मोठी खुलून दिसते, तेव्हा सकाळ-संध्याकाळ मोठ्या आणि ठळक प्रमाणात दिसते.\",\"आंब्याच्या मोहोराने मनाला केवढातरी उल्हास भासला.\",\"सूरपारंब्या खेळायला वडाचे आणि आंब्याचे झाड योग्य असतात.\",\"आंबा आणि चिंच या झाडांशी मैत्री जास्त होती, कारण तांबूस सर्व झाडांमध्ये आपली जास्त मैत्री होते ती फक्त कोवळी पालवी आलेली असतेच.\",\"लेखकाला आब्याच्या झाडाची आठवण एकसारखी होत राहते, कारण एखाददुसरा झाडाची आठवण एकसारखी होतच राहते.\"]','[{\"q\":\"\'आंब्याचा मोहोर\' या पाठाचे लेखक खालीलपैकी कोण आहेत?\",\"options\":[\"व. पु. काळे\",\"देवीदास बागुल\",\"पु. ल. देशपांडे\",\"शांता शेळके\"],\"answer\":1,\"explain\":\"पाठाच्या प्रस्तावनेत लेखकाचे नाव देवीदास बागुल असे दिले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"देवीदास बागुल यांनी खालीलपैकी कोणते पुस्तक लिहिले आहे?\",\"options\":[\"श्यामची आई\",\"बटाट्याची चाळ\",\"मोहोरणारी झाडे\",\"मृत्युंजय\"],\"answer\":2,\"explain\":\"प्रस्तावनेत \'मोहोरणारी झाडे\' हे पुस्तक देवीदास बागुल यांनी प्रसिद्ध केल्याचा उल्लेख आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"आंब्याच्या झाडांना मोहोर कधी येतो?\",\"options\":[\"पावसाळा सुरू झाला की\",\"उन्हाळा संपला की\",\"हिवाळा संपून वसंत ऋतू सुरू झाला की\",\"हिवाळा सुरू झाला की\"],\"answer\":2,\"explain\":\"मजकुरानुसार, हिवाळा संपून वसंत ऋतू सुरू झाला की आंब्याच्या झाडांना मोहोर येतो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आंब्याचा मोहोर आल्यावर परिसरात काय बदल होतो?\",\"options\":[\"संपूर्ण परिसर सुगंधाने दरवळतो\",\"परिसरात खूप पाऊस पडतो\",\"परिसरात अंधार होतो\",\"परिसरात शांतता पसरते\"],\"answer\":0,\"explain\":\"मजकुरात सांगितले आहे की मोहोर आल्यावर संपूर्ण परिसर सुगंधाने दरवळतो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"\'आंब्याचा मोहोर\' हा पाठ कोणत्या मासिकातून घेण्यात आला आहे?\",\"options\":[\"किशोर\",\"चांदोबा\",\"बालभारती जुन्या मासिकातून\",\"साप्ताहिक सकाळ\"],\"answer\":2,\"explain\":\"हा पाठ बालभारती जुन्या मासिकातून घेण्यात आला आहे असे प्रस्तावनेत स्पष्ट केले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"आंब्याचा मोहोर म्हणजे कशाची चाहूल होय?\",\"options\":[\"दुःखाची चाहूल\",\"आनंदाची चाहूल\",\"पावसाची चाहूल\",\"संकटाची चाहूल\"],\"answer\":1,\"explain\":\"आंब्याचा मोहोर म्हणजे वसंत ऋतूचे आगमन व आनंदाची चाहूल होय असे लेखकाने म्हटले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"देवीदास बागुल यांनी खालीलपैकी कोणती भूमिका बजावलेली नाही?\",\"options\":[\"लेखक\",\"संपादक\",\"गायक\",\"छायाचित्रकार\"],\"answer\":2,\"explain\":\"मजकुरात लेखक, संपादक, विचारवंत आणि छायाचित्रकार असा उल्लेख आहे, पण \'गायक\' असा उल्लेख नाही.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"देवीदास बागुल यांचा जीवनकाळ कोणता आहे?\",\"options\":[\"१९३१-२०१९\",\"१९२०-२०००\",\"१९४०-२०१०\",\"१९५०-२०२०\"],\"answer\":0,\"explain\":\"प्रस्तावनेत लेखकाचा काळ (१९३१-२०१९) असा दिला आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"वसंत ऋतूच्या आगमनाचे प्रतीक म्हणून मजकुरात कशाचा उल्लेख केला आहे?\",\"options\":[\"कडक ऊन\",\"आंब्याचा मोहोर\",\"पाऊस\",\"थंडी\"],\"answer\":1,\"explain\":\"आंब्याचा मोहोर म्हणजे वसंत ऋतूचे आगमन होय असे मजकुरात म्हटले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"प्रस्तुत पाठात लेखकाने मुख्यत्वे कशाचे वर्णन केले आहे?\",\"options\":[\"आंबे काढण्याच्या पद्धतीचे\",\"वसंतऋतूतील आंब्याच्या मोहराचे व त्या काळातील प्रसंगांचे\",\"हिवाळ्यातील थंडीचे\",\"छायाचित्रण कसे करावे याचे\"],\"answer\":1,\"explain\":\"पाठात वसंतऋतूतील आंब्याच्या झाडांना आलेल्या मोहराचे व त्या काळातील प्रसंगांचे वर्णन केले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"शिशिर ऋतू म्हटला की डोळ्यांपुढे काय उभी राहते?\",\"options\":[\"पावसाची रिमझिम\",\"झाडांच्या पानांची गळती\",\"फुलांची बाग\",\"कडक ऊन\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच म्हटले आहे की शिशिर ऋतू म्हटला की झाडांच्या पानांची गळती डोळ्यांपुढे उभी राहते.\",\"topic\":\"शिशिर ऋतू आणि पानांची गळती\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात खालीलपैकी कोणत्या झाडाच्या पानांची गळती होत असल्याचा उल्लेख नाही?\",\"options\":[\"गुलमोहर\",\"कडुलिंब\",\"नारळ\",\"चिंच\"],\"answer\":2,\"explain\":\"उताऱ्यात गुलमोहर, कडुलिंब, चिंच आणि वड यांचा उल्लेख आहे, पण नारळाचा उल्लेख नाही.\",\"topic\":\"शिशिर ऋतू आणि पानांची गळती\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"अर्धीमुर्धी वाळलेली पाने फांद्यांच्या बोटांना धरून राहण्याचा प्रयत्न का करत असावीत?\",\"options\":[\"त्यांना खाली पडायचे नसते\",\"त्यांना खेळायचे असते\",\"त्यांना नवीन पाने हवी अस