ons\":[\"निळे आकाश -> केसरी पट्टा -> सूर्योदय\",\"केसरी पट्टा -> निळ्या रंगात मिसळणे -> सूर्योदय\",\"सूर्योदय -> निळा रंग -> केसरी पट्टा\",\"पांढरा रंग -> निळा रंग -> केसरी पट्टा\"],\"answer\":1,\"explain\":\"प्रथम केसरी पट्टा दिसतो, मग तो निळ्या रंगात मिसळतो आणि मग सूर्योदय होतो.\",\"topic\":\"निसर्गातील रंगांची उधळण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"शिशिर ऋतू रंगांच्या बाबतीत कसा आहे असे लेखकाने म्हटले आहे?\",\"options\":[\"कद्रू आणि कंजूस\",\"रसिक कलावंत\",\"साधा आणि भोळा\",\"अल्लड आणि खोडकर\"],\"answer\":1,\"explain\":\"उताऱ्यात शिशिर ऋतूला रंगांच्या बाबतीत \'रसिक कलावंत\' म्हटले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"आंब्याला मोहोर आला की कोणता सण लवकरच येणार असे समजले जाते?\",\"options\":[\"दिवाळी\",\"दसरा\",\"वसंतपंचमी\",\"होळी\"],\"answer\":2,\"explain\":\"मोहोर आला म्हणजे आता वसंतपंचमी लवकरच येणार असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"शिशिर ऋतू कोणत्या बाबतीत \'कद्रू\' भासतो?\",\"options\":[\"रंगांच्या बाबतीत\",\"फळांच्या बाबतीत\",\"हिरव्या पानांच्या बाबतीत\",\"थंडीच्या बाबतीत\"],\"answer\":2,\"explain\":\"शिशिर ऋतू हिरव्या पानांच्या बाबतीत कद्रूपणाच भासतो असे उताऱ्यात म्हटले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"सूरपाळ्या खेळण्यासाठी प्रामुख्याने कोणती दोन झाडे सोईची असतात?\",\"options\":[\"पिंपळ आणि कडुलिंब\",\"नारळ आणि पोफळी\",\"वड आणि आंबा\",\"चिंच आणि बोर\"],\"answer\":2,\"explain\":\"सूरपाळ्या खेळायला दोनच झाडे - एक वडाचे आणि दुसरे आंब्याचे, असे उताऱ्यात दिले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पिंपळ आणि कडुलिंब ही झाडे सूरपाळ्या खेळायला का सोईची वाटत नाहीत?\",\"options\":[\"कारण त्यांना मोहोर येत नाही\",\"कारण त्यांच्या फांद्या खांद्यापासूनच पुढे फुटतात\",\"कारण ती झाडे खूप नाजूक असतात\",\"कारण त्यांची पाने कोवळी नसतात\"],\"answer\":1,\"explain\":\"इतर झाडांना फांद्या फुटतात खांद्यापासूनच पुढे, म्हणून पिंपळ, कडुलिंब सोईची वाटत नाहीत.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"आंब्याच्या फांद्यांची वाढ कशी असते?\",\"options\":[\"नेहमी सरळ रेषेत वर जाणारी\",\"फक्त जमिनीच्या दिशेने झुकलेली\",\"समांतर किंवा तिरकस\",\"वेड्यावाकड्या आकारात\"],\"answer\":2,\"explain\":\"आंब्याच्या झाडांच्या फांद्या सरळ उभ्या न जाता कधी समांतर तर कधी तिरकस अशा वाढत जातात.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्याला झाडावर चढायला शिकायचे असेल, तर लेखकाने कोणते झाड सर्वात सोईस्कर सांगितले आहे?\",\"options\":[\"नारळाचे झाड\",\"पिंपळाचे झाड\",\"आंब्याचे झाड\",\"कडुलिंबाचे झाड\"],\"answer\":2,\"explain\":\"झाडावर चढायला शिकायचे असेल, तर आंब्याइतके दुसरे सोईस्कर झाड नाही, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"नारळी-पोफळीच्या झाडावर चढणे म्हणजे काय करण्यासारखे आहे?\",\"options\":[\"वानरासारख्या उड्या मारणे\",\"मल्लखांब करणे\",\"सूरपाळ्या खेळणे\",\"झोपाळा खेळणे\"],\"answer\":1,\"explain\":\"नारळीपोफळीसारखी झाडे नुसता मल्लखांब करायला लावतात, असे उताऱ्यात वर्णन केले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"आंब्याच्या झाडाला \'डेरेदार\' का म्हटले असावे?\",\"options\":[\"कारण ते खूप उंच वाढते\",\"कारण त्याच्या सर्व भागांतून वानरासारख्या उड्या मारत मनसोक्त हिंडता येते\",\"कारण त्याला खूप मोहोर येतो\",\"कारण त्याची पाने तांबूस रंगाची असतात\"],\"answer\":1,\"explain\":\"आंब्याच्या डेरेदार झाडाच्या सर्व भागांतून वानरासारख्या उड्या मारत हिंडता येते, असे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"चैत्रातील गोरगेईच्या स्थापनेसाठी काय आणले जाते?\",\"options\":[\"वडाच्या फांद्या\",\"कोवळी आंब्यांची पाने\",\"नारळाच्या शेंड्या\",\"पिंपळाची फुले\"],\"answer\":1,\"explain\":\"गोरगेईसाठी कोवळी कोवळी आंब्यांची पाने आणायची, असे उताऱ्यात दिले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सूरपाळ्या खेळताना आंब्याच्या झाडाचा कोणता फायदा होतो?\",\"options\":[\"फांद्या जमिनीपासून फार उंच नसल्याने पटकन चढता येते\",\"झाडावर खूप सावली असते\",\"झाडाला खूप फळे लागलेली असतात\",\"झाडाची पाने मऊ असतात\"],\"answer\":0,\"explain\":\"फांद्या जमिनीपासून फार उंच नसल्याने झटकन उडी मारता येते आणि पटकन चढताही येते, हा फायदा उताऱ्यात सांगितला आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"लेखकाच्या मते झाडावर चढण्याच्या क्रियेत खरी मजा कशात आहे?\",\"options\":[\"नुसते सरसर वर चढण्यात\",\"झाडावरून खाली पडण्यात\",\"अल्लडपणात आणि खेळाच्या अनुभवात\",\"झाडाची पाने तोडण्यात\"],\"answer\":2,\"explain\":\"झाडावर चढण्याखाली एक खेळ असतो, अल्लडपणा असतो, यातच खरी मजा असल्याचे लेखकाने सुचवले आहे.\",\"topic\":\"सूरपाळ्या खेळ आणि आंब्याचे झाड\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"सर्व झाडांपेक्षा आपली सर्वात जास्त मैत्री कोणत्या झाडांशी होते असे उताऱ्यात म्हटले आहे?\",\"options\":[\"वड आणि पिंपळ\",\"चिंच आणि आंबा\",\"नारळ आणि सुपारी\",\"पेरू आणि चिकू\"],\"answer\":1,\"explain\":\"उताऱ्याच्या पहिल्या ओळीत नमूद केले आहे की आपली जास्त मैत्री चिंच आणि आंबा या झाडांशी होते.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"चिंचेच्या झाडाशी मैत्रीची सुरुवात नेमकी कशाने होते?\",\"options\":[\"फुले वेचण्याने\",\"कोवळा तांबूस पाला खाण्याने\",\"चिंचा पाडण्याने\",\"सावलीत बसण्याने\"],\"answer\":1,\"explain\":\"चिंचेचा कोवळा तांबूस पाला खाण्यापासूनच चिंचेची मैत्री सुरू होते असे उताऱ्यात दिले आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"आंब्याच्या मोहराचा मधला देठ कोणत्या रंगाचा होतो?\",\"options\":[\"हिरवा\",\"पिवळा\",\"चांगलाच लाल\",\"पांढरा\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की मोहराचा मधला देठ तर चांगलाच लाल होतो.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"आंब्याच्या मोहराच्या फुलांचा आकार कसा असतो?\",\"options\":[\"त्रिकोणी\",\"लांबट\",\"गोल\",\"चौकोनी\"],\"answer\":2,\"explain\":\"फांद्यांना तिच्याच आकाराएवढी गोल फुले लागतात असे वर्णन उताऱ्यात आले आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"पिवळसर शुभ्र फुलांवर कोणती छटा आल्यावर मादक वास दरवळू लागतो?\",\"options\":[\"निळी छटा\",\"तांबूस छटा\",\"काळी छटा\",\"हिरवी छटा\"],\"answer\":1,\"explain\":\"पिवळसर शुभ्र फुलांना हळूहळू तांबूस छटा येते आणि त्यावर मादक वास दरवळू लागतो.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"थंडीच्या दिवसात आंब्याच्या झाडाजवळ गेल्यावर कोणता अनुभव येतो?\",\"options\":[\"खूप थंडी वाजते\",\"मोहराचा वास जाणवून मन मोहरते\",\"पाने गळताना दिसतात\",\"पक्ष्यांचा किलबिलाट ऐकू येतो\"],\"answer\":1,\"explain\":\"काकडून टाकणाऱ्या थंडीतही मोहराचा वास जाणवताच मन मोहरते असे उताऱ्यात सांगितले आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"होळीचे दिवस जवळ आल्यावर आंब्याच्या मोहराचे काय होते?\",\"options\":[\"मोहर अधिक गडद होतो\",\"मोहराची फुले झडू लागतात\",\"मोहराचा वास थांबतो\",\"नवीन फुले येतात\"],\"answer\":1,\"explain\":\"हळूहळू होळीचे दिवस येतात आणि मोहोराची फुले झडू लागतात असे उताऱ्यात नमूद आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"पिकलेल्या चिंचेचा रंग उताऱ्यात कोणासारखा सांगितला आहे?\",\"options\":[\"साखरेसारखा\",\"गुळाच्या रंगासारखा\",\"मातीसारखा\",\"तांब्यासारखा\"],\"answer\":1,\"explain\":\"शेवटी गुळाच्या रंगासारख्या चिंचा खाता खाता मैत्रीचा पेच उभेतो असे वर्णन आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, मोहराची फुले झडल्यानंतर झाडाच्या फांद्यांना काय लागलेले दिसत आहे?\",\"options\":[\"फक्त फुले\",\"हिरव्या कैऱ्या\",\"वाळलेली पाने\",\"नवीन तांबूस पाला\"],\"answer\":1,\"explain\":\"चित्रात झाडावर भरपूर हिरव्या कैऱ्या दिसत आहेत, जे फुले झडल्यानंतरचे स्वरूप आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"33\\/089_101.jpg\"},{\"q\":\"दिलेल्या चित्रावरून, आंब्याच्या झाडाची कोणती अवस्था दर्शवली आहे?\",\"options\":[\"मोहर येण्याची अवस्था\",\"कैऱ्या लागून त्या काढण्याची अवस्था\",\"पाने गळण्याची अवस्था\",\"झाड लावण्याची अवस्था\"],\"answer\":1,\"explain\":\"चित्रात लोक झाडावरून कैऱ्या काढत आहेत आणि टोपलीत भरत आहेत, ही फळे येण्याची अवस्था आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"evaluate\",\"figure_image\":\"33\\/089_101.jpg\"},{\"q\":\"जर तुम्हाला आंब्याच्या झाडाच्या प्रत्येक फांदीवर चार-पाच कैऱ्या दिसत असतील, तर उताऱ्यानुसार त्याआधी कोणती घटना घडली असेल?\",\"options\":[\"पावसाळा सुरू झाला असेल\",\"मोहराची फुले झडून गेली असतील\",\"झाडाची सर्व पाने गळाली असतील\",\"केवळ नवीन पाला आला असेल\"],\"answer\":1,\"explain\":\"मोहराची फुले झडू लागल्यानंतर फांद्यांना चार-पाच कैऱ्या दिसू लागतात असे उताऱ्यात म्हटले आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"आंब्याच्या झाडाला जाग आल्यावर सुरुवातीला पानांतून काय बाहेर येते?\",\"options\":[\"लाल फुले\",\"निव्वळ हिरवे घोस\",\"पिवळ्या कैऱ्या\",\"वाळलेल्या फांद्या\"],\"answer\":1,\"explain\":\"मकरंदलेल्या हिरव्या पानांतून निव्वळ हिरवे घोस डोके वर काढतात असे उताऱ्यात दिले आहे.\",\"topic\":\"झाडांशी मैत्री आणि मोहराचे वर्णन\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"झाडावर पिकलेला आंबा शोधून काढण्यात कोणाची मदत होते?\",\"options\":[\"गड्यांची\",\"पाखरांची\",\"वनदेवीची\",\"पावसाची\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की, पिकलेला आंबा शोधण्याच्या कामात पाखरांची चांगलीच मदत होते.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पाखरे कैऱ्यांचा आस्वाद कशाच्या साह्याने घेतात?\",\"options\":[\"पायांनी\",\"पंखांनी\",\"चोचींनी\",\"नखांनी\"],\"answer\":2,\"explain\":\"पाखरे आपल्या चोचींनी कैऱ्यांचा आस्वाद घेतात असे उताऱ्यात दिले आहे.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"आंबा उतरवण्यासाठी कसे गडी बोलवावे लागतात?\",\"options\":[\"ओंड्याप्रमाणे मजबूत\",\"उंच आणि सडपातळ\",\"धाडसी आणि चपळ\",\"वयस्कर आणि अनुभवी\"],\"answer\":0,\"explain\":\"उताऱ्यात \'ओंड्याप्रमाणे गडी\' असा उल्लेख आला आहे, ज्याचा अर्थ मजबूत गडी असा होतो.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"गडी झाडावर चढल्यानंतर सर्वात अगोदर काय शोधतात?\",\"options\":[\"पाखरांचे घरटे\",\"वाळलेल्या फांद्या\",\"पाड (पिकू लागलेला आंबा)\",\"मोठ्या कैऱ्या\"],\"answer\":2,\"explain\":\"गडी वर चढले की अगोदर \'पाड\' शोधतात, असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"कैऱ्यांनी खाली वाकलेल्या फांद्या पुन्हा ताठ का होतात?\",\"options\":[\"वारा सुटल्यामुळे\",\"पाऊस पडल्यामुळे\",\"कैऱ्या उतरवल्यामुळे वजन कमी होते\",\"ऊन वाढल्यामुळे\"],\"answer\":2,\"explain\":\"आंबे उतरवल्यामुळे फांद्यांवरील ओझे कमी होते, म्हणून त्या पुन्हा ताठ होतात.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"आंब्याचा ढीग कधीपर्यंत जमतो?\",\"options\":[\"पहिल्या प्रहरापर्यंत\",\"दुपारपर्यंत\",\"तिसऱ्या प्रहरापर्यंत\",\"संध्याकाळपर्यंत\"],\"answer\":2,\"explain\":\"उताऱ्यातील माहितीनुसार, तिसऱ्या प्रहरापर्यंत आंब्याचा ढीग जमतो.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"आंबा उतरवून झाल्यावर लेखकाला हुरहूर का लागते?\",\"options\":[\"आंबे संपले म्हणून\",\"झाडाचा लळा लागलेला असतो म्हणून\",\"गडी निघून गेले म्हणून\",\"पाऊस येणार असतो म्हणून\"],\"answer\":1,\"explain\":\"दोन-तीन महिन्यांच्या काळात आंब्याच्या झाडाचा खूप लळा लागलेला असतो, म्हणून लेखकाला हुरहूर लागते.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात आलेल्या \'ऊन चढते\' या वाक्प्रचाराचा अर्थ काय?\",\"options\":[\"दुपारची वेळ होणे\",\"सूर्य मावळणे\",\"थंडी वाजणे\",\"पाऊस पडणे\"],\"answer\":0,\"explain\":\"ऊन चढणे म्हणजे सकाळ उलटून दुपारची वेळ होणे किंवा उन्हाची तीव्रता वाढणे.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"पाखरे एखाद्या कैरीला चोच मारत असतील, तर त्यावरून काय समजते?\",\"options\":[\"कैरी कडू आहे\",\"कैरी पिकायला सुरुवात झाली आहे\",\"पाखरे खेळत आहेत\",\"झाड वाळले आहे\"],\"answer\":1,\"explain\":\"पाखरांना कैरी पिकायचा सुगावा आधी लागतो, म्हणून त्या चोच मारतात.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"आंबे उतरवल्यानंतर कोणता ऋतू येणार असतो?\",\"options\":[\"हिवाळा\",\"उन्हाळा\",\"वर्षा ऋतू\",\"शरद ऋतू\"],\"answer\":2,\"explain\":\"उताऱ्यात शेवटी \'वर्षा ऋतूत वनदेवी खूप नटणार असते\' असा उल्लेख आहे.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"झोळगे भरभरून खाली येणे ही क्रिया कधी वेगाने घडते?\",\"options\":[\"सकाळी लवकर\",\"जसजसे ऊन चढते तसतसे\",\"रात्रीच्या वेळी\",\"पाऊस पडताना\"],\"answer\":1,\"explain\":\"उताऱ्यात म्हटले आहे की, जसजसे ऊन चढते तसतसे झोळगे भरभरून खाली येतात.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"\'वनदेवी खूप नटणार असते\' या विधानाचा अर्थ काय?\",\"options\":[\"जंगलात जत्रा भरणार आहे\",\"पावसामुळे निसर्ग हिरवागार होणार आहे\",\"झाडाला नवीन आंबे येणार आहेत\",\"वनदेवीची पूजा होणार आहे\"],\"answer\":1,\"explain\":\"वर्षा ऋतूत (पावसाळ्यात) सर्वत्र हिरवळ पसरते, त्यालाच लेखकाने वनदेवी नटणे असे म्हटले आहे.\",\"topic\":\"आंबा उतरवण्याचा बेत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'गोरगेई\' या शब्दाचा अर्थ खालीलपैकी कोणता आहे?\",\"options\":[\"लक्ष्मी\",\"सरस्वती\",\"पार्वती\",\"सावित्री\"],\"answer\":2,\"explain\":\"दिलेल्या मजकुरानुसार \'गोरगेई\' म्हणजे पार्वती होय.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'पोरांनी\' या शब्दाचा नेमका अर्थ काय होतो?\",\"options\":[\"खूप मुले असणे\",\"आईबाप नसलेली व आधार नसलेली\",\"शाळेत जाणारी मुले\",\"खेळणारी मुले\"],\"answer\":1,\"explain\":\"मजकुरात \'पोरांनी\' म्हणजे आईबाप नसलेली, कसलाही आधार नसलेली असे दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'आस्वाद\' या शब्दाचा अर्थ ओळखा.\",\"options\":[\"सुगंध\",\"चव\",\"स्पर्श\",\"दर्शन\"],\"answer\":1,\"explain\":\"मजकुरानुसार \'आस्वाद\' म्हणजे चव होय.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"फळे पिकण्यापूर्वीची पहिली स्थिती म्हणजे काय?\",\"options\":[\"मोहोर\",\"कैरी\",\"पाड\",\"आंबा\"],\"answer\":2,\"explain\":\"मजकुरात \'पाड\' म्हणजे फळे पिकण्यापूर्वीची पहिली स्थिती असे स्पष्ट केले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'केसरी-कुसुंबी\' हा शब्द कशाचे वर्णन करण्यासाठी वापरला आहे?\",\"options\":[\"फळाची चव\",\"पाण्याचा रंग\",\"केशराच्या रंगाचा\",\"फुलांचा सुगंध\"],\"answer\":2,\"explain\":\"\'केसरी-कुसुंबी\' म्हणजे केशराच्या रंगाचा असा अर्थ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"एखाद्या गोष्टीचा तपास किंवा शोध घेणे याला मजकुरात कोणता शब्द आहे?\",\"options\":[\"सुगावा\",\"आस्वाद\",\"कद्रूपणा\",\"पाड\"],\"answer\":0,\"explain\":\"\'सुगावा\' म्हणजे शोध किंवा तपास असा अर्थ मजकुरात दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर एखादी व्यक्ती अतिशय \'निष्ठूर\' वागत असेल, तर तिच्या स्वभावासाठी कोणता शब्द योग्य ठरेल?\",\"options\":[\"गोरगेई\",\"कद्रूपणा\",\"सुगावा\",\"पाड\"],\"answer\":1,\"explain\":\"\'कद्रूपणा\' म्हणजे क्रूर किंवा निष्ठूर होय.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"एखाद्या अनाथ मुलाचे वर्णन करण्यासाठी मजकुरातील कोणता शब्द सर्वात योग्य आहे?\",\"options\":[\"केसरी-कुसुंबी\",\"गोरगेई\",\"पोरांनी\",\"आस्वाद\"],\"answer\":2,\"explain\":\"\'पोरांनी\' या शब्दाचा अर्थ आईबाप नसलेली असा होतो, जो अनाथ मुलासाठी लागू होतो.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती जोडी समानार्थी शब्दांची नाही?\",\"options\":[\"सुगावा - तपास\",\"आस्वाद - चव\",\"कद्रूपणा - दयाळूपणा\",\"गोरगेई - पार्वती\"],\"answer\":2,\"explain\":\"मजकुरानुसार \'कद्रूपणा\' म्हणजे क्रूर किंवा निष्ठूर, त्यामुळे दयाळूपणा ही जोडी चुकीची आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या शब्दांपैकी कोणता शब्द केवळ रंगाशी संबंधित आहे?\",\"options\":[\"पाड\",\"केसरी-कुसुंबी\",\"सुगावा\",\"कद्रूपणा\"],\"answer\":1,\"explain\":\"\'केसरी-कुसुंबी\' हा शब्द केशराच्या रंगाचे वर्णन करतो.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21813,33,6,'Marathi','mr','आम्ही असू वेगळे (कविता)','[\"कविता \'आम्ही असू वेगळे\' दिव्यांग मुलांचे सकारात्मक गुणे दर्शवते.\",\"कवितेत निराळी मुले निर्मळ हृदय, हसरा चेहरा आणि वेगळ्या विचारांची ओळख करतात.\",\"कवितेत \'आपली\' भाषा ठाऊक नाही असे सांगितले जाते, ज्यामुळे सर्वात समानता वाटते.\",\"कवितेत ईर्ष्या, द्वेष अशाची लागण नाही, ज्यामुळे प्रेम व मैत्री वाढते.\",\"कवितेत \'निराळी\' शब्दे वेगळ्यापणा, अनोख्यापणा आणि वैयक्तिक ओळख दर्शवते.\",\"कवितेत \'निर्मळ हृदये, चेहरे हसरे, तरी निराळी मुले\' ओळी बारंबार दोहरवली जाते, ज्यामुळे मुख्य संदेश बलवंत होतो.\",\"कवितेत \'जगात तुमच्या असेल बंदी, आम्ही असू वेगळे\' ओळी दिव्यांग मुलांचे स्वागत व समावेश दर्शवते.\",\"कवितेत \'दार आमुच्या विश्‍वाचे परी खुले\' ओळी खुल्या मनाचा वाटावरण दर्शवते.\",\"कवितेत \'काळीजफुले\' शब्दे सुंदरता, नाजुकता आणि वेगळ्यापणा दर्शवतात.\",\"कवितेत \'स्वागत तुमचे\' ओळी अतिथिस्नेह व स्वीकार्यता दर्शवते.\",\"कवितेत \'तुमच्या जगात जरी आम्हांला बदी असली, तरी आमच्या जगाचे दार तुमच्यासाठी उघडे असेल\' ओळी क्षमापण व उदारता दर्शवते.\",\"कवितेत \'देवाने केलेल्या वाटणीत आम्हाला थोडे कमी मिळाले, तरी आमची तक्रार नाही\' ओळी संतोष व समाधान दर्शवते.\",\"कवितेत \'तशाच हिरव्या वेलींवस्ची जरा निराळी फुले\' ओळी सौंदर्य व वेगळ्यापणा दर्शवते.\",\"कवितेचा मुख्य संदेश: सर्वात समानता, प्रेम, स्वागत आणि वेगळ्यापणाचे मान.\",\"कवितेतील भाषा: सरल, भावनापूर्ण, दोहरावाने बलवंत.\"]','[{\"q\":\"नव्या हिरव्या वेलीवर काय आहे असे कवितेत म्हटले आहे?\",\"options\":[\"फळे\",\"निराळी फुले\",\"पाने\",\"काटे\"],\"answer\":1,\"explain\":\"कवितेच्या पहिल्या ओळीत \'नव्याच हिरव्या वेलीवरची जरि निराळी फुले\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मुलांचे हृदय आणि चेहरे कसे आहेत?\",\"options\":[\"दुःखी हृदय आणि रडवेले चेहरे\",\"कठोर हृदय आणि हसरे चेहरे\",\"निर्मळ हृदय आणि हसरे चेहरे\",\"निर्मळ हृदय आणि रागीट चेहरे\"],\"answer\":2,\"explain\":\"कवितेत \'निर्मळ हृदये, चेहरे हसरे\' असे मुलांचे वर्णन केले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"देवाकडच्या वाटणीत काही कमी मिळाले तरी मुलांची प्रतिक्रिया काय असते?\",\"options\":[\"ते खूप रडतात\",\"त्यांच्या मनात तक्रार किंवा खंत नसते\",\"ते देवावर रागावतात\",\"ते दुसऱ्यांशी भांडतात\"],\"answer\":1,\"explain\":\"कवितेनुसार, देवाकडच्या वाटणीत कमी मिळाले तरी तक्रारीचा सूर किंवा खंत नसते.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"देवाने मुलांना कोणते हिशेब शिकविले नाहीत?\",\"options\":[\"गणिताचे हिशेब\",\"शाळेचे हिशेब\",\"व्यवहाराचे हिशेब\",\"पैशांचे हिशेब\"],\"answer\":2,\"explain\":\"कवितेत म्हटले आहे की, \'व्यवहाराचे हिशेब त्याने, कुठे आम्हां शिकविले\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मुलांना कोणती भाषा ठाऊक नाही?\",\"options\":[\"मराठी-इंग्रजी\",\"मला-तुला आणि माझे-तुमचे\",\"गाण्यांची भाषा\",\"खिदाळण्याची भाषा\"],\"answer\":1,\"explain\":\"कवितेच्या तिसऱ्या कडव्यात \'मला-तुला अन माझे-तुमचे भाषा ठाऊक नाही\' असे म्हटले आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मुले कोणाला \'आपले\' म्हणतात?\",\"options\":[\"जे त्यांना खाऊ देतात\",\"जे त्यांच्याशी भांडतात\",\"जे प्रेमाने हाक मारतात\",\"जे त्यांना खेळणी देतात\"],\"answer\":2,\"explain\":\"कवितेनुसार, प्रेमाने जो हाक मारतो त्याला मुले \'आपुले\' म्हणतात.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"रस्त्याने जाताना मुले कोणाचा हात धरतात?\",\"options\":[\"वडिलांचा\",\"मित्राचा\",\"शिक्षकांचा\",\"आईचा\"],\"answer\":3,\"explain\":\"कवितेत \'रस्त्याने जाताना आम्ही हात आईचा धरूनी\' असा उल्लेख आहे.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सणावाराला मुलांच्या कोणत्या कृतीमुळे आईचा चेहरा बावरलेला असतो?\",\"options\":[\"मुले शांत बसतात म्हणून\",\"मुले तुटूनी सुटूनी येतात म्हणून\",\"मुले रडतात म्हणून\",\"मुले नवीन कपडे घालत नाहीत म्हणून\"],\"answer\":1,\"explain\":\"कवितेत विचारले आहे की, \'कधी सणावाराला आम्ही तुटूनी सुटूनी येतो, का आईचा चेहरा तेव्हा बावरलेला असतो\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"मुलांच्या विश्वाचे दार कसे आहे?\",\"options\":[\"नेहमी बंद\",\"फक्त मित्रांसाठी खुले\",\"सर्वांसाठी खुले\",\"फक्त आईसाठी खुले\"],\"answer\":2,\"explain\":\"कवितेत म्हटले आहे की, \'स्वागत तुमचे, दार आमच्या विश्वाचे परी खुले\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"इतरांच्या जगात काय आहे, जे मुलांच्या जगात नाही?\",\"options\":[\"आनंद\",\"बंदी (निर्बंध)\",\"खेळणी\",\"शाळा\"],\"answer\":1,\"explain\":\"कवितेत म्हटले आहे की \'जातात तुमच्या जगात बंदी, आम्ही असू वेगळे\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"मुलांच्या मते, काळीज केव्हा जुळतील?\",\"options\":[\"जेव्हा लोक त्यांना पैसे देतील\",\"जेव्हा लोक निर्मळ होऊन त्यांच्या विश्वात येतील\",\"जेव्हा लोक त्यांना रागावतील\",\"जेव्हा मुले मोठी होतील\"],\"answer\":1,\"explain\":\"कवितेच्या शेवटी म्हटले आहे, \'एकवार या, निर्मळ होऊनी, जातील काळीज जुळे\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"मुलांना कोणत्या गोष्टीची लागण झालेली नाही?\",\"options\":[\"आजाराची\",\"ईर्ष्या आणि द्वेष\",\"अभ्यासाची\",\"खेळाची\"],\"answer\":1,\"explain\":\"कवितेत स्पष्ट केले आहे की, \'म्हणून ईर्ष्या, द्वेष अशाची लागण आम्हां नाही\'.\",\"topic\":\"कविता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"संजीवनी बोकील यांचा जन्म कोणत्या वर्षी झाला?\",\"options\":[\"१९३९\",\"१९४९\",\"१९५९\",\"१९६९\"],\"answer\":1,\"explain\":\"उताऱ्यात संजीवनी बोकील यांचा जन्म १९४९ मध्ये झाल्याचा उल्लेख आहे.\",\"topic\":\"कवयित्री परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता संजीवनी बोकील यांचा काव्यसंग्रह आहे?\",\"options\":[\"फुलबाग\",\"रंगानुबंध कथा\",\"कांचनझुंगा\",\"आरोग्याची फुले\"],\"answer\":2,\"explain\":\"\'कांचनझुंगा\' हा संजीवनी बोकील यांचा काव्यसंग्रह आहे, तर इतर कथासंग्रह आहेत.\",\"topic\":\"कवयित्री परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"संजीवनी बोकील यांनी साहित्याच्या कोणत्या क्षेत्रात काम केले आहे?\",\"options\":[\"केवळ कवयित्री\",\"कवयित्री, कथाकार, कादंबरीकार आणि अनुवादक\",\"केवळ अनुवादक आणि 