}{4}$\",\"$\\\\frac{13}{4}$\",\"$\\\\frac{3}{4}$\"],\"answer\":2,\"explain\":\"The text shows $3 \\\\frac{1}{4} = \\\\frac{3 \\\\times 4 + 1}{4} = \\\\frac{13}{4}$.\",\"topic\":\"Addition of mixed fractions\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"In the given figure, what is the improper fraction obtained from $3 \\\\frac{3}{4}$?\",\"options\":[\"$\\\\frac{12}{4}$\",\"$\\\\frac{15}{4}$\",\"$\\\\frac{7}{4}$\",\"$\\\\frac{9}{4}$\"],\"answer\":1,\"explain\":\"The figure shows $3 \\\\frac{3}{4} = \\\\frac{3 \\\\times 4 + 3}{4} = \\\\frac{15}{4}$.\",\"topic\":\"Addition of mixed fractions\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"34\\/062_101.jpg\"},{\"q\":\"In the given figure, what is the final sum of the mixed fractions $3 \\\\frac{3}{4} + 2 \\\\frac{3}{5}$?\",\"options\":[\"$5 \\\\frac{13}{20}$\",\"$6 \\\\frac{7}{20}$\",\"$\\\\frac{127}{20}$\",\"$6 \\\\frac{20}{7}$\"],\"answer\":1,\"explain\":\"The final step in the figure calculation shows the result as $6 \\\\frac{7}{20}$.\",\"topic\":\"Addition of mixed fractions\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"34\\/062_101.jpg\"},{\"q\":\"In the text example $3 \\\\frac{1}{4} + 2 \\\\frac{2}{5}$, why are the fractions $\\\\frac{13}{4}$ and $\\\\frac{12}{5}$ multiplied by 5 and 4 respectively?\",\"options\":[\"To make the numerators equal\",\"To make the denominators equal to the LCM (20)\",\"To convert them back to mixed fractions\",\"To simplify the fractions to their lowest terms\"],\"answer\":1,\"explain\":\"Multiplying by 5 and 4 makes both denominators 20, which is the LCM, allowing the fractions to be added.\",\"topic\":\"Addition of mixed fractions\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"What is the numerator of the final improper fraction before it is converted to $5 \\\\frac{13}{20}$ in the text example?\",\"options\":[\"65\",\"48\",\"113\",\"20\"],\"answer\":2,\"explain\":\"The text shows the sum as $\\\\frac{65 + 48}{20} = \\\\frac{113}{20}$.\",\"topic\":\"Addition of mixed fr