:[\"७\",\"१००\",\"२५\",\"५२\"],\"answer\":1,\"explain\":\"दशांश अपूर्णांकाचा छेद १०, १००, १००० यांसारख्या १० च्या पटीत असावा लागतो.\",\"topic\":\"एक दृष्टिक्षेप\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"अभियांत्रिकीमध्ये (Engineering) दशांश अपूर्णांकांचा मुख्य उपयोग काय आहे?\",\"options\":[\"अतिशय सूक्ष्म मोजमापासाठी\",\"केवळ इमारती मोजण्यासाठी\",\"रंगकाम करण्यासाठी\",\"नकाशा काढण्यासाठी\"],\"answer\":0,\"explain\":\"अभियांत्रिकीमध्ये अचूकतेसाठी सूक्ष्म मोजमापे दशांश अपूर्णांकात घेतली जातात.\",\"topic\":\"एक दृष्टिक्षेप\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"दशांश अपूर्णांकांची वजाबाकी करताना नेहमीच्या वजाबाकीसारखीच क्रिया करावी, परंतु कोणती अट पाळावी?\",\"options\":[\"दशांश चिन्ह काढून टाकावे\",\"दशांश चिन्हाची जागा बदलू नये\",\"दशांश चिन्हाखाली दशांश चिन्ह मांडावे\",\"छेदाचा गुणाकार करावा\"],\"answer\":2,\"explain\":\"वजाबाकी करताना दशांश चिन्हाची योग्य एकाखाली एक मांडणी करणे ही महत्त्वाची अट आहे.\",\"topic\":\"एक दृष्टिक्षेप\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर एका अपूर्णांकाचा छेद १००० असेल, तर तो कोणत्या प्रकारचा अपूर्णांक आहे?\",\"options\":[\"साधा अपूर्णांक\",\"दशांश अपूर्णांक\",\"पूर्णांक युक्त अपूर्णांक\",\"अंशाधिक अपूर्णांक\"],\"answer\":1,\"explain\":\"१००० हा १० च्या दहा-दहा पटीतील छेद असल्याने तो दशांश अपूर्णांक आहे.\",\"topic\":\"एक दृष्टिक्षेप\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"दशांश पद्धतीचा वापर व्यवहारात कोठे सोयीचा ठरतो?\",\"options\":[\"फक्त शाळेत\",\"दुकानात हिशोब करताना\",\"केवळ बागेत\",\"जेवण करताना\"],\"answer\":1,\"explain\":\"दुकानातील आर्थिक व्यवहारांत आणि हिशोबात दशांश पद्धत सोयीची असते.\",\"topic\":\"एक दृष्टिक्षेप\",\"part\":10,\"bloom\":\"apply\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21848,35,6,'Maths','mr','नफा-तोटा','[\"नफा म्हणजे विक्री किंमत व खरेदी किंमत यातील फरक, जर विक्री किंमत जास्त असेल तर नफा होतो.\",\"तोटा म्हणजे खरेदी किंमत व विक्री किंमत यातील फरक, जर विक्री किंमत कमी असेल तर तोटा होतो.\",\"नफा = विक्री किंमत – खरेदी किंमत\",\"तोटा = खरेदी किंमत – विक्री किंमत\",\"नफा किंवा तोटा काढण्यासाठी दोन्ही किंमतींची माहिती असणे आवश्यक आहे.\",\"विक्री किंमत ठरवताना उत्पादन खर्च, वाहतूक, कर व ग्राहकांची मागणी यांचा विचार करावा.\",\"उत्पादनाची गुणवत्ता व सादरीकरण यामुळे ग्राहकांना आकर्षित करता येते.\",\"विक्री किंमत कमी असल्यास ग्राहकांना सवलत देऊन विक्री वाढवता येते.\",\"नफा-तोटा गणना करताना सर्व खर्च (मजुरी, वाहतूक, पॅकिंग) एकूण खरेदी किंमतीत समाविष्ट करावा.\",\"नफा झाल्यास तो नफा वाटप, दान किंवा नवीन गुंतवणुकीसाठी वापरता येतो.\",\"तोटा झाल्यास कारण शोधून पुढच्या व्यवहारात सुधारणा करावी.\",\"नफा व तोटा दोन्ही गणना करण्यासाठी समान सूत्र वापरता येते, फक्त चिन्ह बदलते.\",\"विक्री किंमत व खरेदी किंमत यातील फरक लहान असला तरी नफा किंवा तोटा स्पष्ट होतो.\",\"नफा व तोटा हे व्यवसायाचे मूलभूत घटक आहेत, ज्यावरून व्यवसायाची स्थिती कळते.\",\"नफा-तोटा गणना करताना रकमेतील दशांश व शंभराच्या भागाकडे लक्ष द्यावे.\"]','[{\"q\":\"येथेकरी गावात शाळेच्या पटांगणात कोणता मेळावा आयोजित केला होता?\",\"options\":[\"विज्ञान मेळावा\",\"हरित मेळावा\",\"क्रीडा मेळावा\",\"सांस्कृतिक मेळावा\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच \'हरित मेळावा\' आयोजित केल्याचा उल्लेख आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"हरित मेळाव्याचा मुख्य विषय कोणता होता?\",\"options\":[\"आरोग्य रक्षण\",\"जल रक्षण\",\"पर्यावरण रक्षण\",\"प्राणी रक्षण\"],\"answer\":2,\"explain\":\"मेळाव्यात पर्यावरण रक्षण हा मुख्य विषय ठेवला होता असे उताऱ्यात दिले आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"श्रध्दाने किती रुपयांची रोपे खरेदी केली होती?\",\"options\":[\"₹ 1560\",\"₹ 1200\",\"₹ 1250\",\"₹ 1000\"],\"answer\":2,\"explain\":\"श्रध्दाने ₹ 1250 ची रोपे खरेदी केली होती असे संवादात म्हटले आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मेळाव्यात सहभागी होणाऱ्यांमध्ये खालीलपैकी कोणाचा उल्लेख नाही?\",\"options\":[\"विद्यार्थी\",\"शिक्षक\",\"पालक\",\"दुकानदार\"],\"answer\":3,\"explain\":\"\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"एखादी वस्तू खरेदी करण्यासाठी जी रक्कम द्यावी लागते, तिला काय म्हणतात?\",\"options\":[\"विक्री किंमत\",\"नफा\",\"खरेदी किंमत\",\"तोटा\"],\"answer\":2,\"explain\":\"शिक्षकांनी स्पष्ट केले आहे की, खरेदी केलेली रक्कम म्हणजे \'खरेदी किंमत\' होय.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"वस्तू विकून जी रक्कम मिळते, तिला गणिताच्या भाषेत काय म्हणतात?\",\"options\":[\"विक्री किंमत\",\"खरेदी किंमत\",\"मूळ किंमत\",\"बाजार भाव\"],\"answer\":0,\"explain\":\"रोपांच्या विक्रीतून मिळालेल्या रकमेला शिक्षकांनी \'विक्री किंमत\' म्हटले आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राघव आणि मुस्कान यांनी रोपांची विक्री वाढवण्यासाठी काय केले होते?\",\"options\":[\"रोपांची किंमत कमी केली\",\"रोपांची आकर्षक मांडणी व वैशिष्ट्ये लिहिली\",\"मोफत रोपे दिली\",\"जाहिरात केली\"],\"answer\":1,\"explain\":\"राघवने आकर्षक मांडणी केली होती आणि मुस्कानने वैशिष्ट्ये लिहून ठेवली होती.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"श्रध्दाच्या व्यवहारात ₹ 1560 ही कोणती किंमत आहे?\",\"options\":[\"खरेदी किंमत\",\"विक्री किंमत\",\"सवलत किंमत\",\"छापील किंमत\"],\"answer\":1,\"explain\":\"रोपांच्या विक्रीतून ₹ 1560 मिळाले, म्हणून ती विक्री किंमत आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर एका विद्यार्थ्याने ₹ 500 ची पुस्तके विकत घेतली, तर त्याची \'खरेदी किंमत\' किती असेल?\",\"options\":[\"₹ 1000\",\"₹ 500\",\"₹ 0\",\"₹ 250\"],\"answer\":1,\"explain\":\"वस्तू खरेदी करण्यासाठी दिलेली रक्कम म्हणजेच खरेदी किंमत होय.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"श्रध्दाने ₹ 1250 ला घेतलेली रोपे ₹ 1560 ला विकली, तर या व्यवहारातील विक्री किंमत ओळखा.\",\"options\":[\"₹ 1250\",\"₹ 1560\",\"₹ 310\",\"₹ 2810\"],\"answer\":1,\"explain\":\"विक्रीतून मिळालेली रक्कम ₹ 1560 ही विक्री किंमत आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"श्रध्दाच्या व्यवहाराचे निरीक्षण केल्यास, खरेदी किंमत आणि विक्री किंमत यांत काय संबंध दिसतो?\",\"options\":[\"खरेदी किंमत विक्री किंमतीपेक्षा जास्त आहे\",\"विक्री किंमत खरेदी किंमतीपेक्षा जास्त आहे\",\"दोन्ही किंमती समान आहेत\",\"विक्री किंमत शून्य आहे\"],\"answer\":1,\"explain\":\"येथे विक्री किंमत (1560) ही खरेदी किंमतीपेक्षा (1250) मोठी आहे.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"श्रध्दाला या व्यवहारात मूळ खर्चापेक्षा जास्त पैसे मिळाले की कमी?\",\"options\":[\"कमी पैसे मिळाले\",\"जास्त पैसे मिळाले\",\"तेवढेच पैसे मिळाले\",\"काहीच मिळाले नाही\"],\"answer\":1,\"explain\":\"1560 ही रक्कम 1250 पेक्षा मोठी असल्याने तिला जास्त पैसे मिळाले.\",\"topic\":\"समजून घ्या\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"व्यवहारात \'फायदा\' या शब्दाला काय म्हणतात?\",\"options\":[\"तोटा\",\"नफा\",\"खरेदी\",\"विक्री\"],\"answer\":1,\"explain\":\"पाठात शिक्षकांनी सांगितले आहे की फायद्यालाच व्यवहारात आपण नफा म्हणतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"नफा काढण्याचे योग्य सूत्र कोणते?\",\"options\":[\"नफा = खरेदी किंमत - विक्री किंमत\",\"नफा = विक्री किंमत + खरेदी किंमत\",\"नफा = विक्री किंमत - खरेदी किंमत\",\"नफा = खरेदी किंमत + नफा\"],\"answer\":2,\"explain\":\"विक्री किमतीतून खरेदी किंमत वजा केल्यावर नफा मिळतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"तोटा काढण्याचे सूत्र खालीलपैकी कोणते?\",\"options\":[\"तोटा = खरेदी किंमत - विक्री किंमत\",\"तोटा = विक्री किंमत - खरेदी किंमत\",\"तोटा = खरेदी किंमत + विक्री किंमत\",\"तोटा = विक्री किंमत + तोटा\"],\"answer\":0,\"explain\":\"खरेदी किमतीपेक्षा विक्री किंमत कमी असेल तर तोटा होतो, म्हणून तोटा = खरेदी किंमत - विक्री किंमत.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जेव्हा विक्री किंमत ही खरेदी किमतीपेक्षा जास्त असते, तेव्हा काय होतो?\",\"options\":[\"तोटा\",\"नुकसान\",\"नफा\",\"खर्च\"],\"answer\":2,\"explain\":\"खरेदी किमतीपेक्षा विक्री किंमत जास्त असेल तर नफा होतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खरेदी किमतीपेक्षा विक्री किंमत कमी असेल तर काय होते?\",\"options\":[\"नफा\",\"फायदा\",\"तोटा\",\"बचत\"],\"answer\":2,\"explain\":\"खरेदी किमतीपेक्षा विक्री किंमत कमी असेल तर नुकसान म्हणजेच तोटा होतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर खरेदी किंमत ₹ १२५० आणि विक्री किंमत ₹ १५६० असेल, तर नफा किती होईल?\",\"options\":[\"₹ २१०\",\"₹ ३१०\",\"₹ ४१०\",\"₹ ३००\"],\"answer\":1,\"explain\":\"१५६० - १२५० = ३१०, म्हणून नफा ₹ ३१० आहे.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"मुस्कानच्या मते, खरेदी किमतीपेक्षा कमी पैसे मिळाले तर काय होते?\",\"options\":[\"नफा होतो\",\"नुकसान होते\",\"फायदा होतो\",\"काहीच होत नाही\"],\"answer\":1,\"explain\":\"मुस्कान म्हणते की खरेदी किमतीपेक्षा कमी पैसे मिळाले तर आपले नुकसान झाले असते.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती स्थिती \'तोटा\' दर्शवते?\",\"options\":[\"विक्री किंमत > खरेदी किंमत\",\"विक्री किंमत = खरेदी किंमत\",\"विक्री किंमत < खरेदी किंमत\",\"विक्री किंमत + खरेदी किंमत\"],\"answer\":2,\"explain\":\"जेव्हा विक्री किंमत ही खरेदी किमतीपेक्षा कमी (<) असते, तेव्हा तोटा होतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जर एका व्यवहारात विक्री किंमत ₹ ९०० आणि खरेदी किंमत ₹ १००० असेल, तर काय होईल?\",\"options\":[\"₹ १०० नफा\",\"₹ १०० तोटा\",\"₹ १९०० नफा\",\"काहीच नाही\"],\"answer\":1,\"explain\":\"येथे विक्री किंमत खरेदी किमतीपेक्षा कमी आहे, म्हणून १००० - ९०० = १०० रुपये तोटा होईल.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"नफा होण्यासाठी खालीलपैकी कोणती अट आवश्यक आहे?\",\"options\":[\"विक्री किंमत > खरेदी किंमत\",\"विक्री किंमत < खरेदी किंमत\",\"विक्री किंमत = खरेदी किंमत\",\"खरेदी किंमत > विक्री किंमत\"],\"answer\":0,\"explain\":\"जेव्हा विक्री किंमत खरेदी किमतीपेक्षा जास्त असते, तेव्हाच नफा होतो.\",\"topic\":\"नफा व तोटा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"राघवने केलेल्या वजाबाकीनुसार (१५६० - १२५० = ३१०), १५६० ही कोणती किंमत आहे?\",\"options\":[\"खरेदी किंमत\",\"तोटा\",\"विक्री किंमत\",\"नुकसान\"],\"answer\":2,\"explain\":\"नफा काढताना विक्री किमतीतून खरेदी किंमत वजा करतात, म्हणून १५६० ही विक्री क