्री किंमत किती?\",\"options\":[\"₹ 4,550\",\"₹ 10,000\",\"₹ 11,250\",\"₹ 6,700\"],\"answer\":2,\"explain\":\"विक्री किंमत = ४५० × २५ = ₹ ११,२५०.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"बियाणे (८५०), खत व औषधे (१२५०), मजुरी (१६५०) आणि वाहतूक (८००) यावरून आकाशाची एकूण खरेदी किंमत किती झाली?\",\"options\":[\"₹ 4,550\",\"₹ 4,000\",\"₹ 3,750\",\"₹ 5,000\"],\"answer\":0,\"explain\":\"८५० + १२५० + १६५० + ८०० = ₹ ४,५५० ही एकूण खरेदी किंमत आहे.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"नफा काढण्याचे योग्य सूत्र कोणते?\",\"options\":[\"नफा = खरेदी किंमत – विक्री किंमत\",\"नफा = विक्री किंमत + खरेदी किंमत\",\"नफा = विक्री किंमत – खरेदी किंमत\",\"नफा = एकूण खर्च + मजुरी\"],\"answer\":2,\"explain\":\"नफा काढण्यासाठी विक्री किमतीतून खरेदी किंमत वजा करतात.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"आकाशाला सेंद्रिय मेथीच्या या संपूर्ण व्यवहारात किती नफा झाला?\",\"options\":[\"₹ 4,550\",\"₹ 11,250\",\"₹ 6,700\",\"₹ 5,000\"],\"answer\":2,\"explain\":\"नफा = ११,२५० - ४,५५० = ₹ ६,७००.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"एकूण खरेदी किंमत काढताना वाहतूक खर्च का मिळवला जातो?\",\"options\":[\"कारण तो विक्री करण्यापूर्वीचा आवश्यक खर्च आहे\",\"कारण तो विक्री नंतरचा खर्च आहे\",\"कारण तो नफ्याचा भाग आहे\",\"कारण तो बियाण्यांचा खर्च आहे\"],\"answer\":0,\"explain\":\"वस्तू विक्रीसाठी तयार करण्यापूर्वीचा सर्व खर्च खरेदी किमतीत धरला जातो.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"आकाशाने रासायनिक खतांऐवजी कशासाठी ₹ १,२५० खर्च केले?\",\"options\":[\"बियाण्यासाठी\",\"वाहतुकीसाठी\",\"मजुरीसाठी\",\"शेणखत व जैविक औषधांसाठी\"],\"answer\":3,\"explain\":\"आकाशाने शेणखत व जैविक औषधांसाठी ₹ १,२५० खर्च केले.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर आकाशाची एकूण खरेदी किंमत ₹ ४,५५० असेल आणि विक्री किंमत ₹ ४,००० असती, तर काय झाले असते?\",\"options\":[\"नफा\",\"तोटा\",\"नफा किंवा तोटा काहीच नाही\",\"फक्त मजुरीचा खर्च निघाला असता\"],\"answer\":1,\"explain\":\"खरेदी किंमत विक्री किमतीपेक्षा जास्त असल्यास तोटा होतो.\",\"topic\":\"एकूण खरेदी किंमत\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"एकूण खरेदी किंमत काढण्याचे योग्य सूत्र कोणते?\",\"options\":[\"एकूण खरेदी किंमत = मूळ खरेदी किंमत - इतर खर्च\",\"एकूण खरेदी किंमत = मूळ खरेदी किंमत + इतर खर्च\",\"एकूण खरेदी किंमत = विक्री किंमत + नफा\",\"एकूण खरेदी किंमत = विक्री किंमत ÷ साड्यांची संख्या\"],\"answer\":1,\"explain\":\"पाठातील सूत्रानुसार, एकूण खरेदी किंमत म्हणजे मूळ खरेदी किंमत आणि इतर खर्च यांची बेरीज होय.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"सेवाभावी संस्था कोणत्या तत्त्वावर वस्तूंची विक्री करतात?\",\"options\":[\"भरपूर नफा\",\"केवळ तोटा\",\"ना नफा ना तोटा\",\"फक्त वाहतूक खर्च\"],\"answer\":2,\"explain\":\"पाठात उल्लेख केल्याप्रमाणे सेवाभावी संस्था \'ना नफा ना तोटा\' या तत्त्वावर काम करतात.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"संगीताने साड्यांच्या वाहतुकीसाठी किती रुपये खर्च केले?\",\"options\":[\"₹ 10,800\",\"₹ 5,250\",\"₹ 1,400\",\"₹ 750\"],\"answer\":3,\"explain\":\"दिलेल्या उदाहरणात वाहतुकीसाठी ₹ 750 खर्च झाल्याचे नमूद केले आहे.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"एकूण खरेदी किंमत निश्चित करताना मूळ किमतीत खालीलपैकी काय मिळवले जाते?\",\"options\":[\"नफा\",\"इतर खर्च (उदा. वाहतूक, कर)\",\"विक्री किंमत\",\"तोटा\"],\"answer\":1,\"explain\":\"वस्तू आणण्यासाठी लागणारा वाहतूक खर्च किंवा कर यांसारखे इतर खर्च मूळ किमतीत मिळवले जातात.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"नफा झाला असता, एकूण विक्री किंमत काढण्याचे सूत्र काय असेल?\",\"options\":[\"विक्री किंमत = नफा + एकूण खरेदी किंमत\",\"विक्री किंमत = नफा - एकूण खरेदी किंमत\",\"विक्री किंमत = एकूण खरेदी किंमत ÷ नफा\",\"विक्री किंमत = एकूण खरेदी किंमत - नफा\"],\"answer\":0,\"explain\":\"नफा मिळवण्यासाठी खरेदी किमतीत नफ्याची रक्कम मिळवावी लागते.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"ग्राहकांशी रागाने वागल्यास काय परिणाम होईल असे पाठात सुचवले आहे?\",\"options\":[\"ग्राहक पुन्हा येतील\",\"ग्राहक पुन्हा येणार नाहीत\",\"नफा वाढेल\",\"तोटा कमी होईल\"],\"answer\":1,\"explain\":\"व्यवसायात ग्राहकांशी चांगले वागणे महत्त्वाचे असते, अन्यथा ते परत येत नाहीत.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर मूळ खरेदी किंमत ₹ 10,800 आणि इतर खर्च ₹ 750 असेल, तर एकूण खरेदी किंमत किती?\",\"options\":[\"₹ 11,550\",\"₹ 10,050\",\"₹ 11,000\",\"₹ 12,000\"],\"answer\":0,\"explain\":\"10,800 + 750 = 11,550 ही एकूण खरेदी किंमत होईल.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"एकूण विक्री किंमत ₹ 16,800 असून साड्यांची संख्या 12 असल्यास, एका साडीची विक्री किंमत किती?\",\"options\":[\"₹ 1,200\",\"₹ 1,400\",\"₹ 1,500\",\"₹ 1,600\"],\"answer\":1,\"explain\":\"16,800 ÷ 12 = 1,400, म्हणून एका साडीची विक्री किंमत ₹ 1,400 आहे.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"संगीताला 12 साड्या विकून एकूण किती नफा झाला?\",\"options\":[\"₹ 11,550\",\"₹ 5,250\",\"₹ 1,400\",\"₹ 750\"],\"answer\":1,\"explain\":\"उदाहरणात स्पष्ट दिले आहे की सर्व साड्या विकून तिला ₹ 5,250 नफा झाला.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"एकूण खरेदी किंमत ₹ 11,550 आणि नफा ₹ 5,250 असल्यास, एकूण विक्री किंमत किती होईल?\",\"options\":[\"₹ 16,800\",\"₹ 6,300\",\"₹ 15,000\",\"₹ 17,000\"],\"answer\":0,\"explain\":\"11,550 + 5,250 = 16,800 ही एकूण विक्री किंमत आहे.\",\"topic\":\"नमुना उदाहरणे (एकूण खरेदी किंमत)\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"एका वस्तूची विक्री किंमत काढण्यासाठी एकूण विक्री किमतीला कशाने भागावे लागते?\",\"options\":[\"नफ्याने\",\"एकूण खरेदी किमतीने\",\"वस्तूंच्या एकूण संख्येने\",\"वाहतूक खर्चाने\"],\"answer\":2,\"explain\":\"एका वस्तूची किंमत काढण्यासाठी एकूण विक्री किमतीला वस्तूंच्या एकूण संख्