rt\":10,\"bloom\":\"apply\"},{\"q\":\"मांजरीचे पिल्लू पाहताच ते मांजरीचे आहे हे कशावरून ओळखता येते?\",\"options\":[\"त्याच्या आवाजावरून\",\"त्याच्या शरीराच्या ठेवणीवरून\",\"त्याच्या खाण्याच्या सवयीवरून\",\"ते कोठे राहते त्यावरून\"],\"answer\":1,\"explain\":\"शरीराची ठेवण आईवडिलांसारखी असल्याने पिल्लू ओळखता येते.\",\"topic\":\"करून पाहा\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात दिलेल्या उदाहरणांपैकी कोणता प्राणी आपल्या पिल्लाला थेट जन्म देतो?\",\"options\":[\"पक्षी\",\"मासा\",\"गाय\",\"डास\"],\"answer\":2,\"explain\":\"गाय, कुत्रा, मांजर यांसारखे प्राणी पिल्लांना थेट जन्म देतात.\",\"topic\":\"करून पाहा\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"बियांच्या प्रयोगासाठी उताऱ्यात खालीलपैकी कोणत्या बियांचा उल्लेख नाही?\",\"options\":[\"मका\",\"घेवडा\",\"गहू\",\"टोमॅटो\"],\"answer\":2,\"explain\":\"उताऱ्यात मिरची, वांगी, घेवडा, टोमॅटो आणि मका यांचा उल्लेख आहे, गव्हाचा नाही.\",\"topic\":\"करून पाहा\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पिल्लू कोणत्या प्राण्याचे आहे हे ओळखता येत नाही, असे कधी घडते का?\",\"options\":[\"हो, नेहमीच घडते\",\"नाही, कारण पिल्ले आईवडिलांसारखीच दिसतात\",\"केवळ पक्ष्यांच्या बाबतीत घडते\",\"केवळ माशांच्या बाबतीत घडते\"],\"answer\":1,\"explain\":\"पिल्लांची ठेवण आईवडिलांसारखीच असल्याने ते कोणत्या प्राण्याचे आहे हे ओळखता येते.\",\"topic\":\"करून पाहा\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"पावसाळ्याच्या सुरुवातीला बेडकाची अंडी कोठे आढळतात?\",\"options\":[\"जमिनीवर गवतात\",\"तळ्याकाठच्या पाण्यातील वनस्पतींच्या फांद्यांवर\",\"झाडांच्या शेंड्यावर\",\"कोरड्या वाळूमध्ये\"],\"answer\":1,\"explain\":\"पावसाळ्याच्या सुरुवातीला तळ्याकाठच्या पाण्यातील वनस्पतींच्या फांद्यांकडे लक्ष दिल्यास तेथे अंड्यांचे पुंजके दिसतात.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"बेडकाच्या अंड्यांचे पुंजके दिसायला कसे असतात?\",\"options\":[\"कापसासारखे\",\"दगडासारखे\",\"फेसासारखे\",\"काचेच्या गोळ्यांसारखे\"],\"answer\":2,\"explain\":\"पाण्यालगतच्या भागांजवळ बेडकाच्या अंड्यांचे फेसासारखे पुंजके दिसतात.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"अंड्यातून बाहेर आलेले बेडकाचे पिल्लू सुरुवातीला कशासारखे दिसते?\",\"options\":[\"लहान बेडकासारखे\",\"माशासारखे\",\"लांबट अळीसारखे\",\"गोल चेंडूसारखे\"],\"answer\":2,\"explain\":\"अंड्यातून बाहेर आलेले पिल्लू बेडकासारखे नसते, ते लांबट अळीसारखे दिसते.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"बेडकाच्या पिल्लाचे रूपांतर पूर्ण बेडकात होईपर्यंत होणाऱ्या बदलांना काय म्हणतात?\",\"options\":[\"वाढ\",\"अवस्थांतर\",\"हालचाल\",\"पोषण\"],\"answer\":1,\"explain\":\"बेडकाच्या शरीरात होणाऱ्या टप्प्याटप्प्यातील बदलांना जीवनक्रम किंवा अवस्थांतर म्हणतात.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"बेडकाच्या पिल्लाच्या वाढीच्या काही काळात त्याचे श्वसन कशाद्वारे होते?\",\"options\":[\"नाकपुड्यांनी\",\"त्वचेने\",\"फुफ्फुसांनी\",\"कल्ल्यांनी\"],\"answer\":3,\"explain\":\"बेडकाच्या पिल्लाच्या रूपांतरणाच्या काळात काही काळ त्याचे श्वसन कल्ल्यांनी होते.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, अंड्यांचा पुंजका बाटलीतील पाण्यात कशा प्रकारे ठेवला आहे?\",\"options\":[\"पाण्याच्या तळाशी बुडवून\",\"पाण्यावर किंचित वर राहील असा\",\"बाटलीच्या बाहेर कोरड्या जागी\",\"पाण्यात पूर्णपणे तरंगणारा\"],\"answer\":1,\"explain\":\"आकृती आणि मजकुरानुसार, अंडी आणि फांदी पाण्यात किंचित वर राहील अशी ठेवली जाते.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"understand\",\"figure_image\":\"37\\/021_102.jpg\"},{\"q\":\"बेडकाच्या जीवनक्रमाचा अभ्यास करताना निरीक्षणांच्या प्रत्येक चित्राखाली काय लिहिणे आवश्यक आहे?\",\"options\":[\"स्वतःचे नाव\",\"बेडकाचे नाव\",\"त्या दिवसाची तारीख\",\"तळ्याचे नाव\"],\"answer\":2,\"explain\":\"मजकुरानुसार, प्रत्येक चित्राखाली त्या दिवसाची तारीख लिहायला विसरू नका असे सांगितले आहे.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला बेडकाच्या अवस्थांतराचे निरीक्षण करायचे असेल, तर तुम्ही दिवसातून किती वेळा निरीक्षण कराल?\",\"options\":[\"एकदा\",\"दोनदा\",\"तीन वेळा\",\"पाच वेळा\"],\"answer\":2,\"explain\":\"मजकुरात आठवडाभर रोज दिवसातून तीन वेळा निरीक्षण करण्यास सांगितले आहे.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"बेडकाच्या वाढीच्या एका विशिष्ट अवस्थेत त्याला खालीलपैकी कोणते अवयव असतात जे पूर्ण वाढ झालेल्या बेडकात नसतात?\",\"options\":[\"फक्त पुढचे पाय\",\"मागचे दोन पाय आणि शेपूट\",\"फक्त डोळे\",\"फक्त कल्ले आणि पंख\"],\"answer\":1,\"explain\":\"अवस्थांतराच्या एका भागात पिल्लाला फक्त मागचे दोन पाय आणि शेपूट असते.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत दर्शविल्याप्रमाणे, बेडकाच्या जीवनक्रमात बाणांच्या दिशेनुसार सर्वात शेवटची अवस्था कोणती आहे?\",\"options\":[\"अंडी\",\"शेपूट असलेले पिल्लू\",\"कल्ले असलेले पिल्लू\",\"पूर्ण वाढ झालेला बेडूक\"],\"answer\":3,\"explain\":\"आकृतीमधील बाण अंड्यांपासून सुरू होऊन शेवटी जमिनीवर बसलेल्या पूर्ण बेडकाकडे जातात.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"analyze\",\"figure_image\":\"37\\/021_103.jpg\"},{\"q\":\"मित्रांनी केलेल्या नोंदी आणि तुमच्या नोंदी यांची तुलना केल्यावर कशाबद्दल माहिती मिळू शकते?\",\"options\":[\"बेडकाचा रंग कोणता आहे\",\"बदलांसाठी लागलेला वेळ सारखा आहे की त्यात फरक आहे\",\"बेडूक काय खातो\",\"तळ्यात किती पाणी आहे\"],\"answer\":1,\"explain\":\"नोंदींची तुलना केल्यावर बदलांसाठी लागलेला वेळ जवळपास सारखाच आहे की त्यात फरक आहे हे समजते.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"evaluate\"},{\"q\":\"बेडकाच्या जीवनक्रमातील अवस्थांचा योग्य क्रम कोणता?\",\"options\":[\"बेडूक -> अंडी -> शेपूट असलेले पिल्लू -> अळीसारखे पिल्लू\",\"अंडी -> अळीसारखे पिल्लू -> दोन पाय व शेपूट असलेले पिल्लू -> बेडूक\",\"अळीसारखे पिल्लू -> अंडी -> बेडूक -> शेपूट असलेले पिल्लू\",\"शेपूट असलेले पिल्लू -> अंडी -> अळीसारखे पिल्लू -> बेडूक\"],\"answer\":1,\"explain\":\"मजकुरानुसार प्रथम अंडी, मग अळीसारखे पिल्लू, मग पाय व शेपूट असलेली अवस्था आणि शेवटी बेडूक असा क्रम असतो.\",\"topic\":\"बेडकाचा जीवनक्रम\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"सजीवांची प्रमुख लक्षणे कोणती आहेत?\",\"options\":[\"हालचाल आणि श्वसन\",\"वाढ आणि प्रजनन\",\"उत्सर्जन आणि चेतनाक्षमता\",\"अन्न आणि पोषण\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार वाढ आणि प्रजनन ही सजीवांची प्रमुख लक्षणे आहेत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"बीज रुजून त्यापासून नवीन रोपाची वाढ सुरू होण्याच्या क्रियेला काय म्हणतात?\",\"options\":[\"प्रजनन\",\"उत्सर्जन\",\"बीजांकुरण\",\"जीवनक्रम\"],\"answer\":2,\"explain\":\"बीज रुजून नवीन रोप तयार होण्याच्या प्रक्रियेला बीजांकुरण असे म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"झाडाची पाने किंवा साल गळणे ही कोणत्या क्रियेची उदाहरणे आहेत?\",\"options\":[\"वाढ\",\"उत्सर्जन\",\"प्रजनन\",\"चेतनाक्षमता\"],\"answer\":1,\"explain\":\"पाने गळणे आणि साल गळणे ही वनस्पतींमधील उत्सर्जनाची उदाहरणे आहेत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"सजीवांना होणारी आसपासच्या परिस्थितीची जाण आणि त्या परिस्थितीत त्यांच्या कृती यांना काय म्हणतात?\",\"options\":[\"प्रतिसाद\",\"चेतना\",\"चेतनाक्षमता\",\"हालचाल\"],\"answer\":2,\"explain\":\"परिस्थितीची जाण आणि त्यानुसार होणारी कृती म्हणजे चेतनाक्षमता होय.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"सजीवांना अन्नाची गरज प्रामुख्याने कशासाठी असते?\",\"options\":[\"केवळ हालचाल करण्यासाठी\",\"ऊर्जा आणि वाढ यांसाठी\",\"केवळ उत्सर्जन करण्यासाठी\",\"जागा बदलण्यासाठी\"],\"answer\":1,\"explain\":\"ऊर्जा मिळवण्यासाठी आणि शरीराच्या वाढीसाठी प्रत्येक सजीवाला अन्नाची गरज असते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"वनस्पती आणि प्राणी यांच्या हालचालींमधील मुख्य फरक कोणता?\",\"options\":[\"प्राणी स्वतःची जागा बदलू शकत नाहीत\",\"वनस्पती स्वतःची जागा बदलू शकत नाहीत\",\"वनस्पतींमध्ये हालचाल होत नाही\",\"प्राणी हालचाल करू शकत नाहीत\"],\"answer\":1,\"explain\":\"प्राणी हालचाल करून जागा बदलतात, पण वनस्पती स्वतःची जागा बदलू शकत नाहीत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता पदार्थ वनस्पतींचे उत्सर्जन दर्शवतो?\",\"options\":[\"कार्बन डायऑक्साइड\",\"मलमूत्र\",\"डिंक\",\"घाम\"],\"answer\":2,\"explain\":\"डिंक हा वनस्पतींमधून बाहेर पडणारा उत्सर्जित पदार्थ आहे.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"वाढीच्या काळात सजीवांच्या शरीर रचनेत होणाऱ्या बदलांना काय म्हणतात?\",\"options\":[\"बीजांकुरण\",\"जीवनक्रम\",\"चेतनाक्षमता\",\"पोषण\"],\"answer\":1,\"explain\":\"वाढीच्या काळातील शरीर रचनेतील बदलांना जीवनावस्था किंवा जीवनक्रम म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"एखाद्या सजीवाला होणारी जाणीव म्हणजे \'चेतना\' असेल, तर त्यावर त्याने केलेली क्रिया म्हणजे काय?\",\"options\":[\"उत्सर्जन\",\"प्रजनन\",\"प्रतिसाद\",\"वाढ\"],\"answer\":2,\"explain\":\"चेतनेवर होणाऱ्या क्रियेला प्रतिसाद असे म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"सजीवांच्या विविधतेबाबत कोणते विधान अचूक आहे?\",\"options\":[\"सर्व सजीव एकाच आकाराचे असतात\",\"सजीव फक्त विशालकाय शरीराचे असतात\",\"सजीवांमध्ये सूक्ष्म आकार ते विशालकाय शरीर अशी विविधता असते\",\"सर्व सजीव डोळ्यांनी दिसतात\"],\"answer\":2,\"explain\":\"सजीवांमध्ये सूक्ष्म आकारापासून ते मोठ्या विशालकाय शरीरापर्यंत विविधता आढळते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"अन्नामुळे सजीवांच्या शरीराचे काय होते?\",\"options\":[\"केवळ उत्सर्जन होते\",\"पोषण होते\",\"केवळ हालचाल होते\",\"केवळ प्रजनन होते\"],\"answer\":1,\"explain\":\"अन्नामुळे सजीवांच्या शरीराचे पोषण होते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"प्राण्यांच्या उत्सर्जनात खालीलपैकी कशाचा समावेश होतो?\",\"options\":[\"डिंक\",\"पाने गळणे\",\"घाम\",\"बीजांकुरण\"],\"answer\":2,\"explain\":\"घाम, कार्बन डायऑक्साइड आणि मलमूत्र ही प्राण्यांची उत्सर्जित द्रव्ये आहेत.\",\"topic\":\"आपण काय शिकलो?\",\"part\":12,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21870,37,6,'Science','mr','मापन','[\"मापन म्हणजे एखाद्या वस्तूची लांबी, अंतर, वजन किंवा आकारमान अचूकपणे मोजणे.\",\"मापनासाठी योग्य साधन आणि एकक वापरले पाहिजे.\",\"पूर्वी मापन पद्धती वेगवेगळ्या होत्या – हात, विती, मुठी इत्यादी; त्यामुळे मापन वेगळे येत.\",\"अप्रमाणित मापन म्हणजे वेगवेगळ्या व्यक्तींच्या मापनात फरक.\",\"प्रमाणित मापन म्हणजे सर्वांनी एकच एकक वापरून मोजणे, ज्यामुळे मापन एकसारखे येते.\",\"लांबीचे मुख्य एकक मीटर (m) आहे.\",\"१ मीटर = १०० सेंटीमीटर (cm).\",\"१ सेंटीमीटर = १० मिलिमीटर (mm).\",\"१ किलोमीटर (km) = १००० मीटर.\",\"मापन करताना मोजपट्टीचा आरंभबिंदू (०) स्पष्ट असावा.\",\"वस्तूची लांबी मोजताना ती मोजपट्टीच्या संपर्कात असावी.\",\"संदर्भबिंदू म्हणजे ज्या स्थिर बिंदूपासून अंतर मोजले जाते.\",\"तापमान मोजण्यासाठी तापमापी वापरतात – पारा, अल्कोहोल किंवा डिजिटल.\",\"सेल्सिअस (°C), फॅरेनहाइट (°F), केल्विन (K) ही तापमानाची एकके आहेत.\",\"डिजिटल तापमापी त्वचेवर ठेवून तापमान मोजतात.\",\"इन्फ्रारेड तापमापी वस्तूच्या पृष्ठभागाचे तापमान अंतरावरून मोजतात.\",\"मापनाची अचूकता वाढवण्यासाठी विशेष साधने जसे की व्हर्निअर कॅलिपर वापरतात.\",\"मापनात त्रुटी टाळण्यासाठी मोजपट्टीची स्थिती, आरंभबिंदू आणि संदर्भबिंदू योग्य ठेवणे आवश्यक आहे.\",\"मापनाची एकके बदलल्यास व्यापारात आणि विज्ञानात गोंधळ होतो.\",\"मापनाची एकके आंतरराष्ट्रीय पातळीवर मानकीकृत केली आहेत.\",\"मापन करताना मोजपट्टीची खुणा स्पष्ट व वाचनीय असाव्यात.\",\"मापनाचे परिणाम नोंदवताना द्रव्यमान, लांबी, तापमान इत्यादी एकके स्पष्टपणे लिहावीत.\"]','[{\"q\":\"पाठ्यपुस्तकातील व्याख्येनुसार \'मापन\' म्हणजे काय?\",\"options\":[\"वस्तूंची विक्री करणे\",\"माप घेणे\",\"चित्र काढणे\",\"खेळ खेळणे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात स्पष्टपणे दिले आहे की \'मापन म्हणजे माप घेणे\'.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत, कापड विक्रेता कापड मोजण्यासाठी कशाचा वापर करत आहे?\",\"options\":[\"हाताची वीत\",\"काचेची नळी\",\"मोजपट्टी किंवा टेप\",\"लाकडी दांडू\"],\"answer\":2,\"explain\":\"चित्रात कापड विक्रेता टेपचा वापर करून कापड मोजताना दिसत आहे.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"37\\/024_101.jpg\"},{\"q\":\"विटी-दांडूच्या खेळात दोन मित्रांनी मोजलेल्या अंतरात घोटाळा का झाला?\",\"options\":[\"दोघांना मोजता येत नव्हते\",\"दोघांच्या दांडूची लांबी वेगवेगळी होती\",\"मैदान खूप मोठे होते\",\"त्यांनी चुकीच्या ठिकाणी खूण केली\"],\"answer\":1,\"explain\":\"एकाचा दांडू आखूड तर दुसऱ्याचा अधिक लांबीचा असल्यामुळे मोजमापात फरक पडला.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, टेबलाची लांबी मोजण्यासाठी कोणत्या पद्धतीचा वापर केला जात आहे?\",\"options\":[\"पावले मोजणे\",\"वितीने मोजणे\",\"तराजूने मोजणे\",\"नळीने मोजणे\"],\"answer\":1,\"explain\":\"चित्रात एक मुलगी आणि एक व्यक्ती हाताच्या वितीचा वापर करून टेबलाची लांबी मोजत आहेत.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"37\\/025_101.jpg\"},{\"q\":\"क्रिकेटच्या खेळात १५ पावले अंतर मोजताना दोघांच्या खुणा वेगवेगळ्या जागी का आल्या असतील?\",\"options\":[\"प्रत्येकाच्या पावलाची लांबी वेगवेगळी असते\",\"खेळपट्टी वाकडी होती\",\"पंधरा अंक मोजताना चूक झाली\",\"स्टंपची जागा बदलली होती\"],\"answer\":0,\"explain\":\"व्यक्तीनुसार पावलांची लांबी बदलत असल्यामुळे १५ पावलांचे अंतर वेगवेगळे येते.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत, जमिनीवरील अंतर मोजण्यासाठी मुले कशाचा वापर करताना दिसत आहेत?\",\"options\":[\"दोरी आणि टेप\",\"दांडू आणि पावले\",\"तराजू आणि वजन\",\"नळी आणि पाणी\"],\"answer\":1,\"explain\":\"चित्रात मुले विटी-दांडूच्या खेळातील दांडूने आणि चालताना पावलांनी अंतर मोजताना दिसत आहेत.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"37\\/024_102.jpg\"},{\"q\":\"जर तुम्ही आणि तुमच्या मोठ्या भावाने एकाच बाकाची लांबी वितीने मोजली, तर कोणाच्या वितीची संख्या जास्त भरेल?\",\"options\":[\"भावाच्या वितीची संख्या जास्त असेल\",\"दोघांची संख्या समान असेल\",\"तुमच्या वितीची संख्या जास्त असेल\",\"कोणाचीच संख्या मोजता येणार नाही\"],\"answer\":2,\"explain\":\"तुमचा हात लहान असल्याने बाकाची लांबी भरून काढण्यासाठी जास्त विती लागतील.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दूधवाला माप भरून दूध देतो, तेव्हा तो नेमके कशाचे मोजमाप करत असतो?\",\"options\":[\"दुधाच्या लांबीचे\",\"दुधाच्या रंगाचे\",\"दुधाच्या धारकतेचे (प्रमाणाचे)\",\"दुधाच्या तापमानाचे\"],\"answer\":2,\"explain\":\"दूधवाला मापाचा वापर करून दुधाचे आकारमान किंवा प्रमाण मोजतो.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"भाजीवाली भाजी देताना कशाचे मापन करत असते?\",\"options\":[\"भाजीच्या लांबीचे\",\"भाजीच्या वजनाचे\",\"भाजीच्या चवीचे\",\"भाजीच्या रंगाचे\"],\"answer\":1,\"explain\":\"भाजीवाली तराजूचा वापर करून भाजीचे वजन मोजते.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"डॉक्टर हातातील नळीकडे (उदा. थर्मामीटर किंवा सिरिंज) निरखून पाहत आहेत, म्हणजे ते काय करत आहेत?\",\"options\":[\"नळीची स्वच्छता तपासत आहेत\",\"नळीची किंमत ठरवत आहेत\",\"काहीतरी मापन करत आहेत\",\"नळीने खेळत आहेत\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील प्रश्नानुसार डॉक्टर नळीकडे पाहून मापन करत असतात.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मोजमाप करताना \'घोटाळा\' टाळण्यासाठी खालीलपैकी काय करणे आवश्यक वाटते?\",\"options\":[\"प्रत्येकाने स्वतःच्या हाताने मोजावे\",\"मोजण्यासाठी वेगवेगळे दांडू वापरावेत\",\"सर्वांसाठी एकच प्रमाणित साधन वापरावे\",\"अंदाजाने माप सांगावे\"],\"answer\":2,\"explain\":\"साधने बदलली की मापन बदलते, म्हणून प्रमाणित साधनाची गरज असते.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"जर एकाच टेबलाची लांबी बोटांच्या साहाय्याने मोजली, तर सगळ्यांचे मापन समान का येत नाही?\",\"options\":[\"टेबल मोजताना मोठा होतो\",\"प्रत्येकाच्या बोटांची जाडी आणि लांबी वेगळी असते\",\"मोजताना अंक विसरले जातात\",\"टेबल सरकवला जातो\"],\"answer\":1,\"explain\":\"शरीराच्या अवयवांचे आकार प्रत्येकासाठी वेगळे असल्याने मापन समान येत नाही.\",\"topic\":\"मापन - प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"लांबी मोजण्यासाठी SI पद्धतीत कोणते मुख्य एकक वापरले जाते?\",\"options\":[\"सेंटीमीटर\",\"मीटर\",\"किलोमीटर\",\"मिलीमीटर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील तक्त्यानुसार लांबीचे SI एकक मीटर 