:\"remember\",\"figure_image\":\"37\\/028_104.jpg\"},{\"q\":\"प्रयोगशाळेत उकळत्या द्रवांचे तापमान मोजण्यासाठी कोणत्या मर्यादेचा तापमापी सोयीचा ठरतो?\",\"options\":[\"३५° सेल्सिअस ते ४२° सेल्सिअस\",\"०° सेल्सिअस ते ११०° सेल्सिअस\",\"२०° सेल्सिअस ते ८०° सेल्सिअस\",\"५०° सेल्सिअस ते १५०° सेल्सिअस\"],\"answer\":1,\"explain\":\"प्रयोगशाळेत उकळत्या द्रवांचे किंवा वाफेचे तापमान मोजण्यासाठी ०° सेल्सिअस ते ११०° सेल्सिअस मर्यादेचा तापमापी लागतो.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एका व्यक्तीला थंड वाटणारी वस्तू दुसऱ्या व्यक्तीला गरम वाटू शकते, यावरून काय निष्कर्ष निघतो?\",\"options\":[\"वस्तूचे तापमान सतत बदलत असते\",\"स्पर्शाने केलेले अंदाज नेहमी अचूक असतात\",\"नेमके तापमान मोजण्यासाठी तापमापीची गरज असते\",\"हाताचा स्पर्श तापमापीपेक्षा श्रेष्ठ असतो\"],\"answer\":2,\"explain\":\"व्यक्तीनुसार अंदाज बदलू शकतात, म्हणून अचूक मापनासाठी तापमापी आवश्यक असते.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"वैद्यकीय तापमापीचा वापर प्रामुख्याने कशासाठी केला जातो?\",\"options\":[\"उकळत्या पाण्याचे तापमान मोजण्यासाठी\",\"फ्रीजमधील दुधाचे तापमान पाहण्यासाठी\",\"शरीराचा ताप मोजण्यासाठी\",\"वाफेचे तापमान मोजण्यासाठी\"],\"answer\":2,\"explain\":\"आजारपणात शरीराचा ताप किती आहे हे पाहण्यासाठी वैद्यकीय तापमापी वापरतात.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला प्रयोगशाळेत पाण्याची वाफ मोजायची असेल, तर तुम्ही ३५°C ते ४२°C मर्यादेचा तापमापी का वापरू शकणार नाही?\",\"options\":[\"कारण तो तापमापी खूप मोठा असतो\",\"कारण वाफेचे तापमान या तापमापीच्या मर्यादेपेक्षा जास्त असू शकते\",\"कारण तो तापमापी फक्त डॉक्टरांकडेच असतो\",\"कारण तो तापमापी पाण्यात बुडवता येत नाही\"],\"answer\":1,\"explain\":\"वाफेचे तापमान मोजण्यासाठी ११०°C पर्यंतची मर्यादा असलेला तापमापी लागतो, ३५-४२°C ची मर्यादा अपुरी पडते.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"हाताच्या स्पर्शाने मिळणारी जाणीव ही कशाचे मोजमाप नसते?\",\"options\":[\"गरमपणाची\",\"थंडपणाची\",\"तापमानाचे\",\"अंदाजाचे\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट म्हटले आहे की, स्पर्शाने समजणारा अंदाज हे तापमानाचे मोजमाप नसते.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते विधान पाठातील माहितीनुसार अचूक आहे?\",\"options\":[\"तापमान मोजण्यासाठी कोणत्याही साधनाची गरज नसते\",\"तापमान फक्त सेल्सिअसमध्येच मोजता येते\",\"वैद्यकीय तापमापीला ज्वरमापी असेही म्हणतात\",\"हाताच्या स्पर्शाने तापमान नेमके किती आहे हे समजते\"],\"answer\":2,\"explain\":\"पाठात नमूद केल्याप्रमाणे वैद्यकीय तापमापीला ज्वरमापी असे म्हणतात.\",\"topic\":\"तापमान व तापमापी\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"तापमानाचे SI एकक कोणते आहे?\",\"options\":[\"अंश सेल्सिअस\",\"फॅरेनहाईट\",\"केल्व्हीन\",\"डिग्री\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, तापमानाचे SI एकक केल्व्हीन आहे आणि ते K या चिन्हाने दर्शवले जाते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मानवी शरीराचे सामान्य तापमान सुमारे किती असते?\",\"options\":[\"३५° सेल्सिअस\",\"३७° सेल्सिअस\",\"४०° सेल्सिअस\",\"४२° सेल्सिअस\"],\"answer\":1,\"explain\":\"मानवी शरीराचे सामान्य तापमान सुमारे ३७° सेल्सिअस असते असे पाठात नमूद केले आहे.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"डिजिटल तापमापीला हे नाव का दिले असावे?\",\"options\":[\"कारण ती काचेची असते.\",\"कारण ती सेलवर चालते.\",\"कारण ती तापमानाचा नेमका अंक (डिजिट) दाखवते.\",\"कारण ती फक्त काखेमध्ये वापरता येते.\"],\"answer\":2,\"explain\":\"तापमान नेमके किती आहे याचा अंक दाखवणाऱ्या तापमापीला डिजिटल तापमापी म्हणतात.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"डिजिटल तापमापीचे काम कशावर चालते?\",\"options\":[\"मोठ्या बॅटरीवर\",\"नाण्यासारख्या लहान सेलवर\",\"विजेच्या वायरवर\",\"सौर ऊर्जेवर\"],\"answer\":1,\"explain\":\"डिजिटल तापमापीचे काम नाण्यासारख्या लहान सेलवर चालते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"विमानतळ किंवा मोठ्या दुकानांसारख्या गर्दीच्या ठिकाणी शरीराला स्पर्श न करता तापमान मोजण्यासाठी काय वापरतात?\",\"options\":[\"डिजिटल तापमापी\",\"साधी काचेची तापमापी\",\"इन्फ्रारेड तापमापी\",\"प्रयोगशाळेतील तापमापी\"],\"answer\":2,\"explain\":\"व्यक्तीच्या शरीराला स्पर्श न करता पटकन तापमान समजण्यासाठी इन्फ्रारेड तापमापी वापरली जाते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"डिजिटल तापमापीच्या साहाय्याने कोणत्या दरम्यानचे तापमान मोजता येते?\",\"options\":[\"०° ते १००° सेल्सिअस\",\"३५° ते ४२° सेल्सिअस\",\"३७° ते ९८° सेल्सिअस\",\"१०° ते ५०° सेल्सिअस\"],\"answer\":1,\"explain\":\"डिजिटल तापमापीच्या साहाय्याने ३५° सेल्सिअसपासून ४२° सेल्सिअस या दरम्यानचे तापमान मोजता येते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"डिजिटल तापमापीने तापमान मोजताना कोणत्या आवाजाची वाट पाहावी लागते?\",\"options\":[\"गाण्याचा आवाज\",\"घंटीचा आवाज\",\"बीप आवाज\",\"शिट्टीचा आवाज\"],\"answer\":2,\"explain\":\"तापमान मोजताना बीप आवाज येईपर्यंत थांबावे लागते, त्यानंतर तापमानाची नोंद केली जाते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"संशोधनासाठीच्या प्रयोगांमध्ये तापमानाचे कोणते एकक वापरतात?\",\"options\":[\"केल्व्हीन\",\"सेल्सिअस\",\"फॅरेनहाईट\",\"मीटर\"],\"answer\":0,\"explain\":\"केल्व्हीन हे एकक संशोधनासाठीच्या प्रयोगांमध्ये वापरतात.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"कोरोना साथीच्या काळात इन्फ्रारेड तापमापीचा वापर प्रामुख्याने का झाला असावा?\",\"options\":[\"ती स्वस्त असते म्हणून.\",\"ती दिसायला आधुनिक असते म्हणून.\",\"संसर्ग टाळण्यासाठी स्पर्श न करता तापमान मोजणे आवश्यक होते म्हणून.\",\"ती फक्त पाणी मोजण्यासाठी वापरतात म्हणून.\"],\"answer\":2,\"explain\":\"संसर्गजन्य आजार असलेल्या व्यक्तीच्या संपर्कात न येता तापमान मोजण्यासाठी याचा वापर झाला.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"डिजिटल तापमापी वापरताना रिसेट बटन दाबल्यानंतर तापमापीचा तळाचा भाग कुठे ठेवावा?\",\"options\":[\"हाताच्या तळव्यावर\",\"कपाळावर\",\"काखेमध्ये त्वचेला स्पर्श होईल असा\",\"पाण्यामध्ये\"],\"answer\":2,\"explain\":\"पाठातील कृतीनुसार, तापमापीचा तळाचा भाग त्वचेला स्पर्श होईल असा काखेमध्ये ठेवावा.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"इन्फ्रारेड तापमापीचे नाव कोणत्या आधारावर ठेवले आहे?\",\"options\":[\"त्यातील सेलच्या प्रकारावरून\",\"वापरल्या जाणाऱ्या किरणांच्या आधारावरून\",\"त्याच्या आकारावरून\",\"शोध लावणाऱ्या शास्त्रज्ञाच्या नावावरून\"],\"answer\":1,\"explain\":\"इन्फ्रारेड नावाच्या किरणांच्या आधाराने याचे काम चालते, म्हणून याला इन्फ्रारेड तापमापी म्हणतात.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"तापमान मोजण्यासाठी खालीलपैकी कोणते एकक वापरले जात नाही?\",\"options\":[\"अंश सेल्सिअस (⁰से)\",\"फॅरेनहाइट (⁰F)\",\"केल्व्हीन (K)\",\"किलोग्रॅम (kg)\"],\"answer\":3,\"explain\":\"सेल्सिअस, फॅरेनहाइट आणि केल्व्हीन ही तापमानाची एकके आहेत, किलोग्रॅम हे वजनाचे एकक आहे.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"डिजिटल तापमापी वापरून झाल्यावर काय करणे आवश्यक आहे?\",\"options\":[\"ती तशीच उघडी ठेवावी.\",\"तिचे टोक स्वच्छ करून कोरड्या कापडाने पुसून ठेवावे.\",\"ती पाण्यात बुडवून ठेवावी.\",\"तिचा सेल काढून टाकावा.\"],\"answer\":1,\"explain\":\"वापरानंतर तापमापीचे टोक स्वच्छ करून कोरड्या कापडाने पुसून ठेवणे ही स्वच्छतेची पायरी आहे.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत तापमापीचा वापर कशा प्रकारे केला जात आहे?\",\"options\":[\"व्यक्तीच्या काखेला स्पर्श करून\",\"व्यक्तीच्या चेहऱ्यापासून थोड्या अंतरावर धरून\",\"व्यक्तीच्या जिभेखाली ठेवून\",\"व्यक्तीच्या हाताला लावून\"],\"answer\":1,\"explain\":\"आकृतीत दाखवल्याप्रमाणे इन्फ्रारेड तापमापी चेहऱ्यापासून थोड्या अंतरावर धरली जाते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"37\\/030_102.jpg\"},{\"q\":\"दिलेल्या आकृतीतील तापमापी कोणत्या तत्त्वावर आधारित आहे?\",\"options\":[\"पाऱ्याचे प्रसरण\",\"इन्फ्रारेड किरण\",\"पाण्याचे बाष्पीभवन\",\"हवेचा दाब\"],\"answer\":1,\"explain\":\"आकृतीत इन्फ्रारेड तापमापी दाखवली आहे, जी इन्फ्रारेड किरणांच्या आधाराने काम करते.\",\"topic\":\"डिजिटल व इन्फ्रारेड तापमापी\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"37\\/030_102.jpg\"},{\"q\":\"प्रयोगशाळेतील तापमापीच्या तळाशी असलेल्या काचेच्या फुग्यामध्ये कोणता द्रव भरलेला असतो?\",\"options\":[\"पाणी किंवा तेल\",\"पारा किंवा रंगीत अल्कोहोल\",\"केवळ शुद्ध पाणी\",\"दूध किंवा सरबत\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, तापमापीच्या फुग्यामध्ये पारा किंवा रंगीत अल्कोहोल भरलेला असतो.\",\"topic\":\"प्रयोगशाळेतील तापमापी व वापर\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"तापमापीच्या फुग्याला उष्णता मिळाली की त्यातील द्रवाच्या आकारमानावर काय परिणाम होतो?\",\"options\":[\"आकारमान कमी होते\",\"आकारमान स्थिर राहते\",\"आकारमान वाढते\",\"द्रवाचे वायूत रूपांतर होते\"],\"answer\":2,\"explain\":\"उष्णता मिळाली की द्रवाचे आकारमान वाढते आणि तो प्रसरण पावून नळीत वर जातो.\",\"topic\":\"प्रयोगशाळेतील तापमापी व वापर\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"तापमापीवरील दोन मोठ्या खुणांमधील फरक १०° सेल्सिअस असेल आणि त्यामध्ये १० लहान भाग असतील, तर प्रत्येक लहान खूण किती तापमान दर्शवते?\",\"options\":[\"०.१° सेल्सिअस\",\"५° सेल्सिअस\",\"१° सेल्सिअस\",\"१०° सेल्सिअस\"],\"answer\":2,\"explain\":\"१० अंश फरकात १० भाग असल्यास, प्रत्येक भाग १° सेल्सिअस (१०\\/१० = १) दर्शवतो.\",\"topic\":\"प्रयोगशाळेतील तापमापी व वापर\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"तापमानाचे अचूक मोजमाप करण्यासाठी तापमापीतील द्रवाची पातळी कोठे असणे आवश्यक आहे?\",\"options\":[\"डोळ्यांच्या वरच्या बाजूला\",\"डोळ्यांच्या खालच्या बाजूला\",\"डोळ्यांसमोर सरळ रेषेत\",\"कोणत्याही स्थितीत\"],\"answer\":2,\"explain\":\"अचूक मोजमापासाठी द्रवाची पातळी डोळ्यांसमोर येईल अशा प्रकारे तापमापी धरावा लागतो.\",\"topic\":\"प्रयोगशाळेतील तापमापी व वापर\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत तापमापी धरण्याची कोणती योग्य पद्धत दर्शवली आहे?\",\"options\":[\"तापमापी तिरपा धरला आहे\",\"तापमापी सरळ आणि उभा धरला आहे\",\"तापमापी भांड्याच्या तळाला टेकवला आहे\",