{\"q\":\"पिंपळाचे पान काही दिवस पाण्यात ठेवल्यास त्याचा मऊ भाग कुजून गेल्यावर काय शिल्लक राहते?\",\"options\":[\"पानाचे देठ\",\"जाळीदार सांगाडा\",\"पानाचा रंग\",\"पानाची राख\"],\"answer\":1,\"explain\":\"पिंपळाचे पान पाण्यात ठेवल्यास मऊ भाग कुजतो आणि शिरांचा जाळीदार सांगाडा शिल्लक राहतो.\",\"topic\":\"पानांचा शिराविन्यास\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"आंब्याचे पान कडेपासून मध्यभागापर्यंत फाडण्याचा प्रयत्न केल्यास ते सरळ रेषेत का फाटत नाही?\",\"options\":[\"त्यात शिरांचे गुंतागुंतीचे जाळे असते\",\"त्यात समांतर शिरा असतात\",\"ते पान खूप जाड असते\",\"त्या पानाचा आकार मोठा असतो\"],\"answer\":0,\"explain\":\"ज्या पानांमध्ये शिरांचे गुंतागुंतीचे जाळे (जाळीदार शिराविन्यास) असते, ती पाने सरळ रेषेत फाटत नाहीत.\",\"topic\":\"पानांचा शिराविन्यास\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या वनस्पतीच्या पानात समांतर शिराविन्यास आढळतो?\",\"options\":[\"वड\",\"पिंपळ\",\"आंबा\",\"केळी\"],\"answer\":3,\"explain\":\"केळीच्या पानात शिरा एकमेकांना समांतर असतात, म्हणून त्यात समांतर शिराविन्यास असतो.\",\"topic\":\"पानांचा शिराविन्यास\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"ज्या पानांमधील शिरा वहीच्या कागदावरील रेषांप्रमाणे एकमेकांना समांतर असतात, त्या मांडणीला काय म्हणतात?\",\"options\":[\"जाळीदार शिराविन्यास\",\"गुंतागुंतीचा शिराविन्यास\",\"समांतर शिराविन्यास\",\"सरळ शिराविन्यास\"],\"answer\":2,\"explain\":\"वहीच्या कागदावरील रेषांप्रमाणे असणाऱ्या शिरांच्या मांडणीला समांतर शिराविन्यास म्हणतात.\",\"topic\":\"पानांचा शिराविन्यास\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"तुळस आणि शेवंती यांसारख्या वनस्पतींची पाने पाण्यात राहिल्यास पिंपळाच्या पानासारखी जाळी का तयार होत नाही?\",\"options\":[\"त्यांची पाने पाण्यात कुजत नाहीत\",\"त्यांच्या शिराविन्यासात फरक असतो\",\"त्यांची पाने खूप लहान असतात\",\"त्यांच्या शिरा खूप जाड असतात\"],\"answer\":1,\"explain\":\"वनस्पतींमधील शिराविन्यासाच्या प्रकारातील फरकामुळे सर्वच पानांची पिंपळासारखी जाळी होत नाही.\",\"topic\":\"पानांचा शिराविन्यास\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत पिंपळाच्या पाण्य