\":\"apply\"},{\"q\":\"वणवा विझवण्यासाठी अनेक महिने प्रयत्न का करावे लागतात?\",\"options\":[\"कारण तो विझवणे सोपे असते\",\"कारण तो अतिसंहारक असतो आणि मोठ्या क्षेत्रावर पसरलेला असतो\",\"कारण लोक काम करत नाहीत\",\"कारण पाणी उपलब्ध नसते\"],\"answer\":1,\"explain\":\"वणव्याची संहारकता आणि व्याप्ती मोठी असल्याने तो विझवण्यासाठी दिवसरात्र प्रयत्न करावे लागतात.\",\"topic\":\"वणवा\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या चित्रात वणवा लागण्याचे मुख्य कारण काय दर्शवले आहे?\",\"options\":[\"मानवी हस्तक्षेप\",\"वाळलेल्या फांद्यांचे एकमेकांवर होणारे घर्षण\",\"वीज पडणे\",\"ज्वालामुखीचा उद्रेक\"],\"answer\":1,\"explain\":\"चित्राच्या वर्णनानुसार, वाळलेल्या झाडांच्या फांद्या एकमेकांवर घासल्या गेल्यामुळे ही आग लागली आहे.\",\"topic\":\"वणवा\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"37\\/057_103.jpg\"},{\"q\":\"दिलेल्या चित्रावरून वणव्याच्या स्वरूपाबद्दल कोणता निष्कर्ष काढता येईल?\",\"options\":[\"आग फक्त जमिनीवरील गवतापुरती मर्यादित आहे\",\"आग विझलेली असून फक्त धूर दिसत आहे\",\"आग झाडांच्या शेंड्यांपर्यंत पोहोचली असून ती तीव्र स्वरूपाची आहे\",\"आग संथ गतीने पसरत आहे\"],\"answer\":2,\"explain\":\"चित्रात आग झाडांना वेढून मोठ्या प्रमाणात पसरलेली दिसत आहे, जे तिची तीव्रता दर्शवते.\",\"topic\":\"वणवा\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"37\\/057_103.jpg\"},{\"q\":\"मानवाच्या चुकीच्या कृती, निष्काळजीपणा किंवा तंत्रज्ञानाचा अतिवापर यांमुळे येणाऱ्या आपत्तींना काय म्हणतात?\",\"options\":[\"नैसर्गिक आपत्ती\",\"मानवनिर्मित आपत्ती\",\"जैविक आपत्ती\",\"भूगर्भीय आपत्ती\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की मानवाच्या चुकीच्या कृती किंवा निष्काळजीपणामुळे येणाऱ्या आपत्तींना मानवनिर्मित आपत्ती म्हणतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शहरांचा विस्तार आणि महामार्ग तयार करण्यासाठी खालीलपैकी कोणती कृती करावी लागते?\",\"options\":[\"वृक्षारोपण\",\"जंगलतोड\",\"शेतीचा विस्तार\",\"समुद्र भरणे\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, रस्ते, महामार्ग आणि कारखान्यांसाठी मोकळ्या जागा मिळवण्यासाठी जंगलतोड करावी लागते.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"गेल्या काही वर्षांत वातावरणाचे आणि समुद्रांचे तापमान वाढण्याचे मुख्य कारण काय आहे?\",\"options\":[\"पावसाचे वाढते प्रमाण\",\"शेतीचे नुकसान\",\"प्रचंड जंगलतोड आणि इंधनांचा अतिवापर\",\"वाहनांची वाढती संख्या\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे जंगलतोड आणि इंधनांच्या अतिवापराचे परिणाम वातावरणावर होऊन तापमान वाढत आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"कारखान्यात काम करताना यंत्रसामग्री, रसायने किंवा वीजप्रवाह यामुळे होणाऱ्या अपघाताला काय म्हणतात?\",\"options\":[\"नैसर्गिक अपघात\",\"वाहतूक अपघात\",\"औद्योगिक अपघात\",\"तांत्रिक बिघाड\"],\"answer\":2,\"explain\":\"कारखान्यातील धोकादायक घटकांमुळे होणाऱ्या अपघाताला \'औद्योगिक अपघात\' असे म्हणतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पावसाचे प्रमाण आणि पाऊस पडण्याचा काळ बदलल्यामुळे खालीलपैकी कोणती आपत्ती येते?\",\"options\":[\"पूर आणि दरडी कोसळणे\",\"भूकंप\",\"विद्युत दुर्घटना\",\"वाहन अपघात\"],\"answer\":0,\"explain\":\"वातावरणातील बदलांमुळे पावसाचे चक्र बदलून पूर, शेतीचे नुकसान आणि दरडी कोसळणे अशा आपत्ती येतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या तक्त्यानुसार, औद्योगिक अपघात टाळण्यासाठी कोणता उपाय सुचवण्यात आला आहे?\",\"options\":[\"सुरक्षा नियमांकडे दुर्लक्ष करणे\",\"नादुरुस्त यंत्रसामग्री वापरणे\",\"कामगारांना सुरक्षा प्रशिक्षण देणे\",\"सतत काम करून थकवा आणणे\"],\"answer\":2,\"explain\":\"तक्त्यातील \'उपाय\' या रकान्यात कामगारांना सुरक्षा प्रशिक्षण देणे हा महत्त्वाचा उपाय दिला आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"37\\/058_101.jpg\"},{\"q\":\"कारखान्यात रसायनांची गळती किंवा विद्युत दुर्घटना प्रामुख्याने कशामुळे घडतात?\",\"options\":[\"नैसर्गिक बदलांमुळे\",\"मानवाच्या चुका आणि दुर्लक्षामुळे\",\"यंत्रांच्या चांगल्या देखभालीमुळे\",\"सुरक्षा नियमांच्या पालनामुळे\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की रसायनांची गळती आणि विद्युत दुर्घटना या घटना मानवाच्या चुका आणि दुर्लक्षामुळे घडतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या तक्त्यातील माहितीनुसार, \'नादुरुस्त किंवा अयोग्य यंत्रसामग्री\' हे कशाचे निदर्शक आहे?\",\"options\":[\"अपघात टाळण्याचा उपाय\",\"औद्योगिक अपघाताचे कारण\",\"सुरक्षा उपकरणाचा प्रकार\",\"कामाचे वेळापत्रक\"],\"answer\":1,\"explain\":\"तक्त्यानुसार नादुरुस्त यंत्रसामग्री हे औद्योगिक अपघाताचे एक मुख्य कारण आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"37\\/058_101.jpg\"},{\"q\":\"औद्योगिक अपघातामुळे व्यक्तींना होणाऱ्या जखमांशिवाय इतर कोणता परिणाम घडू शकतो?\",\"options\":[\"पावसाचे प्रमाण वाढणे\",\"इमारती कोसळणे आणि आग लागणे\",\"जंगलतोड थांबणे\",\"समुद्राचे तापमान कमी होणे\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केले आहे की अपघातामुळे जखमांसोबतच आग लागणे आणि इमारती कोसळणे असेही परिणाम होतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"एखाद्या कारखान्यात कामगारांना सततच्या कामामुळे थकवा येत असेल, तर तक्त्यानुसार कोणता उपाय योजणे योग्य ठरेल?\",\"options\":[\"यंत्रांची देखभाल करणे\",\"कामाचे योग्य वेळापत्रक ठेवणे\",\"सुरक्षा उपकरणे वापरणे\",\"रसायनांची साठवणूक करणे\"],\"answer\":1,\"explain\":\"तक्त्यानुसार थकवा हे अपघाताचे कारण असल्यास \'कामाचे योग्य वेळापत्रक ठेवणे\' हा त्यावरचा उपाय आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"37\\/058_101.jpg\"},{\"q\":\"जंगलतोडीचा वातावरणावर होणारा परिणाम ओळखा:\",\"options\":[\"हवा शुद्ध होणे\",\"पावसाचे प्रमाण नियमित होणे\",\"वातावरणाचे तापमान वाढणे\",\"जमिनीची सुपीकता वाढणे\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की जंगलतोडीमुळे वातावरणाचे तापमान वाढत आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"सुरक्षा नियमांकडे दुर्लक्ष आणि बेफिकिरी केल्यास काय होऊ शकते?\",\"options\":[\"कामाची गती वाढते\",\"औद्योगिक अपघात घडू शकतात\",\"यंत्रे आपोआप दुरुस्त होतात\",\"पर्यावरणाचे रक्षण होते\"],\"answer\":1,\"explain\":\"तक्त्यानुसार सुरक्षा नियमांकडे दुर्लक्ष करणे हे औद्योगिक अपघाताचे एक प्रमुख कारण आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"37\\/058_101.jpg\"},{\"q\":\"रासायनिक पदार्थांची चुकीची हाताळणी टाळण्यासाठी तक्त्यात कोणता उपाय दिला आहे?\",\"options\":[\"पदार्थांची योग्य प्रकारे साठवणूक आणि हाताळणी करणे\",\"कामाचे तास वाढवणे\",\"यंत्रसामग्री नादुरुस्त ठेवणे\",\"प्रशिक्षणाची कमतरता ठेवणे\"],\"answer\":0,\"explain\":\"तक्त्यात रासायनिक पदार्थांच्या चुकीच्या हाताळणीवर \'योग्य साठवणूक आणि हाताळणी\' हा उपाय दिला आहे.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"apply\",\"figure_image\":\"37\\/058_101.jpg\"},{\"q\":\"उताऱ्यातील माहितीनुसार, मानवनिर्मित आपत्तींचे घातक परिणाम कोणावर होतात?\",\"options\":[\"केवळ मानवावर\",\"केवळ प्राण्यांवर\",\"केवळ पर्यावरणावर\",\"मानव, प्राणी आणि पर्यावरण या सर्वांवर\"],\"answer\":3,\"explain\":\"उताऱ्यात नमूद केले आहे की अशा मोठ्या आपत्तींमुळे मानव, प्राणी आणि पर्यावरण यावर घातक परिणाम होतात.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"तंत्रज्ञानाचा अतिवापर हे कोणत्या प्रकारच्या आपत्तीचे एक कारण असू शकते?\",\"options\":[\"नैसर्गिक आपत्ती\",\"मानवनिर्मित आपत्ती\",\"अवकाशीय आपत्ती\",\"हवामानशास्त्रीय आपत्ती\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच दिले आहे की तंत्रज्ञानाचा अतिवापर मानवनिर्मित आपत्तींना निमंत्रण देतो.\",\"topic\":\"मानवनिर्मित आपत्ती आणि अपघात\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"दोन किंवा अधिक देशांमधील संघर्षांमुळे काय घडून येते?\",\"options\":[\"नैसर्गिक आपत्ती\",\"युद्ध\",\"उत्सव\",\"क्रीडा स्पर्धा\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, दोन किंवा अधिक देशांमधील संघर्षांमुळे युद्धे होतात.\",\"topic\":\"युद्ध आणि सायबर गुन्हे\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"युद्धाचे परिणाम नैसर्गिक आपत्तीच्या तुलनेत कसे असतात?\",\"options\":[\"कमी गं