xplain\":\"असंतुलित बलामध्ये अधिक असणाऱ्या बलाचा परिणाम त्या दिशेला दिसून येतो.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर दोन मुले एकाच पेटीला विरुद्ध दिशेने सारख्याच ताकदीने ढकलत असतील, तर त्या बलाला काय म्हणता येईल?\",\"options\":[\"असंतुलित बल\",\"संतुलित बल\",\"गुरुत्वीय बल\",\"चुंबकीय बल\"],\"answer\":1,\"explain\":\"दोन्ही बाजूंनी समान बल लावल्यास ते संतुलित बल असते.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"रस्सीखेच खेळात दोरी कोणत्याही बाजूला ओढली जात नाही, याचे कारण काय?\",\"options\":[\"दोन्ही बाजूंचे संघ बल लावत नाहीत\",\"दोन्ही बाजूंचे संघ समान बल लावत आहेत\",\"दोन्ही बाजूंचे संघ असमान बल लावत आहेत\",\"दोरी खूप जड आहे\"],\"answer\":1,\"explain\":\"जेव्हा दोन्ही बाजूंचे बल सारखे असते, तेव्हा दोरी कोणत्याही बाजूला सरकत नाही.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते संतुलित बलाचे उदाहरण आहे?\",\"options\":[\"रस्सीखेचमध्ये एका संघाने दोरी स्वतःकडे ओढणे\",\"पिल्लाने कापडाचा तुकडा स्वतःकडे खेचणे\",\"समान बलामुळे कापडाचा तुकडा स्थिर राहणे\",\"चेंडू वेगाने लांब जाणे\"],\"answer\":2,\"explain\":\"समान बलामुळे वस्तू स्थिर राहणे हे संतुलित बलाचे उदाहरण आहे.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"असंतुलित बलामुळे वस्तूच्या स्थितीवर काय परिणाम होतो?\",\"options\":[\"वस्तू स्थिर राहते\",\"बलांचा परिणाम शून्य होतो\",\"वस्तू अधिक बल असलेल्या दिशेला ओढली जाते\",\"वस्तूवर कोणतेही बल कार्य करत नाही\"],\"answer\":2,\"explain\":\"असंतुलित बलामुळे वस्तू जास्त बल असलेल्या दिशेने गतिमान होते किंवा ओढली जाते.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"ज्या बलांमुळे वस्तू \'स्थिर स्थितीत\' राहते, त्या बलांना काय म्हणतात?\",\"options\":[\"असंतुलित बले\",\"संतुलित बले\",\"विद्युत बले\",\"घर्षण बले\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, संतुलित बलांमुळे वस्तू स्थिर स्थितीत राहते.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या वस्तूवर विरुद्ध दिशेने कार्य करणारी बले समान असतील, तर बलांचा एकत्रित परिणाम काय असेल?\",\"options\":[\"शून्य\",\"दुप्पट\",\"खूप जास्त\",\"अनिश्चित\"],\"answer\":0,\"explain\":\"समान आणि विरुद्ध बले एकमेकांचा परिणाम रद्द करतात, म्हणून एकत्रित परिणाम शून्य असतो.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पिल्लांच्या खेळातील कापडाचा तुकडा कधी पहिल्या पिल्लाकडे तर कधी दुसऱ्या पिल्लाकडे जातो, हे कशाचे उदाहरण आहे?\",\"options\":[\"नेहमी संतुलित बल\",\"नेहमी शून्य बल\",\"असंतुलित बल\",\"स्थिर बल\"],\"answer\":2,\"explain\":\"जेव्हा तुकडा एका बाजूला सरकतो, तेव्हा त्या बाजूचे बल जास्त असते, म्हणजेच ते असंतुलित बल असते.\",\"topic\":\"संतुलित आणि असंतुलित बले\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"एकक क्षेत्रफळावर लावलेल्या बलाला काय म्हणतात?\",\"options\":[\"कार्य\",\"ऊर्जा\",\"दाब\",\"त्वरण\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, एकक क्षेत्रफळावरील बलाला \'दाब\' असे म्हणतात.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"दाब मोजण्यासाठी खालीलपैकी कोणते सूत्र वापरले जाते?\",\"options\":[\"दाब = बल × क्षेत्रफळ\",\"दाब = बल \\/ क्षेत्रफळ\",\"दाब = क्षेत्रफळ \\/ बल\",\"दाब = बल + क्षेत्रफळ\"],\"answer\":1,\"explain\":\"दाब काढण्यासाठी बलाला क्षेत्रफळाने भागले जाते, म्हणजेच दाब = बल \\/ क्षेत्रफळ.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"न्यूटन\\/मीटर² या एककाला कोणत्या शास्त्रज्ञाच्या सन्मानार्थ \'पास्कल\' असे नाव दिले आहे?\",\"options\":[\"आईन्स्टाईन\",\"न्यूटन\",\"पास्कल\",\"गॅलिलिओ\"],\"answer\":2,\"explain\":\"न्यूटन\\/मीटर² या एककालाच पास्कल असेही नाव पास्कल यांच्या सन्मानासाठी दिले आहे.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत, खिळा लाकडात सहज शिरण्यासाठी तो कसा ठेवला पाहिजे?\",\"options\":[\"खिळ्याचे पसरट टोक लाकडावर टेकवून\",\"खिळा आडवा ठेवून\",\"खिळ्याचे टोकदार टोक लाकडावर टेकवून\",\"खिळा कोणत्याही बाजूने ठेवला तरी चालेल\"],\"answer\":2,\"explain\":\"आकृतीनुसार, खिळ्याचे टोक लाकडावर टेकवून फटका मारल्यास लावलेल्या बलाचा परिणाम कमी जागेवर होतो व खिळा सहज शिरतो.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"37\\/115_102.jpg\"},{\"q\":\"क्षेत्रफळ आणि दाब यांच्यातील संबंधाबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"क्षेत्रफळ वाढल्यास दाब वाढतो\",\"क्षेत्रफळ कमी असल्यास दाब कमी असतो\",\"क्षेत्रफळ जास्त असल्यास दाब कमी असतो\",\"क्षेत्रफळाचा दाबावर कोणताही परिणाम होत नाही\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात स्पष्ट केले आहे की क्षेत्रफळ जास्त असल्यास दाब कमी असतो.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, कलाकार अनेक टोकदार खिळ्यांवर उभा राहू शकतो, पण तो एकाच खिळ्यावर उभा राहू शकणार नाही, याचे मुख्य कारण काय?\",\"options\":[\"एका खिळ्यावर बल जास्त भागावर वाटले जाते\",\"अनेक खिळ्यांमुळे क्षेत्रफळ वाढते आणि दाब विभागला जातो\",\"खिळे बोथट असल्यामुळे टोचत नाहीत\",\"कलाकाराचे वजन अनेक खिळ्यांमुळे कमी होते\"],\"answer\":1,\"explain\":\"जेव्हा खिळे जास्त असतात तेव्हा क्षेत्रफळ वाढते आणि दाब विभागला जातो, त्यामुळे ते टोचत नाहीत.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"37\\/115_104.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. कोणत्या स्थितीतील वीट ओल्या मातीत अधिक खोलवर रुतेल?\",\"options\":[\"आडव्या स्थितीत सोडलेली वीट\",\"उभ्या स्थितीत सोडलेली वीट\",\"दोन्ही स्थितींत वीट सारखीच रुतेल\",\"वीट मातीत अजिबात रुतणार नाही\"],\"answer\":1,\"explain\":\"उभ्या स्थितीत विटेचा मातीला टेकलेला पृष्ठभाग (क्षेत्रफळ) कमी असतो, त्यामुळे दाब जास्त निर्माण होऊन ती अधिक खोल जाते.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"37\\/116_101.jpg\"},{\"q\":\"जर एखाद्या वस्तूवर १० न्यूटन बल १ मीटर² क्षेत्रफळावर लावले, तर निर्माण होणारा दाब किती असेल?\",\"options\":[\"१ पास्कल\",\"५ पास्कल\",\"१० पास्कल\",\"१०० पास्कल\"],\"answer\":2,\"explain\":\"दाब = बल \\/ क्षेत्रफळ = १० \\/ १ = १० पास्कल.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"खिळ्याचे डोके पसरट असल्यास तो लाकडात का शिरत नाही?\",\"options\":[\"पसरट डोक्यामुळे बल कमी लागते\",\"पसरट डोक्यामुळे लावलेला जोर जास्त भागावर वाटला जातो\",\"पसरट डोक्यामुळे लाकूड कडक होते\",\"पसरट डोक्यामुळे खिळ्याचे वजन वाढते\"],\"answer\":1,\"explain\":\"क्षेत्रफळ वाढल्यामुळे दाब कमी होतो कारण लावलेला जोर जास्त भागावर वाटला जातो.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या ठिकाणी दाबाचे मापन करणे गरजेचे असते?\",\"options\":[\"वाहनांच्या टायरमधील हवा\",\"मोठे जलसाठे\",\"पंप\",\"वरील सर्व ठिकाणी\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकानुसार जलसाठे, पंप आणि टायरमधील हवा अशा अनेक ठिकाणी दाबाचे मापन गरजेचे असते.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"बल मोजण्याचे एकक कोणते आहे?\",\"options\":[\"मीटर\",\"न्यूटन\",\"पास्कल\",\"किलोग्रॅम\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात उल्लेख केल्याप्रमाणे न्यूटन हे बल मोजण्याचे एकक आहे.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला ओल्या मातीत विटेचा दाब कमी करायचा असेल, तर तुम्ही काय कराल?\",\"options\":[\"विटेचे क्षेत्रफळ कमी कराल\",\"वीट उभ्या स्थितीत ठेवाल\",\"विटेचा मातीला टेकणारा पृष्ठभाग (क्षेत्रफळ) वाढवाल\",\"विटेवर अधिक बल लावाल\"],\"answer\":2,\"explain\":\"दाब कमी करण्यासाठी क्षेत्रफळ वाढवणे आवश्यक असते, म्हणून विटेचा जास्त पृष्ठभाग मातीला टेकवावा लागेल.\",\"topic\":\"दाब\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"पृथ्वीभोवती सर्व बाजूंनी असलेल्या हवेच्या आवरणाला काय म्हणतात?\",\"options\":[\"जलावरण\",\"वातावरण\",\"शिलावरण\",\"जीवावरण\"],\"answer\":1,\"explain\":\"पृथ्वीभोवतीच्या हवेच्या आवरणाला वातावरण असे म्हणतात.\",\"topic\":\"वातावरणीय दाब\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जसजसे आपण जमिनीपासून उंच जाऊ, तसतसा हवेचा दाब कसा होतो?\",\"options\":[\"वाढत जातो\",\"कमी होत जातो\",\"स्थिर राहतो\",\"शून्य होतो\"],\"answer\":1,\"explain\":\"उंचीनुसार वातावरण विरळ होत जाते, त्यामुळे हवेचा दाब कमी होतो.\",\"topic\":\"वातावरणीय दाब\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"वारे कोणत्या दिशेकडून कोणत्या दिशेकडे वाहतात?\",\"options\":[\"कमी दाबाकडून जास्त दाबाकडे\",\"जास्त दाबाकडून कमी दाबाकडे\",\"उत्तरेकडून दक्षिणेकडे\",\