",\"options\":[\"गती वाढवते\",\"गतीला विरोध करते\",\"गती बदलत नाही\",\"गतीला दिशा देते\"],\"answer\":1,\"explain\":\"घर्षण बल नेहमी गतीला विरोध करते, ज्यामुळे वस्तूची गती कमी होते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"पृथ्वी सभोवतालच्या वस्तूंना स्वतःकडे खेचते, या बलाला काय म्हणतात?\",\"options\":[\"चुंबकीय बल\",\"स्थितिक विद्युत बल\",\"गुरुत्वीय बल\",\"यांत्रिक बल\"],\"answer\":2,\"explain\":\"पृथ्वीने वस्तूंना स्वतःकडे खेचण्यासाठी लावलेल्या बलाला गुरुत्वीय बल म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या पदार्थावर घर्षणामुळे विद्युत प्रभार निर्माण होऊन स्थितिक विद्युत बल तयार होऊ शकते?\",\"options\":[\"लोखंड\",\"तांबे\",\"प्लॅस्टिक\",\"दगड\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार प्लॅस्टिक, रबर, एबोनाईट यांसारख्या पदार्थांवर घर्षणामुळे विद्युत प्रभार निर्माण होतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"जर लावलेले बल समान असेल, तर क्षेत्रफळ वाढवल्यास दाबावर काय परिणाम होईल?\",\"options\":[\"दाब वाढेल\",\"दाब कमी होईल\",\"दाब समान राहील\",\"दाब शून्य होईल\"],\"answer\":1,\"explain\":\"बल समान असताना क्षेत्रफळ जास्त असल्यास दाब कमी असतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"एखाद्या वस्तूवर दोन विरुद्ध दिशांनी समान बले काम करत असल्यास काय घडते?\",\"options\":[\"वस्तू वेगाने धावते\",\"वस्तूची दिशा बदलते\",\"वस्तू स्थिर राहते\",\"वस्तूचा आकार बदलतो\"],\"answer\":2,\"explain\":\"जेव्हा दोन विरुद्ध दिशांनी समान बले कार्य करतात, तेव्हा ती संतुलित बले असतात आणि वस्तू स्थिर राहते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"वारा आणि वादळे निर्माण होण्याचे मुख्य कारण काय आहे?\",\"options\":[\"गुरुत्वीय बलातील फरक\",\"चुंबकीय बलातील फरक\",\"वातावरणीय दाबातील फरक\",\"स्नायू बलातील फरक\"],\"answer\":2,\"explain\":\"दोन ठिकाणांच्या वातावरणीय दाबांत फरक झाल्यास वारा आणि वादळे निर्माण होतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"एकक क्षेत्रफळावर असलेल्या बलाला काय म्हणतात?\",\"options\":[\"दाब\",\"घर्षण\",\"प्रभार\",\"जोर\"],\"answer\":0,\"explain\":\"एकक क्षेत्रफळावर असलेल्या बलाला किंवा जोराला दाब असे म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"यंत्रामार्फत लावल्या जाणाऱ्या बलाला काय म्हणतात?\",\"options\":[\"स्नायू बल\",\"यांत्रिक बल\",\"गुरुत्वीय बल\",\"स्थितिक विद्युत बल\"],\"answer\":1,\"explain\":\"यंत्रांच्या साहाय्याने लावल्या जाणाऱ्या बलाला यांत्रिक बल म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"वस्तूवर कार्य करणारी बले जेव्हा समान नसतात (असंतुलित असतात), तेव्हा काय दिसून येते?\",\"options\":[\"वस्तू स्थिर राहते\",\"कमी असलेल्या बलाचा परिणाम दिसतो\",\"अधिक असलेल्या बलाचा परिणाम दिसतो\",\"कोणत्याही बलाचा परिणाम दिसत नाही\"],\"answer\":2,\"explain\":\"असंतुलित बलांच्या बाबतीत, ज्या बाजूचे बल अधिक असते त्याचा परिणाम वस्तूवर दिसून येतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"हवेमुळे निर्माण झालेल्या दाबाला काय म्हणतात?\",\"options\":[\"यांत्रिक दाब\",\"स्थितिक दाब\",\"वातावरणीय दाब\",\"चुंबकीय दाब\"],\"answer\":2,\"explain\":\"हवेच्या वजनामुळे किंवा अस्तित्वामुळे निर्माण होणाऱ्या दाबाला वातावरणीय दाब म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21880,37,6,'Science','mr','गती आणि गतीचे प्रकार','[\"गती म्हणजे वस्तूची जागा वेळेनुसार बदलणे.\",\"वस्तू गतिमान असे म्हणतो जेव्हा तिची जागा बदलते.\",\"संदर्भबिंदू म्हणजे स्थिर वस्तू ज्याच्या तुलनेत आपण गती मोजतो.\",\"एकरेषीय गती म्हणजे वस्तू सरळ रेषेत सतत हलते (उदा. पडणारी उल्का).\",\"वर्तुळाकार गती म्हणजे वस्तू वर्तुळाकार मार्गाने फिरते (उदा. पाळणा).\",\"दोलन गती म्हणजे वस्तू पुढे- मागे किंवा वर-खाली कंपते (उदा. तारा).\",\"यादृच्छिक गती म्हणजे वस्तू अनिश्चित दिशांनी हलते (उदा. फुलपाखरू).\",\"सायकलच्या चाकाची गती वर्तुळाकार, पॅडलची एकरेषीय, सुईची दोलन.\",\"पृथ्वी स्वतःच्या अक्षावर फिरते आणि सूर्याभोवती फिरते, त्यामुळे सर्व वस्तू गतिमान.\",\"गतीचे प्रकार एकाच वस्तूमध्ये एकत्र अस्तित्वात असू शकतात.\"]','[{\"q\":\"वस्तूची जागा बदलत असते, तेव्हा ती वस्तू कशी आहे असे म्हणतात?\",\"options\":[\"स्थिर\",\"गतिमान\",\"अदृश्य\",\"मोठी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, वस्तूची जागा बदलत असते, तेव्हा ती वस्तू गतिमान आहे असे म्हणतात.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"गोलंदाजाच्या हातात चेंडू असताना त्याची स्थिती कशी असते?\",\"options\":[\"गतिमान\",\"वेगात\",\"स्थिर\",\"फिरती\"],\"answer\":2,\"explain\":\"प्रथम चेंडू गोलंदाजाच्या हातात असतो, तेथे चेंडू स्थिर असतो.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"फलंदाजाने बॅटने फटका मारला की चेंडूच्या बाबतीत काय घडते?\",\"options\":[\"चेंडू गायब होतो\",\"चेंडू स्थिर होतो\",\"चेंडूची जागा बदलत नाही\",\"चेंडू वेगळ्या दिशेला जातो\"],\"answer\":3,\"explain\":\"फलंदाजाने बॅटने फटका मारला की, चेंडू वेगळ्या दिशेला जातो आणि त्याची जागा बदलते.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"यष्टीरक्षकाच्या हातात चेंडू आल्यावर तो कसा होतो?\",\"options\":[\"स्थिर\",\"गतिमान\",\"वेगात\",\"उड्या मारणारा\"],\"answer\":0,\"explain\":\"जेव्हा चेंडू यष्टीरक्षकाच्या हातात जातो, तेव्हा तो तेथे स्थिर होतो.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या क्रियेत चेंडूची जागा बदलत नाही?\",\"options\":[\"गोलंदाजाने चेंडू टाकला असता\",\"फलंदाजाने फटका मारला असता\",\"चेंडू गोलंदाजाच्या हातात असताना\",\"चेंडू मैदानातून जात असताना\"],\"answer\":2,\"explain\":\"चेंडू हातात असेल तेव्हा तो स्थिर असतो, म्हणजेच त्याची जागा बदलत नाही.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"वस्तू गतिमान आहे हे ओळखण्यासाठी मुख्य लक्षण कोणते?\",\"options\":[\"वस्तूचा रंग बदलणे\",\"वस्तूची जागा बदलणे\",\"वस्तूचा आकार बदलणे\",\"वस्तूचा आवाज येणे\"],\"answer\":1,\"explain\":\"वस्तूची जागा बदलणे हे ती वस्तू गतिमान असल्याचे लक्षण आहे.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"क्रिकेटच्या खेळात गोलंदाज पळत येऊन चेंडू फेकतो, तेव्हा चेंडूच्या बाबतीत काय घडते?\",\"options\":[\"चेंडू स्थिर राहतो\",\"चेंडूची जागा बदलते\",\"चेंडूचा रंग बदलतो\",\"चेंडू अदृश्य होतो\"],\"answer\":1,\"explain\":\"गोलंदाज चेंडू फलंदाजाकडे टाकतो तेव्हा चेंडूची जागा बदलते.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात, फलंदाजाने चेंडू टोलवल्यानंतर चेंडूची स्थिती काय असेल?\",\"options\":[\"तो स्थिर राहील\",\"त्याची जागा बदलत राहील\",\"तो गोलंदाजाच्या हातात जाईल\",\"तो जागेवरच थांबेल\"],\"answer\":1,\"explain\":\"चित्रात फलंदाजाने फटका मारला आहे, त्यामुळे चेंडूची जागा बदलत राहील म्हणजेच तो गतिमान असेल.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"37\\/120_101.jpg\"},{\"q\":\"दिलेल्या चित्राचे निरीक्षण करा; चेंडू जेव्हा फलंदाजाच्या बॅटला स्पर्श करून लांब जातो, तेव्हा त्याला काय म्हणतात?\",\"options\":[\"स्थिर वस्तू\",\"मोठी वस्तू\",\"गतिमान वस्तू\",\"जड वस्तू\"],\"answer\":2,\"explain\":\"जागा बदलणाऱ्या वस्तूला गतिमान वस्तू म्हणतात, चित्रात फटका मारलेला चेंडू जागा बदलत आहे.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"37\\/120_101.jpg\"},{\"q\":\"वस्तूच्या हालचालीवरून \'गती\'ची व्याख्या काय सांगता येईल?\",\"options\":[\"वस्तूचे स्थिर राहणे\",\"वस्तूच्या जागेत सतत होणारा बदल\",\"वस्तूचा आकार स्थिर असणे\",\"वस्तूचा आवाज होणे\"],\"answer\":1,\"explain\":\"वस्तूची जागा बदलत राहणे म्हणजेच ती वस्तू गतिमान असणे किंवा तिला गती असणे होय.\",\"topic\":\"गती आणि गतीचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"एखादी वस्तू गतिमान आहे की नाही हे ठरवण्यासाठी ज्या स्थिर वस्तूच्या जागेचा वापर केला जातो, त्या जागेला काय म्हणतात?\",\"options\":[\"गतीचा बिंदू\",\"संदर्भबिंदू\",\"अंतिम बिंदू\",\"प्रवास बिंदू\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील व्याख्येनुसार, वस्तूची गती ठरवण्यासाठी वापरल्या जाणाऱ्या स्थिर वस्तूच्या जागेला \'संदर्भबिंदू\' म्हणतात.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"चालत्या बसच्या खिडकीतून बाहेर पाहिल्यास रस्त्याच्या कडेची झाडे कोणत्या दिशेला जाताना दिसतात?\",\"options\":[\"पुढे जाताना\",\"मागे जाताना\",\"स्थिर राहताना\",\"वर जाताना\"],\"answer\":1,\"explain\":\"बस गतिमान असताना खिडकीतून बाहेर पाहिल्यास झाडे मागे जाताना दिसतात असे पाठात नमूद केले आहे.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"कोणतीही वस्तू स्थिर आहे की गतिमान आहे हे ठरवण्यासाठी कशाची निश्चित आवश्यकता असते?\",\"options\":[\"वेळेची\",\"वस्तूच्या वजनाची\",\"निश्चित संदर्भाची\",\"वस्तूच्या रंगाची\"],\"answer\":2,\"explain\":\"वस्तूची स्थिती (स्थिर किंवा गतिमान) ठरवण्यासाठी निश्चित संदर्भाची आवश्यकता असते.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"बसमध्ये बसलेल्या प्रवाशाला त्याची बॅग स्थिर का वाटते?\",\"options\":[\"बॅग जड असल्यामुळे\",\"बॅगने प्रवाशाच्या संदर्भात जागा बदलली नाही म्हणून\",\"बस थांबलेली असल्यामुळे\",\"बॅगला गती नसल्यामुळे\"],\"answer\":1,\"explain\":\"बॅग बसमध्ये होती तेथेच राहिल्यामुळे, म्हणजेच तिने जागा न बदलल्यामुळे ती प्रवाशाला स्थिर वाटते.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"बाहेरून पाहणाऱ्या व्यक्तीला बसमधील बॅग गतिमान का वाटते?\",\"options\":[\"बॅग स्वतःहून चालत आहे म्हणून\",\"बॅगचा रंग बदलत आहे म्हणून\",\"बॅगची जागा बदलली आहे म्हणून\",\"बॅग खिडकीबाहेर पडली आहे म्हणून\"],\"answer\":2,\"explain\":\"बाहेरून पाहणाऱ्यासाठी बॅग एका गावाकडून दुसऱ्या गावाकडे गेली आहे, म्हणजेच तिची जागा बदलली आहे.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"एखादी वस्तू गतिमान आहे किंवा नाही हे कशावरून ठरते?\",\"options\":[\"केवळ वस्तूच्या आकारावरून\",\"निरीक्षण कोठून व कसे केले यावरून\",\"वस्तूच्या किमतीवरून\",\"केवळ वस्तूच्या वजनावरून\"],\"answer\":1,\"explain\":\"निरीक्षकाची जागा आणि पद्धत यावर वस्तूची गती अवलंबून असते.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"बस गतिमान असताना बसमधील बॅगेला गती कोणामुळे मिळते?\",\"options\":[\"प्रवाशामुळे\",\"रस्त्यामुळे\",\"बसमुळे\",\"झाडांमुळे\"],\"answer\":2,\"explain\":\"बस गतिमान असल्यामुळे बसची गती त्यातील बॅगेलाही मिळते.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही चालत्या रेल्वेतून प्लॅटफॉर्मवरील खांबाकडे पाहत असाल, तर या स्थितीत \'संदर्भबिंदू\' कोणता असेल?\",\"options\":[\"चालती रेल्वे\",\"रेल्वेतील प्रवासी\",\"प्लॅटफॉर्मवरील स्थिर खांब\",\"तुमची बॅग\"],\"answer\":2,\"explain\":\"गती ठरवण्यासाठी जागा न बदलणाऱ्या (स्थिर) वस्तूची गरज असते, येथे खांब स्थिर आहे.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"एकाच वेळी एक वस्तू एका व्यक्तीला स्थिर आणि दुसऱ्याला गतिमान वाटू शकते का?\",\"options\":[\"नाही, हे कधीही शक्य नाही\",\"हो, निरीक्षकाच्या स्थानानुसार हे शक्य आहे\",\"केवळ रात्रीच्या वेळी शक्य आहे\",\"केवळ बसमध्येच शक्य आहे\"],\"answer\":1,\"explain\":\"पाठातील बसच्या उदाहरणावरून हे स्पष्ट होते की निरीक्षकाच्या स्थानानुसार एकाच वस्तूची स्थिती भिन्न वाटू शकते.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"बसच्या प्रवासात झाडे मागे जाताना दिसतात, तेव्हा प्रत्यक्षात कोण गतिमान असते?\",\"options\":[\"रस्त्यावरील झाडे\",\"रस्त्याशेजारील घरे\",\"बस आणि त्यातील प्रवासी\",\"रस्ता\"],\"answer\":2,\"explain\":\"झाडे स्थिर असतात, परंतु बस गतिमान असल्यामुळे ती मागे जाताना भासतात.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या क्रियेवरून वस्तूने जागा बदलली असे म्हणता येईल?\",\"options\":[\"वस्तू एकाच जागी राहणे\",\"वस्तू एका गावाकडून दुसऱ्या गावाला पोहोचणे\",\"वस्तूचा आकार बदलणे\",\"वस्तू स्थिर राहणे\"],\"answer\":1,\"explain\":\"जागा बदलणे म्हणजेच एका ठिकाणाहून दुसऱ्या ठिकाणी जाणे, जे गतीचे लक्षण आहे.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"वस्तूची गती ठरवण्यासाठी \'संदर्भबिंदू\' म्हणून निवडलेली वस्तू कशी असणे आवश्यक आहे?\",\"options\":[\"ती वस्तू सतत हलणारी असावी\",\"ती वस्तू जागा न बदलणारी (स्थिर) असावी\",\"ती वस्तू खूप मोठी असावी\",\"ती वस्तू रंगीत असावी\"],\"answer\":1,\"explain\":\"गती ठरवण्यासाठी जागा न बदलणाऱ्या वस्तूकडे पाहावे लागते, तिलाच संदर्भबिंदू म्हणतात.\",\"topic\":\"संदर्भबिंदू\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"वस्तूचा स्थानबदल जर सतत एका सरळ रेषेत होत असेल, तर त्या गतीला काय म्हणतात?\",\"options\":[\"आंदोलित गती\",\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"यादृच्छिक गती\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, वस्तूचा स्थानबदल सतत एका सरळ रेषेत होणे म्हणजे एकरेषीय गती होय.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"गतिमान वस्तू सतत काय करत असते?\",\"options\":[\"रंग बदलत असते\",\"आकार बदलत असते\",\"जागा बदलत असते\",\"स्थिर राहत असते\"],\"answer\":2,\"explain\":\"गतीची व्याख्या सांगते की गतिमान वस्तू सतत आपली जागा बदलत असते.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"झाडावरून पडलेले फळ खाली येताना कोणत्या प्रकारची गती दर्शवते?\",\"options\":[\"एकरेषीय गती\",\"वक्ररेषीय गती\",\"नियतकालिक गती\",\"कंपन गती\"],\"answer\":0,\"explain\":\"झाडावरून पडलेले फळ एका सरळ रेषेत खाली येते, म्हणून ती एकरेषीय गती आहे.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पृथ्वी स्वतःच्या आसाभोवती आणि सूर्याभोवती सतत फिरते, यावरून काय सिद्ध होते?\",\"options\":[\"पृथ्वीवरील सर्व वस्तू स्थिर आहेत\",\"पृथ्वीवरील सर्व वस्तू गतिमान आहेत\",\"पृथ्वी फिरत नाही\",\"केवळ झाडेच गतिमान आहेत\"],\"answer\":1,\"explain\":\"पृथ्वी स्वतः फिरत असल्यामुळे तिच्यावरील साऱ्या वस्तू प्रत्यक्षात गतिमान असतात.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"खूप उंचावरून सरळ खाली सोडलेली वस्तू कोणत्या मार्गाने प्रवास करते?\",\"options\":[\"वाकड्या-तिकड्या रेषेत\",\"वर्तुळाकार मार्गाने\",\"एका सरळ रेषेत\",\"मागे-पुढे अशा स्वरूपात\"],\"answer\":2,\"explain\":\"उंचावरून सोडलेली वस्तू गुरुत्वाकर्षणामुळे सरळ रेषेत खाली येते.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते उदाहरण एकरेषीय गतीचे आहे?\",\"options\":[\"बागेतील फिरणारा पाळणा\",\"रुळावरून धावणारी सरळ रेल्वे\",\"उडणारे फुलपाखरू\",\"घड्याळाचा लंबक\"],\"answer\":1,\"explain\":\"रेल्वे रुळावरून सरळ धावत असेल तर ती एकरेषीय गतीचे उदाहरण आहे.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"आपल्याला आसपासचे खांब स्थिर का वाटतात?\",\"options\":[\"कारण ते जमिनीवर घट्ट रोवलेले असतात\",\"कारण ते हालचाल करत नाहीत\",\"कारण आपण त्यांच्या सापेक्ष स्थिर असतो\",\"कारण पृथ्वी फिरत नाही\"],\"answer\":2,\"explain\":\"पृथ्वी फिरत असली तरी आपण आणि खांब एकाच वेगाने फिरत असल्याने ते स्थिर वाटतात.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"एखाद्या वस्तूची गती \'एकरेषीय\' असण्यासाठी कोणती अट आवश्यक आहे?\",\"options\":[\"वस्तूने गोल फिरले पाहिजे\",\"वस्तूने सतत वेग बदलला पाहिजे\",\"वस्तूचा स्थानबदल सरळ रेषेत झाला पाहिजे\",\"वस्तूने एकाच जागी थांबले पाहिजे\"],\"answer\":2,\"explain\":\"स्थानबदल सरळ रेषेत होणे ही एकरेषीय गतीची मुख्य अट आहे.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"रस्त्यावरून चाललेले वाहन जर वळण न घेता सरळ जात असेल, तर त्या गतीला काय म्हणाल?\",\"options\":[\"एकरेषीय गती\",\"यादृच्छिक गती\",\"आंदोलित गती\",\"वर्तुळाकार गती\"],\"answer\":0,\"explain\":\"सरळ रेषेत चालणाऱ्या वाहनाची गती ही एकरेषीय गती असते.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पाठ्यपुस्तकातील माहितीनुसार, गती म्हणजे काय?\",\"options\":[\"वस्तूचे वजन वाढणे\",\"वस्तूचा होणारा स्थानबदल\",\"वस्तूचा आकार बदलणे\",\"वस्तू स्थिर राहणे\"],\"answer\":1,\"explain\":\"वस्तूचे एका ठिकाणाहून दुसऱ्या ठिकाणी होणारे विस्थापन किंवा स्थानबदल म्हणजे गती.\",\"topic\":\"एकरेषीय गती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"वर्तुळाकार मार्गाने होणाऱ्या हालचालीला कोणती गती म्हणतात?\",\"options\":[\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"यादृच्छिक गती\",\"आंदोलित गती\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, वर्तुळाकार मार्गाने होणाऱ्या हालचालीला \'वर्तुळाकार गती\' असे म्हणतात.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या वस्तूची हालचाल वर्तुळाकार मार्गाने होते?\",\"options\":[\"सरळ रेषेत धावणारी बस\",\"जत्रेतील पाळणा (मेरी गो राऊंड)\",\"झाडावरून पडणारे फळ\",\"सरळ उडणारा पक्षी\"],\"answer\":1,\"explain\":\"जत्रेतील पाळणा (मेरी गो राऊंड) हा वर्तुळाकार मार्गाने फिरतो.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मिठाईच्या तुकड्याभोवती जमा झालेल्या मुंग्यांवर मिठाचे पाणी फवारल्यास त्या कशा पळू लागतात?\",\"options\":[\"एका सरळ रेषेत\",\"वर्तुळाकार मार्गाने\",\"सर्व दिशांना सैरावैरा\",\"एकाच जागी थांबतात\"],\"answer\":2,\"explain\":\"मिठाचे पाणी फवारल्यावर मुंग्या सर्व दिशांना सैरावैरा पळू लागतात असे उताऱ्यात दिले आहे.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"गोफणीची हालचाल कोणत्या प्रकारच्या गतीचे उदाहरण आहे?\",\"options\":[\"एकरेषीय गती\",\"यादृच्छिक गती\",\"वर्तुळाकार गती\",\"स्थिर गती\"],\"answer\":2,\"explain\":\"गोफण वर्तुळाकार मार्गाने फिरते, म्हणून ती वर्तुळाकार गती आहे.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जेव्हा मुंग्या सर्व दिशांना सैरावैरा पळतात, तेव्हा त्यांची गती एकरेषीय असते का?\",\"options\":[\"हो, ती एकरेषीय असते\",\"नाही, ती एकरेषीय नसते\",\"ती नेहमी वर्तुळाकार असते\",\"ती फक्त एकाच दिशेला असते\"],\"answer\":1,\"explain\":\"सैरावैरा पळणाऱ्या मुंग्यांची दिशा सतत बदलत असल्याने ती एकरेषीय नसते.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एखादा मुलगा मैदानात वर्तुळाकार मार्गाने धावत असेल, तर त्याच्या गतीला काय म्हणता येईल?\",\"options\":[\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"यादृच्छिक गती\",\"दोलन गती\"],\"answer\":1,\"explain\":\"वर्तुळाकार मार्गावरील हालचालीला वर्तुळाकार गती म्हणतात, हे तत्व येथे लागू होते.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मुंग्या मिठाईच्या तुकड्याभोवती जमा होणे आणि नंतर सैरावैरा पळणे, यातून त्यांच्या गतीबद्दल काय समजते?\",\"options\":[\"त्यांची गती नेहमी निश्चित असते\",\"त्यांची गती एकाच मार्गाने असते\",\"त्यांच्या गतीची दिशा सतत बदलू शकते\",\"त्यांना गती नसते\"],\"answer\":2,\"explain\":\"सैरावैरा पळणे म्हणजे दिशा निश्चित नसणे, म्हणजेच दिशा सतत बदलणे.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या उदाहरणात वस्तूची दिशा सतत वर्तुळाकार बदलत असते?\",\"options\":[\"विमानाचे उड्डाण\",\"मेरी गो राऊंडमधील घोडा\",\"बागेतील घसरगुंडी\",\"धावपट्टीवरील धावपटू\"],\"answer\":1,\"explain\":\"मेरी गो राऊंड वर्तुळाकार फिरत असल्याने त्यातील घोडाही वर्तुळाकार गतीत असतो.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"वर्तुळाकार गती आणि मुंग्यांची सैरावैरा पळण्याची गती यातील मुख्य फरक कोणता?\",\"options\":[\"वर्तुळाकार गतीचा मार्ग निश्चित असतो, मुंग्यांचा नसतो\",\"मुंग्यांची गती वर्तुळाकार असते\",\"दोन्ही गती एकाच प्रकारच्या आहेत\",\"वर्तुळाकार गती सरळ रेषेत असते\"],\"answer\":0,\"explain\":\"वर्तुळाकार गती एका ठराविक मार्गाने होते, तर सैरावैरा पळणे म्हणजे मार्ग निश्चित नसणे.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, मुंग्यांची हालचाल \'एकरेषीय\' का नसते?\",\"options\":[\"कारण त्या सरळ रेषेत पळत नाहीत\",\"कारण त्या खूप वेगाने पळतात\",\"कारण त्या मिठाच्या पाण्यात पळतात\",\"कारण त्या मिठाई खातात\"],\"answer\":0,\"explain\":\"एकरेषीय गतीसाठी वस्तू सरळ रेषेत जाणे आवश्यक असते, मुंग्या सर्व दिशांना सैरावैरा पळतात.\",\"topic\":\"मुंग्यांची यादृच्छिक गती\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"वस्तूच्या खाली-वर किंवा पुढे-मागे अशा सतत होणाऱ्या हालचालीला कोणती गती म्हणतात?\",\"options\":[\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"दोलन गती\",\"यादृच्छिक गती\"],\"answer\":2,\"explain\":\"पाठातील व्याख्येनुसार, वस्तूच्या खाली-वर किंवा पुढे-मागे होणाऱ्या सततच्या हालचालीला दोलन गती म्हणतात.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शिवणयंत्रावर कापड शिवताना कापड सतत पुढे सरकत जाते, म्हणजेच तेथे कापडाची कोणती गती दिसून येते?\",\"options\":[\"एकरेषीय गती\",\"दोलन गती\",\"वर्तुळाकार गती\",\"कंप पावलेली गती\"],\"answer\":0,\"explain\":\"शिवणयंत्रावर कापड एका सरळ रेषेत पुढे सरकते, म्हणून ती एकरेषीय गती आहे.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, शिवणयंत्राच्या बाजूला असलेल्या चाकाची गती कोणत्या प्रकारची असते?\",\"options\":[\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"दोलन गती\",\"अनियतकालिक गती\"],\"answer\":1,\"explain\":\"शिवणयंत्राचे चाक स्वतःभोवती फिरते, म्हणून त्याची गती वर्तुळाकार असते.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"analyze\",\"figure_image\":\"37\\/122_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील झोपाळ्याच्या हालचालीचे वर्णन कसे करता येईल?\",\"options\":[\"ती फक्त एकाच दिशेला जाणारी हालचाल आहे\",\"ती वर्तुळाकार फिरणारी हालचाल आहे\",\"ती एका टोकापासून दुसऱ्या टोकापर्यंत आणि पुन्हा मागे अशी हालचाल आहे\",\"ती कापडासारखी सरळ पुढे जाणारी हालचाल आहे\"],\"answer\":2,\"explain\":\"झोपाळा एका टोकापासून दुसऱ्या टोकापर्यंत आणि पुन्हा मागे अशा प्रकारे दोलन गती करतो.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"37\\/122_102.jpg\"},{\"q\":\"तंबोरा, सतार आणि वीणा या वाद्यांच्या तारा छेडल्यावर त्या काय पावतात?\",\"options\":[\"स्थिर पावतात\",\"कंप पावतात\",\"मोडतात\",\"वर्तुळाकार फिरतात\"],\"answer\":1,\"explain\":\"वाद्यांच्या तारा छेडल्यावर त्या कंप पावतात आणि ही गती दोलन गती असते.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शिवणयंत्राच्या सुईची हालचाल कोणत्या प्रकारची असते?\",\"options\":[\"वर्तुळाकार गती\",\"एकरेषीय गती\",\"दोलन गती\",\"स्थिर गती\"],\"answer\":2,\"explain\":\"सुई सतत खाली-वर हालचाल करते, जी दोलन गतीचे उदाहरण आहे.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"शिवणयंत्राच्या पायठ्याची (जिथे पाय ठेवतात) हालचाल कशी होताना दिसते?\",\"options\":[\"गोल फिरताना\",\"खाली-वर अशी\",\"फक्त पुढे जाणारी\",\"स्थिर राहणारी\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, शिवणयंत्राच्या पायठ्याची हालचाल खाली-वर अशी होताना दिसते.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शिवणयंत्राच्या मोठ्या चाकाच्या आसाजवळच्या टोकाची हालचाल कोणत्या प्रकारची असते?\",\"options\":[\"एकरेषीय\",\"खाली-वर\",\"वर्तुळाकार\",\"कंप पावणारी\"],\"answer\":2,\"explain\":\"पाठात नमूद केल्याप्रमाणे, मोठ्या चाकाच्या आसाजवळच्या टोकाची हालचाल वर्तुळाकार असते.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर एखादी वस्तू एका टोकापासून दुसऱ्या टोकापर्यंत जाऊन पुन्हा मागे येत असेल, तर त्या गतीला काय म्हणाल?\",\"options\":[\"वर्तुळाकार गती\",\"दोलन गती\",\"एकरेषीय गती\",\"स्थिर गती\"],\"answer\":1,\"explain\":\"झोपाळ्याच्या उदाहरणावरून, ही हालचाल दोलन गती दर्शवते.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या वाद्यात दोलन गतीचा वापर होतो?\",\"options\":[\"बासरी\",\"ढोलकी\",\"सतार\",\"शंख\"],\"answer\":2,\"explain\":\"सतार या वाद्याच्या ताणलेल्या तारा छेडल्यावर त्या दोलन गती (कंप) निर्माण करतात.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शिवणयंत्राच्या पायठ्याची हालचाल आणि सुईची हालचाल यात कोणते साम्य आहे?\",\"options\":[\"दोन्ही वर्तुळाकार आहेत\",\"दोन्ही एकरेषीय आहेत\",\"दोन्ही खाली-वर होणाऱ्या हालचाली आहेत\",\"दोन्ही स्थिर आहेत\"],\"answer\":2,\"explain\":\"पायठा आणि सुई या दोन्ही भागांची हालचाल खाली-वर अशी होते, जी दोलन गतीशी संबंधित आहे.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"एखादी ताणलेली तार छेडली असता निर्माण होणारी गती कोणत्या प्रकारची असेल?\",\"options\":[\"दोलन गती\",\"वर्तुळाकार गती\",\"एकरेषीय गती\",\"अनियतकालिक गती\"],\"answer\":0,\"explain\":\"ताणलेली तार छेडल्यावर ती कंप पावते, ज्याला दोलन गती म्हणतात.\",\"topic\":\"दोलन गती\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"वेगवेगळ्या दिशांना सतत बदलणाऱ्या वस्तूंच्या गतीला काय म्हणतात?\",\"options\":[\"एकरेषीय गती\",\"यादृच्छिक गती\",\"दोलन गती\",\"नियतकालिक गती\"],\"answer\":1,\"explain\":\"मजकुरामध्ये स्पष्टपणे नमूद केले आहे की वेगवेगळ्या दिशांना गतिमान असणाऱ्या वस्तूंच्या गतीला \'यादृच्छिक गती\' म्हणतात.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"बागेतील फुलांभोवती उडणाऱ्या फुलपाखराची गती कोणत्या प्रकारची असते?\",\"options\":[\"एकरेषीय गती\",\"वर्तुळाकार गती\",\"यादृच्छिक गती\",\"स्थिर गती\"],\"answer\":2,\"explain\":\"फुलपाखरे वेगवेगळ्या दिशांना वेडीवाकडी उडत असल्याने त्यांची गती यादृच्छिक असते.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती गती \'नैकरेषीय गती\' या प्रकारात मोडते?\",\"options\":[\"केवळ वर्तुळाकार गती\",\"केवळ दोलन गती\",\"केवळ यादृच्छिक गती\",\"यादृच्छिक, वर्तुळाकार आणि दोलन गती\"],\"answer\":3,\"explain\":\"मजकुराप्रमाणे यादृच्छिक, वर्तुळाकार आणि दोलन गती या एका रेषेत नसल्यामुळे त्या नैकरेषीय गती आहेत.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत पट्टीला खालच्या दिशेने धक्का दिल्यावर पट्टीची होणारी हालचाल कोणत्या प्रकारची गती दर्शवते?\",\"options\":[\"एकरेषीय गती\",\"दोलन गती\",\"यादृच्छिक गती\",\"वर्तुळाकार गती\"],\"answer\":1,\"explain\":\"पट्टी वर-खाली हालचाल करते, जी दोलन गतीचे उदाहरण आहे.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"apply\",\"figure_image\":\"37\\/123_101.jpg\"},{\"q\":\"दिलेल्या आकृतीमधील प्रयोगात पट्टीचा टेबलावरील भाग स्थिर राहण्यासाठी त्यावर काय ठेवले आहे?\",\"options\":[\"पाण्याची बाटली\",\"पेन आणि पेन्सिल\",\"वह्या-पुस्तके किंवा वीट\",\"काहीही ठेवलेले नाही\"],\"answer\":2,\"explain\":\"आकृती आणि मजकुराप्रमाणे पट्टीवर वह्या-पुस्तके किंवा वीट यांसारखी जड वस्तू ठेवली आहे.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"37\\/123_101.jpg\"},{\"q\":\"सायकल गतिमान असताना तिच्या चाकामध्ये कोणत्या प्रकारची गती दिसून येते?\",\"options\":[\"वर्तुळाकार गती\",\"यादृच्छिक गती\",\"दोलन गती\",\"एकरेषीय गती\"],\"answer\":0,\"explain\":\"सायकलचे चाक स्वतःभोवती फिरते, म्हणून ती वर्तुळाकार गती आहे.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"फुलपाखराची गती एकरेषीय का नसते?\",\"options\":[\"ते खूप वेगाने उडते म्हणून\",\"ते वेगवेगळ्या दिशांना वेडेवाकडे उडते म्हणून\",\"ते फक्त वर्तुळाकार उडते म्हणून\",\"ते एकाच जागी स्थिर असते म्हणून\"],\"answer\":1,\"explain\":\"फुलपाखरे उडताना वेगवेगळ्या दिशांना वेडीवाकडी उडत असतात, म्हणून त्यांची गती एकरेषीय नसते.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"नैकरेषीय गती म्हणजे काय?\",\"options\":[\"एका सरळ रेषेत असणारी गती\",\"एका रेषेत नसणारी गती\",\"खूप वेगाने होणारी हालचाल\",\"विशिष्ट दिशेने होणारी गती\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्ट केले आहे की ज्या गती एका रेषेत नसतात, त्यांना नैकरेषीय गती म्हणतात.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"पट्टीच्या प्रयोगात पट्टीचा अर्धा भाग टेबलाबाहेर का ठेवला जातो?\",\"options\":[\"पट्टी तोडण्यासाठी\",\"पट्टीला धक्का देऊन हालचाल पाहण्यासाठी\",\"पट्टीचे वजन मोजण्यासाठी\",\"पट्टीचा रंग पाहण्यासाठी\"],\"answer\":1,\"explain\":\"पट्टीच्या हालचालीचे निरीक्षण करण्यासाठी तिचा अर्धा भाग टेबलाबाहेर ठेवला जातो.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"सायकलच्या उदाहरणावरून आपण काय निष्कर्ष काढू शकतो?\",\"options\":[\"एका वस्तूमध्ये एकाच वेळी एकच गती असते\",\"एकाच वेळी एकाच वस्तूमध्ये वेगवेगळ्या प्रकारांच्या गती असू शकतात\",\"सायकलमध्ये फक्त यादृच्छिक गती असते\",\"सायकलला कोणतीही गती नसते\"],\"answer\":1,\"explain\":\"सायकलचे चाक, पॅडल आणि चेन यामध्ये वेगवेगळ्या प्रकारच्या गती एकाच वेळी दिसून येतात.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"पट्टीला धक्का दिल्यावर तिची हालचाल किती वेळ होत राहते?\",\"options\":[\"ती सतत होत राहते\",\"ती लगेच थांबते\",\"काही वेळ हालचाल होत राहते\",\"हालचाल होतच नाही\"],\"answer\":2,\"explain\":\"मजकुराप्रमाणे पट्टीला धक्का दिल्यावर काही वेळ पट्टीच्या त्या भागाची हालचाल होत राहते.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते उदाहरण यादृच्छिक गतीचे नाही?\",\"options\":[\"फुलांभोवती उडणारे फुलपाखरू\",\"वेड्यावाकड्या दिशांना जाणारी वस्तू\",\"सरळ रेषेत जाणारी आगगाडी\",\"मैदानावर धावणारा मुलगा\"],\"answer\":2,\"explain\":\"सरळ रेषेत जाणारी आगगाडी ही एकरेषीय गती आहे, यादृच्छिक नाही.\",\"topic\":\"करून पाहा व निरीक्षण करा\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"जेव्हा वस्तू आपली जागा बदलत असते, तेव्हा ती वस्तू खालीलपैकी काय आहे असे म्हणतात?\",\"options\":[\"स्थिर\",\"गतिमान\",\"जड\",\"अदृश्य\"],\"answer\":1,\"explain\":\"वस्तू आपली जागा बदलत असते, तेव्हा ती वस्तू गतिमान आहे असे म्हणतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"वस्तूचे स्थानबदल पाहताना कोणत्या गोष्टी महत्त्वाच्या असतात?\",\"options\":[\"वस्तूचा आकार आणि वजन\",\"निरीक्षकाचे स्थान आणि स्थिर संदर्भ\",\"केवळ वस्तूचा वेग\",\"केवळ वस्तूचा रंग\"],\"answer\":1,\"explain\":\"स्थानबदल पाहताना निरीक्षकाचे स्थान आणि स्थिर संदर्भ महत्त्वाचे असतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"चालत्या वाहनातील निरीक्षकाला त्याच्या शेजारील प्रवाशांच्या बाबतीत काय वाटते?\",\"options\":[\"प्रवासी वेगाने धावत आहेत\",\"प्रवाशांची जागा बदलली आहे\",\"प्रवाशांची जागा बदलली नाही\",\"प्रवासी वर्तुळाकार फिरत आहेत\"],\"answer\":2,\"explain\":\"वाहनातील निरीक्षकाला शेजारील प्रवासी, वस्तू यांची जागा बदलली नाही असे वाटते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"वाहनाबाहेरील निरीक्षकाला वाहनातील वस्तूंच्या बाबतीत काय दिसते?\",\"options\":[\"वस्तू स्थिर आहेत\",\"वस्तूंची जागा बदलत आहे\",\"वस्तू अदृश्य आहेत\",\"वस्तू मागे जात नाहीत\"],\"answer\":1,\"explain\":\"वाहनाबाहेरील निरीक्षकाला वाहनातील वस्तूंचीही जागा बदलत आहे हे दिसते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता गतीचा एक प्रकार म्हणून पाठात दिलेला नाही?\",\"options\":[\"एकरेषीय गती\",\"यादृच्छिक गती\",\"स्थिर गती\",\"दोलन गती\"],\"answer\":2,\"explain\":\"पाठात एकरेषीय, नैकरेषीय, वर्तुळाकार, दोलन आणि यादृच्छिक गती हे प्रकार दिले आहेत; \'स्थिर गती\' नाही.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"एकाच वेळी वेगवेगळ्या प्रकारांच्या गती दिसणे हे कोणत्या बाबतीत शक्य आहे?\",\"options\":[\"केवळ स्थिर वस्तूंमध्ये\",\"काही विशिष्ट घटनांमध्ये\",\"केवळ एकरेषीय गतीमध्ये\",\"कोणत्याही घटनेत शक्य नाही\"],\"answer\":1,\"explain\":\"काही घटनांमध्ये एकाच वेळी वेगवेगळ्या प्रकारांच्या गती दिसतात.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"गतीचे मोजमाप करण्यासाठी निरीक्षकासाठी काय असणे आवश्यक आहे?\",\"options\":[\"स्थिर संदर्भ\",\"मोठा आवाज\",\"वस्तूचा रंग\",\"अंधार\"],\"answer\":0,\"explain\":\"गती किंवा स्थानबदल पाहताना स्थिर संदर्भ महत्त्वाचा असतो.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर एखादी वस्तू सतत आपली जागा बदलत असेल, तर त्या क्रियेला काय म्हणतात?\",\"options\":[\"विश्रांती\",\"गती\",\"आकार\",\"वजन\"],\"answer\":1,\"explain\":\"जागा बदलण्याच्या क्रियेवरून वस्तू गतिमान आहे की नाही हे ठरते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"एखादी वस्तू गतिमान आहे की नाही हे ठरवण्यासाठी कोणाचे स्थान महत्त्वाचे असते?\",\"options\":[\"केवळ वस्तूचे\",\"निरीक्षकाचे\",\"केवळ सूर्याचे\",\"कोणाचेही नाही\"],\"answer\":1,\"explain\":\"स्थानबदल पाहताना निरीक्षकाचे स्थान महत्त्वाचे असते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या गतीमध्ये वस्तूची दिशा सतत बदलत असते असे आपण म्हणू शकतो? (पाठातील प्रकारानुसार)\",\"options\":[\"एकरेषीय गती\",\"यादृच्छिक गती\",\"स्थिर अवस्था\",\"शून्य गती\"],\"answer\":1,\"explain\":\"यादृच्छिक गती हा गतीचा एक प्रकार आहे ज्यामध्ये दिशा निश्चित नसते.\",\"topic\":\"आपण काय शिकलो?\",\"part\":10,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21881,37,6,'Science','mr','निसर्ग संपदा','[\"मातीची पोत म्हणजे मातीतील कणांचे आकार व प्रमाण.\",\"काळी माती सुपीक असते, लाल माती वाळूयुक्त असते.\",\"मातीची जलधारण क्षमता म्हणजे पाणी धरून ठेवण्याची क्षमता.\",\"पाणी हे निसर्गातील सर्वात महत्त्वाचे संसाधन आहे.\",\"पावसाचे पाणी, भूजल, तलाव, नदी, समुद्र हे पाण्याचे स्रोत आहेत.\",\"सागरातून मासे, मीठ, खनिजे, औषधी वनस्पती मिळतात.\",\"सौरऊर्जा म्हणजे सूर्यप्रकाशाची ऊर्जा, पवनऊर्जा म्हणजे वाऱ्याची ऊर्जा.\",\"जंगलांमधून लाकूड, कागद, औषधी वनस्पती मिळतात.\",\"जीवाश्म इंधन म्हणजे कोळसा, पेट्रोल, नैसर्गिक वायू.\",\"नैसर्गिक संसाधने तीन प्रकारची: नवीकरणीय, अनवबीकरणीय, शाश्वत.\",\"पाणी वाचवणे म्हणजे जीवन वाचवणे.\",\"सौर पॅनल, सौर कुकर, पवनचक्की यांचा वापर ऊर्जा निर्मितीसाठी होतो.\",\"पाणी साठवण्यासाठी होद, बावडी, वाव यांचा वापर होतो.\",\"मातीची ओलावा टिकून ठेवण्याची गुणधर्म मातीच्या पोतावर अवलंबून असतो.\",\"सागरातील गाळात तांबे, लोह, दगड इत्यादी खनिजे मिळतात.\",\"सौरऊर्जेचा वापर स्वयंपाक, पाणी गरम करणे, प्रकाश यासाठी होतो.\",\"पवनऊर्जेचा वापर पवनचक्की, पवनचक्की प्रकल्पांमध्ये होतो.\",\"जंगलतोडीमुळे पाण्याचे प्रमाण कमी होते व प्राण्यांचे अधिवास नष्ट होतात.\",\"जीवाश्म इंधन वापरामुळे हवा व पाणी प्रदूषित होते.\",\"नैसर्गिक संपत्तीचे संरक्षण करणे आपली जबाबदारी आहे.\",\"सौरऊर्जा व पवनऊर्जा नवीकरणीय आहेत, कोळसा व पेट्रोल अनवबीकरणीय.\",\"पाणी वाचवण्यासाठी घरात पाण्याची गळती दुरुस्त करावी.\"]','[{\"q\":\"कर्नाटक, ओडिशा आणि महाराष्ट्र या राज्यांमध्ये कोणत्या रंगाचे खडक मोठ्या प्रमाणात आढळतात?\",\"options\":[\"काळे खडक\",\"पांढरे खडक\",\"लालसर खडक\",\"पिवळसर खडक\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे कर्नाटक, ओडिशा आणि महाराष्ट्र या राज्यांत लालसर खडकांचे डोंगर आहेत.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"डोंगरातील लाल खडकांपासून बनलेली माती शेतीसाठी कशी असते?\",\"options\":[\"अतिशय सुपीक\",\"मध्यम सुपीक\",\"बिलकूल नापीक\",\"फळबागांसाठी उत्तम\"],\"answer\":2,\"explain\":\"पाठात स्पष्ट म्हटले आहे की लाल खडकांची बनलेली ही माती शेतीसाठी बिलकूल नापीक असते.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मातीला आणि खडकांना लाल रंग कशामुळे प्राप्त होतो?\",\"options\":[\"जास्त पावसामुळे\",\"त्यात असणाऱ्या लोखंडाच्या खनिजामुळे\",\"डोंगरावरील वनस्पतींमुळे\",\"हवेतील ऑक्सिजनमुळे\"],\"answer\":1,\"explain\":\"मातीचा आणि खडकांचा लाल रंग त्यात असणाऱ्या लोखंडाच्या खनिजामुळे असतो.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लाल मातीवर प्रक्रिया करून त्यापासून प्रामुख्याने काय मिळवता येते?\",\"options\":[\"सोने आणि तांबे\",\"लोखंड आणि पोलाद\",\"ॲल्युमिनियम आणि पितळ\",\"कोळसा आणि डिझेल\"],\"answer\":1,\"explain\":\"लाल मातीवर प्रक्रिया करून त्यापासून लोखंड आणि पोलाद मिळवता येते.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"भारतातील लोहखनिजाच्या साठ्याबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"भारताकडे लोहखनिज खूप कमी आहे.\",\"भारताला लोहखनिज दुसऱ्या देशांकडून विकत घ्यावे लागते.\",\"भारतातील कारखान्यांची गरज भागवूनही लोहखनिज शिल्लक राहते.\",\"भारतातील लोहखनिज फक्त शेतीसाठी वापरले जाते.\"],\"answer\":2,\"explain\":\"देशातील पोलाद कारखान्यांची गरज भागवूनसुद्धा भारताकडे खूप लोहखनिज शिल्लक राहते.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जगातील अनेक देश भारताकडून दरवर्षी काय विकत घेतात?\",\"options\":[\"लाखो टन लोहखनिज\",\"तयार पोलादी कारखाने\",\"शेतीसाठी लाल माती\",\"डोंगरातील लाल खडक\"],\"answer\":0,\"explain\":\"जगातील अनेक देश दरवर्षी लाखो टन लोह खनिज भारताकडून विकत घेतात.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"काही देशांमध्ये पोलाद बनवण्याचे कारखाने असूनही ते भारतावर का अवलंबून आहेत?\",\"options\":[\"कारण त्यांच्याकडे कामगार नाहीत.\",\"कारण त्यांच्याकडे लोखंडाचे खनिज नाही.\",\"कारण त्यांना भारताची माती आवडते.\",\"कारण त्यांच्याकडे कारखाने चालवायला वीज नाही.\"],\"answer\":1,\"explain\":\"त्या देशांमध्ये पोलाद बनवण्याचे कारखाने आहेत, पण लोखंडाचे खनिज नाही, म्हणून ते भारताकडून खनिज घेतात.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"लोहखनिजाच्या व्यापारामुळे भारताला दरवर्षी किती फायदा होतो?\",\"options\":[\"काही हजार रुपये\",\"काही लाख रुपये\",\"कित्येक कोटी रुपये\",\"फायदा होत नाही\"],\"answer\":2,\"explain\":\"लोहखनिजाच्या व्यापारात आपल्या देशाला दरवर्षी कित्येक कोटी रुपये मिळतात.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"भारतातील लोहखनिजाचे साठे साधारणपणे किती काळ टिकतील असा अंदाज आहे?\",\"options\":[\"पुढील १०-२० वर्षे\",\"पुढील ५० वर्षे\",\"पुढील १००-२०० वर्षे\",\"पुढील ५००-१००० वर्षे\"],\"answer\":2,\"explain\":\"पुढील शंभर, दोनशे वर्षे हा व्यापार चालू राहील इतके साठे भारताकडे आहेत.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या शेतकऱ्याने या लाल मातीत खते न घालता पिके लावली, तर काय होईल?\",\"options\":[\"पिके जोमाने वाढतील.\",\"पिके वाढणार नाहीत कारण माती नापीक आहे.\",\"पिकांचा रंग लाल होईल.\",\"पिकांना लोखंडाची फळे येतील.\"],\"answer\":1,\"explain\":\"ही माती शेतीसाठी नापीक असल्याने त्यात पिके वाढत नाहीत.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"शेतीसाठी नापीक असणारी ही लाल माती प्रत्यक्षात देशाची \'श्रीमंती\' का मानली जाते?\",\"options\":[\"कारण ती दिसायला सुंदर आहे.\",\"कारण ती डोंगराचे रक्षण करते.\",\"कारण तिच्यातील खनिजाच्या निर्यातीतून देशाला मोठी संपत्ती मिळते.\",\"कारण ती सर्व राज्यांमध्ये आढळते.\"],\"answer\":2,\"explain\":\"नापीक असूनही या मातीतील खनिजाच्या व्यापारामुळे देशाला मोठी संपत्ती मिळते, म्हणून ती श्रीमंती आहे.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"परदेशातील पोलाद कारखाने प्रामुख्याने कशावर चालतात?\",\"options\":[\"भारताने दिलेल्या खनिजावर\",\"त्यांच्या स्वतःच्या देशातील खनिजावर\",\"शेतीतील उत्पादनावर\",\"लाल मातीच्या डोंगरावर\"],\"answer\":0,\"explain\":\"उताऱ्यात म्हटले आहे की, परदेशातील ते कारखाने आपण (भारताने) दिलेल्या खनिजावर चालतात.\",\"topic\":\"निसर्ग संपदा - प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"बॉक्साईट या खनिजापासून कोणता धातू मिळतो?\",\"options\":[\"लोखंड\",\"तांबे\",\"ॲल्युमिनिअम\",\"सोने\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की बॉक्साईटपासून ॲल्युमिनिअम धातू मिळतो.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"चिनी मातीचे साठे प्रामुख्याने कोणत्या राज्यांमध्ये आढळतात?\",\"options\":[\"महाराष्ट्र आणि गुजरात\",\"बिहार आणि केरळ\",\"राजस्थान आणि गोवा\",\"कर्नाटक आणि तमिळनाडू\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार बिहार आणि केरळमध्ये चिनी माती आढळते.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'निसर्ग संपदा\' या शब्दातील \'संपदा\' या शब्दाचा अर्थ काय होतो?\",\"options\":[\"गरिबी\",\"श्रीमंती किंवा संपत्ती\",\"व्यवसाय\",\"निसर्गाचा ऱ्हास\"],\"answer\":1,\"explain\":\"उताऱ्यात संपदा म्हणजे संपत्ती किंवा श्रीमंती असा अर्थ दिला आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"सौंदर्य प्रसाधनांसाठी (Cosmetics) कोणत्या मातीचा वापर केला जातो?\",\"options\":[\"काळी माती\",\"चिनी माती\",\"मुलतानी माती\",\"टेराकोटा माती\"],\"answer\":2,\"explain\":\"राजस्थानमधील मुलतानी माती सौंदर्य प्रसाधनांसाठी वापरली जाते असे उताऱ्यात म्हटले आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"एखाद्या कलाकाराला मातीच्या शोभेच्या वस्तू किंवा मूर्ती तयार करायच्या असल्यास, तो कोणत्या प्रकारची माती वापरेल?\",\"options\":[\"मुलतानी माती\",\"टेराकोटा\",\"काळी सुपीक माती\",\"गाळाची माती\"],\"answer\":1,\"explain\":\"टेराकोटा नावाच्या मातीपासून शोभेच्या वस्तू आणि मूर्ती तयार करतात.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, \'मातीमोल होणे\' या वाक्प्रचाराचा उगम कशामुळे झाला असावा?\",\"options\":[\"माती खूप महाग असल्यामुळे\",\"मातीचे महत्त्व आणि उपयोग माहीत नसल्यामुळे\",\"मातीपासून सोने बनवता येते म्हणून\",\"माती केवळ शेतीसाठी वापरली जाते म्हणून\"],\"answer\":1,\"explain\":\"जेव्हा लोकांना मातीचे विशेष गुण माहीत नव्हते, तेव्हा ती क्षुल्लक वाटायची, त्यातून हा वाक्प्रचार आला.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"कोकणातील किनारी प्रदेश आणि रत्नागिरी भागात कोणत्या रंगाचे खडक आढळतात ज्यातून बॉक्साईट मिळते?\",\"options\":[\"काळे खडक\",\"पांढरे खडक\",\"लाल खडक\",\"निळे खडक\"],\"answer\":2,\"explain\":\"कोकण आणि रत्नागिरी भागात लाल खडक आणि त्यापासून बनलेले डोंगर आहेत असे उताऱ्यात दिले आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"नद्यांच्या पुरांसोबत आलेल्या गाळापासून तयार झालेली माती ही \'निसर्ग संपदा\' का मानली जाते?\",\"options\":[\"कारण ती मानवाने कारखान्यात तयार केली आहे\",\"कारण ती निसर्गाने दिलेली देणगी असून ती सुपीक असते\",\"कारण ती फक्त राजस्थानमध्ये आढळते\",\"कारण त्यापासून फक्त मूर्ती बनवता येतात\"],\"answer\":1,\"explain\":\"निसर्गाने दिलेली आणि मानवाने निर्माण न केलेली संपत्ती म्हणजे निसर्ग संपदा होय.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"जर भारताला परकीय चलन मिळवण्यासाठी खनिजाची निर्यात करायची असेल, तर उताऱ्यात कोणत्या खनिजाचा उल्लेख \'लाखो टन निर्यात\' म्हणून केला आहे?\",\"options\":[\"चिनी माती\",\"मुलतानी माती\",\"बॉक्साईट\",\"टेराकोटा\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केले आहे की आपला देश लाखो टन बॉक्साईट इतर देशांना निर्यात करतो.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती गोष्ट \'निसर्ग संपदा\' या व्याख्येत बसत नाही?\",\"options\":[\"नद्यांच्या पुराचा गाळ\",\"जमिनीत असलेली चिनी माती\",\"प्लास्टिकच्या बाटल्या\",\"शेतातील काळी सुपीक माती\"],\"answer\":2,\"explain\":\"निसर्ग संपदा ही निसर्गाने दिलेली देणगी असते, प्लास्टिक हे मानवनिर्मित आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"मुलतानी माती प्रामुख्याने कोणत्या राज्यात आढळते?\",\"options\":[\"केरळ\",\"बिहार\",\"महाराष्ट्र\",\"राजस्थान\"],\"answer\":3,\"explain\":\"उताऱ्यात राजस्थानमधील मुलतानी माती असा स्पष्ट उल्लेख आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मातीचे साठे ही देशाची संपत्ती आहे, हे लोकांना गेल्या काही वर्षांत का समजू लागले आहे?\",\"options\":[\"कारण आता मातीचे उपयोग आणि औद्योगिक महत्त्व समजले आहे\",\"कारण आता माती मिळणे बंद झाले आहे\",\"कारण मातीचा रंग बदलला आहे\",\"कारण माती आता मानवाने तयार केली आहे\"],\"answer\":0,\"explain\":\"मातीचे विशेष गुण आणि उद्योगांमधील वापर समजल्यामुळे ती आता मौल्यवान संपत्ती ठरत आहे.\",\"topic\":\"खनिजे आणि निसर्ग संपदा\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"गाळापासून बनलेल्या मातीचा स्पर्श खालीलपैकी कसा असतो?\",\"options\":[\"वाळूसारखा खरखरीत\",\"रांगोळीसारखा खरखरीत\",\"पिठासारखा मऊ\",\"दगडासारखा कडक\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे गाळापासून बनलेल्या मातीचा स्पर्श पिठासारखा मऊ असतो.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"धुरकट पांढरी माती असलेल्या शेतांमध्ये प्रामुख्याने कोणते पीक घेतले जाते?\",\"options\":[\"गहू\",\"मिरची\",\"तांदूळ\",\"ज्वारी\"],\"answer\":1,\"explain\":\"धुरकट पांढरी माती असलेल्या बऱ्याच शेतांमध्ये मिरचीचे पीक घेतले जाते असे पुस्तकात दिले आहे.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"मातीचा \'पोत\' (Texture) कशावरून ठरवला जातो?\",\"options\":[\"मातीचा रंग आणि चव यावरून\",\"मातीतील पाण्याचे प्रमाण आणि खोली यावरून\",\"मातीतील कणांचा आकार आणि त्यांचे प्रमाण यावरून\",\"मातीमध्ये असलेल्या दगडांच्या संख्येवरून\"],\"answer\":2,\"explain\":\"मातीमध्ये असलेल्या वाळूसारख्या कणांचा आकार आणि त्यांचे प्रमाण यावरून मातीचा पोत ठरतो.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"मातीची पाणी धरून ठेवण्याची क्षमता म्हणजे काय?\",\"options\":[\"जलधारण क्षमता\",\"जलप्रदूषण क्षमता\",\"जलावरण क्षमता\",\"जलसिंचन क्षमता\"],\"answer\":0,\"explain\":\"मातीची पाणी धरून ठेवण्याच्या क्षमतेला \'जलधारण क्षमता\' असे म्हणतात.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या मातीचा स्पर्श रांगोळीसारखा खरखरीत असेल, तर त्या मातीत कोणत्या कणांचे प्रमाण जास्त असेल?\",\"options\":[\"पिठासारख्या मऊ कणांचे\",\"वाळूसारख्या कणांचे\",\"पाण्याचे\",\"तेलाचे\"],\"answer\":1,\"explain\":\"वाळूसारख्या कणांमुळे मातीचा स्पर्श रांगोळीसारखा खरखरीत जाणवतो.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"शेती आणि बांधकाम या दोन्हीसाठी मातीचा कोणता गुणधर्म महत्त्वाचा आहे?\",\"options\":[\"मातीचा पांढरा रंग\",\"मातीचा सुगंध\",\"ओलावा टिकून राहणे\",\"मातीचा कडकपणा\"],\"answer\":2,\"explain\":\"शेती आणि बांधकाम यासाठी मातीमध्ये ओलावा टिकून राहणे हा महत्त्वाचा गुणधर्म आहे.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"मातीची जलधारण क्षमता वाढवण्यासाठी खालीलपैकी कोणता घटक उपयुक्त ठरतो?\",\"options\":[\"केवळ वाळूचे प्रमाण वाढवणे\",\"कुजलेला पालापाचोळा आणि शेण मिसळणे\",\"मातीतील सर्व पाणी काढून टाकणे\",\"मातीचा रंग बदलणे\"],\"answer\":1,\"explain\":\"कुजलेला पालापाचोळा आणि शेण यांसारख्या पदार्थांच्या प्रमाणावर मातीची पाणी धरून ठेवण्याची क्षमता अवलंबून असते.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"मूर्ती बनवण्यासाठी प्रामुख्याने कोणत्या प्रकारची माती वापरली जाते?\",\"options\":[\"वाळूमिश्रित माती\",\"शाडू माती\",\"मुलतानी माती\",\"विटांची माती\"],\"answer\":1,\"explain\":\"पुस्तकात मूर्ती बनवण्यासाठी शाडू मातीचा उल्लेख पर्यायी माती म्हणून केला आहे.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"मातीचे \'खरखरीत, मध्यम खरखरीत आणि मऊ\' असे वर्गीकरण कशाच्या आधारे केले जाते?\",\"options\":[\"मातीच्या रंगाच्या छटांवरून\",\"मातीच्या पोतावरून\",\"मातीच्या वजनावरून\",\"मातीच्या वासावरून\"],\"answer\":1,\"explain\":\"मातीच्या पोतावर आधारित कणांच्या आकारानुसार हे प्रकार केले जातात.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या मातीचा उपयोग सौंदर्य प्रसाधनांमध्ये किंवा त्वचेसाठी केला जातो?\",\"options\":[\"शाडू माती\",\"टेराकोटा\",\"मुलतानी माती\",\"चिनी माती\"],\"answer\":2,\"explain\":\"मुलतानी मातीचा वापर सौंदर्यासाठी केला जातो हे सामान्य ज्ञानासह उताऱ्यातील संदर्भावरून स्पष्ट होते.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"एका शेतकऱ्याला त्याच्या शेतातील मातीची जलधारण क्षमता कमी असल्याचे आढळले, तर त्याने काय करावे?\",\"options\":[\"मातीमध्ये वाळूचे प्रमाण वाढवावे\",\"मातीमध्ये कुजलेला पालापाचोळा आणि शेणखत मिसळावे\",\"मातीचा रंग बदलण्याचा प्रयत्न करावा\",\"शेतात फक्त मिरचीचे पीक घ्यावे\"],\"answer\":1,\"explain\":\"पालापाचोळा आणि शेण यांमुळे मातीची पाणी धरून ठेवण्याची क्षमता सुधारते.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मातीचा पोत आणि तिचे गुणधर्म यांचा एकमेकांशी काय संबंध आहे?\",\"options\":[\"मातीचे उपयोग तिच्या पोतावर अवलंबून असतात\",\"पोत आणि गुणधर्मांचा कोणताही संबंध नसतो\",\"केवळ रंगावरून गुणधर्म ठरतात\",\"पोत फक्त स्पर्शासाठी महत्त्वाचा असतो\"],\"answer\":0,\"explain\":\"मातीचे इतर काही गुणधर्म आणि उपयोग मातीच्या पोतावर अवलंबून असतात असे उताऱ्यात स्पष्ट म्हटले आहे.\",\"topic\":\"मातीचे गुणधर्म आणि पोत\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"या प्रयोगामध्ये प्रत्येक नरसाळ्यात किती मि.ली. पाणी घालण्यास सांगितले आहे?\",\"options\":[\"१० मि.ली.\",\"१५ मि.ली.\",\"२० मि.ली.\",\"२५ मि.ली.\"],\"answer\":2,\"explain\":\"पाठातील मजकुरानुसार प्रत्येक नरसाळ्यात २० मि.ली. पाणी घालण्यास सांगितले आहे.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"प्रयोगासाठी घेतलेल्या मातीच्या प्रत्येक नमुन्याचे वजन किती असावे?\",\"options\":[\"५ ग्रॅम\",\"१० ग्रॅम\",\"१५ ग्रॅम\",\"२० ग्रॅम\"],\"answer\":1,\"explain\":\"मजकुरात (अ) चिकण माती (ब) रेताड माती (क) वाळू प्रत्येकी दहा ग्रॅम घेण्यास सांगितले आहे.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नरसाळ्यामध्ये माती भरण्यापूर्वी त्यामध्ये काय बसवले जाते?\",\"options\":[\"कापड\",\"गाळण कागद\",\"प्लास्टिक पिशवी\",\"काचेची पट्टी\"],\"answer\":1,\"explain\":\"आकृतीत दाखवल्याप्रमाणे काचेच्या नरसाळ्यांमध्ये गाळण कागद बसवला जातो.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"चहा गाळल्यानंतर गाळणीमध्ये राहिलेल्या पदार्थावर चमच्याने दाब दिल्यास काय होईल?\",\"options\":[\"काहीच होणार नाही\",\"गाळणी तुटेल\",\"त्यातील उरलेला द्रव (चहा) खाली पडेल\",\"चहाची पूड कोरडी होईल\"],\"answer\":2,\"explain\":\"गाळणीत राहिलेल्या पदार्थावर दाब दिल्यास त्यातील शोषलेला द्रव बाहेर पडतो, हे प्रयोगाच्या सुरुवातीला विचारलेल्या प्रश्नावरून समजते.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"या प्रयोगात मोजपात्राचा (Measuring Cylinder) मुख्य उपयोग काय आहे?\",\"options\":[\"मातीचे वजन करण्यासाठी\",\"जमा झालेले पाणी मोजण्यासाठी\",\"नरसाळे धरून ठेवण्यासाठी\",\"पाणी गरम करण्यासाठी\"],\"answer\":1,\"explain\":\"मोजपात्राचा वापर नरसाळ्यातून खाली जमा झालेले पाणी किती आहे हे पाहण्यासाठी केला जातो.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्याकडे एकाच वेळी तीन मोजपात्रे उपलब्ध नसतील, तर तुम्ही प्रयोग कसा पूर्ण कराल?\",\"options\":[\"प्रयोग रद्द करावा\",\"एकाच मोजपात्रात सर्व माती एकत्र करावी\",\"एकापाठोपाठ एक तीनही नमुन्यांसाठी सारखीच कृती करावी\",\"पाणी न मोजता अंदाजे घ्यावे\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की एका वेळी तीन मोजपात्रे नसतील तर एकापाठोपाठ एक कृती करून निरीक्षणे नोंदवावीत.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"जर एका नमुन्यात २० मि.ली. पाणी घातले आणि मोजपात्रात ५ मि.ली. पाणी जमा झाले, तर त्या मातीने किती पाणी धरून ठेवले?\",\"options\":[\"५ मि.ली.\",\"१० मि.ली.\",\"१५ मि.ली.\",\"२० मि.ली.\"],\"answer\":2,\"explain\":\"घातलेले पाणी (२०) उणे जमा झालेले पाणी (५) = १५ मि.ली. पाणी मातीने धरून ठेवले.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत कोणत्या नमुन्याची (अ, ब किंवा क) जलधारण क्षमता सर्वात जास्त आहे?\",\"options\":[\"नमुना \'अ\'\",\"नमुना \'ब\'\",\"नमुना \'क\'\",\"सर्व नमुन्यांची क्षमता सारखीच आहे\"],\"answer\":0,\"explain\":\"आकृतीत \'अ\' मोजपात्रात सर्वात कमी पाणी जमा झाले आहे, याचा अर्थ त्या मातीने (चिकण माती) सर्वात जास्त पाणी धरून ठेवले आहे.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"37\\/127_101.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. कोणत्या नमुन्यातून पाणी सर्वात वेगाने किंवा जास्त प्रमाणात खाली आले आहे?\",\"options\":[\"चिकण माती (अ)\",\"रेताड माती (ब)\",\"वाळू (क)\",\"गाळण कागद\"],\"answer\":2,\"explain\":\"आकृती \'क\' मध्ये मोजपात्रात पाण्याची पातळी सर्वाधिक आहे, म्हणजेच वाळूतून पाणी सर्वात जास्त प्रमाणात खाली आले आहे.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"analyze\",\"figure_image\":\"37\\/127_101.jpg\"},{\"q\":\"या संपूर्ण कृतीचा मुख्य उद्देश मातीचा कोणता गुणधर्म तपासणे हा आहे?\",\"options\":[\"मातीचा रंग\",\"मातीचा आकार\",\"मातीची जलधारण क्षमता\",\"मातीचे वजन\"],\"answer\":2,\"explain\":\"विविध प्रकारच्या मातीतून किती पाणी खाली जाते आणि किती धरून ठेवले जाते, यावरून जलधारण क्षमता तपासली जाते.\",\"topic\":\"कृती : जलधारण क्षमता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"१ किलो कागद तयार करण्यासाठी सुमारे किती लिटर पाण्याची गरज असते?\",\"options\":[\"१०० ते २०० लिटर\",\"३४० ते ५०० लिटर\",\"५०० ते ७०० लिटर\",\"१००० लिटर पेक्षा जास्त\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, एक किलो कागद तयार करण्यासाठी सुमारे ३४० ते ५०० लिटर पाणी लागते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"प्राण्यांच्या शरीराचे तापमान नियंत्रित ठेवण्यासाठी खालीलपैकी कशाची मदत होते?\",\"options\":[\"अन्न\",\"घाम\",\"रक्त\",\"हाडे\"],\"answer\":1,\"explain\":\"शरीरातून येणाऱ्या घामामुळे शरीराचे तापमान नियंत्रित राहते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"ज्या पाण्यात साबणाचा भरपूर फेस होतो, त्या पाण्याला काय म्हणतात?\",\"options\":[\"दुष्फेन जल\",\"खारे पाणी\",\"सुफेन जल\",\"भूपृष्ठीय जल\"],\"answer\":2,\"explain\":\"ज्या पाण्यामध्ये साबणाचा भरपूर फेस होतो, त्या पाण्याला \'सुफेन जल\' म्हणतात.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पाऊस पडताना त्या पाण्यात सुरुवातीला खनिजे आणि क्षार नसण्याचे कारण काय?\",\"options\":[\"ते जमिनीवर साठलेले नसते\",\"ते प्रदूषित असते\",\"ते समुद्रातून येते\",\"ते खूप गरम असते\"],\"answer\":0,\"explain\":\"पावसाच्या पाण्यात खनिजे आणि क्षार विरघळलेले नसतात कारण ते थेट वातावरणातून येते, जमिनीतील क्षारांशी त्याचा संपर्क झालेला नसतो.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"राजस्थानमध्ये पायऱ्या असलेल्या विहिरींना काय म्हटले जाते?\",\"options\":[\"वाव\",\"हौद\",\"बावडी\",\"कूपनलिका\"],\"answer\":2,\"explain\":\"राजस्थानमध्ये पायऱ्या असलेल्या विहिरींना \'बावडी\' असे म्हणतात.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात पाणी साठवण्याची कोणती ऐतिहासिक पद्धत दर्शविली आहे?\",\"options\":[\"आधुनिक धरण\",\"दगडांनी बांधलेला हौद किंवा बावडी\",\"कूपनलिका\",\"रेन वॉटर हार्वेस्टिंग\"],\"answer\":1,\"explain\":\"चित्रात जुन्या काळातील दगडांनी बांधलेला मोठा हौद किंवा पायऱ्यांची विहीर (बावडी) दाखवली आहे.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"37\\/129_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील संरचनेच्या भिंती दगडी असण्याचा मुख्य उद्देश काय आहे?\",\"options\":[\"केवळ सजावटीसाठी\",\"साठवलेले पाणी टिकून राहण्यासाठी\",\"पाणी गरम करण्यासाठी\",\"पाणी खारट करण्यासाठी\"],\"answer\":1,\"explain\":\"भिंती दगडी असल्यामुळे साठवलेले पाणी दीर्घकाळ टिकून राहते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"37\\/129_102.jpg\"},{\"q\":\"दिलेल्या चित्रात दर्शविलेल्या \'रेन वॉटर हार्वेस्टिंग\' पद्धतीचा मुख्य फायदा काय आहे?\",\"options\":[\"पावसाचे पाणी समुद्राला मिळते\",\"जमिनीखालील पाण्याची पातळी वाढते\",\"केवळ पिण्यासाठी पाणी मिळते\",\"नदीचे प्रदूषण कमी होते\"],\"answer\":1,\"explain\":\"रेन वॉटर हार्वेस्टिंगमुळे जमिनीत पाणी मुरून भूगर्भातील पाण्याची पातळी वाढते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"apply\",\"figure_image\":\"37\\/129_103.jpg\"},{\"q\":\"काही विहिरींचे पाणी खारे का असते?\",\"options\":[\"त्यात साबण मिसळलेला असतो\",\"पाणी जमिनीत मुरताना त्यात विविध क्षार विरघळतात\",\"विहिरी समुद्राजवळ असतात\",\"विहिरीत कचरा टाकलेला असतो\"],\"answer\":1,\"explain\":\"पाणी जमिनीत मुरत असताना वेगवेगळ्या प्रकारचे अनेक क्षार त्यात विरघळल्यामुळे विहिरीचे पाणी खारे लागते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या पाण्याने कपडे स्वच्छ धुतले जात नसतील आणि साबणाचा फेस होत नसेल, तर ते पाणी कोणत्या प्रकारचे आहे?\",\"options\":[\"सुफेन जल\",\"दुष्फेन जल\",\"शुद्ध जल\",\"भूपृष्ठीय जल\"],\"answer\":1,\"explain\":\"साबणाचा फेस न होणाऱ्या पाण्याला \'दुष्फेन जल\' म्हणतात, ज्याने कपडे स्वच्छ निघत नाहीत.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"वनस्पती पाण्याचा उपयोग प्रामुख्याने कोणत्या कार्यासाठी करतात?\",\"options\":[\"तापमान वाढवण्यासाठी\",\"अन्न तयार करण्यासाठी\",\"क्षार बाहेर टाकण्यासाठी\",\"साफसफाईसाठी\"],\"answer\":1,\"explain\":\"अन्न तयार करण्यासाठी वनस्पती पाण्याचा उपयोग करतात.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जमिनीत मुरलेले आणि झिरपत खाली गेलेले पाणी विहिरींमध्ये पोहोचते, त्या पाण्याला काय म्हणतात?\",\"options\":[\"भूपृष्ठीय जल\",\"भूगर्भजल\",\"नदीचे पाणी\",\"समुद्राचे पाणी\"],\"answer\":1,\"explain\":\"जमिनीच्या खाली असलेल्या पाण्याला \'भूगर्भजल\' असे म्हणतात.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पाणी ही \'अमूल्य निसर्ग संपदा\' का आहे?\",\"options\":[\"कारण ते फुकट मिळते\",\"कारण ते केवळ शेतीसाठी लागते\",\"कारण उद्योग आणि जीवनावश्यक वस्तूंची निर्मिती पाण्याशिवाय शक्य नाही\",\"कारण ते समुद्रात खूप आहे\"],\"answer\":2,\"explain\":\"उद्योगधंद्यांची आणि जीवनावश्यक वस्तूंची निर्मिती पाण्याशिवाय शक्य नसल्यामुळे ते अमूल्य आहे.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"पर्जन्य जलसंवर्धन (Rainwater Harvesting) करताना पाणी कोठून गोळा केले जाते?\",\"options\":[\"केवळ नद्यांमधून\",\"इमारतींच्या छतांवरून आणि मैदानातून\",\"केवळ समुद्रातून\",\"विहिरींमधून\"],\"answer\":1,\"explain\":\"इमारतींच्या छतांवर पडणारे आणि मैदानात पडणारे पावसाचे पाणी गोळा करून साठवले जाते.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एका साखर कारखान्यात रोज टनवारी साखर तयार होते, तर तिथे पाण्याचा वापर कसा होत असेल?\",\"options\":[\"अत्यल्प प्रमाणात\",\"केवळ पिण्यासाठी\",\"खूप मोठ्या प्रमाणावर\",\"पाण्याची गरजच नसेल\"],\"answer\":2,\"explain\":\"ऊस लागवडीपासून साखर तयार होईपर्यंत कित्येक लिटर पाणी लागते, त्यामुळे कारखान्यात पाण्याचा वापर मोठ्या प्रमाणावर होतो.\",\"topic\":\"पाणी : एक अमूल्य निसर्ग संपदा\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जगातील अनेक लोकांचे प्रमुख अन्न खालीलपैकी कोणते आहे?\",\"options\":[\"मासे\",\"शंखशिंपले\",\"सागरी वनस्पती\",\"मीठ\"],\"answer\":0,\"explain\":\"पाठातील माहितीनुसार, मासे हे जगातील अनेक लोकांचे प्रमुख अन्न आहे.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"समुद्रतळातील गाळात खालीलपैकी काय मिळते?\",\"options\":[\"केवळ वाळू\",\"मौल्यवान धातू\",\"केवळ पाणी\",\"लाकूड\"],\"answer\":1,\"explain\":\"समुद्रतळाच्या गाळात काही मौल्यवान धातू मिळतात असे पाठात नमूद केले आहे.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"सागरी किनाऱ्यावरील वाळूचा वापर प्रामुख्याने कशासाठी केला जातो?\",\"options\":[\"अन्न शिजवण्यासाठी\",\"औषध निर्मितीसाठी\",\"काही उद्योगधंद्यांमध्ये\",\"पिण्याच्या पाण्यासाठी\"],\"answer\":2,\"explain\":\"काही ठिकाणच्या समुद्र किनाऱ्यावरील वाळूचा वापर काही उद्योगधंद्यामध्ये केला जातो.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"भारतातील कोणत्या राज्याच्या किनारपट्टीवरील वाळूमध्ये मौल्यवान खनिजांचे साठे आहेत?\",\"options\":[\"गुजरात\",\"महाराष्ट्र\",\"केरळ\",\"गोवा\"],\"answer\":2,\"explain\":\"भारतात केरळ, तमिळनाडू, आंध्र प्रदेश आणि ओडिशा या किनारपट्ट्यांवरील वाळूमध्ये खनिजांचे साठे आहेत.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"समुद्रतळाखालील खनिज तेल आणि नैसर्गिक वायू मिळवण्यासाठी कशाचा वापर केला जातो?\",\"options\":[\"केवळ हातांचा\",\"अनेक यंत्रांचा\",\"सागरी वनस्पतींचा\",\"शंखशिंपल्यांचा\"],\"answer\":1,\"explain\":\"अनेक यंत्रे वापरून समुद्रतळाखालील तेल आणि वायू मिळवता येतात.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत \'खनिजे\' या सागरी संपत्तीचा उपयोग प्रामुख्याने कोठे होतो असे दर्शवले आहे?\",\"options\":[\"अन्न व पोषणासाठी\",\"कारखाने व उद्योगांसाठी\",\"सौंदर्यप्रसाधनांसाठी\",\"दैनंदिन खाद्यपदार्थांसाठी\"],\"answer\":1,\"explain\":\"तक्त्यानुसार, तांबे, लोह, मॅग्नेशियम यांसारखी खनिजे कारखाने व उद्योगांसाठी उपयुक्त आहेत.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"37\\/130_101.jpg\"},{\"q\":\"दिलेल्या चित्रात कोणत्या प्रकारच्या सागरी संपत्तीचा व्यापार होताना दिसत आहे?\",\"options\":[\"खनिजे\",\"सागरी जीवसंपदा\",\"तेल व नैसर्गिक वायू\",\"जलीय वनस्पती\"],\"answer\":1,\"explain\":\"चित्रात मासे विकले जात आहेत, जे सागरी जीवसंपदेचा भाग आहेत.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"37\\/129_104.jpg\"},{\"q\":\"एखाद्या कंपनीला औषध निर्मिती किंवा सौंदर्यप्रसाधने तयार करायची असल्यास, ते खालीलपैकी कोणत्या सागरी संपत्तीचा वापर करतील?\",\"options\":[\"खनिज तेल\",\"मीठ\",\"जलीय वनस्पती\",\"तांबे\"],\"answer\":2,\"explain\":\"जलीय वनस्पतींचा (उदा. समुद्री शैवाल) वापर औषध निर्मिती व सौंदर्यप्रसाधनांमध्ये होतो.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता घटक \'सागरी जीवसंपदा\' या गटात येत नाही?\",\"options\":[\"कोळंबी\",\"खेकडे\",\"शंख\",\"मॅग्नेशियम\"],\"answer\":3,\"explain\":\"मॅग्नेशियम हे खनिज आहे, तर कोळंबी, खेकडे आणि शंख हे जीवसंपदा आहेत.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खनिज तेल आणि नैसर्गिक वायू यांपासून काय मिळते, ज्यामुळे त्यांचा वापर वाहतुकीसाठी होतो?\",\"options\":[\"क्षार\",\"इंधने\",\"आयोडीन\",\"धातू\"],\"answer\":1,\"explain\":\"खनिज तेल आणि नैसर्गिक वायू यांपासून इंधने मिळतात, जी ऊर्जा निर्मिती व वाहतुकीसाठी वापरली जातात.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"समुद्री शैवाल आणि आयोडीन हे कोणत्या प्रकारच्या सागरी संपत्तीचे उदाहरण आहे?\",\"options\":[\"खनिजे\",\"जलीय वनस्पती\",\"उपयोगी पदार्थ\",\"जीवसंपदा\"],\"answer\":1,\"explain\":\"तक्त्यानुसार समुद्री शैवाल आणि आयोडीन यांचा समावेश जलीय वनस्पतींमध्ये होतो.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"दैनंदिन जीवनात खाद्यपदार्थांमध्ये वापरले जाणारे \'मीठ\' हे कोणत्या प्रकारची सागरी संपत्ती आहे?\",\"options\":[\"जलीय वनस्पती\",\"उपयोगी पदार्थ\",\"खनिजे\",\"इंधन\"],\"answer\":1,\"explain\":\"मीठ आणि इतर क्षार हे \'उपयोगी पदार्थ\' या गटात मोडतात.\",\"topic\":\"सागरी संपत्ती\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"सूर्यापासून मिळणाऱ्या ऊर्जेला काय म्हणतात?\",\"options\":[\"पवनऊर्जा\",\"सौरऊर्जा\",\"विद्युत ऊर्जा\",\"अणू ऊर्जा\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की सूर्यापासून मिळणाऱ्या ऊर्जेला \'सौरऊर्जा\' म्हणतात.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"सूर्यप्रकाशामुळे मानवी शरीराला कोणते जीवनसत्त्व मिळते?\",\"options\":[\"\'अ\' जीवनसत्त्व\",\"\'ब\' जीवनसत्त्व\",\"\'क\' जीवनसत्त्व\",\"\'ड\' जीवनसत्त्व\"],\"answer\":3,\"explain\":\"सूर्यप्रकाशामुळे शरीराला ऊब आणि \'ड\' जीवनसत्त्व मिळते असे पाठात दिले आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"सौरऊर्जेबाबत खालीलपैकी कोणते विधान बरोबर आहे?\",\"options\":[\"सौरऊर्जा महागडी आहे\",\"सौरऊर्जा लवकर संपणारी आहे\",\"सौरऊर्जा पर्यावरणपूरक आणि मोफत आहे\",\"सौरऊर्जा फक्त रात्री वापरता येते\"],\"answer\":2,\"explain\":\"सौरऊर्जा पर्यावरणपूरक, मोफत आणि न संपणारी आहे असे मजकुरात सांगितले आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"एका शेतकऱ्याला त्याच्या शेतातील पंप चालवण्यासाठी सूर्यप्रकाशाचा वापर करायचा आहे, तर त्याने खालीलपैकी कशाचा वापर करावा?\",\"options\":[\"पवनचक्की\",\"सोलर पॅनल\",\"डिझेल इंजिन\",\"विद्युत जनरेटर\"],\"answer\":1,\"explain\":\"सूर्यप्रकाशाच्या मदतीने वीज तयार करणाऱ्या फळ्यांसारख्या तक्त्यांना \'सोलर पॅनल\' म्हणतात, ज्याचा वापर शेतीचे पंप चालवण्यासाठी होतो.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"पवनचक्कीच्या मदतीने वीज तयार करण्यासाठी कशाची आवश्यकता असते?\",\"options\":[\"पाण्याचा प्रवाह\",\"कोळसा\",\"वारा\",\"खनिज तेल\"],\"answer\":2,\"explain\":\"वाऱ्यामुळे पवनचक्की फिरते आणि त्या मदतीने वीज तयार केली जाते.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"महाराष्ट्रातील एक मोठा पवन ऊर्जा प्रकल्प सातारा जिल्ह्यात कोठे आहे?\",\"options\":[\"महाबळेश्वर\",\"चाळकेवाडी\",\"कोयना\",\"कराड\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे महाराष्ट्रातील मोठा पवन ऊर्जा प्रकल्प सातारा जिल्ह्यात चाळकेवाडी येथे आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मीठागरात मीठ मिळवण्यासाठी सूर्याच्या कोणत्या गुणधर्माचा वापर फार पूर्वीपासून होत आहे?\",\"options\":[\"सूर्याचा प्रकाश\",\"सूर्याची उष्णता\",\"सूर्याचे आकर्षण\",\"सूर्याचा रंग\"],\"answer\":1,\"explain\":\"मीठागरात मीठ मिळवण्यासाठी सूर्याच्या उष्णतेचा वापर फार पूर्वीपासून होत आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"सौरऊर्जेला \'न संपणारी\' ऊर्जा का म्हटले असावे?\",\"options\":[\"कारण ती मानवाने तयार केली आहे\",\"कारण ती फक्त भारतात मिळते\",\"कारण सूर्यप्रकाश ही निसर्गाची अक्षय देणगी आहे\",\"कारण ती साठवून ठेवता येत नाही\"],\"answer\":2,\"explain\":\"सूर्यप्रकाश ही निसर्गाने दिलेली देणगी असून ती नैसर्गिकरीत्या सतत उपलब्ध असते, म्हणून ती न संपणारी आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"ज्या देशात सूर्यप्रकाश दुर्मिळ असतो, तेथील लोक सूर्यप्रकाश असलेल्या दिवसाला काय म्हणतात?\",\"options\":[\"हॉट डे\",\"ब्राइट डे\",\"सनी डे\",\"गोल्डन डे\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे अशा दिवसाला तेथील लोक \'सनी डे\' म्हणतात.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात दाखवलेल्या प्रकल्पाचा मुख्य उद्देश काय आहे?\",\"options\":[\"पाणी उपसणे\",\"वीज तयार करणे\",\"धान्य दळणे\",\"हवा शुद्ध करणे\"],\"answer\":1,\"explain\":\"चित्रात पवनचक्क्या दिसत आहेत, ज्यांचा उपयोग पवन ऊर्जा प्रकल्पात वीज तयार करण्यासाठी केला जातो.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"37\\/131_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील पवन ऊर्जा प्रकल्प महाराष्ट्रातील कोणत्या जिल्ह्यात स्थित आहे?\",\"options\":[\"पुणे\",\"नाशिक\",\"सातारा\",\"नागपूर\"],\"answer\":2,\"explain\":\"चित्राखालील ओळीत स्पष्ट दिले आहे की हा प्रकल्प सातारा जिल्ह्यात आहे.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"remember\",\"figure_image\":\"37\\/131_102.jpg\"},{\"q\":\"जर एखाद्या घराच्या छतावर सोलर पॅनल बसवले असतील, तर त्या घराला खालीलपैकी कोणता फायदा होईल?\",\"options\":[\"घराला जास्त वारा मिळेल\",\"घर पावसापासून वाचेल\",\"घरच्या वापरासाठी मोफत वीज मिळेल\",\"घराचे तापमान खूप कमी होईल\"],\"answer\":2,\"explain\":\"सोलर पॅनल सूर्यप्रकाशाच्या मदतीने वीज तयार करतात, जी मोफत आणि पर्यावरणपूरक असते.\",\"topic\":\"सौरऊर्जा आणि पवनऊर्जा\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"भारतात जंगल वाचवण्यासाठी \'चिपको आंदोलन\' कोणत्या वर्षी झाले?\",\"options\":[\"१९४७\",\"१९७३\",\"१९९०\",\"२०००\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, भारतात जंगल वाचवण्यासाठी १९७३ मध्ये चिपको आंदोलन झाले.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"आयुर्वेदाचे जनक कोणाला मानले जाते?\",\"options\":[\"सुंदरलाल बहुगुणा\",\"गौरादेवी\",\"चरक ऋषी\",\"आर्यभट्ट\"],\"answer\":2,\"explain\":\"चरक ऋषींनी आयुर्वेदाचा सखोल अभ्यास केला, म्हणून त्यांना आयुर्वेदाचे जनक म्हणतात.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चिपको आंदोलनाला मुख्यत्वे कोणी दिशा दिली?\",\"options\":[\"गौरादेवी\",\"सुंदरलाल बहुगुणा\",\"चरक ऋषी\",\"स्थानिक महिला\"],\"answer\":1,\"explain\":\"सुंदरलाल बहुगुणा यांनी चिपको आंदोलनाला दिशा दिली.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"चरक ऋषींनी लिहिलेल्या ग्रंथाचे नाव काय आहे?\",\"options\":[\"आयुर्वेद संहिता\",\"वनस्पती शास्त्र\",\"चरकसंहिता\",\"निसर्ग संपदा\"],\"answer\":2,\"explain\":\"चरक ऋषींनी औषधी वनस्पतींच्या गुणधर्मांची माहिती देणारा \'चरकसंहिता\' हा ग्रंथ लिहिला.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जंगलतोडीला विरोध करण्यासाठी गौरादेवी आणि इतर महिलांनी कोणती कृती केली?\",\"options\":[\"झाडे लावली\",\"झाडांना मिठ्या मारल्या\",\"झाडे कापली\",\"आंदोलन थांबवले\"],\"answer\":1,\"explain\":\"झाडांना वाचवण्यासाठी महिलांनी झाडांना मिठ्या मारल्या, म्हणून याला चिपको आंदोलन म्हणतात.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"वनस्पतींपासून औषधी अर्क तयार करण्यासाठी झाडांच्या कोणत्या भागांचा उपयोग होतो?\",\"options\":[\"केवळ फुले\",\"केवळ मुळे\",\"केवळ पाने\",\"पाने, फुले, मुळे आणि फांद्या\"],\"answer\":3,\"explain\":\"झाडांची पाने, फुले, मुळे आणि फांद्या या सर्वांपासून औषधी अर्क तयार केले जातात.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला घरासाठी फर्निचर बनवायचे असेल, तर तुम्ही जंगलातील कोणत्या उत्पादनाचा वापर कराल?\",\"options\":[\"डिंक\",\"लाकूड\",\"शिकेकाई\",\"हिरडा\"],\"answer\":1,\"explain\":\"फर्निचर तयार करण्यासाठी लाकूड उपयोगी पडते असे पाठात नमूद आहे.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या वनस्पतीचा वापर औषध म्हणून केला जातो?\",\"options\":[\"साग\",\"अश्वगंधा\",\"बांबू\",\"नारळ\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या यादीनुसार अश्वगंधा ही एक औषधी वनस्पती आहे.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"चरक ऋषींनी सुमारे किती वर्षांपूर्वी आयुर्वेदाचा अभ्यास केला?\",\"options\":[\"५०० वर्षांपूर्वी\",\"१००० वर्षांपूर्वी\",\"२५०० वर्षांपूर्वी\",\"५००० वर्षांपूर्वी\"],\"answer\":2,\"explain\":\"पाठात नमूद केल्याप्रमाणे चरक ऋषी सुमारे २५०० वर्षांपूर्वी होऊन गेले.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"चिपको आंदोलनाचे नाव \'चिपको\' पडण्याचे मुख्य कारण काय असावे?\",\"options\":[\"लोक झाडांना चिकटून बसले होते\",\"झाडांना डिंक लावला होता\",\"झाडे एकमेकांना चिकटून होती\",\"लोक झाडांना मिठ्या मारून संरक्षण करत होते\"],\"answer\":3,\"explain\":\"कार्यकर्त्यांनी झाडांना मिठ्या मारून \'आधी आम्हाला तोडा\' असे म्हटल्यामुळे याला चिपको आंदोलन म्हणतात.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"आयुर्वेद या उपचार पद्धतीमध्ये प्रामुख्याने कशाचा वापर केला जातो?\",\"options\":[\"केवळ प्राण्यांचे अवयव\",\"केवळ रसायने\",\"वनस्पतींपासून बनवलेली औषधे\",\"केवळ व्यायाम\"],\"answer\":2,\"explain\":\"आयुर्वेदामध्ये वनस्पतींपासून बनवलेल्या औषधांनी उपचार करण्यावर भर दिला जातो.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते गट जंगलापासून मिळणाऱ्या उत्पादनांचा आहे?\",\"options\":[\"डिंक, लोखंड, सोने\",\"हिरडा, बेहडा, शिकेकाई\",\"काच, प्लास्टिक, लाकूड\",\"कागद, पेट्रोल, डिझेल\"],\"answer\":1,\"explain\":\"हिरडा, बेहडा आणि शिकेकाई ही जंगलापासून मिळणारी उत्पादने आहेत.\",\"topic\":\"वनसंपत्ती आणि आयुर्वेद\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"जीवाश्म इंधनांचे मुख्य तीन प्रकार कोणते आहेत?\",\"options\":[\"दगडी कोळसा, कच्चे तेल आणि नैसर्गिक वायू\",\"सौर ऊर्जा, पवन ऊर्जा आणि जल ऊर्जा\",\"लाकूड, शेण आणि बायोगॅस\",\"लोखंड, तांबे आणि सोने\"],\"answer\":0,\"explain\":\"पाठात नमूद केल्याप्रमाणे दगडी कोळसा, कच्चे तेल आणि नैसर्गिक वायू हे जीवाश्म इंधनाचे तीन मुख्य प्रकार आहेत.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"नैसर्गिक वायूमध्ये प्रामुख्याने कोणत्या वायूचे मिश्रण असते?\",\"options\":[\"ऑक्सिजन\",\"नायट्रोजन\",\"मिथेन\",\"हायड्रोजन\"],\"answer\":2,\"explain\":\"नैसर्गिक वायू म्हणजे मिथेन व इतर वायूंचे मिश्रण असते.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मृत सजीवांच्या अवशेषांपासून तयार झालेल्या इंधनांना काय म्हणतात?\",\"options\":[\"कृत्रिम इंधन\",\"जीवाश्म इंधन\",\"विद्युत इंधन\",\"सौर इंधन\"],\"answer\":1,\"explain\":\"सजीवांच्या अवशेषांपासून (जीवाश्मांपासून) तयार झाल्यामुळे त्यांना जीवाश्म इंधन म्हणतात.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दगडी कोळसा कशाच्या अवशेषांपासून तयार झाला आहे?\",\"options\":[\"प्राचीन प्राण्यांच्या\",\"समुद्री माशांच्या\",\"प्राचीन वनस्पतींच्या\",\"सूक्ष्मजीवांच्या\"],\"answer\":2,\"explain\":\"पाठातील माहितीनुसार, कोळसा प्राचीन वनस्पतींच्या अवशेषांपासून तयार झाला आहे.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"वाहनांच्या इंजिनांत जळणाऱ्या इंधनामुळे हवेवर काय परिणाम होतो?\",\"options\":[\"हवा शुद्ध होते\",\"हवेत घातक पदार्थ मिसळतात\",\"हवेतील ऑक्सिजन वाढतो\",\"हवेतील ओलावा कमी होतो\"],\"answer\":1,\"explain\":\"इंधनाच्या ज्वलनामुळे घातक वायू तयार होऊन ते हवेत मिसळतात आणि प्रदूषण होते.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"जीवाश्म इंधनांचा वापर विचारपूर्वक का केला पाहिजे?\",\"options\":[\"कारण ते स्वस्त आहेत\",\"कारण त्यांचे साठे कधीतरी संपणार आहेत\",\"कारण ते सहज उपलब्ध होतात\",\"कारण ते धूर सोडत नाहीत\"],\"answer\":1,\"explain\":\"जीवाश्म इंधनाचे साठे मर्यादित असून ते कधीतरी संपणार आहेत, म्हणून त्यांचा वापर विचारपूर्वक केला पाहिजे.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"हवेतील घातक वायूंचे प्रमाण दाखवणारे फलक कोणत्या महानगरात लावले आहेत?\",\"options\":[\"नाशिक\",\"कोल्हापूर\",\"नागपूर\",\"सोलापूर\"],\"answer\":2,\"explain\":\"मुंबई, पुणे आणि नागपूर यांसारख्या महानगरांमध्ये हवेतील वायूंचे प्रमाण दाखवणारे फलक लावले आहेत.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जमिनीत खोलवर गाडलेल्या अवशेषांचे रूपांतर इंधनात होण्यासाठी कोणत्या गोष्टी कारणीभूत ठरतात?\",\"options\":[\"थंडी आणि पाऊस\",\"प्रचंड उष्णता आणि दाब\",\"हवा आणि प्रकाश\",\"पाणी आणि माती\"],\"answer\":1,\"explain\":\"जमिनीखालील प्रचंड उष्णता आणि दाब यांमुळे लाखो वर्षांत अवशेषांचे रूपांतर इंधनात होते.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता पदार्थ कच्च्या तेलापासून (Crude oil) मिळवला जात नाही?\",\"options\":[\"पेट्रोल\",\"डिझेल\",\"केरोसिन\",\"लाकडी कोळसा\"],\"answer\":3,\"explain\":\"पेट्रोल, डिझेल आणि केरोसिन तेलापासून मिळतात, पण लाकडी कोळसा हा वनस्पतींपासून मिळतो.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"जीवाश्म इंधने तयार होण्यासाठी साधारणपणे किती कालावधी लागतो?\",\"options\":[\"काही वर्षे\",\"काही महिने\",\"लाखो वर्षे\",\"काही दिवस\"],\"answer\":2,\"explain\":\"जमिनीखाली जीवाश्म इंधने तयार होण्यासाठी लाखो वर्षे लागतात.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत समुद्रातून काय मिळवणारी तेलविहीर दाखवली आहे?\",\"options\":[\"फक्त पिण्याचे पाणी\",\"तेल आणि वायू\",\"मासे आणि शेवाळ\",\"मीठ आणि वाळू\"],\"answer\":1,\"explain\":\"आकृतीच्या शीर्षकावरून स्पष्ट होते की ती समुद्रातून तेल आणि वायू मिळवणारी तेलविहीर आहे.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"37\\/133_101.jpg\"},{\"q\":\"दिलेल्या आकृतीवरून, तेल आणि वायू मिळवण्यासाठी तेलविहीर कोठे उभारली जाते?\",\"options\":[\"डोंगराच्या शिखरावर\",\"नदीच्या पात्रात\",\"समुद्रात तळाखालील साठे काढण्यासाठी\",\"शेताच्या मध्यभागी\"],\"answer\":2,\"explain\":\"आकृतीमध्ये समुद्राच्या तळाखालील तेल आणि वायू काढण्यासाठी समुद्रात तेलविहीर उभारलेली दिसत आहे.\",\"topic\":\"जीवाश्म इंधन\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"37\\/133_101.jpg\"},{\"q\":\"निसर्गाच्या मदतीने पुन्हापुन्हा निर्माण होणाऱ्या संसाधनांना काय म्हणतात?\",\"options\":[\"अनवीकरणीय संसाधने\",\"नवीकरणीय संसाधने\",\"जीवाश्म इंधने\",\"मर्यादित संसाधने\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, निसर्गाच्या मदतीने पुन्हापुन्हा निर्माण होणाऱ्या संसाधनांना \'नवीकरणीय संसाधने\' म्हणतात.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते संसाधन \'शाश्वत\' (कायम टिकून राहणारे) आहे?\",\"options\":[\"पेट्रोल\",\"कोळसा\",\"समुद्राच्या लाटा\",\"नैसर्गिक वायू\"],\"answer\":2,\"explain\":\"सूर्यप्रकाश, वारा आणि समुद्राच्या लाटा कधीही न संपणारी म्हणजेच शाश्वत संसाधने आहेत.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"अनवीकरणीय संसाधने पुन्हा निर्माण होण्यासाठी साधारणपणे किती काळ लागतो?\",\"options\":[\"काही वर्षे\",\"शेकडो वर्षे\",\"हजारो वर्षे\",\"लाखो वर्षे\"],\"answer\":3,\"explain\":\"मजकुरात नमूद केल्यानुसार, अनवीकरणीय संसाधने पुन्हा निर्माण होण्यासाठी लाखो वर्षे लागतात.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"माती आणि पाणी ही कोणत्या प्रकारच्या संसाधनांची उदाहरणे आहेत?\",\"options\":[\"नवीकरणीय\",\"अनवीकरणीय\",\"जीवाश्म इंधन\",\"केवळ कृत्रिम\"],\"answer\":0,\"explain\":\"पाणी आणि माती ही निसर्गाच्या मदतीने पुन्हा निर्माण होणारी नवीकरणीय संसाधने आहेत.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जीवाश्म इंधनांचे मुख्य तीन प्रकार कोणते आहेत?\",\"options\":[\"पाणी, हवा आणि माती\",\"कोळसा, पेट्रोल आणि नैसर्गिक वायू\",\"सूर्यप्रकाश, वारा आणि लाटा\",\"डिंक, औषधे आणि अन्न\"],\"answer\":1,\"explain\":\"मजकुराच्या सारांशानुसार कोळसा, पेट्रोल\\/डिझेल आणि नैसर्गिक वायू हे जीवाश्म इंधनाचे तीन प्रकार आहेत.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"हवेचा वापर करून कोणती ऊर्जा मिळवता येते?\",\"options\":[\"सौरऊर्जा\",\"अणुऊर्जा\",\"पवनऊर्जा\",\"रासायनिक ऊर्जा\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की हवेपासून पवनऊर्जा मिळवता येते.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर एखादे संसाधन मर्यादित स्वरूपात उपलब्ध असेल आणि संपल्यावर लवकर तयार होत नसेल, तर त्याचे वर्गीकरण कशात कराल?\",\"options\":[\"शाश्वत संसाधन\",\"नवीकरणीय संसाधन\",\"अनवीकरणीय संसाधन\",\"अक्षय संसाधन\"],\"answer\":2,\"explain\":\"मर्यादित स्वरूपात उपलब्ध असणाऱ्या संसाधनांना अनवीकरणीय संसाधने म्हणतात.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"औषध निर्मितीसाठी उपयुक्त संसाधने मिळवण्यासाठी खालीलपैकी कोणता स्रोत मजकुरात सांगितला आहे?\",\"options\":[\"केवळ सूर्यप्रकाश\",\"सागर आणि जंगल\",\"केवळ वारा\",\"केवळ खनिजे\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे सागरापासून आणि जंगलातून औषध निर्मितीसाठी उपयुक्त संसाधने मिळतात.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"एका कारखान्याला इंधन म्हणून कोळसा वापरायचा आहे, तर तो कोणत्या गटातील संसाधन वापरत आहे?\",\"options\":[\"शाश्वत\",\"नवीकरणीय\",\"अनवीकरणीय\",\"अमर्यादित\"],\"answer\":2,\"explain\":\"कोळसा हे अनवीकरणीय संसाधन आहे कारण ते पुन्हा निर्माण व्हायला लाखो वर्षे लागतात.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता गट पूर्णपणे \'शाश्वत संसाधनांचा\' आहे?\",\"options\":[\"सूर्यप्रकाश, वारा, समुद्राच्या लाटा\",\"पेट्रोल, डिझेल, नैसर्गिक वायू\",\"माती, पाणी, कोळसा\",\"जंगल, औषधे, डिंक\"],\"answer\":0,\"explain\":\"सूर्यप्रकाश, वारा आणि लाटा कधीही न संपणारी (शाश्वत) संसाधने आहेत.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"पाणी आणि पेट्रोल यांच्या उपलब्धतेतील मुख्य फरक कोणता?\",\"options\":[\"पाणी अनवीकरणीय आहे, पेट्रोल शाश्वत आहे\",\"पाणी नवीकरणीय आहे, पेट्रोल अनवीकरणीय आहे\",\"दोन्ही शाश्वत संसाधने आहेत\",\"दोन्ही अनवीकरणीय संसाधने आहेत\"],\"answer\":1,\"explain\":\"पाणी पुन्हा निर्माण होते (नवीकरणीय), तर पेट्रोल मर्यादित असून तयार व्हायला लाखो वर्षे लागतात (अनवीकरणीय).\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"जंगलापासून मिळणाऱ्या उत्पादनांमध्ये खालीलपैकी कशाचा समावेश होतो?\",\"options\":[\"नैसर्गिक वायू आणि पेट्रोल\",\"अन्न, औषधे आणि डिंक\",\"सौरऊर्जा आणि पवनऊर्जा\",\"खनिजे आणि समुद्राच्या लाटा\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे जंगल हे अन्न, औषधे, डिंक आणि इतर उपयोगी वस्तूंचा स्रोत आहे.\",\"topic\":\"संसाधनांचे प्रकार व सारांश\",\"part\":10,\"bloom\":\"understand\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21882,40,6,'History & Civics','mr','इतिहासाची साधने','[\"इतिहासाची साधने म्हणजे इतिहास जाणून घेण्यासाठी वापरले जाणारे स्रोत.\",\"प्राथमिक साधने: भौतिक (नाणी, शिलालेख, इ.) आणि लिखित (शिलालेख, ताम्रपट, ग्रंथ).\",\"दुय्यम साधने: इतिहासविषयक पुस्तके, संशोधनपर निबंध, तज्ज्ञांची व्याख्याने.\",\"मौखिक साधने: लोककथा, दंतकथा, ओव्या, म्हणी, लोकगीते, पोवाडे.\",\"भौतिक साधने म्हणजे डोळ्यांनी पाहता येणाऱ्या वस्तू – इमारती, किल्ले, मंदिरे, नाणी, शस्त्रे.\",\"लिखित साधने म्हणजे लेखी स्वरूपात उपलब्ध असलेल्या नोंदी – शिलालेख, ताम्रपट, ग्रंथ, हस्तलिखिते.\",\"मौखिक साधने तोंडी स्वरूपात पिढ्यान् पिढ्या जतन केलेली माहिती – बौद्ध तिपिटके, जैन आगम, लोककथा.\",\"प्रागैतिहासिक काळात लेखन नव्हते, इतिहास भौतिक साधनांद्वारे समजला जातो.\",\"लिपींचा उगम झाल्यावर इतिहासाला \'ऐतिहासिक काळ\' म्हटले जाते.\",\"वेद हे प्राचीन भारतीय लिखित साधनांचे पहिले उदाहरण – यजुर्वेद, सामवेद, अथर्ववेद.\",\"ब्राह्मी लिपी हे प्राचीन भारतातील सर्वात जुने लिपी प्रणाली आहे.\",\"संग्रहालये व वारसास्थळे इतिहासाची भौतिक साधने जतन करतात – छत्रपती शिवाजी वस्तुसंग्रहालय, अजिंठा लेणी, गडगाव इत्यादी.\",\"मौखिक आणि लिखित साधनांमध्ये फरक: लिखित साधने लेखी असतात, मौखिक साधने तोंडी पिढ्यान् पिढ्या जतन होतात.\",\"भौतिक साधनांचे महत्त्व: ते त्या काळातील जीवनशैली, तंत्रज्ञान, अर्थव्यवस्था आणि संस्कृती दर्शवतात.\",\"मौखिक साधनांचे महत्त्व: ते समाजाची स्मृती, परंपरा व तत्त्वज्ञान जतन करतात.\",\"भविष्यातील पिढ्यांना इतिहास सांगण्यासाठी डिजिटल संग्रह, ऑडिओ-व्हिडिओ रेकॉर्डिंग, मोबाइल अॅप्स व ऑनलाइन डेटाबेस उपयुक्त आहेत.\",\"मौखिक व लिखित साधनांचे संयोजन इतिहासकारांना अधिक अचूक चित्र रेखाटण्यास मदत करते.\",\"भौतिक साधने जसे नाणी, शिलालेख, वास्तू इत्यादींची तारीख लिपी व सामग्रीच्या आधारे निश्चित करता येते.\",\"मौखिक साधनांमधील कथा व म्हणींचे विश्लेषण करून त्या काळातील समाजरचना व मूल्ये समजतात.\",\"भौतिक साधनांच्या शोधासाठी पुरातत्त्वीय उत्खनन व शिलालेख विश्लेषण आवश्यक असते.\",\"मौखिक साधनांच्या जतनासाठी लोककला कार्यक्रम व सांस्कृतिक उत्सव महत्त्वाचे आहेत.\",\"सर्व साधनांचे संतुलित वापर इतिहासाच्या सर्वांगीण समजुतीसाठी आवश्यक आहे.\"]','[{\"q\":\"आपल्या देशाचा इतिहास कसा आहे?\",\"options\":[\"अतिशय नवीन\",\"खूप प्राचीन\",\"अपूर्ण\",\"काल्पनिक\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील पहिल्याच ओळीत नमूद केल्याप्रमाणे आपल्या देशाचा इतिहास खूप प्राचीन आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"इतिहास कशाच्या आधारे लिहिला जातो?\",\"options\":[\"कल्पनेच्या आधारे\",\"गोष्टींच्या आधारे\",\"पुराव्याच्या आधारे\",\"अंदाजाच्या आधारे\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की, आपण इतिहासात जे काही शिकतो तो इतिहास पुराव्याच्या आधारे लिहितात.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"ज्या गोष्टींच्या आधारे इतिहासाचे पुरावे मिळतात, त्यांना काय म्हणतात?\",\"options\":[\"इतिहासाची साधने\",\"विज्ञानाचे प्रयोग\",\"कथा संग्रह\",\"नागरिकशास्त्र\"],\"answer\":0,\"explain\":\"ज्या गोष्टींच्या आधारे इतिहासाचे पुरावे मिळतात, त्या गोष्टी इतिहासाची माहिती मिळवण्याचे स्रोत म्हणजेच साधने असतात.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"इयत्ता पाचवीमध्ये तुम्ही कशाची माहिती मिळवली आहे?\",\"options\":[\"नाण्यांची\",\"मानवी प्रगतीची\\/माहितीची\",\"किल्ल्यांची\",\"नकाशांची\"],\"answer\":1,\"explain\":\"उताऱ्यात उल्लेख आहे की, इयत्ता पाचवीमध्ये तुम्हाला मानवी माहिती मिळाली आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"किल्ल्यात फिरताना जमिनीवर सापडलेले नाणे हे कशाचे उदाहरण असू शकते?\",\"options\":[\"खेळण्याचे साधन\",\"इतिहासाचे साधन\",\"सजावटीची वस्तू\",\"भविष्यातील साधन\"],\"answer\":1,\"explain\":\"नाणे हे भूतकाळाची माहिती देणारे इतिहासाचे एक साधन आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"इतिहासाच्या साधनांना \'जादुई किल्ली\' का म्हटले आहे?\",\"options\":[\"कारण ती जादूचे प्रयोग दाखवते\",\"कारण ती जुनी कुलपे उघडते\",\"कारण त्यामुळे हजारो वर्षांपूर्वीच्या लोकांच्या जीवनात डोकावणे शक्य होते\",\"कारण ती सोन्याची असते\"],\"answer\":2,\"explain\":\"इतिहासाच्या साधनांमुळे आपल्याला प्राचीन लोकांच्या जीवनाबद्दल माहिती मिळते, म्हणून त्यांना जादुई किल्ली म्हटले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"इतिहासाच्या अभ्यासातून आपल्याला पूर्वजांच्या कोणत्या गोष्टींची माहिती मिळते?\",\"options\":[\"केवळ त्यांची नावे\",\"केवळ त्यांचे पत्ते\",\"त्यांची संस्कृती, समाज आणि राज्यव्यवस्था\",\"केवळ त्यांच्या आवडीनिवडी\"],\"answer\":2,\"explain\":\"पूर्वजांचे जीवन, संस्कृती, समाज आणि राज्यव्यवस्था यांचा अभ्यास इतिहासाद्वारे केला जातो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"एखाद्या भिंतीवर कोरलेला लेख पाहून आपल्याला कोणता प्रश्न पडू शकतो?\",\"options\":[\"हा लेख कोणत्या रंगाचा आहे?\",\"हा लेख कोणत्या काळातील असेल?\",\"भिंत किती उंच आहे?\",\"भिंत कशापासून बनली आहे?\"],\"answer\":1,\"explain\":\"भिंतीवर कोरलेला लेख पाहून तो कोणत्या काळातील असेल आणि त्याचा अर्थ काय, असे प्रश्न पडतात.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"इतिहासाची माहिती मिळवण्याचे \'स्रोत\' म्हणजे काय?\",\"options\":[\"पाण्याचे साठे\",\"ज्या गोष्टींतून इतिहासाचे पुरावे मिळतात त्या गोष्टी\",\"केवळ जुनी पुस्तके\",\"केवळ नवीन वर्तमानपत्रे\"],\"answer\":1,\"explain\":\"ज्या गोष्टींच्या आधारे इतिहासाचे पुरावे मिळतात, त्या गोष्टी म्हणजे माहितीचे स्रोत होत.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"इतिहास लेखनासाठी पुराव्यांची आवश्यकता का असते?\",\"options\":[\"कारण पुरावे नसले की इतिहास रंजक होतो\",\"कारण पुराव्यांशिवाय इतिहास सत्य मानला जात नाही\",\"कारण पुरावे गोळा करणे हा एक खेळ आहे\",\"कारण पुराव्यामुळे पुस्तकाची पाने वाढतात\"],\"answer\":1,\"explain\":\"इतिहास हा पुराव्याच्या आधारेच लिहिला जातो, ज्यामुळे तो विश्वसनीय ठरतो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"जर तुम्हाला झाडाच्या फांदीत दडलेला जुना कागद सापडला, तर तुम्ही त्याचा अभ्यास कसा कराल?\",\"options\":[\"तो कागद फेकून द्याल\",\"तो इतिहासाचे साधन म्हणून तपासाल\",\"त्यावर नवीन चित्र काढाल\",\"तो कागद जाळून टाकाल\"],\"answer\":1,\"explain\":\"अशा वस्तू भूतकाळाची गोष्ट सांगत असल्यामुळे त्या इतिहासाचे साधन म्हणून अभ्यासल्या जातात.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते विधान इतिहासाच्या साधनांच्या महत्त्वाबद्दल योग्य आहे?\",\"options\":[\"साधनांमुळे केवळ भविष्य कळते\",\"साधनांमुळे भूतकाळातील प्रश्नांची उत्तरे शोधता येतात\",\"साधनांचा इतिहासाशी काहीही संबंध नसतो\",\"साधने केवळ मनोरंजनासाठी असतात\"],\"answer\":1,\"explain\":\"इतिहासाच्या विविध साधनांचा अभ्यास भूतकाळातील प्रश्नांची उत्तरे शोधण्यासाठी केला जातो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"इतिहासाची जुळणी करणे म्हणजे काय जुळवण्यासारखे आहे?\",\"options\":[\"एखादे चित्र रंगवणे\",\"तुकड्यांतुकड्यांचे कोडे जुळवणे\",\"नवीन कथा लिहिणे\",\"मातीची भांडी बनवणे\"],\"answer\":1,\"explain\":\"मजकुरामध्ये इतिहासाची जुळणी म्हणजे तुकड्यांतुकड्यांचे कोडे जुळवण्यासारखे आहे असे म्हटले आहे.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते इतिहासाच्या कोड्याचे छोटे तुकडे मानले जातात?\",\"options\":[\"केवळ नवीन पुस्तके\",\"फक्त आधुनिक चित्रे\",\"नाणी, शिलालेख आणि मातीची भांडी\",\"भविष्यातील कल्पना\"],\"answer\":2,\"explain\":\"भूतकाळातील नाणी, शिलालेख, चित्रे आणि मातीची भांडी हे इतिहासाच्या कोड्याचे छोटे तुकडे असतात.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहासकार जेव्हा इतिहासाचे तुकडे नीट जुळवतात, तेव्हा काय तयार होते?\",\"options\":[\"एक नवीन कोडे\",\"भूतकाळाचे एक सुंदर चित्र\",\"केवळ एक यादी\",\"एक काल्पनिक गोष्ट\"],\"answer\":1,\"explain\":\"जेव्हा इतिहासकार हे तुकडे नीट जुळवतात, तेव्हा आपल्या भूतकाळाचे एक सुंदर चित्र तयार होते.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"संशोधनाच्या स्रोतांच्या आधारे आपण खालीलपैकी काय जाणून घेऊ शकतो?\",\"options\":[\"केवळ भविष्यातील घटना\",\"केवळ हवामानाचा अंदाज\",\"भूतकाळातील घटना, विचार आणि संस्कृती\",\"केवळ आधुनिक तंत्रज्ञान\"],\"answer\":2,\"explain\":\"संशोधनाच्या स्रोतांच्या आधारे आपण भूतकाळातील घटना, विचार, संस्कृती आणि जीवनशैली जाणून घेऊ शकतो.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इतिहासाच्या साधनांची विभागणी किती मुख्य प्रकारांत केली जाते?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"मजकुरानुसार साधनांची विभागणी प्राथमिक, दुय्यम आणि मौखिक अशा तीन प्रकारांत केली जाते.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर एखाद्या संशोधकाला जुन्या काळातील \'लोककथा\' आणि \'लोकसाहित्य\' मिळाले, तर ते कोणत्या प्रकारच्या साधनात येईल?\",\"options\":[\"प्राथमिक साधने\",\"दुय्यम साधने\",\"मौखिक साधने\",\"लिखित साधने\"],\"answer\":2,\"explain\":\"मजकुरात मौखिक साधनांचा उल्लेख असून लोककथा आणि लोकसाहित्य ही मौखिक परंपरेचा भाग असतात.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पूर्वजांनी कोरून ठेवलेले लेख किंवा शिलालेख हे कशाचे उदाहरण आहे?\",\"options\":[\"इतिहासाची साधने\",\"केवळ मनोरंजनाचे साधन\",\"भविष्यातील कागदपत्रे\",\"आधुनिक चित्रे\"],\"answer\":0,\"explain\":\"पूर्वजांनी कोरून ठेवलेले लेख आणि शिलालेख हे इतिहासाच्या साधनांमध्ये मोडतात.\",\"topic\":\"१.१ इतिहासाची जुळणी\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इतिहासाची जुळणी करताना \'नाणी\' आणि \'चित्रे\' यांचे महत्त्व काय आहे?\",\"options\":[\"ती केवळ सजावटीसाठी वापरली जातात\",\"ती इतिहासाचे कोडे पूर्ण करण्यासाठी छोट