:\"अश्मयुग\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"ज्या काळात प्रामुख्याने दगडांची हत्यारे मिळतात, त्या काळाला काय म्हणतात?\",\"options\":[\"ताम्रयुग\",\"लोहयुग\",\"अश्मयुग\",\"सुवर्णयुग\"],\"answer\":2,\"explain\":\"ज्या काळात प्रामुख्याने दगडांची हत्यारे मिळतात, त्या काळाला अश्मयुग म्हणतात.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"अश्मयुगीन मानवाने कठीण कवचाची फळे फोडण्यासाठी कशाचा वापर केला असावा?\",\"options\":[\"लोखंडी हातोडा\",\"दगडी तोडहत्यारे\",\"लाकडी दांडा\",\"तांब्याची कुऱ्हाड\"],\"answer\":1,\"explain\":\"कठीण कवचाची फळे किंवा हाडे फोडण्यासाठी मानवाने दगडी तोडहत्यारांचा वापर केला असावा.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दगडाला विशिष्ट आकार देणे हे मानवाच्या कोणत्या विकासाचे लक्षण आहे?\",\"options\":[\"शारीरिक शक्तीचा विकास\",\"बुद्धीचा विकास\",\"धावण्याचा वेग\",\"गायन कला\"],\"answer\":1,\"explain\":\"दगडाला आकार देणे हे हत्यारांच्या बुद्धीच्या विकासाचे लक्षण आहे.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"अश्मयुगाचे एकूण किती कालखंड पाडले जातात?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"तीन\"],\"answer\":3,\"explain\":\"अश्मयुगाचे पुराश्मयुग, मध्याश्मयुग आणि नवाश्मयुग असे तीन कालखंड पाडले जातात.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अश्मयुगाचे कालखंड कशाच्या आधारावर ठरवले जातात?\",\"options\":[\"मानवाच्या कपड्यांवरून\",\"मानवाच्या भाषेवरून\",\"हत्यारांचे आकार आणि प्रकार यांवरून\",\"राहण्याच्या ठिकाणावरून\"],\"answer\":2,\"explain\":\"हत्यारांचे आकार आणि प्रकार यांवरून अश्मयुगाचे तीन कालखंड पाडले जातात.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता अश्मयुगाचा कालखंड नाही?\",\"options\":[\"पुराश्मयुग\",\"मध्याश्मयुग\",\"लोहयुग\",\"नवाश्मयुग\"],\"answer\":2,\"explain\":\"पुराश्मयुग, मध्याश्मयुग आणि नवाश्मयुग हे अश्मयुगाचे भाग आहेत, लोहयुग नाही.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मानवाने दगडी गोळे तासून कोणती हत्यारे तयार केली असावीत?\",\"options\":[\"तोडहत्यारे\",\"तलवारी\",\"बाण\",\"विळे\"],\"answer\":0,\"explain\":\"मानवाने दगडी गोळे तासून तोडहत्यारे तयार केली असावीत असे पाठात नमूद आहे.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एखाद्या प्राण्याचे हाड फोडून त्यातील आतील भाग खाण्यासाठी अश्मयुगीन मानव काय करत असे?\",\"options\":[\"हाड तसेच गिळत असे\",\"दगडी हत्याराचा वापर करत असे\",\"हाड आगीत जाळत असे\",\"हाड पाण्यात भिजवत असे\"],\"answer\":1,\"explain\":\"हाडे फोडण्यासाठी मानव दगडी तोडहत्यारांचा वापर करत असे.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अश्मयुगाच्या कालखंडांचा योग्य क्रम कोणता?\",\"options\":[\"नवाश्मयुग -> मध्याश्मयुग -> पुराश्मयुग\",\"पुराश्मयुग -> नवाश्मयुग -> मध्याश्मयुग\",\"पुराश्मयुग -> मध्याश्मयुग -> नवाश्मयुग\",\"मध्याश्मयुग -> पुराश्मयुग -> नवाश्मयुग\"],\"answer\":2,\"explain\":\"काळाच्या ओघात पुराश्मयुग, त्यानंतर मध्याश्मयुग आणि शेवटी नवाश्मयुग असा क्रम येतो.\",\"topic\":\"अश्मयुग\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"पुराश्मयुगातील मानवाचे निवासस्थान कोठे होते?\",\"options\":[\"पक्क्या घरांमध्ये\",\"गुहांमध्ये किंवा झाडांच्या फांद्यांवर\",\"तंबूंमध्ये\",\"किल्ल्यांमध्ये\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, पुराश्मयुगातील मानव गुहांमध्ये किंवा मोठ्या झाडांच्या फांद्यांवर राहत असे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पुराश्मयुगातील सुरुवातीची हत्यारे कशी होती?\",\"options\":[\"गुळगुळीत आणि चकचकीत\",\"लोखंडी आणि धारदार\",\"ओबडधोबड\",\"प्लास्टिकची\"],\"answer\":2,\"explain\":\"पुराश्मयुगातील सुरुवातीची हत्यारे ओबडधोबड होती असे पाठात नमूद केले आहे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मानवाच्या जीवनशैलीत मोठा बदल घडवून आणणारा कोणता शोध पुराश्मयुगात लागला?\",\"options\":[\"चाकाचा शोध\",\"अग्नीचा शोध\",\"विमानाचा शोध\",\"संगणकाचा शोध\"],\"answer\":1,\"explain\":\"अग्नीचा शोध हा मानवाच्या जीवनशैलीत बदल घडवणारा महत्त्वाचा शोध याच काळात लागला.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"अन्न शिजवून खाल्ल्यामुळे मानवाला कोणता फायदा झाला?\",\"options\":[\"अन्न पचायला सोपे झाले\",\"अन्न जास्त काळ टिकू लागले\",\"अन्नाची चव कमी झाली\",\"अन्न कडक झाले\"],\"answer\":0,\"explain\":\"अन्न शिजवल्यामुळे ते पचायला सोपे झाले, असे पाठात म्हटले आहे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"नाशिकजवळ पुराश्मयुगीन हत्यारे मिळणारे प्रसिद्ध स्थळ कोणते?\",\"options\":[\"नेवासा\",\"चिरकी\",\"गंगापूर\",\"पैठण\"],\"answer\":2,\"explain\":\"नाशिकजवळचे गंगापूर हे महाराष्ट्रातील एक प्रसिद्ध पुराश्मयुगीन स्थळ आहे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पुराश्मयुगीन मानवाच्या हत्यारांचे अवशेष प्रामुख्याने कोठे सापडतात?\",\"options\":[\"डोंगराच्या शिखरावर\",\"नदीच्या किंवा ओढ्याच्या काठावर\",\"वाळवंटात\",\"समुद्राच्या तळाशी\"],\"answer\":1,\"explain\":\"पुराश्मयुगीन हत्यारे नदीच्या किंवा ओढ्याच्या काठावर मिळतात.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर पुराश्मयुगीन मानवाला जमिनीत गाडलेली मुळे खणून काढायची असतील, तर तो कशाचा वापर करत असे?\",\"options\":[\"लोखंडी फावडे\",\"ओबडधोबड दगडी हत्यारे\",\"ट्रॅक्टर\",\"काचेचे तुकडे\"],\"answer\":1,\"explain\":\"खणणे या कामासाठी मानव ओबडधोबड दगडी हत्यारांचा वापर करत असे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"चिरकी-नेवासा हे प्रसिद्ध पुराश्मयुगीन स्थळ कोणत्या ठिकाणाजवळ आहे?\",\"options\":[\"नाशिक\",\"नेवासा\",\"पुणे\",\"मुंबई\"],\"answer\":1,\"explain\":\"पाठात दिलेल्या माहितीनुसार, चिरकी-नेवासा हे नेवाशाजवळ आहे.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"पुराश्मयुगातील मानवाच्या अन्नाबाबत खालीलपैकी कोणते विधान योग्य आहे?\",\"options\":[\"तो शेती करून धान्य पिकवत असे\",\"तो पूर्णपणे निसर्गावर अवलंबून होता\",\"तो हॉटेलमधून अन्न विकत घेत असे\",\"तो फक्त दूध पित असे\"],\"answer\":1,\"explain\":\"पुराश्मयुगातील मानव पूर्णपणे निसर्गावर अवलंबून होता.\",\"topic\":\"पुराश्मयुग\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"अग्नीच्या शोधामुळे मानवाच्या कोणत्या कृतीत बदल झाला असावा, असे पाठावरून सुचवले आहे?\",\"options\":[\"कपडे शिवण्याच्या पद्धतीत\",\"अन्न ग्