",\"options\":[\"जनावरांच्या भीतीमुळे\",\"पावसामुळे\",\"पेरणीपासून कापणीपर्यंतच्या कामामुळे\",\"फळे गोळा करण्यासाठी\"],\"answer\":2,\"explain\":\"पेरणी करण्यापासून ते कापणी करण्यापर्यंत मानवाला एका ठिकाणी राहून भाग होते, त्यामुळे तो स्थिरावला.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"नवाश्मयुगात मानवाच्या स्थिर जीवनातून कशाचा उदय झाला?\",\"options\":[\"मोठ्या शहरांचा\",\"गाव-वसाहतींचा\",\"किल्ल्यांचा\",\"कारखान्यांचा\"],\"answer\":1,\"explain\":\"एका ठिकाणी राहिल्यामुळे हळूहळू गाव-वसाहतींचा उदय झाला.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"नवाश्मयुगातील सर्वात महत्त्वाची घडामोड कोणती मानली जाते?\",\"options\":[\"दगडी हत्यारे बनवणे\",\"आगीचा वापर\",\"शेतीचा शोध\",\"गुहेत राहणे\"],\"answer\":2,\"explain\":\"शेतीचा शोध ही नवाश्मयुगातील अत्यंत महत्त्वाची घडामोड आहे.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शेतीची सुरुवात करण्याचे श्रेय कोणाला दिले जाते?\",\"options\":[\"पुरुषांना\",\"मुलांना\",\"स्त्रियांना\",\"वृद्धांना\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार शेतीची सुरुवात करण्याचे श्रेय स्त्रियांना दिले जाते.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"नवाश्मयुगात मानवाने अन्नधान्याशिवाय आणखी कशाचे उत्पादन करण्याची कला आत्मसात केली होती?\",\"options\":[\"दूध\",\"मध\",\"कापड\",\"मीठ\"],\"answer\":0,\"explain\":\"या काळात अन्नधान्य आणि दूध यांचे उत्पादन करण्याची कला मानवाने आत्मसात केली होती.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"पेरणी करण्यासाठी वापरल्या जाणाऱ्या टोकदार काठीला वजन (छिद्र असलेला दगड) का बसवले जात असे?\",\"options\":[\"काठी सुंदर दिसण्यासाठी\",\"जमिनीत खोलवर खणता यावे म्हणून\",\"काठी हातातून निसटू नये म्हणून\",\"काठीचा आकार बदलण्यासाठी\"],\"answer\":1,\"explain\":\"काठीला वजन बसवल्यामुळे जमिनीत खोलवर खणणे सोपे जात असे.\",\"topic\":\"नवाश्मयुग\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या मानवाला नवाश्मयुगात धान्य पेरणी करायची असेल, तर त्याने ती कधी करणे अपेक्षित होते?\",\"options\":[\"केवळ र