oom\":\"remember\"},{\"q\":\"मनात हाव बाळगून मालमत्तेचा साठा न करणे, म्हणजे काय?\",\"options\":[\"अस्तेय\",\"अपरिग्रह\",\"ब्रह्मचर्य\",\"अहिंसा\"],\"answer\":1,\"explain\":\"मालमत्तेचा साठा न करणे म्हणजे \'अपरिग्रह\' होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"तीर्थंकरांच्या उपदेशातील सत्य जाणून घेऊन त्यावर श्रद्धा ठेवणे, याला काय म्हणतात?\",\"options\":[\"सम्यक ज्ञान\",\"सम्यक दर्शन\",\"सम्यक चारित्र\",\"सम्यक वाणी\"],\"answer\":1,\"explain\":\"तीर्थंकरांच्या उपदेशावर श्रद्धा ठेवणे म्हणजे \'सम्यक दर्शन\' होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'अस्तेय\' या व्रताचे पालन करण्यासाठी काय करणे आवश्यक आहे?\",\"options\":[\"चोरी न करणे\",\"नेहमी खरे बोलणे\",\"हिंसा न करणे\",\"साठा न करणे\"],\"answer\":0,\"explain\":\"चोरी न करणे म्हणजे \'अस्तेय\' होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखादी व्यक्ती दुसऱ्याची वस्तू त्याच्या संमतीशिवाय घेत नसेल, तर ती कोणत्या व्रताचे पालन करत आहे?\",\"options\":[\"अहिंसा\",\"सत्य\",\"अस्तेय\",\"ब्रह्मचर्य\"],\"answer\":2,\"explain\":\"दुसऱ्याची गोष्ट संमतीशिवाय न घेणे म्हणजेच अस्तेय (चोरी न करणे) होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"शरीराला सुखकारक वाटणाऱ्या गोष्टींचा त्याग करून व्रतांचे पालन करणे, हे कोणत्या व्रतात येते?\",\"options\":[\"अपरिग्रह\",\"ब्रह्मचर्य\",\"सत्य\",\"अहिंसा\"],\"answer\":1,\"explain\":\"सुखकारक गोष्टींचा त्याग करून व्रत पाळणे म्हणजे ब्रह्मचर्य होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'सम्यक चारित्र\' या तत्त्वाचा संबंध खालीलपैकी कशाशी आहे?\",\"options\":[\"केवळ श्रद्धा ठेवणे\",\"तत्त्वज्ञानाचा अभ्यास करणे\",\"पंचमहाव्रतांचे काटेकोर आचरण करणे\",\"मालमत्ता जमा करणे\"],\"answer\":2,\"explain\":\"पंचमहाव्रतांचे काटेकोर आचरण करणे म्हणजे \'सम्यक चारित्र\' होय.\",\"topic\":\"पंचमहाव्रते आणि त्रिरत्ने\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"\'सम्यक ज्ञान\' प्राप्त 