rstand\"},{\"q\":\"यदि दो मित्रों के बीच झगड़ा हो जाता है, तो शब्दों ने यहाँ कौन-सा कार्य किया है?\",\"options\":[\"मनुष्य को ज्ञान से जोड़ना\",\"मनुष्य को मनुष्य से जोड़ना\",\"मनुष्य को मनुष्य से तोड़ना\",\"अक्षरों को अर्थ देना\"],\"answer\":2,\"explain\":\"शब्द ही मनुष्य को मनुष्य से तोड़ते भी हैं।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"निर्जीव अक्षरों को जीवन कौन प्रदान करता है?\",\"options\":[\"विज्ञान\",\"मनुष्य\",\"प्रकृति\",\"ध्वनि\"],\"answer\":1,\"explain\":\"पाठ के अनुसार, मनुष्य ही अक्षरों को अर्थ देता है और उन्हें जीवन बनाता है।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मनुष्य को ज्ञान से कौन जोड़ता है?\",\"options\":[\"मस्तिष्क\",\"शब्द\",\"विज्ञान\",\"संस्कृति\"],\"answer\":1,\"explain\":\"पाठ में स्पष्ट है कि शब्द ही मनुष्य को ज्ञान से जोड़ते हैं।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जब शब्द जीवंत हो जाते हैं, तो उनमें क्या आने लगता है?\",\"options\":[\"केवल ध्वनि\",\"वैज्ञानिक नियम\",\"मनुष्य के विविध स्वभाव और गुण\",\"केवल अक्षरों के चिह्न\"],\"answer\":2,\"explain\":\"जीवंत होने पर शब्दों में मनुष्य के स्वभाव और गुण आने लगते हैं।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दुनिया की सभी ज्ञानशाखाओं का विकास किसके कारण हुआ है?\",\"options\":[\"भाषा\",\"मशीनें\",\"आदिम अवस्था\",\"चित्रकला\"],\"answer\":0,\"explain\":\"पाठ के अनुसार, दुनिया की सभी ज्ञानशाखाओं का विकास भाषा के कारण हुआ है।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"शब्दों के संसार को \'विचित्र\' क्यों कहा गया है?\",\"options\":[\"क्योंकि वे निर्जीव हैं\",\"क्योंकि उनकी ताकत की ओर हमारा ध्यान नहीं जाता\",\"क्योंकि वे केवल ध्वनि हैं\",\"क्योंकि वे केवल विज्ञान से जुड़े हैं\"],\"answer\":1,\"explain\":\"शब्दों की अनदेखी शक्ति के कारण उनके संसार को विचित्र कहा गया है।\",\"topic\":\"भाषा और शब्दों का संसार\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"दी गई आकृति में \'स्वयं अध्ययन\' के अंतर्