],\"answer\":1,\"explain\":\"पाठ के अनुसार, \'चलो\' शब्द का प्रयोग आदेश देने के लिए हुआ है, इसलिए यह आज्ञार्थक वाक्य है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'वाह ! क्या बनावट है ताजमहल की !\' यह किस प्रकार का वाक्य है?\",\"options\":[\"विस्मयार्थक वाक्य\",\"इच्छार्थक वाक्य\",\"संकेतार्थक वाक्य\",\"प्रश्नार्थक वाक्य\"],\"answer\":0,\"explain\":\"इसमें \'वाह\' शब्द का प्रयोग विस्मय-आश्चर्य का भाव प्रकट करने के लिए किया गया है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"जब एक क्रिया दूसरी क्रिया पर निर्भर होती है, तो उसे कौन-सा वाक्य कहते हैं?\",\"options\":[\"संभावनार्थक वाक्य\",\"आज्ञार्थक वाक्य\",\"संकेतार्थक वाक्य\",\"विधानार्थक वाक्य\"],\"answer\":2,\"explain\":\"पाठ के अनुसार, एक क्रिया का दूसरी क्रिया पर निर्भर होना संकेतार्थक वाक्य कहलाता है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'कश्मीर का सौंदर्य देखकर तुम्हें आश्चर्य होगा\' वाक्य में \'होगा\' शब्द क्या व्यक्त करता है?\",\"options\":[\"आदेश\",\"इच्छा\",\"संदेह या संभावना\",\"निश्चित सूचना\"],\"answer\":2,\"explain\":\"पाठ के अनुसार, \'होगा\' शब्द संदेह या संभावना व्यक्त करने के लिए प्रयोग किया गया है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"\'खूब पढ़ो खूब बढ़ो\' वाक्य में क्या व्यक्त किया गया है?\",\"options\":[\"आदेश\",\"इच्छा या आशीर्वाद\",\"प्रश्न\",\"निषेध\"],\"answer\":1,\"explain\":\"पाठ के अनुसार, \'खूब पढ़ो खूब बढ़ो\' में इच्छा या आशीर्वाद व्यक्त किया गया है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"\'यदि बिजली आएगी तो रोशनी होगी\' वाक्य में संकेत के लिए किन शब्दों का प्रयोग हुआ है?\",\"options\":[\"बिजली, रोशनी\",\"आएगी, होगी\",\"यदि, तो\",\"रोशनी, आएगी\"],\"answer\":2,\"explain\":\"पाठ के अनुसार, संकेतार्थक वाक्य में \'यदि\' और \'तो\' शब्दों का प्रयोग निर्भरता दिखाने के लिए होता है।\",\"topic\":\"भाषा की ओर\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"यदि \'माला घर नहीं जाएगी\' वाक्य से \'नहीं\' शब्द हटा दिया जाए, तो वह किस प्रकार का वाक्य बन जाएग