s\":[\"शाळेच्या आवारात\",\"नदीच्या काठी\",\"गाडीजवळच\",\"कडब्याच्या ढिगाऱ्यात\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे बायकांनी गाडीजवळच चुली रेखल्या.\",\"topic\":\"ऊसतोडणीसाठी स्थलांतर\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यातील \'मनात काहूर उठणे\' या वाक्प्रचाराचा अर्थ काय असावा?\",\"options\":[\"खूप आनंद होणे\",\"खूप भीती वाटणे\",\"मनात विचारांचे द्वंद्व किंवा अस्वस्थता निर्माण होणे\",\"खूप राग येणे\"],\"answer\":2,\"explain\":\"गाव सोडल्यामुळे आणि परक्या गावात आल्यामुळे त्यांच्या मनात अस्वस्थता निर्माण झाली होती.\",\"topic\":\"ऊसतोडणीसाठी स्थलांतर\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"जेवण झाल्यावर सगळ्यांनी झोपण्यासाठी काय पसरले?\",\"options\":[\"चटई\",\"अंगरखं\",\"कडबा\",\"गोणपाट\"],\"answer\":1,\"explain\":\"पिठलं-भाकरी पोटात ढकलून सगळ्यांनी अंगरखं पसरलं.\",\"topic\":\"ऊसतोडणीसाठी स्थलांतर\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"या उताऱ्यावरून ऊसतोडणी कामगारांच्या जीवनातील कोणत्या गोष्टीवर प्रकाश पडतो?\",\"options\":[\"त्यांचे श्रीमंत जीवन\",\"त्यांचे स्थलांतर आणि कष्टाचे जीवन\",\"त्यांची फिरण्याची आवड\",\"त्यांचे केवळ शिक्षणाकडे असलेले लक्ष\"],\"answer\":1,\"explain\":\"गाव सोडून दुसऱ्या गावी जाणे, तिथे तात्पुरती व्यवस्था करणे आणि कष्ट करणे यावरून त्यांच्या स्थलांतरित जीवनाचे दर्शन घडते.\",\"topic\":\"ऊसतोडणीसाठी स्थलांतर\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"तांबडं फुटताच झटकन कोण उठले?\",\"options\":[\"शंकर\",\"तारा\",\"मीरा\",\"वसंत\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीलाच दिले आहे की तांबडं फुटताच तारा झटकन उठली.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"ताराने चहा कोणत्या पातेल्यात ठेवला होता?\",\"options\":[\"पितळेच्या\",\"स्टीलच्या\",\"जर्मलच्या\",\"तांब्याच्या\"],\"answer\":2,\"explain\":\"उताऱ्यात \'तिने जर्मलच्या पातेल्यात चहा ठेवला\' असा उल्लेख आहे.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शंकरने चहा कोणत्या प्रकारच्या कपातून पिला?\",\"options\":[\"काचेच्या कपातून\",\"मोठ्या मगधून\",\"बिनदांडीच्या कपातून\",\"मातीच्या कपातून\"],\"answer\":2,\"explain\":\"ताराने बिनदांडीच्या कपात शंकरला चहा दिला होता.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दामूने शंकरला काय देऊन गेल्याचे सांगितले?\",\"options\":[\"भाकरी\",\"पिठुडी\",\"कोयता\",\"चहा\"],\"answer\":1,\"explain\":\"दामू म्हणाला, \'आरं माय पिठुडी देऊन गेलाय\'.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सगळ्यांनी आपले सामान कोठे उतरवले?\",\"options\":[\"उसाच्या शेतात\",\"रस्त्याच्या कडेला\",\"नदीच्या काठावर मोकळ्या रानात\",\"गावातील मंदिरात\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद आहे की सगळ्यांनी नदीच्या काठावर मोकळ्या रानात सामान उतरवलं.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शंकरने कामावर जाताना सोबत काय घेतले?\",\"options\":[\"कुदळ\",\"खुरपे\",\"कोयता\",\"काठी\"],\"answer\":2,\"explain\":\"शंकर-ताराने आपला कोयता सोबतीला घेऊन कामाला सुरुवात केली.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"उसाच्या मोळ्या बांधण्याचे काम कोणी केले?\",\"options\":[\"ताराने\",\"मीराने\",\"वसंतने\",\"दामूने\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की \'मीरानं मोकळ्या मोळ्या बांधल्या\'.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"शंकरने \'घटापटा चहा पोटात ढकलला\' यावरून काय समजते?\",\"options\":[\"त्याला चहा खूप आवडला होता\",\"चहा खूप गरम होता\",\"त्याला कामावर जायची घाई होती\",\"तो खूप दिवसांनी चहा पीत होता\"],\"answer\":2,\"explain\":\"दामूने हाक मारल्यामुळे शंकरने घाईघाईत चहा पिला.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"बैलं का जोमली (उत्साहात) होती?\",\"options\":[\"त्यांना विश्रांती मिळाली होती\",\"त्यांना हिरवा चारा मिळाला होता\",\"त्यांना पाणी मिळाले होते\",\"त्यांना नवीन मालक मिळाला होता\"],\"answer\":1,\"explain\":\"हिरवा चारा मिळण्याने बैलं मस्त जोमली होती, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"टोळीने दुपारच्या थळातून लवकर परतायचे का ठरवले होते?\",\"options\":[\"पाऊस येणार होता म्हणून\",\"काम संपले होते म्हणून\",\"उघड्यावर झोपल्यामुळे थंडी वाजत होती म्हणून\",\"जेवण करायचे होते म्हणून\"],\"answer\":2,\"explain\":\"उघड्यावर झोपून थंडीनं अंग काकडून निघतं, म्हणून त्यांनी लवकर परतायचं ठरवलं.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"या उताऱ्यात \'थळ\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"घर\",\"नदीचा काठ\",\"काम करण्याचे ठिकाण (शेती)\",\"बाजार\"],\"answer\":2,\"explain\":\"ऊसतोडणीच्या संदर्भात \'थळ\' म्हणजे ज्या शेतात काम चालते ते ठिकाण.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील वर्णनावरून या लोकांच्या राहणीमानाबद्दल काय सांगता येईल?\",\"options\":[\"ते खूप श्रीमंत आहेत\",\"ते कष्टकरी असून तात्पुरत्या स्वरूपात उघड्यावर राहतात\",\"ते सहलीला आले आहेत\",\"ते पक्क्या घरात राहतात\"],\"answer\":1,\"explain\":\"उघड्यावर झोपणे आणि नदीकाठी सामान उतरवणे यावरून त्यांचे कष्टकरी जीवन दिसून येते.\",\"topic\":\"कामाचा पहिला दिवस\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"मीराला वसंतचे काय सापडले?\",\"options\":[\"कोयता\",\"पुस्तक\",\"भाकरी\",\"पिशवी\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की, \'मीराला वसंतचं पुस्तक गवसलं\'.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"वसंतने कुणाच्या खांद्यावर हात ठेवून शाळेबद्दल विचारले?\",\"options\":[\"ताराच्या\",\"मीराच्या\",\"शंकरच्या\",\"मालकाच्या\"],\"answer\":2,\"explain\":\"वसंतने शंकरच्या (दादाच्या) खांद्यावर हात ठेवून \'मले शाळेत कवा धाडणार?\' असे विचारले.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"ताराने कशाचा उजेड केला?\",\"options\":[\"विजेरीचा\",\"पणतीचा\",\"मेणबत्तीचा\",\"चिमणीचा\"],\"answer\":3,\"explain\":\"उताऱ्यात उल्लेख आहे की, \'तारानेही सामान लावून चिमणीचा उजेड केला\'.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"वसंतला शाळेची आठवण कधी झाली?\",\"options\":[\"जेवताना\",\"मीराचा आरडाओरडा ऐकल्यावर\",\"सकाळी उठल्यावर\",\"कोयता हातात घेतल्यावर\"],\"answer\":1,\"explain\":\"मीरा जेव्हा \'बया तुमचं पुस्तक\' म्हणून ओरडली, तेव्हा वसंतला शाळेची आठवण झाली.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"शंकरच्या मते वसंतने उद्यापासून कोठे जायचे होते?\",\"options\":[\"शाळेत\",\"गावाला\",\"तोडणीला\",\"बाजारात\"],\"answer\":2,\"explain\":\"शंकर म्हणाला, \'उद्यापासनं तोडणीला जावच हाय\'.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वसंतने विचारलेल्या \'मले शाळेत कवा धाडणार?\' या प्रश्नातून त्याची कोणती ओढ दिसून येते?\",\"options\":[\"कामाची ओढ\",\"खेळण्याची ओढ\",\"शिक्षणाची ओढ\",\"फिरण्याची ओढ\"],\"answer\":2,\"explain\":\"वसंतला शाळेत जायचे होते, म्हणजेच त्याच्या मनात शिक्षणाविषयीची ओढ होती.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वसंत उपाशी का झोपला?\",\"options\":[\"त्याला भूक नव्हती म्हणून\",\"जेवण संपले होते म्हणून\",\"शंकरच्या बोलण्यामुळे त्याला वाईट वाटले म्हणून\",\"तो आजारी होता म्हणून\"],\"answer\":2,\"explain\":\"शंकरने शाळेत जाण्यास नकार दिल्याने वसंत दुःखी झाला आणि उपाशी झोपला.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"उसाच्या मोळ्या बांधण्यासाठी शंकरने कशाचा वापर केला?\",\"options\":[\"दोरीचा\",\"कोयत्याचा\",\"तारेचा\",\"काठीचा\"],\"answer\":1,\"explain\":\"उताऱ्यात \'शंकराच्या कोयत्याने उसाच्या मोळ्या बांधून\' असा उल्लेख आहे.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात आलेल्या \'चिमणी\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"एक पक्षी\",\"केरोसीनवर चालणारा छोटा दिवा\",\"खेळण्यातील बाहुली\",\"एक प्रकारचे धान्य\"],\"answer\":1,\"explain\":\"सामानाची लावणी करताना उजेडासाठी वापरलेली \'चिमणी\' म्हणजे रॉकेलवर चालणारा दिवा होय.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"वसंतच्या मनात शिक्षणाची ओढ निर्माण झाली आहे, हे कोणत्या कृतीवरून समजते?\",\"options\":[\"तो उसाच्या मोळ्या बांधत होता\",\"त्याने दादाला शाळेत पाठवण्याबद्दल विचारले\",\"तो उपाशी झोपला\",\"त्याने सामान लावले\"],\"answer\":1,\"explain\":\"शाळेची आठवण होणे आणि वडिलांकडे शाळेत जाण्याचा हट्ट धरणे यावरून त्याची शिक्षणाची ओढ स्पष्ट होते.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वसंत उपाशी झोपल्यामुळे कोणाला फार वाईट वाटले?\",\"options\":[\"शंकरला\",\"ताराला\",\"मीराला\",\"मालकाला\"],\"answer\":2,\"explain\":\"उताऱ्याच्या शेवटी दिले आहे की, \'वसंत उपाशीच झोपला, तर मीराला फार वाईट वाटलं\'.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील \'हबकून जाणे\' या वाक्प्रचाराचा अर्थ काय असू शकतो?\",\"options\":[\"खूप आनंद होणे\",\"दचकणे किंवा घाबरणे\",\"खूप राग येणे\",\"झोप येणे\"],\"answer\":1,\"explain\":\"वसंत अंगावरच्या खुणा पाहून आणि वडिलांचे बोलणे ऐकून दचकला किंवा घाबरला, म्हणून तो हबकून गेला.\",\"topic\":\"वसंतची शिक्षणाची ओढ\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"वसंतला सडकेवर काय सापडले?\",\"options\":[\"कोयता\",\"कागद\",\"पेन\",\"पैसे\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे सडकेवर पडलेल्या कागदावर वसंतची नजर खिळली आणि त्याने तो उचलला.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कागदावर कोणत्या भाषेतील शब्द लिहिले होते?\",\"options\":[\"मराठी\",\"हिंदी\",\"इंग्रजी\",\"संस्कृत\"],\"answer\":3,\"explain\":\"वसंतला कागदावरच्या संस्कृत शब्दांचा उलगडा होत नव्हता, असे उताऱ्यात दिले आहे.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"मीराचे शिक्षण कितवीपर्यंत झाले होते?\",\"options\":[\"दुसरी\",\"पाचवी\",\"आठवी\",\"दहावी\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट उल्लेख आहे की मीराचे शिक्षण आठवीपर्यंत झाले होते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"वसंतला कागदावरील शब्दांचा उलगडा का होत नव्हता?\",\"options\":[\"कागद फाटलेला होता\",\"अक्षर खराब होते\",\"ते संस्कृत शब्द होते\",\"अंधार होता\"],\"answer\":2,\"explain\":\"कागदावर संस्कृत शब्द असल्यामुळे वसंतला त्यांचा अर्थ समजत नव्हता.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"पाटावर मिरचीचे वाटण कोणी वाटले?\",\"options\":[\"ताराने\",\"मीराने\",\"शंकरने\",\"वसंतने\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की मीराने पाटावर मिरचीचे वाटण वाटून आईकडे दिले.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"ताराने वसंतला कागद वाचून का दाखवला नाही?\",\"options\":[\"तिला वाचता येत नव्हते\",\"ती कामात व्यस्त होती\",\"तिला राग आला होता\",\"तिला संस्कृत आवडत नव्हते\"],\"answer\":0,\"explain\":\"तारा म्हणाली, \'मले तरी कुटं वाचता येतंय, माझी साळा तर दुसरीच झालीय\', म्हणजेच तिला वाचता येत नव्हते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"उसाच्या मोळ्या बांधून सडकेला आणून टाकण्याचे काम कोण करत होते?\",\"options\":[\"शंकर आणि तारा\",\"तारा आणि मीरा\",\"मीरा आणि वसंत\",\"शंकर आणि वसंत\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, मीरा आणि वसंत मोळ्या बांधून सडकेला आणून टाकत होते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"वसंतने कागद वाचण्यासाठी मीराकडेच धाव का घेतली?\",\"options\":[\"ती त्याची मोठी बहीण होती\",\"तिचे शिक्षण आठवीपर्यंत झाले होते\",\"ती घरीच होती\",\"तिला संस्कृत भाषा येत होती\"],\"answer\":1,\"explain\":\"मीराचे शिक्षण आठवीपर्यंत झाल्यामुळे तिला वाचता येईल याची वसंतला खात्री होती.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात आलेल्या \'गवसणे\' या शब्दाचा योग्य अर्थ कोणता?\",\"options\":[\"हरवणे\",\"सापडणे\",\"फेकून देणे\",\"वाचणे\"],\"answer\":1,\"explain\":\"वसंत मीराला म्हणतो, \'मला सडकेवर कागद गवसला\', याचा अर्थ त्याला कागद सापडला.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"ताराच्या \'माझी साळा तर दुसरीच झालीय\' या वाक्यावरून काय समजते?\",\"options\":[\"ती दुसऱ्या शाळेत गेली\",\"तिचे शिक्षण दुसऱ्या इयत्तेतच सुटले\",\"तिला शाळा आवडत नाही\",\"ती शाळेत शिकवत होती\"],\"answer\":1,\"explain\":\"हे वाक्य ताराच्या अल्प शिक्षणाकडे (केवळ दुसरीपर्यंत) निर्देश करते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"वसंतची नजर कागदावर खिळणे, यातून त्याचा कोणता गुण दिसून येतो?\",\"options\":[\"आळशीपणा\",\"जिज्ञासा किंवा शिक्षणाची ओढ\",\"राग\",\"भीती\"],\"answer\":1,\"explain\":\"कागदावर काय लिहिले आहे हे जाणून घेण्याची इच्छा त्याची जिज्ञासा दर्शवते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"शंकर आणि तारा शेतात कोणते काम करत होते?\",\"options\":[\"मोळ्या बांधणे\",\"पाणी भरणे\",\"उसावर घाव घालणे\",\"स्वयंपाक करणे\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट म्हटले आहे की, शंकर आणि तारा उसावर घाव घालत होते.\",\"topic\":\"संस्कृत शब्दांचा उलगडा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"\'तमसो मा ज्योतिर्गमय\' हे वाक्य कोणत्या भाषेत आहे?\",\"options\":[\"मराठी\",\"हिंदी\",\"संस्कृत\",\"इंग्रजी\"],\"answer\":2,\"explain\":\"उताऱ्यात मीरा स्पष्टपणे सांगते की हे संस्कृतमधलं वाक्य आहे.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मीराच्या मते \'तमसो मा ज्योतिर्गमय\' या वाक्याचा अर्थ काय आहे?\",\"options\":[\"उजेडाकडून अंधाराकडे\",\"अंधारातून उजेडाकडे\",\"शिक्षणाकडून कामाकडे\",\"कामाकडून घराकडे\"],\"answer\":1,\"explain\":\"मीराने वसंतला सांगितले की याचा अर्थ अंधारातून उजेडाकडे असा होतो.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"ताराच्या मनात कोणती भीती होती?\",\"options\":[\"वसंत कामाला जाणार नाही\",\"शंकरला काम मिळणार नाही\",\"मीराचे शिक्षण अर्धवट राहू नये\",\"ऊस तोडणी होणार नाही\"],\"answer\":2,\"explain\":\"उताऱ्याच्या सुरुवातीलाच नमूद केले आहे की मीराचे शिक्षण अर्धवट राहू नये ही भीती ताराच्या मनात होती.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात, वसंतच्या हातात काय आहे ज्याकडे मीरा पाहत आहे?\",\"options\":[\"उसाची कांडी\",\"कागद\",\"पाटी\",\"पुस्तक\"],\"answer\":1,\"explain\":\"चित्रात आणि मजकुरात वसंतच्या हातात कागद असल्याचे दाखवले आहे.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"43\\/020_101.jpg\"},{\"q\":\"दिलेल्या चित्रात, मीराने जमिनीवर काय ठेवले आहे?\",\"options\":[\"पाण्याची घागर\",\"भाकरीचे गाठोडे\",\"उसाची मोळी\",\"शाळेचे दप्तर\"],\"answer\":2,\"explain\":\"मजकुरात म्हटले आहे की मीरानं डोक्यावरील मोळी खाली ठेवली, जे चित्रातही दिसते.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"remember\",\"figure_image\":\"43\\/020_101.jpg\"},{\"q\":\"मीराच्या स्पष्टीकरणानुसार, \'अंधार\' म्हणजे काय?\",\"options\":[\"रात्र होणे\",\"दिवा नसणे\",\"वाचता न येणे\",\"शाळेत न जाणे\"],\"answer\":2,\"explain\":\"मीरा वसंतला सांगते की संस्कृतमधलं वाक्य वाचता आलं नाही म्हणजे अंधार.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"वसंतने मीराचा हात धरून कोणता निश्चय व्यक्त केला?\",\"options\":[\"मी काम करणार नाही\",\"मी शिकणारच\",\"मी गावी जाणार\",\"मी खेळायला जाणार\"],\"answer\":1,\"explain\":\"वसंत ठामपणे म्हणतो, \'ताई, काही झालं तरी मी शिकणारच.\'\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"शंकरच्या कोणत्या कृतीमुळे वसंतचे शिक्षण तुटत असल्याची जाणीव त्याला झाली?\",\"options\":[\"वसंतला मारल्यामुळे\",\"वसंतचे बोलणे ऐकल्यामुळे\",\"ताराशी भांडल्यामुळे\",\"ऊस तोडल्यामुळे\"],\"answer\":1,\"explain\":\"वसंतचे \'मी शिकणारच\' हे बोलणे ऐकून शंकरला त्याच्या तुटणाऱ्या शिक्षणाची जाणीव झाली.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर \'वाचता न येणे\' म्हणजे अंधार, तर मीराच्या मते \'उजेड\' म्हणजे काय?\",\"options\":[\"दिवस उजाडणे\",\"पुढच्या वर्गात जाऊन शिकणे व वाचता येणे\",\"काम संपवून घरी जाणे\",\"मोळी डोक्यावर घेणे\"],\"answer\":1,\"explain\":\"पुढच्या वर्गात जाऊन शिकलास तर वाचता येईल म्हणजे उजेड, असे मीरा म्हणते.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"शंकरने ऊस तोडण्याच्या क्रियेची तुलना कशाशी केली आहे?\",\"options\":[\"गाडी रूळावर येण्याशी\",\"वसंतचे शिक्षण तुटण्याशी\",\"कागद वाचण्याशी\",\"मोळी बांधण्याशी\"],\"answer\":1,\"explain\":\"लेखकाने \'तडाडा तोडणाऱ्या उसागत वसंतचं शिक्षण तुटत असल्याची\' तुलना केली आहे.\",\"topic\":\"तमसो मा ज्योतिर्गमय\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"वसंतने मीराला \'म्हणजे काय गं