\', \'समोर\', \'वर\' यांसारखे शब्द जेव्हा नामांना जोडून येतात, तेव्हा त्यांना काय म्हणतात?\",\"options\":[\"क्रियापद\",\"शब्दयोगी अव्यय\",\"विशेषण\",\"केवळप्रयोगी अव्यय\"],\"answer\":1,\"explain\":\"परिच्छेदानुसार, नामांना जोडून येणाऱ्या शब्दांना शब्दयोगी अव्यये म्हणतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'शाळेबाहेर\' या शब्दातील शब्दयोगी अव्यय कोणते?\",\"options\":[\"शाळा\",\"शाळे\",\"बाहेर\",\"बाहेरील\"],\"answer\":2,\"explain\":\"शाळा या शब्दाला \'बाहेर\' हा शब्द जोडून आला आहे, म्हणून तो शब्दयोगी अव्यय आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"शब्दयोगी अव्यये शब्दांना कशी जोडली जातात?\",\"options\":[\"स्वतंत्रपणे लिहिली जातात\",\"शब्दाच्या आधी लिहिली जातात\",\"प्रत्ययाप्रमाणे शब्दांना जोडूनच लिहिली जातात\",\"वाक्याच्या शेवटी लिहिली जातात\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की शब्दयोगी अव्यये प्रत्ययाप्रमाणे शब्दांना जोडूनच लिहायची असतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"शब्दयोगी अव्यये जोडण्यापूर्वी नामांच्या किंवा सर्वनामांच्या रूपात जो बदल होतो, त्याला काय म्हणतात?\",\"options\":[\"विभक्ती\",\"सामान्यरूप\",\"संधी\",\"समास\"],\"answer\":1,\"explain\":\"शब्दयोगी अव्यये जोडण्यापूर्वी नामांचे किंवा सर्वनामांचे सामान्यरूप होते.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'तो पूर्वी श्रीमंत होता\' या वाक्यातील \'पूर्वी\' हे कोणत्या प्रकारचे अव्यय आहे?\",\"options\":[\"शब्दयोगी अव्यय\",\"क्रियाविशेषण अव्यय\",\"उभयान्वयी अव्यय\",\"केवळप्रयोगी अव्यय\"],\"answer\":1,\"explain\":\"येथे \'पूर्वी\' हा शब्द स्वतंत्रपणे आला आहे, म्हणून तो क्रियाविशेषण अव्यय आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"\'जेवणापूर्वी हात धुवावेत\' या वाक्यातील \'पूर्वी\' हे काय आहे?\",\"options\":[\"शब्दयोगी अव्यय\",\"क्रियाविशेषण अव्यय\",\"नाम\",\"क्रियापद\"],\"answer\":0,\"explain\":\"येथे \'पूर्वी\' हा शब्द \'जेवण\' या शब्दाला जोडून आला आहे, म्हणून तो शब्दयोगी अव्यय आहे.\",\"topic\":\