,\"options\":[\"पुढच्या दोन्ही\",\"मागच्या दोन्ही\",\"एकाच पायावर\",\"चारही पायांवर\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की, शीळ ऐकल्यावर तो मागच्या दोन्ही पायांवर उभा राहायचा.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"लेखकाच्या स्वागतासाठी तो प्राणी कसा धावायचा?\",\"options\":[\"वेगाने\",\"लंगडत\",\"दुडदुडत\",\"हळूहळू\"],\"answer\":2,\"explain\":\"उताऱ्यात प्राण्याच्या धावण्याचे वर्णन \'दुडदुडत\' असे केले आहे.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"लेखकाच्या येण्याची चाहूल घेण्यासाठी तो प्राणी काय करायचा?\",\"options\":[\"मान उंचावून रूप न्याहाळायचा\",\"डोळे मिटून घ्यायचा\",\"जोरात ओरडायचा\",\"पळून जायचा\"],\"answer\":0,\"explain\":\"लेखकाच्या येण्याची चाहूल घेण्यासाठी तो मान उंचावून ओळखीचे रूप न्याहाळायचा.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात प्राण्याच्या स्वागताची तुलना कशाशी केली आहे?\",\"options\":[\"मित्राच्या भेटीशी\",\"पाहुण्यांच्या हस्तांदोलनाशी\",\"आईच्या प्रेमाशी\",\"मालकाच्या आज्ञेशी\"],\"answer\":1,\"explain\":\"लेखकाने प्राण्याच्या स्वागताची तुलना पाहुण्यांच्या हस्तांदोलनाशी केली आहे.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"\'अविस्मरणीय\' या शब्दाचा उताऱ्यातील संदर्भाप्रमाणे अर्थ काय?\",\"options\":[\"लवकर विसरता येणारे\",\"कधीही न विसरता येणारे\",\"खूप जुने\",\"दुःखदायक\"],\"answer\":1,\"explain\":\"अविस्मरणीय म्हणजे जे कधीही विसरता येत नाही असे.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"लेखकाने या नात्याचे वर्णन \'नात्याबाहेरचे नाते\' असे का केले असावे?\",\"options\":[\"कारण तो प्राणी लेखकाचा नातेवाईक होता\",\"कारण त्यांच्यात रक्ताचे नाते नव्हते, तरीही प्रेम होते\",\"कारण लेखकाला ते नाते आवडत नव्हते\",\"कारण ते नाते फक्त काही दिवसांचे होते\"],\"answer\":1,\"explain\":\"रक्ताचे नाते नसतानाही केवळ भेटीगाठीतून निर्माण झालेल्या प्रेमामुळे त्याला \'नात्याबाहेरचे नाते\' म्हटले आहे.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"तो प्राणी लेखकाचे हात कशाने चाटायचा?\",\"options\":[\"पायाने\",\"शेपटीने\",\"तोंडाने\",\"कानांनी\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की, तो त्याच्या तोंडाने हात चाटायचा.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"या उताऱ्यातून प्राण्यांचा कोणता मुख्य गुण दिसून येतो?\",\"options\":[\"रागीटपणा\",\"प्रेमळपणा\",\"आळशीपणा\",\"भीती\"],\"answer\":1,\"explain\":\"प्राणी ज्या प्रकारे लेखकाचे स्वागत करतो, त्यावरून त्याचा प्रेमळपणा दिसून येतो.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील वेब लिंकनुसार, हा उतारा कोणत्या प्राण्याशी संबंधित आहे?\",\"options\":[\"मांजर (Cat)\",\"वाघ (Tiger)\",\"कुत्रा (Dog)\",\"घोडा (Horse)\"],\"answer\":2,\"explain\":\"चित्रातील लिंकमध्ये \'Dog\' हा शब्द स्पष्टपणे दिसत आहे, जो कुत्र्याशी संबंधित आहे.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"apply\",\"figure_image\":\"43\\/051_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील माहिती आणि उताऱ्यावरून, हे नाते कशामुळे अविस्मरणीय झाले?\",\"options\":[\"खूप पैशांमुळे\",\"केवळ येण्या-जाण्याने घडून आलेल्या प्रेमामुळे\",\"नातेवाईक असल्यामुळे\",\"प्राण्याने रक्षण केल्यामुळे\"],\"answer\":1,\"explain\":\"उताऱ्याच्या शेवटी म्हटले आहे की, केवळ येऊन-गेल्याने घडून आलेले नाते अविस्मरणीय झाले.\",\"topic\":\"अविस्मरणीय नातं\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"43\\/051_101.jpg\"},{\"q\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार, विद्यार्थ्यांनी पाठाचे काय करावे?\",\"options\":[\"मुखवाचन\",\"पाठांतर\",\"गायन\",\"चित्रकला\"],\"answer\":0,\"explain\":\"मजकुरात शिक्षकांना विद्यार्थ्यांकडून पाठाचे मुखवाचन करून घेण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"\'अनुलेखन\' या शब्दाचा शैक्षणिक अर्थ काय होतो?\",\"options\":[\"ऐकून लिहिणे\",\"पाहून लिहिणे (जसेच्या तसे)\",\"मनातल्या मनात वाचणे\",\"मोठ्याने वाचणे\"],\"answer\":1,\"explain\":\"अनुलेखन म्हणजे दिलेला मजकूर पाहून लिहिणे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"\'श्रुतलेखन\' या क्रियेत विद्यार्थ्याला प्रामुख्याने काय करावे लागते?\",\"options\":[\"चित्र पाहून वर्णन करणे\",\"पाहून सुंदर अक्षरात लिहिणे\",\"ऐकून लिहिणे\",\"स्वतःच्या मनाने गोष्ट लिहिणे\"],\"answer\":2,\"explain\":\"श्रुतलेखन म्हणजे ऐकून लिहिणे (Dictation).\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"अनुलेखन आणि श्रुतलेखनासाठी काय वापरण्यास सांगितले आहे?\",\"options\":[\"वर्तमानपत्रातील बातमी\",\"पाठातील एखादा परिच्छेद\",\"दुसऱ्या पुस्तकातील कविता\",\"स्वतःचे अनुभव\"],\"answer\":1,\"explain\":\"मजकुरात \'पाठातील एखाद्या परिच्छेदाचे\' अनुलेखन व श्रुतलेखन करण्यास सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकातील या विशिष्ट सूचना कोणासाठी आहेत?\",\"options\":[\"पालकांसाठी\",\"विद्यार्थ्यांसाठी\",\"शिक्षकांसाठी\",\"लेखकासाठी\"],\"answer\":2,\"explain\":\"मजकुराची सुरुवातच \'शिक्षकांसाठी\' या शब्दाने झाली आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"मुखवाचन ही क्रिया खालीलपैकी कशाशी संबंधित आहे?\",\"options\":[\"वाचन कौशल्य\",\"लेखन कौशल्य\",\"चित्रकला कौशल्य\",\"हस्ताक्षर सुधारणे\"],\"answer\":0,\"explain\":\"मुखवाचन (Silent reading) हे वाचन कौशल्याशी संबंधित आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"जर शिक्षकांना विद्यार्थ्यांचे ऐकून लिहिण्याचे कौशल्य तपासायचे असेल, तर ते कोणती कृती करतील?\",\"options\":[\"अनुलेखन\",\"मुखवाचन\",\"श्रुतलेखन\",\"प्रकटवाचन\"],\"answer\":2,\"explain\":\"ऐकून लिहिण्याच्या क्रियेला श्रुतलेखन म्हणतात.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या मजकुरानुसार, एकूण किती प्रकारच्या शैक्षणिक कृतींचा उल्लेख आला आहे?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"मुखवाचन, अनुलेखन आणि श्रुतलेखन अशा तीन कृतींचा उल्लेख आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"अनुलेखन करताना विद्यार्थ्याला कशाची आवश्यकता असते?\",\"options\":[\"समोर असलेल्या मजकुराची\",\"केवळ आवाजाची\",\"रंगीत खडूंची\",\"संगीत वाद्यांची\"],\"answer\":0,\"explain\":\"अनुलेखन पाहून करायचे असल्यामुळे समोर मजकूर असणे आवश्यक आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"शिक्षकांसाठी दिलेल्या या सूचनांचा मुख्य उद्देश काय असावा?\",\"options\":[\"विद्यार्थ्यांचे मनोरंजन करणे\",\"विद्यार्थ्यांच्या भाषिक कौशल्यांचा सराव करून घेणे\",\"विद्यार्थ्यांना खेळायला पाठवणे\",\"विद्यार्थ्यांना पाठांतर करायला लावणे\"],\"answer\":1,\"explain\":\"वाचन आणि लेखन (अनुलेखन, श्रुतलेखन) या भाषिक कौशल्यांचा विकास करणे हा याचा उद्देश आहे.\",\"topic\":\"स्वाध्याय\",\"part\":11,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21940,43,7,'Marathi','mr','गोमू माहेरला जाते (गीत)','[\"गोमू माहेरला जाते (गीत) हे कविता एका कोळीणच्या अनुभवावर आधारित आहे.\",\"कवितेत कोळीण रात्रीच्या वेळी घरातील दार बंद करत असते, ज्यामुळे त्याला सुरक्षित वाटते.\",\"कोळीण दाराच्या बाजूला सावज (कीट) पकडतो आणि त्याची गती व आवाज लक्षात घेतो.\",\"कवितेत रात्रीच्या शांतता, चंद्रप्रकाश, आणि जंगली वातावरणाचे वर्णन केले आहे.\",\"कोळीण आपल्या अस्तित्वाची काळजी घेतो, पण सावजाला पकडून त्याला ओढतो.\",\"दार उघडण्याने कोळीणला डर वाटतो, कारण त्याला वाटते की सावज पळेल.\",\"कवितेत कोळीण व सावज यांच्यातील स्पर्श व विश्वासाचे भाव दर्शविले आहेत.\",\"सावज दारात घुसल्यावर कोळीणला आश्चर्य व विस्मय होते.\",\"कवितेत प्रकृतींची शांतता आणि जीवांचे परस्परसंबंध दर्शविले जाते.\",\"कोळीण आपल्या घरट्यावर विश्वास ठेवतो, पण सावजाच्या स्पर्शाने त्याचा विश्वास डोळते.\",\"कवितेत रात्रीच्या वेळी होणाऱ्या लहान-लहान घटनांचे सुंदर वर्णन केले आहे.\",\"कोळीण आपल्या घरातील शांतीचे अनुभव करतो, पण सावजाच्या आगमनाने ते बदलते.\",\"कवितेत शब्दांच्या लयवंत व काव्यात्मक शैली दर्शविली आहे.\",\"कोळीण आपल्या घराच्या दारावर लक्ष देते, ज्यामुळे त्याला सुरक्षित वाटते.\",\"कवितेत भावनात्मक गंभीरता व शांतता एकत्र दिसते.\"]','[{\"q\":\"\'गोमू माहेरला जाते\' या गीताचे कवी कोण आहेत?\",\"options\":[\"व. पु. काळे\",\"म. दि. माडगूळकर\",\"कुसुमाग्रज\",\"बालकवी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील कवी परिचयानुसार या गीताचे कवी म. दि. माडगूळकर आहेत.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"म. दि. माडगूळकर यांचा जीवनकाळ कोणता आहे?\",\"options\":[\"१८१९-१८७७\",\"१९१९-१९७७\",\"१९०९-१९६७\",\"१९२९-१९८७\"],\"answer\":1,\"explain\":\"कवी परिचयात त्यांचा काळ १९१९-१९७७ असा दिला आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"म. दि. माडगूळकर यांना कोणत्या नावाने ओळखले जाते?\",\"options\":[\"गीतगोपालकार\",\"कादंबरीकार\",\"गीतरामायणकार\",\"कथाकार\"],\"answer\":2,\"explain\":\"म. दि. माडगूळकर हे \'गीतरामायणकार\' म्हणून प्रसिद्ध आहेत.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'चैत्रबन\' हा म. दि. माडगूळकर यांचा कोणता साहित्यप्रकार आहे?\",\"options\":[\"कादंबरी\",\"कथासंग्रह\",\"गीतसंग्रह\",\"पटकथा\"],\"answer\":2,\"explain\":\"कवी परिचयात \'चैत्रबन\' हा गीतसंग्रह असल्याचे नमूद केले आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"प्रस्तुत गीतात कवीने कशाचे सुरेख वर्णन केले आहे?\",\"options\":[\"शहरातील धावपळीचे\",\"कोकणातील निसर्गसौंदर्याचे व माणसांचे\",\"डोंगराळ भागातील कष्टाचे\",\"शेतातील कामांचे\"],\"answer\":1,\"explain\":\"कवीने कोकण, तेथील निसर्ग आणि साध्या भोळ्या माणसांचे वर्णन केले आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'तुपाचा नंदादीप\' हा म. दि. माडगूळकर यांचा कोणता साहित्यप्रकार आहे?\",\"options\":[\"गीतसंग्रह\",\"कथासंग्रह\",\"कादंबरी\",\"काव्यनिर्मिती\"],\"answer\":1,\"explain\":\"परिचयानुसार \'तुपाचा नंदादीप\' हा कथासंग्रह आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला म. दि. माडगूळकर यांची कादंबरी वाचायची असेल, तर तुम्ही खालीलपैकी कोणते पुस्तक निवडाल?\",\"options\":[\"जोगिया\",\"गीतगोपाल\",\"आकाशाची फळे\",\"वैशाखी\"],\"answer\":2,\"explain\":\"\'आकाशाची फळे\' ही म. दि. माडगूळकर यांची प्रसिद्ध कादंबरी आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"म. दि. माडगूळकर यांच्या \'गीतसंग्रह\' या श्रेणीत खालीलपैकी कोणते पुस्तक येते?\",\"options\":[\"कृष्णाची करंगळी\",\"पुष्पा\",\"ऊभे धागे आडवे धागे\",\"गीतसौभद्र\"],\"answer\":1,\"explain\":\"\'पुष्पा\' हा म. दि. माडगूळकर यांचा गीतसंग्रह आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या माहितीनुसार, म. दि. माडगूळकर यांनी साहित्याच्या कोणत्या क्षेत्रात काम केलेले नाही?\",\"options\":[\"पटकथालेखक\",\"कादंबरीकार\",\"कवी\",\"वैज्ञानिक संशोधक\"],\"answer\":3,\"explain\":\"परिचयात कवी, लेखक, पटकथालेखक, कादंबरीकार असा उल्लेख आहे, पण वैज्ञानिक संशोधक असा नाही.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"\'गीतगोपाल\' आणि \'गीतसौभद्र\' या साहित्यकृती कोणत्या प्रकारात मोडतात?\",\"options\":[\"कथासंग्रह\",\"काव्यनिर्मिती\",\"कादंबरी\",\"पटकथा\"],\"answer\":1,\"explain\":\"परिचयात \'गीतगोपाल\' व \'गीतसौभद्र\' ही काव्यनिर्मिती असल्याचे सांगितले आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"कवीने कोकणातील माणसांचे स्वभाव वैशिष्ट्य सांगण्यासाठी कोणता शब्द वापरला आहे?\",\"options\":[\"चतुर\",\"साधी भोळी\",\"कष्टकरी\",\"धाडसी\"],\"answer\":1,\"explain\":\"कवीने कोकणातील माणसांचे वर्णन \'साधी भोळी\' असे केले आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"म. दि. माडगूळकर यांच्या साहित्याचा आवाका लक्षात घेता, त्यांनी कोणत्या विषयावर हे गीत लिहिले आहे?\",\"options\":[\"ऐतिहासिक घटना\",\"कोकणचा प्रादेशिक निसर्ग व लोकजीवन\",\"शहरी संस्कृती\",\"देशभक्ती\"],\"answer\":1,\"explain\":\"हे गीत कोकण, तेथील खाडी, निसर्ग आणि माणसांवर आधारित आहे.\",\"topic\":\"कवी परिचय\",\"part\":2,\"bloom\":\"create\"},{\"q\":\"\'उभय\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"एक\",\"दोन\",\"अनेक\",\"संबंध\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार \'उभय\' या शब्दाचा अर्थ \'दोन\' असा आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"\'अन्वय\' या शब्दाचा अर्थ काय आहे?\",\"options\":[\"जोडणे\",\"वाक्य\",\"संबंध\",\"शब्द\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात \'अन्वय\' या शब्दाचा अर्थ \'संबंध\' असा दिला आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दोन वा अधिक शब्दांना किंवा वाक्यांना जोडणाऱ्या शब्दांना काय म्हणतात?\",\"options\":[\"नाम\",\"सर्वनाम\",\"विशेषण\",\"उभयान्वयी अव्यये\"],\"answer\":3,\"explain\":\"दोन शब्द किंवा वाक्ये जोडणाऱ्या शब्दांना उभयान्वयी अव्यये म्हणतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"उभयान्वयी अव्ययाचे मुख्य कार्य काय आहे?\",\"options\":[\"शब्दांची माहिती सांगणे\",\"दोन शब्द किंवा वाक्यांचा संबंध जोडणे\",\"वाक्य पूर्ण करणे\",\"क्रियापदाची माहिती देणे\"],\"answer\":1,\"explain\":\"दोन शब्द किंवा दोन वाक्ये यांचा संबंध जोडणे हे उभयान्वयी अव्ययाचे कार्य आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"\'नंदा आणि आई मंडईत पोहोचल्या\' या वाक्यातील उभयान्वयी अव्यय कोणते?\",\"options\":[\"नंदा\",\"आणि\",\"आई\",\"पोहोचल्या\"],\"answer\":1,\"explain\":\"\'आणि\' हा शब्द नंदा आणि आई या दोन शब्दांना जोडण्याचे काम करतो.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते शब्द उभयान्वयी अव्यये आहेत?\",\"options\":[\"मी, तू, तो\",\"आणि, शिवाय, पण\",\"गाव, पाऊस, रिक्षा\",\"लवकर, जोरात, कोठे\"],\"answer\":1,\"explain\":\"आणि, शिवाय, पण हे शब्द दोन शब्द किंवा वाक्ये जोडण्यासाठी वापरले जातात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"\'ससाची आणि कासवाची पळण्याची शर्यत लागली\' या वाक्यात कोणते उभयान्वयी अव्यय आले आहे?\",\"options\":[\"ससाची\",\"आणि\",\"पळण्याची\",\"शर्यत\"],\"answer\":1,\"explain\":\"या वाक्यात \'आणि\' हे उभयान्वयी अव्यय ससा व कासव या शब्दांना जोडते.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"\'आईने काटकसर केली; ___ काही शिल्लक उरले नाही.\' या वाक्यात कोणते उभयान्वयी अव्यय योग्य ठरेल?\",\"options\":[\"आणि\",\"पण\",\"अथवा\",\"म्हणून\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील उदाहरणाप्रमाणे येथे \'पण\' हे अव्यय वापरले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"नंदाने आईला कोणता पर्याय विचारला?\",\"options\":[\"बटाटे घेऊ की लसूण घेऊ?\",\"लसूण घेऊ की आले घेऊ?\",\"फळे घेऊ की भाजी घेऊ?\",\"रिक्षाने जाऊ की बसने जाऊ?\"],\"