rstand\"},{\"q\":\"मावशीकडे कोणाचा वाढदिवस होता?\",\"options\":[\"श्रुतीचा\",\"तिच्या मावस बहिणीचा\",\"तिच्या आईचा\",\"तिच्या बाबांचा\"],\"answer\":1,\"explain\":\"श्रुती मावशीकडे तिच्या मावस बहिणीच्या वाढदिवसासाठी गेली होती.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मावशीकडील बुफेच्या बेतात खालीलपैकी कोणता पदार्थ नव्हता?\",\"options\":[\"गुलाबजाम\",\"कचोरी\",\"पुलाव\",\"भजी\"],\"answer\":3,\"explain\":\"बुफेच्या बेतात गुलाबजाम, केक, कचोरी आणि पुलाव हे पदार्थ होते, भजी नव्हती.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"श्रुतीने डिशमध्ये काय टाकून दिले?\",\"options\":[\"पुलाव\",\"कचोरी\",\"गुलाबजाम\",\"केक\"],\"answer\":2,\"explain\":\"श्रुतीने एक गुलाबजाम खाल्ला आणि डिश बेसिनमध्ये ठेवून दिली.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"अन्नाची नासाडी केल्यामुळे अन्नाच्या चवीसोबतच आणखी कशाचा अपव्यय होतो?\",\"options\":[\"केवळ पाण्याचा\",\"अनेक घटकांचा\",\"फक्त वेळेचा\",\"केवळ पैशांचा\"],\"answer\":1,\"explain\":\"अन्नाची नासाडी केल्यामुळे अन्नाच्या चवीसोबत अनेक घटकांचाही अपव्यय होतो.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"दूरदर्शनवरील बातम्यांमध्ये कोणत्या भागातील कुपोषित बालके दाखवली होती?\",\"options\":[\"कोकण\",\"विदर्भ\",\"मेळघाट\",\"मराठवाडा\"],\"answer\":2,\"explain\":\"दूरदर्शनवर मेळघाटमधील कुपोषित बालके दाखवण्यात आली होती.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"कुपोषित बालके हाडकुळी का असतात?\",\"options\":[\"त्यांना खेळायला मिळत नाही म्हणून.\",\"त्यांना पुरेसे जेवण व पोषक घटक मिळत नाहीत म्हणून.\",\"ती खूप व्यायाम करतात म्हणून.\",\"त्यांना झोप मिळत नाही म्हणून.\"],\"answer\":1,\"explain\":\"पुरेसे जेवण न मिळाल्याने प्रोटीन्स, व्हिटॅमिन्स व मिनरल्स मिळत नाहीत, म्हणून ती हाडकुळी असतात.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"बाबांच्या ऑफिसमध्ये कॅटरिंगवाल्याने कोणता बोर्ड लावला होता?\",\"options\":[\"आजचा बेत काय आहे याचा.\",\"अन्न किती चविष्ट आहे याचा.\",\"पानात किती अन्न टाकले व त्यात किती लोक जेवू शकतात याचा.\",\"जेवणाचे दर किती आहेत याचा.\"],\"answer\":2,\"explain\":\"अन्नाची नासाडी टाळण्यासाठी कॅटरिंगवाल्याने अन्नाच्या नासाडीचा बोर्ड लावला होता.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"श्रुतीने शेवटी कोणता संकल्प केला?\",\"options\":[\"मी रोज अभ्यास करेन.\",\"मी यापुढे कधीही पानात अन्न टाकणार नाही.\",\"मी दररोज व्यायाम करेन.\",\"मी नेहमी इंग्रजीमध्येच बोलेन.\"],\"answer\":1,\"explain\":\"कुपोषित बालके पाहिल्यावर श्रुतीने अन्न न टाकण्याचा संकल्प केला.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"समारंभात पदार्थांचे वैविध्य व रेलचेल का असते?\",\"options\":[\"कारण अन्न स्वस्त असते.\",\"कारण \'निमंत्रण-जेवण\' हा मनुष्य स्वभावाचा घटक आहे.\",\"कारण लोकांना जास्त खायला आवडते.\",\"कारण पदार्थ खराब होऊ नयेत म्हणून.\"],\"answer\":1,\"explain\":\"मनुष्य स्वभावाचा घटक असल्यामुळे अशा समारंभात पदार्थांची रेलचेल असते.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"श्रुतीच्या आईने तिला घरी आल्यावर का रागावले?\",\"options\":[\"श्रुतीने अभ्यास केला नव्हता म्हणून.\",\"श्रुतीने मावशीशी नीट संवाद साधला नाही म्हणून.\",\"श्रुतीने आवडते पदार्थ असूनही अन्न वाया घालवले म्हणून.\",\"श्रुती उशिरा घरी आली म्हणून.\"],\"answer\":2,\"explain\":\"श्रुतीने डिशमध्ये अन्न टाकून दिल्यामुळे तिची आई रागावली होती.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"उताऱ्यात आलेल्या \'हाडकुळी\' या शब्दाचा अर्थ काय?\",\"options\":[\"खूप उंच\",\"खूप जाड\",\"खूप अशक्त किंवा बारीक\",\"खूप शक्तीवान\"],\"answer\":2,\"explain\":\"कुपोषणामुळे शरीरात मांस कमी होऊन केवळ हाडे दिसतात, त्याला हाडकुळी म्हणतात.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"श्रुतीचा संकल्प कोणत्या गोष्टीवर आधारित आहे?\",\"options\":[\"सामाजिक भान आणि अन्नाचे महत्त्व\",\"केवळ स्वतःचे आरोग्य\",\"इंग्रजी भाषेचे ज्ञान\",\"वाढदिवसाची मजा\"],\"answer\":0,\"explain\":\"अन्नाची नासाडी टाळणे हा सामाजिक जबाबदारीचा भाग आहे.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"बाबांनी श्रुतीला कुपोषित बालकांबद्दल माहिती दिल्यावर तिच्या वागण्यात काय बदल झाला?\",\"options\":[\"ती अधिक नाराज झाली.\",\"तिला अन्नाचे महत्त्व समजले व तिने संकल्प केला.\",\"तिने जेवण करणे सोडून दिले.\",\"तिने टीव्ही पाहणे बंद केले.\"],\"answer\":1,\"explain\":\"परिस्थितीचे गांभीर्य समजल्यावर श्रुतीने उत्साहाने अन्न न टाकण्याचा निर्णय घेतला.\",\"topic\":\"श्रुतीचा संकल्प\",\"part\":2,\"bloom\":\"create\"},{\"q\":\"खालीलपैकी कोणती इंधने दुर्मिळ होत चालली आहेत असे पाठात म्हटले आहे?\",\"options\":[\"सौर ऊर्जा आणि पवन ऊर्जा\",\"खनिज तेल आणि लाकूड\",\"पाणी आणि हवा\",\"वीज आणि कोळसा\"],\"answer\":1,\"explain\":\"पाठात स्पष्टपणे नमूद केले आहे की खनिज तेल आणि लाकूड ही इंधने दुर्मिळ होत चालली आहेत.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"अन्न शिजवताना इंधनाचा अपव्यय का होतो?\",\"options\":[\"जेव्हा आपण अन्न वाया घालवतो\",\"जेव्हा आपण जास्त जेवतो\",\"जेव्हा आपण अन्न विकत घेतो\",\"जेव्हा आपण अन्न झाकून ठेवतो\"],\"answer\":0,\"explain\":\"अन्न वाया घालवल्यामुळे ते शिजवण्यासाठी वापरलेले इंधनही वाया जाते, म्हणजेच त्याचा अपव्यय होतो.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत अन्न शिजवण्यासाठी लागणारी कोणती साधने\\/इंधने दाखवली आहेत?\",\"options\":[\"फक्त सौर चूल\",\"विजेवर चालणारी शेगडी\",\"गॅस सिलिंडर, लाकूड आणि रॉकेल\",\"फक्त कागद आणि कचरा\"],\"answer\":2,\"explain\":\"आकृतीत गॅस सिलिंडर, लाकूड आणि खनिज तेलाचा डबा (रॉकेल) दाखवला आहे.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"remember\",\"figure_image\":\"43\\/096_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत अन्नपदार्थ तयार करण्यासाठी लागणारे कोणते घटक दिसत आहेत?\",\"options\":[\"मसाले, तेल, तूप आणि भाज्या\",\"फक्त फळे आणि फुले\",\"दगड आणि माती\",\"दूध आणि अंडी\"],\"answer\":0,\"explain\":\"आकृतीत तेल, तूप, मसाले आणि विविध भाज्या दाखवल्या आहेत ज्यांचा वापर अन्न बनवण्यासाठी होतो.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"43\\/096_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत ज्वारी, तांदूळ आणि गहू ही धान्ये दाखवली आहेत. पानात कोणता पदार्थ टाकल्यामुळे या धान्याची नासाडी होते?\",\"options\":[\"फक्त लोणचे\",\"चपाती, भाकरी आणि भात\",\"फक्त पाणी\",\"फक्त मीठ\"],\"answer\":1,\"explain\":\"पानात चपाती, भाकरी, भात टाकल्यामुळे धान्याची नासाडी होते, कारण ही धान्ये गहू, ज्वारी आणि तांदळापासून बनतात.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"43\\/096_103.jpg\"},{\"q\":\"अन्नपदार्थ तयार करताना खालीलपैकी कोणत्या घटकांचा अपव्यय होतो असे पाठात सांगितले आहे?\",\"options\":[\"प्लास्टिक आणि कागद\",\"काच आणि लोखंड\",\"मसाले, तेल आणि तूप\",\"रंग आणि खडू\"],\"answer\":2,\"explain\":\"अन्नपदार्थ तयार करताना मसाले, तेल, तूप, पालेभाज्या व फळभाज्या या घटकांचा अपव्यय होतो.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर आपण ताटात अन्न उरवले, तर कोणाचे कष्ट वाया जातात?\",\"options\":[\"फक्त दुकानदाराचे\",\"अन्न शिजवणारे आणि भांडी घासणारे अशा अनेक व्यक्तींचे\",\"फक्त जेवणाऱ्या व्यक्तीचे\",\"फक्त भाजी विकणाऱ्याचे\"],\"answer\":1,\"explain\":\"अन्न शिजवणारे, वाढणारे, भांडी घासणारे अशा अनेक व्यक्तींचे कष्ट अन्नासोबत वाया जातात.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"खनिज तेल आणि लाकूड वाया घालवणे योग्य का नाही?\",\"options\":[\"कारण ती स्वस्त आहेत\",\"कारण ती सहज मिळतात\",\"कारण ती दुर्मिळ होत चालली आहेत\",\"कारण ती खाण्यायोग्य नाहीत\"],\"answer\":2,\"explain\":\"दुर्मिळ होत चाललेल्या नैसर्गिक साधनसंपत्तीची जपणूक करणे आवश्यक आहे, म्हणून ती वाया घालवणे अयोग्य आहे.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"पानात चपाती किंवा भात टाकल्यामुळे प्रत्यक्ष कशाची नासाडी होते?\",\"options\":[\"धान्याची\",\"फक्त पालेभाज्यांची\",\"फक्त फळांची\",\"फक्त मसाल्यांची\"],\"answer\":0,\"explain\":\"चपाती, भाकरी, भात हे पदार्थ धान्यापासून बनतात, म्हणून ते टाकल्यास धान्याची नासाडी होते.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"अन्न शिजवण्याच्या \'पूर्वतयारीमध्ये\' खालीलपैकी कोणत्या कामाचा समावेश होतो?\",\"options\":[\"जेवण करणे\",\"भाजी चिरणे\",\"अन्न विकत घेणे\",\"पाणी पिणे\"],\"answer\":1,\"explain\":\"भाजी चिरणे, चपात्या करणे ही कामे अन्न शिजवण्याच्या पूर्वतयारीचा भाग आहेत.\",\"topic\":\"अन्नाचा अपव्यय\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"कचराकुंडीत अन्न फेकून दिल्याने परिसरात काय परिणाम होतो?\",\"options\":[\"परिसर स्वच्छ होतो\",\"दुर्गंधी पसरते\",\"अन्न ताजे राहते\",\"परिसर सुगंधी होतो\"],\"answer\":1,\"explain\":\"उरलेले अन्न खराब झाल्याने त्या परिसरात दुर्गंधी पसरते असे पाठात नमूद केले आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"कवितेनुसार शेतात राबणाऱ्या व्यक्तीला काय म्हटले आहे?\",\"options\":[\"श्रमिक\",\"यजमान\",\"कृषिवल\",\"विद्यार्थी\"],\"answer\":2,\"explain\":\"\'कृषिवल कृषिकर्मी राबती दिवसात\' या ओळीत शेतकऱ्याला कृषिवल म्हटले आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"जेवताना यजमानाने कोणती मुख्य गोष्ट पाहणे गरजेचे आहे?\",\"options\":[\"लोकांना खूप आग्रह करणे\",\"खूप जास्त पदार्थ बनवणे\",\"लोकांना हवे ते पदार्थ मिळतील का हे पाहणे\",\"लोकांना जास्तीचे अन्न वाढणे\"],\"answer\":2,\"explain\":\"जेवताना लोक जे मागतील ते पदार्थ त्यांना मिळतील का, एवढेच यजमानाने पाहणे गरजेचे आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"स्वेच्छाभोजनामुळे अन्नाची नासाडी का टाळता येते?\",\"options\":[\"लोक जेवणच करत नाहीत\",\"लोक हवे ते व हवे तेवढेच पदार्थ वाढून घेतात\",\"यजमान खूप आग्रह करतात\",\"अन्नपदार्थांची संख्या वाढवली जाते\"],\"answer\":1,\"explain\":\"स्वेच्छाभोजनामुळे लोक स्वतःला हवे तेवढेच वाढून घेतात, त्यामुळे पानात रेलचेल होत नाही.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"समारंभाचे स्वरूप मर्यादित ठेवून अन्नपदार्थांची संख्या कमी ठेवल्यास काय होईल?\",\"options\":[\"अन्न वाया जाणार नाही\",\"पाहुणे नाराज होतील\",\"अन्न जास्त उरेल\",\"खर्च वाढेल\"],\"answer\":0,\"explain\":\"मर्यादित स्वरूपामुळे बनवलेले सर्व अन्नपदार्थ खाल्ले जातील व संपतील, ज्यामुळे नासाडी टळेल.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"अन्नावर अवाजवी खर्च करण्याऐवजी तो पैसा कोठे वापरणे योग्य ठरेल?\",\"options\":[\"नवीन कपडे घेण्यासाठी\",\"मोठा समारंभ करण्यासाठी\",\"गरजू व होतकरू विद्यार्थ्यांना मदत करण्यासाठी\",\"जास्त अन्न शिजवण्यासाठी\"],\"answer\":2,\"explain\":\"अन्नावर अवाजवी खर्च करण्यापेक्षा त्या पैशांतून गरजू विद्यार्थ्यांना मदत करावी असे पाठात सुचवले आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"\'वदनी कवळ घेता\' या ओळींमधून लेखकाला कोणता मुख्य संदेश द्यायचा आहे?\",\"options\":[\"अन्न खाताना फक्त चवीचा विचार करावा\",\"अन्न तयार करणाऱ्या श्रमिकांचे स्मरण करून अन्नाचा आदर करावा\",\"नेहमी पंगतीतच जेवावे\",\"खूप जास्त अन्न खावे\"],\"answer\":1,\"explain\":\"श्रमिक आणि कृषिवल यांच्या कष्टाचे स्मरण करून अन्न सेवन करावे, असा संदेश या ओळी देतात.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"अनाथश्रमाला देणगी दिल्याने समाजातील कोणत्या घटकांना दिलासा मिळेल?\",\"options\":[\"श्रीमंत व्यक्तींना\",\"केवळ यजमानांना\",\"दुखितांना व गरजूना\",\"केवळ शेतकऱ्यांना\"],\"answer\":2,\"explain\":\"अनाथश्रमाला दिलेली देणगी समाजातील दुखितांना आणि गरजूना थोडासा दिलासा देते.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"पाठात दिलेल्या माहितीनुसार सध्या कोणती गोष्ट एक समस्या बनू लागली आहे?\",\"options\":[\"अन्नकचरा\",\"स्वेच्छाभोजन\",\"अनाथश्रम\",\"पाहुणचार\"],\"answer\":0,\"explain\":\"अन्नकचरा ही एक समस्या बनू लागली आहे असे पाठाच्या सुरुवातीलाच म्हटले आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"जेवणपंगतींना फाटा देऊन वाचलेली रक्कम गरजूना देणे, हे कशाचे प्रतीक आहे?\",\"options\":[\"कंजूषपणाचे\",\"सामाजिक बांधिलकी आणि संवेदनशीलतेचे\",\"आळशीपणाचे\",\"अज्ञानाचे\"],\"answer\":1,\"explain\":\"अन्नाची नासाडी टाळून गरजूना मदत करणे हे सामाजिक जबाबदारीचे लक्षण आहे.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रात जेवणाची कोणती पद्धत दर्शवली आहे?\",\"options\":[\"स्वेच्छाभोजन (Buffet)\",\"जेवणपंगत (Traditional Row)\",\"उभे राहून जेवणे\",\"हॉटेलमधील जेवण\"],\"answer\":1,\"explain\":\"चित्रात लोक रांगेत खाली बसून जेवत आहेत, ज्याला \'पंगत\' असे म्हणतात.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"remember\",\"figure_image\":\"43\\/097_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील व्यक्ती काय करत आहेत?\",\"options\":[\"अन्न शिजवत आहेत\",\"भांडी साफ करत आहेत\",\"अन्न सेवन (जेवण) करत आहेत\",\"अन्न फेकून देत आहेत\"],\"answer\":2,\"explain\":\"चित्रात सर्व लोक पानात वाढलेले अन्न खाताना दिसत आहेत.\",\"topic\":\"आपण हे करू शकतो\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"43\\/097_101.jpg\"},{\"q\":\"\'शोध घेऊया\' या भागात कोणत्या मुख्य समस्येचा उल्लेख केला आहे?\",\"options\":[\"बेरोजगारी\",\"प्रदूषण\",\"कुपोषण\",\"अज्ञान\"],\"answer\":2,\"explain\":\"उताऱ्याच्या पहिल्याच ओळीत कुपोषण ही एक खूप मोठी समस्या असल्याचे म्हटले आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कुपोषणाचे भयावह स्वरूप प्रामुख्याने कोणत्या भागात पाहायला मिळते?\",\"options\":[\"शहरी भागात\",\"आदिवासी व दुर्गम भागात\",\"विकसित भागात\",\"औद्योगिक भागात\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की, आदिवासी व दुर्गम भागात या समस्येचे भयावह स्वरूप दिसते.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कुपोषणाच्या समस्येची माहिती मिळवण्यासाठी कोणता स्रोत वापरण्यास सुचवले आहे?\",\"options\":[\"आंतरजाल (Internet)\",\"रेडिओ\",\"वर्तमानपत्र\",\"शब्दकोश\"],\"answer\":0,\"explain\":\"उताऱ्यात \'आंतरजालावरून या समस्येची माहिती करून घ्या\' असे सांगितले आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात दिलेल्या प्रश्नांनुसार, कुपोषणाबाबत नेमकी कोणती माहिती शोधायची आहे?\",\"options\":[\"कुपोषणाचे फायदे\",\"कुपोषण ही समस्या का निर्माण होते?\",\"कुपोषणाचे ऐतिहासिक महत्त्व\",\"कुपोषणावरील कविता\"],\"answer\":1,\"explain\":\"दिलेल्या प्रश्नांपैकी पहिला प्रश्न \'ही समस्या का निर्माण होते?\' असा आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"कुपोषणाच्या निराकरणासाठी कोण कार्य करते, याची माहिती घेण्यास सांगितले आहे?\",\"options\":[\"परदेशी पर्यटक\",\"विविध संस्था\",\"फक्त व्यापारी\",\"फक्त खेळाडू\"],\"answer\":1,\"explain\":\"प्रश्न क्र. २ मध्ये या समस्येच्या निराकरणासाठी कार्य करणाऱ्या संस्थांची माहिती विचारली आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला कुपोषणाचे कारण शोधायचे असेल, तर तुम्ही उताऱ्यातील कोणत्या प्रश्नाचा आधार घ्याल?\",\"options\":[\"प्रश्न १\",\"प्रश्न २\",\"प्रश्न ३\",\"प्रश्न ४\"],\"answer\":0,\"explain\":\"प्रश्न १ हा \'ही समस्या का निर्माण होते?\' या कारणाशी संबंधित आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"तुमच्या परिसरात एखादे कुपोषित बालक आढळल्यास काय करावे, हा प्रश्न विद्यार्थ्यांच्या कोणत्या गुणाला वाव देतो?\",\"options\":[\"चित्रकला\",\"गायन कौशल्य\",\"सामाजिक संवेदनशीलता व कृती\",\"खेळकर वृत्ती\"],\"answer\":2,\"explain\":\"बालकासाठी तुम्ही काय कराल, हे विचारणे विद्यार्थ्याच्या सामाजिक जबाबदारीशी संबंधित आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"संस्थांच्या कामाचे \'स्वरूप\' शोधणे म्हणजे काय शोधणे होय?\",\"options\":[\"संस्थांचे नाव बदलणे\",\"संस्था कोणत्या प्रकारचे काम करतात हे समजून घेणे\",\"संस्थेची इमारत पाहणे\",\"संस्थेची जाहिरात करणे\"],\"answer\":1,\"explain\":\"कामाचे स्वरूप म्हणजे त्या संस्था नेमकी कोणती मदत किंवा कार्य करतात हे जाणून घेणे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, कुपोषण ही समस्या केवळ वैयक्तिक नसून ती कशी आहे?\",\"options\":[\"ती एक खूप मोठी सामाजिक समस्या आहे\",\"ती एक छोटी अडचण आहे\",\"ती फक्त शहरापुरती मर्यादित आहे\",\"ती आपोआप सुटणारी समस्या आहे\"],\"answer\":0,\"explain\":\"उताऱ्यात कुपोषणाला \'खूप मोठी समस्या\' आणि \'भयावह स्वरूप\' असलेले म्हटले आहे, जे सामाजिक गांभीर्य दर्शवते.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या प्रश्नांच्या आधारे माहिती गोळा करण्याचा मुख्य उद्देश काय असू शकतो?\",\"options\":[\"केवळ गुण मिळवणे\",\"समस्येचे सखोल ज्ञान मिळवून उपाययोजनांचा विचार करणे\",\"फक्त इंटरनेटवर वेळ घालवणे\",\"दुर्गम भागात फिरायला जाणे\"],\"answer\":1,\"explain\":\"समस्येची कारणे, संस्थांचे कार्य आणि स्वतःची भूमिका शोधणे हे सखोल अभ्यासाचे लक्षण आहे.\",\"topic\":\"शोध घेऊया\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"\'प्रकृती\' म्हणजे काय?\",\"options\":[\"भूकेपेक्षा जास्त खाणे\",\"जेवढी भूक आहे तेवढेच खाणे\",\"दुसऱ्याला खाऊ घालणे\",\"अन्नाची नासाडी करणे\"],\"answer\":1,\"explain\":\"पाठातील व्याख्येनुसार, जेवढी भूक आहे तेवढेच खाणे म्हणजे प्रकृती होय.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"जेवढी भूक आहे त्यापेक्षा जास्त खाणे म्हणजे काय?\",\"options\":[\"प्रकृती\",\"संस्कृती\",\"विकृती\",\"प्रवृत्ती\"],\"answer\":2,\"explain\":\"पाठात दिलेल्या माहितीनुसार, भूकेपेक्षा जास्त खाणे ही विकृती आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"आपल्या जेवणातील दोन घास भुकेलेल्यांना खाऊ घालणे याला काय म्हणतात?\",\"options\":[\"संस्कृती\",\"प्रकृती\",\"विकृती\",\"आहार\"],\"answer\":0,\"explain\":\"दुसऱ्याला अन्न देणे किंवा भुकेलेल्यांना खाऊ घालणे म्हणजे संस्कृती होय.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणती कृती \'विकृती\' दर्शवते?\",\"options\":[\"भूक लागल्यावर जेवणे\",\"गरजूला अन्न देणे\",\"पोट भरलेले असतानाही आवडीचा पदार्थ म्हणून जास्त खाणे\",\"वाढदिवसाचा खर्च कमी करणे\"],\"answer\":2,\"explain\":\"भूकेपेक्षा जास्त खाणे ही विकृती असल्यामुळे पोट भरलेले असताना खाणे हे विकृतीचे उदाहरण आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"पाठात दिलेल्या प्रश्नांनुसार, हॉटेलमधील उरलेल्या अन्नाबाबत काय विचारले आहे?\",\"options\":[\"अन्न कसे बनवतात?\",\"उरलेल्या अन्नाचे काय करतात?\",\"अन्न किती महाग असते?\",\"अन्न कोठे मिळते?\"],\"answer\":1,\"explain\":\"पाठात हॉटेलमधील उरलेल्या अन्नाचे काय करतात, हा प्रश्न विचारला आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही तुमच्या डब्यातील थोडा भाग एका गरजू मित्राला दिला, तर तुम्ही कशाचे पालन करत आहात?\",\"options\":[\"प्रकृती\",\"विकृती\",\"संस्कृती\",\"फक्त मदत\"],\"answer\":2,\"explain\":\"भुकेलेल्याला आपल्या जेवणातील भाग देणे ही संस्कृती आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"एका मुलाला खूप भूक लागली आहे आणि त्याने त्याच्या गरजेनुसार दोन पोळ्या खाल्ल्या. हे कशाचे उदाहरण आहे?\",\"options\":[\"विकृती\",\"प्रकृती\",\"संस्कृती\",\"अतिरेक\"],\"answer\":1,\"explain\":\"जेवढी भूक आहे तेवढेच खाणे ही प्रकृती आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"प्रकृती आणि विकृती यांमधील मुख्य फरक कोणता?\",\"options\":[\"अन्नाची चव\",\"अन्नाचे प्रमाण (भूक)\",\"अन्नाची किंमत\",\"अन्न देण्याची पद्धत\"],\"answer\":1,\"explain\":\"दोन्हींमधील फरक हा भूकेच्या तुलनेत किती अन्न खाल्ले जाते या प्रमाणावर अवलंबून आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"पाठात वाढदिवसाच्या खर्चाबद्दल प्रश्न विचारण्यामागे कोणता उद्देश असू शकतो?\",\"options\":[\"खर्च वाढवण्यासाठी प्रोत्साहन देणे\",\"अन्नाचा अपव्यय आणि खर्चाचा विचार करायला लावणे\",\"हॉटेलमध्ये जाण्यासाठी सांगणे\",\"भेटवस्तूंची यादी करणे\"],\"answer\":1,\"explain\":\"अन्नाची नासाडी टाळणे आणि खर्चाचा योग्य विनियोग करणे हा या प्रश्नांमागचा उद्देश आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणता गट योग्य क्रमाने (साधी स्थिती ते उच्च विचार) आहे?\",\"options\":[\"विकृती -> प्रकृती -> संस्कृती\",\"संस्कृती -> विकृती -> प्रकृती\",\"प्रकृती -> संस्कृती -> विकृती\",\"विकृती -> संस्कृती -> प्रकृती\"],\"answer\":0,\"explain\":\"विकृती (वाईट), प्रकृती (नैसर्गिक) आणि संस्कृती (आदर्श\\/उच्च) असा हा क्रम आहे.\",\"topic\":\"लक्षात ठेवा\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"शब्दातील \'उपान्त्य अक्षर\' म्हणजे कोणते अक्षर?\",\"options\":[\"शब्दातील पहिले अक्षर\",\"शब्दातील शेवटचे अक्षर\",\"शब्दातील शेवटून दुसरे अक्षर\",\"शब्दातील मधले अक्षर\"],\"answer\":2,\"explain\":\"उपान्त्य अक्षर म्हणजे शब्दातील शेवटून दुसरे अक्षर होय.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"शब्दातील शेवटचे अक्षर दीर्घ स्वरान्त असेल, तर त्या आधीच्या उपान्त्य अक्षरातील इकार व उकार कसे लिहितात?\",\"options\":[\"दीर्घ लिहितात\",\"ऱ्हस्व लिहितात\",\"काना देऊन लिहितात\",\"लिहीत नाहीत\"],\"answer\":1,\"explain\":\"नियमानुसार शेवटचे अक्षर दीर्घ असल्यास उपान्त्य इकार किंवा उकार ऱ्हस्व असतो.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'महिमा\' या शब्दात \'हि\' हे अक्षर ऱ्हस्व असण्याचे कारण काय?\",\"options\":[\"शब्दाचे पहिले अक्षर \'म\' आहे म्हणून\",\"शब्दाचे शेवटचे अक्षर \'मा\' हे दीर्घ स्वरान्त आहे म्हणून\",\"हा शब्द अपवाद आहे म्हणून\",\"या शब्दाला प्रत्यय लागला आहे म्हणून\"],\"answer\":1,\"explain\":\"शेवटचे अक्षर \'मा\' दीर्घ असल्याने उपान्त्य \'हि\' ऱ्हस्व झाले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या शब्दाला बाराखडीतील \'दीर्घ स्वरान्त\' चिन्ह नाही?\",\"options\":[\"पादुका\",\"गरिबी\",\"भिजू\",\"भिज\"],\"answer\":3,\"explain\":\"\'भिज\' या शब्दाच्या शेवटी काना, मात्रा, वेलांटी किंवा उकार नाही.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या नियमानुसार \'बाहुली\' या शब्दाचे उपान्त्य अक्षर कोणते आहे?\",\"options\":[\"बा\",\"हु\",\"ली\",\"ल\"],\"answer\":1,\"explain\":\"\'बाहुली\' या शब्दात शेवटून दुसरे अक्षर \'हु\' आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"शब्दाला प्रत्यय लागल्यावर सामान्यरूपातील नामाचे उपान्त्य अक्षर ऱ्हस्व होत नाही, हे कशाचे उदाहरण आहे?\",\"options\":[\"मुख्य नियमाचे\",\"बाराखडीचे\",\"नियमाच्या अपवादाचे\",\"दीर्घ स्वराचे\"],\"answer\":2,\"explain\":\"प्रत्यय लागल्यावर उपान्त्य अक्षर ऱ्हस्व न होणे हा मुख्य नियमाला अपवाद आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता शब्द नियमानुसार अचूक लिहिला आहे?\",\"options\":[\"खजीना\",\"खजिना\",\"खजीनाा\",\"खजीन\"],\"answer\":1,\"explain\":\"शेवटचे अक्षर \'ना\' दीर्घ असल्याने उपान्त्य \'जि\' ऱ्हस्व असणे आवश्यक आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"\'बहिणीला\' या शब्दात \'ही\' हे अक्षर ऱ्हस्व का झाले नाही?\",\"options\":[\"कारण तो शब्द दीर्घ आहे\",\"कारण शब्दाला प्रत्यय लागला असून ते सामान्यरूप आहे\",\"कारण तो बाराखडीतील शब्द नाही\",\"कारण \'ला\' हे अक्षर ऱ्हस्व आहे\"],\"answer\":1,\"explain\":\"सामान्यरूपातील नामाचे उपान्त्य अक्षर ऱ्हस्व होत नाही हा अपवाद येथे लागू होतो.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"बाराखडीतील कोणती चिन्हे \'दीर्घ स्वरान्त\' म्हणून ओळखली जातात?\",\"options\":[\"फक्त काना\",\"फक्त वेलांटी\",\"काना, मात्रा, वेलांटी, उकार\",\"केवळ जोडाक्षरे\"],\"answer\":2,\"explain\":\"काना, मात्रा, वेलांटी, उकार ही बाराखडीतील चिन्हे दीर्घ स्वरान्त असतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'पादुका\' आणि \'बाहुली\' या शब्दांमधील साम्य काय आहे?\",\"options\":[\"दोन्ही शब्दांचे शेवटचे अक्षर ऱ्हस्व आहे\",\"दोन्ही शब्दांचे उपान्त्य अक्षर दीर्घ आहे\",\"दोन्ही शब्दांचे उपान्त्य अक्षर (उकार) ऱ्हस्व आहे\",\"दोन्ही शब्दांना प्रत्यय लागला आहे\"],\"answer\":2,\"explain\":\"दोन्ही शब्दांत शेवटचे अक्षर दीर्घ असल्याने उपान्त्य उकार ऱ्हस्व आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":10,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21949,43,7,'Marathi','mr','धोंडा','[\"धोंडा म्हणजे पाण्याचे वेगवेगळे स्वरूप जसे की समुद्र, नदी, खाडी, तळ, पाण्यवाहिनी इत्यादी.\",\"समुद्र पृथ्वीवरील सर्वात मोठा पाण्याचा संग्रह आहे, ज्यामध्ये लवण पाणी असतो.\",\"नदी पर्वतांवरून सुरू होते आणि समुद्रात जाणारा पाण्याचा प्रवाह आहे.\",\"खाडी म्हणजे समुद्राचे पाणी जिथे थेट पातळ भाग असतो आणि समुद्रात जोडलेला असतो.\",\"तळ म्हणजे पाण्याचा स्थिर संग्रह, ज्याला नदी, पातळी, वarsh पाण्याने भरले जाते.\",\"पाण्यवाहिनी म्हणजे नद्यांशी जोडलेली लहान नदी किंवा पाण्याची धारा.\",\"समुद्राचे पाण्याला खार पाण्य म्हणतात, ज्यामध्ये लवणाची मात्रा जास्त असते.\",\"नदी व तळातील पाण्याला मीठा पाण्य म्हणतात, ज्यामध्ये लवणाची मात्रा कमी असते.\",\"पाण्याचे वेगवेगळे स्वरूप पाण्याचे संचलन (water cycle) मध्ये महत्त्वाची भूमिका बजवतात.\",\"पाण्याचे संरक्षण करणे आवश्यक आहे, कारण पाणी जीवनसाठी अनिवार्य आहे.\"]','[{\"q\":\"राजूचे बाबा स्वभावाने कसे होते?\",\"options\":[\"मृदू आणि प्रेमळ\",\"कडक शिस्तीचे आणि करारी\",\"आळशी आणि शांत\",\"अतिशय विनोदी\"],\"answer\":1,\"explain\":\"उताऱ्यात उल्लेख आहे की राजूचे वडील बाबा पाटील कडक शिस्तीचे आणि करारी होते.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"बाबांनी राजूच्या खिशातील दगडांचे काय केले?\",\"options\":[\"कपाटात ठेवले\",\"शाळेत नेऊन दिले\",\"बाहेर भिरकावून दिले\",\"धुवून स्वच्छ केले\"],\"answer\":2,\"explain\":\"बाबांनी वैतागून राजूच्या खिशातील सर्व दगडागोट्या काढून बाहेर भिरकावले.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राजूला रात्री झोप का येत नव्हती?\",\"options\":[\"त्याला भूक लागली होती\",\"त्याला बाबांची भीती वाटत होती\",\"त्याला बाहेर फेकलेल्या धोंड्याचा विचार येत होता\",\"त्याचा अभ्यास पूर्ण झाला नव्हता\"],\"answer\":2,\"explain\":\"बाबांनी बाहेर फेकलेला तो गुळगुळीत धोंडाच राजूच्या डोळ्यासमोर येत होता, म्हणून त्याला झोप येत नव्हती.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात आलेल्या \'आशाळभूत नजरेने पाहणे\' या वाक्प्रचाराचा अर्थ काय?\",\"options\":[\"रागाने पाहणे\",\"काहीतरी मिळण्याच्या अपेक्षेने पाहणे\",\"भीतीने पाहणे\",\"दुर्लक्ष करून पाहणे\"],\"answer\":1,\"explain\":\"फेकलेल्या धोंड्याकडे राजू अपेक्षेने पाहत राहिला, म्हणून येथे \'आशाळभूत नजर\' हा शब्द वापरला आहे.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राजूने शोधून आणलेला धोंडा घरात आल्यावर कुठे ठेवला?\",\"options\":[\"खिशात\",\"टेबलाच्या ड्रॉवरमध्ये\",\"गादीखाली\",\"दप्तरात\"],\"answer\":1,\"explain\":\"राजूने टेबलाचा ड्रॉवर हळूच उघडून सगळे दगडागोटे एका कोपऱ्यात ठेवले.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"रात्रीच्या अंधारात तो धोंडा राजूला कसा ओळखता आला?\",\"options\":[\"त्याच्या आवाजावरून\",\"त्याच्या सुगंधावरून\",\"त्याच्या अंधुकशा चमकण्यावरून\",\"त्याच्या जडपणावरून\"],\"answer\":2,\"explain\":\"गर्द झुडपात राजूला काहीतरी अंधुकशी चमकती गोष्ट दिसली, जो तो धोंडा होता.\",\"topic\":\"धोंड्याचा शोध\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"र