bloom\":\"evaluate\"},{\"q\":\"मल्लखांबाचे जनक कोणाला मानले जाते?\",\"options\":[\"बाळशास्त्री जांभेकर\",\"बालंभट्टदादा देवधर\",\"महात्मा फुले\",\"लोकमान्य टिळक\"],\"answer\":1,\"explain\":\"पाठात स्पष्ट उल्लेख आहे की बालंभट्टदादा देवधर हे मल्लखांबाचे जनक होत.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"साधा मल्लखांब सामान्यतः कोणत्या लाकडाचा बनवलेला असतो?\",\"options\":[\"आंबा किंवा फणस\",\"बांबू किंवा वेत\",\"शिसवी अथवा सागवानी\",\"पिंपळ किंवा वटवृक्ष\"],\"answer\":2,\"explain\":\"साधा मल्लखांब शिसवी अथवा सागवानी लाकडाचा असतो असे पाठात सांगितले आहे.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मल्लखांबाच्या खुंट्यापासून मानेपर्यंतच्या निमुळत्या होत जाणाऱ्या भागास काय म्हणतात?\",\"options\":[\"अंग\",\"बांड\",\"मान\",\"पाय\"],\"answer\":0,\"explain\":\"मल्लखांबाच्या खुंट्यापासून मानेपर्यंतच्या निमुळत्या भागाला \'अंग\' म्हणतात.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मल्लखांबावरील कौशल्यांचे एकूण किती प्रकारांत वर्गीकरण केले आहे?\",\"options\":[\"दहा\",\"बारा\",\"सोळा\",\"वीस\"],\"answer\":2,\"explain\":\"पाठात मल्लखांबावरील कौशल्यांचे सोळा प्रकारांत वर्गीकरण केल्याचे नमूद आहे.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या आकृतीत मल्लखांबाचा आकार खालून वरच्या दिशेने कसा दिसत आहे?\",\"options\":[\"रुंद होत जाणारा\",\"निमुळता होत जाणारा\",\"वाकडा झालेला\",\"समान जाडीचा\"],\"answer\":1,\"explain\":\"आकृतीत आणि मजकुरात स्पष्ट आहे की मल्लखांब वरच्या दिशेने निमुळता होत जातो.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"43\\/106_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत मल्ल ज्या गोलाकृती भागावर बसला आहे, त्या सर्वात वरच्या भागाला काय म्हणतात?\",\"options\":[\"अंग\",\"मान\",\"बांड\",\"खुंटी\"],\"answer\":2,\"explain\":\"मल्लखांबाच्या सर्वात वरच्या गोलाकृती भागास \'बांड\' असे म्हणतात.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"43\\/106_101.jpg\"},{\"q\":\"बालंभट्टदादा देवधर यांनी मल्लखांबाची निर्मिती कोणत्या मुख्य उद्देशाने केली?\",\"options\":[\"केवळ मनोरंजनासाठी\",\"कुस्तीगिरांची ताकद व चपळता वाढवण्यासाठी\",\"झाडावर चढण्याचा सराव करण्यासाठी\",\"नृत्य शिकवण्यासाठी\"],\"answer\":1,\"explain\":\"कुस्तीगिरांच्या अंगी ताकद, चपळता, लवचीकपणा वाढवण्यासाठी याची निर्मिती केली गेली.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मल्लखांबाच्या \'मान\' या भागाचे वैशिष्ट्य काय आहे?\",\"options\":[\"तो सर्वात खालचा भाग असतो\",\"तो गोलाकृती असतो\",\"तो बारीक, निमुळता नसलेला सरळ भाग असतो\",\"तो वेताचा बनलेला असतो\"],\"answer\":2,\"explain\":\"अंगाच्या वर जो बारीक निमुळता नसलेला सरळ भाग असतो, त्याला \'मान\' म्हणतात.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता मल्लखांबाचा \'आताचा\' (आधुनिक) प्रकार आहे?\",\"options\":[\"वेताचा मल्लखांब\",\"हजारी मल्लखांब\",\"यष्टीचा मल्लखांब\",\"दोरीचा मल्लखांब\"],\"answer\":3,\"explain\":\"पाठात दोरीचा मल्लखांब हा \'आताच्या\' प्रकारांमध्ये समाविष्ट केला आहे.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मल्लखांब या व्यायामामुळे शरीराच्या स्नायूंवर काय परिणाम होतो?\",\"options\":[\"स्नायू शिथिल होतात\",\"स्नायूंना ताण पडून ते मजबूत होतात\",\"स्नायू आखडतात\",\"काहीही परिणाम होत नाही\"],\"answer\":1,\"explain\":\"मल्लखांबामुळे शरीराच्या सर्व भागांतील स्नायूंना उत्तम प्रकारे ताण पडून ते मजबूत होतात.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीला आपले रक्ताभिसरण सुधारायचे असेल, तर मल्लखांब का उपयुक्त ठरेल?\",\"options\":[\"कारण तो लाकडाचा असतो\",\"कारण त्यातून शरीराला विश्रांती मिळते\",\"कारण त्यातील कौशल्यांमुळे शरीर लवचीक राहते व आरोग्य सुधारते\",\"कारण तो केवळ महाराष्ट्रात खेळला जातो\"],\"answer\":2,\"explain\":\"मल्लखांबाच्या कौशल्यांमुळे शरीर लवचीक राहते आणि रक्ताभिसरणाचे कार्य सुधारते.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"साध्या मल्लखांबाची उंची साधारणपणे किती असते?\",\"options\":[\"१ ते १.५ मीटर\",\"२ ते २.५ मीटर\",\"४ ते ५ मीटर\",\"१० ते १२ मीटर\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे साध्या मल्लखांबाची उंची २ ते २.५ मीटर असते.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मल्लखांबाच्या \'अंग\' आणि \'मान\' या भागांत कोणता प्रमुख फरक आहे?\",\"options\":[\"अंग सरळ असते तर मान निमुळती असते\",\"अंग निमुळते होत जाते तर मान निमुळती नसते\",\"अंग गोलाकृती असते तर मान चौकोनी असते\",\"अंग वर असते तर मान खाली असते\"],\"answer\":1,\"explain\":\"अंग निमुळते होत जाणारे असते, तर मान हा निमुळता नसलेला सरळ भाग असतो.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता गट मल्लखांबाच्या तीन मुख्य भागांचा अचूक क्रम दर्शवतो?\",\"options\":[\"पाय, पोट, डोके\",\"मूळ, खोड, फांदी\",\"अंग, मान, बांड\",\"खांब, दोरी, वेत\"],\"answer\":2,\"explain\":\"मल्लखांबाचे अंग, मान व बांड असे तीन भाग असतात.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मल्लखांब हा व्यायाम प्रकार प्रामुख्याने कोणत्या राज्याचे वैशिष्ट्य आहे?\",\"options\":[\"गुजरात\",\"कर्नाटक\",\"महाराष्ट्र\",\"मध्य प्रदेश\"],\"answer\":2,\"explain\":\"मल्लखांब हा वैशिष्ट्यपूर्ण असा महाराष्ट्रीय व्यायाम प्रकार आहे.\",\"topic\":\"मल्लखांब\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"शब्द कसा बनतो म्हणजे सिद्ध होतो, हे पाहणे यास काय म्हणतात?\",\"options\":[\"शब्दरचना\",\"शब्दसिद्धी\",\"शब्दसंग्रह\",\"शब्दभेद\"],\"answer\":1,\"explain\":\"उताऱ्यातील व्याख्येनुसार, शब्द कसा बनतो हे पाहणे म्हणजे शब्दसिद्धी होय.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मराठी भाषेत प्रामुख्याने किती प्रमुख प्रकारांतील शब्द आहेत?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"मराठीत तत्सम, तद्भव, देशी व परभाषीय असे चार प्रमुख प्रकारांतील शब्द आहेत.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"संस्कृत भाषेतील शब्द जसेच्या तसे, काहीही बदल न होता मराठीत येतात, त्यांना काय म्हणतात?\",\"options\":[\"तद्भव शब्द\",\"देशी शब्द\",\"परभाषीय शब्द\",\"तत्सम शब्द\"],\"answer\":3,\"explain\":\"रूपात बदल न होता येणाऱ्या संस्कृत शब्दांना तत्सम शब्द म्हणतात.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत \'जल\' आणि \'पुष्प\' हे शब्द कोणत्या शब्दप्रकाराची उदाहरणे म्हणून दर्शवले आहेत?\",\"options\":[\"तद्भव शब्द\",\"तत्सम शब्द\",\"देशी शब्द\",\"परभाषीय शब्द\"],\"answer\":1,\"explain\":\"आकृती १ मध्ये हे शब्द तत्सम शब्द म्हणून दिले आहेत.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"43\\/108_101.jpg\"},{\"q\":\"संस्कृत शब्दांच्या रूपात बदल होऊन मराठीत आलेल्या शब्दांना काय म्हणतात?\",\"options\":[\"तत्सम शब्द\",\"तद्भव शब्द\",\"देशी शब्द\",\"परभाषीय शब्द\"],\"answer\":1,\"explain\":\"रूपात बदल होऊन मराठीत येणाऱ्या संस्कृत शब्दांना तद्भव शब्द म्हणतात.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'दुग्ध\' या संस्कृत शब्दापासून मराठीत कोणता तद्भव शब्द तयार झाला आहे?\",\"options\":[\"दही\",\"दूध\",\"दुभते\",\"दुग्धालय\"],\"answer\":1,\"explain\":\"उताऱ्यातील उदाहरणाप्रमाणे दुग्ध (संस्कृत) पासून दूध (तद्भव) शब्द बनला आहे.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीनुसार, खालीलपैकी कोणता शब्द \'देशी शब्द\' या गटात समाविष्ट आहे जो मुख्य उताऱ्यात दिलेला नाही?\",\"options\":[\"चिमणी\",\"वांगे\",\"झोप\",\"दगड\"],\"answer\":1,\"explain\":\"आकृती २ मध्ये \'वांगे\' हा शब्द देशी शब्दांच्या उदाहरणात आहे, जो मुख्य मजकुरात नाही.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"43\\/108_102.jpg\"},{\"q\":\"जे शब्द अन्य भाषांतून आलेले नाहीत, अशा मूळ शब्दांना काय म्हणतात?\",\"options\":[\"देशी शब्द\",\"तत्सम शब्द\",\"तद्भव शब्द\",\"परभाषीय शब्द\"],\"answer\":0,\"explain\":\"अन्य भाषांतून न आलेल्या मूळ शब्दांना देशी शब्द म्हणतात.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'बटाटा\' आणि \'पगार\' हे शब्द कोणत्या भाषेतून मराठीत आले आहेत?\",\"options\":[\"फारसी\",\"अरबी\",\"पोर्तुगीज\",\"इंग्रजी\"],\"answer\":2,\"explain\":\"उताऱ्यातील माहितीनुसार बटाटा आणि पगार हे पोर्तुगीज शब्द आहेत.\",\"topic\":\"शब्दसिद्धी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'मेहनत\', \'इनाम\' आणि \'हुकूम\' हे शब