ons\":[\"गृहपाठ\",\"स्वयंअध्ययन\",\"केवळ वाचन\",\"परीक्षा\"],\"answer\":1,\"explain\":\"उताऱ्याच्या शेवटी \'स्वयंअध्ययनाचा समावेश\' असे दिले आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"apply\"},{\"q\":\"सहज व सोप्या अध्ययनासाठी साहित्यात कशाचा वापर केला आहे?\",\"options\":[\"कठिन शब्दांचा\",\"अभिनव कल्पनांचा\",\"केवळ प्रश्नांचा\",\"मोठ्या परिच्छेदांचा\"],\"answer\":1,\"explain\":\"उताऱ्यात \'सहज व सोप्या अध्ययनासाठी अभिनव कल्पना वापर\' असे दिले आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"understand\"},{\"q\":\"अध्ययनाचे सखोलीकरण करण्यासाठी साहित्यात काय समाविष्ट आहे?\",\"options\":[\"प्रगतिक्षम अध्ययनाचे सखोलीकरण\",\"केवळ पाठांतर\",\"केवळ खेळ\",\"केवळ गाणी\"],\"answer\":0,\"explain\":\"उताऱ्यात \'प्रगतिक्षम अध्ययनाचे सखोलीकरण व आकलनसुकर प्रगती\' असे नमूद आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"analyze\"},{\"q\":\"साहित्यात विविध कृतींसोबत आणखी कशाचा समावेश आहे?\",\"options\":[\"केवळ कविता\",\"चित्रे व आकृत्या\",\"केवळ नकाशे\",\"केवळ नाटके\"],\"answer\":1,\"explain\":\"उताऱ्यात \'विविध कृती, चित्रे, आकृत्या इत्यादींचा समावेश\' असे दिले आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"remember\"},{\"q\":\"विषय योजनेनुसार साहित्यात कशाचा समावेश करण्यात आला आहे?\",\"options\":[\"निर्धारित करण्यात आलेल्या विषयांचा\",\"केवळ आवडीच्या विषयांचा\",\"केवळ खेळांच्या विषयांचा\",\"कठिन विषयांचा\"],\"answer\":0,\"explain\":\"उताऱ्यात \'विषय योजनेनुसार निर्धारित करण्यात आलेला विषयांचा समावेश\' असे म्हटले आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"analyze\"},{\"q\":\"हे ई-लर्निंग साहित्य कोणाकडून उपलब्ध करून दिले जाते?\",\"options\":[\"खाजगी संस्था\",\"ebalbharati\",\"स्थानिक वाचनालय\",\"परदेशी संस्था\"],\"answer\":1,\"explain\":\"उताऱ्याच्या सुरुवातीला \'ebalbharati\' असे नाव दिले आहे.\",\"topic\":\"कृती व स्वयंअध्ययन\",\"part\":25,\"bloom\":\"remember\"},{\"q\":\"ई-लर्निंग साहित्य कोणामार्फत उपलब्ध करून देण्यात येत आहे?\",\"options\":[\"शिक्षण विभाग\",\"पाठ्यपुस्तक मंडळ, बालभारती\",\"खाजगी संस्था\",\"जिल्हा परिषद\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की पाठ्यपुस्तक मंडळ, बालभारती मार्फत हे साहित्य उपलब्ध करून दिले जात आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"remember\"},{\"q\":\"ई-लर्निंग साहित्य कोणत्या इयत्तेच्या विद्यार्थ्यांसाठी उपलब्ध आहे?\",\"options\":[\"५ वी ते १० वी\",\"१ ली ते १० वी\",\"१ ली ते १२ वी\",\"८ वी ते १२ वी\"],\"answer\":2,\"explain\":\"उताऱ्यात इयत्ता १ ली ते १२ वी च्या विद्यार्थ्यांचा उल्लेख आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"remember\"},{\"q\":\"ई-लर्निंग साहित्य कोणत्या माध्यमाच्या विद्यार्थ्यांसाठी उपलब्ध आहे?\",\"options\":[\"केवळ मराठी माध्यम\",\"केवळ इंग्रजी माध्यम\",\"मराठी व इंग्रजी माध्यम\",\"मराठी व हिंदी माध्यम\"],\"answer\":2,\"explain\":\"उताऱ्यात मराठी व इंग्रजी माध्यमाच्या विद्यार्थ्यांसाठी साहित्य असल्याचे म्हटले आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"remember\"},{\"q\":\"ई-लर्निंग साहित्य कोणत्या स्वरूपात (Format) उपलब्ध करून दिले जात आहे?\",\"options\":[\"केवळ ऑडिओ\",\"केवळ व्हिडिओ\",\"ऑडिओ-व्हिज्युअल (Audio-Visual)\",\"केवळ छापील पुस्तके\"],\"answer\":2,\"explain\":\"उताऱ्यात ई-लर्निंग साहित्य (Audio-Visual) असे स्पष्ट दिले आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"understand\"},{\"q\":\"ई-लर्निंग साहित्यासाठी नोंदणी करण्याचा एक मार्ग कोणता आहे?\",\"options\":[\"पत्राद्वारे अर्ज करणे\",\"Q.R Code स्कॅन करणे\",\"थेट कार्यालयात जाणे\",\"ईमेल पाठवणे\"],\"answer\":1,\"explain\":\"उताऱ्यात Q.R Code स्कॅन करून नोंदणी करण्याचा पर्याय दिला आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"apply\"},{\"q\":\"नोंदणी करण्यासाठी कोणते ॲप डाऊनलोड करायचे आहे?\",\"options\":[\"ebalbharati app\",\"e-learning app\",\"Balbharati book app\",\"Google app\"],\"answer\":0,\"explain\":\"उताऱ्यात ebalbharati app डाऊनलोड करण्यास सांगितले आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"apply\"},{\"q\":\"ebalbharati app कोठून डाऊनलोड करायचे आहे?\",\"options\":[\"Facebook\",\"Google play store\",\"YouTube\",\"WhatsApp\"],\"answer\":1,\"explain\":\"उताऱ्यात Google play store वरून ॲप डाऊनलोड करण्याची सूचना दिली आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या माहितीनुसार, ई-लर्निंग साहित्याचा लाभ घेण्यासाठी कोणती प्रक्रिया पूर्ण करणे आवश्यक आहे?\",\"options\":[\"परीक्षा देणे\",\"नोंदणी (Registration) करणे\",\"फी भरणे\",\"पुस्तक खरेदी करणे\"],\"answer\":1,\"explain\":\"साहित्य मिळवण्यासाठी नोंदणी करणे ही मुख्य प्रक्रिया उताऱ्यात सांगितली आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"understand\"},{\"q\":\"जर एखादा विद्यार्थी ११ वीत शिकत असेल, तर त्याला हे साहित्य मिळू शकेल का?\",\"options\":[\"नाही, हे फक्त १० वी पर्यंत आहे\",\"हो, कारण हे १ ली ते १२ वी पर्यंतच्या विद्यार्थ्यांसाठी आहे\",\"नाही, हे फक्त प्राथमिक शाळेसाठी आहे\",\"हो, पण फक्त इंग्रजी माध्यमासाठी आहे\"],\"answer\":1,\"explain\":\"उताऱ्यात १ ली ते १२ वी असा गट दिला असल्याने ११ वीचा विद्यार्थी पात्र आहे.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, \'नोंदणी नोंदवा\' या सूचनेचा योग्य अर्थ काय?\",\"options\":[\"पुस्तकावर नाव लिहिणे\",\"ॲपवर आपली माहिती भरून नोंद करणे\",\"ॲप डिलीट करणे\",\"साहित्य वाचायला सुरुवात करणे\"],\"answer\":1,\"explain\":\"नोंदणी नोंदवणे म्हणजे ई-लर्निंग साहित्यासाठी आपली अधिकृत नोंद (Registration) करणे होय.\",\"topic\":\"नोंदणी प्रक्रिया\",\"part\":27,\"bloom\":\"analyze\"},{\"q\":\"इयत्ता ७ वीच्या मराठी पाठ्यपुस्तकाची किंमत किती आहे?\",\"options\":[\"₹ ४०.००\",\"₹ ४८.००\",\"₹ ५०.००\",\"₹ ५८.००\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की पुस्तकाची किंमत ₹ ४८.०० आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकाची निर्मिती कोणत्या मंडळाने केली आहे?\",\"options\":[\"महाराष्ट्र राज्य माध्यमिक मंडळ\",\"महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती व अभ्यासक्रम संशोधन मंडळ\",\"पुणे विद्यापीठ\",\"शिक्षण विभाग, महाराष्ट्र\"],\"answer\":1,\"explain\":\"पुस्तकाच्या प्रकाशकाचे नाव \'महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती व अभ्यासक्रम संशोधन मंडळ\' असे दिले आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तक मंडळाचे मुख्य कार्यालय कोणत्या शहरात आहे?\",\"options\":[\"मुंबई\",\"नागपूर\",\"पुणे\",\"नाशिक\"],\"answer\":2,\"explain\":\"मजकुरात मंडळाच्या नावापुढे \'पुणे\' या शहराचा उल्लेख आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या मजकुरात पाठ्यपुस्तक मंडळाची किती संकेतस्थळे (websites) दिली आहेत?\",\"options\":[\"एक\",\"दोन\",\"तीन\",\"चार\"],\"answer\":1,\"explain\":\"मजकुरात www.ebalbharati.in आणि www.balbharati.in अशी दोन संकेतस्थळे दिली आहेत.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला पाठ्यपुस्तकाची अधिक माहिती हवी असेल, तर तुम्ही कोठे भेट द्याल?\",\"options\":[\"शाळेत\",\"दुकानात\",\"www.ebalbharati.in या संकेतस्थळावर\",\"ग्रंथालयात\"],\"answer\":2,\"explain\":\"मजकुरात माहितीसाठी संकेतस्थळावर भेट देण्यास सांगितले आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"apply\"},{\"q\":\"इयत्ता ७ वीच्या मराठी पाठ्यपुस्तकाचे नाव काय आहे?\",\"options\":[\"मराठी भारती\",\"बालभारती\",\"कुमारभारती\",\"युवकभारती\"],\"answer\":1,\"explain\":\"मजकुरात \'बालभारती इयत्ता ७ वी (मराठी)\' असा उल्लेख आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तक मंडळाचे पूर्ण नाव काय आहे?\",\"options\":[\"महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती मंडळ\",\"महाराष्ट्र राज्य अभ्यासक्रम संशोधन मंडळ\",\"महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती व अभ्यासक्रम संशोधन मंडळ\",\"महाराष्ट्र राज्य शिक्षण संशोधन मंडळ\"],\"answer\":2,\"explain\":\"मजकुरात मंडळाचे पूर्ण नाव \'महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती व अभ्यासक्रम संशोधन मंडळ\' असे दिले आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"understand\"},{\"q\":\"एका विद्यार्थ्याला अशी दोन पुस्तके विकत घ्यायची असल्यास त्याला एकूण किती रुपये द्यावे लागतील?\",\"options\":[\"₹ ८०.००\",\"₹ ९०.००\",\"₹ ९६.००\",\"₹ १००.००\"],\"answer\":2,\"explain\":\"एका पुस्तकाची किंमत ₹ ४८ आहे, म्हणून दोन पुस्तकांची किंमत ४८ + ४८ = ९६ रुपये होईल.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या मजकुरात \'₹\' हे चिन्ह कशासाठी वापरले आहे?\",\"options\":[\"पुस्तकाची संख्या दर्शवण्यासाठी\",\"पुस्तकाची किंमत दर्शवण्यासाठी\",\"संकेतस्थळाचे नाव दर्शवण्यासाठी\",\"मंडळाचा पत्ता दर्शवण्यासाठी\"],\"answer\":1,\"explain\":\"₹ हे चिन्ह भारतीय रुपयांचे असून ते पुस्तकाची किंमत (४८.००) दर्शवण्यासाठी वापरले आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते संकेतस्थळ पाठ्यपुस्तक मंडळाचे नाही?\",\"options\":[\"www.ebalbharati.in\",\"www.balbharati.in\",\"www.maharashtra.gov.in\",\"दिलेल्या मजकुरात वरीलपैकी पहिले दोन पर्याय आहेत\"],\"answer\":2,\"explain\":\"मजकुरात फक्त ebalbharati आणि balbharati या दोन संकेतस्थळांचा उल्लेख आहे.\",\"topic\":\"प्रकाशक आणि किंमत\",\"part\":29,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(21952,44,7,'Maths','en','Geometrical Constructions','[\"Angle is measured in degrees.  A 40° angle is written as m∠ABC = 40°.\",\"A bisector divides an angle into two equal parts.  If two angles are equal, the bisector ray lies in the middle of the angle.\",\"A perpendicular bisector of a segment is a line that cuts the segment at its midpoint and is perpendicular to it.  All points on a perpendicular bisector are equidistant from the segment’s endpoints.\",\"In any triangle, the three internal angle bisectors meet at a single point called the incentre (I).  The point is inside the triangle.\",\"From the incentre, perpendiculars to each side of the triangle are equal: IA = IB = IC.\",\"In any triangle, the perpendicular bisectors of the three sides meet at a single point called the circumcentre (C).  The point is the centre of the circumscribed circle and is equidistant from all three vertices: CX = CY = CZ.\",\"The circumcentre lies inside an acute triangle, on the hypotenuse of a right triangle, and outside an obtuse triangle.\",\"To construct a triangle when all three side lengths are known, draw one side, then use a compass to draw two arcs from the endpoints with radii equal to the other two sides; their intersection gives the third vertex.\",\"To construct a triangle when two sides and the included angle are known, draw the base, then draw a ray from one endpoint making the given angle; use a compass from the other endpoint to intersect the ray at the third vertex.\",\"To construct a triangle when two angles and the included side are known, draw the side, then draw two rays from its endpoints making the given angles; their intersection gives the third vertex.\",\"If only the three angles are given, a triangle can be drawn but its size is not fixed – any similar triangle satisfies the data.\",\"If only two sides and a non‑included angle are given, a triangle may or may not exist; the given data must satisfy the triangle inequality and the angle must be less than 180° minus the sum of the other two angles.\",\"A line segment AB is congruent to CD if AB = CD in length.  Congruent segments can be superimposed exactly by translation and rotation.\",\"Two angles are congruent if they have the same measure; congruence is independent of arm length.\",\"Two circles are congruent if they have the same radius; they can be superimposed exactly.\",\"The sum of the interior angles of any triangle is 180°.\",\"A right‑angled triangle has one angle of 90°, the side opposite this angle is the hypotenuse.\",\"The perpendicular bisector of the hypotenuse of a right triangle passes through the right‑angle vertex and is the circumcentre.\",\"The perpendicular bisector of a side of an obtuse triangle lies outside the triangle.\",\"The perpendicular bisector of a side of an acute triangle lies inside the triangle.\",\"The angle bisector of a vertex of an isosceles triangle passes through the midpoint of the base.\",\"The perpendicular bisector of the base of an isosceles triangle passes through the vertex.\",\"The intersection of the angle bisectors (incentre) is always inside the triangle.\",\"The intersection of the perpendicular bisectors (circumcentre) is inside, on, or outside the triangle depending on its type.\",\"The distance from the circumcentre to each vertex is the radius of the circumcircle.\"]','[{\"q\":\"In which unit do we measure an angle according to the text?\",\"options\":[\"Centimetres\",\"Degrees\",\"Millimetres\",\"Kilograms\"],\"answer\":1,\"explain\":\"The text states, \'We measure an angle in degrees.\'\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"If the measure of angle ABC is 40 degrees, how is it written in mathematical notation?\",\"options\":[\"angle ABC = 40\",\"m∠ABC = 40°\",\"l(ABC) = 40\",\"deg ∠ABC = 40\"],\"answer\":1,\"explain\":\"The text provides the example: \'If ∠ABC measures 40°, we write it as m∠ABC = 40°.\'\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"What is the primary function of an angle bisector?\",\"options\":[\"It makes the angle 90°\",\"It doubles the size of the angle\",\"It divides an angle into two equal parts\",\"It turns an angle into a line segment\"],\"answer\":2,\"explain\":\"The text defines an angle bisector as something that \'divides an angle into two equal parts.\'\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"If ray BM is the bisector of ∠ABC, which of the following must be true?\",\"options\":[\"∠ABC is a right angle\",\"Ray BM is longer than the angle\",\"Ray BM divides ∠ABC into two equal parts\",\"Ray BM is perpendicular to segment AC\"],\"answer\":2,\"explain\":\"Since BM is the bisector, it performs the function of dividing the angle into two equal parts.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"If m∠ABC = 60° and ray BM is its angle bisector, what would be the measure of each resulting part?\",\"options\":[\"60°\",\"40°\",\"30°\",\"20°\"],\"answer\":2,\"explain\":\"An angle bisector divides the angle into two equal parts; half of 60° is 30°.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"A line segment PS has a length of 4 cm. If line CD is its perpendicular bisector and meets PS at point M, what is the length of segment PM?\",\"options\":[\"4 cm\",\"1 cm\",\"2 cm\",\"8 cm\"],\"answer\":2,\"explain\":\"A bisector divides a segment into two equal parts; half of 4 cm is 2 cm.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"When line CD is the perpendicular bisector of segment PS at point M, what is the measure of ∠CMS?\",\"options\":[\"45°\",\"90°\",\"180°\",\"40°\"],\"answer\":1,\"explain\":\"The term \'perpendicular\' implies that the angle formed at the intersection is 90°.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"Which geometric figure is described as having a specific measurable length like 4 cm in the text?\",\"options\":[\"Line\",\"Ray\",\"Angle\",\"Line segment\"],\"answer\":3,\"explain\":\"The text mentions drawing a \'line segment PS of length 4 cm\'.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"To verify that line CD is the perpendicular bisector of segment PS, which two conditions must be checked at the intersection point M?\",\"options\":[\"m∠CMS = 40° and l(PM) = l(SM)\",\"m∠CMS = 90° and l(PM) = l(SM)\",\"m∠CMS = 180° and l(PS) = 4 cm\",\"m∠CMS = 90° and l(PM) = 4 cm\"],\"answer\":1,\"explain\":\"A perpendicular bisector must be at a right angle (90°) and divide the segment into two equal lengths.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"Based on the text, which of these is NOT listed as something \'learnt in previous classes\'?\",\"options\":[\"Line\",\"Angle bisector\",\"Line segment\",\"Protractor\"],\"answer\":3,\"explain\":\"The text lists line, line segment, angle, and angle bisector, but does not mention the protractor.\",\"topic\":\"Let’s recall\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"When three or more lines pass through the same point, what are they called?\",\"options\":[\"Parallel\",\"Concurrent\",\"Perpendicular\",\"Intersecting\"],\"answer\":1,\"explain\":\"The text states that if three bisectors pass through the same point, they are concurrent.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"In the given activity, what letter is used to name the point of concurrence of the angle bisectors?\",\"options\":[\"P\",\"Q\",\"R\",\"I\"],\"answer\":3,\"explain\":\"The text specifically instructs to name the point of concurrence \'I\'.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"Where is the point of concurrence of the angle bisectors of a triangle located?\",\"options\":[\"On one of the vertices\",\"In the exterior of the triangle\",\"In the interior of the triangle\",\"On one of the sides\"],\"answer\":2,\"explain\":\"The text notes that the point of concurrence of the angle bisectors is in the interior of the triangle.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"Which tool is mentioned in the text to be used for drawing the angle bisectors?\",\"options\":[\"Ruler only\",\"Protractor\",\"Compass\",\"Set square\"],\"answer\":2,\"explain\":\"The text says \'Use a compass to draw the bisectors of all three of its angles.\'\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"What is the relationship between the lengths of the perpendiculars IA, IB, and IC drawn from the point of concurrence to the sides?\",\"options\":[\"IA > IB > IC\",\"IA + IB = IC\",\"IA = IB = IC\",\"IA is half of IB\"],\"answer\":2,\"explain\":\"The text explicitly states: \'Note that IA = IB = IC.\'\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"If the length of perpendicular IA is 2.5 cm, what will be the length of perpendicular IC?\",\"options\":[\"1.25 cm\",\"2.5 cm\",\"5.0 cm\",\"7.5 cm\"],\"answer\":1,\"explain\":\"Since IA = IB = IC, if IA is 2.5 cm, then IC must also be 2.5 cm.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"To which side of triangle PQR is the perpendicular IB drawn?\",\"options\":[\"PQ\",\"QR\",\"PR\",\"PI\"],\"answer\":1,\"explain\":\"The text states to draw perpendiculars IA, IB and IC respectively to sides PQ, QR and PR, meaning IB corresponds to QR.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"Why might a student need to \'extend the bisectors\' while performing the activity?\",\"options\":[\"To make the triangle larger\",\"To ensure they intersect one another\",\"To reach the vertices\",\"To measure the angles\"],\"answer\":1,\"explain\":\"The text suggests extending them \'so that they intersect one another.\'\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"From which point are the perpendiculars IA, IB, and IC drawn to the sides of the triangle?\",\"options\":[\"Vertex P\",\"Vertex Q\",\"The point of concurrence I\",\"The midpoint of the sides\"],\"answer\":2,\"explain\":\"The text says to \'Draw perpendiculars IA, IB and IC respectively from I\'.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"If a student measures IA = 3 cm and IB = 4 cm, what does this indicate about their construction based on the property learned?\",\"options\":[\"The triangle is scalene\",\"The construction is correct\",\"The bisectors were not drawn accurately\",\"The perpendiculars are always different\"],\"answer\":2,\"explain\":\"According to the property IA = IB = IC, so if the measurements are different, the construction is inaccurate.\",\"topic\":\"Angle Bisectors of a Triangle\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"What is the point of concurrence of the perpendicular bisectors of the sides of a triangle called?\",\"options\":[\"Incentre\",\"Circumcentre\",\"Midpoint\",\"Origin\"],\"answer\":1,\"explain\":\"According to the \'Something more\' section, the point of concurrence of perpendicular bisectors is called the circumcentre.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"Which letter is typically used to denote the circumcentre of a triangle?\",\"options\":[\"I\",\"P\",\"C\",\"O\"],\"answer\":2,\"explain\":\"The text states that the circumcentre is shown by the letter \'C\'.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"In the given figure, where is the point of concurrence \'C\' located for the obtuse-angled triangle?\",\"options\":[\"Inside the triangle\",\"On one of the vertices\",\"Outside the triangle\",\"On the longest side\"],\"answer\":2,\"explain\":\"In the first figure, the perpendicular bisectors of the obtuse-angled triangle meet at point C, which is outside the triangle.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"apply\",\"figure_image\":\"44\\/012_101.jpg\"},{\"q\":\"If C is the circumcentre of triangle XYZ, what is the relationship between the distances CX, CY, and CZ?\",\"options\":[\"CX > CY > CZ\",\"CX + CY = CZ\",\"CX = CY = CZ\",\"CX = 2 * CY\"],\"answer\":2,\"explain\":\"The activity notes that the distance between the circumcentre C and the vertices is equal: CX = CY = CZ.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What is the point of concurrence of the angle bisectors of a triangle called?\",\"options\":[\"Circumcentre\",\"Incentre\",\"Centroid\",\"Vertex\"],\"answer\":1,\"explain\":\"The \'Something more\' section defines the point of concurrence of angle bisectors as the incentre.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"In the given figure, what do the lines with arrows passing through the midpoints of the sides represent?\",\"options\":[\"Angle bisectors\",\"Perpendicular bisectors of the sides\",\"Medians of the triangle\",\"Altitudes of the triangle\"],\"answer\":1,\"explain\":\"The figure illustrates the property that perpendicular bisectors of the sides of a triangle are concurrent at point C.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"44\\/012_103.jpg\"},{\"q\":\"If the distance CX from the circumcentre to vertex X is 6 cm, what is the distance CZ to vertex Z?\",\"options\":[\"3 cm\",\"6 cm\",\"12 cm\",\"9 cm\"],\"answer\":1,\"explain\":\"Since CX = CY = CZ, the distance from the circumcentre to any vertex is the same.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"Which property is common to both angle bisectors and perpendicular bisectors of a triangle according to the text?\",\"options\":[\"They are always outside the triangle\",\"They are concurrent\",\"They are shown by the letter \'I\'\",\"They are parallel to the sides\"],\"answer\":1,\"explain\":\"The text states that both the angle bisectors and the perpendicular bisectors of the sides of a triangle are concurrent.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"Based on the activity, what happens to the perpendicular bisectors of an acute-angled triangle?\",\"options\":[\"They never meet\",\"They meet at a point inside the triangle\",\"They meet at a point outside the triangle\",\"They only meet at the vertices\"],\"answer\":1,\"explain\":\"Observation of the acute-angled triangle in the activity (and figure) shows the point of concurrence C lies inside the triangle.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"Which letter is used to represent the incentre of a triangle?\",\"options\":[\"C\",\"A\",\"I\",\"B\"],\"answer\":2,\"explain\":\"The text specifies that the incentre is shown by the letter \'I\'.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"If a student draws the perpendicular bisectors of a triangle and finds they do not meet at a single point, what can be concluded?\",\"options\":[\"The triangle is too small\",\"The construction is inaccurate because they must be concurrent\",\"Perpendicular bisectors only meet in right-angled triangles\",\"The triangle must be obtuse-angled\"],\"answer\":1,\"explain\":\"The text explicitly states that the perpendicular bisectors of the sides of a triangle are concurrent.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"What is the first step mentioned in the activity to study the property of perpendicular bisectors?\",\"options\":[\"Measure the angles of the triangle\",\"Draw an acute-angled and an obtuse-angled triangle using a ruler\",\"Find the incentre of the triangle\",\"Draw a circle around the triangle\"],\"answer\":1,\"explain\":\"Activity step 1 is to use a ruler to draw an acute-angled triangle and an obtuse-angled triangle.\",\"topic\":\"Perpendicular Bisectors of a Triangle\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"What is the first thing drawn on paper before constructing a building?\",\"options\":[\"The roof\",\"The structure of the building\",\"The interior furniture\",\"The garden layout\"],\"answer\":1,\"explain\":\"The text states that before constructing any building, the structure of the building is first drawn on paper.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"Why is a rough sketch of a geometrical construction useful?\",\"options\":[\"It makes it easier to draw the required figure\",\"It is the final step of the construction\",\"It replaces the need for a ruler\",\"It is used to color the triangle\"],\"answer\":0,\"explain\":\"The text mentions that a rough sketch makes it easier to draw the required figure.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"If you are asked to draw $\\\\triangle ABC$ with $l(AB) = 3$ cm and $l(BC) = 3$ cm, how many such triangles can be drawn?\",\"options\":[\"Only one unique triangle\",\"Exactly two triangles\",\"A number of triangles\",\"No triangle can be drawn\"],\"answer\":2,\"explain\":\"The text explicitly states that a number of triangles can be drawn to fulfill these conditions.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"What is required to draw a \'unique\' triangle when two side lengths are given?\",\"options\":[\"A larger piece of paper\",\"A different set of scales\",\"A further condition\",\"A new pencil\"],\"answer\":2,\"explain\":\"The text asks which further condition must be placed to draw a unique triangle using the given information.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"What does a rough sketch help to plan in a geometrical construction?\",\"options\":[\"The cost of the tools\",\"The sequence of the steps\",\"The name of the triangle\",\"The thickness of the paper\"],\"answer\":1,\"explain\":\"According to the text, a rough sketch helps to plan the sequence of the steps in the construction.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"In the building analogy, what is mentioned as being similar to a drawing on paper?\",\"options\":[\"A small model of the building\",\"The bricks used for construction\",\"The workers on the site\",\"The land where the building stands\"],\"answer\":0,\"explain\":\"The text mentions that you might have even seen a small model of some such building, which makes construction easier.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"According to the activity, what are the given measures for sides $AB$ and $BC$?\",\"options\":[\"2 cm and 4 cm\",\"3 cm and 3 cm\",\"5 cm and 5 cm\",\"3 cm and 6 cm\"],\"answer\":1,\"explain\":\"The activity specifies drawing $\\\\triangle ABC$ such that $l(AB) = 3$ cm and $l(BC) = 3$ cm.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"Based on the text, can a unique triangle be drawn if only two side lengths are provided?\",\"options\":[\"Yes, always\",\"No, a number of triangles can be drawn\",\"Yes, but only if the sides are equal\",\"No, because triangles need four sides\"],\"answer\":1,\"explain\":\"The text indicates that without further conditions, a number of triangles can be drawn, not just one unique one.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"What is the relationship between a rough sketch and the required figure?\",\"options\":[\"The rough sketch is drawn after the figure\",\"The rough sketch makes it easier to draw the figure\",\"The rough sketch must be the same size as the figure\",\"The rough sketch is not necessary\"],\"answer\":1,\"explain\":\"The text states that a rough sketch of a geometrical construction makes it easier to draw the required figure.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What is the purpose of the \'Activity\' mentioned in the text?\",\"options\":[\"To measure the height of a building\",\"To see if we can draw triangles when certain measures are given\",\"To calculate the area of a triangle\",\"To learn how to use a compass\"],\"answer\":1,\"explain\":\"The activity starts with \'Let us see if we can draw the triangles when the measures of some sides and angles, are given.\'\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"If a student draws a rough sketch before a construction, what are they primarily doing?\",\"options\":[\"Finishing the task\",\"Planning the sequence of steps\",\"Checking the final answer\",\"Decorating the page\"],\"answer\":1,\"explain\":\"The text states that a rough sketch helps to plan the sequence of the steps in the construction.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"Which of these is compared to a \'rough sketch\' in the context of building construction?\",\"options\":[\"The actual building\",\"The structure drawn on paper\",\"The final paint\",\"The building materials\"],\"answer\":1,\"explain\":\"The text draws a parallel between the structure of a building drawn on paper and a rough sketch of a geometrical construction.\",\"topic\":\"Construction of a Triangle\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"What is the first thing we should do before starting the actual construction of a triangle?\",\"options\":[\"Draw the final arcs\",\"Draw a rough figure quickly\",\"Measure the angles\",\"Draw a circle\"],\"answer\":1,\"explain\":\"The text states that we should draw a rough figure quickly and show the given information in it as accurately as possible.\",\"topic\":\"Triangle Construction: Three Sides\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"In the rough figure for triangle construction, how should the longest side be represented?\",\"options\":[\"It should be drawn as the shortest side\",\"It should be drawn as a dotted line\",\"It should be shown as the longest side\",\"It should not be shown at all\"],\"answer\":2,\"explain\":\"According to the text, in the rough figure, the longest side (like XY in the example) should be the longest side.\",\"topic\":\"Triangle Construction: Three Sides\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"In the example provided, which segment is drawn as the base of ∆XYZ?\",\"options\":[\"seg YZ\",\"seg XZ\",\"seg XY\",\"seg ZX\"],\"answer\":2,\"explain\":\"Step 1 of the construction steps states that segment XY of length 6 cm is drawn as the base.\",\"topic\":\"Triangle Construction: Three Sides\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"Which tool is used to draw an arc by opening it to a specific length like 5 cm?\",\"options\":[\"Protractor\",\"Ruler only\",\"Compass\",\"Set square\"],