ic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"अमरवेल या वनस्पतीला \'संपूर्ण परजीवी\' का म्हटले जाते?\",\"options\":[\"ती जमिनीवर वाढते म्हणून\",\"तिच्यात हरितद्रव्य नसल्याने ती पूर्णपणे आश्रयी वनस्पतीवर अवलंबून असते म्हणून\",\"ती कीटक खाऊन जगते म्हणून\",\"ती बुरशीला अन्न पुरवते म्हणून\"],\"answer\":1,\"explain\":\"हरितद्रव्य नसल्याने अमरवेल अन्नासाठी पूर्णपणे दुसऱ्या वनस्पतीवर अवलंबून असते.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"कीटकभक्षी वनस्पती प्रामुख्याने कोणत्या घटकाचा अभाव असलेल्या जमिनीत वाढतात?\",\"options\":[\"ऑक्सिजन\",\"फॉस्फरस\",\"नायट्रोजन संयुगे\",\"पोटॅशियम\"],\"answer\":2,\"explain\":\"नायट्रोजनची कमतरता भरून काढण्यासाठी या वनस्पती कीटक खातात.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"ड्रॉसेरा बर्मानी या वनस्पतीचा शोध इ.स. 1737 मध्ये कोणत्या देशात लागला?\",\"options\":[\"भारत\",\"श्रीलंका\",\"इंडोनेशिया\",\"थायलंड\"],\"answer\":1,\"explain\":\"जोहान्स बर्मन यांनी 1737 मध्ये श्रीलंकेत या वनस्पतीचा शोध लावला.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"मृतोपजीवी वनस्पती मृत अवशेषांपासून अन्न कसे मिळवतात?\",\"options\":[\"थेट गिळून\",\"पाचकस्रव सोडून कार्बनी पदार्थांचे द्रावण शोषून\",\"प्रकाशसंश्लेषण करून\",\"कीटकांना पकडून\"],\"answer\":1,\"explain\":\"त्या मृत अवशेषांवर पाचकस्रव सोडतात आणि तयार झालेले द्रावण शोषतात.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"सहजीवी पोषणात बुरशी शैवालाला खालीलपैकी काय पुरवते?\",\"options\":[\"अन्न व साखर\",\"निवारा, पाणी व क्षार\",\"केवळ हरितद्रव्य\",\"केवळ ऑक्सिजन\"],\"answer\":1,\"explain\":\"बुरशी शैवालाला निवारा, पाणी व क्षार पुरवते, तर शैवाल अन्न पुरवते.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या ठिकाणी जमिनीतील नायट्रोजनचे प्रमाण अत्यंत कमी असेल, तर तिथे खालीलपैकी कोणती वनस्पती जगण्याची शक्यता जास्त आहे?\",\"options\":[\"अमरवेल\",\"भूछत्र\",\"ड्रॉसेरा बर्मानी\",\"दगडफूल\"],\"answer\":2,\"explain\":\"ड्रॉसेरा ही कीटकभक्षी वनस्पती नायट्रोजनच्या अभावातही कीटक खाऊन जगू शकते.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"बुरशी आणि भूछत्रे हे कोणत्या गटातील सजीव आहेत जे मृत अवशेषांवर जगतात?\",\"options\":[\"कवक\",\"शैवाल\",\"कीटकभक्षी\",\"स्वयंपोषी\"],\"answer\":0,\"explain\":\"कवक गटातील बुरशी व भूछत्रे मृतोपजीवी असतात.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"परजीवी वनस्पती (उदा. बांडगूळ) आणि मृतोपजीवी वनस्पती (उदा. भूछत्र) यांच्यातील मुख्य फरक कोणता?\",\"options\":[\"परजीवी जिवंत सजीवांवर वाढतात, तर मृतोपजीवी मृत अवशेषांवर वाढतात\",\"परजीवी स्वतःचे अन्न स्वतः तयार करतात, तर मृतोपजीवी नाही\",\"मृतोपजीवींना हरितद्रव्य असते, तर परजीवींना नसते\",\"दोन्ही वनस्पती कीटक खातात\"],\"answer\":0,\"explain\":\"परजीवी जिवंत आश्रयीवर अवलंबून असतात, तर मृतोपजीवी कुजलेल्या पदार्थांवर जगतात.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"ड्रॉसेरा बर्मानीच्या पानांच्या कडांना असलेल्या केसतंतूंवर चिकट द्रवबिंदू असण्याचा मुख्य उद्देश काय असावा?\",\"options\":[\"पाणी साठवण्यासाठी\",\"कीटकांना आकर्षित करून पकडण्यासाठी\",\"प्रकाशसंश्लेषण करण्यासाठी\",\"वनस्पतीचे संरक्षण करण्यासाठी\"],\"answer\":1,\"explain\":\"चिकट द्रवबिंदूंमुळे कीटक पानाला चिकटतात आणि वनस्पतीला कीटकभक्षण सोपे जाते.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रातील वनस्पती कोणत्या प्रकारचे पोषण दर्शवते?\",\"options\":[\"कीटकभक्षी पोषण\",\"सहजीवी पोषण\",\"मृतोपजीवी पोषण\",\"स्वयंपोषी पोषण\"],\"answer\":1,\"explain\":\"चित्र 4.5 मध्ये दगडफूल दाखवले आहे, जे सहजीवी पोषणाचे उदाहरण आहे.\",\"topic\":\"वनस्पतींमधील इतर पोषण पद्धती\",\"part\":5,\"bloom\":\"apply\",\"figure_image\":\"47\\/038_102.jpg\"},{\"q\":\"दिलेल्या चित्रातील वनस्पती दुसऱ्या झाडाच्या फांदीवर वाढलेली दिसत आहे, अशा वनस्पतीला काय म्हणतात?\",\"options\":[\"स्वयंपोषी वनस्पती\",\"कीटकभक्षी वनस्पती\",\"परजीवी व