c\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"थर्मास फ्लास्कमध्ये बाहेरील संरक्षक बरणी आणि आतील फ्लास्क यांच्यात स्पंज किंवा रबराचे तुकडे का लावलेले असतात?\",\"options\":[\"फ्लास्क गरम करण्यासाठी\",\"फ्लास्कच्या संरक्षणासाठी\",\"हवा आत जाण्यासाठी\",\"फ्लास्कचे वजन वाढवण्यासाठी\"],\"answer\":1,\"explain\":\"आतील फ्लास्कच्या संरक्षणासाठी स्पंज किंवा रबराचे तुकडे वापरले जातात.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"एका काचेच्या बाटलीवर फुगा लावून ती बाटली गरम पाण्यात ठेवली, तर फुग्याचे काय होईल?\",\"options\":[\"फुगा फुटेल\",\"फुगा आकुंचन पावेल\",\"फुगा प्रसरण पावेल (फुगेल)\",\"काहीही बदल होणार नाही\"],\"answer\":2,\"explain\":\"गरम पाण्यामुळे बाटलीतील वायूचे प्रसरण होते, ज्यामुळे फुगा फुगतो.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"थर्मास फ्लास्कला \'दुपदरी फ्लास्क\' का म्हणतात?\",\"options\":[\"त्यात दोन प्रकारचे पदार्थ ठेवता येतात म्हणून\",\"तो दोन रंगांचा असतो म्हणून\",\"त्यात एकांत एक बसवलेल्या दोन नळ्या (दुहेरी भिंत) असतात म्हणून\",\"तो दोन शास्त्रज्ञांनी शोधला म्हणून\"],\"answer\":2,\"explain\":\"हा दुहेरी भिंत असलेला फ्लास्क असून त्यात एकांत एक बसवलेल्या दोन नळ्या असतात.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"सर जेम्स ड्युआर हे कोणत्या देशाचे वैज्ञानिक होते?\",\"options\":[\"अमेरिका\",\"स्कॉटलंड\",\"भारत\",\"जर्मनी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार सर जेम्स ड्युआर हे स्कॉटिश वैज्ञानिक होते.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"थर्मास फ्लास्कची बाहेरील संरक्षक बरणी साधारणपणे कशापासून बनलेली असते?\",\"options\":[\"केवळ काच\",\"केवळ रबर\",\"धातू किंवा प्लॅस्टिक\",\"कापड किंवा कागद\"],\"answer\":2,\"explain\":\"नळ्यांच्या बाहेर धातू किंवा प्लॅस्टिकची संरक्षक बरणी असते.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"थर्मास फ्लास्कचा वापर प्रामुख्याने कशासाठी केला जातो?\",\"options\":[\"पदार्थ लवकर शिजवण्यासाठी\",\"पदार्थ दीर्घकाळ गरम किंवा थंड राहण्यासाठी\",\"पदार्थाची चव बदलण्यासाठी\",\"पदार्थाचे वजन मोजण्यासाठी\"],\"answer\":1,\"explain\":\"चहा, कॉफी यांसारखे पदार्थ गरम किंवा सरबतासारखे पदार्थ थंड राहण्यासाठी थर्मास वापरतात.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"जर थर्मास फ्लास्कमधील निर्वात पोकळीमध्ये हवा भरली गेली, तर काय होईल?\",\"options\":[\"फ्लास्क अधिक मजबूत होईल\",\"पदार्थाचे तापमान टिकून राहण्यास अडथळा येईल\",\"फ्लास्कचा रंग बदलेल\",\"काहीही फरक पडणार नाही\"],\"answer\":1,\"explain\":\"निर्वात पोकळी उष्णता रोखण्यासाठी असते, हवा भरल्यास उष्णतेचे वहन होऊन तापमान लवकर बदलेल.\",\"topic\":\"थर्मास फ्लास्क (दुपदरी फ्लास्क)\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"जेव्हा एखादा पदार्थ वापरून झाल्यावर टाकाऊ ठरतो, तेव्हा त्याला काय म्हणतात?\",\"options\":[\"घनकचरा\",\"द्रव कचरा\",\"वायू कचरा\",\"उपयुक्त पदार्थ\"],\"answer\":0,\"explain\":\"मजकुराप्रमाणे, वापरून झाल्यावर टाकाऊ ठरणाऱ्या पदार्थाला घनकचरा म्हणतात.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"घनकचरा व्यवस्थापनाच्या कार्यात खालीलपैकी कोणत्या गोष्टीचा समावेश होतो?\",\"options\":[\"कचरा साठवून ठेवणे\",\"कचरा जाळून टाकणे\",\"कचरा कमी करणे\",\"कचरा इतरत्र फेकणे\"],\"answer\":2,\"explain\":\"कचरा कमी करणे, पुनर्वापर करणे आणि प्रक्रिया करणे ही व्यवस्थापनाची कार्ये आहेत.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"कचरा व्यवस्थापनामुळे आरोग्यावर कोणता सकारात्मक परिणाम होतो?\",\"options\":[\"रोगराई वाढते\",\"रोगराई कमी होते\",\"आरोग्य बिघडते\",\"काहीच फरक पडत नाही\"],\"answer\":1,\"explain\":\"कचरा व्यवस्थापनामुळे रोगराई पसरण्यास प्रतिबंध होतो आणि ती कमी होते.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"कचऱ्यापासून खालीलपैकी काय निर्माण करता येते असे मजकुरात नमूद केले आहे?\",\"options\":[\"पाणी\",\"ऊर्जा\",\"हवा\",\"खनिज\"],\"answer\":1,\"explain\":\"घनकचरा व्यवस्थापनाच्या महत्त्वामध्ये कचऱ्यापासून ऊर्जा निर्मितीचा उल्लेख आहे.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"कचरा व्यवस्थापनामुळे पर्यावरणाचा कोणता फायदा होतो?\",\"options\":[\"प्रदूषण वाढते\",\"जमीन कमी होते\",\"प्रदूषण कमी होते\",\"पाऊस पडतो\"],\"answer\":2,\"explain\":\"कचरा व्यवस्थापनामुळे पर्यावरणाचे प्रदूषण कमी होण्यास मदत होते.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"कचरा व्यवस्थापनामुळे आर्थिक क्षेत्रात कोणता बदल होतो?\",\"options\":[\"बेरोजगारी वाढते\",\"रोजगार निर्मिती होते\",\"व्यवसाय बंद पडतात\",\"खर्च वाढतो\"],\"answer\":1,\"explain\":\"कचरा व्यवस्थापनाच्या प्रक्रियेमुळे नवीन रोजगाराच्या संधी निर्माण होतात.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"एखाद्या वस्तूचा वापर झाल्यानंतर ती फेकून न देता पुन्हा वापरणे, याला व्यवस्थापनाच्या भाषेत काय म्हणतात?\",\"options\":[\"प्रदूषण\",\"पुनर्वापर\",\"ऊर्जा निर्मिती\",\"रोगराई\"],\"answer\":1,\"explain\":\"वापरलेल्या वस्तूचा पुन्हा वापर करणे म्हणजे पुनर्वापर (Reuse) होय.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या शहरात कचरा व्यवस्थापन योग्य प्रकारे केले नाही, तर काय होईल?\",\"options\":[\"प्रदूषण कमी होईल\",\"रोजगार वाढेल\",\"रोगराई पसरण्याची शक्यता वाढेल\",\"ऊर्जा बचत होईल\"],\"answer\":2,\"explain\":\"कचऱ्यामुळे रोगराई पसरते, त्यामुळे व्यवस्थापन नसल्यास ती वाढेल.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"घनकचरा व्यवस्थापनाच्या व्याख्येनुसार, कचऱ्यावर प्रक्रिया केल्यानंतर काय करणे अपेक्षित आहे?\",\"options\":[\"तो कचरा फेकून देणे\",\"त्याचा योग्य प्रकारे वापर करणे\",\"तो कचरा साठवून ठेवणे\",\"त्याचे प्रदूषण करणे\"],\"answer\":1,\"explain\":\"कचऱ्यावर प्रक्रिया करून त्याचा योग्य प्रकारे वापर करणे हे व्यवस्थापनाचे कार्य आहे.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणती कृती घनकचरा व्यवस्थापनाच्या उद्दिष्टांशी विसंगत (चुकीची) आहे?\",\"options\":[\"कचऱ्यापासून ऊर्जा मिळवणे\",\"कचऱ्याचा पुनर्वापर करणे\",\"कचऱ्याचे प्रमाण वाढवणे\",\"कचऱ्यामुळे होणारे प्रदूषण रोखणे\"],\"answer\":2,\"explain\":\"कचरा कमी करणे हे व्यवस्थापनाचे उद्दिष्ट आहे, वाढवणे नाही.\",\"topic\":\"घनकचरा व्यवस्थापन\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22015,47,7,'Science','mr','आपत्ती व्यवस्थापन','[\"दुष्काळ म्हणजे पाणी व अन्नधान्याचा दीर्घकाळ तुटवडा होणे.\",\"दुष्काळाचे दोन प्रकार – सौम्य दुष्काळ व तीव्र दुष्काळ.\",\"दुष्काळाचे प्रमुख कारण अवर्षण (पर्जन्यमान कमी होणे).\",\"मानवी कारणे: युद्ध, लोकसंख्या वाढ, जलसंधारणाचा अभाव.\",\"पर्जन्यमान व लोकसंख्या यांचा समतोल बिघडल्यास पाण्याचा तुटवडा वाढतो.\",\"पाण्याचा गैरबापर व वृक्षतोडीमुळे धूप व दुष्काळ वाढतो.\",\"पाण्याचा नियोजनपूर्वक वापर व जलसंधारणाने दुष्काळ कमी होतो.\",\"ढगफुटी म्हणजे ढगात साठलेले पाणी अचानक जमिनीवर पडणे.\",\"महापूर म्हणजे मोठ्या प्रमाणात पाणी वाहून येणे, ज्यामुळे इमारती व वाहतूक प्रभावित होते.\",\"बीज पडणे म्हणजे विजेचा आघात, 95% विजा आकाशातच राहतात.\",\"विजेपासून जीवितहानी टाळण्यासाठी उंच ठिकाणे व विजेचे खांब टाळा.\",\"ज्वालामुखीमुळे राख, उष्ण चिखल व वायू बाहेर पडतात, ज्यामुळे वातावरण प्रदूषित होते.\",\"भूकंप व ज्वालामुखीचे उद्रेक महासागरात त्सुनामी लाट निर्माण करतात.\",\"त्सुनामीची उंची 100 फूटापर्यंत जाऊ शकते व किनारी भागात मोठी हानी होते.\",\"आपत्ती व्यवस्थापनात तात्काळ सूचना व आश्रय व्यवस्था महत्त्वाची.\",\"सामाजिक व पर्यावरणीय संतुलन राखण्यासाठी वृक्षलागवड व जलसंधारण आवश्यक.\",\"आपत्तीच्या वेळी सुरक्षित ठिकाण शोधणे व तात्काळ पळून जाणे गरजेचे.\",\"आपत्ती व्यवस्थापनात राष्ट्रीय व स्थानिक स्तरावर आराखडा तयार करणे आवश्यक.\",\"आपत्तीच्या वेळी मोबाइल व विद्युत उपकरणे वापरणे टाळणे सुरक्षित.\",\"आपत्ती व्यवस्थापनात आंतरराष्ट्रीय मदत व स्वयंसेवकांची भूमिका महत्त्वाची.\",\"आपत्तीच्या वेळी घरातील तारे व विजेचे खांब टाळणे सुरक्षित.\",\"आपत्तीच्या वेळी पाण्याच्या स्रोतांची तपासणी व स्वच्छता आवश्यक.\",\"आपत्तीच्या वेळी तात्काळ आपत्कालीन सेवा क्रमांकावर कॉल करणे आवश्यक.\"]','[{\"q\":\"अचानक उद्भवलेली अशी परिस्थिती, ज्यामुळे मोठ्या प्रमाणावर जीवित व वित्तहानी होते, त्याला काय म्हणतात?\",\"options\":[\"नियोजन\",\"आपत्कालीन स्थिती\",\"प्रशिक्षण\",\"अंमलबजावणी\"],\"answer\":1,\"explain\":\"पाठातील व्याख्येनुसार, अचानक उद्भवलेली आणि हानीकारक परिस्थिती म्हणजे आपत्कालीन स्थिती होय.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणती नैसर्गिक आपत्ती आहे?\",\"options\":[\"बॉम्बस्फोट\",\"दंगल\",\"भूकंप\",\"अपघात\"],\"answer\":2,\"explain\":\"भूकंप ही निसर्गामुळे घडणारी घटना असल्याने ती नैसर्गिक आपत्ती आहे.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मानवनिर्मित आपत्तीचे योग्य उदाहरण ओळखा.\",\"options\":[\"त्सुनामी\",\"ज्वालामुखी\",\"वीज कोसळणे\",\"युद्ध\"],\"answer\":3,\"explain\":\"युद्ध हे मानवाच्या कृतीमुळे घडते, म्हणून ती मानवनिर्मित आपत्ती आहे.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"आपत्कालीन स्थितीचे व्यवस्थापन म्हणजे काय?\",\"options\":[\"केवळ आपत्तीची माहिती मिळवणे\",\"सामना करण्यासाठी योजना तयार करणे व अंमलबजावणी करणे\",\"केवळ आपत्तीनंतर नुकसान भरपाई देणे\",\"केवळ जखमींना मदत करणे\"],\"answer\":1,\"explain\":\"आपत्तीचा सामना करण्यासाठी योजना बनवणे आणि तिची अंमलबजावणी करणे म्हणजे व्यवस्थापन होय.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आपत्कालीन स्थितीच्या व्यवस्थापनाचे एकूण किती टप्पे पाठात सांगितले आहेत?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"तीन\"],\"answer\":3,\"explain\":\"पाठात व्यवस्थापनाचे तीन टप्पे (पूर्वीची, दरम्यानची आणि नंतरची कार्यवाही) दिले आहेत.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लोकांना सुरक्षित ठिकाणी हलवणे आणि जखमींना मदत करणे, हा व्यवस्थापनाचा कोणता टप्पा आहे?\",\"options\":[\"आपत्कालीन स्थितीपूर्वीची तयारी\",\"आपत्कालीन स्थितीदरम्यानची कार्यवाही\",\"आपत्कालीन स्थितीनंतरची कार्यवाही\",\"नुकसान भरपाईचा टप्पा\"],\"answer\":1,\"explain\":\"आपत्ती उद्भवल्यावर प्रत्यक्ष केली जाणारी मदत \'दरम्यानच्या कार्यवाही\' मध्ये येते.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"आपत्कालीन स्थितीपूर्वीच्या तयारीत खालीलपैकी कोणत्या गोष्टीचा समावेश होतो?\",\"options\":[\"लोकांना प्रशिक्षण देणे\",\"नुकसानीची भरपाई करणे\",\"अन्न व पाणी पुरवणे\",\"पुन्हा सामान्य जीवन जगण्यास मदत करणे\"],\"answer\":0,\"explain\":\"आपत्ती येण्यापूर्वी लोकांना तयार करण्यासाठी प्रशिक्षण देणे आवश्यक असते.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आपत्कालीन स्थितीनंतरच्या कार्यवाहीचा मुख्य उद्देश काय असतो?\",\"options\":[\"युद्ध सुरू करणे\",\"लोकांना पुन्हा सामान्य जीवन जगण्यास मदत करणे\",\"साहित्याची व्यवस्था करणे\",\"प्रशिक्षण देणे\"],\"answer\":1,\"explain\":\"आपत्ती ओसरल्यानंतर लोकांना पुन्हा स्थिरस्थावर करणे हा नंतरच्या कार्यवाहीचा उद्देश आहे.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"एका गावात पूर येण्याची शक्यता आहे, अशा वेळी \'आपत्कालीन साहित्याची व्यवस्था करणे\' ही कृती कोणत्या टप्प्यात येईल?\",\"options\":[\"आपत्कालीन स्थितीनंतरची कार्यवाही\",\"आपत्कालीन स्थितीदरम्यानची कार्यवाही\",\"आपत्कालीन स्थितीपूर्वीची तयारी\",\"यापैकी नाही\"],\"answer\":2,\"explain\":\"साहित्याची आगाऊ व्यवस्था करणे ही आपत्ती येण्यापूर्वीची तयारी आहे.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"खालील गटातील विसंगत आपत्ती ओळखा: भूकंप, वादळ, आग, त्सुनामी.\",\"options\":[\"भूकंप\",\"वादळ\",\"आग\",\"त्सुनामी\"],\"answer\":2,\"explain\":\"आग ही मानवनिर्मित आपत्ती असू शकते, तर इतर तिन्ही नैसर्गिक आपत्ती आहेत.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"आपत्कालीन स्थितीचे व्यवस्थापन महत्त्वाचे का आहे?\",\"options\":[\"कारण ते जीवित व वित्तहानी कमी करण्यास मदत करते\",\"कारण त्यामुळे आपत्ती येत नाही\",\"कारण त्यामुळे फक्त वित्तहानी वाढते\",\"कारण ते केवळ दंगलीसाठी असते\"],\"answer\":0,\"explain\":\"योग्य व्यवस्थापनामुळे होणारे नुकसान (जीवित व वित्त) कमी करता येते.\",\"topic\":\"आपत्ती व्यवस्थापन व त्याचे प्रकार\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"आ