":\"apply\"},{\"q\":\"मृदू स्नायूंच्या हालचालीचे वैशिष्ट्य काय आहे?\",\"options\":[\"ती अत्यंत जलद असते.\",\"ती आपल्या इच्छेनुसार नियंत्रित करता येते.\",\"ती सावकाश आणि आपोआप होणारी असते.\",\"ती फक्त हाडांच्या हालचालीसाठी असते.\"],\"answer\":2,\"explain\":\"मृदू स्नायूंची हालचाल अनैच्छिक, सावकाश आणि आपोआप होणारी असते.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत शरीराच्या हाताच्या आणि खांद्याच्या भागातून दर्शवलेले स्नायू कोणत्या प्रकारचे आहेत?\",\"options\":[\"मृदू स्नायू\",\"अस्थी स्नायू\",\"हृदयाचे स्नायू\",\"अनैच्छिक स्नायू\"],\"answer\":1,\"explain\":\"आकृतीत हाताचे स्नायू दाखवले आहेत जे हाडांना जोडलेले असतात, म्हणून ते अस्थी स्नायू आहेत.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"analyze\",\"figure_image\":\"47\\/092_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत हृदयाच्या स्नायूंचे प्रमुख कार्य काय दर्शवले आहे?\",\"options\":[\"हाडांना आधार देणे\",\"अन्नाचे पचन करणे\",\"आकुंचन व शिथिलीकरण घडवून आणणे\",\"शरीराला फक्त आकार देणे\"],\"answer\":2,\"explain\":\"आकृती आणि मजकुरानुसार हृदयाचे स्नायू अविरतपणे आकुंचन व शिथिलीकरण करतात.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"understand\",\"figure_image\":\"47\\/092_101.jpg\"},{\"q\":\"जर एखाद्या व्यक्तीला धावायचे असेल, तर प्रामुख्याने कोणत्या स्नायूंचा वापर होईल?\",\"options\":[\"मृदू स्नायू\",\"अस्थी स्नायू\",\"हृदयाचे स्नायू\",\"अनैच्छिक स्नायू\"],\"answer\":1,\"explain\":\"धावण्यासाठी पायांच्या स्नायूंची गरज असते, जे अस्थी स्नायू (ऐच्छिक) आहेत.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"अस्थी स्नायू आणि मृदू स्नायू यांच्यातील मुख्य फरक कोणता?\",\"options\":[\"अस्थी स्नायू अनैच्छिक असतात, तर मृदू स्नायू ऐच्छिक असतात.\",\"अस्थी स्नायू हाडांना जोडलेले असतात, तर मृदू स्नायू आंतरेंद्रियात असतात.\",\"मृदू स्नायूंची हालचाल जलद असते, तर अस्थी स्नायूंची सावकाश असते.\",\"अस्थी स्नायू फक्त हृदयात आढळतात.\"],\"answer\":1,\"explain\":\"अस्थी स्नायू हाडांना जोडलेले असून ऐच्छिक असतात, तर मृदू स्नायू आंतरेंद्रियात असून अनैच्छिक असतात.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"श्वसन आणि रक्ताभिसरण यांसारख्या जीवनावश्यक क्रिया कोणत्या स्नायूंच्या मदतीने होतात?\",\"options\":[\"केवळ ऐच्छिक स्नायू\",\"अनैच्छिक स्नायू\",\"केवळ अस्थी स्नायू\",\"हातांचे स्नायू\"],\"answer\":1,\"explain\":\"श्वसन आणि रक्ताभिसरण या क्रिया आपल्या इच्छेवर अवलंबून नसल्यामुळे त्या अनैच्छिक स्नायूंद्वारे होतात.\",\"topic\":\"स्नायूंचे प्रकार\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"स्नायूंच्या अभ्यासशास्त्राला काय म्हणतात?\",\"options\":[\"Biology\",\"Myology\",\"Physiology\",\"Muscology\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार स्नायूंच्या अभ्यासशास्त्राला Myology असे म्हणतात.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शरीरातील सर्वात मोठा स्नायू कोठे असतो?\",\"options\":[\"दंडात\",\"पाठीत\",\"मांडीमध्ये\",\"पोटात\"],\"answer\":2,\"explain\":\"शरीरातील सर्वात मोठा स्नायू मांडीमध्ये असतो असे पुस्तकात नमूद केले आहे.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"शरीरातील सर्वात लहान स्नायू कोणत्या हाडाला जोडलेला असतो?\",\"options\":[\"फिमर\",\"स्टेप्स\",\"मणका\",\"बरगडी\"],\"answer\":1,\"explain\":\"सर्वात लहान स्नायू कानातील स्टेप्स (Stapes) या हाडाला जोडलेला असतो.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"स्नायूंचा मूलभूत गुणधर्म कोणता आहे?\",\"options\":[\"कठोर होणे\",\"आकुंचन पावणे\",\"लांब होणे\",\"स्थिर राहणे\"],\"answer\":1,\"explain\":\"स्नायूंचा मूलभूत गुणधर्म आकुंचन पावणे हा आहे.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"आपल्या शरीरातील स्नायू नेहमी कसे काम करतात?\",\"options\":[\"स्वतंत्रपणे\",\"गटाने\",\"विश्रांती घेत\",\"केवळ रात्री\"],\"answer\":1,\"explain\":\"आपल्या शरीरातील स्नायू हे नेहमी गटाने काम करतात.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दंडाच्या हाडाच्या वरच्या बाजूला असलेल्या स्नायूंना काय म्हणतात?\",\"options\":[\"त्रिशिरस्क स्नायू\",\"द्विशिरस्क स्नायू\",\"ऐच्छिक स्नायू\",\"हृदय स्नायू\"],\"answer\":1,\"explain\":\"दंडाच्या हाडाच्या वरच्या बाजूला असलेल्या स्नायूंना द्विशिरस्क स्नायू (Biceps) म्हणतात.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जेव्हा गटातील काही स्नायूंचे आकुंचन होते, तेव्हा त्याच गटातील दुसऱ्या स्नायूंचे काय होते?\",\"options\":[\"ते सुद्धा आकुंचन पावतात\",\"ते शिथिल होतात\",\"ते काम करणे थांबवतात\",\"ते कडक होतात\"],\"answer\":1,\"explain\":\"जेव्हा काही स्नायूंचे आकुंचन होते, तेव्हाच त्याच गटातील दुसरे स्नायू शिथिल होतात.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"स्नायूंच्या वाढीसाठी व त्यांची झिज भरून येण्यासाठी आहारात कशाची आवश्यकता असते?\",\"options\":[\"केवळ स्निग्ध पदार्थ\",\"केवळ जीवनसत्त्वे\",\"प्रथिनयुक्त व पिष्टमय पदार्थ\",\"केवळ क्षार\"],\"answer\":2,\"explain\":\"स्नायूंच्या वाढीसाठी व झिज भरून येण्यासाठी आहारात पुरेसे प्रथिनयुक्त व पिष्टमय पदार्थ असावेत.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"व्यायाम करताना श्वासोच्छ्वास जलद का होतो?\",\"options\":[\"कारण फुफ्फुसे थकतात\",\"हृदयाच्या स्नायूंची हालचाल जलद झाल्यामुळे\",\"रक्त कमी पडल्यामुळे\",\"स्नायू शिथिल झाल्यामुळे\"],\"answer\":1,\"explain\":\"व्यायाम करताना हृदयाच्या स्नायूंची हालचाल जलद होते, त्यामुळे श्वासोच्छ्वास जलद होतो.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"पोक काढून बसल्यास शरीराच्या कोणत्या भागावर वाईट परिणाम होऊ शकतो?\",\"options\":[\"हाताची बोटे\",\"पायाचे स्नायू\",\"पाठीचा कणा आणि मणके\",\"कानाचा पडदा\"],\"answer\":2,\"explain\":\"पोक काढून बसल्यास पाठीच्या कण्याचे आजार संभवतात आणि मणक्यात दुखू लागते.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दंडाच्या खालच्या बाजूला असलेल्या स्नायूंना काय म्हणतात?\",\"options\":[\"Biceps\",\"Triceps\",\"Myology\",\"Stapes\"],\"answer\":1,\"explain\":\"हाडाच्या खालच्या बाजूला असलेल्या स्नायूंना त्रिशिरस्क स्नायू (Triceps) म्हणतात.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"जर जठराच्या स्नायूंनी हालचाल केली नाही, तर काय परिणाम होईल?\",\"options\":[\"अन्नाचे पचन नीट होणार नाही\",\"रक्त शुद्ध होईल\",\"हाडे मजबूत होतील\",\"भूक जास्त लागेल\"],\"answer\":0,\"explain\":\"जठराचे स्नायू हालचाल करून अन्न घुसळण्याचे काम करतात, ती हालचाल थांबल्यास पचन प्रक्रियेत अडथळा येईल.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"व्यायामामुळे शरीराला कशाचा भरपूर पुरवठा होतो?\",\"options\":[\"केवळ पाण्याचा\",\"केवळ कार्बन डायऑक्साइडचा\",\"ऑक्सिजन व पोषकतत्वांचा\",\"केवळ प्रथिनांचा\"],\"answer\":2,\"explain\":\"श्वासोच्छ्वास जलद झाल्याने शरीराला ऑक्सिजन व रक्तातील पोषकतत्वांचा भरपूर पुरवठा होतो.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"स्नायू बळकट करण्यासाठी कोणती सवय सर्वात योग्य आहे?\",\"options\":[\"नेहमी पोक काढून बसणे\",\"नियमित व्यायाम करणे\",\"आहारात फक्त गोड पदार्थ खाणे\",\"दिवसभर एकाच जागी बसून राहणे\"],\"answer\":1,\"explain\":\"नियमित व्यायामामुळे स्नायू बळकट होतात असे पाठात सांगितले आहे.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"हाताची बोटे खांद्याला टेकवताना कोपऱ्याच्या भागातील स्नायूंचे काय होते?\",\"options\":[\"ते फक्त शिथिल होतात\",\"त्यांचे आकुंचन व शिथिलीकरण होते\",\"ते काम करणे थांबवतात\",\"त्यांची लांबी वाढते\"],\"answer\":1,\"explain\":\"हात दुमडताना आणि बोटे खांद्याला टेकवताना स्नायूंचे आकुंचन व शिथिलीकरण होते.\",\"topic\":\"स्नायूंचे कार्य व काळजी\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"मानवी शरीरातील अन्ननलिकेची एकूण लांबी सुमारे किती असते?\",\"options\":[\"पाच मीटर\",\"सात मीटर\",\"नऊ मीटर\",\"अकरा मीटर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, अन्ननलिकेची एकूण लांबी सुमारे नऊ मीटर असते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"खाल्लेल्या अन्नाचे रूपांतर विद्राव्य घटकांत होणे आणि ते रक्तात मिसळणे या क्रियेला काय म्हणतात?\",\"options\":[\"श्वसन\",\"पचन\",\"उत्सर्जन\",\"अभिसरण\"],\"answer\":1,\"explain\":\"अन्नाचे विद्राव्य घटकांत रूपांतर होऊन रक्तात मिसळण्याच्या क्रियेला अन्नपचन म्हणतात.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दातांवरील एनॅमल (Enamel) हे कठीण आवरण कशापासून बनलेले असते?\",\"options\":[\"लोहाच्या क्षारांपासून\",\"कॅल्शिअमच्या क्षारांपासून\",\"सोडिअमच्या क्षारांपासून\",\"पोटॅशिअमच्या क्षारांपासून\"],\"answer\":1,\"explain\":\"दातांवरील एनॅमल हे आवरण कॅल्शिअमच्या क्षारांपासून बनलेले असते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"लाळेमध्ये असणाऱ्या टायलीन (अमायलेज) या विकरामुळे स्टार्चचे रूपांतर कोणत्या शर्करेत होते?\",\"options\":[\"ग्लुकोज\",\"सुक्रोज\",\"लॅक्टोज\",\"माल्टोज\"],\"answer\":3,\"explain\":\"टायलीनमुळे पिष्टमय पदार्थाचे (स्टार्च) रूपांतर माल्टोज या शर्करेत होते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत जबड्याच्या सर्वात पुढच्या बाजूला असणाऱ्या दातांचा प्रकार कोणता?\",\"options\":[\"सुळे\",\"दाढा\",\"पटाशीचे दात\",\"उपदाढा\"],\"answer\":2,\"explain\":\"आकृती १२.४ नुसार, जबड्याच्या सर्वात पुढच्या भागात पटाशीचे दात असतात.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"47\\/094_103.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण केल्यास, जबड्याच्या सर्वात शेवटच्या भागात कोणते दात दिसून येतात?\",\"options\":[\"दाढ\",\"सुळे\",\"पटाशीचे दात\",\"उपदाढ\"],\"answer\":0,\"explain\":\"आकृतीमध्ये जबड्याच्या सर्वात मागील भागात दाढा दाखवल्या आहेत.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"remember\",\"figure_image\":\"47\\/094_103.jpg\"},{\"q\":\"खालीलपैकी कोणता अवयव हा अन्ननलिकेचा भाग नसून ती एक पाचकग्रंथी आहे?\",\"options\":[\"जठर\",\"लहान आतडे\",\"यकृत\",\"ग्रासनलिका\"],\"answer\":2,\"explain\":\"यकृत, स्वादुपिंड आणि लाळग्रंथी या पाचकग्रंथी आहेत, ज्या अन्ननलिकेला जोडलेल्या असतात.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"जर आपण भाकरीचा तुकडा बराच वेळ चावून खाल्ला तर तो गोड लागतो, याचे शास्त्रीय कारण काय असू शकते?\",\"options\":[\"भाकरीत साखर असते\",\"लाळेतील टायलीनमुळे स्टार्चचे रूपांतर माल्टोजमध्ये होते\",\"दातांमुळे अन्नाची चव बदलते\",\"जठरातील रसांमुळे अन्न गोड होते\"],\"answer\":1,\"explain\":\"चावताना लाळेतील टायलीन स्टार्चचे रूपांतर माल्टोज या शर्करेत करते, ज्यामुळे अन्न गोड लागते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"अन्ननलिकेतील अवयवांचा सुरुवातीपासूनचा योग्य क्रम कोणता आहे?\",\"options\":[\"मुख -> ग्रासनलिका -> ग्रसनी -> जठर\",\"मुख -> ग्रसनी -> ग्रासनलिका -> जठर\",\"मुख -> जठर -> ग्रासनलिका -> लहान आतडे\",\"ग्रसनी -> मुख -> ग्रासनलिका -> जठर\"],\"answer\":1,\"explain\":\"अन्ननलिकेत मुख, ग्रसनी, ग्रासनलिका, जठर असा क्रम असतो.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दातांच्या प्रकारांबाबत पाठ्यपुस्तकातील माहितीनुसार कोणते विधान योग्य आहे?\",\"options\":[\"सर्व दातांचे कार्य एकसारखेच असते\",\"प्रत्येक प्रकारच्या दाताचे कार्य वैशिष्ट्यपूर्ण असते\",\"फक्त दाढाच अन्न पचनासाठी उपयुक्त असतात\",\"एनॅमल फक्त पटाशीच्या दातांवर असते\"],\"answer\":1,\"explain\":\"दातांचे पटाशीचे, सुळे, दाढा, उपदाढा असे प्रकार असून प्रत्येकाचे कार्य वैशिष्ट्यपूर्ण असते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीला अन्न गिळताना त्रास होत असल्यास, पचनसंस्थेतील मुखानंतरच्या कोणत्या भागात अडथळा असू शकतो?\",\"options\":[\"लहान आतडे\",\"मोठे आतडे\",\"ग्रसनी किंवा ग्रासनलिका\",\"मलाशय\"],\"answer\":2,\"explain\":\"मुखानंतर अन्न ग्रसनी आणि ग्रासनलिकेतून जाते, त्यामुळे तिथे अडथळा असू शकतो.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"अन्नपचनाची सुरुवात शरीरातील कोणत्या अवयवापासून होते?\",\"options\":[\"जठर\",\"मुख\",\"लहान आतडे\",\"ग्रासनलिका\"],\"answer\":1,\"explain\":\"अन्नपचनाची सुरुवात मुखातील दातांच्या कार्यापासून होते.\",\"topic\":\"पचनसंस्था: प्रस्तावना व दात\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"सजीवांच्या शरीरात स्रवणारे आणि विशिष्ट रासायनिक प्रक्रिया घडवून आणणारे पदार्थ म्हणजे काय?\",\"options\":[\"क्षार\",\"विकर (Enzyme)\",\"जीवनसत्त्वे\",\"कर्बोदके\"],\"answer\":1,\"explain\":\"विकर हे सजीवांच्या शरीरात रासायनिक प्रक्रिया घडवून आणणारे उत्प्रेरक असतात.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"विकरे रासायनिकदृष्ट्या प्रामुख्याने कोणत्या प्रकारचे पदार्थ असतात?\",\"options\":[\"स्निग्ध पदार्थ\",\"कर्बोदके\",\"प्रथिने\",\"क्षार\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, विकरे ही एक प्रकारची प्रथिने असतात.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मानवी शरीरातील सर्वात मोठी ग्रंथी कोणती आहे?\",\"options\":[\"स्वादुपिंड\",\"लाळग्रंथी\",\"जाठरग्रंथी\",\"यकृत\"],\"answer\":3,\"explain\":\"यकृत ही शरीरातील सर्वात मोठी ग्रंथी असून तिला भरपूर रक्तपुरवठा होतो.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"ग्रासनलिकेचे (Esophagus) पचनसंस्थेतील मुख्य कार्य काय आहे?\",\"options\":[\"अन्नाचे पचन करणे\",\"अन्न पुढे ढकलणे\",\"पाण्याचे शोषण करणे\",\"विकर स्रवणे\"],\"answer\":1,\"explain\":\"ग्रासनलिका घशापासून जठरापर्यंत असून ती अन्न पुढे ढकलण्याचे कार्य करते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"यकृताचे मुख्य कार्य खालीलपैकी कोणते आहे?\",\"options\":[\"प्रथिनांचे विघटन करणे\",\"ग्लुकोजचा साठा करणे\",\"पाण्याचे शोषण करणे\",\"अन्न चावणे\"],\"answer\":1,\"explain\":\"यकृताचे मुख्य कार्य म्हणजे ग्लुकोजचा साठा करणे हे आहे.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीने तेलकट (स्निग्ध) पदार्थ खाल्ल्यास, त्याच्या पचनास कोणता रस मदत करतो?\",\"options\":[\"लाळ\",\"जाठररस\",\"पित्तरस\",\"म्यूकस\"],\"answer\":2,\"explain\":\"स्निग्ध पदार्थांच्या पचनास यकृताने स्रवलेल्या पित्तरसामुळे मदत होते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"जठरामध्ये अन्नाचे पचन होताना ते आम्लधर्मी (Acidic) का होते?\",\"options\":[\"पित्तरसामुळे\",\"हायड्रोक्लोरिक आम्ल मिसळल्यामुळे\",\"लाळेमुळे\",\"पाण्यामुळे\"],\"answer\":1,\"explain\":\"जाठररसातील हायड्रोक्लोरिक आम्ल, पेप्सिन आणि म्यूकस मिसळल्यामुळे अन्न आम्लधर्मी होते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"लहान आतड्याची लांबी साधारणपणे किती असते?\",\"options\":[\"१.५ मीटर\",\"३ मीटर\",\"६ ते ७ मीटर\",\"१० मीटर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात नमूद केल्याप्रमाणे लहान आतडे सुमारे ६ ते ७ मीटर लांब असते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"अन्नपचनातून मिळालेले पोषक पदार्थ रक्तात शोषण्याचे काम कोठे होते?\",\"options\":[\"जठर\",\"लहान आतडे\",\"मोठे आतडे\",\"ग्रासनलिका\"],\"answer\":1,\"explain\":\"अन्नपचनातून मिळालेले पोषक पदार्थ रक्तात शोषण्याचे काम लहान आतड्यामध्ये होते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"मोठ्या आतड्याचे मुख्य कार्य कोणते आहे?\",\"options\":[\"प्रथिनांचे पचन\",\"ग्लुकोज साठवणे\",\"केवळ पाण्याचे शोषण\",\"अन्न घुसळणे\"],\"answer\":2,\"explain\":\"मोठ्या आतड्यात फक्त पाण्याचे शोषण होते.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"यकृत आणि पित्ताशय यांच्यातील संबंधाबाबत कोणते विधान योग्य आहे?\",\"options\":[\"पित्ताशय पित्तरस तयार करते आणि यकृत तो साठवते\",\"यकृत पित्तरस स्रवते आणि पित्ताशय तो साठवते\",\"यकृत आणि पित्ताशय दोन्ही ग्लुकोज साठवतात\",\"यकृत पित्तरस साठवते आणि पित्ताशय तो तयार करते\"],\"answer\":1,\"explain\":\"यकृताने स्रवलेला पित्तरस पित्ताशयामध्ये साठवला जातो.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"जर शरीरातील विकरांची (Enzymes) क्रिया थांबली, तर खालीलपैकी कोणत्या क्रियेवर थेट परिणाम होईल?\",\"options\":[\"रक्तपुरवठा\",\"हाडांची वाढ\",\"चयापचय क्रिया\",\"श्वासोच्छवास\"],\"answer\":2,\"explain\":\"विकरांशिवाय शरीरातील चयापचय क्रिया शक्य होत नाही.\",\"topic\":\"पचनसंस्थेतील इंद्रिये व कार्ये\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"जठरामध्ये प्रामुख्याने कोणत्या घटकाचे विघटन होते?\",\"op