न आतड्यात आंत्ररस पिष्टमय पदार्थांचे ग्लुकोजमध्ये रूपांतर करतो.\",\"topic\":\"पचनसंस्थेतील ग्रंथी व कार्ये (तक्ता)\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"जठरातील \'पेप्सिन\' हे विकर अन्नातील कोणत्या घटकावर प्रक्रिया करते?\",\"options\":[\"पिष्टमय पदार्थ\",\"प्रथिने\",\"मेद\",\"जीवनसत्त्वे\"],\"answer\":1,\"explain\":\"पेप्सिन प्रथिनांचे विघटन करण्याचे कार्य करते.\",\"topic\":\"पचनसंस्थेतील ग्रंथी व कार्ये (तक्ता)\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"स्वादुरसातील \'अमायलेज\' हे विकर कोणत्या पदार्थावर कार्य करते?\",\"options\":[\"प्रथिने\",\"मेद\",\"पिष्टमय पदार्थ\",\"अमिनो आम्ल\"],\"answer\":2,\"explain\":\"अमायलेज पिष्टमय पदार्थांचे रूपांतर शर्करेत करते.\",\"topic\":\"पचनसंस्थेतील ग्रंथी व कार्ये (तक्ता)\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"पचनसंस्थेतील कोणत्या भागात मेदाचे रूपांतर मेदाम्ल व ग्लिसरॉलमध्ये होते?\",\"options\":[\"तोंड व जठर\",\"जठर व यकृत\",\"स्वादुपिंड व लहान आतडे\",\"केवळ जठर\"],\"answer\":2,\"explain\":\"स्वादुरस आणि आंत्ररस मेदाचे रूपांतर मेदाम्ल व ग्लिसरॉलमध्ये करतात, जे स्वादुपिंड आणि लहान आतड्याशी संबंधित आहेत.\",\"topic\":\"पचनसंस्थेतील ग्रंथी व कार्ये (तक्ता)\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"जागतिक आरोग्य दिन कोणत्या तारखेला साजरा केला जातो?\",\"options\":[\"३१ मे\",\"७ एप्रिल\",\"१ मे\",\"५ जून\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार ७ एप्रिल हा जागतिक आरोग्य दिन आहे.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जागतिक तंबाखूसेवन विरोधी दिवस कधी पाळला जातो?\",\"options\":[\"७ एप्रिल\",\"२ ऑक्टोबर\",\"३१ मे\",\"१५ ऑगस्ट\"],\"answer\":2,\"explain\":\"३१ मे हा दिवस जागतिक तंबाखूसेवन विरोधी दिवस म्हणून ओळखला जातो.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"व्यक्तीचे आरोग्य चांगले आहे असे केव्हा म्हणता येईल?\",\"options\":[\"जेव्हा व्यक्ती खूप श्रीमंत असते\",\"जेव्हा शरीरातील विविध इंद्रिये सुरक्षितपणे कार्य करतात\",\"जेव्हा व्यक्ती फक्त व्यायाम करते\",\"जेव्हा व्यक्ती औषधे घेते\"],\"answer\":1,\"explain\":\"शरीरातील विविध इंद्रिये सुरक्षितपणे कार्य करतात तेव्हा आरोग्य चांगले आहे असे म्हणतात.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"तंबाखू सेवनामुळे खालीलपैकी कोणते विकार उद्भवतात?\",\"options\":[\"ताप आणि सर्दी\",\"उलटी, मळमळ आणि डोकेदुखी\",\"हाडे मोडणे\",\"त्वचेचा रंग बदलणे\"],\"answer\":1,\"explain\":\"तंबाखू सेवनामुळे उलटी, मळमळ आणि डोकेदुखी हे विकार उद्भवतात असे पाठात नमूद आहे.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"तंबाखूचे कण तोंडाच्या आतील त्वचेला चिकटून बसल्यास काय परिणाम होतो?\",\"options\":[\"दात पांढरे होतात\",\"भूक वाढते\",\"तो भाग हळूहळू खराब होऊन इजा पोहोचते\",\"पचन सुधारते\"],\"answer\":2,\"explain\":\"तंबाखूचे कण त्वचेला चिकटून तो भाग खराब करतात व इजा पोहचवतात.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"तंबाखू, मद्यपान आणि धूम्रपान यांचा प्रामुख्याने कोणत्या संस्थेवर घातक परिणाम होतो?\",\"options\":[\"श्वसनसंस्था\",\"रक्ताभिसरण संस्था\",\"पचनसंस्था\",\"अस्थिसंस्था\"],\"answer\":2,\"explain\":\"तंबाखूजन्य पदार्थ, मद्यपान आणि धूम्रपान यांचा पचनसंस्थेवर परिणाम होतो.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर तुमच्या परिसरात कोणी तंबाखू सेवन करत असेल, तर तुमची पहिली भूमिका काय असावी?\",\"options\":[\"त्यांच्याकडे दुर्लक्ष करणे\",\"स्वतः तंबाखू खाणे\",\"पालक किंवा शिक्षकांना याबद्दल सांगणे\",\"त्यांच्याशी भांडण करणे\"],\"answer\":2,\"explain\":\"सभोवती अशा बाबी घडत असतील तर पालक किंवा शिक्षकांना सांगणे ही विद्यार्थ्याची भूमिका आहे.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"तंबाखू सेवनामुळे हिरड्यांना सूज आल्यावर काय त्रास होतो?\",\"options\":[\"चालताना त्रास होतो\",\"तोंडाची हालचाल करताना वेदना होतात\",\"ऐकू येणे कमी होते\",\"झोप येत नाही\"],\"answer\":1,\"explain\":\"हिरड्यांना सूज आल्यामुळे तोंडाची हालचाल करताना वेदना होतात.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"तंबाखू सेवनामुळे घसा आणि आतड्याचा दाह झाल्यास पुढे त्याचे रूपांतर कोणत्या गंभीर आजारात होऊ शकते?\",\"options\":[\"क्षयरोग (TB)\",\"मधुमेह\",\"कॅन्सर\",\"हिवताप\"],\"answer\":2,\"explain\":\"घसा व आतड्याच्या दाहाचे रूपांतर पुढे कॅन्सरमध्ये होऊन मृत्यू ओढवू शकतो.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"शाळा आणि परिसर तंबाखूमुक्त करण्यासाठी कोणती कृती उपयुक्त ठरेल?\",\"options\":[\"तंबाखूविरोधी चित्रे आणि वाक्ये तयार करून लावणे\",\"मैदानावर खेळणे\",\"अभ्यास करणे\",\"झाडे लावणे\"],\"answer\":0,\"explain\":\"तंबाखूविरोधी चित्रे आणि वाक्ये लावल्याने जनजागृती होऊन परिसर तंबाखूमुक्त होण्यास मदत होते.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"व्यक्तिमत्त्व विकासामध्ये खालीलपैकी कशाला अत्यंत महत्त्व आहे?\",\"options\":[\"चांगले कपडे\",\"शारीरिक आरोग्य\",\"मोठा बंगला\",\"महागडा मोबाईल\"],\"answer\":1,\"explain\":\"व्यक्तिमत्त्व विकासामध्ये शारीरिक आरोग्य अत्यंत महत्त्वाचे आहे.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"तंबाखू सेवनामुळे पचनसंस्थेचे कोणते अवयव व्यवस्थित कार्य करेनासे होतात?\",\"options\":[\"फक्त नाक\",\"तोंड, घसा आणि अन्ननलिका\",\"केवळ कान\",\"केवळ पाय\"],\"answer\":1,\"explain\":\"तंबाखूमुळे तोंड, घसा, अन्ननलिका व पचनसंस्थेचे इतर अवयव कार्यात अडथळा येतो.\",\"topic\":\"आरोग्य आणि घातक सवयी\",\"part\":9,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22018,47,7,'Science','mr','बदल : भौतिक व रासायनिक','[\"बदल म्हणजे एखाद्या पदार्थाचे गुणधर्म किंवा स्वरूप बदलणे.\",\"भौतिक बदलात पदार्थाचे रूप बदलते पण रासायनिक संघटन तसंच राहते (उदा. पाण्याचे बाष्पीभवन).\",\"रासायनिक बदलात पदार्थाचे रासायनिक संघटन बदलते, नवीन पदार्थ तयार होतो (उदा. लोखंडाचे गंजणे).\",\"निसर्गनिर्मित बदल म्हणजे निसर्गात स्वतःहून होणारे बदल (फळ पिकणे, पाऊस पडणे).\",\"मानवनिर्मित बदल म्हणजे मानवाने केलेले बदल (भाजी चिरणे, भाकरी भाजणे).\",\"उपयुक्त बदल म्हणजे मानवाला उपयोगी पडणारे बदल (उदा. अन्न शिजवणे).\",\"हानिकारक बदल म्हणजे मानवाला हानी पोहोचवणारे बदल (उदा. लोखंड गंजणे).\",\"परिवर्तनीय बदल म्हणजे उलट सुलट होऊ शकणारे बदल (उदा. मेणबत्ती वितळणे आणि पुन्हा मेण बनवणे).\",\"अपरिवर्तनीय बदल म्हणजे एकदा झाल्यावर परत येऊ न शकणारे बदल (उदा. पिकलेल्या आंब्याचे पुन्हा आंबे होणे).\",\"आवर्ती बदल म्हणजे ठराविक कालावधीनंतर पुन्हा होणारे बदल (उदा. पाऊस, सूर्यप्रकाश).\",\"अनावर्ती बदल म्हणजे एकदा झाल्यावर पुन्हा होण्याची खात्री नसलेले बदल (उदा. भूकंप).\",\"भौतिक बदलाचे उदाहरण: पाण्याचे बाष्पीभवन, वस्तू फुटणे, द्रवाचे अवस्थांतर.\",\"रासायनिक बदलाचे उदाहरण: लोखंडाचे गंजणे, दुधाचे दही होणे, साखरेचे जळणे.\",\"भौतिक बदलात पदार्थाचे गुणधर्म बदलतात पण रासायनिक सूत्र तसंच राहते. रासायनिक बदलात नवीन रासायनिक सूत्र तयार होते.\",\"बदलाचे वर्गीकरण करताना बदलाचे कारण, कालावधी, परिणाम, आणि पदार्थाचे रूप बदलते का हे लक्षात घ्यावे.\"]','[{\"q\":\"जे बदल निसर्गतःच घडून येतात, त्यांना काय म्हणतात?\",\"options\":[\"मानवनिर्मित बदल\",\"नैसर्गिक बदल\",\"अनुकूल बदल\",\"प्रतिकूल बदल\"],\"answer\":1,\"explain\":\"पाठातील व्याख्येनुसार, निसर्गतःच घडून येणाऱ्या बदलांना नैसर्गिक बदल (Natural change) म्हणतात.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता बदल नैसर्गिक बदलाचे उदाहरण आहे?\",\"options\":[\"भाजी चिरणे\",\"विजेचा दिवा लावणे\",\"दूध नासणे\",\"फटाके उडवणे\"],\"answer\":2,\"explain\":\"दूध नासणे हा बदल निसर्गतःच घडून येतो, म्हणून तो नैसर्गिक बदल आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"झाडावरून फळ खाली पडणे हा कोणत्या प्रकारचा बदल आहे?\",\"options\":[\"मानवनिर्मित बदल\",\"कृत्रिम बदल\",\"नैसर्गिक बदल\",\"अनपेक्षित बदल\"],\"answer\":2,\"explain\":\"झाडावरून फळ खाली पडणे ही क्रिया आपोआप किंवा नैसर्गिकरीत्या घडते.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"पाठात दिलेल्या उदाहरणांपैकी कोणता बदल मानवाकडून घडवून आणला जातो?\",\"options\":[\"पाऊस पडणे\",\"भाजी चिरणे\",\"लोखंड गंजणे\",\"फळ पिकणे\"],\"answer\":1,\"explain\":\"भाजी चिरणे ही क्रिया मानवाकडून केली जाते, म्हणून तो मानवनिर्मित बदल आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"फळ पिकणे आणि दूध नासणे या बदलांमध्ये कोणते साम्य आहे?\",\"options\":[\"दोन्ही मानवनिर्मित बदल आहेत\",\"दोन्ही नैसर्गिक बदल आहेत\",\"दोन्हीसाठी विजेची गरज असते\",\"दोन्ही बदल भाजी चिरण्यासारखे आहेत\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे फळ पिकणे आणि दूध नासणे हे दोन्ही निसर्गतःच घडून येणारे बदल आहेत.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात पातेल्यातील पाणी तापवून त्याची वाफ होत आहे, हा बदल घडण्यासाठी कशाची मदत घेतली आहे?\",\"options\":[\"केवळ हवा\",\"शेगडी किंवा उष्णता\",\"पाऊस\",\"नैसर्गिक थंडावा\"],\"answer\":1,\"explain\":\"चित्रात पातेले शेगडीवर ठेवले असून उष्णतेमुळे पाण्याचे वाफेत रूपांतर होत आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"47\\/098_104.jpg\"},{\"q\":\"दिलेल्या चित्रात लाकूड जळताना दिसत आहे, हा बदल कोणत्या कारणाने घडत आहे?\",\"options\":[\"पाऊस पडल्यामुळे\",\"नैसर्गिक थंडाव्यामुळे\",\"मानवाने लाकूड पेटवल्यामुळे\",\"झाडावरून फळ पडल्यामुळे\"],\"answer\":2,\"explain\":\"लाकूड जळणे हा मानवाने घडवून आणलेला किंवा बाह्य कारणाने झालेला बदल आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"47\\/098_106.jpg\"},{\"q\":\"दिलेल्या चित्रात फटाके फुटताना दिसत आहेत, हा बदल नैसर्गिक बदलापेक्षा वेगळा का आहे?\",\"options\":[\"कारण हा बदल आपोआप घडतो\",\"कारण हा बदल मानवनिर्मित आहे\",\"कारण हा बदल झाडावर घडतो\",\"कारण हा बदल पावसाळ्यातच होतो\"],\"answer\":1,\"explain\":\"फटाके उडवणे हा मानवी कृतीतून घडणारा बदल आहे, तो नैसर्गिकरीत्या घडत नाही.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"47\\/098_107.jpg\"},{\"q\":\"पाऊस पडणे हा बदल \'नैसर्गिक\' गटात का मोडतो?\",\"options\":[\"तो मानवाच्या नियंत्रणात असतो\",\"तो निसर्गतःच घडून येतो\",\"तो केवळ भाजी चिरताना घडतो\",\"तो लोखंड गंजण्यासारखा मानवनिर्मित आहे\"],\"answer\":1,\"explain\":\"निसर्गतःच घडणाऱ्या क्रियांना नैसर्गिक बदल म्हणतात, पाऊस पडणे ही अशीच एक क्रिया आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"विजेचा दिवा लावणे हा बदल कोणत्या गटात वर्गीकृत करता येईल?\",\"options\":[\"नैसर्गिक बदल\",\"मानवनिर्मित बदल\",\"आपोआप होणारा बदल\",\"जैविक बदल\"],\"answer\":1,\"explain\":\"विजेचा दिवा लावणे ही मानवी कृती आहे, म्हणून तो मानवनिर्मित बदल आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लोखंड गंजणे आणि भाजी चिरणे या दोन बदलांचे वर्गीकरण करताना मुख्य निकष कोणता असेल?\",\"options\":[\"बदलाचा रंग\",\"बदल नैसर्गिक आहे की मानवनिर्मित\",\"बदल केवळ रात्री होतो की नाही\",\"बदलाचा आकार\"],\"answer\":1,\"explain\":\"पाठात बदलांचे वर्गीकरण करताना ते आपोआप (नैसर्गिक) होतात की मानवामुळे, हा मुख्य विचार केला आहे.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"सभोवतालच्या बदलांचा अभ्यास करताना \'नैसर्गिक बदल\' ओळखण्यासाठी कोणती बाब महत्त्वाची आहे?\",\"options\":[\"तो बदल मानवाने केला असावा\",\"तो बदल विजेवर चालणारा असावा\",\"तो बदल आपोआप किंवा निसर्गतः घडून आलेला असावा\",\"तो बदल केवळ स्वयंपाकघरात व्हावा\"],\"answer\":2,\"explain\":\"नैसर्गिक बदलाचे मुख्य वैशिष्ट्य म्हणजे ते निसर्गतःच किंवा आपोआप घडून येतात.\",\"topic\":\"प्रस्तावना व नैसर्गिक बदल\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"मानवास उपयुक्त असणाऱ्या बदलांना काय म्हणतात?\",\"options\":[\"हानिकारक बदल\",\"उपयुक्त बदल\",\"नैसर्गिक बदल\",\"रासायनिक बदल\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे, ज्या बदलांची आपल्याला उपयुक्तता असते त्यांना उपयुक्त बदल म्हणतात.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मानवास हानी पोहोचवणाऱ्या बदलांना कोणत्या नावाने ओळखले जाते?\",\"options\":[\"उपयुक्त बदल\",\"भौतिक बदल\",\"हानिकारक बदल\",\"मानवनिर्मित बदल\"],\"answer\":2,\"explain\":\"उपयुक्त नसणाऱ्या किंवा मानवास हानी पोहोचवणाऱ्या बदलांना हानिकारक बदल म्हणतात.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दैनंदिन जीवनातील मानवनिर्मित पदार्थ प्रामुख्याने कशासाठी निर्माण केले जातात?\",\"options\":[\"केवळ मनोरंजनासाठी\",\"विशिष्ट उपयोगासाठी किंवा गरजेसाठी\",\"निसर्ग नष्ट करण्यासाठी\",\"बदल टाळण्यासाठी\"],\"answer\":1,\"explain\":\"मानवनिर्मित पदार्थ मानवाच्या विविध गरजा आणि उपयोगासाठी निर्माण केले जातात.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता बदल उपयुक्त बदल या गटात मोडतो?\",\"options\":[\"वादळात झाड पडणे\",\"अन्न शिजवणे\",\"पदार्थ सडणे\",\"पूर येणे\"],\"answer\":1,\"explain\":\"अन्न शिजवणे ही मानवासाठी गरजेची आणि उपयुक्त प्रक्रिया आहे.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पेन्सिलीला टोक करणे हा कोणत्या प्रकारचा बदल आहे?\",\"options\":[\"हानिकारक बदल\",\"उपयुक्त बदल\",\"नैसर्गिक बदल\",\"अनपेक्षित बदल\"],\"answer\":1,\"explain\":\"पेन्सिलीला टोक केल्यामुळे ती लिहिण्यासाठी वापरता येते, म्हणून तो उपयुक्त बदल आहे.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"भाकरी भाजणे हा बदल कोणत्या प्रकारचा आहे?\",\"options\":[\"हानिकारक बदल\",\"उपयुक्त बदल\",\"नैसर्गिक बदल\",\"टाकाऊ बदल\"],\"answer\":1,\"explain\":\"भाकरी भाजल्यामुळे ती खाण्यायोग्य होते, म्हणून हा उपयुक्त बदल आहे.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"\'वादळात उन्मळून पडलेले झाड\' हा बदल हानिकारक का मानला जातो?\",\"options\":[\"कारण तो मानवनिर्मित आहे.\",\"कारण तो मानवास किंवा मालमत्तेस हानी पोहोचवू शकतो.\",\"कारण तो उपयुक्त बदल आहे.\",\"कारण तो पेन्सिल टोक करण्यासारखा आहे.\"],\"answer\":1,\"explain\":\"ज्या बदलांमुळे हानी पोहोचते त्यांना हानिकारक बदल म्हणतात; झाड पडल्याने नुकसान होऊ शकते.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"दुधाचे दही होणे हा बदल मानवासाठी सामान्यतः कसा असतो?\",\"options\":[\"हानिकारक\",\"उपयुक्त\",\"टाकाऊ\",\"अनावश्यक\"],\"answer\":1,\"explain\":\"दही हा खाद्यपदार्थ मानवासाठी उपयुक्त असल्याने दुधाचे दही होणे हा उपयुक्त बदल आहे.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"अन्न शिजवणे हा बदल कोणत्या श्रेणीत येतो?\",\"options\":[\"हानिकारक बदल\",\"उपयुक्त बदल\",\"नैसर्गिक बदल\",\"अनावश्यक बदल\"],\"answer\":1,\"explain\":\"अन्न शिजवणे ही मानवासाठी एक उपयुक्त क्रिया आहे.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"ज्या बदलांची आपल्याला उपयुक्तता नसते, त्यांना काय म्हणतात?\",\"options\":[\"मानवनिर्मित बदल\",\"उपयुक्त बदल\",\"हानिकारक बदल\",\"भौतिक बदल\"],\"answer\":2,\"explain\":\"उपयुक्त नसणाऱ्या बदलांना हानिकारक बदल असे संबोधले जाते.\",\"topic\":\"मानवनिर्मित, उपयुक्त व हानिकारक बदल\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जे बदल घडून येण्यासाठी कमी कालावधी लागतो, त्यास काय म्हणतात?\",\"options\":[\"सावकाश होणारे बदल\",\"शीघ्र होणारे बदल\",\"नैसर्गिक बदल\",\"मानवनिर्मित बदल\"],\"answer\":1,\"explain\":\"मजकुराप्रमाणे, ज्या बदलांना कमी कालावधी लागतो त्यांना शीघ्र होणारे बदल म्हणतात.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"फळ पिकणे हा कोणत्या प्रकारचा बदल आहे?\",\"options\":[\"शीघ्र होणारा बदल\",\"सावकाश होणारा बदल\",\"हानिकारक बदल\",\"मानवनिर्मित बदल\"],\"answer\":1,\"explain\":\"फळ पिकण्याची क्रिया पूर्ण होण्यासाठी जास्त वेळ लागतो, म्हणून तो सावकाश होणारा बदल आहे.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"फुगा फुटणे हा बदल फळ पिकण्याच्या बदलापेक्षा कसा आहे?\",\"options\":[\"जास्त कालावधीचा\",\"समान कालावधीचा\",\"कमी कालावधीचा\",\"अतिशय सावकाश\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की फुगा फुटण्याचा कालावधी फळ पिकण्याच्या कालावधीपेक्षा कितीतरी कमी आहे.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"बदलांचे \'शीघ्र\' आणि \'सावकाश\' असे वर्गीकरण कोणत्या निकषावर आधारित आहे?\",\"options\":[\"बदलाचे स्वरूप\",\"बदलाचा कालावधी\",\"बदलाची उपयुक्तता\",\"बदलाचे कारण\"],\"answer\":1,\"explain\":\"बदल घडून येण्यासाठी लागणाऱ्या वेळेवरून (कालावधी) हे वर्गीकरण केले जाते.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"मजकुरात सुरुवातीला बदलांचे कोणत्या दोन गटात वर्गीकरण करता येईल का, असा प्रश्न विचारला आहे?\",\"options\":[\"भौतिक व रासायनिक\",\"नैसर्गिक व मानवनिर्मित\",\"उपयुक्त व हानिकारक\",\"शीघ्र व सावकाश\"],\"answer\":2,\"explain\":\"मजकुराच्या सुरुवातीला निसर्गनिर्मित व मानवनिर्मित बदलांचे उपयुक्त व हानिकारक असे वर्गीकरण सुचवले आहे.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एखादी क्रिया सेकंदात पूर्ण होत असेल, तर ती कोणत्या गटात मोडेल?\",\"options\":[\"सावकाश होणारे बदल\",\"शीघ्र होणारे बदल\",\"नैसर्गिक बदल\",\"उपयुक्त बदल\"],\"answer\":1,\"explain\":\"कमी कालावधीत घडणाऱ्या क्रियांना शीघ्र बदल म्हणतात.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणता बदल मजकुरात \'सावकाश होणारा बदल\' म्हणून दिला आहे?\",\"options\":[\"फुगा फुटणे\",\"फळ पिकणे\",\"काच फुटणे\",\"दूध नासणे\"],\"answer\":1,\"explain\":\"मजकुरात फळ पिकणे हे सावकाश होणाऱ्या बदलाचे उदाहरण दिले आहे.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"फुगा फुटणे आणि फळ पिकणे यांमधील मुख्य फरक कोणता?\",\"options\":[\"दोन्ही नैसर्गिक आहेत\",\"दोन्ही मानवनिर्मित आहेत\",\"त्यांच्यासाठी लागणारा वेळ भिन्न आहे\",\"दोन्ही उपयुक्त बदल आहेत\"],\"answer\":2,\"explain\":\"या दोन बदलांमधील मुख्य फरक त्यांच्या कालावधीचा (वेळेचा) आहे.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या मजकुरावरून, बदलांचे वर्गीकरण करण्यासाठी कोणता घटक महत्त्वाचा ठरतो?\",\"options\":[\"बदल कोठे घडला\",\"बदल किती वेळात घडला\",\"बदल कोणी घडवला\",\"बदल दिसतो का\"],\"answer\":1,\"explain\":\"शीघ्र आणि सावकाश हे शब्द बदलाच्या वेळेवर किंवा कालावधीवर लक्ष केंद्रित करतात.\",\"topic\":\"शीघ्र व सावकाश होणारे बदल\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मजकुरातील माहितीनुसार, खालीलपैकी कोणते विधान अचूक आहे?\",\"options\":[\"सर्व नैसर्गिक बदल शीघ्र असतात.\",\"फुगा फुटणे हा सावकाश होणारा बदल आहे.\",\"फळ पिकणे हा शीघ्र होणारा बदल आहे.\",\"बदलांचा कालावधी वेगवेगळ