वर खोलवर परिणाम होतो\",\"त्यांचा मानवी जीवनाशी काहीही संबंध नाही\",\"केवळ धूमकेतूंचा मानवी जीवनाशी संबंध असतो\",\"केवळ ग्रहांचा मानवी जीवनाशी संबंध असतो\"],\"answer\":1,\"explain\":\"विज्ञानामुळे सिद्ध झाले आहे की सूर्यमालेचे घटक किंवा ताऱ्यांचा मानवी जीवनाशी काहीही संबंध नाही.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"वैज्ञानिक चाचण्यांमुळे फोल ठरलेल्या कल्पनांवर विश्वास ठेवल्यास कशाचा निरुपयोग होतो?\",\"options\":[\"केवळ वेळेचा\",\"केवळ धनाचा\",\"केवळ शक्तीचा\",\"वेळ, शक्ती आणि धन या तिन्हींचा\"],\"answer\":3,\"explain\":\"अशा कल्पनांवर विश्वास ठेवणे म्हणजे स्वतःच्या वेळेचा, शक्तीचा आणि धनाचा निरुपयोग करणे होय.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर एखादी व्यक्ती ग्रहांच्या स्थितीवरून भविष्यातील संकटांची भीती बाळगत असेल, तर ती व्यक्ती काय करत आहे?\",\"options\":[\"वैज्ञानिक दृष्टिकोन पाळत आहे\",\"खगोलशास्त्राचा अभ्यास करत आहे\",\"स्वतःच्या शक्तीचा आणि वेळेचा निरुपयोग करत आहे\",\"मूलभूत संशोधन करत आहे\"],\"answer\":2,\"explain\":\"वैज्ञानिक चाचण्यांमुळे फोल ठरलेल्या कल्पनांवर विश्वास ठेवणे म्हणजे शक्ती आणि वेळेचा निरुपयोग आहे.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत प्लॅनेटोरियमच्या छताचा आकार कसा दर्शवला आहे?\",\"options\":[\"सपाट (Flat)\",\"त्रिकोणी (Triangular)\",\"घुमटाकार किंवा अर्धवर्तुळाकार (Dome-shaped)\",\"चौकोनी (Square)\"],\"answer\":2,\"explain\":\"आकृतीवरून स्पष्ट होते की प्लॅनेटोरियमचे छत घुमटाकार असते जेणेकरून त्यावर आकाशाचे प्रक्षेपण करता येईल.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"apply\",\"figure_image\":\"47\\/146_101.jpg\"},{\"q\":\"दिलेल्या आकृतीनुसार, प्लॅनेटोरियममध्ये प्रेक्षकांसाठी बसण्याची व्यवस्था कोठे केलेली असते?\",\"options\":[\"छताच्या वरच्या बाजूला\",\"मध्यवर्ती प्रक्षेपण यंत्राच्या सभोवताली\",\"प्लॅनेटोरियमच्या बाहेर\",\"केवळ एका कोपऱ्यात\"],\"answer\":1,\"explain\":\"आकृतीत प्रेक्षकांच्या खुर्च्या मध्यवर्ती यंत्राच्या सभोवताली मांडलेल्या दिसत आहेत.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"analyze\",\"figure_image\":\"47\\/146_101.jpg\"},{\"q\":\"खालीलपैकी कोणत्या शहरात नेहरू प्लॅनेटोरियम नाही असे पाठ्यपुस्तकातील माहितीवरून समजते?\",\"options\":[\"नवी दिल्ली\",\"अलाहाबाद\",\"नागपूर\",\"बंगळूरु\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात नवी दिल्ली, बंगळूरु, अलाहाबाद, मुंबई आणि पुणे यांचा उल्लेख आहे, नागपूरचा नाही.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"वैज्ञानिक युगात ताऱ्यांकडे पाहण्याचा कोणता दृष्टिकोन महत्त्वाचा आहे?\",\"options\":[\"धार्मिक दृष्टिकोन\",\"वैज्ञानिक दृष्टिकोन\",\"काल्पनिक दृष्टिकोन\",\"पारंपारिक दृष्टिकोन\"],\"answer\":1,\"explain\":\"आजच्या वैज्ञानिक युगात या सर्वांकडे विज्ञानाच्या दृष्टिकोनातून पाहणे महत्त्वाचे आहे.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"IUCAA या संक्षिप्त रूपातील \'A\' या अक्षराचा अर्थ काय आहे?\",\"options\":[\"Agriculture\",\"Astronomy\",\"Aerodynamics\",\"Anatomy\"],\"answer\":1,\"explain\":\"IUCAA म्हणजे Inter university centre for astronomy & astrophysics.\",\"topic\":\"संस्थात्मक कार्य व वैज्ञानिक दृष्टिकोन\",\"part\":10,\"bloom\":\"remember\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (22026,49,7,'Geography','mr','ऋतुनिर्मिती (भाग-१)','[\"लाटा म्हणजे समुद्रातील पाण्याची उभी गती.\",\"लाटा वाऱ्याच्या वेगावर अवलंबून असतो.\",\"लाटेची लांबी, उंची व वेग यांच्यात संबंध असतो.\",\"लाटेची लांबी = शीर्ष आणि द्रोणी यांच्यामधील उभे अंतर.\",\"लाटेची उंची = शीर्ष आणि द्रोणी यांच्यामधील उभे अंतर.\",\"लाटा दोन प्रकारे होतो: प्रबाही (उभे) व अप्रबाही (गोड).\",\"प्रबाही लाटा: लाटेची लांबी उंचीपेक्षा जास्त, तरंगे सुटू शकतात.\",\"अप्रबाही लाटा: लाटेची लांबी उंचीपेक्षा कम, तरंगे किनाऱ्यावर थमतात.\",\"लाटेवर फुंकर मारल्यास लाटेची रचना बदलते व लहरी येतात.\",\"सागरी लाटे किनाऱ्याकडे येतात व त्यामुळे किनाराचे अपघात होतो.\",\"लाटेतील ऊर्जा किनाऱ्यापर्यंत घेऊन येते, पाणी पुढे येत नाही.\",\"लाटेचे वेग वाऱ्याच्या वेगावर अवलंबून असतो.\",\"लाटा निर्माण करण्यासाठी पाण्याची सतत उभा गती आवश्यक आहे.\",\"लाटेची लांबी मापण्यासाठी शीर्ष व द्रोणी यांच्यामधील अंतर मापावे.\",\"लाटा निर्माण करताना भांड्याला स्पर्श न करावा किंवा धक्का न लावावा.\"]','[{\"q\":\"पृथ्वीवर दिन व रात्र होण्याचे मुख्य कारण काय?\",\"options\":[\"पृथ्वीचे परिभ्रमण\",\"पृथ्वीचे परिवलन\",\"सूर्याचे फिरणे\",\"चंद्राचे आकर्षण\"],\"answer\":1,\"explain\":\"पृथ्वी स्वतःभोवती फिरते (परिवलन), त्यामुळे दिवस व रात्र होतात.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या सूर्यभोवती प्रदक्षिणा घालण्याच्या क्रियेस काय म्हणतात?\",\"options\":[\"परिवलन\",\"अक्षीय गती\",\"परिभ्रमण\",\"स्थित्यंतर\"],\"answer\":2,\"explain\":\"पृथ्वीच्या सूर्याभोवती फिरण्याच्या क्रियेला परिभ्रमण म्हणतात.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीला सूर्याभोवती एक प्रदक्षिणा पूर्ण करण्यास साधारण किती कालावधी लागतो?\",\"options\":[\"२४ तास\",\"३० दिवस\",\"१ वर्ष\",\"१२ तास\"],\"answer\":2,\"explain\":\"पृथ्वीला सूर्याभोवती एक फेरी पूर्ण करण्यास एक वर्ष (३६५ दिवस) लागतात.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"आपला भारत देश कोणत्या गोलार्धामध्ये स्थित आहे?\",\"options\":[\"दक्षिण गोलार्ध\",\"उत्तर गोलार्ध\",\"पश्चिम गोलार्ध\",\"मध्य गोलार्ध\"],\"answer\":1,\"explain\":\"भौगोलिक स्थानानुसार भारत उत्तर गोलार्धात येतो.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीवर सूर्यकिरणे सर्व ठिकाणी लंबरूप का पडत नाहीत?\",\"options\":[\"पृथ्वीच्या गोलाकार स्वरूपामुळे\",\"ढगांच्या अडथळ्यामुळे\",\"सूर्याच्या उष्णतेमुळे\",\"समुद्रसपाटीमुळे\"],\"answer\":0,\"explain\":\"पृथ्वीचा आकार गोल असल्यामुळे सूर्यकिरणे सर्वत्र लंबरूप पडत नाहीत.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'करून पाहू!\' या कृतीमध्ये कोणत्या महिन्यासाठी सूर्योदय व सूर्यास्ताच्या वेळांची नोंद करण्यास सांगितले आहे?\",\"options\":[\"जानेवारी\",\"मार्च\",\"जून\",\"डिसेंबर\"],\"answer\":2,\"explain\":\"मजकुरात १९ जून महिन्यासाठी तक्ता तयार करण्यास सांगितले आहे.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"सूर्योदय व सूर्यास्ताच्या वेळांची माहिती मिळवण्यासाठी खालीलपैकी कोणत्या साधनाचा वापर मजकुरात सुचवलेला नाही?\",\"options\":[\"दिनदर्शिका\",\"वृत्तपत्र\",\"आंतरजाल (इंटरनेट)\",\"रेडिओ\"],\"answer\":3,\"explain\":\"मजकुरात प्रत्यक्ष निरीक्षण, दिनदर्शिका, वृत्तपत्र आणि इंटरनेटचा उल्लेख आहे, रेडिओचा नाही.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या कृतीनुसार, सूर्योदय व सूर्यास्ताच्या वेळा नोंदवल्यामुळे आपल्याला प्रामुख्याने काय समजण्यास मदत होईल?\",\"options\":[\"हवेचे तापमान\",\"दिवसाचा कालावधी (दिनमान)\",\"पावसाचे प्रमाण\",\"सूर्याचे अंतर\"],\"answer\":1,\"explain\":\"सूर्योदय आणि सूर्यास्ताच्या वेळांमधील फरकावरून दिवसाचा कालावधी समजतो.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही १९ जूनच्या सूर्योदय आणि सूर्यास्ताच्या वेळांची नोंद केली, तर त्या माहितीवरून तुम्ही कोणती चर्चा करू शकाल?\",\"options\":[\"चंद्राच्या कला\",\"दिन व रात्रीच्या कालावधीतील बदल\",\"ग्रहांची स्थिती\",\"समुद्राची भरती-ओहोटी\"],\"answer\":1,\"explain\":\"वेळांच्या नोंदीवरून दिवस मोठा की रात्र मोठी यावर चर्चा करता येते.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीच्या परिभ्रमणामुळे खालीलपैकी कोणती गोष्ट घडते असे मजकुरातील प्रश्नावरून सूचित होते?\",\"options\":[\"दिवस व रात्र होणे\",\"ऋतूंची निर्मिती\",\"भरती-ओहोटी\",\"ग्रहणे\"],\"answer\":1,\"explain\":\"परिभ्रमण आणि पृथ्वीचा कललेला अक्ष यामुळे ऋतूंची निर्मिती होते, जो या पाठाचा मुख्य विषय आहे.\",\"topic\":\"करून पाहू !\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"तक्त्यातील नोंदींवरून प्रामुख्याने काय शोधण्यास सांगितले आहे?\",\"options\":[\"सर्वात मोठा दिन\",\"सर्वात लहान रात्र\",\"पावसाचे प्रमाण\",\"वाऱ्याचा वेग\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील पहिल्या ओळीनुसार तक्त्यातील नोंदींवरून सर्वात मोठा दिन सांगण्यास सांगितले आहे.\",\"topic\":\"निरीक्षण व चर्चा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"रात्रमान काढताना तुम्हांला कोणती गणिती क्रिया करावी लागली असावी?\",\"options\":[\"बेरीज\",\"वजाबाकी\",\"गुणाकार\",\"भागाकार\"],\"answer\":1,\"explain\":\"एकूण २४ तासांतून दिनमान वजा केल्यावर रात्रमान मिळते, म्हणून वजाबाकी करावी लागते.\",\"topic\":\"निरीक्षण व चर्चा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पाठ्यपुस्तकातील सूचनेनुसार कोणत्या दोन महिन्यांतील १९ ते २८ तारखांच्या दिनमानाची नोंद वहीत करायची आहे?\",\"options\":[\"जानेवारी व मार्च\",\"एप्रिल व मे\",\"सप्टेंबर व डिसेंबर\",\"जून व ऑगस्ट\"],\"answer\":2,\"explain\":\"मजकुराच्या शेवटी सप्टेंबर व डिसेंबर महिन्यांच्या नोंदी करण्यास सांगितले आहे.\",\"topic\":\"निरीक्षण व चर्चा\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"तक्त्यातील नोंदीनुसार रात्रमान दररोज कसे दिसते?\",\"options\":[\"नेहमी स्थिर राहते\",\"बदलत जाताना दिसते\",\"फक्त वाढतच जाते\",\"फक्त कमी होत जाते\"],\"answer\":1,\"explain\":\"मजकुरात \'रात्रमान दररोज कोणत्या प्रकारे बदलत दिसते?\' असा प्रश्न विचारून बदलाचे निरीक्षण करण्यास सांगितले आहे.\",\"topic\":\"निरीक्षण व चर्चा\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या विशिष्ट तारखेला दिनमान व रात्रमान समान असेल, तर त्याचा अर्थ काय होतो?\",\"options\":[\"दिवस १० तासांचा आहे\",\"रात्र १४ तासांची आहे\",\"दोन्ही कालावधी १२-१२ तास आहेत\",\"दिवस २४ तासांचा आहे\"],\"answer\":2,\"explain\":\"दि