emember\"},{\"q\":\"हा उपक्रम साधारणपणे कोणत्या महिन्यापर्यंत सुरू ठेवायचा आहे?\",\"options\":[\"ऑगस्ट अखेर\",\"सप्टेंबर अखेर\",\"नोव्हेंबर अखेर\",\"डिसेंबर अखेर\"],\"answer\":3,\"explain\":\"शिक्षकांसाठी दिलेल्या सूचनेनुसार हा उपक्रम डिसेंबर अखेरपर्यंत सुरू ठेवायचा आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"आठवड्यातून कोणत्या दिवशी निरीक्षण करण्यास सुचवले आहे?\",\"options\":[\"सोमवार\",\"मंगळवार\",\"शुक्रवार\",\"रविवार\"],\"answer\":1,\"explain\":\"मजकुरानुसार आठवड्यातून एक दिवस, मंगळवारी निरीक्षण करावे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"काठीच्या सावलीची नोंद करताना खालीलपैकी कोणत्या गोष्टींची नोंद करणे आवश्यक आहे?\",\"options\":[\"केवळ वेळ\",\"केवळ दिनांक\",\"दिनांक व वेळ\",\"काठीची लांबी\"],\"answer\":2,\"explain\":\"निरीक्षणानंतर काठीच्या सावलीची जागा दिनांक व वेळेच्या खुणाने नोंदवण्यास सांगितले आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"सप्टेंबर महिन्यासाठी भरलेल्या तक्त्याच्या नोंदीवरून कशाचा अभ्यास करता येतो?\",\"options\":[\"केवळ पावसाचे प्रमाण\",\"दिनमान व रात्रमानाचा कालावधी\",\"काठीची जाडी\",\"सूर्याचे तापमान\"],\"answer\":1,\"explain\":\"सप्टेंबर महिन्यातील नोंदीवरून दिनमान व रात्रमानाचा कालावधी अभ्यासता येतो.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर सावलीच्या जागेत फरक पडत असेल, तर काय करणे अपेक्षित आहे?\",\"options\":[\"काठीची जागा बदलणे\",\"निरीक्षण थांबवणे\",\"सावलीच्या जागेतील अंतर मोजणे\",\"काठीची लांबी वाढवणे\"],\"answer\":2,\"explain\":\"सावलीच्या जागेत फरक पडत असल्यास त्यातील अंतर मोजून ठेवण्यास सांगितले आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत मुले कशाचे निरीक्षण करत आहेत?\",\"options\":[\"काठीच्या सावलीचे\",\"झाडाच्या पानांचे\",\"भिंतीवरील रंगाचे\",\"आकाशातील ढगांचे\"],\"answer\":0,\"explain\":\"आकृती १.२ मध्ये मुले जमिनीवर पडलेल्या काठीच्या सावलीचे निरीक्षण करताना दिसत आहेत.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"49\\/012_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत भिंतीवर असलेल्या \'x\' खुणा काय दर्शवतात?\",\"options\":[\"काठीची उंची\",\"सावलीच्या बदललेल्या जागा\",\"भिंतीवरील भेगा\",\"सूर्याची दिशा\"],\"answer\":1,\"explain\":\"आकृतीमध्ये \'x\' खुणा सावलीच्या स्थानात होणारा बदल किंवा वेगवेगळ्या वेळच्या सावलीच्या जागा दर्शवतात.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"49\\/012_102.jpg\"},{\"q\":\"काठी कोणत्या ठिकाणी रोवणे आवश्यक आहे?\",\"options\":[\"नेहमी सावली असणाऱ्या जागी\",\"वर्गाच्या आत कोपऱ्यात\",\"वर्षभर सूर्यप्रकाश पडणाऱ्या क्षितिजाजवळ\",\"पाणी साचलेल्या जागी\"],\"answer\":2,\"explain\":\"काठी सूर्योदयाच्या किंवा सूर्यास्ताच्या वेळेस वर्षभर सूर्यप्रकाश पडणाऱ्या क्षितिजाजवळ ठेवण्यास सांगितली आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"सूर्याच्या उगवतीच्या व मावळतीच्या स्थानाचे वर्षभर निरीक्षण केल्यास काय लक्षात येते?\",\"options\":[\"स्थान कायम तेच राहते\",\"स्थानात बदल होतात\",\"सूर्य उगवणे थांबते\",\"सावली गायब होते\"],\"answer\":1,\"explain\":\"मजकुरानुसार वर्षभर निरीक्षण केल्यास सूर्याच्या उगवतीच्या व मावळतीच्या स्थानात बदल झाल्याचे लक्षात येते.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"प्रयोगासाठी काठी \'वर्षभरासाठी\' एकाच ठिकाणी का रोवलेली असावी?\",\"options\":[\"काठी हरवू नये म्हणून\",\"सावलीच्या स्थानातील बदलांचे अचूक निरीक्षण करण्यासाठी\",\"काठीची उंची वाढवण्यासाठी\",\"जागा वाचवण्यासाठी\"],\"answer\":1,\"explain\":\"सावलीच्या स्थानात होणारे बदल एका स्थिर संदर्भावरून (काठीवरून) मोजण्यासाठी ती एकाच जागी असणे आवश्यक आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"टेबलाची जागा बदलल्यामुळे सावलीच्या स्थानात होणारा बदल हा कोणत्या नैसर्गिक घटनेशी संबंधित आहे?\",\"options\":[\"चंद्राच्या कला\",\"सूर्याची उगवती व मावळतीची बदलणारी स्थाने\",\"भरती-ओहोटी\",\"वाऱ्याचा वेग\"],\"answer\":1,\"explain\":\"मजकुरात टेबलाच्या प्रयोगाची तुलना सूर्याच्या उगवतीच्या व मावळतीच्या स्थानातील बदलांशी केली आहे.\",\"topic\":\"करून पहा\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीवर दिवस व रात्र होण्यासाठी खालीलपैकी कोणती क्रिया कारणीभूत असते?\",\"options\":[\"पृथ्वीचे परिवलन\",\"पृथ्वीचे परिभ्रमण\",\"सूर्याचे परिवलन\",\"चंद्राचे परिभ्रमण\"],\"answer\":0,\"explain\":\"पृथ्वी स्वतःभोवती फिरते (परिवलन), त्यामुळे पृथ्वीवर दिवस व रात्र होतात.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या स्वतःभोवती फिरण्याच्या क्रियेस काय म्हणतात?\",\"options\":[\"परिभ्रमण\",\"परिवलन\",\"कक्षा\",\"गती\"],\"answer\":1,\"explain\":\"पृथ्वी जेव्हा स्वतःच्या अक्षाभोवती फिरते, तेव्हा त्या क्रियेला परिवलन म्हणतात.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीला सूर्याभोवती एक फेरी पूर्ण करण्यास जो काळ लागतो, त्यास काय म्हणतात?\",\"options\":[\"एक दिवस\",\"एक महिना\",\"एक वर्ष\",\"एक आठवडा\"],\"answer\":2,\"explain\":\"पृथ्वीला सूर्याभोवती फिरण्यास लागणाऱ्या काळाला एक वर्ष असे म्हणतात.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"भारतात साधारणपणे प्रामुख्याने कोणते ऋतू मानले जातात?\",\"options\":[\"वसंत, ग्रीष्म व शरद\",\"उन्हाळा, पावसाळा व हिवाळा\",\"हेमंत, शिशिर व वर्षा\",\"उन्हाळा, हिवाळा व शरद\"],\"answer\":1,\"explain\":\"भारतात मुख्यत्वे उन्हाळा, पावसाळा आणि हिवाळा हे तीन ऋतू मानले जातात.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"ऋतूंच्या एकामागून एक येणाऱ्या चक्राला काय म्हणतात?\",\"options\":[\"कालचक्र\",\"जलचक्र\",\"ऋतूचक्र\",\"जीवनचक्र\"],\"answer\":2,\"explain\":\"ऋतूंच्या नियमितपणे होणाऱ्या बदलाला किंवा चक्राला ऋतूचक्र म्हणतात.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर क्षितिजावरील सावलीची जागा सातत्याने उत्तरेकडे सरकत असेल, तर सूर्योदयाचे ठिकाण कोणत्या दिशेला सरकल्यासारखे वाटेल?\",\"options\":[\"दक्षिणेकडे\",\"उत्तरेकडे\",\"पूर्वेकडे\",\"पश्चिमेकडे\"],\"answer\":1,\"explain\":\"सावलीची जागा ज्या दिशेला सरकते, त्याच दिशेला सूर्योदय किंवा सूर्यास्ताचे ठिकाण सरकल्यासारखे वाटते.\",\"topic\":\"थोडे आठवूया\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीच्या सूर्याभोवती फिरण्याच्या क्रियेला काय म्हणतात?