t\":20,\"bloom\":\"analyze\"},{\"q\":\"एखाद्या ठिकाणी \'आवर्त प्रणाली\' आल्यास काय घडते?\",\"options\":[\"ती प्रणाली तिथेच कायमस्वरूपी थांबते\",\"ती प्रणाली एका ठिकाणाहून दुसऱ्या ठिकाणी सरकते\",\"तिथे पाऊस पडणे बंद होते\",\"तिथे हवेचा दाब वाढतो\"],\"answer\":1,\"explain\":\"आवर्ते प्रणाली एका ठिकाणाहून दुसऱ्या ठिकाणी सरकते असे पाठ सांगतो.\",\"topic\":\"आवर्ते\",\"part\":20,\"bloom\":\"evaluate\"},{\"q\":\"आवर्ताचे क्षेत्र प्रामुख्याने कसे असते?\",\"options\":[\"अमर्याद\",\"मर्यादित\",\"संपूर्ण जगभर पसरलेले\",\"स्थिर\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, आवर्त वादळे प्रामुख्याने मर्यादित क्षेत्रावर असतात.\",\"topic\":\"आवर्ते\",\"part\":20,\"bloom\":\"understand\"},{\"q\":\"पॅसिफिक महासागराच्या पश्चिम भागात निर्माण होणाऱ्या वादळांना काय म्हणतात?\",\"options\":[\"हरिकेन्स\",\"टायफून\",\"समशीतोष्ण आवर्त\",\"व्यापारी वारे\"],\"answer\":1,\"explain\":\"पॅसिफिक महासागराच्या पश्चिम भागात जपान, चीन यांसारख्या देशांच्या किनाऱ्यालगत निर्माण होणाऱ्या वादळांना \'टायफून\' म्हणतात.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"टायफून ही वादळे प्रामुख्याने कोणत्या कालावधीत निर्माण होतात?\",\"options\":[\"जानेवारी ते मार्च\",\"एप्रिल ते मे\",\"जून ते ऑक्टोबर\",\"नोव्हेंबर ते डिसेंबर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार टायफून ही वादळे जून ते ऑक्टोबर या महिन्यांत निर्माण होतात.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"टायफून वादळे विनाशकारी असण्याचे मुख्य कारण काय आहे?\",\"options\":[\"कमी वेग आणि थंडी\",\"वेगाने वाहणारे वारे आणि मुसळधार पाऊस\",\"केवळ समुद्राच्या लाटा\",\"वाऱ्यांची दिशा बदलणे\"],\"answer\":1,\"explain\":\"वेगाने वाहणारे वारे आणि मुसळधार पाऊस यांमुळे टायफून वादळे विनाशकारी असतात.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"कॅरिबियन समुद्रात निर्माण होणाऱ्या चक्रीवादळांना कोणत्या नावाने ओळखले जाते?\",\"options\":[\"टायफून\",\"हरिकेन्स\",\"मोसमी वारे\",\"स्थानिक वारे\"],\"answer\":1,\"explain\":\"कॅरिबियन समुद्रात निर्माण होणारी चक्रीवादळे म्हणजे \'हरिकेन्स\' होय.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"चक्रीवादळांच्या वेळी वाऱ्यांचा वेग दर ताशी कमीतकमी किती असतो?\",\"options\":[\"३० किमी\",\"४५ किमी\",\"६० किमी\",\"१०० किमी\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार, वादळांच्या वेळी वाऱ्यांचा वेग दर ताशी कमीतकमी ६० किमी असतो.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"apply\"},{\"q\":\"समशीतोष्ण कटिबंधात तयार होणाऱ्या आवर्तांची तीव्रता कशी असते?\",\"options\":[\"खूप जास्त आणि विनाशकारी\",\"कमी असते\",\"टायफूनपेक्षा जास्त\",\"अतिशय विनाशकारी\"],\"answer\":1,\"explain\":\"समशीतोष्ण कटिबंधात तयार होणाऱ्या आवर्तांची तीव्रता कमी असते.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता देश टायफून वादळांमुळे प्रभावित होतो?\",\"options\":[\"भारत\",\"ब्राझील\",\"फिलिपाइन्स\",\"अमेरिका\"],\"answer\":2,\"explain\":\"पॅसिफिक महासागराच्या पश्चिम भागात फिलिपाइन्स देशाच्या किनाऱ्यालगत टायफून वादळे निर्माण होतात.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"remember\"},{\"q\":\"समशीतोष्ण कटिबंधातील आवर्तांबाबत कोणते विधान सत्य आहे?\",\"options\":[\"ती अतिशय विनाशकारी असतात.\",\"ती विनाशकारी नसतात.\",\"त्यांचा वेग ताशी २०० किमी असतो.\",\"ती फक्त जून महिन्यात येतात.\"],\"answer\":1,\"explain\":\"समशीतोष्ण कटिबंधातील आवर्त विनाशकारी नसतात असे पाठ्यपुस्तकात नमूद केले आहे.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"analyze\"},{\"q\":\"हरिकेन्स आणि टायफून या दोन्ही वादळांमध्ये कोणते साम्य आहे?\",\"options\":[\"दोन्ही कमी तीव्रतेची असतात.\",\"दोन्ही विनाशकारी असतात.\",\"दोन्ही फक्त भारतात येतात.\",\"दोन्ही हिवाळ्यात येतात.\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात टायफून आणि हरिकेन्स या दोन्ही वादळांचे वर्णन विनाशकारी असे केले आहे.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"understand\"},{\"q\":\"जर एखादे चक्रीवादळ जपानच्या किनाऱ्यावर धडकले, तर त्याला भौगोलिक भाषेत काय म्हणाल?\",\"options\":[\"हरिकेन\",\"टायफून\",\"समशीतोष्ण आवर्त\",\"स्थानिक वारे\"],\"answer\":1,\"explain\":\"जपान हा पॅसिफिक महासागराच्या पश्चिम भागात असल्याने तेथील वादळाला टायफून म्हणतात.\",\"topic\":\"चक्रीवादळे\",\"part\":21,\"bloom\":\"apply\"},{\"q\":\"हवेची स्थिती दर्शवणाऱ्या नकाशात प्रत्यावर्ताचा केंद्रभाग कोणत्या अक्षराने दाखवतात?\",\"options\":[\"L\",\"H\",\"P\",\"A\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, प्रत्यावर्ताचा केंद्रभाग \'H\' (High) या अक्षराने दाखवतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"प्रत्यावर्ते प्रामुख्याने कोणत्या कटिबंधात निर्माण होतात?\",\"options\":[\"उष्ण कटिबंध\",\"शीत कटिबंध\",\"समशीतोष्ण कटिबंध\",\"ध्रुवीय कटिबंध\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात नमूद केल्याप्रमाणे असे प्रत्यावर्त समशीतोष्ण कटिबंधात निर्माण होतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"प्रत्यावर्ताच्या केंद्रात हवेचा दाब कसा असतो?\",\"options\":[\"अतिशय कमी\",\"सभोवतालच्या प्रदेशापेक्षा जास्त\",\"सभोवतालच्या प्रदेशापेक्षा कमी\",\"शून्य\"],\"answer\":1,\"explain\":\"प्रत्यावर्तात हवेच्या केंद्रात सभोवतालच्या प्रदेशापेक्षा जास्त दाब निर्माण होतो.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"उत्तर गोलार्धात प्रत्यावर्ताचे वारे कोणत्या दिशेने वाहतात?\",\"options\":[\"घड्याळाच्या काट्याच्या विरुद्ध दिशेने\",\"सरळ रेषेत\",\"घड्याळाच्या काट्याच्या दिशेने\",\"खालून वरच्या दिशेने\"],\"answer\":2,\"explain\":\"उत्तर गोलार्धात प्रत्यावर्ताचे वारे घड्याळाच्या काट्याच्या दिशेने (Clockwise) वाहतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही दक्षिण गोलार्धात असाल, तर तेथील प्रत्यावर्ताच्या वाऱ्यांची दिशा कशी असेल?\",\"options\":[\"घड्याळाच्या काट्याच्या दिशेने\",\"घड्याळाच्या काट्याच्या विरुद्ध दिशेने\",\"केंद्राच्या दिशेने\",\"स्थिर\"],\"answer\":1,\"explain\":\"दक्षिण गोलार्धात प्रत्यावर्ताचे वारे घड्याळाच्या काट्याच्या विरुद्ध दिशेने वाहतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"apply\"},{\"q\":\"प्रत्यावर्ताच्या प्रदेशात पावसाचे प्रमाण कमी का असते?\",\"options\":[\"तेथे हवा थंड असते\",\"तेथे वारे वेगाने वाहतात\",\"त्या प्रदेशातून वारे बाहेर जात असतात\",\"तेथे आकाश नेहमी ढगाळ असते\"],\"answer\":2,\"explain\":\"प्रत्यावर्ताच्या प्रदेशातून वारे बाहेर जात असल्यामुळे तेथे पावसाचे प्रमाण कमी असते.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"analyze\"},{\"q\":\"प्रत्यावर्ताची स्थिती साधारणपणे किती काळ टिकू शकते?\",\"options\":[\"काही तास\",\"काही दिवस अथवा एक आठवडा\",\"एक महिना\",\"पूर्ण ऋतूभर\"],\"answer\":1,\"explain\":\"प्रत्यावर्ताची स्थिती बहुधा काही दिवस अथवा एक आठवडाही असू शकते.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"remember\"},{\"q\":\"प्रत्यावर्ताच्या कालावधीत हवामानाची स्थिती कशी असते?\",\"options\":[\"निरभ्र आकाश आणि कमी वेगाने वाहणारे वारे\",\"ढगाळ आकाश आणि वादळी वारे\",\"अतिवृष्टी आणि वेगाने वाहणारे वारे\",\"निश्चित आणि स्थिर हवामान\"],\"answer\":0,\"explain\":\"प्रत्यावर्ताच्या काळात निरभ्र आकाश, कमी वेगाने वाहणारे वारे आणि अनिश्चित हवामान असते.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"हवामान नकाशात एखाद्या ठिकाणी \'H\' हे चिन्ह असल्यास, तेथील वाऱ्यांच्या प्रवाहाबद्दल काय सांगता येईल?\",\"options\":[\"वारे केंद्राकडे चक्राकार वाहत येतील\",\"वारे केंद्राकडून सभोवतालच्या प्रदेशाकडे वाहत जातील\",\"वारे सरळ वरच्या दिशेला जातील\",\"तेथे वारे वाहणार नाहीत\"],\"answer\":1,\"explain\":\"\'H\' म्हणजे जास्त दाब, जिथून वारे बाहेरच्या बाजूला चक्राकार दिशेत वाहतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"apply\"},{\"q\":\"प्रत्यावर्ताच्या निर्मितीसाठी खालीलपैकी कोणती अट आवश्यक आहे?\",\"options\":[\"केंद्रात कमी दाबाची निर्मिती\",\"केंद्रात जास्त दाबाची निर्मिती\",\"वाऱ्यांचा वेग वाढणे\",\"आकाशात ढग जमा होणे\"],\"answer\":1,\"explain\":\"प्रत्यावर्तात विशिष्ट वातावरणीय परिस्थितीत केंद्राभोवती हवेचा जास्त दाब निर्माण होणे आवश्यक असते.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. केंद्राकडून (H) बाहेरील वर्तुळांकडे जाताना वायूदाब मूल्यात (millibar) कोणता बदल दिसून येतो?\",\"options\":[\"वायूदाब वाढत जातो\",\"वायूदाब कमी होत जातो\",\"वायूदाब स्थिर राहतो\",\"वायूदाब आधी कमी होऊन नंतर वाढतो\"],\"answer\":1,\"explain\":\"आकृतीत केंद्रात १०१० mb दाब असून बाहेर जाताना तो १००८, १००६, १००४ असा कमी होताना दिसतो.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"analyze\",\"figure_image\":\"49\\/038_101.jpg\"},{\"q\":\"दिलेल्या आकृतीत बाणांच्या खुणा वाऱ्यांच्या वहनाची कोणती दिशा दर्शवतात?\",\"options\":[\"बाहेरून केंद्राकडे\",\"केंद्राकडून बाहेरच्या बाजूला\",\"सरळ रेषेत उत्तर दिशेला\",\"फक्त वरच्या दिशेला\"],\"answer\":1,\"explain\":\"आकृतीतील बाण केंद्रातील जास्त दाबाकडून (H) बाहेर कमी दाबाच्या प्रदेशाकडे वारे वाहत असल्याचे दर्शवतात.\",\"topic\":\"प्रत्यावर्ते\",\"part\":22,\"bloom\":\"analyze\",\"figure_image\":\"49\\/038_101.jpg\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29'),(22031,49,7,'Geography','mr','नैसर्गिक प्रदेश','[\"नैसर्गिक प्रदेश: हवामान, वनस्पती, प्राणीजीवन आधारित समान गुणधर्मांचा प्रदेश.\",\"विषुववृत्तीय प्रदेश: उष्ण, आर्द्र, वर्षभर पाऊस, घन वनस्पती.\",\"मोसमी प्रदेश: शीत हिवाळी, उष्ण वाळवंत, पाऊस समानपणे वितरित.\",\"भूमध्य सागरी प्रदेश: गरम वाळवंत, शीत हिवाळी, पाऊस हिवाळ्यात.\",\"पश्‍चिम युरोपीय प्रदेश: समुद्राचा प्रभाव, सौम्य हवामान, वर्षभर पाऊस.\",\"तैगा प्रदेश: शीत, हिमपात, शंकु वृक्षे (पाइन, स्प्रूस).\",\"टंड्रा प्रदेश: खूप शीत, अल्पकालीन लहान वनस्पती, पावस कमी.\",\"गवताळ प्रदेश: खूप उष्ण, कमी पाऊस, घास व झुडुपे प्रमुख.\",\"उष्ण वाळवंटी प्रदेश: उष्ण, शुष्क, उंट जैसे प्राणी विशेष.\",\"प्रेअरी प्रदेश: मध्यम पाऊस, घासभूमि, गहू उत्पादन प्रमुख.\",\"सुदान प्रदेश: उष्ण, शुष्क वाळवंत, आर्द्र हिवाळी, तृणभक्षक प्राणी.\",\"वनस्पती वितरण: पाऊसाची उपलब्धता वितरणानुसार बदलते.\",\"प्राणी वितरण: हवामान व वनस्पतीनुसार प्राणी वितरित.\",\"मानवी व्यवसाय: शेती, चरवाहीकरी, वनोत्पादन आधारित.\",\"संसाधन उपलब्धता: हवामानानुसार जल, वन, खनिज व इतर संसाधने.\"]','[{\"q\":\"दिलेल्या मजकुरानुसार, आकृती ९.१ कशाशी संबंधित आहे?\",\"options\":[\"भारताची लोकसंख्या\",\"जगातील नैसर्गिक प्रदेश\",\"जगातील हवामान\",\"महाराष्ट्राची शेती\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्टपणे \'आकृती ९.१ : जगातील नैसर्गिक प्रदेश\' असा उल्लेख आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भारतात कोणते नैसर्गिक प्रदेश आढळतात, हे शोधण्यासाठी कोणत्या आकृतीचा वापर करण्यास सांगितले आहे?\",\"options\":[\"आकृती ८.१\",\"आकृती ९.२\",\"आकृती ९.१\",\"आकृती १०.१\"],\"answer\":2,\"explain\":\"मजकुराच्या सुरुवातीलाच \'आकृती ९.१ चा वापर करून खालील प्रश्नांची उत्तरे द्या\' असे म्हटले आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मजकुरात कोणत्या गोलार्धातील नैसर्गिक प्रदेशांबद्दल प्रश्न विचारला आहे?\",\"options\":[\"दक्षिण गोलार्ध\",\"पूर्व गोलार्ध\",\"पश्चिम गोलार्ध\",\"उत्तर गोलार्ध\"],\"answer\":3,\"explain\":\"मजकुरात \'उत्तर गोलार्धात कोणत्या नैसर्गिक प्रदेशात आढळतात?\' असा प्रश्न विचारला आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"नकाशात नैसर्गिक प्रदेश दर्शवण्यासाठी प्रामुख्याने कशाचा वापर केला जातो, असे मजकुरावरून सुचवले आहे?\",\"options\":[\"रेषा काम\",\"रंग काम\",\"ठिपके पद्धत\",\"चिन्हे आणि खुणा\"],\"answer\":1,\"explain\":\"मजकुरात \'रंग काम करण्यासाठी प्रदेशांना जास्त कोणत्या खिड्या येतात?\' असा उल्लेख आहे, जो नकाशातील रंगांशी संबंधित आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिक प्रदेशांच्या संदर्भात सर्वात जास्त काय आढळते, असे विचारले आहे?\",\"options\":[\"समानता\",\"लोकसंख्या\",\"विविधता\",\"पाऊस\"],\"answer\":2,\"explain\":\"मजकुरात \'नैसर्गिक प्रदेशात सर्वात जास्त विविधता कोणत्या येतात?\' असा प्रश्न आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिक प्रदेशांचे स्थान निश्चित करण्यासाठी कोणत्या भौगोलिक घटकाचा मजकुरात उल्लेख आहे?\",\"options\":[\"रेखांश\",\"अक्षांश\",\"उंची\",\"समुद्रकिनारा\"],\"answer\":1,\"explain\":\"मजकुरात \'नैसर्गिक प्रदेशात कोणत्या अक्षांशामध्ये काय कारणे कोणते असतात?\' असा उल्लेख आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला भारताचा नैसर्गिक प्रदेश शोधायचा असेल, तर तुम्ही आकृती ९.१ मध्ये प्रामुख्याने काय पाहाल?\",\"options\":[\"भारताचे स्थान आणि तेथील रंग\",\"केवळ उत्तर ध्रुव\",\"केवळ दक्षिण ध्रुव\",\"केवळ अमेरिका खंड\"],\"answer\":0,\"explain\":\"भारतातील नैसर्गिक प्रदेश शोधण्यासाठी आकृती ९.१ मधील भारताचे स्थान आणि त्या भागातील रंग पाहणे आवश्यक आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"उत्तर गोलार्धातील नैसर्गिक प्रदेशांची माहिती मिळवण्यासाठी विद्यार्थ्याने काय करणे अपेक्षित आहे?\",\"options\":[\"केवळ मजकूर वाचणे\",\"आकृती ९.१ चे निरीक्षण करणे\",\"स्वतः नकाशा काढणे\",\"इतर देशांचा इतिहास वाचणे\"],\"answer\":1,\"explain\":\"मजकूर \'आकृती ९.१ चा वापर करून\' उत्तरे देण्यास सांगतो, ज्यामध्ये उत्तर गोलार्धाचाही समावेश आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"नैसर्गिक प्रदेश आणि अक्षांश यांचा संबंध जोडण्यासाठी मजकुरात कोणता प्रश्न विचारला आहे?\",\"options\":[\"अक्षांश म्हणजे काय?\",\"कोणत्या अक्षांशामध्ये कोणते प्रदेश व त्यांची कारणे काय?\",\"रेखांशाचा परिणाम काय होतो?\",\"भारताचे अक्षांश किती आहेत?\"],\"answer\":1,\"explain\":\"मजकुरात अक्षांश आणि त्यामागील कारणांचा शोध घेण्याबाबत विचारले आहे.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"या \'जरा डोके चालवा\' भागाचा मुख्य उद्देश काय आहे?\",\"options\":[\"केवळ पाठांतर करणे\",\"आकृती ९.१ चे विश्लेषण करून भौगोलिक ज्ञान मिळवणे\",\"केवळ रंग भरण्याचे काम करणे\",\"गणिते सोडवणे\"],\"answer\":1,\"explain\":\"हा भाग विद्यार्थ्यांना आकृतीचे निरीक्षण करून त्यावरून निष्कर्ष काढण्यास प्रवृत्त करतो.\",\"topic\":\"जरा डोके चालवा.\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"उष्ण वाळवंटी प्रदेशात खालीलपैकी कोणता व्यवसाय केला जातो?\",\"options\":[\"शेती\",\"पशुपालन\",\"खाणकाम\",\"मासेमारी\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की उष्ण वाळवंटी प्रदेशात पशुपालन करतात.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"वाळवंटी प्रदेशातील लोकांचे जीवन कोणत्या स्वरूपाचे असते?\",\"options\":[\"स्थायिक\",\"शहरी\",\"भटक्या\",\"आधुनिक\"],\"answer\":2,\"explain\":\"वाळवंटी प्रदेशातील लोकांचे जीवन भटक्या स्वरूपाचे असते असे उताऱ्यात दिले आहे.\",\"topic\":\"हे नेहमी लक