,\"उष्ण वाळवंटी प्रदेश\",\"विषुववृत्तीय प्रदेश\",\"थंड प्रदेश\"],\"answer\":1,\"explain\":\"उताऱ्यात वाळवंटी प्रदेशातील लोकांचे जीवन भटक्या स्वरूपाचे असल्याचे सांगितले आहे.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर आपण नैसर्गिक साधनसंपत्तीचा वापर करताना इतर सजीवांचा विचार केला नाही, तर कोणत्या कल्पनेला बाधा येईल?\",\"options\":[\"पशुपालन\",\"भटके जीवन\",\"वसुधैव कुटुंबकम्\",\"प्राकृतिक प्रदेश\"],\"answer\":2,\"explain\":\"इतर सजीवांचा विचार करणे ही \'वसुधैव कुटुंबकम्\' साठी आवश्यक अट आहे.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यातील \'हे नेहमी लक्षात ठेवा\' या भागाचा मुख्य उद्देश काय आहे?\",\"options\":[\"केवळ वाळवंटाची माहिती देणे\",\"पर्यावरणातील सर्व सजीवांच्या सहअस्तित्वाचे महत्त्व सांगणे\",\"मांसाभक्षक प्राण्यांची भीती घालणे\",\"पशुपालनाचे फायदे सांगणे\"],\"answer\":1,\"explain\":\"हा भाग सर्व सजीवांचा विचार करून साधनसंपत्ती वापरण्यावर भर देतो.\",\"topic\":\"हे नेहमी लक्षात ठेवा.\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीवरील एकूण वाळवंटापैकी साधारण किती टक्के वाळवंटे वाळूची असतात?\",\"options\":[\"२५ टक्के\",\"५० टक्के\",\"७५ टक्के\",\"१०० टक्के\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे दिले आहे की पृथ्वीवरील साधारण ५० टक्के वाळवंटे वाळूची असतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"वाळू नसलेली उरलेली वाळवंटे प्रामुख्याने कशाने व्यापलेली असतात?\",\"options\":[\"केवळ घनदाट जंगलांनी\",\"मोठ्या नद्यांनी आणि तलावांनी\",\"कातळ, छोटे दगड किंवा गोट्यांनी\",\"कायमस्वरूपी बर्फाच्या थरांनी\"],\"answer\":2,\"explain\":\"उरलेली वाळवंटे माळरांनासारखी कातळांनी, छोट्या छोट्या दगडांनी किंवा गोट्यांनी व्यापलेली असतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सहारा हे प्रसिद्ध वाळवंट कोणत्या खंडात किंवा देशात आहे?\",\"options\":[\"आशिया\",\"ऑस्ट्रेलिया\",\"आफ्रिका\",\"युरोप\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे सहारा वाळवंट आफ्रिका देशात (खंडात) आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"वाऱ्यामुळे तयार होणाऱ्या वाळूच्या टेकड्यांना इंग्रजीत काय म्हणतात?\",\"options\":[\"रॉक्स (Rocks)\",\"डूनस् (Dunes)\",\"पीक्स (Peaks)\",\"व्हॅलीज (Valleys)\"],\"answer\":1,\"explain\":\"वाऱ्यातून वाहणाऱ्या वाळूच्या टेकड्या तयार होतात, त्यांना इंग्रजीत \'डूनस्\' (Dunes) म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"काही वाळूच्या टेकड्यांची (Dunes) उंची साधारण किती मीटरपर्यंत असू शकते?\",\"options\":[\"५० मीटर\",\"१०० मीटर\",\"२०० मीटर\",\"५०० मीटर\"],\"answer\":2,\"explain\":\"काही डूनस् २०० मीटर उंचीही गाठतात असे उताऱ्यात दिले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"वाळवंटातील वाळूच्या टेकड्यांच्या हालचालीबाबत कोणते विधान योग्य आहे?\",\"options\":[\"त्या एका जागी कायमस्वरूपी स्थिर असतात.\",\"त्या वाऱ्यामुळे हळूहळू सरकत राहतात.\",\"त्या केवळ पावसाळ्यातच सरकतात.\",\"त्यांची जागा कधीही बदलत नाही.\"],\"answer\":1,\"explain\":\"या टेकड्या एका जागी स्थिर न राहता वाऱ्यामुळे हळूहळू सरकत राहतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर एखादे गाव सरकणाऱ्या वाळूच्या टेकड्यांच्या मार्गात असेल, तर काय होऊ शकते?\",\"options\":[\"गावात पाऊस पडू लागेल.\",\"गाव वाळूच्या टेकड्यांखाली गाडले जाऊ शकते.\",\"गावातील जमीन अधिक सुपीक होईल.\",\"गावातील तापमान खूप कमी होईल.\"],\"answer\":1,\"explain\":\"टेकड्या हळूहळू सरकत असल्यामुळे काही वेळेस त्यांच्याखाली गावेही गाडली जातात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"ॲरिझोना येथील वाळवंटात खालीलपैकी काय पाहायला मिळू शकते?\",\"options\":[\"विस्तीर्ण बर्फाचे डोंगर\",\"चित्रविचित्र आकारांच्या कातळांचे सुळके\",\"मोठ्या प्रमाणात दलदलीचा प्रदेश\",\"सदाहरित वर्षावने\"],\"answer\":1,\"explain\":\"सहारा किंवा ॲरिझोना येथील वाळवंटांमध्ये उंच डोंगर किंवा चित्रविचित्र आकारांच्या कातळांचे सुळके असतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"वाळवंटात वाळूचे ढिगारे किंवा टेकड्या तयार होण्यासाठी मुख्यत्वे कोणता घटक कारणीभूत असतो?\",\"options\":[\"पाऊस\",\"भूकंप\",\"वारा\",\"समुद्राच्या लाटा\"],\"answer\":2,\"explain\":\"वाळवंटातून वाहणारे वारे वाळूचे ढिगारे आणि टेकड्या तयार करतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्याच्या आधारे वाळवंटांच्या स्वरूपाबाबत कोणता निष्कर्ष काढता येईल?\",\"options\":[\"सर्व वाळवंटे केवळ वाळूनेच बनलेली असतात.\",\"वाळवंटात डोंगर किंवा कातळ असू शकत नाहीत.\",\"वाळवंटांचे स्वरूप वाळू, कातळ आणि दगड अशा विविध प्रकारचे असू शकते.\",\"वाळवंटातील टेकड्यांची जागा कधीही बदलत नाही.\"],\"answer\":2,\"explain\":\"उताऱ्यावरून समजते की वाळवंटे वाळूची, कातळांची किंवा दगडांची असू शकतात, म्हणजेच त्यांचे स्वरूप विविध असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"टुंड्रा प्रदेशात जगण्यासाठी लोकांना प्रामुख्याने कोणते व्यवसाय करावे लागतात?\",\"options\":[\"शेती आणि पशुपालन\",\"शिकार आणि मासेमारी\",\"लाकूडतोड आणि फळे गोळा करणे\",\"विस्तीर्ण शेती आणि व्यापार\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, टुंड्रा प्रदेशात फक्त शिकार व मासेमारी करावी लागते.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"विषुववृत्तीय प्रदेशाकडून भूमध्य सागरी प्रदेशाकडे जाताना जैवविविधतेमध्ये काय बदल होतो?\",\"options\":[\"जैवविविधता वाढत जाते\",\"जैवविविधता स्थिर राहते\",\"जैवविविधता उत्तरोत्तर कमी होत जाते\",\"जैवविविधतेत कोणताही बदल होत नाही\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे, विषुववृत्तीय प्रदेशाकडून भूमध्य सागरी प्रदेशाकडे जाताना जैवविविधता कमी होत जाते.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"मौसमी प्रदेशात खालीलपैकी कोणते व्यवसाय प्रामुख्याने केले जातात?\",\"options\":[\"शिकार आणि मासेमारी\",\"शेती व शेती पूरक व्यवसाय\",\"केवळ लाकूडतोड\",\"फळे व कंदमुळे गोळा करणे\"],\"answer\":1,\"explain\":\"मौसमी प्रदेशात शेती व शेती पूरक व्यवसाय केले जातात असे पाठात म्हटले आहे.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"विषुववृत्तीय वनांमध्ये लाकूडतोड व्यवसाय मोठ्या प्रमाणावर चालण्याचे मुख्य कारण काय?\",\"options\":[\"तेथे कठीण लाकूड आढळते\",\"तेथे मृदू लाकूड आढळते\",\"तेथे शेतीसाठी जागा नसते\",\"तेथे फक्त लाकूडच उपलब्ध असते\"],\"answer\":1,\"explain\":\"विषुववृत्तीय वनांमध्ये मृदू लाकूड आढळते, त्यामुळे तेथे लाकूडतोड व्यवसाय चालतो.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"अलीकडच्या काळात कोणत्या नैसर्गिक प्रदेशात विस्तीर्ण शेती केली जाते?\",\"options\":[\"विषुववृत्तीय प्रदेश\",\"टुंड्रा प्रदेश\",\"गवताळ प्रदेश\",\"मौसमी प्रदेश\"],\"answer\":2,\"explain\":\"गवताळ प्रदेशात अलीकडे विस्तीर्ण शेती केली जाते असे उताऱ्यात दिले आहे.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"एखाद्या प्रदेशातील साधनसंपत्तीचा वापर हा प्रामुख्याने कशावर अवलंबून असतो?\",\"options\":[\"केवळ हवामानावर\",\"केवळ लोकसंख्येवर\",\"विज्ञान आणि तंत्रज्ञानाच्या प्रभावावर\",\"केवळ जमिनीच्या प्रकारावर\"],\"answer\":2,\"explain\":\"साधनसंपत्तीचा वापर हा त्या त्या प्रदेशातील विज्ञान आणि तंत्रज्ञानाचा प्रभाव असतो.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर तुम्ही विषुववृत्तीय वनांच्या प्रदेशात राहत असाल, तर अन्नासाठी तुम्ही कोणता व्यवसाय निवडाल?\",\"options\":[\"विस्तीर्ण शेती करणे\",\"फळे व कंदमुळे गोळा करणे\",\"मोठ्या प्रमाणावर पशुपालन करणे\",\"केवळ गहू पिकवणे\"],\"answer\":1,\"explain\":\"विषुववृत्तीय प्रदेशात फळे, कंदमुळे गोळा करणे हा अन्नासाठीचा एक व्यवसाय आहे.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"नैसर्गिक प्रदेशातील लोकजीवनावर खालीलपैकी कोणत्या घटकांचा प्रभाव पडतो?\",\"options\":[\"केवळ आधुनिक फॅशनचा\",\"केवळ परकीय व्यापाराचा\",\"इतिहास व सांस्कृतिक जडणघडणीचा\",\"केवळ मनोरंजनाच्या साधनांचा\"],\"answer\":2,\"explain\":\"प्रत्येक प्रदेशाचा इतिहास व सांस्कृतिक जडणघडण ही तेथील लोकजीवनावर प्रभाव टाकते.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"समशीतोष्ण कटिबंधातील गवताळ प्रदेशातील जैवविविधतेचा परिणाम कशावर होतो?\",\"options\":[\"केवळ प्राण्यांच्या स्थलांतरावर\",\"मानवी व्यवसायांवर\",\"केवळ पावसाच्या प्रमाणावर\",\"सागराच्या खोलीवर\"],\"answer\":1,\"explain\":\"जैवविविधतेतील बदलाचा परिणाम मानवी व्यवसायांवर होतो असे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"एका संशोधकाला अशा प्रदेशात जायचे आहे जिथे फक्त शिकार आणि मासेमारीवर अवलंबून राहावे लागेल. त्याने कोणत्या प्रदेशाची निवड करावी?\",\"options\":[\"मौसमी प्रदेश\",\"विषुववृत्तीय प्रदेश\",\"टुंड्रा प्रदेश\",\"गवताळ प्रदेश\"],\"answer\":2,\"explain\":\"टुंड्रा प्रदेशात फक्त शिकार व मासेमारी करावी लागते, म्हणून संशोधकाला तिथे जावे लागेल.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"विषुववृत्तीय प्रदेश आणि टुंड्रा प्रदेश यांच्या व्यवसायांची तुलना केल्यास कोणता निष्कर्ष निघतो?\",\"options\":[\"दोन्ही प्रदेशात शेती हा मुख्य व्यवसाय आहे\",\"पर्यावरणानुसार उपलब्ध साधनसंपत्तीत आणि व्यवसायात फरक असतो\",\"दोन्ही प्रदेशात लाकूडतोड व्यवसाय मोठ्या प्रमाणावर चालतो\",\"दोन्ही प्रदेशातील लोकजीवन सारखेच आहे\"],\"answer\":1,\"explain\":\"नैसर्गिक प्रदेशानुसार पर्यावरण आणि साधनसंपत्तीत फरक असल्याने व्यवसायातही फरक असतो.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"विषुववृत्तीय वनांच्या प्रदेशात वाघ, सिंह यांसारखे प्राणी का आढळत नाहीत, याचा विचार करताना कोणता घटक महत्त्वाचा ठरेल?\",\"options\":[\"तेथील लाकूड मृदू असणे\",\"तेथील मानवी वस्ती\",\"तेथील विशिष्ट नैसर्गिक पर्यावरण व जैवविविधता\",\"तेथील शेती व्यवसाय\"],\"answer\":2,\"explain\":\"नैसर्गिक प्रदेशातील विशिष्ट पर्यावरण आणि जैवविविधता प्राण्यांच्या वास्तव्यावर परिणाम करते.\",\"topic\":\"नैसर्गिक प्रदेशातील लोकजीवन\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"उष्ण वाळवंटी प्रदेश प्रामुख्याने खंडांच्या कोणत्या भागात आढळतात?\",\"options\":[\"पूर्व भागात\",\"पश्चिम भागात\",\"उत्तर भागात\",\"दक्षिण भागात\"],\"answer\":1,\"explain\":\"दिलेल्या मजकुरानुसार, उष्ण वाळवंटी प्रदेश बहुधा खंडांच्या पश्चिम भागांत आढळतात.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'जरा विचार करा !\' या चौकटीत कोणत्या नैसर्गिक प्रदेशाचा उल्लेख केला आहे?\",\"options\":[\"मान्सून प्रदेश\",\"विषुववृत्तीय प्रदेश\",\"उष्ण वाळवंटी प्रदेश\",\"गवताळ प्रदेश\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे \'उष्ण वाळवंटी प्रदेश\' असा उल्लेख आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"खंडांच्या पश्चिम भागात कोणते प्रदेश बहुधा आढळतात?\",\"options\":[\"उष्ण वाळवंटी प्रदेश\",\"बर्फाच्छादित प्रदेश\",\"दलदलीचे प्रदेश\",\"दाट वनप्रदेश\"],\"answer\":0,\"explain\":\"मजकुरानुसार खंडांच्या पश्चिम भागात उष्ण वाळवंटी प्रदेशांचे अस्तित्व जास्त असते.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"अधिक माहितीसाठी कोणत्या इयत्तेच्या भूगोल पुस्तकाचा संदर्भ दिला आहे?\",\"options\":[\"इयत्ता पाचवी\",\"इयत्ता सहावी\",\"इयत्ता सातवी\",\"इयत्ता आठवी\"],\"answer\":1,\"explain\":\"मजकुरात \'इयत्ता सहावी- भूगोल\' असा संदर्भ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"इयत्ता सहावीच्या भूगोल पुस्तकातील कोणत्या पानावर \'मी आणखी कोठे?\' हा भाग पाहता येईल?\",\"options\":[\"पृष्ठ ३८\",\"पृष्ठ ४८\",\"पृष्ठ ५८\",\"पृष्ठ ६८\"],\"answer\":1,\"explain\":\"मजकुरात पृष्ठ ४८ चा संदर्भ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"सजीवांमधील अनुकूलन व वर्गीकरण हा पाठ कोणत्या विषयाच्या संदर्भात वाचण्यास सांगितले आहे?\",\"options\":[\"इतिहास\",\"नागरिकशास्त्र\",\"सामान्य विज्ञान\",\"मराठी\"],\"answer\":2,\"explain\":\"मजकुरात \'इयत्ता सहावी- सामान्य विज्ञान- सजीवांमधील अनुकूलन व वर्गीकरण\' असा उल्लेख आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला नकाशावर उष्ण वाळवंटी प्रदेश शोधायचा असेल, तर तुम्ही खंडाच्या कोणत्या दिशेला प्राधान्याने पाहाल?\",\"options\":[\"पूर्व\",\"उत्तर\",\"पश्चिम\",\"दक्षिण\"],\"answer\":2,\"explain\":\"उष्ण वाळवंटी प्रदेशांचे स्थान खंडांच्या पश्चिम भागात असते, असे मजकुरात दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या मजकुरानुसार, उष्ण वाळवंटी प्रदेशांच्या स्थानाबाबत कोणते विधान सत्य आहे?\",\"options\":[\"ते खंडांच्या मध्य भागात असतात.\",\"ते खंडांच्या पूर्व किनारपट्टीवर असतात.\",\"ते बहुधा खंडांच्या पश्चिम भागात आढळतात.\",\"ते फक्त बेटांवर आढळतात.\"],\"answer\":2,\"explain\":\"मजकुरात उष्ण वाळवंटी प्रदेशांचे स्थान पश्चिम भागात असल्याचे सांगितले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"नैसर्गिक प्रदेशांचा अभ्यास करताना \'सजीवांमधील अनुकूलन\' हा घटक का महत्त्वाचा असावा?\",\"options\":[\"कारण तो केवळ विज्ञानाचा भाग आहे.\",\"कारण नैसर्गिक प्रदेशांनुसार सजीवांमध्ये बदल होतात.\",\"कारण वाळवंटात सजीव नसतात.\",\"कारण भूगोल आणि विज्ञान यांचा संबंध नसतो.\"],\"answer\":1,\"explain\":\"नैसर्गिक प्रदेशांच्या अभ्यासात सजीवांचे अनुकूलन समजून घेण्यासाठी विज्ञानाचा संदर्भ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या माहितीवरून, उष्ण वाळवंटी प्रदेशांचे वितरण कशावर आधारित असल्याचे सूचित होते?\",\"options\":[\"खंडांच्या राजकीय सीमांवर\",\"खंडांच्या भौगोलिक स्थानावर (पश्चिम भाग)\",\"केवळ मानवी वस्तीवर\",\"केवळ पावसाच्या प्रमाणावर\"],\"answer\":1,\"explain\":\"मजकुरात खंडांच्या \'पश्चिम भागात\' आढळतात असे म्हणून भौगोलिक स्थानाचा संदर्भ दिला आहे.\",\"topic\":\"स्वाध्याय\",\"part\":9,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22032,49,7,'Geography','mr','मृदा','[\"मृदा म्हणजे खडकांचे भुगा, जैविक पदार्थे, पाणी, हवा आणि सूक्ष्मजीवांचे मिश्रण.\",\"मृदानिर्मितीसाठी आवश्यक घटक: मूळ खडक, हवामान, जैविक पदार्थे, आणि वेळ.\",\"ह्युमस म्हणजे वनस्पती व प्राण्यांचे विघटन झालेल्या जैविक पदार्थे.\",\"ह्युमस मृदेची उर्वरता व पाण्यधारण क्षमता वाढवतो.\",\"जैविक घटक: वनस्पती, प्राण्यांचे मृतावशेष, ह्युमस.\",\"अजैविक घटक: मूळ खडक, खनिजे, पाणी, हवा.\",\"मृदेचे प्रमुख प्रकार: जाडीभरडी, काळी (रेगूर), जांभी, गाळाची, पिवळसर तपकिरी.\",\"रेगूर मृदा महाराष्ट्रातील दख्खन पठारावर शोधली जाते, ती काळी व सुपीक असते.\",\"जांभी मृदा सह्याद्रीच्या पाश्चिम भागात व कोकणातील अतिपावस प्रदेशात आढळते.\",\"गाळाची मृदा नद्यांच्या खोऱ्यांमधील व समुद्रकिनारातील प्रदेशात आढळते.\",\"पिवळसर तपकिरी मृदा अतिरिक्त पावसाच्या प्रदेशात, जसे की चंद्रपूर, भंडारा, आढळते.\",\"मृदेची धूप म्हणजे मृदेची उर्वरता व संरचना बिगडणे.\",\"मृदेची अवनती रासायनिक खतांचे अतिरेक, अतिरिक्त पाणी, वनों कापण्यामुळे होतो.\",\"मृदा संधारणासाठी बांध बांधणे, वृक्ष लावणे, खेतीचे पाळणे, कंपोस्ट खत वापरणे उपाय आहेत.\",\"सुपीक मृदा वनस्पतींची वाढीसाठी आवश्यक आहे, त्यामुळे शेती उत्पादन वाढतो.\",\"मृदानिर्मिती प्रक्रिया मोड आहे, हजारो वर्षे लागतात.\"]','[{\"q\":\"मृदेचा रंग, पोत आणि निर्मिती प्रक्रिया यांनुसार महाराष्ट्रात मृदेचे किती प्रमुख प्रकार केले जातात?\",\"options\":[\"तीन\",\"चार\",\"पाच\",\"सहा\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार मृदेचे पाच प्रमुख प्रकार केले जातात.\",\"topic\":\"महाराष्ट्रातील मृदेचे प्रमुख प्रकार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"काळी मृदा खालीलपैकी कोणत्या नावाने ओळखली जाते?\",\"options\":[\"जांभी मृदा\",\"रेगूर मृदा\",\"पिवळसर मृदा\",\"गाळाची मृदा\"],\"answer\":1,\"explain\":\"काळी मृदा रेगूर किंवा काळी कापसाची मृदा या नावाने प्रसिद्ध आहे.\",\"topic\":\"महाराष्ट्रातील मृदेचे प्रमुख प्रकार\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जांभी मृदेचा तांबडा रंग कशामुळे तयार होतो?\",\"options\":[\"ह्युमसच्या प्रमाणामुळे\",\"पावसाच्या कमतरतेमुळे\",\"लोहाचा प्राणवायूशी संयोग झाल्यामुळे\",\"नदीच्या वेगामुळे\"],\"answer\":2,\"explain\":\"खडकातील लोहाचा वातावरणातील प्राणवायूंशी संयोग घडून रासायनिक क्रियेतून हा रंग मिळतो.\",\"topic\":\"महाराष्ट्रातील मृदेचे प्रमुख प्रकार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"कोकणातील नद्यांच्या मुखाशी कोणती मृदा निर्माण झाली आहे?\",\"options\":[\"काळी मृदा\",\"पिवळसर तपकिरी मृदा\",\"किनारपट्टीवरील गाळाची मृदा\",\"रेगूर मृदा\"],\"answer\":2,\"explain\":\"कोकणातील नद्यांनी वाहून आणलेला गाळ मुखाशी साचल्याने किनारपट्टीवरील गाळाची मृदा तयार होते.\",\"topic\":\"महाराष्ट्रातील मृदेचे प्रमुख प्रकार\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"एखादा शेतकरी बालाघाट किंवा महादेव डोंगर रांगांच्या भागात शेती करत असेल, तर तिथे कोण