m\":\"analyze\"},{\"q\":\"चित्रात उंच इमारती दिसत असल्यास, ती कोणत्या प्रकारची वस्ती असेल?\",\"options\":[\"आदिवासी पाडा\",\"ग्रामीण वस्ती\",\"शहर\",\"शेतीची वस्ती\"],\"answer\":2,\"explain\":\"उंच इमारती आणि दाट लोकवस्ती ही शहराची वैशिष्ट्ये आहेत.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"मानवी वस्ती विशिष्ट ठिकाणीच असण्याचे मुख्य कारण काय असावे?\",\"options\":[\"केवळ मनोरंजनासाठी\",\"अनुकूल भौगोलिक परिस्थिती व उपलब्धता\",\"जास्त पाऊस पडतो म्हणून\",\"तेथे रस्ते नसतात म्हणून\"],\"answer\":1,\"explain\":\"मानवी वस्ती कोठे होऊ शकेल याचा अंदाज तेथील नैसर्गिक व भौगोलिक अनुकूलतेवरून लावला जातो.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"चित्रात शेती दिसत असल्यास ती कोणत्या प्रकारची वस्ती असण्याची शक्यता जास्त आहे?\",\"options\":[\"नगर\",\"शहर\",\"ग्रामीण वस्ती\",\"औद्योगिक वस्ती\"],\"answer\":2,\"explain\":\"ग्रामीण वस्तीमध्ये प्रामुख्याने शेती हा व्यवसाय आणि शेतीची जमीन दिसून येते.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"आकृती १०.२ मधील चित्रांचे निरीक्षण करताना कोणत्या बाबीवर विचार करण्यास सांगितले आहे?\",\"options\":[\"चित्रातील रंगांवर\",\"चित्रातील लोकांच्या कपड्यांवर\",\"वस्त्यांमधील दिसणाऱ्या विकासावर\",\"चित्रातील झाडांच्या संख्येवर\"],\"answer\":2,\"explain\":\"मजकुराच्या शेवटी वस्त्यांमधील दिसणाऱ्या विकासावर विचार करून क्रम लावण्यास सांगितले आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"वस्त्या इतर ठिकाणी (उदा. दुर्गम भाग) न दाखवण्याचे कारण काय असू शकते?\",\"options\":[\"तेथे राहण्यासाठी जागा नसते\",\"तेथे जीवन जगण्यासाठी प्रतिकूल परिस्थिती असू शकते\",\"तेथे फक्त प्राणी राहतात\",\"तेथे चित्रे काढता येत नाहीत\"],\"answer\":1,\"explain\":\"मानवी वस्तीसाठी आवश्यक सोयीसुविधा नसलेल्या ठिकाणी वस्त्या स्थापन होत नाहीत.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"दिलेल्या पर्यायांपैकी सर्वात लहान मानवी वस्तीचा प्रकार कोणता?\",\"options\":[\"नगर\",\"शहर\",\"ग्रामीण वस्ती\",\"आदिवासी पाडा\"],\"answer\":3,\"explain\":\"मजकुरातील नावांपैकी \'आदिवासी पाडा\' हा सर्वात प्राथमिक व लहान वस्तीचा प्रकार आहे.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"दाट लोकवस्ती असलेल्या चित्रात खालीलपैकी काय दिसण्याची शक्यता जास्त आहे?\",\"options\":[\"मोठी शेते\",\"खूप कमी घरे\",\"एकमेकांना लागून असलेली घरे व इमारती\",\"केवळ झाडे आणि डोंगर\"],\"answer\":2,\"explain\":\"दाट लोकवस्ती म्हणजे जिथे घरे जवळजवळ आणि जास्त प्रमाणात असतात.\",\"topic\":\"सांगा पाहू !\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मानवी वस्ती विकसित होण्यासाठी खालीलपैकी कोणती भौगोलिक परिस्थिती अनुकूल असते?\",\"options\":[\"पाण्याची कमतरता\",\"सुलभ हवामान\",\"नापीक जमीन\",\"अतिवृष्टी\"],\"answer\":1,\"explain\":\"पाण्याची उपलब्धता, सुलभ हवामान आणि सुपीक जमीन असलेल्या ठिकाणी मानवी वस्ती विकसित होते.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"वस्त्यांच्या सुरुवातीच्या काळात लोकांचे व्यवसाय कशावरून ठरत गेले?\",\"options\":[\"शिक्षणावरून\",\"उपलब्ध साधनसंपत्तीवरून\",\"शासकीय नियमांवरून\",\"परकीय व्यापारावरून\"],\"answer\":1,\"explain\":\"प्रदेशात उपलब्ध असणाऱ्या साधनसंपत्तीवरून लोकांचे व्यवसाय ठरत गेले.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"समुद्रकिनाऱ्यावरील लोकांच्या वस्तीला काय म्हणतात?\",\"options\":[\"आदिवासी पाडा\",\"वाडी\",\"कोळीवाडा\",\"नगर\"],\"answer\":2,\"explain\":\"समुद्रकिनाऱ्यावरील लोकांचा व्यवसाय मासेमारी असतो आणि त्यांच्या वस्तीला कोळीवाडा म्हणतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"वनप्रदेशात राहणाऱ्या आदिवासींच्या वस्तीला कोणत्या नावाने ओळखले जाते?\",\"options\":[\"आदिवासी पाडा\",\"कोळीवाडा\",\"शेतवस्ती\",\"शहर\"],\"answer\":0,\"explain\":\"वनप्रदेशातील लोकांचे व्यवसाय वनांवर अवलंबून असतात आणि त्यांच्या वस्तीला आदिवासी पाडा म्हणतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शेतकरी कुटुंबे आपल्या शेतातच घरे बांधून का राहतात?\",\"options\":[\"करमणुकीसाठी\",\"व्यवसायाच्या सोईच्या दृष्टीने\",\"जमीन वाचवण्यासाठी\",\"वाहतुकीसाठी\"],\"answer\":1,\"explain\":\"शेतकरी आपल्या शेती व्यवसायाच्या सोईसाठी शेतात घरे बांधून राहतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वस्तीचा विस्तार झाल्यावर तिला काय म्हणतात?\",\"options\":[\"शहर\",\"गाव\",\"वाडी\",\"महानगर\"],\"answer\":2,\"explain\":\"कालांतराने वस्तीचा विस्तार झाला की त्यांना वाडी म्हणतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"ग्रामीण वस्ती म्हणजे काय?\",\"options\":[\"जिथे लोक फक्त नोकरी करतात\",\"जिथे बहुसंख्य लोकांचे व्यवसाय स्थानिक नैसर्गिक साधनसंपत्तीशी निगडित असतात\",\"जिथे फक्त कारखाने असतात\",\"जिथे लोक फक्त व्यापारासाठी येतात\"],\"answer\":1,\"explain\":\"ज्या वस्तीतील लोकांचे मूळ व्यवसाय स्थानिक नैसर्गिक साधनसंपत्तीशी निगडित असतात, तिला ग्रामीण वस्ती म्हणतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता व्यवसाय ग्रामीण वस्तीतील लोकांचा मूळ व्यवसाय असू शकतो?\",\"options\":[\"सॉफ्टवेअर इंजिनिअरिंग\",\"बँकिंग\",\"खाणकाम\",\"विमान चालवणे\"],\"answer\":2,\"explain\":\"शेती, मासेमारी आणि खाणकाम हे नैसर्गिक साधनसंपत्तीशी निगडित ग्रामीण व्यवसाय आहेत.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"जर एखाद्या प्रदेशात सुपीक जमीन उपलब्ध असेल, तर तेथे प्रामुख्याने कोणती वस्ती विकसित होईल?\",\"options\":[\"कोळीवाडा\",\"आदिवासी पाडा\",\"शेतकऱ्यांची वस्ती\",\"खाणकाम वस्ती\"],\"answer\":2,\"explain\":\"सुपीक जमीन असलेल्या ठिकाणी शेती व्यवसाय केला जातो, म्हणून तिथे शेतकऱ्यांची वस्ती विकसित होते.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"वस्त्यांच्या निर्मितीचा योग्य क्रम कोणता असू शकतो?\",\"options\":[\"वाडी -> वस्ती -> शहर\",\"वस्ती -> वाडी -> ग्रामीण वस्ती\",\"शहर -> वाडी -> वस्ती\",\"ग्रामीण वस्ती -> शहर -> वस्ती\"],\"answer\":1,\"explain\":\"सुरुवातीला वस्ती निर्माण होते, तिचा विस्तार झाल्यावर वाडी होते आणि अशा वस्त्यांना ग्रामीण वस्ती म्हणतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"नैसर्गिक साधनसंपत्ती आणि मानवी वस्ती यांचा संबंध कसा आहे?\",\"options\":[\"साधनसंपत्तीचा वस्तीवर कोणताही परिणाम होत नाही\",\"साधनसंपत्तीमुळे फक्त शहरांचा विकास होतो\",\"उपलब्ध साधनसंपत्तीनुसार लोकांचे व्यवसाय आणि वस्त्यांचे प्रकार ठरतात\",\"केवळ हवामानामुळे वस्त्या ठरतात\"],\"answer\":2,\"explain\":\"साधनसंपत्तीवरून लोकांचे व्यवसाय आणि त्यावरून विशिष्ट समूहांच्या स्वतंत्र वस्त्या निर्माण होतात.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता घटक मानवी वस्तीच्या विकासासाठी कारणीभूत नाही असे उताऱ्यावरून वाटते?\",\"options\":[\"पाण्याची उपलब्धता\",\"सुलभ हवामान\",\"मोठी बाजारपेठ\",\"सुपीक जमीन\"],\"answer\":2,\"explain\":\"उताऱ्यात पाणी, हवामान आणि जमीन हे घटक दिले आहेत, बाजारपेठेचा उल्लेख भौगोलिक स्पष्टीकरणात नाही.\",\"topic\":\"भौगोलिक स्पष्टीकरण\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"ग्रामीण वस्तीचे नागरी वस्तीत रूपांतर होताना प्राथमिक व्यवसायांचे प्रमाण काय होते?\",\"options\":[\"वाढते\",\"कमी होते\",\"स्थिर राहते\",\"दुप्पट होते\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, नागरी वस्तीत रूपांतर होताना जुन्या प्राथमिक व्यवसायांचे प्रमाण कमी होत जाते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"आजूबाजूच्या प्रदेशातील लोक ग्रामीण वस्तीत येऊन स्थायिक होण्याचे मुख्य कारण काय असते?\",\"options\":[\"केवळ फिरण्यासाठी\",\"शेती करण्यासाठी\",\"कामाधंद्यानिमित्त\",\"पर्यावरणासाठी\"],\"answer\":2,\"explain\":\"कामाधंद्यानिमित्त आजूबाजूच्या प्रदेशांतील लोक तेथे येऊन स्थायिक होऊ लागतात.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"मोठ्या प्रमाणात लोकसंख्या व इतर सोईसुविधांमुळे शहराचे रूपांतर कशात होते?\",\"options\":[\"खेड्यात\",\"महानगरात\",\"वाड्यावस्त्यांत\",\"जिल्ह्यात\"],\"answer\":1,\"explain\":\"वाढत्या लोकसंख्या व सोईसुविधांमुळे शहराचे रूपांतर पुढे महानगरात होते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"नागरी वस्तीत कोणत्या प्रकारच्या व्यवसायांचे महत्त्व व प्रमाण वाढते?\",\"options\":[\"प्राथमिक व द्वितीयक\",\"केवळ प्राथमिक\",\"द्वितीयक व तृतीयक\",\"केवळ चतुर्थक\"],\"answer\":2,\"explain\":\"नागरी वस्तीत द्वितीयक व तृतीयक व्यवसायांचे महत्त्व व प्रमाण वाढते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"एखाद्या ग्रामीण वस्तीत पर्यटनाची सोय उपलब्ध झाली, तर त्या वस्तीचे रूपांतर कशात होऊ शकते?\",\"options\":[\"शहरात\",\"जंगलात\",\"शेतात\",\"तांड्यात\"],\"answer\":0,\"explain\":\"पर्यटन, धार्मिक, ऐतिहासिक अशा कारणांमुळे वस्तीचे रूपांतर शहरात होते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"ग्रामीण वस्तीत पूरक व्यवसायांची वाढ कशामुळे होते?\",\"options\":[\"केवळ पर्यटनामुळे\",\"मूळ व्यवसायाच्या अनुषंगाने\",\"शासकीय आदेशामुळे\",\"केवळ शिक्षणामुळे\"],\"answer\":1,\"explain\":\"ग्रामीण वस्तीत मूळ व्यवसायाच्या अनुषंगाने हळूहळू इतरही पूरक व्यवसायांची वाढ होत जाते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते कारण वस्तीचे शहरात रूपांतर होण्यासाठी उताऱ्यात दिलेले नाही?\",\"options\":[\"व्यापारी\",\"प्रशासकीय\",\"ऐतिहासिक\",\"नैसर्गिक आपत्ती\"],\"answer\":3,\"explain\":\"धार्मिक, ऐतिहासिक, व्यापारी, शैक्षणिक, पर्यटन व प्रशासकीय ही कारणे उताऱ्यात दिली आहेत, नैसर्गिक आपत्ती नाही.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"वाढत्या लोकसंख्येला राहण्यासाठी ग्रामीण वस्तीत कशाचा विकास केला जातो?\",\"options\":[\"केवळ शेतजमिनीचा\",\"घरे व विविध सुविधांचा\",\"केवळ रस्त्यांचा\",\"केवळ विहिरींचा\"],\"answer\":1,\"explain\":\"वाढत्या लोकसंख्येला राहण्यासाठी घरे, तसेच विविध सुविधा विकसित केल्या जातात.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"एका गावात नवीन कारखाने (द्वितीयक व्यवसाय) आणि बँका (तृतीयक व्यवसाय) सुरू झाल्या आहेत. उताऱ्याच्या आधारे तिथे कोणता बदल अपेक्षित आहे?\",\"options\":[\"ती वस्ती नष्ट होईल\",\"तिथे लोकसंख्या कमी होईल\",\"तिचे रूपांतर नागरी वस्तीत होईल\",\"तिथे फक्त शेतीच केली जाईल\"],\"answer\":2,\"explain\":\"द्वितीयक व तृतीयक व्यवसायांचे प्रमाण वाढल्यास ग्रामीण वस्तीचे रूपांतर नागरी वस्तीत होते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"ग्रामीण वस्तीचे महानगरात रूपांतर होण्याच्या प्रक्रियेचा योग्य क्रम कोणता?\",\"options\":[\"महानगर -> शहर -> ग्रामीण वस्ती\",\"ग्रामीण वस्ती -> शहर -> महानगर\",\"शहर -> महानगर -> ग्रामीण वस्ती\",\"ग्रामीण वस्ती -> महानगर -> शहर\"],\"answer\":1,\"explain\":\"प्रथम ग्रामीण वस्तीचे शहरात आणि नंतर शहराचे महानगरात रूपांतर होते.\",\"topic\":\"ग्रामीण व नागरी वस्ती\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"आकृती १०.३ मधील चित्र \'अ\' आणि \'ब\' मधील निरीक्षणातून काय स्पष्ट होते?\",\"options\":[\"दोन्ही वस्त्या समान आहेत\",\"मानवी वस्त्यांमध्ये फरक आढळतो\",\"वस्त्यांमध्ये फक्त झाडे आहेत\",\"वस्त्यांमध्ये रस्ते नाहीत\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील प्रश्नानुसार चित्र \'अ\' आणि \'ब\' मधील मानवी वस्तीत फरक आढळतो.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"निसर्गामध्ये असलेल्या स्थितीनुसार मानवी वस्तींचे काय निर्माण होतात?\",\"options\":[\"आकृतिबंध\",\"नकाशे\",\"रस्ते\",\"पर्वत\"],\"answer\":0,\"explain\":\"निसर्गातील स्थितीनुसार मानवी वस्तींचे आकृतिबंध निर्माण होतात असे मजकुरात नमूद आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"आकृती १०.४ मध्ये वस्त्या कशा स्वरूपात आढळतात?\",\"options\":[\"केवळ एकाच ठिकाणी\",\"विखुरलेल्या स्वरूपात\",\"फक्त डोंगरावर\",\"फक्त नदीकाठी\"],\"answer\":1,\"explain\":\"नकाशात काही ठिकाणी वस्त्या विखुरलेल्या स्वरूपात असल्याचे मजकुरात विचारले आहे.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"मानव वेगवेगळ्या नैसर्गिक परिस्थितींमध्ये राहताना काय करतो?\",\"options\":[\"निसर्गाचा नाश करतो\",\"निसर्गाशी जुळवून घेतो\",\"निसर्गाला बदलतो\",\"निसर्गाकडे दुर्लक्ष करतो\"],\"answer\":1,\"explain\":\"मानव वेगवेगळ्या नैसर्गिक परिस्थितींमध्ये वस्ती करून राहतो व तेथील निसर्गाशी जुळवून घेतो.\",\"topic\":\"नकाशाशी मैत्री\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दोनपेक्षा कमी घरे असणारी वस्ती शोधण्यासाठी कोणत्या आकृतीचे निरीक्षण करण्यास सांगितले आहे?\",\"options\":[\"आकृती १०.१\",\"आकृती १०.२