":\"आकृती ११.२ (ब) मध्ये समोच्चरेषा नकाशा दिला असल्याचे मजकुरात म्हटले आहे.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"नकाशात पुरंदर किल्ला कोणत्या दिशेला आहे, हे शोधण्यासाठी तुम्हाला प्रामुख्याने काय वापरावे लागेल?\",\"options\":[\"नकाशातील दिशाचक्र\",\"नदीचा प्रवाह\",\"रस्त्यांची लांबी\",\"खोऱ्याचे नाव\"],\"answer\":0,\"explain\":\"कोणत्याही ठिकाणाची दिशा शोधण्यासाठी नकाशातील दिशाचक्र (North arrow) वापरले जाते.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"नकाशातील कऱ्हा नदीच्या प्रवाहाची दिशा ओळखण्यासाठी कशाचे निरीक्षण करणे आवश्यक आहे?\",\"options\":[\"केवळ झाडांचे\",\"उताराची दिशा व समोच्च रेषा\",\"किल्ल्याची उंची\",\"नकाशाचा रंग\"],\"answer\":1,\"explain\":\"नदी नेहमी उंचाकडून सखल भागाकडे वाहते, जे समोच्च रेषांवरून समजते.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"प्रतिकृतीतील काही भाग नकाशात असूनही दिसत नाही, याचे संभाव्य कारण काय असू शकते?\",\"options\":[\"नकाशा चुकीचा आहे\",\"तो भाग अस्तित्वात नाही\",\"भूरूपाची उंची आणि पाहण्याचा कोन\",\"नदीचा वेग जास्त आहे\"],\"answer\":2,\"explain\":\"त्रिमितीय प्रतिकृतीत उंच भागामुळे त्यामागील सखल भाग झाकला जाऊ शकतो.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"कात्रज-दिवेघाट डोंगरांगेची उंची कोणत्या दिशेने वाढत गेली आहे, हे कशावरून ठरवता येईल?\",\"options\":[\"नदीच्या नावाने\",\"समोच्च रेषांवरील वाढत्या मूल्यांवरून\",\"किल्ल्याच्या नावावरून\",\"नकाशाच्या आकारावरून\"],\"answer\":1,\"explain\":\"समोच्च रेषांवरील आकडे उंची दर्शवतात, त्यावरून उंची वाढण्याची दिशा समजते.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"नकाशात कोणत्या बाजूला डोंगरांग नाही, हे ओळखण्यासाठी कोणती खूण महत्त्वाची ठरेल?\",\"options\":[\"समोच्च रेषांची विरळता किंवा अभाव\",\"नदीचा उगम\",\"किल्ल्याचे स्थान\",\"नकाशाची चौकट\"],\"answer\":0,\"explain\":\"ज्या भागात समोच्च रेषा नसतात किंवा खूप लांब असतात, तिथे डोंगराळ भाग नसतो.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"उंच डोंगरांगा कोणत्या दिशेला आहेत हे शोधणे, हे कशाचे उदाहरण आहे?\",\"options\":[\"नकाशा वाचन\",\"नकाशा काढणे\",\"नकाशा रंगवणे\",\"नकाशाची घडी घालणे\"],\"answer\":0,\"explain\":\"दिलेल्या माहितीवरून दिशा आणि भूरूपे ओळखणे म्हणजे नकाशा वाचन होय.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"सासवड कड्यावरील नकाशा कोणत्या आकृती क्रमांकात दर्शवला आहे?\",\"options\":[\"११.१\",\"११.२ (ब)\",\"११.५\",\"११.२ (अ)\"],\"answer\":1,\"explain\":\"मजकुरात ११.२ (ब) हा सासवड कड्यावरील नकाशा असल्याचे स्पष्ट केले आहे.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"कात्रज-दिवेघाट डोंगरांगेच्या पलीकडे कोणता भाग दिसत आहे?\",\"options\":[\"अरबी समुद्र\",\"सह्याद्रीचे मुख्य शिखर\",\"मुळा-मुठा नद्यांच्या खोऱ्याचा काही भाग\",\"थरचे वाळवंट\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केले आहे की डोंगरांगेच्या पलीकडे मुळा-मुठा खोऱ्याचा काही भाग दिसत आहे.\",\"topic\":\"जरा डोके चालवा !\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"समुद्रसपाटीपासूनची उंची मोजण्यासाठी कोणत्या एककाचा वापर केला जातो?\",\"options\":[\"सेंटीमीटर\",\"मीटर\",\"किलोमीटर\",\"मिलीमीटर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील मजकुरानुसार, समुद्रसपाटीपासूनची उंची मीटरमध्ये मोजली जाते.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"उपक्रमात सांगितल्याप्रमाणे, प्रत्येक समोच्च रेषेतील अंतर जास्तीत जास्त किती मीटर घ्यावे?\",\"options\":[\"१० मीटर\",\"२५ मीटर\",\"५० मीटर\",\"१०० मीटर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात प्रत्येक समोच्च रेषेतील अंतर जास्तीत जास्त ५० मीटर घेण्यास सांगितले आहे.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"समोच्च रेषांच्या मदतीने आपण नकाशातील काय ओळखू शकतो?\",\"options\":[\"लोकसंख्या\",\"प्रमुख भूरूपे\",\"पिकांचे प्रकार\",\"हवेचा दाब\"],\"answer\":1,\"explain\":\"समोच्च रेषांमुळे नकाशातील प्रमुख भूरूपे ओळखण्यास मदत होते.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या गावाच्या उंचीपर्यंत ५० मीटरच्या अंतराने ४ समोच्च रेषा काढल्या असतील, तर त्या गावाची उंची साधारणपणे किती असेल?\",\"options\":[\"५० मीटर\",\"१०० मीटर\",\"१५० मीटर\",\"२०० मीटर\"],\"answer\":3,\"explain\":\"४ रेषा गुणिले ५० मीटर अंतर म्हणजे एकूण २०० मीटर उंची (५०, १००, १५०, २००).\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या आकृतीत, डोंगराच्या सर्वात उंच भागाला (शिखराला) कोणते अक्षर दिले आहे?\",\"options\":[\"अ\",\"ब\",\"क\",\"ड\"],\"answer\":0,\"explain\":\"आकृती ११.४ मध्ये डोंगराच्या शिखरावर \'अ\' हे अक्षर दिलेले आहे.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"apply\",\"figure_image\":\"49\\/083_103.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण केल्यास, डोंगराच्या कोणत्या बाजूने चढणे अधिक सहज व सुरक्षित असेल?\",\"options\":[\"ज्या बाजूला रेषा एकमेकींच्या खूप जवळ आहेत\",\"ज्या बाजूला रेषांमधील अंतर जास्त आहे\",\"ज्या बाजूला रेषांची संख्या कमी आहे\",\"ज्या बाजूला रेषा वक्राकार आहेत\"],\"answer\":1,\"explain\":\"समोच्च रेषांमधील अंतर जास्त असल्यास उतार मंद असतो, जो मार्ग सुरक्षित असतो.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"49\\/083_103.jpg\"},{\"q\":\"गिर्यारोहणासाठी डोंगरावर चढताना कोणता मार्ग निवडणे योग्य ठरते?\",\"options\":[\"खूप तीव्र उताराचा मार्ग\",\"समोच्च रेषा जवळ असलेला मार्ग\",\"समोच्च रेषांमधील अंतर जास्त असलेला मार्ग\",\"उंची जास्त असलेला मार्ग\"],\"answer\":2,\"explain\":\"रेषांमधील अंतर जास्त असल्यास उतार मंद असतो, जो गिर्यारोहणासाठी सोयीचा असतो.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"समोच्च रेषा नकाशात उंची कशाच्या संदर्भात मोजली जाते?\",\"options\":[\"नदीच्या पातळीपासून\",\"जमिनीच्या पातळीपासून\",\"समुद्रसपाटीपासून\",\"ढगांच्या पातळीपासून\"],\"answer\":2,\"explain\":\"उंची नेहमी समुद्रसपाटीपासून मोजली जाते.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर समोच्च रेषा एकमेकींच्या खूप जवळ असतील, तर त्या भागातील उतार कसा असतो?\",\"options\":[\"मंद\",\"तीव्र\",\"सपाट\",\"समान\"],\"answer\":1,\"explain\":\"समोच्च रेषा जवळ असणे म्हणजे त्या भागाचा उतार तीव्र असणे होय.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"नकाशातील समोच्च रेषांचे निरीक्षण करून मार्ग ठरवणे हे कशाचे उदाहरण आहे?\",\"options\":[\"नकाशा वाचन\",\"नकाशा काढणे\",\"नकाशा रंगवणे\",\"नकाशाची छपाई\"],\"answer\":0,\"explain\":\"समोच्च रेषांच्या आधारे मार्ग शोधणे ही नकाशा वाचनाची प्रक्रिया आहे.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"डोंगराच्या शिखरावर पोहोचण्यासाठी \'सुरक्षित मार्ग\' निवडताना तुम्ही प्रामुख्याने काय पाहाल?\",\"options\":[\"रेषांचा रंग\",\"रेषांमधील अंतर\",\"रेषांची लांबी\",\"रेषांचा क्रमांक\"],\"answer\":1,\"explain\":\"उताराचे स्वरूप समजण्यासाठी रेषांमधील अंतर पाहणे आवश्यक असते.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"एका डोंगराची उंची ३०० मीटर आहे. ५० मीटरच्या अंतराने समोच्च रेषा काढल्यास, सर्वात शेवटच्या (वरच्या) रेषेवर कोणता आकडा असेल?\",\"options\":[\"५०\",\"१५०\",\"२५०\",\"३००\"],\"answer\":3,\"explain\":\"समोच्च रेषेवर त्या रेषेची समुद्रसपाटीपासूनची उंची दर्शवलेली असते.\",\"topic\":\"उपक्रम व नकाशा वाचन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"चंद्राच्या पृथ्वीपासून सर्वाधिक दूरच्या स्थितीस काय म्हणतात?\",\"options\":[\"उपभू\",\"अपभू\",\"अपसूर्य\",\"उपसूर्य\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, चंद्राच्या पृथ्वीपासून सर्वाधिक दूरच्या स्थितीस \'अपभू\' म्हणतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीची सूर्यापासून सर्वाधिक दूरची स्थिती (अपभू) कोणत्या महिन्यात येते?\",\"options\":[\"जानेवारी\",\"जून\",\"जुलै\",\"डिसेंबर\"],\"answer\":2,\"explain\":\"पृथ्वीची सूर्यापासून सर्वाधिक दूरची स्थिती जुलै महिन्यात येते.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जास्त पाऊस असलेल्या प्रदेशात मृदेतील क्षार पाण्यात विरघळून वाहून जाण्याच्या प्रक्रियेला काय म्हणतात?\",\"options\":[\"अपक्षालन\",\"मृदा अवनती\",\"मृदेची धूप\",\"ह्युमस\"],\"answer\":0,\"explain\":\"जास्त पावसाच्या प्रदेशात क्षार पाण्यात विरघळून वाहून जाण्याला \'अपक्षालन\' (Leaching) म्हणतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"२१ जून रोजी सूर्यकिरणे कोणत्या वृत्तावर लंबरूप पडतात?\",\"options\":[\"विषुववृत्त\",\"मकरवृत्त\",\"कर्कवृत्त\",\"आर्क्टिक वृत्त\"],\"answer\":2,\"explain\":\"२१ जून रोजी उत्तर ध्रुव सूर्याकडे कलेला असतो आणि कर्कवृत्तावर सूर्यकिरणे लंबरूप पडतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"दोन्ही गोलार्धातील २५° ते ३०° अक्षवृत्तीय प्रदेशाला \'अश्व अक्षांश\' का म्हणतात?\",\"options\":[\"तेथे खूप वारे वाहतात\",\"तेथे हवेचा दाब जास्त असल्याने हवा शांत असते\",\"तेथे पावसाचे प्रमाण जास्त असते\",\"तेथे चक्रीवादळे येतात\"],\"answer\":1,\"explain\":\"या प्रदेशात जास्त दाबाचे पट्टे असल्याने हवा शांत असते, म्हणून याला अश्व अक्षांश म्हणतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर एखादी वस्ती नदी किंवा कालव्याच्या कडेने विकसित झाली असेल, तर त्या वस्तीचा आकृतिबंध कसा असेल?\",\"options\":[\"केंद्रित वस्ती\",\"विखुरलेली वस्ती\",\"रेषाकृती वस्ती\",\"चक्राकार वस्ती\"],\"answer\":2,\"explain\":\"रस्ता, कालवा किंवा नदीलगतच्या वस्त्यांची मांडणी रेषात्मक असते, तिला रेषाकृती वस्ती म्हणतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"भारतीय उपखंडात खालीलपैकी कोणत्या देशाचा समावेश होत नाही?\",\"options\":[\"पाकिस्तान\",\"श्रीलंका\",\"म्यानमार\",\"भूतान\"],\"answer\":2,\"explain\":\"भारतीय उपखंडात भारत, पाकिस्तान, बांगलादेश, नेपाळ, भूतान व श्रीलंका यांचा समावेश होतो; म्यानमारचा नाही.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"सूर्यग्रहणाच्या वेळी चंद्र \'अपभू\' स्थितीत असल्यास कोणते सूर्यग्रहण दिसते?\",\"options\":[\"खग्रास सूर्यग्रहण\",\"खंडग्रास सूर्यग्रहण\",\"कंकणाकृती सूर्यग्रहण\",\"चंद्रग्रहण\"],\"answer\":2,\"explain\":\"अपभू स्थितीत चंद्र लांब असल्याने त्याची सावली पृथ्वीपर्यंत पोहोचत नाही, त्यामुळे बांगडीसारखी कडा दिसणारे कंकणाकृती ग्रहण होते.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"गुरुत्वाकर्षण बलाचे (F) अचूक सूत्र कोणते आहे?\",\"options\":[\"F = G M1 M2 \\/ D\",\"F = G M1 M2 \\/ D2\",\"F = G M1 \\/ D2\",\"F = G M2 \\/ D2\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील परिशिष्टानुसार गुरुत्वाकर्षण बलाचे सूत्र F = G M1 M2 \\/ D2 असे आहे.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"शुक्ल व कृष्ण पक्षातील अष्टमीला येणाऱ्या भरती-ओहोटीची कक्षा कमी का असते?\",\"options\":[\"चंद्र पृथ्वीपासून लांब असतो\",\"सूर्य पृथ्वीच्या जवळ असतो\",\"चंद्र, सूर्य व पृथ्वी काटकोन स्थितीत असतात\",\"पृथ्वीचा अक्ष कलेला असतो\"],\"answer\":2,\"explain\":\"अष्टमीला चंद्र, सूर्य व पृथ्वी काटकोन स्थितीत असल्याने त्यांची गुरुत्वाकर्षण बले एकमेकांस पूरक राहत नाहीत.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"मृदेतील ह्युमसचे प्रमाण कमी झाल्याने किंवा अनावश्यक रसायने मिसळल्याने काय घडते?\",\"options\":[\"मृदेची धूप\",\"मृदा अवनती\",\"अपक्षालन\",\"मृदा निर्मिती\"],\"answer\":1,\"explain\":\"मृदेचा गुणात्मक ऱ्हास होणे म्हणजेच \'मृदा अवनती\' होय.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"एका प्रयोगशाळेत एका द्रवाचे सामू (pH) मूल्य ७ आढळले, तर तो पदार्थ कोणत्या प्रकारचा आहे?\",\"options\":[\"आम्ल धर्मी\",\"अल्कली धर्मी\",\"उदासीन\",\"क्षारयुक्त\"],\"answer\":2,\"explain\":\"सामूचे मूल्य ७ असल्यास तो पदार्थ \'उदासीन\' असतो.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"२१ मार्च या दिवशी पृथ्वीवर दिनमान व रात्रीमान सारखे असते, या स्थितीला काय म्हणतात?\",\"options\":[\"शरद संपात\",\"वसंत संपात\",\"उन्हाळ्यातील अपसूर्य\",\"हिवाळ्यातील अपसूर्य\"],\"answer\":1,\"explain\":\"२१ मार्च रोजी होणाऱ्या संपात स्थितीला \'वसंत संपात\' म्हणतात.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"समुद्रसपाटीजवळ हवेचा दाब किती असतो?\",\"options\":[\"९१३.२ मिलिबार\",\"१०१३.२ मिलिबार\",\"१११३.२ मिलिबार\",\"८१३.२ मिलिबार\"],\"answer\":1,\"explain\":\"समुद्रसपाटीजवळ हवेचा दाब १०१३.२ मिलिबार इतका असतो.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"मृदेची धूप आणि मृदा अवनती यांमधील मुख्य फरक काय आहे?\",\"options\":[\"धूप म्हणजे गुणवत्ता कमी होणे, अवनती म्हणजे थर वाहून जाणे\",\"धूप म्हणजे थर वाहून जाणे, अवनती म्हणजे गुणवत्ता कमी होणे\",\"दोन्ही प्रक्रिया एकाच आहेत\",\"धूप केवळ पाण्यामुळे होते, अवनती केवळ वाऱ्यामुळे होते\"],\"answer\":1,\"explain\":\"मृदेचे थर वाहून जाणे म्हणजे धूप, तर गुणात्मक ऱ्हास होणे म्हणजे अवनती होय.\",\"topic\":\"परिशिष्ट: भौगोलिक शब्दार्थ\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"\'Physical Geography in Diagrams\' या पुस्तकाचे लेखक कोण आहेत?\",\"options\":[\"A. N. Strahler\",\"G. T. Miller\",\"R.B. Bunnett\",\"Monkhouse\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील संदर्भ साहित्यानुसार \'Physical Geography in Diagrams\' हे पुस्तक R.B. Bunnett यांनी लिहिले आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'J. T. Molesworth आणि T. Candy\' यांनी कोणते संदर्भ साहित्य तयार केले आहे?\",\"options\":[\"मराठी विश्वकोश\",\"इंग्रजी मराठी शब्दकोश\",\"प्राकृतिक भूगोल\",\"एकांकिका संग्रह\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात दिलेल्या माहितीनुसार J. T. Molesworth आणि T. Candy यांचा इंग्रजी मराठी शब्दकोश संदर्भासाठी दिला आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"मराठी विश्वकोशाचे खालीलपैकी कोणते खंड संदर्भासाठी सुचवले आहेत?\",\"options\":[\"खंड २ व ३\",\"खंड ५ व ६\",\"खंड ९ व १७\",\"खंड १० व १२\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात मराठी विश्वकोश खंड १, ४, ९, १७ व १८ संदर्भासाठी दिले आहेत.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"शालेय विद्यार्थ्यांसाठी भौगोलिक माहिती मिळवण्यासाठी खालीलपैकी कोणते संकेतस्थळ (website) पाठ्यपुस्तकात दिले आहे?\",\"options\":[\"www.kidsgeog.com\",\"www.google.com\",\"www.maharashtra.gov.in\",\"www.balbharati.in\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकात संदर्भासाठी www.kidsgeog.com हे संकेतस्थळ दिले आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"\'किशोर\' मासिकातील साहित्यामध्ये खालीलपैकी कोणत्या प्रकारच्या साहित्याचा समावेश नाही?\",\"options\":[\"कविता\",\"विज्ञान\",\"दैनिक बातम्या\",\"लोककथा\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार किशोर मासिकात कथा, कविता, कादंबरीका, एकांकिका, विज्ञान आणि लोककथा असतात, पण दैनिक बातम्यांचा उल्लेख नाही.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"\'Living in the Environment\' हे पुस्तक कोणी लिहिले आहे?\",\"options\":[\"A. N. Strahler\",\"G. T. Miller\",\"Monkhouse\",\"R.B. Bunnett\"],\"answer\":1,\"explain\":\"संदर्भ साहित्याच्या यादीनुसार \'Living in the Environment\' हे पुस्तक G. T. Miller यांनी लिहिले आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रात \'निवडक किशोर\'च्या १४ खंडांची एकूण किंमत किती रुपये दर्शवली आहे?\",\"options\":[\"₹ १६३\\/-\",\"₹ ४८.००\",\"₹ १६००\\/-\",\"₹ ३८.००\"],\"answer\":2,\"explain\":\"चित्रात खालील बाजूस १४ खंडांची एकूण किंमत ₹ १६००\\/- अशी स्पष्टपणे दिली आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"apply\",\"figure_image\":\"49\\/091_101.jpg\"},{\"q\":\"भूगोल विषयाच्या सखोल अभ्यासासाठी \'Encyclopaedia Britannica\' चे कोणते खंड उपयुक्त आहेत?\",\"options\":[\"खंड १ व २\",\"खंड ५ व २१\",\"खंड १० व १५\",\"खंड २० व २५\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात Encyclopaedia Britannica Vol. 5 and 21 चा संदर्भ दिला आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रात इयत्ता सातवीच्या भूगोल पाठ्यपुस्तकाची किंमत किती रुपये छापली आहे?\",\"options\":[\"₹ ४८.००\",\"₹ ३८.००\",\"₹ १६३.००\",\"₹ १६००.००\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकाच्या मागील पृष्ठाच्या चित्रात उजव्या कोपऱ्यात किंमत ₹ ३८.०० अशी छापली आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"understand\",\"figure_image\":\"49\\/092_101.jpg\"},{\"q\":\"महाराष्ट्र राज्य पाठ्यपुस्तक निर्मिती व अभ्यासक्रम संशोधन मंडळ कोणत्या शहरात स्थित आहे?\",\"options\":[\"मुंबई\",\"नागपूर\",\"पुणे\",\"छत्रपती संभाजीनगर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार हे मंडळ पुणे शहरात आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"\'प्राकृतिक भूगोल\' या मराठी संदर्भ पुस्तकाचे लेखक कोण आहेत?\",\"options\":[\"प्रा. दाते व सौ. दाते\",\"J. T. Molesworth\",\"A. N. Strahler\",\"T. Candy\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील संदर्भ साहित्यानुसार \'प्राकृतिक भूगोल\' हे पुस्तक प्रा. दाते व सौ. दाते यांनी लिहिले आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पाठ्यपुस्तकात दिलेल्या माहितीनुसार, \'निवडक किशोर\'चे किती खंड उपलब्ध आहेत?\",\"options\":[\"१० खंड\",\"१२ खंड\",\"१४ खंड\",\"१८ खंड\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात आणि चित्रात \'निवडक किशोर\'चे १४ खंड असल्याचे नमूद केले आहे.\",\"topic\":\"संदर्भ साहित्य व इतर माहिती\",\"part\":10,\"bloom\":\"evaluate\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29'),(22037,51,7,'History & Civics','mr','इतिहासाची साधने','[\"भौतिक साधने म्हणजे इमारती, स्मारके, किल्ले, नाणी, शिलालेख व इतर अवशेष ज्याद्वारे भूतकाळातील घटना समजतात.\",\"लिखित साधने म्हणजे ग्रंथ, पत्रे, ताम्रपट, भूर्जपत्रे, प्रवासवर्णने व इतर लेखी दस्तऐवज.\",\"मौखिक साधने म्हणजे लोकगीते, पोवाडे, दंतकथा, तवारिखा आणि प्रवासी वर्णने.\",\"शिलालेख हे दगडावर कोरलेले लेख असून इतिहासलेखनाचे विश्वसनीय पुरावे मानले जातात.\",\"नाणी इतिहास सांगतात कारण त्यावर राज्यकर्त्यांची नावे, धर्म, कला व आर्थिक स्थिती दर्शविली जाते.\",\"किल्ल्यांचे प्रकार: गिरिदुर्ग, वनदुर्ग, जलदुर्ग, भुईकोट.\",\"भौतिक साधनांमधून वास्तुकलेची प्रगती व समाजाचे राहणीमान समजते.\",\"लिखित साधनांमधून भाषा, लिपी, समाजजीवन व राजकीय संबंध समजतात.\",\"मौखिक साधनांमधून लोकजीवन, परंपरा व सांस्कृतिक मूल्ये जाणवतात.\",\"इतिहास लिहिताना स्रोतांची विश्वसनीयता, अस्सलपणा व तटस्थता तपासणे आवश्यक आहे.\",\"स्रोतांचे मूल्यमापन करताना अतिरंजना, लेखकाचा पक्षपात व ऐतिहासिक संदर्भ लक्षात घ्यावा.\",\"भौतिक साधनांचे वर्गीकरण: स्मारके, नाणी, शिलालेख, इमारती व इतर अवशेष.\",\"लिखित साधनांचे वर्गीकरण: ताम्रपट, भूर्जपत्रे, ग्रंथ, प्रवासवर्णने.\",\"मौखिक साधनांचे वर्गीकरण: पोवाडे, दंतकथा, ओव्या, तवारिखा.\",\"इतिहासाची व्याख्या: \'इति\' + \'ह\' + \'आस्\' म्हणजे \'असे घडले\'.\",\"भौतिक साधनांमध्ये किल्ले व स्मारकांद्वारे काळाची ओळख पटते.\",\"लिखित साधनांमध्ये राजदरबारातील वंशावळी व पत्रव्यवहार महत्त्वाचे.\",\"मौखिक साधनांमध्ये परकीय प्रवाशांची वर्णने व लोकगीते महत्त्वाची.\",\"भौतिक साधनांमधून वास्तुकलेचे शैली व कलात्मक स्तर समजतात.\",\"लिखित साधनांमधून आर्थिक व्यवहार व धातूशास्त्राची प्रगती स्पष्ट होते.\",\"मौखिक साधनांमधून सामाजिक व सांस्कृतिक जीवनाची झलक मिळते.\",\"स्रोतांचे मूल्यमापन करताना अस्सल व बनावट यातील फरक ओळखणे आवश्यक.\",\"इतिहासलेखनात लेखकाच्या तटस्थतेची तपासणी करणे महत्त्वाचे.\",\"भौतिक साधने: स्मारके, किल्ले, नाणी, शिलालेख.\",\"लिखित साधने: ताम्रपट, भूर्जपत्रे, ग्रंथ, प्रवासवर्णने.\"]','[{\"q\":\"मागील वर्षी (इयत्ता सहावीत) आपण भारताच्या कोणत्या कालखंडाचा अभ्यास केला आहे?\",\"options\":[\"मध्ययुगीन कालखंड\",\"प्राचीन कालखंड\",\"आधुनिक कालखंड\",\"प्रागैतिहासिक कालखंड\"],\"answer\":1,\"explain\":\"मजकुराच्या पहिल्या ओळीनुसार, मागील वर्षी प्राचीन कालखंडाचा अभ्यास केला आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भारतीय इतिहासातील मध्ययुगाचा कालखंड ढोबळमानाने कोणत्या शतकापासून सुरू होतो?\",\"options\":[\"पाचव्या शतकापासून\",\"सातव्या शतकापासून\",\"नवव्या शतकापासून\",\"दहाव्या शतकापासून\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट नमूद केले आहे की मध्ययुगाचा कालखंड इसवी सनाच्या नवव्या शतकापासून सुरू होतो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मध्ययुगीन कालखंडाची व्याप्ती कोणत्या शतकाअखेरपर्यंत मानली जाते?\",\"options\":[\"पंधराव्या\",\"सोळाव्या\",\"सतराव्या\",\"अठराव्या\"],\"answer\":3,\"explain\":\"भारतीय इतिहासातील मध्ययुगाचा कालखंड अठराव्या शतकाअखेरपर्यंतचा मानला जातो.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"इतिहास म्हणजे काय?\",\"options\":[\"केवळ जुन्या कथांची माहिती\",\"भूतकाळात घडलेल्या घटनांची शास्त्रशुद्ध माहिती\",\"भविष्यात घडणाऱ्या घटनांचा अंदाज\",\"केवळ राजांची आणि युद्धांची माहिती\"],\"answer\":1,\"explain\":\"इतिहास म्हणजे भूतकाळात घडलेल्या घटनांची कालक्रमानुसार, शास्त्रशुद्ध आणि पद्धतशीरपणे दिलेली माहिती होय.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"या पाठात आपण प्रामुख्याने कशाचा अभ्यास करणार आहोत?\",\"options\":[\"प्राचीन इतिहासाची साधने\",\"आधुनिक भारताचा इतिहास\",\"मध्ययुगीन इतिहासाची साधने\",\"जगाचा इतिहास\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की, या पाठात आपण मध्ययुगीन इतिहासाच्या साधनांचा अभ्यास करणार आहोत.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर एखादा इतिहासकार इसवी सनाच्या १२ व्या शतकातील घटनेचा अभ्यास करत असेल, तर तो कोणत्या कालखंडाचा अभ्यास करत आहे?\",\"options\":[\"प्राचीन कालखंड\",\"मध्ययुगीन कालखंड\",\"आधुनिक कालखंड\",\"अश्मयुगीन कालखंड\"],\"answer\":1,\"explain\":\"९ वे ते १८ वे शतक हा मध्ययुगीन कालखंड असल्याने १२ वे शतक त्यातच येते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"इतिहासाच्या व्याख्येनुसार, माहितीची मांडणी कशी असणे आवश्यक आहे?\",\"options\":[\"केवळ मनोरंजक\",\"अस्ताव्यस्त आणि विस्कळीत\",\"कालक्रमानुसार आणि पद्धतशीर\",\"फक्त मौखिक स्वरूपाची\"],\"answer\":2,\"explain\":\"इतिहास म्हणजे घटनांची कालक्रमानुसार आणि पद्धतशीरपणे दिलेली माहिती होय.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता शब्द इतिहासाच्या शास्त्रशुद्ध स्वरूपावर भर देतो?\",\"options\":[\"ढोबळमानाने\",\"पद्धतशीरपणे\",\"प्राचीन\",\"अखेरपर्यंत\"],\"answer\":1,\"explain\":\"पद्धतशीरपणे आणि शास्त्रशुद्धपणे दिलेली माहिती ही विज्ञानासारखी अचूक असते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"इसवी सन ८५० ही वर्षसंख्या कोणत्या कालखंडाच्या अगदी जवळ किंवा सुरुवातीची मानली जाईल?\",\"options\":[\"मध्ययुगीन कालखंडाची सुरुवात\",\"प्राचीन कालखंडाची सुरुवात\",\"मध्ययुगीन कालखंडाचा शेवट\",\"आधुनिक कालखंडाची सुरुवात\"],\"answer\":0,\"explain\":\"९ वे शतक (इसवी सन ८०१ पासून) मध्ययुगाची सुरुवात मानली जाते, म्हणून ८५० हे वर्ष सुरुवातीच्या काळात येते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"इतिहासाची माहिती \'शास्त्रशुद्ध\' असणे म्हणजे काय?\",\"options\":[\"ती माहिती प्रयोगशाळेत तपासणे\",\"ती माहिती केवळ विज्ञानावर आधारित असणे\",\"ती माहिती पुराव्यांवर आधारित आणि पद्धतशीर असणे\",\"ती माहिती फक्त आधुनिक काळातील असणे\"],\"answer\":2,\"explain\":\"शास्त्रशुद्ध माहिती म्हणजे जी पद्धतशीरपणे आणि पुराव्यांच्या आधारे मांडलेली असते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'इतिहास\' या शब्दाची संधी खालीलपैकी कोणती आहे?\",\"options\":[\"इति + हा + स\",\"इति + ह + आस\",\"इ + ति + हास\",\"इती + ह + आस\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे दिले आहे की इतिहास हा शब्द ‘इति+ह+आस’ असा तयार झालेला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"\'इतिहास\' या शब्दाचा नेमका अर्थ काय होतो?\",\"options\":[\"असे घडले\",\"जुन्या गोष्टी\",\"राजांची कथा\",\"भविष्यकाळ\"],\"answer\":0,\"explain\":\"उताऱ्यात \'इतिहास\' या शब्दाचा अर्थ ‘असे घडले’ असा दिला आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"इतिहासाच्या दृष्टीने खालीलपैकी कोणता घटक अत्यंत महत्त्वाचा नाही?\",\"options\":[\"व्यक्ती\",\"समाज\",\"हवामान\",\"काळ\"],\"answer\":2,\"explain\":\"व्यक्ती, समाज, स्थळ आणि काळ हे चार घटक महत्त्वाचे आहेत; हवामान हा त्यात समाविष्ट नाही.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इतिहास कशावर आधारित असावा लागतो?\",\"options\":[\"कल्पनांवर\",\"विश्वसनीय पुराव्यांवर\",\"केवळ गोष्टींवर\",\"लोकांच्या अफवांवर\"],\"answer\":1,\"explain\":\"इतिहास हा विश्वसनीय पुराव्यांवर आधारित असावा लागतो, असे उताऱ्यात म्हटले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इतिहासाच्या साधनांचे मुख्य किती प्रकारांत वर्गीकरण केले जाते?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"तीन\"],\"answer\":3,\"explain\":\"भौतिक, लिखित आणि मौखिक अशा तीन प्रकारांत वर्गीकरण केले जाते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"एखाद्या ऐतिहासिक घटनेचा अभ्यास करताना कशाचा आधार घ्यावा लागतो?\",\"options\":[\"ऐतिहासिक साधनांचा\",\"केवळ स्वतःच्या विचारांचा\",\"वर्तमानपत्रातील बातम्यांचा\",\"काल्पनिक कथांचा\"],\"answer\":0,\"explain\":\"घटनेशी संबंधित ऐतिहासिक साधनांचा आधार घेणे गरजेचे असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"ऐतिहासिक साधनांचा वापर करण्यापूर्वी काय करणे गरजेचे असते?\",\"options\":[\"ती साधने पाठ करणे\",\"ती साधने तपासून घेणे\",\"ती साधने नष्ट करणे\",\"ती साधने विकून टाकणे\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, ऐतिहासिक साधने तपासून घेणे आणि त्यांचा अस्सलपणा तपासणे गरजेचे असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"साधनांचा वापर करताना तो कसा करणे आवश्यक आहे?\",\"options\":[\"घाईघाईने\",\"चिकित्सकपणे\",\"केवळ करमणुकीसाठी\",\"विनाचौकशी\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केले आहे की साधनांचा चिकित्सकपणे वापर करणे आवश्यक असते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"इतिहासाच्या साधनांचे मूल्यमापन करणे म्हणजे नेमके काय?\",\"options\":[\"साधनांची किंमत ठरवणे\",\"साधनांची विश्वासार्हता व अस्सलपणा तपासणे\",\"साधने संग्रहालयात ठेवणे\",\"साधनांची चित्रे काढणे\"],\"answer\":1,\"explain\":\"मूल्यमापन करणे म्हणजे साधनांचा अस्सलपणा आणि विश्वासार्हता तपासून त्यांचा चिकित्सक वापर करणे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"इतिहासाच्या साधनांच्या वर्गीकरणात खालीलपैकी कशाचा समावेश होत नाही?\",\"options\":[\"भौतिक साधने\",\"लिखित साधने\",\"मौखिक साधने\",\"तांत्रिक साधने\"],\"answer\":3,\"explain\":\"उताऱ्यात भौतिक, लिखित आणि मौखिक या तीनच साधनांचा उल्लेख आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"वस्तू आणि वास्तू किंवा त्यांचे अवशेष यांना इतिहासाची कोणती साधने म्हणतात?\",\"options\":[\"लिखित साधने\",\"मौखिक साधने\",\"भौतिक साधने\",\"आधुनिक साधने\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार वस्तू, वास्तू किंवा त्यांचे अवशेष म्हणजे भौतिक साधने होत.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता किल्ल्यांचा एक प्रकार म्हणून पाठात उल्लेखलेला नाही?\",\"options\":[\"गिरीदुर्ग\",\"जलदुर्ग\",\"भुईकोट\",\"नभदुर्ग\"],\"answer\":3,\"explain\":\"पाठात गिरीदुर्ग, वनदुर्ग, जलदुर्ग आणि भुईकोट या किल्ल्यांच्या प्रकारांचा उल्लेख आहे.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"स्मारकांमध्ये खालीलपैकी कोणत्या घटकाचा समावेश होतो?\",\"options\":[\"राजवाडे\",\"वीरगळ\",\"राणीवसा\",\"मंत्रीनिवास\"],\"answer\":1,\"explain\":\"समाधी, कबर आणि वीरगळ यांचा समावेश स्मारकांमध्ये होतो.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"इमारतींच्या अभ्यासातून आपल्याला त्या कालखंडातील कोणत्या गोष्टीचा बोध होतो?\",\"options\":[\"लोकांचे राहणीमान\",\"युद्धाचे नियम\",\"राजकीय करार\",\"धार्मिक ग्रंथ\"],\"answer\":0,\"explain\":\"इमारतींवरून त्या काळातील आर्थिक स्थिती, कलेचा दर्जा आणि लोकांचे राहणीमान समजते.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या संशोधकाला जुन्या काळातील \'वास्तूकलेची प्रगती\' अभ्यासायची असेल, तर त्याने खालीलपैकी कशाचा अभ्यास करणे सर्वात योग्य ठरेल?\",\"options\":[\"लोककथा\",\"पोवाडे\",\"भौतिक साधने\",\"हस्तलिखिते\"],\"answer\":2,\"explain\":\"वास्तू आणि त्यांच्या अवशेषांवरून (भौतिक साधने) वास्तूकलेची प्रगती समजते.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"एका उत्खननात \'सामान्य जनतेची घरे\' सापडली आहेत, तर ती इतिहासाच्या कोणत्या साधनाचे उदाहरण ठरेल?\",\"options\":[\"किल्ले\",\"इमारती\",\"स्मारके\",\"लिखित साधने\"],\"answer\":1,\"explain\":\"पाठात सामान्य जनतेच्या घरांचा समावेश \'इमारती\' या गटात केला आहे.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"भौतिक साधनांच्या आधारे खालीलपैकी कोणती माहिती मिळत नाही?\",\"options\":[\"आर्थिक स्थिती\",\"बांधकामाची शैली\",\"कलेचा दर्जा\",\"लोकांच्या मनातील विचार\"],\"answer\":3,\"explain\":\"भौतिक साधनांतून आर्थिक स्थिती, शैली आणि कलेचा दर्जा समजतो, पण लोकांचे विचार थेट समजत नाहीत.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"किल्ल्यांचे ऐतिहासिक महत्त्व कशावरून स्पष्ट होते?\",\"options\":[\"ते केवळ राहण्यासाठी वापरले जात\",\"भौतिक साधनांमध्ये किल्ल्यांचे महत्त्वपूर्ण स्थान असते\",\"ते फक्त पर्यटनासाठी असतात\",\"ते आधुनिक काळात बांधले गेले आहेत\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात स्पष्ट नमूद केले आहे की भौतिक साधनांमध्ये किल्ल्यांचे महत्त्वपूर्ण स्थान असते.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणती जोडी \'स्मारके\' या गटाशी संबंधित आहे?\",\"options\":[\"राजवाडे आणि मंत्रीनिवास\",\"गिरीदुर्ग आणि जलदुर्ग\",\"समाधी आणि कबर\",\"राणीवसा आणि सामान्य जनतेची घरे\"],\"answer\":2,\"explain\":\"समाधी आणि कबर ही स्मारकांची उदाहरणे आहेत.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"जमिनीवर बांधलेल्या किल्ल्याला पाठात काय म्हटले आहे?\",\"options\":[\"गिरीदुर्ग\",\"वनदुर्ग\",\"जलदुर्ग\",\"भुईकोट\"],\"answer\":3,\"explain\":\"जमिनीवर (भुईवर) बांधलेल्या किल्ल्याला भुईकोट म्हणतात.\",\"topic\":\"भौतिक साधने\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"दगडावर किंवा भिंतीवर कोरलेल्या लेखांना काय म्हणतात?\",\"options\":[\"ताम्रपट\",\"शिलालेख\",\"हस्तलिखिते\",\"भूर्जपत्रे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, दगडावर किंवा भिंतीवर कोरलेल्या लेखांना \'शिलालेख\' म्हणतात.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"तंजावर येथील कोणत्या मंदिराच्या परिसरात महत्त्वाचे शिलालेख आढळतात?\",\"options\":[\"कैलास मंदिर\",\"बृहदीश्वर मंदिर\",\"विठ्ठल मंदिर\",\"घृष्णेश्वर मंदिर\"],\"answer\":1,\"explain\":\"तंजावर येथील बृहदीश्वर मंदिराच्या परिसरातील लेख हे शिलालेखाचे महत्त्वाचे उदाहरण आहे.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"शिलालेख हा इतिहासलिखनाचा कोणता पुरावा मानला जातो?\",\"options\":[\"अविश्वसनीय\",\"काल्पनिक\",\"विश्वसनीय\",\"दुय्यम\"],\"answer\":2,\"explain\":\"शिलालेख हा इतिहासलिखनाचा फार महत्त्वाचा आणि विश्वसनीय पुरावा मानला जातो.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"तांब्याच्या पत्र्यावर कोरलेल्या लेखांना काय म्हणतात?\",\"options\":[\"शिलालेख\",\"ताम्रपट\",\"आज्ञापत्र\",\"सनद\"],\"answer\":1,\"explain\":\"तांब्याच्या पत्र्यावर कोरलेल्या लेखांना \'ताम्रपट\' म्हणतात.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"ताम्रपटावर प्रामुख्याने कोणती माहिती कोरलेली असते?\",\"options\":[\"युद्धाचे वर्णन\",\"कवितेच्या ओळी\",\"राजाज्ञा व निवाडे\",\"व्यापाराची यादी\"],\"answer\":2,\"explain\":\"ताम्रपटावर राजाज्ञा, निवाडे इत्यादी प्रकारची माहिती कोरलेली असे.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"\'चमडी जाय पर ____ न जाय!\' ही म्हण पूर्ण करण्यासाठी योग्य नाणे निवडा.\",\"options\":[\"पैसा\",\"दमडी\",\"आणा\",\"कवडी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात दिलेल्या म्हणीनुसार \'चमडी जाय पर दमडी न जाय!\' हे योग्य उत्तर आहे.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"शिलालेखांमुळे आपल्याला खालीलपैकी कोणती बाब समजायला मदत होते?\",\"options\":[\"हवामान\",\"शेतीचे तंत्र\",\"समाजजीवन\",\"युद्धाचे डावपेच\"],\"answer\":2,\"explain\":\"शिलालेखातून भाषा, लिपी, समाजजीवन यांसारख्या बाबी समजायला मदत होते.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या राजघराण्याच्या काळातील शिलालेख मिळालेले नाहीत असे पाठ्यपुस्तकात नमूद केले आहे?\",\"options\":[\"चालुक्य\",\"राष्ट्रकूट\",\"चोळ\",\"मुघल\"],\"answer\":3,\"explain\":\"पाठ्यपुस्तकात चालुक्य, राष्ट्रकूट, चोळ, यादव या राजांच्या काळातील शिलालेखांचा उल्लेख आहे, मुघलांचा नाही.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीमधील तक्त्यानुसार, \'शस्त्रे\', \'भांडी\' आणि \'दागिने\' ही सर्व कोणत्या प्रकारची साधने आहेत?\",\"options\":[\"लिखित साधने\",\"मौखिक साधने\",\"भौतिक साधने\",\"आधुनिक साधने\"],\"answer\":2,\"explain\":\"आकृतीमधील तक्त्यात स्पष्टपणे नमूद केले आहे की ही सर्व भौतिक साधने आहेत.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"51\\/012_102.jpg\"},{\"q\":\"दिलेल्या चित्रात दाखवलेले साधन ओळखा.\",\"options\":[\"ताम्रपट\",\"वीरगळ\",\"स्तंभलेख\",\"किल्ला\"],\"answer\":1,\"explain\":\"दिलेले चित्र \'वीरगळ\' या भौतिक साधनाचे आहे.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"remember\",\"figure_image\":\"51\\/012_101.jpg\"},{\"q\":\"जर एखाद्या संशोधकाला प्राचीन काळातील न्यायदानाची पद्धत (निवाडे) अभ्यासायची असेल, तर त्याने खालीलपैकी कोणत्या साधनांचा वापर करणे अधिक योग्य ठरेल?\",\"options\":[\"नाणी\",\"ताम्रपट\",\"किल्ले\",\"वाद्ये\"],\"answer\":1,\"explain\":\"ताम्रपटावर निवाडे कोरलेले असल्यामुळे संशोधकासाठी ते योग्य साधन ठरेल.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"शिलालेखांना विश्वसनीय पुरावा मानण्याचे मुख्य कारण काय असू शकते?\",\"options\":[\"ते खूप महाग असतात.\",\"ते दगडावर कोरलेले असल्याने त्यात बदल करणे कठीण असते.\",\"ते फक्त तंजावरलाच मिळतात.\",\"ते फक्त राजांनीच लिहिलेले असतात.\"],\"answer\":1,\"explain\":\"शिलालेख हे दगडावर कोरलेले असल्याने ते मूळ स्वरूपात दीर्घकाळ टिकतात, म्हणून ते विश्वसनीय असतात.\",\"topic\":\"शिलालेख व ताम्रपट\",\"part\":5,\"bloom\":\"evaluate\"},{\"q\":\"खालीलपैकी कोणते इतिहासाचे \'लिखित साधन\' आहे?\",\"options\":[\"शस्त्रे\",\"पोथ्या\",\"दागिने\",\"वाद्ये\"],\"answer\":1,\"explain\":\"पोथ्या, ग्रंथ आणि भूर्जपत्रे ही लिखित स्वरूपात असल्याने त्यांना लिखित साधने म्हणतात.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"नाण्यांवरून आपल्याला राज्यकर्त्यांच्या कोणत्या बाबींची माहिती मिळते?\",\"options\":[\"लोकांचे खाण्यापिण्याचे पदार्थ\",\"राज्यकर्त्यांचा काळ आणि राज्यकारभार\",\"त्या काळातील वेशभूषा\",\"खेळांचे प्रकार\"],\"answer\":1,\"explain\":\"नाण्यांवरून राज्यकर्ते कोण होते, त्यांचा काळ, राज्यकारभार आणि वैयक्तिक तपशील समजतो.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"सम्राट अकबराच्या नाण्यांवरील रामसीतेच्या चित्रावरून आपल्याला काय समजते?\",\"options\":[\"त्या काळातील आर्थिक स्थिती\",\"त्या काळातील धार्मिक समन्वय\",\"त्या काळातील भाषाव्यवहार\",\"त्या काळातील युद्धकला\"],\"answer\":1,\"explain\":\"अकबराच्या नाण्यांवरील रामसीतेच्या चित्रावरून त्या काळातील धार्मिक समन्वयाची जाणीव होते.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"पेशव्यांच्या नाण्यांवर कोणत्या भाषेचा वापर होत असे?\",\"options\":[\"मराठी किंवा संस्कृत\",\"अरेबिक किंवा पर्शियन\",\"हिंदी किंवा इंग्रजी\",\"तामिळ किंवा तेलगू\"],\"answer\":1,\"explain\":\"पेशव्यांच्या नाण्यांवर अरेबिक किंवा पर्शियन भाषेचा वापर होत असे, यावरून त्या काळातील भाषाव्यवहार समजतो.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला मध्ययुगीन काळातील लोकांच्या आचारविचारांची माहिती मिळवायची असेल, तर तुम्ही कोणत्या साधनांचा प्रामुख्याने वापर कराल?\",\"options\":[\"शिल्प\",\"नाणी\",\"लिखित साधने\",\"शस्त्रे\"],\"answer\":2,\"explain\":\"लिखित साधनांमधून लोकजीवन, वेशभूषा, आचारविचार आणि सण-समारंभ यांची माहिती मिळते.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"नाण्यांच्या अभ्यासावरून त्या काळातील कोणत्या शास्त्राची प्रगती समजते?\",\"options\":[\"खगोलशास्त्र\",\"धातुशास्त्र\",\"वैद्यकशास्त्र\",\"वास्तुशास्त्र\"],\"answer\":1,\"explain\":\"नाणी तयार करण्यासाठी वापरलेल्या धातूंवरून त्या काळातील धातुशास्त्राची प्रगती समजते.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, \'खलिते\' हे कोणत्या प्रकारच्या साधनांमध्ये मोडतात?\",\"options\":[\"भौतिक साधने\",\"मौखिक साधने\",\"लिखित साधने\",\"दृश्य साधने\"],\"answer\":2,\"explain\":\"दिलेल्या ओघतक्त्यात खलिते हे लिखित साधनांचा एक प्रकार म्हणून दर्शवले आहेत.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"remember\",\"figure_image\":\"51\\/012_105.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. \'परदेशी प्रवाशांची प्रवासवर्णने\' हे कशाचे उदाहरण आहे?\",\"options\":[\"लिखित साधने\",\"भौतिक साधने\",\"नाणी\",\"किल्ले\"],\"answer\":0,\"explain\":\"आकृतीमध्ये परदेशी प्रवाशांची प्रवासवर्णने हे लिखित साधनांच्या वर्गीकरणात दिले आहे.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"51\\/012_105.jpg\"},{\"q\":\"हैदरअलीच्या नाण्यांवरील शिवपार्वतीच्या प्रतिमा काय दर्शवतात?\",\"options\":[\"केवळ राजाची आवड\",\"धार्मिक असहिष्णुता\",\"धार्मिक समन्वयाची जाणीव\",\"परकीय आक्रमण\"],\"answer\":2,\"explain\":\"मुस्लिम शासकाच्या नाण्यावर हिंदू देवतांच्या प्रतिमा असणे हे धार्मिक समन्वयाचे प्रतीक आहे.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"मध्ययुगीन काळात माहिती मिळवण्यासाठी वापरल्या जाणाऱ्या लिपींमध्ये खालीलपैकी कशाचा समावेश होतो?\",\"options\":[\"मोडी\",\"रोमन\",\"ग्रीक\",\"ब्राह्मी\"],\"answer\":0,\"explain\":\"मजकुरात देवनागरी, अरेबियन, पर्शियन आणि मोडी या लिपींचा उल्लेख लिखित साधनांच्या संदर्भात केला आहे.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणती गोष्ट \'लिखित साधन\' नाही?\",\"options\":[\"तवारीख\",\"आज्ञापत्रे\",\"वंशावळी\",\"दागिने\"],\"answer\":3,\"explain\":\"दागिने हे भौतिक साधन आहे, तर तवारीख, आज्ञापत्रे आणि वंशावळी ही लिखित साधने आहेत.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"भूर्जपत्रे, पोथ्या आणि ग्रंथ यांसारख्या लिखित साधनांमुळे आपल्याला कोणती महत्त्वाची माहिती मिळते?\",\"options\":[\"केवळ धातूंची शुद्धता\",\"ऐतिहासिक घटना आणि लोकजीवन\",\"जमिनीची खोली\",\"समुद्रातील मार्ग\"],\"answer\":1,\"explain\":\"या साधनांवरून ऐतिहासिक घटना, लोकजीवन, वेशभूषा आणि सण-समारंभ यांची माहिती मिळते.\",\"topic\":\"लिखित साधने\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"कवी परमानंद यांनी संस्कृत भाषेत खालीलपैकी कोणते चरित्र लिहिले आहे?\",\"options\":[\"बाबरचे चरित्र\",\"शिवभारत\",\"सभासद बखर\",\"९१ कलमी बखर\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, कवी परमानंद यांनी संस्कृत भाषेत \'शिवभारत\' हे शिवाजी महाराजांचे चरित्र लिहिले आहे.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'तवारीख\' किंवा \'तारीख\' या शब्दाचा नेमका अर्थ काय होतो?\",\"options\":[\"बातमी\",\"प्रवासवर्णन\",\"घटनाक्रम\",\"राजकीय धोरण\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात स्पष्टपणे नमूद केले आहे की तवारिख किंवा तारीख म्हणजे घटनाक्रम होय.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'बखर\' हा शब्द कोणत्या शब्दावरून तयार झाला आहे?\",\"options\":[\"बखैर\",\"खबर\",\"खैर\",\"बखत\"],\"answer\":1,\"explain\":\"बखर हा शब्द \'खबर\' या शब्दावरून आला असून खबर म्हणजे बातमी होय.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता परकीय प्रवासी भारतात आला नव्हता असे पाठ्यपुस्तकातील माहितीवरून सांगता येईल?\",\"options\":[\"अल्बेरुनी\",\"इब्न बतूता\",\"निकोलस मनुची\",\"रॉबर्ट आर्म\"],\"answer\":3,\"explain\":\"अल्बेरुनी, इब्न बतूता आणि निकोलस मनुची हे परकीय प्रवासी होते, तर रॉबर्ट आर्म हे पाश्चात्त्य इतिहासकार होते.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"बखर हा इतिहासलेखनाचा प्रकार कोठे निर्माण झाला?\",\"options\":[\"दिल्लीत\",\"महाराष्ट्रात\",\"कर्नाटकात\",\"बंगालमध्ये\"],\"answer\":1,\"explain\":\"बखर हा महाराष्ट्रात निर्माण झालेला इतिहासलेखनाचा एक प्रकार आहे.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मराठीतील अनेक बखरींच्या विश्वासार्हतेबाबत पाठ्यपुस्तकात कोणती महत्त्वाची बाब नमूद केली आहे?\",\"options\":[\"त्या घटना घडत असतानाच लिहिल्या गेल्या\",\"त्या केवळ संस्कृत भाषेत आहेत\",\"त्यात अनेकदा ऐकीव माहितीवर भर दिल्याचे आढळते\",\"त्या केवळ परकीयांनी लिहिल्या आहेत\"],\"answer\":2,\"explain\":\"बखरी घटना घडून गेल्यानंतर अनेक वर्षांनी लिहिलेल्या असल्याने त्यात अनेकदा ऐकीव माहितीवर भर असतो.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला ऐतिहासिक काळातील \'बातमी\' किंवा राजकीय घडामोडी जाणून घ्यायच्या असतील, तर तुम्ही खालीलपैकी कोणते साधन वापराल?\",\"options\":[\"प्रवासवर्णने\",\"बखर\",\"शिलालेख\",\"नाणी\"],\"answer\":1,\"explain\":\"बखर म्हणजे खबर (बातमी) असून त्यातून तत्कालीन राजकीय घडामोडी कळायला मदत होते.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणती बखर ही खर्ड्यांच्या लढाईशी संबंधित आहे?\",\"options\":[\"सभासद बखर\",\"९१ कलमी बखर\",\"खर्ड्यांच्या लढायांची बखर\",\"महिकावतीची बखर\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात बखरींच्या उदाहरणांमध्ये \'खर्ड्यांच्या लढायांची बखर\' असा उल्लेख आहे.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"झियाउद्दीन बर्नी यांनी लिहिलेले ऐतिहासिक साधन कोणत्या प्रकारात मोडते?\",\"options\":[\"बखर\",\"तवारीख\",\"प्रवासवर्णन\",\"पोवाडा\"],\"answer\":1,\"explain\":\"झियाउद्दीन बर्नी यांनी लिहिलेल्या तवारिखा (तवारीख) उपलब्ध आहेत.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"राजघराण्यांची चरित्रे आणि वंशपरंपरा यांवरून आपल्याला कोणती माहिती मिळते?\",\"options\":[\"केवळ युद्धांचे वर्णन\",\"प्रशासकीय व्यवस्था आणि राजकीय संबंध\",\"केवळ भौगोलिक सीमा\",\"परकीय प्रवाशांची नावे\"],\"answer\":1,\"explain\":\"राजघराण्यांच्या चरित्रांवरून त्यांची धोरणे, प्रशासकीय व्यवस्था आणि राजकीय संबंध यांची कल्पना येते.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"ग्रँट डफ हे कोणत्या प्रकारचे लेखक म्हणून ओळखले जातात?\",\"options\":[\"परकीय प्रवासी\",\"संस्कृत कवी\",\"समकालीन पाश्चात्त्य इतिहासकार\",\"बखरकार\"],\"answer\":2,\"explain\":\"रॉबर्ट आर्म, एम.सी.स्प्रिंगेल आणि ग्रँट डफ हे समकालीन पाश्चात्त्य इतिहासकार आहेत.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"तवारीख लिहिणाऱ्या लेखकांच्या गटात खालीलपैकी कोणाचा समावेश होतो?\",\"options\":[\"मिर्झा हैदर आणि भीमसेन सक्सेना\",\"रॉबर्ट आर्म आणि ग्रँट डफ\",\"कवी परमानंद आणि बाबर\",\"इब्न बतूता आणि मनुची\"],\"answer\":0,\"explain\":\"मिर्झा हैदर आणि भीमसेन सक्सेना यांनी तवारिखा लिहिल्या आहेत.\",\"topic\":\"प्रवासवर्णने, तवारीख आणि बखर\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"लोकपरंपरेत पिढ्यानपिढ्या संक्रमित होत राहिलेल्या साधनांना काय म्हणतात?\",\"options\":[\"लिखित साधने\",\"भौतिक साधने\",\"मौखिक साधने\",\"दृश्य-श्राव्य साधने\"],\"answer\":2,\"explain\":\"पाठातील व्याख्येनुसार, लोकपरंपरेत पिढ्यानपिढ्या संक्रमित होणाऱ्या साधनांना \'मौखिक साधने\' म्हणतात.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जात्यावरील ओव्या आणि लोकगीते यांतून आपल्याला कशाचे विविध पैलू समजतात?\",\"options\":[\"राजकीय घडामोडींचे\",\"लोकजीवनाचे\",\"केवळ युद्धाचे\",\"परकीय आक्रमणाचे\"],\"answer\":1,\"explain\":\"मौखिक साधनांतून आपल्याला लोकजीवनाचे विविध पैलू समजतात असे पाठात नमूद केले आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"इतिहासाचे संशोधन कोणत्या प्रकारे चालते?\",\"options\":[\"काही काळापुरते\",\"अखंडपणे\",\"फक्त एकदाच\",\"दहा वर्षांतून एकदा\"],\"answer\":1,\"explain\":\"इतिहासाचे संशोधन अखंडपणे चालूच राहते, असे पाठात स्पष्ट केले आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"इतिहासाचे पुनर्लेखन का करावे लागते?\",\"options\":[\"जुन्या पुस्तकांचा कंटाळा येतो म्हणून\",\"संशोधनातून नवी साधने व नवी माहिती समोर येते म्हणून\",\"लेखकाची इच्छा असते म्हणून\",\"केवळ चित्रे बदलण्यासाठी\"],\"answer\":1,\"explain\":\"संशोधनातून नवी माहिती समोर आल्यामुळे इतिहासाचे पुनर्लेखन करावे लागते.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत मध्यभागी असलेल्या वर्तुळात कोणत्या प्रकारच्या साधनांचा उल्लेख केला आहे?\",\"options\":[\"लिखित साधने\",\"भौतिक साधने\",\"मौखिक साधने\",\"प्राचीन साधने\"],\"answer\":2,\"explain\":\"दिलेल्या आकृतीच्या मध्यभागी \'मौखिक साधने\' असे स्पष्टपणे लिहिले आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"51\\/013_101.jpg\"},{\"q\":\"दिलेल्या आकृतीनुसार, खालीलपैकी कोणते मौखिक साधनाचे एक उदाहरण आहे?\",\"options\":[\"किल्ले\",\"ताम्रपट\",\"अभंग\",\"नाणी\"],\"answer\":2,\"explain\":\"आकृतीमध्ये मौखिक साधनांच्या उदाहरणांमध्ये \'अभंग\' चा समावेश आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"remember\",\"figure_image\":\"51\\/013_101.jpg\"},{\"q\":\"जर तुम्हाला एखाद्या जुन्या परंपरेतील \'पोवाडा\' सापडला, तर तुम्ही त्याचे वर्गीकरण कोणत्या साधनांत कराल?\",\"options\":[\"लिखित साधने\",\"मौखिक साधने\",\"भौतिक साधने\",\"सांस्कृतिक साधने\"],\"answer\":1,\"explain\":\"पोवाडा हे लोकपरंपरेतून येणारे मौखिक साधन आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"आजी-आजोबांच्या काळातील आणि तुमच्या काळातील इतिहासाच्या पुस्तकांत फरक असण्याचे मुख्य कारण काय असू शकते?\",\"options\":[\"पुस्तकाचा आकार बदलला आहे\",\"नवीन संशोधनामुळे इतिहासाचे पुनर्लेखन झाले आहे\",\"जुनी पुस्तके हरवली आहेत\",\"भाषेचा प्रकार बदलला आहे\"],\"answer\":1,\"explain\":\"नव्या संशोधनातून समोर आलेल्या माहितीनुसार इतिहासाचे पुनर्लेखन झाल्यामुळे पुस्तकांत फरक पडतो.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणते साधन मौखिक साधनांच्या गटात बसत नाही?\",\"options\":[\"मिथके\",\"दंतकथा\",\"ओव्या\",\"शिलालेख\"],\"answer\":3,\"explain\":\"ओव्या, मिथके आणि दंतकथा ही मौखिक साधने आहेत, तर शिलालेख हे लिखित साधन आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"इतिहास लेखनाबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"इतिहास एकदा लिहिला की तो कधीच बदलत नाही\",\"इतिहास लेखनासाठी साधनांची गरज नसते\",\"नव्या माहितीनुसार इतिहासाचे पुनर्लेखन होऊ शकते\",\"मौखिक साधने ही इतिहासाचा आधार नसतात\"],\"answer\":2,\"explain\":\"संशोधनातून नवी माहिती समोर आल्यास इतिहासाचे पुनर्लेखन करावे लागते, हे विधान पाठात दिले आहे.\",\"topic\":\"मौखिक साधने\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"तानाजीच्या पोवाड्यातून प्रामुख्याने कोणाच्या जीवनातील काही घटना कळतात?\",\"options\":[\"छत्रपती शिवाजी महाराज\",\"छत्रपती संभाजी महाराज\",\"बाजीराव पेशवे\",\"कान्होजी आंग्रे\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकातील मजकुरानुसार, या पोवाड्यातून शिवाजी महाराजांच्या जीवनातील काही घटना कळतात.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पोवाड्यात खालीलपैकी कोणाचे शब्दचित्र दिलेले नाही?\",\"options\":[\"तानाजी\",\"वीरमाता जिजाबाई\",\"शेलारमामा\",\"बाजीप्रभू देशपांडे\"],\"answer\":3,\"explain\":\"मजकुरात तानाजी, शेलारमामा, शिवाजी महाराज आणि वीरमाता जिजाबाई यांची शब्दचित्रे असल्याचे नमूद केले आहे; बाजीप्रभूंचा उल्लेख नाही.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पोवाड्यातील ओळींनुसार, तानाजी सुभेदार कोणत्या गडावर गेले होते?\",\"options\":[\"रायगड\",\"प्रतापगड\",\"सिंहगड\",\"पुरंदर\"],\"answer\":2,\"explain\":\"मजकुरातील \'माझ्या तानाजी सुभेदारा। ते गेले सिंहगडाला ।।\' या ओळीवरून हे स्पष्ट होते.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"\'शब्दचित्रे दिली आहेत\' या विधानाचा अर्थ काय?\",\"options\":[\"पोवाड्यात चित्रे काढलेली आहेत\",\"शब्दांच्या माध्यमातून व्यक्तींचे प्रभावी वर्णन केले आहे\",\"पोवाड्यात फक्त नावे लिहिली आहेत\",\"पोवाडा म्हणजे एक चित्रकला आहे\"],\"answer\":1,\"explain\":\"शब्दचित्र म्हणजे शब्दांच्या सहाय्याने उभे केलेले हुबेहूब वर्णन.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"तानाजीने \'आम्ही सूरमर्द शूर। नाही भिणार मरणाला\' असे कोणाला उद्देशून म्हटले आहे?\",\"options\":[\"शिवाजी महाराज\",\"जिजाबाई\",\"शेलारमामा\",\"शत्रू सैन्य\"],\"answer\":2,\"explain\":\"मजकुरात मामांच्या बोलण्याला उत्तर देताना तानाजीने हे उद्गार काढले आहेत.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"इतिहासाचा अभ्यास करताना \'पोवाडा\' हे कोणत्या प्रकारचे साधन म्हणून वापरता येईल?\",\"options\":[\"भौतिक साधन\",\"लिखित किंवा मौखिक साधन\",\"पुरातत्वीय साधन\",\"केवळ मनोरंजनाचे साधन\"],\"answer\":1,\"explain\":\"पोवाडा हा ऐतिहासिक घटनांची माहिती देणारा एक महत्त्वाचा स्रोत (साधन) आहे.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"शेलारमामांनी तानाजीला सिंहगड किल्ल्याच्या वाटेबद्दल काय इशारा दिला होता?\",\"options\":[\"वाट खूप सोपी आहे\",\"वाटेत खूप खजिना आहे\",\"वाटेने जाणे धोक्याचे आहे (सपोटा होईल)\",\"वाट खूप लांबची आहे\"],\"answer\":2,\"explain\":\"शेलारमामांनी धोक्याची सूचना दिल्यावर तानाजीने \'तुमचा सपोटा होईल। असे बोलू नको रे मामा\' असे उत्तर दिले आहे.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या मजकुरातील तानाजीच्या संवादावरून त्यांचा कोणता गुण दिसून येतो?\",\"options\":[\"भीती\",\"निर्भयता आणि शौर्य\",\"आळस\",\"स्वार्थ\"],\"answer\":1,\"explain\":\"\'नाही भिणार मरणाला\' या वाक्यातून तानाजीची निर्भयता आणि शौर्य दिसून येते.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"पोवाड्यातील \'मामा बोलाया तो लागला। ऐशी गर्जना झाली ।।\' या ओळीतून काय समजते?\",\"options\":[\"मामा हळू आवाजात बोलत होते\",\"मामांचे बोलणे अत्यंत प्रभावी आणि खंबीर होते\",\"मामा रडत होते\",\"मामांना बोलता येत नव्हते\"],\"answer\":1,\"explain\":\"\'गर्जना\' हा शब्द खंबीर आणि मोठ्या आवाजातील बोलण्याचे प्रतीक आहे.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"इतिहासाची साधने म्हणून पोवाड्याचे महत्त्व काय आहे?\",\"options\":[\"त्यातून केवळ काल्पनिक कथा कळतात\",\"त्यातून ऐतिहासिक व्यक्तींची स्वभाववैशिष्ट्ये आणि घटनांची माहिती मिळते\",\"त्यातून फक्त गाणी गाता येतात\",\"त्याचा इतिहासाशी काहीही संबंध नसतो\"],\"answer\":1,\"explain\":\"मजकुरात म्हटल्याप्रमाणे, पोवाड्यातून घटना कळतात आणि व्यक्तींची शब्दचित्रे (स्वभाववैशिष्ट्ये) रेखाटली जातात.\",\"topic\":\"तानाजीचा पोवाडा\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"ऐतिहासिक साधने वापरण्यापूर्वी काय तपासणे आवश्यक असते?\",\"options\":[\"साधनांची किंमत\",\"साधनांची विश्वसनीयता\",\"साधनांचे वजन\",\"साधनांचा आकार\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार, साधने वापरण्यापूर्वी त्यांची विश्वसनीयता तपासणे आवश्यक असते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"साधनांचा दर्जा कशाच्या आधारे ठरवता येतो?\",\"options\":[\"बाह्य स्वरूपावरून\",\"लेखकाच्या प्रसिद्धीवरून\",\"अंतर्गत प्रमाणांवरून\",\"साधनांच्या वयावरून\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे, अंतर्गत प्रमाणे पाहून साधनांचा दर्जा ठरवता येतो.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"इतिहासलेखनात लेखकाचे कोणते गुण फार महत्त्वाचे असतात?\",\"options\":[\"श्रीमंती आणि सत्ता\",\"निःपक्षपातीपणा आणि तटस्थता\",\"लेखनशैली आणि वेग\",\"कौटुंबिक पार्श्वभूमी\"],\"answer\":1,\"explain\":\"इतिहासलेखनात लेखकाचा निःपक्षपातीपणा आणि तटस्थता फार महत्त्वाची असते असे उताऱ्यात म्हटले आहे.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"एखादी माहिती \'अतिरंजित\' असण्याची शक्यता असल्यास इतिहासकाराने काय करावे?\",\"options\":[\"ती माहिती जशीच्या तशी स्वीकारावी\",\"ती माहिती पूर्णपणे नाकारावी\",\"माहिती वापरताना तारतम्य ठेवावे\",\"माहितीमध्ये स्वतःच्या मनाने बदल करावा\"],\"answer\":2,\"explain\":\"माहिती अतिरंजित असण्याची शक्यता असल्याने तिचा वापर करताना तारतम्य ठेवणे गरजेचे असते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"लेखकाच्या बाबतीत खालीलपैकी कोणत्या गोष्टीचा अभ्यास करणे आवश्यक असते?\",\"options\":[\"त्यांचे व्यक्तिगत हितसंबंध आणि राजकीय दबाव\",\"त्यांचा आहार आणि विहार\",\"त्यांचे शिक्षण आणि छंद\",\"त्यांची संपत्ती आणि दागिने\"],\"answer\":0,\"explain\":\"लेखकांचा खरेखोटेपणा, व्यक्तिगत हितसंबंध आणि राजकीय दबाव यांचा अभ्यास करावा लागतो.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"मिळालेली माहिती \'ऐकीव\' आहे की \'स्वयंनिरीक्षण\' करून मिळवली आहे, हे का तपासावे लागते?\",\"options\":[\"लेखकाचे हस्ताक्षर तपासण्यासाठी\",\"माहितीची पडताळणी करण्यासाठी\",\"पुस्तकाची पाने मोजण्यासाठी\",\"भाषेचे व्याकरण सुधारण्यासाठी\"],\"answer\":1,\"explain\":\"माहितीची सत्यता पडताळून पाहण्यासाठी ती ऐकीव आहे की प्रत्यक्ष पाहिलेली आहे हे पाहणे गरजेचे असते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"analyze\"},{\"q\":\"साधनांचा वापर करण्यापूर्वी कोणती दक्षता घेणे गरजेचे असते?\",\"options\":[\"नेहमी चिकित्सा करणे\",\"केवळ जुन्या साधनांचा वापर करणे\",\"केवळ नवीन साधनांचा वापर करणे\",\"साधने सुंदर सजवणे\"],\"answer\":0,\"explain\":\"सदैव चिकित्सा करूनच साधनांचा वापर करण्याची दक्षता घेणे गरजेचे असते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"जर एखादे साधन \'बनावट\' आढळले, तर मूल्यमापनाच्या प्रक्रियेत त्याला काय म्हटले जाईल?\",\"options\":[\"अस्सल साधन\",\"विश्वासार्ह साधन\",\"कमी दर्जाचे किंवा अविश्वसनीय साधन\",\"तटस्थ साधन\"],\"answer\":2,\"explain\":\"अस्सल आणि बनावट साधनांमधील फरक शोधणे हे मूल्यमापनाचा भाग असून बनावट साधन अविश्वसनीय ठरते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"evaluate\"},{\"q\":\"माहिती \'एकांगी\' असणे म्हणजे काय?\",\"options\":[\"माहिती सर्व बाजूंनी परिपूर्ण असणे\",\"माहिती केवळ एकाच दृष्टिकोनातून मांडलेली असणे\",\"माहिती खूप मोठी असणे\",\"माहिती चित्रांच्या स्वरूपात असणे\"],\"answer\":1,\"explain\":\"एकांगी माहिती म्हणजे केवळ एका बाजूचा विचार केलेली माहिती, जी विसंगत असू शकते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"इतिहास लेखकाने लेखकाचा \'काळ\' का अभ्यासावा?\",\"options\":[\"लेखकाचे वय मोजण्यासाठी\",\"त्या काळातील परिस्थितीचा लेखनावर झालेला परिणाम समजण्यासाठी\",\"लेखकाचा वाढदिवस साजरा करण्यासाठी\",\"लेखकाच्या घराचा पत्ता शोधण्यासाठी\"],\"answer\":1,\"explain\":\"लेखकाचा काळ अभ्यासल्यामुळे त्यावेळच्या राजकीय किंवा सामाजिक दबावाचे विश्लेषण करता येते.\",\"topic\":\"ऐतिहासिक साधनांचे मूल्यमापन\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22038,51,7,'History & Civics','mr','शिवपूर्वकालीन भारत','[\"शिवपूर्वकालीन भारत म्हणजे इ.स. १२०० पूर्वीचा काळ, ज्यात विविध राजवंशांची सत्ता होती.\",\"यादव राजवंशाची सत्ता महाराष्ट्रात ११व्या शतकात होती.\",\"गुर्जर-प्रतिहार वायव्येकडील आक्रमणांनी आंध्र, कलिंग, विदर्भ इत्यादी राज्यांवर प्रभाव टाकला.\",\"पृथ्वीराज चौहान हे चौहान राजवंशाचे प्रमुख होते आणि त्यांनी मुहम्मद घोरीचा पराभव केला.\",\"मुहम्मद घोरीने ११व्या शतकात भारतात आक्रमण करून सिंध, तमिळनाडू इत्यादी प्रदेश जिंकले.\",\"कृष्ण तिसरा आणि महमूद गझनी यांनी भारतात अनेक स्वारी केल्या.\",\"बाह्मनी आणि विजयनगर हे दक्षिण भारतातील प्रमुख राज्ये होती.\",\"बाह्मनी राज्याची स्थापना १३३६ मध्ये झाली आणि त्याचे प्रमुख सुलतान बहमनी होते.\",\"विजयनगर राज्याची सत्ता १३४७ मध्ये सुरू झाली आणि १५३० मध्ये समाप्त झाली.\",\"मुघल सत्तेची स्थापना बाबरने १५२६ मध्ये केली.\",\"अकबर, हुमायून, शेरशाह, आणिंगजेब हे मुघल साम्राज्याचे प्रमुख सुलतान होते.\",\"अकबराने पानिपतची लढाई (१५५६) आणि पानिपतची दुसरी लढाई (१५५६) लढून मुघल साम्राज्याचे क्षेत्र वाढवले.\",\"महाराणा प्रताप, चांदबिबी, राणी दुर्गावती हे शिख, मराठा आणि आहोम यांच्या संघर्षात महत्त्वाचे होते.\",\"सुलतान शाही, निजामशाही, कुतुबशाही इत्यादी विविध उपराज्ये मुघल साम्राज्याखाली आली.\",\"मुघल साम्राज्याच्या पतनानंतर भारतात विविध स्वायत्त राज्ये उभी राहिली.\",\"शिवपूर्वकालीन भारतात राजकीय, सांस्कृतिक आणि धार्मिक विविधता होती.\",\"यादव राजवंशाची राजधानी घोरी होती.\",\"बाह्मनी आणि विजयनगर राज्यांनी दक्षिण भारतात आपली सत्ता स्थापन केली.\",\"मुघल साम्राज्याने भारतात तोफखाना आणि प्रशासनिक सुधारणा आणल्या.\",\"महाराणा प्रतापाने दीन-इ-इलाही धर्माची स्थापना केली.\",\"शाही आणि उपराज्यांच्या संघर्षामुळे भारतात विविध राजकीय बदल झाले.\"]','[{\"q\":\"आठव्या शतकात बंगालमध्ये कोणते बलशाली राजघराणे अस्तित्वात होते?\",\"options\":[\"चोळ\",\"पाल\",\"यादव\",\"होयसळ\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, आठव्या शतकात बंगालमध्ये \'पाल\' हे बलशाली राजघराणे होते.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"तराईन येथे झालेल्या पहिल्या युद्धात पृथ्वीराज चौहानने कोणाचा पराभव केला?\",\"options\":[\"मुहम्मद घोरी\",\"भिल्लम पाचवा\",\"राजेंद्र पहिला\",\"गोविंद तिसरा\"],\"answer\":0,\"explain\":\"तराईनच्या पहिल्या युद्धात पृथ्वीराज चौहानने मुहम्मद घोरीचा पराभव केला होता.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मध्य भारतात सत्तेवर आलेल्या गुर्जर-प्रतिहार घराण्याने आपला विस्तार कोठे केला नाही?\",\"options\":[\"काश्मीर\",\"कनोज\",\"गुजरात\",\"श्रीलंका\"],\"answer\":3,\"explain\":\"गुर्जर-प्रतिहारांनी काश्मीर, कनोज, दिल्ली, उत्तर प्रदेश आणि गुजरातमध्ये विस्तार केला, पण श्रीलंकेचा उल्लेख नाही.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"तमिळनाडूतील चोळ घराण्यातील कोणत्या पराक्रमी राजाने मालदीव बेटे आणि श्रीलंका जिंकून घेतली?\",\"options\":[\"विष्णूवर्धन\",\"राजेंद्र पहिला\",\"कृष्ण तिसरा\",\"सिंघण\"],\"answer\":1,\"explain\":\"चोळ राजा पहिला राजेंद्र याने आग्नेय आशियातील मालदीव आणि श्रीलंका जिंकली होती.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"कर्नाटकातील संपूर्ण प्रदेश कोणत्या होयसळ राजाने जिंकला?\",\"options\":[\"विष्णूवर्धन\",\"भिल्लम पाचवा\",\"पृथ्वीराज चौहान\",\"गोविंद तिसरा\"],\"answer\":0,\"explain\":\"होयसळ घराण्यातील विष्णूवर्धन या राजाने संपूर्ण कर्नाटक जिंकला होता.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राष्ट्रकूट राजा गोविंद तिसरा याने आपली सत्ता कोठून कोठपर्यंत विस्तारली होती?\",\"options\":[\"दिल्ली ते गुजरात\",\"कनोज ते रामेश्वर\",\"बंगाल ते महाराष्ट्र\",\"कर्नाटक ते श्रीलंका\"],\"answer\":1,\"explain\":\"गोविंद तिसरा याने कनोजपासून रामेश्वरपर्यंत राष्ट्रकूट सत्तेचा प्रसार केला.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"यादव घराण्यातील भिल्लम पाचवा याची राजधानी कोठे होती?\",\"options\":[\"पैठण\",\"नाशिक\",\"देवगिरी\",\"पुणे\"],\"answer\":2,\"explain\":\"भिल्लम पाचवा याने औरंगाबादजवळच्या देवगिरी येथे आपली राजधानी स्थापन केली होती.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"तराईनच्या दुसऱ्या युद्धाचा परिणाम काय झाला?\",\"options\":[\"पृथ्वीराज चौहानने घोरीचा पराभव केला.\",\"मुहम्मद घोरीने पृथ्वीराज चौहानचा पराभव केला.\",\"दोघांमध्ये तह झाला.\",\"यादवांनी मध्यस्थी केली.\"],\"answer\":1,\"explain\":\"तराईनच्या दुसऱ्या युद्धात मुहम्मद घोरीने पृथ्वीराज चौहानचा पराभव केला.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"यादव काळात महाराष्ट्रात कोणत्या दोन महत्त्वाच्या संप्रदायांचा उदय झाला?\",\"options\":[\"नाथ आणि दत्त\",\"महानुभाव आणि वारकरी\",\"भक्ती आणि शक्ती\",\"शैव आणि वैष्णव\"],\"answer\":1,\"explain\":\"यादवांच्या काळात महाराष्ट्रात महानुभाव आणि वारकरी या संप्रदायांचा उदय झाला.\",\"topic\":\"शिवपूर्वकाळातील भारतातील राजसत्ता\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राष्ट्रकूट राजा कृष्ण तिसरा याने आपली सत्ता कोठपर्यंत नेली होती?\",\"options\":[\"अलाहाबाद\",\"रामेश्वर\",\"दिल्ली\",\"ब