om\":\"understand\"},{\"q\":\"कृष्णदेवरायाने \'आमुक्तमाल्यदा\' हा ग्रंथ कोणत्या भाषेत लिहिला?\",\"options\":[\"मराठी\",\"संस्कृत\",\"कन्नड\",\"तेलुगू\"],\"answer\":3,\"explain\":\"कृष्णदेवरायाने \'आमुक्तमाल्यदा\' हा ग्रंथ तेलुगू भाषेत लिहिला.\",\"topic\":\"विजयनगरचे राज्य\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील व्यक्तीने विजयनगरमध्ये कोणत्या मंदिराचे बांधकाम केले?\",\"options\":[\"कैलास मंदिर\",\"विठ्ठल मंदिर\",\"कोनार्क मंदिर\",\"बृहदीश्वर मंदिर\"],\"answer\":1,\"explain\":\"चित्रातील कृष्णदेवरायाच्या कारकिर्दीत विजयनगरमध्ये विठ्ठल मंदिराचे बांधकाम झाले.\",\"topic\":\"विजयनगरचे राज्य\",\"part\":4,\"bloom\":\"apply\",\"figure_image\":\"51\\/016_101.jpg\"},{\"q\":\"दिलेल्या चित्रात दर्शवलेल्या राजाच्या कारकिर्दीत विजयनगरचे राज्य उत्तरेस कोठपर्यंत पसरलेले होते?\",\"options\":[\"कटक\",\"गोवा\",\"रायचूर दोआब\",\"हिंदी महासागर\"],\"answer\":2,\"explain\":\"चित्रातील कृष्णदेवरायाच्या काळात विजयनगरचे राज्य उत्तरेस रायचूर दोआबापर्यंत पसरलेले होते.\",\"topic\":\"विजयनगरचे राज्य\",\"part\":4,\"bloom\":\"apply\",\"figure_image\":\"51\\/016_101.jpg\"},{\"q\":\"तालिकोटच्या लढाईत विजयनगरच्या राजाविरुद्ध खालीलपैकी कोण एकत्र आले नव्हते?\",\"options\":[\"आदिलशाही\",\"निजामशाही\",\"मुघलशाही\",\"बरीदशाही\"],\"answer\":2,\"explain\":\"तालिकोटच्या लढाईत आदिलशाही, निजामशाही, कुतुबशाही आणि बरीदशाही एकत्र आल्या होत्या; मुघलशाहीचा उल्लेख नाही.\",\"topic\":\"विजयनगरचे राज्य\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"कृष्णदेवरायाने खालीलपैकी कोणते प्रदेश जिंकून आपल्या राज्याला जोडले?\",\"options\":[\"विजयवाडा आणि राजमहेंद्री\",\"गोवा आणि कटक\",\"हंपी आणि तालिकोट\",\"रामेश्वर आणि रायचूर\"],\"answer\":0,\"explain\":\"कृष्णदेवरायाने विजयवाडा आणि राजमहेंद्री हे प्रदेश जिंकून आपल्या राज्याला जोडले.\",\"topic\":\"विजयनगरचे राज्य\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"विजयनगरच्या राज्याला उतरती कळा केव्हा लागली?\",\"options\":[\"हरिहरच्या मृत्यूनंतर\",\"बुक्कच्या मृत्यूनंतर\",\"कृष्णदेवरायानंतर\",\"मुहम्मद तुघलकाच्या मृत्यूनंतर\"],\"answer\":2,\"explain\":\"पाठातील