":\"understand\"},{\"q\":\"महंमूद गावानने अरबी व फारसी विद्यांच्या अभ्यासासाठी मदरसा कोठे स्थापन केली?\",\"options\":[\"गुलबर्गा\",\"विजापूर\",\"बीदर\",\"गोवळकोंडा\"],\"answer\":2,\"explain\":\"महंमूद गावानने बीदर येथे अरबी व फारसी विद्यांच्या अभ्यासासाठी मदरसा स्थापन केली.\",\"topic\":\"बहमनी राज्य\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"महंमूद गावानच्या प्रशासकीय सुधारणांमुळे बहमनी राज्यावर कोणता परिणाम झाला?\",\"options\":[\"राज्याचे लष्करी सामर्थ्य कमी झाले\",\"राज्यास आर्थिक सामर्थ्य प्राप्त झाले\",\"राज्याची राजधानी बदलली\",\"राज्यात यादवी माजली\"],\"answer\":1,\"explain\":\"महंमूद गावान एक उत्तम प्रशासक होता आणि त्याने बहमनी राज्यास आर्थिक सामर्थ्य प्राप्त करून दिले.\",\"topic\":\"बहमनी राज्य\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"बहमनी राज्याच्या विघटनानंतर खालीलपैकी कोणती \'शाही\' अस्तित्वात आली नाही?\",\"options\":[\"वऱ्हाडची इमादशाही\",\"विजापूरची आदिलशाही\",\"अहमदनगरची निजामशाही\",\"पुण्याची पेशवेशाही\"],\"answer\":3,\"explain\":\"बहमनी राज्याच्या विघटनातून इमादशाही, बरीदशाही, आदिलशाही, निजामशाही व कुतुबशाही या पाच शाही निर्माण झाल्या; पेशवेशाही नाही.\",\"topic\":\"बहमनी राज्य\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"महंमूद गावाननंतर बहमनी राज्यामध्ये कोणत्या गोष्टीची वाढ झाली, ज्यामुळे राज्याला उतरती कळा लागली?\",\"options\":[\"परकीय आक्रमणे\",\"सरदारांमधील गटबाजी\",\"दुष्काळ\",\"धार्मिक युद्धे\"],\"answer\":1,\"explain\":\"महंमूद गावाननंतर बहमनी सरदारांमध्ये गटबाजी वाढीस लागली, ज्यामुळे राज्याचे विघटन झाले.\",\"topic\":\"बहमनी राज्य\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"बहमनी राज्याचे एकूण किती शकले (तुकडे) झाले?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":3,\"explain\":\"बहमनी राज्याचे विघटन होऊन पाच स्वतंत्र राज्ये (शकले) निर्माण झाली.\",\"topic\":\"बहमनी राज्य\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"विजयनगर आणि बहमनी यांच्यातील संघर्षाचा बहमनी राज्यावर काय परिणाम झाला?\",\"options\":[\"बहमनी राज्य अधिक शक्तिशाली झाले\",\"बहमनी राज्यावर प्रतिकूल परिणाम झाला\",\"बहमनी राज्याने विजयनगर जिंकले\",\"दोन्ही राज्यांन