ember\"},{\"q\":\"महाराजांनी पर्यावरणाच्या रक्षणासाठी कशावर बंदी घातली होती?\",\"options\":[\"शेती करण्यावर\",\"किल्ले बांधण्यावर\",\"झाडे तोडण्यावर\",\"कचरा जाळण्यावर\"],\"answer\":2,\"explain\":\"पर्यावरण आणि निसर्गाच्या रक्षणासाठी महाराजांनी झाडे तोडण्यावर बंदी घातली होती.\",\"topic\":\"स्वराज्यसेवा\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"किल्ल्यावरील कचऱ्याचे व्यवस्थापन कसे करावे, असा महाराजांचा आदेश होता?\",\"options\":[\"कचरा किल्ल्यावरून खाली फेकून द्यावा.\",\"कचरा तलावात टाकावा.\",\"कचरा परसात जाळावा.\",\"कचरा तसाच साठवून ठेवावा.\"],\"answer\":2,\"explain\":\"स्वच्छतेसाठी कचरा इकडे-तिकडे न टाकता परसात जाळावा, असा महाराजांचा आदेश होता.\",\"topic\":\"स्वराज्यसेवा\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"कचरा जाळल्यानंतर उरलेल्या राखेचा उपयोग कशासाठी करायला सांगितला होता?\",\"options\":[\"शस्त्रास्त्रे घासण्यासाठी\",\"भाजीपाला पिकवण्यासाठी (राखेवर मातीचा पालापाचोळा)\",\"किल्ल्याच्या भिंती बांधण्यासाठी\",\"नदीत विसर्जित करण्यासाठी\"],\"answer\":1,\"explain\":\"राखेवर मातीचा पालापाचोळा टाकून त्याचा उपयोग शेती\\/बागेसाठी करण्याचे संकेत मजकुरातून मिळतात.\",\"topic\":\"स्वराज्यसेवा\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"महाराजांच्या कोणत्या कृतीतून त्यांचे \'बारीक-सारीक बाबींकडे लक्ष\' असल्याचे स्पष्ट होते?\",\"options\":[\"केवळ मोठ्या लढाया जिंकणे\",\"कचरा व्यवस्थापन आणि भाजी घेण्याबाबतचे छोटे आदेश\",\"दुसऱ्या राज्यांवर स्वारी करणे\",\"केवळ किल्ले बांधणे\"],\"answer\":1,\"explain\":\"कचरा व्यवस्थापन आणि शेतकऱ्यांच्या भाजीसारख्या छोट्या गोष्टींकडे लक्ष देणे हे त्यांच्या सूक्ष्म नियोजनाचे लक्षण आहे.\",\"topic\":\"स्वराज्यसेवा\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"महाराज केवळ योद्धे नव्हते, तर ते कोणत्या समाजाचे शिल्पकार होते?\",\"options\":[\"केवळ श्रीमंत समाजाचे\",\"केवळ लढाऊ समाजाचे\",\"नीतिमान आणि सुसंस्कृत समाजाचे\",\"परंपरावादी समाजाचे\"],\"answer\":2,\"explain\":\"महाराज एका नव्या, स्वतंत्र, नीतिमान आणि सुसंस्कृत समाजाची निर्मिती करणारे शिल्पकार होते.\",\"topic\":\"स्वराज्यसेवा\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"महाराजा