 दोन शाखा निघाल्या आहेत, म्हणजेच ते भाऊ आहेत.\",\"topic\":\"मराठी सत्तेच्या वर्चस्वाची पुन:स्थापना\",\"part\":10,\"bloom\":\"remember\",\"figure_image\":\"51\\/061_101.jpg\"},{\"q\":\"दिलेल्या वंशावळीनुसार, बाळाजी विश्वनाथ यांचे पुत्र कोण होते?\",\"options\":[\"बाळाजी उर्फ नानासाहेब\",\"बाजीराव (पहिला)\",\"चिमाजीअप्पा\",\"रघुनाथराव\"],\"answer\":1,\"explain\":\"वंशावळीत बाळाजी विश्वनाथ यांच्यानंतर बाजीराव (पहिला) यांचे नाव येते.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"तक्त्यानुसार, चिमाजीअप्पा यांच्या मुलाचे नाव काय आहे?\",\"options\":[\"सदाशिवरावभाऊ\",\"विश्वासराव\",\"माधवराव\",\"जनार्दन\"],\"answer\":0,\"explain\":\"वंशावळीत चिमाजीअप्पा यांच्या खाली सदाशिवरावभाऊंचे नाव दिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"सवाई माधवराव (पेशवा) हे कोणाचे पुत्र होते?\",\"options\":[\"माधवराव (पेशवा)\",\"रघुनाथराव\",\"नारायणराव (पेशवा)\",\"बाजीराव (दुसरा)\"],\"answer\":2,\"explain\":\"वंशावळीनुसार नारायणराव (पेशवा) यांच्याकडून सवाई माधवराव (पेशवा) ही शाखा दाखवली आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या माहितीनुसार, बाळाजी उर्फ नानासाहेब यांचे पुत्र म्हणून कोणाचा उल्लेख नाही?\",\"options\":[\"रघुनाथराव\",\"रामचंद्र\",\"जनार्दन\",\"चिमाजीअप्पा\"],\"answer\":3,\"explain\":\"चिमाजीअप्पा हे बाजीराव (पहिला) यांच्याकडून आलेली शाखा आहे, नानासाहेबांची नाही.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"रघुनाथराव यांनी दत्तक घेतलेल्या मुलाचे नाव काय होते?\",\"options\":[\"बाजीराव (दुसरा)\",\"नानासाहेब\",\"विश्वासराव\",\"सदाशिवरावभाऊ\"],\"answer\":1,\"explain\":\"तक्त्यात रघुनाथराव यांच्या नावाखाली \'नानासाहेब (दत्तक)\' असा उल्लेख आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"बाजीराव (दुसरा) हे कोणाचे पुत्र होते?\",\"options\":[\"नारायणराव\",\"बाळाजी उर्फ नानासाहेब\",\"रघुनाथराव\",\"चिमाजीअप्पा\"],\"answer\":2,\"explain\":\"वंशावळीनुसार बाजीराव (दुसरा) हे रघुनाथराव यांच्याकडून आलेले वंशज आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या संपूर्ण वंशावळीत एकूण किती व्यक्तींच्या नावापुढे \'पेशवा\' अशी पदवी लावली आहे?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"माधवराव, नारायणराव आणि सवाई माधवराव या तिघांच्या नावापुढे \'पेशवा\' असे लिहिले आहे.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"जर सदाशिवरावभाऊ हे चिमाजीअप्पांचे पुत्र असतील, तर बाजीराव (पहिला) हे सदाशिवरावभाऊंचे कोण लागतील?\",\"options\":[\"वडील\",\"भाऊ\",\"आजोबा\",\"काका\"],\"answer\":2,\"explain\":\"बाजीराव (पहिला) -> चिमाजीअप्पा -> सदाशिवरावभाऊ असा क्रम असल्याने ते आजोबा ठरतात.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या तक्त्यानुसार, नानासाहेबांच्या कोणत्या मुलाचा उल्लेख \'पेशवा\' म्हणून केलेला नाही?\",\"options\":[\"माधवराव\",\"नारायणराव\",\"विश्वासराव\",\"सवाई माधवराव\"],\"answer\":2,\"explain\":\"नानासाहेबांच्या मुलांपैकी विश्वासराव यांच्या नावापुढे \'पेशवा\' असे लिहिलेले नाही.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता गट बाळाजी उर्फ नानासाहेब यांच्या मुलांचा (थेट वंशजांचा) आहे?\",\"options\":[\"विश्वासराव, माधवराव, नारायणराव\",\"बाजीराव (दुसरा), नानासाहेब (दत्तक)\",\"चिमाजीअप्पा, सदाशिवरावभाऊ\",\"बाळाजी विश्वनाथ, बाजीराव (पहिला)\"],\"answer\":0,\"explain\":\"तक्त्यात नानासाहेब यांच्याकडून विश्वासराव, माधवराव आणि नारायणराव ही नावे दिली आहेत.\",\"topic\":\"स्वाध्याय\",\"part\":12,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22048,51,7,'History & Civics','mr','साम्राज्याची वाटचाल','[\"साम्राज्याची वाटचाल म्हणजे मराठा साम्राज्याचा इतिहास आणि त्याची वाढ-घट.\",\"मराठा साम्राज्याची सुरुवात शिवाजी महाराजांनी केली आणि नंतर पानिपतच्या युद्धानंतर त्याची शक्ती कमी झाली.\",\"इंदौरचे होळकर, नाना फडणवीस, ग्वालियरचे शिंदे, गायकवाड हे प्रमुख सरदार होते.\",\"इंदौरचे होळकर यांनी मराठा सत्तेची पुनःस्थापना केली आणि दिल्लीच्या बादशाहाला गादीवर परत आणले.\",\"नाना फडणवीस यांनी दक्षिण भारतात मराठा सत्तेचा विस्तार केला.\",\"ग्वालियरचे शिंदे यांनी ओडिशा व बंगालमध्ये मराठा प्रभाव वाढवला.\",\"गायकवाड यांनी इंग्रजांना धान्यसामग्री न दिल्याने मराठा-इंग्रज संघर्ष तीव्र झाला.\",\"शिवाजी महाराजांनी आरमार उभारला ज्याने मराठा सत्तेला मदत केली.\",\"इंग्रजांनी १८१७ मध्ये पुणे ताब्यात घेतल्यावर मराठा सत्तेचा अंत झाला.\",\"मराठा सत्तेच्या पतनाचे मुख्य कारण म्हणजे आंतरिक वाद आणि इंग्रजांचा दबाव.\",\"माल्हारराव होळकर यांनी उत्तर भारतात मराठा प्रतिष्ठा पुनःस्थापित केली.\",\"पानिपतच्या युद्धात मराठा सैन्याची शक्ती कमी झाली.\",\"साम्राज्याच्या विस्तारात शेतकरी, कर, व्यापार आणि तलाव-आढावा महत्त्वाचे होते.\",\"माल्हारराव होळकर यांनी शेतकऱ्यांना विहिरी खोदून मदत केली.\",\"मराठा सत्तेच्या पतनानंतर भारतात ब्रिटिश राजवट स्थापन झाली.\",\"मराठा सरदारांनी विविध प्रदेशात प्रशासन व लष्करी कार्य केले.\",\"मराठा सत्तेच्या काळात गनिमी काव्याची पद्धत वापरली.\",\"शिवाजी महाराजांनी आरमाराने समुद्रावर नियंत्रण ठेवले.\",\"इंदौरचे होळकर यांनी धर्मस्थळांची सेवा केली.\",\"नाना फडणवीस यांनी दक्षिणेतील राजकारणाची सूत्रे सांभाळली.\",\"ग्वालियरचे शिंदे यांनी ओडिशा व बंगालमध्ये मराठा प्रभाव वाढवला.\",\"गायकवाड यांनी इंग्रजांना धान्यसामग्री न दिल्याने संघर्ष तीव्र झाला.\",\"मराठा सत्तेच्या पतनानंतर ब्रिटिशांनी भारतावर नियंत्रण घेतले.\",\"मराठा सत्तेच्या इतिहासात विविध सरदारांनी योगदान दिले.\",\"मराठा सत्तेच्या पतनानंतर भारतीय समाजव्यवस्थेत बदल झाले.\"]','[{\"q\":\"इंदूरच्या होळकर सत्तेचे संस्थापक कोण होते?\",\"options\":[\"मल्हारराव होळकर\",\"पहिला बाजीराव\",\"माधवराव पेशवे\",\"नानासाहेब पेशवे\"],\"answer\":0,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की मल्हारराव हे इंदूरच्या होळकरांच्या सत्तेचे संस्थापक होते.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मल्हारराव होळकर कोणत्या युद्धपद्धतीत निष्णात होते?\",\"options\":[\"आरमारी युद्ध\",\"गनिमी कावा\",\"समोरासमोरचे युद्ध\",\"तटबंदीचे युद्ध\"],\"answer\":1,\"explain\":\"मल्हारराव होळकर गनिमी काव्याच्या युद्धपद्धतीत निष्णात होते, असे मजकुरात दिले आहे.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मल्हारराव होळकर यांनी कोणत्या दोन पेशव्यांच्या काळात उत्तरेत पराक्रम गाजवला?\",\"options\":[\"शिवाजी महाराज व संभाजी महाराज\",\"पहिला बाजीराव व नानासाहेब पेशवा\",\"माधवराव व नारायणराव पेशवा\",\"बाळाजी विश्वनाथ व बाजीराव\"],\"answer\":1,\"explain\":\"पहिला बाजीराव व नानासाहेब पेशवा यांच्या काळात त्यांनी उत्तरेत पराक्रम गाजवला.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मराठ्यांचे वर्चस्व माळव्यात आणि राजपुतान्यात प्रस्थापित करण्यात कोणाचा मोठा वाटा होता?\",\"options\":[\"निजाम-उल-मुल्क\",\"माधवराव पेशवे\",\"मल्हारराव होळकर\",\"शिवाजी महाराज\"],\"answer\":2,\"explain\":\"माळव्यात आणि राजपुतान्यात मराठ्यांचे वर्चस्व प्रस्थापित करण्यात मल्हाररावांचा मोठा वाटा होता.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पानिपतच्या युद्धानंतर उत्तरेतील मराठ्यांची प्रतिष्ठा सांभाळण्यासाठी मल्हाररावांनी कोणाला मदत केली?\",\"options\":[\"पहिला बाजीराव\",\"नानासाहेब पेशवा\",\"माधवराव पेशवा\",\"शाहू महाराज\"],\"answer\":2,\"explain\":\"पानिपतानंतर मराठ्यांची प्रतिष्ठा सांभाळण्यात त्यांनी माधवराव पेशव्यांना मदत केली.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"मल्हारराव होळकर यांच्या लष्करी कौशल्याचा उपयोग प्रामुख्याने कशासाठी झाला?\",\"options\":[\"केवळ स्वतःचे राज्य वाचवण्यासाठी\",\"मराठी सत्तेचा उत्तर भारतात विस्तार करण्यासाठी\",\"व्यापारात वाढ करण्यासाठी\",\"समुद्रावर ताबा मिळवण्यासाठी\"],\"answer\":1,\"explain\":\"मल्हाररावांनी उत्तरेत पराक्रम गाजवून मराठ्यांचे वर्चस्व प्रस्थापित केले, म्हणजेच साम्राज्यविस्तारात मदत केली.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, मराठ्यांच्या साम्राज्यविस्तारामागे कोणाचे महत्त्वाचे योगदान होते?\",\"options\":[\"केवळ पेशव्यांचे\",\"सरदार घराण्यांचे\",\"परकीय आक्रमकांचे\",\"स्थानिक शेतकऱ्यांचे\"],\"answer\":1,\"explain\":\"साम्राज्यविस्तारामागे ज्या सरदार घराण्यांनी महत्त्वाचे योगदान दिले, त्यांचा आढावा या पाठात घेतला आहे.\",\"topic\":\"इंदूरचे होळकर\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"मल्हारराव होळकर यांच्याबद्दल कोणते विधान चुकीचे 