\":\"परिचय\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'अशोक के फूल\' द्विवेदी जी की किस प्रकार की साहित्यिक कृति है?\",\"options\":[\"उपन्यास\",\"निबंध\",\"कविता\",\"नाटक\"],\"answer\":1,\"explain\":\"प्रमुख कृतियों की सूची में \'अशोक के फूल\' को निबंध के रूप में वर्गीकृत किया गया है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"द्विवेदी जी द्वारा रचित \'पुनर्नवा\' साहित्य की कौन-सी विधा है?\",\"options\":[\"निबंध\",\"आत्मकथा\",\"उपन्यास\",\"समालोचना\"],\"answer\":2,\"explain\":\"पाठ के अनुसार \'पुनर्नवा\' एक उपन्यास है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"आचार्य हजारीप्रसाद द्विवेदी की मृत्यु कब हुई थी?\",\"options\":[\"१९७९\",\"१९८९\",\"१९६९\",\"१९५९\"],\"answer\":0,\"explain\":\"लेखक का निधन वर्ष १९७९ में हुआ था।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"द्विवेदी जी के साहित्यिक व्यक्तित्व के संबंध में कौन-सा कथन सही है?\",\"options\":[\"वे केवल एक कवि थे।\",\"वे उत्कृष्ट समालोचक और निबंधकार थे।\",\"वे केवल विदेशी साहित्य के अनुवादक थे।\",\"वे केवल विज्ञान लेखक थे।\"],\"answer\":1,\"explain\":\"परिचय के अनुसार वे मौलिक निबंधकार और उत्कृष्ट समालोचक थे।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"यदि आपको द्विवेदी जी का कोई निबंध संग्रह पढ़ना हो, तो आप इनमें से किसे चुनेंगे?\",\"options\":[\"बाणभट्ट की आत्मकथा\",\"पुनर्नवा\",\"कल्पलता\",\"इनमें से कोई नहीं\"],\"answer\":2,\"explain\":\"पाठ में \'कल्पलता\' को निबंध श्रेणी में रखा गया है, जबकि अन्य दो उपन्यास हैं।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"प्रस्तुत निबंध \'नाखून क्यों बढ़ते हैं?\' के लेखक कौन हैं?\",\"options\":[\"आचार्य हजारीप्रसाद\",\"प्रेमचंद\",\"महादेवी वर्मा\",\"रामधारी सिंह दिनकर\"],\"answer\":0,\"explain\":\"पाठ के अनुसार, इस वैचारिक निबंध के लेखक आचार्य हजारीप्रसाद हैं।\",\"topic\":\"नाखून क्यों बढ़ते हैं?\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"लेखक के अनुसार नाखून किसका प्रतीक हैं?\",\"options\":[\"मानवता का\",\"पशुता और बुराइयों का\",\"सभ्यता का\",\"सुंदरता का\"],\"answe