केवल \'बेबात - बिना बात\' ही पाठ में दिए गए अर्थों के अनुसार सही है।\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खेत में बीज डालने की प्रक्रिया को पाठ के शब्दार्थ में क्या कहा गया है?\",\"options\":[\"सीकर\",\"रोपना\",\"बेबात\",\"जुबाँ\"],\"answer\":1,\"explain\":\"बीज बोने या डालने को \'रोपना\' कहा जाता है।\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"पाठ के आधार पर \'जुबाँ\' शब्द के बारे में क्या सही है?\",\"options\":[\"इसके दो अर्थ जीभ और मुँह दिए गए हैं\",\"इसका अर्थ केवल कान है\",\"इसका अर्थ बिना बात है\",\"इसका अर्थ सिलाकर है\"],\"answer\":0,\"explain\":\"पाठ के शब्दार्थ में \'जुबाँ\' के सामने \'जीभ, मुँह\' लिखा गया है।\",\"topic\":\"स्वाध्याय\",\"part\":6,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (22080,53,8,'Hindi','hi','मेरे रजा साहब','[\"सहयोग, मन, वचन, कर्म जीवन के चार मूलमंत्र हैं।\",\"इन चार तत्वों से ही सुखी और सफल जीवन बनता है।\",\"सहयोग का अर्थ है दूसरों की मदद करना और एक साथ काम करना।\",\"मन का शुद्ध होना आवश्यक है; बुरे विचार जीवन को दूषित करते हैं।\",\"वचन की पवित्रता मतलब है अपने वादे को निभाना।\",\"कर्म का अर्थ है ईमानदारी और लगन से काम करना।\",\"जब मन, वचन और कर्म एक साथ काम करते हैं, तो जीवन में शांति आती है।\",\"श्रीमती जी की सलाह से पता चलता है कि छोटी-छोटी बातों का ध्यान रखना भी जरूरी है।\",\"सामान रखना भूल जाना कभी-कभी बड़ी परेशानी खड़ी कर देता है।\",\"यात्रा की तैयारी में सूची बनाना स्मरण शक्ति को बढ़ाता है।\",\"जिम्मेदारी का अर्थ है अपने कामों को समय पर पूरा करना।\",\"पत्रों का जवाब देना संबंधों को मजबूत बनाता है।\",\"बिजली के बिल और बीमा का भुगतान करना जिम्मेदार नागरिक होने का हिस्सा है।\",\"धूप से बचने के लिए चश्मा, छतरी और क्रीम जैसे उपाय करना समझदारी है।\",\"नेलकटर जैसी छोटी चीज का न मिलना भी परेशानी का कारण बन सकता है।\"]','[{\"q\":\"सुजाता बजाज का जन्म कब हुआ था?\",\"options\":[\"१९४६\",\"१९५६\",\"१९६६\",\"१९७६\"],\"answer\":1,\"explain\":\"पाठ के अनुसार सुजाता बजाज का जन्म १९५६ में हुआ था।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सुजाता बजाज का जन्म स्थान कौन-सा है?\",\"options\":[\"जोधपुर\",\"उदयपुर\",\"जयपुर\",\"बीकानेर\"],\"answer\":2,\"explain\":\"लेखिका का जन्म राजस्थान के जयपुर शहर में हुआ था।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सुजाता बजाज मुख्य रूप से किस क्षेत्र में प्रसिद्ध हैं?\",\"options\":[\"लेखिका\",\"गायिका\",\"चित्रकार\",\"नृत्यांगना\"],\"answer\":2,\"explain\":\"परिचय के अनुसार सुजाता बजाज एक प्रसिद्ध चित्रकार हैं।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सुजाता बजाज आजकल कहाँ रहती हैं?\",\"options\":[\"लंदन\",\"न्यूयॉर्क\",\"पेरिस\",\"दिल्ली\"],\"answer\":2,\"explain\":\"पाठ में स्पष्ट उल्लेख है कि वे आजकल पेरिस में रहती हैं।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सुजाता बजाज की कला पर किस संस्कृति का प्रभाव दिखाई पड़ता है?\",\"options\":[\"चीनी कला\",\"पश्चिमी कला\",\"अफ्रीकी कला\",\"जापानी कला\"],\"answer\":1,\"explain\":\"उनकी चित्र एवं मूर्तिकला पर पश्चिमी कला का प्रभाव दिखाई पड़ता है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सुजाता बजाज की चित्र एवं मूर्तिकला किस रंग में डूबी हुई रहती है?\",\"options\":[\"विदेशी रंग\",\"आधुनिक रंग\",\"भारतीय रंग\",\"प्राकृतिक रंग\"],\"answer\":2,\"explain\":\"उनकी कला भारतीय रंग में डूबी हुई रहती है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"सुजाता बजाज द्वारा बनाए गए चित्रों पर आधारित पुस्तक किस पर केंद्रित है?\",\"options\":[\"शिव जी\",\"गणेश जी\",\"कृष्ण जी\",\"राम जी\"],\"answer\":1,\"explain\":\"सुजाता जी द्वारा बनाए गए ‘गणेश’ जी के चित्रों पर आधारित एक पुस्तक प्रकाशित है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"सुजाता बजाज की कला में \'सादगी\' के साथ और किसका संगम दिखाई देता है?\",\"options\":[\"कठोरता\",\"रंगीनी\",\"अंधेरा\",\"जटिलता\"],\"answer\":1,\"explain\":\"उनकी कला में ऐसी दुनिया का सृजन है जिसमें सादगी भी है और रंगीनी भी।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"लेखिका की कला में किन दो विपरीत भावों का सृजन दिखाई देता है?\",\"options\":[\"क्रोध और शांति\",\"डर और साहस\",\"खुशी और गम\",\"सफलता और असफलता\"],\"answer\":2,\"explain\":\"पाठ के अनुसार उनकी कला में खुशी भी है और गम भी।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"सुजाता बजाज के परिचय के आधार पर उनकी कला की विशेषता क्या है?\",\"options\":[\"केवल पश्चिमी प्रभाव\",\"केवल सादगी का चित्रण\",\"भारतीय रंग और पश्चिमी कला का मेल\",\"केवल मूर्तिकला पर ध्यान\"],\"answer\":2,\"explain\":\"उनकी कला भारतीय रंगों में डूबी है और उस पर पश्चिमी कला का प्रभाव भी है।\",\"topic\":\"परिचय\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"\'मेरे रजा साहब\' पाठ की लेखिका कौन हैं?\",\"options\":[\"सुभद्रा कुमारी चौहान\",\"सुजाता बजाज\",\"महादेवी वर्मा\",\"अमृता प्रीतम\"],\"answer\":1,\"explain\":\"पाठ के परिचय के अनुसार, लेखिका सुजाता बजाज ने अपने संस्मरण लिखे हैं।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"सैयद हैदर रजा किस क्षेत्र में प्रसिद्ध थे?\",\"options\":[\"संगीतकार\",\"लेखक\",\"चित्रकार\",\"नर्तक\"],\"answer\":2,\"explain\":\"पाठ में उन्हें प्रसिद्ध चित्रकार बताया गया है।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"प्रस्तुत पाठ साहित्य की किस विधा में लिखा गया है?\",\"options\":[\"कहानी\",\"कविता\",\"संस्मरण\",\"निबंध\"],\"answer\":2,\"explain\":\"पाठ परिचय में स्पष्ट है कि लेखिका ने अपने \'संस्मरण\' लिखे हैं।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"रजा साहब का युवा कलाकारों के प्रति कैसा दृष्टिकोण था?\",\"options\":[\"उन्हें हतोत्साहित करना\",\"उन्हें अनदेखा करना\",\"उन्हें प्रोत्साहन देना\",\"उनसे प्रतिस्पर्धा करना\"],\"answer\":2,\"explain\":\"पाठ में उनके गुणों में \'युवा कलाकारों को प्रोत्साहन\' देना शामिल है।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"रजा साहब की \'जिज्ञासुवृत्ति\' से क्या तात्पर्य है?\",\"options\":[\"कुछ नया जानने की इच्छा\",\"शांत रहने का स्वभाव\",\"केवल चित्र बनाना\",\"घूमने का शौक\"],\"answer\":0,\"explain\":\"जिज्ञासुवृत्ति का अर्थ है जानने या सीखने की इच्छा रखना।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"यदि कोई व्यक्ति अपनी बनाई हुई पेंटिंग्स से बहुत जुड़ाव महसूस करता है, तो रजा साहब का कौन-सा गुण उसमें दिखता है?\",\"options\":[\"मानवीयता से प्रेम\",\"कृतियों के प्रति लगाव\",\"जिज्ञासुवृत्ति\",\"युवाओं को प्रोत्साहन\"],\"answer\":1,\"explain\":\"अपनी रचनाओं या कृतियों से जुड़ाव \'कृतियों के प्रति लगाव\' कहलाता है।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"पाठ के अनुसार, कला का मानव पर क्या प्रभाव पड़ता है?\",\"options\":[\"मानव दुखी होता है\",\"मानव आनंद अनुभव करता है\",\"मानव कला से डरता है\",\"मानव आलसी हो जाता है\"],\"answer\":1,\"explain\":\"मौलिक सृजन के बिंदु में दिया गया है कि \'कला से मानव आनंद अनुभव करता है\' ।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"रजा साहब के \'सर्जक-मनभाव\' का क्या अर्थ है?\",\"options\":[\"नष्ट करने की भावना\",\"कुछ नया निर्माण करने का भाव\",\"व्यापार करने का भाव\",\"आलोचना करने का भाव\"],\"answer\":1,\"explain\":\"सर्जक का अर्थ है सृजन करने वाला या निर्माण करने वाला।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"लेखिका ने रजा साहब के किन गुणों को इस पाठ में दर्शाया है?\",\"options\":[\"केवल उनकी चित्रकला की तकनीक\",\"उनकी धन-संपत्ति\",\"मानवीयता, जिज्ञासा और कलाकारों को प्रोत्साहन\",\"उनकी विदेश यात्राएं\"],\"answer\":2,\"explain\":\"पाठ में उनके मानवीय प्रेम, जिज्ञासा और प्रोत्साहन जैसे गुणों का वर्णन है।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"लेखिका के अनुसार, इस पाठ में किसके दर्शन होते हैं?\",\"options\":[\"एक सफल व्यापारी के\",\"एक सच्चे कलाकार के\",\"एक कठोर शिक्षक के\",\"एक प्रसिद्ध राजनेता के\"],\"answer\":1,\"explain\":\"पाठ के अंत में उल्लेख है कि \'इस पाठ में एक सच्चे कलाकार के दर्शन होते हैं\' ।\",\"topic\":\"मौलिक सृजन\",\"part\":3,\"bloom\":\"evaluate\"},{\"q\":\"लेखिका को रजा साहब के निधन का समाचार कब मिला?\",\"options\":[\"२३ अगस्त की सुबह\",\"२३ जुलाई की सुबह\",\"२३ फरवरी की सुबह\",\"२३ जनवरी की सुबह\"],\"answer\":1,\"explain\":\"पाठ के अनुसार, २३ जुलाई सुबह-सुबह ही समाचार मिला कि रजा साहब नहीं रहे।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"लेखिका फरवरी में दिल्ली किस उद्देश्य से गई थीं?\",\"options\":[\"रजा साहब से मिलने\",\"अस्पताल में भर्ती होने\",\"अपनी \'गणपति प्रदर्शनी\' के लिए\",\"छुट्टियाँ बिताने\"],\"answer\":2,\"explain\":\"लेखिका ने बताया है कि वे फरवरी में अपनी \'गणपति प्रदर्शनी\' के लिए दिल्ली पहुँची थीं।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"लेखिका को क्या उम्मीद थी कि रजा साहब प्रदर्शनी के उद्घाटन पर कैसे आएँगे?\",\"options\":[\"पैदल चलकर\",\"गाड़ी में बैठकर\",\"अपनी व्हीलचेयर पर\",\"अपने शिष्यों के साथ\"],\"answer\":2,\"explain\":\"लेखिका सोच रही थी कि रजा साहब शायद अपनी व्हीलचेयर पर प्रदर्शनी के उद्घाटन पर आएँ।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"लेखिका के अनुसार उस रात कौन सी \'अनहोनी\' हुई?\",\"options\":[\"रजा साहब अस्पताल पहुँच गए\",\"रजा साहब सपने में आए\",\"प्रदर्शनी रद्द हो गई\",\"दिल्ली में बारिश हुई\"],\"answer\":1,\"explain\":\"लेखिका ने रजा साहब के सपने में आने और उनसे बात करने को अनहोनी कहा है।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"सपने में रजा साहब ने लेखिका से क्या कहा?\",\"options\":[\"मैं प्रदर्शनी में आऊँगा\",\"सुजाता, एक बार मुझसे मिलने आ जाओ\",\"गणपति की पेंटिंग बहुत अच्छी है\",\"मुझे दिल्ली पसंद नहीं है\"],\"answer\":1,\"explain\":\"सपने में रजा साहब ने कहा, \'सुजाता एक बार मुझसे मिलने आ जाओ। अब मैं जाने वाला हूँ।\'\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"अस्पताल में रजा साहब किस अवस्था में लेटे हुए थे?\",\"options\":[\"नींद में\",\"बातें करते हुए\",\"शून्य की तरह\",\"हँसते हुए\"],\"answer\":2,\"explain\":\"पाठ में उल्लेख है कि वे अस्पताल में \'शून्य की तरह\' लेटे हुए थे।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"अस्पताल में लेखिका ने रजा साहब के शरीर के किस हिस्से को छुआ?\",\"options\":[\"सिर को\",\"पैरों को\",\"हाथों को\",\"कंधों को\"],\"answer\":2,\"explain\":\"लेखिका ने उनके हाथों को छुआ और अलविदा कहकर लौट आई।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"अस्पताल में रजा साहब के जीवित होने का क्या प्रमाण था?\",\"options\":[\"वे बोल रहे थे\",\"सिर्फ साँस चल रही थी\",\"वे आँखें खोल रहे थे\",\"वे हाथ हिला रहे थे\"],\"answer\":1,\"explain\":\"लेखिका के अनुसार, अस्पताल में रजा साहब की सिर्फ साँस चल रही थी।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"सपने में रजा साहब ने लेखिका को किस बात के लिए शुभकामना दी?\",\"options\":[\"जन्मदिन के लिए\",\"यात्रा के लिए\",\"शो (प्रदर्शनी) के लिए\",\"अच्छे स्वास्थ्य के लिए\"],\"answer\":2,\"explain\":\"रजा साहब ने सपने में लेखिका को उनके शो के लिए शुभकामना दी।\",\"topic\":\"रजा साहब की यादें\",\"part\":4,\"bl