\":\"analyze\"},{\"q\":\"अण्णांनी मानधनाचे पैसे मिळवण्याचा आग्रह का टाळला असावा?\",\"options\":[\"त्यांना पैशांची गरज नव्हती\",\"त्यांना गरिबी विसरण्याची भीती वाटत होती\",\"बँक लांब होती\",\"त्यांना लिहायचा कंटाळा आला होता\"],\"answer\":1,\"explain\":\"अण्णांना वाटले की पैशांच्या मोहात ते गरिबीला विसरून जातील आणि त्यांचे वास्तववादी लेखन थांबेल.\",\"topic\":\"वास्तववादी साहित्याचा विचार\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यात आलेल्या \'बटईची भाषा\' हा शब्द कोणाशी संबंधित आहे?\",\"options\":[\"प्रकाशकांशी\",\"शेतगड्यांशी\",\"लेखकाच्या पत्नीशी\",\"परदेशी लोकांशी\"],\"answer\":1,\"explain\":\"अण्णांनी \'शेतगड्यांची बटईची भाषा\' अनुभवायला मिळते असे म्हटले आहे.\",\"topic\":\"वास्तववादी साहित्याचा विचार\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"अण्णांच्या साहित्याचा मुख्य स्रोत (Source) कोणता आहे?\",\"options\":[\"कल्पनाविलास\",\"ऐकीव गोष्टी\",\"प्रत्यक्ष जगण्याचे वास्तव अनुभव\",\"परदेशी कादंबऱ्या\"],\"answer\":2,\"explain\":\"अण्णांच्या मते वास्तवातून भरलेले जगण्याचे साहित्य त्यांना झोपडीतच लिहिता येते.\",\"topic\":\"वास्तववादी साहित्याचा विचार\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"लेखकाने अण्णांना दिलेल्या सल्ल्यावरून लेखकाची कोणती इच्छा दिसून येते?\",\"options\":[\"अण्णांनी गरिबीतच राहावे\",\"अण्णांचे जीवन सुखवस्तू आणि थाटामाटाचे व्हावे\",\"अण्णांनी लिहिणे थांबवावे\",\"अण्णांनी शहरात येऊ नये\"],\"answer\":1,\"explain\":\"लेखकाने बंगला, डायनिंग टेबल आणि सुखसोयींचा उल्लेख करून अण्णांचे जीवन सुसह्य व्हावे अशी इच्छा व्यक्त केली.\",\"topic\":\"वास्तववादी साहित्याचा विचार\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"जेव्हा वाक्यात कर्माच्या लिंग, वचनाप्रमाणे क्रियापदाचे रूप बदलते, तेव्हा त्यास कोणता प्रयोग म्हणतात?\",\"options\":[\"कर्तरी प्रयोग\",\"कर्मणी प्रयोग\",\"भावे प्रयोग\",\"मिश्र प्रयोग\"],\"answer\":1,\"explain\":\"कर्माच्या लिंग-वचनानुसार क्रियापद बदलल्यास तो कर्मणी प्रयोग असतो.\",\"topic\":\"व्याकरण: प्रयोग\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"कर्मणी प्रयोगात कर्ता सामान्यतः कोणत्या विभक्तीत असतो?\",\"options\":[\"प्रथमा\",\"द्विती