wer\":2,\"explain\":\"भावे प्रयोगात कर्ता तृतीया आणि कर्म द्वितीया विभक्तीत असते.\",\"topic\":\"व्याकरण: प्रयोग\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"भावे प्रयोगाच्या व्याख्येनुसार क्रियापद कोणत्या पुरुषात असते?\",\"options\":[\"प्रथम पुरुषी\",\"द्वितीय पुरुषी\",\"तृतीय पुरुषी\",\"उत्तम पुरुषी\"],\"answer\":2,\"explain\":\"भावे प्रयोगाची व्याख्या सांगते की क्रियापद नेहमी तृतीयपुरुषी असते.\",\"topic\":\"व्याकरण: प्रयोग\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात कोणत्या प्रसिद्ध म्हणीचा उल्लेख केला आहे?\",\"options\":[\"अति तेथे माती\",\"व्यक्ती तितक्या प्रकृती\",\"हातच्या काकणाला आरसा कशाला\",\"गरज सरो अन् वैद्य मरो\"],\"answer\":1,\"explain\":\"उताऱ्यात \'व्यक्ती तितक्या प्रकृती\' ही म्हण स्पष्टपणे दिली आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"सामान्यांना कशा प्रकारचे बोलणे हवे असते?\",\"options\":[\"अलंकारिक आणि कठीण\",\"केवळ शब्दबोधापुरते\",\"साधे, सरळ आणि उगवतीत\",\"गूढ आणि अनाकलनीय\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केले आहे की सामान्यांना साधे, सरळ आणि उगवतीत बोलणे हवे असते.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"लेखकाने वाणीवर कोणती नवीन म्हण बनवायला हरकत नाही असे म्हटले आहे?\",\"options\":[\"वाणी तितके विचार\",\"भाषेचे तितकेही बोलणे\",\"बोलणे तितके अर्थ\",\"शब्दांचे तितके खेळ\"],\"answer\":1,\"explain\":\"उताऱ्यात \'वाणीवर भाषेचे तितकेही बोलणे अशी म्हण बनवायला हरकत नाही\' असे म्हटले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"समाजात वावरताना \'मोकळ्या संवादावर\' काय पडत असतात?\",\"options\":[\"प्रकाशझोत\",\"फुले\",\"बंधने\",\"पडदे\"],\"answer\":2,\"explain\":\"समाजात वावरताना तथाकथित मोकळ्या संवादावर बंधने पडत असतात असे उताऱ्यात म्हटले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"आपण कोणाशी गप्पा मारताना खूप मुक्त असतो अशी आपली समजूत असते?\",\"options\":[\"अनोळखी लोकांशी\",\"शत्रूंशी\",\"जवळच्या लोकांशी (उदा. पती\\/पत्नी)\",\"केवळ स्वतःशी\"],\"answer\":2,\"explain\":\"उताऱ्यात \'किमडेओशी (जवळच्या व्यक्तींशी) गप्पा मारताना आपण मुक्त असतो अशी समजूत असते\' असे दिले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"संवाद साधताना आपण \'मतभेदाचे अवघड विषय\' का टाळतो?\",\"options\":[\"वेळ वाचवण्यासाठी\",\"विषय माहित नसल्यामुळे\",\"समोरच्याचे मत माहीत नसल्यामुळे\",\"समोरच्याचे आग्रह-दुराग्रह ठाऊक असल्यामुळे\"],\"answer\":3,\"explain\":\"एकमेकांची मते, आग्रह, दुराग्रह ठाऊक असल्यामुळे आपण मतभेदाचे विषय शिताफीने टाळतो.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"बोलताना कशाची सतत काळजी घ्यावी लागते?\",\"options\":[\"व्याकरण बरोबर असण्याची\",\"समोरच्याचे मन दुखावले जाणार नाही याची\",\"खूप जोरात बोलण्याची\",\"इंग्रजी शब्द वापरण्याची\"],\"answer\":1,\"explain\":\"समोरच्या व्यक्तीचे मन दुखावले जाणार नाही, याची सतत काळजी घ्यावी लागते असे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात आलेल्या \'अवरोध\' या शब्दाचा संदर्भाप्रमाणे अर्थ काय होतो?\",\"options\":[\"प्रवाह\",\"अडथळा किंवा रोखणे\",\"प्रोत्साहन\",\"वेग\"],\"answer\":1,\"explain\":\"संवादात येणारा चमत्कारिक \'अवरोध\' म्हणजे बोलण्यातील अडथळा किंवा संकोच.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"लेखकाने संवादाला \'तथाकथित मोकळा संवाद\' असे का म्हटले आहे?\",\"options\":[\"कारण तो खरोखर मोकळा असतो\",\"कारण त्यावर अनेक बंधने असतात\",\"कारण तो फक्त भाषणात असतो\",\"कारण तो सर्वांना आवडतो\"],\"answer\":1,\"explain\":\"संवादावर अनेक सामाजिक आणि वैयक्तिक बंधने येत असल्याने त्याला \'तथाकथित\' (फक्त नावाला) मोकळा म्हटले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"सारांश लेखनाच्या दृष्टीने या उताऱ्याचा मुख्य विषय कोणता आहे?\",\"options\":[\"भाषेचे व्याकरण\",\"संवादातील सहजता आणि त्यातील मर्यादा\",\"पती-पत्नीमधील भांडणे\",\"म्हणींचा वापर\"],\"answer\":1,\"explain\":\"हा उतारा मानवी संवादाचे स्वरूप आणि त्यावर येणाऱ्या मर्यादांवर भाष्य करतो.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, संवादाचे किती प्रकार असू शकतात?\",\"options\":[\"मोजकेच\",\"दोनच\",\"अनंत\",\"शून्य\"],\"answer\":2,\"explain\":\"उताऱ्यात \'बोलण्याचे किती अनंत प्रकार असतात\' असे वाक्य आले आहे.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणते विधान उताऱ्याशी सुसंगत आहे?\",\"options\":[\"माणूस नेहमी पूर्णपणे मोकळेपणाने बोलतो.\",\"संवादात समोरच्याच्या स्वाभिमानाची काळजी घ्यावी लागत नाही.\",\"ओळखीच्या व्यक्तींमध्येही संवादावर काही मर्यादा येतात.\",\"सामान्यांना कठीण शब्दबोधाचे संवाद आवडतात.\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट केले आहे की ओळखीच्या व्यक्तींमध्येही एकमेकांच्या गुणादोषांमुळे संवादात मर्यादा येतात.\",\"topic\":\"सारांश लेखन\",\"part\":9,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22099,54,8,'Marathi','mr','धाडसी कॅप्टन : राधिका मेनन','[\"राधिका मेनन भारतातील पहिल्या महिला मर्चंट नेव्ही कॅप्टन आहेत.\",\"त्यांना इंटरनॅशनल मेरिटाईम ऑर्गनायझेशनने \'अँबार्ड फॉर एक्सेप्शनल ब्रेव्हरी अँट सी\' पुरस्कार दिला गेला.\",\"हा पुरस्कार मिळवणाऱ्या त्यांना जगातील पहिल्या महिला ठरली.\",\"राधिकाने बंगालच्या उपसागरात वादळात फसलेली सात मच्छीमारांचीजीव वाचवली.\",\"त्यांचे पालक नौसेनेत जायचं हेच विचार केल्यामुळे त्यांच्याशी मतभेद झाले होते.\",\"राधिकाने घरापासून लांब राहून पण त्यांच्या सपने पूर्ण केले.\",\"त्यांचे विवाह नेव्हीमधील रेडिओ ऑफिसरशी झाला, ज्यामुळे दोघांचे व्यवसाय एकमेकांशी संबंधित होते.\",\"समुद्री जहाजातील संवाद प्रणालींचा ज्ञान त्यांच्याकडून मच्छीमारांना मदत करण्यात आला.\",\"वादळामुळे जहाजाची स्थिती खतरनाक होते, पण राधिकाने धैर्याने काम केला.\",\"त्यांचे लक्ष्य मोठ्या जहाजाची कमान सांभाळणे होता, जे त्यांनी २०१२ मधे पूर्ण केला.\",\"राधिकांचा साहस आणि धाडस त्यांच्या टीमच्या मनोबलाला टिकट ठेवले.\",\"त्यांनी \'ऑल इंडिया मरीन कॉलेज\' मधे रेडिओ कोर्स साठी प्रवेश घेतला.\",\"राधिकांचे गाव कोचीच्या किलोमीटर अंतरावर असलेला कोची आहे.\",\"त्यांचे विवाह नोकरीच्या बंधनांमुळे घरातील जबाबदारी वाढली.\",\"राधिकांचे कृती ओघतक्ता तयार करण्यासाठी टीमने सुतकेच्या मोहिमेला सुरुवात केली.\"]','[{\"q\":\"\'जालन एक्सप्रेस\' हा कोणत्या प्रकारचा कथासंग्रह आहे?\",\"options\":[\"विनोदी कथासंग्रह\",\"बालकथासंग्रह\",\"ऐतिहासिक कथासंग्रह\",\"साहसी कथासंग्रह\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे \'जालन एक्सप्रेस\' हा बालकथासंग्रह आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखकाचा विनोदी कथासंग्रह कोणता?\",\"options\":[\"किनार\",\"छावा-केसरी\",\"हसत जगावे\",\"जालन एक्सप्रेस\"],\"answer\":2,\"explain\":\"\'हसत जगावे\' हा विनोदी कथासंग्रह असल्याचे प्रस्तावनेत दिले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भारतीय मर्चंट नेव्हीच्या पहिल्या महिला कॅप्टन कोण आहेत?\",\"options\":[\"राधिका मेनन\",\"पी. टी. उषा\",\"कल्पना चावला\",\"किरण बेदी\"],\"answer\":0,\"explain\":\"राधिका मेनन या भारतीय मर्चंट नेव्हीच्या पहिल्या महिला कॅप्टन आहेत.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"प्रस्तुत पाठ कोणत्या मासिकातून घेतला आहे?\",\"options\":[\"साधना\",\"चांदोबा\",\"किशोर\",\"लोकराज्य\"],\"answer\":2,\"explain\":\"हा पाठ \'किशोर\', मे २०१७ या मासिकातून घेतला आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राधिका मेनन यांना कोणत्या संस्थेचा पुरस्कार मिळाला आहे?\",\"options\":[\"युनेस्को\",\"इंटरनॅशनल मेरीटाईम ऑर्गनायझेशन\",\"जागतिक आरोग्य संघटना\",\"भारतीय नौसेना\"],\"answer\":1,\"explain\":\"त्यांना \'इंटरनॅशनल मेरीटाईम ऑर्गनायझेशन\'चा पुरस्कार मिळाला आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राधिका मेनन यांनी किती मच्छीमारांचे प्राण वाचवले?\",\"options\":[\"पाच\",\"सहा\",\"सात\",\"दहा\"],\"answer\":2,\"explain\":\"त्यांनी समुद्रात वादळात सापडलेल्या सात मच्छीमारांना वाचवले होते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"लेखकाने इंग्रजी विषयावर किती लेख लिहिले आहेत?\",\"options\":[\"१९७४\",\"२०१७\",\"२००७\",\"२०००\"],\"answer\":2,\"explain\":\"इंग्रजीवर त्यांचे २००७ लेख प्रसिद्ध आहेत असे उताऱ्यात म्हटले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राधिका मेनन यांना मिळालेल्या पुरस्काराचे जागतिक महत्त्व काय?\",\"options\":[\"हा भारतातील पहिला पुरस्कार आहे.\",\"हा पुरस्कार मिळवणाऱ्या त्या जगातील पहिल्या महिला ठरल्या आहेत.\",\"हा पुरस्कार फक्त कॅप्टनलाच मिळतो.\",\"हा पुरस्कार मच्छीमारांनी दिला आहे.\"],\"answer\":1,\"explain\":\"हा पुरस्कार मिळवणाऱ्या त्या जगातील पहिल्या महिला ठरल्या आहेत, हे त्याचे जागतिक महत्त्व आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर तुम्हाला बालकांसाठीच्या मासिकातील कथा वाचायच्या असतील, तर लेखकाच्या कोणत्या साहित्याचा शोध घ्याल?\",\"options\":[\"हसत जगावे\",\"इंग्रजी लेख\",\"वृत्तपत्रातील लेख\",\"किनार आणि छावा-केसरी\"],\"answer\":3,\"explain\":\"\'किनार\' आणि \'छावा-केसरी\' या बालमासिक कथा बालकांमध्ये प्रसिद्ध आहेत.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"राधिका मेनन यांच्या कार्यावरून त्यांना कोणता पुरस्कार देणे योग्य ठरले?\",\"options\":[\"बेस्ट रायटर अवॉर्ड\",\"अवॉर्ड फॉर एक्सेप्शनल ब्रेव्हरी ॲट सी\",\"बेस्ट कॅप्टन ऑफ द इयर\",\"जीवन गौरव पुरस्कार\"],\"answer\":1,\"explain\":\"त्यांच्या समुद्रातील शौर्यामुळे त्यांना \'अवॉर्ड फॉर एक्सेप्शनल ब्रेव्हरी ॲट सी\' देण्यात आला.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"प्रस्तुत पाठातून राधिका मेनन यांच्या कोणत्या पैलूचे दर्शन घडते?\",\"options\":[\"त्यांच्या लेखनाचे\",\"त्यांच्या विनोदी स्वभावाचे\",\"त्यांच्या शौर्याचे आणि धाडसाचे\",\"त्यांच्या शिक्षणाचे\"],\"answer\":2,\"explain\":\"प्रस्तुत पाठात त्यांच्या शौर्याचा परिचय करून दिलेला आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"लेखकाच्या लेखन व्यापाबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"त्यांनी फक्त पुस्तके लिहिली आहेत.\",\"त्यांनी केवळ इंग्रजीतून लेखन केले आहे.\",\"त्यांनी कथासंग्रह, बालमासिक कथा आणि वृत्तपत्रीय लेखन असे विविधांगी लेखन केले आहे.\",\"त्यांनी फक्त मच्छीमारांवर लेखन केले आहे.\"],\"answer\":2,\"explain\":\"लेखकाने कथासंग्रह, बालमासिके आणि वृत्तपत्रे अशा विविध माध्यमांतून लेखन केले आहे.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"राधिका मेनन यांचे बालपण कोणत्या भागात गेले?\",\"options\":[\"कोडुंगल्लूर, केरळ\",\"कोची, केरळ\",\"मुंबई, महाराष्ट्र\",\"चेन्नई, तामिळनाडू\"],\"answer\":0,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की राधिका या केरळच्या कोडुंगल्लूर भागात लहानाच्या मोठ्या झाल्या.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"राधिका यांच्यातील कोणते गुणविशेष उताऱ्यात सांगितले आहेत?\",\"options\":[\"शांतता आणि संयम\",\"धाडस आणि काहीतरी करून दाखवण्याची हिम्मत\",\"अभ्यास आणि खेळ\",\"चित्रकला आणि संगीत\"],\"answer\":1,\"explain\":\"उताऱ्यात \'धाडस आणि काहीतरी करून दाखवण्याची हिम्मत\' हे त्यांचे गुणविशेष सांगितले आहेत.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"राधिका मोकळ्या वेळेत काय करत असत?\",\"options\":[\"पुस्तके वाचणे\",\"घरातील कामे करणे\",\"सागरकिनारी भटकणे आणि किरण गोळावणे\",\"मैदानावर खेळणे\"],\"answer\":2,\"explain\":\"उताऱ्यात दिले आहे की मोकळ्या वेळेत त्यांचे नेहमी सागरकिनारी भटकणे आणि किरण गोळावणे असे.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"आई-वडिलांनी राधिका यांच्या निर्णयाला सुरुवातीला विरोध का केला?\",\"options\":[\"त्यांना ती नोकरी आवडत नव्हती\",\"ती नोकरी जोखमीची आहे असे त्यांना वाटले\",\"त्यांना राधिकाला परदेशी पाठवायचे नव्हते\",\"त्यांना राधिकाला डॉक्टर बनवायचे होते\"],\"answer\":1,\"explain\":\"आई-वडिलांना वाटले की ही जोखमीची नोकरी आहे, म्हणून त्यांनी विरोध केला.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"राधिका यांनी पालकांचा विरोध असतानाही आपला निर्णय कसा कायम ठेवला?\",\"options\":[\"घर सोडून जाऊन\",\"मित्रांच्या मदतीने\",\"उत्तुंग इच्छाशक्तीच्या जोरावर\",\"शिक्षकांच्या सल्ल्याने\"],\"answer\":2,\"explain\":\"उताऱ्यात म्हटले आहे की उत्तुंग इच्छाशक्ती असलेल्या राधिकेने त्यांच्या विरोधाची पर्वा केली नाही.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"राधिका यांनी आपले ध्येय कशावरून निश्चित केले?\",\"options\":[\"समुद्रातील लाटांना पाहून\",\"आई-वडिलांच्या सांगण्यावरून\",\"पुस्तकातील माहिती वाचून\",\"शिक्षकांच्या मार्गदर्शनामुळे\"],\"answer\":0,\"explain\":\"उताऱ्यात म्हटले आहे की \'या लाटांना पाहूनच त्यांची जीवंतच नाख (ध्येय) निश्चित केले\'.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"कोडुंगल्लूर हा भाग भारताच्या कोणत्या राज्यात आहे?\",\"options\":[\"कर्नाटक\",\"तामिळनाडू\",\"केरळ\",\"आंध्र प्रदेश\"],\"answer\":2,\"explain\":\"उताऱ्याच्या पहिल्या ओळीतच केरळ राज्याचा उल्लेख आहे.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"आई-वडिलांच्या मते राधिका यांचा स्वभाव कसा होता?\",\"options\":[\"खूप रागीट\",\"नाजूक\",\"खोडकर\",\"आळशी\"],\"answer\":1,\"explain\":\"आई-वडिलांना वाटले की आपली \'नाजूक\' मुलगी समुद्रातल्या धोक्यांचा सामना कसा करेल.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"\'उत्तुंग इच्छाशक्ती\' या शब्दाचा अर्थ उताऱ्याच्या संदर्भात काय होतो?\",\"options\":[\"खूप मोठी स्वप्ने पाहणे\",\"अतिशय प्रबळ जिद्द असणे\",\"नेहमी आनंदी राहणे\",\"दुसऱ्यांचे ऐकणे\"],\"answer\":1,\"explain\":\"राधिका यांनी विरोधाला न जुमानता आपला निर्णय पाळला, हे त्यांच्या प्रबळ जिद्दीचे लक्षण आहे.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"राधिका यांच्या बालपणातील वातावरणाने त्यांच्या करिअरवर कसा परिणाम केला?\",\"options\":[\"त्यांना शिक्षणाची गोडी लागली\",\"त्यांना समुद्राची ओढ लागली आणि ध्येय निश्चित झाले\",\"त्यांना प्रवासाचा कंटाळा आला\",\"त्यांना शेती करण्याची इच्छा झाली\"],\"answer\":1,\"explain\":\"सागरकिनारी भटकणे आणि लाटा पाहणे यामुळेच त्यांनी समुद्रातील करिअर निवडले.\",\"topic\":\"बालपण आणि जिद्द\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"पदवी मिळवल्यानंतर राधिका मेनन यांनी कोणत्या कॉलेजमध्ये रेडिओ कोर्ससाठी प्रवेश घेतला?\",\"options\":[\"कोची मर्चंट कॉलेज\",\"ऑल इंडिया मर्चंट कॉलेज\",\"शिपिंग कॉर्पोरेशन कॉलेज\",\"भारतीय समुद्री महाविद्यालय\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की त्यांनी \'ऑल इंडिया मर्चंट कॉलेज\'मध्ये प्रवेश घेतला.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"राधिका यांचे कॉलेज त्यांच्या घरापासून किती अंतरावर होते?\",\"options\":[\"२० किलोमीटर\",\"२५ किलोमीटर\",\"३० किलोमीटर\",\"४० किलोमीटर\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, कॉलेज त्यांच्या घरापासून तीस (३०) किलोमीटर अंतरावर होते.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"प्रशिक्षणादरम्यान राधिका यांना प्रामुख्याने कशाची माहिती मिळाली?\",\"options\":[\"जहाज चालवण्याचे तंत्र\",\"समुद्री हवामानाचा अंदाज\",\"समुद्री जहाजावरची संवादप्रणाली\",\"जहाजाची इंजिन दुरुस्ती\"],\"answer\":2,\"explain\":\"प्रशिक्षणदरम्यान राधिका यांना समुद्री जहाजावरच्या संवादप्रणालीची (Communication System) माहिती झाली.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"प्रशिक्षण पूर्ण झाल्यावर राधिका यांना कोणत्या संस्थेत नोकरी मिळाली?\",\"options\":[\"ऑल इंडिया मर्चंट नेव्ही\",\"शिपिंग कॉर्पोरेशन ऑफ इंडिया\",\"कोची पोर्ट ट्रस्ट\",\"भारतीय नौदल\"],\"answer\":1,\"explain\":\"त्यांना \'शिपिंग कॉर्पोरेशन ऑफ इंडिया\'मध्ये प्रशिक्षक रेडिओ ऑफिसरची नोकरी मिळाली.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"राधिका यांनी २०१० साली कोणत्या प्रमाणपत्रासाठी अर्ज केला?\",\"options\":[\"रेडिओ ऑफिसर सर्टिफिकेट\",\"नेव्ही कॅप्टन सर्टिफिकेट\",\"भारत सर्टिफिकेट\",\"कोची मर्चंट सर्टिफिकेट\"],\"answer\":2,\"explain\":\"उताऱ्यात दिलेल्या माहितीनुसार, २०१० साली त्यांनी \'भारत सर्टिफिकेट\'साठी अर्ज केला.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"राधिका यांच्या करिअरचा योग्य क्रम कोणता आहे?\",\"options\":[\"पदवी -> रेडिओ कोर्स -> रेडिओ ऑफिसर -> कॅप्टन\",\"रेडिओ कोर्स -> पदवी -> कॅप्टन -> रेडिओ ऑफिसर\",\"पदवी -> कॅप्टन -> रेडिओ कोर्स -> रेडिओ ऑफिसर\",\"रेडिओ ऑफिसर -> पदवी -> रेडिओ कोर्स -> कॅप्टन\"],\"answer\":0,\"explain\":\"उताऱ्यातील घटनाक्रमानुसार आधी पदवी, मग रेडिओ कोर्स, त्यानंतर रेडिओ ऑफिसरची नोकरी आणि शेवटी कॅप्टन पद मिळाले.\",\"topic\":\"शिक्षण आणि कारकीर्द\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"रेडिओ ऑफिसर म्हणून काम केल्यानंतर राधिका यांचे पुढील ध्येय काय होते?\",\"options\":[\"परदेशात नोकरी करणे\",\"स्वतःचे कॉलेज सुरू कर