ाऱ्यात \'मॅडोना अँड दी रॉक्स\' हे लिओनार्दोने काढलेल्या चित्रांपैकी एक असल्याचे म्हटले आहे.\",\"topic\":\"अष्टपैलू व्यक्तिमत्त्व आणि वारसा\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"लिओनार्दोने जगासाठी वारसा म्हणून काय मागे ठेवले आहे?\",\"options\":[\"केवळ अमाप संपत्ती\",\"चित्र, शिल्पे, इमारती, पूल आणि संशोधन\",\"केवळ काही जुनी कपडे\",\"केवळ लष्करी शस्त्रे\"],\"answer\":1,\"explain\":\"उताऱ्याच्या शेवटी लिओनार्दोने चित्र, शिल्पे, इमारती, पूल आणि संशोधन वारसा म्हणून ठेवल्याचे सांगितले आहे.\",\"topic\":\"अष्टपैलू व्यक्तिमत्त्व आणि वारसा\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"लिओनार्दो दा व्हिंची यांचा मृत्यू कोणत्या तारखेला झाला?\",\"options\":[\"२ मे, १५१९\",\"२ जून, १५१९\",\"२ मे, १६१९\",\"२ एप्रिल, १५१९\"],\"answer\":0,\"explain\":\"उताऱ्यात मृत्यूची तारीख २ मे, १५१९ अशी दिली आहे.\",\"topic\":\"अष्टपैलू व्यक्तिमत्त्व आणि वारसा\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"लिओनार्दोच्या व्यक्तिमत्त्वाच्या अभ्यासावरून कोणता निष्कर्ष निघतो?\",\"options\":[\"तो केवळ विज्ञानात रस घेत असे.\",\"तो कला आणि विज्ञान या दोन्ही शाखांत संचार करणारा होता.\",\"त्याला गणिताची अजिबात आवड नव्हती.\",\"तो केवळ एक लेखक होता.\"],\"answer\":1,\"explain\":\"उताऱ्यात लिओनार्दोला कला आणि विज्ञान या दोन्ही शाखांत संचार करणारा म्हटले आहे.\",\"topic\":\"अष्टपैलू व्यक्तिमत्त्व आणि वारसा\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"लिओनार्दो दा व्हिंची कोणत्याही कामाला सुरुवात करण्यापूर्वी कोणती महत्त्वाची गोष्ट करत असत?\",\"options\":[\"कामाची घाई करत असत\",\"गोष्ट नीट समजून घेतल्याशिवाय सुरुवात करत नसत\",\"दुसऱ्यांच्या सल्ल्याने काम करत असत\",\"फक्त चित्र काढण्यावर लक्ष देत असत\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे, लिओनार्दो प्रत्येक गोष्टीच्या मुळाशी जाऊन ती नीट समजून घेतल्याशिवाय कामाला सुरुवात करत नसत.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"व्यंजनसंधीची व्याख्या खालीलपैकी कोणती आहे?\",\"options\":[\"दोन स्वर एकमेकांशेजारी येणे\",\"दोन विसर्ग एकमेकांशेजारी येणे\",\"एकमेकांशेजारी येणाऱ्या वर्णांपैकी दोन्ही व्यंजने किंवा पहिला वर्ण व्यंजन व दुसरा स्वर असणे\",\"पहिला वर्ण स्वर आणि दुसरा वर्ण व्यंजन असणे\"],\"answer\":2,\"explain\":\"व्यंजनसंधीमध्ये दोन्ही व्यंजने किंवा पहिले व्यंजन व दुसरा स्वर एकत्र येतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'सत् + जन = सज्जन\' या उदाहरणात कोणत्या वर्णांचा संधी झाला आहे?\",\"options\":[\"त् + ज\",\"स + ज\",\"त + न\",\"स + न\"],\"answer\":0,\"explain\":\"सत् मधील \'त्\' आणि जन मधील \'ज\' एकत्र येऊन \'ज्ज\' हा संधी तयार झाला आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"प्रथम-व्यंजनसंधीच्या नियमानुसार, अनुनासिकाशिवाय कोणत्याही व्यंजनापुढे कठोर व्यंजन आल्यास पहिल्या व्यंजनाच्या जागी काय येते?\",\"options\":[\"त्याच वर्गातील तिसरे व्यंजन\",\"त्याच वर्गातील अनुनासिक\",\"त्याच वर्गातील पहिले कठोर व्यंजन\",\"त्याच वर्गातील मृदू व्यंजन\"],\"answer\":2,\"explain\":\"प्रथम-व्यंजनसंधीच्या नियमानुसार, पहिल्या व्यंजनाच्या जागी त्याच्याच वर्गातील पहिले कठोर व्यंजन येते.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'वाग् + पति = वाक्पती\' या संधीत \'ग्\' या व्यंजनाचे रूपांतर \'क्\' मध्ये होण्याचे कारण काय?\",\"options\":[\"पुढे स्वर आल्यामुळे\",\"पुढे कठोर व्यंजन आल्यामुळे\",\"पुढे अनुनासिक आल्यामुळे\",\"पुढे मृदू व्यंजन आल्यामुळे\"],\"answer\":1,\"explain\":\"प्रथम-व्यंजनसंधीच्या नियमानुसार, \'ग्\' पुढे \'प\' हे कठोर व्यंजन आल्यामुळे \'ग्\' चा \'क्\' झाला आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"तृतीय-व्यंजनसंधीमध्ये कठोर व्यंजनापुढे स्वर किंवा मृदू व्यंजन आल्यास, त्या कठोर व्यंजनाच्या जागी कोणते व्यंजन येते?\",\"options\":[\"त्याच वर्गातील पहिले व्यंजन\",\"त्याच वर्गातील पाचवे व्यंजन\",\"त्याच वर्गातील तिसरे व्यंजन\",\"त्याच वर्गातील दुसरे व्यंजन\"],\"answer\":2,\"explain\":\"तृतीय-व्यंजनसंधीच्या नियमानुसार, कठोर व्यंजनाच्या जागी त्याच वर्गातील तिसरे व्यंजन येते.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'अप् + ज = अब्ज\' या उदाहरणात \'प्\' च्या जागी \'ब्\' का आले आहे?\",\"options\":[\"कारण \'ज\' हे कठोर व्यंजन आहे\",\"कारण \'ज\' हे मृदू व्यंजन आहे\",\"कारण \'ज\' हे अनुनासिक आहे\",\"कारण \'ज\' हा स्वर आहे\"],\"answer\":1,\"explain\":\"तृतीय-व्यंजनसंधीच्या नियमानुसार, \'प्\' पुढे \'ज\' हे मृदू व्यंजन आल्यामुळे \'प्\' च्या जागी \'ब्\' (तिसरे व्यंजन) आले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"अनुनासिक संधी होण्यासाठी पहिल्या पाच वर्गातील व्यंजनापुढे काय येणे आवश्यक आहे?\",\"options\":[\"स्वर\",\"कठोर व्यंजन\",\"अनुनासिक\",\"मृदू व्यंजन\"],\"answer\":2,\"explain\":\"नियमानुसार, कोणत्याही व्यंजनापुढे अनुनासिक आल्यास अनुनासिक संधी होतो.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'षट् + मास = षण्मास\' या संधीत \'ट्\' बद्दल \'ण्\' का आले आहे?\",\"options\":[\"कारण \'म\' हे अनुनासिक आहे\",\"कारण \'म\' हे कठोर व्यंजन आहे\",\"कारण \'म\' हा स्वर आहे\",\"कारण \'म\' हे मृदू व्यंजन आहे\"],\"answer\":0,\"explain\":\"अनुनासिक संधीच्या नियमानुसार, \'ट्\' पुढे \'म\' हे अनुनासिक आल्यामुळे \'ट्\' बद्दल \'ण्\' हे अनुनासिक आले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"\'सम् + आचार = समाचार\' या उदाहरणात \'म्\' चे काय झाले आहे?\",\"options\":[\"त्याचा अनुस्वार झाला\",\"तो लोप पावला\",\"पुढील स्वर \'म्\' मध्ये मिसळला\",\"त्याचे कठोर व्यंजन झाले\"],\"answer\":2,\"explain\":\"नियमानुसार, \'म्\' पुढे स्वर आल्यास तो स्वर मागील \'म\' मध्ये मिसळतो.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीतील तक्त्यानुसार, \'व्यंजन + स्वर\' एकत्र येऊन होणाऱ्या संधीचे अचूक उदाहरण कोणते?\",\"options\":[\"सत् + जन = सज्जन\",\"चित् + आनंद = चिदानंद\",\"विपद् + काल = विपत्काल\",\"वाक् + निश्चय = वाङ्निश्चय\"],\"answer\":1,\"explain\":\"तक्त्यात \'चित् + आनंद = चिदानंद\' हे उदाहरण \'व्यंजन + स्वर\' (त् + आ = दा) या गटात दिले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"54\\/053_102.jpg\"},{\"q\":\"दिलेल्या आकृतीतील तक्त्यामध्ये \'अनुस्वार किंवा शीर्षबिंदू\' या नियमासाठी कोणते उदाहरण दिले आहे?\",\"options\":[\"वाक् + ईश्वरी = वागीश्वरी\",\"षट् + मास = षण्मास\",\"सम् + गती = संगती\",\"वाग् + पति = वाक्पती\"],\"answer\":2,\"explain\":\"तक्त्याच्या शेवटच्या भागात \'सम् + गती = संगती\' हे अनुस्वाराचे उदाहरण दिले आहे.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"54\\/053_102.jpg\"},{\"q\":\"खालीलपैकी कठोर व्यंजनांचा गट ओळखा.\",\"options\":[\"ग, घ, ज, झ\",\"ड, ढ, द, ध\",\"क, ख, च, छ\",\"ब, भ, ग, घ\"],\"answer\":2,\"explain\":\"उताऱ्यातील टीपेनुसार क, ख, च, छ ही कठोर व्यंजने आहेत.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"ज्या व्यंजनांचा उच्चार तुलनेने सौम्य असतो, त्यांना काय म्हणतात?\",\"options\":[\"कठोर व्यंजने\",\"मृदू व्यंजने\",\"अनुनासिके\",\"स्वर\"],\"answer\":1,\"explain\":\"उताऱ्यातील टीपेनुसार ज्यांचा उच्चार सौम्य असतो त्यांना मृदू व्यंजने म्हणतात.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'वाक् + निश्चय = वाङ्निश्चय\' या उदाहरणात \'क्\' बद्दल \'ङ्\' येण्याचे कारण काय?\",\"options\":[\"पुढील वर्ण \'न\' हे अनुनासिक आहे\",\"पुढील वर्ण \'न\' हा स्वर आहे\",\"पुढील वर्ण \'न\' हे कठोर व्यंजन आहे\",\"पुढील वर्ण \'न\' हे मृदू व्यंजन आहे\"],\"answer\":0,\"explain\":\"अनुनासिक संधीच्या नियमानुसार, व्यंजनापुढे अनुनासिक आल्यास पहिल्या व्यंजनाबद्दल त्याच्याच वर्गातील अनुनासिक येते.\",\"topic\":\"आपण समजून घेऊया\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"दैनंदिन व्यवहारात घडणाऱ्या घटनांची माहिती आपल्याला कोणत्या माध्यमातून मिळते?\",\"options\":[\"केवळ पुस्तकांतून\",\"वृत्तपत्रे, टी. व्ही., रेडिओ\",\"केवळ मित्रांकडून\",\"केवळ जाहिरातींमधून\"],\"answer\":1,\"explain\":\"उताऱ्यात बातमीची माध्यमे म्हणून वृत्तपत्रे, टी. व्ही. आणि रेडिओ यांचा उल्लेख आहे.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"बातमी लेखनासाठी खालीलपैकी कोणता गुण आवश्यक आहे?\",\"options\":[\"चित्रकला कौशल्य\",\"भाषेचे उत्तम ज्ञान\",\"संगीत ज्ञान\",\"अभिनय कौशल्य\"],\"answer\":1,\"explain\":\"बातमी लेखनासाठी आवश्यक गुणांमध्ये \'भाषेचे उत्तम ज्ञान\' हा एक महत्त्वाचा गुण आहे.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"बातमीच्या माध्यमातून आपल्याला कोणत्या काळातील घटनांची माहिती मिळते?\",\"options\":[\"केवळ भूतकाळातील\",\"केवळ भविष्यकाळातील\",\"घडलेल्या, घडत असलेल्या आणि घडणाऱ्या\",\"केवळ काल्पनिक\"],\"answer\":2,\"explain\":\"बातमीमुळे घडलेल्या, घडत असलेल्या आणि घडणाऱ्या विविध घटनांची माहिती मिळते.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"बातमी लेखनातील वाक्यरचना कशी असावी असे उताऱ्यात म्हटले आहे?\",\"options\":[\"अलंकारिक आणि कठीण\",\"खूप मोठी आणि गुंतागुंतीची\",\"सोपी आणि सुटसुटीत\",\"केवळ एका शब्दाची\"],\"answer\":2,\"explain\":\"बातमी लेखनासाठी सोपी आणि सुटसुटीत वाक्यरचना असणे आवश्यक आहे.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"एखाद्या नवीन शोध लावल्याची बातमी कोणत्या क्षेत्रात येईल?\",\"options\":[\"सांस्कृतिक\",\"राजकीय\",\"वैज्ञानिक\",\"सामाजिक\"],\"answer\":2,\"explain\":\"विज्ञानाशी संबंधित घटना \'वैज्ञानिक\' या बातमीच्या क्षेत्रात येतात.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"क्रिकेट सामन्याचा निकाल ही बातमी कोणत्या क्षेत्राशी संबंधित आहे?\",\"options\":[\"क्रीडा\",\"राजकीय\",\"वैज्ञानिक\",\"सांस्कृतिक\"],\"answer\":0,\"explain\":\"खेळांशी संबंधित बातम्या \'क्रीडा\' या क्षेत्रात मोडतात.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"बातमी लेखनासाठी \'चौफेर वाचन\' का आवश्यक असावे?\",\"options\":[\"केवळ वेळ घालवण्यासाठी\",\"विविध विषयांची सविस्तर माहिती मिळवण्यासाठी\",\"केवळ मनोरंजन करण्यासाठी\",\"पुस्तके विकण्यासाठी\"],\"answer\":1,\"explain\":\"चौफेर वाचनामुळे लेखकाला विविध विषयांचे ज्ञान मिळते, जे बातमी लेखनासाठी गरजेचे असते.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता घटक बातमी लेखनासाठी आवश्यक गुणांमध्ये येत नाही?\",\"options\":[\"व्याकरणाची जाण\",\"लेखनकौशल्य\",\"चौफेर वाचन\",\"केवळ कल्पनाशक्ती\"],\"answer\":3,\"explain\":\"उताऱ्यात दिलेल्या पाच गुणांमध्ये कल्पनाशक्तीचा उल्लेख नाही; तिथे वास्तव घटनांना महत्त्व असते.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"बातमी लेखनासाठी \'व्याकरणाची जाण\' असणे का महत्त्वाचे आहे?\",\"options\":[\"बातमी अचूक आणि स्पष्ट होण्यासाठी\",\"बातमी मोठी करण्यासाठी\",\"बातमी गुंतागुंतीची करण्यासाठी\",\"बातमी लपवण्यासाठी\"],\"answer\":0,\"explain\":\"व्याकरणाच्या जाणिवेमुळे बातमीतील अर्थ स्पष्ट होतो आणि ती भाषादृष्ट्या अचूक होते.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"उताऱ्यात बातमीची एकूण किती क्षेत्रे दिली आहेत?\",\"options\":[\"चार\",\"सहा\",\"आठ\",\"दहा\"],\"answer\":1,\"explain\":\"उताऱ्यात सांस्कृतिक, क्रीडा, राजकीय, दैनंदिन घटना, वैज्ञानिक आणि सामाजिक अशी सहा क्षेत्रे दिली आहेत.\",\"topic\":\"बातमी लेखन\",\"part\":9,\"bloom\":\"remember\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (22102,54,8,'Marathi','mr','स्वामी विवेकानंदांची भारतयात्रा','[\"स्वामी विवेकानंदांची भारतयात्रा १९०५‑१९०६ मध्ये झाली आणि ती भारताच्या विविध भागांतून फिरून देशभक्ती आणि समाजसेवा यावर भर दिला.\",\"त्यांनी हिमालयापासून कन्याकुमारीपर्यंत प्रवास केला आणि दररोज सकाळी वाचन व ध्यान केले.\",\"त्यांची वाचनगती अतिशय वेगवान होती – एका तासात २०० पृष्ठे वाचणे शक्य होते.\",\"त्यांची एकाग्रता अतुलनीय होती; मन एकाग्रतेने ते ग्रंथ वाचून लगेच लक्षात ठेवू शकत होते.\",\"कन्याकुमारीच्या शिलाखंडावर तीन दिवस ध्यानस्थ बसून त्यांनी भारताच्या स्थितीवर चिंतन केले.\",\"त्यांनी तीन दिवस आणि तीन रात्री ध्यानात घालून राष्ट्रभक्ती आणि समाज सुधारणा यावर विचार केला.\",\"त्यांनी ग्रंथपालाला आव्हान दिले आणि तीन खंड वाचून परत केले, ज्याने त्यांच्या वाचनशक्तीचे दर्शन दिले.\",\"त्यांनी नावाड्यांना पैसे न घेता मदत करण्यास नकार दिला, कारण ते स्वावलंबी आणि स्वच्छंद असावेत असे मानत होते.\",\"त्यांची शिक्षण पद्धती ‘वाचनप्रेम’, ‘मनाची एकाग्रता’, ‘दृढनिश्चय’ आणि ‘निर्भयता’ या गुणांवर आधारित होती.\",\"त्यांनी ‘विसर्गसंधी’ आणि ‘विरामचिन्ह’ यांबद्दलही शिकवले आणि विद्यार्थ्यांना व्याकरणाचे नियम समजावले.\",\"त्यांनी ‘साहित्यिक’ आणि ‘तत्त्वज्ञानिक’ ग्रंथ वाचून समाजात परिवर्तन घडवायचे प्रयत्न केले.\",\"त्यांनी ‘सामाजिक सेवा’ आणि ‘स्वावलंबन’ यावर जोर दिला, ज्यामुळे भारतात स्वावलंबी समाजाची निर्मिती झाली.\",\"त्यांनी ‘शिलाखंड’ या प्रतीकात्मक स्थळी ध्यान करून ‘आत्मा’ आणि ‘भू-आत्मा’ यांचा संगम साधला.\",\"त्यांची ‘साहित्यिक’ आणि ‘भाषिक’ कौशल्ये विद्यार्थ्यांना प्रेरणा देणारी होती.\",\"त्यांनी ‘सामाजिक सुधारणा’ आणि ‘शिक्षण’ यावर लक्ष केंद्रीत केले, ज्यामुळे भारतातील शिक्षणात क्रांती आली.\",\"त्यांनी ‘वाचनप्रेम’ आणि ‘ज्ञानप्राप्ती’ यावर भर दिला, ज्यामुळे विद्यार्थ्यांना वाचनाची आवड निर्माण झाली.\",\"त्यांनी ‘सामाजिक सेवा’ आणि ‘राष्ट्रभक्ती’ यांना एकत्रित करून ‘सामाजिक सुधारणा’ साध्य केली.\",\"त्यांनी ‘वाचनप्रेम’ आणि ‘ज्ञानप्राप्ती’ यावर लक्ष केंद्रीत केले, ज्यामुळे विद्यार्थ्यांना वाचनाची आवड निर्माण झाली.\",\"त्यांनी ‘सामाजिक सेवा’ आणि ‘राष्ट्रभक्ती’ यांना एकत्रित करून ‘सामाजिक सुधारणा’ साध्य केली.\",\"त्यांनी ‘वाचनप्रेम’ आणि ‘ज्ञानप्राप्ती’ यावर लक्ष केंद्रीत केले, ज्यामुळे विद्यार्थ्यांना वाचनाची आवड निर्माण झाली.\",\"त्यांनी ‘सामाजिक सेवा’ आणि ‘राष्ट्रभक्ती’ यांना एकत्रित करून ‘सामाजिक सुधारणा’ साध्य केली.\",\"त्यांनी ‘वाचनप्रेम’ आणि ‘ज्ञानप्राप्ती’ यावर लक्ष केंद्रीत केले, ज्यामुळे विद्यार्थ्यांना वाचनाची आवड निर्माण झाली.\",\"त्यांनी ‘सामाजिक सेवा’ आणि ‘राष्ट्रभक्ती’ यांना एकत्रित करून ‘सामाजिक सुधारणा’ साध्य केली.\"]','[{\"q\":\"\'स्वामी विवेकानंदांची भारतयात्रा\' या पाठाचे लेखक कोण आहेत?\",\"options\":[\"सुनील चोकोपकर\",\"समर्थ रामदास\",\"स्वामी विवेकानंद\",\"सिद्धार्थ चोकोपकर\"],\"answer\":0,\"explain\":\"पाठाच्या सुरुवातीला दिलेल्या लेखक परिचयानुसार सुनील चोकोपकर हे या पाठाचे लेखक आहेत.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"सुनील चोकोपकर हे कोणत्या विषयाचे गाढे अभ्यासक आहेत?\",\"options\":[\"विज्ञान साहित्य\",\"संत साहित्य\",\"कथा साहित्य\",\"लोक साहित्य\"],\"answer\":1,\"explain\":\"लेखक परिचयात त्यांना \'संत साहित्याचे अभ्यासक\' असे संबोधले आहे.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"लेखक सुनील चोकोपकर यांची एकूण किती पुस्तके प्रकाशित झाली आहेत?\",\"options\":[\"तीस\",\"पन्नास\",\"चाळीस\",\"दहा\"],\"answer\":2,\"explain\":\"लेखक परिचयात त्यांची \'चाळीस पुस्तके प्रकाशित\' असल्याचे नमूद केले आहे.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणता पुरस्कार सुनील चोकोपकर यांना मिळालेला नाही?\",\"options\":[\"शिवालयी पुरस्कार\",\"कुंजलता पुरस्कार\",\"समर्थ रामदास पुरस्कार\",\"महाराष्ट्र भूषण पुरस्कार\"],\"answer\":3,\"explain\":\"परिच्छेदानुसार त्यांना शिवालयी, कुंजलता आणि समर्थ रामदास पुरस्कार मिळाले आहेत, पण महाराष्ट्र भूषणचा उल्लेख नाही.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"प्रस्तुत पाठात स्वामी विवेकानंदांच्या कोणत्या कौशल्याचे वर्णन आले आहे?\",\"options\":[\"गायन कला व वादन\",\"चित्रकला व हस्तकला\",\"वाचनाची गती व आकलनशक्ती\",\"खेळ व व्यायाम\"],\"answer\":2,\"explain\":\"पाठाच्या प्रस्तावनेत स्वामीजींच्या वाचनाची गती आणि आकलनशक्ती याविषयी वर्णन असल्याचे म्हटले आहे.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"स्वामी विवेकानंद भारतयात्रेच्या समारोप प्रसंगी कोठे ध्यानस्थ बसले होते?\",\"options\":[\"हिमालय पर्वतावर\",\"कन्याकुमारी येथील शिलाखंडावर\",\"रामेश्वरमच्या मंदिरात\",\"गंगेच्या काठी\"],\"answer\":1,\"explain\":\"प्रस्तावनेनुसार स्वामीजी कन्याकुमारी येथील शिलाखंडावर ध्यानस्थ बसले होते.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"स्वामीजींनी शिलाखंडावर सलग किती काळ चिंतन केले?\",\"options\":[\"दोन दिवस व दोन रात्री\",\"पाच दिवस व पाच रात्री\",\"तीन दिवस व तीन रात्री\",\"एक दिवस व एक रात्र\"],\"answer\":2,\"explain\":\"पाठात स्पष्ट उल्लेख आहे की त्यांनी सलग तीन दिवस तीन रात्री चिंतन केले.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"स्वामीजींनी शिलाखंडावर बसून प्रामुख्याने कशाचे चिंतन केले?\",\"options\":[\"स्वतःच्या भविष्याचे\",\"भारतभूमीच्या सद्यस्थितीचे\",\"परदेश प्रवासाचे\",\"ग्रंथ लेखनाचे\"],\"answer\":1,\"explain\":\"स्वामीजींनी भारतभूमीच्या सद्यस्थितीचे आणि तिच्या परिस्थितीचे परिपूर्ण घडवून आणण्याविषयी चिंतन केले.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"कन्याकुमारी येथील प्रसंगातून स्वामीजींचा कोणता गुण प्रकर्षाने दिसून येतो?\",\"options\":[\"धनसंपत्तीची ओढ\",\"केवळ स्वतःचा विकास\",\"राष्ट्रभक्ती आणि जनसामान्यांच्या परिवर्तनाची तळमळ\",\"केवळ निसर्गप्रेम\"],\"answer\":2,\"explain\":\"या प्रसंगातून स्वामीजींची राष्ट्रभक्ती आणि जनसामान्यांच्या जीवनात परिवर्तन घडवून आणण्याची आंतरिक तळमळ दिसून येते.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"\'स्वामी विवेकानंदांची भारतयात्रा\' हा पाठ कोणत्या पुस्तकातून घेतला आहे?\",\"options\":[\"संस्कारांचे मोती\",\"श्री दासबोध विवरण\",\"मानवतेचा महापुरूष : स्वामी विवेकानंद\",\"दत्त संत चरित्र\"],\"answer\":2,\"explain\":\"प्रस्तावनेच्या शेवटी हा पाठ \'मानवतेचा महापुरूष : स्वामी विवेकानंद\' या पुस्तकातून घेतल्याचे सांगितले आहे.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"लेखक सुनील चोकोपकर यांनी लिहिलेल्या कोणत्या पुस्तकात \'रामदास\' या नावाचा उल्लेख नाही?\",\"options\":[\"समर्थ रामदासांचे व्यवस्थापन\",\"सिद्धार्थचे श्री रामदास\",\"श्री दासबोध विवरण सच\",\"संस्कारांचे मोती\"],\"answer\":3,\"explain\":\"दिलेल्या यादीत \'संस्कारांचे मोती\' या पुस्तकाच्या नावात रामदास हा शब्द नाही.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"स्वामी विवेकानंदांच्या भारतयात्रेचा समारोप कोठे झाला असे प्रस्तावनेवरून समजते?\",\"options\":[\"मुंबई\",\"कोलकाता\",\"कन्याकुमारी\",\"दिल्ली\"],\"answer\":2,\"explain\":\"भारतयात्रेच्या समारोप प्रसंगी ते कन्याकुमारी येथे होते, असे मजकुरात नमूद आहे.\",\"topic\":\"लेखक परिचय व प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"स्वामी विवेकानंदांनी कोठून कोठपर्यंत भ्रमण केले?\",\"options\":[\"काश्मीरपासून कन्याकुमारीपर्यंत\",\"हिमालयापासून कन्याकुमारीपर्यंत\",\"पोरबंदरपासून हिमालयापर्यंत\",\"मुंबईपासून कोलकात्यापर्यंत\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट उल्लेख आहे की स्वामीजींनी हिमालयापासून कन्याकुमारीपर्यंत भ्रमण केले.\",\"topic\":\"ग्रंथपालाचा अनुभव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"स्वामी विवेकानंदांनी भारतभ्रमण का केले?\",\"options\":[\"निसर्ग सौंदर्य पाहण्यासाठी\",\"ग्रंथालयांचा शोध घेण्यासाठी\",\"देश आणि समाजाची सेवा करण्यापूर्वी तो डोळ्यांखालून घालण्यासाठी\",\"इंग्रजी भाषेचा अभ्यास करण्यासाठी\"],\"answer\":2,\"explain\":\"ज्या देशाची आणि समाजाची सेवा करायची आहे, तो एकदा डोळ्यांखालून घालण्यासाठी त्यांनी भ्रमण केले.\",\"topic\":\"ग्रंथपालाचा अनुभव\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पोरबंदरच्या वास्तव्यात स्वामीजी कोणत्या भाषेतील ग्रंथांचे खंड वाचत असत?\",\"options\":[\"मराठी\",\"संस्कृत\",\"हिंदी\",\"इंग्रजी\"],\"answer\":3,\"explain\":\"उताऱ्यात नमूद केले आहे की स्वामीजी इंग्रजी ग्रंथांचे खंड वाचत असत.\",\"topic\":\"ग्रंथपालाचा अनुभव\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"ग्रंथपालाच्या मते एक