:7,\"bloom\":\"remember\"},{\"q\":\"वसंततिलका वृत्ताचे गण खालीलपैकी कोणते आहेत?\",\"options\":[\"य-य-य-य\",\"त-भ-ज-ज-ग-ग\",\"म-स-ज-स-त-त-ग\",\"न-ज-भ-ज-ज-र\"],\"answer\":1,\"explain\":\"वसंततिलका वृत्ताचे गण \'त-भ-ज-ज-ग-ग\' असे पडतात.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'मातीत ते पसरले अति रम्य पंख\' या ओळीत कोणते वृत्त आहे?\",\"options\":[\"भुजंगप्रयात\",\"मालिनी\",\"वसंततिलका\",\"शिखरिणी\"],\"answer\":2,\"explain\":\"ही ओळ वसंततिलका वृत्ताचे उदाहरण म्हणून पाठ्यपुस्तकात दिली आहे.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"ज्या वृत्तात १४ अक्षरे असून गण \'त-भ-ज-ज-ग-ग\' असतात, त्यास काय म्हणतात?\",\"options\":[\"वसंततिलका\",\"आर्या\",\"नववधू\",\"पादाकुलक\"],\"answer\":0,\"explain\":\"दिलेली लक्षणे वसंततिलका वृत्ताची आहेत.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"\'द्वेष्यास हे गमन-मार्ग खुळावकाश\' या ओळीत यती कोणत्या अक्षरानंतर येईल?\",\"options\":[\"हे\",\"मार्ग\",\"खुळा\",\"काश\"],\"answer\":1,\"explain\":\"८ व्या अक्षरावर यती असतो, \'मार्ग\' हे ८ वे अक्षर आहे.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"\'ऐकी रसात तळी मधुगंधपाश\' या ओळीचे गण पाडल्यास योग्य क्रम कोणता असेल?\",\"options\":[\"त-भ-ज-ज-ग-ग\",\"त-त-ज-ज-ग-ग\",\"भ-भ-ज-ज-ग-ग\",\"ज-ज-त-त-ग-ग\"],\"answer\":0,\"explain\":\"वसंततिलका वृत्ताचे गण नेहमी त-भ-ज-ज-ग-ग या क्रमानेच येतात.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"वसंततिलका वृत्ताच्या गणांमधील शेवटची दोन अक्षरे कोणती असतात?\",\"options\":[\"ल-ग\",\"ग-ल\",\"ग-ग\",\"ल-ल\"],\"answer\":2,\"explain\":\"गणांच्या शेवटी दोन \'ग\' (गुरू) अक्षरे येतात.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"वसंततिलका वृत्ताच्या लक्षणांबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"यात प्रत्येक चरणात १२ अक्षरे असतात.\",\"यती प्रत्येक चरणाच्या शेवटी असतो.\",\"या वृत्ताचे गण त-भ-ज-ज-ग-ग असे आहेत.\",\"यात फक्त दोनच चरण असतात.\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील लक्षणांनुसार गण त-भ-ज-ज-ग-ग हे विधान अचूक आहे.\",\"topic\":\"(२) वसंततिलका\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"मालिनी वृत्तात एकूण किती चरण असतात?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील लक्षणांनुसार मालिनी वृत्तात एकूण चार चरण असतात.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मालिनी वृत्ताच्या प्रत्येक चरणात किती अक्षरे असतात?\",\"options\":[\"८ अक्षरे\",\"१२ अक्षरे\",\"१५ अक्षरे\",\"२० अक्षरे\"],\"answer\":2,\"explain\":\"मालिनी वृत्ताच्या प्रत्येक चरणात १५ अक्षरे असतात असे लक्षणांमध्ये दिले आहे.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"मालिनी वृत्तात यती कितव्या अक्षरावर असतो?\",\"options\":[\"४ थ्या\",\"८ व्या\",\"१२ व्या\",\"१५ व्या\"],\"answer\":1,\"explain\":\"दिलेल्या लक्षणांनुसार मालिनी वृत्तात यती ८ व्या अक्षरावर असतो.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"मालिनी वृत्ताचे गण खालीलपैकी कोणते आहेत?\",\"options\":[\"य य य य\",\"त त ज र\",\"न न म य य\",\"म स ज स त त ग\"],\"answer\":2,\"explain\":\"मालिनी वृत्ताचे गण \'न न म य य\' असे पडतात.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"\'पद्मवर्ण भ्रमा भावरी पारिजात\' या ओळीत एकूण किती अक्षरे आहेत?\",\"options\":[\"१२\",\"१४\",\"१५\",\"१६\"],\"answer\":2,\"explain\":\"मालिनी वृत्ताच्या नियमानुसार या चरणात १५ अक्षरे आहेत.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"\'न न म य य\' हे गण कोणत्या वृत्ताचे लक्षण आहे?\",\"options\":[\"भुजंगप्रयात\",\"मालिनी\",\"वसंततिलका\",\"शिखरिणी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार \'न न म य य\' हे मालिनी वृत्ताचे गण आहेत.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'अचित्त पथी चाले, पांग नेमस्त मानी-\' या ओळीचे गण पाडल्यास कोणते येतील?\",\"options\":[\"न न म य य\",\"य य य य\",\"त त ज र\",\"भ भ भ भ\"],\"answer\":0,\"explain\":\"ही ओळ मालिनी वृत्ताची असल्याने तिचे गण \'न न म य य\' असे येतील.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"मालिनी वृत्ताच्या लक्षणांनुसार ८ व्या अक्षरावर काय असते?\",\"options\":[\"गण\",\"यती\",\"चरण\",\"मात्रा\"],\"answer\":1,\"explain\":\"मालिनी वृत्ताच्या लक्षणांमध्ये \'यती ८ व्या अक्षरावर असतो\' असे स्पष्ट नमूद केले आहे.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"\'धरणि हरितवस्त्रा मालिनी साजते ही\' या उदाहरणातील ओळीत \'मालिनी\' हा शब्द काय दर्शवतो?\",\"options\":[\"एका मुलीचे नाव\",\"फुलाचे नाव\",\"वृत्ताचे नाव\",\"नदीचे नाव\"],\"answer\":2,\"explain\":\"हे उदाहरण मालिनी वृत्ताचे असल्याने येथे \'मालिनी\' हे वृत्ताचे नाव आहे.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या कवितेच्या चरणात १५ अक्षरे असतील आणि गण \'न न म य य\' असतील, तर ते कोणते वृत्त असेल?\",\"options\":[\"भुजंगप्रयात\",\"मालिनी\",\"आर्या\",\"वसंततिलका\"],\"answer\":1,\"explain\":\"१५ अक्षरे आणि \'न न म य य\' गण ही मालिनी वृत्ताची वैशिष्ट्ये आहेत.\",\"topic\":\"(३) मालिनी\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"\'गवतफुला\'साठी कवितेच्या ओळीत कोणते विशेषण वापरले आहे?\",\"options\":[\"मोठमोठ्या\",\"रंगरंगुल्या\",\"लाललाल\",\"पांढऱ्याशुभ्र\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील ओळीत \'रंगरंगुल्या, सानसानुल्या\' ही विशेषणे गवतफुलासाठी वापरली आहेत.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'आनंदी आनंद गडे\' या ओळीनुसार आनंद कोठे पसरला आहे?\",\"options\":[\"फक्त एका बाजूला\",\"वर आणि खाली\",\"चोहीकडे\",\"केवळ मनात\"],\"answer\":2,\"explain\":\"दिलेल्या ओळीत \'इकडे तिकडे चोहीकडे\' असे स्पष्ट म्हटले आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'या बालांनो, या रे या!\' या ओळीत कोणाला लवकर येण्याचे आवाहन केले आहे?\",\"options\":[\"पशूंना\",\"पक्ष्यांना\",\"मुलांना (बालांनो)\",\"वृद्धांना\"],\"answer\":2,\"explain\":\"\'बालांनो\' या शब्दाचा अर्थ मुले असा होतो, ज्यांना ओळीत बोलावले आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'एका तळ्यात होती...\' या ओळीनुसार तळ्यात कोण होते?\",\"options\":[\"मासे\",\"बदके पिले\",\"कमळाची फुले\",\"बेडूक\"],\"answer\":1,\"explain\":\"ओळीत \'एका तळ्यात होती बदके पिले सुरेख\' असा उल्लेख आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'ने मजसी ने परत मातृभूमीला\' ही हाक कोणाला मारली आहे?\",\"options\":[\"आकाशाला\",\"सागराला\",\"वाऱ्याला\",\"जमिनीला\"],\"answer\":1,\"explain\":\"ओळीत \'सागरा प्राण तळमळला\' असे म्हणून सागराला विनंती केली आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'अरे संसार संसार\' या ओळीत संसाराची तुलना कशाशी केली आहे?\",\"options\":[\"पाण्यातील माशाशी\",\"आकाशातील ढगाशी\",\"चुल्ह्यावरील तव्याशी\",\"बागेतील फुलाशी\"],\"answer\":2,\"explain\":\"ओळीत \'जसा तवा चुल्ह्यावर\' असे म्हणून संसाराची तुलना केली आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"संकटांनी छळून घेतल्यावर काय पुन्हा मिळणार नाही असे ओळीत म्हटले आहे?\",\"options\":[\"वेळ\",\"संधी\",\"मदत\",\"पैसा\"],\"answer\":1,\"explain\":\"\'संधी पुन्हा मिळणार नाही\' असे स्पष्टपणे ओळीत नमूद केले आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'घरा बांधिते तोरण\' ही कृती केव्हा केली जात आहे?\",\"options\":[\"सण असल्यामुळे\",\"पाहुणे येणार असल्यामुळे\",\"बाळ रणांगणावर चालल्यामुळे\",\"नवीन घर घेतल्यामुळे\"],\"answer\":2,\"explain\":\"\'बाळ, चाललासे रणा, घरा बांधिते तोरण\' या ओळीतून हे स्पष्ट होते.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"\'देणाऱ्याने देत जावे\' या ओळीनुसार घेणाऱ्याने काय करावे?\",\"options\":[\"विसरून जावे\",\"परत करावे\",\"घेत जावे\",\"साठवून ठेवावे\"],\"answer\":2,\"explain\":\"ओळीत \'घेणाऱ्याने घेत जावे\' असा उपदेश केला आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'या नभाने या भूमीला...\' काय द्यावे असे कवीला वाटते?\",\"options\":[\"पाणी\",\"प्रकाश\",\"दान\",\"आशीर्वाद\"],\"answer\":2,\"explain\":\"ओळीत \'या नभाने या भूमीला दान दयावे\' असे शब्द आहेत.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"\'खरा तो एकचि धर्म\' या ओळीनुसार खरा धर्म कोणता आहे?\",\"options\":[\"देवाची भक्ती करणे\",\"जगाला प्रेम अर्पावे\",\"उपवास करणे\",\"तीर्थयात्रा करणे\"],\"answer\":1,\"explain\":\"ओळीत \'जगाला प्रेम अर्पावे\' हाच खरा धर्म असल्याचे सांगितले आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"\'आई\' या शब्दाचे वर्णन करताना तिला कशाची उपमा दिली आहे?\",\"options\":[\"एक सुंदर मंदिर\",\"गजबजलेलं गाव\",\"वाहती नदी\",\"थंड सावली\"],\"answer\":1,\"explain\":\"ओळीत \'घरातल्या घरात गजबजलेलं गाव असतं\' असे आईबद्दल म्हटले आहे.\",\"topic\":\"भाषासौंदर्य\",\"part\":9,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22112,54,8,'Marathi','mr','संतवाणी','[\"संत तुकाराम (१६०८‑१६५०) हे वारकरी परंपरेतील श्रेष्ठ संतकवी होते. त्यांची अभंगं अध्यात्म, भक्ती व व्यवहार यांचा संगम आहेत.\",\"त्यांच्या अभंगात शब्दांना ‘रून’ आणि ‘शस्त्र’ असे मानले जाते – शब्द हे धन व जीवनाचे सर्वस्व आहे.\",\"संत तुकाराम म्हणतात की ‘आमच्या घरी धन शब्दरूपी रून आहे’ – शब्दांनी समाजप्रबोधन व उपदेश करता येतो.\",\"शब्दांना गौरव व पूजा करणे हे त्यांच्या तत्त्वज्ञानाचे मुख्य अंग आहे.\",\"संत सावता माळी (१२५०‑१२९५) हे नामदेबकालीन संत होते, ज्यांनी शेतात‑मळ्यात भजन‑नामस्मरण केले.\",\"त्यांचे अभंग ‘संतांची आठवण राहावी’ अशी मागणी करतात – संत हेच भक्तीचे मार्गदर्शक आहेत.\",\"संत सावता म्हणतात ‘परमेश्वराला काही मागणे नाही, फक्त संतांची संगत हवी’.\",\"संत तुकाराम व संत सावता दोघेही शब्द व संतांच्या संगतीला महत्त्व देतात.\",\"संत तुकारामच्या अभंगात ‘शब्दचि आमुच्या जीवाचें जीवन’ हे वाक्य शब्दांचे महत्त्व दर्शवते.\",\"संत सावता अभंगात ‘संतांना परमेश्वर रूप समजतात’ या विचाराचे समर्थन करतात.\",\"संत तुकारामच्या अभंगातील ‘शब्दांचीच रने’ म्हणजे शब्दांना रूनासारखे मानणे.\",\"संत तुकारामच्या ‘शब्दांचीच शस्त्रे’ म्हणजे शब्दांनी समाजाला प्रबुद्ध करणे.\",\"संत तुकारामच्या ‘शब्द वाटूं धन जनलोकां’ या ओळीचा अर्थ शब्दांनी जनतेला धन वाटणे.\",\"संत तुकारामच्या ‘शब्दांचे सामर्थ्य अफाट असते’ या विधानावर अनुभव लिहिणे अपेक्षित.\",\"संत सावता अभंगात ‘संतांची आठवण’ हे भक्तीचे मुख्य साधन आहे.\",\"संत सावता अभंगात ‘संतांची संगत’ हे परमेश्वराचे रूप मानले जाते.\",\"संत तुकाराम व संत सावता यांच्या अभंगातून शब्द व संतांच्या महत्त्वाचे शिक्षण मिळते.\",\"संत तुकारामच्या ‘शब्दांचा गौरव’ हे शब्दांना देवस्वरूप मानणे.\",\"संत सावता अभंगात ‘परमेश्वराला काही मागणे नाही’ हे भक्तीचे स्वातंत्र्य दर्शवते.\",\"संत तुकाराम व संत सावता यांच्या अभंगात ‘संतांना देव रूप’ हे भक्तीचे सर्वोच्च लक्ष्य आहे.\"]','[{\"q\":\"संत तुकाराम महाराज यांचा कालखंड कोणता आहे?\",\"options\":[\"१५०८ ते १५५०\",\"१६०८ ते १६५०\",\"१७०८ ते १७५०\",\"१८०८ ते १८५०\"],\"answer\":1,\"explain\":\"पाठातील परिचयानुसार संत तुकाराम महाराजांचा कालखंड १६०८ ते १६५० असा आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"संत तुकाराम हे कोणत्या परंपरेतील श्रेष्ठ संतकवी आहेत?\",\"options\":[\"महानुभाव परंपरा\",\"दत्त परंपरा\",\"वारकरी परंपरा\",\"नाथ परंपरा\"],\"answer\":2,\"explain\":\"संत तुकाराम हे वारकरी परंपरेतील एक श्रेष्ठ संतकवी म्हणून ओळखले जातात.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"संत तुकारामांच्या रचनांमध्ये खालीलपैकी कोणत्या गोष्टींची सांगड घातलेली दिसते?\",\"options\":[\"अध्यात्म, भक्ती आणि व्यवहार\",\"राजकारण, समाजकारण आणि भक्ती\",\"केवळ अध्यात्म आणि योग\",\"केवळ व्यवहार आणि व्यापार\"],\"answer\":0,\"explain\":\"त्यांच्या रचनांमध्ये अध्यात्म, भक्ती आणि व्यवहार यांची सांगड घातलेली दिसते.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"संत तुकारामांनी आपल्या अभंगांतून कशाचा परखड समाचार घेतला आहे?\",\"options\":[\"निसर्ग आणि प्राणी\",\"ढोंग, दैववाद आणि अहंकारी वृत्ती\",\"केवळ गरिबी आणि भूक\",\"परकीय आक्रमणे\"],\"answer\":1,\"explain\":\"ढोंग, दैववाद, अहंकारी वृत्ती आणि दुराचार यांचा त्यांनी परखड समाचार घेतला आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"आदर्श प्रापंचिक जीवन कसे जगावे, यासाठी संत तुकारामांनी कोणती मूल्ये स्वीकारण्यास सांगितले आहे?\",\"options\":[\"संपत्ती आणि सत्ता\",\"केवळ कर्मकांड\",\"प्रेम, नैतिकता, करुणा व सर्वांमध्ये ईश्वराचे अस्तित्व\",\"अहंकार आणि स्वार्थ\"],\"answer\":2,\"explain\":\"प्रेम, नैतिकता, करुणा व सर्वांमध्ये ईश्वराचे अस्तित्व ही मूल्ये स्वीकारून आदर्श जीवन जगण्याचा उपदेश त्यांनी केला आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"संत तुकारामांच्या अभंगातील ओळींना कशाचे मोल प्राप्त झाले आहे?\",\"options\":[\"कथांचे\",\"सुभाषिताचे\",\"इतिहासाचे\",\"केवळ गाण्यांचे\"],\"answer\":1,\"explain\":\"त्यांच्या अभंगातील ओळींना सुभाषिताचे (सुविचार) मोल प्राप्त झाले आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"प्रस्तुत अभंगात संत तुकाराम महाराजांनी कशाचे महत्त्व विविध उदाहरणे देऊन पटवून दिले आहे?\",\"options\":[\"पैशांचे महत्त्व\",\"शब्दांचे महत्त्व\",\"शस्त्रांचे महत्त्व\",\"विद्येचे महत्त्व\"],\"answer\":1,\"explain\":\"प्रस्तुत अभंगात शब्दांचे महत्त्व विविध उदाहरणे देऊन पटवून दिलेले आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"एखाद्या व्यक्तीने \'दैववादावर\' विसंबून राहण्याऐवजी प्रयत्न करावेत, हा विचार तुकारामांच्या कोणत्या कृतीतून स्पष्ट होतो?\",\"options\":[\"केवळ भक्ती करणे\",\"दैववादाचा परखड समाचार घेणे\",\"केवळ अध्यात्म सांगणे\",\"सुभाषिते लिहिणे\"],\"answer\":1,\"explain\":\"दैववादाचा परखड समाचार घेणे म्हणजे नशिबावर अवलंबून राहण्याच्या वृत्तीला विरोध करणे होय.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"संत तुकारामांच्या उपदेशाचा मुख्य उद्देश काय आहे?\",\"options\":[\"केवळ संन्यास घेण्यास सांगणे\",\"आदर्श प्रापंचिक जीवन कसे जगावे हे शिकवणे\",\"लोकांना घाबरवणे\",\"केवळ कविता करणे\"],\"answer\":1,\"explain\":\"आदर्श प्रापंचिक जीवन कसे जगावे, याचा उपदेश करणे हा त्यांच्या अभंगांचा उद्देश आहे.\",\"topic\":\"संत तुकाराम - परिचय\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"परिच्छेदानुसार, संत तुकाराम महाराज \'दुराचाराचा\' समाचार घेतात, याचा अर्थ काय?\",\"options\":[\"ते वाईट वर्तणुकीवर टीका करतात\",\"ते वाईट वर्तणुकीचे समर्थन करतात\",\"ते केवळ शब्दांचा वापर करतात\",\"ते दुराचाराकडे दुर्लक्ष करतात\"],\"answer\":0,\"explain\":\"\'परखड समाचार घेणे\' म्हणजे चुकीच्या गोष्टींवर किंवा वाईट वर्तणुकीवर (दुराचारावर) क