,\"options\":[\"केवळ प्रोटॉन\",\"प्रोटॉन आणि इलेक्ट्रॉन\",\"प्रोटॉन आणि न्यूट्रॉन\",\"न्यूट्रॉन आणि इलेक्ट्रॉन\"],\"answer\":2,\"explain\":\"अणूच्या केंद्रकात धनप्रभारित प्रोटॉन व विद्युतप्रभार नसलेले न्यूट्रॉन असतात.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"मूलद्रव्याचा अणुअंक (Atomic Number) दर्शवण्यासाठी कोणती संज्ञा वापरली जाते?\",\"options\":[\"N\",\"A\",\"Z\",\"e\"],\"answer\":2,\"explain\":\"अणूच्या केंद्रकातील प्रोटॉनसंख्या म्हणजे अणुअंक असून तो \'Z\' ह्या संज्ञेने दर्शवतात.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"अणू विद्युतदृष्ट्या उदासीन का असतो?\",\"options\":[\"कारण त्यात न्यूट्रॉन नसतात\",\"प्रोटॉन आणि इलेक्ट्रॉनची संख्या समान असते\",\"केंद्रकावर कोणताही प्रभार नसतो\",\"इलेक्ट्रॉनचे वस्तुमान नगण्य असते\"],\"answer\":1,\"explain\":\"इलेक्ट्रॉनची संख्या प्रोटॉनसंख्येइतकीच असल्याने विद्युतप्रभाराचे संतुलन होऊन अणू उदासीन असतो.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर एका मूलद्रव्याचा अणुअंक (Z) ११ असेल, तर त्या अणूमध्ये किती इलेक्ट्रॉन असतील?\",\"options\":[\"१\",\"११\",\"२२\",\"०\"],\"answer\":1,\"explain\":\"अणूकेंद्रकाबाहेरील इलेक्ट्रॉनची संख्या केंद्रकातील प्रोटॉनसंख्येइतकीच (Z) असते.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"एका प्रोटॉनवर असणाऱ्या +1e प्रभाराचे परिमाण किती असते?\",\"options\":[\"१.६ × १०⁻¹⁹ कुलंब\",\"१.६६ × १०⁻²⁷ कुलंब\",\"९.१ × १०⁻³¹ कुलंब\",\"१.६ × १०⁻२७ कुलंब\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार, 1e = 1.6 × 10⁻¹⁹ कुलंब इतका प्रभार असतो.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"खालीलपैकी कोणत्या मूलद्रव्याच्या अणूकेंद्रकात न्यूट्रॉन नसतात?\",\"options\":[\"हेलियम\",\"कार्बन\",\"हायड्रोजन\",\"ऑक्सिजन\"],\"answer\":2,\"explain\":\"1u वस्तुमान असलेला हायड्रोजनचा अपवाद वगळता सर्व मूलद्रव्यांच्या केंद्रकात न्यूट्रॉन असतात.\",\"topic\":\"अणूची संरचना\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"इलेक्ट्रॉनचे वस्तुमान हायड्रोजन अणूच्या वस्तुमानापेक्षा सुमारे किती पटी