चऱ्याचे खतात रूपांतर न करता तो चुकीच्या पद्धतीने फेकून दिल्यास काय परिणाम होतो?\",\"options\":[\"हवा शुद्ध होते\",\"जमीन सुपीक होते\",\"हानिकारक रोगजंतूंची वाढ होते\",\"पाणी स्वच्छ होते\"],\"answer\":2,\"explain\":\"ओला कचरा कुजल्यामुळे त्यात हानिकारक रोगजंतू वाढतात आणि पाणी प्रदूषण होते.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"कीटकनाशके आणि तणनाशकांच्या फवारणीमुळे प्रामुख्याने कोणते प्रदूषण घडून येते?\",\"options\":[\"केवळ मृदा प्रदूषण\",\"केवळ जल प्रदूषण\",\"हवा प्रदूषण\",\"ध्वनी प्रदूषण\"],\"answer\":2,\"explain\":\"फवारणीमुळे रसायने हवेत मिसळतात, ज्यामुळे हवा प्रदूषण होते.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"मृदा प्रदूषणाचा आणि हवा प्रदूषणाचा संबंध खालीलपैकी कोणत्या क्रियेमुळे येतो?\",\"options\":[\"पाणी गाळल्यामुळे\",\"विष्ठेतून बाहेर पडणारे वायू हवेत मिसळल्यामुळे\",\"झाडे लावल्यामुळे\",\"मातीची धूप थांबवल्यामुळे\"],\"answer\":1,\"explain\":\"मलमूत्र व विष्ठा मातीत राहिल्यास त्यातून वायू बाहेर पडतात व दुर्गंधी सुटते, ज्यामुळे हवा प्रदूषण होते.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"शेतीसाठी रासायनिक खतांचा अतिवापर केल्यास काय घडते?\",\"options\":[\"हवा शुद्ध होते\",\"ही रसायने पाण्यात मिसळून पाणी प्रदूषण होते\",\"जमिनीची उत्पादकता कायमची वाढते\",\"पिकांना रोग होत नाहीत\"],\"answer\":1,\"explain\":\"रासायनिक खतांचा जास्त वापर केल्यास ती रसायने पाण्यात मिसळतात व पाणी प्रदूषण होते.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"मृदा प्रदूषण कशामुळे होते?\",\"options\":[\"केवळ नैसर्गिक कारणांमुळे\",\"केवळ मानवी कृत्यामुळे\",\"नैसर्गिकरीत्या व मानवी कृत्यामुळे\",\"केवळ चंद्राच्या गुरुत्वाकर्षणामुळे\"],\"answer\":2,\"explain\":\"मृदेच्या गुणधर्मात नैसर्गिकरीत्या व मानवी कृत्यामुळे होणारे बदल म्हणजे मृदा प्रदूषण.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"अन्नसाखळीतील प्रदूषकांचा प्रवासाचा योग्य मार्ग कोणता?\",\"options\":[\"मानव -> पिके -> मृदा\",\"मृदा -> पिके -> मानव\",\"हवा -> मानव -> मृदा\",\"पाणी -> मृदा -> हवा\"],\"answer\":1,\"explain\":\"प्रदूषक मृदेमधून पिके आणि पिकांमधून मानवापर्यंत पोहोचतात.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"मृदा प्रदूषणामुळे विविध रोगांचा प्रसार होण्याचे मुख्य कारण काय?\",\"options\":[\"मातीचा रंग बदलणे\",\"मातीतील जीवजंतू\",\"मातीचे तापमान वाढणे\",\"माती कोरडी पडणे\"],\"answer\":1,\"explain\":\"मृदेतील जीवजंतूमुळे विविध रोगांचा प्रसार होतो असे पाठात नमूद आहे.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता घटक मृदा प्रदूषणास कारणीभूत ठरतो?\",\"options\":[\"सेंद्रिय खतांचा वापर\",\"तणनाशकांचा वापर\",\"शुद्ध पाण्याचा वापर\",\"वृक्षारोपण\"],\"answer\":1,\"explain\":\"शेतीसाठी कीटकनाशके, रासायनिक खते आणि तणनाशकांचा वापर केल्यामुळे मृदा प्रदूषण होते.\",\"topic\":\"मृदा प्रदूषण (Soil Pollution)\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"जल प्रदूषण (प्रतिबंध व नियंत्रण) अधिनियम कोणत्या वर्षी करण्यात आला?\",\"options\":[\"1981\",\"1974\",\"1986\",\"1990\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार जल प्रदूषण (प्रतिबंध व नियंत्रण) अधिनियम 1974 मध्ये करण्यात आला.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"हवा प्रदूषण (प्रतिबंध व नियंत्रण) अधिनियम कोणत्या वर्षी लागू झाला?\",\"options\":[\"1974\",\"1986\",\"1981\",\"2000\"],\"answer\":2,\"explain\":\"हवा प्रदूषण (प्रतिबंध व नियंत्रण) अधिनियम 1981 साली करण्यात आला.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"पर्यावरण संरक्षण अधिनियम कोणत्या वर्षी अस्तित्वात आला?\",\"options\":[\"1986\",\"1974\",\"1981\",\"1992\"],\"answer\":0,\"explain\":\"पर्यावरण संरक्षण अधिनियम 1986 मध्ये करण्यात आला.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"remember\"},{\"q\":\"प्रदूषण नियंत्रणाशी संबंधित कायद्यांचे पालन होते की नाही, यावर देखरेख ठेवण्याचे काम कोण करते?\",\"options\":[\"खाजगी कंपन्या\",\"केवळ कारखाने\",\"महाराष्ट्र व केंद्रीय प्रदूषण नियंत्रण मंडळ\",\"केवळ ग्रामपंचायती\"],\"answer\":2,\"explain\":\"प्रदूषण नियंत्रण मंडळांसारख्या शासकीय संस्था कायद्यांच्या पालनावर देखरेख ठेवतात.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या घटकाबाबत प्रदूषण नियंत्रणाचे विविध कायदे व नियम अस्तित्वात आहेत?\",\"options\":[\"केवळ हवा\",\"केवळ पाणी\",\"जैव वैद्यकीय कचरा व ध्वनी प्रदूषण\",\"केवळ कारखाने\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे जैव वैद्यकीय कचरा, ध्वनी प्रदूषण इत्यादींबाबतही कायदे आहेत.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"महाराष्ट्रातील एखाद्या औद्योगिक वसाहतीने प्रदूषण नियमांचे उल्लंघन केल्यास त्यावर कोणती संस्था कारवाई करू शकते?\",\"options\":[\"महाराष्ट्र प्रदूषण नियंत्रण मंडळ\",\"शिक्षण विभाग\",\"आरोग्य विभाग\",\"कृषी विभाग\"],\"answer\":0,\"explain\":\"महाराष्ट्रात प्रदूषण नियंत्रणाची जबाबदारी महाराष्ट्र प्रदूषण नियंत्रण मंडळाची आहे.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"प्रदूषण नियंत्रण मंडळाची देखरेख खालीलपैकी कोणत्या स्थानिक स्वराज्य संस्थेवर असते?\",\"options\":[\"केवळ महानगरपालिका\",\"केवळ जिल्हा परिषद\",\"केवळ ग्रामपंचायत\",\"महानगरपालिका, जिल्हा परिषद व ग्रामपंचायत या सर्वांवर\"],\"answer\":3,\"explain\":\"उताऱ्यात महानगरपालिका, जिल्हा परिषद, पंचायत समिती आणि ग्रामपंचायत या सर्वांचा उल्लेख आहे.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या शहरात ध्वनी प्रदूषणाची समस्या वाढली असेल, तर ते कोणत्या नियमांतर्गत येते?\",\"options\":[\"हवा प्रदूषण अधिनियम 1981\",\"जल प्रदूषण अधिनियम 1974\",\"ध्वनी प्रदूषण नियंत्रण नियम\",\"केवळ घनकचरा नियम\"],\"answer\":2,\"explain\":\"ध्वनी प्रदूषण नियंत्रणाबाबत स्वतंत्र कायदे व नियम अस्तित्वात आहेत.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"apply\"},{\"q\":\"महाराष्ट्र प्रदूषण नियंत्रण मंडळ व केंद्रीय प्रदूषण नियंत्रण मंडळ या कोणत्या प्रकारच्या संस्था आहेत?\",\"options\":[\"स्वयंसेवी संस्था (NGO)\",\"शासकीय संस्था\",\"खाजगी संस्था\",\"आंतरराष्ट्रीय संस्था\"],\"answer\":1,\"explain\":\"उताऱ्यात या संस्थांचा उल्लेख \'शासकीय संस्था\' असा केला आहे.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"understand\"},{\"q\":\"भारत सरकारने प्रदूषण नियंत्रणासाठी कायदे का केले असावेत?\",\"options\":[\"केवळ कारखाने बंद करण्यासाठी\",\"प्रदूषण नियंत्रण, नियमन व ते रोखण्यासाठी\",\"केवळ दंड वसूल करण्यासाठी\",\"केवळ माहिती गोळा करण्यासाठी\"],\"answer\":1,\"explain\":\"प्रदूषण नियंत्रण, नियमन आणि ते रोखणे हा या कायद्यांचा मुख्य उद्देश आहे.\",\"topic\":\"प्रदूषण - प्रतिबंध व नियंत्रण\",\"part\":11,\"bloom\":\"analyze\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22178,58,8,'Science','mr','आपत्ती व्यवस्थापन','[\"आपत्ती म्हणजे अनपेक्षितपणे घडणारी नैसर्गिक किंवा मानवनिर्मित घटना ज्यामुळे जीव, मालमत्ता आणि पर्यावरणाला मोठी हानी पोहोचते.\",\"भूकंप म्हणजे पृथ्वीच्या पृष्ठभागावर अचानक कंपन होणे, ज्यामुळे इमारती, रस्ते व इतर संरचना हलतात.\",\"भूकंपाचे परिणाम: इमारतींचे तडे, पाण्याचे झिरपणे, नद्या व तळे बदलणे, त्सुनामी, आग, जीवित व वित्तीय हानी.\",\"भूकंपाची तीव्रता मोजण्यासाठी रिच्टर स्केल वापरतात; 5.3 पेक्षा जास्त तीव्रता ‘भूकंपरेधक’ इमारतींना आवश्यक असते.\",\"भूकंपरोधक इमारतींमध्ये विशेष बांधकाम तंत्रज्ञान व भारतीय मानक संस्था (IS) 456, 1893, 13920 कोड्स वापरले जातात.\",\"भूकंपाची पूर्वसूचना मिळवण्यासाठी सेस्मोमीटर, बेसलाइन, स्ट्रेन मीटर, टिल्ट मीटर इत्यादी आधुनिक साधने वापरली जातात.\",\"भूकंपाच्या वेळी घरात असाल तर शांत उभे राहा, टेबलखाली झाका, बाहेर असाल तर सुरक्षित जागा शोधा आणि वाहन थांबवा.\",\"भूकंपानंतर विजेचे शॉर्ट सर्किट टाळण्यासाठी मुख्य स्विच बंद करा, मेणबत्त्या व कंदील वापरू नका, बॅटरी\\/टॉर्च वापरा.\",\"भूकंपरोधक इमारतींमध्ये पायाभूत रचना, लवचिक फ्रेम व शॉक अॅब्सॉर्बर असतात, ज्यामुळे भूकंपाची ऊर्जा शोषली जाते.\",\"दरड कोसळणे (भूस्खलन) म्हणजे खडक व मातीचे उतरणे, ज्याचे कारण भूकंप, अतिवृष्टी, वृक्षतोडी व रस्ते बांधणी असते.\",\"दरड कोसळण्याचे परिणाम: पूर, नद्यांचे मार्ग बदलणे, जीव व मालमत्तेची हानी, वाहतुकीचे विघटन.\",\"शाळेच्या आपत्ती व्यवस्थापनात आपत्ती निवारण आराखडा, सुरक्षा समिती, अग्निशामक, वाहतूक व्यवस्थापन, नकाशा व रंगीत तालीम यांचा समावेश असतो.\",\"आपत्ती निवारण आराखड्यात शाळेची माहिती, इमारतीचे तपशील, मैदानाचे प्रकार, संभाव्य धोके व त्यांची उपाययोजना नोंदवली जाते.\",\"आपत्तीच्या वेळी लिफ्टचा वापर करू नका, जिना वापरा, आणि इमारतीच्या भूकंपरोधक तंत्रज्ञानाबद्दl माहिती घ्या.\",\"आपत्ती व्यवस्थापनात राष्ट्रीय भूकंपशास्त्र संस्था, भूस्खलन संशोधन संस्था व इतर सरकारी व गैर-सरकारी संस्था मदत करतात.\",\"आपत्तीच्या वेळी मदतकार्य करताना लोकांना सुरक्षित जागा द्या, आपत्कालीन संपर्क क्रमांक ठेवा आणि तात्काळ वैद्यकीय मदत घ्या.\",\"आपत्ती निवारण आराखडा तयार करताना शाळेच्या परिसरातील सर्व संभाव्य धोके ओळखा व त्यानुसार नकाशा व ताळीम योजना तयार करा.\",\"भूकंप व दरड कोसळणे यांचा संबंध: भूकंपामुळे जमिनीची हालचाल व पाण्याचे झिरपणे दरड कोसळण्यास कारणीभूत ठरते.\",\"भूकंपरोधक इमारतींची वैशिष्ट्ये: लवचिक फ्रेम, शॉक अॅब्सॉर्बर, पायाभूत रचना, कमी वजन व जड भाराचे संतुलन.\",\"भूकंपानंतर मदतकार्य करताना लोकांना तात्काळ वैद्यकीय व मानसिक सहाय्य द्या.\",\"आपत्ती व्यवस्थापनात शाळेच्या परिसरात दरड कोसळण्याची शक्यता असलेल्या ठिकाणांची ओळख व निरीक्षण करा.\"]','[{\"q\":\"भूकवचामध्ये अचानक कंपन होणे अथवा भूकवच अचानक काही क्षण हादरणे यास काय म्हणतात?\",\"options\":[\"ज्वालामुखी\",\"भूकंप\",\"चक्रीवादळ\",\"त्सुनामी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील व्याख्येनुसार भूकवचाच्या अचानक होणाऱ्या कंपनास भूकंप म्हणतात.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भूकंपामुळे हानीचे प्रमाण सर्वांत जास्त कोठे असते?\",\"options\":[\"भूकंप नाभीपाशी\",\"समुद्र किनाऱ्यावर\",\"भूकंप केंद्राच्या लगत\",\"पृथ्वीच्या ध्रुवीय भागात\"],\"answer\":2,\"explain\":\"तीव्र स्वरूपाच्या लाटा सर्वप्रथम केंद्रालगत पोहोचतात, त्यामुळे तेथे हानीचे प्रमाण सर्वाधिक असते.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"National Earthquakes Information Centre च्या निरीक्षणानुसार पृथ्वीवर प्रत्येक वर्षाला सुमारे किती भूकंप होतात?\",\"options\":[\"५,००० ते १०,०००\",\"१२,४०० ते १४,०००\",\"२०,००० ते २५,०००\",\"१,००० ते २,०००\"],\"answer\":1,\"explain\":\"दिलेल्या माहितीनुसार दरवर्षी १२,४०० ते १४,००० भूकंप होतात.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भूकंपनाभीच्या अगदी वर, भूपृष्ठावर असलेल्या बिंदूस काय म्हणतात?\",\"options\":[\"भूकंप केंद्रबिंदू\",\"भूकंप लाटा\",\"भूकंप नाभी\",\"भूस्तरीय हालचाल\"],\"answer\":0,\"explain\":\"नाभीच्या बरोबर वरच्या भूपृष्ठावरील बिंदूला भूकंपाचा केंद्रबिंदू म्हणतात.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीवर होणाऱ्या भूकंपांच्या संख्येबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"विध्वंसक भूकंपांची संख्या सौम्य भूकंपापेक्षा जास्त असते.\",\"सौम्य भूकंपांची संख्या विध्वंसक भूकंपापेक्षा खूपच जास्त असते.\",\"पृथ्वीवर दररोज भूकंप होत नाहीत.\",\"सौम्य आणि विध्वंसक भूकंपांची संख्या समान असते.\"],\"answer\":1,\"explain\":\"पृथ्वीवर विध्वंसक भूकंपापेक्षा सौम्य भूकंपाची संख्या खूपच जास्त असते.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"भूकंपामुळे जमिनीची हालचाल नेमकी कशी होते?\",\"options\":[\"फक्त गोल फिरते\",\"फक्त स्थिर राहते\",\"मागे-पुढे किंवा वर-खाली होते\",\"फक्त एकाच दिशेने सरकते\"],\"answer\":2,\"explain\":\"भूकंपामुळे भूपृष्ठाचा काही भाग मागे-पुढे किंवा वर-खाली होतो.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"जर पृथ्वीवर दरवर्षी सरासरी १३,२०० भूकंप होत असतील, तर दर महिन्याला सरासरी किती भूकंप होतात असे म्हणता येईल?\",\"options\":[\"५००\",\"८००\",\"११००\",\"१५००\"],\"answer\":2,\"explain\":\"१३२०० भागिले १२ महिने = ११०० भूकंप प्रति महिना (दिलेल्या आकडेवारीवर आधारित गणना).\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"पृथ्वी सतत कमी-अधिक प्रमाणात कंप पावत असते, या विधानाचे समर्थन करणारा पुरावा कोणता?\",\"options\":[\"भूकंप फक्त समुद्रात होतात.\",\"वर्षाला होणाऱ्या १२,४००-१४,००० भूकंपांची नोंद.\",\"भूकंप फक्त मानवनिर्मित कारणांमुळे होतात.\",\"भूकंपनाभी नेहमी भूपृष्ठावरच असते.\"],\"answer\":1,\"explain\":\"वर्षाला होणाऱ्या हजारो भूकंपांच्या नोंदीवरून पृथ्वी सतत कंप पावत असल्याचे सिद्ध होते.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीत जमिनीच्या आत ज्या ठिकाणाहून भूकंपाच्या लाटा निर्माण होतात, त्या ठिकाणाला काय म्हटले आहे?\",\"options\":[\"भूकंप केंद्रबिंदू\",\"नाभी\",\"भूस्तरीय हालचाल\",\"भूकंप लाटा\"],\"answer\":1,\"explain\":\"आकृती ९.२ मध्ये जमिनीच्या आतील लाल रंगाच्या भागाला \'नाभी\' असे दर्शवले आहे.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"understand\",\"figure_image\":\"58\\/072_102.jpg\"},{\"q\":\"दिलेल्या आकृतीत भूकंपाची नोंद घेण्यासाठी कोणत्या यंत्राचे प्रकार दाखवले आहेत?\",\"options\":[\"तापमापक यंत्र\",\"वायुदाबमापक यंत्र\",\"भूकंपमापक यंत्र\",\"वर्षामापक यंत्र\"],\"answer\":2,\"explain\":\"आकृती ९.३ मध्ये उभे आणि आडवे \'भूकंपमापक यंत्र\' दाखवले आहे.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"remember\",\"figure_image\":\"58\\/072_103.jpg\"},{\"q\":\"दिलेल्या चित्रात भूकंपाचा कोणता दृश्य परिणाम स्पष्टपणे दिसत आहे?\",\"options\":[\"पूर येणे\",\"इमारतींना तडे जाणे\",\"आग लागणे\",\"झाडे कोसळणे\"],\"answer\":1,\"explain\":\"आकृती ९.१ मध्ये भूकंपामुळे इमारतींना गेलेले मोठे तडे दाखवले आहेत.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"58\\/072_101.jpg\"},{\"q\":\"भूकंप लाटा जमिनीच्या कोणत्या भागात पसरतात?\",\"options\":[\"केवळ जमिनीच्या आत\",\"केवळ जमिनीच्या वरच्या पृष्ठभागावर\",\"जमिनीच्या आत आणि वरच्या पृष्ठभागावर सर्व दिशांनी\",\"केवळ नाभीच्या दिशेने\"],\"answer\":2,\"explain\":\"भूकंप लाटा जमिनीच्या आत आणि वरच्या पृष्ठभागावर सर्व दिशांनी पसरतात.\",\"topic\":\"प्रस्तावना व भूकंप\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"भूकंपाची नोंद घेणाऱ्या यंत्रास काय म्हणतात?\",\"options\":[\"सेस्मोग्राफ\",\"रिश्टर स्केल\",\"थर्मामीटर\",\"बॅरोमीटर\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार भूकंपाची नोंद घेणाऱ्या यंत्रास \'सेस्मोग्राफ\' किंवा \'सेस्मोमीटर\' म्हणतात.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"भूकंपाची \'तीव्रता\' मोजण्यासाठी कोणत्या एककाचा वापर केला जातो?\",\"options\":[\"मीटर\",\"रिश्टर स्केल\",\"किलोग्राम\",\"सेल्सिअस\"],\"answer\":1,\"explain\":\"भूकंपाची तीव्रता मोजण्यासाठी \'रिश्टर स्केल\' या गणिती एककाचा वापर केला जातो.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"रिश्टर स्केल हे कोणत्या प्रकारचे एकक आहे?\",\"options\":[\"भौतिक\",\"रासायनिक\",\"गणिती\",\"जैविक\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात स्पष्टपणे नमूद केले आहे की रिश्टर स्केल हे एक गणिती एकक आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जमिनीच्या आत प्रचंड उष्णतेमुळे पाण्याचे वाफेत रूपांतर होऊन ती कमकुवत भूपृष्ठातून बाहेर येण्याचा प्रयत्न करते, तेव्हा काय घडते?\",\"options\":[\"पाऊस पडतो\",\"भूकंप होतो\",\"दुष्काळ पडतो\",\"वादळ येते\"],\"answer\":1,\"explain\":\"अंतर्गत वाफ कमकुवत भूपृष्ठातून बाहेर येण्याचा प्रयत्न करते तेव्हा भूकंप होतात.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणते भूकंपाचे एक कारण आहे?\",\"options\":[\"वृक्षारोपण\",\"खाणकाम\",\"पाऊस\",\"शेती\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकात दिलेल्या कारणांच्या यादीत \'खाणकाम\' हे भूकंपाचे एक कारण आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"शहरी भागात भूकंप झाल्यास प्रामुख्याने कोणता धोका संभवतो?\",\"options\":[\"त्सुनामी\",\"आग लागणे\",\"पूर येणे\",\"वादळ\"],\"answer\":1,\"explain\":\"भूकंपाच्या परिणामांमध्ये शहरी भागात आग लागण्याचा धोका असतो असे दिले आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"समुद्रतळाशी भूकंप झाल्यास कोणत्या लाटा निर्माण होतात?\",\"options\":[\"थंड लाटा\",\"त्सुनामी लाटा\",\"साध्या लाटा\",\"स्थिर लाटा\"],\"answer\":1,\"explain\":\"समुद्रतळाशी भूकंप झाल्यास त्सुनामी लाटा निर्माण होऊन किनारपट्टीचे नुकसान होते.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"भूकंपामुळे नैसर्गिक जलस्त्रोतांवर कोणता परिणाम होतो?\",\"options\":[\"पाणी शुद्ध होते\",\"नद्या, नाले यांचे प्रवाह बदलतात\",\"पाणी आटून जाते\",\"पाणी गोठते\"],\"answer\":1,\"explain\":\"भूकंपाच्या परिणामांमुळे नद्या आणि नाले यांचे नैसर्गिक प्रवाह बदलू शकतात.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जमिनीच्या आत घेतल्या जाणाऱ्या अणुचाचण्यांमुळे खालीलपैकी काय होऊ शकते?\",\"options\":[\"भूकंप\",\"ज्वालामुखी\",\"पाऊस\",\"बर्फवृष्टी\"],\"answer\":0,\"explain\":\"अणुचाचण्या हे भूकंपाचे एक महत्त्वाचे कारण पाठ्यपुस्तकात दिले आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"भूकंपामुळे परिसंस्था धोक्यात येण्याचे मुख्य कारण काय आहे?\",\"options\":[\"रस्ते खराब होणे\",\"जैवविविधतेचे नुकसान होणे\",\"वीज जाणे\",\"पाईप लाईन फुटणे\"],\"answer\":1,\"explain\":\"जैवविविधतेचे नुकसान झाल्यामुळे परिसंस्था धोक्यात येते, हा भूकंपाचा एक परिणाम आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता भूकंपाचा \'आर्थिक\' (वित्तहानी) परिणाम आहे?\",\"options\":[\"नद्यांचे प्रवाह बदलणे\",\"लोहमार्ग उद्ध्वस्त होणे\",\"त्सुनामी येणे\",\"ज्वालामुखी होणे\"],\"answer\":1,\"explain\":\"लोहमार्ग, इमारती आणि रस्ते उद्ध्वस्त होणे हे मोठ्या प्रमाणावरील वित्तहानीचे उदाहरण आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"भूकंपामुळे डोंगराळ भागात कोणती घटना घडण्याची शक्यता असते?\",\"options\":[\"अणुचाचणी\",\"भूस्खलन\",\"खाणकाम\",\"ज्वालामुखी\"],\"answer\":1,\"explain\":\"भूकंपाच्या परिणामांमध्ये भूस्खलन (Landslide) होण्याची शक्यता असते असे नमूद केले आहे.\",\"topic\":\"भूकंपाची कारणे व परिणाम\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"भूकंप होत असताना तुम्ही शाळेत असाल, तर स्वतःच्या संरक्षणासाठी कोठे बसाल?\",\"options\":[\"शाळेच्या मैदानावर धावत जावे\",\"शाळेतील बेंचखाली बसाल\",\"शाळेच्या गच्चीवर जाल\",\"खिडकीपाशी उभे राहाल\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, शाळेत असताना बेंचखाली बसून स्वतःचे संरक्षण करावे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"भूकंप सुरू असताना तुम्ही घराबाहेर असाल, तर खालीलपैकी काय करणे योग्य ठरेल?\",\"options\":[\"उंच इमारतींच्या जवळ उभे राहणे\",\"विजेच्या तारांखाली थांबणे\",\"मोठ्या झाडाखाली आश्रय घेणे\",\"जमिनीची हालचाल थांबेपर्यंत सुरक्षित ठिकाणी थांबणे\"],\"answer\":3,\"explain\":\"बाहेर असताना जमिनीची हालचाल थांबेपर्यंत थांबणे आणि इमारती, झाडे, तारांपासून दूर राहणे आवश्यक आहे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"घरात असताना भूकंपाचे धक्के जाणवल्यास पलंगाखाली किंवा टेबलखाली का बसावे?\",\"options\":[\"थंडीपासून वाचण्यासाठी\",\"घरातील वस्तू अंगावर पडून डोक्याला इजा होऊ नये म्हणून\",\"लपून बसण्यासाठी\",\"अंधश्रद्धेमुळे\"],\"answer\":1,\"explain\":\"घरातील वस्तू पडून डोक्याला इजा होऊ शकते, म्हणून टेबल किंवा पलंगाखाली बसून संरक्षण करावे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"भूकंपग्रस्तांना मदत करताना खालीलपैकी कोणती गोष्ट पुरवणे आवश्यक नाही?\",\"options\":[\"अन्न आणि पाणी\",\"औषधे\",\"अंधश्रद्धेच्या गोष्टी\",\"कपडे\"],\"answer\":2,\"explain\":\"भूकंपग्रस्तांना अन्न, पाणी, कपडे आणि औषधे द्यावीत, पण अंधश्रद्धेच्या गोष्टी सांगू नयेत.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"भूकंपग्रस्तांच्या बाबतीत खालीलपैकी कोणती कृती चुकीची आहे?\",\"options\":[\"त्यांना सुरक्षित ठिकाणी घेऊन जाणे\",\"त्यांना मानसिक आधार देणे\",\"त्यांना एकटे सोडणे\",\"जखमींना प्रथमोपचार करणे\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकानुसार, भूकंपग्रस्तांना कधीही एकटे सोडू नये.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"भूकंपग्रस्तांना \'मानसिक आधार\' देण्याची गरज का असते?\",\"options\":[\"त्यांना घाबरवण्यासाठी\",\"त्यांना धीर देण्यासाठी आणि सावरण्यासाठी\",\"त्यांना चुकीची माहिती देण्यासाठी\",\"त्यांना एकटे पाडण्यासाठी\"],\"answer\":1,\"explain\":\"आपत्तीच्या काळात व्यक्ती मानसिकदृष्ट्या खचलेली असते, म्हणून त्यांना धीर देणे आवश्यक असते.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जखमी भूकंपग्रस्तांसाठी सर्वात पहिली महत्त्वाची कृती कोणती असावी?\",\"options\":[\"त्यांना अंधश्रद्धेच्या गोष्टी सांगणे\",\"त्यांना चुकीचे उपचार करणे\",\"त्यांना प्रथमोपचार करणे\",\"त्यांना घाबरवणे\"],\"answer\":2,\"explain\":\"जखमींना त्वरित प्रथमोपचार करणे ही प्राथमिक मदत आहे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"भूकंपग्रस्तांना मदत करताना कोणती खबरदारी घ्यावी?\",\"options\":[\"त्यांना चुकीची माहिती देऊ नये\",\"त्यांना फक्त अन्न द्यावे, पाणी देऊ नये\",\"त्यांना एकटे सोडून निघून जावे\",\"त्यांना चुकीचे उपचार करावेत\"],\"answer\":0,\"explain\":\"भूकंपग्रस्तांना चुकीची माहिती देऊन गोंधळ निर्माण करू नये.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"भूकंप सुरू असताना जमिनीची हालचाल थांबेपर्यंत बाहेर थांबणे, हे कशाचे निदर्शक आहे?\",\"options\":[\"भीतीचे\",\"सुरक्षिततेच्या नियमांचे पालन\",\"अंधश्रद्धेचे\",\"वेळ वाया घालवण्याचे\"],\"answer\":1,\"explain\":\"हालचाल थांबेपर्यंत थांबणे हा स्वतःच्या संरक्षणाचा एक महत्त्वाचा नियम आहे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"भूकंपग्रस्तांना अन्न, पाणी आणि औषधे पुरवणे ही कोणत्या प्रकारची मदत आहे?\",\"options\":[\"केवळ मानसिक मदत\",\"अनावश्यक मदत\",\"जीवनावश्यक वस्तूंची मदत\",\"चुकीची मदत\"],\"answer\":2,\"explain\":\"अन्न, पाणी, औषधे या मानवाच्या मूलभूत आणि जीवनावश्यक गरजा आहेत.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"भूकंपग्रस्तांना चुकीचे उपचार केल्यास काय होऊ शकते?\",\"options\":[\"त्यांना लवकर बरे वाटेल\",\"त्यांच्या जीवाला धोका निर्माण होऊ शकतो\",\"त्यांना मानसिक आधार मिळेल\",\"काहीही फरक पडणार नाही\"],\"answer\":1,\"explain\":\"चुकीच्या उपचारामुळे जखम किंवा आजार बळावून जीवाला धोका होऊ शकतो, म्हणून ते टाळावे.\",\"topic\":\"भूकंपग्रस्तांसाठी मदत व सुरक्षा\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"भूकंपग्रस्तांना सुरक्षित ठिकाणी हलवणे का गरजेचे असते?\",\"options\":[\"त्यांना एकटे पाडण्यासाठी\",\"पुढील