om\":\"remember\"},{\"q\":\"थर्मोकोलचे नैसर्गिक पद्धतीने विघटन होण्यासाठी किती वेळ लागतो?\",\"options\":[\"खूप कमी कालावधी\",\"काही दिवस\",\"खूप मोठा कालावधी\",\"विघटन लगेच होते\"],\"answer\":2,\"explain\":\"थर्मोकोल हा जैवअविघटनशील असल्याने त्याच्या विघटनास खूप मोठा कालावधी लागतो.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"थर्मोकोल हा पदार्थ पर्यावरणाच्या दृष्टीने खालीलपैकी कोणत्या गटात मोडतो?\",\"options\":[\"जैवविघटनशील\",\"जैवअविघटनशील\",\"पाण्यात विरघळणारा\",\"हवेपेक्षा हलका\"],\"answer\":1,\"explain\":\"थर्मोकोलचे नैसर्गिक पद्धतीने विघटन होत नाही, म्हणून तो जैवअविघटनशील आहे.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत थर्मोकोलच्या कोणत्या क्रियेमुळे पर्यावरणाचे नुकसान होताना दिसत आहे?\",\"options\":[\"पुनर्वापर\",\"उत्पादन\",\"ज्वलन\",\"साठवणूक\"],\"answer\":2,\"explain\":\"आकृती १७.४ मध्ये थर्मोकोलचे ज्वलन व त्यातून होणारे प्रदूषण दाखवले आहे.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"understand\",\"figure_image\":\"58\\/128_104.jpg\"},{\"q\":\"थर्मोकोलच्या भांड्यात ठेवलेले अन्नपदार्थ पुन्हा गरम केल्यास काय घडण्याची शक्यता असते?\",\"options\":[\"अन्नपदार्थ अधिक चविष्ट होतात\",\"स्टायरीनचा काही अंश अन्नात विरघळतो\",\"अन्न लवकर खराब होत नाही\",\"थर्मोकोलचा आकार वाढतो\"],\"answer\":1,\"explain\":\"थर्मोकोलच्या भांड्यात अन्न गरम केल्यास स्टायरीनचा अंश अन्नात विरघळण्याची शक्यता असते.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"थर्मोकोल बनविणाऱ्या कंपनीत काम करणाऱ्या व्यक्तींना खालीलपैकी कोणत्या संस्थेचे आजार संभवतात?\",\"options\":[\"केवळ हाडांचे आजार\",\"केवळ कानाचे आजार\",\"श्वसनसंस्था व पचनसंस्थेचे आजार\",\"केवळ स्मरणशक्तीचे आजार\"],\"answer\":2,\"explain\":\"स्टायरीनच्या संपर्कात राहिल्याने डोळे, श्वसनसंस्था, त्वचा आणि पचनसंस्थेचे आजार होऊ शकतात.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीवरून थर्मोकोलच्या ज्वलनामुळे हवेत काय सोडले जात असल्याचे स्पष्ट होते?\",\"options\":[\"शुद्ध हवा\",\"विषारी वायू\",\"पाण्याची वाफ\",\"ऑक्सिजन वायू\"],\"answer\":1,\"explain\":\"थर्मोकोलच्या ज्वलनामुळे विषारी वायू हवेत सोडले जातात, जे आकृतीतील धुरावरून स्पष्ट होते.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"analyze\",\"figure_image\":\"58\\/128_104.jpg\"},{\"q\":\"एखाद्या गर्भवती महिलेने थर्मोकोल कारखान्यात दीर्घकाळ काम केल्यास कोणता गंभीर धोका संभवतो?\",\"options\":[\"रक्तदाब कमी होणे\",\"गर्भपात होणे\",\"ताप येणे\",\"भूक मंदावणे\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, स्टायरीनच्या संपर्कात राहणाऱ्या गर्भवती महिलांना गर्भपात होण्याचा धोका असतो.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"थर्मोकोलच्या अतिवापराचा मानवी आरोग्यावर होणारा परिणाम आणि संबंधित घटक यांची योग्य जोडी ओळखा.\",\"options\":[\"स्टायरीन - कर्करोगजन्य घटक\",\"नायट्रोजन - डोळ्यांचे आजार\",\"ऑक्सिजन - श्वसनसंस्थेचे आजार\",\"कार्बन - पचनसंस्थेचे आजार\"],\"answer\":0,\"explain\":\"स्टायरीनमध्ये कर्करोगजन्य घटक असल्याने ते मानवी आरोग्यासाठी घातक आहे.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"समारंभांमध्ये थर्मोकोलच्या पत्रावळी व कप वापरणे आरोग्यास घातक का ठरू शकते?\",\"options\":[\"कारण त्या वजनाला हलक्या असतात\",\"कारण त्या दिसायला पांढऱ्या असतात\",\"कारण त्यातील विषारी घटक अन्नात मिसळू शकतात\",\"कारण त्या स्वस्त मिळतात\"],\"answer\":2,\"explain\":\"गरम पदार्थामुळे स्टायरीन अन्नात विरघळण्याची शक्यता असते, जे आरोग्यास घातक आहे.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"थर्मोकोलच्या विल्हेवाटीसाठी तो जाळणे हा पर्याय चुकीचा का आहे?\",\"options\":[\"कारण त्यामुळे उष्णता मिळते\",\"कारण त्यामुळे विषारी वायू हवेत पसरतात\",\"कारण त्यामुळे जागा वाचते\",\"कारण त्यामुळे प्रकाश मिळतो\"],\"answer\":1,\"explain\":\"थर्मोकोलच्या ज्वलनामुळे विषारी वायू हवेत सोडले जातात, ज्यामुळे प्रदूषण होते.\",\"topic\":\"थर्मोकोलचे दुष्परिणाम\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"सिलिका (Silica) म्हणजे रासायनिक भाषेत खालीलपैकी काय आहे?\",\"options\":[\"मॅग्नेशिअम ऑक्साईड\",\"सिलिकॉन डायॉक्साईड\",\"कॅल्शिअम कार्बोनेट\",\"सोडियम सिलिकेट\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की सिलिका म्हणजेच सिलिकॉन डायॉक्साईड (SiO₂).\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"काच हा कोणत्या प्रकारचा घनपदार्थ आहे?\",\"options\":[\"स्फटिकी आणि मऊ\",\"अस्फटिकी आणि लवचिक\",\"अस्फटिकी, टणक आणि ठिसूळ\",\"स्फटिकी, टणक आणि पारदर्शक\"],\"answer\":2,\"explain\":\"काच म्हणजे सिलिका आणि सिलिकेट यांच्या मिश्रणातून तयार झालेला अस्फटिकी, टणक पण ठिसूळ घनपदार्थ होय.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"केवळ वाळू (सिलिका) वितळण्यासाठी सुमारे किती तापमानाची गरज असते?\",\"options\":[\"850 °C\",\"1500 °C\",\"1000 °C\",\"1700 °C\"],\"answer\":3,\"explain\":\"वाळू म्हणजेच सिलिकॉन डायॉक्साईड वितळण्यास सुमारे 1700 °C तापमानाची गरज असते.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"काच निर्मितीच्या प्रक्रियेत मिश्रणाचे तापमान कमी करण्यासाठी त्यात काय मिसळले जाते?\",\"options\":[\"जास्त प्रमाणात चुनखडी\",\"टाकाऊ काचेचे तुकडे\",\"शुद्ध मॅग्नेशिअम\",\"जास्त प्रमाणात सोडा\"],\"answer\":1,\"explain\":\"कमी तापमानावर मिश्रण वितळण्यासाठी मिश्रणात टाकाऊ काचेचे तुकडे घालतात.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"मिश्रणात टाकाऊ काचेचे तुकडे घातल्यामुळे ते सुमारे किती तापमानावर वितळते?\",\"options\":[\"1700 °C\",\"1500 °C\",\"850 °C\",\"500 °C\"],\"answer\":2,\"explain\":\"टाकाऊ काचेच्या तुकड्यांमुळे मिश्रण सुमारे 850 °C तापमानावर वितळते.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"काचेला \'अस्फटिक\' (Amorphous) रूप प्राप्त होण्याचे मुख्य कारण काय आहे?\",\"options\":[\"मिश्रण खूप वेळ तापवणे\",\"मॅग्नेशिअम ऑक्साईडचा वापर करणे\",\"मिश्रण एकदम थंड करणे\",\"वाळूचा वापर करणे\"],\"answer\":2,\"explain\":\"मिश्रण एकदम थंड केल्याने ते स्फटिक रूप घेत नाहीत, तर अस्फटिक रूप प्राप्त होते.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"काच बनवण्यासाठी खालीलपैकी कोणत्या घटकांचा संच वापरला जातो?\",\"options\":[\"वाळू, सोडा, चुनखडी, मॅग्नेशिअम ऑक्साईड\",\"वाळू, मीठ, चुनखडी, लोह\",\"सिलिका, तांबे, सोडा, मॅग्नेशिअम\",\"वाळू, सोडा, पोटॅशिअम, चुनखडी\"],\"answer\":0,\"explain\":\"काच बनविण्यासाठी वाळू, सोडा, चुनखडी आणि अल्प प्रमाणात मॅग्नेशिअम ऑक्साईड यांचे मिश्रण वापरतात.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"सोडा लाईम काच तयार करताना द्रवरूपातील मिश्रण किती तापमानापर्यंत तापवून मग थंड केले जाते?\",\"options\":[\"850 °C\",\"1700 °C\",\"1500 °C\",\"2000 °C\"],\"answer\":2,\"explain\":\"मिश्रणातील सर्व पदार्थ द्रवरूपात गेल्यानंतर ते 1500 °C पर्यंत तापवून एकदम थंड केले जातात.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"उताऱ्यात दिलेल्या माहितीनुसार, खालीलपैकी कोणता काचेचा प्रकार नाही?\",\"options\":[\"बोरोसिलिकेट काच\",\"अल्कली सिलिकेट काच\",\"सोडा लाईम काच\",\"लेड-क्रिस्टल काच\"],\"answer\":3,\"explain\":\"उताऱ्यात सोडा लाईम, बोरोसिलिकेट, सिलिका आणि अल्कली सिलिकेट काचेचे प्रकार दिले आहेत; लेड-क्रिस्टलचा उल्लेख नाही.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"काच निर्मितीच्या प्रक्रियेत \'एकजिनसीपणा\' येण्यासाठी कोणती कृती महत्त्वाची ठरते?\",\"options\":[\"मिश्रण सावकाश थंड करणे\",\"मिश्रण एकदम थंड करणे\",\"केवळ वाळू वापरणे\",\"तापमान 1700 °C च्या वर नेणे\"],\"answer\":1,\"explain\":\"एकदम थंड केल्याने मिश्रण स्फटिक रूप घेत नाही आणि एकजिनसी अस्फटिक रूप प्राप्त होते.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"जर काच निर्मितीमध्ये टाकाऊ काचेचे तुकडे वापरले नाहीत, तर काय परिणाम होईल?\",\"options\":[\"काच अधिक पारदर्शक होईल\",\"मिश्रण वितळण्यासाठी जास्त उष्णता (तापमान) लागेल\",\"मिश्रण लवकर वितळेल\",\"काच स्फटिकी तयार होईल\"],\"answer\":1,\"explain\":\"टाकाऊ तुकड्यांमुळे तापमान 1700 वरून 850 पर्यंत खाली येते, ते नसल्यास जास्त तापमान लागेल.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"काच निर्मितीच्या प्रक्रियेतील घटनांचा योग्य क्रम कोणता?\",\"options\":[\"तापवणे -> द्रवरूप होणे -> एकदम थंड करणे\",\"थंड करणे -> तापवणे -> द्रवरूप होणे\",\"द्रवरूप होणे -> थंड करणे -> तापवणे\",\"एकदम थंड करणे -> तापवणे -> द्रवरूप होणे\"],\"answer\":0,\"explain\":\"प्रथम मिश्रण तापवतात, ते द्रवरूपात जाते आणि शेवटी एकदम थंड केले जाते.\",\"topic\":\"काच (Glass)\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"काच तापवल्यानंतर तिच्यात कोणता बदल होतो?\",\"options\":[\"ती अधिक कडक होते\",\"ती मऊ होते\",\"ती बाष्परूपात जाते\",\"तिचा रंग बदलतो\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, काच तापवल्यानंतर मऊ होते व तिला हवा तो आकार देता येतो.\",\"topic\":\"काचेचे गुणधर्म\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"काचेची घनता प्रामुख्याने कशावर अवलंबून असते?\",\"options\":[\"काचेच्या आकारावर\",\"काचेच्या पारदर्शकतेवर\",\"काचेमधील घटकतत्त्वांवर\",\"काचेच्या तापमानावर\"],\"answer\":2,\"explain\":\"काचेची घनता तिच्यामधील घटकतत्त्वांवर अवलंबून असते असे मजकुरात नमूद आहे.\",\"topic\":\"काचेचे गुणधर्म\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"विद्युत उपकरणात काचेचा उपयोग \'विद्युत विसंवाहक\' म्हणून का केला जातो?\",\"options\":[\"काच उष्णतेची मंद वाहक आहे म्हणून\",\"काच पारदर्शक आहे म्हणून\",\"काच विजेची दुर्वाहक आहे म्हणून\",\"काच मऊ असते म्हणून\"],\"answer\":2,\"explain\":\"काच विजेची दुर्वाहक असल्याने तिचा उपयोग विद्युत विसंवाहक म्हणून करतात.\",\"topic\":\"काचेचे गुणधर्म\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"उष्ण काच जलद थंड केल्यास काय घडते?\",\"options\":[\"ती अधिक पारदर्शक होते\",\"ती तडकते किंवा फुटते\",\"ती लवचिक होते\",\"तिची घनता वाढते\"],\"answer\":1,\"explain\":\"काच उष्णतेची मंद वाहक असल्याने, तिला जलद थंड केल्यास ती तडकते किंवा फुटते.\",\"topic\":\"काचेचे गुणधर्म\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"काचेमध्ये खालीलपैकी कोणत्या पदार्थाचा अंतर्भाव झाल्यास प्रकाश मोठ्या प्रमाणात शोषला जातो?\",\"options\":[\"सोडिअम ऑक्साइड\",\"कॅल्शिअम ऑक्साइड\",\"क्रोमिअम\",\"सिलिका\"],\"answer\":2,\"explain\":\"काचेमध्ये क्रोमिअम, व्हेनेडिअम किंवा आयर्न ऑक्साइडचा अंतर्भाव झाल्यास प्रकाश शोषला जातो.\",\"topic\":\"काचेचे गुणधर्म\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"एका काचेच्या भांड्यातू