ons\":[\"लहरींचा रंग व आवाज\",\"लहरींची दिशा व वेग\",\"लहरींची लांबी व उंची\",\"लहरींचा उगम व शेवट\"],\"answer\":1,\"explain\":\"भूकंपलहरींची दिशा व वेग यांचा अभ्यास करून अंतरंगाचे अनुमान काढले जाते.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीचे अंतरंग उष्ण व प्रवाही असावे, असे अनुमान शास्त्रज्ञांनी कशावरून काढले?\",\"options\":[\"समुद्राच्या भरती-ओहोटीवरून\",\"तप्त लाव्हारस व खाणीतील वाढते तापमान यावरून\",\"वातावरणातील बदलांवरून\",\"चंद्राच्या हालचालीवरून\"],\"answer\":1,\"explain\":\"तप्त लाव्हारस आणि खाणीतील तापमान वाढ यावरून अंतरंग उष्ण व प्रवाही असल्याचे अनुमान काढले.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मानवाने भूकंपाच्या अभ्यासासाठी प्रत्यक्ष काय केले आहे?\",\"options\":[\"पृथ्वीच्या केंद्रापर्यंत प्रवास केला\",\"मोठी धरणे बांधली\",\"कृत्रिम छिद्रे पाडली\",\"पर्वत पोखरले\"],\"answer\":2,\"explain\":\"भूकंपाच्या अभ्यासासाठी मानवाने कृत्रिम छिद्रेदेखील पाडली आहेत.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर पृथ्वी पृष्ठभागाकडून केंद्राकडे थंड झाली असेल, तर खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"केंद्राकडील भाग पृष्ठभागापेक्षा जास्त गरम असेल\",\"पृष्ठभाग केंद्रापेक्षा जास्त गरम असेल\",\"दोन्ही भागांचे तापमान समान असेल\",\"केंद्राकडील भाग पूर्णपणे थंड झाला असेल\"],\"answer\":0,\"explain\":\"पृष्ठभागाकडून थंड झाल्यामुळे आतील भाग (केंद्र) अद्याप उष्ण आहे.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"ज्वालामुखीच्या उद्रेकातून लाव्हारसाव्यतिरिक्त कोणते घटक बाहेर पडतात?\",\"options\":[\"केवळ दगड आणि माती\",\"वायू आणि वाफ\",\"बर्फ आणि थंड पाणी\",\"केवळ कोळसा\"],\"answer\":1,\"explain\":\"ज्वालामुखीच्या उद्रेकातून लाव्हारस, वायू आणि वाफ इत्यादी घटक बाहेर पडतात.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीच्या अंतरंगाचे प्रत्यक्ष निरीक्षण करणे का अशक्य आहे?\",\"options\":[\"पृथ्वी खूप लहान आहे\",\"पृथ्वीच्या अंतरंगात प्रचंड उष्णता व दाब आहे\",\"पृथ्वीवर खूप पाणी आहे\",\"पृथ्वी सतत फिरत असते\"],\"answer\":1,\"explain\":\"उताऱ्यात प्रत्यक्ष निरीक्षण अशक्य असल्याचे म्हटले आहे, कारण अंतरंग उष्ण व दुर्गम आहे.\",\"topic\":\"पृथ्वीचे अंतरंग\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीची उत्पत्ती सुमारे किती कोटी वर्षांपूर्वी झाली?\",\"options\":[\"३६० कोटी\",\"४६० कोटी\",\"५६० कोटी\",\"२६० कोटी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार पृथ्वीची उत्पत्ती सुमारे ४६० कोटी वर्षांपूर्वी झाली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"पृथ्वी तिच्या प्राथमिक अवस्थेत कोणत्या रूपात होती?\",\"options\":[\"घनरूप\",\"द्रवरूप\",\"वायुरूप\",\"प्लाझ्मा\"],\"answer\":2,\"explain\":\"पृथ्वी सुरुवातीला वायुरूप अवस्थेत होती.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"पृथ्वी थंड होण्याची प्रक्रिया कोणत्या कारणामुळे घडून आली?\",\"options\":[\"उष्णता उत्सर्जन\",\"उष्णता शोषण\",\"पाऊस\",\"सूर्याचा प्रकाश\"],\"answer\":0,\"explain\":\"उष्णता उत्सर्जन प्रक्रिया होऊन पृथ्वी हळूहळू थंड होत गेली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"वायुरूप अवस्थेनंतर पृथ्वीला प्रथम कोणती अवस्था प्राप्त झाली?\",\"options\":[\"घनरूप\",\"बाष्परूप\",\"द्रवस्वरूप\",\"स्थिररूप\"],\"answer\":2,\"explain\":\"थंड होण्याच्या प्रक्रियेत पृथ्वीला प्रथम द्रवस्वरूप अवस्था प्राप्त झाली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीचा कोणता भाग सर्वात प्रथम थंड झाला?\",\"options\":[\"मध्य भाग\",\"सर्वात बाह्य भाग\",\"अंतर्गाभा\",\"दक्षिण ध्रुव\"],\"answer\":1,\"explain\":\"कालांतराने पृथ्वीचा सर्वात बाह्य भाग प्रथम थंड झाला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या बाह्य भागाला घनरूप अवस्था प्राप्त झाल्यावर त्याला काय संबोधले जाते?\",\"options\":[\"प्रावरण\",\"गाभा\",\"भूकवच\",\"वातावरण\"],\"answer\":2,\"explain\":\"पृथ्वीच्या बाह्य घनरूप भागाला भूकवच असे म्हणतात.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या मजकुरानुसार, सूर्यमालेतील बाह्य ग्रह सध्या कोणत्या अवस्थेत आहेत?\",\"options\":[\"घनरूप\",\"द्रवरूप\",\"वायुरूप\",\"बर्फाळ\"],\"answer\":2,\"explain\":\"अजूनही भूगर्भातील बाह्य ग्रह वायुरूप अवस्थेत आहेत असे मजकुरात नमूद आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"पृथ्वीच्या अवस्थांतराचा योग्य क्रम कोणता आहे?\",\"options\":[\"वायुरूप -> घनरूप -> द्रवरूप\",\"द्रवरूप -> वायुरूप -> घनरूप\",\"वायुरूप -> द्रवस्वरूप -> घनरूप\",\"घनरूप -> द्रवरूप -> वायुरूप\"],\"answer\":2,\"explain\":\"पृथ्वी प्रथम वायुरूप होती, मग द्रवस्वरूप झाली आणि शेवटी बाह्य भाग घनरूप झाला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीचा बाह्य भाग घनरूप होण्याचे मुख्य कारण काय असावे?\",\"options\":[\"तो भाग सूर्याच्या जवळ होता\",\"तो भाग प्रथम थंड झाला\",\"त्या भागावर पाणी साचले\",\"तो भाग वायुरूप नव्हता\"],\"answer\":1,\"explain\":\"सर्वात बाह्य भाग प्रथम थंड झाल्याने त्या भागाला घनरूप अवस्था प्राप्त झाली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"जर पृथ्वीची निर्मिती ४६० कोटी वर्षांपूर्वी झाली असेल, तर तिच्या थंड होण्याच्या प्रक्रियेबद्दल काय सांगता येईल?\",\"options\":[\"ती अचानक थंड झाली\",\"ती उष्णता उत्सर्जित करून हळूहळू थंड झाली\",\"ती अजूनही पूर्णपणे वायुरूप आहे\",\"ती थंड होण्यासाठी फक्त १० वर्षे लागली\"],\"answer\":1,\"explain\":\"उष्णता उत्सर्जन प्रक्रिया होऊन पृथ्वी हळूहळू थंड होत गेली.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"या कृतीसाठी कोणत्या तीन रंगांचे मातीचे गोळे घ्यायला सांगितले आहेत?\",\"options\":[\"लाल, हिरवा व निळा\",\"लाल, पिवळा व निळा\",\"पिवळा, पांढरा व निळा\",\"लाल, पिवळा व काळा\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील पहिल्या ओळीनुसार लाल, पिवळा व निळा रंगाचे गोळे घ्यायचे आहेत.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"मातीचा पृथ्वीगोल तयार करताना कोणत्या रंगाचा गोळा थोडा मोठा असावा?\",\"options\":[\"निळा\",\"पिवळा\",\"लाल\",\"हिरवा\"],\"answer\":2,\"explain\":\"कृतीमध्ये स्पष्टपणे सांगितले आहे की लाल रंगाचा गोळा थोडा मोठा असावा.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"पिवळ्या रंगाच्या गोळ्यामध्ये लाल रंगाचा गोळा भरताना कोणत्या पदार्थाचे उदाहरण दिले आहे?\",\"options\":[\"मोदक\",\"करंजी\",\"पुरणपोळी\",\"लाडू\"],\"answer\":2,\"explain\":\"ज्याप्रमाणे पुरणपोळी करताना पोळीत पुरण भरतात, तसे लाल रंगाचा गोळा भरण्यास सांगितले आहे.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"पृथ्वीगोलाप्रमाणे या प्रतिकृतीवर \'खंड\' दर्शवण्यासाठी कोणत्या रंगाचा वापर करायचा आहे?\",\"options\":[\"लाल\",\"निळा\",\"पिवळा\",\"काळा\"],\"answer\":2,\"explain\":\"पृथ्वीगोलाप्रमाणे या घनरूपावर पिवळ्या रंगाने वेगवेगळे खंड दाखवण्यास सांगितले आहे.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"मातीचा बनवलेला भूगोल मध्यभागी अर्धा कापल्यास काय दिसेल?\",\"options\":[\"केवळ निळा रंग\",\"पृथ्वीचे अंतरंग\",\"केवळ लाल रंग\",\"काहीच दिसणार नाही\"],\"answer\":1,\"explain\":\"भूगोल मध्यभागी कापल्यास पृथ्वीच्या अंतरंगाप्रमाणे विविध थर दिसतात.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"या कृतीमध्ये सर्वात बाहेरचा थर कोणत्या रंगाचा तयार होतो?\",\"options\":[\"लाल\",\"पिवळा\",\"निळा\",\"पांढरा\"],\"answer\":2,\"explain\":\"सर्वात शेवटी निळ्या रंगाचा गोळा लाटून त्यात पिवळा गोळा भरला जातो, म्हणून निळा थर सर्वात बाहेर असतो.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"जर आपण तयार केलेला पृथ्वीगोल कापला, तर केंद्राकडून पृष्ठभागाकडे रंगांचा क्रम काय असेल?\",\"options\":[\"निळा - पिवळा - लाल\",\"लाल - पिवळा - निळा\",\"पिवळा - लाल - निळा\",\"लाल - निळा - पिवळा\"],\"answer\":1,\"explain\":\"सर्वात आत लाल, त्यावर पिवळा आणि सर्वात बाहेर निळा असा थर तयार होतो.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"या प्रयोगात पिवळ्या रंगाचा वापर कोणत्या दोन गोष्टींसाठी केला आहे?\",\"options\":[\"मध्य थर आणि खंड\",\"केंद्र आणि महासागर\",\"बाहेरचा थर आणि खंड\",\"मध्य थर आणि केंद्र\"],\"answer\":0,\"explain\":\"पिवळा गोळा मधल्या थरासाठी वापरला आहे आणि पिवळ्या रंगानेच खंड दाखवले आहेत.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"मातीचा गोळा लाटून त्यात दुसरा गोळा भरल्यानंतर त्याला कोणता आकार द्यायचा आहे?\",\"options\":[\"पोळीचा आकार\",\"त्रिकोणी आकार\",\"घनरूप आकार\",\"लंबवर्तुळाकार\"],\"answer\":2,\"explain\":\"गोळा भरल्यानंतर त्याला घनरूपात आकार देण्यास सांगितले आहे.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"या संपूर्ण कृतीचा मुख्य उद्देश काय आहे?\",\"options\":[\"मातीची खेळणी बनवणे\",\"रंगांची ओळख करून घेणे\",\"पृथ्वीच्या अंतरंगाची प्रतिकृती तयार करणे\",\"नकाशा वाचन शिकणे\"],\"answer\":2,\"explain\":\"ही कृती पृथ्वीचे अंतरंग आणि त्यातील थर समजून घेण्यासाठी दिली आहे.\",\"topic\":\"करून पाहा.\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"पृथ्वीचा सर्वात वरचा घनरूप भाग कोणत्या नावाने ओळखला जातो?\",\"options\":[\"प्रावरण\",\"गाभा\",\"भूकवच\",\"खंडीय कवच\"],\"answer\":2,\"explain\":\"पाठातील माहितीनुसार, पृथ्वीचा सर्वात वरचा घनरूप भाग भूकवच म्हणून ओळखला जातो.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खंडीय कवचाला पूर्वी कोणत्या नावाने ओळखले जात असे?\",\"options\":[\"सायमा\",\"सियाल\",\"ग्रॅनाईट\",\"बेसाल्ट\"],\"answer\":1,\"explain\":\"सिलिका व ॲल्युमिनिअम यांपासून बनलेल्या खंडीय कवचाला पूर्वी सियाल म्हणत असत.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"खंडीय कवचात प्रामुख्याने कोणते खडक आढळतात?\",\"options\":[\"बेसाल्ट\",\"गॅब्रो\",\"ग्रॅनाईट\",\"चुनखडक\"],\"answer\":2,\"explain\":\"खंडीय कवचाच्या थरात प्रामुख्याने ग्रॅनाईट खडक आढळतात.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या अंतरंगाचे विभाग प्रामुख्याने कोणत्या घटकांतील बदलांच्या अनुषंगाने पडतात?\",\"options\":[\"तापमान व घनता\",\"खडक व माती\",\"पाणी व हवा\",\"जाडी व लांबी\"],\"answer\":0,\"explain\":\"भूपृष्ठापासून गाभ्याकडे येणाऱ्या तापमान आणि घनता यातील बदलांनुसार अंतरंगाचे विभाग पडतात.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"भूकवचाची सरासरी जाडी किती मानली जाते?\",\"options\":[\"१० ते १५ किमी\",\"३० ते ३५ किमी\",\"७० ते १०० किमी\",\"१५० ते २०० किमी\"],\"answer\":1,\"explain\":\"पाठात नमूद केल्याप्रमाणे भूकवचाची सरासरी जाडी ३० ते ३५ किमी मानली जाते.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"खंडीय कवच प्रामुख्याने कोणत्या दोन मूलद्रव्यांपासून बनलेले आहे?\",\"options\":[\"सिलिका व मॅग्नेशिअम\",\"लोह व मॅग्नेशिअम\",\"सिलिका व ॲल्युमिनिअम\",\"ॲल्युमिनिअम व लोह\"],\"answer\":2,\"explain\":\"खंडीय कवच सिलिका व ॲल्युमिनिअम यांपासून बनलेले आहे.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एका खडकाची घनता ३.१ ग्रॅम\\/सेमी³ आहे, तर तो खडक भूकवचाच्या कोणत्या उपविभागात आढळण्याची शक्यता जास्त आहे?\",\"options\":[\"खंडीय कवच\",\"सियाल थर\",\"महासागरीय कवच\",\"बाह्यतम कवच\"],\"answer\":2,\"explain\":\"महासागरीय कवचाची घनता २.९ ते ३.३ ग्रॅम\\/सेमी³ असते, त्यामुळे ३.१ घनतेचा खडक तिथे आढळेल.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"जर तुम्हाला भूपृष्ठाखाली बेसाल्ट आणि गॅब्रो या खडकांचा थर आढळला, तर तुम्ही कोणत्या थरात आहात?\",\"options\":[\"खंडीय कवच\",\"महासागरीय कवच\",\"सियाल\",\"प्रावरण\"],\"answer\":1,\"explain\":\"बेसाल्ट व गॅब्रो हे खडक प्रामुख्याने महासागरीय कवचात आढळतात.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"खंडीय कवच आणि महासागरीय कवच यांच्या घनतेची तुलना केल्यास कोणते विधान योग्य ठरते?\",\"options\":[\"दोन्ही थरांची घनता सारखीच असते.\",\"खंडीय कवचाची घनता महासागरीय कवचापेक्षा जास्त असते.\",\"महासागरीय कवचाची घनता खंडीय कवचापेक्षा जास्त असते.\",\"महासागरीय कवचाची घनता खंडीय कवचापेक्षा कमी असते.\"],\"answer\":2,\"explain\":\"खंडीय कवचाची घनता २.६५-२.९० आहे, तर महासागरीय कवचाची २.९-३.३ आहे, म्हणजेच महासागरीय कवचाची घनता जास्त आहे.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"भूकवचाच्या उपविभागांपैकी कोणते कवच भूपृष्ठाचे सर्वात बाह्यतम कवच मानले जाते?\",\"options\":[\"महासागरीय कवच\",\"खंडीय कवच\",\"सायमा थर\",\"प्रावरण\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार खंडीय कवच हे भूपृष्ठाचे बाह्यतम कवच आहे.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीनुसार, महासागरीय कवचाला पूर्वी कोणत्या नावाने ओळखले जात असे?\",\"options\":[\"सियाल\",\"सायमा\",\"बेसाल्ट\",\"गॅब्रो\"],\"answer\":1,\"explain\":\"आकृतीमधील मजकुरानुसार, महासागरीय कवचाला पूर्वी सायमा असे नाव होते.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"remember\",\"figure_image\":\"60\\/022_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील माहितीनुसार, महासागरीय कवचाची सरासरी जाडी किती आहे?\",\"options\":[\"३० ते ३५ किमी\",\"७० ते १०० किमी\",\"७ ते १० किमी\",\"२.९ ते ३.३ किमी\"],\"answer\":2,\"explain\":\"आकृतीमध्ये स्पष्टपणे नमूद केले आहे की या थराची सरासरी जाडी ७ ते १० किमी आहे.\",\"topic\":\"भूकवच\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"60\\/022_101.jpg\"},{\"q\":\"भूकवचाखाली असलेल्या प्रावरणाचे एकूण किती उपविभाग केले जातात?\",\"options\":[\"तीन\",\"दोन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार प्रावरणाचे उच्च प्रावरण व निम्न प्रावरण असे दोन उपविभाग केले जातात.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"ज्वालामुखीच्या उद्रेकादरम्यान बाहेर येणारा शिलारस प्रावरणाच्या कोणत्या भागात आढळतो?\",\"options\":[\"निम्न प्रावरण\",\"भूकवच\",\"उच्च प्रावरण\",\"गाभा\"],\"answer\":2,\"explain\":\"उच्च प्रावरणात शिलारस कोटी आढळतात, ज्यामधून ज्वालामुखीचा शिलारस बाहेर येतो.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"प्रावरणाच्या कोणत्या भागास \'दुर्बलावरण\' असेही म्हणतात?\",\"options\":[\"निम्न प्रावरण\",\"उच्च प्रावरण\",\"खंडीय कवच\",\"महासागरीय कवच\"],\"answer\":1,\"explain\":\"उच्च प्रावरणास दुर्बलावरण असेही म्हणतात.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"भूपृष्ठापासून सुमारे किती किमी खोलीवर प्रावरणास सुरुवात होते?\",\"options\":[\"१०० किमी\",\"२९०० किमी\",\"४२ किमी\",\"२४०० किमी\"],\"answer\":2,\"explain\":\"भूपृष्ठापासून सुमारे ४२ किमी खोलीवर प्रावरणास सुरुवात होते.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"प्रावरणातील अंतर्गत शक्तीमुळे होणाऱ्या हालचालींचा परिणाम खालीलपैकी कोणता नाही?\",\"options\":[\"पर्वत निर्मिती\",\"ज्वालामुखी\",\"भूकंप\",\"वातावरण निर्मिती\"],\"answer\":3,\"explain\":\"प्रावरणातील हालचालींमुळे पर्वत, द्रोणी, ज्वालामुखी व भूकंप होतात, पण वातावरण निर्मिती होत नाही.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"प्रावरणाची सरासरी घनता किती ग्रॅम\\/सेमी३ आहे?\",\"options\":[\"३.३\",\"४.५\",\"५.७\",\"२.९\"],\"answer\":1,\"explain\":\"प्रावरणाची सरासरी घनता ४.५ ग्रॅम\\/सेमी३ इतकी आहे.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"प्रावरणात खोलीनुसार घनतेत वाढ होण्याचे मुख्य कारण काय आहे?\",\"options\":[\"वाढता दाब\",\"कमी होणारे तापमान\",\"पाण्याची उपस्थिती\",\"हवेचा दाब\"],\"answer\":0,\"explain\":\"वाढत्या दाबामुळे प्रावरणात खोलीपरत्वे घनतेत वाढ होत जाते.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"निम्न प्रावरणाची घनता किती ग्रॅम\\/सेमी३ आहे?\",\"options\":[\"४.५\",\"३.५\",\"५.७\",\"७.५\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार निम्न प्रावरणाची घनता ५.७ ग्रॅम\\/सेमी३ आहे.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"२४०० ते २९०० किमी खोलीवर प्रावरणातील तापमान किती असावे असे अनुमान आहे?\",\"options\":[\"१०००° से. ते १५००° से.\",\"२२००° से. ते २५००° से.\",\"३०००° से. ते ३५००° से.\",\"५०००° से. ते ६०००° से.\"],\"answer\":1,\"explain\":\"या खोलीवर तापमान २२००° से. ते २५००° से. पर्यंत असावे असे अनुमान आहे.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"भूकंपाची केंद्रे प्रामुख्याने प्रावरणाच्या कोणत्या भागात आढळतात?\",\"options\":[\"निम्न प्रावरण\",\"उच्च प्रावरण\",\"बाह्य गाभा\",\"अंतर्गाभा\"],\"answer\":1,\"explain\":\"भूकंपाची केंद्रे प्रामुख्याने उच्च प्रावरणात (दुर्बलावरणात) आढळतात.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"जर प्रावरणाची सुरुवात ४२ किमीवर होत असेल आणि अंदाजित शेवट २९७० किमीवर असेल, तर प्रावरणाची एकूण जाडी किती किमी असेल?\",\"options\":[\"२९७० किमी\",\"३०१२ किमी\",\"२९२८ किमी\",\"४२ किमी\"],\"answer\":2,\"explain\":\"२९७० - ४२ = २९२८ किमी ही प्रावरणाची अंदाजित जाडी ठरते.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"प्रावरणाच्या संदर्भात खालीलपैकी कोणते विधान शास्त्रीयदृष्ट्या योग्य आहे?\",\"options\":[\"खोलीनुसार घनता कमी होत जाते\",\"निम्न प्रावरण हे उच्च प्रावरणापेक्षा जास्त प्रभावी असते\",\"खोलीनुसार घनतेत वाढ होत जाते\",\"प्रावरणात शिलारस कोटी नसतात\"],\"answer\":2,\"explain\":\"वाढत्या दाबामुळे प्रावरणात खोलीनुसार घनतेत वाढ होत जाते हे विधान योग्य आहे.\",\"topic\":\"प्रावरण\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"भूपृष्ठापासून सुमारे किती किमी खोलीच्या खाली गाभा सुरू होतो?\",\"options\":[\"२९०० किमी\",\"५१०० किमी\",\"३४७१ किमी\",\"६३७१ किमी\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार, भूपृष्ठापासून सुमारे २९०० किमी खोलीच्या खाली गाभा सुरू होतो.\",\"topic\":\"गाभा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"गाभ्याची एकूण जाडी किती किमी आहे?\",\"options\":[\"२९०० किमी\",\"५१०० किमी\",\"३४७१ किमी\",\"६३७१ किमी\"],\"answer\":2,\"explain\":\"गाभ्याची जाडी ३४७१ किमी असल्याचे पाठ्यपुस्तकात नमूद केले आहे.\",\"topic\":\"गाभा\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"बाह्यगाभ्यातून भूकंपाच्या कोणत्या लहरी प्रवास करू शकत नाहीत?\",\"options\":[\"प्राथमिक लहरी\",\"दुय्यम लहरी\",\"भूपृष्ठ लहरी\",\"विद्युत चुंबकीय लहरी\"],\"answer\":1,\"explain\":\"भूकंपाच्या दुय्यम लहरी गाभा क्षेत्रातून (बाह्यगाभ्यातून) प्रवास करू शकत नाहीत.\",\"topic\":\"गाभा\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"बाह्यगाभा हा द्रव किंवा अर्धद्रव स्वरूपात असावा, असे शास्त्रज्ञांनी कोणत्या आधारावर अनुमान काढले?\",\"options\":[\"प्राथमिक लहरींचा वेग वाढतो म्हणून\",\"तेथील तापमान कमी आहे म्हणून\",\"दुय्यम लहरी तेथून प्रवास करू शकत नाहीत म्हणून\",\"तेथे लोह आढळते म्हणून\"],\"answer\":2,\"explain\":\"दुय्यम लहरी द्रव भागातून प्रवास करू शकत नाहीत, यावरून शास्त्रज्ञांनी बाह्यगाभा द्रव असावा असे अनुमान काढले.\",\"topic\":\"गाभा\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"बाह्यगाभ्याची घनता किती ग्रॅम\\/सेमी३ इतकी आहे?\",\"options\":[\"५.५\",\"९.८\",\"१३.३\",\"२.८\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील माहितीनुसार बाह्यगाभ्याची घनता ९.८ ग्रॅम\