वीच्या केंद्रापाशी (सुमारे ६४०० किमी) गुरुत्वीय तीव्रतेचे मूल्य किती असते?\",\"options\":[\"१२००\",\"९००\",\"४००\",\"०\"],\"answer\":3,\"explain\":\"आकृती \'आ\' मधील गुलाबी वक्र केंद्रापाशी (६४०० किमी) शून्य रेषेला स्पर्श करतो.\",\"topic\":\"भूकंपलहरींचा वेग व घनता\",\"part\":10,\"bloom\":\"analyze\",\"figure_image\":\"60\\/024_102.jpg\"},{\"q\":\"बाह्य गाभ्यांच्या सीमेपाशी दुय्यम लहरींचा वेग किती असतो?\",\"options\":[\"२ ते ४ किमी\\/सेकंद\",\"४ ते ६ किमी\\/सेकंद\",\"६ ते ८ किमी\\/सेकंद\",\"८ ते १० किमी\\/सेकंद\"],\"answer\":2,\"explain\":\"मजकुरात दिले आहे की दुय्यम लहरींचा वेग बाह्य गाभ्यांच्या सीमेपाशी ६ ते ८ किमी\\/सेकंदच्या दरम्यान असतो.\",\"topic\":\"भूकंपलहरींचा वेग व घनता\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीच्या अंतरंगात खोलीनुसार प्राथमिक लहरींच्या वेगात २९०० किमी पर्यंत काय बदल होतो?\",\"options\":[\"वेग कमी होत जातो\",\"वेग वाढत जातो\",\"वेग बदलत नाही\",\"वेग शून्यावर येतो\"],\"answer\":1,\"explain\":\"मजकुरात स्पष्ट केले आहे की प्राथमिक लहरींचा वेग खोलीप्रमाणे २९०० किमीपर्यंत वाढत जातो.\",\"topic\":\"भूकंपलहरींचा वेग व घनता\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"गुरुत्वीय बलाच्या वक्रावरून खालीलपैकी कोणता निष्कर्ष काढता येतो?\",\"options\":[\"ते पृष्ठभागापासून केंद्रापर्यंत सतत वाढते\",\"ते केंद्रापाशी सर्वाधिक असते\",\"ते काही खोलीपर्यंत वाढते व नंतर कमी होऊन केंद्रापाशी शून्य होते\",\"ते खोलीनुसार बदलत नाही\"],\"answer\":2,\"explain\":\"वक्रावरून दिसते की गुरुत्वाकर्षण बल काही खोलीपर्यंत वाढते व त्यानंतर खोलीनुसार कमी होऊन केंद्रापाशी शून्य होते.\",\"topic\":\"भूकंपलहरींचा वेग व घनता\",\"part\":10,\"bloom\":\"evaluate\"},{\"q\":\"प्राथमिक लहरींचा वेग बाह्यगाभ्यात प्रवेश करताना कमी होतो, हे कोणत्या वक्रावरून लक्षात येते?\",\"options\":[\"एकेरी वक्र\",\"द्विवेगने दाखविलेला वक्र\",\"सरळ रेषा\",\"वर्तुळाकार वक्र\"],\"answer\":1,\"explain\":\"मजकुरात \'द्विवेगने दाखविलेल्या वक्रावरून लक्षात घ्या\' असा उल्लेख प्राथमिक लहरींच्या संदर्भात आला आहे.\",\"topic\":\"भूकंपलहरींचा वेग व घनता\",\"part\":10,\"bloom\":\"analyze\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (22191,60,8,'Geography','mr','आर्द्रता व ढग','[\"आर्द्रता म्हणजे हवेतील बाष्पाचे प्रमाण.\",\"बाष्पधारण क्षमता म्हणजे विशिष्ट तापमानावर हवा किती बाष्प धारण करू शकते.\",\"गरम हवा थंड हवापेक्षा जास्त बाष्प धारण करते.\",\"हवेचे तापमान वाढल्यास बाष्पधारण क्षमता वाढते, तापमान कमी झाल्यास कमी होते.\",\"बाष्पसंपृक्त हवा म्हणजे बाष्पधारण क्षमता आणि बाष्पाचे प्रमाण समान असते.\",\"सापेक्ष आर्द्रता = (निरपेक्ष आर्द्रता ÷ बाष्पधारण क्षमता) × 100%.\",\"सापेक्ष आर्द्रता 100% असताना हवा बाष्पसंपृक्त असते.\",\"सापेक्ष आर्द्रता कमी असताना हवा कोरडी असते.\",\"दवबिंदू तापमान म्हणजे हवा सापेक्ष आर्द्रता 100% झाल्यावरचे तापमान.\",\"सांद्रीभवन म्हणजे बाष्प थंड पृष्ठभागावर जाऊन द्रवात रूपांतरित होणे.\",\"ढग हे सूक्ष्म पाण्याचे थेंब किंवा हिमकणांच्या समूहाने बनलेले असतात.\",\"ढगांची उंची 2000 मी ते 14000 मी दरम्यान असते.\",\"सिरस ढग सर्वात उंचीवर, क्युम्युलस ढग मध्यम उंचीवर, निम्बो स्ट्रेटस कमी उंचीवर असतात.\",\"क्युम्युलो निम्बस ढग वादळाचे निदर्शक असतात आणि पाऊस किंवा गारपीट आणतात.\",\"ढगांमध्ये विद्युत भार निर्माण होऊन विजेची निर्मिती होते.\",\"वातावरणातील बाष्पधारण क्षमता उंची वाढल्यास कमी होते.\",\"आर्द्रतेचे मापन सामान्यतः ग्रॅम प्रति घनमीटर (g\\/m³) मध्ये केले जाते.\",\"बाष्पधारण क्षमता आणि निरपेक्ष आर्द्रता यावरून सापेक्ष आर्द्रता काढता येते.\",\"बाष्पसंपृक्त हवा म्हणजे बाष्पधारण क्षमता आणि बाष्पाचे प्रमाण समान असणे.\",\"सापेक्ष आर्द्रता वाढल्यास दवबिंदू तापमान कमी होते.\"]','[{\"q\":\"वातावरणात बाष्प हा घटक कोणत्या स्थितीत असतो?\",\"options\":[\"द्रवरूप स्थितीत\",\"अदृश्य स्थितीत\",\"घन स्थितीत\",\"दृश्य स्थितीत\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, बाष्प हा घटक वातावरणात अदृश्य स्थितीत असतो.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राजस्थान हा प्रदेश कोणत्या प्रकारच्या हवेच्या प्रदेशात येतो?\",\"options\":[\"थंड व कोरड्या\",\"उष्ण व दमट\",\"कोरड्या व उष्ण\",\"थंड व दमट\"],\"answer\":2,\"explain\":\"राजस्थान कोरड्या व उष्ण हवेच्या प्रदेशात येतो, जिथे हवेत बाष्प अल्प असते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या चित्रातील पहिल्या भागात (वाळवंटी प्रदेश) लोक कोणत्या प्रकारचे कपडे वापरत असल्याचे दिसून येते?\",\"options\":[\"उबदार व जाड कपडे\",\"सुती व सैल पेहराव\",\"रेनकोट आणि छत्री\",\"रेशमी आणि घट्ट कपडे\"],\"answer\":1,\"explain\":\"चित्रातील संवादावरून आणि मजकुरावरून स्पष्ट होते की राजस्थानसारख्या उष्ण प्रदेशात लोक सुती व सैल पेहराव वापरतात.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"60\\/026_101.jpg\"},{\"q\":\"मुंबईतील हवेत बाष्पाचे प्रमाण जास्त असते, म्हणून तेथील हवा कशी असते?\",\"options\":[\"कोरडी\",\"थंड\",\"दमट\",\"अतिथंड\"],\"answer\":2,\"explain\":\"हवेत बाष्पाचे प्रमाण जास्त असल्यास ती हवा दमट असते, जशी मुंबईत आढळते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील दुसऱ्या भागात व्यक्तीला मोठ्या प्रमाणावर घाम येण्याचे मुख्य कारण काय असावे?\",\"options\":[\"हवेतील कोरडेपणा\",\"हवेतील उष्णता व दमटपणा\",\"हवेतील अतिथंडपणा\",\"वाळूचे वादळ\"],\"answer\":1,\"explain\":\"मुंबईसारख्या उष्ण व दमट हवेच्या प्रदेशात हवेत बाष्प जास्त असल्याने उकाडा जाणवतो व घाम येतो.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"60\\/026_101.jpg\"},{\"q\":\"काश्मीरमधील हवेच्या स्थितीबाबत खालीलपैकी कोणते विधान सत्य आहे?\",\"options\":[\"हवा उष्ण व दमट आहे.\",\"हवेत बाष्पाचे प्रमाण खूप जास्त आहे.\",\"हवा थंड व कोरडी आहे.\",\"हवा फक्त उष्ण व कोरडी आहे.\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकातील भौगोलिक स्पष्टीकरणानुसार काश्मीर थंड व कोरड्या हवेच्या प्रदेशात आहे.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"कोणत्याही ठिकाणी हवेची स्थिती स्पष्ट करताना कोणता घटक प्राधान्याने विचारात घेतला जातो?\",\"options\":[\"वाळू\",\"बाष्प\",\"पेहराव\",\"वनस्पती\"],\"answer\":1,\"explain\":\"हवेची स्थिती स्पष्ट करताना बाष्प हा घटक प्राधान्याने विचारात घेतला जातो.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"एखाद्या ठिकाणी पर्जन्यस्थिती निर्माण होण्यासाठी वातावरणात काय असणे आवश्यक असते?\",\"options\":[\"धुळीचे कण\",\"अतिउष्णता\",\"बाष्प\",\"कोरडी हवा\"],\"answer\":2,\"explain\":\"मजकुरात नमूद केल्याप्रमाणे, पर्जन्यस्थिती निर्माण होण्यासाठी वातावरणात बाष्प असणे आवश्यक असते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मुंबईत जर आकाशात काळे ढग जमले, तर हवेवर काय परिणाम होतो?\",\"options\":[\"उष्णता कमी होते.\",\"उष्णता अधिक वाढते.\",\"हवा कोरडी होते.\",\"काहीही बदल होत नाही.\"],\"answer\":1,\"explain\":\"मुंबईत उष्ण व दमट हवा असते, त्यात काळे ढग जमल्यास हवेतील उष्णता अधिक वाढते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"राजस्थान आणि काश्मीर या दोन्ही प्रदेशांच्या हवेत कोणता समान गुणधर्म आढळतो?\",\"options\":[\"दोन्हीकडे हवा उष्ण आहे.\",\"दोन्हीकडे हवा दमट आहे.\",\"दोन्हीकडे बाष्पाचे प्रमाण अल्प आहे.\",\"दोन्हीकडे बाष्पाचे प्रमाण जास्त आहे.\"],\"answer\":2,\"explain\":\"राजस्थान (उष्ण व कोरडी) आणि काश्मीर (थंड व कोरडी) या दोन्ही ठिकाणी हवेत बाष्पाचे प्रमाण अल्प असते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता शब्द हवेचा \'स्थितीदर्शक\' शब्द नाही?\",\"options\":[\"दमट\",\"कोरडी\",\"सुती\",\"थंड\"],\"answer\":2,\"explain\":\"उष्ण, दमट, कोरडी, थंड हे हवेचे स्थितीदर्शक शब्द आहेत; \'सुती\' हा कपड्याचा प्रकार आहे.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"हवेचा दमटपणा किंवा कोरडेपणा कशावर अवलंबून असतो?\",\"options\":[\"वातावरणातील बाष्पावर\",\"लोकांच्या पेहरावावर\",\"केवळ तापमानावर\",\"समुद्राच्या अंतरावर\"],\"answer\":0,\"explain\":\"हवेचा दमटपणा किंवा कोरडेपणा याची सांगड वातावरणातील बाष्पाशी येते.\",\"topic\":\"प्रस्तावना व भौगोलिक स्पष्टीकरण\",\"part\":1,\"bloom\":\"evaluate\"},{\"q\":\"पाण्याचे बाष्पात रूपांतर होणाऱ्या प्रक्रियेला काय म्हणतात?\",\"options\":[\"सांद्रीभवन\",\"बाष्पीभवन\",\"वृष्टी\",\"अभिसरण\"],\"answer\":1,\"explain\":\"पाण्याचे बाष्पात रूपांतर होणाऱ्या प्रक्रियेला बाष्पीभवन असे म्हणतात.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पृथ्वीवरील पाण्याचे बाष्पात रूपांतर होण्यासाठी कशाची उष्णता कारणीभूत असते?\",\"options\":[\"चंद्राची\",\"भूगर्भातील\",\"सूर्याची\",\"वातावरणाची\"],\"answer\":2,\"explain\":\"सूर्याच्या उष्णतेमुळे पृथ्वीवरील पाण्याचे बाष्पात रूपांतर होते.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"बाष्पीभवनाची प्रक्रिया खालीलपैकी कोणत्या घटकावर आधारित नसते?\",\"options\":[\"हवेची शुष्कता\",\"तापमान\",\"वाऱ्याचा वेग\",\"पाण्याची खोली\"],\"answer\":3,\"explain\":\"बाष्पीभवन हवेची शुष्कता, तापमान आणि वाऱ्याचा वेग यांवर आधारित असते; पाण्याचा खोलीचा उल्लेख पाठात नाही.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"हवा कोरडी व उष्ण असेल, तर बाष्पीभवनाच्या वेगावर काय परिणाम होतो?\",\"options\":[\"वेग कमी होतो\",\"वेग वाढतो\",\"वेग स्थिर राहतो\",\"बाष्पीभवन थांबते\"],\"answer\":1,\"explain\":\"कोरडी व उष्ण हवा असेल तर बाष्पीभवनाचा वेग वाढतो.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"अतिशय दमट हवा असताना बाष्पीभवनाची क्रिया कशी असते?\",\"options\":[\"जलद होते\",\"मंद होते\",\"खूप जास्त वाढते\",\"काहीच फरक पडत नाही\"],\"answer\":1,\"explain\":\"अतिशय दमट हवा असताना बाष्पीभवनाची क्रिया मंदावते.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"वाऱ्याचा वेग जास्त आणि हवेचे तापमान जास्त असल्यास बाष्पीभवन कसे होईल?\",\"options\":[\"मंद गतीने\",\"कमी प्रमाणात\",\"जलद गतीने\",\"अतिशय कमी\"],\"answer\":2,\"explain\":\"वाऱ्याचा वेग व तापमान जास्त असेल तर बाष्पीभवनाची क्रिया जलद होते.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"कोरड्या व थंड हवेत बाष्पीभवनाची क्रिया कशी राहते?\",\"options\":[\"मंद\",\"अतिजलद\",\"वाढलेली\",\"शून्य\"],\"answer\":0,\"explain\":\"कोरड्या व थंड हवेत बाष्पीभवनाची क्रिया मंद राहते.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"हिवाळ्यात आरशाच्या काचेवर उच्छ्वास सोडल्यास काय घडते?\",\"options\":[\"काच गरम होते\",\"काचेवर बाष्प जमा होते\",\"काच फुटते\",\"काहीच बदल होत नाही\"],\"answer\":1,\"explain\":\"हिवाळ्यात हवेचे तापमान कमी असल्याने उच्छ्वासातील बाष्प काचेवर जमा झाल्याचा अनुभव येतो.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"वाळत घातलेले कपडे कोणत्या ऋतूत लवकर वाळतात?\",\"options\":[\"पावसाळ्यात\",\"हिवाळ्यात\",\"उन्हाळ्यात\",\"सर्व ऋतूत सारखेच\"],\"answer\":2,\"explain\":\"उन्हाळ्यात तापमान जास्त व हवा कोरडी असल्याने बाष्पीभवन जलद होऊन कपडे लवकर वाळतात.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"वारा कमी वेगाने वाहत असेल व हवा थंड असेल तर बाष्पीभवनावर काय परिणाम होईल?\",\"options\":[\"बाष्पीभवन वाढेल\",\"बाष्पीभवन कमी होईल\",\"बाष्पीभवन जलद होईल\",\"बाष्पीभवन खूप जास्त होईल\"],\"answer\":1,\"explain\":\"कमी वारा आणि थंड हवा या दोन्ही स्थिती बाष्पीभवन कमी करण्यास कारणीभूत ठरतात.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणत्या परिस्थितीत बाष्पीभवन सर्वात जलद होईल?\",\"options\":[\"थंड आणि दमट हवा\",\"उष्ण आणि दमट हवा\",\"उष्ण आणि कोरडी हवा\",\"थंड आणि कोरडी हवा\"],\"answer\":2,\"explain\":\"उष्णता आणि कोरडेपणा या दोन्हीमुळे बाष्पीभवनाचा वेग सर्वाधिक असतो.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"बाष्पीभवन प्रक्रियेबाबत कोणते विधान सत्य आहे?\",\"options\":[\"हवेचे तापमान वाढल्यास बाष्पीभवन कमी होते.\",\"वाऱ्याचा वेग वाढल्यास बाष्पीभवन मंदावते.\",\"हवेची शुष्कता वाढल्यास बाष्पीभवनाचा वेग वाढतो.\",\"दमट हवेत बाष्पीभवन जलद होते.\"],\"answer\":2,\"explain\":\"हवेची शुष्कता (कोरडेपणा) वाढल्यास बाष्पीभवनाचा वेग वाढतो हे विधान पाठातील माहितीनुसार अचूक आहे.\",\"topic\":\"बाष्पीभवन\",\"part\":2,\"bloom\":\"evaluate\"},{\"q\":\"हवेतील बाष्पाच्या प्रमाणाला काय म्हणतात?\",\"options\":[\"हवेचा दाब\",\"हवेची आर्द्रता\",\"हवेची घनता\",\"हवेचे तापमान\"],\"answer\":1,\"explain\":\"हवेतील बाष्पाचे प्रमाण म्हणजेच हवेची आर्द्रता होय.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"हवेचा दमटपणा किंवा कोरडेपणा प्रामुख्याने कशावर अवलंबून असतो?\",\"options\":[\"हवेच्या वेगावर\",\"हवेच्या दाबावर\",\"बाष्पाच्या प्रमाणावर\",\"ढगांच्या प्रकारावर\"],\"answer\":2,\"explain\":\"हवेचा दमटपणा किंवा कोरडेपणा हा बाष्पाच्या प्रमाणावर (आर्द्रतेवर) अवलंबून असतो.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"हवा जसजशी थंड होते, तसतशी तिच्या बाष्पधारणक्षमतेत काय बदल होतो?\",\"options\":[\"ती वाढते\",\"ती कमी होते\",\"ती स्थिर राहते\",\"ती दुप्पट होते\"],\"answer\":1,\"explain\":\"हवा थंड झाल्यावर तिची बाष्प धारण करण्याची क्षमता कमी होते.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"गरम हवा आणि थंड हवा यांच्या बाष्पधारणक्षमतेबाबत कोणते विधान योग्य आहे?\",\"options\":[\"थंड हवा गरम हवेपेक्षा जास्त बाष्प धारण करू शकते\",\"दोन्ही हवेची बाष्पधारणक्षमता नेहमी सारखीच असते\",\"गरम हवा थंड हवेपेक्षा जास्त बाष्प धारण करू शकते\",\"गरम हवेत बाष्प धारण करण्याची क्षमता नसते\"],\"answer\":2,\"explain\":\"गरम हवेची बाष्पधारणक्षमता थंड हवेपेक्षा जास्त असते.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"हवेची बाष्पधारण क्षमता आणि बाष्पाचे प्रमाण सारखेच असते, त्या स्थितीला काय म्हणतात?\",\"options\":[\"बाष्पविरहित स्थिती\",\"बाष्पसंपृक्त स्थिती\",\"कोरडी स्थिती\",\"अतिउष्ण स्थिती\"],\"answer\":1,\"explain\":\"जेव्हा बाष्पधारण क्षमता आणि बाष्पाचे प्रमाण समान होते, तेव्हा तिला बाष्पसंपृक्त स्थिती म्हणतात.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"जर एका ठिकाणच्या हवेचे तापमान अचानक वाढले, तर त्या हवेच्या बाष्पधारणक्षमतेवर काय परिणाम होईल?\",\"options\":[\"बाष्पधारणक्षमता कमी होईल\",\"बाष्पधारणक्षमता वाढेल\",\"बाष्पधारणक्षमता शून्य होईल\",\"काहीही बदल होणार नाही\"],\"answer\":1,\"explain\":\"तापमान वाढल्यास (हवा गरम झाल्यास) बाष्पधारणक्षमता वाढते, हे पाठातील तत्त्वावरून स्पष्ट होते.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"विशिष्ट तापमानाला हवेच्या बाष्प धारण करण्याच्या मर्यादेबाबत काय सांगता येईल?\",\"options\":[\"हवा कितीही बाष्प धारण करू शकते\",\"हवा विशिष्ट प्रमाणातच बाष्प धारण करू शकते\",\"हवेची बाष्प धारण करण्याची क्षमता तापमानावर अवलंबून नसते\",\"केवळ थंड हवाच बाष्प धारण करू शकते\"],\"answer\":1,\"explain\":\"हवा विशिष्ट तापमानास विशिष्ट प्रमाणातच बाष्प धारण करू शकते असे पाठ्यपुस्तकात नमूद आहे.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"एका खोलीतील हवा बाष्पसंपृक्त आहे, याचा अर्थ काय?\",\"options\":[\"खोलीतील हवा अतिशय कोरडी आहे\",\"हवेची बाष्प धारण करण्याची क्षमता संपली आहे व ती पूर्ण भरली आहे\",\"हवेतील बाष्पाचे प्रमाण क्षमतेपेक्षा खूप कमी आहे\",\"खोलीतील तापमान खूप जास्त आहे\"],\"answer\":1,\"explain\":\"बाष्पसंपृक्त म्हणजे बाष्पधारण क्षमता आणि बाष्पाचे प्रमाण सारखे असणे.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या घटकाचा हवेच्या बाष्पधारणक्षमतेशी थेट संबंध आहे?\",\"options\":[\"हवेचा वेग\",\"हवेची दिशा\",\"हवेचे तापमान\",\"हवेचा रंग\"],\"answer\":2,\"explain\":\"हवेचे तापमान बदलले की तिची बाष्पधारणक्षमता बदलते (थंड हवेची कमी, गरम हवेची जास्त).\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"हवेच्या स्थितीबाबत चुकीचा पर्याय निवडा:\",\"options\":[\"हवा थंड झाल्यावर बाष्पधारणक्षमता कमी होते\",\"गरम हवा जास्त बाष्प धारण करू शकते\",\"बाष्पसंपृक्त स्थितीत हवा अधिक बाष्प घेऊ शकते\",\"आर्द्रता म्हणजे हवेतील बाष्पाचे प्रमाण होय\"],\"answer\":2,\"explain\":\"बाष्पसंपृक्त स्थितीत क्षमता आणि प्रमाण सारखे असल्याने हवा अधिक बाष्प घेऊ शकत नाही.\",\"topic\":\"वातावरणातील आर्द्रता\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"बाष्पधारण क्षमतेच्या प्रयोगासाठी दिलेल्या कृतीत कोणता पदार्थ वापरला आहे?\",\"options\":[\"कापूस\",\"स्पंज\",\"कापड\",\"कागद\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकातील कृतीनुसार ट्रेमध्ये स्पंजचा तुकडा ठेवण्यास सांगितले आहे.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"ट्रेच्या सपाट तळाभागावर छिद्रे पाडण्यासाठी कशाचा वापर करण्यास सांगितले आहे?\",\"options\":[\"सुई\",\"पेन\",\"खिळे\",\"कात्री\"],\"answer\":2,\"explain\":\"कृतीमध्ये ट्रेच्या तळाला खिळ्यांच्या साहाय्याने छिद्रे पाडण्यास सांगितले आहे.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"सुरुवातीस स्पंजवर ओतलेल्या पाण्याचे काय होते?\",\"options\":[\"ते छिद्रांतून खाली जाते\",\"ते स्पंजमध्ये शोषले जाते\",\"ते ट्रेमध्ये पसरते\",\"ते हवेत बाष्पीभवन होते\"],\"answer\":1,\"explain\":\"सुरुवातीला स्पंज कोरडा असल्याने ओतलेले पाणी त्यात शोषले जाते.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत पाणी ओतण्यासाठी कोणत्या साधनाचा वापर केला जात आहे?\",\"options\":[\"पेला\",\"बादली\",\"चमचा\",\"नळी\"],\"answer\":2,\"explain\":\"आकृती ३.३ मध्ये स्पंजवर चमच्याने पाणी ओतताना दाखवले आहे.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"remember\",\"figure_image\":\"60\\/027_102.jpg\"},{\"q\":\"स्पंज पूर्ण ओला झाल्यानंतरही पाणी ओतत राहिल्यास काय होईल?\",\"options\":[\"स्पंज आकुंचन पावेल\",\"पाणी स्पंजमध्येच राहील\",\"पाणी छिद्रांतून खाली टपकेल\",\"स्पंजचा रंग बदलेल\"],\"answer\":2,\"explain\":\"स्पंजची पाणी धरून ठेवण्याची क्षमता संपल्यावर जास्तीचे पाणी छिद्रांतून खाली येते.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत स्पंज ट्रेमध्ये कोठे ठेवला आहे?\",\"options\":[\"ट्रेच्या कोपऱ्यात\",\"ट्रेच्या मध्यभागी\",\"ट्रेच्या बाहेर\",\"ट्रेच्या खाली\"],\"answer\":1,\"explain\":\"आकृती ३.३ आणि मजकुरानुसार स्पंज ट्रेच्या मध्यभागी ठेवला आहे.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"understand\",\"figure_image\":\"60\\/027_102.jpg\"},{\"q\":\"जर एका स्पंजची क्षमता १० चमचे पाणी धरून ठेवण्याची असेल आणि आपण त्यात १२ चमचे पाणी ओतले, तर किती पाणी खाली पडेल?\",\"options\":[\"१० चमचे\",\"१२ चमचे\",\"२ चमचे\",\"० चमचे\"],\"answer\":2,\"explain\":\"क्षमतेपेक्षा जास्त (१२ - १० = २) असलेले पाणी बाहेर पडेल.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"स्पंजमधून पाणी खाली टपकायला लागणे, हे कशाचे लक्षण आहे?\",\"options\":[\"स्पंज कोरडा आहे\",\"स्पंजची पाणी धारण करण्याची क्षमता पूर्ण झाली आहे\",\"स्पंजमध्ये छिद्रे नाहीत\",\"पाणी खूप गरम आहे\"],\"answer\":1,\"explain\":\"जेव्हा स्पंजची पाणी धरून ठेवण्याची मर्यादा संपते, तेव्हाच पाणी बाहेर पडते.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"जर आपण स्पंजचा मोठा तुकडा घेतला, तर पाणी शोषण्याच्या क्षमतेवर काय परिणाम होईल?\",\"options\":[\"क्षमता कमी होईल\",\"क्षमता वाढेल\",\"क्षमता तीच राहील\",\"स्पंज पाणी शोषणार नाही\"],\"answer\":1,\"explain\":\"आकारमान वाढल्यास पाणी धरून ठेवण्याची क्षमताही वाढते.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"या स्पंजच्या कृतीचा निष्कर्ष हवेच्या संदर्भात काय असू शकतो?\",\"options\":[\"हवा पाणी निर्माण करते\",\"हवेला वजन नसते\",\"हवेची ठराविक बाष्पधारण क्षमता असते\",\"हवा कधीही संपत नाही\"],\"answer\":2,\"explain\":\"जशी स्पंजची पाणी धरून ठेवण्याची क्षमता असते, तशीच हवेची बाष्पधारण क्षमता असते.\",\"topic\":\"कृती: बाष्पधारण क्षमता\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"हवेची बाष्पधारण क्षमता प्रामुख्याने कशावर अवलंबून असते?\",\"options\":[\"हवेचा दाब\",\"हवेचे तापमान\",\"हवेची दिशा\",\"हवेची गती\"],\"answer\":1,\"explain\":\"पाठातील भौगोलिक स्पष्टीकरणानुसार, हवेची बाष्पधारण क्षमता हवेच्या तापमानावर अवलंबून असते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"दिलेल्या तक्त्याचे निरीक्षण करा. २०° से. तापमानावर एक घनमीटर हवेची बाष्पधारण क्षमता किती असते?\",\"options\":[\"१२.८३ ग्रॅम\\/मी³\",\"३०.३७ ग्रॅम\\/मी³\",\"१७.३० ग्रॅम\\/मी³\",\"९.४० ग्रॅम\\/मी³\"],\"answer\":2,\"explain\":\"दिलेल्या तक्त्यानुसार, २०° से. तापमानासमोर १७.३० ग्रॅम\\/मी³ ही बाष्पधारण क्षमता दर्शवली आहे.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"remember\",\"figure_image\":\"60\\/028_101.jpg\"},{\"q\":\"जेव्हा हवेची बाष्प धारण करण्याची क्षमता पूर्ण होते, तेव्हा ती हवा _________ बनली आहे असे म्हणतात.\",\"options\":[\"असंपृक्त\",\"शुष्क\",\"संपृक्त\",\"विरल\"],\"answer\":2,\"explain\":\"स्पंजच्या उदाहरणावरून स्पष्ट केल्याप्रमाणे, क्षमता पूर्ण झाल्यावर हवा संपृक्त बनते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"वातावरणात जसजसे जास्त उंच जावे, तसतशी हवेची बाष्पधारण क्षमता कमी का होत जाते?\",\"options\":[\"कारण उंच गेल्यावर हवा थंड होते\",\"कारण उंच गेल्यावर हवा गरम होते\",\"कारण उंच गेल्यावर हवेचा दाब वाढतो\",\"कारण उंच गेल्यावर बाष्प वाढते\"],\"answer\":0,\"explain\":\"उंच गेल्यावर हवा थंड होते आणि तापमान कमी झाल्यामुळे बाष्पधारण क्षमताही कमी होते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत, स्पंजमधून पाणी थेंबाथेंबाने खाली झिरपण्याचे भौगोलिक कारण काय असू शकते?\",\"options\":[\"स्पंज कोरडा आहे\",\"स्पंजची पाणी धारण करण्याची क्षमता पूर्ण झाली आहे\",\"स्पंजवर कमी पाणी टाकले आहे\",\"स्पंजचा आकार मोठा झाला आहे\"],\"answer\":1,\"explain\":\"जेव्हा स्पंजची पाणी धारण करण्याची क्षमता पूर्ण होते, तेव्हा तो संपृक्त होतो आणि पाणी खाली झिरपते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"60\\/028_102.jpg\"},{\"q\":\"हवेची बाष्पधारण क्षमता मोजण्यासाठी कोणते एकक वापरले जाते?\",\"options\":[\"किमी\\/तास\",\"डिग्री सेल्सिअस\",\"ग्रॅम\\/मी³\",\"मिलीबार\"],\"answer\":2,\"explain\":\"तक्त्यामध्ये बाष्पधारण क्षमता मोजण्यासाठी ग्रॅम\\/मी³ (ग्रॅम प्रति घनमीटर) हे एकक दिले आहे.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"हवेचे तापमान जितके जास्त असेल, तितकी तिची बाष्पधारण क्षमता _________ असते.\",\"options\":[\"कमी\",\"स्थिर\",\"शून्य\",\"अधिक\"],\"answer\":3,\"explain\":\"पाठातील नियमानुसार, हवेचे तापमान जितके जास्त तितकी बाष्पधारण क्षमता अधिक असते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या तक्त्यानुसार, ०° से. आणि ५° से. तापमानातील बाष्पधारण क्षमतेतील फरक किती ग्रॅम\\/मी³ आहे?\",\"options\":[\"१.९५\",\"१.५९\",\"२.८५\",\"३.२६\"],\"answer\":0,\"explain\":\"५° से. (६.८०) - ०° से. (४.८५) = १.९५ ग्रॅम\\/मी³.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"apply\",\"figure_image\":\"60\\/028_101.jpg\"},{\"q\":\"हवेतील बाष्प हे हवेच्या बाष्पधारण क्षमतेपेक्षा अतिरिक्त झाल्यास काय घडते?\",\"options\":[\"हवा गरम होते\",\"पाऊस किंवा हिमाच्या स्वरूपात वृष्टी होते\",\"हवा अधिक बाष्प शोषून घेते\",\"हवेचा दाब कमी होतो\"],\"answer\":1,\"explain\":\"बाष्प क्षमतेपेक्षा जास्त झाल्यास ते पावसाच्या किंवा हिमाच्या स्वरूपात पृथ्वीवर पडते.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"बाष्पधारण क्षमतेच्या प्रयोगात \'स्पंजचा तुकडा\' म्हणजे काय असे मानले आहे?\",\"options\":[\"पाणी\",\"ढग\",\"हवा\",\"जमीन\"],\"answer\":2,\"explain\":\"भौगोलिक स्पष्टीकरणात सुरुवातीलाच म्हटले आहे की, स्पंजचा तुकडा हवेप्रमाणे आहे असे मानू.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"जर हवेचे तापमान ३०° से. वरून १५° से. पर्यंत कमी झाले, तर तक्त्यानुसार बाष्पधारण क्षमतेत काय बदल होईल?\",\"options\":[\"ती ३०.३७ वरून १२.८३ पर्यंत कमी होईल\",\"ती १२.८३ वरून ३०.३७ पर्यंत वाढेल\",\"ती स्थिर राहील\",\"ती शून्य होईल\"],\"answer\":0,\"explain\":\"तक्त्यानुसार ३०° से. ला क्षमता ३०.३७ आहे आणि १५° से. ला १२.८३ आहे, म्हणजेच ती कमी होईल.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"60\\/028_101.jpg\"},{\"q\":\"एका घनमीटर हवेत -५° से. तापमानाला किती बाष्प मावू शकते?\",\"options\":[\"४.८५ ग्रॅम\",\"३.२६ ग्रॅम\",\"६.८० ग्रॅम\",\"९.४० ग्रॅम\"],\"answer\":1,\"explain\":\"तक्त्यातील पहिल्या नोंदीनुसार, -५° से. तापमानाला बाष्पधारण क्षमता ३.२६ ग्रॅम\\/मी³ आहे.\",\"topic\":\"बाष्पधारण क्षमता व तापमान\",\"part\":5,\"bloom\":\"apply\",\"figure_image\":\"60\\/028_101.jpg\"},{\"q\":\"आर्द्रतेचे मापन सामान्यपणे कोणत्या एककात केले जाते?\",\"options\":[\"ग्रॅम प्रति घनमीटर\",\"किलोग्रॅम प्रति मीटर\",\"मिलीग्राम प्रति सेंटीमीटर\",\"ग्रॅम प्रति लिटर\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार आर्द्रतेचे मापन ग्रॅम प्रति घनमीटर (g\\/m³) या एककात केले जाते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"कोणत्याही तापमानाला हवेतील आर्द्रतेचे प्रमाण किती असल्यास ती हवा \'कोरडी\' असते?\",\"options\":[\"१० ग्रॅम\\/मी³\",\"५ ग्रॅम\\/मी³\",\"० ग्रॅम\\/मी³\",\"३०.३७ ग्रॅम\\/मी³\"],\"answer\":2,\"explain\":\"हवेतील आर्द्रतेचे प्रमाण ० ग्रॅम\\/मी³ असल्यास ती हवा कोरडी मानली जाते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"३०° से. तापमानास हवेतील बाष्प किती ग्रॅम\\/मी³ असल्यास हवा बाष्पसंपृक्त असते?\",\"options\":[\"२०.०० ग्रॅम\\/मी³\",\"३०.३७ ग्रॅम\\/मी³\",\"१५.५० ग्रॅम\\/मी³\",\"४०.०० ग्रॅम\\/मी³\"],\"answer\":1,\"explain\":\"३०° से. तापमानाला हवेची बाष्पधारण क्षमता ३०.३७ ग्रॅम\\/मी³ असते, तेव्हा ती संपृक्त होते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"सापेक्ष आर्द्रता कशामध्ये व्यक्त केली जाते?\",\"options\":[\"अंश सेल्सिअस\",\"घनमीटर\",\"टक्केवारी\",\"ग्रॅम\"],\"answer\":2,\"explain\":\"सापेक्ष आर्द्रता नेहमी टक्केवारीत (%) व्यक्त केली जाते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"सापेक्ष आर्द्रता काढण्याचे अचूक सूत्र कोणते?\",\"options\":[\"(बाष्पधारण क्षमता \\/ निरपेक्ष आर्द्रता) × १००\",\"(निरपेक्ष आर्द्रता \\/ बाष्पधारण क्षमता) × १००\",\"(निरपेक्ष आर्द्रता + बाष्पधारण क्षमता) \\/ १००\",\"(निरपेक्ष आर्द्रता × बाष्पधारण क्षमता) \\/ १००\"],\"answer\":1,\"explain\":\"सापेक्ष आर्द्रता म्हणजे निरपेक्ष आर्द्रता व बाष्पधारण क्षमता यांचे गुणोत्तर गुणिले १०० होय.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एका घनमीटर हवेची निरपेक्ष आर्द्रता २० ग्रॅम\\/मी³ असून बाष्पधारण क्षमता ३० ग्रॅम\\/मी³ आहे, तर तिची सापेक्ष आर्द्रता किती?\",\"options\":[\"५०%\",\"६०%\",\"६६.६६%\",\"७५%\"],\"answer\":2,\"explain\":\"(२० \\/ ३०) × १०० = ६६.६६% ही सापेक्ष आर्द्रता येते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"एका घनमीटर हवेची निरपेक्ष आर्द्रता १५ ग्रॅम\\/मी³ असून बाष्पधारण क्षमता १५ ग्रॅम\\/मी³ असल्यास ती हवा कोणत्या स्थितीला पोहोचली आहे?\",\"options\":[\"कोरडी हवा\",\"बाष्पसंपृक्त हवा\",\"अतिउष्ण हवा\",\"विरळ हवा\"],\"answer\":1,\"explain\":\"जेव्हा निरपेक्ष आर्द्रता आणि बाष्पधारण क्षमता समान असते (सापेक्ष आर्द्रता १००%), तेव्हा हवा बाष्पसंपृक्त असते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"दिवसा तापमान वाढल्यामुळे सापेक्ष आर्द्रतेवर काय परिणाम होतो?\",\"options\":[\"सापेक्ष आर्द्रता वाढते\",\"सापेक्ष आर्द्रता कमी होते\",\"सापेक्ष आर्द्रता स्थिर राहते\",\"सापेक्ष आर्द्रता शून्यावर येते\"],\"answer\":1,\"explain\":\"दिवसा तापमान वाढल्यामुळे हवेची बाष्पधारण क्षमता वाढते, परिणामी सापेक्ष आर्द्रता कमी होते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"साधारणपणे कोणत्या वेळी सापेक्ष आर्द्रता जास्त असते?\",\"options\":[\"दुपारी\",\"संध्याकाळी\",\"सकाळी व रात्री\",\"केवळ मध्यरात्री\"],\"answer\":2,\"explain\":\"तापमान कमी असताना सापेक्ष आर्द्रता जास्त असते, जे साधारणपणे सकाळी व रात्री घडते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"समुद्र किनाऱ्याजवळील प्रदेशातील हवा दमट का असते?\",\"options\":[\"तेथे पाऊस जास्त पडतो\",\"तेथे सापेक्ष आर्द्रता जास्त असते\",\"तेथे तापमान खूप जास्त असते\",\"तेथे निरपेक्ष आर्द्रता शून्य असते\"],\"answer\":1,\"explain\":\"समुद्र किनाऱ्याजवळ बाष्पाचे प्रमाण जास्त असल्याने सापेक्ष आर्द्रता जास्त असते, म्हणून हवा दमट असते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"वाळवंटी प्रदेशातील हवा कोरडी असण्याचे मुख्य कारण काय?\",\"options\":[\"सापेक्ष आर्द्रता कमी असणे\",\"बाष्पधारण क्षमता कमी असणे\",\"निरपेक्ष आर्द्रता जास्त असणे\",\"तापमान कमी असणे\"],\"answer\":0,\"explain\":\"वाळवंटी प्रदेशात बाष्पाचे प्रमाण कमी असल्याने सापेक्ष आर्द्रता कमी असते, परिणामी हवा कोरडी असते.\",\"topic\":\"सापेक्ष आर्द्रता\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"२०° से. तापमान असलेल्या बाष्पसंपृक्त हवेचे तापमान अचानक १०° से. झाले तर काय होईल?\",\"options\":[\"सापेक्ष आर्द्रता कमी होईल\",\"हवेची बाष्पधारण क्षमता वाढेल\",\"हवेची बाष्पधारण क्षमता कमी होईल\",\"हवा अधिक कोरडी होईल\"],\"answer\":2,\"explain\":\"तापमान कमी झाल्यामुळे हवेची बाष्प धरून ठेवण्याची क्षमता कमी ह