ge\":\"60\\/031_102.jpg\"},{\"q\":\"दिलेल्या आकृतीवरून, कोणत्या ढगांच्या प्रकाराचा विस्तार जमिनीपासून कमी-जास्त असू शकतो?\",\"options\":[\"सिरस\",\"स्ट्रॅटस\",\"क्युम्युलो निम्बस\",\"अल्टो क्युम्युलस\"],\"answer\":2,\"explain\":\"तक्त्यात क्युम्युलो निम्बस ढगांचा विस्तार कमी-जास्त असू शकतो असे नमूद केले आहे.\",\"topic\":\"ढग व ढगांचे प्रकार\",\"part\":8,\"bloom\":\"apply\",\"figure_image\":\"60\\/031_102.jpg\"},{\"q\":\"जर एखाद्या ढगाची निर्मिती २००० मीटरपेक्षा कमी उंचीवर झाली असेल, तर तो खालीलपैकी कोणता प्रकार असू शकतो?\",\"options\":[\"सिरो स्ट्रॅटस\",\"अल्टो क्युम्युलस\",\"निम्बो स्ट्रॅटस\",\"सिरो क्युम्युलस\"],\"answer\":2,\"explain\":\"निम्बो स्ट्रॅटस ढग २००० मीटरपेक्षा कमी उंचीवर आढळतात.\",\"topic\":\"ढग व ढगांचे प्रकार\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"ढगांच्या निर्मिती प्रक्रियेत वातावरणातील कशाची भूमिका महत्त्वाची असते ज्याभोवती सांद्रीभवन होते?\",\"options\":[\"मोठे दगड\",\"सूक्ष्मकण\",\"केवळ ऑक्सिजन\",\"पाण्याचे ओहोळ\"],\"answer\":1,\"explain\":\"ढग वातावरणातील सूक्ष्मकणांभोवती सांद्रीभवन झाल्यामुळे तयार होतात.\",\"topic\":\"ढग व ढगांचे प्रकार\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"बाष्पाचे प्रमाण आणि ढगांचा आकार यांचा संबंध स्पष्ट करणारे योग्य विधान ओळखा.\",\"options\":[\"बाष्पाचे प्रमाण वाढले की ढगांचा आकार लहान होतो.\",\"बाष्पाचे प्रमाण कमी झाले की ढगांचा आकार मोठा होतो.\",\"जमिनीजवळ बाष्प अधिक असल्याने ढग आकाराने मोठे असतात.\",\"उंची वाढली की बाष्प वाढते व ढग मोठे होतात.\"],\"answer\":2,\"explain\":\"जमिनीवर बाष्पाचे प्रमाण अधिक असल्याने कमी उंचीवरील ढग आकाराने मोठे असतात.\",\"topic\":\"ढग व ढगांचे प्रकार\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"एखादा ढग ५००० मीटर उंचीवर तरंगत असल्यास, तो कोणत्या उंचीच्या गटात मोडतो?\",\"options\":[\"अति उच्च उंची\",\"मध्यम उंची\",\"कमी उंची\",\"जमिनीलगतची उंची\"],\"answer\":1,\"explain\":\"२००० ते ७००० मीटर ही मध्यम उंचीची श्रेणी आहे, ज्यामध्ये ५००० मीटरचा समावेश होतो.\",\"topic\":\"ढग व ढगांचे प्रकार\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"वातावरणात ७००० ते १४००० मीटर उंचीच्या दरम्यान आढळणाऱ