loom\":\"analyze\"},{\"q\":\"मध्यम उंचीच्या ढगांची व्याप्ती साधारणपणे किती असते?\",\"options\":[\"७००० ते १४००० मी\",\"२००० ते ७००० मी\",\"५०० ते ६००० मी\",\"२००० मी पेक्षा कमी\"],\"answer\":1,\"explain\":\"२००० ते ७००० मी दरम्यानच्या ढगांना मध्यम उंचीचे ढग म्हणतात.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"लहान लहान लाटांच्या समुदायासारखे दिसणारे ढग कोणते?\",\"options\":[\"सिरस\",\"सिरो स्ट्रॅटस\",\"सिरो क्युम्युलस\",\"अल्टो स्ट्रॅटस\"],\"answer\":2,\"explain\":\"सिरो क्युम्युलस या ढगांचे स्वरूप लहान लहान लाटांच्या समुदायासारखे दिसते.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"जर आकाश आल्हाददायक हवेचा निर्देश करत असेल, तर आकाशात कोणते ढग असण्याची शक्यता जास्त आहे?\",\"options\":[\"निंबो स्ट्रॅटस\",\"क्युम्युलस\",\"अल्टो स्ट्रॅटस\",\"स्ट्रॅटस\"],\"answer\":1,\"explain\":\"क्युम्युलस ढग हे आल्हाददायक हवेचे निर्देशक असतात.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"कोणत्या प्रकारच्या ढगांच्या भोवती \'तेजोमंडल\' (Halo) असते?\",\"options\":[\"सिरो स्ट्रॅटस\",\"अल्टो क्युम्युलस\",\"स्ट्रॅटो क्युम्युलस\",\"सिरस\"],\"answer\":0,\"explain\":\"सिरो स्ट्रॅटस ढग चादरीसारखे दिसतात आणि त्यांच्याभोवती तेजोमंडल असते.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"क्युम्युलस ढगांच्या निर्मितीसाठी खालीलपैकी कोणता घटक महत्त्वाचा ठरतो?\",\"options\":[\"हवेचा क्षितिजसमांतर प्रवाह\",\"हवेचा जोरदार उर्ध्वगामी प्रवाह\",\"अति कमी तापमान\",\"बाष्पाचा अभाव\"],\"answer\":1,\"explain\":\"हवेच्या जोरदार उर्ध्वगामी प्रवाहाचा क्युम्युलस ढगांच्या निर्मितीस हातभार लागतो.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीनुसार, कोणता ढग कमी उंचीपासून सुरू होऊन जास्त उंचीपर्यंत उभा विस्तारलेला दिसतो?\",\"options\":[\"सिरस\",\"अल्टो क्युम्युलस\",\"क्युम्युलस निंबस\",\"स्ट्रॅटस\"],\"answer\":2,\"explain\":\"आकृती ३.८ मध्ये क्युम्युलस निंबस ढग तिन्ही स्तरांत विस्तारलेला दाखवला आहे.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"60\\/031_101.jpg\"},{\"q\":\"दिलेल्या आकृतीचे निरीक्षण करा. \'मध्यम उंचीवरील\' स्तरामध्ये खालीलपैकी कोणता ढग दर्शविला आहे?\",\"options\":[\"सिरो क्युम्युलस\",\"अल्टो क्युम्युलस\",\"स्ट्रॅटो क्युम्युलस\",\"सिरस\"],\"answer\":1,\"explain\":\"आकृती ३.८ मध्ये मध्यम उंचीवरील स्तरामध्ये अल्टो क्युम्युलस व अल्टो स्ट्रॅटस दाखवले आहेत.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"60\\/031_101.jpg\"},{\"q\":\"राखाडी रंग आणि तळाकडील भाग एकसमान असणे हे कोणत्या ढगाचे वैशिष्ट्य आहे?\",\"options\":[\"सिरस\",\"स्ट्रॅटस\",\"क्युम्युलस\",\"अल्टो क्युम्युलस\"],\"answer\":1,\"explain\":\"स्ट्रॅटस ढगांचा रंग राखाडी असतो व तळाकडील भाग एकसमान असतो.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"evaluate\"},{\"q\":\"पांढऱ्या रंगाचे असून त्यात करड्या रंगाच्या छटा असणारे आणि तरंगित रचना असणारे ढग कोणते?\",\"options\":[\"अल्टो क्युम्युलस\",\"निंबो स्ट्रॅटस\",\"सिरो स्ट्रॅटस\",\"स्ट्रॅटस\"],\"answer\":0,\"explain\":\"अल्टो क्युम्युलस ढग पांढऱ्या रंगाचे असून त्यात करड्या छटा व तरंगित रचना असते.\",\"topic\":\"ढगांचे प्रकारांचे सविस्तर वर्णन\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"क्युम्युलो निंबस ढग खालीलपैकी कशाचे निर्देशक आहेत?\",\"options\":[\"शांत हवामान\",\"वादळाचे\",\"दुष्काळाचे\",\"थंडीची लाट\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, क्युम्युलो निंबस हे वैशिष्ट्यपूर्ण ढग वादळाचे निर्देशक आहेत.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"क्युम्युलो निंबस ढगांच्या माथ्याजवळील भाग कसा दिसतो?\",\"options\":[\"पक्षाच्या पंखांसारखा\",\"कापसाच्या गोळ्यासारखा\",\"ऐरणीसारखा सपाट\",\"गोल घुमटाकार\"],\"answer\":2,\"explain\":\"या ढगांच्या माथ्याजवळील भाग ऐरणीसारखा सपाट दिसतो असे पाठात नमूद केले आहे.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"क्युम्युलो निंबस ढगांच्या बाबतीत विद्युत प्रभाराचे कोणते वितरण योग्य आहे?\",\"options\":[\"वरचा भाग ऋण (-) व खालचा भाग धन (+)\",\"वरचा भाग धन (+) व खालचा भाग ऋण (-)\",\"संपूर्ण ढग फक्त धन (+) प्रभारित असतो\",\"संपूर्ण ढग प्रभाररहित असतो\"],\"answer\":1,\"explain\":\"ढगांच्या वरच्या भागात धन (+) व खालच्या बाजूला ऋण (-) प्रभार असतो.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"ढगांच्या गडगडाटाचे मुख्य कारण काय आहे?\",\"options\":[\"ढगांचे एकमेकांवर आदळणे\",\"पावसाच्या थेंबांचा वेग\",\"अतिउष्णतेमुळे हवेचे एकदम प्रसरण पावणे\",\"ढगांमधील पाण्याचे घर्षण\"],\"answer\":2,\"explain\":\"विजेच्या अतिउष्णतेमुळे हवा एकदम प्रसरण पावते, ज्यामुळे मोठा गडगडाट होतो.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"क्युम्युलो निंबस ढगांतून पडणारे पावसाचे थेंब इतर ढगांपेक्षा मोठे का असतात?\",\"options\":[\"ते खूप उंचावरून पडतात म्हणून\",\"ढगात थेंब वारंवार वर-खाली फिरून अधिक पाणी शोषतात म्हणून\",\"ढगातील हवा गरम असते म्हणून\",\"ढगांचा रंग करडा असतो म्हणून\"],\"answer\":1,\"explain\":\"थेंब ढगात खूपदा वर-खाली फिरतात व प्रत्येक वेळी आणखी पाणी शोषल्यामुळे मोठे होतात.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"जर क्युम्युलो निंबस ढगातील हवा अत्यंत थंड असेल, तर पावसाच्या थेंबांचे रूपांतर कशात होते?\",\"options\":[\"धुक्यात\",\"वाफेत\",\"गारांमध्ये\",\"दवात\"],\"answer\":2,\"explain\":\"ढगातील हवा फार थंड असल्यास थेंब गोठतात व गारांच्या स्वरूपात जमिनीवर येतात.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"आकाशात दिसणाऱ्या सर्वात मोठ्या ढगाचे नाव काय आहे?\",\"options\":[\"सिरस\",\"क्युम्युलस\",\"क्युम्युलो निंबस\",\"अल्टो-स्ट्रॅटस\"],\"answer\":2,\"explain\":\"क्युम्युलो निंबस हे आकाशात असणारे सर्वात मोठे ढग आहेत.\",\"topic\":\"क्युम्युलो निंबस ढग\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"क्युम्युलो निंबस ढगांच्या खाली असणारी जमीन कोणत्या प्रभारयुक्त असते?\",\"options\":[\"ऋण (-) प्रभारयुक्त\",\"धन (+) प्रभारयुक्त\",\"प्रभाररहित\",\"चुंबकीय प्रभारयुक्त\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, ढगांच्या खाल