age\":\"60\\/058_101.jpg\"},{\"q\":\"दिलेल्या चित्रात लोक आपले गाव सोडून जाताना दिसत आहेत, ही प्रक्रिया लोकसंख्येच्या कोणत्या घटकाशी संबंधित आहे?\",\"options\":[\"जन्मदर\",\"मृत्यूदर\",\"स्थलांतर\",\"साक्षरता\"],\"answer\":2,\"explain\":\"चित्रात लोक पिशव्या घेऊन बाहेर पडताना दिसत आहेत, जे स्थलांतर दर्शवते.\",\"topic\":\"लोकसंख्या एक संसाधन व विकास\",\"part\":9,\"bloom\":\"understand\",\"figure_image\":\"60\\/057_101.jpg\"},{\"q\":\"दिलेल्या चित्रात शहरांकडे जाणारा लोहचुंबक काय दर्शवतो?\",\"options\":[\"शहरांमधील प्रदूषणाचे आकर्षण\",\"शहरांमधील संधी आणि सोयींचे आकर्षण\",\"शहरांमधील वाढती गुन्हेगारी\",\"शहरांमधील नैसर्गिक आपत्ती\"],\"answer\":1,\"explain\":\"शहरे लोकांना रोजगाराच्या संधी आणि सोयीसुविधांमुळे स्वतःकडे आकर्षित करतात.\",\"topic\":\"लोकसंख्या एक संसाधन व विकास\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"60\\/057_102.jpg\"},{\"q\":\"जर एखाद्या देशात साक्षरतेचे प्रमाण आणि आरोग्य सुविधा उत्तम असतील, तर तिथे कोणत्या प्रकारच्या मनुष्यबळाचा पुरवठा होईल?\",\"options\":[\"केवळ अकुशल मनुष्यबळ\",\"कुशल मनुष्यबळ\",\"फक्त वृद्ध मनुष्यबळ\",\"मनुष्यबळाचा तुटवडा\"],\"answer\":1,\"explain\":\"लोकसंख्येच्या गुणवत्तेनुसार (शिक्षण व आरोग्य) कुशल मनुष्यबळाचा पुरवठा होतो.\",\"topic\":\"लोकसंख्या एक संसाधन व विकास\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"मानवी विकास निर्देशांकात \'आरोग्य\' हा निकष मोजण्यासाठी काय विचारात घेतले जाते?\",\"options\":[\"रुग्णालयांची संख्या\",\"डॉक्टरांची संख्या\",\"अपेक्षित आयुर्मान\",\"औषधांचा वापर\"],\"answer\":2,\"explain\":\"आरोग्यासाठी \'अपेक्षित आयुर्मान\' हा निकष मानला जातो.\",\"topic\":\"लोकसंख्या एक संसाधन व विकास\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"बरीच दशके एखाद्या देशाचा विकास मोजण्यासाठी कोणते परिमाण वापरले जात असे?\",\"options\":[\"साक्षरता प्रमाण\",\"लिंग गुणोत्तर\",\"स्थूल राष्ट्रीय उत्पन्न\",\"लोकसंख्या वाढ\"],\"answer\":2,\"explain\":\"पूर्वी विकास फक्त स्थूल राष्ट्रीय उत्पन्नावरून (GNP) मोजला जायचा.\",\"topic\":\"लोकसंख्या एक संसाधन व विकास\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"\'वृद्धी म्हणजे विकास