},{\"q\":\"जमिनीवरील प्रत्यक्ष अंतर व नकाशातील अंतर यांच्या गुणोत्तराला काय म्हणतात?\",\"options\":[\"नकाशा आराखडा\",\"नकाशाप्रमाण\",\"नकाशाचे शीर्षक\",\"नकाशाची दिशा\"],\"answer\":1,\"explain\":\"जमिनीवरील प्रत्यक्ष अंतर व नकाशातील अंतर यांचे गुणोत्तर म्हणजे नकाशाप्रमाण होय.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"नकाशाप्रमाणे व्यक्त करण्याचे एकूण किती प्रकार पाठात दिले आहेत?\",\"options\":[\"दोन\",\"चार\",\"पाच\",\"तीन\"],\"answer\":3,\"explain\":\"नकाशाप्रमाणे व्यक्त करण्याचे शब्दप्रमाण, अंकप्रमाण आणि रेषाप्रमाण असे तीन प्रकार आहेत.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"नकाशा तयार करण्यासाठी जमिनीवरील प्रत्यक्ष अंतर माहीत असणे का आवश्यक असते?\",\"options\":[\"नकाशा रंगवण्यासाठी\",\"प्रमाणानुसार नकाशा काढण्यासाठी\",\"नकाशाचे नाव ठरवण्यासाठी\",\"नकाशाची छपाई करण्यासाठी\"],\"answer\":1,\"explain\":\"प्रमाणानुसार नकाशा काढण्यासाठी जमिनीवरील प्रत्यक्ष अंतर माहीत असणे आवश्यक असते.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"\'१ सेमी = १० किमी\' हे कोणत्या प्रकारचे नकाशाप्रमाण आहे?\",\"options\":[\"अंकप्रमाण\",\"रेषाप्रमाण\",\"शब्दप्रमाण\",\"प्रतिनिधिक अपूर्णांक\"],\"answer\":2,\"explain\":\"ज्या प्रमाणात अंतरासाठी परिमाणदर्शक शब्द वापरले जातात, त्याला शब्दप्रमाण म्हणतात.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"अंकप्रमाणाला खालीलपैकी दुसरे नाव काय आहे?\",\"options\":[\"शब्दप्रमाण\",\"प्रतिनिधिक अपूर्णांक\",\"आलेखात्मक प्रमाण\",\"रेषाप्रमाण\"],\"answer\":1,\"explain\":\"अंकप्रमाणास \'प्रतिनिधिक अपूर्णांक\' असेही म्हणतात.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर नकाशाप्रमाण १ सेमी = १० किमी असेल आणि दोन गावांमधील प्रत्यक्ष अंतर ५० किमी असेल, तर नकाशात ते अंतर किती दिसेल?\",\"options\":[\"५ सेमी\",\"१० सेमी\",\"५० सेमी\",\"१ सेमी\"],\"answer\":0,\"explain\":\"१ सेमी = १० किमी, म्हणून ५० किमी = ५ सेमी (५०\\/१०).\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अंकप्रमाणात (उदा. १ : ६०,००,०००) डाव्या बाजूचा अंक काय दर्शवतो?\",\"options\":[\"जमिनीवरील अंतर\",\"नकाशावरील अंतर\",\"गावांची संख्या\",\"समुद्रसपाटीपासूनची उंची\"],\"answer\":1,\"explain\":\"अंकप्रमाणात गुणोत्तराच्या डाव्या बाजूचा अंक नकाशावरील अंतर दर्शवतो.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"नकाशावर पट्टी उपलब्ध नसेल, तर रेषाप्रमाणाच्या साहाय्याने अंतर मोजण्यासाठी कशाचा वापर करता येतो?\",\"options\":[\"पेन्सिलचा\",\"केवळ डोळ्यांचा अंदाज\",\"धाग्याचा\",\"रंगीत खडूचा\"],\"answer\":2,\"explain\":\"पट्टी उपलब्ध नसेल तर धागा किंवा कंपासचा वापर करून रेषाप्रमाणाद्वारे अंतर मोजता येते.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"अंकप्रमाणाचे (१ : ६०,००,०००) मुख्य वैशिष्ट्य कोणते?\",\"options\":[\"यात फक्त शब्दांचा वापर होतो\",\"यात परिमाणदर्शक शब्द लिहिता येत नाहीत\",\"यात दोन्ही बाजूंची एकके वेगवेगळी असतात\",\"हे प्रमाण फक्त भारतातच वापरले जाते\"],\"answer\":1,\"explain\":\"अंकप्रमाणात परिमाणदर्शक शब्द लिहिता येत नाहीत, ते केवळ गुणोत्तराच्या स्वरूपात असते.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"जमिनीवरील अंतर मोजण्यासाठी सर्वेक्षण केव्हा केले जाते?\",\"options\":[\"नकाशा तयार केल्यानंतर\",\"नकाशा वाचताना\",\"नकाशा तयार करण्यापूर्वी\",\"नकाशाचे प्रमाण ठरवल्यानंतर\"],\"answer\":2,\"explain\":\"नकाशा तयार करण्यासाठी आवश्यक असलेले जमिनीवरील अंतर सर्वेक्षण करताना मोजले जाते.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर शब्दप्रमाण १ सेमी = ६० किमी असेल, तर त्याचे अंकप्रमाण किती होईल? (टीप: १ किमी = १,००,००० सेमी)\",\"options\":[\"१ : ६०\",\"१ : ६,०००\",\"१ : ६०,००,०००\",\"१ : ६००\"],\"answer\":2,\"explain\":\"६० किमी = ६०,००,००० सेमी, म्हणून अंकप्रमाण १ : ६०,००,००० होईल.\",\"topic\":\"नकाशाप्रमाणाचे प्रकार\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"नकाशात प्रमाणाची नोंद करणे का आवश्यक असते?\",\"options\":[\"नकाशा सुंदर दिसण्यासाठी\",\"नकाशाचे वाचन करणे व प्रत्यक्ष अंतर समजणे सोईचे होण्या