\":10,\"bloom\":\"apply\"},{\"q\":\"शिखांनी इंग्रजांवर हल्ला करण्याचे मुख्य कारण काय होते?\",\"options\":[\"इंग्रजांनी पंजाबवर प्रत्यक्ष आक्रमण केले होते.\",\"इंग्रज पंजाबवर आक्रमण करणार असा शिखांचा समज झाला.\",\"मुलराजने शिखांना युद्धासाठी प्रवृत्त केले.\",\"रणजितसिंगांनी युद्धाची तयारी केली होती.\"],\"answer\":1,\"explain\":\"इंग्रज पंजाबवर आक्रमण करणार असा शिखांचा समज झाल्यामुळे त्यांनी स्वतःहून हल्ला केला.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"पहिल्या शीख-इंग्रज युद्धाचा परिणाम काय झाला?\",\"options\":[\"शिखांचा विजय झाला.\",\"इंग्रजांनी दलीपसिंगाला गादीवरून हटवले.\",\"या युद्धात शिखांचा पराभव झाला.\",\"इंग्रजांनी १८४५ मध्येच पंजाब खालसा केला.\"],\"answer\":2,\"explain\":\"पहिल्या शीख-इंग्रज युद्धात शिखांचा पराभव झाला, पण दलीपसिंगाला गादीवर कायम ठेवले गेले.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या चित्रातील व्यक्तीच्या काळात पंजाबमधील सत्तेची स्थिती कशी होती?\",\"options\":[\"इंग्रजांनी पंजाबवर पूर्ण ताबा मिळवला होता.\",\"पंजाबमधील सत्ता प्रबळ आणि संघटित होती.\",\"मुलराजने इंग्रजांविरुद्ध बंड केले होते.\",\"राणी जिंदान राज्याचा कारभार पाहत होती.\"],\"answer\":1,\"explain\":\"रणजितसिंगांच्या काळात पंजाबची सत्ता त्यांच्या हाती सुरक्षित होती, त्यांच्या मृत्यूनंतरच अस्थिरता निर्माण झाली.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"understand\",\"figure_image\":\"62\\/018_101.jpg\"},{\"q\":\"इंग्रजांविरुद्ध बंड करणारा मुलराज हा कोणत्या ठिकाणचा अधिकारी होता?\",\"options\":[\"लाहोर\",\"अमृतसर\",\"मुलतान\",\"पतियाळा\"],\"answer\":2,\"explain\":\"मुलतानचा अधिकारी मुलराज याने इंग्रजांविरुद्ध बंड केले होते.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"दुसऱ्या शीख-इंग्रज युद्धाचे मूळ कारण खालीलपैकी कोणते असू शकते?\",\"options\":[\"इंग्रजांनी दलीपसिंगाला गादीवरून काढले होते.\",\"पंजाबवरील इंग्रजांचा वाढता प्रभाव शिखांना मान्य नव्हता.\",\"रणजितसिंगांनी इंग्रजांशी मैत्री तोडली होती.\",\"मराठ्यांनी शिखांना मदतीचे आश्वासन दिले होते.\"],\"answer\":1,\"explain\":\"पंजाबवरील इंग्रजांचा वाढता प्रभाव काही स्वाभिमानी शिखांना मान्य नसल्यामुळे दुसरे युद्ध झाले.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"इंग्रजांनी पंजाबचा प्रदेश आपल्या राज्याला कोणत्या वर्षी जोडला?\",\"options\":[\"१८४५\",\"१८४७\",\"१८४८\",\"१८४९\"],\"answer\":3,\"explain\":\"दुसऱ्या युद्धात शिखांचा पराभव झाल्यानंतर १८४९ मध्ये इंग्रजांनी पंजाब आपल्या राज्याला जोडला.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"शीख सत्तेचा पाडाव झाल्यानंतर इंग्रजांनी भारतातील आपला पाया मजबूत करण्यासाठी कोणाचा पराभव करणे आवश्यक होते?\",\"options\":[\"मुघलांचा\",\"मराठ्यांचा\",\"निजामाचा\",\"पोर्तुगीजांचा\"],\"answer\":1,\"explain\":\"मराठ्यांची सत्ता ही भारतातील महत्त्वाची प्रबळ सत्ता होती, जिचा पराभव करणे इंग्रजांसाठी आवश्यक होते.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"शीख सत्तेच्या ऱ्हासाच्या घटनांचा योग्य क्रम कोणता?\",\"options\":[\"रणजितसिंगाचा मृत्यू -> राणी जिंदानचा कारभार -> पहिले शीख-इंग्रज युद्ध -> पंजाबचे विलीनीकरण\",\"पहिले शीख-इंग्रज युद्ध -> रणजितसिंगाचा मृत्यू -> मुलराजचे बंड -> पंजाबचे विलीनीकरण\",\"मुलराजचे बंड -> पहिले शीख-इंग्रज युद्ध -> रणजितसिंगाचा मृत्यू -> पंजाबचे विलीनीकरण\",\"पंजाबचे विलीनीकरण -> दुसरे शीख-इंग्रज युद्ध -> राणी जिंदानचा कारभार -> रणजितसिंगाचा मृत्यू\"],\"answer\":0,\"explain\":\"रणजितसिंगांच्या मृत्यूनंतर राणी जिंदानकडे कारभार आला, त्यानंतर दोन युद्धे झाली आणि शेवटी पंजाब इंग्रज साम्राज्यात विलीन झाले.\",\"topic\":\"शीख सत्तेचा पाडाव\",\"part\":10,\"bloom\":\"analyze\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29');
INSERT INTO `ep_topic_packs` VALUES (22201,62,8,'History & Civics','mr','ब्रिटिश सत्तेचे परिणाम','[\"ब्रिटिश सत्तेची सुरुवात १७५७ मध्ये क्लाइव्हच्या विजयाने झाली.\",\"इंग्रजी ईस्ट इंडिया कंपनीने १७६५ मध्ये बंगालमध्ये दुहेरी नोकरशाही सुरू केली.\",\"दुहेरी नोकरशाही म्हणजे कंपनीचे अधिकारी व ब्रिटिश सरकारचे अधिकारी दोघेही एकाच प्रदेशात काम करतात.\",\"कंपनीने महसूल गोळा करण्यासाठी ‘जमीन महसूल पद्धती’ लागू केली.\",\"या पद्धतीने शेतकऱ्यांना ‘शेतसारा’ द्यावा लागे, ज्यामुळे शोषण वाढले.\",\"शेतसारा भरण्यासाठी शेतकरी पिके विकायला भाग पाडले गेले.\",\"इंग्रजी आर्थिक धोरणाने भारतात कापूस, तंबाखू, चहा यांसारखी नगदी पिके प्रोत्साहित केली.\",\"या पिकांच्या लागवडीमुळे पारंपरिक उद्योगधंदे मागे पडले.\",\"इंग्रजी वाहतूक व दळणवळण सुधारणांनी रेल्वे, डाक व्यवस्था सुरू केली.\",\"मुलकी नोकरशाहीने भारतीयांना कमी पगार व भत्ते दिले, ज्यामुळे असंतोष वाढला.\",\"शेतकऱ्यांना कर्जबाजारी होण्यास भाग पाडले गेले.\",\"सामाजिक सुधारणा म्हणून सतीबंदी व विधवा पुनर्विवाह कायदे लागू झाले.\",\"इंग्रजी शिक्षणाने इंग्रजी व विज्ञानाची ओळख करून दिली.\",\"१८५७ चा स्वातंत्र्यलढा इंग्रजी सत्तेविरुद्धचा पहिला मोठा उठाव होता.\",\"लढ्यानंतर ब्रिटिशांनी भारतात ‘सामान्य कायदा’ लागू केला.\",\"इंग्रजी सत्तेने भारतीय राजवटीत बदल घडवून आणले.\",\"इंग्रजी सत्तेने भारतीय समाजात पाश्चात्त्य विचारांचा प्रसार केला.\",\"इंग्रजी सत्तेने भारतीय राजकीय व सामाजिक जीवनावर दीर्घकालीन परिणाम केला.\",\"इंग्रजी सत्तेच्या समाप्तीने भारतीय स्वातंत्र्य चळवळीला चालना मिळाली.\",\"ब्रिटिश सत्तेच्या समाप्तीनंतर भारताने १९४७ मध्ये स्वातंत्र्य मिळवले.\"]','[{\"q\":\"इंग्रज भारतात व्यापाराच्या निमित्ताने आले तेव्हा भारतात आधीच कोणती युरोपीय सत्ता होती?\",\"options\":[\"फ्रेंच\",\"डच\",\"पोर्तुगीज\",\"जर्मन\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे, इंग्रज आले तेव्हा पोर्तुगिजांचा त्यांना कडवा विरोध झाला कारण ते आधीच तिथे होते.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"युरोपीय सत्ता भारताच्या किनाऱ्यावर कशामुळे येऊन पोहोचल्या?\",\"options\":[\"औद्योगिक क्रांतीमुळे\",\"भौगोलिक शोधांमुळे\",\"स्थानिक राजांच्या निमंत्रणामुळे\",\"युद्धाच्या भीतीमुळे\"],\"answer\":1,\"explain\":\"पाठाच्या सुरुवातीलाच म्हटले आहे की भौगोलिक शोधांमुळे युरोपीय सत्ता भारताच्या किनाऱ्यावर पोहोचल्या.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इंग्रजांना सुरुवातीच्या काळात कोणाच्या कडव्या विरोधाला तोंड द्यावे लागले?\",\"options\":[\"पोर्तुगीज\",\"फ्रेंच\",\"डच\",\"स्थानिक सत्ताधीश\"],\"answer\":0,\"explain\":\"इंग्रज भारतात आले तेव्हा आधीच असलेल्या पोर्तुगिजांनी त्यांना कडवा विरोध केला.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"नंतरच्या काळात इंग्रज आणि पोर्तुगीज यांच्यातील संबंध कसे झाले?\",\"options\":[\"शत्रुत्वाचे\",\"मैत्रीचे\",\"उदासीन\",\"तणावाचे\"],\"answer\":1,\"explain\":\"उताऱ्यात दिले आहे की नंतरच्या काळात इंग्रज-पोर्तुगीज संबंध मैत्रीचे होऊन विरोध कमी झाला.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"भारतावर वर्चस्व प्रस्थापित करण्याच्या स्पर्धेत इंग्रजांना कोणाच्या विरोधाला तोंड द्यावे लागले नाही?\",\"options\":[\"फ्रेंच\",\"डच\",\"स्थानिक सत्ताधीश\",\"अमेरिकन\"],\"answer\":3,\"explain\":\"उताऱ्यात फ्रेंच, डच आणि स्थानिक सत्ताधीशांचा उल्लेख आहे, अमेरिकन सत्तेचा नाही.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"युरोपीय सत्तांमध्ये भारताबाबत कोणती स्पर्धा सुरू होती?\",\"options\":[\"धार्मिक प्रसाराची\",\"बाजारपेठ काबीज करण्याची\",\"शेती सुधारण्याची\",\"शिक्षण देण्याची\"],\"answer\":1,\"explain\":\"सर्व युरोपीय सत्ता भारताची बाजारपेठ काबीज करण्याच्या सत्तास्पर्धेत उतरल्या होत्या.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"इंग्रज भारतात कोणत्या मुख्य उद्देशाने आले होते?\",\"options\":[\"राज्य करण्यासाठी\",\"प्रवास करण्यासाठी\",\"व्यापाराच्या निमित्ताने\",\"धर्मप्रसारासाठी\"],\"answer\":2,\"explain\":\"इंग्रज भारतात व्यापाराच्या निमित्ताने आले असे उताऱ्यात स्पष्ट केले आहे.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"जर एखादी युरोपीय सत्ता भारतावर वर्चस्व मिळवू पाहत असेल, तर तिला उताऱ्यानुसार कोणाशी संघर्ष करावा लागला असता?\",\"options\":[\"केवळ इतर युरोपीय सत्तांशी\",\"केवळ स्थानिक सत्ताधीशांशी\",\"युरोपीय सत्ता आणि स्थानिक सत्ताधीश या दोघांशी\",\"केवळ पोर्तुगिजांशी\"],\"answer\":2,\"explain\":\"इंग्रजांना फ्रेंच, डच आणि स्थानिक सत्ताधीश अशा सर्वांच्या विरोधाला तोंड द्यावे लागले.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणत्या युरोपीय सत्तेचा उल्लेख बाजारपेठ काबीज करण्याच्या स्पर्धेत उताऱ्यात आलेला नाही?\",\"options\":[\"डच\",\"स्पॅनिश\",\"फ्रेंच\",\"पोर्तुगीज\"],\"answer\":1,\"explain\":\"उताऱ्यात पोर्तुगीज, डच, फ्रेंच आणि ब्रिटिश यांचा उल्लेख आहे, स्पॅनिशचा नाही.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"इंग्रजांच्या भारतातील सुरुवातीच्या संघर्षाचे स्वरूप कसे होते?\",\"options\":[\"सुरुवातीला पोर्तुगिजांशी विरोध आणि नंतर इतर सत्तांशी स्पर्धा\",\"सुरुवातीला सर्वांशी मैत्री आणि नंतर युद्ध\",\"केवळ स्थानिक लोकांशी संघर्ष\",\"सुरुवातीलाच सर्व युरोपीय सत्तांशी मैत्री\"],\"answer\":0,\"explain\":\"इंग्रजांना आधी पोर्तुगिजांचा विरोध झाला आणि नंतर वर्चस्वासाठी इतरांशी स्पर्धा करावी लागली.\",\"topic\":\"ब्रिटिश ईस्ट इंडिया कंपनीची स्थापना\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"पश्चिम भारतातील इंग्रजांचे प्रमुख केंद्र कोणते होते?\",\"options\":[\"पुणे\",\"मुंबई\",\"सुरत\",\"सातारा\"],\"answer\":1,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की मुंबई हे इंग्रजांचे पश्चिम भारतातील प्रमुख केंद्र होते.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"माधवराव पेशवे यांच्या मृत्यूनंतर कोणी पेशवेपदाच्या लालसेपोटी इंग्रजांची मदत मागितली?\",\"options\":[\"नाना फडणवीस\",\"सवाई माधवराव\",\"रघुनाथराव\",\"बाजीराव\"],\"answer\":2,\"explain\":\"माधवराव पेशव्यांच्या मृत्यूनंतर त्यांचा चुलता रघुनाथरावाने इंग्रजांची मदत मागितली.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"मराठ्यांच्या राजकारणात इंग्रजांचा शिरकाव होण्याचे मुख्य कारण काय होते?\",\"options\":[\"मराठ्यांची कमकुवत सैन्यशक्ती\",\"रघुनाथरावाने पेशवेपदासाठी मागितलेली इंग्रजांची मदत\",\"मुंबईवर झालेला इंग्रजांचा हल्ला\",\"सालबाईचा तह\"],\"answer\":1,\"explain\":\"रघुनाथरावाने पेशवेपदाच्या लालसेपोटी इंग्रजांची मदत मागितल्यामुळे त्यांचा शिरकाव झाला.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"१७७४ ते १८१८ या दरम्यान मराठे व इंग्रज यांच्यात एकूण किती युद्धे झाली?\",\"options\":[\"दोन\",\"तीन\",\"चार\",\"पाच\"],\"answer\":1,\"explain\":\"उताऱ्यातील माहितीनुसार, १७७४ ते १८१८ या काळात मराठे व इंग्रज यांच्यात तीन युद्धे झाली.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"पहिल्या इंग्रज-मराठा युद्धात मराठ्यांची सरशी होण्याचे मुख्य कारण काय होते?\",\"options\":[\"इंग्रजांकडे आधुनिक शस्त्रे नव्हती\",\"मराठा सरदारांनी एकजुटीने दिलेला लढा\",\"रघुनाथरावाने मराठ्यांना केलेली मदत\",\"सालबाईचा तह आधीच झाला होता\"],\"answer\":1,\"explain\":\"मराठा सरदारांनी एकजुटीने इंग्रजांना तोंड दिल्यामुळे पहिल्या युद्धात मराठ्यांची सरशी झाली.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"पहिले इंग्रज-मराठा युद्ध कोणत्या तहाने संपले?\",\"options\":[\"पुणे तह\",\"मुंबई तह\",\"सालबाईचा तह\",\"सुरत तह\"],\"answer\":2,\"explain\":\"१७८२ साली सालबाईचा तह होऊन पहिले इंग्रज-मराठा युद्ध संपले.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"remember\"},{\"q\":\"इंग्रजांना मुंबईच्या जवळपासचा प्रदेश मिळवण्यात सुरुवातीला कोणती अडचण होती?\",\"options\":[\"तिथे खूप घनदाट जंगल होते\",\"मराठ्यांची त्या प्रदेशावर घट्ट पकड होती\",\"इंग्रजांकडे पुरेसे नौदल नव्हते\",\"पोर्तुगीजांनी तो प्रदेश अडवून धरला होता\"],\"answer\":1,\"explain\":\"मुंबईच्या जवळपासच्या प्रदेशावर मराठ्यांची घट्ट पकड असल्याने इंग्रजांना तो मिळवणे कठीण जात होते.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"जर एखादा इतिहासकार १७८२ सालातील मराठा-इंग्रज संबंधांचा अभ्यास करत असेल, तर तो कोणत्या घटनेचा संदर्भ घेईल?\",\"options\":[\"मुंबई केंद्राची स्थापना\",\"सालबाईचा तह\",\"माधवराव पेशव्यांचा मृत्यू\",\"रघुनाथरावाचा पेशवेपदाचा त्याग\"],\"answer\":1,\"explain\":\"१७८२ हे वर्ष सालबाईच्या तहासाठी प्रसिद्ध आहे, ज्याने पहिले युद्ध संपले.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"रघुनाथरावाच्या कृतीचा मराठा साम्राज्यावर कोणता दीर्घकालीन परिणाम झाला?\",\"options\":[\"मराठ्यांनी मुंबईवर ताबा मिळवला\",\"इंग्रजांचा मराठ्यांच्या अंतर्गत राजकारणात शिरकाव झाला\",\"मराठा सरदारांनी रघुनाथरावाला पाठिंबा दिला\",\"इंग्रजांनी पश्चिम भारत सोडून दिला\"],\"answer\":1,\"explain\":\"रघुनाथरावाच्या मदतीच्या मागणीमुळे इंग्रजांना मराठ्यांच्या राजकारणात हस्तक्षेप करण्याची संधी मिळाली.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"उताऱ्याच्या आधारे, पहिल्या इंग्रज-मराठा युद्धाचा निष्कर्ष काय होता?\",\"options\":[\"इंग्रजांनी मराठ्यांचा पूर्ण पराभव केला\",\"मराठ्यांनी एकजुटीने लढा देऊन सरशी मिळवली\",\"रघुनाथराव पेशवे बनले\",\"मुंबई मराठ्यांच्या ताब्यात आली\"],\"answer\":1,\"explain\":\"पहिल्या युद्धात मराठा सरदारांच्या एकजुटीमुळे मराठ्यांची सरशी झाली असा उल्लेख आहे.\",\"topic\":\"इंग्रज व मराठे\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"१७९८ मध्ये गव्हर्नर जनरल म्हणून भारतात कोण आले?\",\"options\":[\"लॉर्ड डलहौसी\",\"लॉर्ड वेलस्ली\",\"लॉर्ड कर्झन\",\"लॉर्ड माउंटबॅटन\"],\"answer\":1,\"explain\":\"पाठातील माहितीनुसार, १७९८ मध्ये लॉर्ड वेलस्ली गव्हर्नर जनरल म्हणून भारतात आला.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"लॉर्ड वेलस्लीने भारतात \'तैनाती फौज\' ही पद्धत का सुरू केली?\",\"options\":[\"भारतीय सत्ताधीशांना मदत करण्यासाठी\",\"मुघलांना हरवण्यासाठी\",\"सर्व भारतावर इंग्रजांचे वर्चस्व प्रस्थापित करण्यासाठी\",\"मराठा सरदारांना एकत्र करण्यासाठी\"],\"answer\":2,\"explain\":\"सर्व भारतावर इंग्रजांचे वर्चस्व प्रस्थापित करण्याचे वेलस्लीचे धोरण होते, त्यासाठी त्याने तैनाती फौज सुरू केली.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तैनाती फौजेच्या करारातील अटीनुसार, भारतीय राज्यकर्त्यांनी त्यांच्या दरबारी कोणाला ठेवणे बंधनकारक होते?\",\"options\":[\"इंग्रज सैन्यप्रमुख\",\"इंग्रजांचा रेसिडेंट (प्रतिनिधी)\",\"मुघल बादशहाचा दूत\",\"पेशव्यांचा वकील\"],\"answer\":1,\"explain\":\"कराराच्या अटीनुसार भारतीय सत्ताधीशांनी आपल्या दरबारी इंग्रजांचा रेसिडेंट (प्रतिनिधी) ठेवणे आवश्यक होते.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"तैनाती फौजेच्या लष्कराच्या खर्चासाठी भारतीय राज्यकर्त्यांना काय करावे लागत असे?\",\"options\":[\"इंग्रजांना सोन्याची नाणी द्यावी लागत\",\"इंग्रजांना कर माफ करावा लागत असे\",\"रोख रक्कम किंवा तेवढ्या उत्पन्नाचा प्रदेश कंपनीला तोडून द्यावा लागत असे\",\"इंग्रजांना व्यापारात सवलती द्याव्या लागत असत\"],\"answer\":2,\"explain\":\"लष्कराच्या खर्चासाठी रोख रक्कम किंवा तेवढ्या उत्पन्नाचा प्रदेश कंपनीला तोडून देण्याची अट होती.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"१८०२ मध्ये कोणत्या पेशव्याने इंग्रजांशी तैनाती फौजेचा करार केला?\",\"options\":[\"पहिला बाजीराव पेशवा\",\"माधवराव पेशवा\",\"दुसरा बाजीराव पेशवा\",\"नानासाहेब पेशवा\"],\"answer\":2,\"explain\":\"१८०२ मध्ये दुसऱ्या बाजीराव पेशव्याने इंग्रजांशी तैनाती फौजेचा करार केला.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दुसऱ्या बाजीराव पेशव्याने इंग्रजांशी केलेल्या तैनाती फौजेच्या कराराला कोणत्या नावाने ओळखले जाते?\",\"options\":[\"पुण्याचा तह\",\"वसईचा तह\",\"सालबायचा तह\",\"पुरंदरचा तह\"],\"answer\":1,\"explain\":\"१८०२ मधील दुसऱ्या बाजीरावाचा करार \'वसईचा तह\' म्हणून प्रसिद्ध आहे.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"remember\"},{\"q\":\"दुसरे इंग्रज-मराठा युद्ध होण्याचे मुख्य कारण काय होते?\",\"options\":[\"इंग्रजांनी दिल्लीवर हल्ला केला\",\"वसईचा तह काही मराठा सरदारांना मान्य नव्हता\",\"पेशव्यांनी इंग्रजांना खंडणी दिली नाही\",\"मुघल बादशहाने इंग्रजांशी हातमिळवणी केली\"],\"answer\":1,\"explain\":\"वसईचा तह काही मराठा सरदारांना मान्य नसल्यामुळे दुसरे इंग्रज-मराठा युद्ध झाले.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"तैनाती फौजेचा करार स्वीकारलेल्या सत्ताधीशांवर कोणता परिणाम झाला?\",\"options\":[\"त्यांचे राज्य अधिक विस्तारले\",\"त्यांना मुघलांचे संरक्षण मिळाले\",\"त्यांनी आपले स्वातंत्र्य गमावले\",\"त्यांना इंग्रजांकडून मोठी संपत्ती मिळाली\"],\"answer\":2,\"explain\":\"भारतातील काही सत्ताधीशांनी ही पद्धत स्वीकारली व आपले स्वातंत्र्य गमावले असे पाठात नमूद आहे.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"analyze\"},{\"q\":\"दुसऱ्या बाजीराव पेशव्याने १८१८ मध्ये इंग्रजांसमोर शरणागती का पत्करली?\",\"options\":[\"त्याला दिल्लीचा बादशहा बनायचे होते\",\"इंग्रजांविरुद्धच्या युद्धात त्याचा पराभव झाला\",\"मराठा सरदारांनी त्याला पाठिंबा दिला नाही\",\"त्याला तैनाती फौज मान्य नव्हती\"],\"answer\":1,\"explain\":\"इंग्रजांविरुद्ध पुकारलेल्या युद्धात पराभव झाल्यामुळे १८१८ मध्ये त्याने शरणागती पत्करली.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"understand\"},{\"q\":\"जर एखाद्या राजाने तैनाती फौज स्वीकारली असेल आणि त्याला शेजारील राज्याशी बोलणी करायची असतील, तर तो ती कशी करू शकत असे?\",\"options\":[\"थेट पत्रव्यवहार करून\",\"मुघल बादशहाच्या परवानगीने\",\"केवळ इंग्रजांच्या मध्यस्थीनेच\",\"स्वतःच्या मंत्र्यांच्या सल्ल्याने\"],\"answer\":2,\"explain\":\"कराराच्या अटीनुसार इतर सत्ताधीशांशी इंग्रजांच्या मध्यस्थीनेच संबंध ठेवणे बंधनकारक होते.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"जनरल लेक याने मुघल बादशहाला ताब्यात घेण्यासाठी कोणाच्या फौजेचा पराभव केला?\",\"options\":[\"दुसरा बाजीराव पेशवा\",\"नाना फडणवीस\",\"दौलतराव शिंदे\",\"हैदर अली\"],\"answer\":2,\"explain\":\"मुघलांची राजधानी दिल्ली दौलतराव शिंदे यांच्या नियंत्रणाखाली होती, त्यांच्या फौजेचा पराभव करून जनरल लेकने बादशहाला ताब्यात घेतले.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"apply\"},{\"q\":\"दुसऱ्या बाजीरावाने इंग्रजांविरुद्ध युद्ध पुकारण्याचे नेमके कारण काय होते?\",\"options\":[\"इंग्रजांनी वसईचा तह मोडला\",\"इंग्रजांचा मराठी राज्यातील हस्तक्षेप असह्य झाला\",\"त्याला मुघलांना मदत करायची होती\",\"इंग्रजांनी रेसिडेंटला परत बोलावले\"],\"answer\":1,\"explain\":\"इंग्रजांचा मराठी राज्यातील हस्तक्षेप असह्य होऊन दुसऱ्या बाजीरावाने इंग्रजांविरुद्ध युद्ध पुकारले.\",\"topic\":\"तैनाती फौज\",\"part\":4,\"bloom\":\"evaluate\"},{\"q\":\"इंग्रजांनी छत्रपती प्रतापसिंहांच्या राज्यकारभारात मदत करण्यासाठी कोणत्या अधिकाऱ्याची नेमणूक केली होती?\",\"options\":[\"लॉर्ड डलहौसी\",\"ग्रँड डफ\",\"रंगो बापूजी\",\"माउंट स्टुअर्ट एल्फिन्स्टन\"],\"answer\":1,\"explain\":\"मजकुरानुसार, इंग्रजांनी ग्रँड डफ या अधिकाऱ्याची नेमणूक छत्रपती प्रतापसिंहांच्या मदतीसाठी केली होती.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"छत्रपती प्रतापसिंहांच्या कारभारी रंगो बापूजी गुप्ते यांनी इंग्लंडला जाऊन काय करण्याचा प्रयत्न केला?\",\"options\":[\"नवीन तह करण्यासाठी\",\"इंग्रजी शिक्षण घेण्यासाठी\",\"अन्यायाविरुद्ध दाद मागण्यासाठी\",\"व्यापारासाठी परवानगी मिळवण्यासाठी\"],\"answer\":2,\"explain\":\"रंगो बापूजी गुप्ते यांनी छत्रपतींवर झालेल्या अन्यायाविरुद्ध दाद मागण्यासाठी इंग्लंडपर्यंत प्रवास केला.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"छत्रपती प्रतापसिंहांचा मृत्यू कोणत्या वर्षी झाला?\",\"options\":[\"१८४८\",\"१८१८\",\"१८४७\",\"१८५७\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्टपणे नमूद केले आहे की १८४७ मध्ये काशी येथे त्यांचा मृत्यू झाला.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"लॉर्ड डलहौसीने १८४८ मध्ये सातारचे राज्य खालसा करण्याचे मुख्य कारण काय होते?\",\"options\":[\"छत्रपतींचा मृत्यू झाला म्हणून\",\"दत्तकविधान नामंजूर केल्यामुळे\",\"प्रतापसिंहांच्या कारभारातील त्रुटींमुळे\",\"रंगो बापूजींच्या इंग्लंड दौऱ्यामुळे\"],\"answer\":1,\"explain\":\"लॉर्ड डलहौसीने दत्तकविधान नामंजूर करून सातारचे राज्य खालसा केले.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"analyze\"},{\"q\":\"पेशवाईचा अस्त झाल्यानंतरही कोणत्या ठिकाणचे छत्रपती गादीवर होते?\",\"options\":[\"कोल्हापूर\",\"सातारा\",\"पुणे\",\"नागपूर\"],\"answer\":1,\"explain\":\"पेशवाईचा अस्त झाला तरी सातारचे छत्रपती प्रतापसिंह गादीवर होते असे मजकूर सांगतो.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"remember\"},{\"q\":\"रंगो बापूजी गुप्ते यांच्या न्याय मिळवण्याच्या प्रयत्नांचे काय झाले?\",\"options\":[\"त्यांना पूर्ण यश मिळाले\",\"इंग्रजांनी त्यांचे म्हणणे मान्य केले\",\"त्यांच्या प्रयत्नांना यश आले नाही\",\"त्यांना भारतात परत पाठवण्यात आले\"],\"answer\":2,\"explain\":\"मजकुरानुसार, रंगो बापूजी गुप्ते यांच्या न्याय मिळवण्याच्या प्रयत्नांना यश आले नाही.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"understand\"},{\"q\":\"जर लॉर्ड डलहौसीने दत्तकविधान मंजूर केले असते, तर मजकुरानुसार १८४८ मध्ये कोणती घटना टळली असती?\",\"options\":[\"छत्रपतींचा मृत्यू\",\"ग्रँड डफची नेमणूक\",\"सातारचे राज्य खालसा होणे\",\"पेशवाईचा अस्त\"],\"answer\":2,\"explain\":\"दत्तकविधान नामंजूर केल्यामुळेच राज्य खालसा झाले, त्यामुळे ते मंजूर झाले असते तर राज्य खालसा झाले नसते.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"छत्रपती प्रतापसिंहांच्या संदर्भात खालीलपैकी कोणता घटनाक्रम योग्य आहे?\",\"options\":[\"राज्य खालसा -> काशीला रवानगी -> मृत्यू\",\"नेमणूक -> इंग्लंड दौरा -> पदच्युती\",\"तह -> पदच्युती -> काशी येथे मृत्यू\",\"मृत्यू -> पदच्युती -> दत्तकविधान\"],\"answer\":2,\"explain\":\"प्रथम इंग्रजांशी तह झाला, नंतर त्यांना पदच्युत केले गेले आणि शेवटी काशी येथे त्यांचा मृत्यू झाला.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात कोणत्या ऐतिहासिक व्यक्तीचे छायाचित्र दर्शवले आहे?\",\"options\":[\"रंगो बापूजी गुप्ते\",\"छत्रपती प्रतापसिंह\",\"लॉर्ड डलहौसी\",\"ग्रँड डफ\"],\"answer\":1,\"explain\":\"दिलेले चित्र सातारचे छत्रपती प्रतापसिंह यांचे आहे.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"understand\",\"figure_image\":\"62\\/020_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील व्यक्तीला गादीवरून पदच्युत केल्यानंतर कोठे ठेवण्यात आले होते?\",\"options\":[\"सातारा\",\"पुणे\",\"इंग्लंड\",\"काशी\"],\"answer\":3,\"explain\":\"मजकुरानुसार, छत्रपती प्रतापसिंहांना पदच्युत करून काशी येथे ठेवण्यात आले होते.\",\"topic\":\"छत्रपती प्रतापसिंह\",\"part\":5,\"bloom\":\"analyze\",\"figure_image\":\"62\\/020_101.jpg\"},{\"q\":\"छत्रपती प्रतापसिंह यांनी १८२७ साली राजनीतीविषयक कोणता ग्रंथ लिहून छापला?\",\"options\":[\"राज्यनीति\",\"सभानीति\",\"समाजनीति\",\"प्रजाधर्मी\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे १८२७ साली त्यांनी \'सभानीति\' नावाचा राजनीतीविषयक ग्रंथ लिहिला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"छत्रपती प्रतापसिंह यांनी सातारा शहरात पाणी पुरवण्यासाठी तलाव कोठे बांधले?\",\"options\":[\"प्रतापगड आणि महाड\",\"महाबळेश्वर आणि सातारा\",\"येवतेश्वर आणि महादरा\",\"महादरा आणि महाड\"],\"answer\":2,\"explain\":\"येवतेश्वराच्या देवालयाच्या मागील बाजूस व महादरा येथे तलाव बांधून त्याचे पाणी शहरात खेळवले गेले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"छत्रपती प्रतापसिंह यांनी स्थापन केलेल्या पाठशाळेत मुलामुलींना कोणत्या भाषा शिकवण्याची सोय होती?\",\"options\":[\"केवळ मराठी आणि संस्कृत\",\"मराठी, हिंदी आणि इंग्रजी\",\"संस्कृत, मराठी आणि इंग्रजी\",\"संस्कृत, पाली आणि मराठी\"],\"answer\":2,\"explain\":\"पाठशाळेत संस्कृत, मराठी आणि इंग्रजी या तीन भाषा शिकवल्या जात असत.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"साताऱ्याहून महाबळेश्वर ते प्रतापगडापर्यंत तयार केलेला रस्ता पुढे कोठपर्यंत नेण्यात आला?\",\"options\":[\"पुणे\",\"महाड\",\"कोल्हापूर\",\"रत्नागिरी\"],\"answer\":1,\"explain\":\"साताऱ्याहून महाबळेश्वर ते प्रतापगडापर्यंतचा रस्ता पुढे महाडपर्यंत नेण्यात आला.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"छत्रपती प्रतापसिंह यांच्या कोणत्या कृतीवरून त्यांना पर्यावरणाची काळजी होती हे समजते?\",\"options\":[\"त्यांनी छापखाना काढला\",\"त्यांनी रोजनिशी लिहिली\",\"त्यांनी रस्त्यांच्या दोन्ही बाजूंना झाडे लावली\",\"त्यांनी संस्कृत शाळा बांधली\"],\"answer\":2,\"explain\":\"रस्त्यांच्या दोन्ही बाजूंना झाडे लावणे ही कृती पर्यावरण रक्षणाशी संबंधित आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"छत्रपती प्रतापसिंह स्वतः दररोज काय लिहीत असत?\",\"options\":[\"कविता\",\"रोजनिशी\",\"कथा\",\"पत्रे\"],\"answer\":1,\"explain\":\"छत्रपती प्रतापसिंह हे दररोज रोजनिशी स्वतः लिहीत असत असे उताऱ्यात दिले आहे.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"दिलेल्या आकृतीत (मजकुरात) नमूद केल्याप्रमाणे, येवतेश्वराच्या देवालयाच्या मागील बाजूस काय बांधण्यात आले?\",\"options\":[\"पाठशाळा\",\"तलाव\",\"छापखाना\",\"रस्ता\"],\"answer\":1,\"explain\":\"आकृतीतील मजकुरानुसार येवतेश्वराच्या देवालयाच्या मागील बाजूस तलाव बांधला होता.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"understand\",\"figure_image\":\"62\\/021_101.jpg\"},{\"q\":\"दिलेल्या आकृतीतील माहितीनुसार, छत्रपती प्रतापसिंह यांनी छापखाना का काढला असावा?\",\"options\":[\"केवळ स्वतःची रोजनिशी छापण्यासाठी\",\"शाळेतील मुलांच्या परीक्षा घेण्यासाठी\",\"अनेक उपयुक्त ग्रंथ छापून घेण्यासाठी\",\"केवळ इंग्रजी पुस्तके छापण्यासाठी\"],\"answer\":2,\"explain\":\"मजकुरात स्पष्ट केले आहे की छापखाना काढून अनेक उपयुक्त ग्रंथ छापून घेतले.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"analyze\",\"figure_image\":\"62\\/021_101.jpg\"},{\"q\":\"छत्रपती प्रतापसिंह यांच्या कार्यावरून त्यांच्या व्यक्तिमत्त्वाचा कोणता पैलू ठळकपणे दिसून येतो?\",\"options\":[\"ते केवळ युद्धकलेत निपुण होते\",\"ते एक प्रजाहितदक्ष आणि सुधारक शासक होते\",\"त्यांना केवळ परकीय भाषांची आवड होती\",\"त्यांना प्रवासाची आवड नव्हती\"],\"answer\":1,\"explain\":\"रस्ते, पाणी, शिक्षण आणि ग्रंथनिर्मिती यांसारख्या कामांवरून ते सुधारक शासक असल्याचे सिद्ध होते.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"छत्रपती प्रतापसिंह यांनी बांधलेल्या रस्त्यांच्या जाळ्याचा मुख्य मार्ग कोणता होता?\",\"options\":[\"सातारा - महाबळेश्वर - प्रतापगड - महाड\",\"सातारा - पुणे - प्रतापगड\",\"महाड - सातारा - कोल्हापूर\",\"प्रतापगड - महाबळेश्वर - पुणे\"],\"answer\":0,\"explain\":\"उताऱ्यातील माहितीनुसार रस्ता साताऱ्याहून महाबळेश्वर, प्रतापगड आणि पुढे महाडपर्यंत होता.\",\"topic\":\"माहीत आहे का तुम्हांला?\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"बंगालमध्ये दुहेरी राज्यव्यवस्था कोणी अस्तित्वात आणली?\",\"options\":[\"वॉरन हेस्टिंग्स\",\"रॉबर्ट क्लाइव्ह\",\"लॉर्ड 