:19,\"bloom\":\"apply\"},{\"q\":\"इंग्रजांनी संदेशवहनासाठी तारायंत्रासोबतच आणखी कोणती व्यवस्था सुरू केली?\",\"options\":[\"दूरध्वनी व्यवस्था\",\"इंटरनेट व्यवस्था\",\"डाकव्यवस्था\",\"रेडिओ व्यवस्था\"],\"answer\":2,\"explain\":\"इंग्रजांनी दळणवळणासाठी तारायंत्रासोबतच टपाल (डाक) व्यवस्थाही सुरू केली.\",\"topic\":\"वाहतूक व दळणवळण व्यवस्थेत सुधारणा\",\"part\":19,\"bloom\":\"remember\"},{\"q\":\"जर १८५३ मध्ये रेल्वे आणि तारायंत्र सुरू झाले, तर या सुधारणांचा मुख्य उद्देश काय असावा असे तुम्हाला वाटते?\",\"options\":[\"भारताला आधुनिक राष्ट्र बनवणे\",\"ब्रिटीश साम्राज्याची पकड मजबूत करणे आणि व्यापार वाढवणे\",\"भारतीयांना मोफत प्रवास देणे\",\"केवळ पर्यटनाचा विकास करणे\"],\"answer\":1,\"explain\":\"प्रशासकीय सोय आणि व्यापार हे ब्रिटीश साम्राज्याचे मुख्य उद्दिष्ट होते.\",\"topic\":\"वाहतूक व दळणवळण व्यवस्थेत सुधारणा\",\"part\":19,\"bloom\":\"analyze\"},{\"q\":\"वाहतुकीच्या आधुनिक सोयींमुळे देशाच्या विविध भागांमधील लोकांचा परस्परांशी संपर्क वाढला, हे विधान कोणत्या प्रक्रियेला गती देते?\",\"options\":[\"राष्ट्रीय एकात्मता\",\"धार्मिक कट्टरता\",\"आर्थिक मंदी\",\"प्रादेशिक विलगीकरण\"],\"answer\":0,\"explain\":\"संपर्क वाढल्याने लोकांमध्ये एकतेची भावना वाढली, जी राष्ट्रीय एकात्मतेचा भाग आहे.\",\"topic\":\"वाहतूक व दळणवळण व्यवस्थेत सुधारणा\",\"part\":19,\"bloom\":\"apply\"},{\"q\":\"भारतातून इंग्लंडला जाणाऱ्या मालावर इंग्रज सरकार कसा कर आकारत असे?\",\"options\":[\"अतिशय कमी कर\",\"मध्यम स्वरूपाचा कर\",\"जबरदस्त कर\",\"कर आकारला जात नसे\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट नमूद केले आहे की, भारतातून इंग्लंडला जाणाऱ्या मालावर इंग्रज सरकार जबरदस्त कर आकारत असे.\",\"topic\":\"भारतातील जुन्या उद्योगांचा ऱ्हास\",\"part\":20,\"bloom\":\"remember\"},{\"q\":\"इंग्लंडमधून भारतात येणाऱ्या मालावर कराचे प्रमाण कसे होते?\",\"options\":[\"अतिशय कमी\",\"खूप जास्त\",\"भारतीय मालासारखेच\",\"दुप्पट\"],\"answer\":0,\"explain\":\"इंग्लंडमधून भारतात येणाऱ्या मालावर अतिशय कमी कर आकारण्यात येत असे.\",\"topic\":\"भारतातील जुन्या उद्योगांचा ऱ्हास\",\"part\":20,\"bloom\":\"remember\"},{\"q\":\"इंग्लंड