:\"मुस्लीम व हिंदू समाजातील सुधारणा\",\"part\":9,\"bloom\":\"analyze\",\"figure_image\":\"62\\/034_101.jpg\"},{\"q\":\"अब्दुल लतीफ यांनी मुस्लीम समाजातील धर्मसुधारणेची सुरुवात कोणत्या प्रांतात केली?\",\"options\":[\"महाराष्ट्र\",\"पंजाब\",\"बंगाल\",\"उत्तर प्रदेश\"],\"answer\":2,\"explain\":\"अब्दुल लतीफ यांनी बंगाल प्रांतातून मुस्लीम समाजातील धर्मसुधारणेला सुरुवात केली.\",\"topic\":\"मुस्लीम व हिंदू समाजातील सुधारणा\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या दोन संस्थांची स्थापना हिंदू समाजातील संघटना किंवा शिक्षणासाठी झाली होती?\",\"options\":[\"हिंदुमहासभा व बनारस हिंदू विद्यापीठ\",\"मोहम्मदन लिटरेरी सोसायटी व हिंदुमहासभा\",\"अलीगढ मुस्लीम विद्यापीठ व राष्ट्रीय स्वयंसेवक संघ\",\"मोहम्मदन ॲंग्लो-ओरिएंटल कॉलेज व हिंदुमहासभा\"],\"answer\":0,\"explain\":\"हिंदुमहासभा (१९१५) आणि बनारस हिंदू विद्यापीठ या दोन्ही संस्था हिंदू समाजाशी संबंधित आहेत.\",\"topic\":\"मुस्लीम व हिंदू समाजातील सुधारणा\",\"part\":9,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या व्यक्तीला १९ व्या शतकात मुस्लीम समाजात आधुनिक विज्ञानाचा प्रसार करायचा असेल, तर तो खालीलपैकी कोणाच्या विचारांशी सहमत असेल?\",\"options\":[\"डॉ. केशव बळीराम हेडगेवार\",\"पंडित मदन मोहन मालवीय\",\"सर सय्यद अहमद खान\",\"वरीलपैकी कोणीही नाही\"],\"answer\":2,\"explain\":\"सर सय्यद अहमद खान यांनी मुस्लीम समाजात पाश्चिमात्य विज्ञान व तंत्रज्ञानाचा पुरस्कार केला होता.\",\"topic\":\"मुस्लीम व हिंदू समाजातील सुधारणा\",\"part\":9,\"bloom\":\"apply\"},{\"q\":\"साहित्याच्या क्षेत्रात खालीलपैकी कोणाला नोबेल पारितोषिक मिळाले?\",\"options\":[\"महात्मा गांधी\",\"गुरुदेव रवींद्रनाथ टागोर\",\"सी.व्ही. रामन\",\"लोकमान्य टिळक\"],\"answer\":1,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे साहित्याच्या क्षेत्रात गुरुदेव रवींद्रनाथ टागोर यांना नोबेल पारितोषिक मिळाले.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"विज्ञानाच्या क्षेत्रात नोबेल पारितोषिक मिळवणारे भारतीय कोण होते?\",\"options\":[\"जगदीशचंद्र बोस\",\"डॉ. होमी भाभा\",\"सी.व्ही. रामन\",\"डॉ. ए.पी.जे. अब्दुल कलाम\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्ट उल्लेख आहे की विज्ञानाच्या क्षेत्रात सी.व्ही. रामन यांना नोबेल पारितोषिक मिळाले.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"समाजसुधारणा व राजकीय जागृतीची वाहक कोण ठरली?\",\"options\":[\"नवी वृत्तपत्रे व मासिके\",\"केवळ कथा-कादंबऱ्या\",\"केवळ संगीत\",\"परदेशी पुस्तके\"],\"answer\":0,\"explain\":\"नवी वृत्तपत्रे व मासिके ही समाजसुधारणा व राजकीय जागृतीची वाहक ठरली असे उताऱ्यात म्हटले आहे.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"प्रबोधनकाळात चित्रकलेमध्ये कोणत्या दोन गोष्टींचा मेळ घालून नवीन शैली पुढे आली?\",\"options\":[\"ग्रामीण आणि शहरी शैली\",\"प्राचीन आणि मध्ययुगीन शैली\",\"भारतीय शैली आणि पाश्चात्त्य तंत्रे\",\"मराठी आणि हिंदी शैली\"],\"answer\":2,\"explain\":\"भारतीय शैली आणि पाश्चात्त्य तंत्रे यांचा मेळ घालून नवीन चित्रकला पुढे आली.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"कथा-कादंबऱ्यांमधून प्रामुख्याने कोणती प्रेरणा मिळू लागली?\",\"options\":[\"व्यापाराची प्रेरणा\",\"स्वातंत्र्याची प्रेरणा\",\"युद्धाची प्रेरणा\",\"धार्मिक कर्मकांडांची प्रेरणा\"],\"answer\":1,\"explain\":\"उताऱ्यानुसार कथा-कादंबऱ्यांमधून स्वातंत्र्याची प्रेरणा मिळू लागली.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"भारताच्या प्रगतीसाठी लोकांमध्ये कोणत्या गोष्टीचे महत्त्व उमगू लागले?\",\"options\":[\"केवळ जुन्या परंपरा\",\"प्रयोगशीलता व वैज्ञानिक दृष्टी\",\"केवळ पाश्चात्त्य शिक्षण\",\"केवळ संगीत कला\"],\"answer\":1,\"explain\":\"भारताच्या प्रगतीसाठी प्रयोगशीलता व वैज्ञानिक दृष्टीचे महत्त्व लोकांना उमगू लागले.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"प्रबोधनकाळात लेखनाच्या क्षेत्रात कोणता महत्त्वाचा बदल दिसून आला?\",\"options\":[\"केवळ पुरुष लेखन करू लागले\",\"स्त्रिया लेखन करू लागल्या\",\"लेखन पूर्णपणे बंद झाले\",\"केवळ संस्कृतमध्ये लेखन होऊ लागले\"],\"answer\":1,\"explain\":\"या काळात स्त्रिया लेखन करू लागल्या, हा एक महत्त्वाचा बदल होता.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"प्रबोधनकाळातील सुधारकांनी कोणत्या कल्पनांनी भारून राजकीय क्षेत्रात राष्ट्राची चळवळ उभी केली?\",\"options\":[\"स्वातंत्र्य, समता, राष्ट्रवाद\",\"हुकूमशाही आणि साम्राज्यवाद\",\"केवळ धार्मिक कट्टरता\",\"केवळ व्यापार आणि नफा\"],\"answer\":0,\"explain\":\"स्वातंत्र्य, समता, राष्ट्रवाद या कल्पनांनी भारलेल्या सुधारकांनी राजकीय चळवळ उभी केली.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"विज्ञानाविषयी अनेक ग्रंथ लिहिले जाऊ लागल्यामुळे लोकांच्या विचारसरणीत कोणता बदल झाला असावा?\",\"options\":[\"लोक अधिक अंधश्रद्धाळू झाले\",\"लोकांना वैज्ञानिक दृष्टीचे महत्त्व उमजले\",\"लोकांनी वाचन करणे सोडून दिले\",\"विज्ञानाकडे दुर्लक्ष झाले\"],\"answer\":1,\"explain\":\"विज्ञानाविषयी ग्रंथ लिहिल्यामुळे लोकांना वैज्ञानिक दृष्टीचे महत्त्व उमगू लागले.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"नोबेल पारितोषिकांच्या उदाहरणावरून लेखकाला भारताच्या बाबतीत काय सुचवायचे आहे?\",\"options\":[\"भारताची प्रगती होत होती\",\"भारत मागे पडत होता\",\"भारतात कलेचा अभाव होता\",\"भारतात शिक्षणाची गरज नव्हती\"],\"answer\":0,\"explain\":\"नोबेल पारितोषिकांच्या उदाहरणावरून भारताच्या प्रगतीची कल्पना येते असे उताऱ्यात म्हटले आहे.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"प्रबोधनकाळात कलेच्या क्षेत्रात कोणता बदल झाला?\",\"options\":[\"संगीत आणि लोकअभिरुची वाढू लागली\",\"कलेचा ऱ्हास झाला\",\"केवळ पाश्चात्त्य संगीत ऐकले जाऊ लागले\",\"चित्रकला पूर्णपणे बंद झाली\"],\"answer\":0,\"explain\":\"कलेच्या क्षेत्रात प्रगती होऊन संगीत आणि लोकअभिरुची वाढू लागली.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्याच्या आधारे, प्रबोधनकाळातील \'अद्भुत क्रांती\' कोणत्या क्षेत्रांमध्ये झाली?\",\"options\":[\"केवळ युद्धकला\",\"साहित्य, कला, विज्ञान\",\"केवळ शेती\",\"केवळ व्यापार\"],\"answer\":1,\"explain\":\"प्रबोधनकाळात साहित्य, कला, विज्ञान यांसारख्या क्षेत्रांमध्ये अद्भुत क्रांतीची प्रगती महत्त्वाची होती.\",\"topic\":\"प्रबोधनाचे इतर क्षेत्रांमधील आविष्कार\",\"part\":10,\"bloom\":\"evaluate\"}]','gemini/gemini-3-flash-preview','2026-10-03 16:25:29'),(22203,62,8,'History & Civics','mr','स्वातंत्र्य चळवळीच्या युगास प्रारंभ','[\"स्वातंत्र्य चळवळीच्या युगास प्रारंभ म्हणजे १८८५‑१९१४ या काळात भारतात स्वातंत्र्याची जाणीव जागृत होऊन विविध चळवळींची सुरुवात झाली.\",\"इंग्रजी शिक्षणामुळे न्याय, स्वातंत्र्य, समता आणि लोकशाहीची कल्पना भारतीय समाजात पसरली.\",\"ब्रिटिश प्रशासनाने भारतात केंद्रीकृत शासन आणि पायाभूत सुविधा जसे रेल्वे, रस्ते उभारले, ज्यामुळे विविध प्रदेशांतील लोकांना एकत्र येणे सोपे झाले.\",\"ब्रिटिश आर्थिक शोषणामुळे शेतकऱ्यांना नगदी पिके लावावी लागली, ज्यामुळे शेतकरी वर्गाला दुष्काळ आणि गरीबीचा त्रास सहन करावा लागला.\",\"उद्योगांचे ऱ्हास, बेरोजगारी आणि कामगार वर्गाचे शोषण यामुळे असंतोष वाढला.\",\"पाश्चात्त्य शिक्षणामुळे भारतीयांना नवीन विचार, विज्ञान आणि तंत्रज्ञानाची ओळख झाली.\",\"वृत्तपत्रे आणि नियतकालिके इंग्रजी व प्रादेशिक भाषांमध्ये प्रकाशित होऊ लागली, ज्यामुळे राजकीय जागरूकता वाढली.\",\"राष्ट्रीय सभेची स्थापना १८८५ मध्ये झाली, ज्याचे पहिले अधिवेशन कोलकात्यात झाले.\",\"राष्ट्रीय सभेचे उद्दिष्ट भारतीयांना प्रशासनात अधिक प्रतिनिधित्व आणि स्वराज्याची मागणी करणे होते.\",\"मवाळ आणि जहाल या दोन गटांमध्ये राष्ट्रीय सभेच्या धोरणावर मतभेद झाले.\",\"मवाळ गट स्वदेशी आणि बहिष्कारावर भर देत होते, तर जहाल गट अधिक क्रांतिकारी मार्गावर विश्वास ठेवत होते.\",\"बंगाल फाळणी (१९०५) ने हिंदू-मुस्लिमांमध्ये फूट पाडण्याचा प्रयत्न केला, ज्याला विरोध करण्यात आला.\",\"मुस्लीम लीगची स्थापना १९०६ मध्ये झाली, ज्याने मुस्लीमांच्या हिताचे संरक्षण करण्याचा प्रयत्न केला.\",\"लखनौ अधिवेशन (१९१६) मध्ये ब्रिटिशांनी भारतीयांना काही राजकीय अधिकार दिले, ज्याला लखनौ करार म्हणतात.\",\"मोरले‑मिंटो कायदा (१९१९) आणि चेम्सफर्ड कायदा (१९१९) यांनी भारतीयांना अधिक स्वराज्याची मागणी करण्यास प्रवृत्त केले.\",\"स्वराज्य चळवळीत विविध नेते जसे लोकमान्य टिळक, बाळ गंगाधर टिळक, लाला लजपतराय यांनी महत्त्वाची भूमिका बजावली.\",\"सामाजिक सलोखा आणि राष्ट्रीय एकात्मतेसाठी विविध संघटना आणि वृत्तपत्रे उभी राहिली.\",\"स्वातंत्र्य चळवळीच्या या युगात भारतीयांनी स्वशासन, स्वदेशी आणि राष्ट्रीय एकात्मतेची जाणीव विकसित केली.\",\"स्वातंत्र्य लढ्यातील प्रमुख घटना आणि व्यक्तिमत्त्वे या युगात घडलेल्या आहेत.\",\"या युगातील चळवळींचे उद्दिष्ट ब्रिटिश सत्तेचा अंत आणि स्वराज्य प्राप्त करणे होते.\",\"स्वातंत्र्य चळवळीच्या या युगाने भारताच्या इतिहासात एक महत्त्वपूर्ण वळण आणले.\"]','[{\"q\":\"इंग्रजी शिक्षणामुळे भारतीय समाजजीवनावर खालीलपैकी कोणते परिणाम झाले?\",\"options\":[\"केवळ सकारात्मक परिणाम\",\"केवळ नकारात्मक परिणाम\",\"संमिश्र परिणाम\",\"कोणतेही परिणाम झाले नाहीत\"],\"answer\":2,\"explain\":\"उताऱ्यात स्पष्टपणे नमूद केले आहे की इंग्रजी शिक्षणामुळे भारतीय समाजजीवनावर संमिश्र परिणाम झाले.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राष्ट्रीयत्वाच्या भावनेचे बीजारोपण कोणामुळे झाले?\",\"options\":[\"ब्रिटीश अधिकाऱ्यांमुळे\",\"नवसुशिक्षित समाजाने घडवून आणलेल्या प्रबोधनामुळे\",\"केवळ परकीय व्यापारांमुळे\",\"प्रादेशिक युद्धांमुळे\"],\"answer\":1,\"explain\":\"नवसुशिक्षित समाजाने केलेल्या प्रबोधनामुळे लोकांमध्ये राष्ट्रीयत्वाची भावना निर्माण झाली.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"विविध प्रांतांतील राजकीय संस्थांचे काय करणे आवश्यक होते?\",\"options\":[\"त्यांचे विसर्जन करणे\",\"त्यांचे एकसूत्रीकरण करणे\",\"त्यांच्यात स्पर्धा लावणे\",\"त्यांना स्वतंत्र ठेवणे\"],\"answer\":1,\"explain\":\"विविध भागांतील चळवळींमुळे प्रांतीय संस्थांचे एकसूत्रीकरण करण्याची गरज निर्माण झाली होती.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"कोणत्या स्तरावरील राजकीय संस्थेची गरज असल्याची अनुकूल परिस्थिती निर्माण झाली?\",\"options\":[\"केवळ स्थानिक स्तरावरील\",\"केवळ जिल्हा स्तरावरील\",\"अखिल भारतीय स्तरावरील\",\"केवळ आंतरराष्ट्रीय स्तरावरील\"],\"answer\":2,\"explain\":\"उताऱ्यात नमूद केल्याप्रमाणे अखिल भारतीय स्तरावरील राजकीय संस्थेची गरज निर्माण झाली होती.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"राजकीयदृष्ट्या जागृत असलेल्या विविध गटांना एकत्र आणण्याचा मुख्य उद्देश काय होता?\",\"options\":[\"राष्ट्राच्या हिताच्या प्रश्नाकडे लोकांचे लक्ष वेधणे\",\"ब्रिटीश संस्कृतीचा प्रसार करणे\",\"केवळ शिक्षण प्रसार करणे\",\"प्रादेशिक भाषांचा त्याग करणे\"],\"answer\":0,\"explain\":\"विविध गटांना एकत्र आणून राष्ट्राच्या हिताच्या प्रश्नांकडे लोकांचे लक्ष वेधणे हा उद्देश होता.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"उताऱ्याच्या संदर्भात, \'राष्ट्राच्या आकांक्षा प्रकट करणे\' यासाठी खालीलपैकी काय आवश्यक मानले गेले?\",\"options\":[\"लष्करी बंड\",\"एक अखिल भारतीय राजकीय संस्था\",\"परकीय मदत\",\"केवळ धार्मिक सुधारणा\"],\"answer\":1,\"explain\":\"राष्ट्राच्या आकांक्षा प्रकट करण्यासाठी एक मध्यवर्ती राजकीय संस्था आवश्यक होती.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"भारताच्या विविध भागांतील चळवळींचा कोणता परिणाम उताऱ्यात दिला आहे?\",\"options\":[\"लोकांमध्ये भीती निर्माण झाली\",\"राजकीय संस्थांच्या एकसूत्रीकरणाची गरज भासली\",\"इंग्रजी शिक्षण बंद झाले\",\"प्रादेशिक वाद वाढले\"],\"answer\":1,\"explain\":\"विविध भागांतील चळवळींमुळे राजकीय संस्थांना एकत्र आणण्याची अनुकूल परिस्थिती निर्माण झाली.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"नवसुशिक्षित समाजाने प्रबोधन घडवून आणल्यामुळे काय साध्य झाले?\",\"options\":[\"लोकांनी शेती सोडली\",\"राष्ट्रीयत्वाची भावना रुजली\",\"इंग्रजी भाषा बंद झाली\",\"केवळ व्यापार वाढला\"],\"answer\":1,\"explain\":\"प्रबोधनामुळे लोकांमध्ये राष्ट्रीयत्वाची भावना निर्माण होण्यास मदत झाली.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"राजकीयदृष्ट्या जागृत व्यक्तींना एकत्र आणणे हे कशाचे लक्षण होते?\",\"options\":[\"राजकीय विघटनाचे\",\"राष्ट्रीय चळवळीच्या सुरुवातीच्या अनुकूल परिस्थितीचे\",\"केवळ शैक्षणिक प्रगतीचे\",\"ब्रिटीश प्रशासनाच्या यशाचे\"],\"answer\":1,\"explain\":\"विविध गटांना आणि व्यक्तींना एकत्र आणणे हे अखिल भारतीय संस्थेसाठी पोषक वातावरण दर्शवते.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"उताऱ्यातील माहितीनुसार, अखिल भारतीय संस्थेची स्थापना करण्यासाठी खालीलपैकी कोणता घटक कारणीभूत ठरला नाही?\",\"options\":[\"इंग्रजी शिक्षण\",\"नवसुशिक्षितांचे प्रबोधन\",\"विविध प्रांतांतील चळवळी\",\"केवळ शेतीमधील सुधारणा\"],\"answer\":3,\"explain\":\"उताऱ्यात शिक्षण, प्रबोधन आणि चळवळींचा उल्लेख आहे, पण शेतीमधील सुधारणांचा उल्लेख नाही.\",\"topic\":\"प्रस्तावना\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"ब्रिटिश प्रशासनामुळे भारतात कोणत्या प्रकारचा अंमल खऱ्या अर्थाने सुरू झाला?\",\"options\":[\"दुहेरी अंमल\",\"एकछत्री अंमल\",\"लष्करी अंमल\",\"प्रादेशिक अंमल\"],\"answer\":1,\"explain\":\"उताऱ्यातील पहिल्या ओळीनुसार, ब्रिटिश प्रशासनामुळे भारतात खऱ्या अर्थाने एकछत्री अंमल सुरू झाला.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"लोकांमध्ये एकत्वाची भावना विकसित होण्याचे मुख्य कारण काय होते?\",\"options\":[\"रेल्वेचा प्रवास\",\"लष्करी हालचाली\",\"समान धोरणे आणि कायद्यासमोर समान दर्जा\",\"परकीय व्यापार\"],\"answer\":2,\"explain\":\"देशभर समान धोरणे आणि कायद्यासमोर सर्वांना समान दर्जा मिळाल्यामुळे लोकांमध्ये एकत्वाची भावना निर्माण झाली.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"ब्रिटिशांनी रेल्वे आणि रस्ते यांचे जाळे प्रामुख्याने कशासाठी उभारले?\",\"options\":[\"भारतीयांच्या पर्यटनासाठी\",\"प्रशासनाच्या सोईसाठी व लष्कराच्या जलद हालचालीसाठी\",\"शेतीचा विकास करण्यासाठी\",\"शिक्षणाचा प्रसार करण्यासाठी\"],\"answer\":1,\"explain\":\"ब्रिटिशांनी स्वतःच्या प्रशासकीय सोईसाठी आणि लष्करी हालचालींसाठी या भौतिक सुविधा निर्माण केल्या होत्या.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"विविध प्रांतांतील लोकांचा परस्परांशी संवाद वाढल्यामुळे काय परिणाम झाला?\",\"options\":[\"प्रादेशिक वाद वाढले\",\"इंग्रजी भाषेचा द्वेष वाढला\",\"राष्ट्रभावना वाढीला लागली\",\"लोक शेती सोडून शहरात गेले\"],\"answer\":2,\"explain\":\"लोकांचा परस्परांशी संबंध येऊन संवाद वाढल्यामुळे त्यांच्यात राष्ट्रभावना निर्माण झाली.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"समजा, १९ व्या शतकात एका बंगालमधील व्यक्तीला मद्रासमधील व्यक्तीशी संपर्क साधणे सोपे झाले, तर उताऱ्यानुसार याचे भौतिक कारण काय असेल?\",\"options\":[\"समान कायदे\",\"लष्करी भरती\",\"रेल्वे आणि रस्ते यांचे जाळे\",\"एकछत्री अंमल\"],\"answer\":2,\"explain\":\"रेल्वे आणि रस्ते या भौतिक सुविधांमुळे विविध प्रांतांतील लोकांचा परस्परांशी संबंध येणे सोपे झाले.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"ब्रिटिशांनी स्वतःच्या सोईसाठी उभारलेल्या सुविधांचा भारतीयांना फायदा झाला, हे विधान कोणत्या प्रक्रियेचे निदर्शक आहे?\",\"options\":[\"केवळ लष्करी प्रगती\",\"अनपेक्षित सकारात्मक परिणाम\",\"आर्थिक शोषण\",\"प्रशासकीय अपयश\"],\"answer\":1,\"explain\":\"ब्रिटिशांनी स्वतःच्या सोईसाठी सुविधा केल्या तरी त्याचा फायदा भारतीयांना राष्ट्रभावना वाढवण्यासाठी झाला.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"analyze\"},{\"q\":\"कायद्यासमोर सर्वांना समान दर्जा मिळाल्याने कोणता बदल झाला?\",\"options\":[\"लोकांमध्ये भेदभाव वाढला\",\"लोकांमध्ये एकत्वाची भावना विकसित झाली\",\"ब्रिटीश अधिकारी घाबरले\",\"लष्करी हालचाली मंदावल्या\"],\"answer\":1,\"explain\":\"समान धोरणे आणि कायद्यातील समानतेमुळे लोकांमध्ये एकत्वाची भावना निर्माण झाली.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"उताऱ्यात उल्लेखिलेल्या \'भौतिक सुविधा\' या शब्दाचा अर्थ खालीलपैकी कोणता?\",\"options\":[\"समान धोरणे आणि कायदे\",\"एकत्वाची भावना\",\"रेल्वे आणि रस्ते\",\"राष्ट्रभावना\"],\"answer\":2,\"explain\":\"उताऱ्यात रेल्वे आणि रस्ते यांचा उल्लेख भौतिक सुविधा असा केला आहे.\",\"topic\":\"प्रशासकीय केंद्रीकरण\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"प्रशासकीय केंद्रीकरणामुळे राष्ट्रभावना वाढीस लागली, या प्रक्रियेचा योग्य क्रम कोणता?\",\"options\":[\"रेल्वे सुविधा -> संवाद वाढला -> राष्ट्रभावना\",\"राष्ट्रभावना -> रेल्वे सुविधा -> संवाद वाढला\",\"संवाद वाढला -> राष्ट्रभावना -> रेल्वे सुविधा\",\"लष्करी हालचाल -> राष्ट्रभावना -> रेल्वे सुविधा\"],\"answer\":0,\"explain\":\"भौतिक सुविधांमुळे (रेल्वे) लोकांचा संबंध येऊन संवाद वाढला आणि त्यातून राष्ट्र