gure_image\":\"62\\/045_101.jpg\"},{\"q\":\"दिलेल्या चित्रातील नेत्याने ३१ डिसेंबर १९२९ रोजी केलेल्या कृतीचा मुख्य उद्देश काय होता?\",\"options\":[\"वसाहतीचे स्वराज्य जाहीर करणे\",\"संपूर्ण स्वातंत्र्याचा निर्धार व्यक्त करणे\",\"असहकार चळवळ मागे घेणे\",\"ब्रिटिश मंत्र्यांचे स्वागत करणे\"],\"answer\":1,\"explain\":\"पं. जवाहरलाल नेहरू यांनी तिरंगा फडकावून भारताच्या संपूर्ण स्वातंत्र्याचे ध्येय अधोरेखित केले.\",\"topic\":\"नेहरू अहवाल व पूर्ण स्वराज्य\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"62\\/045_101.jpg\"}]','vertex/gemini-3-flash-preview','2026-10-03 16:25:29'),(22205,62,8,'History & Civics','mr','सविनय कायदेभंग चळवळ','[\"सविनय कायदेभंग चळवळ म्हणजे अहिंसात्मक पद्धतीने ब्रिटिश सरकारच्या अन्यायकारक कायद्यांना मोडणे.\",\"१९३० मध्ये लाहोर अधिवेशनात संपूर्ण स्वातंत्र्याचा ठराव झाल्यानंतर गांधीजींचे ‘सविनय कायदेभंग’ या घोषणेनं चळवळ सुरू झाली.\",\"मुख्य लक्ष्य: मिठावर लावलेल्या कराची रद्दी आणि ब्रिटिश सरकारची मक्तेदारी मोडणे.\",\"दांडी यात्रा (६ एप्रिल १९३०) – मिठाच्या कायद्याला विरोध म्हणून दांडी किनाऱ्यावर मिठाचे उत्पादन.\",\"सोलापूर सत्याग्रह – १२ मार्च १९३० रोजी सोलापूरमध्ये ३८५ किमीची पदयात्रा, १९३० मध्ये ‘सोलापूर सत्याग्रह’ आयोजित.\",\"पेशावर सत्याग्रह – २३ एप्रिल १९३० रोजी खान अब्दुल गफारखान यांनी ‘खुदा-इ-खिदमतगार’ संघटनेची स्थापना करून सुरू केले.\",\"मिठाचा कायदा मोडून देशभर सत्याग्रह चालू ठेवला, ज्यात महिलांनीही मोठा सहभाग घेतला.\",\"गांधीजींना ४ मे १९३० रोजी अटक करण्यात आली, तरीही चळवळीला देशभर समर्थन मिळाले.\",\"गांधी-आयर्विन करार (१९३२) – ब्रिटिश सरकारने भारतातील स्वायत्ततेच्या मागणीला मान्यता दिली.\",\"सविनय कायदेभंग चळवळीच्या दुसऱ्या फेरीत १९३४ मध्ये चळवळ थांबवण्यात आली, परंतु ती भारताच्या स्वातंत्र्य संग्रामाची पायाभरणी ठरली.\"]','[{\"q\":\"लाहोर अधिवेशनात कोणता ठराव संमत झाल्यावर गांधीजींनी सविनय कायदेभंग करण्याचा निर्णय घेतला?\",\"options\":[\"असहकार चळवळ\",\"संपूर्ण स्वातंत्र्य\",\"मीठ सत्याग्रह\",\"प्रांतिक स्वायत्तता\"],\"answer\":1,\"explain\":\"लाहोर अधिवेशनात संपूर्ण स्वातंत्र्याचा ठराव संमत झाल्यावर सविनय कायदेभंगाचा निर्णय घेण्यात आला.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"गांधीजींनी ब्रिटिश सरकारकडे केलेल्या प्रमुख मागण्यांपैकी एक कोणती होती?\",\"options\":[\"जमीन महसूल वाढवणे\",\"परदेशी कापडावर बंदी घालणे\",\"मिठावरील कर रद्द करणे\",\"लष्करी खर्च वाढवणे\"],\"answer\":2,\"explain\":\"मिठावरील कर रद्द करून सरकारी मक्तेदारी संपवणे ही गांधीजींची प्रमुख मागणी होती.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"गांधीजींनी मिठाच्या सत्याग्रहासाठी गुजरातमधील कोणत्या ठिकाणाची निवड केली?\",\"options\":[\"सूरत\",\"अहमदाबाद\",\"दांडी\",\"पोरबंदर\"],\"answer\":2,\"explain\":\"मिठाचा सत्याग्रह करण्यासाठी गांधीजींनी गुजरातमधील समुद्रकिनाऱ्यावरील दांडी या ठिकाणाची निवड केली.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"remember\"},{\"q\":\"मिठाचा सत्याग्रह हा कोणत्या स्वरूपाचा होता?\",\"options\":[\"हिंसक\",\"प्रतीकात्मक\",\"गुप्त\",\"राजकीय\"],\"answer\":1,\"explain\":\"मिठाचा सत्याग्रह हा जुलमी कायदे शांततेने मोडण्यासाठी केलेला एक प्रतीकात्मक सत्याग्रह होता.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"मिठासारख्या जीवनावश्यक वस्तूंवर कर लादणे अन्यायकारक का होते?\",\"options\":[\"कारण मीठ महाग होते\",\"कारण मीठ फक्त श्रीमंत लोक वापरत\",\"कारण मीठ हा सामान्य जनतेच्या आहारातील महत्त्वाचा घटक आहे\",\"कारण मीठ भारतात तयार होत नसे\"],\"answer\":2,\"explain\":\"मीठ हा सर्वांच्या आहारातील महत्त्वाचा घटक असल्याने त्यावर कर लावणे अन्यायकारक होते.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"गांधीजींच्या भाषणांचा जनतेवर कोणता मुख्य परिणाम झाला?\",\"options\":[\"लोक घाबरून घरात बसले\",\"जनतेमध्ये निर्भयता निर्माण होऊन चळवळीला अनुकूल वातावरण झाले\",\"लोकांनी ब्रिटिश सरकारला पाठिंबा दिला\",\"लोकांनी पदयात्रा थांबवण्याची विनंती केली\"],\"answer\":1,\"explain\":\"गांधीजींच्या भाषणामुळे जनता निर्भय झाली आणि कायदेभंगाचा संदेश सर्वत्र पसरला.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"understand\"},{\"q\":\"साबरमती आश्रम ते दांडी हे सुमारे ३८५ किलोमीटरचे अंतर कापण्यासाठी गांधीजींना किती दिवस लागले? (१२ मार्चला सुरुवात आणि ५ एप्रिलला आगमन)\",\"options\":[\"१० दिवस\",\"१५ दिवस\",\"२५ दिवस\",\"४० दिवस\"],\"answer\":2,\"explain\":\"१२ मार्च ते ५ एप्रिल या कालावधीत ही पदयात्रा पूर्ण झाली, म्हणजेच साधारण २५ दिवस लागले.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"६ एप्रिल १९३० रोजी दांडी येथे गांधीजींनी नेमकी कोणती कृती केली?\",\"options\":[\"ब्रिटीश अधिकाऱ्यांची भेट घेतली\",\"समुद्रकिनाऱ्यावरील मीठ उचलून कायदा मोडला\",\"उपोषणाला सुरुवात केली\",\"नवीन आश्रम स्थापन केला\"],\"answer\":1,\"explain\":\"६ एप्रिल रोजी दांडीच्या समुद्रकिनाऱ्यावरील मीठ उचलून गांधीजींनी मिठाचा कायदा मोडला.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"apply\"},{\"q\":\"दिलेल्या चित्रात गांधीजींसोबत त्यांचे सहकारी कोणत्या प्रकारे प्रवास करताना दिसत आहेत?\",\"options\":[\"बैलगाडीने\",\"रेल्वेने\",\"पदयात्रेने (चालत)\",\"समुद्री जहाजाने\"],\"answer\":2,\"explain\":\"चित्रात गांधीजी आणि त्यांचे ७८ सहकारी साबरमती ते दांडी अशी पदयात्रा करताना दिसत आहेत.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"apply\",\"figure_image\":\"62\\/046_101.jpg\"},{\"q\":\"सविनय कायदेभंग चळवळीमागील व्यापक हेतू खालीलपैकी कोणता होता?\",\"options\":[\"केवळ मिठाचा व्यापार करणे\",\"ब्रिटीश सरकारला घाबरवणे\",\"जुलमी व अन्यायकारक कायदे शांततेच्या मार्गाने मोडणे\",\"परदेशी वस्तूंना प्रोत्साहन देणे\"],\"answer\":2,\"explain\":\"अन्यायकारक कायदे सत्याग्रहाच्या मार्गाने मोडून काढणे हा या चळवळीचा व्यापक हेतू होता.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"सरकारने गांधीजींच्या मागण्या फेटाळल्याचा कोणता परिणाम झाला?\",\"options\":[\"गांधीजींनी राजकारण सोडले\",\"गांधीजींनी देशभर मिठाचा सत्याग्रह करण्याचे ठरवले\",\"ब्रिटीश सरकारने कर कमी केला\",\"चळवळ स्थगित करण्यात आली\"],\"answer\":1,\"explain\":\"मागण्या फेटाळल्यामुळे गांधीजींनी मिठाचा कायदा मोडून सत्याग्रह करण्याचा निर्णय घेतला.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या चित्रावरून गांधीजींच्या नेतृत्वाखालील या चळवळीबद्दल काय निष्कर्ष काढता येतो?\",\"options\":[\"ही चळवळ केवळ काही नेत्यांपुरती मर्यादित होती\",\"गांधीजींनी सामान्य जनतेला एकत्र करून शिस्तबद्ध पदयात्रा काढली\",\"चळवळीत केवळ शस्त्रधारी लोकांचा सहभाग होता\",\"ही एक हिंसक निदर्शने होती\"],\"answer\":1,\"explain\":\"चित्रातील शिस्तबद्ध पदयात्रा आणि लोकांचा सहभाग गांधीजींच्या प्रभावी नेतृत्वाचे दर्शन घडवतो.\",\"topic\":\"प्रस्तावना आणि दांडी यात्रा\",\"part\":1,\"bloom\":\"analyze\",\"figure_image\":\"62\\/046_101.jpg\"},{\"q\":\"वायव्य सरहद्द प्रांतात \'सरहद्द गांधी\' म्हणून कोणाला ओळखले जाते?\",\"options\":[\"खान अब्दुल गफारखान\",\"चंद्रसिंग ठाकूर\",\"मौलाना आझाद\",\"बॅरिस्टर जिना\"],\"answer\":0,\"explain\":\"पाठ्यपुस्तकानुसार, वायव्य सरहद्द प्रांतात खान अब्दुल गफारखान यांना \'सरहद्द गांधी\' म्हणून ओळखले जाते.\",\"topic\":\"पेशावरचा सत्याग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"खान अब्दुल गफारखान यांनी कोणत्या संघटनेची स्थापना केली?\",\"options\":[\"आझाद हिंद सेना\",\"स्वराज्य पक्ष\",\"खुदा-ई-खिदमतगार\",\"अभिनव भारत\"],\"answer\":2,\"explain\":\"खान अब्दुल गफारखान यांनी \'खुदा-ई-खिदमतगार\' या संघटनेची स्थापना केली होती.\",\"topic\":\"पेशावरचा सत्याग्रह\",\"part\":2,\"bloom\":\"remember\"},{\"q\":\"पेशावर येथे सत्याग्रह कोणत्या तारखेला सुरू झाला?\",\"options\":[\"१२ मार्च १९३०\",\"६ एप्रिल १९३०\",\"२३ एप्रिल १९३०\",\"४ मे १९३०\"],\"answer\":2,\"explain\":\"पेशावर येथे २३ एप्रिल १९३० रोजी सत्याग्रह सुरू झाला.\",\"topic\":\"पेशावरचा सत्याग्रह\",\"part\":2,\"bloom\":\"understand\"},{\"q\":\"पेशावरच्या सत्याग्रहादरम्यान सत्याग्रहींनी शहरावर सुमारे किती काळ ताबा मिळवला होता?\",\"options\":[\"दोन दिवस\",\"आठवडाभर\",\"एक महिना\",\"पंधरा दिवस\"],\"answer\":1,\"explain\":\"पेशावर शहर सुमारे आठवडाभर सत्याग्रहींच्या ताब्यात होते.\",\"topic\":\"पेशावरचा सत्याग्रह\",\"part\":2,\"bloom\":\"apply\"},{\"q\":\"गढवाल पलटणीचे अधिकारी चंद्रसिंग ठाकूर यांना लष्करी न्यायालयाने जबर शिक्षा का दिली?\",\"options\":[