part\":10,\"bloom\":\"remember\"},{\"q\":\"जातीय निवाडा कोणी जाहीर केला?\",\"options\":[\"लॉर्ड आयर्विन\",\"रॅम्से मॅक्डोनाल्ड\",\"महात्मा गांधी\",\"माऊंटबॅटन\"],\"answer\":1,\"explain\":\"दुसऱ्या गोलमेज परिषदेत ब्रिटिश प्रधानमंत्री रॅम्से मॅक्डोनाल्ड यांनी जातीय निवाडा जाहीर केला.\",\"topic\":\"पुणे करार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"गांधीजींनी येरवडा तुरुंगात आमरण उपोषण का सुरू केले?\",\"options\":[\"मिठाच्या सत्याग्रहासाठी\",\"स्वदेशी चळवळीसाठी\",\"जातीय निवाड्यामुळे हिंदू समाजाची होणारी विभागणी टाळण्यासाठी\",\"गोलमेज परिषदेला विरोध करण्यासाठी\"],\"answer\":2,\"explain\":\"जातीय निवाड्यामुळे हिंदू समाजाची होणारी विभागणी गांधीजींना मान्य नव्हती, म्हणून त्यांनी उपोषण केले.\",\"topic\":\"पुणे करार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"महात्मा गांधी आणि डॉ. बाबासाहेब आंबेडकर यांच्यात पुणे करार कोणत्या वर्षी झाला?\",\"options\":[\"१९३०\",\"१९३१\",\"१९३२\",\"१९३४\"],\"answer\":2,\"explain\":\"१९३२ मध्ये महात्मा गांधी आणि डॉ. बाबासाहेब आंबेडकर यांच्यात पुणे येथे करार झाला.\",\"topic\":\"पुणे करार\",\"part\":10,\"bloom\":\"remember\"},{\"q\":\"पुणे करारानुसार दलितांसाठी कोणती तरतूद करण्यात आली?\",\"options\":[\"स्वतंत्र मतदारसंघ\",\"राखीव जागा\",\"स्वतंत्र राज्य\",\"दुहेरी मतदान\"],\"answer\":1,\"explain\":\"पुणे करारानुसार दलितांसाठी स्वतंत्र मतदारसंघाऐवजी राखीव जागांची तरतूद करण्यात आली.\",\"topic\":\"पुणे करार\",\"part\":10,\"bloom\":\"understand\"},{\"q\":\"डॉ. बाबासाहेब आंबेडकरांनी राष्ट्रीय सभेच्या नेत्यांची विनंती का मान्य केली?\",\"options\":[\"ब्रिटिशांच्या दबावामुळे\",\"राष्ट्रहित लक्षात घेऊन\",\"उपोषण संपवण्यासाठी\",\"निवडणुकीत जिंकण्यासाठी\"],\"answer\":1,\"explain\":\"राष्ट्रहित लक्षात घेऊन डॉ. बाबासाहेब आंबेडकरांनी मागणीचा पुनर्विचार करण्याची विनंती मान्य केली.\",\"topic\":\"पुणे करार\",\"part\":10,\"bloom\":\"apply\"},{\"q\":\"जातीय निवाड्याचा कोणता परिणाम गांधीजींना मान्य नव्हता?\",\"options\":[\"हिंदू समाजाची विभागणी\",\"मुस्लिमांना दिलेले अधिकार\",\"ब्रिटिशांचे वर्चस्व\",\"आर्थिक नुकसान\"],\"answer\":0,\"explain\":\"जातीय निव