om\":\"understand\"},{\"q\":\"खालीलपैकी कोणत्या क्रांतिकारकाला काकोरी कटासाठी फाशी देण्यात आली नाही?\",\"options\":[\"अशफाक उल्ला खान\",\"रामप्रसाद बिस्मिल\",\"चंद्रशेखर आझाद\",\"रोशन सिंग\"],\"answer\":2,\"explain\":\"अशफाक उल्ला खान, बिस्मिल आणि रोशन सिंग यांना फाशी झाली, पण चंद्रशेखर आझाद पोलिसांशी लढताना हुतात्मा झाले.\",\"topic\":\"काकोरी कट व HSR असोसिएशन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"१९२८ साली दिल्लीतील फिरोजशहा कोटला मैदानावर कोणत्या संघटनेची स्थापना करण्यात आली?\",\"options\":[\"अभिनव भारत\",\"अनुशीलन समिती\",\"गदर पार्टी\",\"हिंदुस्थान सोशालिस्ट रिपब्लिकन असोसिएशन\"],\"answer\":3,\"explain\":\"१९२८ मध्ये दिल्लीत चंद्रशेखर आझाद, भगतसिंग व इतर सहकाऱ्यांनी HSRA ची स्थापना केली.\",\"topic\":\"काकोरी कट व HSR असोसिएशन\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"हिंदुस्थान सोशालिस्ट रिपब्लिकन असोसिएशनचे मुख्य उद्दिष्ट काय होते?\",\"options\":[\"केवळ रेल्वे लुटणे\",\"भारतात ब्रिटीश साम्राज्य मुळांतून उखडून टाकणे\",\"निवडणुका लढवणे\",\"परदेशी वस्तूंवर बहिष्कार टाकणे\"],\"answer\":1,\"explain\":\"ब्रिटीश साम्राज्य मुळांतून उखडून टाकणे हे या संघटनेचे प्रमुख उद्दिष्ट होते.\",\"topic\":\"काकोरी कट व HSR असोसिएशन\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"हिंदुस्थान सोशालिस्ट रिपब्लिकन आर्मीचे (HSRA चा लष्करी विभाग) प्रमुख कोण होते?\",\"options\":[\"भगतसिंग\",\"राजगुरू\",\"सुखदेव\",\"चंद्रशेखर आझाद\"],\"answer\":3,\"explain\":\"या लष्करी विभागाचे नाव \'हिंदुस्थान सोशालिस्ट रिपब्लिकन आर्मी\' होते आणि तिचे प्रमुख चंद्रशेखर आझाद होते.\",\"topic\":\"काकोरी कट व HSR असोसिएशन\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"भगतसिंग व राजगुरू यांनी साँडर्स या ब्रिटीश अधिकाऱ्याला गोळ्या घालून का ठार केले?\",\"options\":[\"काकोरी कटाचा बदला घेण्यासाठी\",\"लाला लजपतराय यांच्या मृत्यूचा बदला घेण्यासाठी\",\"विधिमंडळात बॉम्ब फेकण्यासाठी\",\"ब्रिटीश खजिना लुटण्यासाठी\"],\"answer\":1,\"explain\":\"लाला लजपतराय यांच्या मृत्यूचा बदला घेण्यासाठी त्यांनी साँडर्सला ठार केले.\",\"topic\":\"काकोरी कट व HSR असोसिएशन\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"सरकारच्या धो