ons\":[\"हवा शुद्ध झाली आहे\",\"हवा अशुद्ध झाली आहे\",\"झाडांची संख्या वाढली आहे\",\"सावली थंडगार झाली आहे\"],\"answer\":1,\"explain\":\"वाहनांचा धूर वाढल्यामुळे हवा अशुद्ध झाली आहे असे पाठात म्हटले आहे.\",\"topic\":\"वातावरण म्हणजे काय?\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वडाच्या झाडाने वातावरणात कोणते बदल झाल्याचे सांगितले आहे?\",\"options\":[\"वातावरण पूर्वीपेक्षा अधिक शुद्ध झाले आहे\",\"वातावरण आता खूप बदलले असून ते अशुद्ध झाले आहे\",\"वातावरणात आता फक्त ऑक्सिजन वाढला आहे\",\"वातावरणात काहीही बदल झालेला नाही\"],\"answer\":1,\"explain\":\"वडाने स्पष्ट केले की आता वातावरण खूप बदलले असून ते पूर्वीसारखे शुद्ध राहिले नाही.\",\"topic\":\"वातावरण म्हणजे काय?\",\"part\":3,\"bloom\":\"understand\"},{\"q\":\"वातावरण पुन्हा शुद्ध करण्यासाठी वडाने कोणता उपाय सुचवला आहे?\",\"options\":[\"वाहनांचा वापर वाढवा\",\"कचरा कुठेही फेका\",\"जास्त झाडे लावा\",\"पाणी जास्त वाया घालवा\"],\"answer\":2,\"explain\":\"वातावरण सुधारण्यासाठी जास्त झाडे लावण्याचा सल्ला वडाने दिला आहे.\",\"topic\":\"वातावरण म्हणजे काय?\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"कचऱ्याच्या समस्येवर वडाने कोणता उपाय सांगितला आहे?\",\"options\":[\"कचऱ्याची योग्य विल्हेवाट लावा\",\"कचरा झाडाखाली जमा करा\",\"कचरा जाळून टाका\",\"कचरा जमिनीत गाडून टाका\"],\"answer\":0,\"explain\":\"वडाने कचऱ्याची योग्य विल्हेवाट लावण्यास सांगितले आहे.\",\"topic\":\"वातावरण म्हणजे काय?\",\"part\":3,\"bloom\":\"apply\"},{\"q\":\"पाठातील माहितीनुसार, वातावरणातील बदलाचा कोणता क्रम योग्य आहे?\",\"options\":[\"शुद्ध हवा -> झाडे वाढली -> अशुद्ध हवा\",\"शुद्ध हवा -> झाडे कमी झाली व धूर वाढला -> अशुद्ध हवा\",\"अशुद्ध हवा -> झाडे लावली -> अशुद्ध हवा\",\"धूर कमी झाला -> झाडे कमी झाली -> शुद्ध हवा\"],\"answer\":1,\"explain\":\"पूर्वी हवा शुद्ध होती, पण झाडे कमी झाल्याने व धूर वाढल्याने ती अशुद्ध झाली.\",\"topic\":\"वातावरण म्हणजे काय?\",\"part\":3,\"bloom\":\"analyze\"},{\"q\":\"मुलांच्या कोणत्या कृतीमुळे वडाला त्यांच्याशी संवाद साधण्याची संधी मिळाली?\",\"options\":[\"मुले वडाच्या झाडाविषयीच गप्पा मारत होती\",\"मुले झाडावर दगड मारत हो