:\"भरतीच्या पाण्याबरोबर मासे खाडीत येतात, ज्यामुळे मासेमारी करणे सोपे होते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"understand\"},{\"q\":\"एका जहाजाला बंदरात प्रवेश करायचा आहे, तर खालीलपैकी कोणती स्थिती सर्वात सोयीस्कर ठरेल?\",\"options\":[\"ओहोटीची वेळ\",\"भरतीची वेळ\",\"काटकोन स्थिती\",\"कमी पावसाची वेळ\"],\"answer\":1,\"explain\":\"भरतीमुळे पाण्याची पातळी वाढते, त्यामुळे जहाजे बंदरात आणणे सोपे होते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"मिठागरातून मीठ तयार करण्यासाठी कोणत्या नैसर्गिक प्रक्रियेचा उपयोग केला जातो?\",\"options\":[\"केवळ पावसाचे पाणी\",\"नदीचे पाणी साठवणे\",\"भरतीचे पाणी साठवणे\",\"जमिनीखालील पाणी उपसणे\"],\"answer\":2,\"explain\":\"भरतीचे पाणी मिठागरात साठवून त्यापासून मीठ तयार केले जाते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"भांगाची भरती ही उधाणाच्या भरतीपेक्षा लहान का असते?\",\"options\":[\"कारण गुरुत्वीय बल एकाच दिशेला असते\",\"कारण सूर्य आणि चंद्र यांचे गुरुत्वीय बल दोन वेगवेगळ्या दिशांना विभागले जाते\",\"कारण पृथ्वीची गती वाढते\",\"कारण त्या दिवशी चंद्र दिसत नाही\"],\"answer\":1,\"explain\":\"काटकोन स्थितीमुळे सूर्य आणि चंद्र यांचे गुरुत्वीय बल विभागले गेल्याने भांगाची भरती लहान असते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"भरती-ओहोटीमुळे किनारी भागातील जैवविविधतेवर काय परिणाम होतो?\",\"options\":[\"जैवविविधता नष्ट होते\",\"खारफुटी वनांचा विकास व जतन होते\",\"किनारी भाग वाळवंटी होतो\",\"केवळ मासे कमी होतात\"],\"answer\":1,\"explain\":\"भरती-ओहोटीमुळे खारफुटी वने आणि किनारी भागातील जैवविविधतेचा विकास व जतन होते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"remember\"},{\"q\":\"जर तुम्हाला भरती-ओहोटीच्या ऊर्जेचा वापर करायचा असेल, तर तुम्ही कोणता प्रकल्प सुरू कराल?\",\"options\":[\"सौर ऊर्जा प्रकल्प\",\"वीज निर्मिती प्रकल्प\",\"अणुऊर्जा प्रकल्प\",\"वायू ऊर्जा प्रकल्प\"],\"answer\":1,\"explain\":\"भरती-ओहोटीच्या परिणामांपैकी एक म्हणजे त्यापासून वीज निर्माण करता येते.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"apply\"},{\"q\":\"भरती-ओहोटीमुळे किनाऱ्याच्या भौगोलिक स्वरूपात कोणता बदल होतो?\",\"options\":[\"किनाऱ्याची उंची वाढते\",\"किनाऱ्याची धूप होते व गाळ वाहून नेला जातो\",\"किनारा स्थिर राहतो\",\"किनाऱ्यावर नवीन पर्वत तयार होतात\"],\"answer\":1,\"explain\":\"भरती-ओहोटीमुळे किनाऱ्याची धूप होते आणि गाळ वाहून नेला जातो.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"analyze\"},{\"q\":\"खालीलपैकी कोणता पर्याय भरती-ओहोटीचा सकारात्मक परिणाम दर्शवतो?\",\"options\":[\"किनाऱ्याची धूप होणे\",\"गाळ साचणे\",\"खारफुटी वनांचे जतन होणे\",\"जहाजे अडकून पडणे\"],\"answer\":2,\"explain\":\"खारफुटी वनांचे जतन आणि विकास हा भरती-ओहोटीचा एक महत्त्वाचा सकारात्मक परिणाम आहे.\",\"topic\":\"भरती-ओहोटीचे प्रकार व परिणाम\",\"part\":6,\"bloom\":\"evaluate\"},{\"q\":\"पृथ्वीवरील सर्वांत मोठी परिसंस्था (Ecosystem) कोणती आहे?\",\"options\":[\"जमीन\",\"महासागर\",\"जंगल\",\"वाळवंट\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, महासागर ही पृथ्वीवरील सर्वांत मोठी परिसंस्था आहे.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"जगातील ऑक्सिजनपैकी किती भाग महासागरांतील वनस्पतींद्वारे तयार केला जातो?\",\"options\":[\"दहा टक्क्यांहून कमी\",\"केवळ २५ टक्के\",\"निम्मेहून अधिक (५०% पेक्षा जास्त)\",\"शंभर टक्के\"],\"answer\":2,\"explain\":\"जगातील निम्मेहून अधिक ऑक्सिजन महासागरांतील वनस्पतींद्वारे तयार केला जातो.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"महासागरांना \'पृथ्वीची फुफ्फुसे\' असे का म्हटले जाते?\",\"options\":[\"ते कार्बन डायऑक्साईड तयार करतात म्हणून\",\"ते जगातील निम्मेहून अधिक ऑक्सिजन तयार करतात म्हणून\",\"ते केवळ माशांचे घर आहेत म्हणून\",\"ते खूप खोल आहेत म्हणून\"],\"answer\":1,\"explain\":\"महासागरातील वनस्पती मोठ्या प्रमाणात ऑक्सिजन तयार करत असल्याने त्यांना पृथ्वीची फुफ्फुसे म्हणतात.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"महासागरामुळे पृथ्वीवरील कोणते चक्र अबाधित राहून गोड्या पाण्याचा साठा नवीन होतो?\",\"options\":[\"अन्नचक्र\",\"वायूचक्र\",\"जलचक्र\",\"ऊर्जाचक्र\"],\"answer\":2,\"explain\":\"महासागरामुळेच पृथ्वीवरील जलचक्र अबाधित असून गोड्या पाण्याचा साठा सतत नवीन होतो.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"समुद्रात जहाजातून तेलगळती झाल्यास त्याचा प्राथमिक परिणाम कशावर होईल?\",\"options\":[\"समुद्राची खोली वाढेल\",\"समुद्री जीवांवर व मानवावर परिणाम होईल\",\"पाऊस पडणे बंद होईल\",\"जमिनीची धूप थांबेल\"],\"answer\":1,\"explain\":\"मानवी कृतींमुळे (उदा. तेलगळती) होणाऱ्या प्रदूषणाचा परिणाम समुद्री जीवांवर व मानवावर होतो.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"खालीलपैकी कोणते महासागराच्या प्रदूषणाचे कारण नाही?\",\"options\":[\"कारखान्यातील रसायने\",\"प्लास्टिकचा कचरा\",\"सौर ऊर्जेचा वापर\",\"खाणकाम\"],\"answer\":2,\"explain\":\"पाठ्यपुस्तकात रसायने, प्लास्टिक आणि खाणकाम ही प्रदूषणाची कारणे दिली आहेत, सौर ऊर्जा नाही.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"analyze\"},{\"q\":\"दिलेल्या आकृतीतील मजकुरानुसार, जर आपण महासागरांचा सन्मान केला नाही तर काय होईल?\",\"options\":[\"पाणी गोड होईल\",\"पृथ्वीवरील भविष्य धोक्यात येईल\",\"मासेमारी वाढेल\",\"हवामान थंड होईल\"],\"answer\":1,\"explain\":\"आकृतीमधील संदेशानुसार महासागरांचा सन्मान न केल्यास पृथ्वीवरील भविष्य धोक्यात येईल.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"understand\",\"figure_image\":\"63\\/075_103.jpg\"},{\"q\":\"दिलेल्या आकृतीत महासागरांच्या महत्त्वाबाबतचा संदेश कोणाचा आहे?\",\"options\":[\"महात्मा गांधी\",\"डॉ. ए. पी. जे. अब्दुल कलाम\",\"लोकमान्य टिळक\",\"पंडित नेहरू\"],\"answer\":1,\"explain\":\"आकृतीमध्ये डॉ. ए. पी. जे. अब्दुल कलाम यांचा संदेश दिलेला आहे.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"remember\",\"figure_image\":\"63\\/075_103.jpg\"},{\"q\":\"महासागर वातावरणातील कोणता वायू मोठ्या प्रमाणात शोषून घेतात?\",\"options\":[\"नायट्रोजन\",\"हायड्रोजन\",\"कार्बन डायऑक्साईड\",\"हेलियम\"],\"answer\":2,\"explain\":\"महासागर वातावरणातील कार्बन डायऑक्साईड मोठ्या प्रमाणात शोषून घेतात.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"remember\"},{\"q\":\"सूक्ष्म समुद्री जीव पर्यावरणात कशी मदत करतात?\",\"options\":[\"पाणी गरम करून\",\"प्रकाश संश्लेषणाद्वारे प्राणवायू (ऑक्सिजन) तयार करून\",\"समुद्राची खोली वाढवून\",\"प्लास्टिक खाऊन\"],\"answer\":1,\"explain\":\"सूक्ष्म समुद्री जीव प्रकाश संश्लेषणाद्वारे प्राणवायू तयार करून पर्यावरणात मदत करतात.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"understand\"},{\"q\":\"एखाद्या किनारपट्टीच्या भागात शेतीसाठी कीटकनाशकांचा अतिवापर केल्यास काय घडू शकते?\",\"options\":[\"समुद्राचे पाणी कमी होईल\",\"समुद्राचे प्रदूषण वाढेल\",\"समुद्रातील मासे मोठे होतील\",\"समुद्राचे पाणी गोड होईल\"],\"answer\":1,\"explain\":\"कीटकनाशके हे महासागर प्रदूषित होण्याचे एक महत्त्वाचे कारण आहे.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"apply\"},{\"q\":\"महासागराला \'पर्यावरणाचे संतुलन राखणारे शक्तिस्थान\' का म्हटले जाते?\",\"options\":[\"कारण ते केवळ संपत्तीचे भांडार आहे\",\"कारण ते तापमान, हवामान व पर्जन्यमान यात समतोल राखते\",\"कारण त्यात फक्त मीठ असते\",\"कारण ते मानवापासून दूर आहे\"],\"answer\":1,\"explain\":\"महासागर उष्णता शोषून तापमान, हवामान व पर्जन्यमान यात समतोल राखत असल्याने त्याला शक्तिस्थान म्हणतात.\",\"topic\":\"महासागर व पर्यावरण\",\"part\":7,\"bloom\":\"evaluate\"},{\"q\":\"जीवावरणात वातावरणाचा सुमारे किती उंचीपर्यंतचा थर समाविष्ट होतो?\",\"options\":[\"२ ते ५ किमी\",\"८ ते १० किमी\",\"१५ ते २० किमी\",\"५० किमी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, वातावरणाचा सुमारे ८ ते १० किमी उंचीपर्यंतचा थर जीवावरणात येतो.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"शिलावरणाचा किती जाडीचा भाग जीवावरणात समाविष्ट होतो?\",\"options\":[\"१ किमी\",\"२ किमी\",\"५ किमी\",\"१० किमी\"],\"answer\":1,\"explain\":\"शिलावरणाचा सुमारे २ किमी जाडीचा भाग जीवावरणात समाविष्ट होतो.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"जलावरणाचा किती खोलीपर्यंतचा भाग जीवावरणात येतो?\",\"options\":[\"१,००० मी.\",\"५,००० मी.\",\"८,००० मी.\",\"१०,००० मी.\"],\"answer\":3,\"explain\":\"जलावरणाचा सुमारे १०,००० मी. खोलीपर्यंतचा बहुतेक सर्व भाग जीवावरणात समाविष्ट होतो.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"remember\"},{\"q\":\"जीवावरण म्हणजे नेमके काय?\",\"options\":[\"फक्त जमिनीवरील सजीव\",\"फक्त पाण्यातील सजीव\",\"शिलावरण, जलावरण व वातावरण यांचा परस्परसंबंधी भाग\",\"केवळ हवेत उडणारे पक्षी\"],\"answer\":2,\"explain\":\"सजीव तिन्ही आवरणांच्या परस्परसंबंधी भागात असतात, म्हणून जीवावरणात तिन्ही आवरणांचा समावेश होतो.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"ज्या प्राण्यांची डिंभावस्था पाण्यात व प्रौढावस्था जमिनीवर असते, त्यांना काय म्हणतात?\",\"options\":[\"भूचर\",\"जलचर\",\"उभयचर\",\"वनस्पती\"],\"answer\":2,\"explain\":\"उभयचर प्राण्यांचे जीवनचक्र पाणी आणि जमीन अशा दोन्ही ठिकाणी पूर्ण होते.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"अन्नसाखळीतील सर्वात महत्त्वाचा घटक कोणता आहे?\",\"options\":[\"भूचर प्राणी\",\"वनस्पती\",\"जलचर प्राणी\",\"उभयचर प्राणी\"],\"answer\":1,\"explain\":\"पाठ्यपुस्तकानुसार, वनस्पती हा अन्नसाखळीतील महत्त्वाचा घटक आहे.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"understand\"},{\"q\":\"खालीलपैकी कोणता प्राणी \'भूचर\' या गटात मोडतो?\",\"options\":[\"व्हेल मासा\",\"बेडूक\",\"हत्ती\",\"ऑक्टोपस\"],\"answer\":2,\"explain\":\"हत्ती हा जमिनीवर राहणारा प्राणी असल्याने तो भूचर आहे.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"शेवाळ आणि कमळ या वनस्पती कोठे आढळतात?\",\"options\":[\"जमिनीवर\",\"वाळवंटात\",\"पाण्यात\",\"हवेत\"],\"answer\":2,\"explain\":\"शेवाळ आणि कमळ यांसारख्या वनस्पती पाण्यात आढळतात.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"सॅलॅमँडर या प्राण्याचे वर्गीकरण कोणत्या गटात केले जाते?\",\"options\":[\"जलचर\",\"उभयचर\",\"भूचर\",\"वनस्पती\"],\"answer\":1,\"explain\":\"बेडूक आणि सॅलॅमँडर ही उभयचर प्राण्यांची उदाहरणे आहेत.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"apply\"},{\"q\":\"जीवावरणाच्या विस्ताराचा विचार करता, खालीलपैकी कोणते विधान योग्य आहे?\",\"options\":[\"जीवावरण फक्त हवेत असते.\",\"जीवावरण शिलावरण, जलावरण व वातावरण या तिन्ही थरांमध्ये पसरलेले असते.\",\"जीवावरण जमिनीच्या आत १० किमी पर्यंत असते.\",\"जीवावरण फक्त समुद्राच्या तळाशी असते.\"],\"answer\":1,\"explain\":\"जीवावरणात शिलावरण, जलावरण आणि वातावरण या तिन्ही आवरणांचा समावेश होतो.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"व्हेल मासा आणि ऑक्टोपस यांना \'जलचर\' का म्हटले जाते?\",\"options\":[\"कारण ते जमिनीवर चालू शकतात.\",\"कारण ते फक्त पाण्यात राहणारे सजीव आहेत.\",\"कारण ते हवेत उडू शकतात.\",\"कारण ते अन्न तयार करतात.\"],\"answer\":1,\"explain\":\"फक्त पाण्यात राहणाऱ्या सजीवांना जलचर म्हणतात.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"analyze\"},{\"q\":\"जर एखाद्या सजीवाचे अस्तित्व जमिनीवर, पाण्यात आणि हवेत अशा तिन्ही ठिकाणी असेल, तर तो कोणत्या आवरणाचा भाग आहे?\",\"options\":[\"केवळ जलावरण\",\"केवळ शिलावरण\",\"जीवावरण\",\"केवळ वातावरण\"],\"answer\":2,\"explain\":\"सजीव ज्या भागात राहतात, त्या तिन्ही आवरणांच्या एकत्रित भागाला जीवावरण म्हणतात.\",\"topic\":\"जीवावरण आणि सजीवांचे वर्गीकरण\",\"part\":8,\"bloom\":\"evaluate\"},{\"q\":\"जीवावरण सजीवांना जगण्यासाठी कोणती महत्त्वाची संसाधने पुरवते?\",\"options\":[\"केवळ सोने आणि चांदी\",\"केवळ दगड आणि माती\",\"अन्न, पाणी आणि हवा\",\"केवळ पेट्रोल आणि डिझेल\"],\"answer\":2,\"explain\":\"उताऱ्यानुसार, जीवावरण सजीवांना आवश्यक असलेले अन्न, पाणी आणि हवा ही संसाधने पुरवते.\",\"topic\":\"जीवावरणाचे महत्त्व\",\"part\":9,\"bloom\":\"remember\"},{\"q\":\"जीवावरणातील सजीव एकमेकांशिवाय आणखी कोणावर अवलंबून असतात?\",\"options\":[\"केवळ इतर प्राण्यांवर\",\"निर्जीव घटकांवर\",\"केवळ मानवावर\",\"केवळ यंत्रांवर\"],\"answer\":1,\"explain\":\"सजीव परस्परांव्यतिरिक्त निर्जीव घटकांवरही अवलंबून असतात असे उताऱ्यात नमूद केले आहे.\",\"topic\":\"जीवावरणाचे महत्त्व\",\"part\":9,\"bloom\":\"understand\"},{\"q\":\"वनस्